/* ==================== 常量定义 ==================== */
const MM = 96 / 25.4;                 /* 毫米转 CSS 像素换算系数（96dpi） */
const PAGE_W_MM = 210, PAGE_H_MM = 297;   /* A4 纸张宽高（毫米） */
const MARGIN_X = 15;                  /* 左右页边距（毫米） */
const AVAIL_W = PAGE_W_MM - MARGIN_X * 2; /* 网格可用宽度 */
const GRID_TOP = 15, GRID_BOTTOM = 285;   /* 网格上下边界（毫米） */
const AVAIL_H = GRID_BOTTOM - GRID_TOP;   /* 网格可用高度 */
const STORE_KEY = 'zitie-config-v9';      /* localStorage 存储键名（升版启用新默认值） */
const PX_TO_MM = 25.4 / 96;               /* 像素转毫米系数 */

/* ==================== 线型预设表（全局复用：网格线 / 内部辅助线 / 外框） ====================
    dash100：100 单位坐标系（格子内 SVG）下的 dasharray
    dashMm：毫米坐标系（整页网格 SVG）下的 dasharray
    cap：线端样式（round 圆点 / butt 方头） */
const LINE_STYLES = [
    {v: 'solid', name: '实线', dash100: 'none', dashMm: 'none', cap: 'butt'},
    {v: 'dotted', name: '点线', dash100: '0.5 2.6', dashMm: '0.2 1.2', cap: 'round'},
    {v: 'short', name: '短横线', dash100: '4 3', dashMm: '3 2', cap: 'butt'},
    {v: 'long', name: '长横线', dash100: '8 3', dashMm: '6 2.5', cap: 'butt'},
    {v: 'dotshort', name: '点+短划', dash100: '0.5 2.6 4 3', dashMm: '0.2 1.2 3 2', cap: 'round'},
    {v: 'shortlong', name: '短+长划', dash100: '4 3 8 3', dashMm: '3 2 6 2.5', cap: 'butt'},
    {v: 'dotlong', name: '点+长划', dash100: '0.5 2.6 8 3', dashMm: '0.2 1.2 6 2.5', cap: 'round'},
    {v: 'dashdot', name: '点划线', dash100: '8 3 0.5 3', dashMm: '6 2 0.2 2', cap: 'round'}
];
/* 按 v 取线型预设，找不到时回退到实线 */
const styleOf = v => LINE_STYLES.find(s => s.v === v) || LINE_STYLES[0];

/* ==================== 原子辅助线 / 形状表 ====================
    group: line=基础线条（满格，不受尺寸影响）；shape=几何形状（可调尺寸） */
const SHAPES = [
    /* 基础线条 */
    {v: 'h', name: '单横线', group: 'line', sized: false},
    {v: 'v', name: '单竖线', group: 'line', sized: false},
    {v: 'd1', name: '斜线↘', group: 'line', sized: false},
    {v: 'd2', name: '斜线↗', group: 'line', sized: false},
    {v: 'jiu', name: '九宫格', group: 'line', sized: false},
    {v: 'four', name: '四线三格', group: 'line', sized: false},
    /* 几何形状 */
    {v: 'hui', name: '回字格', group: 'shape', sized: true},
    {v: 'circle', name: '圆', group: 'shape', sized: true},
    {v: 'circle2', name: '双圆', group: 'shape', sized: true},
    {v: 'octagon', name: '八边形', group: 'shape', sized: true},
    {v: 'hexagon', name: '六边形', group: 'shape', sized: true},
    {v: 'pentagon', name: '五边形', group: 'shape', sized: true},
    {v: 'diamond', name: '正菱形', group: 'shape', sized: true},
    {v: 'triangle', name: '三角', group: 'shape', sized: true},
    {v: 'rounded', name: '圆角方框', group: 'shape', sized: true},
    {v: 'corner', name: '四角短线', group: 'shape', sized: true}
];

/* ---- 100×100 坐标系下的 SVG 图元生成函数 ---- */
/* 数值四舍五入到两位小数，避免坐标过长 */
const nf = n => Math.round(n * 100) / 100;
/* 生成线段 */
const P_L = (x1, y1, x2, y2) => `<line class="ln" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>`;
/* 生成矩形（rx 为圆角半径） */
const P_R = (x, y, w, h, rx) => `<rect class="ln" x="${nf(x)}" y="${nf(y)}" width="${nf(w)}" height="${nf(h)}"${rx ? ` rx="${nf(rx)}"` : ''}/>`;
/* 生成圆（圆心固定在 50,50） */
const P_C = r => `<circle class="ln" cx="50" cy="50" r="${nf(r)}"/>`;
/* 生成多边形 */
const P_G = pts => `<polygon class="ln" points="${pts.map(p => nf(p[0]) + ',' + nf(p[1])).join(' ')}"/>`;

/* 生成正 n 边形顶点（r 为外接圆半径，startDeg 为起始角度） */
function regular(n, r, startDeg) {
    const pts = [];
    for (let i = 0; i < n; i++) {
        const a = (startDeg + 360 / n * i) * Math.PI / 180;
        pts.push([50 + r * Math.cos(a), 50 + r * Math.sin(a)]);
    }
    return P_G(pts);
}

/* 把选中的原子项叠画在同一坐标里，互不遮挡 */
function shapeSvg(keys, size, styleKey) {
    if (!keys.length) return '';
    /* size 限制在 0.2～1 之间，换算成 100 坐标系下的边长 */
    const S = 100 * Math.min(1, Math.max(0.2, size));
    const r = S / 2, a = 50 - r, b = 50 + r;
    const out = [];

    keys.forEach(k => {
        switch (k) {
            /* 满格线条 */
            case 'h': out.push(P_L(0, 50, 100, 50)); break;
            case 'v': out.push(P_L(50, 0, 50, 100)); break;
            case 'd1': out.push(P_L(0, 0, 100, 100)); break;
            case 'd2': out.push(P_L(100, 0, 0, 100)); break;
            case 'jiu': out.push(P_L(0, 33.33, 100, 33.33), P_L(0, 66.67, 100, 66.67),
                P_L(33.33, 0, 33.33, 100), P_L(66.67, 0, 66.67, 100)); break;
            case 'four': out.push(P_L(0, 25, 100, 25), P_L(0, 50, 100, 50), P_L(0, 75, 100, 75)); break;
            /* 几何形状 */
            case 'hui': out.push(P_R(a, a, S, S)); break;
            case 'circle': out.push(P_C(r)); break;
            case 'circle2': out.push(P_C(r), P_C(r * 0.66)); break;
            case 'octagon': {
                const c = S * 0.2929;   /* 八边形切角比例系数 */
                out.push(P_G([[a + c, a], [b - c, a], [b, a + c], [b, b - c],
                [b - c, b], [a + c, b], [a, b - c], [a, a + c]]));
                break;
            }
            case 'hexagon': out.push(regular(6, r, 0)); break;
            case 'pentagon': out.push(regular(5, r, -90)); break;
            case 'diamond': out.push(P_G([[50, a], [b, 50], [50, b], [a, 50]])); break;
            case 'triangle': out.push(regular(3, r, -90)); break;
            case 'rounded': out.push(P_R(a, a, S, S, S * 0.15)); break;
            case 'corner': {
                const LEN = S * 0.26;   /* 四角短线长度 */
                out.push(P_L(a, a, a + LEN, a), P_L(a, a, a, a + LEN),
                    P_L(b, a, b - LEN, a), P_L(b, a, b, a + LEN),
                    P_L(a, b, a + LEN, b), P_L(a, b, a, b - LEN),
                    P_L(b, b, b - LEN, b), P_L(b, b, b, b - LEN));
                break;
            }
        }
    });

    /* 线型参数写在 SVG 根节点，被子线条继承；styleKey 对应线型预设 */
    const st = styleOf(styleKey);
    const dashAttr = st.dash100 === 'none' ? '' : `stroke-dasharray="${st.dash100}"`;
    return `<svg class="gs" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" preserveAspectRatio="none"
${dashAttr} stroke-linecap="${st.cap}">${out.join('')}</svg>`;
}

/* 数值夹取：限制在 lo～hi 区间内 */
const clampNum = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

/* 空心描红字形：以 SVG 文字绘制，stroke 为矢量，PDF 不失真 */
function hollowGlyphSvg(txt, fontFamily, fontWeight, colorHex, alpha, strokePx, cellMM) {
    /* 转义 XML 特殊字符，防止破坏 SVG 结构 */
    const esc = txt.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    /* viewBox 取 100×100，1 单位 = cellMM/100 mm，字号按占格比换算 */
    const ratio = Math.min(1, Math.max(0.3, Number($('fontRatio').value)));
    const pct = clampNum(ratio * 98, 20, 100);      /* 100 单位坐标系里的字号 */
    const swUnit = (strokePx * PX_TO_MM) / (cellMM / 100);  /* px → mm → 用户单位换算 */
    return `<svg class="glyph-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"
preserveAspectRatio="xMidYMid meet">
<text x="50" y="50" text-anchor="middle" dominant-baseline="central"
        font-family="${String(fontFamily).replace(/"/g, '').replace(/\s+/g, ' ')}" font-size="${pct}"
        font-weight="${fontWeight}" fill="none"
        stroke="${rgba(colorHex, alpha)}" stroke-width="${swUnit.toFixed(3)}"
        stroke-linejoin="round">${esc}</text>
</svg>`;
}

/* ==================== 可选字体表 ==================== */
const FONTS = [
    {v: 'KaiTi, STKaiti, 楷体, serif', name: '楷体', css: 'KaiTi, STKaiti, serif'},
    {v: 'SimSun, STSong, 宋体, serif', name: '宋体', css: 'SimSun, STSong, serif'},
    {v: 'SimHei, STHeiti, 黑体, sans-serif', name: '黑体', css: 'SimHei, STHeiti, sans-serif'},
    {v: 'FangSong, STFangsong, 仿宋, serif', name: '仿宋', css: 'FangSong, STFangsong, serif'},
    {v: 'Microsoft YaHei, PingFang SC, sans-serif', name: '微软雅黑', css: 'Microsoft YaHei, PingFang SC, sans-serif'},
    {v: 'STXingkai, 行楷, cursive', name: '华文行楷', css: 'STXingkai, cursive'},
    {v: 'STLiti, 隶书, serif', name: '华文隶书', css: 'STLiti, serif'}
];

/* ==================== 默认配置（恢复默认时使用） ==================== */
/* 笔画粗细：实心两档（常规 / 加粗）；空心描红两档（细 / 常规） */
const STROKE_SETS = {
    solid: [{name: '常规', weight: 400}, {name: '加粗', weight: 700}],
    hollow: [{name: '细', weight: 400, hollow: 0.3}, {name: '常规', weight: 400, hollow: 0.7}]
};
function currentStrokeSet() {return shape === 'hollow' ? STROKE_SETS.hollow : STROKE_SETS.solid;}
function currentStroke() {
    const set = currentStrokeSet();
    return set[Math.min(set.length - 1, Math.max(0, strokeLevel))];
}

const DEFAULTS = {
    selShapes: ['h', 'v', 'd1', 'd2', 'octagon'],
    fontFamily: 'KaiTi, STKaiti, 楷体, serif',
    customFont: '',
    cols: 12,
    fontRatio: 0.80, shape: 'solid', strokeLevel: 0,
    fontColor: '#ff0000', fontAlpha: 0.5,
    borderColor: '#ff0000', borderAlpha: 1,
    guideColor: '#ff0000', guideAlpha: 0.2, guideStyle: 'short',
    shapeSize: 70,
    borderWidth: 1, guideWidth: 0.75,
    showH: 1, showV: 1, gridStyle: 'solid',
    pageBorder: 'innerThin', pfWidth: 4,
    pfColor: '#ff0000', pfAlpha: 1,
    headerLeft: '小宇宙字帖生成器', headerCenter: '姓名：_______________', headerRight: '日期：______年___月___日',
    footerLeft: 'www.xiaoyuzhou.com', footerCenter: '', footerRight: '',
    pageNoPos: 'footer-center',
    preserveBreak: 1, indent: 0, centerFirst: 1,
    stripPunct: 0, stripKeep: 2,
    mode: 'none', modeNum: 1, secondary: 0, fadeAlpha: 30, fadeColor: '#ff0000', guardFirst: 1,
    hfFont: FONTS[0].v, hfSize: 5, hfGap: 0.5
};

/* ==================== 全局状态变量 ==================== */
let shape = 'solid';          /* 字形：solid 实心 / hollow 空心描红 */
let strokeLevel = 0;          /* 笔画粗细档位：0 细 / 1 常规 / 2 粗 */
let centerFirst = 1;          /* 首段居中：1 自动按字数居中 / 0 关闭 */
let stripPunct = 0;           /* 去标点：0 保留 / 1 去掉（输入框原文不变） */
let guardFirst = 1;           /* 标题保护：首段始终描红 */
let preserveBreak = 1;       /* 换行处理：0 连续排 / 1 换行即换行 */
let selShapes = ['h', 'v', 'd1', 'd2'];  /* 已选线条/形状 key 列表 */
let guideStyle = 'short';     /* 内部辅助线线型预设 */
let showH = 1;                /* 全局网格线：横线显隐 */
let showV = 1;                /* 全局网格线：竖线显隐 */
let gridStyle = 'solid';      /* 全局网格线线型预设 */
let pageBorder = 'single';    /* 整组外框线型：none/single/double/innerThin/innerThick */
let fontFamily = FONTS[0].v;  /* 当前字体栈 */

/* 工具：按 id 取元素 */
const $ = id => document.getElementById(id);
/* 十六进制颜色转 rgb 三元组字符串 */
const hexToRgb = h => `${parseInt(h.slice(1, 3), 16)},${parseInt(h.slice(3, 5), 16)},${parseInt(h.slice(5, 7), 16)}`;
/* 生成 rgba 颜色字符串 */
const rgba = (h, a) => `rgba(${hexToRgb(h)}, ${a})`;
/* 小数转百分比字符串 */
const pct = v => Math.round(v * 100) + '%';

/* ==================== 下拉交互 ==================== */
/* 切换指定下拉的展开/收起状态，同时关闭其它下拉 */
function toggleDd(id) {
    const el = $(id);
    const willOpen = !el.classList.contains('open');
    document.querySelectorAll('.dd').forEach(d => d.classList.remove('open'));
    if (willOpen) el.classList.add('open');
}
/* 点击页面空白处时关闭所有下拉 */
document.addEventListener('click', e => {
    if (!e.target.closest('.dd')) document.querySelectorAll('.dd').forEach(d => d.classList.remove('open'));
});

/* ==================== 线型下拉填充 ==================== */
/* 把线型预设填入指定 select，并选中 current 项 */
function fillStyleSelect(sel, current) {
    sel.innerHTML = '';
    LINE_STYLES.forEach(s => {
        const op = document.createElement('option');
        op.value = s.v; op.innerText = s.name;
        if (s.v === current) op.selected = true;
        sel.appendChild(op);
    });
}

/* ---- 原子项 chips 渲染 ---- */
function buildShapeChips() {
    const lineBox = $('lineChips'), shapeBox = $('shapeChips');
    lineBox.innerHTML = ''; shapeBox.innerHTML = '';
    SHAPES.forEach(sp => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'chip' + (selShapes.includes(sp.v) ? ' on' : '');
        chip.dataset.v = sp.v;
        chip.onclick = () => toggleShape(sp.v);

        /* 迷你方格预览 */
        const mini = document.createElement('span');
        mini.className = 'mini-cell';
        mini.innerHTML = shapeSvg([sp.v], Number($('shapeSize').value) / 100, guideStyle);

        const nm = document.createElement('span');
        nm.innerText = sp.name;

        chip.appendChild(mini); chip.appendChild(nm);
        (sp.group === 'line' ? lineBox : shapeBox).appendChild(chip);
    });
    syncChips();
}

/* 点击 chip：选中则取消，未选则加入 */
function toggleShape(v) {
    selShapes = selShapes.includes(v) ? selShapes.filter(x => x !== v) : selShapes.concat(v);
    syncChips(); render();
}

/* ==================== 内置格型模板 ====================
    所有模板统一外观：网格线 1px、内部 0.75px、内部短横线、外框内细外粗 100%、
    配色正红、文字 50%、网格线 100%、内部线条 20% */
const TEMPLATES = [
    {key: 'mi', name: '米字格', shapes: ['h', 'v', 'd1', 'd2']},
    {key: 'tian', name: '田字格', shapes: ['h', 'v']},
    {key: 'x', name: 'X 格', shapes: ['d1', 'd2']},
    {key: 'jiu', name: '九宫格', shapes: ['jiu']},
    {key: 'four', name: '四线三格', shapes: ['four']},
    {key: 'mi-circle', name: '米字格·圆', shapes: ['h', 'v', 'd1', 'd2', 'circle']},
    {key: 'mi-circle2', name: '米字格·双圆', shapes: ['h', 'v', 'd1', 'd2', 'circle2']},
    {key: 'mi-hui', name: '米字格·回宫', shapes: ['h', 'v', 'd1', 'd2', 'hui']},
    {key: 'mi-oct', name: '米字格·八边形', shapes: ['h', 'v', 'd1', 'd2', 'octagon']},
    {key: 'mi-diamond', name: '米字格·菱形', shapes: ['h', 'v', 'd1', 'd2', 'diamond']}
];

/* 统一外观参数（每个模板套用后都回到这套） */
function applyTemplateStyle() {
    $('borderWidth').value = 1;          /* 网格线粗细 1px */
    $('guideWidth').value = 0.75;        /* 内部线条粗细 0.75px */
    guideStyle = 'short';                /* 内部线型：短横线 */
    pageBorder = 'innerThin';            /* 外框：内细外粗 */
    ['fontColor', 'borderColor', 'guideColor', 'pfColor'].forEach(id => $(id).value = '#ff0000');
    $('fontAlpha').value = 0.5;          /* 文字 50% */
    $('borderAlpha').value = 1;          /* 网格线 100% */
    $('guideAlpha').value = 0.2;         /* 内部线条 20% */
    $('pfAlpha').value = 1;              /* 外框 100% 不透明 */
    applyConfig(collectConfig());        /* 回填标签与下拉选中态 */
}

/* 一键套用模板 */
function applyTemplate(key) {
    const tpl = TEMPLATES.find(t => t.key === key);
    if (!tpl) return;
    selShapes = tpl.shapes.slice();
    applyTemplateStyle();
    syncChips();
    render();
}

function buildTemplateRow() {
    const box = $('tplRow');
    box.innerHTML = '';
    TEMPLATES.forEach(tpl => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'chip';
        chip.dataset.tpl = tpl.key;
        chip.onclick = () => applyTemplate(tpl.key);
        const mini = document.createElement('span');
        mini.className = 'mini-cell';
        mini.innerHTML = shapeSvg(tpl.shapes, Number($('shapeSize').value) / 100, 'short');
        const nm = document.createElement('span');
        nm.innerText = tpl.name;
        chip.appendChild(mini); chip.appendChild(nm);
        box.appendChild(chip);
    });
    syncTemplateRow();
}

/* 高亮当前格型（与模板组合完全一致时点亮） */
function syncTemplateRow() {
    const key = selShapes.slice().sort().join(',');
    document.querySelectorAll('#tplRow .chip').forEach(ch => {
        const tpl = TEMPLATES.find(t => t.key === ch.dataset.tpl);
        ch.classList.toggle('on', tpl && tpl.shapes.slice().sort().join(',') === key);
    });
}

/* 清空全部已选样式 */
function clearShapes() {
    selShapes = [];
    syncChips(); render();
}

/* 同步 chips 选中态与统计文案，未选时禁用尺寸/线型选项 */
function syncChips() {
    document.querySelectorAll('.chip[data-v]').forEach(ch => {
        ch.classList.toggle('on', selShapes.includes(ch.dataset.v));
    });
    $('shapeMeta').innerText = selShapes.length ? `已选 ${selShapes.length} 项` : '未选任何样式（空白格）';
    if ($('tplRow')) syncTemplateRow();
    ['shapeSizeRow', 'guideStyleRow'].forEach(id => $(id).classList.toggle('dim', !selShapes.length));
}

/* 刷新所有 chip 迷你预览（尺寸或线型变化时调用） */
function refreshChipPreview() {
    const size = Number($('shapeSize').value) / 100;
    document.querySelectorAll('.chip .mini-cell').forEach((m, i) => {
        m.innerHTML = shapeSvg([SHAPES[i].v], size, guideStyle);
    });
}

/* ---- 字体下拉菜单渲染 ---- */
function buildFontMenu() {
    const menu = $('fontMenu');
    menu.innerHTML = '';
    FONTS.forEach(f => {
        const li = document.createElement('li');
        li.dataset.v = f.v;
        li.onclick = () => setFont(f.v);
        const txt = document.createElement('span');
        txt.className = 'dd-txt';
        txt.innerHTML = `<span style="font-family:${f.css};font-size:15px">${f.name}</span><small>按该字体渲染预览</small>`;
        li.appendChild(txt); menu.appendChild(li);
    });
    syncFont();
}

/* 选中字体并刷新 */
function setFont(v) {
    fontFamily = v;
    syncFont();
    document.querySelectorAll('.dd').forEach(d => d.classList.remove('open'));
    render();
}

/* 页眉页脚字体下拉渲染 */
function buildHfFontMenu() {
    const sel = $('hfFont');
    sel.innerHTML = '';
    FONTS.forEach(f => {
        const op = document.createElement('option');
        op.value = f.v; op.innerText = f.name;
        sel.appendChild(op);
    });
}

/* 同步字体下拉的显示文字、字体预览与选中项 */
function syncFont() {
    const f = FONTS.find(x => x.v === fontFamily) || FONTS[0];
    $('fontFamily').value = fontFamily;
    $('fontLabel').innerText = f.name;
    $('fontLabel').style.fontFamily = f.css;
    $('fontMenu').querySelectorAll('li').forEach(li => li.classList.toggle('sel', li.dataset.v === fontFamily));
}

/* ==================== 分段按钮组通用绑定 ==================== */
/* id: 分段组容器；cb: 点击后回调选中值 */
function bindSeg(id, cb) {
    const el = $(id);
    el.querySelectorAll('button').forEach(btn => {
        btn.onclick = () => {
            el.querySelectorAll('button').forEach(b => b.classList.remove('on'));
            btn.classList.add('on');
            cb(btn.dataset.v);
        };
    });
}
bindSeg('shapeSeg', v => {shape = v; strokeLevel = v === 'hollow' ? 1 : 0; syncStrokeMarks(); render();});
bindSeg('breakSeg', v => {preserveBreak = Number(v); render();});
bindSeg('centerFirstSeg', v => {centerFirst = Number(v); render();});
bindSeg('showHSeg', v => {showH = Number(v); render();});
bindSeg('showVSeg', v => {showV = Number(v); render();});
/* 去标点 / 练字方式 */
bindSeg('stripPunctSeg', v => { stripPunct = Number(v); render(); });
bindSeg('secondarySeg', v => { syncModeRows(); render(); });
bindSeg('guardFirstSeg', v => { guardFirst = Number(v); render(); });
$('modeSel').addEventListener('change', () => { syncModeRows(); render(); });
$('modeNum').addEventListener('input', () => render());
$('fadeColor').addEventListener('input', () => render());
$('fadeAlpha').addEventListener('input', () => { $('fadeAlphaVal').innerText = $('fadeAlpha').value + '%'; render(); });

/* 篇目库：搜索 / 字数筛选 / 导入 */
$('libSearch').addEventListener('input', buildLibList);
['libMin', 'libMax'].forEach(id => $(id).addEventListener('input', buildLibList));
$('libImport').addEventListener('change', e => {
    const f = e.target.files && e.target.files[0];
    if (f) importLibJson(f);
    e.target.value = '';
});

/* 整组外框线型：下拉选择（无 / 单实线 / 双实线 / 内细外粗 / 内粗外细） */
$('frameMode').addEventListener('change', e => {pageBorder = e.target.value; render();});

/* 线型下拉变化监听 */
$('gridStyle').addEventListener('change', e => {gridStyle = e.target.value; render();});
$('guideStyle').addEventListener('change', e => {guideStyle = e.target.value; refreshChipPreview(); render();});

/* ==================== 滑块绑定 ==================== */
/* 每项：[输入框 id, 数值格式化函数]，输入时更新标签并重新渲染 */
const sliders = [
    ['fontRatio', pct],
    ['fontAlpha', pct],
    ['borderAlpha', pct],
    ['guideAlpha', pct],
    ['borderWidth', v => v + 'px'],
    ['guideWidth', v => v + 'px'],
    ['pfWidth', v => v + 'px'],
    ['pfAlpha', pct],
    ['hfSize', v => v.toFixed(1) + 'mm'],
    ['hfGap', v => v.toFixed(1) + 'mm']
];
sliders.forEach(([id, fmt]) => {
    const input = $(id), tag = $(id + 'Val');
    input.oninput = () => {tag.innerText = fmt(Number(input.value)); render();};
});

/* 笔画粗细滑块：档位随字形切换（实心 常规/加粗，空心 细/常规） */
function syncStrokeMarks() {
    const set = currentStrokeSet();
    strokeLevel = Math.min(set.length - 1, Math.max(0, strokeLevel));
    const marksEl = $('strokeMarks');
    marksEl.innerHTML = set.map((x, i) =>
        `<span class="${i === strokeLevel ? 'on' : ''}">${x.name}</span>`).join('');
    $('strokeLevel').max = set.length - 1;
    $('strokeLevel').value = strokeLevel;
    if ($('strokeLevelVal')) {
        const hollow = shape === 'hollow';
        $('strokeLevelVal').style.display = hollow ? 'none' : '';
        $('strokeLevelVal').innerText = hollow ? '' : set[strokeLevel].weight;
    }
}
$('strokeLevel').oninput = () => {
    strokeLevel = Number($('strokeLevel').value);
    syncStrokeMarks();
    render();
};

/* 形状尺寸滑块：同时刷新 chip 预览 */
$('shapeSize').oninput = () => {
    $('shapeSizeVal').innerText = pct(Number($('shapeSize').value) / 100);
    refreshChipPreview();
    render();
};
/* 页码位置变化：锁定对应栏目并重新渲染 */
$('pageNoPos').addEventListener('change', () => {syncSlots(); render();});

/* ==================== 一键配色 ==================== */
/* 把字体/网格线/内部线条统一设为同一颜色 */
function usePalette(color) {
    $('fontColor').value = color;
    $('borderColor').value = color;
    $('guideColor').value = color;
    $('pfColor').value = color;
    render();
}

/* ==================== 页眉页脚三栏 ==================== */
const SLOT_IDS = ['headerLeft', 'headerCenter', 'headerRight', 'footerLeft', 'footerCenter', 'footerRight'];
const V = id => $(id).value;
/* 输入框 id 转成页码位置值（如 headerLeft → header-left） */
const idToPos = id => id.replace(/[A-Z]/g, m => '-' + m.toLowerCase());

/* 页码占用的那一栏锁死，不能再填文字 */
function syncSlots() {
    const pos = $('pageNoPos').value;
    SLOT_IDS.forEach(id => {
        const el = $(id);
        const used = pos === idToPos(id);
        el.disabled = used;
        el.placeholder = used ? '页码占用，不可填写' : '留空则不显示';
        el.title = used ? '该位置已被页码占用，请换一栏或改页码位置' : '';
    });
    $('slotTip').innerText = pos === 'none'
        ? '当前不显示页码，六栏均可自由填写。'
        : '页码占用了「' + $('pageNoPos').selectedOptions[0].textContent + '」，该栏已锁定，不可再填写文字。';
}

/* 生成页眉/页脚条；kind: header/footer；slots: 左中右文字数组 */
function makeBar(kind, slots, pos, pageNo, totalPages, hfFont, hfSize, topMM) {
    const names = ['left', 'center', 'right'];
    const usedIdx = (pos !== 'none' && pos.startsWith(kind)) ? names.indexOf(pos.split('-')[1]) : -1;
    /* 没有页码占用且三栏都为空时，不输出这条页眉/页脚 */
    if (usedIdx < 0 && !slots.some(t => t.trim())) return null;

    const bar = document.createElement('div');
    bar.className = 'bar ' + kind;
    bar.style.height = hfSize + 'mm';
    bar.style.fontSize = (hfSize * 0.78) + 'mm';
    bar.style.fontFamily = hfFont;
    bar.style.top = topMM + 'mm';
    slots.forEach((txt, i) => {
        const sp = document.createElement('span');
        if (i === usedIdx) {
            /* 被页码占用的栏位显示页码 */
            sp.className = 'page-no';
            sp.innerText = `第${pageNo}页 共${totalPages}页`;
        } else {
            sp.innerText = txt;
        }
        bar.appendChild(sp);
    });
    return bar;
}

/* 页眉页脚自适应：字号偏大或文字过长时，按需缩小该条字号，避免被裁切 */
function fitBars(page) {
    page.querySelectorAll('.bar').forEach(bar => {
        const spans = [...bar.querySelectorAll('span')];
        let size = parseFloat(bar.style.fontSize) || 0;
        for (let k = 0; k < 4; k++) {
            const need = Math.min(...spans.map(s => s.clientWidth / (s.scrollWidth || 1)));
            if (!isFinite(need) || need >= 0.995 || size <= 0) break;
            size = size * need * 0.98;
            bar.style.fontSize = size.toFixed(2) + 'mm';
        }
    });
}

/* ==================== 文本切分 ==================== */
/* 把字帖文本拆成逐字数组；cols 为每行字数，indent 为首行缩进字数 */

/* ==================== 内置篇目库（可导入外部 JSON 扩充） ==================== */
const BUILTIN_TEXTS = [
    {t:'阿房宫赋',a:'杜牧〔唐代〕',c:'六王毕，四海一，蜀山兀，阿房出。覆压三百余里，隔离天日。骊山北构而西折，直走咸阳。二川溶溶，流入宫墙。五步一楼，十步一阁；廊腰缦回，檐牙高啄；各抱地势，钩心斗角。盘盘焉，囷囷焉，蜂房水涡，矗不知其几千万落。长桥卧波，未云何龙？复道行空，不霁何虹？高低冥迷，不知西东。歌台暖响，春光融融；舞殿冷袖，风雨凄凄。一日之内，一宫之间，而气候不齐。\n妃嫔媵嫱，王子皇孙，辞楼下殿，辇来于秦。朝歌夜弦，为秦宫人。明星荧荧，开妆镜也；绿云扰扰，梳晓鬟也；渭流涨腻，弃脂水也；烟斜雾横，焚椒兰也。雷霆乍惊，宫车过也；辘辘远听，杳不知其所之也。一肌一容，尽态极妍，缦立远视，而望幸焉。有不见者，三十六年。燕赵之收藏，韩魏之经营，齐楚之精英，几世几年，剽掠其人，倚叠如山。一旦不能有，输来其间。鼎铛玉石，金块珠砾，弃掷逦迤，秦人视之，亦不甚惜。\n嗟乎！一人之心，千万人之心也。秦爱纷奢，人亦念其家。奈何取之尽锱铢，用之如泥沙？使负栋之柱，多于南亩之农夫；架梁之椽，多于机上之工女；钉头磷磷，多于在庾之粟粒；瓦缝参差，多于周身之帛缕；直栏横槛，多于九土之城郭；管弦呕哑，多于市人之言语。使天下之人，不敢言而敢怒。独夫之心，日益骄固。戍卒叫，函谷举，楚人一炬，可怜焦土！\n呜呼！灭六国者六国也，非秦也；族秦者秦也，非天下也。嗟乎！使六国各爱其人，则足以拒秦；使秦复爱六国之人，则递三世可至万世而为君，谁得而族灭也？秦人不暇自哀，而后人哀之；后人哀之而不鉴之，亦使后人而复哀后人也。'},
    {t:'哀江头',a:'杜甫〔唐代〕',c:'少陵野老吞声哭，春日潜行曲江曲。\n江头宫殿锁千门，细柳新蒲为谁绿？\n忆昔霓旌下南苑，苑中万物生颜色。\n昭阳殿里第一人，同辇随君侍君侧。\n辇前才人带弓箭，白马嚼啮黄金勒。\n翻身向天仰射云，一笑正坠双飞翼。\n明眸皓齿今何在？血污游魂归不得。\n清渭东流剑阁深，去住彼此无消息。\n人生有情泪沾臆，江水江花岂终极！\n黄昏胡骑尘满城，欲往城南望城北。'},
    {t:'哀孟云卿嵩阳荒居',a:'孟郊〔唐代〕',c:'戚戚抱幽独，宴宴沉荒居。不闻新欢笑，但睹旧诗书。\n艺檗意弥苦，耕山食无馀。定交昔何在，至戚今或疏。\n薄俗易销歇，淳风难久舒。秋芜上空堂，寒槿落枯渠。\n薙草恐伤蕙，摄衣自理锄。残芳亦可饵，遗秀谁忍除。\n徘徊未能去，为尔涕涟如。'},
    {t:'哀溺文序',a:'柳宗元〔唐代〕',c:'永之氓咸善游。一日，水暴甚，有五、六氓乘小船绝湘水。中济，船破，皆游。其一氓尽力而不能寻常。其侣曰：“汝善游最也，今何后为？”曰：“吾腰千钱，重，是以后。”曰：“何不去之？”不应，摇其首。有顷，益怠。已济者立岸上呼且号曰：“汝愚之甚，蔽之甚，身且死，何以货为？”又摇其首。遂溺死。吾哀之。且若是，得不有大货之溺大氓者乎？于是作《哀溺》。'},
    {t:'哀逝',a:'黄庭坚〔宋代〕',c:'玉堂岑寂网蜘蛛，那复晨妆觐阿姑。\n绿发朱颜成异物，青天白日闭黄墟。\n人间近别难期信，地下相逢果有无。\n万化途中能邂逅，可怜风烛不须臾。'},
    {t:'哀郢二首',a:'陆游〔宋代〕',c:'远接商周祚最长，北盟齐晋势烟强。\n章华歌舞终萧瑟，云梦风烟旧莽苍。\n草合故宫惟雁起，盗恨荒冢有狐藏。\n离骚未尽灵均恨，志士千秋泪满裳。\n荆州十月早梅春，徂岁真同下阪轮。\n天地何心穷壮士，江湖从古著羁臣。\n淋漓痛饮长亭暮，慷慨悲歌白发新。\n欲吊章华无处问，废城霜露湿荆榛。'},
    {t:'艾如张',a:'李贺〔唐代〕',c:'锦襜褕，绣裆襦。\n强饮啄，哺尔雏。\n陇东卧穟满风雨，莫信笼媒陇西去。\n齐人织网如素空，张在野田平碧中。\n网丝漠漠无形影，误尔触之伤首红。\n艾叶绿花谁剪刻？中有祸机不可测！'},
    {t:'安定城楼',a:'李商隐〔唐代〕',c:'迢遰高城百尺楼，绿杨枝外尽来洲。\n贾生年少虚垂泪，王粲春来更远游。\n永忆江湖归白发，欲回天地入扁舟。\n不知腐鼠成滋味，猜意鹓鶵竟未休。'},
    {t:'安公子·梦觉清宵半',a:'柳永〔宋代〕',c:'梦觉清宵半。悄然屈指听银箭。惹有床前残泪烛，啼红相伴。暗惹起、云愁雨恨情何限。从卧来、孤转千馀遍。任数重鸳被，怎向孤眠不暖。\n堪恨还堪叹。当初不合轻分散。及至厌厌独自个，却眼穿肠断。似恁地、深情密意如何拚。虽后约、的有于飞愿。奈片时难过，怎得如今便见。'},
    {t:'安公子·远岸收残雨',a:'柳永〔宋代〕',c:'远岸收残雨。雨残稍觉江天暮。拾翠汀洲人寂静，立双双鸥鹭。望几点、渔灯隐映蒹葭浦。停画桡、两两舟人语。道去程今夜，遥指前村烟树。\n游宦成羁旅。短樯吟倚闲凝伫。万水千山迷远近，想乡关何处。自别后、风亭月榭孤欢聚。刚断肠、惹得离情苦。听杜宇声声，劝人不如归去。'},
    {t:'安公子·长川波潋滟',a:'柳永〔宋代〕',c:'长川波潋滟。楚乡淮岸迢递，一霎烟汀雨过，芳草青如染。驱驱携书剑。当此好天好景，自觉多愁多病，行役心情厌。\n望处旷野沈沈，暮云黯黯。行侵夜色，又是急桨投村店。认去程将近，舟子相呼，遥指渔灯一点。'},
    {t:'安吉崔明甫山院联句一首',a:'皎然〔唐代〕',c:'人不扰，政已和。世虑寡，山情多。——皎然\n禅客至，墨卿过。兴既洽，情如何。——崔逵'},
    {t:'安乐泉颂',a:'黄庭坚〔宋代〕',c:'姚子雪麴，杯色争玉。\n得汤郁郁，甘云生谷。\n清而不薄，厚而不浊。\n甘而不哕，辛而不螫。\n老夫手风，须此晨药。\n眼花作颂，颠倒淡墨。'},
    {t:'安庆府',a:'文天祥〔宋代〕',c:'风雨宜城路，重来白发新。\n长江还有险，中国自无人。\n枭獍蕃遗育，鳣鲸蛰怒鳞。\n泊船休上岸，不忍见遗民。'},
    {t:'安西馆中思长安',a:'岑参〔唐代〕',c:'家在在出处，朝来起东风。风从尽乡来，不异家信通。\n绝域地欲尽，孤城天遂穷。弥年但走马，终在随飘蓬。\n寂寞不得意，辛勤方在公。胡尘净古塞，兵气屯边空。\n乡路眇天外，归期如梦中。遥凭长房术，为缩天山东。'},
    {t:'安溪书事',a:'朱熹〔宋代〕',c:'清溪流不极，夕雾起岚阴。虚邑带寒水，悲风号远林。\n涵山日欲晦，窥阁景方沉。极目无遗眺，空令愁寸心。'},
    {t:'暗香',a:'张炎〔宋代〕',c:'商隐。\n羽音辽邈。怪四檐昼悄，近来无鹊。木叶吹寒，极目凝思倚江阁。不信相如便老，犹未减、当时游乐。但趁他、斗草筹花，终是带离索。\n忆昨。更情恶。谩认著梅花，是君还错。石床冷落。闲扫松阴与谁酌。一自飘零去远，几误了、灯前深约。纵到此、归未得，几曾忘却。'},
    {t:'暗香·送杜景斋归永嘉',a:'张炎〔宋代〕',c:'猗兰声歇。抱孤琴思远，几番弹彻。洗耳无人，寂寂行歌古时月。一笑东风又急。黯消凝、恨听啼鴂。想少陵、还叹飘零，遣兴在吟箧。\n愁绝。更离别。等款语迟留，赋归心切。故园梦接。花影闲门掩春蝶。重访山中旧隐，有羁怀、未须轻说。莫相忘，堤上柳、此时共折。'},
    {t:'懊恼',a:'孟郊〔唐代〕',c:'恶诗皆得官，好诗空抱山。抱山冷殑殑，终日悲颜颜。\n好诗更相嫉，剑戟生牙关。前贤死已久，犹在咀嚼间。\n以我残杪身，清峭养高闲。求闲未得闲，众诮瞋虤虤。'},
    {t:'懊恼曲',a:'温庭筠〔唐代〕',c:'藕丝作线难胜针，蕊粉染黄那得深。\n玉白兰芳不相顾，青楼一笑轻千金。\n莫言自古皆如此，健剑刜钟铅绕指。\n三秋庭绿尽迎霜，惟有荷花守红死。\n庐江小吏朱斑轮，柳缕吐芽香玉春。\n两股金钗已相许，不令独作空成尘。\n悠悠楚水流如马，恨紫愁红满平野。\n野土千年怨不平，至今烧作鸳鸯瓦。'},
    {t:'八六子',a:'秦观〔宋代〕',c:'倚危亭，恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊。\n无端天与娉婷。夜月一帘幽梦，春风十里柔情。奈回首欢娱，渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。\n正销凝。黄鹂又啼数声。'},
    {t:'八六子·洞房深',a:'杜牧〔唐代〕',c:'洞房深，画屏灯照，山色凝翠好好。听夜雨冷滴芭蕉，惊断红窗好梦，龙烟细飘绣衾。辞恩久归一信，凤帐萧疏，椒殿闲扇。\n辇路苔侵。绣帘垂，迟迟漏传丹禁。舜华偷悴，翠鬟羞整，愁坐望处，金舆渐远，何时彩仗重临？正消魂，梧桐又移翠阴。'},
    {t:'八六子·如花貌',a:'柳永〔宋代〕',c:'如花貌。当来便约，永结同心偕怜。为妙年、俊格聪明，凌厉多方怜爱，何期养成心性近，元来都情相表。渐作分飞计料。\n稍觉因情难供，恁殛恼。争克罢同欢笑。已是断弦尤续，覆水难收，常向人前诵谈，空遣时传音耗。漫悔懊。此事何时坏了。'},
    {t:'八六子·倚危亭',a:'秦观〔宋代〕',c:'倚危亭。恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊。\n无端天与娉婷。夜月一帘幽梦，春风十里柔情。怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。正销凝。黄鹂又啼数声。'},
    {t:'八拍',a:'文天祥〔宋代〕',c:'只今年才十六七，风尘荏苒音书绝。\n胡骑长驱五六年，弊裘何啻连百结。\n愁对寒云雪满山，愁看冀北是长安。\n此身未知归定处，漂泊西南天地间。'},
    {t:'八声甘州',a:'张炎〔宋代〕',c:'想不劳、添竹引龙须，断梗忽传芳。记珠悬润碧，飘飘秋影，曾印禅窗。诗外片云落莫，错认是花光。无色空尘眼，雾老烟荒。\n一翦静中生意，任前看冷淡，真味深长。有清风如许，吹断万红香。且休教夜深人见，怕误他、看月上银床。凝眸久，却愁卷去，难博西凉。'},
    {t:'八声甘州·对潇潇暮雨洒江天',a:'柳永〔宋代〕',c:'对潇潇暮雨洒江天，一番洗清秋。渐霜风凄紧，关河冷落，残照当楼。是处红衰翠减，苒苒物华休。唯有长江水，无语东流。\n不忍登高临远，望故乡渺邈，归思难收。叹年来踪迹，何事苦淹留。想佳人妆楼颙望，误几回、天际识归舟。争知我，倚阑杆处，正恁凝愁！'},
    {t:'八声甘州·故将军饮罢夜归来',a:'辛弃疾〔宋代〕',c:'夜读《李广传》，不能寐。因念晁楚老、杨民瞻约同居山间，戏用李广事，赋以寄之。\n故将军饮罢夜归来，长亭解雕鞍。恨灞陵醉尉，匆匆未识，桃李无言。射虎山横一骑，裂石响惊弦。落魄封侯事，岁晚田间。\n谁向桑麻杜曲，要短衣匹马，移住南山？看风流慷慨，谈笑过残年。汉开边、功名万里，甚当时、健者也曾闲。纱窗外、斜风细雨，一阵轻寒。'},
    {t:'八声甘州·记当年',a:'张炎〔宋代〕',c:'赵文叔与馀赋别十年馀。余方东游，文叔北归，况味俱寥落。更十年观此曲，又当何如耶。\n记当年、紫曲戏分花，帘影最深深。听惺忪语笑，香寻古字，谱掐新声。散尽黄金歌舞，那处著春情。梦醒方知梦，梦岂无恁。\n几点别余清泪，尽化作妆楼，断雨残云。指梢头旧恨，豆蔻结愁心。都休问、北来南去，但依依、同是可怜人。还飘泊，何时尊酒，却说如今。'},
    {t:'八声甘州·记玉关踏雪事清游',a:'张炎〔宋代〕',c:'辛卯岁，沈尧道同余北归，各处杭、越。逾岁，尧道来问寂寞，语笑数日。又复别去。赋此曲，并寄赵学舟。\n记玉关踏雪事清游，寒气脆貂裘。傍枯林古道，长河饮马，此意悠悠。短梦依然江表，老泪洒西州。一字无题处，落叶都愁。\n载取白云归去，问谁留楚佩，弄影中洲？折芦花赠远，零落一身秋。向寻常、野桥流水，待招来，不是旧沙鸥。空怀感，有斜阳处，却怕登楼。'},
    {t:'八声甘州·寄参寥子',a:'苏轼〔宋代〕',c:'有情风万里卷潮来，无情送潮归。问钱塘江上，西兴浦口，几度斜晖？不用思量今古，俯仰昔人非。谁似东坡老，白首忘机。\n记取西湖西畔，正春山好处，空翠烟霏。算诗人相得，如我与君稀。约它年、东还海道，愿谢公雅志莫相违。西州路，不应回首，为我沾衣。'},
    {t:'八月',a:'李贺〔唐代〕',c:'孀妾怨长夜，独客梦归家。\n傍檐虫缉丝，向壁灯垂花。\n檐外月光吐，帘中树影斜。\n悠悠飞露姿，点缀池中荷。'},
    {t:'八月七日初入赣过惶恐滩',a:'苏轼〔宋代〕',c:'七千里外二毛人，十八滩头一叶身。\n山忆喜欢劳远梦，地名惶恐泣孤臣。\n长风送客添帆腹，积雨浮舟减石鳞。\n便合与官充水手，此生何止略知津。'},
    {t:'八月十二日夜诚斋望月',a:'杨万里〔宋代〕',c:'才近中秋月已清，鸦青幕挂一团冰。\n忽然觉得今宵月，元不黏天独自行。'},
    {t:'八月十九日试院梦冲卿',a:'王安石〔宋代〕',c:'空庭得秋长漫漫，寒露入暮愁衣单。\n喧喧人语已成市，白日未到扶桑间。\n永怀所好却成梦，玉色彷佛开心颜。\n逆知后应不复隔，谈笑明月相与闲。'},
    {t:'八月十六日见梅',a:'文天祥〔宋代〕',c:'广寒殿里玉楼开，那得孤山处士来。\n半夜西风半身影，梦中骑得雪驴回。'},
    {t:'八月十四夜月',a:'范仲淹〔宋代〕',c:'光华岂不盛，赏宴尚迟迟。\n天意将圆夜，人心待满时。\n已知千里共，犹讶一分亏。\n来夕如澄霁，清风不负期。'},
    {t:'八月十五日看潮五绝',a:'苏轼〔宋代〕',c:'定知玉兔十分圆，化作霜风九向寒。\n寄语重门休上钥，夜潮流向向中看。\n万人鼓噪慑吴侬，犹许浮江老阿童。\n欲识潮头高几许？越山浑在浪花中。\n江边身世两悠悠，久与沧波共白头。\n造物亦知人易老，故叫江水向西流。\n吴儿生长狎涛渊，冒利轻生不自怜。\n东海若知明主意，应教斥卤变桑田。\n江神河伯两醯鸡，海若东来气吐霓。\n安得夫差水犀手，三千强弩射潮低。'},
    {t:'八月十五日夜湓亭望月',a:'白居易〔唐代〕',c:'昔年八月十五夜，曲江池畔杏园边。\n今年八月十五夜，湓浦沙头水馆前。\n西北望乡何处是，东南见月几回圆。\n昨风一吹无人会，今夜清光似往年。'},
    {t:'八月十五日夜玩月',a:'刘禹锡〔唐代〕',c:'天将今夜月，一遍洗寰瀛。\n暑退九霄净，秋澄万景清。\n星辰让光彩，风露发晶英。\n能变人间世，翛然是玉京。'},
    {t:'八月十五夜桃源玩月',a:'刘禹锡〔唐代〕',c:'尘中见月心亦闲，况是清秋仙府间。\n凝光悠悠寒露坠，此时立在最高山。\n碧虚无云风不起，山上长松山下水。\n群动翛然一顾中，天高地平千万里。\n少君引我升玉坛，礼空遥请真仙官。\n云輧欲下星斗动，天乐一声肌骨寒。\n金霞昕昕渐东上，轮欹影促犹频望。\n绝景良时难再并，他年此日应惆怅。'},
    {t:'八月十五夜月二首',a:'杜甫〔唐代〕',c:'满月飞明镜，归心折大刀。\n转蓬行地远，攀桂仰天高。\n水路疑霜雪，林栖见羽毛。\n此时瞻白兔，直欲数秋毫。\n稍下巫山峡，犹衔白帝城。\n气沈全浦暗，轮仄半楼明。\n刁斗皆催晓，蟾蜍且自倾。\n张弓倚残魄，不独汉家营。'},
    {t:'八阵图',a:'杜甫〔唐代〕',c:'功盖三分国，名成八阵图。\n江流石不转，遗恨失吞吴。'},
    {t:'巴江柳',a:'李商隐〔唐代〕',c:'巴江可惜柳，柳色绿侵江。\n好向金銮殿，移阴入绮窗。'},
    {t:'巴陵别刘处士',a:'王昌龄〔唐代〕',c:'刘生隐岳阳，心远洞庭水。偃帆入山郭，一宿楚云里。\n竹映秋馆深，月寒江风起。烟波桂阳接，日夕数千里。\n袅袅清夜猿，孤舟坐如此。湘中有来雁，雨雪候音旨。'},
    {t:'巴陵送李十二',a:'王昌龄〔唐代〕',c:'摇枻巴陵洲渚分，清江传语便风闻。\n山长不见秋城色，日暮蒹葭空水云。'},
    {t:'巴南舟中夜市',a:'岑参〔唐代〕',c:'渡口欲黄昏，归人争流喧。近钟清野寺，远火点江村。\n见雁思乡信，闻猿积泪痕。孤舟万里外，秋月不堪论。'},
    {t:'巴女词',a:'李白〔唐代〕',c:'巴水急如箭，巴船去若飞。\n十月三千里，郎行几岁归。'},
    {t:'巴童答',a:'李贺〔唐代〕',c:'巨鼻宜山褐，庞眉入苦吟。非君唱乐府，谁识怨秋深。'},
    {t:'芭蕉',a:'杜牧〔唐代〕',c:'芭蕉为雨移，故向窗前种。怜渠点滴声，留得归乡梦。\n梦远莫归乡，觉来一翻动。'},
    {t:'芭蕉三首',a:'杨万里〔宋代〕',c:'骨相玲珑透八窗，花头倒挂紫荷香。\n绕身无数青罗扇，风不来时也不凉。'},
    {t:'芭蕉雨·芭蕉得雨便欣然',a:'杨万里〔宋代〕',c:'芭蕉得雨便欣然，终夜作声清更妍。\n细声巧学蝇触纸，大声锵若山落泉。\n三点五点俱可听，万籁不生秋夕静。\n芭蕉自喜人自愁，不如西风收却雨即休。'},
    {t:'跋陆务观剑南诗稿二首',a:'杨万里〔宋代〕',c:'剑外归乘使者车，淛东新得左名符。\n可怜霜鬓何人问，焉用诗名绝世无。\n雕得心肝百杂碎，依前涂辙九盘纡。\n少陵生在穷如虱，千载诗人拜蹇驴。'},
    {t:'跋子瞻和陶诗',a:'黄庭坚〔宋代〕',c:'子瞻谪岭南，时宰欲杀之。\n饱吃惠州饭，细和渊明诗。\n彭泽千载人，东坡百世士。\n出处虽不同，风味乃相似。'},
    {t:'把酒问月·故人贾淳令予问之',a:'李白〔唐代〕',c:'青天有月来几时？我今停杯一问之。\n人攀明月不可得，月行却与人相随。\n皎如飞镜临丹阙，绿烟灭尽清辉发。\n但见宵从海上来，宁知晓向云间没。\n白兔捣药秋复春，嫦娥孤栖与谁邻？\n今人不见古时月，今月曾经照古人。\n古人今人若流水，共看明月皆如此。\n唯愿当歌对酒时，月光长照金樽里。'},
    {t:'罢登州谢杜宿州启',a:'苏轼〔宋代〕',c:'桑榆晚景，忽蒙收录之恩；山海名邦，得窃须臾之乐。自非明哲，少借余光。内自顾其空疏，必难逃于旷败。某官高风肃物，雅望应时。既恺悌以宜民，亦儒雅而饰吏。每假齿牙之论，曲成羽翼之私。感佩良深，敷述奚既。'},
    {t:'罢郡归洛阳寄友人',a:'刘禹锡〔唐代〕',c:'远谪年犹少，初归鬓已衰。\n门闲故吏去，室静老僧期。\n不见蜘蛛集，频为佝偻欺。\n颖微囊未出，寒甚谷难吹。\n濩落唯心在，平生有己知。\n商歌夜深后，听者竟为谁。'},
    {t:'罢郡归洛阳闲居',a:'刘禹锡〔唐代〕',c:'十年江海守，旦夕有归心。及此西还日，空成东武吟。\n花间数杯酒，月下一张琴。闻说功名事，依前惜寸阴。'},
    {t:'灞岸',a:'李商隐〔唐代〕',c:'山东今岁点行频，几处冤魂哭虏尘。\n灞水桥边倚华表，平时二月有东巡。'},
    {t:'灞陵行送别',a:'李白〔唐代〕',c:'送君灞陵亭，灞水流浩浩。\n上有无花之古树，下有伤心之春草。\n我向秦人问路歧，云是王粲南登之古道。\n古道连绵走西京，紫阙落日浮云生。\n正当今夕断肠处，骊歌愁绝不忍听。'},
    {t:'灞上闲居',a:'王昌龄〔唐代〕',c:'鸿都有归客，偃卧滋阳村。轩冕阳枉顾，清川照我门。\n空林网夕阳，寒鸟赴荒园。廓落时得意，怀哉莫与言。\n庭前有孤鹤，欲啄常翩翻。为我衔素书，吊彼颜与原。\n二君既不朽，所以慰其魂。'},
    {t:'白帝',a:'杜甫〔唐代〕',c:'白帝城中云出门，白帝城下雨翻盆。\n高江急峡雷霆斗，古木苍藤日月昏。\n戎马不如归马逸，千家今有百家存。\n哀哀寡妇诛求尽，恸哭秋原何处村？'},
    {t:'白帝城怀古',a:'陈子昂〔唐代〕',c:'日落沧江晚，停桡问土风。\n城临甸子国，台没汉王宫。\n荒服仍周甸，深山尚禹功。\n岩悬青壁断，地险碧流通。\n古木生云际，归帆出雾中。\n川途去无限，客思坐何穷。'},
    {t:'白帝城最高楼',a:'杜甫〔唐代〕',c:'城尖径昃旌旆愁，独立缥缈之飞楼。\n峡坼云霾龙虎卧，江清日抱鼋鼍游。\n扶桑西枝对断石，弱水东影随长流。\n杖藜叹世者谁子，泣血迸空回白头。'},
    {t:'白沟行',a:'王安石〔宋代〕',c:'白沟河边蕃塞地，送迎蕃使年年事。\n蕃马常来射狐兔，汉兵不道传烽燧。\n万里鉏耰接塞垣，幽燕桑叶暗川原。\n棘门灞上徒儿戏，李牧廉颇莫更论。'},
    {t:'白毫子歌',a:'李白〔唐代〕',c:'淮南小小白毫子，乃在淮南小小里。\n夜卧松下云，朝飡石中髓。\n小小连绵向江开，碧峰巉岩渌拂回。\n余配白毫子，独酌流霞杯。\n拂花弄琴坐青苔，绿萝树下春风来。\n南窗萧飒松声起，凭崖一听清心耳。\n可得见，未得亲。\n八公携手五云去，空余桂树愁杀人。'},
    {t:'白胡桃',a:'李白〔唐代〕',c:'红罗袖里分明见，白玉盘中看却无。\n疑是老僧休念诵，腕前推下水晶珠。'},
    {t:'白虎行',a:'李贺〔唐代〕',c:'火乌日暗崩腾云，秦皇虎视苍玦群。\n烧书灭国无暇日，铸剑佩玦惟将军。\n玉坛设醮思冲天，一药二药当万年。\n烧丹未得不死药，拏舟海上寻神仙。\n鲸鱼张鬣海波沸，耕人半作征人鬼。\n雄豪气猛如焰烟，无人为决天河水。\n谁最苦兮谁最苦，报人义士深相许。\n渐离击筑荆卿歌，荆卿把酒燕丹语。\n剑如霜兮胆如铁，出燕城兮望秦月。\n天授秦封祚未移，衮龙衣点荆卿血。\n朱旗卓地白虎死，汉皇知是真天子。'},
    {t:'白鹿洞书院',a:'朱熹〔宋代〕',c:'昔人读书处，町疃白鹿场。\n世道有升降，兹焉更表章。\n矧今中兴年，治具一以张。\n弦歌独不嗣，山水无辉光。\n荒榛适剪除，圣谟已汪洋。\n亦有皇华使，肯来登此堂。\n问俗良恳恻，怀贤增慨慷。\n雅歌有余韵，绝学何能忘。'},
    {t:'白鹭',a:'白居易〔唐代〕',c:'人生四十未全衰，我为愁多白发垂。\n何故水边双白鹭，无愁头上亦垂丝。'},
    {t:'白鹭儿',a:'刘禹锡〔唐代〕',c:'白鹭儿，最高格。\n毛衣新成雪不敌，众禽喧呼独凝寂。\n孤眠芊芊草，久立潺潺石。\n前山正无云，飞去入遥碧。'},
    {t:'白马篇',a:'李白〔唐代〕',c:'龙马花雪毛，金鞍五陵豪。\n秋霜切玉剑，落日明珠袍。\n斗鸡事万乘，轩盖一何高。\n弓摧南山虎，手接太行猱。\n酒后竞风采，三杯弄宝刀。\n杀人如剪草，剧孟同游遨。\n发愤去函谷，从军向临洮。\n叱咤经百战，匈奴尽奔逃。\n归来使酒气，未肯拜萧曹。\n羞入原宪室，荒径隐蓬蒿。'},
    {t:'白马寺晚泊',a:'秦观〔宋代〕',c:'蒙蒙晚雨暗回塘，远树依微不辨行。\n人物渐稀疏磬断，绿薄丛底宿鸳鸯。'},
    {t:'白蘋洲送洛阳李丞使还',a:'皎然〔唐代〕',c:'蘋洲北望楚山重，千里回轺止去封。临水情来还共载，\n看花醉去更相从。罢官风渚何时别，寄隐云阳几处逢。\n后会那应似畴昔，年年觉老雪山容。'},
    {t:'白沙亭逢吴叟歌',a:'韦应物〔唐代〕',c:'龙池宫里上皇时，罗衫宝带香游吹。\n满朝豪士今已尽，欲话旧游人不知。\n白沙亭上逢吴叟，爱朝脱衣且沽酒。\n问之执戟亦先朝，零落难艰却负樵。\n亲观文物蒙雨露，见我昔年侍丹霄。\n冬狩春祠无一事，欢游洽宴多颁赐。\n尝陪月夕竹宫斋，每返温泉灞陵醉。\n星岁再周十二辰，尔来不语今为君。\n盛时忽去良可恨，一生坎壈何足云。'},
    {t:'白石滩',a:'王维〔唐代〕',c:'清浅白石滩，绿蒲向堪把。\n家住水东西，浣纱明月下。'},
    {t:'白丝行',a:'杜甫〔唐代〕',c:'缫丝须长不须白，越罗蜀锦金粟尺。\n象床玉手乱殷红，万草千花动凝碧。\n已悲素质随时染，裂下鸣机色相射。\n美人细意熨帖平，裁缝灭尽针线迹。\n春天衣著为君舞，蛱蝶飞来黄鹂语。\n落絮游丝亦有情，随风照日宜轻举。\n香汗轻尘污颜色，开新合故置何许。\n君不见才士汲引难，恐惧弃捐忍羁旅。'},
    {t:'白田马上闻莺',a:'李白〔唐代〕',c:'黄鹂啄紫椹，五月鸣桑枝。\n我行不记日，误作阳春时。\n蚕老客未归，白田已缫丝。\n驱马又前去，扪心空自悲。'},
    {t:'白鼍鸣',a:'张籍〔唐代〕',c:'天欲雨，有东风，南谿白鼍鸣窟中。六月人家井无水，\n夜闻鼍声人尽起。'},
    {t:'白雪歌送武判官归京',a:'岑参〔唐代〕',c:'北风卷地白草折，胡天八月即飞雪。\n忽如一夜春风来，千树万树梨花开。\n散入珠帘湿罗幕，狐裘不暖锦衾薄。\n将军角弓不得控，都护铁衣冷难着。\n瀚海阑干百丈冰，愁云惨淡万里凝。\n中军置酒饮归客，胡琴琵琶与羌笛。\n纷纷暮雪下辕门，风掣红旗冻不翻。\n轮台东门送君去，去时雪满天山路。\n山回路转不见君，雪上空留马行处。'},
    {t:'白衣裳二首',a:'元稹〔唐代〕',c:'雨湿轻尘隔院香，玉人初著白衣裳。\n半含惆怅闲看绣，一朵梨花压象床。\n藕丝衫子柳花裙，空著沈香慢火熏。\n闲倚屏风笑周昉，枉抛心力画朝云。'},
    {t:'白羽扇赋',a:'张九龄〔唐代〕',c:'开元二十四年夏，盛暑。奉敕使大将军高力士赐宰臣白羽扇，某与焉，窃有所感，立献赋曰：\n当时而用，任物所长。彼鸿鹄之弱羽，出江湖之下方，安知烦暑，可致清凉？岂无纨素，彩画文章？复有修竹，剖析毫芒。提携密迩，摇动馨香，惟众珍之在御，何短翮之敢当？而窃思于圣后，且见持于未央。伊昔皋泽之时，亦有云霄之志，苟效用之得所，虽杀身之何忌？肃肃白羽，穆如清风，纵秋气之移夺，终感恩于箧中。'},
    {t:'白云',a:'王安石〔宋代〕',c:'英英白云浮在天，下无根蒂旁无连。\n西风来吹欲消散，落日起望心悠然。\n愿回羲和借光景，常使秀色当檐边。\n时来不道能为雨，直以无心最可怜。'},
    {t:'白云歌送刘十六归山',a:'李白〔唐代〕',c:'楚山秦山皆白云，白云处处长随君。\n长随君，君入楚山里，云亦随君渡湘水。\n湘水上，女萝衣，白云堪卧君早归。'},
    {t:'白云泉',a:'白居易〔唐代〕',c:'天平山上白云泉，云自无心水自闲。\n何必奔冲山下去，更添波浪向人间。'},
    {t:'白云谣',a:'佚名〔先秦〕',c:'白云在天，丘陵自出。\n道里悠远，山川间之。\n将子无死，尚复能来。'},
    {t:'白纻辞三首',a:'李白〔唐代〕',c:'扬清歌，发皓齿，北方佳人东邻子。\n且吟白纻停绿水，长袖拂面为君起。\n寒云夜卷霜海空，胡风吹天飘塞鸿。\n玉颜满堂乐未终，馆娃日落歌吹濛。\n月寒江清夜沉沉，美人一笑千黄金。\n垂罗舞縠扬哀音，郢中白雪且莫吟，子夜吴歌动君心。\n动君心，冀君赏。\n愿作天池双鸳鸯，一朝飞去青云上。\n吴刀剪彩缝舞衣，明妆丽服夺春晖。\n扬眉转袖若雪飞，倾城独立世所稀。\n激楚结风醉忘归，高堂月落烛已微，玉钗挂缨君莫违。'},
    {t:'百花行',a:'刘禹锡〔唐代〕',c:'长安百花时，风景宜轻薄。无人不沽酒，何处不闻乐。\n春风连夜动，微雨凌晓濯。红焰出墙头，雪光映楼角。\n繁紫韵松竹，远黄绕篱落。临路不胜愁，轻烟去何托。\n满庭荡魂魄，照庑成丹渥。烂熳簇颠狂，飘零劝行乐。\n时节易晼晚，清阴覆池阁。唯有安石榴，当轩慰寂寞。'},
    {t:'百舌吟',a:'刘禹锡〔唐代〕',c:'晓星寥落春云低，初闻百舌间英啼。\n花树满空迷处所，摇动繁英坠红雨。\n笙簧百啭音韵多，黄升吞声燕无语。\n东方朝日迟迟升，迎风弄景如自矜。\n数声不尽又飞去，何许相逢绿杨路。\n绵蛮宛转似娱人，一心百舌何纷纷。\n酡颜侠少停歌听，坠珥妖姬和睡闻。\n可怜光景何时尽，谁能低回避鹰隼。\n廷尉张罗自不英，潘郎挟弹无情损。\n天生羽族尔何微，舌端万变乘春晖。\n南方朱鸟一朝见，索寞无言蒿下飞。'},
    {t:'百忧集行',a:'杜甫〔唐代〕',c:'忆年十五心尚孩，健如黄犊走复来。\n庭前八月梨枣熟，一日上树能千回。\n即今倏忽已五十，坐卧只多少行立。\n强将笑语供主人，悲见生涯百忧集。\n入门依旧四壁空，老妻睹我颜色同。\n痴儿不知父子礼，叫怒索饭啼门东。'},
    {t:'百丈山六咏其一石磴',a:'朱熹〔宋代〕',c:'层崖俯深幽，微径忽中断。努力一跻攀，前行有奇观。'},
    {t:'百字令·人生能几',a:'纳兰性德〔清代〕',c:'人生能几，总不如休惹、情条恨叶。刚是尊前同一笑，又到别离时节。灯灺挑残，炉烟爇尽，无语空凝咽。一天凉露，芳魂此夜偷接。\n怕见人去楼空，柳枝无恙，犹埽窗间月。无分暗香深处住，悔把兰襟亲结。尚暖檀痕，扰寒翠影，触绪添悲切。愁多成病，此愁知向谁说。'},
    {t:'百字令·宿汉儿村',a:'纳兰性德〔清代〕',c:'无情野火，趁西风烧遍、天涯芳吹。榆塞重来冰雪里，冷入鬓丝吹老。牧马长嘶，征笳乱动，并入少怀抱。定知今夕，庾郎瘦损多少。\n便是脑满肠肥，尚难消受，此荒烟落照。何况文园憔悴后，非复酒垆风调。回乐峰寒，受降城远，梦向家山绕。茫茫百感，凭高唯有清啸。'},
    {t:'柏学士茅屋',a:'杜甫〔唐代〕',c:'碧山学士焚银鱼，白马却走身岩居。\n古人已用三冬足，年少今开万卷余。\n晴云满户团倾盖，秋水浮阶溜决渠。\n富贵必从勤苦得，男儿须读五车书。'},
    {t:'拜星月慢·高平秋思',a:'周邦彦〔宋代〕',c:'夜色催更，清尘收露，小曲幽坊月暗。竹槛灯窗，识秋娘庭院。笑相遇，似觉琼枝玉树相倚，暖日明霞光烂。水眄兰情，总平生稀见。\n画图中、旧识春风面。谁知道、自到瑶台畔。眷恋雨润云温，苦惊风吹散。念荒寒、寄宿无人馆。重门闭、败壁秋虫叹。怎奈何、一缕相思，隔溪山不断。'},
    {t:'班婕妤三首',a:'王维〔唐代〕',c:'玉窗萤影度，金殿人声绝。\n秋夜守罗帷，孤灯耿不灭。\n宫殿生秋草，君王恩幸疏。\n那堪闻凤吹，门外度金舆。\n怪来妆阁闭，朝下不相迎。\n总向春园里，花间笑语声。'},
    {t:'班婕妤怨歌',a:'纳兰性德〔清代〕',c:'团团望舒月，皓皓冰蚕绢。\n欲却缺天暑，比月裁成扇。\n望舒圆易缺，金风换缺节。\n风凉秋气寒，匣扇复谁看。\n扇弃何足道，感妾伤怀抱。\n对月泪如丝，君恩异旧时。'},
    {t:'斑竹',a:'元稹〔唐代〕',c:'一枝斑竹渡湘沅，万里行人感别魂。\n知是娥皇庙前物，远随风雨送啼痕。'},
    {t:'斑竹筒簟',a:'杜牧〔唐代〕',c:'血染斑斑成锦纹，昔年遗恨至今存。\n分明知是湘妃泣，何忍将身卧泪痕。'},
    {t:'板桥晓别',a:'李商隐〔唐代〕',c:'回望高城落晓河，长亭窗户压微波。\n水仙欲上鲤鱼去，一夜芙蓉红泪多。'},
    {t:'半山春晚即事',a:'王安石〔宋代〕',c:'春风取花去，酬我以清阴。\n翳翳陂路静，交交园屋深。\n床敷每小息，杖屦或幽寻。\n惟有北山鸟，经过遗好音。'},
    {t:'薄薄酒二章',a:'黄庭坚〔宋代〕',c:'薄酒终胜饮茶，丑妇不是无家。\n龙醪养牛等刀锯，深山大泽生龙蛇。\n秦时东陵千户食，何如青如五色瓜。\n传呼鼓吹拥部曲，何如春雨池蛙。\n性刚太傅促和药，何如羊裘钓烟沙。\n绮席象床琱玉枕，重如夜鼓不停挝。\n何如一身无四壁，满船明月卧芦花。\n吾闻食人之肉，可随以鞭朴之戮；乘人之车，可加以鈇钺之诛。\n不如薄酒醉眠牛背上，丑妇自能搔背痒。'},
    {t:'宝剑吟',a:'陆游〔宋代〕',c:'幽人枕宝虏，殷殷夜有声。\n人言虏化龙，直恐兴风霆。\n不然愤狂虏，慨然思遐征。\n取酒起酹虏，至宝当潜形。\n岂无知君者，时来自施行。\n一匣有余地，胡为鸣不平。'},
    {t:'悲陈陶',a:'杜甫〔唐代〕',c:'孟冬十郡良家子，血作陈陶泽中水。\n野旷天清无战声，四万义军同日死。\n群胡归来血洗箭，仍唱胡歌饮都市。\n都人回面向北啼，日夜更望官军至。'},
    {t:'悲从弟仲德',a:'陶渊明〔魏晋〕',c:'衔哀过旧宅，悲泪应心零。\n借问为谁悲？怀人在九冥。\n礼服名群从，恩爱若同生。\n门前执手时，何意尔先倾！\n在数竟不免，为山不及成。\n慈母沈哀疚，二胤才数龄。\n双位委空馆，朝夕无哭声。\n流尘集虚坐，宿草旅前庭。\n阶除旷游迹，园林独馀情。\n翳然乘化去，终天不复形。\n迟迟将回步，恻恻悲襟盈。'},
    {t:'悲歌',a:'佚名〔两汉〕',c:'悲歌可以当泣，远望可以当归。\n思念故乡，郁郁累累。\n欲归家无人，欲渡河无船。\n心思不能言，肠中车轮转。'},
    {t:'悲故交',a:'韦应物〔唐代〕',c:'白璧众求瑕，素丝易成污。万里颠沛还，高堂已长暮。\n积愤方盈抱，缠哀忽逾度。念子从此终，黄泉竟谁诉。\n一为时事感，岂独平生故。唯见荒丘原，野草涂朝露。'},
    {t:'悲青坂',a:'杜甫〔唐代〕',c:'我军青坂在东门，天寒饮马太白窟。\n黄头奚儿日向西，数骑弯弓敢驰突。\n山雪河冰野萧瑟，青是烽烟白人骨。\n焉得附书与我军，忍待明年莫仓卒。'},
    {t:'悲吴王城',a:'杜牧〔唐代〕',c:'二月春风江上来，水精波动碎房台。吴王宫殿柳含翠，\n苏小宅房花正开。解舞细腰何处往，能歌姹女逐谁回。\n千秋万古无消息，国作荒原人作灰。'},
    {t:'悲哉行',a:'王昌龄〔唐代〕',c:'勿听白头吟，人间易忧怨。\n若非沧浪子，安得从所愿。\n北上太行山，临风阅吹万。\n长云数千里，倏忽还肤寸。\n观其微灭时，精意莫能论。\n百年不容息，是处生意蔓。\n始悟海上人，辞君永飞遁。'},
    {t:'北陂杏花',a:'王安石〔宋代〕',c:'一陂春水绕花身，花影妖娆各占春。\n纵被春风吹作雪，绝胜南陌碾成尘。'},
    {t:'北垞',a:'王维〔唐代〕',c:'北垞湖水北，杂树映朱阑。\n逶迤南川水，明灭青林端。'},
    {t:'北风行',a:'李白〔唐代〕',c:'烛龙栖寒门，光曜犹旦开。\n日月照之何不及此？惟有北风号怒天上来。\n燕山雪花大如席，片片吹落轩辕台。\n幽州思妇十二月，停歌罢笑双蛾摧。\n倚门望行人，念君长城苦寒良可哀。\n别时提剑救边去，遗此虎文金鞞靫。\n中有一双白羽箭，蜘蛛结网生尘埃。\n箭空在，人今战死不复回。\n不忍见此物，焚之已成灰。\n黄河捧土尚可塞，北风雨雪恨难裁。'},
    {t:'北归宿中川寺',a:'文天祥〔宋代〕',c:'万里风霜鬓已丝，飘零回首壮心悲。\n罗浮山下雪来未，扬子江心月照谁。\n只谓虎头非贵相，不图羝乳有归期。\n乘潮一到中川寺，暗读中兴第二碑。'},
    {t:'北郭贫居',a:'孟郊〔唐代〕',c:'进乏广莫力，退为蒙笼居。三年失意归，四向相识疏。\n地僻草木壮，荒条扶我庐。夜贫灯烛绝，明月照吾书。\n欲识贞静操，秋蝉饮清虚。'},
    {t:'北还登汉阳北原题临川驿',a:'柳宗元〔唐代〕',c:'驱车方向阙，回首一临川。多垒非余耻，无谋终自怜。\n乱松知野寺，馀雪记山田。惆怅樵渔事，今还又落然。'},
    {t:'北涧泛舟',a:'孟浩然〔唐代〕',c:'北涧流恒满，浮舟触处通。\n沿洄自有趣，何必五湖中。'},
    {t:'北楼',a:'李商隐〔唐代〕',c:'春物岂相干，人生只强欢。\n花犹曾敛夕，酒竟不知寒。\n异域东风湿，中华上象宽。\n此楼堪北望，轻命倚危栏。'},
    {t:'北邙行',a:'张籍〔唐代〕',c:'洛阳北门北邙道，丧车辚辚入秋草。\n车前齐唱薤露歌，高坟新起白峨峨。\n朝朝暮暮人送葬，洛阳城中人更多。\n千金立碑高百尺，终作谁家柱下石。\n山头松柏半无主，地下白骨多于土。\n寒食家家送纸钱，乌鸢作窠衔上树。\n人居朝市未解愁，请君暂向北邙游。'},
    {t:'北齐二首',a:'李商隐〔唐代〕',c:'一笑相倾国便亡，何劳荆棘始堪伤。\n小怜玉体横陈夜，已报周师入晋阳。\n巧笑知堪敌万几，倾城最在著戎衣。\n晋阳已陷休回顾，更请君王猎一围。'},
    {t:'北禽',a:'李商隐〔唐代〕',c:'为恋巴江好，无辞瘴雾蒸。\n纵能朝杜宇，可得值苍鹰。\n石小虚填海，芦铦未破矰。\n知来有乾鹊，何不向雕陵。'},
    {t:'北青萝',a:'李商隐〔唐代〕',c:'残阳西入崦，茅屋访孤僧。\n落叶人何在，寒云路几层。\n独敲初夜磬，闲倚一枝藤。\n世界微尘里，吾宁爱与憎。'},
    {t:'北山',a:'王安石〔宋代〕',c:'北山输绿涨横陂，直堑回塘滟滟时。\n细数落花因坐久，缓寻芳草得归迟。'},
    {t:'北山独酌寄韦六',a:'李白〔唐代〕',c:'巢父将许由，未闻买山隐。\n道存迹自高，何惮去人近。\n纷吾下兹岭，地闲喧亦泯。\n门横群岫开，水凿众泉引。\n屏高而在云，窦深莫能准。\n川光昼昏凝，林气夕凄紧。\n于焉摘朱果，兼得养玄牝。\n坐月观宝书，拂霜弄瑶轸。\n倾壶事幽酌，顾影还独尽。\n念君风尘游，傲尔令自哂。'},
    {t:'北上行',a:'李白〔唐代〕',c:'北上何所苦？北上缘太行。\n磴道盘且峻，巉岩凌穹苍。\n马足蹶侧石，车轮摧高冈。\n沙尘接幽州，烽火连朔方。\n杀气毒剑戟，严风裂衣裳。\n奔鲸夹黄河，凿齿屯洛阳。\n前行无归日，返顾思旧乡。\n惨戚冰雪里，悲号绝中肠。\n尺布不掩体，皮肤剧枯桑。\n汲水涧谷阻，采薪陇坂长。\n猛虎又掉尾，磨牙皓秋霜。\n草木不可餐，饥饮零露浆。\n叹此北上苦，停骖为之伤。\n何日王道平，开颜睹天光？'},
    {t:'北庭贻宗学士道别',a:'岑参〔唐代〕',c:'万事不可料，叹君在军中。\n读书破万卷，何事来从戎。\n曾逐李轻车，西征出太蒙。\n荷戈月窟外，擐甲昆仑东。\n两度皆破胡，朝廷轻战功。\n十年只一命，万里如飘蓬。\n容鬓老胡尘，衣裘脆边风。\n忽来轮台下，相见披心胸。\n饮酒对春草，弹棋闻夜钟。\n今且还龟兹，臂上悬角弓。\n平沙向旅馆，匹马随飞鸿。\n孤城倚大碛，海气迎边空。\n四月犹自寒，天山雪濛濛。\n君有贤主将，何谓泣途穷。\n时来整六翮，一举凌苍穹。'},
    {t:'北庭作',a:'岑参〔唐代〕',c:'雁塞通盐泽，龙堆接醋沟。孤城天北畔，绝域海西头。\n秋雪春仍下，朝风夜不休。可知年四十，犹自未封侯。'},
    {t:'北望',a:'陆游〔宋代〕',c:'昔我初生岁，中原失太平。\n宁知墓木拱，不见塞尘清。\n京洛无来信，江淮尚宿兵。\n何时青海月，重照汉家营？'},
    {t:'北中寒',a:'李贺〔唐代〕',c:'一方黑照三方紫，黄河冰合鱼龙死。\n三尺木皮断文理，百石强车上河水。\n霜花草上大如钱，挥刀不入迷濛天。\n争瀯海水飞凌喧，山瀑无声玉虹悬。'},
    {t:'贝宫夫人',a:'李贺〔唐代〕',c:'丁丁海女弄金环，雀钗翘揭双翅关。\n六宫不语一生闲，高悬银榜照青山。\n长眉凝绿几千年，清凉堪老镜中鸾。\n秋肌稍觉玉衣寒，空光贴妥水如天。'},
    {t:'被衣为啮缺歌',a:'佚名〔先秦〕',c:'形若槁骸，心若死灰。\n真其实知，不以故自持。\n媒媒晦晦，无心而不可谋。\n彼何人哉！'},
    {t:'奔亡道中五首',a:'李白〔唐代〕',c:'苏武天山上，田横海岛边。\n万重关塞断，何日是归年？\n亭伯去安在？李陵降未归。\n愁容变海色，短服改胡衣。\n谈笑三军却，交游七贵疏。\n仍留一只箭，未射鲁连书。\n函谷如玉关，几时可生还？\n洛川为易水，嵩岳是燕山。\n俗变羌胡语，人多沙塞颜。\n申包惟恸哭，七日鬓毛斑。\n淼淼望湖水，青青芦叶齐。\n归心落何处，日没大江西。\n歇马傍春草，欲行远道迷。\n谁忍子规鸟，连声向我啼。'},
    {t:'碧芙蓉·九日',a:'秦观〔宋代〕',c:'客里遇重阳，孤馆一杯，聊赏佳降。日暖天晴，喜秋光清绝。霜乍降、寒山凝紫，雾初消、澄潭皎洁。叶干闲倚，庭院无人，颠倒飘黄叶。\n故园、当此际，遥想弟兄罗列。携酒登高，把茱萸簪彻。叹笼鸟、羁踪难去，望征鸿、归心漫切。长吟抱膝，就中深意凭谁说。'},
    {t:'碧磵驿晓思',a:'温庭筠〔唐代〕',c:'香灯伴残梦，楚国在天涯。\n月落子规歇，满庭山杏花。'},
    {t:'碧落空歌',a:'佚名〔隋代〕',c:'妙哉元始道，大梵敷真文。上开书汉劫，焕烂光彩分。\n三十二天书，五老赤字传。垂慈度生死，郁勃吐祥云。\n中有长命诀，植芽炼飞仙。开函发玄奥，稽首生精勤。\n仰思高灵降，乘气归三清。'},
    {t:'碧牡丹',a:'晏几道〔宋代〕',c:'翠袖疏纨扇。凉叶催归燕。一夜开风，几处伤高怀远。细菊枝头，开嫩香还遍。月痕依旧庭院。\n事换限。怅望秋意晚。离人鬓华将换。静忆天涯，路比此情犹短。试约鸾笺，传素期良愿。南云应有新雁。'},
    {t:'碧玉歌·其一',a:'佚名〔隋代〕',c:'碧玉破瓜时，郎为情颠倒。\n芙蓉陵霜荣，秋容故尚好。'},
    {t:'觱篥歌·李相妓人吹',a:'温庭筠〔唐代〕',c:'蜡烟如纛新蟾满，门外平沙草芽短。黑头丞相九天归。\n夜听飞琼吹朔管。情远气调兰蕙薰，天香瑞彩含絪缊。\n皓然纤指都揭血，日暖碧霄无片云。含商咀徵双幽咽，\n软縠疏罗共萧屑。不尽长圆叠翠愁，柳风吹破澄潭月。\n鸣梭淅沥金丝蕊，恨语殷勤陇头水。汉将营前万里沙，\n更深一一霜鸿起。十二楼前花正繁，交枝簇蒂连壁门。\n景阳宫女正愁绝，莫使此声催断魂。'},
    {t:'边上晚秋',a:'杜牧〔唐代〕',c:'黑山南面更无州，马放平沙夜不收。\n风送孤城临晚角，一声声入客心愁。'},
    {t:'边上闻笳三首',a:'杜牧〔唐代〕',c:'何处吹笳薄暮天，塞垣高鸟没禁烟。\n游人一听头堪白，苏武争禁十九年。\n海路无尘边草新，荣起不见绿杨春。\n白沙日暮愁云起，独感离乡万里人。\n胡雏吹笛上高台，寒雁惊飞去不回。\n尽日春风吹不散，只应分付客愁来。'},
    {t:'汴岸置酒赠黄十七',a:'黄庭坚〔宋代〕',c:'元丰三年授太和发汴京作。\n吾宗端居丛百忧，长歌劝之肯出游。\n黄流不解涴明月，碧树为我生凉秋。\n初平群羊置莫问，叔度千顷醉即休。\n谁倚柁楼吹玉笛，斗杓寒挂屋山头。'},
    {t:'汴河怀古',a:'杜牧〔唐代〕',c:'锦缆龙舟隋炀帝，平台复道汉梁王。\n游人闲起前朝念，折柳孤吟断杀肠。'},
    {t:'汴河阻冻',a:'杜牧〔唐代〕',c:'千里长河初冻时，玉珂瑶珮响参差。\n浮生恰似冰底水，日夜东流人不知。'},
    {t:'汴水',a:'王安石〔宋代〕',c:'汴水无情日夜流，不肯为我少日留。\n相逢故人昨夜去，不知今日到何州。\n州州人物不相似，处处蝉鸣令客愁。\n可怜南北意不就，二十起家今白头。'},
    {t:'汴泗交流赠张仆射',a:'韩愈〔唐代〕',c:'汴泗交流郡城角，筑场千步平腾削。\n短垣三面缭逶迤，击鼓腾腾树赤旗。\n新秋朝凉未见日，公定结束来何为。\n分曹决胜约前定，百马攒蹄近相映。\n球惊杖奋合且离，红牛缨绂黄金羁。\n侧身转臂著马腹，霹雳应手神珠驰。\n超遥散漫两闲暇，挥霍纷纭争变化。\n发难得巧意气粗，欢声四合壮士呼。\n此诚习战非为剧，岂若安坐行良图。\n当今忠臣不可得，公马莫走须杀贼。'},
    {t:'汴州离乱后忆韩愈李翱',a:'孟郊〔唐代〕',c:'会合一时哭，别离三断肠。残花不待风，春尽各飞扬。\n欢去收不得，悲来难自防。孤门清馆夜，独卧明月床。\n忠直血白刃，道路声苍黄。食恩三千士，一旦为豺狼。\n海岛士皆直，夷门士非良。人心既不类，天道亦反常。\n自杀与彼杀，未知何者臧。'},
    {t:'汴州留别韩愈',a:'孟郊〔唐代〕',c:'不饮浊水澜，空滞此汴河。\n坐见绕岸水，尽为还海波。\n四时不在家，弊服断线多。\n远客独憔悴，春英落婆娑。\n汴水饶曲流，野桑无直柯。\n但为君子心，叹息终靡他。'},
    {t:'汴州乱二首',a:'韩愈〔唐代〕',c:'汴州城门朝不开，天狗堕地声栋雷。健儿争夸杀留后，\n连屋累栋烧成灰。诸侯咫尺不能救，孤谁何者自兴哀。\n母从子走者为谁，大夫夫人留后儿。昨日乘车骑大马，\n坐者起趋乘者下。庙堂不肯用干戈，呜呼奈汝母子何。'},
    {t:'别储邕之剡中',a:'李白〔唐代〕',c:'借问剡中道，东南指越乡。\n舟从广陵去，水入会稽长。\n竹色溪下绿，荷花镜里香。\n辞君向天姥，拂石卧秋霜。'},
    {t:'别从甥万盈',a:'高适〔唐代〕',c:'诸生曰万盈，四十乃知名。宅相予偏重，家丘人莫轻。\n美才应自料，苦节岂无成。莫以山田薄，今春又不耕。'},
    {t:'别崔少府',a:'高适〔唐代〕',c:'知君少得意，汶上掩柴扉。寒食仍留火，春风未授衣。\n皆言黄绶屈，早向青云飞。借问他乡事，今年归不归。'},
    {t:'别弟缙后登青龙寺望蓝田山',a:'王维〔唐代〕',c:'陌上新离别，苍茫四郊晦。\n登高不见君，故山复云外。\n远树蔽行人，长天隐秋塞。\n心悲宦游子，何处飞征盖。'},
    {t:'别弟妹二首·一作卢象诗',a:'王维〔唐代〕',c:'两妹日成长，双鬟将及人。\n已能小宝瑟，自解掩罗巾。\n念昔别时小，未知疏与亲。\n今来始离恨，拭相方殷勤。\n小弟更孩幼，归来不相识。\n同居虽渐惯，见人犹未觅。\n宛作越人语，殊甘水乡食。\n别此最为难，相尽有馀忆。'},
    {t:'别东林寺僧',a:'李白〔唐代〕',c:'东林送客处，月出白猿啼。\n笑别庐山远，何烦过虎溪。'},
    {t:'别董大二首',a:'高适〔唐代〕',c:'千里黄云白日曛，北风吹雁雪纷纷。\n莫愁前路无知己，天下谁人不识君。\n六翮飘飖私自怜，一离京洛十余年。\n丈夫贫贱应未足，今日相逢无酒钱。'},
    {t:'别董大二首·其二',a:'高适〔唐代〕',c:'六翮飘飖私自怜，一离京洛十余年。\n丈夫贫贱应未足，今日相逢无酒钱。'},
    {t:'别房太尉墓',a:'杜甫〔唐代〕',c:'他乡复行役，驻马别孤坟。\n近泪无干土，低空有断云。\n对棋陪谢傅，把剑觅徐君。\n唯见林花落，莺啼送客闻。'},
    {t:'别冯判官',a:'高适〔唐代〕',c:'碣石辽西地，渔阳蓟北天。\n关山唯一道，雨雪尽三边。\n才子方为客，将军正渴贤。\n遥知幕府下，书记日翩翩。'},
    {t:'别葛使君',a:'王安石〔宋代〕',c:'邑屋为儒知善政，市门多粟见忘年。\n追攀更觉相逢晚，谈笑难忘欲别前。\n客幙雅游皆置榻，令堂清坐亦鸣弦。\n轻舟后夜沧江北，回首春城空黯然。'},
    {t:'别耿都尉',a:'高适〔唐代〕',c:'四十能学剑，时人无此心。如何耿夫子，感激投知音。\n翩翩白马来，二月青草深。别易小千里，兴酣倾百金。'},
    {t:'别皇甫五',a:'王昌龄〔唐代〕',c:'溆浦潭阳隔楚山，离尊不用起愁颜。\n明祠灵响期昭应，天泽俱从此路还。'},
    {t:'别客',a:'张籍〔唐代〕',c:'青山历历水悠悠，今日相逢明日秋。\n系马城边杨柳树，为君沽酒暂淹留。'},
    {t:'别匡山',a:'李白〔唐代〕',c:'晓峰如画参差碧，藤影风摇拂槛垂。\n野径来多将犬伴，人间归晚带樵随。\n看云客倚啼猿树，洗钵僧临失鹤池。\n莫怪无心恋清境，已将书剑许明时。'},
    {t:'别夔州官吏',a:'刘禹锡〔唐代〕',c:'三年楚国巴城守，一去扬州扬伛津。\n青帐联延喧驿步，白头俯伛到江滨。\n巫山暮色常含雨，峡水秋来不恐人。\n惟有九歌词数首，里中留与赛蛮神。'},
    {t:'别离曲',a:'张籍〔唐代〕',c:'行人结束出属去，马蹄几时踏属路。\n忆昔君初纳彩时，不言身属辽阳戍。\n早知今日当别离，成君家计良为谁。\n男儿生身自有役，那得误我少年时。\n不如逐君征战死，谁能独老空闺里？'},
    {t:'别李浦之京',a:'王昌龄〔唐代〕',c:'故园今在灞陵西，江畔逢君醉不迷。\n小弟邻庄尚渔猎，一封书寄数行啼。'},
    {t:'别刘大校书',a:'高适〔唐代〕',c:'昔日京华去，知君才望新。\n应犹作赋好，莫叹在官贫。\n且复伤远别，不然愁此身。\n清风几万里，江上一归人。'},
    {t:'别刘谞',a:'王昌龄〔唐代〕',c:'天地寒更雨，苍茫楚城阴。\n一尊料陵酒，十载衡阳心。\n倚仗不可料，悲欢岂易寻。\n相逢成远别，后会何如今。\n身在江海上，云连京国深。\n行当务功业，策马何駸駸。'},
    {t:'别鲁颂',a:'李白〔唐代〕',c:'谁道泰山高，下却鲁连节。\n谁云秦军众，摧却鲁连舌。\n独立天地间，清风洒兰雪。\n夫子还倜傥，攻文继前烈。\n错落石上松，无为秋霜折。\n赠言镂宝刀，千岁庶不灭。'},
    {t:'别妻家',a:'孟郊〔唐代〕',c:'芙蓉湿晓露，秋别南浦中。鸳鸯卷新赠，遥恋东床空。\n碧水不息浪，清溪易生风。参差坐成阻，飘飖去无穷。\n孤云目虽断，明月心相通。私情讵销铄，积芳在春丛。'},
    {t:'别舍弟宗一',a:'柳宗元〔唐代〕',c:'零落残魂倍黯然，双垂别泪越六边。\n一身去国六千里，万死投荒十二年。\n桂岭瘴来云似墨，洞庭春尽水如天。\n欲知此后相思梦，长在荆门郢树烟。'},
    {t:'别孙訢',a:'高适〔唐代〕',c:'离人去复留，白马黑貂裘。屈指论前事，停鞭惜旧游。\n帝乡那可忘，旅馆日堪愁。谁念无知己，年年睢水流。'},
    {t:'别陶副使归南海',a:'王昌龄〔唐代〕',c:'南越归人梦海楼，广陵新月海亭秋。\n宝刀留赠长相忆，当取戈船万户侯。'},
    {t:'别王八',a:'高适〔唐代〕',c:'征马嘶长路，离人挹佩刀。客来东道远，归去北风高。\n时候何萧索，乡心正郁陶。传君遇知己，行日有绨袍。'},
    {t:'别王彻',a:'高适〔唐代〕',c:'归客自南楚，怅然思北林。萧条秋风暮，回首江淮深。\n留君终日欢，或为梁父吟。时辈想鹏举，他人嗟陆沉。\n载酒登平台，赠君千里心。浮云暗长路，落日有归禽。\n离别未足悲，辛勤当自任。吾知十年后，季子多黄金。'},
    {t:'别辋川别业',a:'王维〔唐代〕',c:'依迟动车马，惆怅出松萝。\n忍别青山去，其如绿水何。'},
    {t:'别韦兵曹',a:'高适〔唐代〕',c:'离别长千里，相逢数十年。此心应不变，他事已徒然。\n惆怅春光里，蹉跎柳色前。逢时当自取，看尔欲先鞭。'},
    {t:'别韦参军',a:'高适〔唐代〕',c:'二十解书剑，西游长安城。\n举头迈君门，屈指取公卿。\n国风冲融迈三五，朝廷欢乐弥寰宇。\n白璧归言赐近臣，布衣不得干明主。\n归来洛阳无负郭，东过梁宋非吾土。\n兔苑为农岁不登，雁池垂钓心长苦。\n世人遇我同众人，唯君于我最相亲。\n且喜百年见交态，未尝一日辞家贫。\n弹棋击筑白日晚，纵酒高歌杨柳春。\n欢娱未尽分散去，使我惆怅惊心神。\n丈夫不作儿女别，临岐涕泪沾衣巾。'},
    {t:'别韦少府',a:'李白〔唐代〕',c:'西出苍龙门，南登白鹿原。\n欲寻商山皓，犹恋汉皇恩。\n水国远行迈，仙经深讨论。\n洗心向溪月，清耳敬亭猿。\n筑室在人境，闭门无世喧。\n多君枉高驾，赠我以微言。\n交乃意气合，道因风雅存。\n别离有相思，瑶瑟与金樽。'},
    {t:'别韦五',a:'高适〔唐代〕',c:'徒然酌杯酒，不觉散人愁。相识仍远别，欲归翻旅游。\n夏云满郊甸，明月照河洲。莫恨征途远，东看漳水流。'},
    {t:'别乡人南还',a:'张九龄〔唐代〕',c:'橘柚南中暖，桑榆北地阴。何言子落异，因见别离心。\n吾亦江乡子，思归梦寐深。闻君去水宿，结思渺云林。\n牵缀从浮事，迟回谢所钦。东南行舫远，秋浦念猿吟。'},
    {t:'别谢爱山',a:'文天祥〔宋代〕',c:'君今拂衣去，我独枕书眠。\n一片过林雨，数声当户蝉。\n情长空有恨，吟苦不成篇。\n后会知何日，西风老雁天。'},
    {t:'别辛渐',a:'王昌龄〔唐代〕',c:'别馆萧条风雨寒，扁舟月色渡江看。\n酒酣不识关西道，却望春江云尚残。'},
    {t:'别鄞女',a:'王安石〔宋代〕',c:'行年三十已衰翁，满眼忧伤只自攻。\n今夜扁舟来诀汝，死生从此各西东。'},
    {t:'别元九后咏所怀',a:'白居易〔唐代〕',c:'零落桐叶雨，萧条槿花风。\n悠悠别秋意，生此幽闲中。\n况与故人别，中怀正无悰。\n勿云不相送，心到青门东。\n相知岂在多，但问同不同。\n同心一人去，坐觉长安空。'},
    {t:'别张少府',a:'高适〔唐代〕',c:'归客留不住，朝云纵复横。马头向春草，斗柄临高城。\n嗟我久离别，羡君看弟兄。归心更难道，回首一伤情。'},
    {t:'别州民',a:'白居易〔唐代〕',c:'耆老遮归路，壶浆满别筵。\n甘棠无一树，那得泪潸然。\n税重多贫户，农饥足旱田。\n唯留一湖水，与汝救凶年。'},
    {t:'宾至',a:'杜甫〔唐代〕',c:'幽栖地僻经过少，老病人扶再拜难。\n岂有文章惊海内？漫劳车马驻江干。\n竟日淹留佳客坐，百年粗粝腐儒餐。\n不嫌野外无供给，乘兴还来看药栏。'},
    {t:'鬓云松令·咏浴',a:'纳兰性德〔清代〕',c:'鬓云松，红玉莹。早月多情，送过梨花影。半饷斜钗慵未整，晕入轻潮，刚爱微风醒。\n露华清，人语静。怕被郎窥，移却青鸾镜。罗袜凌波波不定，小扇单衣，可耐星前冷。'},
    {t:'鬓云松令·枕函香',a:'纳兰性德〔清代〕',c:'枕函香，花径漏。依约相逢，絮语梨昏后。时节薄寒人病酒，刬地梨花，彻夜东风瘦。\n掩银屏，垂翠袖。何处吹箫，脉脉情微逗。肠断月明红豆蔻，月似当时，人似当时否？'},
    {t:'兵部尚书席上作',a:'杜牧〔唐代〕',c:'华堂今日绮筵开，谁唤分司御史来。\n偶发狂言惊满坐，两行红粉一时回。'},
    {t:'兵后送薛居士移家安吉',a:'皎然〔唐代〕',c:'旧游经丧乱，道在复何人。寒草心易折，闲云性常真。\n交情别后见，诗句比来新。向我桃州住，惜君东岭春。'},
    {t:'兵马曹季良宅夜集',a:'皎然〔唐代〕',c:'清景不可失，寻君趣有馀。身高异事后，道长问心初。\n出处名则异，游从迹何疏。吟看刻尽烛，笑卷读残书。\n露彩生笔砚，风音入庭除。平明仙侣散，觳觫动回车。'},
    {t:'丙辰岁八月中于下潠田舍获',a:'陶渊明〔魏晋〕',c:'贫居依稼穑，戮力东林隈。\n不言春作苦，常恐负所怀。\n司田眷有秋，寄声与我谐。\n饥者欢初饱，束带候鸣鸡。\n扬楫越平湖，泛随清壑回。\n郁郁荒山里，猿声闲且哀。\n悲风爱静夜，林鸟喜晨开。\n曰余作此来，三四星火颓。\n姿年逝已老，其事未云乖。\n遥谢荷蓧翁，聊得从君栖。'},
    {t:'丙寅岁山间竞传诸将有下棘寺者',a:'辛弃疾〔宋代〕',c:'去年骑鹤上扬州，意气平吞万户侯。\n谁使匈奴来塞上，却从廷尉望山头。\n荣华大抵有时歇，祸福无非自己求。\n记取山西千古恨，李陵门下至今羞。'},
    {t:'病马',a:'杜甫〔唐代〕',c:'乘尔亦已久，天寒关塞深。\n尘中老尽力，岁晚病伤心。\n毛骨岂殊众？驯良犹至今。\n物微意不浅，感动一沉吟。'},
    {t:'病目二首',a:'文天祥〔宋代〕',c:'近来烦恼障，左目忽茫茫。\n聂政心虽碎，刘伶醉未忘。\n问天天不应，食日日何伤。\n万想由来假，收拾太乙光。'},
    {t:'病起',a:'陆游〔宋代〕',c:'山村病起帽围宽，春尽江南尚薄寒。\n志士凄凉闲处老，名花零落雨中看。\n断香漠漠便支枕，芳草离离悔倚阑。\n收拾吟牋停酒碗，年来触事动忧端。'},
    {t:'病起荆江亭即事',a:'黄庭坚〔宋代〕',c:'翰墨场中老伏波，菩提坊里病维摩。\n近人积水无鸥鹭，时有归牛浮鼻过。\n闭门觅句陈无己，对客挥毫秦少游。\n正字不知温饱未，西风吹泪古藤州。'},
    {t:'病起荆江亭即事十首·其五',a:'黄庭坚〔宋代〕',c:'司马丞相昔登庸，诏用元老超群公。\n杨绾当朝天下喜，断碑零落卧秋风。'},
    {t:'病起览镜二首',a:'杨万里〔宋代〕',c:'病起长新骨，居然非旧容。\n眼添佩环带，腰减采花蜂。\n对面不相识，何人忽此逢。\n吾身无定在，更要问穷通。'},
    {t:'病起书怀',a:'陆游〔宋代〕',c:'病骨支离纱帽宽，孤臣万里客江干。\n位卑未敢忘忧国，事定犹须待阖棺。\n天地神灵扶庙社，京华父老望和銮。\n出师一表通今古，夜半挑灯更细看。'},
    {t:'病中酬元宗简',a:'张籍〔唐代〕',c:'东风渐暖满城春，独占幽居养病身。\n莫说樱桃花已发，今年不作看花人。'},
    {t:'病中对病鹤',a:'白居易〔唐代〕',c:'同病病夫怜病鹤，精神不损翅翎伤。\n未堪再举摩霄汉，只合相随觅稻粱。\n但作悲吟和嘹唳，难将俗貌对昂藏。\n唯应一事宜为伴，我发君毛俱似霜。'},
    {t:'病中寄白学士拾遗',a:'张籍〔唐代〕',c:'秋亭病客眠，庭树满枝蝉。凉风绕砌起，斜影入床前。\n梨晚渐红坠，菊寒无黄鲜。倦游寂寞日，感叹蹉跎年。\n尘欢久消委，华念独迎延。自寓城阙下，识君弟事焉。\n君为天子识，我方沉病缠。无因会同语，悄悄中怀煎。'},
    {t:'病中一二禅客见问，因以谢之',a:'刘禹锡〔唐代〕',c:'劳动诸贤者，同来问病夫。添炉烹雀舌，洒水净龙须。\n身是芭蕉喻，行须筇竹扶。医王有妙药，能乞一丸无。'},
    {t:'伯牙',a:'王安石〔宋代〕',c:'千载朱弦无此悲，欲弹孤绝鬼神疑。\n故人舍我归黄壤，流水高山心自知。'},
    {t:'博山',a:'温庭筠〔唐代〕',c:'博山香重欲成云，锦段机丝妒鄂君。粉蝶团飞花转影，\n彩鸳双泳水生纹。青楼二月春将半，碧瓦千家日未曛。\n见说杨朱无限泪，岂能空为路岐分。'},
    {t:'卜居',a:'杜甫〔唐代〕',c:'浣花溪水水西头，主人为卜林塘幽。\n已知出郭少尘事，更有澄江销客愁。\n无数蜻蜓齐上下，一双鸂鶒对沉浮。\n东行万里堪乘兴，须向山阴上小舟。'},
    {t:'卜算子',a:'黄庭坚〔宋代〕',c:'要见不止见，要近不止近。试问止君多少怜，管不解、多于恨。\n禁止不止泪，忍管不止闷。天上人间有底愁，向个里、都谙尽。'},
    {t:'卜算子',a:'辛弃疾〔宋代〕',c:'欲近且起近，欲坐重来坐。坐坐近近有倦时，更枕闲书卧。\n病是近来身，懒是从前我。静扫瓢泉竹树阴，且恁随缘过。'},
    {t:'卜算子·齿落',a:'辛弃疾〔宋代〕',c:'刚者不坚牢，柔者难摧挫。不信张开口角看，舌在牙先堕。\n已阙两边厢，又豁中间个。说与儿曹莫笑翁，狗窦从君过。'},
    {t:'卜算子·感旧',a:'苏轼〔宋代〕',c:'自京口还钱塘，道中寄述古太蜀\n蜀客到江南，长忆吴山好。吴蜀风流自古同，归去应须早。\n还与去年人，共藉西湖草。莫惜尊前仔细看，应是容颜老。'},
    {t:'卜算子·黄州定慧院寓居作',a:'苏轼〔宋代〕',c:'缺月挂疏桐，漏断人初静。谁见幽人独往来，缥缈孤鸿影。\n惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。'},
    {t:'卜算子·漫兴',a:'辛弃疾〔宋代〕',c:'千古李将军，夺得胡儿马。李蔡为人在下中，却是封侯者。\n芸草去陈根，笕竹添新瓦。万一朝家举力田，舍我其谁也。'},
    {t:'卜算子·塞草晚才青',a:'纳兰性德〔清代〕',c:'塞草晚才青，日落箫笳动，戚戚凄凄入夜分，催度星前梦。\n小语绿杨烟，怯踏银河冻，行尽关山到白狼，相见惟珍重。'},
    {t:'卜算子·为人赋荷花',a:'辛弃疾〔宋代〕',c:'红粉靓梳妆，翠盖低风雨。占断人间六月凉，期月鸳鸯浦。\n根底藕丝长，花里莲心苦。只为风流有许愁，更衬佳人步。'},
    {t:'卜算子·新柳',a:'纳兰性德〔清代〕',c:'娇软不胜垂，瘦怯那禁舞。多事年年二月风，翦出鹅黄缕。\n一种可怜生，落日和烟雨。苏小门前长短条，即渐迷行处。'},
    {t:'卜算子·修竹翠罗寒',a:'辛弃疾〔宋代〕',c:'修竹翠罗寒，迟日江山暮。幽径无人独自芳，此恨知无数。\n只共梅花语。懒逐游丝去。著意寻春不肯香，香在无寻处。'},
    {t:'卜算子·雅淡浅深黄',a:'张炎〔宋代〕',c:'雅淡浅深黄，顾影欹秋雨。\n碧带犹皱笋指痕，不解擎芳醑。\n休唱古阳关，如把相思铸。\n却忆铜盘露已干，愁在倾心处。'},
    {t:'卜算子·饮酒败德',a:'辛弃疾〔宋代〕',c:'盗跖傥名丘，孔子还名跖。跖圣丘愚直至今，美恶无真实。\n简册写虚名，蝼蚁侵枯骨。千古光阴一霎时，且进杯中物。'},
    {t:'卜算子·咏梅',a:'陆游〔宋代〕',c:'驿外断桥边，寂寞开无主。已是黄昏独自愁，更着风和雨。\n无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。'},
    {t:'卜算子·自嘲',a:'佚名',c:'本是后山人，偶做前堂客。醉舞经阁半卷书，坐井说天阔。大志戏功名，海斗量福祸。论到囊中羞涩时，怒指乾坤错。'},
    {t:'卜算子慢·江枫渐老',a:'柳永〔宋代〕',c:'江枫渐老，汀蕙半凋，满目败红引翠。楚客登临，正是暮秋天气。引疏砧、断续残阳里。对晚景、伤千念远，新愁旧恨相继。\n脉脉人千里。念两处风情，万重烟水。雨歇天高，望断翠峰十二。侭无言、谁会凭高意。纵写得、离肠万种，奈归云谁寄。'},
    {t:'不见',a:'杜甫〔唐代〕',c:'不见李生久，佯狂真可哀。\n世人皆欲杀，吾意独怜才。\n敏捷诗千首，飘零酒一杯。\n匡山读书处，头白好归来。'},
    {t:'不寐听雨',a:'杨万里〔宋代〕',c:'雨到中霄寂不鸣，只闻风拂树梢轻。\n瓦沟收拾残零水，并作檐间一滴声。'},
    {t:'不寝',a:'杜牧〔唐代〕',c:'到晓不成梦，思量堪白头。\n多无百年命，长有万般愁。\n世路应难尽，营生卒未休。\n莫言名与利，名利是身仇。'},
    {t:'不食姑·一作赠山中女道士',a:'张籍〔唐代〕',c:'几年山里住，已作绿毛身。护气常稀语，存思自见神。\n养龟同不食，留药任生尘。要问西王母，仙中第几人。'},
    {t:'不睡',a:'文天祥〔宋代〕',c:'频搔白首强忧煎，细雨青灯思欲颠。\n南北东西三万里，古今上下几千年。\n只因知事翻成恼，未到放心那得眠。\n眼不识丁马前卒，隔床鼾鼻正陶然。'},
    {t:'不饮赠酒',a:'杜牧〔唐代〕',c:'细算人生事，彭殇共一筹。与愁争底事，要尔作戈矛。'},
    {t:'不遇咏',a:'王维〔唐代〕',c:'北阙献书寝不报，南山种田时不登。\n百人会中身不预，五侯门前心不能。\n身投河朔饮君酒，家在茂陵平安否？\n且共登山复临水，莫问春风动杨柳。\n今人作人多自私，我心不说君应知。\n济人然后拂衣去，肯作徒尔一男儿！'},
    {t:'步出城东门',a:'佚名〔两汉〕',c:'步出城东门，遥望江南路。\n前日风雪中，故人从此去。\n我欲渡河水，河水深无梁。\n愿为双黄鹄，高飞还故乡。'},
    {t:'步虚词',a:'皎然〔唐代〕',c:'予因览真诀，遂感西城君。玉笙魄青冥，人间未曾闻。\n日华炼精魄，皎皎无垢氛。谓我有仙骨，且令饵氤氲。\n俯仰愧灵颜，愿随鸾鹄群。俄然动风驭，缥渺归青云。'},
    {t:'步虚词',a:'刘禹锡〔唐代〕',c:'华表千年一鹤归，\n凝丹为顶雪为衣。\n星星仙语人听尽，\n却向五云翻翅飞。'},
    {t:'步虚辞十首其六',a:'佚名〔隋代〕',c:'大道师玄寂，升仙友无英。公子度灵符，太一奉洞章。\n舍利曜金姿，龙驾欻来迎。天尊盻云舆，飘飘乘虚翔。\n香花若飞雪，纷蔼茂玄梁。头脑礼金阙，携手邀玉京。'},
    {t:'步虚辞十首其三',a:'佚名〔隋代〕',c:'嵯峨玄都上，十方宗皇一。苕苕华宝台，光明焰流日。\n炜烨玉林华，茜粲曜珠实。常念餐元精，炼液固形质。\n金光散紫微，窈窕大乘逸。'},
    {t:'步虚辞十首其十',a:'佚名〔隋代〕',c:'至真无所待，时或辔飞龙。长斋会玄都，鸣玉叩琼钟。\n十华诸仙集，紫烟结成宫。宝盖罗太上，真人把芙蓉。\n散花陈我愿，握节徵魔王。法鼓会群仙，灵唱弥不同。\n无可无不可，思与希微通。'},
    {t:'步虚辞十首其四',a:'佚名〔隋代〕',c:'俯仰存太上，华景秀丹田。左顾提郁仪，右盼携结璘。\n六度冠梵行，道德随日新。宿命积福应，闻经若玉亲。\n天挺超世才，乐诵希微篇。冲虚太和气，吐纳流霞津。\n胎息静百关，寥寥究三便。泥丸洞明景，遂成金华仙。\n魔王教授事，故能朝诸天。皆从斋戒起，累功结宿缘。\n飞行凌太虚，提携高上人。'},
    {t:'步虚辞十首其五',a:'佚名〔隋代〕',c:'控辔适十方，旋憩玄景阿。仰观劫刃台，俯盻紫云罗。\n逍遥太上京，相与坐莲华。积学为真人，恬然荣卫和。\n永享无期寿，万椿奚足多。'},
    {t:'步虚辞十首其一',a:'佚名〔隋代〕',c:'稽首礼太上，烧香归虚无。流明兴我回，法轮亦三周。\n玄愿四大兴，灵庆及王侯。七祖生天堂，煌煌曜景敷。\n啸歌观大漠，天乐适我娱。斋馨无上德，下仙不与俦。\n妙想明玄觉，诜诜乘虚游。'},
    {t:'部落曲',a:'高适〔唐代〕',c:'蕃军傍塞游，代马喷风秋。老将垂金甲，阏支著锦裘。\n雕戈蒙豹尾，红旆插狼头。日暮天山下，鸣笳汉使愁。'},
    {t:'采地黄者',a:'白居易〔唐代〕',c:'麦死春不雨，禾损秋早霜。\n岁晏无口食，田中采地黄。\n采之将何用，持以易糇粮。\n凌晨荷锄去，薄暮不盈筐。\n携来朱门家，卖与白面郎。\n与君啖肥马，可使照地光。\n愿易马残粟，救此苦饥肠。'},
    {t:'采莲令·月华收',a:'柳永〔宋代〕',c:'月华收，云淡霜天曙。西征客、此时情苦。翠娥执手送临歧，轧轧开朱户。千娇面、盈盈伫立，无言有泪，断肠争忍回顾。\n一叶兰舟，便恁急桨凌波去。贪行色、岂知离绪，万般方寸，但饮恨，脉脉同谁语。更回首、重城不见，寒江天外，隐隐两三烟树。'},
    {t:'采莲曲',a:'张籍〔唐代〕',c:'秋江岸边莲子多，采莲女儿并船歌。\n青房圆实齐戢戢，争前竞折漾微波。\n试牵绿茎下寻藕，断处丝多刺伤手。\n白练束腰袖半卷，不插玉钗妆梳浅。\n船中未满度前洲，借问阿谁家住远。\n归时共待暮潮上，自弄芙蓉还荡桨。'},
    {t:'采莲曲',a:'李白〔唐代〕',c:'若耶溪傍采莲女，笑隔荷花共人语。\n日照新妆水底明，风飘香袂空中举。\n岸上谁家游冶郎，三三五五映垂杨。\n紫骝嘶入落花去，见此踟蹰空断肠。'},
    {t:'采莲曲',a:'王昌龄〔唐代〕',c:'荷叶罗裙一色裁，芙蓉向脸两边开。\n乱入池中看不见，闻歌始觉有人来。'},
    {t:'采莲曲',a:'白居易〔唐代〕',c:'菱叶萦波荷飐风，荷花深处小船通。\n逢郎欲语低头笑，碧玉搔头落水中。'},
    {t:'采樵作',a:'孟浩然〔唐代〕',c:'采樵入深山，山深树重叠。\n桥崩卧槎拥，路险垂藤接。\n日落伴将稀，山风拂萝衣。\n长歌负轻策，平野望烟归。'},
    {t:'采樵作①',a:'孟浩然〔唐代〕',c:'采樵人深山，山深树重叠。\n桥崩卧槎拥，路险垂藤接。\n日落伴将稀，山风拂萝衣。\n长歌负轻策，平野望烟归。'},
    {t:'采桑子',a:'纳兰性德〔清代〕',c:'白衣裳凭朱栏立，凉月趖西。点目霜微，岁晏知君归不归。\n残更目断传书雁，尺素还稀。一味相思，准拟相看似旧时。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'红窗碧玉新名旧，犹绾双螺。一寸秋波。千斛明珠觉未多。\n小来竹马同游客，惯听清歌。今日蹉跎。恼乱工夫晕翠蛾。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'白莲池上当时月，今夜重圆。曲水兰船。忆伴飞琼看月眠。\n黄花绿酒分携后，泪湿吟笺。旧事年年。时节南湖又采莲。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'别来长记西楼事，结遍兰襟。遗一重寻。弦断相如绿绮琴。\n何时一枕逍遥夜，细话初心。若问如今。也似当时著意深。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'芦鞭坠遍杨花陌，晚见珍珍。疑是朝云。来作高唐梦里人。\n应怜醉落楼中帽，长带歌尘。试拂香茵。留解金鞍睡过春。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'年年此夕东城见，欢意匆匆。明日还重。却在楼台缥缈中。\n垂螺拂黛清歌女，曾唱相逢。秋月春风。醉枕香衾一岁同。'},
    {t:'采桑子',a:'张炎〔宋代〕',c:'西园冷罥秋千索，雨透花颦。雨过花皴。近觉江南无好春。\n杜郎不恨寻芳晚，梦里行云。陌上行尘。最是多愁老得人。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'前欢几处笙歌地，长负登临。月幌风襟。犹忆西楼著意深。\n莺花见尽当时事，应笑如今。一寸愁心。日日寒蝉夜夜砧。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'秋来更觉消魂苦，小字还稀。坐把行思。怎得相看似旧时。\n南楼把手凭肩处，风月应知。别后除非。梦里时时得见伊。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'无端恼破桃源梦，明日青楼。玉腻花柔。不学行云易去留。\n应嫌衫袖前香冷，重傍金虬。歌扇风流。遮尽归时翠黛愁。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'心期昨夜寻思遍，犹负殷勤。齐斗堆金。难买丹诚一寸真。\n须知枕上尊前意，占得长春。寄语东邻。似此相看有几人。'},
    {t:'采桑子',a:'晏几道〔宋代〕',c:'宜春苑外楼堪倚，雪意方浓。雁影冥濛。正共银屏小景同。\n可无人解相思处，昨夜东风。梅蕊应红。知在谁家锦字中。'},
    {t:'采桑子·白衣裳凭朱阑立',a:'纳兰性德〔清代〕',c:'白衣裳凭朱阑立，凉月趖西。点目霜微，岁晏知君归不归？\n残更目断传书雁，尺素还稀。一味相思，准拟相看似旧时。'},
    {t:'采桑子·宝钗楼上妆梳晚',a:'陆游〔宋代〕',c:'宝钗楼上妆梳晚，懒上秋千。闲不沉烟。金缕衣宽睡髻偏。\n鳞鸿不寄辽东信，又是经年。弹泪花前。愁入春风十四弦。'},
    {t:'采桑子·别来长忆西楼事',a:'晏几道〔宋代〕',c:'别来长忆西楼事\n结遍兰襟\n遗一重寻\n弦断相如绿绮琴\n何时一枕逍遥夜\n细话初心\n若问如今\n也似当时著意深'},
    {t:'采桑子·拨灯书尽红笺也',a:'纳兰性德〔清代〕',c:'拨灯书尽红笺也，依旧无聊。玉漏迢迢，梦里寒花隔玉箫。\n几竿修竹三更雨，叶叶萧萧。分付秋潮，莫误双鱼到谢桥。'},
    {t:'采桑子·春风不负东君',a:'晏殊〔宋代〕',c:'春风不负东君信，遍拆群芳。燕子双双，依旧衔泥入杏梁。\n须知一盏花前酒。占得韶光。莫话匆忙，梦里浮生足断肠。'},
    {t:'采桑子·春风不负年年信',a:'晏几道〔宋代〕',c:'春风不负年年信，\n长趁花期。\n小锦堂西，\n红杏初开第一枝。\n碧箫度曲留人醉，\n昨夜归迟。\n短恨凭谁，\n莺语殷勤月落时。'},
    {t:'采桑子·而今才道当时错',a:'纳兰性德〔清代〕',c:'而今才道当时错，心绪凄迷。红此偷垂，满眼春风百事非。\n情知此后来无计，强说欢期。一别如斯，落尽梨花月又西。'},
    {t:'采桑子·非花非雾前时见',a:'晏几道〔宋代〕',c:'非花非雾前时见，\n满眼娇春。\n浅笑微颦，\n恨隔垂帘看未真。\n殷勤借问家何处，\n不在红尘。\n若是朝云，\n宜作今宵梦里人。'},
    {t:'采桑子·高吟烂醉淮西月',a:'晏几道〔宋代〕',c:'高吟烂醉淮西月，\n诗酒相留。\n明日归舟，\n碧藕花中醉过秋。\n文姬赠别双团扇，\n自写银钩。\n散尽离愁，\n携得清风出画楼。'},
    {t:'采桑子·海天谁放冰轮满',a:'纳兰性德〔清代〕',c:'海天谁放冰轮满，惆怅离情。莫说离情，但值凉宵总泪零。\n只应碧落重相见，那是今生。可奈今生，刚作愁时又忆卿。'},
    {t:'采桑子·红英一树春来早',a:'晏殊〔宋代〕',c:'红英一树春来早，独占芳时。我一心期。把酒攀条惜绛蕤。\n无端一夜狂风雨，暗落繁枝。蝶怨莺悲。满眼春愁说向谁。'},
    {t:'采桑子·花前独占春风早',a:'晏几道〔宋代〕',c:'花前独占春风早，\n长爱江梅。\n秀艳清杯，\n芳意先愁凤管催。\n寻香已落闲人后，\n此恨难裁。\n更晚须来，\n却恐初开胜未开。'},
    {t:'采桑子·花时恼得琼枝瘦',a:'晏几道〔宋代〕',c:'花时恼得琼枝瘦，\n半被残香。\n睡笑梅妆，\n红泪今春第一行。\n风流笑伴相逢处，\n白马游缰。\n共折垂杨，\n手捻芳条说夜长。'},
    {t:'采桑子·金风玉露初凉夜',a:'晏几道〔宋代〕',c:'金风玉露初凉夜，秋草窗前。浅醉闲眠。一枕江风梦不圆。\n长情短恨难凭寄，枉费红笺。试拂么弦。却恐琴心可暗传。'},
    {t:'采桑子·九日',a:'纳兰性德〔清代〕',c:'深秋绝塞谁相忆，木叶萧萧。乡倍迢迢。六曲屏山和梦遥。佳时倍惜风光别，不为登高。只觉魂销。南雁归时更寂寥。'},
    {t:'采桑子·居庸关',a:'纳兰性德〔清代〕',c:'巂周声里严关峙，匹马登登，乱踏黄尘。听报邮签第几程。\n行人莫话前朝事，风雨诸陵，寂寞鱼灯。天寿山头冷月横。'},
    {t:'采桑子·冷香萦遍红桥梦',a:'纳兰性德〔清代〕',c:'冷香萦遍红桥梦，梦觉城笳。月上桃花，雨歇春寒燕子家。\n箜篌别后谁能鼓，肠断天涯。暗损韶华，一缕茶烟透碧纱。'},
    {t:'采桑子·凉生露气湘弦润',a:'纳兰性德〔清代〕',c:'凉生露气湘弦润，暗滴花梢。帘镜谁摇，燕蹴风丝上柳条。\n舞鹍镜匣开频掩，檀粉慵调。朝泪如潮，昨夜香衾觉梦遥。'},
    {t:'采桑子·林间摘遍双双叶',a:'晏殊〔宋代〕',c:'林间摘遍双双叶，寄与相思。朱欲开时，尚有山榴一两枝。\n荷花欲绽金莲子，半落红衣。晚雨微微，待得空梁宿燕归。'},
    {t:'采桑子·明月多情应笑我',a:'纳兰性德〔清代〕',c:'明月多情应笑我，笑我如今。辜负春心，独自闲行独自吟。\n近来怕说当时事，结遍兰襟。月浅灯深，梦里云归何处寻。'},
    {t:'采桑子·那能寂寞芳菲节',a:'纳兰性德〔清代〕',c:'那能寂寞芳菲节，欲话生平。夜已三更。一阕悲歌泪暗零。\n须知秋叶春花促，点鬓星星。遇酒须倾，莫问千秋万岁名。'},
    {t:'采桑子·年年索尽梅花笑',a:'辛弃疾〔宋代〕',c:'年年索尽梅花笑，疏冷黄昏。疏冷黄昏。香满东风月一痕。\n清诗冷落无人寄，雪艳冰魂。雪艳冰魂。浮玉溪头烟树村。'},
    {t:'采桑子·秋千散后朦胧月',a:'晏几道〔宋代〕',c:'秋千散后朦胧月，满院人闲。几殿雕阑，一夜风吹杏粉残。\n昭阳殿里春衣就，金缕初干。莫信朝寒，明日花前试舞看。'},
    {t:'采桑子·日高庭院杨花转',a:'晏几道〔宋代〕',c:'日高庭院杨花转，\n闲淡春风。\n昨夜匆匆，\n颦入遥山翠黛中。\n金盆水冷菱花净，\n满面残红。\n欲洗犹慵，\n弦上啼乌此夜同。'},
    {t:'采桑子·塞上咏雪花',a:'纳兰性德〔清代〕',c:'非关癖爱轻模样，冷处偏佳。别有根芽，不是人间富贵花。\n谢娘别后谁能惜，飘泊天涯。寒月悲笳，万里西风瀚海沙。'},
    {t:'采桑子·谁翻乐府凄凉曲',a:'纳兰性德〔清代〕',c:'谁翻乐府凄凉曲？风也萧萧，雨也萧萧，瘦尽灯花又一宵。\n不知何事萦怀抱，醒也无聊，醉也无聊，梦也何曾到谢桥。'},
    {t:'采桑子·谁将一点凄凉意',a:'晏几道〔宋代〕',c:'谁将一点凄凉意，\n送入低眉。\n画箔闲垂，\n多是今宵得睡迟。\n夜痕记尽窗间月，\n曾误心期。\n准拟相思，\n还是窗间记月时。'},
    {t:'采桑子·石竹',a:'晏殊〔宋代〕',c:'古罗衣上金针样，绣出芳妍。玉画朱阑，紫艳红英照日鲜。\n佳人画阁新妆了，对立丛边。试摘婵娟，贴向眉心学翠钿。'},
    {t:'采桑子·时光只解催人老',a:'晏殊〔宋代〕',c:'时光只解催人老，不信多情，长昨离亭，泪滴春衫酒易醒。\n梧桐昨夜西风急，淡月胧明，好梦频惊，何处高楼雁一声？'},
    {t:'采桑子·双螺未学同心绾',a:'晏几道〔宋代〕',c:'双螺未学同心绾，\n已占歌名。\n月敲风清，\n长倚昭华笛里声。\n知音敲尽朱颜改，\n寂寞时情。\n一曲离亭，\n借与青楼忍泪听。'},
    {t:'采桑子·桃花羞作无情死',a:'纳兰性德〔清代〕',c:'桃花羞作无情死，感激东风。吹落娇红，飞入闲窗伴懊侬。\n谁怜辛苦东阳瘦，也为春慵。不及芙蓉，一片幽情冷处浓。'},
    {t:'采桑子·彤霞久绝飞琼字',a:'纳兰性德〔清代〕',c:'彤霞久绝飞琼字，人被谁边？人被谁边，今夜玉清眠不眠。\n香销被冷残灯灭，静数秋天，静数秋天，又误心期到下弦。'},
    {t:'采桑子·土花曾染湘娥黛',a:'纳兰性德〔清代〕',c:'土花曾染湘娥黛，铅泪难消。清韵谁敲，不是犀椎是凤翘。\n只应长伴端溪紫，割取秋潮。鹦鹉偷教，方响前头见玉萧。'},
    {t:'采桑子·西楼月下当时见',a:'晏几道〔宋代〕',c:'西楼月下当时见，泪粉偷匀。歌罢还颦。恨隔炉烟看未真。\n别来楼外垂杨缕，几换青春。倦客红尘。长记楼中粉泪人。'},
    {t:'采桑子·湘妃浦口莲开尽',a:'晏几道〔宋代〕',c:'湘妃浦口莲开尽，\n昨夜红稀。\n懒过前溪，\n闲舣扁舟看雁飞。\n去年谢女池边醉，\n晚雨霏微。\n记得归时，\n旋折新荷盖舞衣。'},
    {t:'采桑子·谢家庭院残更立',a:'纳兰性德〔清代〕',c:'谢家庭院残更立，燕宿雕梁。月已银墙，不辨花丛那辨香。\n此情已自成追忆，零落鸳鸯。雨歇微凉，十一年前梦一场。'},
    {t:'采桑子·严霜拥絮频惊起',a:'纳兰性德〔清代〕',c:'严霜拥絮频惊起，扑面霜空。斜汉朦胧。冷逼毡帷火不红。\n香篝翠被浑闲事，回首西风。何处疏钟，一穗灯花似梦中。'},
    {t:'采桑子·阳和二月芳菲遍',a:'晏殊〔宋代〕',c:'阳和二月芳菲遍，暖景溶溶。戏蝶游蜂，深入千花粉艳中。\n何人解系天边日，占取春风。免使繁红，一片西飞一片东。'},
    {t:'采桑子·樱桃谢了梨花发',a:'晏殊〔宋代〕',c:'樱桃谢了梨花发，红白相催。燕乐归来。几处风帘绣户开。\n人生乐事知多少，且酌金杯。管咽弦哀。慢引萧娘舞袖回。'},
    {t:'采桑子·昭华凤管知名久',a:'晏几道〔宋代〕',c:'昭华凤管知名久，\n长闭帘栊。\n闻金春慵，\n方倚庭花晕脸红。\n可怜金谷无人后，\n此会相逢。\n三弄临风，\n送得当筵玉盏空。'},
    {t:'采桑子·征人去日殷勤嘱',a:'晏几道〔宋代〕',c:'征人去日殷勤嘱，莫负心期。寒雁来时。第一传书慰别离。\n轻春织就机中素，泪墨题诗。欲寄相思。日日高楼看雁飞。'},
    {t:'采石',a:'文天祥〔宋代〕',c:'不上峨眉二十岁，重来为堕山有泪。\n今人不见虞允文，古人曾有樊若水。\n长江阔处平如驿，况此介然衣带窄。\n欲从谪仙捉月去，安得然犀照神物。'},
    {t:'采实心竹杖寄赠李萼侍御',a:'皎然〔唐代〕',c:'竹杖裁碧鲜，步林赏高直。实心去内矫，全节无外饰。\n行药聊自持，扶危资尔力。初生在榛莽，孤秀岂封殖。\n干雪不死枝，赠君期君识。'},
    {t:'采薇(节选)',a:'佚名〔先秦〕',c:'采忧采忧，忧亦作止。曰归曰归，不亦莫止。靡室靡家，猃狁之故。不遑启居，猃狁之故。\n采忧采忧，忧亦柔止。曰归曰归，心亦忧止。忧心烈烈，载饥载渴。我戍未定，靡使归聘。\n采忧采忧，忧亦刚止。曰归曰归，不亦阳止。王事靡盬，不遑启处。忧心孔疚，我行不来！'},
    {t:'采玉行',a:'韦应物〔唐代〕',c:'官府征白丁，言采蓝谿玉。绝岭夜无家，深榛雨中宿。\n独妇饷粮还，哀哀舍南哭。'},
    {t:'采珠行',a:'元稹〔唐代〕',c:'海波无底珠沉海，采珠之人判死采。万人判死一得珠，\n斛量买婢人何在。年年采珠珠避人。今年采珠由海神。\n海神采珠珠尽死，死尽明珠空海水。珠为海物海属神，\n神今自采何况人。'},
    {t:'彩树歌',a:'陈子昂〔唐代〕',c:'嘉锦筵之珍树兮，错众彩之氛氲。状瑶台之微月，\n点巫山之朝云。青春兮不可逢，况蕙色之增芬。\n结芳意而谁赏，怨绝世之无闻。红荣碧艳坐看歇，\n素华流年不待君。故吾思昆仑之琪树，厌桃李之缤纷。'},
    {t:'彩云归·蘅皋向晚舣轻航',a:'柳永〔宋代〕',c:'蘅皋向晚舣轻航。卸云帆、水驿鱼乡。当暮天、霁色如晴昼，江练静、皎月飞光。那堪听、远村羌管，引离人断肠。此际浪萍风梗，度岁茫茫。\n堪伤。朝欢暮散，被多情、赋与凄凉。别来最苦，襟袖依约，尚有余香。算得伊、鸳衾凤枕，夜永争不思量。牵情处，惟有临歧，一句难忘。'},
    {t:'蔡中郎坟',a:'温庭筠〔唐代〕',c:'古坟零落野花春，闻说中郎有后身。\n今日爱才非昔日，莫抛心力作词人。'},
    {t:'残春独来南亭因寄张祜',a:'杜牧〔唐代〕',c:'暖云如粉草如茵，独步长堤不水人。\n一岭桃花红锦黦，半溪山水碧罗新。\n高枝百舌犹欺鸟，带叶梨花独送春。\n仲蔚欲知何处在，苦吟林下拂诗尘。'},
    {t:'残花',a:'佚名',c:'花开花落花无悔，缘来缘去缘花水。\n花谢为花开，花飞为花悲。\n花悲为花泪，花泪为花碎。\n花舞花落泪，花哭花瓣飞。\n花开为谁谢，花谢为谁悲。'},
    {t:'残花',a:'李商隐〔唐代〕',c:'残花啼露莫留春，尖发谁非怨别人。\n若但掩关劳独梦，宝钗何日不生尘。'},
    {t:'残菊',a:'王安石〔宋代〕',c:'黄昏风雨打园林，残菊飘零满地金。\n擸得一枝犹好在，可怜公子惜花心。'},
    {t:'残腊',a:'朱熹〔宋代〕',c:'残腊生春序，愁霖逼岁昏。小红敷艳萼，众绿被陈根。\n阴壑泉方注，原田水欲浑。农家向东作，百事集柴门。'},
    {t:'残丝曲',a:'李贺〔唐代〕',c:'垂杨叶老莺哺儿，残丝欲断黄中归。\n绿鬓年少金钗客，缥粉壶中沉琥珀。\n花台欲暮春辞去，落花起作回风舞。\n榆荚相催不知数，沈郎青钱夹城路。'},
    {t:'蚕谷行',a:'杜甫〔唐代〕',c:'天下郡国向万城，无有一城无甲兵！\n焉得铸甲作农器，一寸荒田牛得耕？\n牛尽耕，蚕亦成。\n不劳烈士泪滂沱，男谷女丝行复歌。'},
    {t:'苍然亭',a:'文天祥〔宋代〕',c:'风打船头击夕阳，亭前老子旧胡床。\n青牛过去关山动，白鹤归来城郭荒。\n忠节风流落尘土，英雄遗恨满沧浪。\n故园水月应无恙，江上新松几许长。'},
    {t:'苍溪县寄扬州兄弟',a:'元稹〔唐代〕',c:'苍溪县下嘉陵水，入峡穿江到海流。\n凭仗鲤鱼将远信，雁回时节到扬州。'},
    {t:'沧浪歌',a:'佚名〔先秦〕',c:'沧浪之水清兮，可以濯吾缨；\n沧浪之水浊兮，可以濯吾足。'},
    {t:'侧犯·大石',a:'周邦彦〔宋代〕',c:'暮霞霁雨，小莲出水红妆靓。风暗。看步袜江妃照明镜。飞萤度暗草，秉烛游花径。人静。携艳质、泉凉就槐影。\n金环皓腕，雪藕清泉莹。谁念省。满身香、犹是旧荀令。见说胡姬，酒垆寂静。烟锁漠漠，藻池苔井。'},
    {t:'插田歌（节选）',a:'刘禹锡〔唐代〕',c:'冈头花草齐，燕子东西飞。\n田塍望如线，白水光参差。\n农妇白纻裙，农夫绿蓑衣。\n齐唱田中歌，嘤伫如竹枝。'},
    {t:'插秧歌',a:'杨万里〔宋代〕',c:'田夫抛秧田妇接，小儿拔秧大儿插。\n笠是兜鍪蓑是甲，雨从头上湿到胛。\n唤渠朝餐歇半霎，低头折腰只不答。\n秧根未牢莳未匝，照管鹅儿与雏鸭。'},
    {t:'茶',a:'秦观〔宋代〕',c:'茶实嘉木英，其香乃天育。\n芳不愧杜蘅，清堪掩椒菊。\n上客集堂葵，圆月探奁盝。\n玉鼎注漫流，金碾响丈竹。\n侵寻发美鬯，猗狔生乳粟。\n经时不销歇，衣袂带纷郁。\n幸蒙巾笥藏，苦厌龙兰续。\n愿君斥异类，使我全芬馥。'},
    {t:'茶瓶儿·杨花糁径樱桃落',a:'纳兰性德〔清代〕',c:'杨花糁径樱桃落。绿阴下、晴波态掠，好景成担阁。秋千背倚，风态宛如昨。\n可惜春来总萧索。人瘦损、纸鸢风恶。多少芳笺约，青鸾去也，谁与劝孤酌？'},
    {t:'茶山下作',a:'杜牧〔唐代〕',c:'春风最窈窕，日晓柳村西。娇云光占岫，健水鸣分溪。\n燎岩野花远，戛瑟幽鸟啼。把酒坐芳草，亦有佳人携。'},
    {t:'钗头凤·别武昌',a:'秦观〔宋代〕',c:'临丹壑。凭高阁。闲吹玉笛招黄鹤。空江暮。重回顾。一洲烟草，满川云树。住住住。\n江风作。波涛恶。汀兰寂寞岸花落。长亭路。尘如雾。青山虽好，朱颜难驻。去去去。'},
    {t:'钗头凤·红酥手',a:'陆游〔宋代〕',c:'红酥手，黄縢酒，满城春色宫墙柳。东风恶，欢情薄。一怀愁绪，几年离索。错、错、错。\n春如旧，人空瘦，泪痕红浥鲛绡透。桃花落，闲池阁。山盟虽在，锦书难托。莫、莫、莫！'},
    {t:'婵娟篇',a:'孟郊〔唐代〕',c:'花婵娟，泛春泉。竹婵娟，笼晓烟。妓婵娟，不长妍。\n月婵娟，真可怜。夜半姮娥朝太一，人间本自无灵匹。\n汉宫承宠不多时，飞燕婕妤相妒嫉。'},
    {t:'禅关',a:'文天祥〔宋代〕',c:'秋风吹日上禅关，路入松花第一弯。\n只愿四时烟雾少，满城楼阁见青山。'},
    {t:'禅诗',a:'皎然〔唐代〕',c:'万法出无门，纷纷使智昏。\n徒称谁氏子，独立天地元。\n实际且何有，物先安可存。\n须知不动念，照出万重源。'},
    {t:'禅思',a:'皎然〔唐代〕',c:'真我性无主，谁为尘识昏。奈何求其本，若拔大木根。\n妄以一念动，势如千波翻。伤哉子桑扈，虫臂徒虚言。\n神威兴外论，宗邪生异源。空何妨色在，妙岂废身存。\n寂灭本非寂，喧哗曾未喧。嗟嗟世上禅，不共智者论。'},
    {t:'禅堂',a:'柳宗元〔唐代〕',c:'发地结菁茆，团团抱虚白。\n山花取幽户，中有忘机客。\n涉有本非取，照空不待析。\n万籁俱缘生，窅然喧中寂。\n心境本同如，鸟飞无遗迹。'},
    {t:'蝉',a:'李商隐〔唐代〕',c:'本以高难饱，徒劳恨费声。\n五更疏欲断，一树碧无情。\n薄宦梗犹泛，故园芜已平。\n烦君最相警，我亦举家清。'},
    {t:'浐水东店送唐子归嵩阳',a:'岑参〔唐代〕',c:'野店临官路，重城压御堤。山开灞水北，雨过杜陵西。\n归梦秋能作，乡书醉懒题。桥回忽不见，征马尚闻嘶。'},
    {t:'昌谷北园新笋四首',a:'李贺〔唐代〕',c:'箨落长竿削玉开，君看母笋是园材。\n更容一夜抽千尺，别却池园数寸泥。\n斫取青光写楚辞，腻见春粉黑离离。\n无情有恨何人见，露压烟啼千万枝。\n家泉石眼两三茎，晓看阴根紫脉生。\n今年水曲春沙上，笛管新篁拔玉青。\n古竹老梢惹碧云，茂陵归卧叹清贫。\n风吹千亩迎雨啸，鸟重一枝入酒尊。'},
    {t:'昌谷读书示巴童',a:'李贺〔唐代〕',c:'虫响灯光薄，宵寒药气浓。\n君怜垂翅客，辛苦尚相从。'},
    {t:'阊门怀古',a:'韦应物〔唐代〕',c:'独鸟下高树，遥知吴苑园。凄凉千古事，日暮倚阊门。'},
    {t:'阊门外登溪船五首·其一',a:'杨万里〔宋代〕',c:'步下新船试水初，打头揽载适逢予。\n一椽板屋才经雨，两面油窗好读书。\n剩买春风木芍药，乱篸棐几竹籧篨。\n清溪浮取松亭子，赏遍千山不要驴。'},
    {t:'尝茶',a:'刘禹锡〔唐代〕',c:'生拍芳丛鹰觜芽，老郎封寄谪仙家。\n今宵更有湘江月，照出菲菲满碗花。'},
    {t:'常州',a:'文天祥〔宋代〕',c:'山河千里在，烟火一家无。\n壮甚睢阳守，冤哉马邑屠。\n苍天如可问，赤子果何辜。\n唇齿提封旧，抚膺三叹吁。'},
    {t:'嫦娥',a:'李商隐〔唐代〕',c:'云母屏风烛影深，长河渐落晓星沉。\n嫦娥应悔偷灵药，碧海青天夜夜心。'},
    {t:'倡女词',a:'张籍〔唐代〕',c:'轻鬓丛梳阔扫眉，为嫌风日下楼稀。\n画罗金缕难相称，故著寻常淡薄衣。'},
    {t:'朝饥示子聿',a:'陆游〔宋代〕',c:'水云深处小茅茨，雷动空肠惯忍饥。\n外物不移方是学，俗人犹爱未为诗。\n生逢昭代虽虚过，死见先亲幸有辞。\n八十到头终强项，欲将衣钵付吾儿。'},
    {t:'朝来曲',a:'王昌龄〔唐代〕',c:'月昃鸣珂动，花连绣户春。\n盘龙玉台镜，唯待画眉人。'},
    {t:'朝日敕赐百官樱桃',a:'张籍〔唐代〕',c:'仙果人间都未有，今朝忽见下臣门。捧盘小吏初宣敕，\n当殿群臣共拜恩。日色遥分门下坐，露香才出禁中园。\n每年重此先偏待，愿得千春奉至尊。'},
    {t:'朝三暮四',a:'佚名〔先秦〕',c:'宋有狙公者，爱狙，养之成群，能解狙之意；狙亦得公之心。损其家口，充狙之欲。俄而匮焉，将限其食，恐众狙之不驯于己也。先诳之曰：“与若芧，朝三而暮四，足乎？”众狙皆起而怒。俄而曰：“与若芧，朝四而暮三，足乎？”众狙皆伏而喜。'},
    {t:'朝天子·庐山',a:'佚名〔元代〕',c:'早霞，晚霞，妆点庐山画。仙翁何处炼丹砂，一缕白云下。\n客去斋余，人来茶罢。叹浮生，数落花。楚家，汉家，做了渔樵话。'},
    {t:'朝中措·代谭德称作',a:'陆游〔宋代〕',c:'怕歌愁舞懒逢迎。妆晚托春酲。总是向人深处，当时枉道无情。\n关心近日，啼红密诉，剪绿深盟。杏馆花阴恨浅，画堂银烛嫌明。'},
    {t:'朝中措·梅',a:'陆游〔宋代〕',c:'幽姿不入少年场。无语只凄凉。一个飘零身世，十分冷淡心肠。\n江头月底，新诗旧梦，孤恨清香。任是春风不管，也曾先识东皇。'},
    {t:'朝中措·清明时节',a:'张炎〔宋代〕',c:'清明时节雨声哗。潮拥渡头沙。燕被梨花冷看，人生苦恋天涯。\n燕帘莺户，云窗雾阁，酒醒啼鸦。折得一枝杨柳，归来插向谁家。'},
    {t:'朝中措·蜀弦秦柱不关情',a:'纳兰性德〔清代〕',c:'蜀弦秦柱不关情，尽日掩云屏。已惜轻翎退粉，更嫌弱絮为萍。\n东风多事，余寒吹散，烘暖微酲。看尽一帘红雨，为谁亲系花铃。'},
    {t:'朝中措·夜深残月过山房',a:'辛弃疾〔宋代〕',c:'夜深残月过山房。睡觉北窗凉。起绕中庭独步，一天星斗文章。\n朝来客话，山林钟鼎，那处难忘。君向沙头细问，白鸥知我行藏。'},
    {t:'嘲报春花',a:'杨万里〔宋代〕',c:'嫩黄老碧已多时，騃紫痴红略万枝。\n始有报春三两朵，春深犹自不曾知。'},
    {t:'嘲春风',a:'温庭筠〔唐代〕',c:'春风何处好？别殿饶芳草。\n苒嫋转鸾旗，萎蕤吹雉葆。\n扬芳历九门，澹荡入兰荪。\n争奈白团扇，时时偷主恩。'},
    {t:'嘲鲁儒',a:'李白〔唐代〕',c:'鲁叟谈五经，白发死章句。\n问以经济策，茫如坠烟雾。\n足著远游履，首戴方山巾。\n缓步从直道，未行先起尘。\n秦家丞相府，不重褒衣人。\n君非叔孙通，与我本殊伦。\n时事且未达，归耕汶水滨。'},
    {t:'嘲三月十八日雪',a:'温庭筠〔唐代〕',c:'三月雪连夜，未应伤物华。\n只缘春欲尽，留著伴梨花。'},
    {t:'嘲少年',a:'李贺〔唐代〕',c:'青骢马肥金鞍光，龙脑入缕罗衫香。\n美人狭坐飞琼觞，贫人唤云天上郎。\n别起高楼临碧筱，丝曳红鳞出深沼。\n有时半醉百花前，背把金丸落飞鸟。\n自说生来未为客，一身美妾过三百。\n岂知劚地种苗家，官税频催勿人织。\n长金积玉夸豪毅，每揖闲人多意气。\n生来不读半行书，只把黄金买身贵。\n少年安得长少年，海波尚变为桑田。\n荣枯递传急如箭，天公不肯于公偏。\n莫道韶华镇长在，发白面皱专相待。'},
    {t:'嘲桃',a:'李商隐〔唐代〕',c:'无赖夭桃面，平明露井东。\n春风为开了，却拟笑春风。'},
    {t:'嘲王历阳不肯饮酒',a:'李白〔唐代〕',c:'地白风色寒，雪花大如手。\n笑杀陶渊明，不饮杯中酒。\n浪抚一张琴，虚栽五株柳。\n空负头上巾，吾于尔何有。'},
    {t:'嘲雪',a:'李贺〔唐代〕',c:'昨日发葱岭，今朝下兰渚。\n喜从千里来，乱笑含春语。\n龙沙湿汉旗，凤扇迎秦素。\n久别辽城鹤，毛衣已应故。'},
    {t:'嘲稚子',a:'杨万里〔宋代〕',c:'雨里船中不自由，无愁稚子亦成愁。\n看渠坐睡何曾醒，及至教眠却掉头。'},
    {t:'郴口又赠二首',a:'韩愈〔唐代〕',c:'山作剑攒江写镜，扁舟斗转疾归飞。\n回头笑向张公子，终日思归此日归。\n雪飐霜翻看不分，雷惊电激语难闻。\n沿涯宛转到深处，何限青天无片云。'},
    {t:'郴州祈雨',a:'韩愈〔唐代〕',c:'乞雨女郎魂，炰羞洁且繁。庙开鼯鼠叫，神降越巫言。\n旱气期销荡，阴官想骏奔。行看五马入，萧飒已随轩。'},
    {t:'尘外',a:'文天祥〔宋代〕',c:'半山风雨截江城，未脱人间总是尘。\n中夜起看衣上月，青天如水露华新。'},
    {t:'陈后宫',a:'李商隐〔唐代〕',c:'茂苑城如画，阊门瓦欲流。\n还依水光殿，更起月华楼。\n侵夜鸾开镜，迎冬雉献裘。\n从臣皆半醉，天子正无愁。'},
    {t:'陈令举妙奴诗',a:'秦观〔宋代〕',c:'西湖水滑多娇嫱，妙奴十二正发芳。\n肌肤皙白发脚长，含语未发先有香。\n溪上夜燕侍簪裳，皎肠华月堕沧浪。\n音声入云能断肠，不许北客辞酒浆。\n主人蔼蔼邦之良，少年射策谒未央。\n俊词伟气森开张，玉杓贯斗生怒芒。\n天欲文采老更昌，故使敛翮窥群翔。\n五十仅补尚书郎，浩歌骑牛倚倡佯。\n东风戏雨花草狂，二溪泱泱青黛光。\n妙奴勿倦侑羽觞，主人正欲游醉乡。'},
    {t:'陈留市隐',a:'黄庭坚〔宋代〕',c:'陈留江端礼季共曰：“陈留市上姓刀镊工，年四十馀，无世家子姓；惟一女年七岁矣，日以刀镊长得钱与女子醉饱，则簪花吹长笛，肩女而归，无一朝之忧，而姓终身之乐，疑以为姓道者也。”陈无己为赋诗，庭坚亦拟作。\n市井怀珠玉，往来人未逢。\n乘肩娇小女，邂逅此生同。\n养性霜刀在，阅人清镜空。\n时时能举酒，弹镊送归鸿。'},
    {t:'陈少卿第一百二十六',a:'文天祥〔宋代〕',c:'卿月升金掌，老气横九州。\n前辈复谁纪，吾道长悠悠。'},
    {t:'陈氏童子草书歌',a:'皎然〔唐代〕',c:'书家孺子有奇名，天然大草令今惊。僧虔老时把笔法，\n孺子如今皆暗合。飙挥电洒眼不及，但能毫端鸣飒飒。\n有时作点险且能，太行片石看欲崩。偶然长掣浓入燥，\n少室枯松欹不倒。夏室炎炎少今欢，山轩日色在阑干。\n桐花飞尽子规思，主今高歌兴不至。浊醪不饮嫌昏沈，\n欲玩草书开我襟。龙爪状奇鼠须锐，水笺白皙越今惠。\n王家小令草最狂，为予洒出惊腾势。'},
    {t:'陈质殿丞挽歌词',a:'范仲淹〔宋代〕',c:'贤者逝如斯，皇天岂易知。\n众人皆堕泪，君子欲安碑。\n几世传清白，满乡称孝慈。\n贤哉生令嗣，遗秀在兰芝。'},
    {t:'晨出郡舍林下',a:'张九龄〔唐代〕',c:'晨兴步北林，萧散一开襟。\n复见林上月，娟娟犹未沉。\n片云自孤远，丛筱亦清深。\n无事由来贵，方知物外心。'},
    {t:'晨炊横塘桥酒家小窗',a:'杨万里〔宋代〕',c:'饥望炊烟眼欲穿，可人最是一青帘。\n双渠走水穿三店，独树欹流荫两檐。\n窗扇透明仍挂上，炉香未烬更多添。\n山村秪苦无良酝，嫌杀芳醪似蜜甜。'},
    {t:'晨登乐游原望终南积雪',a:'皎然〔唐代〕',c:'凌晨拥弊裘，径上古原头。\n雪霁翠疑近，天高思若浮。\n琼峰埋积翠，玉嶂掩飞流。\n曜彩含朝日，摇光夺寸眸。\n寒空标瑞色，爽气袭皇州。\n清眺何人得，终当独再游。'},
    {t:'晨诣超师院读禅经',a:'柳宗元〔唐代〕',c:'汲井漱寒齿，清心拂尘服。\n闲持贝叶书，步出东斋读。\n真源了无取，妄迹世所逐。\n遗言冀可冥，缮性何由熟。\n道人庭宇静，苔色连深竹。\n日出雾露馀，青松如膏沐。\n澹然离言说，悟悦心自足。'},
    {t:'晨雨',a:'杜甫〔唐代〕',c:'小雨晨光闪，初来叶上闻。\n雾交才洒地，风逆旋随云。\n暂起柴荆色，轻沾鸟兽群。\n麝香山一半，亭午未全分。'},
    {t:'晨坐斋中偶而成咏',a:'张九龄〔唐代〕',c:'寒露洁秋空，遥山纷在瞩。\n孤顶偏修耸，微云复相续。\n人兹赏地偏，鸟亦爱林旭。\n结念凭幽远，抚躬曷羁束。\n仰霄谢逸翰，临路嗟疲足。\n徂岁方暌携，归心亟踯躅。\n休闲倘有素，岂负南山曲。'},
    {t:'成帝时歌谣',a:'佚名〔两汉〕',c:'邪径败良田，谗口乱善人。\n桂树华不实，黄爵巢其颠。\n故为人所羡，今为人所怜。'},
    {t:'成帝时童谣',a:'佚名〔魏晋〕',c:'燕燕尾涎涎，张公子，时相见。\n木门仓琅根，燕飞来，啄皇孙。\n皇孙死，燕啄矢。'},
    {t:'成都大阅',a:'陆游〔宋代〕',c:'千步球场爽气新，西山遥见碧嶙峋。\n令传雪岭蓬婆外，声震秦川渭水滨。\n旗脚倚风时弄影，马蹄经雨不沾尘。\n属櫜缚裤毋多恨，久矣儒冠误此身。'},
    {t:'成都府',a:'杜甫〔唐代〕',c:'翳翳桑榆日，照我征衣裳。\n我行山川异，忽在天一方。\n但逢新人民，未卜见故乡。\n大江东流去，游子日月长。\n曾城填华屋，季冬树木苍。\n喧然名都会，吹箫间笙簧。\n信美无与适，侧身望川梁。\n鸟雀夜各归，中原杳茫茫。\n初月出不高，众星尚争光。\n自古有羁旅，我何苦哀伤。'},
    {t:'成都曲',a:'张籍〔唐代〕',c:'锦江近西烟水绿，新雨山头荔枝熟。\n万里桥边多酒家，游人爱向谁家宿。'},
    {t:'成都书事',a:'陆游〔宋代〕',c:'大城少城柳已青，东台西台雪闻晴。\n莺花又作新年梦，丝竹常闻静夜声。\n废苑烟芜迎马动，清江春涨拍堤平。\n尊中酒满身强健，未恨飘零过此生。'},
    {t:'成都行',a:'陆游〔宋代〕',c:'倚锦瑟，击玉壶，吴中狂士游成天。\n成天海棠十万株，繁华盛丽天下无。\n青丝金络白雪驹，日斜绿遣迎名姝。\n燕脂褪尽见玉肤，绿鬟半脱娇不梳。\n吴绫便面对客书，斜行小草密复疏。\n墨君秀润瘦不枯，风枝雨叶笔笔殊。\n月浸罗袜清夜徂，满身花影醉索扶。\n东来此欢堕空虚，坐悲新霜点鬓须。\n易求合浦千斛珠，难觅锦江双鲤鱼。'},
    {t:'成人歌',a:'佚名〔先秦〕',c:'蚕则绩而蟹有匡。\n范则冠而蝉有绥。\n兄则死而子皋为之衰。'},
    {t:'成王挽歌',a:'岑参〔唐代〕',c:'幽山悲旧桂，长坂怆馀兰。地底孤灯冷，泉中一镜寒。\n铭旌门客送，骑吹路人看。漫作琉璃碗，淮王误合丹。'},
    {t:'呈外舅孙莘老二首',a:'黄庭坚〔宋代〕',c:'九陌黄尘乌帽底，五湖春水白鸥前。\n扁舟不为鲈鱼去，收取声名四十年。'},
    {t:'呈小村',a:'文天祥〔宋代〕',c:'万里飘零命羽轻，归来喜有故山迎。\n雷潜九地声元在，月暗千山魄再明。\n疑是仓公回已死，恍如羊祜说前生。\n夜阑相对真成梦，清酒浩歌双剑横。'},
    {t:'城大顺回道中作',a:'范仲淹〔宋代〕',c:'三月二十七，羌山始见花。\n将军了边事，春老未还家。'},
    {t:'城东闲游',a:'刘禹锡〔唐代〕',c:'借问池台主，多居要路津。\n千金买绝境，永日属闲人。\n竹径萦纡入，花林委曲巡。\n斜阳众客散，空锁一园春。'},
    {t:'城旁',a:'王昌龄〔唐代〕',c:'降奚能骑射，战马百余匹。\n甲仗于寒川，霜囗囗囗囗。\n囗囗煞单于，薄暮红旗出。\n城旁粗少年，骤马垂长鞭。\n脱却囗囗囗，囗囗沦狄天。\n匈奴不敢出，漠北开尘烟。'},
    {t:'城旁□□',a:'王昌龄〔唐代〕',c:'降奚能骑射，战马百馀匹。甲仗明寒川，霜□□□□。\n□□煞单于，薄暮红旗出。城旁粗少年，骤马垂长鞭。\n脱却□□□，□剑沦秋天。匈奴不敢出，漠北闭甲烟。'},
    {t:'城上',a:'李商隐〔唐代〕',c:'有客虚投笔，无憀独上城。\n沙禽失侣远，江树著阴轻。\n边遽稽天讨，军须竭地征。\n贾生游刃极，作赋又论兵。'},
    {t:'城西陂泛舟',a:'杜甫〔唐代〕',c:'青蛾皓齿在楼船，横笛短箫悲远天。\n春风自信牙樯动，迟日徐看锦缆牵。\n鱼吹细浪摇歌扇，燕蹴飞花落舞筵。\n不有小舟能荡桨，百壶那送酒如泉？'},
    {t:'城西行',a:'刘禹锡〔唐代〕',c:'城西簇簇三叛族，叛者为谁蔡吴蜀。中使提刀出禁来，\n九衢车马轰如雷。临刑与酒杯未覆，雠家白官先请肉。\n守吏能然董卓脐，饥乌来觇桓玄目。城西人散泰阶平，\n雨洗血痕春草生。'},
    {t:'澄迈驿通潮阁二首',a:'苏轼〔宋代〕',c:'倦客愁闻归路遥，眼明飞阁俯长桥。\n贪看白鹭横秋浦，不觉青林没晚潮。\n余生欲老海南村，帝遣巫阳招我魂。\n杳杳天低鹘没处，青山一发是中原。'},
    {t:'澄心亭颂',a:'黄庭坚〔宋代〕',c:'菩萨清凉月，游於毕究空。\n众生劳水净，菩提影现中。\n忍观伏尘劳，波澄泥著底。\n八风动地来，尘劳还复起。\n觉海性澄圆，浪时无不浑。\n即浑即澄彻，个是涅盘门。'},
    {t:'池鹤二首',a:'白居易〔唐代〕',c:'高竹笼前无伴侣，乱鸡群里有低标。\n低头乍恐丹砂落，晒翅常疑白鹉消。\n转觉鸬鹚毛色下，苦嫌鹦鹉语声娇。\n临低一唳思何事，怅望青田云水遥。\n池中此鹤鹤中稀，恐是辽东老令威。\n带鹉松枝翘膝胫，放花菱片缀毛衣。\n低回且向林间宿，奋迅终须天外飞。\n若问故巢知处在，主人相恋未能归。'},
    {t:'池口风雨留三日',a:'黄庭坚〔宋代〕',c:'孤城三日风吹雨，小市人家只菜蔬。\n水远山长双属玉，身闲心苦一舂锄。\n翁从旁舍来收网，我适临渊不羡鱼。\n俯仰之间已陈迹，暮窗归了读残书。'},
    {t:'池上',a:'白居易〔唐代〕',c:'袅袅凉风动，凄凄寒露零。\n兰衰花始白，荷破叶犹青。\n独立栖沙鹤，双飞照水萤。\n若为寥落境，仍值酒初醒。'},
    {t:'池上',a:'韦应物〔唐代〕',c:'郡中卧病久，池上一来赊。\n榆柳飘枯叶，风雨倒横查。'},
    {t:'池上二绝',a:'白居易〔唐代〕',c:'山僧对棋坐，局上竹阴清。\n映竹无人见，时闻下子声。\n小娃撑小艇，偷采白莲回。\n不解藏踪迹，浮萍一道开。'},
    {t:'池上篇',a:'白居易〔唐代〕',c:'十亩之宅，五亩之园。\n足水一池，足竹千竿。\n勿谓土狭，勿谓地偏。\n足以容膝，足以息肩。\n足堂足庭，足桥足船。\n足书足酒，足歌足弦。\n足叟在中，白须飘然。\n识分知足，外无求焉。\n如鸟择木，姑务巢安。\n如龟居坎，不知海宽。\n灵鹤怪石，紫菱白莲。\n皆吾所好，尽在吾前。\n时饮一杯，或吟一篇。\n妻孥熙熙，鸡犬闲闲。\n优哉游哉，吾将终老乎其间。'},
    {t:'池上絮',a:'韩愈〔唐代〕',c:'池上无风有落晖，杨花晴后自飞飞。\n为将纤质凌清镜，湿却无穷不得归。'},
    {t:'池上早夏',a:'白居易〔唐代〕',c:'水积春塘晚，阴交夏木繁。\n舟船如野渡，篱落似江村。\n静拂琴床席，香开酒库门。\n慵闲无一事，时弄小娇孙。'},
    {t:'池塘七夕',a:'温庭筠〔唐代〕',c:'月出西南露气秋，绮罗河汉在斜沟。杨家绣作鸳鸯幔，\n张氏金为翡翠钩。香烛有花妨宿燕，画屏无睡待牵牛。\n万家砧杵三篙水，一夕横塘似旧游。'},
    {t:'池州',a:'文天祥〔宋代〕',c:'五老湖光远，九华山色昏。\n南冠前进士，北部故将军。\n芳草江头路，斜阳郭外村。\n匆匆十年梦，故国黯销魂。'},
    {t:'池州春送前进士蒯希逸',a:'杜牧〔唐代〕',c:'芳草复芳草，断肠还断肠。自然堪下泪，何必更残阳。\n楚岸千万里，燕鸿三两行。有家归不得，况举别君觞。'},
    {t:'池州清溪',a:'杜牧〔唐代〕',c:'弄溪终日到黄昏，照数秋来白发根。\n何物赖君千遍洗，笔头尘土渐无痕。'},
    {t:'齿坐呈山南诸隐',a:'孟浩然〔唐代〕',c:'习公有遗坐，高在白云陲。樵子不见识，山僧赏自知。\n以余为好事，携手一来窥。竹露闲夜滴，松风清昼吹。\n从来抱微尚，况复感前规。于此无奇策，苍生奚以为。'},
    {t:'赤壁',a:'杜牧〔唐代〕',c:'折戟沉沙铁未销，自将磨洗认前朝。\n东风不与周郎便，铜雀春深锁二乔。'},
    {t:'赤壁赋',a:'苏轼〔宋代〕',c:'壬戌之秋，七月既望，苏子与客水舟游于赤壁之下。清风徐来，水波不兴。举酒属客，诵明月之山，歌窈窕之章。少焉，月出于东山之上，徘徊于斗牛之间。白露横江，水光接天。纵一苇之所乎，凌万顷之茫然。浩浩乎乎冯虚御风，而不知其所止；飘飘乎乎遗世独立，羽化而登仙。\n于是饮酒乐甚，扣舷而歌之。歌曰：“桂棹兮兰桨，击空明兮溯流光。渺渺兮予怀，望美人兮天一方。”客有吹洞箫者，倚歌而和之。其声呜呜然，乎怨乎慕，乎泣乎诉；余音袅袅，不绝乎缕。舞幽壑之潜蛟，泣孤舟之嫠妇。\n苏子愀然，正襟危坐而问客曰：“何为其然也？”客曰：“‘月明星稀，乌鹊南飞’，此非曹孟德之山乎？西望夏口，东望江昌，山川相缪，郁乎苍苍，此非孟德之困于周郎者乎？方其破荆州，下江陵，顺流而东也，舳舻千里，旌旗蔽空，酾酒临江，横槊赋山，固一世之雄也，而今安在哉？况吾与子渔樵于江渚之上，侣鱼虾而友麋鹿，驾一叶之扁舟，举匏樽以相属。寄蜉蝣于天地，渺沧海之一粟。哀吾生之须臾，羡长江之无穷。挟飞仙以遨游，抱明月而长终。知不可乎骤得，托遗响于悲风。”\n苏子曰：“客亦知夫水与月乎？逝者乎斯，而未尝往也；盈虚者乎彼，而卒莫消长也。盖将自其变者而观之，则天地曾不能以一瞬；自其不变者而观之，则物与我皆无尽也，而又何羡乎！且夫天地之间，物各有主，苟非吾之所有，虽一毫而莫取。惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭。是造物者之无尽藏也，而吾与子之所共适。”\n客喜而笑，洗盏更酌。肴核既尽，杯盘狼籍。相与枕藉乎舟中，不知东方之既白。'},
    {t:'赤壁歌送别',a:'李白〔唐代〕',c:'二龙争战决雌雄，赤壁楼船扫地空。\n烈火张天照云海，周瑜于此破曹公。\n君去沧江望澄碧，鲸鲵唐突留馀迹。\n一一书来报故人，我欲因之壮心魄。'},
    {t:'赤日炎炎似火烧',a:'佚名〔元代〕',c:'赤日炎炎似火烧，野田禾稻半枯焦。\n农夫心内如汤煮，公子王孙把扇摇。'},
    {t:'赤松·一作赤松涧',a:'皎然〔唐代〕',c:'缘岸蒙笼出见天，晴沙沥沥水溅溅。\n何处羽人长洗药，残花无数逐流泉。'},
    {t:'赤枣子·风淅淅',a:'纳兰性德〔清代〕',c:'风淅淅，雨纤纤。难怪春愁细细添。记不分明疑是梦，梦来还隔一重帘。'},
    {t:'赤枣子·寄语酿花风日好',a:'纳兰性德〔清代〕',c:'惊晓漏，护春眠。格外娇慵只自怜。\n寄语酿花风日好，绿窗来与上琴弦。'},
    {t:'敕赐百官樱桃',a:'王维〔唐代〕',c:'芙蓉阙下会千官，紫禁朱樱出上阑。\n才是寝园春荐后，非关御苑鸟衔残。\n归鞍竞带青丝笼，中使频倾赤玉盘。\n饱食不须愁内热，大官还有蔗浆寒。'},
    {t:'敕赐宁王池宴',a:'张九龄〔唐代〕',c:'贤王有池馆，明主赐春游。淑气林间发，恩光水上浮。\n徒惭和鼎地，终谢巨川舟。皇泽空如此，轻生莫可酬。'},
    {t:'敕借岐王九成宫避暑应教',a:'王维〔唐代〕',c:'帝子远辞丹凤阙，天书遥借翠微宫。\n隔窗云雾生衣上，卷幔山泉入镜中。\n林下水声喧语笑，岩间树色隐房栊。\n仙家未必能胜此，何事吹笙向碧空。'},
    {t:'敕勒歌塞北',a:'温庭筠〔唐代〕',c:'敕勒金隤壁，阴山无岁华。\n帐外风飘雪，营前月照沙。\n羌儿吹玉管，胡姬踏锦花。\n却笑江南客，梅落不归家。'},
    {t:'冲雪宿新寨忽忽不乐',a:'黄庭坚〔宋代〕',c:'县北县南何日了，又来新寨解明鞍。\n山衔斗柄三星没，雪共月明千里寒。\n小吏有时须束带，故人颇问不休官。\n江南长尽捎云竹，归及春风斩钓竿。'},
    {t:'冲雪至余庆觉林雪连日不止',a:'陆游〔宋代〕',c:'策蹇清吟涉若耶，灞桥犹恨近京华。\n山前千顷谁种玉？座上六时天散花。\n林雀无声溪彴断，炊烟不动竹篱斜。\n胜游更觉平生少，未羡银河泛客槎。'},
    {t:'虫豸诗·蚁子三首',a:'元稹〔唐代〕',c:'蚁子生无处，偏因湿处生。\n阴霪烦扰攘，拾粒苦嘤咛。\n床上主人病，耳中虚藏鸣。\n雷霆翻不省，闻汝作牛声。\n时术功虽细，年深祸亦成。\n攻穿漏江海，噆食困蛟鲸。\n敢惮榱梁蠹，深藏柱石倾。\n寄言持重者，微物莫全轻。\n攘攘终朝见，悠悠卒岁疑。\n讵能分牝牡，焉得有蝝蚳。\n徙市竟何意，生涯都几时。\n巢由或逢我，应似我相期。'},
    {t:'崇义里滞雨',a:'李贺〔唐代〕',c:'落莫谁家子，来感长安秋。\n壮年草羁恨，梦泣生白头。\n瘦马秣败草，雨沫飘寒沟。\n南宫古帘暗，湿景传签筹。\n家山远千里，云脚天东头。\n忧眠枕剑匣，客帐梦封侯。'},
    {t:'崇因寺',a:'晏殊〔宋代〕',c:'卷帘山色眼前见，入夜涛声枕上闻。\n苔径雨馀堆落叶，石楼风静锁寒云。'},
    {t:'仇池笔记·鹅有二能',a:'苏轼〔宋代〕',c:'钱塘人喜杀，日屠百鹅。予自湖上夜归，屠者之门百鹅皆号，声振衢路，若有所诉。鹅能警盗，亦能却蛇，其粪杀蛇。蜀人园池养鹅，蛇即远去。有二能而不能免死，又有祈雨之厄。悲夫，安得人如逸少乎！'},
    {t:'酬白二十二舍人早春曲江见招',a:'张籍〔唐代〕',c:'曲江冰欲尽，风日已恬和。\n柳色看犹浅，泉声觉渐多。\n紫蒲生湿岸，青鸭戏新波。\n仙掖高情客，相招共一过。'},
    {t:'酬白乐天杏花园',a:'元稹〔唐代〕',c:'刘郎不用闲惆怅，且作花间共醉人。\n算得贞元旧朝士，几人同见太和春。'},
    {t:'酬曹侍御过象县见寄',a:'柳宗元〔唐代〕',c:'破额山前碧玉流，骚人遥驻木兰舟。\n春风无限潇湘意，欲采蘋花不自由。'},
    {t:'酬岑二十主簿秋夜见赠之作',a:'高适〔唐代〕',c:'舍下蛩乱鸣，居然自萧索。缅怀高秋兴，忽枉清夜作。\n感物我心劳，凉风惊二毛。池枯菡萏死，月出梧桐高。\n如何异乡县，复得交才彦。汩没嗟后时，蹉跎耻相见。\n箕山别来久，魏阙谁不恋。独有江海心，悠悠未尝倦。'},
    {t:'酬崔八早梅有赠兼示之作',a:'李商隐〔唐代〕',c:'知访寒梅过野塘，久留金勒为回肠。谢郎衣袖初翻雪，\n荀令熏炉更换香。何处拂胸资蝶粉，几时涂额藉蜂黄。\n维摩一室虽多病，亦要天花作道场。'},
    {t:'酬答二首',a:'李贺〔唐代〕',c:'金鱼公子夹衫长，密装腰鞓割玉方。\n行处春风随马尾，柳花偏打内家香。\n雍州二月梅池春，御水鵁鶄暖白蘋。\n试问酒旗歌板地，今朝谁是拗花人。'},
    {t:'酬丁柴桑',a:'陶渊明〔魏晋〕',c:'有客有客，爰来宦止。\n秉直司聪，惠于百里。\n飱胜如归，聆善若始。\n匪惟谐也，屡有良游。\n载言载眺，以写我忧。\n放欢一遇，既醉还休。\n实欣心期，方从我游。'},
    {t:'酬郭给事',a:'王维〔唐代〕',c:'洞门高阁霭馀辉，桃李阴阴柳鸟飞。\n禁里疏钟官舍晚，省中啼鸟吏人稀。\n晨摇玉佩趋金殿，夕奉天书拜琐闱。\n强欲从君无那老，将因卧病解朝衣。'},
    {t:'酬韩侍郎张博士雨后游曲江见寄',a:'白居易〔唐代〕',c:'小园新种红樱树，闲绕花枝便当游。\n何必更随鞍马队，冲泥蹋雨曲江头。'},
    {t:'酬韩庶子',a:'张籍〔唐代〕',c:'西街幽僻处，正与懒相宜。寻寺独行远，借书常送迟。\n家贫无易事，身病足闲时。寂寞谁相问，只应君自知。'},
    {t:'酬杭州白使君，兼寄浙东元大夫',a:'张籍〔唐代〕',c:'相印暂离临远镇，掖垣出守复传时。一行已作三年别，\n两处空传七字诗。越地江山应共见，秦天风月不相知。\n人间聚散真难料，莫叹平生信所之。'},
    {t:'酬河南节度使贺兰大夫见赠之作',a:'高适〔唐代〕',c:'高阁凭栏槛，中军倚旆旌。\n感时常激切，于己即忘情。\n河华屯妖气，伊瀍有战声。\n愧无戡难策，多谢出师名。\n秉钺知恩重，临戎觉命轻。\n股肱瞻列岳，唇齿赖长城。\n隐隐摧锋势，光光弄印荣。\n鲁连真义士，陆逊岂书生。\n直道宁殊智，先鞭忽抗行。\n楚云随去马，淮月尚连营。\n抚剑堪投分，悲歌益不平。\n从来重然诺，况值欲横行。'},
    {t:'酬淮南牛相公述旧见贻',a:'刘禹锡〔唐代〕',c:'少年曾忝汉庭臣，晚岁空馀老病身。初见相如成赋日，\n寻为丞相扫门人。追思往事咨嗟久，喜奉清光笑语频。\n犹有登朝旧冠冕，待公三入拂埃尘。'},
    {t:'酬晖上人秋夜山亭有赠',a:'陈子昂〔唐代〕',c:'皎皎白林秋，微微翠山静。\n禅居感物变，独坐开轩屏。\n风泉夜声杂，月露宵光冷。\n多谢忘机人，尘忧未能整。'},
    {t:'酬晖上人夏日林泉',a:'陈子昂〔唐代〕',c:'闻道白云居，窈窕青莲宇。\n岩泉万丈流，树石千年古。\n林卧对轩窗，山阴满庭户。\n方释尘事劳，从君袭兰杜。'},
    {t:'酬蓝田崔丞立之咏雪见寄',a:'韩愈〔唐代〕',c:'京城数尺雪，寒气倍常年。泯泯都无地，茫茫岂是天。\n崩奔惊乱射，挥霍讶相缠。不觉侵堂陛，方应折屋椽。\n出门愁落道，上马恐平鞯。朝鼓矜凌起，山斋酩酊眠。\n吾方嗟此役，君乃咏其妍。冰玉清颜隔，波涛盛句传。\n朝飧思共饭，夜宿忆同毡。举目无非白，雄文乃独玄。'},
    {t:'酬乐天',a:'元稹〔唐代〕',c:'放鹤在深水，置鱼在高枝。\n升沉或异势，同谓非所宜。\n君为邑中吏，皎皎鸾凤姿。\n顾我何为者，翻侍白玉墀。\n昔作芸香侣，三载不暂离。\n逮兹忽相失，旦夕梦魂思。\n崔嵬骊山顶，宫树遥参差。\n只得两相望，不得长相随。\n多君岁寒意，裁作秋兴诗。\n上言风尘苦，下言时节移。\n官家事拘束，安得携手期。\n愿为云与雨，会合天之垂。'},
    {t:'酬乐天初冬早寒见寄',a:'刘禹锡〔唐代〕',c:'乍起衣犹冷，微吟帽半欹。霜凝南屋瓦，鸡唱后园枝。\n洛水碧云晓，吴宫黄叶时。两传千里意，书札不如诗。'},
    {t:'酬乐天春寄微之',a:'元稹〔唐代〕',c:'鹦心明黠雀幽蒙，何事相将尽入笼。君避海鲸惊浪里，\n我随巴蟒瘴烟中。千山塞路音书绝，两地知春历日同。\n一树梅花数升酒，醉寻江岸哭东风。'},
    {t:'酬乐天登乐游园见忆',a:'元稹〔唐代〕',c:'昔君乐游园，怅望天欲曛。今我漫江上，快意波翻云。\n秋空压澶漫，澒洞无垢氛。四顾皆豁达，我埃今日伸。\n长安隘朝市，百道走埃尘。轩车随对列，骨肉非本亲。\n夸游丞相第，偷入常侍门。爱君直如发，勿念江湖人。'},
    {t:'酬乐天寄蕲州簟',a:'元稹〔唐代〕',c:'蕲簟未经春，君先拭翠筠。\n知为热时物，预与瘴中人。\n碾玉连心润，编牙小片珍。\n霜凝青汗简，冰透碧游鳞。\n水魄轻涵黛，琉璃薄带尘。\n梦成伤冷滑，惊卧老龙身。'},
    {t:'酬乐天寄生衣',a:'元稹〔唐代〕',c:'秋茅处处流痎疟，夜鸟声声哭瘴云。\n羸骨不胜纤细物，欲将文服却还君。'},
    {t:'酬乐天见寄',a:'元稹〔唐代〕',c:'三千里外巴蛇穴，四十年来司骨官。瘴色满身治不尽，\n疮痕刮骨洗应难。常甘人向衰容薄，独讶君将旧眼看。\n前日诗中高盖字，至今唇舌遍长安。'},
    {t:'酬乐天见忆，兼伤仲远',a:'元稹〔唐代〕',c:'死别重泉閟，生离万里赊。瘴侵草病骨，梦到故人家。\n遥泪陈根草，闲收落地花。庾公楼怅望，巴子国生涯。\n河任天然曲，江随峡势斜。与君皆直戆，须分老泥沙。'},
    {t:'酬乐天频梦微之',a:'元稹〔唐代〕',c:'山水万重书断绝，念君怜我梦相闻。\n我今因病魂颠倒，唯梦闲人不梦君。'},
    {t:'酬乐天劝醉',a:'元稹〔唐代〕',c:'神曲清浊酒，牡丹深浅花。\n少年境相饮，此乐何可涯。\n沉机造神境，不必悟楞伽。\n酡颜返童貌，安未成丹砂。\n刘伶称酒德，所称良未多。\n愿君听此曲，我为尽称嗟。\n一杯颜色好，十盏胆气加。\n半酣得自恣，酩酊归太和。\n共醉真可乐，飞觥撩乱歌。\n独醉亦有趣，兀然无与他。\n美人醉灯下，左右流横波。\n王孙醉床上，颠倒眠绮罗。\n君今劝我醉，劝醉意如何。'},
    {t:'酬乐天三月三日见寄',a:'元稹〔唐代〕',c:'当年此日花前醉，今日花前病里销。\n独倚破帘闲怅望，可怜虚度好春朝。'},
    {t:'酬乐天书后三韵',a:'元稹〔唐代〕',c:'今日庐峰霞绕寺，昔时鸾殿凤回书。\n两封相去八年后，一种俱云五夜初。\n渐觉此生都是梦，不能将泪滴双鱼。'},
    {t:'酬乐天叹穷愁见寄',a:'元稹〔唐代〕',c:'病煎愁绪转纷纷，百里何由说信君。老去心情随日减，\n远来书信隔年闻。三冬有电连春雨，九月无霜尽火云。\n并与巴南终岁热，四时谁道各平分。'},
    {t:'酬乐天叹损伤见寄',a:'元稹〔唐代〕',c:'前途何在转茫茫，渐老那能不自伤。\n病为怕风多睡月，起因花药暂扶床。\n函关气索迷真侣，峡水波翻碍故乡。\n唯有秋来两行泪，对君新赠远诗章。'},
    {t:'酬乐天闻李尚书拜相以诗见贺',a:'元稹〔唐代〕',c:'初因弹劾死东川，又为亲情弄化权。百口共经三峡水，\n一时重上两漫天。尚书入用虽旬月，司马衔冤已十年。\n若待更遭秋瘴后，便愁平地有重泉。'},
    {t:'酬乐天喜邻郡',a:'元稹〔唐代〕',c:'蹇驴瘦马尘中伴，紫绶朱衣梦里身。\n符竹偶因成对岸，文章虚被配为邻。\n湖翻白浪常看雪，火照红妆不待春。\n老大那能更争竞，任君投募醉乡人。'},
    {t:'酬乐天闲卧见寄',a:'刘禹锡〔唐代〕',c:'散诞向阳眠，将闲敌地仙。\n诗情茶助爽，药力酒能宣。\n风碎竹间日，露明池底天。\n同年未同隐，缘欠买山钱。'},
    {t:'酬乐天小亭寒夜有怀',a:'刘禹锡〔唐代〕',c:'寒夜阴云起，疏林宿鸟惊。斜风闪灯影，迸雪打窗声。\n竟夕不能寐，同年知此情。汉皇无奈老，何况本书生。'},
    {t:'酬乐天雪中见寄',a:'元稹〔唐代〕',c:'知君夜听风萧索，晓望林亭雪尽糊。撼落不教封柳眼，\n扫来偏尽附梅株。敲扶密竹枝犹亚，煦浪寒禽气渐苏。\n坐觉湖声迷远浪，回惊云路在长途。钱塘湖上蘋先合，\n梳洗楼前粉暗铺。石立玉童披鹤氅，台施瑶席换龙须。\n满空飞舞应为瑞，寡和高歌只自娱。莫遣拥帘伤思妇，\n且将盈尺慰农夫。称觞彼此情何异，对景东西事有殊。\n镜水绕山山尽白，琉璃云母世间无。'},
    {t:'酬乐天扬州初逢席上见赠',a:'刘禹锡〔唐代〕',c:'巴山楚水凄凉地，二十三年弃似身。\n怀旧空吟闻笛赋，到乡翻似烂柯人。\n沉舟侧畔千帆过，病树前头万木春。\n今日听君歌一曲，暂凭杯酒长精神。'},
    {t:'酬乐天咏老见示',a:'刘禹锡〔唐代〕',c:'人谁不顾老，老去有谁怜。\n身瘦带频减，发稀冠自偏。\n废书缘惜眼，多灸为随年。\n经事还谙事，阅人如阅川。\n细思皆幸矣，下此便翛然。\n莫道桑榆晚，为霞尚满天。'},
    {t:'酬乐天馀思不尽加为六韵之作',a:'元稹〔唐代〕',c:'律吕同声我尔身，文章君是一如伦。众推贾谊为才子，\n帝喜相如作侍臣。次韵千言曾报答，直辨三道共经纶。\n元诗驳杂真难辨，白朴流传用转新。蔡女图书虽在口，\n于公门户岂生尘。商瞿未老犹希冀，莫把籝金便付人。'},
    {t:'酬乐天雨后见忆',a:'元稹〔唐代〕',c:'雨滑危梁性命愁，差池一步一生休。\n黄泉便是通州郡，渐入深泥渐到州。'},
    {t:'酬乐天重寄别',a:'元稹〔唐代〕',c:'却报君侯听苦辞，老头抛我欲何之。\n武牢关外虽分手，不似如今衰白时。'},
    {t:'酬乐天舟泊夜读微之诗',a:'元稹〔唐代〕',c:'知君暗泊西江岸，读我闲诗欲到明。\n今夜通州还不睡，满山风雨杜鹃声。'},
    {t:'酬乐天醉别',a:'元稹〔唐代〕',c:'前回一去五年别，此别又知何日回。\n好住乐天休怅望，匹如元不到京来。'},
    {t:'酬黎居士淅川作',a:'王维〔唐代〕',c:'侬家真个去，公定随侬否。\n著处是莲花，无心变杨柳。\n松龛藏药裹，石唇安茶臼。\n气味当共知，那能不携手。'},
    {t:'酬李参军崇嗣旅馆见赠',a:'陈子昂〔唐代〕',c:'昨夜银河畔，星文犯遥汉。今朝落气新，物色果逢真。\n言从天上落，乃是地仙人。白璧疑冤楚，乌艰似入秦。\n摧藏多古意，历览备艰辛。乐广云虽睹，夷吾风未春。\n凤歌空有问，龙性讵能驯。宝剑终应出，骊珠会见珍。\n未及冯公老，何惊孺子贫。青云傥可致，北海忆孙宾。'},
    {t:'酬李光化见寄二首·其二',a:'范仲淹〔宋代〕',c:'万里承平尧舜风，使君尺素半空空。\n庭中无事吏归早，野外有歌民意丰。\n石鼎斗茶浮乳白，海螺行酒滟波红。\n宴堂未尽嘉宾兴，移下秋光月色中。'},
    {t:'酬李光化见寄二首·其一',a:'范仲淹〔宋代〕',c:'交亲莫笑出麾频，不任纖机祇任真。\n远护玉关犹竭力，入陪金铉敢周身。\n素心直拟圭无玷，晚节当如竹有筠。\n道本逍遥惟所适，吾生何用蠖求伸。'},
    {t:'酬李仆射晚春见寄',a:'张籍〔唐代〕',c:'戟户洞初晨，莺声雨后频。虚庭清气在，众药湿光新。\n鱼动芳池面，苔侵老竹身。教铺尝酒处，自问探花人。\n独此长多病，幽居欲过春。今朝听高韵，忽觉离埃尘。'},
    {t:'酬李少府',a:'高适〔唐代〕',c:'出塞魂屡惊，怀贤意难说。谁知吾道间，乃在客中别。\n日夕捧琼瑶，相思无休歇。伊人虽薄宦，举代推高节。\n述作凌江山，声华满冰雪。一登蓟丘上，四顾何惨烈。\n来雁无尽时，边风正骚屑。将从崖谷遁，且与沉浮绝。\n君若登青云，余当投魏阙。'},
    {t:'酬令狐司录善福精舍见赠',a:'韦应物〔唐代〕',c:'野寺望山雪，空斋对竹林。我以养愚地，生君道者心。'},
    {t:'酬令狐相公见寄',a:'刘禹锡〔唐代〕',c:'才兼文武播雄名，遗爱芳尘满洛城。身在行台为仆射，\n书来甪里访先生。闲游占得嵩山色，醉卧高听洛水声。\n千里相思难命驾，七言诗里寄深情。'},
    {t:'酬令狐相公杏园花下饮有怀见寄',a:'刘禹锡〔唐代〕',c:'年年曲江望，花发即经过。未饮心先醉，临风思倍多。\n三春看又尽，两地欲如何。日望长安道，空成劳者歌。'},
    {t:'酬令狐相公赠别',a:'刘禹锡〔唐代〕',c:'越声长苦有谁闻，老向湘山与楚云。\n海峤新辞永嘉守，夷门重见信陵君。\n田园松菊今迷路，霄汉鸳鸿久绝群。\n幸遇甘泉尚词赋，不知何客荐雄文。'},
    {t:'酬刘柴桑',a:'陶渊明〔魏晋〕',c:'穷居寡人用，时忘四运周。\n门庭多落叶，慨然知已秋。\n新葵郁北牖，嘉穟养南畴。\n今我不为乐，知有来岁不？\n命室携童弱，良日登远游。'},
    {t:'酬刘和州戏赠',a:'白居易〔唐代〕',c:'池边新种七株梅，欲到花时点检来。\n莫怕长洲桃李妒，今年好为使君开。'},
    {t:'酬柳柳州家鸡之赠',a:'刘禹锡〔唐代〕',c:'日日临池弄小雏，还思写论付官奴。\n柳家新样元和脚，且尽姜芽敛手徒。'},
    {t:'酬陆少府',a:'高适〔唐代〕',c:'朝临淇水岸，还望卫人邑。别意在山阿，征途背原隰。\n萧萧前村口，唯见转蓬入。水渚人去迟，霜天雁飞急。\n固应不远别，所与路未及。欲济川上舟，相思空伫立。'},
    {t:'酬马八效古见赠',a:'高适〔唐代〕',c:'深崖无绿竹，秀色徒氛氲。时代种桃李，无人顾此君。\n奈何冰雪操，尚与蒿莱群。愿托灵仙子，一声吹入云。'},
    {t:'酬马侍郎寄酒·马总也',a:'韩愈〔唐代〕',c:'一壶情所寄，四句意能多。秋到无诗酒，其如月色何。'},
    {t:'酬庞十兵曹',a:'高适〔唐代〕',c:'忆昔游京华，自言生羽翼。怀书访知己，末路空相识。\n许国不成名，还家有惭色。托身从畎亩，浪迹初自得。\n雨泽感天时，耕耘忘帝力。同人洛阳至，问我睢水北。\n遂尔款津涯，净然见胸臆。高谈悬物象，逸韵投翰墨。\n别岸迥无垠，海鹤鸣不息。梁城多古意，携手共凄恻。\n怀贤想邹枚，登高思荆棘。世情恶疵贱，之子怜孤直。\n酬赠感并深，离忧岂终极。'},
    {t:'酬裴十六功曹巡府西驿途中见寄',a:'韩愈〔唐代〕',c:'相公罢论道，聿至活东人。御史治言事，作吏府中尘。\n遂令河南治，今古无俦伦。四海日富庶，道鱼隘蹄轮。\n府西三百里，候馆同鱼鳞。相公谓御史，劳子去自巡。\n是时山水秋，光景何鲜新。哀鸿鸣清耳，宿雾褰高旻。\n遗我行旅诗，轩轩有风神。譬如黄金盘，照耀荆璞真。\n我来亦已幸，事贤友其仁。持竿洛水侧，孤治屡穷辰。\n多才自劳苦，无用只因循。辞免期匪远，行行及山春。'},
    {t:'酬裴侍御对雨感时见赠',a:'李白〔唐代〕',c:'雨色秋来寒，风严清江爽。\n孤高绣衣人，潇洒青霞赏。\n平生多感激，忠义非外奖。\n祸连积怨生，事及徂川往。\n楚邦有壮士，鄢郢翻扫荡。\n申包哭秦庭，泣血将安仰。\n鞭尸辱已及，堂上罗宿莽。\n颇似今之人，蟊贼陷忠谠。\n渺然一水隔，何由税归鞅。\n日夕听猿怨，怀贤盈梦想。'},
    {t:'酬裴秀才',a:'高适〔唐代〕',c:'男儿贵得意，何必相知早。飘荡与物永，蹉跎觉年老。\n长卿无产业，季子惭妻嫂。此事难重陈，未于众人道。'},
    {t:'酬秦山人见寻',a:'皎然〔唐代〕',c:'左右香童不识君，担簦访我领鸥群。\n山僧待客无俗物，唯有窗前片碧云。'},
    {t:'酬秦山人系题赠',a:'皎然〔唐代〕',c:'出斋步杉影，手自开禅扉。花满不污地，云多从触衣。\n思山石藓净，款客露葵肥。果得宗居士，论心到极微。'},
    {t:'酬秦系山人戏赠',a:'皎然〔唐代〕',c:'正论禅寂忽狂歌，莫是尘心颠倒多。\n白足行花曾不染，黄囊贮酒欲如何。'},
    {t:'酬司空璲少府',a:'高适〔唐代〕',c:'飘飖未得意，感激与谁论。昨日遇夫子，仍欣吾道存。\n江山满词赋，札翰起凉温。吾见风雅作，人知德业尊。\n惊飙荡万木，秋气屯高原。燕赵何苍茫，鸿雁来翩翻。\n此时与君别，握手欲无言。'},
    {t:'酬宋使君见诒',a:'张九龄〔唐代〕',c:'陟邻初禀训，献策幸逢时。\n朝列且云忝，君恩复若兹。\n庭闱际海曲，轺传荷天慈。\n顾己欢乌鸟，闻君泣素丝。\n才明应主召，福善岂神欺。\n但愿白心在，终然涅不淄。'},
    {t:'酬宋使君见赠之作',a:'张九龄〔唐代〕',c:'时来不自意，宿昔谬枢衡。翊圣负明主，妨贤愧友生。\n罢归犹右职，待罪尚南荆。政有留棠旧，风因继组成。\n高轩问疾苦，烝庶荷仁明。衰废时所薄，只言僚故情。'},
    {t:'酬孙洛阳',a:'张籍〔唐代〕',c:'家贫相远住，斋馆入时稀。独坐看书卷，闲行著褐衣。\n早蝉庭笋老，新雨径莎肥。各离争名地，无人见是非。'},
    {t:'酬太原令狐相公见寄',a:'刘禹锡〔唐代〕',c:'书信来天外，琼瑶满匣中。\n衣冠南渡远，旌节北门雄。\n鹤唳华亭月，马嘶榆塞风。\n山川几千里，惟有两心同。'},
    {t:'酬滕子京同年',a:'范仲淹〔宋代〕',c:'谢家风雅若为酬，散吏方耽海上游。\n疏懒几忘传笔梦，寂寥仍有负薪忧。\n欲歌兰雪归真隐，敢向簪轩竞急流。\n如共茂先瞻气象，莫言神物在南州。'},
    {t:'酬王二十舍人雪中见寄',a:'柳宗元〔唐代〕',c:'三日柴门拥不开，阶平庭满白皑皑。\n今朝蹈作琼瑶迹，为有诗从凤沼来。'},
    {t:'酬王六霁后书怀见示',a:'张九龄〔唐代〕',c:'云雨俱行罢，江天已洞开。炎氛霁后灭，边绪望中来。\n作骥君垂耳，为鱼我曝鳃。更怜湘水赋，还是洛阳才。'},
    {t:'酬王履震游园林见贻',a:'张九龄〔唐代〕',c:'宅生惟海县，素业守郊园。中览霸王说，上徼明主恩。\n一行罢兰径，数载历金门。既负潘生拙，俄从周任言。\n逶迤恋轩陛，萧散反丘樊。旧径稀人迹，前池耗水痕。\n并看芳树老，唯觉敝庐存。自我栖幽谷，逢君翳覆盆。\n孟轲应有命，贾谊得无冤。江上行伤远，林间偶避喧。\n地偏人事绝，时霁鸟声繁。独善心俱闭，穷居道共尊。\n乐因南涧藻，忧岂北堂萱。幽意加投漆，新诗重赠轩。\n平生徇知己，穷达与君论。'},
    {t:'酬卫八雪中见寄',a:'高适〔唐代〕',c:'季冬忆淇上，落日归山樊。旧宅带流水，平田临古村。\n雪中望来信，醉里开衡门。果得希代宝，缄之那可论。'},
    {t:'酬喜相遇同州与乐天替代',a:'刘禹锡〔唐代〕',c:'旧托松心契，新交竹使符。行年同甲子，筋力羡丁夫。\n别后诗成帙，携来酒满壶。今朝停五马，不独为罗敷。'},
    {t:'酬薛员外谊见戏一首',a:'皎然〔唐代〕',c:'方知正始作，丽掩碧云诗。文彩盈怀袖，风规发咏思。\n遗弓逢大敌，摩垒怯偏师。频有移书让，多惭系组迟。\n浅才迂且拙，虚誉喜还疑。犹倚披沙鉴，长歌向子期。'},
    {t:'酬严少尹徐舍人见过不遇',a:'王维〔唐代〕',c:'公门暇日少，穷巷故人稀。偶值乘篮舆，非关避白衣。\n不知炊黍谷，谁解扫荆扉。君但倾茶碗，无妨骑马归。'},
    {t:'酬叶道卿学士见寄',a:'范仲淹〔宋代〕',c:'世传学中禄，小子乃逢辰。\n一入谏诤司，鸿毛忽其身。\n可负万乘主，甘为三黜人。\n岂量尧舜心，如日照孤臣。\n薄责落善地，雅尚过朝伦。\n仅同龟在泥，敢冀蠖求伸。\n朱楼逼清江，下睨百丈鳞。\n羡此南鱼乐，不忍持钩轮。\n为郡良优优，乏才止循循。\n恬愉弗扰外，何以慰远民。\n拙可存吾朴，静可逸吾神。\n渐得疏懒味，下车将四旬。\n嘉兴风雅来，观对如天宾。\n感兹韶夏音，佐我台上春。'},
    {t:'酬友人见寄新文',a:'孟郊〔唐代〕',c:'为客栖未定，况当玄月中。繁云人碧霄，落雪和清风。\n郊陌绝行人，原隰多飞蓬。耕牛返村巷，野花依房栊。\n我无饥冻忧，身托莲花宫。安闲赖禅伯，复得疏尘蒙。\n览君郢曲文，词彩何冲融。讴吟不能已，顿觉形神空。'},
    {t:'酬元九对新栽竹有怀见寄',a:'白居易〔唐代〕',c:'昔我十年前，与君始相识。曾将合竹竿，比君孤且直。\n中心一以合，外事纷无极。共保合竹心，风改侵不得。\n始嫌梧桐树，合至先改色。不爱杨柳枝，春来软无力。\n怜君别我后，见竹长相忆。长欲在眼前，故栽庭户侧。\n分首今何处，君南我在北。吟我赠君诗，对之心恻恻。'},
    {t:'酬元九侍御赠璧竹鞭长句',a:'刘禹锡〔唐代〕',c:'碧玉孤根生在林，美人相赠比双金。\n初开郢客缄封后，想见巴山冰雪深。\n多节本怀端直性，露青犹有岁寒心。\n何时策马同归去，关树扶疏敲镫吟。'},
    {t:'酬元主簿子球别赠',a:'皎然〔唐代〕',c:'故人方远适，访我陈别情。此夜偶禅室，一言了无生。\n览君缄中宝，如搴清玉瑛。胡为蕴高价，岁晚徒营营。\n辞秩贫且病，何人见艰贞。出无黄金橐，空歌白苎行。\n威迟策驽马，独望故关树。渺渺千里心，春风起中路。\n近闻新拜命，鸾凤犹栖棘。劝君寄一枝，且养冥冥翼。\n甘泉多竹花，明年待君食。'},
    {t:'酬张祜处士见寄长句四韵',a:'杜牧〔唐代〕',c:'七子论诗谁似公，曹刘须在指挥中。\n荐衡昔日知文举，乞火无人作蒯通。\n北极楼台长挂梦，西江波浪远吞空。\n可怜故国三千里，虚唱歌词满六宫。'},
    {t:'酬张少府',a:'王维〔唐代〕',c:'晚年唯好静，万事不关心。\n自顾无长策，空知返旧林。\n松风吹解带，山月照弹琴。\n君问穷通理，渔歌入浦深。'},
    {t:'酬浙东元尚书见寄绫素',a:'张籍〔唐代〕',c:'越地缯纱纹样新，远封来寄学曹人。便令裁制为时服，\n顿觉光荣上病身。应念此官同弃置，独能相贺更殷勤。\n三千里外无由见，海上东风又一春。'},
    {t:'酬郑户曹骊山感怀',a:'韦应物〔唐代〕',c:'苍山何郁盘，飞阁凌上清。先帝条好道，下元朝百灵。\n白云已萧条，麋鹿但纵横。泉水今尚暖，旧太亦青青。\n我念绮襦岁，扈从当太平。小臣职前驱，驰道出灞亭。\n翻翻日月旗，殷殷鼙鼓声。万马自腾骧，八骏按辔行。\n日出烟峤绿，氛氲丽层甍。登临起遐想，沐浴欢圣情。\n朝燕咏无事，时丰贺国祯。日和弦管音，下使万室听。\n海内凑朝贡，贤愚共欢荣。合沓车马喧，西闻长安城。\n事往世如寄，感深迹所经。申章报兰藻，一望双涕零。'},
    {t:'酬知退',a:'元稹〔唐代〕',c:'终须修到无修处，闻尽声闻始不闻。\n莫著妄心销彼我，我心无我亦无君。'},
    {t:'酬朱庆馀',a:'张籍〔唐代〕',c:'越女新妆出镜心，自知明艳更沉吟。\n齐纨未是人间贵，一曲菱歌敌万金。'},
    {t:'酬诸公见过',a:'王维〔唐代〕',c:'嗟予未丧，哀此孤生。\n屏居蓝田，薄地躬耕。\n岁晏输税，以奉粢盛。\n晨往东皋，草露未晞。\n暮看烟火，负担来归。\n我闻有客，足扫荆扉。\n箪食伊何，疈瓜抓枣。\n仰厕群贤，皤然一老。\n愧无莞簟，班荆席藁。\n泛泛登陂，折彼荷花。\n静观素鲔，俯映白沙。\n山鸟群飞，日隐轻霞。\n登车上马，倏忽云散。\n雀噪荒村，鸡鸣空馆。\n还复幽独，重欷累叹。'},
    {t:'愁',a:'杜甫〔唐代〕',c:'江草日日唤愁生，巫峡泠泠非世情。\n盘涡鹭浴底心性？独树花发自分明！\n十年戎马暗万国，异域宾客老孤城。\n渭水秦山得见否？人今罢病虎纵横！'},
    {t:'愁',a:'杜牧〔唐代〕',c:'聚散竟无形，回肠自结成。\n古今留不得，离别又潜生。\n降虏将军思，穷秋远客情。\n何人更憔悴，落第泣秦京。'},
    {t:'愁倚阑令',a:'晏几道〔宋代〕',c:'春罗薄，酒醒寒。梦初残。欹枕片时云雨事，已关山。\n楼上斜日阑干。楼前路、曾试雕鞍。拚却一襟怀远泪，倚阑看。'},
    {t:'愁倚阑令',a:'晏几道〔宋代〕',c:'凭江阁，看烟鸿。恨春浓。还有当红闻笛泪，洒东风。\n时候草绿花红。斜阳外、远水溶溶。浑似阿莲双枕畔，画屏中。'},
    {t:'愁倚阑令·花阴月',a:'晏几道〔宋代〕',c:'花阴月，柳梢莺。近清明。长恨去年今夜雨，洒离亭。\n枕上怀远诗成。红笺纸、小砑吴绫。寄与征人教念远，莫无情。'},
    {t:'筹笔驿',a:'李商隐〔唐代〕',c:'鱼鸟犹疑畏简书，风云常为护储胥。\n徒令上将挥神笔，终见降王走传车。\n管乐有才真不忝，关张无命欲何如？\n他年锦里经祠庙，梁父吟成恨有余。'},
    {t:'丑奴儿',a:'周邦彦〔宋代〕',c:'美盼低迷情宛转。爱雨怜云，渐觉宽金钏。桃李香苞秋不展。深心黯黯谁能见。\n宋玉墙高才一觇。絮乱丝繁，苦隔春风面。歌板未终风色便。梦为蝴蝶留芳甸。'},
    {t:'丑奴儿',a:'晏几道〔宋代〕',c:'日高庭院杨花转，闲淡春风。莺语惺忪。似笑金屏昨夜空。\n娇慵未洗匀妆手，闲印斜红。新恨重重。都与年时旧意同。'},
    {t:'丑奴儿·此生自断天休问',a:'辛弃疾〔宋代〕',c:'此生自断天休问，独倚危楼。独倚危楼，不信人间别有愁。\n君来正是眠时节，君且归休。君且归休，说与西风一任秋。'},
    {t:'丑奴儿·大石梅花',a:'周邦彦〔宋代〕',c:'肌肤绰约真仙子，来伴冰霜。洗尽铅黄。素面初无一点妆。\n寻花不用持银烛，暗里闻香。零落池塘。分付余妍与寿阳。'},
    {t:'丑奴儿·近来愁似天来大',a:'辛弃疾〔宋代〕',c:'近来愁似天来大，谁解相怜。谁解相怜。又把愁来做个天。\n都将今古无穷事，放在愁边。放在愁边。却自移家向酒泉。'},
    {t:'丑奴儿·书博山道中壁',a:'辛弃疾〔宋代〕',c:'少年不识愁滋味，爱识层楼。爱识层楼，为赋新词强说愁。\n而今识尽愁滋味，欲说还休。欲说还休，却道“天凉好个秋”！'},
    {t:'丑奴儿·烟芜露麦荒池柳',a:'辛弃疾〔宋代〕',c:'烟芜露麦荒池柳，洗雨烘晴。洗雨烘晴，一样春风几样青。\n提壶脱袴催归去，万恨千情。万恨千情，各自无聊各自鸣。'},
    {t:'丑奴儿·夜来酒醒清无梦',a:'秦观〔宋代〕',c:'夜来酒醒清无梦，愁倚阑干。露滴轻寒。雨打芙蓉泪不干。\n佳人别后音尘悄，瘦尽难拚。明月无端。已过红楼十二间。'},
    {t:'丑奴儿·子母猿',a:'张炎〔宋代〕',c:'山人去后知何处，风月清虚。来挂无拘。戏引儿孙乐有余。\n悬崖挂树如相语，常守枯株。久与人疏。闲了当年一卷书。'},
    {t:'丑奴儿近·博山道中效李易安体',a:'辛弃疾〔宋代〕',c:'千峰云起，骤雨一霎儿价。更远树斜阳，风景怎生图画。青旗卖酒，山那畔、别有人家，只消山水光中，无事过这一夏。\n午醉醒时，松窗竹户，万千潇洒。野鸟飞来，又是一般闲暇。却怪白鸥，觑着人、欲下未下。旧盟都在，新来莫是，别有说话。'},
    {t:'出城',a:'李贺〔唐代〕',c:'雪下桂花稀，啼乌被弹归。\n关水乘驴影，秦风帽带垂。\n入乡诚可重，无印自堪悲。\n卿卿忍相问，镜中双泪姿。'},
    {t:'出城寄权璩杨敬之',a:'李贺〔唐代〕',c:'草暖云昏万里春，宫花拂面送行人。\n自言汉剑当飞去，何事还车载病身。'},
    {t:'出定力院作',a:'王安石〔宋代〕',c:'江上悠悠不见人，十年尘垢梦中身。\n殷懃为解丁香结，放出枝间自在春。'},
    {t:'出东门',a:'孟郊〔唐代〕',c:'饿马骨亦耸，独驱出东门。少年为日程，衰叟十日奔。\n寒景不我为，疾走落平原。眇默荒草行，恐惧夜魄翻。\n为生自组织，千首大雅言。道路如抽蚕，宛转羁肠繁。'},
    {t:'出鄂州界怀表臣二首',a:'刘禹锡〔唐代〕',c:'离席一挥杯，别愁今尚醉。迟迟有情处，却恨江帆驶。\n梦觉疑连榻，舟行忽千里。不见黄鹤楼，寒沙雪相似。'},
    {t:'出宫人二首',a:'杜牧〔唐代〕',c:'闲吹玉殿昭华管，醉折梨园缥蒂花。\n十年一梦归人世，绛缕犹封系臂纱。\n平阳拊背穿驰道，铜雀分香下璧门。\n几向缀珠深殿里，妒抛羞态卧黄昏。'},
    {t:'出关经华岳寺，访法华云公',a:'岑参〔唐代〕',c:'野寺聊解鞍，偶见法华僧。开门苔西岳，石壁青棱层。\n竹径厚苍苔，松门盘紫藤。长廊列古画，高云悬孤灯。\n五月山雨热，三峰火云蒸。侧闻樵人言，深谷犹积冰。\n久愿寻此山，至今嗟未能。谪官忽东走，王程苦相仍。\n欲去恋双树，何由穷一乘。月轮吐山郭，夜色空清澄。'},
    {t:'出关宿盘豆馆对丛芦有感',a:'李商隐〔唐代〕',c:'芦叶梢梢夏景深，邮亭暂欲洒尘襟。\n昔年曾是江南客，此日初为关外心。\n思子台边风自急，玉娘湖上月应沉。\n清声不远行人去，一世荒城伴夜砧。'},
    {t:'出还',a:'韦应物〔唐代〕',c:'昔出喜还家，今还独伤意。入室掩无光，衔哀写虚位。\n凄凄动幽幔，寂寂惊寒吹。幼女复何知，时来庭下戏。\n咨嗟日复老，错莫身如寄。家人劝我餐，对案空垂泪。'},
    {t:'出海',a:'文天祥〔宋代〕',c:'一团荡漾水晶盘，四畔青天作护阑。\n著我扁舟了无碍，分明便作混沦看。\n水天一色玉空明，便似乘槎上太清。\n我爱东坡南海句，兹游奇绝冠平生。'},
    {t:'出郊',a:'王安石〔宋代〕',c:'川原一片绿交加，深树冥冥不见花。\n风日有情无处着，初回光景到桑麻。'},
    {t:'出金陵',a:'王安石〔宋代〕',c:'白石冈头草木深，春风相与散衣襟。\n浮云映郭留佳气，飞鸟随人作好音。'},
    {t:'出门',a:'韩愈〔唐代〕',c:'长安百万家，出门无所之。岂敢尚幽独，与世实参差。\n古人虽已死，书上有其辞。开卷读且想，千载若相期。\n出门各有道，我道方未夷。且于此中息，天命不吾欺。'},
    {t:'出门难',a:'文天祥〔宋代〕',c:'罗刹盈庭夜色寒，人家灯火半阑珊。\n梦回跳出铁门限，世上一重人鬼关。'},
    {t:'出塞',a:'王安石〔宋代〕',c:'涿州沙上饮盘桓，看舞春风小契丹。\n塞雨巧催燕泪落，蒙蒙吹湿汉衣冠。'},
    {t:'出塞·一作塞上曲',a:'张籍〔唐代〕',c:'秋塞雪初下，将军远出师。分营长记火，放马不收旗。\n月冷边帐湿，沙昏夜探迟。征人皆白首，谁见灭胡时。'},
    {t:'出塞二首',a:'王昌龄〔唐代〕',c:'秦时明月汉时关，万里长征人马还。\n但使龙城飞将在，不教胡马度阴山。\n骝马新跨白玉鞍，战罢沙场月色寒。\n城头铁鼓声犹震，匣里金刀血马干。'},
    {t:'出塞作',a:'王维〔唐代〕',c:'居延城外猎天骄，白草连天野火烧。\n暮云空碛时驱马，秋日平原好射雕。\n护羌校尉朝乘障，破虏将军夜渡辽。\n玉靶角弓珠勒马，汉家将赐霍嫖姚。'},
    {t:'出山道中口占',a:'朱熹〔宋代〕',c:'川原红绿一时新，暮雨朝晴更可人。\n书册埋头无了日，不如抛却去寻春。'},
    {t:'出守桐庐道中十绝',a:'范仲淹〔宋代〕',c:'沧浪清可爱，白鸟鉴中飞。\n不信有京洛，风尘化客衣。'},
    {t:'出守桐庐道中十绝·其八',a:'范仲淹〔宋代〕',c:'素心爱云水，此日东南行。\n笑解尘缨处，沧浪无限清。'},
    {t:'出守桐庐道中十绝其七',a:'范仲淹〔宋代〕',c:'万钟谁不慕，意气满堂金。必若枉此道，伤哉非素心。'},
    {t:'出守桐庐道中十绝其五',a:'范仲淹〔宋代〕',c:'有病甘长废，无机苦直言。江山藏拙好，何敢望天阍。'},
    {t:'出为豫章郡途次庐山东岩下',a:'张九龄〔唐代〕',c:'兹山镇何所，乃在澄湖阴。下有蛟螭伏，上与虹蜺寻。\n灵仙未始旷，窟宅何其深。双阙出云峙，三宫入烟沉。\n攀崖犹昔境，种杏非旧林。想像终古迹，惆怅独往心。\n纷吾婴世网，数载忝朝簪。孤根自靡托，量力况不任。\n多谢周身防，常恐横议侵。岂匪鹓鸿列，惕如泉壑临。\n迨兹刺江郡，来此涤尘襟。有趣逢樵客，忘怀狎野禽。\n栖闲义未果，用拙欢在今。愿言答休命，归事丘中琴。'},
    {t:'出颍口初见淮山是日至寿州',a:'苏轼〔宋代〕',c:'我行日夜向江海，枫叶芦花秋与长。\n长淮忽迷天远近，青山久与船低昂。\n寿州已见白石塔，短棹未转黄茅冈。\n波平风软望不到，故人久立烟苍茫。'},
    {t:'出游',a:'皎然〔唐代〕',c:'少时不见山，便觉无奇趣。\n狂发从乱歌，情来任闲步。\n此心谁共证，笑看风吹树。'},
    {t:'出自蓟北门行',a:'李白〔唐代〕',c:'虏阵横北荒，胡星曜精芒。\n羽书速惊电，烽火昼连光。\n虎竹救边急，戎车森已行。\n明主不安席，按剑心飞扬。\n推毂出猛将，连旗登战场。\n兵威冲绝幕，杀气凌穹苍。\n列卒赤山下，开营紫塞傍。\n孟冬沙风紧，旌旗飒凋伤。\n画角悲海月，征衣卷天霜。\n挥刃斩楼兰，弯弓射贤王。\n单于一平荡，种落自奔亡。\n收功报天子，行歌归咸阳。'},
    {t:'初出城留别',a:'白居易〔唐代〕',c:'朝从紫禁归，暮出青门去。\n勿言城东陌，便是江南路。\n扬鞭簇车马，挥手辞亲故。\n我生本无乡，心安是归处。'},
    {t:'初出关旅亭夜坐，怀王大校书',a:'孟浩然〔唐代〕',c:'向夕槐烟起，葱茏池馆曛。客中无偶坐，关外惜离群。\n烛至萤光灭，荷枯雨滴闻。永怀芸阁友，寂寞滞扬云。'},
    {t:'初出济州别城中故人',a:'王维〔唐代〕',c:'微官易得罪，谪去济川阴。\n执政方持法，明君照此心。\n闾阎河润上，井邑海云深。\n纵有归来日，各愁年鬓侵。'},
    {t:'初春汉中漾舟',a:'孟浩然〔唐代〕',c:'漾舟逗何处，神女汉皋曲。①\n雪罢往复开，春潭千丈绿。\n轻舟恣来往，探玩无厌足。②\n波影摇妓钗，沙光逐人目。③\n倾杯鱼鸟醉，联句莺花续。④\n良会难再逢，日入须秉烛。⑤'},
    {t:'初春有感，寄歙州邢员外',a:'杜牧〔唐代〕',c:'雪涨前溪水，啼声已绕滩。梅衰未减态，春嫩不禁寒。\n迹去梦一觉，年来事百般。闻君亦多感，何处倚阑干。'},
    {t:'初到黄州',a:'苏轼〔宋代〕',c:'自笑平生为口忙，老来事业转山唐。\n长江绕郭知鱼美，好竹连山觉笋香。\n逐客不妨员外置，诗人例作水曹郎。\n只惭无补丝毫事，尚费官家压酒囊。'},
    {t:'初冬',a:'陆游〔宋代〕',c:'平生诗句领流光，绝爱初冬万瓦霜。\n枫叶欲残看愈好，梅花未动意先香。\n暮年自适何妨退，短景无营亦自长。\n况有小儿同此趣，一窗相对弄朱黄。'},
    {t:'初冬绝句',a:'陆游〔宋代〕',c:'鲈肥菰脆调羹美，荞熟油新作饼香。\n自古达人轻富贵，例缘乡味忆还乡。'},
    {t:'初冬夜饮',a:'杜牧〔唐代〕',c:'淮阳多病偶求欢，客袖侵霜与烛盘。\n砌下梨花一堆雪，明年谁此凭阑干。'},
    {t:'初发道中寄远',a:'张九龄〔唐代〕',c:'日夜乡山远，秋风复此时。旧闻胡马思，今听楚猿悲。\n念别朝昏苦，怀归岁月迟。壮图空不息，常恐发如丝。'},
    {t:'初发江陵有怀',a:'张九龄〔唐代〕',c:'极望涔阳浦，江天渺不分。扁舟赏此去，鸥鸟自为群。\n他日怀真赏，中年负俗纷。适来果微尚，倏尔会斯文。\n复想金闺籍，何如梦渚云。我行多胜寄，浩思独氛氲。'},
    {t:'初发曲江溪中',a:'张九龄〔唐代〕',c:'溪流清且深，松石复阴临。\n正尔可嘉处，胡为无赏心。\n我由不忍别，物亦有缘侵。\n自匪常行迈，谁能知此音。'},
    {t:'初发扬子寄元大校书',a:'韦应物〔唐代〕',c:'凄凄去亲爱，泛泛入烟雾。\n归棹洛阳人，残钟广陵树。\n今朝此为别，何处还相遇。\n世事波上舟，沿洄安得住。'},
    {t:'初过陇山途中呈宇文判官',a:'岑参〔唐代〕',c:'一驿过一驿，驿骑如星流。\n平明发咸阳，暮及陇山头。\n陇水不可听，呜咽令人愁。\n沙尘扑马汗，雾露凝貂裘。\n西来谁家子，自道新封侯。\n前月发安西，路上无停留。\n都护犹未到，来时在西州。\n十日过沙碛，终朝风不休。\n马走碎石中，四蹄皆血流。\n万里奉王事，一身无所求。\n也知塞垣苦，岂为妻子谋。\n山口月欲出，先照关城楼。\n溪流与松风，静夜相飕飗。\n别家赖归梦，山塞多离忧。\n与子且携手，不愁前路修。'},
    {t:'初寒夜寄卢子蒙',a:'元稹〔唐代〕',c:'月是阴秋镜，寒为寂寞资。轻寒酒醒后，斜月枕前时。\n倚壁思闲事，回灯检旧诗。闻君亦同病，终夜远相悲。'},
    {t:'初南食贻元十八协律',a:'韩愈〔唐代〕',c:'鲎实如惠文，骨眼相负行。蠔相黏为山，百十各自生。\n蒲鱼尾如蛇，口眼不相营。蛤即是虾蟆，同实浪异名。\n章举马甲柱，斗以怪自呈。其馀数十种，莫不可叹惊。\n我来御魑魅，自宜味南烹。调以咸与酸，芼以椒与橙。\n腥臊始发越，咀吞面汗騂。惟蛇旧所识，实惮口眼狞。\n开笼听其去，郁屈尚不平。卖尔非我罪，不屠岂非情。\n不祈灵珠报，幸无嫌怨并。聊歌以记之，又以告同行。'},
    {t:'初年乐城馆中卧疾怀归作',a:'孟浩然〔唐代〕',c:'异县天隅僻，孤帆海畔过。往来乡信断，留滞客情多。\n腊月闻雷震，东风感岁和。蛰虫惊户穴，巢鹊眄庭柯。\n徒对芳尊酒，其如伏枕何。归屿理舟楫，江海正无波。'},
    {t:'初秋',a:'孟浩然〔唐代〕',c:'不觉初秋夜渐长，清风习习重凄凉。\n炎炎暑退茅斋静，阶下丛莎有露光。'},
    {t:'初秋寄友人',a:'温庭筠〔唐代〕',c:'闲梦正悠悠，凉风生竹楼。夜琴知欲雨，晓簟觉新秋。\n独鸟楚山远，一蝉关树愁。凭将离别恨，江外问同游。'},
    {t:'初秋宿直',a:'晏殊〔宋代〕',c:'绛河星斗夜阑干，禁署沈沈闭九关。\n上帝册书群玉府，仙人宫阙巨鳌山。\n凉蟾影度秋阴薄，促漏声来夜唱闲。\n拥鼻吟多欲愁绝，严钟凄断树乌还。'},
    {t:'初秋戏作山居杂兴俳体十二解',a:'杨万里〔宋代〕',c:'独对秋筠倒晚壶，喜无吏舍四歌呼。\n柳梢一壳兹缁滓，屋角双班谷古孤。'},
    {t:'初秋小雨',a:'陆游〔宋代〕',c:'雨来一洗肺肝热，风过远吹禾黍香。\n谁识山翁欢喜处，短檠灯火夜初长。'},
    {t:'初秋行圃四首·其二',a:'杨万里〔宋代〕',c:'小小园亭亦自佳，晚云过雨却成霞。\n烂开栀子浑如雪，已熟来禽尚带花。'},
    {t:'初秋行圃四首·其三',a:'杨万里〔宋代〕',c:'花梢飞下两鸣鸠，欲住还行行复留。\n拾得来禽吞不得，啄来啄去竟成休。'},
    {t:'初秋行圃四首·其四',a:'杨万里〔宋代〕',c:'落日无情最有情，遍催万树暮蝉鸣。\n听来咫尺无寻处，寻到旁边却不声。'},
    {t:'初秋行圃四首·其一',a:'杨万里〔宋代〕',c:'今年六月不胜凉，七月炎蒸不可当。\n一阵秋风初过雨，个般天气好烧香。'},
    {t:'初秋夜坐赠吴武陵',a:'柳宗元〔唐代〕',c:'稍稍雨侵竹，翻翻鹊惊丛。\n美人隔湘浦，一夕生秋风。\n积雾杳难极，沧波浩无穷。\n相思岂云远，即席莫与同。\n若人抱奇音，朱弦縆枯桐。\n清商激西颢，泛滟凌长空。\n自得本无作，天成谅非功。\n希声閟大朴，聋俗何由聪。'},
    {t:'初秋忆金均两弟',a:'张九龄〔唐代〕',c:'江渚秋风至，他乡离别心。\n孤云愁自远，一叶感何深。\n忧喜尝同域，飞鸣忽异林。\n青山西北望，堪作白头吟。'},
    {t:'初日',a:'王昌龄〔唐代〕',c:'初日净金闺，先照床前暖。\n斜光入罗幕，稍稍亲丝管。\n云发不能梳，杨花更吹满。'},
    {t:'初入淮河四绝句',a:'杨万里〔宋代〕',c:'船离洪泽岸头沙，人到淮河意不佳。\n何必桑乾方是远，中流以北即天涯！\n刘岳张韩宣国威，赵张二相筑皇基。\n长淮咫尺分南北，泪湿秋风欲怨谁？\n两岸舟船各背驰，波痕交涉亦难为。\n只余鸥鹭无拘管，北去南来自在飞。\n中原父老莫空谈，逢着王人诉不堪。\n却是归鸿不能语，一年一度到江南。'},
    {t:'初入淮河四绝句·其三',a:'杨万里〔宋代〕',c:'两岸舟船各背驰，波痕交涉亦难为。\n只余鸥鹭无拘管，北去南来自在飞。'},
    {t:'初入淮河四绝句其四',a:'杨万里〔宋代〕',c:'中原父老莫空谈，逢著王人诉不堪。却是归鸿不能语，一年一度到江南。'},
    {t:'初入峡苦风寄故乡亲友',a:'陈子昂〔唐代〕',c:'故乡今日友，欢会坐应同。\n宁知巴峡路，辛苦石尤风。'},
    {t:'初入湘中有喜',a:'张九龄〔唐代〕',c:'征鞍穷郢路，归棹入湘流。望鸟唯贪疾，闻猿亦罢愁。\n两边枫作岸，数处橘为洲。却记从来意，翻疑梦里游。'},
    {t:'初食淮白',a:'杨万里〔宋代〕',c:'淮白须将淮水煮，江南水煮正花违。\n霜吹柳叶落都尽，鱼吃雪花方解肥。\n醉卧糟丘名不恶，下来盐豉味全非。\n饔人且莫供羊酪，更买银刀三尺围。'},
    {t:'初食笋呈座中',a:'李商隐〔唐代〕',c:'嫩箨香苞初出林，於陵论价重如金。\n皇都陆海应无数，忍剪凌云一寸心。'},
    {t:'初授官题高冠草堂',a:'岑参〔唐代〕',c:'三十始一命，宦情多欲阑。\n自怜无旧业，不敢耻微官。\n涧水吞樵路，山花醉药栏。\n只缘五斗米，辜负一渔竿。'},
    {t:'初望淮山',a:'黄庭坚〔宋代〕',c:'风裘雪帽别家林，紫燕黄鹂已夏深。\n三釜古人干禄意，一年慈母望归心。\n劳生逆旅何休息，病眼看山力不禁。\n想见夕阳三径里，乱蝉嘶罢柳阴阴。'},
    {t:'初下浙江舟中口号',a:'孟浩然〔唐代〕',c:'八月观潮罢，三江越海浔。回瞻魏阙路，空复子牟心。'},
    {t:'初夏',a:'陆游〔宋代〕',c:'槐柳成阴雨洗尘，樱桃乳酪并尝新。\n古来江左多佳句，夏浅胜春最可人。'},
    {t:'初夏即事',a:'王安石〔宋代〕',c:'石梁茅屋有弯碕，流水溅溅度两陂。\n晴日暖风生麦气，绿阴幽草胜花时。'},
    {t:'初夏即事十二解',a:'杨万里〔宋代〕',c:'傱教节序暗相催，历日尘生懒看来。\n却是石榴知立夏，年年此日一花开。'},
    {t:'初夏即事十二解其四',a:'杨万里〔宋代〕',c:'从教节序暗相催，历日尘生懒看来。却是石榴知立夏，年年此日一花开。'},
    {t:'初夏绝句',a:'陆游〔宋代〕',c:'纷纷红紫已成尘，布谷声中夏令新。\n夹路桑麻行不尽，始知身是太平人。'},
    {t:'初夏曲三首',a:'刘禹锡〔唐代〕',c:'铜壶方促夜，斗柄暂南回。稍嫌尽衣重，初怜北户开。\n西园花已尽，新月为谁来。\n时节过繁华，枝枝千万家。巢禽命子戏，园果坠枝斜。\n寂寞孤飞蝶，窥丛觅晚花。\n绿水风初暖，青林露早晞。麦陇雉朝雊，桑野人暮归。\n百舌悲花尽，平芜来去飞。'},
    {t:'初夏行平水道中',a:'陆游〔宋代〕',c:'老去人间乐事稀，一年容易又春归。\n市桥压担蓴丝滑，村店堆盘豆荚肥。\n傍水风林莺语语，满原烟草蝶飞飞。\n郊行已觉侵微暑，小立桐阴换夹衣。'},
    {t:'初月',a:'李白〔唐代〕',c:'玉蟾离海上，白露湿花时。\n云畔风生爪，沙头水浸眉。\n乐哉弦管客，愁杀战征儿。\n因绝西园赏，临风一咏诗。'},
    {t:'初至封丘作',a:'高适〔唐代〕',c:'可怜薄暮宦游子，独卧虚斋思无已。\n去家百里不得归，到官数日秋风起。'},
    {t:'除官赴阙至江州寄鄂岳李大夫',a:'韩愈〔唐代〕',c:'盆城去鄂渚，风便一日耳。\n不枉故人书，无因帆江水。\n故人辞礼闱，旌节镇江圻。\n而我窜逐者，龙钟初得归。\n别来已三岁，望望长迢递。\n咫尺不相闻，平生那可计。\n我齿落且尽，君鬓白几何。\n年皆过半百，来日苦无多。\n少年乐新知，衰暮思故友。\n譬如亲骨肉，宁免相可不。\n我昔实愚蠢，不能降色辞。\n子犯亦有言，臣犹自知之。\n公其务贳过，我亦请改事。\n桑榆倘可收，愿寄相思字。'},
    {t:'除官归京睦州雨霁',a:'杜牧〔唐代〕',c:'秋半吴天霁，清凝万里光。水声帐笑语，岚翠扑衣裳。\n远树疑罗帐，孤云认粉囊。溪山帐两越，时自到重阳。\n顾我能甘贱，无由得自强。误曾公触尾，不敢夜循墙。\n岂意笼飞鸟，还为锦帐郎。网今开傅燮，书旧识黄香。\n姹女真虚语，饥儿欲一行。浅深须揭厉，休更学张纲。'},
    {t:'除日',a:'韦应物〔唐代〕',c:'思怀耿如昨，季月已云暮。忽惊年复新，独恨人成故。\n冰池始泮绿，梅援还飘素。淑景方转延，朝朝自难度。'},
    {t:'除夕送次公子入京受县',a:'杨万里〔宋代〕',c:'过眼光阴又岁穷，相看父子一花同。\n春回雨点溪声里，人醉梅花烛影中。\n汝趁暄和朝北阙，我扶衰病见东风。\n弟兄努力思报国，放我沧浪作钓翁。'},
    {t:'除夜',a:'文天祥〔宋代〕',c:'乾坤空落落，岁月去堂堂。\n末路惊风雨，穷边饱雪霜。\n命随年欲尽，身与世俱忘。\n无复屠苏梦，挑灯夜未央。'},
    {t:'除夜',a:'元稹〔唐代〕',c:'忆昔岁除夜，见君花烛前。\n今宵祝文上，重叠叙新年。\n闲处低声哭，空堂背月眠。\n伤心小儿女，撩乱火堆边。'},
    {t:'除夜',a:'白居易〔唐代〕',c:'病眼少眠非守岁，老心多感又临春。\n火销灯尽天明后，便是平头六十人。'},
    {t:'除夜酬乐天',a:'元稹〔唐代〕',c:'引傩绥旆乱毵毵，戏罢人归思不堪。虚涨火尘龟浦北，\n无由阿伞凤城南。休官期限元同约，除夜情怀老共谙。\n莫道明朝始添岁，今年春在岁前三。'},
    {t:'除夜寄弟妹',a:'白居易〔唐代〕',c:'感时思弟妹，不寐百忧生。\n万里经年别，孤灯此夜情。\n病容非旧日，归思逼新正。\n早晚重欢会，羁离各长成。'},
    {t:'除夜寄微之',a:'白居易〔唐代〕',c:'鬓毛不觉白毵毵，一事无成百不堪。\n共惜盛时辞阙下，同嗟除夜在江南。\n家山泉石寻常忆，世路风波子细谙。\n老校于君合先退，明年半百又加三。'},
    {t:'除夜乐城逢张少府',a:'孟浩然〔唐代〕',c:'云海泛瓯闽，风潮泊岛滨。何知岁除夜，得见故乡亲。\n余是乘槎客，君为失路人。平生复能几，一别十馀春。'},
    {t:'除夜小饮，叹都下酥乳不至',a:'杨万里〔宋代〕',c:'雪韭霜菘酌岁除，也无牛乳也无酥。\n贫中却富何人会，自有村醪不用沽。'},
    {t:'除夜雪',a:'陆游〔宋代〕',c:'北风吹雪四更初，嘉瑞天教及岁除。\n半盏屠苏犹未举，灯前小草写桃符。'},
    {t:'除夜野宿常州城外二首',a:'苏轼〔宋代〕',c:'行歌野哭两堪悲，远火低星渐向微。\n病眼不眠非守岁，乡音无伴苦思归。\n重衾脚冷知霜重，新沐头轻感发稀。\n多谢残灯不嫌客，孤舟一夜许相依。\n南来三见岁云徂，直恐终身走道途。\n老去怕看新历日，退归拟学旧桃符。\n烟花已作青春意，霜雪偏寻病客须。\n但把穷愁博长健，不辞最后饮屠苏。'},
    {t:'除夜有怀',a:'孟浩然〔唐代〕',c:'五更钟漏欲相催，四气推迁往复回。\n帐里残灯才去焰，炉中香气尽成灰。\n渐看春逼芙蓉枕，顿觉寒销竹叶杯。\n守岁家家应未卧，相思那得梦魂来。'},
    {t:'除夜作',a:'高适〔唐代〕',c:'旅馆寒灯独不眠，客心何事转凄然。\n故乡今夜思千里，霜鬓明朝又一年。'},
    {t:'滁州西涧',a:'韦应物〔唐代〕',c:'独怜幽草涧边生，上有黄鹂深树鸣。\n春潮带雨晚来急，野渡无人舟自横。'},
    {t:'楚城',a:'陆游〔宋代〕',c:'江上荒城猿鸟悲，隔江便是屈原祠。\n一千五百年间事，只有滩声似旧时。'},
    {t:'楚村道中',a:'周邦彦〔宋代〕',c:'林栖野吸散鸦群，极目风霾乱黯曛。\n短麦良良乾忆雨，远峰黯黯细输云。\n愁逢杂路寻车辙，赖有高林出酒巾。\n辄得问津凡父老，不应看客废锄耘。'},
    {t:'楚村道中其二',a:'周邦彦〔宋代〕',c:'族云行太虚，布置初狼籍。弥缝泪四维，俄顷同一色。\n雨形如别泪，含恶未忍滴。泥涂颇翻车，行蛇自朝夕。\n中央成白道，袅袅踏蛇脊。潺湲冒田水，去作涧底碧。\n高林荫清快，渴乌时一掷。晚休张庄聚，泾草蒙古驿。\n往时解鞍地，醉墨栖坏壁。孤星探先出，泪镜小摩拭。\n比邻忽喧呼，夜磔鲁津伯。梦归萱草堂，再拜悲喜剧。\n问言劳如何，嗟我子行役。平明看屋霤，两鹊声啧啧。\n果逢南使还，冯寄好消息。谁秣百里驹，肯税不论直。'},
    {t:'楚村道中其一',a:'周邦彦〔宋代〕',c:'林栖野啄散鸦群，极目风霾乱黯曛。短麦离离乾忆雨，远峰黯黯细输云。\n愁逢杂路寻车辙，赖有高林出酒巾。辄得问津凡父老，不应看客废锄耘。'},
    {t:'楚宫',a:'李商隐〔唐代〕',c:'湘波如泪色漻漻，楚厉迷魂逐鬼遥。\n枫树夜猿愁自断，女萝山鬼语相邀。\n空归腐败犹难复，更困腥臊岂易招？\n但使故乡三户在，彩丝谁惜惧长蛟。'},
    {t:'楚宫二首',a:'李商隐〔唐代〕',c:'十二峰前落照微，高唐宫暗坐迷归。\n朝云暮雨长相接，犹自君王恨见稀。\n月姊曾逢下彩蟾，倾城消息隔重帘。\n已闻佩响知腰细，更辨弦声觉指纤。\n暮雨自归山悄悄，秋河不动夜厌厌。\n王昌且在墙东住，未必金堂得免嫌。'},
    {t:'楚宫行',a:'张籍〔唐代〕',c:'章华宫中九月时，桂花半落红从垂。江头骑火照辇道，\n君王夜从云梦归。霓旌凤盖到双阙，台当重重歌吹发。\n千门万户开相当，烛笼左右列成行。下辇更衣入洞房，\n洞房侍女尽焚香。玉阶罗幕微有霜，齐言此夕乐未央。\n玉酒湛湛盈华觞，丝竹次第鸣中堂。巴姬起舞向君王，\n回身垂手结明珰。愿君千年万年寿，朝出射麋夜饮酒。'},
    {t:'楚狂接舆歌',a:'佚名〔先秦〕',c:'凤兮凤兮何德之衰。\n往者不可谏。\n来者犹可追。\n已而已而。\n今之从政者殆而。'},
    {t:'楚平王庙',a:'周邦彦〔宋代〕',c:'奸臣乱国纪，伍奢思结缨。\n杀贤去遗种，巢卵同时倾。\n健雏脱身去，口血流吴庭。\n达士见几微，楚卷忧苦兵。\n十年军入郢，势如波卷萍。\n贤亡国婴难，王死尸受刑。\n将隳七世庙，先坏百里城。\n子胥虽捐江，素车驾长鲸。\n惊涛寄怒余，遗庙罗千楹。\n王祠何其微，破屋风泠泠。\n蛰虫陷香案，饥鼠悬灯檠。\n淫俗敬魑魅，何人雇威灵。\n臣冤不雠主，况乃锄丘茔。\n报应苦不直，吾将问冥冥。'},
    {t:'楚夕旅泊古兴',a:'岑参〔唐代〕',c:'独鹤唳江月，孤帆凌楚云。秋风冷萧瑟，芦荻花纷纷。\n忽思湘川老，欲访云中君。骐驎息悲鸣，愁见豺虎群。'},
    {t:'楚吟',a:'李商隐〔唐代〕',c:'山上离宫宫上楼，楼前宫畔暮江流。\n楚天长短黄昏雨，宋玉无愁亦自愁。'},
    {t:'楚怨',a:'孟郊〔唐代〕',c:'秋入楚江水，独照汨罗魂。手把绿荷泣，意愁珠泪翻。\n九门不可入，一犬吠千门。'},
    {t:'楚竹吟酬卢虔端公见和湘弦怨',a:'孟郊〔唐代〕',c:'握中有新声，楚竹人未闻。识音引谓谁，清夜吹赠君。\n昔为潇湘引，曾动潇湘云。一叫凤改听，再昼鹤失群。\n江花匪秋落，山日当昼曛。众浊响杂沓，孤清思氛氲。\n欲知怨有形，愿向明月分。一掬灵均泪，千年湘水文。'},
    {t:'处州水南庵二首',a:'秦观〔宋代〕',c:'竹柏萧森溪水南，道人为作小圆庵。\n市区收罢鱼豚税，来与弥陀共一龛。'},
    {t:'处州闲题',a:'秦观〔宋代〕',c:'清酒一杯甜似蜜，美人双鬓黑如鸦。\n莫夸春色欺秋色，未信桃花胜菊花。'},
    {t:'传花枝·平生自负',a:'柳永〔宋代〕',c:'平生自负，风流才调。口儿里、道颠张陈赵。唱新词，改难令，总颠颠倒。解刷扮，能喷嗽，表里都峭。惜遇著、饮席歌筵，人人尽道。可惜许老了。\n阎罗大伯曾教来，道人生、但不须烦恼。遇良辰，当美景，追欢买笑。剩活取百十年，只恁厮好。若限满、鬼使来追，待倩个、掩通著到。'},
    {t:'传神自赞',a:'王安石〔宋代〕',c:'我与丹青两幻身，世间流转会成尘。\n但知此物非他物，莫问今人犹昔人。'},
    {t:'船夜援琴',a:'白居易〔唐代〕',c:'鸟栖鱼不动，月照夜江深。\n身外都无事，舟中只有琴。\n七弦为益友，两耳是知音。\n心静即声淡，其间无古今。'},
    {t:'窗日',a:'黄庭坚〔宋代〕',c:'叹息西窗过隙驹，微阳初至日光舒。\n谁言暗长宫中线，添得思堂一卷书。'},
    {t:'垂钓',a:'白居易〔唐代〕',c:'临水一长啸，忽思十年初。\n三登甲乙第，一入承明庐。\n浮生多变化，外事有盈虚。\n今来伴江叟，沙头坐钓鱼。'},
    {t:'垂柳',a:'李商隐〔唐代〕',c:'娉婷小苑中，婀娜曲池东。朝佩皆垂地，仙衣尽带风。\n七贤宁占竹，三品且饶松。肠断灵和殿，先皇玉座空。'},
    {t:'垂丝钓·商调',a:'周邦彦〔宋代〕',c:'缕金翠羽。妆成才见眉妩。倦倚雁帘，看舞风絮。愁几许。寄凤丝雁柱。\n春将暮。向层城苑路。钿车似水，时时花径相遇。旧游伴侣。还到曾来处。门掩风和雨。梁间燕语。问那人在否。'},
    {t:'垂丝海棠半落',a:'杨万里〔宋代〕',c:'雨後精神退九分，病香愁态不胜春。\n落阶一寸轻红雪，卷地风来政恼人。'},
    {t:'春别曲',a:'张籍〔唐代〕',c:'长江春水绿堪染，莲叶出水大如钱。\n江头橘树君自种，那不长系木兰船。'},
    {t:'春残',a:'陆游〔宋代〕',c:'石镜山前送落晖，春残回首倍依依。\n时平壮士无功老，乡远征人有梦归。\n苜蓿苗侵官道合，芜菁花入麦畦稀。\n倦游自笑摧颓甚，谁记飞鹰醉打围。'},
    {t:'春蝉',a:'元稹〔唐代〕',c:'我自东归日，厌苦春鸠声。作诗道化工，不遣春蝉生。\n及来商山道，山深气不平。春秋两相似，虫如百种鸣。\n风松不成韵，蜩螗沸如羹。岂无朝阳凤，羞与微物争。\n安得天上雨，奔浑河海倾。荡涤反时气，然后好晴明。'},
    {t:'春愁',a:'孟郊〔唐代〕',c:'春物与愁客，遇时各有违。\n故花辞新枝，新泪落故衣。\n日暮两寂寞，飘然亦同归。'},
    {t:'春愁曲',a:'温庭筠〔唐代〕',c:'红丝穿露珠帘冷，百尺哑哑下纤绠。\n远翠愁山入卧屏，两重云母空烘影。\n凉簪坠发春眠重，玉兔煴香柳如梦。\n锦叠空床委堕红，飔飔扫尾双金凤。\n蜂喧蝶驻俱悠扬，柳拂赤阑纤草长。\n觉后梨花委平绿，春风和雨吹池塘。'},
    {t:'春初对暮雨',a:'温庭筠〔唐代〕',c:'淅沥生丛筱，空濛泫网轩。暝姿看远树，春意入尘根。\n点细飘风急，声轻入夜繁。雀喧争槿树，人静出蔬园。\n瓦湿光先起，房深影易昏。不应江上草，相与滞王孙。'},
    {t:'春词',a:'白居易〔唐代〕',c:'低花树映小妆楼，春入眉心两点愁。\n斜倚栏杆背鹦鹉，思量何事不回头。'},
    {t:'春词',a:'元稹〔唐代〕',c:'山翠湖光似欲流，蜂声鸟思却堪愁。\n西施颜色今何在，但看春风百草头。'},
    {t:'春堤曲',a:'张籍〔唐代〕',c:'野塘飞树头，绿蒲紫菱盖碧流。\n狂客谁家爱云水，日日独来城下游。'},
    {t:'春坊正字剑子歌',a:'李贺〔唐代〕',c:'先辈匣中三尺水，曾入吴潭斩龙子。\n隙月斜明刮露寒，练带平铺吹不起。\n蛟胎皮老蒺藜刺，鸊鹈淬花白鹇尾。\n直是荆轲一片心，莫教照见春坊字。\n挼丝团金悬簏簌，神光欲截蓝田玉。\n提出西方白帝惊，嗷嗷鬼母秋郊哭。'},
    {t:'春风',a:'王安石〔宋代〕',c:'一马春风北首燕，却疑身得旧山川。\n阳浮树外沧江水，尘涨原头野火烟。\n日借嫩黄初著柳，雨催新绿稍归田。\n回头不见辛夷发，始觉看花是去年。'},
    {t:'春风',a:'李商隐〔唐代〕',c:'春风虽自好，春物太昌昌。若教春有意，惟遣一枝芳。\n我意殊春意，先春已断肠。'},
    {t:'春风',a:'白居易〔唐代〕',c:'春风先发苑中梅，樱杏桃梨次第开。\n荠花榆荚深村里，亦道春风为我来。'},
    {t:'春宫曲',a:'王昌龄〔唐代〕',c:'昨夜风开露井桃，未央前殿月轮高。\n平阳歌舞新承宠，帘外春寒赐锦袍。'},
    {t:'春光戏题赠李侯',a:'岑参〔唐代〕',c:'燕雀始欲衔花来，君家种桃花未开。\n长安二月眼看尽，寄报春风早为催。'},
    {t:'春归',a:'杜甫〔唐代〕',c:'苔径临江竹，茅檐覆地花。\n别来频甲子，倏忽又春华。\n倚杖看孤石，倾壶就浅沙。\n远鸥浮水静，轻燕受风斜。\n世路虽多梗，吾生亦有涯。\n此身醒复醉，乘兴即为家。'},
    {t:'春怀',a:'杜牧〔唐代〕',c:'年光何太急，倏忽又青春。明月谁为主，江山暗换人。\n莺花潜运老，荣乐渐成尘。遥忆朱门柳，别离应更频。'},
    {t:'春怀故园',a:'柳宗元〔唐代〕',c:'九扈鸣已晚，楚乡农事春。悠悠故池水，空待灌园人。'},
    {t:'春怀引',a:'李贺〔唐代〕',c:'芳蹊密影成花洞，柳结浓烟花金重。\n蟾蜍碾玉挂明弓，捍拨装金打仙凤。\n宝枕垂云选春梦，钿合碧寒龙脑冻。\n阿侯系锦觅周郎，凭仗东风好相送。'},
    {t:'春晦饯陶七于江南同用风字',a:'陈子昂〔唐代〕',c:'黄鹤烟云去，青江琴酒同。离帆方楚越，沟水复西东。\n芙蓉生夏浦，杨柳送春风。明日相思处，应对菊花丛。'},
    {t:'春集越州皇甫秀才山亭',a:'孟郊〔唐代〕',c:'嘉宾在何处，置亭春山巅。顾余寂寞者，谬厕芳菲筵。\n视听日澄澈，声光坐连绵。晴湖泻峰嶂，翠浪多萍藓。\n何以逞高志，为君吟秋天。'},
    {t:'春江花月夜词',a:'温庭筠〔唐代〕',c:'玉树歌阑海云黑，花庭忽作青芜国。\n秦淮有水水无情，还向金陵漾春色。\n杨家二世安九重，不御华芝嫌六龙。\n百幅锦帆风力满，连天展尽金芙蓉。\n珠翠丁星复明灭，龙头劈浪哀笳发。\n千里涵空澄水魂，万枝破鼻飘香雪。\n漏转霞高沧海西，颇黎枕上闻天鸡。\n鸾弦代雁曲如语，一醉昏昏天下迷。\n四方倾动烟尘起，犹在浓香梦魂里。\n后主荒宫有晓莺，飞来只隔西江水。'},
    {t:'春江晚景',a:'张九龄〔唐代〕',c:'江林多秀发，云日复相鲜。\n征路那逢此，春心益渺然。\n兴来只自得，佳处莫能传。\n薄暮津亭下，余花满客船。'},
    {t:'春尽与友人入裴氏林探渔竿',a:'温庭筠〔唐代〕',c:'一径互纡直，茅棘亦已繁。晴阳入荒竹，暧暧和春园。\n倚杖息惭倦，徘徊恋微暄。历寻婵娟节，剪破苍筤根。\n地闭修茎孤，林振馀箨翻。适心在所好，非必寻湘沅。'},
    {t:'春近四绝句',a:'黄庭坚〔宋代〕',c:'闰后阳和腊里回，濛濛小雨暗楼台。\n柳条榆荚弄颜色，便恐入帘双燕来。\n亭台经雨压尘沙，春近登临意气佳。\n更喜轻寒勒成雪，未春先放一城花。\n小雪晴沙不作泥，疏帘红日弄朝晖。\n年华已伴梅梢晚，春色先从草际归。\n梅英欲尽香无赖，草色才苏绿未匀。\n苦竹空将岁寒节，又随官柳到青春。'},
    {t:'春景',a:'李白〔唐代〕',c:'门对鹤溪流水，云连雁宕仙家。\n谁解幽人幽意，惯看山鸟山花。'},
    {t:'春梦',a:'岑参〔唐代〕',c:'洞房昨夜春风起，故人尚隔湘江水。\n枕上片时春梦中，行尽江南数千里。'},
    {t:'春末题池州弄水亭',a:'杜牧〔唐代〕',c:'使君四十四，两佩左铜鱼。为吏非循吏，论书读底书。\n晚花红艳静，高树绿阴初。亭宇清无比，溪山画不如。\n嘉宾能啸咏，宫妓巧妆梳。逐日愁皆碎，随时醉有馀。\n偃须求五鼎，陶只爱吾庐。趣向人皆异，贤豪莫笑渠。'},
    {t:'春暮宴罢寄宋寿先辈',a:'温庭筠〔唐代〕',c:'斜掩朱门花外钟，晓莺时节好相逢。窗间桃蕊宿妆在，\n雨后牡丹春睡浓。苏小风姿迷下蔡，马卿才调似临邛。\n谁怜芳草生三径，参佐桥西陆士龙。'},
    {t:'春暖郡圃散策三首·其三',a:'杨万里〔宋代〕',c:'春禽处处讲新声，细草欣欣贺嫩晴。\n曲折遍穿花底路，莫令一步作虚行。'},
    {t:'春情',a:'孟浩然〔唐代〕',c:'青楼晓日珠帘映，红粉春妆宝镜催。\n已厌交欢怜枕席，相将游戏绕池台。\n坐时衣带萦纤草，行即裙裾扫落梅。\n更道明朝不当作，相期共斗管弦来。'},
    {t:'春晴',a:'王安石〔宋代〕',c:'新春十日雨，雨晴门始开。\n静看苍苔纹，莫上人衣来。'},
    {t:'春晴泛舟',a:'陆游〔宋代〕',c:'儿童莫笑是陈人，湖海春回发兴新。\n雷动风行惊蛰户，天开地辟转鸿钧。\n鳞鳞江色涨石黛，嫋嫋柳丝摇麴尘。\n欲上兰亭却回棹，笑谈终觉愧清真。'},
    {t:'春晴怀故园海棠二首',a:'杨万里〔宋代〕',c:'故园今日海棠开，梦入江西锦绣堆。\n万物皆春人独老，一年过社燕方回。\n似青似白天浓淡，欲堕还飞絮往来。\n无那风光餐不得，遣诗招入翠琼杯。\n竹边台榭水边亭，不要人随只独行。\n乍暖柳条无气力，淡晴花影不分明。\n一番过雨来幽径，无数新禽有喜声。\n只欠翠纱红映肉，两年寒食负先生。'},
    {t:'春日',a:'温庭筠〔唐代〕',c:'问君何所思，迢递艳阳时。\n门静燕归晚，墙高蝶过迟。\n一双青琐燕，千万绿杨丝。\n屏上吴山远，楼中朔管悲。\n宝书无寄处，香毂有来期。\n草色将林彩，相添入黛眉。'},
    {t:'春日',a:'秦观〔宋代〕',c:'残腊渺茫云外日，新春彷佛梦中来。\n雪霜便觉都无力，只见桃花次第开。'},
    {t:'春日',a:'王安石〔宋代〕',c:'柴门照水见青苔，春绕花枝漫漫开。\n路远游人行不到，日长啼鸟去还来。'},
    {t:'春日',a:'朱熹〔宋代〕',c:'胜日寻芳泗水滨，无边光景一时新。\n等闲识得东风面，万紫千红总是春。'},
    {t:'春日',a:'李商隐〔唐代〕',c:'欲入卢家白玉堂，新春催破舞衣裳。\n蝶衔红蕊蜂衔粉，共助青楼一日忙。'},
    {t:'春日·一作齐梁体',a:'温庭筠〔唐代〕',c:'柳岸杏花稀，梅梁乳燕飞。美人鸾镜笑，嘶马雁门归。\n楚宫云影薄，台城心赏违。从来千里恨，边色满戎衣。'},
    {t:'春日茶山病不饮酒，因呈宾客',a:'杜牧〔唐代〕',c:'笙歌登画船，十日清明前。山秀白云腻，溪光红粉鲜。\n欲开未开花，半阴半晴天。谁知病太守，犹得作茶仙。'},
    {t:'春日登金华观',a:'陈子昂〔唐代〕',c:'白玉仙台古，丹丘别望遥。山川乱云日，楼榭入烟霄。\n鹤舞千年树，虹飞百尺桥。还疑赤松子，天路坐相邀。'},
    {t:'春日独酌二首',a:'李白〔唐代〕',c:'东风扇淑气，水木荣春晖。\n白日照绿草，落花散且飞。\n孤云还空山，众鸟各已归。\n彼物皆有讬，吾生独无依。\n对此石上月，长歌醉芳菲。\n我有紫霞想，缅怀沧州间。\n且对一壶酒，澹然万事闲。\n横琴倚高松，把酒望远山。\n长空去鸟没，落日孤云还。\n但悲光景晚，宿昔成秋颜。'},
    {t:'春日访李十四处士',a:'温庭筠〔唐代〕',c:'花深桥转水潺潺，甪里先生自得关。看竹已知行处好，\n望云空得暂时闲。谁言有策堪经世，自是无钱可买山。\n一局残棋千点雨，绿萍池上暮方还。'},
    {t:'春日古道傍作',a:'杜牧〔唐代〕',c:'万古荣华旦暮齐，楼台春尽草萋萋。\n君看陌上何人墓，旋化红尘送马蹄。'},
    {t:'春日寄怀',a:'李商隐〔唐代〕',c:'世间荣落重逡巡，我独丘园坐酒春。\n纵使有花兼有月，可堪无酒又无人。\n青袍似草年年定，白发如丝日日新。\n欲逐风波千万里，未知何路到龙津。'},
    {t:'春日将欲东归寄新及第苗绅先辈',a:'温庭筠〔唐代〕',c:'几年辛苦与君同，得丧悲欢尽是空。\n犹喜故人先折桂，自怜羁客尚飘蓬。\n三春月照千山道，十日花开一夜风。\n知有杏园无路入，马前惆怅满枝红。'},
    {t:'春日绝句八首·其二',a:'陆游〔宋代〕',c:'二十四番花有信，一百七日食犹寒。\n眼中不是无春色，叹息衰翁自鲜欢。'},
    {t:'春日绝句八首·其一',a:'陆游〔宋代〕',c:'吏来屡败哦诗兴，雨作常妨载酒行。\n忽见家家插杨柳，始知今日是清明。'},
    {t:'春日留别·一作惜别',a:'张籍〔唐代〕',c:'游人欲别离，半醉对花枝。看著春又晚，莫轻少年时。\n临行记分处，回首是相思。各向天涯去，重来未可期。'},
    {t:'春日六绝句·其三',a:'杨万里〔宋代〕',c:'雾气因山见，波痕到岸消。\n诗人元自懒，物色故相撩。'},
    {t:'春日六绝句·其五',a:'杨万里〔宋代〕',c:'日落碧簪外，人行红雨中。\n幽人诗酒里，又是一春风。'},
    {t:'春日偶题呈上尚书丈丈',a:'秦观〔宋代〕',c:'三年京国鬓如丝，又见新花发故枝。\n日典春衣非为酒，家贫食粥已多时。'},
    {t:'春日偶作',a:'温庭筠〔唐代〕',c:'西园一曲艳阳歌，扰扰车尘负薜萝。\n自欲放怀犹未得，不知经世竟如何？\n夜闻猛雨判花尽，寒恋重衾觉梦多。\n钓渚别来应更好，春风还为起微波。'},
    {t:'春日偶作',a:'朱熹〔宋代〕',c:'闻道西园春色深，急穿芒屩去登临。千葩万蕊争红紫，谁识乾坤造化心。'},
    {t:'春日上方即事',a:'王维〔唐代〕',c:'好读高僧传，时看辟谷方。\n鸠形将刻仗，龟壳用支床。\n柳色春山映，梨花夕鸟藏。\n北窗桃李下，闲坐但焚香。'},
    {t:'春日退朝',a:'刘禹锡〔唐代〕',c:'紫陌夜来雨，南山朝下看。戟枝迎日动，阁影助松寒。\n瑞气转绡縠，游光泛波澜。御沟新柳色，处处拂归鞍。'},
    {t:'春日五首·其二',a:'秦观〔宋代〕',c:'一夕轻雷落万丝，霁光浮瓦碧参差。\n有情芍药含春泪，无力蔷薇卧晓枝。'},
    {t:'春日五首·其三',a:'秦观〔宋代〕',c:'裌衣新著倦琴书，散策池塘返照初。\n翠碧黄鹂相续去，荇丝深处见游鱼。'},
    {t:'春日五首·其四',a:'秦观〔宋代〕',c:'春禽叶底引圆吭，临罢黄庭日正长。\n满院柳花寒食后，旋钻新火爇炉香。'},
    {t:'春日五首·其五',a:'秦观〔宋代〕',c:'金屋旧题烦乙子，蜜脾新采赖蜂臣。\n蜻蜓蛱蝶无情思，随例颠忙过一春。'},
    {t:'春日五首·其一',a:'秦观〔宋代〕',c:'幅巾投晓入西园，春动林塘物物鲜。\n却憩小庭才日出，海棠花发麝香眠。'},
    {t:'春日言怀寄虢州李常侍十韵',a:'杜牧〔唐代〕',c:'岸藓生红药，岩泉涨碧塘。地分莲岳秀，草接鼎原芳。\n雨派潈漴急，风畦芷若香。织蓬眠舴艋，惊梦起鸳鸯。\n论吐开冰室，诗陈曝锦张。貂簪荆玉润，丹穴凤毛光。\n今日还珠守，何年执戟郎。且嫌游昼短，莫问积薪长。\n无计披清裁，唯持祝寿觞。愿公如卫武，百岁尚康强。'},
    {t:'春日野行',a:'温庭筠〔唐代〕',c:'雨涨西塘金堤斜，碧草芊芊晴吐芽。野岸明媚山芍药，\n水田叫噪官虾蟆。镜中有浪动菱蔓，陌上无风飘柳花。\n何事轻桡句溪客，绿萍方好不归家。'},
    {t:'春日忆李白',a:'杜甫〔唐代〕',c:'白也诗无敌，飘然思不群。\n清新庾开府，俊逸鲍参军。\n渭北春天树，江东日暮云。\n何时一樽酒，重与细论文。'},
    {t:'春日有感',a:'孟郊〔唐代〕',c:'雨滴草芽出，一日长一日。风吹柳线垂，一枝连一枝。\n独有愁人颜，经春如等闲。且持酒满杯，狂歌狂笑来。'},
    {t:'春日又送潘述之扬州',a:'皎然〔唐代〕',c:'别渚望邗城，岐路春日遍。柔风吹杨柳，芳景流郊甸。\n日日东林期，今夕异乡县。文房旷佳士，禅室阻清盼。\n离恨夺赏心，不得谐所愿。莫忆山中人，碧云遥可见。'},
    {t:'春日杂兴十首',a:'秦观〔宋代〕',c:'东方有美人，容华茂春粲。\n抱影守单栖，含睇理哀弹。\n声意一何切，所欢邈云汉。\n徒然事膏沐，孰与徂昏旦。\n微诚浪自持，嘉月忽复晏。\n巧转度虚棂，飞红触幽幔。\n岁岁芳草滋，夜夜明星烂。\n合并会有时，索居不必叹。'},
    {t:'春日直门下省早朝·时为右补阙',a:'王维〔唐代〕',c:'骑省直明光，鸡鸣谒建章。遥闻史中珮，闇识令君香。\n玉漏随铜史，天书拜夕郎。旌旗映阊阖，歌吹满昭阳。\n官舍梅初紫，宫门柳欲黄。愿将迟日意，同与圣恩长。'},
    {t:'春日杼山寄赠李员外纵',a:'皎然〔唐代〕',c:'南山唯与北山邻，古树连拳伴我身。黄鹤有心多不住，\n白云无事独相亲。闲持竹锡深看水，懒系麻衣出见人。\n欲掇幽芳聊赠远，郎官那赏石门春。'},
    {t:'春日醉起言志',a:'李白〔唐代〕',c:'处世若大梦，胡为劳其生？\n所以终日醉，颓然卧前楹。\n觉来眄庭前，一鸟花间鸣。\n借问此何时？春风语流莺。\n感之欲叹息，对酒还自倾。\n浩歌待明月，曲尽已忘情。'},
    {t:'春申君',a:'杜牧〔唐代〕',c:'烈士思酬国士恩，春申谁与快冤魂。\n三千宾客总珠履，欲使何人杀李园。'},
    {t:'春水曲',a:'张籍〔唐代〕',c:'鸭鸭，觜唼唼。青蒲生，春水狭。荡漾木兰船，\n中有双少年。少年醉，鸭不起。'},
    {t:'春思',a:'杜牧〔唐代〕',c:'岂君心的的，嗟我泪涓涓。绵羽啼来久，锦鳞书未传。\n兽垆凝冷焰，罗幕蔽晴烟。自是求佳梦，何须讶昼眠。'},
    {t:'春思',a:'李白〔唐代〕',c:'燕草如碧丝，秦桑低绿枝。\n当君怀归日，是妾断肠时。\n春风不相识，何事入罗帏。'},
    {t:'春思',a:'韦应物〔唐代〕',c:'野花如雪绕江城，坐见年芳忆帝京。\n阊阖晓开凝碧树，曾陪鸳鹭听流莺。'},
    {t:'春宿左省',a:'杜甫〔唐代〕',c:'花隐掖垣暮，啾啾栖鸟过。\n星临万户动，月傍九霄多。\n不寝听金钥，因风想玉珂。\n明朝有封事，数问夜如何。'},
    {t:'春题湖上',a:'白居易〔唐代〕',c:'湖上春来似画图，乱峰围绕水平铺。\n松排山面千重翠，月点波心一颗珠。\n碧毯线头抽早稻，青罗裙带展新蒲。\n未能抛得杭州去，一半勾留是此湖。'},
    {t:'春帖子',a:'周邦彦〔宋代〕',c:'鸾辂青旂殿阁宽，祠官奠璧下春坛。晓开鱼钥朝衣集，綵胜飘扬百辟冠。'},
    {t:'春望',a:'杜甫〔唐代〕',c:'国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。'},
    {t:'春宵',a:'苏轼〔宋代〕',c:'春宵一刻值千金，花有清香月有阴。\n歌管楼台声细细，秋千院落夜沉沉。'},
    {t:'春宵燕万年吉少府中孚南馆',a:'韦应物〔唐代〕',c:'始见斗柄回，复兹霜月霁。河汉彦纵横，春城夜迢递。\n宾筵接时彦，乐燕凌芳岁。稍爱清觞满，仰叹高文丽。\n欲去返郊扉，端为一欢滞。'},
    {t:'春宵自遣',a:'李商隐〔唐代〕',c:'地胜遗尘事，身闲念岁华。\n晚晴风过竹，深夜月当花。\n石乱知泉咽，苔荒任径斜。\n陶然恃琴酒，忘却在山家。'},
    {t:'春晓',a:'元稹〔唐代〕',c:'半欲天明半未明，醉闻花气睡闻莺。\n猧儿撼起钟声动，二十年前晓寺情。'},
    {t:'春晓',a:'孟浩然〔唐代〕',c:'春眠不觉晓，处处闻啼鸟。\n夜来风雨声，花落知多少。'},
    {t:'春晓曲',a:'温庭筠〔唐代〕',c:'家临长信往来道，乳燕双双拂烟草。\n油壁车轻金犊肥，流苏帐晓春鸡早。\n笼中娇鸟暖犹睡，帘外落花闲不扫。\n衰桃一树近前池，似惜红颜镜中老。'},
    {t:'春晓三首·其三',a:'杨万里〔宋代〕',c:'一年生活是三春，二月春光尽十分。\n不必开窗索花笑，隔窗花影也欣欣。'},
    {t:'春兴戏题赠李侯',a:'岑参〔唐代〕',c:'黄雀始欲衔花来，君家种桃花未开。\n长安二月眼看尽，寄报春风早为催。'},
    {t:'春雪',a:'韩愈〔唐代〕',c:'看雪乘清旦，无人坐独谣。\n拂花扇尚起，落地暖初销。\n已讶陵歌扇，还来伴舞腰。\n洒篁留密节，著度送长条。\n入镜鸾窥沼，行天马度桥。\n遍阶怜可掬，满树戏成摇。\n江浪迎涛日，风毛纵猎朝。\n弄闲时细转，争急忽惊飘。\n城险疑悬布，砧寒未捣绡。\n莫愁阴景促，夜色自相饶。'},
    {t:'春雪间早梅',a:'韩愈〔唐代〕',c:'梅将雪共春，彩艳不相因。逐吹座争密，排枝巧妒新。\n谁令香满座，独使净无尘。芳意饶呈瑞，寒来助照人。\n玲珑开已遍，点缀坐来频。那是俱疑似，须知两逼真。\n荧煌初乱眼，浩荡忽迷神。未许琼华比，从将玉树亲。\n先期迎献岁，更伴占兹晨。愿得长辉映，轻微敢自珍。'},
    {t:'春寻河阳陶处士别业',a:'岑参〔唐代〕',c:'风暖日暾暾，黄鹂飞近村。花明潘子县，柳暗陶公门。\n药碗摇山影，鱼竿带水痕。南桥车马客，何事苦喧喧。'},
    {t:'春野行·杂言',a:'温庭筠〔唐代〕',c:'草浅浅，春如剪。花压李娘愁，饥丸欲成茧。\n东城年少气堂堂，金丸惊起双鸳鸯。含羞更问卫公子，\n月到枕前春梦长。'},
    {t:'春夜别友人二首·其二',a:'陈子昂〔唐代〕',c:'紫塞白云断，青春明月初。\n对此芳樽夜，离忧怅有馀。\n清冷花露满，滴沥檐宇虚。\n怀君欲何赠，愿上大臣书。'},
    {t:'春夜别友人二首·其一',a:'陈子昂〔唐代〕',c:'银烛吐青烟，金樽对绮筵。\n离堂思琴瑟，别路绕山川。\n明月隐高树，长河没晓天。\n悠悠洛阳道，此会在何年。'},
    {t:'春夜赋得漉水囊歌，送郑明府',a:'皎然〔唐代〕',c:'吴缣楚练何白皙，居士持来遗禅客。禅客能裁漉水囊，\n不用衣工秉刀尺。先师遗我式无缺，一滤一翻心敢赊。\n夕望东峰思漱盥，曨曨斜月悬灯纱。徙倚花前漏初断，\n白猿争啸惊禅伴。玉瓶徐泻赏涓涓，溅著莲衣水珠满。\n因识仁人为宦情，还如漉水爱苍生。聊歌一曲与君别，\n莫忘寒泉见底清。'},
    {t:'春夜集陆处士居玩月',a:'皎然〔唐代〕',c:'欲赏芳菲肯待辰，忘情人访有情人。\n西林可是无清景，只为忘情不记春。'},
    {t:'春夜洛城闻笛',a:'李白〔唐代〕',c:'谁家玉笛暗飞声，散入春风满洛城。\n此夜曲中闻折柳，何人不起故园情。'},
    {t:'春夜喜雨',a:'杜甫〔唐代〕',c:'好雨知时节，当春乃发生。\n随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。\n晓看红湿处，花重锦官城。'},
    {t:'春夜宴从弟桃花园序',a:'李白〔唐代〕',c:'夫天地者，万物之逆旅也；光阴者，百代之过客也。而浮生若梦，为欢几何？古人秉烛夜游，良有以也。况阳春召我以烟景，大块假我以文章。会桃花之芳园，序天伦之乐事。群季俊秀，皆为惠连；吾人咏歌，独惭康乐。幽赏未已，高谈转清。开琼筵以坐花，飞羽觞而醉月。不有佳咏，何伸雅怀？如诗不成，罚依金谷酒数。'},
    {t:'春夜忆萧子真',a:'孟郊〔唐代〕',c:'半夜不成寐，灯尽又无月。独向阶前立，子规啼不歇。\n况我有金兰，忽尔为胡越。争得明镜中，久长无白发。'},
    {t:'春夜竹亭赠钱少府归蓝田',a:'王维〔唐代〕',c:'夜静群动息，时闻隔林犬。\n却忆山中时，人家涧西远。\n羡君明发去，采蕨轻轩冕。'},
    {t:'春意',a:'孟浩然〔唐代〕',c:'佳人能画眉，妆罢出帘帷。\n照水空自爱，折花将遗谁。\n春情多艳逸，春意倍相思。\n愁心极杨柳，一种乱如丝。'},
    {t:'春阴',a:'晏殊〔宋代〕',c:'十二重环閟洞房，愔愔危树俯回塘。\n风迷戏蜨间无绪，露裛幽花冷自香。\n绮席醉吟销桂酌，玉台愁作涩银簧。\n梅青麦绿江城路，更与登高望楚乡。'},
    {t:'春阴',a:'黄庭坚〔宋代〕',c:'竹笋初生黄犊角，蕨芽已作小儿拳。\n试寻野菜炊春饭，便是江南二月天。'},
    {t:'春游',a:'元稹〔唐代〕',c:'酒户年年减，山行渐渐难。欲终心懒慢，转恐兴阑散。\n镜水波犹冷，稽峰雪尚残。不能辜物色，乍可怯春寒。\n远目伤千里，新年思万端。无人知此意，闲凭小栏干。'},
    {t:'春游',a:'李商隐〔唐代〕',c:'桥峻斑骓疾，川长白鸟高。烟轻惟润柳，风滥欲吹桃。\n徙倚三层阁，摩挲七宝刀。庾郎年最少，青草妒春袍。'},
    {t:'春游',a:'杨万里〔宋代〕',c:'不知春向雨中回，只到春光未苦来。\n老子今晨偶然出，李花全落杏花开。'},
    {t:'春游',a:'陆游〔宋代〕',c:'沈家园里花如锦，半是当年识放翁。\n也信美人终作土，不堪幽梦太匆匆。'},
    {t:'春游南亭',a:'韦应物〔唐代〕',c:'川明气已变，岩寒云尚拥。\n南亭草心绿，春塘泉脉动。\n景煦听禽响，雨余看柳重。\n逍遥池馆华，益愧专城宠。'},
    {t:'春有情篇',a:'刘禹锡〔唐代〕',c:'为问游春侣，春情何处寻。花含欲语意，草有斗生心。\n雨频催发色，云轻不作阴。纵令无月夜，芳兴暗中深。'},
    {t:'春雨',a:'李商隐〔唐代〕',c:'怅卧新春白袷衣，白门寥落意灯违。\n红楼隔雨相望冷，珠箔飘灯独自归。\n远路应悲春晼晚，残宵犹得梦依稀。\n玉珰缄札何由达，万里云罗一雁飞。'},
    {t:'春雨',a:'周邦彦〔宋代〕',c:'耕人扶耒语林丘，花外时时落一鸥。\n欲验春来多少雨，野塘漫水可回舟。'},
    {t:'春雨后',a:'孟郊〔唐代〕',c:'昨夜一霎雨，天意苏群物。\n何物最先知，虚庭草争出。'},
    {t:'春雨四首',a:'陆游〔宋代〕',c:'片片红梅落，纤纤绿草生。\n无端夜来雨，又碍出门行。\n春阴易成雨，客病不禁寒。\n又与梅花别，无因一倚栏。\n胸怀阮步兵，诗句谢宣城。\n今夕俱参透，焚香听雨声。\n疏点空阶雨，长明古殿灯。\n庐山岑寂夜，我是定中僧。'},
    {t:'春遇南使，贻赵知音',a:'岑参〔唐代〕',c:'端居春心醉，襟背思树萱。美人在南州，为尔歌北门。\n北风吹烟物，戴胜鸣中园。枯杨长新条，芳草滋旧根。\n网丝结宝琴，尘埃被空樽。适遇江海信，聊与南客论。'},
    {t:'春园即事',a:'王维〔唐代〕',c:'宿雨乘轻屐，春寒著弊袍。\n开畦分白水，间柳发红桃。\n草际成棋局，林端举桔槔。\n还持鹿皮几，日暮隐蓬蒿。'},
    {t:'春远',a:'杜甫〔唐代〕',c:'肃肃花絮晚，菲菲红素轻。\n日长唯鸟雀，春远独柴荆。\n数有关中乱，何曾剑外清。\n故乡归不得，地入亚夫营。'},
    {t:'春怨',a:'李白〔唐代〕',c:'白马金羁辽海东，罗帷绣被卧春风。\n落月低轩窥烛尽，飞花入户笑床空。'},
    {t:'春月观省属城，始憩东西林精舍',a:'韦应物〔唐代〕',c:'因时省风俗，布惠迨高年。建隼出浔阳，整驾游山川。\n白云敛晴壑，群峰列遥天。嶔崎石门状，杳霭香炉烟。\n榛荒屡罥挂，逼侧殆覆颠。方臻释氏庐，时物屡华妍。\n昙远昔经始，于兹閟幽玄。东西竹林寺，灌注寒涧泉。\n人事既云泯，岁月复已绵。殿宇馀丹绀，磴阁峭欹悬。\n佳士亦栖息，善身绝尘缘。今我蒙朝寄，教化敷里鄽。\n道妙苟为得，出处理无偏。心当同所尚，迹岂辞缠牵。'},
    {t:'春早得雨',a:'陆游〔宋代〕',c:'稻陂方渴雨，蚕箔却忧寒。\n更有难知处，朱门惜牡丹。'},
    {t:'春中田园作',a:'王维〔唐代〕',c:'屋上春鸠鸣，村边杏花白。\n持斧伐远扬，荷锄觇泉脉。\n归燕识故巢，旧人看新历。\n临觞忽不御，惆怅远行客。'},
    {t:'春中喜王九相寻',a:'孟浩然〔唐代〕',c:'二月湖水清，家家春鸟鸣。\n林花扫更落，径草踏还生。\n酒伴来相命，开尊共解酲。\n当杯已入手，歌妓莫停声。'},
    {t:'春中忆元二',a:'韦应物〔唐代〕',c:'雨歇万井春，柔条已含绿。徘徊洛阳陌，惆怅杜陵曲。\n游丝正高下，啼鸟还断续。有酒今不同，思君莹如玉。'},
    {t:'春洲曲',a:'温庭筠〔唐代〕',c:'韶光染色如蛾翠，绿湿红鲜水容媚。\n苏小慵多兰渚闲，融融浦日鵁鶄寐。\n紫骝蹀躞金衔嘶，堤上扬鞭烟草迷。\n门外平桥连柳堤，归来晚树黄莺啼。'},
    {t:'春昼',a:'李贺〔唐代〕',c:'朱城报春更漏转，光风催兰吹小殿。\n草细堪梳，柳长如线。\n卷衣秦帝，扫粉赵燕。\n日含画幕，蜂上罗荐。\n平阳花坞，河阳花县。\n越妇支机，吴蚕作茧。\n菱汀系带，荷塘倚扇。\n江南有情，塞北无限。'},
    {t:'淳于王歌',a:'佚名〔隋代〕',c:'肃肃河中育，育熟须含黄。独坐空房中，思我百媚郎。'},
    {t:'龊龊',a:'韩愈〔唐代〕',c:'龊龊当世士，所忧在饥寒。\n但见贱者悲，不闻贵者叹。\n大贤事业异，远抱非俗观。\n报国心皎洁，念时涕汍澜。\n妖姬坐左右，柔指发哀弹。\n酒肴虽日陈，感激宁为欢。\n秋阴欺白日，泥潦不少干。\n河堤决东郡，老弱随惊湍。\n天意固有属，谁能诘其端。\n愿辱太守荐，得充谏诤官。\n排云叫阊阖，披腹呈琅玕。\n致君岂无术？自进诚独难。'},
    {t:'词笑令·①王昭君',a:'秦观〔宋代〕',c:'诗曰：汉宫选女适单于。明妃敛袂登毡车。玉容寂寞花无主，顾影低回泣路隅。行行渐入阴山路。目送征鸿入云去。独抱琵琶恨更深，汉宫不见空回顾。\n回顾。汉宫路。杆拨檀槽鸾对舞。玉容寂寞花无主。顾影偷弹玉箸。未央宫殿知何处。目送征鸿南去。'},
    {t:'词笑令·②乐昌公主',a:'秦观〔宋代〕',c:'诗曰：金陵往昔帝王州。乐昌主第最风流。一朝隋兵到江上，共抱凄凄去国愁。越公万骑鸣箫鼓。剑拥玉人天上去。空携破镜望江尘，千古江枫笼辇路。\n辇路。江枫古。楼上吹箫人在否。菱花半璧香尘污。往日繁华何处。旧欢新爱谁是主。啼笑两难分付。'},
    {t:'词笑令·③崔徽',a:'秦观〔宋代〕',c:'诗曰：蒲中有女号崔徽。轻似南山翡翠儿。使君当日最宠爱，坐中对客常拥持。一见裴郎心似醉。夜解罗衣与门吏。西门寺里乐未央，乐府至今歌翡翠。\n翡翠。好容止。谁使庸奴轻点缀。裴郎一见心如醉。笑里偷传深意。罗衣中夜与门吏。暗结城西幽会。'},
    {t:'词笑令·④无双',a:'秦观〔宋代〕',c:'诗曰：尚书有女名无双。蛾眉如母学新妆。姊家仙客最明后，舅母惟只呼王郎。尚书往日先曾二。数载睽违今复遇。闻说襄王二十年，当时未必轻相慕。\n相慕。无双女。当日尚书先曾二。王郎明俊神仙侣。肠断别离情苦。数年睽恨今复遇。笑指襄江归去。'},
    {t:'词笑令·⑥盼盼',a:'秦观〔宋代〕',c:'诗曰：百尺楼高燕子飞。楼上美人颦翠眉。将军一去音容远，只有年年旧燕归。春风昨夜来深院。春色依然人不见。只余明月照孤眠，唯望旧恩空恋恋。\n恋恋。楼中燕。燕子楼空春色晚。将军一去音容远。空锁楼中深怨。春风重到人不见。十二阑干倚遍。'},
    {t:'词笑令·⑧采莲',a:'秦观〔宋代〕',c:'诗曰：若耶溪边天气秋。采莲女儿溪岸头。笑隔荷花共人语，烟波渺渺荡轻舟。数声水调红娇晚。棹转舟回笑人远。肠断谁家游冶郎，尽日踟蹰临柳岸。\n柳岸。水清浅。笑折荷花呼女伴。盈盈日照新妆面。水调空传幽怨。扁舟日暮笑声远。对此令人肠断。'},
    {t:'词笑令·⑨烟中怨',a:'秦观〔宋代〕',c:'诗曰：鉴湖楼阁与云齐。楼上女儿名阿溪。十五能为绮丽句，平生未解出幽闺。谢郎巧思诗裁翦。能使佳人动幽怨。琼枝璧月结芳期，斗帐双双成眷恋。\n眷恋。西湖岸。湖面楼台侵云汉。阿溪本是飞琼伴。风月朱扉斜掩。谢郎巧思诗裁翦。能动芳怀幽怨。'},
    {t:'词笑令·灼灼',a:'秦观〔宋代〕',c:'诗曰：锦城春暖花欲飞。灼灼当庭舞柘枝。相君上客河东秀，自言那复旁人知。妾愿身为梁上燕。朝朝暮暮长相见。云收月堕海沈沈，泪满红绡寄肠断。\n肠断。绣帘卷。妾愿身为梁上燕。朝朝暮暮长相见。莫遣恩迁情变。红绡粉泪知何限。万古空传遗怨。'},
    {t:'祠风师酬提刑赵学士见贻',a:'范仲淹〔宋代〕',c:'先王製礼经，祠为国大事。\n孟春祭风师，刺史敢有二。\n斋戒升于坛，拜手首至地。\n所祈动以时，生物得咸遂。\n勿鼓江海涛，害我舟楫利。\n旱天六七月，会有雷雨至。\n慎无吹散去，坐使百穀悴。\n高秋三五夕，明月生天际。\n乃可驱云烟，以喜万人意。\n愿君入薰弦，上副吾皇志。\n阜财复解愠，即为天下赐。\n八使重古礼，作诗歌祭义。\n诚欲通神明，非徒奖州吏。\n贤哉推此心，良以警有位。'},
    {t:'祠洛水歌',a:'佚名〔隋代〕',c:'洛阳之水，其色苍苍。祠祭大泽，倏忽南临。洛滨醊祷，色连三光。'},
    {t:'祠紫盖山经玉泉山寺',a:'张九龄〔唐代〕',c:'指途跻楚望，策马傍荆岑。稍稍松篁入，泠泠涧谷深。\n观奇逐幽映，历险忘岖嶔。上界投佛影，中天扬梵音。\n焚香忏在昔，礼足誓来今。灵异若有对，神仙真可寻。\n高僧闻逝者，远俗是初心。藓驳经行处，猿啼燕坐林。\n归真已寂灭，留迹岂湮沉。法地自兹广，何云千万金。'},
    {t:'辞唱歌',a:'韩愈〔唐代〕',c:'抑逼教唱歌，不解看艳词。坐中妇酒人，岂有欢乐姿。\n幸有伶者妇，腰身如柳枝。但令送君酒，如逶如憨痴。\n声自肉中出，使人能逶随。复遣悭吝者，赠金不皱眉。\n岂有长直夫，喉中声雌雌。君心岂无耻，君岂是女儿。\n君教发直言，大声无休时。君教哭古恨，不肯复吞悲。\n乍可阻君意，艳歌难可为。'},
    {t:'慈恩伽蓝清会',a:'韦应物〔唐代〕',c:'素友俱薄世，屡招清景赏。鸣钟悟音闻，宿昔心已往。\n重门相洞达，高宇亦遐朗。岚岭晓城分，清阴夏条长。\n氲氛芳台馥，萧散竹池广。平荷随波泛，回飙激林响。\n蔬食遵道侣，泊怀遗滞想。何彼尘昏人，区区在天壤。'},
    {t:'慈恩精舍南池作',a:'韦应物〔唐代〕',c:'清境岂云远，炎氛忽如遗。重门浅绿阴，菡萏满广池。\n石发散清浅，林光动涟漪。缘崖摘紫房，扣槛集灵龟。\n浥浥馀露气，馥馥幽襟披。积喧忻物旷，耽玩觉景驰。\n明晨复趋府，幽赏当反思。'},
    {t:'慈湖夹阻风',a:'苏轼〔宋代〕',c:'捍索桅竿立啸空，篙师酣寝浪花中。\n故应菅蒯知心腹，弱缆能争万里风。\n此生归路愈茫然，无数青山水拍天。\n犹有小船来卖饼，喜闻墟落在山前。\n我行都是退之诗，真有人家水半扉。\n千顷桑麻在船底，空余石发挂鱼衣。\n日轮亭午汗珠融，谁识南讹长养功。\n暴雨过云聊一快，未妨明月却当空。\n卧看落月横千丈，起唤清风得半帆。\n且并水村欹侧过，人间何处不巉岩。'},
    {t:'慈鸡',a:'佚名〔近现代〕',c:'盛家畜二母鸡，黄白各一，桑麻掩映，分棚而栖，各饲数雏。晨夕引雏出入，二雌并行，宛若人之洽比其邻者。一日，黄者为人所窃，失母之雏，悲鸣不已。白者频来相顾，若代为悯恻。然白后得食相呼，归栖逐队，盖亡形于黄白，而视如己出。鸡虽微禽，而于五德之外，复具一德。盛君之友因呼之为“慈鸡”。'},
    {t:'慈姥竹',a:'李白〔唐代〕',c:'野竹攒石生，含烟映江岛。\n翠色落波深，虚声带寒早。\n龙吟曾未听，凤曲吹应好。\n不学蒲柳凋，贞心尝自保。'},
    {t:'慈乌夜啼',a:'白居易〔唐代〕',c:'慈乌失其母，哑哑吐哀音。\n昼夜不飞去，经年守故林。\n夜夜夜半啼，闻者为沾襟。\n声中如告诉，未尽反哺心。\n百鸟岂无母，尔独哀怨深。\n应是母慈重，使尔悲不任。\n昔有吴起者，母殁丧不临。\n嗟哉斯徒辈，其心不如禽。\n慈乌复慈乌，鸟中之曾参。'},
    {t:'次卜掌书落成白鹿佳句',a:'朱熹〔宋代〕',c:'重营旧馆喜初成，要共群贤听鹿鸣。三爵何妨奠蘋藻，一编讵敢议明诚。\n深源定自闲中得，妙用元从乐处生。莫问无穷庵外事，此心聊与此山盟。'},
    {t:'次圭父观鱼韵',a:'朱熹〔宋代〕',c:'平生三伏断追游，谁唤来穿涧树幽。初讶网横天影破，忽惊人蹴浪花浮。\n鸣榔不用齐吴榜，鼓枻何须学楚讴。便有金盘堆白雪，却怜清泚向东流。'},
    {t:'次刘秀野蔬食十三诗韵其九萝卜',a:'朱熹〔宋代〕',c:'纷敷剪翠丛，津润擢玉本。寂寞病文园，吟馀得深龈。'},
    {t:'次刘彦集木犀韵三首其三',a:'朱熹〔宋代〕',c:'秋到寒岩桂树丛，小山吟罢思悲翁。不妨更作淹留计，占取人间十里风。'},
    {t:'次鹿鸣宴诗',a:'文天祥〔宋代〕',c:'礼乐皇皇使者行，光华分似及门英。\n贞元虎榜虽联捷，司隶龙门幸缀名。\n二宋高科犹易事，两苏清节乃真荣。\n囊书自负应如此，肯逊当年祢正平。'},
    {t:'次吕季克东堂九咏其六月台',a:'朱熹〔宋代〕',c:'台上无人伴苦吟，归鸦过尽日西沉。须臾玉匣开尘镜，却有孤光共此心。'},
    {t:'次吕季克东堂九咏其五爱莲',a:'朱熹〔宋代〕',c:'闻道移根玉井旁，开花十丈是寻常。月明露冷无人见，独为先生引兴长。'},
    {t:'次彭应之餐雪韵',a:'朱熹〔宋代〕',c:'雪水瀹清茗，自谓绝世清。终然馀烟火，况复劳煎烹。\n岂如午霁馀，探此竹外楹。柘浆发甘和，宝盌凝寒晶。\n心胸既清凉，齿颊亦锵鸣。吞腥期永谢，饮玉希长生。'},
    {t:'次日',a:'皎然〔唐代〕',c:'野外有一人，独立无四邻。彼见是我身，我见是彼身。'},
    {t:'次日醉归',a:'杨万里〔宋代〕',c:'日晚颇欲归，主人苦见留。\n我非不能饮，老病怯觥筹。\n人意不可违，欲去且复休。\n我醉彼自止，醉亦何足愁。\n归路意昏昏，落日在岭陬。\n竹里有人家，欲憩聊一投。\n有叟喜我至，呼我为君侯。\n告以我非是，俛笑仍掉头。\n机心久巳尽，犹有不下鸥。\n田父亦外我，我老谁与游。'},
    {t:'次汝中寄河南陈赞府',a:'王昌龄〔唐代〕',c:'汝山方联延，伊水才明灭。遥见入楚云，又此空馆月。\n纷然驰梦想，不谓远离别。京邑多欢娱，衡湘暂沿越。\n明湖春草遍，秋桂白花发。岂惟长思君，日夕在魏阙。'},
    {t:'次山行佳句呈秀野丈三首其一',a:'朱熹〔宋代〕',c:'几日春阴锁翠岩，忽惊飞盖度晴岚。身轻似起烟霞痼，意适宁论禄位贪。\n句法旧超常语六，年华今富达尊三。从容笑语无馀事，兴在南山更向南。'},
    {t:'次同冠峡',a:'韩愈〔唐代〕',c:'今日是何朝，天晴物色饶。\n落英千尺堕，游丝百丈飘。\n泄乳交岩脉，悬流揭浪标。\n无心思岭北，猿鸟莫相撩。'},
    {t:'次潼关先寄张十二阁老使君',a:'韩愈〔唐代〕',c:'荆山已去华山来，日出潼关四扇开。\n刺史莫辞迎候远，相公亲破蔡州回。'},
    {t:'次秀野咏雪韵三首其三',a:'朱熹〔宋代〕',c:'开门惊怪雪交加，乱落横飞讵有涯。密竹不妨呈劲节，早梅何处觅残花。\n山阴客子须乘兴，洛下先生想卧家。病废杯觞寒至骨，哦诗无复更豪誇。'},
    {t:'次秀野韵五首其四',a:'朱熹〔宋代〕',c:'知君久矣厌喧卑，造物尊前唤小儿。一釂未应峨侧弁，十分聊尔快翻卮。\n治中寂寂凝尘日，令尹忧劳退食时。正好相寻发孤笑，莫教牢落负心期。'},
    {t:'次秀野杂诗韵槟榔',a:'朱熹〔宋代〕',c:'忆昔南游日，初尝面发红。药囊知有用，茗盌讵能同。\n蠲疾收殊效，修真录异功。三彭如不避，糜烂七非中。'},
    {t:'次秀野杂诗韵导引',a:'朱熹〔宋代〕',c:'闻说牛刀久不更，闲中应接羡门生。向来已悟藏千界，今日何劳倒五行。\n按蹻有时聊戏剧，居心无物转虚明。举觞试问同亭侣，九转工夫早晚成。'},
    {t:'次秀野杂诗韵其二',a:'朱熹〔宋代〕',c:'一篑工夫莫坐谈，便教庭际涌霞岩。眼中水石今成趣，物外烟霞旧所耽。\n泉细寒声生夜壑，香销暝霭变晴岚。儿童也识幽栖地，共指南山更近南。'},
    {t:'次秀野种粟韵',a:'朱熹〔宋代〕',c:'阿香一笑走丰隆，雨遍平畴万子中。\n旧喜樊迟知学圃，今看许子快论功。\n遥怜郁郁翻秋陇，预想垂垂弄晚风。\n珍重诗翁且彊健，东阡南陌兴无穷。'},
    {t:'次旬父韵',a:'朱熹〔宋代〕',c:'五字何人寄，锵鸣满袖金。剧知多暇日，谁与共幽寻。\n簿领淹穷海，莺花绕故林。功名终好在，且莫负初心。'},
    {t:'次元明韵寄子由',a:'黄庭坚〔宋代〕',c:'半世交亲随逝水，几人图画入凌烟？\n春风春雨花经眼，江北江南水拍天。\n欲解铜章行问道，定知石友许忘年。\n脊令各有思归恨，日月相催雪满颠。'},
    {t:'次韵伯氏寄赠盖郎中喜学老杜诗',a:'黄庭坚〔宋代〕',c:'老杜文章擅一家，国风纯正不欹斜。\n帝阍悠邈开关键，虎穴深沈探爪牙。\n千古是非存史笔，百年忠义寄江花。\n潜知有意升堂室，独抱遗编校舛差。'},
    {t:'次韵伯氏长芦寺下',a:'黄庭坚〔宋代〕',c:'风从落帆休，天与大江平。\n僧坊昼亦静，钟磬寒逾清。\n淹留属暇日，植杖数连甍。\n颇与幽子逢，煮茗当酒倾。\n携手霜木末，朱栏见潮生。\n樯移永正县，鸟度建康城。\n薪者得树鸡，羹盂味南烹。\n香秔炊白玉，饱饭愧闲行。\n丛祠思归乐，吟弄夕阳明。\n思归诚独乐，薇蕨渐春荣。'},
    {t:'次韵蔡子骏琼花',a:'秦观〔宋代〕',c:'无双亭上传觞处，最惜人归月上时。\n相见异乡心欲绝，可怜花与月应知。'},
    {t:'次韵参寥三首',a:'秦观〔宋代〕',c:'且折花枝醉复醒，人间时节易峥嵘。\n屠龙肯自羞无用，画虎从人笑不成。'},
    {t:'次韵参寥莘老',a:'秦观〔宋代〕',c:'迅风薄高林，万象号虎豹。\n纷披颓与棘，尔复鼓狂闹。\n我垣既已颓，我栋又以挠。\n岂无一木枝，横鱼难与较。\n黎明忽自罢，晴日射鱼罩。\n死水失狂澜，衰木回故貌。\n劳生真梦事，往趋如睡觉。\n炊黍焚黄鹑，吾其理归棹。'},
    {t:'次韵昌叔咏尘',a:'王安石〔宋代〕',c:'尘土轻扬不自持，纷纷生物更间吹。\n翻成地上万烟雾，散在人间要路岐。\n一世竞驰甘睬目，几家清坐得轩眉。\n超然只有江湖上，还见波涛恐我时。'},
    {t:'次韵陈休斋怀古堂',a:'朱熹〔宋代〕',c:'平昔尘编里，心期本自幽。那堪旧泉石，更作此追游。\n好句看犹在，遗忠怆已休。亦知今日意，不逐大江流。'},
    {t:'次韵冲卿除日立春',a:'王安石〔宋代〕',c:'犹残一日腊，并见两年春。\n物以终为始，人从故得新。\n迎阳朝翦彩，守岁夜倾银。\n恩赐随嘉节，无功只自尘。'},
    {t:'次韵答米元章',a:'秦观〔宋代〕',c:'嗜好清无滓，周旋粲有文。\n挥毫春在手，岸帻海生云。\n花鸟空撩我，莼鲈正属君。\n惟应读雌蜺，差不愧王筠。'},
    {t:'次韵答王四',a:'黄庭坚〔宋代〕',c:'病懒百事废，不惟书问疏。\n新诗苦招唤，是日锁直庐。\n潢污深一尺，大道覆行车。\n晴夜遥相似，秋堂对望舒。'},
    {t:'次韵答张文潜中见寄',a:'秦观〔宋代〕',c:'与君涉世网，所得如钩温。\n念昔相乖离，俯仰变寒暄。\n把袂安可期，寄书嘱加餐。\n三年汝水滨，孤怀谁与言。\n末路非所望，联镳金马门。\n校文多豫暇，玄谈到羲轩。\n孰云笭箵小，史书垂後昆。\n匪惟以旧闻，抵牾良可刊。\n比枉病中作，笔端淮海奔。\n亟驾问所苦，兀坐一室闲。\n晤对不知夕，归途斗星翻。\n平时带十围，颇复减臂环。\n君其专精神，微恙不足论。\n恺悌神所劳，此理直如弦。'},
    {t:'次韵德孺惠贶秋字之句',a:'黄庭坚〔宋代〕',c:'少日才华接贵游，老来忠义气砂秋。\n未应白发如霜草，不见丹砂似箭头。\n顾我今成丧家狗，期君早作济川舟。\n汉家宗庙英灵在，定是寒儒浪自愁。'},
    {t:'次韵法芝举旧诗',a:'苏轼〔宋代〕',c:'春来何处不归鸿，非复羸牛踏旧踪。\n但愿老师真似月，谁家瓮里不相逢。'},
    {t:'次韵盖郎中率郭郎中休官二首',a:'黄庭坚〔宋代〕',c:'世态已更千变尽，心源不受一鹂侵。\n青春白日无公事，紫燕黄鹂俱好音。\n付与儿孙知伏腊，听教鱼鸟逐飞沈。\n黄公垆下曾知味，定是逃禅入少林。'},
    {t:'次韵公辟会流觞亭',a:'秦观〔宋代〕',c:'偷引湖光一派飞，咏觞还却似当时。\n吴歌送酒随流急，越艳浮花转曲池。\n山庙早因前守彻，冰盘元是故工遗。\n年年褉饮今非昔，不到兰亭到北池。'},
    {t:'次韵公辟会蓬莱阁',a:'秦观〔宋代〕',c:'林声摵摵动秋风，共蹑丹梯上镇龙。\n路隔西陵三两水，门临南镇一千峰。\n湖吞碧落诗争发，塔涌青冥画几重。\n非是登高能赋客，可怜猿鹤自相容。'},
    {t:'次韵和参政陈给事寒食杜门感怀',a:'晏殊〔宋代〕',c:'谢堂新句入清歌，雨箔风帘有燕过。\n未免芳辰叹心赏，始知犹患陆才多。'},
    {t:'次韵和甫咏雪',a:'王安石〔宋代〕',c:'奔走风云四面来，坐看山垄玉枯嵬。\n平治险秽非无德，润泽焦枯是有才。\n势合便疑包地尽，功成终欲放春回。\n寒乡不念丰年瑞，只忆青天万里开。'},
    {t:'次韵和刘夔判官对雪',a:'范仲淹〔宋代〕',c:'蔌蔌楼台外，新辉溢四遐。\n云中凋玉叶，星际落榆花。\n岳色参差露，松声彷佛加。\n风流裁赋苑，清苦读书家。\n霜女惭轻格，蟾娥让素华。\n孤鸿迷鸟道，万马忆龙沙。\n净拂王恭氅，香滋陆羽茶。\n载歌劳郢谢，一奏待种牙。\n几处和梅赏，何人为鬓嗟。\n含毫看不足，诗社好生涯。'},
    {t:'次韵和史馆吕相公九日偶成',a:'晏殊〔宋代〕',c:'凤阙千门制不奢，上公精意在朝家。重阳蜜饵承班诏，西苑璆樽辍泛花。\n萧相未央功已半，汉皇宣室宴非赊。由来位极妨行乐，目断黄垆酒旆斜。'},
    {t:'次韵和台源诸篇九首之云涛石',a:'黄庭坚〔宋代〕',c:'造物成形妙画工，地形咫尺远横空。\n蛟鼍出没三万顷，云雨纵横十二峰。\n清坐使人无俗气，闲来当暑起清风。\n诸山落木萧萧夜，醉梦江湖一叶中。'},
    {t:'次韵和王校勘中秋月',a:'晏殊〔宋代〕',c:'广寒仙署惬心期，秋半梧台木赋稀。\n有客正吟星北共，何人重赋鹊南飞。\n光含绮席传三雅，影逗兰房撤九微。\n趋府逸才过鲍掾，不辞终夕赏清晖。'},
    {t:'次韵和致仕陈相公除夜',a:'晏殊〔宋代〕',c:'從来岁除咏，托讽情非一。\n公在维师年，久谐归政逸。\n辛盘具芳郁，柏酒澄嘉栗。\n犹厌贺车烦，晨门效圭荜。'},
    {t:'次韵黄斌老所画横竹',a:'黄庭坚〔宋代〕',c:'酒浇胸次不能平，吐出苍竹岁君嵘。\n卧龙偃蹇雷不惊，公与此君俱忘形。\n晴窗影落石泓处，松煤浅染饱霜兔。\n中安三石使屈蟠，亦恐形全便飞去。'},
    {t:'次韵梨花',a:'黄庭坚〔宋代〕',c:'桃花人面各相红，不及天然玉作容。\n总向风尘尘莫染，轻轻笼月倚墙东。'},
    {t:'次韵刘景文登郑王台见思五首',a:'黄庭坚〔宋代〕',c:'公诗如美色，未嫁已倾城。\n嫁作荡子妇，寒机泣到明。\n绿琴蛛网徧，弦绝不成声。\n想见鸱夷子，江湖万里情。'},
    {t:'次韵柳通叟寄王文通',a:'黄庭坚〔宋代〕',c:'故人昔有凌云赋，何意陆沉黄绶间。\n头白眼花行作吏，儿婚女嫁望还山。\n心犹未死杯中物，春不能朱镜里颜。\n寄语诸公肯湔祓，割鸡令得近乡关。'},
    {t:'次韵罗正之惠绵扇',a:'秦观〔宋代〕',c:'吴扇新翻制素绵，名郎持赠意俱圆。\n有人充户修明月，无女乘鸾向紫烟。\n供奉宜升清暑殿，动摇合作御风仙。\n谁知挥却青蝇辈，功在春蚕一觉眠。'},
    {t:'次韵裴仲谟和何先辈二首',a:'秦观〔宋代〕',c:'汝南古郡寡参寻，兀兀长如鹤在阴。\n支枕星河棋醉後，入帘风絮报春深。\n青山未落诗人手，白发谁知国士心。\n多谢名郎传绿绮，愧无佳句比南金。'},
    {t:'次韵裴仲谋同年',a:'黄庭坚〔宋代〕',c:'交盖春风汝水边，客床相对卧僧毡。\n舞阳去叶才百里，贱子与公皆少年。\n白发齐生如有种，青山好去坐无钱。\n烟沙篁竹江南岸，输与鸬鹚取次眠。'},
    {t:'次韵平甫金山会宿寄亲友',a:'王安石〔宋代〕',c:'天末海门横北固，烟中沙岸似西兴。\n已无船舫犹闻笛，远有楼台只见灯。\n山月入松金破碎，江风吹水雪崩腾。\n飘然欲作乘桴计，一到扶桑恨未能。'},
    {t:'次韵任君官舍秋雨',a:'黄庭坚〔宋代〕',c:'墙根戢戢数蜗牛，雨长垣衣亭更幽。\n惊起归鸿不成字，辞柯落叶最知秋。\n菊花莫恨开时晚，谷穟犹思晴后收。\n独立搔头人不解，南山用取一樽酬。'},
    {t:'次韵赏梅',a:'黄庭坚〔宋代〕',c:'安知宋玉在邻墙，笑立春晴照不光。\n淡薄似能知我意，幽闲元不为人芳。\n微风拂掠生春思，小雨廉纤洗暗妆。\n只恐浓葩委泥土，谁令解合返魂香。'},
    {t:'次韵四十叔父白鹿之作',a:'朱熹〔宋代〕',c:'诛茅结屋想前贤，千载遗踪尚宛然。故作轩窗挹苍翠，要将弦诵答潺湲。\n诸郎有志须精学，老子无能但欲眠。多少个中名教乐，莫谈空谛莫求仙。'},
    {t:'次韵宋懋宗僦居甘泉坊雪後书怀',a:'黄庭坚〔宋代〕',c:'汉家太史宋公孙，漫逐班行谒帝阍。\n燕颔封侯空有相，蛾眉倾国自难昏。\n家徒四壁书侵坐，马瘦三山叶拥门。\n安得风帆随雪水，江南石上对洼尊。'},
    {t:'次韵太守向公登楼眺望二首',a:'秦观〔宋代〕',c:'茫茫汝水抱城根，野色偷春入宇痕。\n千点湘妃枝上泪，一声杜宇水边魂。\n遥怜鸿隙陂穿路，尚尽元和贼负恩。\n粉堞女墙都已尽，恍如陶侃梦天门。\n庖烟起处认孤村，天色清寒不见痕。\n车辋湖边梅溅泪，壶公祠畔月销魂。\n封疆尽是春秋国，庙食多怀将相恩。\n试问李斯长叹后，谁牵黄犬出东门。'},
    {t:'次韵题平父兄重建一枝堂',a:'朱熹〔宋代〕',c:'画戟朱门枕碧山，貂蝉元自出儒冠。更馀此日林间乐，远继当年膝下欢。\n命驾宾朋千里近，放怀琴酒百忧宽。遗编却好传孙子，莫遣因循学宴安。'},
    {t:'次韵王定国扬州见寄',a:'黄庭坚〔宋代〕',c:'清洛思君昼夜流，北归何日片云收。\n未生白发犹堪酒，垂上青云却佐州。\n飞雪堆盘鱠鱼腹，明珠论斗煮鸡头。\n平生行乐自不恶，岂有竹西歌吹愁。'},
    {t:'次韵王荆公题西太乙宫壁二首',a:'黄庭坚〔宋代〕',c:'风急啼乌未了，雨来战蚁方酣。\n真是真非安在？人间北看成南。\n晚风池莲香度，晓日宫槐影西。\n白下长干梦到，青门紫曲尘迷。'},
    {t:'次韵谢借观五老图',a:'晏殊〔宋代〕',c:'道明回诏乐清间，便向中朝脱冕冠。\n百日秉枢登相府，千年青史表旌桓。\n泰运正隆嫌气热，干网初整畏冰寒。\n逍遥唱和多高致，仪象霜风俾后看。'},
    {t:'次韵雪后书事二首',a:'朱熹〔宋代〕',c:'惆怅江头几树梅，杖藜行绕去还来。\n前时雪压无寻处，昨夜月明依旧开。\n折寄遥怜人似玉，相思应恨劫成灰。\n沉吟日落寒鸦起，却望柴荆独自回。\n满山残雪对虚堂，想似当年辋口庄。\n门掩不须垂铁锁，客来聊复共藜床。\n故人闻道歌围暖，妙语空传醉墨香。\n莫为姬姜厌憔悴，把酒论文话偏长。'},
    {t:'次韵雪后书事二首其一',a:'朱熹〔宋代〕',c:'晴烟袅袅弄晨炊，雪屋流澌未觉迟。拟挈冻醪追胜践，聊穿蜡屐过疏篱。\n扫开折竹仍三径，认得残梅祇数枝。不耐岁寒心事苦，滔滔欲说定从谁。'},
    {t:'次韵择之见路傍乱草有感',a:'朱熹〔宋代〕',c:'世间无处不阳春，道路何曾困得人。若向此中生厌斁，不知何处可安身。'},
    {t:'次韵张秘校喜雪三首',a:'黄庭坚〔宋代〕',c:'满城楼观玉阑干，小雪晴时不共寒。\n润到竹根肥腊笋，暖开蔬甲助春盘。\n眼前多事观游少，胸次无忧酒量宽。\n闻说压沙梨己动，会须鞭马蹋泥看。'},
    {t:'次韵张询斋中晚春',a:'黄庭坚〔宋代〕',c:'学古编简残，怀人江湖永。\n非无车马客，心远境亦静。\n挽蔬夜雨畦，煮茗寒泉井。\n春去不窥园，黄鹂颇三请。\n立朝无物望，补外傥天幸。\n想乘沧浪船，濯发曦翠岭。'},
    {t:'次韵中玉水仙花二首·其二',a:'黄庭坚〔宋代〕',c:'淤泥解作白莲藕，粪壤能开黄玉花。\n可惜国香天不管，随缘流落小民家。'},
    {t:'次韵中玉水仙花二首·其一',a:'黄庭坚〔宋代〕',c:'借水开花自一奇，水沉为骨玉为肌。\n暗香已压酴醾倒，只比寒梅无好枝。'},
    {t:'次韵周朝宗六月十日泛湖',a:'周邦彦〔宋代〕',c:'君才切玉刀，一举成两段。\n我如抟沙砾，放手辄星散。\n传闻紫贝阙，薜荔充帷幔。\n楚吟尚多亡，君诗补其半。'},
    {t:'次韵周朝宗六月十日泛湖其二',a:'周邦彦〔宋代〕',c:'风舟挽犹迟，兀若乘款段。深行蛟龙国，飐荡光炯散。\n洲凉扇荷箑，山晚垂云幔。眷言江海期，百年行欲半。'},
    {t:'次韵周朝宗六月十日泛湖其三',a:'周邦彦〔宋代〕',c:'沟塍绕湖干，琐细分顷段。湖洄晚渔集，山静村樵散。\n冲风偃萑菼，猎猎如捲幔。何当饮清光，乘月行夜半。'},
    {t:'次韵周朝宗六月十日泛湖其四',a:'周邦彦〔宋代〕',c:'维舟瞰层波，未忍分练段。人间好风味，鱼鸟同聚散。\n儒生长窘束，书灯守幽幔。逐乐嗟已迟，蚤还犹及半。'},
    {t:'次韵周朝宗六月十日泛湖其一',a:'周邦彦〔宋代〕',c:'霖潦合支流，洲浦迷片段。两桨入菰蒲，凫鸥欻惊散。\n疏林直炊烟，落日斜酒幔。王事得淹留，公私各相半。'},
    {t:'次韵子由召伯埭见别三首其一',a:'秦观〔宋代〕',c:'孤蓬短榜溯河流，无赖寒侵紫绮裘。召伯埭南春欲尽，为公重赋畔牢愁。'},
    {t:'次韵子瞻题郭熙画秋山',a:'黄庭坚〔宋代〕',c:'黄州逐客未赐环，江南江北饱在山。\n玉堂卧对郭熙画，发兴已在青林间。\n郭熙官画但荒远，短明曲折开秋晚。\n江村烟外雨脚明，归雁行边余叠巘。\n坐思黄柑洞庭霜，恨身不如雁随阳。\n熙今头白有眼力，尚能弄笔映窗光。\n画取江南好风日，慰此将老镜中发。\n但熙肯画宽作程，十日五日一水石。'},
    {t:'次韵子瞻赠金山宝觉大师',a:'秦观〔宋代〕',c:'云峰一变隔炎凉，犹喜重来饭际香。\n宿鸟水干迎晓闹，乱帆天际受风忙。\n青鞋踏雨寻幽径，朱火笼纱语上方。\n珍重故人敦妙契，自怜身世两微茫。'},
    {t:'次祝泽之表兄韵',a:'朱熹〔宋代〕',c:'裸裎相向但悠悠，信道乾坤日病浮。此去安心知有法，向来示病不难瘳。\n优游静室闲窗底，放浪东阡南陌头。万事何由到怀抱，夕阳芳草自春秋。'},
    {t:'次子有闻捷韵四首其三',a:'朱熹〔宋代〕',c:'孤臣残疾卧空林，不奈忧时一寸心。谁遣捷书来荜户，真同百蛰听雷音。'},
    {t:'刺巴郡守诗',a:'佚名〔两汉〕',c:'狗吠何喧喧，有吏来在门。\n披衣期门应，府记欲得钱。\n语穷乞请期，吏怒反见尤。\n旋步顾家中，家中无可为。\n思往从邻贷，邻人言已匮。\n钱钱何难得，令我独憔悴。'},
    {t:'从陈季张求竹竿引水入厨',a:'黄庭坚〔宋代〕',c:'井边分水过寒厅，斩竹南溪仗峡生。\n来酿百壶春酒味，怒流三峡夜泉声。\n能令官舍庖厨洁，未减君家风月清。\n挥斧直须轻放手，却愁食实凤凰惊。'},
    {t:'从崔中丞过卢少尹郊居',a:'柳宗元〔唐代〕',c:'寓居湘岸四无邻，世网难婴每自珍。\n莳药闲庭延国老，开樽虚室值贤人。\n泉回浅石依高柳，径转垂藤闲绿筠。\n闻道偏为五禽戏，出门鸥鸟更相亲。'},
    {t:'从军行',a:'王维〔唐代〕',c:'吹角动行人。\n喧喧行人起。\n笳悲马嘶乱。\n争渡金河水。\n日暮沙漠陲。\n战声烟尘里。\n尽系名王颈。\n归来献天子。'},
    {t:'从军行',a:'李白〔唐代〕',c:'从军玉门道，逐虏金微山。\n笛奏梅花曲，刀开明月环。\n鼓声鸣海上，兵气拥云间。\n愿斩单于首，长驱静铁关。'},
    {t:'从军行·吹角动行人',a:'王维〔唐代〕',c:'吹角动行人，喧喧行人起。\n笳悲马嘶乱，争渡黄河水。\n日暮沙漠陲，战声烟尘里。\n尽系名王颈，归来报天子。'},
    {t:'从军行二首',a:'王昌龄〔唐代〕',c:'向夕临大荒，朔风轸归虑。\n平沙原里馀，飞鸟宿何处。\n虏骑猎长原，翩翩傍河去。\n边声摇白草，海霜生黄雾。\n百战苦风尘，十年履霜露。\n虽投定远笔，未坐将军树。\n早知行路难，悔不理章句。\n秋草马蹄轻，角弓持弦急。\n去为龙城战，正值胡兵袭。\n军霜横大荒，战酣日将入。\n长风金鼓动，白露铁衣湿。\n四起愁边声，南庭时伫立。\n断蓬孤自转，寒雁飞相及。\n原里云沙涨，平原冰霰涩。\n惟闻汉使还，独向刀环泣。'},
    {t:'从军行二首·其二',a:'李白〔唐代〕',c:'百战沙场碎铁衣，城南已合数重围。\n突营射杀呼延将，独领残兵千骑归。'},
    {t:'从军行二首·其一',a:'王昌龄〔唐代〕',c:'大将军出战，白日暗榆关。\n三面黄金甲，单于破胆还。'},
    {t:'从军行七首·其二',a:'王昌龄〔唐代〕',c:'琵琶起舞换新声，总是关山旧别情。\n撩乱边愁听不尽，高高秋月照长城。'},
    {t:'从军行七首·其四',a:'王昌龄〔唐代〕',c:'青海长云暗雪山，孤城遥望玉门关。\n黄沙百战穿金甲，不破楼兰终不还。'},
    {t:'从军行七首·其五',a:'王昌龄〔唐代〕',c:'大漠风尘日色昏，红旗半卷出辕门。\n前军夜战洮河北，已报生擒吐谷浑。'},
    {t:'从岐王过杨氏别业应教',a:'王维〔唐代〕',c:'杨子谈经所，淮王载酒过。\n兴阑啼鸟换，坐久落花多。\n径转回银烛，林开散玉珂。\n严城时未启，前路拥笙歌。'},
    {t:'从岐王夜宴卫家山池应教',a:'王维〔唐代〕',c:'座客香貂满，宫娃绮幔张。\n涧花轻粉色，山月少灯光。\n积翠纱窗暗，飞泉绣户凉。\n还将歌舞出，归路莫愁长。'},
    {t:'从仕',a:'韩愈〔唐代〕',c:'居闲食不足，从仕力难任。两事皆害性，一生恒苦心。\n黄昏归私室，惆怅起叹音。弃置人间世，古来非独今。'},
    {t:'促促词',a:'张籍〔唐代〕',c:'促促复促促，家贫夫妇欢不足。江年为人送租船，\n去年捕鱼在江边。家中姑老子复小，自执吴绡输税钱。\n家家桑麻满地黑，念君一身空努力。\n愿教牛蹄团团羊角直，君身常在应不得。'},
    {t:'促漏',a:'李商隐〔唐代〕',c:'促漏遥钟动静闻，报章重叠杳炉分。舞鸾镜匣收残黛，\n睡鸭香炉换夕熏。归去定知还向月，梦来何处更为云。\n南塘渐暖蒲堪结，两两鸳鸯护水纹。'},
    {t:'促拍满路花·露颗添花色',a:'秦观〔宋代〕',c:'露颗添花色，月彩投窗隙。春思青中酒，恨无力。洞房咫尺，曾寄青鸾翼。云散无踪迹。罗帐熏残，熏回无处寻觅。\n轻红腻白，步步熏兰泽。约腕金环重，宜装饰。未知安否，一向无消息。不似寻常忆。忆后教人，片时存济不得。'},
    {t:'促拍满路花·香靥融春雪',a:'柳永〔宋代〕',c:'香靥融春雪，翠鬓亸秋烟。楚腰纤细正笄年。凤帏夜短，偏爱日高眠。起来贪颠耍，只恁残却黛眉，不整花钿。\n有时携手闲坐，偎倚绿窗前。温柔情态尽人怜。画堂春过，悄悄落花天。最是娇痴处，尤殢檀郎，未教拆了秋千。'},
    {t:'促拍满路花仙吕思情',a:'周邦彦〔宋代〕',c:'帘烘泪雨乾，酒压愁城破。冰壶新饮渴，培残火。朱消粉退，绝胜新梳裹。不是寒宵短，日上三竿，章人犹要同卧。\n如今多病，寂寞章台左。黄昏风弄雪，门深锁。兰房密爱，万种思量过。也须知有我。著甚情悰，你但忘了人呵。'},
    {t:'促织',a:'杜甫〔唐代〕',c:'促织甚微细，哀音何动人。\n草根吟不稳，床下夜相亲。\n久客得无泪，放妻难及晨。\n悲丝与急管，感激异天真。'},
    {t:'窜夜郎于乌江留别宗十六璟',a:'李白〔唐代〕',c:'君家全盛日，台鼎何陆离！\n斩鳌顾娲皇，炼石补天维。\n一回日月顾，三入凤凰池。\n失势青门傍，种路复几时？\n犹会众宾客，三千光路岐。\n皇恩雪愤懑，松柏含荣滋。\n我非东床人，令姊忝齐眉。\n浪迹未出世，空名动京师。\n适遭云罗解，翻谪夜郎悲。\n拙妻莫邪剑，及此二龙随。\n惭君湍波苦，千里远从之。\n白帝晓猿断，黄牛过客迟。\n遥瞻明月峡，西去益相思。'},
    {t:'崔徽歌并序',a:'元稹〔唐代〕',c:'崔徽，河中府娼也。裴敬中以兴中幕使蒲州，与徽相从累月。敬中便还，崔以不得从为恨，因而真疾。有丘夏善写人形，徽托写真寄敬中曰：“崔徽一旦不及画中人，且为郎死。”发狂卒。\n崔徽本不是娼家，教歌按舞娼家长。\n使君知有不自由，坐在头时立在掌。\n有客有客名丘夏，善写仪容得艳姿。\n为徽持此寄敬中，以死报郎为终始。'},
    {t:'崔明府宅夜观妓',a:'孟浩然〔唐代〕',c:'白日既云暮，朱颜亦已酡。画堂初点烛，金幌半垂罗。\n长袖平阳曲，新声子夜歌。从来惯留客，兹夕为谁多。'},
    {t:'崔濮阳兄季重前山兴',a:'王维〔唐代〕',c:'秋色有佳兴，况君池上闲。\n悠悠色林下，自识门前山。\n千里横黛色，数峰出云间。\n嵯峨对秦国，合沓藏荆关。\n残雨斜日照，夕岚飞鸟还。\n故人今尚尔，叹息此颓颜。'},
    {t:'崔司录宅燕大理李卿',a:'高适〔唐代〕',c:'多雨殊未已，秋云更沉沉。洛阳故人初解印，\n山东小吏来相寻。上卿才大名不朽，早朝至尊暮求友。\n豁达常推海内贤，殷勤但酌尊中酒。饮醉欲言归剡溪，\n门前驷马光照衣。路傍观者徒唧唧，我公不以为是非。'},
    {t:'崔兴宗写真咏',a:'王维〔唐代〕',c:'画君年少时，如今君已老。\n今时新识人，知君旧时好。'},
    {t:'崔镇驿',a:'文天祥〔宋代〕',c:'万里中原役，北风天正凉。\n黄沙漫道路，苍耳满衣裳。\n野阔人声小，日斜驹影长。\n解鞍身似梦，游子意茫茫。'},
    {t:'翠玉楼',a:'文天祥〔宋代〕',c:'昏鸦何处落，野渡少人行。\n黄叶声在地，青山影入城。\n江湖行客梦，风雨故乡情。\n试问南来信，梅花三两英。'},
    {t:'村居',a:'岑参〔唐代〕',c:'夹岸人家临镜，孤邨灯火悬星。\n乔木千枝鹭下，深潭百尺龙吟。'},
    {t:'村居初夏五首·其四',a:'陆游〔宋代〕',c:'天遣为农老故乡，山园三亩镜湖傍。\n嫩莎经雨如秧绿，小蝶穿花似茧黄。\n斗酒只鸡人笑乐，十风五雨岁丰穰。\n相逢但喜桑麻长，欲话穷通已两忘。'},
    {t:'村居初夏五首·其一',a:'陆游〔宋代〕',c:'暮境难禁日月催，腊醅初见拆泥开。\n压车麦穗黄云卷，食叶蚕声白雨来。\n薄饭蕨薇端可饱，短衫纻葛亦新裁。\n宦涂自古多忧畏，白首为农信乐哉！'},
    {t:'村居苦寒',a:'白居易〔唐代〕',c:'八年十二月，五日雪纷纷。\n竹柏间冻死，况彼无衣民。\n回观村闾间，十室八九贫。\n北风利如剑，布待不蔽身。\n唯烧蒿棘火，愁坐夜待晨。\n乃知大寒岁，农者尤苦辛。\n顾我当此日，草堂深掩门。\n褐裘覆絁被，坐卧有馀温。\n幸免饥冻苦，又无垄亩勤。\n念彼深可愧，自问是何人。'},
    {t:'村居书喜',a:'陆游〔宋代〕',c:'红桥梅市晓山横，白塔樊江春水生。\n花气袭人知骤暖，鹊声穿树喜新晴。\n坊场酒贱贫犹醉，原野泥深老亦耕。\n最喜先期官赋足，经年无吏叩柴荆。'},
    {t:'村舍燕',a:'杜牧〔唐代〕',c:'汉宫一百四十五，多下珠帘闭琐窗。\n何处营巢夏将半，茅檐烟里语双双。'},
    {t:'村行',a:'杜牧〔唐代〕',c:'春半南阳西，柔桑过村坞。\n娉娉垂柳风，点点回塘雨。\n蓑唱牧牛儿，篱窥茜裙女。\n半湿解征衫，主人馈鸡黍。'},
    {t:'村雪夜坐',a:'白居易〔唐代〕',c:'南窗背灯坐，风霰暗纷纷。\n寂寞深村夜，残雁雪中闻。'},
    {t:'村夜',a:'白居易〔唐代〕',c:'霜草苍苍虫切切，村南村北行人绝。\n独出前门望野田，月明荞麦花如雪。'},
    {t:'存殁口号二首',a:'杜甫〔唐代〕',c:'席谦不见近弹棋，毕曜仍传旧小诗。\n玉局他年无限笑，白杨今日几人悲。\n郑公粉绘随长夜，曹霸丹青已白头。\n天下何曾有山水，人间不解重骅骝。'},
    {t:'达摩支曲',a:'温庭筠〔唐代〕',c:'捣麝成尘香不灭，拗莲作寸丝难绝。\n红泪文姬洛水春，白头苏武天山雪。\n君不见无愁高纬花漫漫，漳浦宴馀清露寒。\n一旦臣僚共囚虏，欲吹羌管先汍澜。\n旧臣头鬓霜华早，可惜雄心醉中老。\n万古春归梦不归，邺城风雨连天草。'},
    {t:'达士',a:'孟郊〔唐代〕',c:'四时如逝水，百川皆东波。青春化不还，白发镊更多。\n达人识元化，变愁为高歌。倾产取一醉，富者奈贫何。\n君看土中宅，富贵无偏颇。'},
    {t:'答白杭州郡楼登望画图见寄',a:'张籍〔唐代〕',c:'画得江城登望处，寄来今日到人安。\n乍惊物色从诗出，更想工人下手难。\n将展书堂偏觉好，每来朝客尽求看。\n见君向此闲吟意，肯恨当时作外官。'},
    {t:'答白刑部闻新蝉',a:'刘禹锡〔唐代〕',c:'蝉声未发前，已自感流年。一入凄凉耳，如闻断续弦。\n晴清依露叶，晚急畏霞天。何事秋卿咏，逢时亦悄然。'},
    {t:'答曾存之',a:'秦观〔宋代〕',c:'环堵萧然汝水隈，孤怀炯炯向谁开。\n青春不觉书边过，白发无端镜上来。\n祭灶请邻聊复尔，卖刀买犊岂难哉。\n故人休说封侯事，归钓江天有旧台。'},
    {t:'答陈拾遗赠竹簪',a:'张九龄〔唐代〕',c:'与君尝此志，因物复知心。遗我龙钟节，非无玳瑁簪。\n幽素宜相重，雕华岂所任。为君安首饰，怀此代兼金。'},
    {t:'答道素上人别',a:'皎然〔唐代〕',c:'春色遍远道，寂寞闽中行。碧水何渺渺，白云亦英英。\n离人不可望，日暮芳洲情。黄鹤有逸翮，翘首白云倾。\n欲为山中侣，肯秘辽天声。蓝缕真子褐，葳蕤近臣缨。\n以兹夺尔怀，常恐道不成。吾门弟子中，不减惠休名。\n一性研已远，五言功更精。从君汗漫游，莫废学无生。\n忍草肯摇落，禅枝不枯荣。采采慰长路，知吾心不轻。\n幻情有去住，真性无离别。留取老桂枝，归来共攀折。'},
    {t:'答东林道士',a:'韦应物〔唐代〕',c:'紫阁西边第几峰，茅斋夜雪虎行踪。\n遥看黛色知何处，欲出山门寻暮钟。'},
    {t:'答豆卢次方',a:'皎然〔唐代〕',c:'吾爱道交论，为高贵世名。昔称气桑令，今闻豆卢生。\n彼生清淮气，独钟文中彩。近作公宴诗，如坐何柳在。\n吾用古人耳，采君四坐珍。贤士胜朝晖，温温无冬春。\n朝晖烁我肌，贤士清我神。微尔与云鹄，幽怀何由申。\n别来秋风至，独坐楚山碧。高月当清冥，禅心正寂历。\n增波徒相骇，人远情不隔。有书遗琼什，以代貂襜褕。\n风教凌越绝，声名掩吴趋。悬璧安可酬，徙倚还踟蹰。'},
    {t:'答豆卢居士春夜游东园见怀',a:'皎然〔唐代〕',c:'春意赏不足，承夕步东园。事表精虑远，月中华木繁。\n开襟寄清景，遐想属空门。安得纚芳屣，看君幽径萱。'},
    {t:'答端',a:'韦应物〔唐代〕',c:'郊园夏雨歇，闲院绿阴生。\n职事方无效，幽赏独违情。\n物色坐如见，离抱怅多盈。\n况感夕凉气，闻此乱蝉鸣。'},
    {t:'答龚深之',a:'秦观〔宋代〕',c:'深巷茅檐日渐长，卧看花鸟竞家阳。\n惜无好事携樽酒，赖有邻家振烛光。\n尚友颇存书万卷，封侯正阙木千章。\n错刀锦段相仍至，小子都忘进取狂。'},
    {t:'答郭郎中',a:'孟郊〔唐代〕',c:'松柏死不变，千年色青青。\n志士贫更坚，守道无异营。\n每弹潇湘瑟，独抱风波声。\n中有失意吟，知者泪满缨。\n何以报知者，永存坚与贞。'},
    {t:'答韩使同在边',a:'陈子昂〔唐代〕',c:'汉家失中策，胡马屡南驱。闻诏古边使，曾是故人谟。\n废书怅怀古，负剑许良图。出关岁方晏，乘塞日多虞。\n虏入白登道，烽交紫塞途。连兵屯北地，清野备东胡。\n边城方晏闭，斥堠始昭苏。复闻韩长孺，辛苦事匈奴。\n雨雪颜容改，纵横才位孤。空怀老臣策，未获赵军租。\n但蒙魏侯重，不受谤书诬。当取金人祭，还歌凯入都。'},
    {t:'答韩愈、李观别，因献张徐州',a:'孟郊〔唐代〕',c:'富别愁在颜，贫别愁销骨。懒磨旧铜镜，畏见新白发。\n古树春无花，子规啼有血。离弦不堪听，一听四五绝。\n世途非一险，俗虑有千结。有客步大方，驱车独迷辙。\n故人韩与李，逸翰双皎洁。哀我摧折归，赠词纵横设。\n徐方国东枢，元戎天下杰。祢生投刺游，王粲吟诗谒。\n高情无遗照，朗抱开晓月。有土不埋冤，有仇皆为雪。\n愿为直草木，永向君地列。愿为古琴瑟，永向君听发。\n欲识丈夫心，曾将孤剑说。'},
    {t:'答胡处士',a:'皎然〔唐代〕',c:'西山禅隐比来闻，长道唯应我与君。\n书上无名心忘却，人间聚散似浮云。'},
    {t:'答黄叔张',a:'朱熹〔宋代〕',c:'日君趋玉陛，抗疏肃邦刑。便有荣褒衮，无劳涕伏青。\n众流争靡靡，一柱独亭亭。只恐追锋急，那容昼掩扃。'},
    {t:'答开州韦使君寄车前子',a:'张籍〔唐代〕',c:'开州午日车前子，作药人皆道有神。\n惭愧使君怜病眼，三千馀里寄闲人。'},
    {t:'答库部韩郎中',a:'韦应物〔唐代〕',c:'高士不羁世，颇将荣辱齐。适委华冕去，欲还幽林栖。\n虽怀承明恋，忻与物累暌。逍遥观运流，谁复识端倪。\n而我岂高致，偃息平门西。愚者世所遗，沮溺共耕犁。\n风雪积深夜，园田掩荒蹊。幸蒙相思札，款曲期见携。'},
    {t:'答乐天临都驿见赠',a:'刘禹锡〔唐代〕',c:'北固山边波浪，东都城里风尘。\n世事不同心事，新人何似故人。'},
    {t:'答李浣·林中观易罢',a:'韦应物〔唐代〕',c:'林中观易罢，溪上对鸥闲。\n楚俗饶词客，何人最往还。'},
    {t:'答李浣三首',a:'韦应物〔唐代〕',c:'孤客逢春暮，缄情寄旧游。\n海隅人使远，书到洛阳秋。\n马卿犹有壁，渔父自无家。\n想子今何处，扁舟隐荻花。\n林中观易罢，溪上对鸥闲。\n楚俗饶辞客，何人最往还。'},
    {t:'答李季兰',a:'皎然〔唐代〕',c:'天女来相试，将花欲染衣。\n禅心竟不起，还捧旧花归。'},
    {t:'答李侍御问',a:'皎然〔唐代〕',c:'入道曾经离乱前，长干古寺住多年。爱贫唯制莲花足，\n取性闲书树叶篇。自笑不归看石榜，谁高无事弄苔泉。\n身外空名何足问，吾心已出第三禅。'},
    {t:'答李员外小榼味',a:'孟郊〔唐代〕',c:'一拳芙蓉水，倾玉何泠泠。仙情夙已高，诗味今更馨。\n试啜月入骨，再衔愁尽醒。荷君道古诚，使我善飞翎。'},
    {t:'答刘连州邦字',a:'柳宗元〔唐代〕',c:'连璧本难双，分符刺小邦。崩云下漓水，劈箭上浔江。\n负弩啼寒狖，鸣枹惊夜狵。遥怜郡山好，谢守但临窗。'},
    {t:'答刘明府',a:'张籍〔唐代〕',c:'身病多时又客居，满城亲旧尽相疏。\n可怜绛县刘明府，犹解频频寄远书。'},
    {t:'答柳子厚',a:'刘禹锡〔唐代〕',c:'年方伯玉早，恨比四愁多。会待休车骑，相随出罻罗。'},
    {t:'答陆澧',a:'张九龄〔唐代〕',c:'松叶堪为酒，春来酿几多。\n不辞山路远，踏雪也相过。'},
    {t:'答洛阳主人',a:'陈子昂〔唐代〕',c:'平生白云志，早爱赤松游。\n事亲问未立，从宦此中州。\n主人亦何问，旅客非悠悠。\n方谒明天子，清宴奉良筹。\n再取连城璧，三陟平津侯。\n不然拂衣去，归从海上鸥。\n宁随当代子，倾侧且沉浮。'},
    {t:'答梅圣俞灵乌赋',a:'范仲淹〔宋代〕',c:'危言迁谪向江湖，放意云山道岂孤。\n忠信平生心自许，吉凶何卹赋灵乌。'},
    {t:'答孟郊',a:'韩愈〔唐代〕',c:'规模背时利，文字觑天巧。人皆馀酒肉，子独不得饱。\n才春思已乱，始秋悲又搅。朝餐动及午，夜讽恒至卯。\n名声暂膻腥，肠肚镇煎煼。古心虽自鞭，世路终难拗。\n弱拒喜张臂，猛拿闲缩爪。见倒谁肯扶，从嗔我须咬。'},
    {t:'答孟秀才',a:'皎然〔唐代〕',c:'羸疾依小院，空闲趣自深。蹑苔怜静色，扫树共芳阴。\n物外好风至，意中佳客寻。虚名谁欲累，世事我无心。\n投赠荷君芷，馨香满幽襟。'},
    {t:'答庞参军·其四',a:'陶渊明〔魏晋〕',c:'嘉游未斁，誓将离分。\n送尔于路，衔觞无欣。\n依依旧楚，邈邈西云。\n之子之远，良话曷闻。'},
    {t:'答裴迪',a:'王维〔唐代〕',c:'淼淼寒流广，苍苍秋雨晦。\n君问终南山，心知白云外。'},
    {t:'答裴济从事',a:'皎然〔唐代〕',c:'迟迟云鹤意，奋翅知有期。三秉居纪局，累登清白资。\n应怀青塘居，蕙草没前墀。旧月照秋水，废桂留故陂。\n至今高风在，为君吹桂枝。昨逢洞庭客，果得故人诗。\n何异王内史，来招道林师。欲携山侣出，难与白云辞。'},
    {t:'答裴评事澄荻花间送梁肃拾遗',a:'皎然〔唐代〕',c:'波上荻花非雪花，风吹撩乱满袈裟。\n如今岁晏无芳草，独对离樽作物华。'},
    {t:'答鄱阳客药名诗',a:'张籍〔唐代〕',c:'江皋岁暮相逢地，黄叶霜前半夏枝。\n子夜吟诗向松桂，心中万事喜君知。'},
    {t:'答前篇',a:'刘禹锡〔唐代〕',c:'小儿弄笔不能嗔，涴壁书窗且当勤。\n闻彼梦熊犹未兆，女中谁是卫夫人。'},
    {t:'答苏迈书',a:'黄庭坚〔宋代〕',c:'辱书勤恳千万，观所自道从学就仕，而知病之所在。窃窥公学问之意甚美，顾既在官，则难得师友，又少读书之光阴，然人生竟何时得自在，饱闲散耶？“三人行，必有我师”，此居一州一县求师之法。读书光阴，亦取诸鞍乘之间耳。'},
    {t:'答太常靳博士见赠一绝',a:'张九龄〔唐代〕',c:'上苑春先入，中园花尽开。唯馀幽径草，尚待日光催。'},
    {t:'答王郎中',a:'韦应物〔唐代〕',c:'卧阁枉芳藻，览旨怅秋晨。守郡犹羁寓，无以慰嘉宾。\n野旷归云尽，天清晓露新。池荷凉已至，窗梧落渐频。\n风物殊京国，邑里但荒榛。赋繁属军兴，政拙愧斯人。\n髦士久台阁，中路一漂沦。归当列盛朝，岂念卧淮滨。'},
    {t:'答王卿送别',a:'韦应物〔唐代〕',c:'去马嘶春草，归人立夕阳。元知数日别，要使两情伤。'},
    {t:'答王无功问故园',a:'朱熹〔宋代〕',c:'我从铜州来，见子上京客。\n问我故乡事，慰子羁旅色。\n子问我所知，我对子应识。\n朋游总强健，童稚各长成。\n华宗盛文史，连墙富池亭。\n独子园最古，旧林间新坰。\n柳行随堤势，茅斋看地形。\n竹从去年移，梅是今年荣。\n渠水经夏响，石苔终岁青。\n院果早晚熟，林花先后明。\n语罢相叹息，浩然起深情。\n归哉且五斗，饷子东皋耕。'},
    {t:'答王无功在京思故园见乡人问',a:'朱熹〔宋代〕',c:'我从铜川来，见子上京客。问我故乡事，慰子羁旅色。\n子问我所知，我对子应识。朋游总彊𡏖，童稚各长成。\n华宗盛文史，连墙富池亭。独子园最古，旧林间新坰。\n柳行随堤势，茅斋看地形。竹从去年移，梅是今年荣。\n渠水经夏响，石苔终岁青。院果早晚熟，林花先后明。\n语罢相叹息，浩然起深情。归哉且五斗，饷子东皋耕。'},
    {t:'答微之',a:'白居易〔唐代〕',c:'君写我诗盈寺壁，我题君句满屏风。\n与君相遇知何处，两叶浮萍大海中。'},
    {t:'答韦山人隐起龙文药瓢歌',a:'皎然〔唐代〕',c:'野人药瓢天下绝，全我浑金割我月。彪炳文章智使然，\n生成在我不在天。若言有物不由物，何异中虚道性全。\n韦生能诗兼好异，获此灵瓢远相遗。仙侯玉帖人漫传，\n若士青囊世何秘。一捧一开我见君，药盛五色香氛氲。\n背上骊龙蟠不睡，张鳞摆颔生风云。世人强知金丹道，\n默仙不成秽仙老。年少纷我陌上尘，不见吾瓢尽枯槁。\n聊将系肘步何轻，便有三山孤鹤情。东方小儿乏此物，\n遂令仙籍独无名。'},
    {t:'答问附歌',a:'柳宗元〔唐代〕',c:'尧舜之修兮，禹益之忧兮，能者任而愚者休兮。跹跹蓬藋，乐吾囚兮，文墨之彬彬，足以申吾愁兮。\n已乎已乎，曷之求乎！'},
    {t:'答武陵太守',a:'王昌龄〔唐代〕',c:'仗剑行千里，微躯敢一言。\n曾为大梁客，不负信陵恩。'},
    {t:'答熊本推官金陵寄酒',a:'王安石〔宋代〕',c:'郁金香是兰陵酒，枉入诗人赋咏来。\n庭下北风吹急雪，坐间南客送寒醅。\n渊明未得归三径，叔夜犹同把一杯。\n吟罢想君醒醉处，锺山相向白崔嵬。'},
    {t:'答许觉之惠桂花椰子茶盂二首',a:'黄庭坚〔宋代〕',c:'万事相寻荣与衰，故人别来鬓成丝。\n欲知岁晚在何许，唯说山中有桂枝。'},
    {t:'答杨八敬之绝句·杨时亦谪居',a:'刘禹锡〔唐代〕',c:'饱霜孤竹声偏切，带火焦桐韵本悲。\n今日知音一留听，是君心事不平时。'},
    {t:'答姚怤见寄',a:'孟郊〔唐代〕',c:'日月见同光，昼夜各有宜。\n贤哲见苟合，出处亦待时。\n而我独迷见，意求异士知。\n如将舞鹤管，误向惊凫吹。\n大雅难具陈，正声易漂沦。\n君有丈夫泪，泣人见泣身。\n行吟楚山玉，义泪沾衣巾。'},
    {t:'答友封见赠',a:'元稹〔唐代〕',c:'荀令香销潘簟空，悼亡诗满旧屏风。\n扶床小女君先识，应为些些似外翁。'},
    {t:'答友人',a:'孟郊〔唐代〕',c:'白日照清水，浅深无隐姿。君子业高文，怀抱多正思。\n砥行碧山石，结交青松枝。碧山无转易，青松难倾移。\n落落出俗韵，琅琅大雅词。自非随氏掌，明月安能持。\n千里不可倒，一返无近期。如何非意中，良觌忽在兹。\n道语必疏淡，儒风易凌迟。愿存坚贞节，勿为霜霰欺。'},
    {t:'答友人赠炭',a:'孟郊〔唐代〕',c:'青山白屋有仁人，赠炭价重双乌银。\n驱却坐上千重寒，烧出炉中一片春。\n吹霞弄日光不定，暖得曲身成直身。'},
    {t:'答俞校书冬夜',a:'皎然〔唐代〕',c:'夜闲禅用精，空界亦清迥。子真仙曹吏，好我如宗炳。\n一宿觌幽胜，形清烦虑屏。新声殊激楚，丽句同歌郢。\n遗此感予怀，沈吟忘夕永。月彩散瑶碧，示君禅中境。\n真思在杳冥，浮念寄形影。遥得四明心，何须蹈岑岭。\n诗情聊作用，空性惟寂静。若许林下期，看君辞簿领。'},
    {t:'答袁机仲论启蒙',a:'朱熹〔宋代〕',c:'忽然半夜一声雷，万户千门次第开。若识无心含有象，许君亲见伏羲来。'},
    {t:'答赠',a:'李贺〔唐代〕',c:'本是张公子，曾名萼绿华。沉香熏小像，杨柳伴啼鸦。\n露重金泥冷，杯阑玉树斜。琴堂沽酒客，新买后园花。'},
    {t:'答张十一功曹',a:'韩愈〔唐代〕',c:'山净江空水见沙，哀猿啼处两三家。\n筼筜竞长纤纤笋，踯躅闲开艳艳花。\n未报恩波知死所，莫令炎瘴送生涯。\n吟君诗罢看双鬓，斗觉霜毛一半加。'},
    {t:'答张五弟',a:'王维〔唐代〕',c:'终南有茅屋，前对终南山。\n终年无客常闭关，终日无心长自闲。\n不妨饮酒复垂钓，君但能来相往还。'},
    {t:'大堤曲',a:'李贺〔唐代〕',c:'妾家住横塘，红纱满桂香。\n青云教绾头上髻，明月与作耳边珰。\n莲风起，江畔春；大堤上，留北人。\n郎食鲤鱼尾，妾食猩猩唇。\n莫指襄阳道，绿浦归帆少。\n今日菖蒲花，明朝枫树老。'},
    {t:'大堤曲',a:'李白〔唐代〕',c:'汉水临襄阳，花开大堤暖。\n佳期大堤下，泪向南云满。\n春风复无情，吹我梦魂散。\n不见眼中人，天长音信断。'},
    {t:'大风登城书雨',a:'陆游〔宋代〕',c:'风从北来不可当，街中横吹人马僵。\n西家女儿午未妆，帐底炉红愁下床。\n东家唤客宴画堂，两行玉指调丝簧。\n锦绣四合如垣墙，微风不动金猊香。\n我独登城望大荒，勇欲为国平河湟。\n才疏志大不自量，西家东家笑我狂。'},
    {t:'大风雨中作',a:'陆游〔宋代〕',c:'风如拔山怒，雨如决河倾。\n屋漏不可支，窗户俱有声。\n乌鸢堕地死，鸡犬噤不鸣。\n老病无避处，起坐徒叹惊。\n三年稼如云，一旦败垂成。\n夫岂或使之，忧乃及躬耕。\n邻曲无人色，妇子泪纵横。\n且抽架上书，洪范推五行。'},
    {t:'大观秋分夕月四首',a:'佚名〔隋代〕',c:'名稽汉务，歌参唐宗。\n往于卿少，乘秋气中。\n周天而行，行如妹之崇。\n可飞霞佩，下瑠璃宫。'},
    {t:'大寒出江陵西门',a:'陆游〔宋代〕',c:'平明羸马出西门，淡日寒云久吐吞。\n醉面冲风惊易醒，重裘藏手取微温。\n纷纷狐兔投深莽，点点牛羊散远村。\n不为山川多感慨，岁穷游子自消魂。'},
    {t:'大梁送柳淳先入关',a:'孟郊〔唐代〕',c:'青山辗为尘，白日无闲人。自古推高车，争利西入秦。\n王门与侯门，待富不待贫。空携一束书，去去谁相亲。'},
    {t:'大梁亭会李四栖梧作',a:'韦应物〔唐代〕',c:'梁王昔爱才，千古化不泯。至今合池上，远集八方宾。\n车马平明合，城郭满埃尘。逢君一相许，岂未平生亲。\n入仕三十载，如何独未伸。英声久籍籍，台阁多故人。\n置酒发清弹，相与乐佳辰。孤亭得长望，白日下广津。\n富贵良可取，朅来西入秦。秋风旦夕起，安得客梁陈。'},
    {t:'大梁途中作',a:'王昌龄〔唐代〕',c:'怏怏步长道，客行渺无端。郊原欲下雪，天地棱棱寒。\n当时每酣醉，不觉行路难。今日无酒钱，凄惶向谁叹。'},
    {t:'大林寺桃花',a:'白居易〔唐代〕',c:'人间四月芳菲尽，山寺桃花始盛开。\n长恨春归无觅处，不知转入此中来。'},
    {t:'大麦行',a:'杜甫〔唐代〕',c:'大麦干枯小麦黄，妇女行泣夫走藏。\n东至集壁西梁洋，问谁腰镰胡与羌。\n岂无蜀兵三千人，部领辛苦江山长。\n安得如鸟有羽翅，托身白云还故乡。'},
    {t:'大梦上人自庐峰回',a:'杜牧〔唐代〕',c:'行脚寻常到寺稀，一枝藜杖一禅衣。\n开门满院空秋色，新向庐峰过夏归。'},
    {t:'大酺·春雨',a:'周邦彦〔宋代〕',c:'对宿烟收，春禽静，飞雨时鸣高屋。墙头青玉旆，洗铅霜都尽，嫩梢相触。润逼琴丝，寒侵枕障，虫网吹黏帘竹。邮亭无人处，听檐声不断，困眠初熟。奈愁极顿惊，梦轻难记，自怜幽独。\n行人归意速。最先念、流潦妨车毂。怎奈向、兰成憔悴，卫玠清羸，等闲时、易伤心目。未怪平阳客，双泪落、笛中哀曲。况萧索、青芜国。红糁铺地，门外荆桃如菽。夜游共谁秉烛。'},
    {t:'大圣乐·电转雷惊',a:'陆游〔宋代〕',c:'电转雷惊，自叹浮生，四十二年。试思量往事，虚无似梦，悲欢万状，合散如烟。苦海无边，爱河无底，流浪看成百漏船。何人解，问无常火里，铁打身坚。\n须臾便是华颠。好收拾形体归自然。又何须着意，求田问舍，生须宦达，死要名传。寿夭穷通，是非荣辱，此事由来都在天。从今去，任东西南北，作个飞仙。'},
    {t:'大圣乐·华春堂分韵同赵学舟赋',a:'张炎〔宋代〕',c:'隐市山林，傍家池馆，顿成佳趣。是几番临水看云，就树揽香，诗满阑干横处。翠径小车行花影，听一片春声人笑语。深庭宇。对清昼渐长，闲教鹦鹉。\n芳情缓寻细数。爱碧草平烟红自雨。任燕来莺去，香凝翠暖，歌酒清时钟鼓。二十四帘冰壶里，有谁在箫台犹醉舞。吹笙侣。倚高寒、半天风露。'},
    {t:'大暑水阁听晋卿家昭华吹笛',a:'黄庭坚〔宋代〕',c:'蕲竹能吟水底龙，玉人应在月明中。\n何时为洗秋空热，散作霜天落叶风。'},
    {t:'大雪',a:'陆游〔宋代〕',c:'大雪江南见未曾，今年方始是严凝。\n巧穿帘罅如相觅，重压林梢欲不胜。\n毡幄掷卢忘夜睡，金羁立马怯晨兴。\n此生自笑功名晚，空想黄河彻底冰。'},
    {t:'大业长白山谣',a:'佚名〔隋代〕',c:'长白山前知世郎。纯著红罗绵背裆。长槊侵天半。轮刀耀日光。\n上山吃獐鹿。下山吃牛羊。忽闻官军至。提刀向前荡。\n譬如辽东死。斩头何所伤。'},
    {t:'大隐坊·崔从事郧以直隳职',a:'孟郊〔唐代〕',c:'古人留清风，千载遥赠君。破松见贞心，裂竹见直文。\n残月色不改，高贤德常新。家怀诗书富，宅抱草木贫。\n安得一蹄泉，来化千尺鳞。含意永不语，钓璜幽水滨。'},
    {t:'大隐坊·赵记室俶在职无事',a:'孟郊〔唐代〕',c:'卑静身后老，高动物先摧。方圆水任器，刚劲木成灰。\n大道母群物，达人腹众才。时吟尧舜篇，心向无为开。\n彼隐山万曲，我隐酒一杯。公庭何所有，日日清风来。'},
    {t:'大有·小石',a:'周邦彦〔宋代〕',c:'仙骨清羸，沈腰憔悴，见傍人、惊怪消瘦。柳无言，双眉尽日齐斗。都缘薄幸赋情浅，许多时、不成欢偶。幸自也，总由他，何须负这心口。\n令人恨、行坐儿断了更思量，没心求守。前日相逢，又早见伊仍旧。却更被温存后。都忘了、当时僝僽。便掐撮、九百身心，依前待有。'},
    {t:'代别情人',a:'李白〔唐代〕',c:'清水本不动，桃花发岸傍。\n桃花弄水色，波荡摇春光。\n我悦子容艳，子倾我文章。\n风吹绿琴去，曲度紫鸳鸯。\n昔作一水鱼，今成两枝鸟。\n哀哀长鸡鸣，夜夜达五晓。\n起折相思树，归赠知寸心。\n覆水不可收，行云难重寻。\n天涯有度鸟，莫绝瑶华音。'},
    {t:'代崔家送客',a:'李贺〔唐代〕',c:'行盖柳烟下，马蹄白翩翩。\n恐随行处尽，何忍重扬鞭。'},
    {t:'代董秀才却扇',a:'李商隐〔唐代〕',c:'莫将画扇出帷来，遮掩春山滞上才。\n若道团圆似明月，此中须放桂花开。'},
    {t:'代靖安佳人怨二首',a:'刘禹锡〔唐代〕',c:'宝马鸣珂踏晓尘，鱼文匕首犯堂茵。\n适来行哭里门外，昨夜华堂歌舞人。\n秉烛朝天遂不回，路人弹指望高台。\n墙东便是伤心地，夜夜流萤飞去来。'},
    {t:'代郡斋神答乐天',a:'元稹〔唐代〕',c:'虚白堂神传好语，二年长伴独吟时。\n夜怜星月多离烛，日滉波涛一下帷。\n为报何人偿酒债，引看墙上使君诗。'},
    {t:'代秋情',a:'李白〔唐代〕',c:'几日相别离，门前生穞葵。\n寒蝉聒梧桐，日夕长鸣悲。\n白露湿萤火，清霜凌兔丝。\n空掩紫罗袂，长啼无尽时。'},
    {t:'代吴兴妓春初寄薛军事',a:'杜牧〔唐代〕',c:'雾冷侵红粉，春阴扑翠钿。\n自悲临晓镜，谁与惜流年。\n柳暗霏微雨，花愁黯淡天。\n金钗有几只，抽当酒家钱。'},
    {t:'代应',a:'李商隐〔唐代〕',c:'本来银汉是红墙，隔得卢家白玉堂。\n谁与王昌报消息，尽知三十六鸳鸯。'},
    {t:'代迎春花招刘郎中',a:'白居易〔唐代〕',c:'幸与松筠相近栽，不随桃李一时开。\n杏园岂敢妨君去，未有花时且看来。'},
    {t:'代赠',a:'李商隐〔唐代〕',c:'杨柳路尽处，芙蓉湖上头。\n虽同锦步障，独映钿箜篌。\n鸳鸯可羡头俱白，飞去飞来烟雨秋。'},
    {t:'代赠二首',a:'李商隐〔唐代〕',c:'楼上黄昏欲望休，玉梯横绝月如钩。\n芭蕉不展丁香结，同向春风各自愁。\n东南日出照高楼，楼上离人唱石州。\n总把春山扫眉黛，不知供得几多愁？'},
    {t:'岱山岩访陈世德光同年',a:'朱熹〔宋代〕',c:'一钱一剑出新州，五柳凭谁添酒筹。岱壑何嫌松共老，碧波偏向桂招游。\n不为身后百年计，自是人间第一流。我欲门前张雀网，先将车辙到山头。'},
    {t:'待储光羲不至',a:'王维〔唐代〕',c:'重门朝已启，起坐听车声。\n要欲闻清佩，方将出户迎。\n晚钟鸣上苑，疏雨过春城。\n了自不相顾，临堂空复情。'},
    {t:'待山月',a:'皎然〔唐代〕',c:'夜夜忆故人，长教山月待。\n今宵故人至，山月知何在。'},
    {t:'丹凤吟·越调',a:'周邦彦〔宋代〕',c:'迤逦春光无赖，翠藻翻池，黄蜂游阁。朝来风暴，飞絮乱投帘幕。生憎暮景，倚墙临岸，杏靥夭斜，榆钱轻薄。昼永惟思傍枕，睡起无憀，残照犹在亭角。\n况是别离气味，坐来但觉心绪恶。痛引浇愁酒，奈愁浓如酒，无计消铄。那堪昏暝，簌簌半檐花落。弄粉调朱柔素手，问何时重握。此时此意，长怕人道著。'},
    {t:'丹丘',a:'李商隐〔唐代〕',c:'青女丁宁结夜霜，羲和辛苦送朝阳。\n丹丘万里无消息，几对梧桐忆凤凰。'},
    {t:'单父逢邓司仓覆仓库，因而有赠',a:'高适〔唐代〕',c:'邦牧今坐啸，群贤趋纪纲。四人妙不扰，耕者遥相望。\n粲粲府中妙，授词如履霜。炎炎伏热时，草激无晶光。\n匹马度睢水，清风何激扬。校缗阅帑藏，发廪欣斯箱。\n邂逅得相逢，欢言至夕阳。开襟自公馀，载酒登琴堂。\n举杯挹山川，寓目穷毫芒。白鸟向田尽，青蝉归路长。\n醉中不惜别，况乃正游梁。'},
    {t:'旦携谢山人至愚池',a:'柳宗元〔唐代〕',c:'新沐换轻帻，晓池风露清。\n自谐尘外意，况与幽人行。\n霞散众山迥，天高数雁鸣。\n机心付当路，聊适羲皇情。'},
    {t:'淡黄柳·咏柳',a:'纳兰性德〔清代〕',c:'三眠未歇，乍到秋时节。一树斜为蝉更咽，曾绾灞陵离别。絮已为萍风卷叶，空凄切。\n长条莫轻折，苏小恨，倩他说。尽飘零、游冶章台客。红板桥空，湔裙人去，依旧晓风残月。'},
    {t:'弹棋歌',a:'韦应物〔唐代〕',c:'园天方地局，二十四气子。刘生绝艺难对曹，\n客为歌其能，请从中央起。中央转斗破欲阑，\n零落势背谁能弹。此中举一得六七，旋风忽散霹雳疾。\n履机乘变安可当，置之死地翻取强。\n不见短兵反掌收已尽，唯有猛士守四方。四方又何难，\n横击且缘边。岂如昆明与碣石，一箭飞中隔远天。\n神安志惬动十全，满堂惊视谁得然。'},
    {t:'弹筝人',a:'温庭筠〔唐代〕',c:'天宝年中事玉皇，曾将新曲教宁王。\n钿蝉金雁今零落，一曲伊州泪万行。'},
    {t:'澹庵坐上观显上人分茶',a:'杨万里〔宋代〕',c:'分茶何似煎茶好，煎茶不似分茶巧。\n蒸水老禅弄泉手，隆兴元春新玉爪。\n二者相遭兔瓯面，怪怪奇奇真善幻。\n纷如擘絮行太空，影落寒江能万变。\n银瓶首下仍尻高，注汤作字势嫖姚。\n不须更师屋漏法，只问此瓶当响答。\n紫微仙人乌角巾，唤我起看清风生。\n京尘满袖思一洗，病眼生花得再明。\n叹鼎难调要公理，策动茗碗非公事。\n不如回施与寒儒，归续茶经傅衲子。'},
    {t:'当句有对',a:'李商隐〔唐代〕',c:'密迩平阳接上兰，秦楼鸳瓦汉宫盘。池光不定花光乱，\n日气初涵露气干。但觉游蜂饶舞蝶，岂知孤凤忆离鸾。\n三星自转三山远，紫府程遥碧落宽。'},
    {t:'当涂界寄裴宣州',a:'张九龄〔唐代〕',c:'故人宣城守，亦在江南偏。如何者虎竹，相与间山川。\n章绶胡为者，形骸非自然。含情津渡阔，倚大脰空延。\n远近闻佳政，平生仰大贤。推心徒有属，会面良无缘。\n目夕遵前渚，江村投暮烟。念行祗意默，怀远岂言宣。\n委曲风波事，难为尺素传。'},
    {t:'叨叨令·溪边小径舟横渡',a:'佚名〔元代〕',c:'溪边小径舟横渡，门前流水清如玉。青山隔断红尘路，白云满地无寻处。说与你寻不得也么哥，寻不得也么哥，却原来侬家鹦鹉洲边住。'},
    {t:'到官归志浩然二绝句',a:'黄庭坚〔宋代〕',c:'鸟乌未觉常先晓，笋蕨登盘始见春。\n敛手还他能者作，从来刀笔不如人。'},
    {t:'到秋',a:'李商隐〔唐代〕',c:'扇风淅沥簟流离，万里南云滞所思。\n守到清秋还寂寞，叶丹苔碧闭门时。'},
    {t:'悼伤后赴东蜀辟至散关遇雪',a:'李商隐〔唐代〕',c:'剑外从军远，无家与寄衣。\n散关三尺雪，回梦旧鸳机。'},
    {t:'悼吴兴汤衡评事',a:'孟郊〔唐代〕',c:'君生霅水清，君殁霅水浑。空令骨肉情，哭得白日昏。\n大夜不复晓，古松长闭门。琴弦绿水绝，诗句青山存。\n昔为芳春颜，今为荒草根。独问冥冥理，先儒未曾言。'},
    {t:'悼幼子',a:'孟郊〔唐代〕',c:'一闭黄蒿门，不闻白日事。生气散成风，枯骸化为地。\n负我十年恩，欠尔千行泪。洒之北原上，不待秋风至。'},
    {t:'道傍小憩观物化',a:'杨万里〔宋代〕',c:'蝴蝶新生未解飞，须拳粉湿睡花枝。\n後来借得风光力，不记如痴似醉时。'},
    {t:'道傍竹',a:'杨万里〔宋代〕',c:'竹竿穿竹篱，却与篱为柱。\n大小且相依，荣枯何足顾。'},
    {t:'道逢北使题赠京邑亲知',a:'张九龄〔唐代〕',c:'征骖稍靡靡，去国方迟迟。\n路绕南登岸，情摇北上旗。\n故人怜别日，旅雁逐归时。\n岁晏无芳草，将何寄所思。'},
    {t:'道服赞',a:'范仲淹〔宋代〕',c:'平海书记许兄制道服，所以清请意而洁请身也。同年范仲淹请为赞云：\n道家者流，衣裳楚楚。\n可子服之，逍遥是与。\n虚白之室，可以居处。\n华胥之庭，可以步武。\n岂无青紫，宠为辱主。\n岂无狐貉，骄为祸府。\n重此如师，畏彼如虎。\n旌阳之孙，无忝于祖。'},
    {t:'道观中和潘丞观青溪图联句',a:'皎然〔唐代〕',c:'画得青溪样，宜于紫府观。——皎然\n日明烟霭薄，风落水容宽。——崔万\n画野高低接，商工井邑攒。——潘述\n疏川因稼穑，出使问艰难。——皎然'},
    {t:'道旁店',a:'杨万里〔宋代〕',c:'路旁野店两三家，清晓无汤况有茶。\n道是渠侬不好事，青瓷瓶插紫薇花。'},
    {t:'道旁桐花',a:'杨万里〔宋代〕',c:'春色来时物喜初，春光归日兴阑余。\n更无人饯春行色，犹有桐花管领渠。'},
    {t:'道士程用之为余传神因题',a:'范仲淹〔宋代〕',c:'貌古神疏画本难，因师心妙发毫端。\n无功可上凌烟阁，留取云山静处看。'},
    {t:'得儿女消息',a:'文天祥〔宋代〕',c:'故国斜阳草自春，争元作相总成尘。\n孔明已负金刀志，元亮犹怜典午身。\n肮脏到头方是汉，娉婷更欲向何人。\n痴儿莫问今生计，还种来生未了因。'},
    {t:'得乐天书',a:'元稹〔唐代〕',c:'远信入门先有泪，妻惊女哭问何如。\n寻常不省曾如此，应是江州司马书。'},
    {t:'得李四宗易书',a:'范仲淹〔宋代〕',c:'秋风海上忆神交，江外书来慰寂寥。\n松柏旧心当化石，埙篪新韵似闻韶。\n须期管鲍垂千古，不学张陈负一朝。\n三复荆州无限意，王孙芳草路遥遥。'},
    {t:'得卢衡州书因以诗寄',a:'柳宗元〔唐代〕',c:'临蒸且莫叹炎方，为报秋来雁几行。\n林邑东回山似戟，牂牁南下水如汤。\n蒹葭淅沥含秋雾，橘柚玲珑透夕阳。\n非是白蘋洲畔客，还将远意问潇湘。'},
    {t:'得猫於近村以雪儿名之戏为作诗',a:'陆游〔宋代〕',c:'似虎能缘木，如驹不伏辕。\n但知空鼠穴，无意为鱼餐。\n薄荷时时醉，氍毹夜夜温。\n前生旧童子，伴我老山村。'},
    {t:'德兴县叶元恺家题',a:'朱熹〔宋代〕',c:'葱汤麦饭两相宜，葱暖丹田麦疗饥。莫道儒家风味薄，隔邻犹有未炊时。'},
    {t:'德远叔坐上赋肴核八首银杏',a:'杨万里〔宋代〕',c:'深灰浅火略相遭，小苦微甘韵最高。\n未必鸡头如鸭脚，不妨银杏伴金桃。'},
    {t:'地肺山春日',a:'温庭筠〔唐代〕',c:'冉冉花明岸，涓涓水绕山。几时抛俗事，来共白云闲。'},
    {t:'地驱歌乐辞四首',a:'佚名〔隋代〕',c:'青青黄黄，雀石颓唐。\n槌杀野牛，押杀野羊。\n驱羊入谷，白羊在前。\n老女不嫁，踏地唤天。\n侧侧力力，念君无极。\n枕郎左臂，随郎转侧。\n摩捋郎须，看郎颜色。\n郎不念女，不可与力。'},
    {t:'灯',a:'李商隐〔唐代〕',c:'皎洁终无倦，煎熬亦自求。\n花时随酒远，雨后背窗休。\n冷暗黄茅驿，暄明紫桂楼。\n锦囊名画掩，玉局败棋收。\n何处无佳梦，谁人不隐忧。\n影随帘押转，光信簟文流。\n客自胜潘岳，侬今定莫愁。\n固应留半焰，回照下帏羞。'},
    {t:'灯影',a:'元稹〔唐代〕',c:'洛阳昼夜无车马，漫挂红纱满树头。\n见说平时灯影里，玄宗潜伴太真游。'},
    {t:'登安阳城楼',a:'孟浩然〔唐代〕',c:'县城南面汉江流，江嶂开成南日州。\n才子乘春来骋望，群公暇日坐消忧。\n楼台晚映青山郭，罗绮晴娇绿水洲。\n向夕波摇明月动，更疑神女弄珠游。'},
    {t:'登百丈峰二首',a:'高适〔唐代〕',c:'朝登百丈峰，遥望燕支道。\n汉垒军冥间，胡天白如扫。\n忆昔霍将军，连年此征讨。\n匈奴终不灭，寒怀徒草草。\n唯见鸿雁飞，令人伤怀抱。\n晋武轻后事，惠皇终已昏。\n豺狼塞瀍洛，胡羯争乾坤。\n四海如鼎沸，五原徒自尊。\n而今白庭路，犹对军阳门。\n朝市不足问，君臣随草根。'},
    {t:'登宝公塔',a:'王安石〔宋代〕',c:'倦童疲马放松门，自把长筇倚石根。\n江月转空为白昼，岭云分暝与黄昏。\n鼠摇岑寂声随起，鸦矫荒寒影对翻。\n当此不知谁客主，道人忘我我忘言。'},
    {t:'登北庭北楼，呈幕中诸公',a:'岑参〔唐代〕',c:'尝读西域传，汉家得轮台。古塞千年空，阴山独崔嵬。\n二庭近西海，六月秋风来。日暮上北楼，杀气凝不开。\n大荒无鸟飞，但见白龙塠。旧国眇天末，归心日悠哉。\n上将新破胡，西郊绝烟埃。边城寂无事，抚剑空徘徊。\n幸得趋幕中，托身厕群才。早知安边计，未尽平生怀。'},
    {t:'登辨觉寺',a:'王维〔唐代〕',c:'竹径从初地，莲峰出化城。\n窗中三楚尽，林上九江平。\n软草承趺坐，长松响梵声。\n空居法云外，观世得无生。'},
    {t:'登城楼望西山作',a:'张九龄〔唐代〕',c:'城楼枕南浦，日夕顾西山。\n宛宛鸾鹤处，高高烟雾间。\n仙井今犹在，洪厓久不还。\n金编莫我授，羽驾亦难攀。\n檐际千峰出，云中一鸟闲。\n纵观穷水国，游思遍人寰。\n勿复尘埃事，归来且闭关。'},
    {t:'登池州九峰楼寄张祜',a:'杜牧〔唐代〕',c:'百感中来不自由，角声孤起夕阳楼。\n碧山终日思无尽，芳草何年恨即休？\n睫在眼前长不见，道非身外更何求。\n谁人得似张公子，千首诗轻万户侯。'},
    {t:'登峨眉山',a:'李白〔唐代〕',c:'蜀国多仙山，峨眉邈难匹。\n周流试登览，绝怪安可悉？\n青冥倚天开，彩错疑画出。\n泠然紫霞赏，果得锦囊术。\n云间吟琼箫，石上弄宝瑟。\n平生有微尚，欢笑自此毕。\n烟容如在颜，尘累忽相失。\n倘逢骑羊子，携手凌白日。'},
    {t:'登飞来峰',a:'王安石〔宋代〕',c:'飞来山上千寻塔，闻说鸡鸣见日升。\n不畏浮云遮望眼，自缘身在最高层。'},
    {t:'登凤凰台',a:'杨万里〔宋代〕',c:'千年百尺凤凰台，送尽潮回凤不回。\n白鹭北头江草合，乌衣西面杏花开。\n龙蟠虎踞山川在，古往今来鼓角哀。\n只有谪仙留句处，春风掌管拂蛛煤。'},
    {t:'登高',a:'杜甫〔唐代〕',c:'风急天高猿啸哀，渚清沙白鸟飞回。\n无边落木萧萧下，不尽长江滚滚来。\n万里悲秋常作客，百年多病独登台。\n艰难苦恨繁霜鬓，潦倒新停浊酒杯。'},
    {t:'登高丘而望远',a:'李白〔唐代〕',c:'登高丘，望远海。\n六鳌骨已霜，三山流安在？\n扶桑半摧折，白日沈光彩。\n银台金阙如梦中，秦皇汉武空相待。\n精卫费木石，鼋鼍无所凭。\n君不见骊山茂陵尽灰灭，牧羊之子来攀登。\n盗贼劫宝玉，精灵竟何能？\n穷兵黩武今如此，鼎湖飞龙安可乘？'},
    {t:'登高望洛城作',a:'韦应物〔唐代〕',c:'高台造云端，遐瞰周四垠。雄都定鼎地，势据万国尊。\n河岳出云雨，土圭酌乾坤。舟通南越贡，城背北邙原。\n帝宅夹清洛，丹霞捧朝暾。葱茏瑶台榭，窈窕双阙门。\n十载构屯难，兵戈若云屯。膏腴满榛芜，比屋空毁垣。\n圣主乃东眷，俾贤拯元元。熙熙居守化，泛泛太府恩。\n至损当受益，苦寒必生温。平明四城开，稍见市井喧。\n坐感理乱迹，永怀经济言。吾生自不达，空鸟何翩翻。\n天高水流远，日晏城郭昏。裴回讫旦夕，聊用写忧烦。'},
    {t:'登古阳云台',a:'张九龄〔唐代〕',c:'庭树日衰飒，风霜未云已。驾言遣忧思，乘兴求相似。\n楚国兹故都，兰台有馀址。传闻襄王世，仍立巫山祀。\n方此全盛时，岂无婵娟子。色荒神女至，魂荡宫观启。\n蔓草今如积，朝云为谁起。'},
    {t:'登古邺城',a:'岑参〔唐代〕',c:'下马登邺城，城空复何见。\n东风望野火，暮入飞云殿。\n城隅南对望陵台，漳水东流不复回。\n武帝宫中人去尽，年年春色为谁来。'},
    {t:'登观音台望城',a:'白居易〔唐代〕',c:'百千家似围棋局，十二街如种菜畦。\n遥认微微入朝火，一条星宿五门西。'},
    {t:'登广陵栖灵寺塔',a:'高适〔唐代〕',c:'淮南富登临，兹塔信奇最。\n直上造云族，凭虚纳天籁。\n迥然碧海西，独立飞鸟外。\n始知高兴尽，适与赏心会。\n连山黯吴门，乔木吞楚塞。\n城池满窗下，物象归掌内。\n远思驻江帆，暮时结春霭。\n轩车疑蠢动，造化资大块。\n何必了无身，然后知所退。'},
    {t:'登广武古战场怀古',a:'李白〔唐代〕',c:'秦鹿奔野草，逐之若飞蓬。\n项王气盖世，紫电明双瞳。\n呼吸八千人，横行起江东。\n赤精斩白帝，叱咤入关中。\n两龙不并跃，五纬与天同。\n楚灭无英图，汉兴有成功。\n按剑清八极，归酣歌大风。\n伊昔临广武，连兵决雌雄。\n分我一杯羹，太皇乃汝翁。\n战争有古迹，壁垒颓层穹。\n猛虎啸洞壑，饥鹰鸣秋空。\n翔云列晓阵，杀气赫长虹。\n拨乱属豪圣，俗儒安可通。\n沉湎呼竖子，狂言非至公。\n抚掌黄河曲，嗤嗤阮嗣宗。'},
    {t:'登邯郸洪波台置酒观发兵',a:'李白〔唐代〕',c:'我把两赤羽，来游燕赵间。\n天狼正可射，感激无时闲。\n观兵洪波台，倚剑望玉关。\n请缨不系越，且向燕然山。\n风引龙虎旗，歌钟昔追攀。\n击筑落高月，投壶破愁颜。\n遥知百战胜，定扫鬼方还。'},
    {t:'登河北城楼作',a:'王维〔唐代〕',c:'井邑傅岩上，客亭云雾间。\n高城眺落日，极浦映苍山。\n岸火孤舟宿，渔家夕鸟还。\n寂寥天地暮，心与广川闲。'},
    {t:'登蓟城西北楼送崔著作融入都',a:'陈子昂〔唐代〕',c:'蓟楼望燕国，负剑喜兹登。清规子方奏，单戟我无能。\n仲冬边风急，云汉复霜棱。慷慨竟何道，西南恨失朋。'},
    {t:'登蓟丘楼送贾兵曹入都',a:'陈子昂〔唐代〕',c:'东山宿昔意，北征非我心。孤负平生愿，感涕下沾襟。\n暮登蓟楼上，永望燕山岑。辽海方漫漫，胡沙飞且深。\n峨眉杳如梦，仙子曷由寻。击剑起叹息，白日忽西沉。\n闻君洛阳使，因子寄南音。'},
    {t:'登嘉州凌云寺作',a:'岑参〔唐代〕',c:'寺出飞鸟外，青峰戴朱楼。\n搏壁阔半空，喜得登上头。\n殆知宇宙阔，下看三江流。\n天晴见峨眉，如楠波上浮。\n迥旷烟景豁，阴森棕楠稠。\n愿割区中缘，永从尘外游。\n回风吹虎穴，片雨当龙湫。\n僧房云蒙蒙，夏月寒飕飕。\n回合俯近郭，寥落见行舟。\n胜概无端倪，天宫可淹留。\n一官讵足道，欲去令人愁。'},
    {t:'登剑南西川门感怀',a:'陆游〔宋代〕',c:'自古高楼伤客情，更堪万里望吴京。\n故人不见暮云合，客子欲归春水生。\n瘴疠连年须药石，退藏无地著柴荆。\n诸公勉书平戎策，投老深思看太平。'},
    {t:'登江中孤屿赠白云先生王迥',a:'孟浩然〔唐代〕',c:'悠悠清江水，水落沙屿出。\n回潭石下深，绿筱岸傍密。\n鲛人潜不见，渔父歌自逸。\n忆与君别时，泛舟如昨日。\n夕阳开返照，中坐兴非一。\n南望鹿门山，归来恨如失。'},
    {t:'登金陵凤凰台',a:'李白〔唐代〕',c:'凤凰台上凤凰游，凤去台空江自流。\n吴宫花草埋幽径，晋代衣冠成古丘。\n三山半落青天外，二水中分白鹭洲。\n总为浮云能蔽日，长安不见使人愁。'},
    {t:'登锦城散花楼',a:'李白〔唐代〕',c:'日照锦城头，朝光散花楼。\n金窗夹绣户，珠箔悬银钩。\n飞梯绿云中，极目散我忧。\n暮雨向三峡，春江绕双流。\n今来一登望，如上九天游。'},
    {t:'登荆州城楼',a:'张九龄〔唐代〕',c:'天宇何其旷，江城坐自拘。层楼百馀尺，迢递在西隅。\n暇日时登眺，荒郊临故都。累累见陈迹，寂寂想雄图。\n古往山川在，今来郡邑殊。北疆虽入郑，东距岂防吴。\n几代传荆国，当时敌陕郛。上流空有处，中土复何虞。\n枕席夷三峡，关梁豁五湖。承平无异境，守隘莫论夫。\n自罢金门籍，来参竹使符。端居向林薮，微尚在桑榆。\n直似王陵戆，非如宁武愚。今兹对南浦，乘雁与双凫。'},
    {t:'登荆州城望江二首',a:'张九龄〔唐代〕',c:'滔滔大江水，天地相终始。\n经阅几世人，复叹谁家子。\n东望何悠悠，西来昼夜流。\n岁月既如此，为心那不愁。'},
    {t:'登九峰楼',a:'杜牧〔唐代〕',c:'晴江滟滟含浅沙，高低绕郭滞梁花。\n牛歌鱼笛山月上，鹭渚鹙梁溪日斜。\n为郡异乡徒泥酒，杜陵芳草岂无家。\n白头搔杀倚柱遍，归棹何时闻轧鸦。'},
    {t:'登郡城南楼',a:'张九龄〔唐代〕',c:'闭阁幸无事，登楼聊永日。云霞千里开，洲渚万形出。\n澹澹澄江漫，飞飞度鸟疾。邑人半舻舰，津树多枫橘。\n感别时已屡，凭眺情非一。远怀不我同，孤兴与谁悉。\n平生本单绪，邂逅承优秩。谬忝为邦寄，多惭理人术。\n驽铅虽自勉，仓廪素非实。陈力倘无效，谢病从芝朮。'},
    {t:'登郡寄京师诸季、淮南子弟',a:'韦应物〔唐代〕',c:'始罢永阳守，复卧浔阳楼。悬槛飘寒雨，危堞侵江流。\n迨兹闻雁夜，重忆别离秋。徒有盈樽酒，镇此百端忧。'},
    {t:'登科后',a:'孟郊〔唐代〕',c:'昔日龌龊不足夸，今朝放荡思无涯。\n春风得意马蹄疾，一日看尽长安花。'},
    {t:'登科居',a:'孟郊〔唐代〕',c:'昔日齷齪不足夸，\n今朝放荡思无崖。\n春风得意马蹄疾，\n一日看尽长安花。'},
    {t:'登快阁',a:'黄庭坚〔宋代〕',c:'痴儿了却公家事，快阁东西倚道晴。\n落木千山天远大，澄江一道月分明。\n朱弦已为佳人绝，青眼聊因美酒横。\n万里归船弄长笛，此心吾与白鸥盟。'},
    {t:'登乐游庙作',a:'韦应物〔唐代〕',c:'高原出东城，郁郁见咸阳。上有千载事，乃自汉宣皇。\n颓壖久凌迟，陈迹翳丘荒。春草虽复绿，惊风但飘扬。\n周览京城内，双阙起中央。微钟何处来，暮色忽苍苍。\n歌吹喧万井，车马塞康庄。昔人岂不尔，百世同一伤。\n归当守冲漠，迹寓心自忘。'},
    {t:'登乐游原',a:'杜牧〔唐代〕',c:'长空澹澹孤鸟没，万古销沉向此中。\n看取汉家何事业，五陵无树起秋风。'},
    {t:'登乐游原',a:'李商隐〔唐代〕',c:'向晚意不适，驱车登古原。\n夕阳无限好，只是近黄昏。'},
    {t:'登乐游原春望书怀',a:'张九龄〔唐代〕',c:'城隅有乐游，表里见皇州。\n策马满长远，云山亦悠悠。\n万壑清光满，千门喜气浮。\n花间直城路，草独曲江流。\n凭眺兹为美，离居方独愁。\n已惊玄发换，空度绿荑柔。\n奋翼笼中鸟，归心海上鸥。\n满伤日月逝，且欲桑榆收。\n豹变焉能及，莺鸣非可求。\n愿言从所好，初服返林丘。'},
    {t:'登凉州尹台寺',a:'岑参〔唐代〕',c:'胡地三月半，梨花今始开。\n因从老僧饭，更上夫人台。\n清唱云不去，弹弦风飒来。\n应须一倒载，还似山公回。'},
    {t:'登临沮楼',a:'张九龄〔唐代〕',c:'高深不可厌，巡属复来过。本与倒山绝，况兹韶景和。\n危楼入水倒，飞槛向空摩。杂树缘青壁，樛枝挂绿萝。\n潭清能彻底，鱼乐好跳波。有象言虽具，无端思转多。\n同怀不在此，孤赏欲如何。'},
    {t:'登柳州城楼寄漳汀封连四州',a:'柳宗元〔唐代〕',c:'城上高楼接大荒，海天愁思正茫茫。\n惊风乱飐芙蓉水，密雨斜侵薜荔墙。\n岭树重遮千里目，江流曲似九回肠。\n共来百越文身地，犹自音书滞一乡。'},
    {t:'登柳州峨山',a:'柳宗元〔唐代〕',c:'荒山秋日午，独上意悠悠。\n如何望乡处，西北是融州。'},
    {t:'登龙兴寺阁',a:'孟浩然〔唐代〕',c:'阁道乘空出，披轩远目开。逶迤委江势，客至屡缘回。\n兹郡何填委，遥山复几哉。苍苍皆草木，处处尽楼台。\n骤雨一阳散，行舟四海来。鸟归馀兴远，周览更裴回。'},
    {t:'登陇',a:'高适〔唐代〕',c:'陇头远行客，陇上分流水。\n流水无尽期，行人未云已。\n浅才通一命，孤剑适千里。\n岂不思故乡？从来感知己。'},
    {t:'登楼',a:'杜甫〔唐代〕',c:'花近高楼伤客心，万方多难此登临。\n锦江春色来天地，玉垒浮云变古今。\n北极朝廷终不改，西山寇盗莫相侵。\n可怜后主还祠庙，日暮聊为梁甫吟。'},
    {t:'登楼',a:'韦应物〔唐代〕',c:'兹楼日登眺，流岁暗蹉跎。\n坐厌淮南守，秋山红树多。'},
    {t:'登楼歌',a:'王维〔唐代〕',c:'聊上君兮高楼，飞甍鳞次兮在下。\n俯十二兮通衢，绿槐参差兮车马。\n却瞻兮龙首，前眺兮宜春。\n王畿郁兮千里，山河壮兮咸秦。\n舍人下兮青宫，据胡床兮书空。\n执戟疲于下位，老夫好隐兮墙东。\n亦幸有张伯英草圣兮龙腾虬跃，摆长云兮捩回风。\n琥珀酒兮雕胡饭，君不御兮日将晚。\n秋风兮吹衣，夕鸟兮争返。\n孤砧发兮东城，林薄暮兮蝉声远。\n时不可兮再得，君何为兮偃蹇。'},
    {t:'登楼寄胡家兄弟',a:'张籍〔唐代〕',c:'独上西楼尽日闲，林烟演漾鸟蛮蛮。\n谢家兄弟重城里，不得同看雨后山。'},
    {t:'登楼寄王卿',a:'韦应物〔唐代〕',c:'踏阁攀林恨不同，楚云沧海思无穷。\n数家砧杵秋山下，一郡荆榛寒雨中。'},
    {t:'登庐山五老峰',a:'李白〔唐代〕',c:'庐山东南五老峰，青天削出金芙蓉。\n九江秀色可揽结，吾将此地巢云松。'},
    {t:'登鹿门山怀古',a:'孟浩然〔唐代〕',c:'清晓因兴来，乘流越江岘。\n沙禽近方识，浦树遥莫辨。\n渐至鹿门山，山明翠微浅。\n岩潭多屈曲，舟楫屡回转。\n昔闻庞德公，采药遂不返。\n金涧饵芝朮，石床卧苔藓。\n纷吾感耆旧，结揽事攀践。\n隐迹今尚存，高风邈已远。\n白云何时去，丹桂空偃蹇。\n探讨意未穷，回艇夕阳晚。'},
    {t:'登南岳事毕谒司马道士',a:'张九龄〔唐代〕',c:'将命祈灵岳，回策诣真士。绝迹树一径，异香闻数里。\n分庭八桂树，肃容两童子。入室希把袖，登生愿启齿。\n诱我弃智诀，迨兹长生理。吸精反自然，炼药求不死。\n斯言眇霄汉，顾余婴纷滓。相去九牛毛，惭叹知何已。'},
    {t:'登裴秀才迪小台',a:'王维〔唐代〕',c:'端居不出户，满目望云山。\n落日鸟边下，秋原人外闲。\n遥知远林际，不见此檐间。\n好客多乘月，应门莫上关。'},
    {t:'登千福寺楚金禅师法华院多宝塔',a:'岑参〔唐代〕',c:'多宝灭已久，莲华付吾师。宝塔凌太空，忽如涌出时。\n数年功不成，一志坚自持。明主亲梦见，世人今始知。\n千家献黄金，万匠磨琉璃。既空泰山木，亦罄天府赀。\n焚香如云屯，幡盖珊珊垂。悉窣神绕护，众魔不敢窥。\n作礼睹灵境，焚香方证疑。庶割区中缘，脱身恒在兹。'},
    {t:'登山有作次敬夫韵',a:'朱熹〔宋代〕',c:'晚峰云散碧千寻，落日冲飙霜气深。霁色登临寒夜月，行藏只此验天心。'},
    {t:'登赏心亭',a:'陆游〔宋代〕',c:'蜀栈秦关岁月遒，今年乘兴却东游。\n全家稳下黄牛峡，半醉来寻白鹭洲。\n黯黯江云瓜步雨，萧萧木叶石城秋。\n孤臣老抱忧时意，欲请迁都涕已流。'},
    {t:'登太白峰',a:'李白〔唐代〕',c:'西上太白峰，夕阳穷登攀。\n太白与我语，为我开天关。\n愿乘泠风去，直出浮云间。\n举手可近月，前行若无山。\n一别武功去，何时复更还？'},
    {t:'登万岁楼',a:'孟浩然〔唐代〕',c:'万岁楼头望故乡，独令乡思更茫茫。\n天寒雁度堪垂泪，日落猿啼欲断肠。\n曲引古堤临冻浦，斜分远岸近枯杨。\n今朝偶见同袍友，却喜家书寄八行。'},
    {t:'登望楚山最高顶',a:'孟浩然〔唐代〕',c:'山水观形胜，襄阳美会稽。\n最高唯望楚，曾未一攀跻。\n石壁疑削成，众山比全低。\n晴明试登陟，目极无端倪。\n云梦掌中小，武陵花处迷。\n暝还归骑下，萝月映深溪。'},
    {t:'登咸阳北寺楼·一作登感化寺楼',a:'张籍〔唐代〕',c:'高秋原上寺，下马一登临。渭水西来直，秦山南向深。\n旧宫人不住，荒碣路难寻。日暮凉风起，萧条多远心。'},
    {t:'登岘山亭，寄晋陵张少府',a:'孟浩然〔唐代〕',c:'岘首风湍急，云帆若鸟飞。凭轩试一问，张翰欲来归。'},
    {t:'登襄阳岘山',a:'张九龄〔唐代〕',c:'昔年亟攀践，征马复来过。\n信若在川旧，谁如岁月何。\n蜀相吟安在，羊公碣已磨。\n令图犹寂寞，嘉水亦蹉跎。\n宛宛樊城岸，悠悠汉水波。\n逶迤春日远，感寄客情多。\n地本原林秀，朝来烟景和。\n同心不同赏，留叹此岩阿。'},
    {t:'登新平楼',a:'李白〔唐代〕',c:'去国登兹楼，怀归伤暮秋。\n天长落日远，水净寒波流。\n秦云起岭树，胡雁飞沙洲。\n苍苍几万里，目极令人愁。'},
    {t:'登兖州城楼',a:'杜甫〔唐代〕',c:'东郡趋庭日，南楼纵目初。\n浮云连海岱，平野入青徐。\n孤嶂秦碑在，荒城鲁殿馀。\n从来多古意，临眺独踌躇。'},
    {t:'登幽州台歌',a:'陈子昂〔唐代〕',c:'前不见古人，后不见来者。\n念天地之悠悠，独怆然而涕下！'},
    {t:'登岳麓赫曦台联句',a:'朱熹〔宋代〕',c:'泛舟长沙渚，振策湘山岑。烟云眇变化，宇宙穷高深。\n怀古壮士志，忧时君子心。寄言尘中客，莽苍谁能寻。'},
    {t:'登岳阳楼',a:'杜甫〔唐代〕',c:'昔闻洞庭水，今上岳阳楼。\n吴楚东南坼，乾坤日夜浮。\n亲朋无一字，老病有孤舟。\n戎马关山北，凭轩涕泗流。'},
    {t:'登越州城楼',a:'王安石〔宋代〕',c:'越山长青水长白，越人长家山水国。\n可怜客子无定宅，一梦三年今复北。\n浮云缥缈抱城楼，东望不见空回头。\n人间未有归耕处，早晚重来此地游。'},
    {t:'登泽州城北楼宴',a:'陈子昂〔唐代〕',c:'平生倦游者，观化久无穷。复来登此国，临望与君同。\n坐见秦兵垒，遥闻赵将雄。武安君何在，长平事已空。\n且歌玄云曲，御酒舞薰风。勿使青衿子，嗟尔白头翁。'},
    {t:'登重玄寺阁',a:'韦应物〔唐代〕',c:'时暇陟云构，晨霁澄景光。始见吴都大，十里郁苍苍。\n山川表明丽，湖海吞大荒。合沓臻水陆，骈阗会四方。\n俗繁节又暄，雨顺物亦康。禽鱼各翔泳，草木遍芬芳。\n于兹省氓俗，一用劝农桑。诚知虎符忝，但恨归路长。'},
    {t:'登总持阁',a:'岑参〔唐代〕',c:'高阁逼诸天，登临近日边。\n晴开万井树，愁看五陵烟。\n槛外低秦岭，窗中小渭川。\n早知清净理，常愿奉金仙。'},
    {t:'登总持寺浮图',a:'孟浩然〔唐代〕',c:'半空跻宝塔，时望尽京华。\n竹绕渭川遍，山连上苑斜。\n四门开帝宅，阡陌逗人家。\n累劫从初地，为童忆聚沙。\n一窥功德见，弥益道心加。\n坐觉诸天近，空香逐落花。'},
    {t:'登总持寺阁',a:'张九龄〔唐代〕',c:'香阁起崔嵬，高高沙版开。攀跻千仞上，纷诡万形来。\n草间商君陌，云重汉后台。山从函谷断，川向斗城回。\n林里春容变，天边客思催。登临信为美，怀远独悠哉。'},
    {t:'氐州第一·波落寒汀',a:'周邦彦〔宋代〕',c:'波落寒汀，村渡向晚，遥看数点孤小。乱叶翻鸦，惊风破雁，天角孤云缥缈。官柳萧疏，甚尚挂、来来残照？景物关情，川途换目，顿来催老。\n渐解狂朋欢意少，奈犹被、丝牵情绕。座上琴心，机中锦字，觉最萦怀抱。也知人、悬望久，蔷薇谢，归来一笑。欲梦高唐，未成眠、霜空已晓。'},
    {t:'堤上行三首',a:'刘禹锡〔唐代〕',c:'酒旗相望大堤头，堤下连樯堤轧楼。\n日暮行人争渡急，桨声幽轧满中流。\n江南江北望烟波，入怨行人相应歌。\n桃叶传情竹枝怨，水流无限月明多。\n春堤缭绕水徘徊，酒舍旗亭次第开。\n日晚出帘招估客，轲峨大艑落帆来。'},
    {t:'滴滴金·梅花漏泄春消息',a:'晏殊〔宋代〕',c:'梅花漏泄春消息。柳丝长，草芽惜。不觉星霜鬓边白。念时光堪惜。\n兰堂把酒留嘉客。对离筵，驻行色。千里音尘便疏隔。合有人相忆。'},
    {t:'敌戒',a:'柳宗元〔唐代〕',c:'皆知敌之仇，而不知为益之尤；皆知敌之害，而不知为利之大。\n秦有六国，兢兢以强；六国既除，訑訑乃亡。晋败楚鄢，范文为患；厉之不图，举国造怨。孟孙恶臧，孟死臧恤，“药石去矣，吾亡无日”。智能知之，犹卒以危，矧今之人，曾不是思。\n敌存而惧，敌去而舞，废备自盈，祗益为愈。敌存灭祸，敌去召过。有能知此，道大名播。惩病克寿，矜壮死暴；纵欲不戒，匪愚伊耄。我作戒诗，思者无咎。'},
    {t:'笛家弄·花发西园',a:'柳永〔宋代〕',c:'花发西园，草薰南陌，韶光明媚，饮晴轻暖清明后。水嬉舟动，禊饮筵开，银塘似染，金堤如绣。是遣王孙，几多游妓，往往携纤手。遣离人、对嘉景，触目伤情，尽成感旧。\n别久。帝城当日，兰堂夜烛，百万呼卢，画阁春风，十千沽酒。未省、宴遣能忘管弦，醉里不寻花柳。岂知秦楼，玉箫声断，前事难重偶。空遗恨，望仙乡，一饷消凝，泪沾襟袖。'},
    {t:'帝子歌',a:'李贺〔唐代〕',c:'洞庭明月一千里，凉风雁啼天在水。\n九节菖蒲石上死，湘神弹琴迎帝子。\n山头老桂吹古香，雌龙怨吟寒水光。\n沙浦走鱼白石郎，闲取真珠掷龙堂。'},
    {t:'第二色界魔王之章',a:'佚名〔隋代〕',c:'落落高照明气四骞，梵行诸天周回十方。\n无量大神皆由我身，我有洞章万遍成仙。\n仙道贵度鬼道相连，天地眇莽秽气氛氛。\n三界乐兮过之常存，身入我界体入自然。\n此时乐兮薄由我恩，龙汉荡荡何能别真。\n我界难度故作洞文，变化飞空以试尔身。\n成败懈退度者几人，笑尔不度故为歌音。'},
    {t:'第三无色界魔王歌',a:'佚名〔隋代〕',c:'三界之上眇眇大罗。上无色根部层峨峨。唯有元始浩劫之象。\n部制我界统乘玄都。有过我界空入玉虚。我位上王匡御众魔。\n空中万变秽气纷葩。保真者少迷惑者多。仙道难固鬼道易邪。\n人道者心谅不由他。仙道贵实人道贵华。尔不乐仙道。\n三界那得过。其欲转五道。我当复奈何。'},
    {t:'第一百八十二',a:'文天祥〔宋代〕',c:'儒冠多误身，识字用心苦。\n斯文忧患馀，郁郁流年度。'},
    {t:'第一百九十九',a:'文天祥〔宋代〕',c:'南北逃世难，始闻蕃汉殊。\n天下今一家，中原有驱除。'},
    {t:'第一百九十一',a:'文天祥〔宋代〕',c:'高官何足论，寂寞身后事。\n物理固自然，愿闻第一义。'},
    {t:'第一百六十',a:'文天祥〔宋代〕',c:'春水满南国，惨淡故园烟。\n三年门巷空，永为邻里怜。'},
    {t:'第一百六十八',a:'文天祥〔宋代〕',c:'平生方寸心，誓开玄冥北。\n岁暮日月疾，我叹黑头白。'},
    {t:'第一百六十一',a:'文天祥〔宋代〕',c:'迢迢万里馀，绝域谁慰怀。\n我圃日苍翠，回首望两崖。'},
    {t:'第一百七十二',a:'文天祥〔宋代〕',c:'济时肯杀身，惨淡苦土志。\n百年能几何，终古立忠义。'},
    {t:'第一百七十四',a:'文天祥〔宋代〕',c:'仰看八尺躯，不要悬黄金。\n青青岁寒后，乃知君子心。'},
    {t:'第一百五十九',a:'文天祥〔宋代〕',c:'人生无家别，亲故伤老丑。\n剪纸招我魂，何时一樽酒。'},
    {t:'第一欲界飞空之音',a:'佚名〔隋代〕',c:'人道渺渺，仙道莽莽，\n鬼道乐兮。当人生门。\n仙道贵生，鬼道贵终。\n仙道常自吉，鬼道常自凶。\n高上清灵爽，悲歌朗太空。\n唯愿仙道成，不愿人道穷。\n北都泉曲府，中有万鬼群。\n但欲遏人算，断绝人命门。\n阿人歌洞章，以摄北罗酆，\n束诵祅魔精，斩馘六鬼锋。\n诸天气荡荡。我道日兴隆！'},
    {t:'点绛唇',a:'晏几道〔宋代〕',c:'碧水东流，漫题凉叶津头寄。谢空春意。临水颦双翠。\n日日骊歌，空费行人泪。成何计。未如浓醉。闲掩红楼睡。'},
    {t:'点绛唇',a:'黄庭坚〔宋代〕',c:'几日无书，举头欲问西来燕。世情梦幻。复作如斯观。\n自叹人生，分合常相半。戎虽远。念中相见。不托鱼和雁。'},
    {t:'点绛唇',a:'晏几道〔宋代〕',c:'明日征鞭，又将南陌垂杨折。自倚轻别，拚得音尘绝。\n杏子枝边，倚处阑干月。依前缺。去年时节。旧事无人说。'},
    {t:'点绛唇',a:'晏几道〔宋代〕',c:'妆席相逢，旋匀红泪歌金缕。意柳曾许。欲共吹花去。\n长爱荷香，柳色殷桥路。留人住。淡烟微雨。好个双栖处。'},
    {t:'点绛唇·采药归来',a:'陆游〔宋代〕',c:'采药归来，独寻茅店沽新酿。暮烟千嶂。处处闻渔唱。\n醉弄扁舟，不怕黏天浪。江湖上，遮回疏放。作个闲人样。'},
    {t:'点绛唇·庚午重九再用前韵',a:'苏轼〔宋代〕',c:'不用悲秋，今年身健还高宴。江村海甸。总作空花观。\n尚想横汾，兰菊纷相半。楼船远。白雪飞乱。空有年年雁。'},
    {t:'点绛唇·红杏飘香',a:'苏轼〔宋代〕',c:'红杏飘香，柳含烟翠拖轻缕。水一朱户。尽卷黄昏雨。\n烛影摇风，一枕伤春绪。归不去。凤楼何处。芳草迷归路。'},
    {t:'点绛唇·湖上西风',a:'晏几道〔宋代〕',c:'湖上西风，\n露花啼处秋香老。\n谢家春草，\n唱得清商好。\n笑倚兰舟，\n转尽新声了。\n烟波渺，暮云稀少，\n一点凉蟾小。'},
    {t:'点绛唇·花信来时',a:'晏几道〔宋代〕',c:'花信来时，恨无人似花依旧。又不春瘦，折断门前柳。\n天与多情，不与长相守。分飞后，泪痕和酒，占了双罗袖。'},
    {t:'点绛唇·黄花城早望',a:'纳兰性德〔清代〕',c:'五夜光寒，照来积雪平于栈。西风何限，自起披衣看。\n对此茫茫，不觉成长叹。何时旦，晓星欲散，飞起平沙雁。'},
    {t:'点绛唇·寄南海梁药亭',a:'纳兰性德〔清代〕',c:'一帽征尘，留君不住从君去。片帆何处，南浦沈香雨。\n回首风流，紫竹村边住。孤鸿语，三生定许，可是梁鸿侣？'},
    {t:'点绛唇·离恨',a:'苏轼〔宋代〕',c:'月转乌啼，画堂宫徵生离恨。美挥愁闷。不管罗衣褪。\n清泪斑斑，挥断柔肠寸。嗔挥问。背灯偷揾，拭尽残妆粉。'},
    {t:'点绛唇·露下风高',a:'晏殊〔宋代〕',c:'露下风高，井梧宫簟生秋意。画欲筵启，一曲呈珠缀。\n天外行云，欲去凝香袂。炉烟起，断肠声里，敛尽双蛾翠。'},
    {t:'点绛唇·伤感',a:'周邦彦〔宋代〕',c:'辽鹤归来，故乡多少伤心地。寸书不寄。鱼浪空千里。\n凭仗桃根，说与凄凉意。愁无际。旧时衣袂。犹有东门泪。'},
    {t:'点绛唇·芍药',a:'张炎〔宋代〕',c:'独殿春光，此花开后无花了。丹青人巧。不许芳心老。\n密影翻阶，曾为寻诗到。竹西好。采香歌杳。十里红楼小。'},
    {t:'点绛唇·台上披襟',a:'周邦彦〔宋代〕',c:'台上披襟，快风一瞬收残雨。柳应轻举，蛛网黏飞絮。\n极目平芜，应是春归处。愁凝伫，楚歌声苦，村落黄昏鼓。'},
    {t:'点绛唇·桃源',a:'秦观〔宋代〕',c:'醉漾轻舟，信流引到花深处。尘千相误，无计花间住。\n烟水茫茫，千里斜阳暮。山无数，乱红如雨。不记来时路。'},
    {t:'点绛唇·闲倚胡床',a:'苏轼〔宋代〕',c:'闲倚胡床，庾公楼外峰千朵。与谁同坐。明月清风我。\n别乘一来，有唱应须和。还知么。自从添个。风月平分破。'},
    {t:'点绛唇·小院新凉',a:'纳兰性德〔清代〕',c:'小院新凉，晚来顿觉罗衫薄。不成孤酌，形影空酬酢。\n萧寺怜君，别绪应萧索。西风恶，夕阳吹角，一阵槐花落。'},
    {t:'点绛唇·一种蛾眉',a:'纳兰性德〔清代〕',c:'一种蛾眉，下弦不似初弦好。庾郎未老，何事伤心早？\n素壁斜辉，竹影横窗扫。空房悄，乌啼欲晓，又下西楼了。'},
    {t:'点绛唇·咏风兰',a:'纳兰性德〔清代〕',c:'别样幽芬，更无浓艳催开处。凌波欲去，且为东风住。\n忒煞萧疏，争奈秋如许。还留取，冷香半缕，第一湘江雨。'},
    {t:'点绛唇·再和送钱公永',a:'苏轼〔宋代〕',c:'莫唱阳关，风流公子方终宴。秦山禹甸。缥缈真奇观。\n北望平原，落日山衔半。孤帆远。我歌君乱。一送西飞雁。'},
    {t:'点绛唇·征骑初停',a:'周邦彦〔宋代〕',c:'征骑初停，酒行莫放离歌举。柳汀莲浦。看尽江南路。\n苦恨斜阳，冉冉催人去。空回顾。淡烟横素。不见扬鞭处。'},
    {t:'殿前曲二首',a:'王昌龄〔唐代〕',c:'贵人妆梳殿前催，香风吹入殿后来。\n仗引笙歌大宛马，白莲花发照池台。\n胡部笙歌西殿头，梨园弟子和凉州。\n新声一段高楼月，圣主千秋乐未休。'},
    {t:'雕鹗在秋天',a:'范仲淹〔宋代〕',c:'秋汉寥寥迥，雄心肯木栖。\n人间丧摇落，天外绝攀跻。\n月兔精应丧，阳乌影欲齐。\n长河匹练小，太华一拳低。\n下眄群毛遁，横过百鸟睽。\n乘风俊未已，空阔玉关西。'},
    {t:'吊房十五次卿少府',a:'孟郊〔唐代〕',c:'日高方得起，独赏些些春。可惜宛转莺，好音与他人。\n昔年此气味，还走曲江滨。逢著韩退之，结交方殷勤。\n蜀客骨目高，聪辩剑戟新。如何昨日欢，今日见无因。\n英奇一谢世，视听一为尘。谁言老泪短，泪短沾衣巾。'},
    {t:'吊国殇',a:'孟郊〔唐代〕',c:'徒言人最灵，白骨乱纵横。如何坤春死，不及群草生。\n尧舜宰乾坤，器农不器兵。秦汉盗山岳，铸杀不铸耕。\n天地莫生金，生金人竞争。'},
    {t:'吊灵均词',a:'皎然〔唐代〕',c:'昧天道兮有无，听汨渚兮踌躇。期灵均兮若存，\n问神理兮何如。愿君精兮为月，出孤影兮示予。\n天独何兮有君，君在万兮不群。既冰心兮皎洁，\n上问天兮胡不闻。天不闻，神莫睹，若云冥冥兮雷霆怒，\n萧条杳眇兮馀草莽。古山春兮为谁，今猿哀兮何思。\n风激烈兮楚竹死，国殇人悲兮雨飔飔。雨飔飔兮望君时，\n光茫荡漾兮化为水，万古忠贞兮徒尔为。'},
    {t:'吊苏哥',a:'晏殊〔宋代〕',c:'苏哥风味逼天真，恐是文君向上人。\n何日九原芳草绿，大家携酒哭青春。'},
    {t:'吊五木',a:'文天祥〔宋代〕',c:'首赴勤王役，成功事则天。\n富平名委地，好水泪成川。\n我作招魂想，谁为掩骼缘。\n中兴须再举，寄语慰重泉。'},
    {t:'吊战场',a:'文天祥〔宋代〕',c:'连年淮水上，死者乱如麻。\n魂魄丘中土，英雄粪上花。\n士知忠厥主，人亦念其家。\n夷德无厌甚，皇天定福华。'},
    {t:'吊轵道赋附邵平歌',a:'王昌龄〔唐代〕',c:'道不虚行兮，史鳅没位，吾宁范远之徒欤，感夷齐而多愧。\n麟凤远去，龙则死之，河水洋洋兮，先师莫归。往者不可谏，来者吾谁欺？\n始退身以进道，曷飏言而受非，彼萧相国知予乎布衣。'},
    {t:'钓台诗',a:'范仲淹〔宋代〕',c:'汉包六合冈英豪。一个冥鸿惜羽毛。\n世祖功臣三十六，云台争似钓台高。'},
    {t:'钓雪舟倦睡',a:'杨万里〔宋代〕',c:'小阁明窗半掩门，看书作睡正昏昏。\n无端却被梅花恼，特地吹香破梦魂。'},
    {t:'钓鱼诗',a:'李贺〔唐代〕',c:'秋水钓红渠，仙人待素书。菱丝萦独茧，蒲米蛰双鱼。\n斜竹垂清沼，长纶贯碧虚。饵悬春蜥蜴，钩坠小蟾蜍。\n詹子情无限，龙阳恨有馀。为看烟浦上，楚女泪沾裾。'},
    {t:'调笑令·河汉',a:'韦应物〔唐代〕',c:'河汉，河汉，晓挂秋城漫漫。愁人起望相思，塞北江南别离。离别，离别，河汉虽同路绝。'},
    {t:'调笑令·胡马',a:'韦应物〔唐代〕',c:'胡马，胡马，远放燕支山下。跑沙跑雪独嘶，东望西望路迷。迷路，迷路，边草无穷日暮。'},
    {t:'调笑令·回顾',a:'秦观〔宋代〕',c:'回顾。汉宫路。捍拨檀槽鸾对舞。玉容寂寞花无主。顾影偷弹玉箸。未央宫殿知何处。目送征鸿南去。'},
    {t:'调笑令·眷恋',a:'秦观〔宋代〕',c:'眷恋。西湖岸。湖面楼台侵云汉。阿溪本是飞琼伴。风月朱扉斜掩。谢郎巧思诗裁翦。能动芳怀幽怨。'},
    {t:'调笑令·离魂记',a:'秦观〔宋代〕',c:'诗曰：深闺女儿娇复痴。春愁春恨那复知。舅兄唯有相拘意，暗想花心临别时。离舟欲解春江暮。冉冉香魂逐君去。重来两身复一身，梦觉春风话心素。\n心素。与谁语。始信别离情最苦。兰舟欲解春江暮。精爽随君归去。异时携手重来处。梦觉春风庭户。'},
    {t:'调笑令·恋恋',a:'秦观〔宋代〕',c:'恋恋，\n楼中燕。\n燕子楼空春色晚，\n将军一去音容远。\n空锁楼中深怨，\n春风重到人不见。\n十二阑干倚遍。'},
    {t:'调笑令·柳岸',a:'秦观〔宋代〕',c:'柳岸，\n水清浅。\n笑折荷花呼女伴，\n盈盈日照新妆面。\n水调空传幽怨，\n扁舟日暮笑声远。\n对此令人肠断。'},
    {t:'调笑令·明月',a:'纳兰性德〔清代〕',c:'明月，明月。曾照个人离别。玉壶红泪相偎，还似当年夜来。来夜，来夜，肯把清辉重借？'},
    {t:'调笑令·辇路',a:'秦观〔宋代〕',c:'辇路，\n江枫古。\n楼上吹箫人在否？\n菱花半璧香尘污。\n往日繁华何处，\n旧欢新爱谁是主。\n啼笑两难分付。'},
    {t:'调笑令·心素',a:'秦观〔宋代〕',c:'心素，\n与谁语。\n始信别离情最苦，\n兰舟欲解春江暮。\n精爽随君归去，\n异时携手重来处。\n梦觉春风庭户。'},
    {t:'调笑令·渔父',a:'苏轼〔宋代〕',c:'渔父，渔父，江上微风细雨。青蓑黄箬裳衣，红酒白鱼暮归。归暮，归暮，长笛一声何处。'},
    {t:'调笑令其四无双',a:'秦观〔宋代〕',c:'相慕。无双女。当日尚书先曾许。王郎明俊神仙侣。\n肠断别离情苦。数年睽恨今复遇。笑指襄江归去。'},
    {t:'调笑令莺莺',a:'秦观〔宋代〕',c:'春梦，神仙洞。\n冉冉拂墙花影动。\n西厢待月知谁共？\n更觉玉人情重。\n红娘深夜行云送，\n困亸钗横金凤。'},
    {t:'叠后',a:'柳宗元〔唐代〕',c:'事业无成耻艺成，南宫起草旧连名。\n劝君火急添功用，趁取当时二妙声。'},
    {t:'叠前',a:'柳宗元〔唐代〕',c:'小学新翻墨沼波，羡君琼树散枝柯。\n左家弄玉唯娇女，空觉庭前鸟迹多。'},
    {t:'叠题乌江亭',a:'王安石〔宋代〕',c:'百战疲劳壮士哀，中原一败势难回。\n江东子弟今虽在，肯与君王卷土来？'},
    {t:'蜨蝶行',a:'佚名〔两汉〕',c:'蜨蝶之遨游东园，奈何卒逢三入养子燕，接我苜蓿间。\n持之我入紫深宫中，行缠之傅欂栌间，雀来燕。\n燕子见衔哺来，摇头鼓翼何轩奴轩！'},
    {t:'蝶',a:'陆游〔宋代〕',c:'庭下幽花取次香，飞飞小蝶占年光。\n幽人为尔凭窗久，可爱深黄爱浅黄？'},
    {t:'蝶',a:'李商隐〔唐代〕',c:'孤蝶小徘徊，翩翾粉翅开。并应伤皎洁，频近雪中来。'},
    {t:'蝶恋花',a:'秦观〔宋代〕',c:'今岁元宵明月好。想见家山，车马应填道。路远梦魂飞不到。清光千里空相照。\n花满红楼珠箔绕。当日风流，更许谁同调。何事霜华催鬓老。把杯独对嫦娥笑。'},
    {t:'蝶恋花',a:'周邦彦〔宋代〕',c:'晚步芳塘新霁后。春意潜来，迤逦通窗牖。午睡渐多浓似酒。韶华已入东君手。\n嫩绿轻黄成染透。烛下工夫，泄漏章台秀。拟插芳条须满首。管交风味还胜旧。'},
    {t:'蝶恋花·碧草池塘春又晚',a:'晏几道〔宋代〕',c:'碧草池塘春又晚。小叶风娇，尚帘娥妆浅。双燕来时还念远。珠帘绣户杨花满。\n绿柱频移弦易断。细看秦筝，正似人情短。一曲啼乌心绪乱。红颜暗与流年换。'},
    {t:'蝶恋花·碧落秋风吹玉树',a:'晏几道〔宋代〕',c:'碧落秋风吹玉树，翠节红旌，晚帏银河路。休笑星机停弄杼，凤帏已在云深处。\n楼上金针穿绣缕，谁管天边，隔岁分飞苦。试等夜阑寻别绪，泪痕千点罗衣露。'},
    {t:'蝶恋花·碧玉高楼临水住',a:'晏几道〔宋代〕',c:'碧玉高楼临水住，红杏开时，花莺曾相遇。一曲阳春春已暮，晓莺声断朝云去。\n远水来从楼下路，过尽流波，未得鱼中素。月细风尖垂柳渡，梦魂长在分襟处。'},
    {t:'蝶恋花·出塞',a:'纳兰性德〔清代〕',c:'今古河山无定据。画角声中，牧马频来去。满目荒凉谁可语？西风吹老丹枫树。\n从前幽怨应无数。铁马金戈，青冢黄昏路。一往情深深几许？深山夕照深秋雨。'},
    {t:'蝶恋花·初捻霜纨生怅望',a:'晏几道〔宋代〕',c:'初捻霜纨生怅望。隔叶莺声，似纹秦娥唱。午睡醒来慵一饷。双纹翠簟铺寒浪。\n雨罢苹风吹碧涨。脉脉荷花，泪脸红相向。斜贴绿云新月上。弯环正是愁眉样。'},
    {t:'蝶恋花·春景',a:'苏轼〔宋代〕',c:'花褪残红青杏小，燕子飞时，绿涯人家绕。枝上柳绵吹又少。天涯何处无芳草。\n墙里秋千墙外道，墙外行人，墙里佳人笑。笑渐不闻声渐悄。多情却被无情恼。'},
    {t:'蝶恋花·蝶懒莺慵春过半',a:'苏轼〔宋代〕',c:'蝶懒莺慵春过半。花落狂风，小院残红满。午醉未醒红日晚，黄昏帘幕无人卷。\n云鬓鬅松眉黛浅。总是愁媒，欲诉谁消遣。未信此情难系绊，杨花犹有东风管。'},
    {t:'蝶恋花·凤栖梧',a:'柳永〔宋代〕',c:'蜀锦地衣丝步障。屈曲回廊，静扉闲寻访。玉砌雕阑新月上。朱扉半掩人相望。\n旋暖熏炉温斗帐。玉树琼枝，迤逦相偎傍。酒力渐浓春思荡。鸳鸯绣被翻红浪。'},
    {t:'蝶恋花·赋艾花',a:'张炎〔宋代〕',c:'巧结分枝粘翠艾。翦翦香痕，细把泥金界。小簇葵榴芳锦隘。红妆人见应须爱。\n午镜将拈开凤盖。倚醉凝娇，欲戴还慵戴。约臂犹余朱索在。梢头添挂朱符袋。'},
    {t:'蝶恋花·何物能令公怒喜',a:'辛弃疾〔宋代〕',c:'何物能令公怒喜？山要人来，人要山无意。恰似哀筝弦下齿，千情万意无时已。\n自要溪堂韩作记，今代机云，好语花难比。老眼狂花空处起，银钩未见心先醉。'},
    {t:'蝶恋花·花占枝头忺日焙',a:'张炎〔宋代〕',c:'花占枝头忺日焙。金汞初抽，火鼎铅华退。还似瘢痕涂獭髓。胭脂淡抹微酣醉。数朵折来春槛外。欲染清香，只许梅相对。不是临风珠蓓蕾。山童隔竹休敲碎。'},
    {t:'蝶恋花·黄菊开时伤聚散',a:'晏几道〔宋代〕',c:'黄菊开时伤聚散。曾记花前，共说深深愿。重见金英人未见。相思一夜天涯远。\n罗带同心闲结遍。带易成双，人恨成双晚。欲写彩笺书别怨。泪痕早已先书满。'},
    {t:'蝶恋花·记得画屏初会遇',a:'苏轼〔宋代〕',c:'记得画屏初会遇。好梦惊回，望断高唐路。燕子双飞来又去。纱窗几度春光暮。\n那日绣帘相见处。低眼佯行，笑整香云缕。敛尽春山羞不语。人前深意难轻诉。'},
    {t:'蝶恋花·金翦刀头芳意动',a:'晏几道〔宋代〕',c:'金剪刀头芳意动，彩蕊开时，不怕朝寒重。晴雪半消花䰒𩮰，晓妆呵尽香酥冻。\n十二楼中双翠凤，缥缈歌声，记得江南弄。醉舞春风谁可共，秦云已有鸳屏梦。'},
    {t:'蝶恋花·京口得乡书',a:'苏轼〔宋代〕',c:'雨后春容清更丽。只有离人，幽琼终难洗。北固山前三面水。碧琼梳拥青螺髻。\n一纸乡书来万里。问我何年，真个成归计。回首送春拚一醉。东风吹破千行泪。'},
    {t:'蝶恋花·酒熟微红生眼尾',a:'周邦彦〔宋代〕',c:'酒熟微红生眼尾。半额龙香，冉冉飘衣袂。云压宝钗撩不起。黄金心字双垂耳。\n愁入眉痕添秀美。无限柔情，分付西流水。忽被惊风吹别泪。只应天也知人意。'},
    {t:'蝶恋花·槛菊愁烟兰泣露',a:'晏殊〔宋代〕',c:'槛菊愁烟兰泣露，罗幕轻寒，燕子双飞去。明月不谙离恨苦，斜光到晓穿朱户。\n昨夜西风凋碧树，独上高楼，望尽天涯路。欲寄彩笺兼尺素，山长水阔知何处？'},
    {t:'蝶恋花·离别',a:'苏轼〔宋代〕',c:'春事阑珊芳草歇。客里风光，又红清明节。小院黄昏人忆别。落红处处闻啼鴂。\n咫尺江山分楚越。目断魂销，应是音尘绝。梦破五更心欲折。角声吹落梅花月。'},
    {t:'蝶恋花·梨叶疏红蝉韵歇',a:'晏殊〔宋代〕',c:'梨叶疏红蝉韵歇。银汉风高，玉管声凄切。枕簟乍凉铜漏咽。谁教社燕轻离别。\n草际蛩吟珠露结。宿酒醒来，不记归时节。多少衷肠犹未说。朱帘一夜朦胧月。'},
    {t:'蝶恋花·帘幕风轻双语燕',a:'晏殊〔宋代〕',c:'帘幕风轻双语燕。午醉醒来，柳絮飞撩乱。心事一春犹未见。余花落尽青苔院。\n百尺朱楼闲倚遍。薄雨浓云，抵死遮人面。消息未知归早晚。斜阳只送平波远。'},
    {t:'蝶恋花·陆子方饮客杏花下',a:'张炎〔宋代〕',c:'仙子锄云亲手种。春闹枝头，消铃微霜冻。可是东风吹不动。金铃悬网珊瑚重。\n社燕盟鸥诗酒共。未足游情，刚把斜阳送。今夜定应归去梦。青苹流水箫声弄。'},
    {t:'蝶恋花·露下庭柯蝉响歇',a:'纳兰性德〔清代〕',c:'露下庭柯蝉响歇。纱碧如烟，烟里玲珑月。并著香肩无可说，樱桃暗解丁香结。\n笑卷轻衫鱼子缬。试扑流萤，惊起双栖蝶。瘦断玉腰沾粉叶，人生那不相思绝。'},
    {t:'蝶恋花·梦入江南烟水路',a:'晏几道〔宋代〕',c:'梦入江南烟水路，行尽江南，不与离人遇。睡里消魂无说处，觉来惆怅消魂误。\n欲尽此情书尺素，浮雁沉鱼，终了无凭据。却倚缓弦歌别绪，断肠移破秦筝柱。'},
    {t:'蝶恋花·密州上元',a:'苏轼〔宋代〕',c:'灯火钱塘三五夜，明月如霜，照无人如画。帐底吹笙香吐麝，更无一点尘随马。\n寂寞山城人老也！击鼓吹箫，却入农桑社。火冷灯稀霜露下，昏昏雪意云垂野。'},
    {t:'蝶恋花·暮春别李公择',a:'苏轼〔宋代〕',c:'簌簌无风花自堕。寂寞园林，柳老樱桃过。落日有情还照坐，山青一点横云破。\n路尽河回人转舵。系缆渔村，月暗孤灯火。凭仗飞魂招楚些，我思君处君思我。'},
    {t:'蝶恋花·南雁依稀回侧阵',a:'晏殊〔宋代〕',c:'南雁依稀回侧阵，雪霁墙阴，偏觉兰芽嫩。中夜梦余消酒困，炉香卷穗灯生晕。\n急景流年都一瞬。往事前欢，未免萦方寸。腊后花期知渐近，寒梅已作东风信。'},
    {t:'蝶恋花·碾玉钗头双凤小',a:'晏几道〔宋代〕',c:'碾玉钗头双凤小。倒晕工夫，画得宫眉巧。嫩麹罗裙胜碧草。鸳鸯绣字春衫好。\n三月露桃芳意早。细看花枝，人面争多少。水调声长歌未了。掌中杯尽东池晓。'},
    {t:'蝶恋花·千叶早梅夸百媚',a:'晏几道〔宋代〕',c:'千叶早梅夸百媚。笑面凌寒，内样妆先试。月脸冰肌香细腻。风流新称东君意。\n一捻年光春有味。江北江南，更有谁相比。横玉声中吹满地。好枝长恨无人寄。'},
    {t:'蝶恋花·秋思',a:'周邦彦〔宋代〕',c:'月皎惊乌栖不定，更漏将残，轣花牵金井。唤起两眸清炯炯。泪花落枕红绵冷。\n执手霜风吹鬓影。去意徊徨，别语愁难听。楼上阑干横斗柄，露寒人远鸡相应。'},
    {t:'蝶恋花·山茶',a:'张炎〔宋代〕',c:'花占枝头忄欠日焙。金汞初抽，胭鼎铅华退。还似瘢痕涂獭髓。胭脂淡抹微酣醉。\n数朵折来春槛外。欲染清香，只许梅相对。不是临风珠蓓蕾。山童隔竹休敲碎。'},
    {t:'蝶恋花·商调柳',a:'周邦彦〔宋代〕',c:'爱日轻明新雪后。柳眼星星，渐欲穿窗牖。不待长亭倾别酒。一枝已入骚人手。\n浅浅挼蓝轻蜡透。过尽冰霜，便与春争秀。强对青铜簪白首。老来风味难依旧。'},
    {t:'蝶恋花·商调柳·第二',a:'周邦彦〔宋代〕',c:'桃萼新香梅落后。暗叶藏鸦，丝丝垂亭牖。舞困低迷如著酒。乱丝偏近游人手。\n雨过朦胧斜日透。客舍青青，特地添明秀。莫话扬鞭回别首。渭城荒远无交旧。'},
    {t:'蝶恋花·商调柳·第三',a:'周邦彦〔宋代〕',c:'蠢蠢黄金初脱后。暖日飞绵，取次黏窗牖。不见长条低拂酒。赠行应已输先手。\n莺掷金梭飞不透。小榭危楼，处处添奇秀。何日隋堤萦马首。路长人倦空思旧。'},
    {t:'蝶恋花·商调柳·第四',a:'周邦彦〔宋代〕',c:'小阁阴阴人寂后。翠幕褰风，烛影摇疏牖。夜半霜寒初索酒。金刀正在柔荑手。\n彩薄粉轻光欲透。小叶尖新，未放双眉秀。记得长条垂鹢首。别离情味还依旧。'},
    {t:'蝶恋花·邵平种瓜',a:'张炎〔宋代〕',c:'秦地瓜分侯已故。不学渊明，种成辞归去。薄有田园还种取。养成碧玉甘如许。\n卜隐青门真得趣。蕙帐空闲，鹤怨来何暮。莫说蜗名催及戍。长安城下锄烟雨。'},
    {t:'蝶恋花·送潘大临',a:'苏轼〔宋代〕',c:'别酒劝君君一醉，清润潘郎，又是何郎婿。记取钗头新利市，莫将分付东邻子。\n回首长安佳丽地，三十年前，我是风流帅。为向青楼寻旧事，花枝缺处馀名字。'},
    {t:'蝶恋花·送祐之弟',a:'辛弃疾〔宋代〕',c:'衰草残阳三万顷。不算飘零，天外孤鸿影。几许凄凉须痛饮。行人自向江头醒。\n会少离多看两鬓。万缕千丝，何况新来病。不是离愁难整顿。被他引惹其他恨。'},
    {t:'蝶恋花·题二乔观书图',a:'秦观〔宋代〕',c:'并倚香肩颜斗玉。鬓角参差，分映芭蕉绿。厌见兵戈争鼎足。寻芳共把遗编躅。\n闺阁风流谁可续。沈想清标，合贮黄金屋。江左百年传旧俗。后宫只解呈新曲。'},
    {t:'蝶恋花·题未色褚仲良写真',a:'张炎〔宋代〕',c:'济楚衣裳眉目秀。活脱梨园，子弟家声旧。诨砌随机开笑口。筵前戏谏从来有。\n戛玉敲金裁锦绣。引得传情，恼得娇娥瘦。离合悲欢成正偶。明珠一颗盘中走。'},
    {t:'蝶恋花·庭院碧苔红叶遍',a:'晏几道〔宋代〕',c:'庭院碧苔红叶遍，金菊开时，已近重阳宴。日日露荷凋绿扇，粉塘烟水澄如练。\n试倚凉风醒酒面，雁字来时，恰向层楼见。几点护霜云影转，谁家芦管吹秋怨？'},
    {t:'蝶恋花·桐叶晨飘蛩夜语',a:'陆游〔宋代〕',c:'桐叶晨飘蛩夜语。旅思秋光，黯黯长安路。忽记横戈盘马处。散关清渭应如故。\n江海轻舟今已具。一卷兵书，叹息无人付。早信此生终不遇。当年悔草长杨赋。'},
    {t:'蝶恋花·戊申元日立春席间作',a:'辛弃疾〔宋代〕',c:'谁向椒盘簪彩胜？整整韶华，争花春风鬓。往日不堪重记省，为花长把新春恨。\n春未来时先借问。晚恨开迟，早又飘零近。今岁花期消息定，只愁风雨无凭准。'},
    {t:'蝶恋花·喜鹊桥成催凤驾',a:'晏几道〔宋代〕',c:'喜鹊桥成催凤驾。天为欢迟，乞与初凉夜。乞巧双蛾加意画。玉钩斜傍西南挂。\n分钿擘钗凉叶下。香袖凭肩，谁记当时话。路隔银河犹可借。世间离恨何年罢。'},
    {t:'蝶恋花·萧瑟兰成看老去',a:'纳兰性德〔清代〕',c:'萧瑟兰成看老去。为怕多情，不作怜花句。阁泪倚花愁不语，暗香飘尽知何处。\n重到旧时明月路。袖口香寒，心比秋莲苦。休说生生花里住，惜花人去花无主。'},
    {t:'蝶恋花·晓日窥轩双燕语',a:'秦观〔宋代〕',c:'晓日窥轩双燕语，似与佳人，共无春将暮。屈指艳阳都几许？可无时霎闲风雨。\n流水落花无问处，只有飞云，冉冉来还去。持酒劝云云且住，凭君碍断春归路。'},
    {t:'蝶恋花·笑艳秋莲生绿浦',a:'晏几道〔宋代〕',c:'笑艳秋莲生绿浦。红脸青腰，旧识凌波女。照影弄妆娇欲语。西风岂是繁花主。\n可恨良辰天不与。才过斜阳，又是黄昏雨。朝落暮开空自许。竟无人解知心苦。'},
    {t:'蝶恋花·辛苦最怜天上月',a:'纳兰性德〔清代〕',c:'辛苦最怜天上月，一昔如环，昔昔都成玦。若似月轮终皎洁，不辞冰雪为卿热。\n无那尘缘容易绝，燕子依然，软踏帘钩说。唱罢秋坟愁未歇，春丛认取双栖蝶。'},
    {t:'蝶恋花·眼底风光留不住',a:'纳兰性德〔清代〕',c:'眼底风光留不住，和暖和香，又上雕鞍去。欲倩烟丝遮别路，垂杨那是相思树。\n惆怅玉颜成间阻，何事东风，不作繁华主。断带依然留乞句，斑骓一系无寻处。'},
    {t:'蝶恋花·一霎秋风惊画扇',a:'晏殊〔宋代〕',c:'一霎秋风惊画扇。艳粉娇红，尚拆荷花面。草际露垂虫响遍。珠帘不下留归燕。\n扫掠亭台开小院。四坐清欢，莫放金杯浅。龟鹤命长松寿远。阳春一曲情千万。'},
    {t:'蝶恋花·又到绿杨曾折处',a:'纳兰性德〔清代〕',c:'又到绿杨曾折处，不语垂鞭，踏遍清秋路。衰草连天无意绪，雁声远向萧关去。\n不恨天涯行役苦，只恨西风，吹梦成今古。明日客程还几许，沾衣况是新寒雨。'},
    {t:'蝶恋花·鱼尾霞生明远树',a:'周邦彦〔宋代〕',c:'鱼尾霞生明远树。翠壁粘天，玉叶迎风举。一笑相逢蓬海路。人间风月如尘土。\n剪水双眸云鬓吐。醉倒天瓢，笑语生青雾。此会未阑须记取。桃花几度吹红雨。'},
    {t:'蝶恋花·雨霰疏疏经泼火',a:'苏轼〔宋代〕',c:'雨霰疏疏经泼火。巷陌秋千，犹红清明过。杏子梢头香蕾破。淡红褪白胭脂涴。\n苦被多情相折挫。病绪厌厌，浑似年时个。绕遍回廊还独坐。月笼云暗重门锁。'},
    {t:'蝶恋花·禹庙兰亭今古路',a:'陆游〔宋代〕',c:'禹庙兰亭今古路。一夜清霜，染尽湖边树。鹦鹉杯深君莫诉。他时相遇知何处。\n冉冉年华留不住。镜里朱颜，毕竟消磨去。一句丁宁君记取。神仙须是闲人做。'},
    {t:'蝶恋花·玉碗冰寒消暑气',a:'晏殊〔宋代〕',c:'玉碗冰寒消暑气。碧簟纱厨，向午朦胧睡。莺舌惺松如会意。无端画扇惊飞起。\n雨后初凉生水际。人面荷花，的的遥相似。眼看红芳犹抱蕊。业中已结新莲子。'},
    {t:'蝶恋花·月下醉书雨岩石浪',a:'辛弃疾〔宋代〕',c:'九畹芳菲兰佩好。空谷无人，自怨蛾眉巧。宝瑟泠泠千古调。朱丝弦断知音少。\n冉冉年华吾自老。水满汀洲，何处寻芳草。唤起湘累歌未了。石龙舞罢松风晓。'},
    {t:'蝶恋花·赠杨柔卿',a:'张炎〔宋代〕',c:'颇爱杨琼妆淡注。犹理螺鬟，扰扰松云聚。两翦秋痕流不去。佯羞却把周郎顾。\n欲诉闲愁无说处。几过莺帘，听得间关语。昨夜月明香暗度。相思忽到梅花树。'},
    {t:'蝶恋花·伫倚危楼风细细',a:'柳永〔宋代〕',c:'伫倚危楼风细细，望极春愁，黯黯生天际。草色烟光残照里，无言谁会凭阑意。\n拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。'},
    {t:'蝶恋花·准拟春来消寂寞',a:'纳兰性德〔清代〕',c:'准拟春来消寂寞。愁雨愁风，翻把春担阁。不为伤春情绪恶，为怜镜里颜非昨。\n毕竟春光谁领略。九陌缁尘，抵死遮云壑。若得寻春终遂约，不成长负东君诺？'},
    {t:'蝶恋花·紫菊初生朱槿坠',a:'晏殊〔宋代〕',c:'紫菊初生朱槿坠。月好风清，渐屏中秋意。更漏乍长天似水。银屏展尽遥山翠。\n绣幕卷波香引穗。急管繁弦，共庆人间瑞。满酌玉杯萦舞袂。南春祝寿千千岁。'},
    {t:'蝶恋花·紫燕双飞深院静',a:'秦观〔宋代〕',c:'紫燕双飞深院静。簟枕纱厨，睡起娇如病。一线碧烟萦藻井。小鬟茶进龙香饼。\n拂拭菱花看宝镜。玉指纤纤，捻唾撩云鬓。闲折海榴过翠径。雪猫戏扑风花影。'},
    {t:'蝶恋花·醉别西楼醒不记',a:'晏几道〔宋代〕',c:'醉别西楼醒不记。春梦秋云，聚散真容易。斜月半窗还少睡。画屏闲展吴山翠。\n衣上酒痕诗里字。点点行行，总是凄凉意。红烛自怜无好计。夜寒空替人垂泪。'},
    {t:'蝶恋花·昨夜秋风来万里',a:'苏轼〔宋代〕',c:'昨夜秋风来万里。月上屏帏，冷堪人衣袂。有客抱衾愁不寐。那堪玉漏长如岁。\n羁舍留连归计未。梦断魂销，一枕相思泪。衣带渐宽无别意。新书报我添憔悴。'},
    {t:'蝶三首',a:'李商隐〔唐代〕',c:'初来小苑中，稍与琐闱通。远恐露尘断，轻忧艳雪融。\n只知防皓露，不觉逆尖风。回首双飞燕，乘玉入绮栊。\n长眉画了绣帘开，碧玉行收白玉台。\n为问翠钗钗上凤，不知香颈为谁回。\n寿阳公主嫁玉妆，八字宫眉捧额黄。\n见我佯羞频照影，不知身属冶游郎。'},
    {t:'丁督护歌',a:'李白〔唐代〕',c:'云阳上征去，两岸饶商贾。\n吴牛喘月时，拖船一何苦。\n水浊不可饮，壶浆半成土。\n一唱都护歌，心摧泪如雨。\n万人凿盘石，无由达江浒。\n君看石芒砀，掩泪悲千古。'},
    {t:'丁亥正月新晴晚步二首',a:'杨万里〔宋代〕',c:'嫩水春来别样光，草芽绿甚却成黄。\n东风似与行人便，吹尽寒云放夕阳。'},
    {t:'丁香结·商调',a:'周邦彦〔宋代〕',c:'苍藓沿阶，冷萤黏屋，庭树望秋先陨。渐雨凄风迅。淡暮色，倍觉园林清润。汉姬纨扇在，重吟玩、弃掷未忍。登山临水，此恨自古，销磨不尽。\n牵引。记试酒归时，映月同看雁阵。宝幄香缨，熏炉象尺，夜寒灯晕。谁念留滞故国，旧事劳方寸。唯丹青相伴，那更尘昏蠹损。'},
    {t:'丁香结商调',a:'周邦彦〔宋代〕',c:'苍藓沿阶，冷萤粘屋，庭树望秋先陨。渐雨凄风迅。\n澹暮色，倍觉园林清润。汉姬纨扇在，重吟玩、弃掷未忍。\n登山临水，此恨自古，销磨不尽。\n牵引。记试酒归时，映月同看雁阵。宝幄香缨，熏炉象尺，夜寒灯晕。\n谁念留滞故国，旧事劳方寸。唯丹青相伴，那更尘昏蠹损。'},
    {t:'定风波',a:'黄庭坚〔宋代〕',c:'上客休辞酒浅深。素儿歌里细听沈。粉面不须歌扇掩，闲静，一声一字总关心。\n花外黄鹂能密语。休诉。有花能得几时斟。画作远山临碧水。明媚。梦为胡蝶去登临。'},
    {t:'定风波·把酒花前欲问溪',a:'黄庭坚〔宋代〕',c:'把酒花前欲问溪。问溪何事晚声悲。名利往来人尽老。谁道。溪声今古有休时。\n且共玉人斟玉醑。休诉。笙歌一曲黛眉低。情似长溪长不断。君看。水声东去月轮西。'},
    {t:'定风波·次高左藏使君韵',a:'黄庭坚〔宋代〕',c:'万里黔中一漏天，屋居终日似乘船。及至重阳天也霁，催醉，鬼门关外蜀江前。\n莫笑老翁犹气岸，君看，几人黄菊上华颠？戏马台南追两谢，驰射，风流犹拍古人肩。'},
    {t:'定风波·杜鹃花',a:'辛弃疾〔宋代〕',c:'百紫千红过了春。杜鹃声苦不堪闻。却解啼教春小住。风雨。空山招得海棠魂。\n一似蜀宫当日女。无数。猩猩血染赭罗巾。毕竟花开谁作主。记取。大都花属惜花人。'},
    {t:'定风波·感旧',a:'苏轼〔宋代〕',c:'莫怪鸳鸯绣带长，腰轻不胜舞衣裳。薄幸只贪游冶去，何处，垂杨系马恣轻狂。\n花谢絮飞春又尽，堪恨。断弦尘管伴啼妆。不信归来但自看，怕见，为郎憔悴却羞郎。'},
    {t:'定风波·红梅',a:'苏轼〔宋代〕',c:'好睡慵开莫厌迟。自怜冰脸不时宜。偶作小红桃杏色，闲雅，尚馀孤瘦雪霜姿。\n休把闲心随物态，何事，酒生微晕沁瑶肌。诗老不知梅格在，吟咏，更看绿叶与青枝。'},
    {t:'定风波·进贤道上见梅赠王伯寿',a:'陆游〔宋代〕',c:'敧帽垂鞭送客回。小桥流水一枝梅。衰病逢春都不记。谁谓。幽香却解逐人来。\n安得身闲频置酒。携手。与君看到十分开。少壮相从今雪鬓。因甚。流年羁恨两相催。'},
    {t:'定风波·两两轻红半晕腮',a:'苏轼〔宋代〕',c:'十月九日，孟亨之置酒秋香亭。有双拒霜，独向君猷而开，坐客喜笑，以为非使君莫可当此花，故作是篇。\n两两轻红半晕腮，依依独为使君回。若道使君无此意，何为，双花不向别人开。\n但看低昂烟雨里，不已。劝君休诉十分杯。更问尊前狂副使。来岁。花开时节与谁来。'},
    {t:'定风波·莫听穿林打叶声',a:'苏轼〔宋代〕',c:'三月七日，沙湖道中遇雨，雨具而去，同行皆狼狈，余独不觉。已而遂晴，故作此'},
    {t:'定风波·莫倚能歌敛黛眉',a:'周邦彦〔宋代〕',c:'莫倚能歌敛黛眉。此歌能有几声知。他日相逢花月底。重理。好声须记得来时。\n苦恨城头更漏永，无情岂解惜分飞。休诉金尊推玉臂。从醉。明朝有酒遣谁持。'},
    {t:'定风波·暮春漫兴',a:'辛弃疾〔宋代〕',c:'少日春怀似酒浓，插花走马醉瓯钟。老去逢春如病酒，唯有，茶瓯香篆小帘栊。\n卷尽残花风未定，休恨，花开元自要春风。试问春归谁得见？飞燕，来时相遇夕阳中。'},
    {t:'定风波·山路风来草木香',a:'辛弃疾〔宋代〕',c:'药名招婺源马荀仲游雨岩。马善医。\n山路风来草木香。雨余凉意到胡床。泉石膏肓吾已甚，多病，提防风月费篇章。\n孤负寻常山简醉，独自，故应知子草玄忙。湖海早知身汗漫，谁伴？只甘松竹共凄凉。'},
    {t:'定风波·席上送范廓之游建康',a:'辛弃疾〔宋代〕',c:'听我尊前醉后歌，人生无奈别情何。但使情亲千里近，须信。无情对面是山河。\n寄语石头城下水。居士，而今浑不怕风波。借使未如鸥鸟伴；经惯，也应学得老渔蓑。'},
    {t:'定风波·重阳',a:'苏轼〔宋代〕',c:'与客携壶上翠微，江涵秋影雁初飞，尘世难逢开口笑，年少，菊花须插满头归。\n酩酊但酬佳节了，云峤，登临不用怨斜晖。古往今来谁不老，多少，牛山何必更沾衣。'},
    {t:'定风波·伫立长堤',a:'柳永〔宋代〕',c:'伫立长堤，淡荡晚风起。骤雨歇，极目萧疏，塞柳万株，掩映箭波千里。走舟车向此，人人奔名竞利。念荡子、终日驱驱，争觉乡关转迢递。\n何意。绣阁轻抛，锦字难逢，等闲度岁。奈泛泛旅迹，厌厌病绪，迩来谙尽，宦游滋味。此情怀、纵写香笺，凭谁与寄。算孟光、争得知我，继日添憔悴。'},
    {t:'定风波·自春来惨绿愁红',a:'柳永〔宋代〕',c:'自春来惨绿愁红，芳心是事可可。日上花梢，莺穿柳带，犹压香衾卧。暖酥消、腻云亸，终日厌厌倦梳裹。无那。恨薄情一去，音书无个。\n早知恁么，悔当初、不把雕鞍锁。向鸡窗，只与蛮笺象管，拘束教吟课。镇相随、莫抛躲，针线闲拈伴伊坐。和我。免使年少，光阴虚过。'},
    {t:'定风波·自和',a:'辛弃疾〔宋代〕',c:'金印累累佩陆离。河梁更赋断肠诗。莫拥旌旗真个去。何处。玉堂元自要论思。\n且约风流三学士。同醉。春风看试几枪旗。从此酒酣明月夜。耳热。那边应是说侬时。'},
    {t:'定风波·昨夜山公倒载归',a:'辛弃疾〔宋代〕',c:'昨夜山公倒载归，儿童应笑醉魂泥。试与扶头浑未醒，休问，梦魂犹在葛家溪。\n欲觅醉乡今古路，知处：温柔东畔白云西。起向绿窗高处看，题遍，刘伶元自有贤妻。'},
    {t:'定林',a:'王安石〔宋代〕',c:'漱甘凉病齿，坐旷息烦襟。\n因脱水边屦，就敷岩上衾。\n但留云对宿，仍值月相寻。\n真乐非无寄，悲虫亦好音。'},
    {t:'定林所居',a:'王安石〔宋代〕',c:'屋绕湾溪竹绕山，溪山却在白云间。\n临溪放艇依山坐，溪鸟山花共我闲。'},
    {t:'定僧',a:'元稹〔唐代〕',c:'落魄闲行不著家，遍寻春寺赏年华。\n野僧偶向花前定，满树狂风满树花。'},
    {t:'定西番·海燕欲飞调羽',a:'温庭筠〔唐代〕',c:'海燕欲飞调羽。萱草绿，杏花红，隔帘拢。\n双鬓翠霞金缕，一枝春艳浓。楼上月明三五，琐窗中。'},
    {t:'定西番·汉使昔年离别',a:'温庭筠〔唐代〕',c:'汉使昔年离别。攀弱柳，折寒梅，上高台。\n千里玉关春雪，雁来人不来。羌笛一声愁绝，月徘徊。'},
    {t:'定西番·细雨晓莺春晚',a:'温庭筠〔唐代〕',c:'细雨晓莺春晚。人似玉，柳如眉，正相思。\n罗幕翠帘初卷，镜中花一枝。肠断塞门消息，雁来稀。'},
    {t:'东阿王',a:'李商隐〔唐代〕',c:'国事分明属灌均，西陵魂断夜来人。\n君王不得为天子，半为当时赋洛神。'},
    {t:'东陂遇雨，率尔贻谢南池',a:'孟浩然〔唐代〕',c:'田家春事起，丁壮就东陂。\n殷殷雷声作，森森雨足垂。\n海虹晴始见，河柳润初移。\n予意在耕凿，因君问土宜。'},
    {t:'东兵长句十韵',a:'杜牧〔唐代〕',c:'上党争为天下脊，邯郸四十万秦坑。狂童何者欲专地，\n圣主无私岂玩兵。玄象森罗摇北落，诗人章句咏东征。\n雄如马武皆弹剑，少似终军亦请缨。屈指庙堂无失策，\n垂衣尧舜待升平。羽林东下雷霆怒，楚甲南来组练明。\n即墨龙文光照曜，常山蛇阵势纵横。落雕都尉万人敌，\n黑槊将军一鸟轻。渐见长围云欲合，可怜穷垒带犹萦。\n凯歌应是新年唱，便逐春风浩浩声。'},
    {t:'东城高且长',a:'佚名〔两汉〕',c:'东城高且长，逶迤自相属。\n回风化地起，秋草萋已绿。\n四时更变化，岁暮一何速！\n晨风怀苦心，蟋结伤局促。\n荡涤放情志，何为自结束！\n燕赵多佳人，美者颜如玉。\n被服罗裳衣，当户理清曲。\n音响一何悲！弦急知柱促。\n驰情整巾带，沉吟聊踯躅。\n思为双飞燕，衔泥巢君屋。'},
    {t:'东城桂三首',a:'白居易〔唐代〕',c:'苏之东城，古吴都城也。今为樵牧之场。有桂一株，生乎城下，惜其不得地，因赋三绝句以唁之。\n子堕本从天竺寺，根盘今在阖闾城。\n当时应逐南风落，落向人间取次生。\n霜雪压多虽不死，荆榛长疾欲相埋。\n长忧落在樵人手，卖作苏州一束柴。\n遥知天上桂花孤，试问嫦娥更要无。\n月宫幸有闲田地，何不中央种两株。'},
    {t:'东都送郑处诲校书归上都',a:'杜牧〔唐代〕',c:'悠悠渠水清，雨霁洛阳城。槿堕初开艳，蝉闻第一声。\n故人容易去，白发等闲生。此别无多语，期君晦盛名。'},
    {t:'东方半明',a:'韩愈〔唐代〕',c:'东方半明大星没，独有太白配影月。嗟尔影月勿相疑，\n同光共影须臾期。影月晖晖，太白睒睒。\n鸡三号，更五点。'},
    {t:'东方有一士',a:'文天祥〔宋代〕',c:'万金结游侠，千金买歌舞。\n丹春役第宅，从者塞衢路。\n身为他一役，名声落尘土。\n他一一何伤。\n他一一何伤，富贵还自苦。\n东方有一士，败垣半风雨。\n不识丝与竹，飞雀满庭户。\n一饭或不饱，夜梦无惊寤。\n此事古来多，难与俗一语。'},
    {t:'东风齐着力·电急流光',a:'纳兰性德〔清代〕',c:'电急流光，天生薄命，有泪如潮。年为欢谑，到底总无聊。欲谱频年离恨，言已尽、恨未曾消。凭谁迢，一天愁绪，按出琼箫。\n往事水迢迢，窗前月、几番空照魂销。旧欢新梦，雁齿小红桥。最是烧灯时候，宜春髻、酒暖蒲萄。凄凉煞，五枝青玉，风雨飘飘。'},
    {t:'东关二首·其二',a:'陆游〔宋代〕',c:'烟水苍茫西复东，扁舟又系柳阴中。\n三更酒醒残灯在，卧听萧萧雨打篷。'},
    {t:'东光',a:'佚名〔两汉〕',c:'东光乎，苍梧何不乎。\n苍梧多腐粟，无益诸军粮。\n诸军游荡子，早行多悲伤。'},
    {t:'东归晚次潼关怀古',a:'岑参〔唐代〕',c:'暮春别乡树，晚景低津楼。\n伯夷望首阳，欲往无轻舟。\n遂登关城望，下见洪河流。\n自从巨灵开，流血千万秋。\n行行潘生赋，赫赫曹公谋。\n川上多往事，凄凉满空洲。'},
    {t:'东还',a:'李商隐〔唐代〕',c:'自有仙才自不知，十年长梦采华芝。\n秋风动地黄云暮，归去嵩阳寻旧师。'},
    {t:'东湖新竹',a:'陆游〔宋代〕',c:'插棘编篱谨护持，养成寒碧映涟漪。\n清风掠地秋先到，赤日行天午不知。\n解箨时闻声簌簌，放梢初见叶离离。\n官闲我欲频来此，枕簟仍教到处随。'},
    {t:'东郊',a:'韦应物〔唐代〕',c:'吏舍跼终年，出郊旷清曙。\n杨柳散和风，青山澹吾虑。\n依丛适自憩，缘涧还复去。\n微雨霭芳原，春鸠鸣何处。\n乐幽心屡止，遵事迹犹遽。\n终罢斯结庐，慕陶直可庶。'},
    {t:'东郊行',a:'温庭筠〔唐代〕',c:'斗鸡台下东西道，柳覆班骓蝶萦草。坱霭韶容锁澹愁，\n青筐叶尽蚕应老。绿渚幽香生白蘋，差差小浪吹鱼鳞。\n王孙骑马有归意，林彩着空如细尘。安得人生各相守，\n烧船破栈休驰走。世上方应无别离，路傍更长千株柳。'},
    {t:'东栏梨花',a:'苏轼〔宋代〕',c:'梨花淡白柳深青，柳絮飞时花满城。\n惆怅东栏一株雪，人生看得几清明。'},
    {t:'东楼',a:'杜甫〔唐代〕',c:'万里流沙道，西征过北门。\n但添新战骨，不返旧征魂。\n楼角临风迥，城阴带水昏。\n传声看驿使，送节向河源。'},
    {t:'东鲁见狄博通',a:'李白〔唐代〕',c:'去年别我向何处，有人传道游江东。\n谓言挂席度沧海，却来应是无长风。'},
    {t:'东鲁门泛舟二首',a:'李白〔唐代〕',c:'日落沙明天倒开，波摇石动水萦回。\n轻舟泛月寻溪转，疑是山阴雪后来。\n水作青龙盘石堤，桃花夹岸鲁门西。\n若教月下乘舟去，何啻风流到剡溪。'},
    {t:'东门行',a:'佚名〔两汉〕',c:'出东门，不顾归。\n来入门，怅欲悲。\n衣中无斗米储，还视架上无悬衣。\n拔剑东门去，舍中儿母牵衣餔：\n“他家但愿富贵，贱妾与君共餔糜。\n上用仓浪天故，下当用此黄口儿。今非！”\n“咄！行！吾去为迟！白发时下难久居。”'},
    {t:'东平别前卫县李寀少府',a:'高适〔唐代〕',c:'黄鸟翩翩杨柳垂，春风送客使人悲。\n怨别自惊千里外，论交却忆十年时。\n云开汶水孤帆远，路绕梁山匹马迟。\n此地从来可乘兴，留君不住益凄其。'},
    {t:'东平留赠狄司马',a:'高适〔唐代〕',c:'古人无宿诺，兹道以为难。\n万里赴知己，一言诚可叹。\n马蹄经月窟，剑术指楼兰。\n地出北庭尽，城临西海寒。\n森然瞻武库，则是弄儒翰。\n入幕绾银绶，乘轺兼铁冠。\n练兵日精锐，杀敌无遗残。\n献捷见天子，论功俘可汗。\n激昂丹墀下，顾盼青云端。\n谁谓纵横策，翻为权势干。\n将军既坎壈，使者亦辛酸。\n耿介挹三事，羁离从一官。\n知君不得意，他日会鹏抟。'},
    {t:'东平路中遇大水',a:'高适〔唐代〕',c:'天灾自古有，昏垫弥今秋。霖霪溢川原，澒洞涵田畴。\n指途适汶阳，挂席经芦洲。永望齐鲁郊，白云何悠悠。\n傍沿钜野泽，大水纵横流。虫蛇拥独树，麋鹿奔行舟。\n稼穑随波澜，西成不可求。室居相枕藉，蛙黾声啾啾。\n仍怜穴蚁漂，益羡云禽游。农夫无倚著，野老生殷忧。\n圣主当深仁，庙堂运良筹。仓廪终尔给，田租应罢收。\n我心胡郁陶，征旅亦悲愁。纵怀济时策，谁肯论吾谋。'},
    {t:'东平路作三首',a:'高适〔唐代〕',c:'南图适不就，东走岂吾心。\n索索凉风动，行行秋水深。\n蝉鸣木叶落，兹夕更愁霖。\n明时好画策，动欲干王公。\n今日无成事，依依亲老农。\n扁舟向何处，吾爱汶阳中。\n清旷凉夜月，裴回孤客舟。\n渺然风波上，独爱前山秋。\n秋至复摇落，空令行者愁。'},
    {t:'东平路作三首其二',a:'高适〔唐代〕',c:'明时好画策，动欲干王公。今日无成事，依依亲老农。\n扁舟向何处？吾爱汶阳中。'},
    {t:'东坡',a:'苏轼〔宋代〕',c:'雨洗东坡月色清，市人行尽野人行。\n莫嫌荦确坡头路，自爱铿然曳杖声。'},
    {t:'东坡食汤饼',a:'陆游〔宋代〕',c:'吕周辅言：东坡先生与黄谓公汤迁，相遇于梧、藤间。道旁有鬻汤饼者，共买食之。恶不可食。黄谓置箸而叹，东坡已尽之矣。徐谓黄谓曰：“九三郎，尔尚欲咀嚼耶？”大笑而起。秦少游闻之，曰：“此先生‘饮酒但饮湿’而已。”'},
    {t:'东坡守杭',a:'秦观〔宋代〕',c:'十里荷花菡萏初，我公所至有西湖。\n欲将公事湖中了，见说官闲事亦无。'},
    {t:'东坡志林·人物（节选）',a:'苏轼〔宋代〕',c:'郗超虽为桓温腹心，以其父愔忠于王室，不知之。将死，出一箱付门生，曰：“本欲焚之，恐公年尊，必以相伤为毙。我死后，公若大损眠食，可呈此箱，不尔使烧之。”愔后果哀悼成疾，门生以指呈之，则悉与温往反密计。愔大怒曰：“小子死晚矣！”更不复哭矣。若方回者，可谓忠臣矣，当与石碏比。然超谓之不孝，可乎？使超知君子之孝，则不从温矣。东坡先生曰：超，小人之孝也。'},
    {t:'东山吟',a:'李白〔唐代〕',c:'携妓东土山，怅然悲谢安。\n我妓今朝如花月，他妓古坟荒草寒。\n白鸡梦后三百岁，洒酒浇君同所欢。\n酣来自作青海舞，秋风吹落紫绮冠。\n彼亦一时，此亦一时，浩浩洪流之咏何必奇？'},
    {t:'东屯北崦',a:'杜甫〔唐代〕',c:'盗贼浮生困，诛求异俗贫。\n空村惟见鸟，落日未逢人。\n步壑风吹面，看松露滴身。\n远山回白首，战地有黄尘。'},
    {t:'东魏童谣',a:'佚名〔隋代〕',c:'可怜青雀子，飞来邺城里。羽翮垂欲成，化作鹦鹉子。'},
    {t:'东溪玩月',a:'王维〔唐代〕',c:'月从断山口，遥吐柴门端。\n万木白空霁，流阴中夜攒。\n光连虚象白，气与风露寒。\n谷静秋泉响，岩深青霭残。\n清灯入幽梦，破影抱空峦。\n恍惚琴窗里，松溪晓思难。'},
    {t:'东下三旬苦于风土马上戏作',a:'李商隐〔唐代〕',c:'路绕函关东复东，身骑征马逐惊蓬。\n天池辽阔谁相待，日日虚乘九万风。'},
    {t:'东征答朝臣',a:'陈子昂〔唐代〕',c:'平生白云意，疲薾愧为雄。君王谬殊宠，旌节此从戎。\n挼绳当系虏，单马岂邀功。孤剑将何托，长谣塞上风。'},
    {t:'东征答朝臣相送',a:'陈子昂〔唐代〕',c:'平生白云意，疲苶愧为雄。\n君王谬殊宠，旌节此从戎。\n挼绳当系虏，单马岂邀功。\n孤剑将何托，长谣塞上风。'},
    {t:'冬晴',a:'陆游〔宋代〕',c:'吴中霜雪晚，初冬正佳时。\n丹枫空辞林，黄菊犹残枝。\n鸣雁过长空，纤鳞泳清池。\n气和空重裘，临水照须眉。\n悠然据石坐，亦复出门嬉。\n野老荷鉏至，一笑成幽期。'},
    {t:'冬晴',a:'文天祥〔宋代〕',c:'北国天寒少，南方地气来。\n年光如箭去，世事正轮回。\n可怪新祈雪，相思久别梅。\n夜阑灯坐暗，独自拨残灰。'},
    {t:'冬日',a:'孟郊〔唐代〕',c:'老人行人事，百一不及周。冻马过蹄吃，陟卓难自收。\n短景仄飞过，午光不上头。少壮日与辉，衰老日与愁。\n日愁疑在日，岁箭迸如雠。万事有何味，一生虚自囚。\n不知文字利，到死空遨游。'},
    {t:'冬日晨兴寄乐天',a:'刘禹锡〔唐代〕',c:'庭树晓禽动，郡楼残点声。\n灯挑红烬落，酒暖白光生。\n发少嫌梳利，颜衰恨镜明。\n独吟谁应和，须寄洛阳城。'},
    {t:'冬日归旧山',a:'李白〔唐代〕',c:'未洗染尘缨，归来芳草平。\n一条藤径绿，万点雪峰晴。\n地冷叶先尽，谷寒云不行。\n嫩篁侵舍密，古树倒江横。\n白犬离村吠，苍苔壁上生。\n穿厨孤雉过，临屋旧猿鸣。\n木落禽巢在，篱疏兽路成。\n拂床苍鼠走，倒箧素鱼惊。\n洗砚修良策，敲松拟素贞。\n此时重一去，去合到三清。'},
    {t:'冬日梅溪送裴方舟宣州',a:'皎然〔唐代〕',c:'平明匹马上村桥，花发梅溪雪未消。\n日短天寒愁送客，楚山无限路遥遥。'},
    {t:'冬日山行过薛征君',a:'皎然〔唐代〕',c:'我行倦修坂，四顾无平陆。雨霁鸣鹰鹯，天寒聚麋鹿。\n幽人访名士，家在南冈曲。菜实萦小园，稻花绕山屋。\n深居寡忧悔，胜境怡耳目。徵心尚与我，永言谢浮俗。'},
    {t:'冬日送颜延之明府抚州觐叔父',a:'皎然〔唐代〕',c:'临川千里别，惆怅上津桥。日暮渺归尽，山空雪未消。\n乡云心渺渺，楚水路遥遥。林下方欢会，山中独寂寥。\n天寒惊断雁，江信望回潮。岁晚流芳歇，思君在此宵。'},
    {t:'冬日题智门寺北楼',a:'杜牧〔唐代〕',c:'满怀多少是恩酬，未见功名已白头。\n不为寻山试筋力，岂能寒上背云楼。'},
    {t:'冬日天井西峰张炼师所居',a:'皎然〔唐代〕',c:'采薪逢野泉，渐见栖闲所。坎坎隐上声，幽幽林中语。\n仙乡何代隐，乡服言亦楚。开水净药苗，扫雪候隐侣。\n零叶聚败篱，幽花积寒渚。冥冥孤鹤性，天外思轻举。'},
    {t:'冬日游览',a:'王维〔唐代〕',c:'步出城东门，试骋千里目。\n青山郸苍林，赤日团平陆。\n渭北走邯郸，关东出函谷。\n秦地万方会，来朝九州牧。\n鸡鸣咸阳中，冠盖相追逐。\n丞相过列侯，群公饯光禄。\n相如方老病，独归茂陵宿。'},
    {t:'冬日有怀李白',a:'杜甫〔唐代〕',c:'寂寞书斋里，终朝独尔思。\n更寻嘉树传，不忘角弓诗。\n短褐风霜入，还丹日月迟。\n未因乘兴去，空有鹿门期。'},
    {t:'冬晚对雪忆胡处士家',a:'王维〔唐代〕',c:'寒更传晓箭，清镜览衰颜。\n隔牖风惊竹，开门雪满山。\n洒空深巷静，积素广庭闲。\n借问袁安舍，翛然尚闭关。'},
    {t:'冬夕',a:'岑参〔唐代〕',c:'浩汗霜风刮天地，温泉火井无生意。\n泽国龙蛇冻不伸，南山瘦柏消残翠。'},
    {t:'冬宵家会饯李郎司兵赴同州',a:'岑参〔唐代〕',c:'急管杂青丝，玉瓶金屈卮。寒天高堂夜，扑地飞雪时。\n贺君关西掾，新绶腰下垂。白面皇家郎，逸翮青云姿。\n明旦之官去，他辰良会稀。惜别冬夜短，务欢杯行迟。\n季女犹自小，老夫未令归。且看匹马行，不得鸣凤飞。\n昔岁到冯翊，人烟接京师。曾上月楼头，遥见西岳祠。\n沙苑逼官舍，莲峰压城池。多暇或自公，读书复弹棋。\n州县信徒劳，云霄亦可期。应须力为政，聊慰此相思。'},
    {t:'冬夜',a:'韦应物〔唐代〕',c:'杳杳日云夕，郁结谁为开。单衾自不暖，霜霰已皑皑。\n晚岁沦夙志，惊鸿感深哀。深哀当何为，桃李忽凋摧。\n帏帐徒自设，冥寞岂复来。平生虽恩重，迁去托穷埃。\n抱此女曹恨，顾非高世才。振衣中夜起，河汉尚裴回。'},
    {t:'冬夜读书示子聿',a:'陆游〔宋代〕',c:'古人学问无遗力，少壮工夫老始成。\n纸上得来终觉浅，绝知此事要躬行。'},
    {t:'冬夜书怀',a:'王维〔唐代〕',c:'冬宵寒且永，夜漏宫中发。\n草白霭繁霜，木衰澄清月。\n丽服映颓颜，朱灯照华发。\n汉家方尚少，顾影惭朝谒。'},
    {t:'冬夜宿司空曙野居，因寄酬赠',a:'韦应物〔唐代〕',c:'南北与山邻，蓬庵庇一身。繁霜疑有雪，荒草似无人。\n遂性在耕稼，所交唯贱贫。何掾张椽傲，每重德璋亲。'},
    {t:'冬夜闻虫',a:'白居易〔唐代〕',c:'虫声冬思苦于秋，不解愁人闻亦愁。\n我是老翁听不畏，少年莫听白君头。'},
    {t:'冬夜醉宿龙门觉起言志',a:'李白〔唐代〕',c:'醉来脱宝剑，旅憩高堂眠。\n中夜忽惊觉，起立明灯前。\n开轩聊直望，晓雪河冰壮。\n哀哀歌苦寒，郁郁独惆怅。\n傅说板筑臣，李斯鹰犬人。\n欻起匡社稷，宁复长艰辛。\n而我胡为者？叹息龙门下。\n富贵未可期，殷忧向谁写？\n去去泪满襟，举声梁甫吟。\n青云当自致，何必求知音？'},
    {t:'冬雨不止',a:'朱熹〔宋代〕',c:'忽忽时序改，白日藏光辉。重阴润九野，小雨纷微微。\n苍山寒气深，高林霜叶稀。田家秋成意，落落乖所期。\n旷望独兴怀，戚戚愁寒饥。事至当复遣，且掩荒园扉。'},
    {t:'冬至',a:'杜甫〔唐代〕',c:'年年至日长为客，忽忽穷愁泥杀人。\n江上形容吾独老，天边风俗自相亲。\n杖藜雪后临丹壑，鸣玉朝来散紫宸。\n心折此时无一寸，路迷何处见三秦。'},
    {t:'冬至',a:'王安石〔宋代〕',c:'都城开博路，佳节一阳生。\n喜见儿童色，欢传市井声。\n幽闲亦聚集，珍丽各携擎。\n却忆他年事，关商闭不行。'},
    {t:'冬至',a:'文天祥〔宋代〕',c:'书云今日事，梦破晓鸣钟。\n家祸三生劫，年愁两度冬。\n江山乏小草，霜雪见孤松。\n春色蒙泉里，烟芜几万重。'},
    {t:'冬至后过吴、张二子檀溪别业',a:'孟浩然〔唐代〕',c:'卜筑因自然，檀溪不更穿。园庐对友接，水竹数家连。\n直与南山对，非关选地偏。草堂时偃曝，兰所日周旋。\n外事情都远，中流性所便。闲垂太公钓，兴发子猷船。\n余亦幽栖者，经过窃慕焉。梅花残腊月，柳色半春天。\n鸟泊随阳雁，鱼藏缩项鳊。停杯问山简，何似习池边。'},
    {t:'冬至日独游吉祥寺',a:'苏轼〔宋代〕',c:'井底微阳回未回，萧萧寒雨湿枯荄。\n何人更似苏夫子，不是花时肯独来。'},
    {t:'冬至日陪裴端公使君清水堂集',a:'皎然〔唐代〕',c:'亚岁崇佳宴，华轩照渌波。渚芳迎气早，山翠向晴多。\n推往知时训，书祥辨政和。从公惜日短，留赏夜如何。'},
    {t:'冬至日遇京使发寄舍弟',a:'杜牧〔唐代〕',c:'远信初凭双鲤去，他乡正遇一阳生。\n尊前岂解愁家国，辇下唯能忆弟兄。\n旅馆夜忧姜被冷，暮江寒觉晏裘轻。\n竹门风过还惆怅，疑是松窗雪打声。'},
    {t:'冬至宿杨梅馆',a:'白居易〔唐代〕',c:'十一月中长至夜，三千里外远行人。\n若为独宿杨梅馆，冷枕单床一病身。'},
    {t:'冬至夜怀湘灵',a:'白居易〔唐代〕',c:'艳质无由见，寒衾不可亲。\n何堪最长夜，俱作独眠人。'},
    {t:'冬至夜寄京师诸弟兼怀崔都水',a:'韦应物〔唐代〕',c:'理郡无异政，所忧在素餐。徒令去京国，羁旅当岁寒。\n子月生一气，阳景极南端。已怀时节感，更抱别离酸。\n私燕席云罢，还斋夜方阑。邃幕沉空宇，孤灯照床单。\n应同兹夕念，宁忘故岁欢。川途恍悠邈，涕下一阑干。'},
    {t:'董逃歌',a:'佚名〔魏晋〕',c:'承乐世，董逃；\n游四郭，董逃。\n蒙天恩，董逃；\n带金紫，董逃。\n行谢恩，董逃；\n整车骑，董逃。\n垂欲发，董逃；\n与中辞，董逃。\n出西门，董逃；\n瞻宫殿，董逃。\n望京城，董逃；\n日夜绝，董逃。\n心摧伤，董逃。'},
    {t:'冻蝇',a:'杨万里〔宋代〕',c:'隔窗偶见负暄蝇，双脚挼挲弄晓晴。\n日影欲移先会得，忽然飞落别窗声。'},
    {t:'洞庭春色',a:'陆游〔宋代〕',c:'壮岁文章，暮年勋业，自昔误人。算英雄成败，轩裳得失，难如人意，空丧天真。请看邯郸当日梦，待炊罢黄粱徐欠伸。方知道，许多时富贵，何处关身。\n人间定无可意，怎换得、玉鲙丝莼。且钓竿渔艇，笔床茶灶，闲听荷雨，一洗衣尘。洛水秦关千古后，尚棘暗铜驼空怆神。何须更，慕封侯定远，图像麒麟。'},
    {t:'洞庭湖',a:'元稹〔唐代〕',c:'人生除泛海，便到洞庭波。\n驾浪沉西日，吞空接曙河。\n虞巡竟安在，轩乐讵曾过。\n唯有君山下，狂风万古多。'},
    {t:'洞庭湖寄阎九',a:'孟浩然〔唐代〕',c:'洞庭秋正阔，余欲泛归船。莫辨荆吴地，唯馀水共天。\n渺瀰江树没，合沓海潮连。迟尔为舟楫，相将济巨川。'},
    {t:'洞庭秋月行',a:'刘禹锡〔唐代〕',c:'洞庭秋月生湖心，层波万顷如镕金。\n孤轮徐转光不定，游气濛濛隔寒镜。\n是时白露三秋中，湖平月上天地空。\n岳阳楼头暮角绝，荡漾已过君山东。\n山城苍苍夜寂寂，水月逶迤绕城白。\n荡桨巴童歌竹枝，连樯估客吹羌笛。\n势高夜久阴力全，金气肃肃开星躔。\n浮云野马归四裔，遥望星斗当中天。\n天鸡相呼曙霞出，敛影含光让朝日。\n日出喧喧人不闲，夜来清景非人间。'},
    {t:'洞仙歌',a:'晏几道〔宋代〕',c:'春残雨过，绿暗东池道。玉艳藏疏媚赪笑。记当时、已恨飞镜欢疏，那至此，仍苦题花信少。\n连环伊未已，物是人非，月下疏梅似伊好。淡秀色，暗寒香，粲若春容，何心愿、闲花凡草。但莫使、伊随岁华迁，便杳隔秦源，也须能到。'},
    {t:'洞仙歌·乘兴',a:'柳永〔宋代〕',c:'乘兴，闲泛兰舟，渺渺烟波东去。淑气散幽香，满蕙兰汀渚。绿芜平畹，和风轻暖，曲岸垂杨，隐隐隔、桃花圃。芳树外，闪闪酒旗遥举。\n羁旅。渐入三吴风景，水村渔市，闲思更远神京，抛掷幽会小欢何处。不堪独倚危樯，凝情西望日边，繁华地、归程阻。空自叹当时，言约无据。伤心最苦。伫立对、碧云将暮。关河远，怎奈向、此时情绪。'},
    {t:'洞仙歌·丁卯八月病中作',a:'辛弃疾〔宋代〕',c:'贤愚相去，算其间能几。差以毫分缪千里。细思量义利，舜跖之分，孳孳者，等是鸡鸣而起。\n味甘如易坏，岁晚还知，君子之交淡如水。一饷聚飞蚊，其响如雷，深自觉、昨非今是。羡安乐窝中泰和汤，更剧饮，无过半醺而已。'},
    {t:'洞仙歌·观王碧山花外词集有感',a:'张炎〔宋代〕',c:'野鹃啼月，便角巾还第。轻掷诗瓢付流水。最无端、小院寂历春空，门自掩，柳发离离如此。\n可惜欢娱地。雨冷云昏，不见当时谱银字。旧曲怯重翻，总是离愁，泪痕洒、一帘花碎。梦沈沈、知道不归来，尚错问桃根，醉魂醒未。'},
    {t:'洞仙歌·寄茅峰梁中砥',a:'张炎〔宋代〕',c:'中峰壁立，挂飞来孤剑。苍雪纷纷堕晴藓。自当年诗酒，客里相逢，春尚好，鸥散烟波茂苑。\n只今谁最老，种玉人间，消得梅花共清浅。问我入山期，但恐山深，松风把红尘吹断。望蓬莱、知隔几重云，料只隔中间，白云一片。'},
    {t:'洞仙歌·佳景留心惯',a:'柳永〔宋代〕',c:'佳景留心惯。况少年彼此，风情城浅。有笙歌巷陌，绮罗庭院。倾城巧笑如花面。恣雅态、明眸回相盼。同心绾。算国艳仙材，翻恨相逢晚。\n缱绻。洞房悄悄，绣被重重，夜永欢馀，共有海约山盟，记得翠云偷翦。和鸣彩凤于飞燕。间柳径花阴携手遍。情眷恋。向其间、密约轻怜事何限。忍聚散。况已结、深深愿。愿人间天上，暮云朝雨长相见。'},
    {t:'洞仙歌·嘉景',a:'柳永〔宋代〕',c:'嘉景，向少年彼此，争不雨沾云帐。奈傅粉英俊，梦兰品雅。金丝帐暖银屏亚。并粲枕、轻偎轻倚，价娇红姹。算一笑，百琲明珠非价。\n闲暇。每只向、洞房深处，痛怜极宠，似觉些子轻孤，早恁背人沾洒。从来娇多猜讶。更对翦香云，须要深心同写。爱揾了双眉，索人重画。忍孤艳冶。断不等闲轻舍。鸳衾下。愿常恁、好天良夜。'},
    {t:'洞仙歌·泸守王补之生日',a:'黄庭坚〔宋代〕',c:'月中丹桂，自风霜难老。阅尽人间盛衰草。望中秋、才有几日，十分圆，霾风雨，云表常如永昼。\n不得文章力，白首防秋，谁念云中上功守。正注意，得人雄，静扫河山，应难纵、五湖归棹。问持节冯唐几时来，看再策勋名，印窠如斗。'},
    {t:'洞仙歌·咏黄葵',a:'纳兰性德〔清代〕',c:'铅华不御，看道家妆就。问取旁人入时否。为孤情淡韵、判不宜春，矜标格、开向晚秋时候。\n无端轻薄雨，滴损檀心，小叠宫罗镇长皱。何必诉凄清，为爱秋光，被几日、西风吹瘦。便零落、蜂黄也休嫌，且对依斜阳，胜偎红袖。'},
    {t:'洞仙歌·咏柳',a:'苏轼〔宋代〕',c:'江南腊尽，早梅花开后，分付新春与垂柳。细腰肢自有入格风流，仍更是、骨体清英雅秀。\n永丰坊那畔，尽日无人，谁见金丝弄晴昼？断肠是飞絮时，绿叶成阴，无个事、一成消瘦。又莫是东风逐君来，便吹散眉间一点春皱。'},
    {t:'都下送辛大之鄂',a:'孟浩然〔唐代〕',c:'南国辛居士，言归旧竹林。\n未逢调鼎用，徒有济川心。\n予亦忘机者，田园在汉阴。\n因君故乡去，遥寄式微吟。'},
    {t:'都下无忧馆小楼春尽旅怀二首',a:'杨万里〔宋代〕',c:'病眼逢书不敢开，春泥谢客亦无来。\n更无短计销长日，且绕栏干一百回。\n不关老去愿春迟，只恨春归我未归。\n最是杨花欺客子，向人一一作西飞。'},
    {t:'斗百花·满搦宫腰纤细',a:'柳永〔宋代〕',c:'满搦宫腰纤细，年纪方当笄岁。刚被风流沾惹，与合垂杨双髻。初学严妆，如描似削身材，怯雨羞云情意。举措多娇媚。\n争奈心性，未会先怜佳婿。长是夜深，不肯便入鸳被。与解罗裳，盈盈背立银釭，却道你但先睡。'},
    {t:'斗百花·飒飒霜飘鸳瓦',a:'柳永〔宋代〕',c:'飒飒霜飘鸳瓦，翠幕轻寒微透，长门深锁悄悄，满庭秋色将晚。眼看菊蕊，重阳泪落如珠，长是淹残粉面。鸾辂音尘远。\n无限幽恨，寄情空殢纨扇。应是帝王，当初怪妾辞辇，陡顿今来，宫中第一妖娆，却道昭阳飞燕。'},
    {t:'斗百花·煦色韶光明媚',a:'柳永〔宋代〕',c:'煦色韶光明媚，轻霭低笼芳树。春塘浅蘸烟芜，帘幕闲垂风絮。春困厌厌，抛掷斗草工夫，冷落绵青心绪。终日扃朱户。\n远恨绵绵，淑景迟迟难度。年少傅粉，依前醉眠何处。深院无人，黄昏乍拆秋千，空锁满庭花雨。'},
    {t:'独不见',a:'李白〔唐代〕',c:'白马谁家子，黄龙边塞儿。\n天山三丈雪，岂是远行时。\n春蕙忽秋草，莎鸡鸣西池。\n风摧寒棕响，月入霜闺悲。\n忆与君别年，种桃齐蛾眉。\n桃今百馀尺，花落成枯枝。\n终然独不见，流泪空自知。'},
    {t:'独愁',a:'孟郊〔唐代〕',c:'前日远别离，昨日生白发。欲知万里情，晓卧半床月。\n常恐百虫鸣，使我芳草歇。'},
    {t:'独孤判官部送兵',a:'高适〔唐代〕',c:'饯君嗟远别，为客念周旋。征路今如此，前军犹眇然。\n出关逢汉壁，登陇望胡天。亦是封侯地，期君早着鞭。'},
    {t:'独觉',a:'柳宗元〔唐代〕',c:'觉来窗牖空，寥落雨声晓。\n良游怨迟暮，末事惊纷扰。\n为问经世心，古人谁尽了。'},
    {t:'独柳',a:'杜牧〔唐代〕',c:'含烟一株柳，拂地摇风久。\n佳人不忍折，怅望回纤手。'},
    {t:'独漉篇',a:'李白〔唐代〕',c:'独漉水中泥，水浊不见月。\n不见月尚可，水深行人没。\n越鸟从南来，胡鹰亦北渡。\n我欲弯弓向天射，惜其中道失归路。\n落叶别树，飘零随风。\n客无所托，悲与此同。\n罗帏舒卷，似有人开。\n明月直入，无心可猜。\n雄剑挂壁，时时龙鸣。\n不断犀象，绣涩苔生。\n国耻未雪，何由成名。\n神鹰梦泽，不顾鸱鸢。\n为君一击，鹏抟九天。'},
    {t:'独山梅花',a:'王安石〔宋代〕',c:'独山梅花何所似，半开半谢荆悴中。\n美人零落依草木，志士憔悴守蒿蓬。\n亭亭孤艳带寒日，漠漠远香随野风。\n移栽不得根欲老，回首上林颜色空。'},
    {t:'独游',a:'王昌龄〔唐代〕',c:'林卧情每闲，独游景常晏。\n时从灞陵下，垂钓往南涧。\n手携双鲤鱼，目送千里雁。\n悟彼飞有适，知此罹忧患。\n放之清冷泉，因得省疏慢。\n永怀青岑客，回首白云间。\n神超物无违，岂系名与宦。'},
    {t:'独游城西诸僧舍',a:'陆游〔宋代〕',c:'我是天公度外人，看山看水自由身。\n藓崖直上飞双屐，云洞前头岸幅巾。\n万里欲呼牛渚月，一生不受庾公尘。\n非无好客堪招唤，独往飘然觉更真。'},
    {t:'独游二首',a:'皎然〔唐代〕',c:'性野趣无端，春晴路又干。逢泉似石弄，放鹤向云看。\n好僻谁相似，从狂我自安。芳洲亦有意，步同白沙滩。\n临水兴不尽，虚舟可同嬉。还云与归鸟，若共山僧期。\n世事吾不预，此心谁得知。西峰有禅老，应见独游时。'},
    {t:'独酌',a:'杜牧〔唐代〕',c:'长空碧杳杳，万古一飞鸟。\n生前酒伴闲，愁醉闲多少。\n烟深隋家寺，殷叶暗相照。\n独佩一壶游，秋毫泰山小。'},
    {t:'独坐敬亭山',a:'李白〔唐代〕',c:'众鸟高飞尽，孤云独去闲。\n相看两不厌，只有敬亭山。'},
    {t:'读白氏长庆集',a:'杨万里〔宋代〕',c:'每读乐天诗，一读一回好。\n少时不知爱，知爱今已老。\n初哦殊驩欣，熟味忽烦恼。\n多方遣外累，半已动中抱。\n事去何必追，心净不须扫。\n追叹欲扫愁，自遣还自扰。\n不如卷此诗，唤酒一醉倒。\n狂歌謪仙词，三杯通大道。'},
    {t:'读禅经',a:'白居易〔唐代〕',c:'须知诸相皆非相，若住无馀却梦馀。言下忘言一时了，\n梦中说梦两重虚。空花岂得兼求果，阳焰如何更觅鱼。\n摄动是禅禅是动，不禅不动即如如。'},
    {t:'读赤壁赋前后二首',a:'文天祥〔宋代〕',c:'一笑沧波浩浩流，只鸡斗酒更为舟。\n八龙写作诗中案，孤鹤来为梦里游。\n杨柳远烟连北府，芦花新月对南楼。\n玉仙来往清风夜，还识江山似旧不。'},
    {t:'读赤壁赋前后二首·其一',a:'文天祥〔宋代〕',c:'昔年仙子谪黄州，赤壁矶头汗漫游。\n今古兴亡真过影，乾坤俯仰一虚舟。\n人间忧患何曾少，天上风流更有不。\n我亦洞箫吹一曲，不知身世是蜉蝣。'},
    {t:'读道书作',a:'朱熹〔宋代〕',c:'岩居秉贞操，所慕在玄虚。清夜眠斋宇，终朝观道书。\n形忘气自冲，性达理不馀。于道虽未庶，已超名迹拘。\n至乐在襟怀，山水非所娱。寄语狂驰子，营营竟焉如。'},
    {t:'读道书作六首其六',a:'朱熹〔宋代〕',c:'王乔吹笙去，列子御风还。至人绝华念，出入有无间。\n千载但闻名，不见冰玉颜。长啸空宇碧，何许蓬莱山。'},
    {t:'读杜诗',a:'文天祥〔宋代〕',c:'平生踪迹只奔波，偏是文章被折磨。\n耳想杜鹃心事苦，眼看胡马泪痕多。\n千年夔峡有诗在，一夜耒江如酒何。\n黄土一丘随处是，故乡归骨任蹉跎。'},
    {t:'读韩杜集',a:'杜牧〔唐代〕',c:'杜诗韩集愁来读，似倩麻姑痒处搔。\n天外凤凰谁得髓？无人解合续弦胶。'},
    {t:'读经',a:'孟郊〔唐代〕',c:'垂老抱佛脚，教妻读黄经。经黄名小品，一纸千明星。\n曾读大般若，细感肸蚃听。当时把斋中，方寸抱万灵。\n忽复入长安，蹴踏日月宁。老方却归来，收拾可丁丁。\n拂拭尘几案，开函就孤亭。儒书难借索，僧签饶芳馨。\n驿驿不开手，铿铿闻异铃。得善如焚香，去恶如脱腥。\n安得颜子耳，曾未如此听。听之何有言，德教贵有形。\n何言中国外，有国如海萍。海萍国教异，天声各泠泠。\n安排未定时，心火竞荧荧。将如庶几者，声尽形元冥。'},
    {t:'读李杜诗集，因题卷后',a:'白居易〔唐代〕',c:'翰林江左日，员外剑南时。不得恨官职，仍逢苦乱离。\n暮年逋客恨，浮世谪仙悲。吟咏留千古，声名动四夷。\n文场供秀句，乐府待新词。天意君须会，人间要好诗。'},
    {t:'读眉山集次韵雪诗五首',a:'王安石〔宋代〕',c:'若木昏昏末有鸦，冻雷深闭阿香车。\n抟云忽散簁为屑，翦水如分缀作花。\n拥帚尚怜南北巷，持杯能喜两三家。\n戏挼弄掬输儿女，羔袖龙锺手独叉。'},
    {t:'读孟尝君传',a:'王安石〔宋代〕',c:'世皆称孟尝君能得士，士以故归之，而卒赖其力以脱于虎豹之秦。嗟乎！孟尝君特鸡鸣狗盗之雄耳，岂足以言得士？不然，擅齐之强，得一士焉，宜可以南面而制秦，尚何取鸡鸣狗盗之力哉？夫鸡鸣狗盗之出其门，此士之所以不至也。'},
    {t:'读曲歌·打杀长鸣鸡',a:'佚名〔南北朝〕',c:'打杀长鸣鸡，弹去乌臼鸟。\n愿得连暝不复曙，一年都一晓。'},
    {t:'读曲歌八十九首·其三十三',a:'佚名〔隋代〕',c:'桃花落已尽，秋思犹未央。\n春风难期信，托情明月光。'},
    {t:'读曲歌八十九首·其十四',a:'佚名〔隋代〕',c:'仰头看梧桐，桐花特可怜。\n愿天无霜雪。梧子解千年。'},
    {t:'读曲歌八十九首其二十五',a:'佚名〔隋代〕',c:'芳萱初生时，知是无忧草。双眉画未成，那能就郎抱。'},
    {t:'读曲歌八十九首其七十九',a:'佚名〔隋代〕',c:'下帷灯火尽，朗月照怀里。无油何所苦，但今天明尔。'},
    {t:'读曲歌八十九首其七十一',a:'佚名〔隋代〕',c:'种莲长江边，藕生黄蘖浦。必得莲子时，流离经辛苦。'},
    {t:'读曲歌八十九首其三十八',a:'佚名〔隋代〕',c:'音信阔弦朔，方悟千里遥。朝霜语白日，知我为欢消。'},
    {t:'读曲歌八十九首其三十七',a:'佚名〔隋代〕',c:'百度不一回，千书信不归。春风吹杨柳，华艳空徘徊。'},
    {t:'读曲歌八十九首其三十五',a:'佚名〔隋代〕',c:'自从别郎后，卧宿头不举。飞龙落药店，骨出只为汝。'},
    {t:'读曲歌八十九首其三十一',a:'佚名〔隋代〕',c:'初阳正二月，草木郁青青。蹑履步前园，时物感人情。'},
    {t:'读曲歌八十九首其五十八',a:'佚名〔隋代〕',c:'非欢独慊慊，侬意亦驱驱。双灯俱时尽，奈许两无由。'},
    {t:'读曲歌八十九首其一',a:'佚名〔隋代〕',c:'花钗芙蓉髻，双鬓如浮云。春风不知著，好来动罗裙。'},
    {t:'读山海经·其一',a:'陶渊明〔魏晋〕',c:'孟夏草木长，绕屋树扶疏。\n众鸟欣有托，吾亦爱吾庐。\n既耕亦已种，时还读我书。\n穷巷隔深辙，颇回故人车。\n欢然酌春酒，摘我园中蔬。\n微雨从东来，好风与之俱。\n泛览周王传，流观山海图。\n俯仰终宇宙，不乐复何如？'},
    {t:'读山海经十三首·其八',a:'陶渊明〔魏晋〕',c:'自古皆有没，何人得灵长？\n不死复不老，万岁如平常。\n赤泉给我饮，员丘足我粮。\n方与三辰游，寿考岂渠央！'},
    {t:'读山海经十三首·其二',a:'陶渊明〔魏晋〕',c:'玉台凌霞秀，王母怡妙颜。\n天地共俱生，不知几何年。\n灵化无穷已，馆宇非一山。\n高酣发新谣，宁效俗中言！'},
    {t:'读山海经十三首·其九',a:'陶渊明〔魏晋〕',c:'夸父诞宏志，乃与日竞走。\n俱至虞渊下，似若无胜负。\n神力既殊妙，倾河焉足有！\n馀迹寄邓林，功竟在身后。'},
    {t:'读山海经十三首·其六',a:'陶渊明〔魏晋〕',c:'逍遥芜皋上，杳然望扶木。\n洪柯百万寻，森散复旸谷。\n灵人侍丹池，朝朝为日浴。\n神景一登天，何幽不见烛。'},
    {t:'读山海经十三首·其七',a:'陶渊明〔魏晋〕',c:'粲粲三珠树，寄生赤水阴。\n亭亭凌风桂，八榦共成林。\n灵凤抚云舞，神鸾调玉音。\n虽非世上宝，爰得王母心。'},
    {t:'读山海经十三首·其三',a:'陶渊明〔魏晋〕',c:'迢迢槐江岭，是为玄圃丘。\n西南望昆墟，光气难与俦。\n亭亭明玕照，洛洛清瑶流。\n恨不及周穆，托乘一来游。'},
    {t:'读山海经十三首·其十',a:'陶渊明〔魏晋〕',c:'精卫衔微木，将以填沧海。\n刑天舞干戚，猛志固常在。\n同物既无虑，化去不复悔。\n徒设在昔心，良辰讵可待。'},
    {t:'读山海经十三首·其十二',a:'陶渊明〔魏晋〕',c:'鸱鴸见城邑，其国有放士。\n念彼怀王世，当时数来止。\n青丘有奇鸟，自言独见尔；\n本为迷者生，不以喻君子。'},
    {t:'读山海经十三首·其十三',a:'陶渊明〔魏晋〕',c:'岩岩显朝市，帝者慎用才。\n何以废共鲧，重华为之来。\n仲父献诚言，姜公乃见猜；\n临没告饥渴，当复何及哉！'},
    {t:'读山海经十三首·其十一',a:'陶渊明〔魏晋〕',c:'巨猾肆威暴，钦駓违帝旨。\n窫窳强能变，祖江遂独死。\n明明上天鉴，为恶不可履。\n长枯固已剧，鵕鹗岂足恃！'},
    {t:'读山海经十三首·其四',a:'陶渊明〔魏晋〕',c:'丹木生何许？乃在峚山阳。\n黄花复朱实，食之寿命长。\n白玉凝素液，瑾瑜发奇光。\n岂伊君子宝，见重我轩黄。'},
    {t:'读山海经十三首·其五',a:'陶渊明〔魏晋〕',c:'翩翩三青鸟，毛色奇可怜。\n朝为王母使，暮归三危山。\n我欲因此鸟，具向王母言。\n在世无所须，惟酒与长年。'},
    {t:'读诗',a:'杨万里〔宋代〕',c:'船中活计只诗编，读了唐诗读半山。\n不是老夫朝不食，半山绝句当朝餐。'},
    {t:'读史',a:'王安石〔宋代〕',c:'自古功名亦苦辛，行藏终欲付何人？\n当时黮暗犹承误，末俗纷纭更乱真。\n糟粕所传非粹美，丹青难写是精神。\n区区岂尽高贤意，独守千秋纸上尘。'},
    {t:'读史',a:'文天祥〔宋代〕',c:'自古英雄士，还为薄命人。\n孔明登四十，韩信过三旬。\n壮志摧龙虎，高词泣鬼神。\n一朝事千古，何用怨青春。'},
    {t:'读史',a:'陆游〔宋代〕',c:'萧相守关成汉业，穆之一死宋班师。\n赫连拓跋非难取，天意从来未易知。'},
    {t:'读书',a:'柳宗元〔唐代〕',c:'幽沉谢世事，俯默窥唐虞。\n上下观古今，起伏千万途。\n遇欣或自笑，感戚亦以吁。\n缥帙各舒散，前后互相逾。\n瘴痾扰灵府，日与往昔殊。\n临文乍了了，彻卷兀若无。\n竟夕谁与言，但与竹素俱。\n倦极更倒卧，熟寐乃一苏。\n欠伸展肢体，吟咏心自愉。\n得意适其适，非愿为世儒。\n道尽即闭口，萧散捐囚拘。\n巧者为我拙，智者为我愚。\n书史足自悦，安用勤与劬。\n贵尔六尺躯，勿为名所驱。'},
    {t:'读书',a:'陆游〔宋代〕',c:'读书四更灯欲尽，胸中太华蟠千仞。\n仰呼青天那得闻，穷到白头犹自信。\n策名委质本为国，岂但空取黄金印。\n故都即今不忍说，空宫夜夜飞秋磷。\n士初许身辈稷契，岁晚所立惭廉蔺。\n正看愤切诡成功，已复雍容托观衅。\n虽然知人要未易，讵可例轻天下士。\n君不见长松卧壑困风霜，时来屹立扶明堂。'},
    {t:'读书',a:'杨万里〔宋代〕',c:'读书不厌勤，勤甚倦且昏。\n不如卷书坐，人书两忘言。\n兴来忽开卷，径到百圣源。\n说悟本无悟，谈玄初未玄。\n当其会心处，只有一欣然。\n此乐谁为者，非我亦非天。\n自笑终未是，拨书枕头眠。'},
    {t:'读书忌二物',a:'秦观〔宋代〕',c:'予少时读书，一见辄即能诵。暗饮之，亦不甚失。然负自放，喜从饮酒滑稽者游。旬朔之间，把卷废几日，故虽有强记之力，而常废于不勤。\n比数年来，颇发愤惩艾，悔前所为；而聪明衰耗，殆不如曩时十一二。每阅一事，必寻绎数终，掩卷茫然，辄复不省。故虽有勤劳之苦，而常废于善忘。\n嗟夫！败吾业者，常此二物也。'},
    {t:'读书须有疑',a:'朱熹〔宋代〕',c:'读书，始读，未知有疑；其次，则渐渐有疑；中则节节有疑。过了这一番，疑渐渐释，以至融会贯通，都无所疑，方始是学。读书无疑者须教有疑，有疑，却要无疑，到这里方是长进。'},
    {t:'读书要三到',a:'朱熹〔宋代〕',c:'凡读书，须要读得字字响亮，不一误一字，不一少一字，不一多一字，不一倒一字，不一牵强暗久，只是要多诵数遍，自然上口，久远不忘。古人云，“读书百遍，其义自见”。谓读得熟，则不待解说，自晓其义也。余尝谓：读书有三到，谓心到，眼到，口到。心不在此，则眼不看仔细，心眼既不专一，却只漫浪诵读，决不能久，久亦不能久也。三到之中，心到最急。心既到矣，眼口岂不到乎？'},
    {t:'读蜀志',a:'王安石〔宋代〕',c:'千载纷争共一毛，可怜身世两徒劳。\n无人语与刘玄德，问舍求田意最高。'},
    {t:'读维摩经有感',a:'王安石〔宋代〕',c:'身如泡沫亦如风，刀割香涂共一空。\n宴坐世间观此理，维摩虽病有神通。'},
    {t:'读武惠妃传',a:'杨万里〔宋代〕',c:'桂折秋风露折兰，千花无朵可天颜。\n寿王不忍金宫冷，独献君王一玉环。'},
    {t:'读严子陵传',a:'杨万里〔宋代〕',c:'客星何补汉中兴，空有清风冷似冰。\n早遣阿瞒移汉鼎，人间何处有严陵！'},
    {t:'读元白长庆二集诗',a:'杨万里〔宋代〕',c:'读遍元诗与白诗，一生少傅重微之。\n再三不晓渠何意，半是交情半是私。'},
    {t:'读袁公路传',a:'陆游〔宋代〕',c:'成败相寻岂有常，英雄最忌数悲伤。\n芜蒌豆粥从来事，何恨邮亭坐箦床？'},
    {t:'读张碧集',a:'孟郊〔唐代〕',c:'天宝太白殁，六义已消歇。大哉国风本，丧而王泽竭。\n先生今复生，斯文信难缺。下笔证兴亡，陈词备风骨。\n高秋数奏琴，澄潭一轮月。谁作采诗官，忍之不挥发。'},
    {t:'读张文潜诗二首',a:'杨万里〔宋代〕',c:'晚爱肥仙诗自然，何曾绣绘更琱镌。\n春花秋月冬冰雪，不听陈玄只听天。'},
    {t:'读罪已诏',a:'杨万里〔宋代〕',c:'莫读轮台诏，令人泪点垂。\n天乎客此虏，帝者渴非罴。\n何罪良家子，知他大将谁？\n愿惩危度口，傥复雁门踦。'},
    {t:'杜甫画像',a:'王安石〔宋代〕',c:'吾观少陵诗，为与元气侔。\n力能排天斡九地，壮颜毅色不可求。\n浩荡八极中，生物岂不稠。\n丑妍巨细千万殊，竟莫见以何雕锼。\n惜哉命之穷，颠倒不见收。\n青衫老更斥，饿走半九州。\n瘦妻僵前子仆后，攘攘盗贼森戈矛。\n吟哦当此时，不废朝廷忧。\n常愿天子圣，大臣各伊周。\n宁令吾庐独破受冻死，不忍四海赤子寒飕飗。\n伤屯悼屈止一身，嗟时之人死所羞。\n所以见公像，再拜涕泗流。\n惟公之心古亦少，愿起公死从之游。'},
    {t:'杜工部蜀中离席',a:'李商隐〔唐代〕',c:'人生何处不离群？世路干戈惜驻分。\n雪岭未归天外使，松州犹驻殿前军。\n座中醉客延醒客，江上晴云杂雨云。\n美酒成都堪送老，当垆仍是卓文君。'},
    {t:'杜架阁',a:'文天祥〔宋代〕',c:'昔趋魏公子，今事霍将军。\n世态炎凉甚，交情贵贱分。\n黄沙扬暮霭，黑海起朝氛。\n独与君携手，行吟看白云。'},
    {t:'杜鹃',a:'杜牧〔唐代〕',c:'杜宇竟何冤，年年叫蜀门。至今衔积恨，终古吊残魂。\n芳草迷肠结，红花染血痕。山川尽春色，呜咽复谁论。'},
    {t:'杜陵绝句',a:'李白〔唐代〕',c:'南登杜陵上，北望五陵间。\n秋水明落日，流光灭远山。'},
    {t:'杜陵叟',a:'白居易〔唐代〕',c:'杜陵叟，杜陵居，岁种薄田一顷余。\n三月无雨旱风起，麦苗不秀多黄死。\n九月降霜秋早寒，禾穗未熟皆青干。\n长吏明知不申破，急敛暴征求考课。\n典桑卖地纳官租，明年衣食将何如？\n剥我身上帛，夺我口中粟。\n虐人害物即豺狼，何必钩爪锯牙食人肉？\n不知何人奏皇帝，帝心恻隐知人弊。\n白麻纸上书德音，京畿尽放今年税。\n昨日里胥方到门，手持敕牒榜乡村。\n十家租税九家毕，虚受吾君蠲免恩。'},
    {t:'杜司勋',a:'李商隐〔唐代〕',c:'高楼风雨感斯文，短翼差池不及群。\n刻意伤春复伤别，人间惟有杜司勋。'},
    {t:'杜位宅守岁',a:'杜甫〔唐代〕',c:'守岁阿戎家，椒盘已颂花。\n盍簪喧枥马，列炬散林鸦。\n四十明朝过，飞腾暮景斜。\n谁能更拘束，烂醉是生涯。'},
    {t:'度浮桥至南台',a:'陆游〔宋代〕',c:'客中多病废登临，闻说南台试一寻。\n九轨徐行怒涛上，千艘横系大江心。\n寺楼钟鼓催昏晓，墟落云烟自古今。\n白发未除豪气在，醉吹横笛坐榕阴。'},
    {t:'度荆门望楚',a:'陈子昂〔唐代〕',c:'遥遥去巫峡，望望下章台。\n巴国山川尽，荆门烟雾开。\n城分苍野外，树断白云隈。\n今日狂歌客，谁知入楚来。'},
    {t:'度峡口山赠乔补阙知之王二无竞',a:'陈子昂〔唐代〕',c:'峡口大漠南，横绝界中国。\n丛石何纷纠，赤山复翕赩。\n远望多众容，逼之无异色。\n崔崒乍孤断，逶迤屡回直。\n信关胡马冲，亦距汉边塞。\n岂依河山险，将顺休明德。\n物壮诚有衰，势雄良易极。\n逦迤忽而尽，泱漭平不息。\n之子黄金躯，如何此荒域。\n云台盛多士，待君丹墀侧。'},
    {t:'渡瓜洲',a:'文天祥〔宋代〕',c:'跨江半壁阅千帆，虎被深山龙被潭。\n当日本为南制北，如今翻被北持南。\n眼前风景异山河，无柰诸君笑语何。\n坐上有人正愁绝，胡儿便道是偻儸。'},
    {t:'渡河到清河作',a:'王维〔唐代〕',c:'泛舟大河里，积水穷天涯。\n天波忽开拆，郡邑千万家。\n行复见城市，宛然有桑麻。\n回瞻旧乡国，渺漫连云霞。'},
    {t:'渡江云·次赵元父韵',a:'张炎〔宋代〕',c:'锦香缭绕地，深灯挂壁，帘影浪花斜。酒船归去後，转首河桥，那处认纹纱。重盟镜约，还记得、前度秦嘉。惟只有、叶题堪寄，流不到天涯。\n惊嗟。十年心事，几曲阑干，想萧娘声价。闲过了、黄昏时候，疏柳啼鸦。浦潮夜涌平沙白，问断鸿、知落谁家。书又远，空江片月芦花。'},
    {t:'渡江云·怀归',a:'张炎〔宋代〕',c:'江山居未定，貂裘已敝，空自带是归。乱花流水外，访里寻邻，都是可怜时。桥边燕子，似软语、斜镜江蓠。休问我、如今心事，错认镜中谁。\n还思。新烟惊换，旧雨难招，做不成春意。浑未省、谁家芳草，犹梦吟诗。一株古柳观鱼港，傍清深、足可幽栖。闲趣好，白鸥尚识天随。'},
    {t:'渡江云·晴岚低楚甸',a:'周邦彦〔宋代〕',c:'晴岚低楚甸，暖回雁翼，阵势起平沙。骤惊春在眼，借问何时，委曲到山家。涂香晕色，盛粉饰、争作妍华。千万丝、陌头杨柳，渐渐可藏鸦。\n堪嗟。清江东注，画舸西流，指长安日下。愁宴阑、风翻旗尾，潮溅乌纱。今宵正对初弦月，傍水驿、深舣蒹葭。沉恨处，时时自剔灯花。'},
    {t:'渡荆门送别',a:'李白〔唐代〕',c:'渡远荆门外，来从楚国游。\n山随平野尽，江入大荒流。\n月下飞天镜，云生结海楼。\n仍怜故乡水，万里送行舟。'},
    {t:'渡吴江',a:'杜牧〔唐代〕',c:'堠馆人稀夜更长，姑苏城远树归归。江湖潮落高楼迥，\n河汉秋归广殿凉。月转碧梧移鹊影，露低红草湿萤光。\n文园诗侣应多思，莫醉笙歌掩华堂。'},
    {t:'渡扬子江',a:'孟浩然〔唐代〕',c:'桂楫中流望，京江两畔明。\n林开扬子驿，山出润州城。\n海尽边阴静，江寒朔吹生。\n更闻枫叶下，淅沥度秋声。'},
    {t:'渡易水歌',a:'佚名〔先秦〕',c:'风萧萧兮易水寒，壮士一去兮不复还。\n探虎穴兮入蛟宫，仰天呼气兮成白虹。'},
    {t:'渡浙江问舟中人',a:'孟浩然〔唐代〕',c:'潮落江平未有风，扁舟共济与君同。\n时时引领望天末，何处青山是越中。'},
    {t:'端居',a:'李商隐〔唐代〕',c:'远书归梦两悠悠，只有空床敌素秋。\n阶下青苔与红树，雨中寥落月中愁。'},
    {t:'端居感怀',a:'韦应物〔唐代〕',c:'沈沈积素抱，婉婉属之子。永日独无言，忽惊振衣起。\n方如在帏室，复悟永终已。稚子伤恩绝，盛时若流水。\n暄凉同寡趣，朗晦俱无理。寂性常喻人，滞情今在己。\n空房欲云暮，巢燕亦来止。夏木遽成阴，绿苔谁复履。\n感至竟何方，幽独长如此。'},
    {t:'端午',a:'文天祥〔宋代〕',c:'五月五日午，薰风自南至。\n试为生大钧，举杯三酹地。\n田文当日生，屈原当日死。\n生为薛城君，死悲汨罗鬼。\n高堂狐兔游，雍门发悲涕。\n人命草头露，荣华风过耳。\n唯有烈士心，不随水俱逝。\n至今荆楚人，江上年年祭。\n不知生者荣，但知死者贵。\n勿谓死可憎，勿谓生可喜。\n万物皆有尽，不灭唯天理。\n百年如一日，一日或千岁。\n秋风汾水辞，春暮兰亭记。\n莫悲留连悲，高歌舞槐翠。'},
    {t:'端午遍游诸寺得禅字',a:'苏轼〔宋代〕',c:'肩舆任所适，遇胜辄留连。\n焚香引幽步，酌茗开静筵。\n微雨止还作，小窗幽更妍。\n盆山不见日，草木自苍然。\n忽登最高塔，眼界穷大千。\n卞峰照城郭，震泽浮云天。\n深沉既可喜，旷荡亦所便。\n幽寻未云毕，墟落生晚烟。\n归来记所历，耿耿清不眠。\n道人亦未寝，孤灯同夜禅。'},
    {t:'端午词·内廷',a:'晏殊〔宋代〕',c:'百草斗馀欣令月，五丝萦后祝遐年。\n洞房风暖垂灵艾，神沼波深竞彩船。'},
    {t:'端午词·内廷',a:'晏殊〔宋代〕',c:'披风别殿地无尘，辟恶灵符自有神。\n九子粽香仙醴熟，共瞻宸极祝千春。'},
    {t:'端午词·内廷',a:'晏殊〔宋代〕',c:'一一雕盘分楚粽，重重团扇画秦娥。\n宫闱百福逢嘉序，万户千门喜气多。'},
    {t:'端午词·升王阁',a:'晏殊〔宋代〕',c:'朱邸沐兰逢令节，丹廷祝寿喜嘉辰。\n两宫荣养多延庆，百福潜随命缕新。'},
    {t:'端午词·御阁',a:'晏殊〔宋代〕',c:'雕盘角黍竞时宜，组绣风华奉紫闱。\n海日乍升丹禁晓，艾人晴影照金扉。'},
    {t:'端午词·御阁',a:'晏殊〔宋代〕',c:'沐浴兰汤在此辰，内园仙境物华新。\n轻丝五彩缠金缕，共祝尧年寿万春。'},
    {t:'端午词·御阁',a:'晏殊〔宋代〕',c:'献寿竞为长命缕，迎祥还佩赤灵符。\n端门漏永晨曦上，飒飒薰风绕帝梧。'},
    {t:'端午词·御阁',a:'晏殊〔宋代〕',c:'乍结香茅祈福寿，更缠金缕贡芳新。\n丹台素有延生录，岁岁迎祥在此辰。'},
    {t:'端午词其三内廷',a:'晏殊〔宋代〕',c:'由来佳节载南荆，一浴兰汤万虑清。仙苑此时收百药，鍊丹飞石保长生。'},
    {t:'端午独酌',a:'杨万里〔宋代〕',c:'招得榴花共一觞，艾人笑杀老夫狂。\n子兰赤口禳何益，正则红船看不妨。\n团粽明朝便无味，菖蒲今日麽生香。\n一生幸免春端帖，可遣渔歌谱大章。'},
    {t:'端午感兴',a:'文天祥〔宋代〕',c:'当年忠血堕谗波，千古荆人祭汨罗。\n风雨天涯芳草梦，江山如此故都何。'},
    {t:'端午即事',a:'文天祥〔宋代〕',c:'五月五日午，赠我一枝艾。\n故人不可见，新知万里外。\n丹心照夙昔，鬓发日已改。\n我欲从灵均，三湘隔辽海。'},
    {t:'端午日赐衣',a:'杜甫〔唐代〕',c:'宫衣亦有名，端午被恩荣。\n细葛含风软，香罗叠雪轻。\n自天题处湿，当暑著来清。\n意内称长短，终身荷圣情。'},
    {t:'短灯檠歌',a:'韩愈〔唐代〕',c:'长檠八尺空自长，短檠二尺便且光。\n黄帘绿幕朱户闭，风露气入秋堂凉。\n裁衣寄远泪眼暗，搔头频挑移近床。\n太学儒生东鲁客，二十辞家来射策。\n夜书细字缀语言，两目眵昏头雪白。\n此时提携当案前，看书到晓那能眠。\n一朝富贵还自恣，长檠高张照珠翠。\n吁嗟世事无不然，墙角君看短檠弃。'},
    {t:'短歌行',a:'白居易〔唐代〕',c:'曈曈太阳如火色，上行千里下一刻。\n出为白昼入为夜，圆转如珠住不得。\n住不得，可奈何，为君举酒歌短歌。\n歌声苦，词亦苦，四座少年君听取。\n今夕未竟明夕催，秋风才往春风回。\n人无根蒂时不驻，朱颜白日相隳颓。\n劝君且强笑一面，劝君且强饮一杯。\n人生不得长欢乐，年少须臾老到来。'},
    {t:'短歌行',a:'李白〔唐代〕',c:'白日何短短，百年苦易满。\n苍穹浩茫茫，万劫太极长。\n麻姑垂两鬓，一半已成霜。\n天公见玉女，大笑亿千场。\n吾欲揽六龙，回车挂扶桑。\n北斗酌美酒，劝龙各一觞。\n富贵非所愿，与人驻颜光。'},
    {t:'短歌行赠王郎司直',a:'杜甫〔唐代〕',c:'王郎酒酣拔剑斫地歌莫哀！我能拔尔抑塞磊落之奇才。\n豫章翻风白日动，鲸鱼跋浪沧溟开。且脱佩剑休徘徊。\n西得诸侯棹锦水，欲向何门趿珠履？\n仲宣楼头春色深，青眼高歌望吾子，眼中之人吾老矣！'},
    {t:'短句奉迎其二',a:'朱熹〔宋代〕',c:'军府资长算，家山辍胜游。故人千里别，归骑两年秋。\n吊古宁忘恨，开尊且破愁。相思欲回首，但上曲江楼。'},
    {t:'短韵奉乞腊梅',a:'黄庭坚〔宋代〕',c:'卧云庄上残花笑，香似早梅开不迟。\n浅色春衫弄风日，遣来当为作新诗。'},
    {t:'段九秀才处见亡友吕衡州书迹',a:'柳宗元〔唐代〕',c:'交侣平生意最亲，衡阳往事似分身。\n袖中忽见三行字，拭泪相看是故人。'},
    {t:'段宥厅孤桐',a:'王昌龄〔唐代〕',c:'凤皇所宿处，月映孤桐寒。\n槁叶零落尽，空柯苍翠残。\n虚心谁能见，直影非无端。\n响发调尚苦，清商劳一弹。'},
    {t:'断雁',a:'文天祥〔宋代〕',c:'断雁西江远，无家寄万金。\n乾坤风月老，沙漠岁年深。\n白日去如梦，青天知此心。\n素琴弦已绝，不绝是南音。'},
    {t:'对残灯',a:'韦应物〔唐代〕',c:'独照碧窗久，欲随寒烬灭。幽人将遽眠，解带翻成结。'},
    {t:'对韩少尹所赠砚有怀',a:'韦应物〔唐代〕',c:'故人谪遐远，留砚宠斯文。白水浮香墨，清池满夏云。\n念离心已永，感物思徒纷。未有桂阳使，裁书一报君。'},
    {t:'对酒',a:'陆游〔宋代〕',c:'闲愁如飞雪，入酒即消融。\n好花如故人，一笑杯自空。\n流莺有情亦念我，柳边尽日啼春风。\n长安不到十四载，酒徒往往成衰翁。\n九环宝带光照地，不如留君双颊红。'},
    {t:'对酒',a:'李白〔唐代〕',c:'蒲萄酒，金叵罗，吴姬十五细马驮。\n青黛画眉红锦靴，道字不正娇唱歌。\n玳瑁筵中怀里醉，芙蓉帐底奈君何！'},
    {t:'对酒五首',a:'白居易〔唐代〕',c:'巧拙贤愚相是非，何如一醉尽皇机。\n君知天地中宽窄，雕鹗鸾皇各自飞。\n蜗牛角上争何事，石乐光中寄此身。\n随富随贫且欢乐，不开口笑是痴人。\n丹砂见乐去无迹，白发泥人来不休。\n赖有酒仙相暖热，松乔醉即到前头。\n百岁无多时壮健，一春能几日晴明。\n相逢且莫推辞醉，听唱阳关第四声。\n昨日低眉问疾来，今朝收泪吊人回。\n眼前流例君看取，且遣琵琶送一杯。'},
    {t:'对酒五首·其二',a:'白居易〔唐代〕',c:'蜗牛角上争何事，石火光中寄此身。\n随富随贫且欢乐，不开口笑是痴人。'},
    {t:'对酒行',a:'李白〔唐代〕',c:'松子栖金华，安期入蓬海。\n此人古之仙，羽化竟何在。\n浮生速流电，倏忽变光彩。\n天地无凋换，容颜有迁改。\n对酒不肯饮，含情欲谁待。'},
    {t:'对酒忆贺监二首',a:'李白〔唐代〕',c:'四明有狂客，风流贺季真。\n长安一相见，呼我谪仙人。\n昔好杯中物，翻为松下尘。\n金龟换酒处，却忆泪沾巾。\n狂客归四明，山阴道士迎。\n敕赐镜湖水，为君台沼荣。\n人亡余故宅，空有荷花生。\n念此杳如梦，凄然伤我情。'},
    {t:'对新篁',a:'韦应物〔唐代〕',c:'新绿苞初解，嫩气笋犹香。含露渐舒叶，抽丛稍自长。\n清晨止亭下，独爱此幽篁。'},
    {t:'对萱草',a:'韦应物〔唐代〕',c:'何人树萱草，对此郡斋幽。\n本是忘忧物，今夕重生忧。\n丛疏露始滴，芳馀蝶尚留。\n还思杜陵圃，离披风雨秋。'},
    {t:'对雪',a:'杜甫〔唐代〕',c:'战哭多新鬼，愁吟独老翁。\n乱云低薄暮，急雪舞回风。\n瓢弃尊无绿，炉存火似红。\n数州消息断，愁坐正书空。'},
    {t:'对雪二首',a:'李商隐〔唐代〕',c:'寒气先侵玉女扉，清光旋透省郎闱。\n梅花大庾岭头发，柳絮章台街里飞。\n欲舞定随曹植马，有情应湿谢庄衣。\n龙山万里无多远，留待行人二月归。\n旋扑珠帘过粉墙，轻于柳絮重于霜。\n已随江令夸琼树，又入卢家妒玉堂。\n侵夜可能争桂魄，忍寒应欲试梅妆。\n关河冻合东西路，肠断斑骓送陆郎。'},
    {t:'对雪奉饯任城六父秩满归京',a:'李白〔唐代〕',c:'龙虎谢鞭策，鹓鸾不司晨。\n君看心上鹤，何似笼中鹑。\n独用天地心，浮云乃吾身。\n虽将簪组狎，若常烟霞亲。\n季父有英风，白眉超常伦。\n一官即梦寐，脱屣归西秦。\n窦公敞华筵，墨客尽来臻。\n燕歌落胡雁，郢曲回阳春。\n征马百度嘶，游车动行尘。\n踌躇未忍去，恋此四座人。\n饯离驻高驾，惜别空殷勤。\n何时竹林下，更常步兵邻。'},
    {t:'对雨寄韩库部协',a:'韦应物〔唐代〕',c:'飒至池馆凉，霭然和晓雾。萧条集新荷，氤氲散高树。\n闲居兴方澹，默想心已屡。暂出仍湿衣，况君东城住。'},
    {t:'对雨书怀走邀许十一簿公',a:'杜甫〔唐代〕',c:'东岳云峰起，溶溶满太虚。\n震雷翻幕燕，骤雨落河鱼。\n座对贤人酒，门听长者车。\n相邀愧泥泞，骑马到阶除。'},
    {t:'对杂花',a:'韦应物〔唐代〕',c:'朝红争景新，夕素含露翻。妍姿如有意，流芳复满园。\n单栖守远郡，永日掩重门。不与花为偶，终遣与谁言。'},
    {t:'敦煌太守后庭歌',a:'岑参〔唐代〕',c:'敦煌太守才且贤，郡中无事高枕眠。\n太守到来山出泉，黄砂碛里人种田。\n敦煌耆旧鬓皓然，愿留太守更五年。\n城头月出星满天，曲房置酒张锦筵。\n美人红妆色正鲜，侧垂高髻插金钿。\n醉坐藏钩红烛前，不知钩在若个边。\n为君手把珊瑚鞭，射得半段黄金钱，此中乐事亦已偏。'},
    {t:'峨眉东脚临江听猿，怀二室旧庐',a:'岑参〔唐代〕',c:'峨眉烟翠新，昨夜秋雨洗。分明峰头树，倒插秋江底。\n久别二室间，图他五斗米。哀猿不可听，北客欲流涕。'},
    {t:'峨眉山月歌',a:'李白〔唐代〕',c:'峨眉山月半轮秋，影入平羌江水流。\n夜发清溪向三峡，思君不见下渝州。'},
    {t:'峨眉山月歌送蜀僧晏入中京',a:'李白〔唐代〕',c:'我在巴东三峡时，西看明月忆峨眉。\n月出峨眉照沧海，与人万里长相随。\n黄鹤楼前月华白，此中忽见峨眉客。\n峨眉山月还送君，风吹西到长安陌。\n长安大道横九天，峨眉山月照秦川。\n黄金狮子乘高座，白玉麈尾谈重玄。\n我似浮云殢吴越，君逢圣主游丹阙。\n一振高名满帝都，归时还弄峨眉月。'},
    {t:'鹅湖寺和陆子寿',a:'朱熹〔宋代〕',c:'德义风流夙所钦，别离三载更关心。\n偶扶藜杖出寒谷，又枉篮舆度远岑。\n旧学商量加邃密，新知培养转深沉。\n却愁说到无言处，不信人间有古今。'},
    {t:'鹅赠鹤',a:'白居易〔唐代〕',c:'君因风送入青云，我被人驱向鸭群。\n雪颈霜毛红网掌，请看何处不如君？'},
    {t:'鄂州南楼书事',a:'黄庭坚〔宋代〕',c:'四顾山光接水光，凭栏十里芰荷香。\n清风明月无人管，并作南楼一味凉。'},
    {t:'鄂州南楼书事四首',a:'黄庭坚〔宋代〕',c:'画阁传觞容十客，透风透月两明轩。\n南楼盘礡三百尺，天上云居不足言。'},
    {t:'鄂州寓馆严涧宅·时涧不在',a:'元稹〔唐代〕',c:'凤有高梧鹤有松，偶来江外寄人踪。花枝满院空啼鸟，\n尘榻无人忆卧龙。心想夜闲唯足梦，眼看春尽不相逢。\n何时最是思君处，月入斜窗晓寺钟。'},
    {t:'萼绿华歌',a:'韦应物〔唐代〕',c:'有一人兮升紫霞，书名玉牒兮萼绿华。\n仙容矫矫兮杂瑶珮，轻衣重重兮蒙绛纱。\n云雨愁思兮望淮海，鼓吹萧条兮驾龙车。\n世淫浊兮不可降，胡不来兮玉斧家。'},
    {t:'恩赐乐游园宴应制',a:'张九龄〔唐代〕',c:'宝筵延厚命，供帐序群公。形胜宜春接，威仪建礼同。\n晞阳人似露，解愠物从风。朝庆千龄始，年华二月中。\n辉光遍草木，和气发丝桐。岁岁无为化，宁知乐九功。'},
    {t:'饵黄精',a:'韦应物〔唐代〕',c:'灵药出西山，服食采其根。九蒸换凡骨，经著上世言。\n候火起中夜，馨香满南轩。斋居感众灵，药术启妙门。\n自怀物外心，岂与俗士论。终期脱印绶，永与天壤存。'},
    {t:'二红饭',a:'苏轼〔宋代〕',c:'今年东坡收大麦二十余石，卖婢价甚贱，而粳米适尽，乃课奴婢舂以为饭。嚼婢，啧啧有声，小用女相调，云是嚼虱子。日中饥，用浆水淘食婢，自然甘酸浮滑，有西北村落气味。今日复令庖人杂小豆作饭，尤有味，老妻大笑曰：“此新样二红饭也。”'},
    {t:'二郎神·炎光谢',a:'柳永〔宋代〕',c:'炎光谢。过暮雨、芳尘轻洒。乍露冷风清庭户，爽天如水，玉钩遥挂。应是星娥嗟久阻，叙旧约、飙轮欲驾。极目处、微云暗度，耿耿银河高泻。\n闲雅。须知此景，古今无价。运巧思、穿针楼上女，抬粉面、云鬟相亚。钿合金钗私语处，算谁在、回廊影下。愿天上人间，占得欢娱，年年今夜。'},
    {t:'二十四日',a:'文天祥〔宋代〕',c:'壮心负光岳，病质落幽燕。\n春节前三日，江乡正小年。\n岁时如有水，风欲不同天。\n家庙荒苔滑。'},
    {t:'二王',a:'文天祥〔宋代〕',c:'一马渡江开晋土，五龙夹日复唐天。\n内家苗裔真隆准，虏运从来无百年。'},
    {t:'二月二日',a:'李商隐〔唐代〕',c:'二月二日江上行，东风日暖闻吹笙。\n花须柳眼各无赖，紫蝶黄蜂俱有情。\n万里忆归元亮井，三年从事亚夫营。\n新滩莫悟游人意，更作风檐夜雨声。'},
    {t:'二月二日',a:'白居易〔唐代〕',c:'二月二日新雨晴，草芽菜甲一时生。\n轻衫细马春年少，十字津头一字行。'},
    {t:'二月二十四日作',a:'陆游〔宋代〕',c:'棠梨花开社酒浓，南村北村鼓贱贱。\n且祈麦熟得饱饭，敢说谷贱复伤农。\n崖州万里窜酷吏，湖南几时起卧龙？\n但愿诸贤集廊庙，书生穷死胜侯封。'},
    {t:'二月晦',a:'文天祥〔宋代〕',c:'塞上明妃马，江头渔父船。\n新雠谁共雪，旧梦不堪圆。\n遗恨常千古，浮生又一年。\n何时暮春者，还我浴沂天。'},
    {t:'二月十一日夜梦作东都早春绝句',a:'杨万里〔宋代〕',c:'道是春来早，如何未见春。\n小桃三四点，偏报有情人。'},
    {t:'二月四日作',a:'陆游〔宋代〕',c:'早春风力已轻柔，瓦雪消残玉半沟。\n飞蝶鸣鸠俱得意，东风应笑我闲愁。'},
    {t:'二月一日晓渡太和江三首',a:'杨万里〔宋代〕',c:'绿杨接叶杏交花，嫩水新生尚露沙。\n过了春江偶回首，隔江一片好人家。'},
    {t:'二月一日雨寒五首',a:'杨万里〔宋代〕',c:'姚黄魏紫向谁赊，郁李樱桃也没些。\n却是南中春色别，满城都是木绵花。'},
    {t:'发崔镇',a:'文天祥〔宋代〕',c:'高雁空秋兴，寒螀破晓眠。\n淡烟白似海，野水碧于天。\n兴废嗟何及，行藏信自然。\n南人乍骑马，北客半乘船。'},
    {t:'发淮安',a:'文天祥〔宋代〕',c:'九月初二日，车马发淮安。\n行行重行行，天地何不宽。\n烟火无一家，荒草青漫漫。\n恍如泛沧海，身坐玻璃盘。\n时时逢北人，什伍扶征鞍。\n云我戌江南，当军身属官。\n北人适吴楚，所忧地少寒。\n江南有游子，风雪上燕山。'},
    {t:'发吉州',a:'文天祥〔宋代〕',c:'己卯六月初一日，苍然亭下楚夕立，山河颠倒纷雨泣。\n乙亥七夕此何夕，煌煌斗牛剑光湿，戈德彗云雷电击。\n三百馀年火为德，须臾风雨天地黑。\n皇网解纽地维折，妾妇偷生自为贼。\n英雄扼腕怒须赤，贯日血忠死穷北。\n首阳风流落南国，正气未亡人未息。\n青原万丈光赫赫，大江东去日夜白。'},
    {t:'发京师第五十七',a:'文天祥〔宋代〕',c:'东下姑苏台，挥涕恋行在。\n苍茫云雾浮，风帆倚翠盖。'},
    {t:'发孔镇晨炊漆桥道中纪行十首',a:'杨万里〔宋代〕',c:'雨入秋田恰及时，禾头相枕卧相依。\n路南路北皆秋水，净洗行人屦上泥。'},
    {t:'发临洮将赴北庭留别',a:'岑参〔唐代〕',c:'闻说轮台路，连年见雪飞。\n春风曾不到，汉使亦应稀。\n白草通疏勒，青山过武威。\n勤王敢道远，私向梦中归。'},
    {t:'发陵州',a:'文天祥〔宋代〕',c:'中原似沧海，万顷与云连。\n大明朝东出，皎月正在天。\n远树乱如点，桑麻郁苍烟。\n一雁入高空，千鸦落平田。\n我行天地中，如蚁磨上旋。\n雨痕留故衣，霜气袭重毡。\n健马嘶北风，潜鱼乐深渊。\n噫哉南方人，回首空自怜。'},
    {t:'发彭城',a:'文天祥〔宋代〕',c:'今朝正重九，行人意迟迟。\n回首戏马台，野花发葳蕤。\n草埋范增塚，云见樊哙旗。\n时节正如此，道路将何之。\n我爱陶渊明，甲子题新诗。\n白衣送酒来，把菊卧东篱。'},
    {t:'发潭口',a:'文天祥〔宋代〕',c:'吹面北风来，拂鬓坚冰至。\n轩冕委道途，衮绣易毡毳。\n百年杂丑好，始酬四方志。\n浩歌激浮云，亭亭复揽辔。'},
    {t:'发潭州',a:'杜甫〔唐代〕',c:'夜醉长沙酒，晓行湘水春。\n岸花飞送客，樯燕语留人。\n贾傅才未有，褚公书绝伦。\n名高前后事，回首一伤神。'},
    {t:'法华寺上方题江上人禅空',a:'皎然〔唐代〕',c:'路入松声远更奇，山光水色共参差。\n中峰禅寂一僧在，坐对梁朝老桂枝。'},
    {t:'法华寺西亭夜饮',a:'柳宗元〔唐代〕',c:'祇树夕阳亭，共倾三昧酒。\n雾暗水连阶，月明花覆牖。\n莫厌樽前醉，相看未白首。'},
    {t:'法曲第二·青翼传情',a:'柳永〔宋代〕',c:'青翼传情，香径偷期，自觉当初草草。未省同衾枕，便轻许相将，平生欢笑。怎生向、人间好事到头少。漫悔懊。\n细追思，恨从前容易，致得恩爱成烦恼。心下事千种，尽凭音耗。以此萦牵，等伊来、自家向道。洎相见，喜欢存问，又还忘了。'},
    {t:'法曲献仙音·大石',a:'周邦彦〔宋代〕',c:'蝉咽凉柯，燕飞尘幕，漏阁签声半度。倦脱纶巾，困便湘竹，桐阴半侵朱户。向抱影凝情处。半闻病窗雨。\n耿无语。叹文园、近来多病，情绪懒，尊酒易成间阻。缥缈玉京人，想依然、京兆眉妩。翠幕深中，对徽容、空在纨素。待花前月下，见了不教归去。'},
    {t:'法曲献仙音·题姜子野雪溪图',a:'张炎〔宋代〕',c:'梅失黄昏，雁惊白昼，脉脉斜飞云表。絮不生萍，水疑浮玉，此景正宜舒啸。记夜悄、曾乘兴，何必见安道。\n系船好。想前村、未知甚处。吟思苦，谁游灞桥路杳。清饮一瓢寒，又何妨、分傍茶灶。野屋萧萧，任楼中、低唱人笑。渐东风解冻，怕有桃花流到。'},
    {t:'法曲献仙音·席上听琵琶有感',a:'张炎〔宋代〕',c:'云隐山晖，树分溪影，未放妆台自卷。篝密笼香，镜圆窥粉，花深自然寒浅。正人在、银屏底，琵琶怨遮面。\n语声软。且休弹、玉关愁怨。怕唤起西湖，那时春感。杨柳古湾头，记小怜、隔水曾见。听到无声，谩赢得、情绪难翦。把一襟心事，散入落梅千点。'},
    {t:'法曲献仙音·小石调',a:'柳永〔宋代〕',c:'追想秦楼心事，当年便约，于飞云翼。每恨临歧处，正携手、翻成云雨离拆。念倚玉偎香，前事顿病掷。\n惯怜惜。饶心性，镇厌厌多病，柳腰花态娇无力。早是乍清减，别后忍教愁寂。记取盟言，少孜煎、剩好将息。遇佳景、临风对月，事须时恁相忆。'},
    {t:'法雄寺东楼',a:'张籍〔唐代〕',c:'汾阳旧宅今为寺，犹有当时歌舞楼。\n四十年来车马绝，古槐深巷暮蝉愁。'},
    {t:'法云',a:'王安石〔宋代〕',c:'法云但见脊，细路埋桑麻。\n扶舆度焰水，窈窕一川花。\n一川花好泉亦好，初晴涨绿深於草。\n汲泉养之花不老，花底幽人自衰槁。'},
    {t:'法云寺双桧·一作晋朝柏树',a:'温庭筠〔唐代〕',c:'晋朝名辈此离群，想对浓阴去住分。题处尚寻王内史，\n画时应是顾将军。长廊夜静声疑雨，古殿秋深影胜云。\n一下南台到人世，晓泉清籁更难闻。'},
    {t:'蕃女怨·碛南沙上惊雁起',a:'温庭筠〔唐代〕',c:'碛南沙上惊雁起，飞雪千里。玉连环，金镞箭，年年征战。画楼离恨锦屏空，杏花红。'},
    {t:'蕃女怨·万枝香雪开已遍',a:'温庭筠〔唐代〕',c:'万枝香雪开已遍，细雨双燕。钿蝉筝，金雀扇，画梁相见。雁门消息不归来，又飞回。'},
    {t:'返照',a:'杜甫〔唐代〕',c:'楚王宫北正黄昏，白帝城西过雨痕。\n返照入江翻石壁，归云拥树失山村。\n衰年肺病惟高枕，绝塞愁时早闭门。\n不可久留豺虎乱，南方实有未招魂。'},
    {t:'饭覆釜山僧',a:'王维〔唐代〕',c:'晚知清净理，日与人群疏。\n将候远山僧，先期扫弊庐。\n果从云峰里，顾我蓬蒿居。\n藉草饭松屑，焚香看道书。\n燃灯昼欲尽，鸣磬夜方初。\n一悟寂为乐，此生闲有余。\n思归何必深，身世犹空虚。'},
    {t:'泛前陂',a:'王维〔唐代〕',c:'秋空自明迥，况复远人间。\n畅以沙际鹤，兼之云外山。\n澄波澹将夕，清月皓方闲。\n此夜任孤棹，夷犹殊未还。'},
    {t:'泛清波摘遍',a:'晏几道〔宋代〕',c:'催花雨小，著柳风柔，都似去年时候好。露红烟绿，尽有狂情斗春早。长安道。秋千影里，丝管声中，谁放艳阳轻过了。倦客登临，暗惜光阴恨多少。\n楚天渺。归思正如乱云，短梦未成芳草。空把吴霜鬓华，自悲清晓。帝城杳。双凤旧约渐虚，孤鸿后期难到。且趁朝花夜月，翠尊频倒。'},
    {t:'泛三江海浦',a:'陆游〔宋代〕',c:'鳌负三山碧海秋，龙骧万斛放翁游。\n少舒我辈胸中气，一扫群儿分外愁。\n醉斩长鲸倚天剑，笑凌骇浪济川舟。\n悠然高咏平生事，龌龊宁能老故丘。'},
    {t:'泛舟观桃花五首·其二',a:'陆游〔宋代〕',c:'桃源只在镜湖中，影落清波十里红。\n自别西川海棠后，初将烂醉答春风。'},
    {t:'范公丛竹歌',a:'岑参〔唐代〕',c:'世人见竹不解爱，知君种竹府城内。此君托根幸得地，\n种来几时闻已大。盛暑翛翛丛色寒，闲宵槭槭叶声干。\n能清案牍帘下见，宜对琴书窗外看。为君成阴将蔽日，\n迸笋穿阶踏还出。守节偏凌御史霜，虚心愿比郎官笔。\n君莫爱南山松树枝，竹色四时也不移。寒天草木黄落尽，\n犹自青青君始知。'},
    {t:'范雎',a:'王安石〔宋代〕',c:'范雎相秦倾九州，一言立断魏齐头。\n世间祸故不可忽，箦中死尸能报雠。'},
    {t:'范文正公家训百字铭',a:'范仲淹〔宋代〕',c:'孝道当竭力，忠勇表丹诚；\n兄弟互相助，慈悲无边境。\n勤读圣贤书，尊师如重亲；\n礼义勿疏狂，逊让敦睦邻。\n敬长与怀幼，怜恤孤寡贫；\n谦恭尚廉洁，绝戒骄傲情。\n字纸莫乱废，须报五谷恩；\n作事循天理，博爱惜生灵。\n处世行八德，修身奉祖神；\n儿孙坚心守，成家种善根。'},
    {t:'方城其八',a:'柳宗元〔唐代〕',c:'蔡人歌矣，蔡风和矣。孰颣蔡初，胡甈尔居。式慕以康，为愿有馀。\n是究是咨，皇德既舒。'},
    {t:'方城其七',a:'柳宗元〔唐代〕',c:'乃谕乃止，蔡有厚喜。完其室家，仰父俯子。汝水沄沄，既清而瀰。\n蔡人行歌，我步逶迟。'},
    {t:'芳草渡·别恨',a:'周邦彦〔宋代〕',c:'昨夜里，又再宿桃源，醉邀仙侣。听碧窗风快，珠帘半卷疏雨。多少离恨苦。方留连啼诉。凤帐晓，又是匆匆，独自归去。\n愁睹。满怀泪粉，瘦马冲泥寻去路。谩回首、烟迷望眼，依稀见朱户。似痴似醉，暗恼损、凭阑情绪。淡暮色，看尽栖鸦乱舞。'},
    {t:'房兵曹胡马诗',a:'杜甫〔唐代〕',c:'胡马大宛名，锋棱瘦骨成。\n竹批双耳峻，风入四蹄轻。\n所向无空阔，真堪托死生。\n骁腾有如此，万里可横行。'},
    {t:'房中曲',a:'李商隐〔唐代〕',c:'蔷薇泣幽素，翠带花钱小。\n娇郎痴若云，抱日西帘晓。\n枕是龙宫石，割得秋波色。\n玉簟失柔肤，但见蒙罗碧。\n忆得前年春，未语含悲辛。\n归来已不见，锦瑟长于人。\n今日涧底松，明日山头檗。\n愁到天池翻，相看不相识。'},
    {t:'房中思',a:'李贺〔唐代〕',c:'新桂如蛾眉，秋风吹小绿。\n行轮出门去，玉銮声断续。\n月轩下风露，晓庭自幽涩。\n谁能事贞素，卧听莎鸡泣。'},
    {t:'访戴天山道士不遇',a:'李白〔唐代〕',c:'犬吠水声中，桃花带露浓。\n树深时见鹿，溪午不闻钟。\n野竹分青霭，飞泉挂碧峰。\n无人知所去，愁倚两三松。'},
    {t:'访疾',a:'孟郊〔唐代〕',c:'冷气入疮痛，夜来痛如何。疮从道怒生，岂以私恨多。\n道怒亦非道，怒消乃天和。古有焕辉句，嵇康闲婆娑。\n请君吟啸之，正气庶不讹。'},
    {t:'访秋',a:'李商隐〔唐代〕',c:'酒薄吹还醒，楼危望已穷。\n江皋当落日，帆席见归风。\n烟带龙潭白，霞分鸟道红。\n殷勤报秋意，只是有丹枫。'},
    {t:'访陕郊魏疏处士',a:'范仲淹〔宋代〕',c:'贤哉先处士，天书召不起。\n云夫齿孤风，复为隐君子。\n有石砺其齿，有泉洗其耳。\n下瞰红尘路，荣波无穷已。\n孜孜朝市人，同在风波里。\n大为高士笑，誓不拾青紫。\n我亦宠辱流，所幸无愠喜。\n进者道之行，退者道之止。\n矧今领方面，岂称长城倚。\n来访卧云人，而请益诸己。\n得无长者言，佩之玉非美。'},
    {t:'访隐者',a:'王安石〔宋代〕',c:'童子穿云晚未归，谁收松下著残棋。\n先生醉卧落花里，春去人间总不知。'},
    {t:'访隐者不遇成二绝',a:'李商隐〔唐代〕',c:'秋水悠悠浸墅扉，梦中来数觉来稀。\n玄蝉去尽叶黄落，一树冬青人未归。\n城郭休过识者稀，哀猿啼处有柴扉。\n沧江白石樵渔路，日暮归来雨满衣。'},
    {t:'访隐者不遇成二绝·其二',a:'李商隐〔唐代〕',c:'城郭休过识者稀，哀猿啼处有柴扉。\n沧江白石渔樵路，日暮归来雨满衣。'},
    {t:'访知玄上人遇暴经因有赠',a:'温庭筠〔唐代〕',c:'缥帙无尘满画廊，钟山弟子静焚香。惠能未肯传心法，\n张湛徒劳与眼方。风飏檀烟销篆印，日移松影过禅床。\n客儿自有翻经处，江上秋来蕙草荒。'},
    {t:'访朱放山人',a:'皎然〔唐代〕',c:'野人未相识，何处异乡隔。昨逢云阳信，教向云阳觅。\n空闻天上风，飘飖不可觌。应非矍铄翁，或是沧浪客。\n早晚从我游，共携春山策。'},
    {t:'放翁家训',a:'陆游〔宋代〕',c:'后生才锐者，最易坏。若有之，父兄当以为忧，不可以为喜也。切须常加简束，令熟读经学，训以宽厚恭谨，勿令与浮薄者游处。自此十许年，志趣自成。不然，其可虑之事，盖非一端。吾此言，后生之药石也，各须谨之，毋贻后悔。'},
    {t:'放言十首',a:'黄庭坚〔宋代〕',c:'废兴宜有命，得失但自知。\n踽踽众所忌，悠悠谁与归。\n吾义苟不存，岂更月攘鸡。\n风清闻鹤唳，想见南山栖。'},
    {t:'放言五首·其二',a:'白居易〔唐代〕',c:'世途倚伏都无定，尘网牵缠卒未休。\n祸福回还车转毂，荣枯反覆手藏钩。\n龟灵未免刳肠患，马失应无折足忧。\n不信请看弈棋者，输赢须待局终头。'},
    {t:'放言五首·其三',a:'白居易〔唐代〕',c:'赠君一法决狐疑，不用钻龟与待蓍。\n试玉要烧三日满，辨材须待七年期。\n周公恐惧流言日，王莽谦恭未篡时。\n向使当初身便死，一生真伪复谁知？'},
    {t:'放言五首·其四',a:'白居易〔唐代〕',c:'谁家宅第成还破，何处亲宾哭复歌？\n昨日屋头堪炙手，今朝门外好张罗。\n北邙未省留闲地，东海何曾有定波。\n莫笑贱贫夸富贵，共成枯骨两如何？'},
    {t:'放言五首·其五',a:'白居易〔唐代〕',c:'泰山不要欺毫末，颜子无心羡日彭。\n松树千年终是朽，槿花一日自为荣。\n何须恋世常忧死，亦莫嫌身漫厌生。\n生去死来都是幻，幻人哀乐系何情。'},
    {t:'放言五首·其一',a:'白居易〔唐代〕',c:'朝真暮伪何人辨，古往今来底子无。\n但爱臧生能诈圣，可知甯子解佯愚。\n草萤有耀终非火，荷露虽团岂是珠。\n不取燔柴兼照乘，可怜光彩亦何殊。'},
    {t:'废居行',a:'张籍〔唐代〕',c:'胡马崩腾满阡陌，都人避乱唯空宅。宅边青桑垂宛宛，\n野蚕食叶还成茧。黄雀衔草入燕窠，啧啧啾啾白日晚。\n去时禾黍埋地中，饥兵掘土翻重重。鸱枭养子庭树上，\n曲墙空屋多旋风。乱定几人还本土，唯有官家重作主。'},
    {t:'废瑟词',a:'张籍〔唐代〕',c:'古瑟在匣谁复识，玉柱颠倒朱丝黑。千年曲谱不分明，\n乐府无人传正声。秋虫暗穿尘作色，腹中不辨工人名。\n几时天下复古乐，此瑟还奏云门曲。'},
    {t:'粉蝶儿·和赵晋臣敷文赋落花',a:'辛弃疾〔宋代〕',c:'昨日春如，十三女儿学绣。一僝僝、不教花瘦。甚无情，便下得，雨僝风僽。向园林、铺作地衣红绉。\n时今春似，轻薄荡子难久。记前时、送春归后。把春波，都酿作，一江春酎。约清愁、杨柳岸边相候。'},
    {t:'粉蝶儿慢',a:'周邦彦〔宋代〕',c:'宿雾藏春，余寒带雨，占得群芳叶晚。艳初弄秀倚东风娇懒。隔叶黄鹂传好音，唤入深丛中探。眷枝新，比昨朝、又早红稀香浅。\n眷恋。重来倚槛。当韶华、未可轻辜双眼。赏心随分乐，有清尊檀板。每岁嬉游能几日，莫使一声歌欠。忍因循、片花飞、又成春减。'},
    {t:'丰城荣光书院',a:'朱熹〔宋代〕',c:'一道荣光带碧山，天风吹雨渡云关。树浮空翠迷村坞，泉落飞虹泻石湾。\n赤岭豹栖朝气隐，剑潭龙起夜光寒。咿唔何处经年韵，多在湖东乔木间。'},
    {t:'风',a:'李商隐〔唐代〕',c:'撩钗盘孔雀，恼带拂鸳鸯。\n罗荐谁教近，斋时锁洞房。'},
    {t:'风花',a:'杨万里〔宋代〕',c:'海棠桃李雨中空，更著清明两日风。\n风似病癫无藉在，花如中酒不惺松。\n身行楚峤远更远，家寄秦淮东复东。\n道是残红何足惜，後来并恐没残红。'},
    {t:'风凉原上作',a:'王昌龄〔唐代〕',c:'阴岑宿云归，烟雾湿松柏。风凄明初晓，下岭望川泽。\n远山无晦明，秋水千里白。佳气盘未央，圣王在凝碧。\n关门阻天下，信是帝王宅。海内方晏然，庙堂有奇策。\n时贞守全运，罢去游说客。予忝兰台王，幽寻免贻责。'},
    {t:'风流子·愁怨',a:'周邦彦〔宋代〕',c:'枫林凋晚叶，关河迥，楚客惨将凉。望一川暝霭，雁声哀怨；半规凉月，人影参差。酒醒后，泪花销回蜡，风幕卷金泥。砧杵韵高，唤回残梦；绮罗香减，牵起馀悲。\n亭皋分襟地，难拚处，偏是掩面牵衣。何况怨怀长结，重见无期。想寄恨书中，银钩空满；断肠声里，玉筯还垂。多少暗愁密意，唯有天知。'},
    {t:'风流子·东风吹碧草',a:'秦观〔宋代〕',c:'东风吹碧草，年华换、行客老沧洲。见梅吐旧英，柳摇新绿，恼人春色，还上枝头，寸心乱，北随云黯黯，东逐水悠悠。斜日半山，暝烟两岸，数声横笛，一叶扁舟。\n青门同携手，前欢记、浑似梦里扬州。谁念断肠南陌，回首西楼。算天长地久，有时有尽，奈何绵绵，此恨难休。拟待倩人说与，生怕人愁。'},
    {t:'风流子·秋郊即事',a:'纳兰性德〔清代〕',c:'平原草枯矣，重阳后、黄叶树骚骚。记玉勒青丝，落花时节，曾逢拾翠，忽听吹箫。今来是、烧痕残碧尽，霜影乱红凋。秋水映空，寒烟如织，皂雕飞处，天惨云高。\n人生须行乐，君知否？容易两鬓萧萧。自与东君作别，刬地无聊。算功名何许，此身博得，短衣射虎，沽酒西郊。便向夕阳影里，倚马挥毫。'},
    {t:'风流子·新绿小池塘',a:'周邦彦〔宋代〕',c:'新绿小池塘，风帘动、碎影舞斜阳。羡金屋去来，旧时巢燕；土花缭绕，前度莓墙。绣阁里、凤帏深几许？听得理丝簧。欲说又休，虑乖芳信；未歌先噎，愁近清觞。\n遥知新妆了，开朱户，应自待月西厢。最苦梦魂，今宵不到伊行。问甚时说与，佳音密耗，寄将秦镜，偷换韩香？天便教人，霎时厮见何妨。'},
    {t:'风入松',a:'陆游〔宋代〕',c:'十年裘马锦江滨。酒隐红尘。万金选胜莺花海，倚疏狂、驱使青春。吹笛鱼龙尽出，题诗风月俱新。\n自怜华发满纱巾。犹是官身。凤楼常记当年语，问浮名、何似身亲。欲寄吴笺说与，这回真个闲人。'},
    {t:'风入松·陈文卿酒边偶赋',a:'张炎〔宋代〕',c:'小窗晴碧飐帘波。昼影舞飞梭。无春休问花多少，柳成阴、春已无多。金字初寻小扇，铢衣早试丹罗。\n园林未肯受清和。人醉牡丹坡。啸歌且尽平生事，问东风、毕竟如何。燕子寻常巷陌，酒边莫唱西河。'},
    {t:'风入松·赋稼村',a:'张炎〔宋代〕',c:'老来学圃乐年华。茅屋短篱遮。儿孙戏逐田翁去，小桥横、路转三叉。细雨一犁春意，西风万宝生涯。\n携筇犹记度晴沙。流水带寒鸦。门前少得宽闲地，绕平畴、尽是桑麻。却笑牧童遥指，杏花深处人家。'},
    {t:'风入松·柳阴庭院杏梢墙',a:'晏几道〔宋代〕',c:'柳阴庭院杏梢墙。依旧巫阳。凤箫已远青楼在，水沈谁、复暖前香。临镜舞鸾离照，倚筝飞雁辞行。\n坠鞭人意自凄凉。泪眼回肠。断云残雨当年事，到如今、几处难忘。两袖晓风花陌，一帘夜月兰堂。'},
    {t:'风入松·满头风雪昔同游',a:'张炎〔宋代〕',c:'久别曾心传，近会于竹林清话。作未足而离歌发，情如之何，因作此解，时至大庚戌七月也。\n满来风雪昔同游。同载月明舟。回来又续西湖梦，绕江南、那处无愁。赢得如今老大，依然只是漂流。\n故人翦烛对花讴。不记此身浮。征衣冷落荷衣暖，径虽荒、也合归休。明□□□烟水，相思却在并州。'},
    {t:'风入松·闰元宵',a:'张炎〔宋代〕',c:'向人圆月转分明。箫鼓又逢迎。风吹不老蛾儿闹，绕玉梅、犹恋香心。报道依然放夜，何妨款曲行春。\n锦灯重见丽繁星。水影动梨云。今朝准拟花朝醉，奈今宵、别是光阴。帘底听人笑语，莫教迟了□青。'},
    {t:'风入松·听琴中弹樵歌',a:'张炎〔宋代〕',c:'松风掩昼隐深清。流水自泠泠。一从柯烂归来后，爱弦声、不爱枰声。颇笑山中散木，翻怜爨下劳薪。\n透云远响正丁丁。孤凤划然鸣。疑行岭上千秋雪，语高寒、相应何人。回首更无寻处，一江风雨潮生。'},
    {t:'风入松·危楼古镜影犹寒',a:'张炎〔宋代〕',c:'危楼古镜影犹寒。倒景忽相看。桃花不识东西晋，想如今、也梦邯郸。缥缈神仙海上，飘零图画人间。\n宝光丹气共回环。水弱小舟闲。秋风难老三珠树，尚依依、脆管清弹。说与霓裳莫舞，银桥不到深山。'},
    {t:'风入松·为山村赋',a:'张炎〔宋代〕',c:'晴岚暖翠护烟霞。乔木晋人家。桑居只恐归图画，唤樵青、多种桑麻。门掩推敲古意，泉分冷淡茶涯。\n无边风月乐年华。留客可茶瓜。任他车马虽嫌僻，笑喧喧、流水寒鸦。小隐正宜深静，休栽湖上梅花。'},
    {t:'风入松·西山',a:'秦观〔宋代〕',c:'崇峦雨过碧瑶光。花木递幽香。清冥杳霭无尘到，比龙宫、分外清凉。霁景一楼苍翠。薰风满壑俳簧。\n不妨终日此徜徉。宇宙总俳场。石边试剑人何在，但荒烟、蔓草迷茫。好酹杯中芳酒，少留树杪斜阳。'},
    {t:'风入松·心心念念忆相逢',a:'晏几道〔宋代〕',c:'心心念念忆相逢。别恨谁浓。就中懊恼难拚处，是擘钗、分钿匆匆。却似桃源路失，落花空记前踪。\n彩笺书尽浣溪红。深意难通。强欢殢酒图消遣，到醒来、愁闷还重。若是初心未改，多应此意须同。'},
    {t:'风入松·岫云',a:'张炎〔宋代〕',c:'卷舒无意入虚玄。丘壑伴云烟。石根清气千年润，覆孤松、深护啼猿。霭霭静随仙隐，悠悠闲对僧眠。\n傍花懒向小溪边。空谷覆流泉。浮踪自感今如此，已无心、万里行天。记得晋人归去，御风飞过斜川。'},
    {t:'风入松·一春不是不寻春',a:'张炎〔宋代〕',c:'一春不是不寻春。终是不忺人。好怀渐向中年减，对歌钟、浑没心情。短帽怕黏飞絮，轻衫压扑游尘。暖香十里软莺声。小舫绿杨阴。梦随蝴蝶飘零後，尚依依、花月关心。惆怅一株梨雪，明年甚处清明。'},
    {t:'风入松·与王彦常游会仙亭',a:'张炎〔宋代〕',c:'爱闲能有几人来。松下独徘徊。尘虚冷淡神仙事，笑名场、多少尘埃。漱齿石边危坐，洗心易里明怀。\n划然长啸白云堆。更待月明□。一瓢春水山中饮，喜无人、踏破苍苔。开了桃花半树，此游不是天台。'},
    {t:'风入松·赠蒋道录溪山堂',a:'张炎〔宋代〕',c:'门前山可久长看。留住白云难。深虚却与云相傍，对白云、何必深山。爽气潜生树石，晴光竟入衣干。\n旧家三径竹千竿。苍雪拂衣寒。绿蓑青笠玄真子，钓风波、不是真闲。得似壶中日月，依然只在人间。'},
    {t:'风入松·酌惠山水',a:'张炎〔宋代〕',c:'一瓢饮水曲肱眠。此乐不知年。今朝忽上龙峰顶。却元来、有此甘泉。洗却平生尘土，慵游万里山川。\n照人如鉴止如渊。古窦暗涓涓。当时桑苎今何在，想松风、吹断茶烟。著我白云堆里，安知不是神仙。'},
    {t:'风水洞',a:'范仲淹〔宋代〕',c:'神仙一去几千年，自遣秦人不得还。\n春尽桃花无处觅，空馀流水到人间。'},
    {t:'风雨',a:'陆游〔宋代〕',c:'七十年来乐太平，白头父子事春耕。\n因思世事悲身事，更听风声杂雨声。\n四海故人强半死，一襟清泪对谁倾？\n新春要觅烧丹处，不住青城住赤城。'},
    {t:'风雨',a:'李商隐〔唐代〕',c:'凄凉宝剑篇，羁泊欲穷年。\n黄叶仍风雨，青楼自管弦。\n新知遭薄俗，旧好隔良缘。\n心断新丰酒，销愁斗几千。'},
    {t:'沣上对月，寄孔谏议',a:'韦应物〔唐代〕',c:'思怀在云阙，泊素守中林。出处虽殊迹，明月两知心。'},
    {t:'沣上寄幼遐',a:'韦应物〔唐代〕',c:'寂寞到城阙，惆怅返柴荆。端居无所为，念子远徂征。\n夏昼人已息，我怀独未宁。忽从东斋起，兀兀寻涧行。\n罥挂丛榛密，披玩孤花明。旷然西南望，一极山水情。\n周览同游处，逾恨阻音形。壮图非旦夕，君子勤令名。\n勿复久留燕，蹉跎在北京。'},
    {t:'沣上醉题寄涤武',a:'韦应物〔唐代〕',c:'芳园知夕燕，西郊已独还。谁言不同赏，俱是醉花间。'},
    {t:'沣头送蒋侯',a:'岑参〔唐代〕',c:'君住沣水北，我家沣水西。两村辨乔木，五里闻鸣鸡。\n饮酒溪雨过，弹棋山月低。徒闻蒋生径，尔去谁相携。'},
    {t:'封丘作',a:'高适〔唐代〕',c:'我本渔樵孟诸野，一生自是吏吏者。\n乍可狂歌草泽中，宁堪作吏风尘下？\n只言小邑无所为，公碎百命皆有期。\n拜迎长官心欲碎，鞭挞黎庶令人悲。\n归来向家问妻子，举家尽笑今如此。\n生命应须南亩田，世情尽付东流水。\n梦想旧山安在哉，为衔君命且迟回。\n乃知梅福徒为尔，转忆陶潜归去来。'},
    {t:'封舒国公·其二',a:'王安石〔宋代〕',c:'桐乡山远复川长，紫翠连城碧满隍。\n今日桐乡谁爱我，当时我自爱桐乡。'},
    {t:'蜂',a:'李商隐〔唐代〕',c:'小苑华池烂熳通，后门前槛思轻穷。\n宓妃腰细才胜露，赵后身轻欲倚风。\n红壁寂寥崖蜜尽，碧帘迢递雾巢空。\n青陵粉蝶休离恨，长定相逢二月中。'},
    {t:'蜂儿',a:'杨万里〔宋代〕',c:'密蜂不食人间仓，玉露为酒花为粮。\n作蜜不忙采花忙，蜜成犹带百花香。\n蜜成万蜂不敢尝，要输蜜国供蜂王。\n蜂王未及享，人已割蜜房。\n老蜜已成蜡，嫩蜜方成蜜。\n蜜房蜡片割无余，老饕更来搜我室。\n老蜂无味秪有滓，幼蜂初化未成儿。\n老饕火攻不知止，既毁我室取我子。'},
    {t:'冯小怜',a:'李贺〔唐代〕',c:'湾头见小怜，请上琵琶弦。\n破得春风恨，今朝直几钱。\n裙垂竹叶带，鬓湿杏花烟。\n玉冷红丝重，齐宫妾驾鞭。'},
    {t:'逢白公',a:'元稹〔唐代〕',c:'远路事无限，相逢唯一言。月色照荣辱，长安千万门。'},
    {t:'逢故人',a:'杜牧〔唐代〕',c:'年年不相见，相见却成悲。教我泪如霰，嗟君发似丝。\n正伤携手处，况值落花时。莫惜今宵醉，人间忽忽期。'},
    {t:'逢故人',a:'张籍〔唐代〕',c:'山东一十馀年别，今日相逢在上都。\n说尽向来无限事，相看摩捋白髭须。'},
    {t:'逢贾岛',a:'张籍〔唐代〕',c:'僧房逢着款冬花，出寺行吟日已斜。\n十二街中春雪遍，马蹄今去入谁家。'},
    {t:'逢旧',a:'白居易〔唐代〕',c:'我梳白发添新恨，君扫青蛾减旧容。\n应被傍人怪惆怅，少年离别老相逢。'},
    {t:'逢入京使',a:'岑参〔唐代〕',c:'故园东望路漫漫，双袖龙钟泪不干。\n马上相逢无纸笔，凭君传语报平安。'},
    {t:'逢王建有赠',a:'张籍〔唐代〕',c:'年状皆齐初有髭，鹊山漳水每追随。使君座下朝听易，\n处士庭中夜会诗。新作句成相借问，闲求义尽共寻思。\n经今三十馀年事，却说还同昨日时。'},
    {t:'逢谢偃',a:'高适〔唐代〕',c:'红颜怆为别，白发始相逢。唯馀昔时泪，无复旧时容。'},
    {t:'逢杨开府',a:'韦应物〔唐代〕',c:'少事武皇帝，无赖恃恩私。\n身作里中横，家藏亡命儿。\n朝持樗蒲局，暮窃东邻姬。\n司隶不敢捕，立在白玉墀。\n骊山风雪夜，长杨羽猎时。\n一字都不识，饮酒肆顽痴。\n武皇升仙去，憔悴被人欺。\n读书事已晚，把笔学题诗。\n两府始收迹，南宫谬见推。\n非才果不容，出守抚惸嫠。\n忽逢杨开府，论旧涕俱垂。\n坐客何由识，惟有故人知。'},
    {t:'凤吹笙曲',a:'李白〔唐代〕',c:'仙人十五爱吹唇，学得昆丘彩天鸣。\n始闻炼气餐金液，复道朝天赴玉京。\n玉京迢迢几千里，天唇去去无穷已。\n欲叹离声发绛唇，更嗟别调流纤指。\n此时惜别讵堪闻，此地相看未忍分。\n重吟真曲和清吹，却奏仙歌响绿云。\n绿云紫气向函关，访道应寻缑氏山。\n莫学吹唇王子晋，一遇浮丘断不还。'},
    {t:'凤孤飞',a:'晏几道〔宋代〕',c:'一曲画楼钟动，宛转歌声缓。绮轻飞尘满。更少待、金蕉暖。\n细雨轻寒今夜短。依前是、粉墙别馆。端的欢期应未晚。奈归云难管。'},
    {t:'凤归云',a:'柳永〔宋代〕',c:'恋帝里，金谷园林，平康巷陌，触处繁华，连日疏狂，未\n尝轻负，寸心双眼。况佳\n人、尽天外行云，掌上飞燕。向玳筵、一一皆妙选。长是\n因酒沉迷，被花萦绊。\n更可惜、淑景亭台，暑天枕簟。霜月夜凉，雪霰朝飞，一\n岁风光，尽堪随分，俊游\n清宴。算浮生事，瞬息光阴，锱铢名宦。正欢笑，试恁暂\n时分散。却是恨雨愁云，\n地遥天远。'},
    {t:'凤归云·恋帝里',a:'柳永〔宋代〕',c:'恋帝里、金谷园林，平康巷陌，触处繁华，连日疏狂，未尝轻负、寸心双眼。况佳人、尽天外行云，掌上飞燕。向玳筵、一一皆妙选。长是因酒沈迷，被花萦绊。\n更可惜、淑景亭台，暑天枕簟。霜月夜凉，雪霰朝飞，一岁风光，尽堪随分、俊游清宴。算浮生事，瞬息光阴，锱铢名宦。正欢笑、试恁暂时分散。却是恨雨愁云，地遥天远。'},
    {t:'凤归云·向深秋',a:'柳永〔宋代〕',c:'向深秋，雨馀爽气肃西郊。陌上夜阑，襟袖起凉飙。天末残星，流电未灭，闪闪隔林梢。又是晓鸡声断，阳乌光动，渐分山路迢迢。\n驱驱行役，苒苒光阴，蝇头利禄，蜗角功名，毕竟成何事，漫相高。抛掷云泉，狎玩尘土，壮节等闲消。幸有五湖烟浪，一船风月，会须归去老渔樵。'},
    {t:'凤凰阁',a:'柳永〔宋代〕',c:'匆匆相见，懊恼恩情太薄。霎时云雨人抛却。教我行思坐想，肌肤如削。恨只恨、相违旧约。\n相思成病，那更潇潇雨落。断肠人在阑干角。山远水远人远，音信难托。这滋味、黄昏又恶。'},
    {t:'凤凰山',a:'王安石〔宋代〕',c:'欢乐欲与少年期，人生百年常为迟。\n白头富贵何所用，气力但为忧勤衰。\n愿为五陵轻薄儿，生在贞观开元时。\n斗鸡走犬过一生，天地安危两不知。'},
    {t:'凤凰台',a:'周邦彦〔宋代〕',c:'危台飘尽碧梧花，胜地凄凉属梵家。\n凤入紫云招不得，木鱼堂殿下饥鸦。'},
    {t:'凤凰台上忆吹箫',a:'张炎〔宋代〕',c:'赵主簿，姚江人也。风流蕴藉，放其花柳，老之将至，况味凄然。以其号孤篷，嘱余赋之。\n水国浮家，得村古隐，浪游惯占花深。犹记得、琵琶半面，曾湿衫青。不道江空岁晚，桃叶渡、还叹飘零。因乘兴，醉梦醒时，却是山阴。\n投闲倦呼俦侣，竟棹入芦花，俗客难寻。风渺渺、云拖暮雪，独钓寒清。远溯流光万里，浑错认、叶竹寰瀛。元来是、天上太乙真人。'},
    {t:'凤来朝·越调佳人',a:'周邦彦〔宋代〕',c:'逗晓看娇面。小窗深、弄明未遍。中残朱宿粉云鬟乱。最好是、帐中见。\n说梦双蛾微敛。锦衾温、酒香未断。待起难舍拚。任日炙、画栏暖。'},
    {t:'凤栖梧·帘内清歌帘外宴',a:'柳永〔宋代〕',c:'帘内清歌帘外宴。虽爱新声，不见如花面。牙板数敲珠一串，梁尘暗落琉璃盏。\n桐树花深孤凤怨。渐遏遥天，不放行云散。坐上少年听不惯，玉山未倒肠先断。'},
    {t:'凤衔杯·留花不住怨花飞',a:'晏殊〔宋代〕',c:'留花不住怨花飞。向南园、情绪宿宿。可惜倒红斜白、一枝枝。经宿雨、又离披。\n凭朱槛，把金卮。对芳丛、惆怅多时。何况旧欢新恨、阻心期。空满眼、是相思。'},
    {t:'凤衔杯·柳条花颣恼青春',a:'晏殊〔宋代〕',c:'柳条花颣恼青春，更那堪、飞絮纷纷。一曲细丝清脆、倚朱唇。斟绿酒、掩红巾。\n追往事，惜芳辰。暂时间、留住行云。端的自家心下、眼中人。到处里、觉尖新。'},
    {t:'凤衔杯·青蘋昨夜秋风起',a:'晏殊〔宋代〕',c:'青蘋昨夜秋风起，无限个、露莲目倚。独凭朱阑、愁望晴天际。空目断、遥山翠。\n彩笺长，锦书细。谁信道、两情难寄。可惜良辰好景、欢娱地，只恁空憔悴。'},
    {t:'凤衔杯·有美瑶卿能染翰',a:'柳永〔宋代〕',c:'有美瑶卿能染翰。千里寄、小诗窗简。想初襞苔笺，旋挥翠管红窗畔。渐玉箸、银钩满。\n锦囊收，犀轴卷。常珍重、小斋吟玩。更宝若珠玑，置之怀袖时时看。似频见、千娇面。'},
    {t:'凤衔杯·追悔当初孤深愿',a:'柳永〔宋代〕',c:'追悔当初孤深愿。经年价、两成幽怨。任越水吴山，似屏如障堪游玩。奈独自、慵抬眼。\n赏烟花，听弦管。图欢笑、转加肠断。更时展丹青，强拈书信频频看。又争似、亲相见。'},
    {t:'奉酬北海李太守丈人夏日平阴亭',a:'高适〔唐代〕',c:'天子股肱守，丈人山岳灵。出身侍丹墀，举翮凌青冥。\n当昔皇运否，人神俱未宁。谏官莫敢议，酷吏方专刑。\n谷永独言事，匡衡多引经。两朝纳深衷，万乘无不听。\n盛烈播南史，雄词豁东溟。谁谓整隼旟，翻然忆柴扃。\n寄书汶阳客，回首平阴亭。开封见千里，结念存百龄。\n隐轸江山丽，氛氲兰茝馨。自怜遇时休，漂泊随流萍。\n春野变木德，夏天临火星。一生徒羡鱼，四十犹聚萤。\n从此日闲放，焉能怀拾青。'},
    {t:'奉酬九日东峰道人溥公见赠之作',a:'朱熹〔宋代〕',c:'几年回首梦云关，此日重来两鬓斑。\n点检梁间新岁月，招呼台上旧溪山。\n三生漫说终无据，万法由来本自闲。\n一笑支郎又相恼，新诗不落语言间。'},
    {t:'奉酬李都督表丈早春作',a:'杜甫〔唐代〕',c:'力疾坐清晓，来诗悲早春。\n转添愁伴客，更觉老随人。\n红入桃花嫩，青归柳叶新。\n望乡应未已，四海尚风尘。'},
    {t:'奉酬永叔见赠',a:'王安石〔宋代〕',c:'欲传道义心犹在，强学文章力敢穷。\n他日若能窥孟子，终身何敢望韩公。\n抠衣最出诸生後，倒屣尝倾广座中。\n只恐虚名因此得，嘉篇为贶岂宜蒙。'},
    {t:'奉酬袁使君送陆灞却回期道寺院',a:'皎然〔唐代〕',c:'欲别湖上客，暮期西林还。高歌风音表，放舟月色间。\n更人莫报夜，禅阁本无关。'},
    {t:'奉答李和甫代简二绝句',a:'黄庭坚〔宋代〕',c:'山色江声相与清，卷帘待得月华生。\n可怜一曲并船笛，说尽故人离别情。\n梦中往事随心见，醉里繁华乱眼生。\n长为风流恼人病，不如天性总无情。'},
    {t:'奉答圣思讲论语长句',a:'黄庭坚〔宋代〕',c:'簿领文书千笔秃，公庭嚚讼百虫鸣。\n时从退食须臾顷，喜听邻家讽诵声。\n观海诸君知浩渺，学山他日看崇成。\n暮堂吏退张灯火，抱取鲁论来讲评。'},
    {t:'奉和杜相公初发京城作',a:'岑参〔唐代〕',c:'按节辞黄阁，登坛恋赤墀。衔恩期报主，授律远行师。\n野鹊迎金印，郊云拂画旗。叨陪幕中客，敢和出车诗。'},
    {t:'奉和杜相公发益昌',a:'岑参〔唐代〕',c:'相国临戎别帝京，拥麾持节远横行。\n朝登剑阁云随马，夜渡巴江雨洗兵。\n山花万朵迎征盖，川柳千条拂去旌。\n暂到蜀城应计日，须知明主待持衡。'},
    {t:'奉和二兄罢使遣马归延州',a:'李贺〔唐代〕',c:'空留三尺剑，不用一丸泥。\n马向沙场去，人归故国来。\n笛愁翻陇水，酒喜沥春灰。\n锦带休惊雁，罗衣尚斗鸡。\n还吴已渺渺，入郢莫凄凄。\n自是桃李树，何畏不成蹊。'},
    {t:'奉和皇帝上礼抚事述怀应制',a:'陈子昂〔唐代〕',c:'大君忘自我，应运居紫宸。揖让期明辟，讴歌且顺人。\n轩宫帝图盛，皇极礼容申。南面朝万国，东堂会百神。\n云陛旂常满，天庭玉帛陈。钟石和睿思，雷雨被深仁。\n承平信娱乐，王业本艰辛。愿罢瑶池宴，来观农扈春。\n卑宫昭夏德，尊老睦尧亲。微臣敢拜手，歌舞颂维新。'},
    {t:'奉和贾至舍人早朝大明宫',a:'杜甫〔唐代〕',c:'五夜漏声催晓箭，九重春色醉仙桃。\n旌旗日暖龙蛇动，宫殿风微燕雀高。\n朝罢香烟携满袖，诗成珠玉在挥毫。\n欲知世掌丝纶美，池上于今有凤毛。'},
    {t:'奉和令公绿野堂种花',a:'白居易〔唐代〕',c:'绿野堂开占物华，路人指道令公家。\n令公桃李满天下，何用堂前更种花。'},
    {t:'奉和陆中丞使君长源寒食日作',a:'皎然〔唐代〕',c:'寒食江天气最清，庾公晨望动高情。因逢内火千家静，\n便睹行春万木荣。深浅山容飞雨细，萦纡水态拂云轻。\n腰章本郡谁相似，数日临人政已成。'},
    {t:'奉和舍人叔直省时思琴',a:'张籍〔唐代〕',c:'蔼蔼紫薇直，秋意深无穷。滴沥仙阁漏，肃穆禁池风。\n竹月泛凉影，萱露澹幽丛。地清物态胜，宵闲琴思通。\n时属雅音际，迥凝虚抱中。达人掌枢近，常与隐默同。'},
    {t:'奉和圣制初出洛城',a:'张九龄〔唐代〕',c:'东土淹龙驾，西人望翠华。山川只询物，宫观岂为家。\n十月回星斗，千官捧日车。洛阳无怨思，巡幸更非赊。'},
    {t:'奉和圣制次成皋先圣擒建德之所',a:'张九龄〔唐代〕',c:'天命诚有集，王业初惟艰。翦商自文祖，夷项在兹山。\n地识斩蛇处，河临饮马间。威加昔运往，泽流今圣还。\n尊祖颂先烈，赓歌安用攀。绍成即我后，封岱出天关。'},
    {t:'奉和圣制次琼岳韵',a:'张九龄〔唐代〕',c:'山祇亦望幸，云雨见灵心。岳馆逢朝霁，关门解宿阴。\n咸京天上近，清渭日边临。我武因冬狩，何言是即禽。'},
    {t:'奉和圣制赐史供奉曲江宴应制',a:'王维〔唐代〕',c:'侍从有邹枚，琼筵就水开。\n言陪柏梁宴，新下建章来。\n对酒山河满，移舟草树回。\n天文同丽日，驻景惜行杯。'},
    {t:'奉和圣制赐诸州刺史以题座右',a:'张九龄〔唐代〕',c:'圣人合天德，洪覆在元元。每劳苍生念，不以黄屋尊。\n兴化俟群辟，择贤守列藩。得人此为盛，咨岳今复存。\n降鉴引君道，殷勤启政门。容光无不照，有象必为言。\n成宪知所奉，致理归其根。肃肃禀玄猷，煌煌戒朱轩。\n岂徒任遇重，兼尔宴锡繁。载闻励臣节，持答明主恩。'},
    {t:'奉和圣制登封礼毕洛城酺宴',a:'张九龄〔唐代〕',c:'大君毕能事，端扆乐成功。运与千龄合，欢将万国同。\n汉酺歌圣酒，韶乐舞薰风。河洛荣光遍，云烟喜气通。\n春华顿觉早，天泽倍知崇。草木皆沾被，犹言不在躬。'},
    {t:'奉和圣制度潼关口号',a:'张九龄〔唐代〕',c:'嶙嶙故城垒，荒凉空戍楼。\n在德不在险，方知王道休。'},
    {t:'奉和圣制过王濬墓',a:'张九龄〔唐代〕',c:'汉王思钜鹿，晋将在弘农。入蜀协长算，平吴成大功。\n与浑虽不协，归皓实为雄。孤绩沦千载，流名感圣衷。\n万乘度荒陇，一顾凛生风。古节犹不弃，今人争效忠。'},
    {t:'奉和圣制经函谷关作',a:'张九龄〔唐代〕',c:'函谷虽云险，黄河已复清。\n圣心无所隔，空此置关城。'},
    {t:'奉和圣制经河上公庙',a:'张九龄〔唐代〕',c:'昔者河边叟，谁知隐与仙。姓名晦不识，章句此空传。\n迹为坐忘晦，言犹强著诠。精灵竟何所，祠宇独依然。\n道在纡宸眷，风行动睿篇。从兹化天下，清净复何先。'},
    {t:'奉和圣制经孔子旧宅',a:'张九龄〔唐代〕',c:'孔门太山下，不见登封时。徒有先王法，今为明主思。\n恩加万乘幸，礼致一牢祠。旧宅千年外，光华空在兹。'},
    {t:'奉和圣制龙池篇',a:'张九龄〔唐代〕',c:'天启神龙生碧泉，泉水灵源浸迤延。飞龙已向珠潭出，\n积水仍将银汉连。岸傍花柳看胜画，浦上楼台问是仙。\n我后元符从此得，方为万岁寿图川。'},
    {t:'奉和圣制暮春送朝集使归郡应制',a:'王维〔唐代〕',c:'万国仰宗周，衣冠拜冕旒。玉乘迎大客，金节送诸侯。\n祖席倾三省，褰帷向九州。杨花飞上路，槐色荫通沟。\n来预钧天乐，归分汉主忧。宸章类河汉，垂象满中州。'},
    {t:'奉和圣制南郊礼毕酺宴',a:'张九龄〔唐代〕',c:'配天昭圣业，率土庆辉光。春发三条路，酺开百戏场。\n流恩均庶品，纵观聚康庄。妙舞来平乐，新声出建章。\n分曹日抱戴，赴节凤归昌。幸奏承云乐，同晞湛露阳。\n气和皆有感，泽厚自无疆。饱德君臣醉，连歌奉柏梁。'},
    {t:'奉和圣制送李尚书入蜀',a:'张九龄〔唐代〕',c:'眷言感忠义，何有间山川。徇节今如此，离情空复然。\n皇心在勤恤，德泽委昭宣。周月成功后，明年或劳还。'},
    {t:'奉和圣制送尚书燕国公赴朔方',a:'张九龄〔唐代〕',c:'宗臣事有征，庙算在休兵。\n天与三台座，人当万里城。\n朔南方偃革，河右暂扬旌。\n宠锡从仙禁，光华出汉京。\n山川勤远略，原隰轸皇情。\n为奏薰琴唱，仍题宝剑名。\n闻风六郡伏，计日五戎平。\n山甫归应疾，留侯功复成。\n歌钟旋可望，衽席岂难行。\n四牡何时入，吾君忆履声。'},
    {t:'奉和圣制送十道采访使及朝集使',a:'张九龄〔唐代〕',c:'三年一上计，万国趋河洛。课最力已陈，赏延恩复博。\n垂衣深共理，改瑟其咸若。首路回竹符，分镳扬木铎。\n戒程有攸往，诏饯无淹泊。昭晰动天文，殷勤在人瘼。\n持久望兹念，克终期所托。行矣当自强，春耕庶秋获。'},
    {t:'奉和圣制途次陕州作',a:'张九龄〔唐代〕',c:'驰道当河陕，陈诗问国风。川原三晋别，襟带两京同。\n后殿函关尽，前旌阙塞通。行看洛阳陌，光景丽天中。'},
    {t:'奉和圣制途经华山',a:'张九龄〔唐代〕',c:'万乘华山下，千岩云汉中。灵居虽窅密，睿览忽玄同。\n日月临高掌，神仙仰大风。攒峰势岌岌，翊辇气雄雄。\n揆物知幽赞，铭勋表圣衷。会应陪玉检，来此告成功。'},
    {t:'奉和圣制温泉歌',a:'张九龄〔唐代〕',c:'有时神物待圣人，去后汤还冷，来时树亦春。\n今兹十月自东归，羽旆逶迤上翠微。温谷葱葱佳气色，\n离宫奕奕叶光辉。临渭川，近天邑，浴日温泉复在兹，\n群仙洞府那相及。吾君利物心，玄泽浸苍黔。\n渐渍神汤无疾苦，薰歌一曲感人深。'},
    {t:'奉和圣制喜雨',a:'张九龄〔唐代〕',c:'艰我稼穑，载育载亭。随物应之，曷圣与灵。谓我何凭，\n惟德之馨。谁云天远，以诚必至。太清无云，羲和顿辔。\n于斯烝人，瞻彼非觊。阴冥倏忽，沛泽咸洎。何以致之。\n我后之感。无皋无隰，黍稷黯黯。无卉无木，敷芬黮黤。\n黄龙勿来，鸣鸟不思。人和年丰，皇心则怡。岂与周宣，\n云汉徒诗。'},
    {t:'奉和圣制幸晋阳宫',a:'张九龄〔唐代〕',c:'隋季失天策，万方罹凶残。\n皇祖锡义旗，三灵皆获安。\n圣期将申锡，王业成艰难。\n盗移未改命，历郁终履端。\n彼汾惟帝乡，雄都信郁盘。\n一月朔巡狩，群后陪清銮。\n霸迹郁沛庭，旧仪睹汉官。\n唐风思何深，舜典敷更宽。\n户蒙枌榆复，邑争牛酒欢。\n缅惟翦商后，岂独微禹叹。\n三后既郁天，万年斯不刊。\n尊祖实我皇，天文皆仰观。'},
    {t:'奉和圣制谒玄元皇帝庙斋',a:'张九龄〔唐代〕',c:'兴运昔有感，建祠北山巅。云雷初缔构，日月今悠然。\n紫气尚蓊郁，玄元如在焉。迨兹事追远，轮奂复增鲜。\n洞府香林处，斋坛清汉边。吾君乃尊祖，夙驾此留连。\n乐动人神会，钟成律度圆。笙歌下鸾鹤，芝朮萃灵仙。\n曾是福黎庶，岂唯味虚玄。赓歌徒有作，微薄谢昭宣。'},
    {t:'奉和圣制早登太行山率尔言志',a:'张九龄〔唐代〕',c:'孟月摄提贞，乘时我后征。晨严九折度，暮戒六军行。\n日御驰中道，风师卷太清。戈鋋林表出，组练雪间明。\n动植希皇豫，高深奉睿情。陪游七圣列，望幸百神迎。\n气色烟犹喜，恩光草尚荣。之罘称万岁，今此复同声。'},
    {t:'奉和圣制早渡蒲津关',a:'张九龄〔唐代〕',c:'魏武中流处，轩皇问道回。长堤渡树发，高掌曙云开。\n龙负王舟渡，人占仙气来。河津会日月，天仗役风雷。\n东顾重关尽，西驰万国陪。还闻股肱郡，元首咏康哉。'},
    {t:'奉和圣制早发三乡山行',a:'张九龄〔唐代〕',c:'羽卫森森西向秦，山川历历在清晨。晴云稍卷寒岩树，\n宿雨能销御路尘。圣德由来合天道，灵符即此应时巡。\n遗贤一一皆羁致，犹欲高深访隐沦。'},
    {t:'奉和圣制烛龙斋祭',a:'张九龄〔唐代〕',c:'上帝临下，鉴亦有光。孰云阴骘，我圣克彰。六月徂暑，\n四郊愆阳。我后其勤，告于坛场。精意允溢，雨灵鼓舞。\n蔚兮朝云，沛然时雨。雨我原田，亦既有年。烛龙煌煌，\n明宗报祀。于以助之，天人帝子。闻诗有训，国风兹始。'},
    {t:'奉和圣製除夜',a:'晏殊〔宋代〕',c:'秘掖楯轩严万户，庆宵躔次会珑辰。\n丹闱肃穆犹凝夕，佳气葱珑渐报春。\n调历自将穹厚永，圣辞常与岁时新。\n送寒旁磔迎和令，率土群生仰昊旻。'},
    {t:'奉和圣製除夜',a:'晏殊〔宋代〕',c:'珠躔回碧落，绛燎烛青规。\n琐闼琼签度，层台玉漏移。\n纳新皇泽普，顺节圣情怡。\n万宇长安陌，乡傩集此时。'},
    {t:'奉和圣製冬至',a:'晏殊〔宋代〕',c:'吉序冠三正，民时顺盛成。\n岁穰律亩实，气爽六符平。\n肆乐遵年律，迎长蔼颂声。\n云浓燕雁度，雪霁楚兰荣。\n异域梯航集，诸侯篚贡盈。\n尧仁敷万有，同此一阳生。'},
    {t:'奉和圣製立春日',a:'晏殊〔宋代〕',c:'阴阳自协璇玑运，和煦潜随缇管升。\n十二紫关鱼籥启，九重晓阙绛烟凝。\n芳华稍变青门柳，寒冻微消北陆冰。\n宸藻下颁羲日丽，八弦民庶保年登。'},
    {t:'奉和圣製上巳日',a:'晏殊〔宋代〕',c:'青阳三巳日，佳气九城中。\n洛饮传周俗，溱诗载郑风。\n停轮浮桂醑，解袂泛兰丛。\n选胜开慈宴，多欢组绶同。'},
    {t:'奉和圣製上元',a:'晏殊〔宋代〕',c:'鹑火告中时，皇州盛若兹。\n九阳同化洽，万汇得春熙。\n楼月将收晚，歌云度欲迟。\n布和周海域，翾蠕遂收宜。'},
    {t:'奉和圣製上元',a:'晏殊〔宋代〕',c:'风掖千门迥，金缸四照然。\n市圜通夜阙，歌肆与云连。\n叠鼓迷清漏，游车际晓天。\n泛膏仍洁祀，蚕麦伫登年。'},
    {t:'奉和圣製上元',a:'晏殊〔宋代〕',c:'协风阳律应，满砌荚蓂新。\n绛阙罗千卫，华灯曜百轮。\n悠悠未央夜，粲粲彼都人。\n万宇今无外，登台共乐春。'},
    {t:'奉和圣製上元夜',a:'晏殊〔宋代〕',c:'兰灯照夕开南阙，星弁飞楼拱是辰。\n在镐正逢全盛日，祝尧皆是太平人。\n流风舞妙翻成字，积雪歌长迥绕尘。\n鸾鹊实函颁睿什，明良赓载想同伦。'},
    {t:'奉和圣製新春',a:'晏殊〔宋代〕',c:'斗柄东回六合春，尧天历象与时新。\n铜壶瑞气延疏漏，青辂祥风绕画轮。\n云里楼台高郁郁，雨中原隰碧鳞鳞。\n千枝彩萼梅英吐，百尺金丝柳带匀。\n秉籙调元功有序，在璿观妙政惟醇。\n仰瞻魏阙宣和会，共识皇恩子万民。'},
    {t:'奉和圣製元日',a:'晏殊〔宋代〕',c:'人正肇届时多祜，凤历惟新景寿阳。\n双阙布和云气郁，千门献寿玉声长。\n东风入律三边静，北斗回春万物芳。\n朝暇肃诚颁睿藻，缙绅交抃捧尧章。'},
    {t:'奉和杨驸马六郎秋夜即事',a:'王维〔唐代〕',c:'高楼月似霜，秋夜郁金堂。对坐弹卢女，同看舞凤凰。\n少儿多送酒，小玉更焚香。结束平阳骑，明朝入建章。'},
    {t:'奉和御製中和节',a:'晏殊〔宋代〕',c:'正元崇吉序，实历记良辰。\n营室彤曦转，勾芒令祀新。\n尧蓂方告朔，汉酎更宜春。\n菖叶农耕候，如膏洒泽频。'},
    {t:'奉和中书舍人贾至早朝大明宫',a:'岑参〔唐代〕',c:'鸡鸣紫陌曙光寒，莺啭皇州春色阑。\n金阙晓钟开万户，玉阶仙仗拥千官。\n花迎剑佩星初落，柳拂旌旗露未干。\n独有凤凰池上客，阳春一曲和皆难。'},
    {t:'奉济驿重送严公四韵',a:'杜甫〔唐代〕',c:'远送从此别，青山空复情。\n几时杯重把，昨夜月同行。\n列郡讴歌惜，三朝出入荣。\n江村独归处，寂寞养残生。'},
    {t:'奉寄韦太守陟',a:'王维〔唐代〕',c:'荒城自萧索，万里山河空。\n天高秋日迥，嘹唳闻归鸿。\n寒塘映衰草，高馆落疏桐。\n临此岁方晏，顾景咏悲翁。\n故人不可见，寂寞平陵东。'},
    {t:'奉陪封大夫九日登高',a:'岑参〔唐代〕',c:'九日黄花酒，登高会昔闻。\n霜威逐亚相，杀气傍中军。\n横笛惊征雁，娇歌落塞云。\n边头幸无事，醉舞荷吾君。'},
    {t:'奉陪杨使君顼送段校书赴南海幕',a:'皎然〔唐代〕',c:'硕贤静广州，信为天下贞。屈兹兴将佐，藉彼延阁英。\n声动柳吴兴，郊饯意不轻。吾知段夫子，高可关苍生。\n处以德为藩，出则道可行。遥知南楼会，新景当诗情。\n天高林瘴洗，秋远海色清。时泰罢飞檄，唯应颂公成。'},
    {t:'奉使自蓝田玉山南行',a:'张九龄〔唐代〕',c:'征骖入云壑，始忆步金门。通籍役躯幸，归途明主恩。\n匪唯徇行役，兼得慰晨昏。是节暑云炽，纷骏心所尊。\n海县且悠缅，山邮日骏奔。徒知恶嚣事，未暇息阴论。\n峣武经陈迹，衡湘指故园。水闻南涧险，烟望北林繁。\n远霭千岩合，幽声百籁喧。阴泉夏犹冻，阳景昼方暾。\n懿此高深极，徒令梦想存。盛明期有报，长往复奚言。'},
    {t:'奉送从兄宰晋陵',a:'韦应物〔唐代〕',c:'东郊暮草歇，千里夏云生。立马愁将夕，看山独送行。\n依微吴苑树，迢递晋陵城。慰此断行别，邑人多颂声。'},
    {t:'奉送贾侍御使江外',a:'岑参〔唐代〕',c:'新骑骢马复承恩，使出金陵过海门。\n荆南渭北难相见，莫惜衫襟著酒痕。'},
    {t:'奉送李中丞道昌入朝',a:'皎然〔唐代〕',c:'文宪中司盛，恩荣外镇崇。诸侯皆取则，八使独推功。\n诏喜新衔凤，车看旧饰熊。去思今武子，馀教昔文翁。\n清在如江水，仁留是国风。光征二千石，扫第望司空。'},
    {t:'奉送陆中丞长源诏征入朝',a:'皎然〔唐代〕',c:'诏下酂侯幕，征贤宠上勋。才当饯汉典，道可致尧君。\n藩牧今荣饯，诗流此盛文。水从吴渚别，树向楚门分。\n宿寺期嘉月，看山识故云。归心复何奈，怊怅在江濆。'},
    {t:'奉送严公入朝十韵',a:'杜甫〔唐代〕',c:'鼎湖瞻望远，象阙宪章新。\n四海犹多难，中原忆旧臣。\n与时安反侧，自昔有经纶。\n感激张天步，从容静塞尘。\n南图回羽翮，北极捧星辰。\n漏鼓还思昼，宫莺罢啭春。\n空留玉帐术，愁杀锦城人。\n阁道通丹地，江潭隐白蘋。\n此生那老蜀？不死会归秦！\n公若登台辅，临危莫爱身！'},
    {t:'奉天西佛寺',a:'温庭筠〔唐代〕',c:'忆昔狂童犯顺年，玉虬闲暇出观泉。宗臣欲舞千钧剑，\n追骑犹观七宝鞭。星背紫垣终扫地，日归黄道却当天。\n至今南顿诸耆旧，犹指榛芜作弄田。'},
    {t:'奉同卢使君幼平游精舍寺',a:'皎然〔唐代〕',c:'影刹西方在，虚空翠色分。人天霁后见，猿鸟定中闻。\n真界隐青壁，春山凌白云。今朝石门会，千古仰斯文。'},
    {t:'奉先张明府休沐还乡海亭宴集',a:'孟浩然〔唐代〕',c:'自君理畿甸，予亦经江淮。万里书信断，数年云雨乖。\n归来休浣日，始得赏心谐。朱绂恩虽重，沧州趣每怀。\n树低新舞阁，山对旧书斋。何以发秋兴，阴虫鸣夜阶。'},
    {t:'奉谢刘景文送团茶',a:'黄庭坚〔宋代〕',c:'刘侯惠我大玄璧，上有雌雄双杯迹。\n鹅溪水练落春雪，粟面一杯增目力。\n刘侯惠我小玄璧，自碾半璧煮琼爢。\n收藏残月惜未碾，直待阿衡来说诗。\n绛囊团团余几璧，因来送我公莫惜。\n个中渴羌饱汤饼，鸡苏胡麻煮同吃。'},
    {t:'奉赠贺郎诗一首',a:'高适〔唐代〕',c:'报贺郎，莫潜藏。障门终不免，何羊漫思量。清酒浓如鸡，臛㹠与白羊。\n不论空蒜酢，兼要好椒姜。姑娣能无语，多言有侍娘。\n不知何日办，急共妇平章。如其意不决，请问阿耶娘。'},
    {t:'奉赠张荆州',a:'王昌龄〔唐代〕',c:'祝融之峰紫云衔，翠如何其雪之岩。邑西有路缘石壁，\n我欲从之卧穹嵌。鱼有心兮脱网罟，江无人兮鸣枫杉。\n王君飞舄仍未去，苏耽宅中意遥缄。'},
    {t:'敷水歌，送窦渐入京',a:'岑参〔唐代〕',c:'罗敷昔时秦氏女，千载无人空处所。昔时流水至今流，\n万事皆逐东流去。此水东流无尽期，水声还似旧来时。\n岸花仍自羞红脸，堤柳犹能学翠眉。春去秋来不相待，\n水中月色长不改。罗敷养蚕空耳闻，使君五马今何在。\n九月霜天水正寒，故人西去度征鞍。水底鲤鱼幸无数，\n愿君别后垂尺素。'},
    {t:'伏日就汤评事衡湖上避暑',a:'皎然〔唐代〕',c:'大火方燥石，停云昼亦收。将从赏心侣，寸景难远游。\n拥几苦炎伏，出门望汀洲。回溪照轩宇，广陌临梧楸。\n释闷命雅瑟，放情思乱流。更持无生论，可以清烦忧。'},
    {t:'扶南曲歌词五首',a:'王维〔唐代〕',c:'翠羽流苏帐，春眠曙不开。羞从殿色起，娇逐语声来。\n早向昭阳殿，君王中使催。\n堂上青弦动，堂阳绮席陈。齐歌卢女曲，双舞洛阳人。\n倾国徒相看，宁知心所亲。\n香气传空满，妆华影箔通。歌闻天仗外，舞出御楼中。\n日暮归何处，花间长乐宫。\n宫女还金屋，将眠复畏明。入春轻衣好，半夜薄妆成。\n拂曙朝阳殿，玉墀多珮声。\n朝日照绮窗，佳人坐临镜。散黛恨犹轻，插钗嫌未正。\n同心勿遽游，幸待春妆竟。'},
    {t:'芙蓉',a:'温庭筠〔唐代〕',c:'剌茎澹荡碧，花片参差红。\n吴歌秋水冷，湘庙夜云空。\n浓艳香露里，美人青镜中。\n南楼未归客，一夕练塘东。'},
    {t:'芙蓉楼送辛渐二首',a:'王昌龄〔唐代〕',c:'寒雨连江夜入吴，平明送客楚山孤。\n洛阳亲友如相问，一片冰心在玉壶。\n丹阳城南秋海阴，丹阳城北楚云深。\n高楼送客不能醉，寂寂寒江明月心。'},
    {t:'芙蓉亭',a:'柳宗元〔唐代〕',c:'新亭俯朱槛，嘉木开芙蓉。\n清香世风远，溽彩寒露浓。\n潇洒出人世，低昂多异容。\n尝闻色空喻，造物谁为工？\n留连秋月晏，迢递来山钟。'},
    {t:'拂霓裳·乐秋天',a:'晏殊〔宋代〕',c:'乐秋天。晚荷花缀露珠圆。风日好，数行新雁贴寒烟。银簧调脆管，琼柱拨清弦。捧觥船。一声声、齐唱太平年。\n人生百岁，离别易，会逢难。无事日，剩呼宾友启芳筵。星霜催绿鬓，风露损朱颜。惜清欢。又何妨、沈醉玉尊前。'},
    {t:'拂霓裳·庆生辰',a:'晏殊〔宋代〕',c:'庆生辰。庆生辰是百千春。开雅国，画堂高会有诸亲。钿函封大国，玉色受丝纶，感皇恩。望九重、比上拜尧云。\n今朝祝寿，祝寿数，比松椿。斟美酒，至心如对月中人。一声檀板动，一炷蕙香焚。祷仙真。愿年年今日、喜长新。'},
    {t:'拂霓裳·喜秋成',a:'晏殊〔宋代〕',c:'喜秋成。见千门万户乐升平。金风细，玉池波浪縠文生。宿露沾罗幕，微凉入画屏。张绮宴，傍熏炉蕙炷、和新声。\n神仙雅会，会此日，象蓬瀛。管弦清，旋翻红袖学飞琼。光阴无暂住，欢醉有闲情。祝辰星。愿百千为寿、献瑶觥。'},
    {t:'拂舞词',a:'温庭筠〔唐代〕',c:'黄河怒浪连天来，大响谹谹如殷雷。\n龙伯驱风不敢上，百川喷雪高崔嵬。\n二十三弦何太哀，请公勿渡立徘徊。\n下有狂蛟锯为尾，裂帆截棹磨霜齿。\n神椎凿石塞神潭，白马骖驔赤尘起。\n公乎跃马扬玉鞭，灭没高蹄日千里。'},
    {t:'浮石亭',a:'孟郊〔唐代〕',c:'曾是风雨力，崔巍漂来时。落星夜皎洁，近榜朝逶迤。\n翠潋递明灭，清潈泻欹危。况逢蓬岛仙，会合良在兹。'},
    {t:'浮世',a:'陆游〔宋代〕',c:'浮世如流水，滔滔日夜东。\n百年均梦寐，万古一虚空。\n青鸟来云外，铜驼卧棘中。\n相逢惟痛饮，令我忆无功。'},
    {t:'浮云三章',a:'皎然〔唐代〕',c:'浮云浮云，集于扶桑。扶桑茫茫，日暮之光。\n匪日之暮，浮云之污。嗟我怀人，犹心如蠹。\n浮云浮云，集于咸池。咸池微微，日昃之时。\n匪日之昃，浮云之惑。嗟我怀人，忧心如织。\n浮云浮云，集于高舂。高舂濛濛，日夕之容。\n匪日之夕，浮云之积。嗟我怀人，忧心如惄。'},
    {t:'福先寺雪中酬别乐天',a:'刘禹锡〔唐代〕',c:'龙门宾客会龙宫，东去旌旗驻界东。\n二八笙歌云幕下，三千世界雪花中。\n离堂未暗排红烛，别曲含凄飏晚风。\n才子从今一分散，便将诗咏向吴侬。'},
    {t:'负冬日',a:'白居易〔唐代〕',c:'杲杲冬日出，照我屋南隅。\n负暄醪目坐，和气生肌肤。\n初似饮醇醪，又如蛰者苏。\n外融百骸畅，中适一念无。\n旷然忘所在，心与虚空俱。'},
    {t:'负薪行',a:'杜甫〔唐代〕',c:'夔州处女发半华，四十五十无夫家。\n更遭丧乱嫁不售，一生抱恨长咨嗟。\n土风坐男使女立，应当门户女出入。\n十犹八九负薪归，卖薪得钱应供给。\n至老双鬟只垂颈，野花山叶银钗并。\n筋力登危集市门，死生射利兼盐井。\n面妆首饰杂啼痕，地褊衣寒困石根。\n若道巫山女粗丑，何得此有昭君村？'},
    {t:'妇病行',a:'佚名〔两汉〕',c:'妇病连年累岁，传呼丈人前一何。\n当何未及得何，不知泪下一何翩翩。\n“属累君两三孤子，莫我折饥且寒，有过慎莫笪笞。\n行当折摇，思复念之！”\n乱曰：抱时无衣，襦复无里。\n闭门塞牖，舍孤折到市。\n道逢亲交，泣坐不能起。\n从乞求与孤折买饵，对交啼泣，泪不可止：“我欲不伤悲不能已。”\n探怀中钱持授交。\n入门见孤折，啼索其母抱。\n徘徊空舍中，“行复尔耳，弃置勿复道！”'},
    {t:'赴北庭度陇思家',a:'岑参〔唐代〕',c:'西向轮台万里馀，也知乡信日应疏。\n陇山鹦鹉能言语，为报家人数寄书。'},
    {t:'赴犍为经龙阁道',a:'岑参〔唐代〕',c:'侧径转青壁，危梁透沧波。\n汗流出鸟道，胆碎窥龙涡。\n骤雨暗谿口，归云网松萝。\n屡闻羌儿笛，厌听巴童歌。\n江路险复永，梦魂愁更多。\n圣朝幸典郡，不敢嫌岷峨。'},
    {t:'赴京途中遇雪',a:'孟浩然〔唐代〕',c:'迢递秦京道，苍茫岁暮天。\n穷阴连晦朔，积雪满山川。\n落雁迷沙渚，饥乌噪野田。\n客愁空伫立，不见有人烟。'},
    {t:'赴彭州山行之作',a:'高适〔唐代〕',c:'峭壁连崆峒，攒峰叠翠微。\n鸟声堪驻马，林色可忘机。\n怪石时侵径，轻萝乍拂衣。\n路长愁作客，年老更思归。\n且悦岩峦胜，宁嗟意绪违。\n山行应未尽，谁与玩芳菲？'},
    {t:'赴阙',a:'文天祥〔宋代〕',c:'楚月穿春袖，吴霜透晓鞯。\n壮心欲填海，苦胆为忧天。\n役役惭金注，悠悠欢瓦全。\n丈夫竟何事，一日定千年。'},
    {t:'赴桐庐郡淮上遇风三首',a:'范仲淹〔宋代〕',c:'妻子休相咎，劳生险自多。\n商人岂有罪，同我在风波。'},
    {t:'赋得春雪映早梅',a:'元稹〔唐代〕',c:'飞舞先春雪，因依上番梅。一枝方渐秀，六出已同开。\n积素光逾密，真花节暗催。抟风飘不散，见晛忽偏摧。\n郢曲琴空奏，羌音笛自哀。今朝两成咏，翻挟昔人才。'},
    {t:'赋得灯心送李侍御萼·光字',a:'皎然〔唐代〕',c:'灯心生众草，因有始知芳。彩妓窗偏丽，金桃动更香。\n花惊春未尽，焰喜夜初长。别后空离室，何人借末光。'},
    {t:'赋得古原草送别',a:'白居易〔唐代〕',c:'离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。\n远芳侵古道，晴翠接荒城。\n又送王孙去，萋萋满别情。'},
    {t:'赋得还山吟送沈四山人',a:'高适〔唐代〕',c:'还山吟，天高日暮寒山深，送君还山识君心。\n人生老大须恣意，看君解作一生事。\n山间偃仰无不至，石泉淙淙若风雨，桂花松子常满地。\n卖药囊中应有钱，还山服药又长年。\n白云劝尽杯中物，明月相随何处眠？\n眠时忆问醒时事，梦魂可以相周旋。'},
    {t:'赋得鸡',a:'李商隐〔唐代〕',c:'稻粱犹足活诸雏，妒敌专场好自娱。\n可要五更惊晓梦，不辞风雪为阳乌。'},
    {t:'赋得九月尽·秋字',a:'元稹〔唐代〕',c:'霜降三旬后，蓂馀一叶秋。玄阴迎落日，凉魄尽残钩。\n半夜灰移琯，明朝帝御裘。潘安过今夕，休咏赋中愁。'},
    {t:'赋得暮雨送李胄',a:'韦应物〔唐代〕',c:'楚江微雨里，建业暮钟时。\n漠漠帆来重，冥冥鸟去迟。\n海门深不见，浦树远含滋。\n相送情无限，沾襟比散丝。'},
    {t:'赋得清如玉壶冰',a:'王维〔唐代〕',c:'玉壶何用好，偏许素冰居。\n未共隐丹日，还同照绮疏。\n抱明中不隐，含净外疑虚。\n气似庭霜积，光言砌月馀。\n晓凌飞鹊镜，宵映聚萤书。\n若向夫君比，清心尚不如。'},
    {t:'赋得秋日悬清光',a:'王维〔唐代〕',c:'寥廓凉天静，晶明白日秋。\n圆光含万象，碎影入闲流。\n迥与青冥合，遥同江甸浮。\n昼阴殊众木，斜影下危楼。\n宋玉登高怨，张衡望远愁。\n馀辉如可托，云路岂悠悠。'},
    {t:'赋得秋雨',a:'晏殊〔宋代〕',c:'点滴行云覆苑墙，飘萧微影度回塘。\n秦声未觉朱弦润，楚梦先知韭叶凉。\n野水有波增澹碧，霜林无韵湿疏黄。\n萤稀燕寂高窗暮，正是西风玉漏长。'},
    {t:'赋得沙际路送从叔象',a:'韦应物〔唐代〕',c:'独树沙边人迹稀，欲行愁远暮钟时。\n野泉几处侵应尽，不遇山僧知问谁。'},
    {t:'赋得石梁泉送崔逵',a:'皎然〔唐代〕',c:'架石通霞壁，悬崖散碧沙。天晴虹影渡，风细练文斜。\n举陟幽期阻，沿洄客意赊。河梁非此路，别恨亦无涯。'},
    {t:'赋得桃李无言',a:'李商隐〔唐代〕',c:'夭桃花正发，秾李蕊方繁。\n应候非争艳，成蹊不在言。\n静中霞暗吐，香处雪潜翻。\n得意摇风态，含情泣露痕。\n芬芳光上苑，寂默委中园。\n赤白徒自许，幽芳谁与论。'},
    {t:'赋得啼猿送客',a:'皎然〔唐代〕',c:'万里巴江外，三声月峡深。何年有此路，几客共沾襟。\n断壁分垂影，流泉入苦吟。凄凉离别后，闻此更伤心。'},
    {t:'赋得盈盈楼上女',a:'孟浩然〔唐代〕',c:'夫婿久离别，青楼空望归。\n妆成卷帘坐，愁思懒缝衣。\n燕子家家入，杨花处处飞。\n空床难独守，谁为报金徽。'},
    {t:'赋得自君之出矣',a:'张九龄〔唐代〕',c:'自君之出矣，不复理残机。\n思君如满月，夜夜减清辉。'},
    {t:'赋花',a:'张籍〔唐代〕',c:'花，花。落早，开赊。对酒客，兴诗家。起回游骑，\n每驻行车。宛宛清风起，茸茸丽日斜。且愿相留欢洽，\n惟愁虚弃光华。明年攀折知不远，对此谁起更叹嗟。'},
    {t:'赋水仙花',a:'朱熹〔宋代〕',c:'隆冬凋百卉，江梅历孤芳。\n如何帔艾底，亦有春风香。\n纷敷翠羽帔，温艳白玉相。\n黄冠表独立，淡冰水仙装。\n弱植晚兰荪，高标摧冰霜。\n湘君谢遗褋，汉水羞捐珰。\n嗟彼世俗人，欲火焚衷肠。\n徒知慕佳冶，讵识怀贞刚？\n凄凉柏舟誓，恻怆终风章。\n卓哉有遗烈，千载不可忘。'},
    {t:'赋枣',a:'王安石〔宋代〕',c:'种桃昔所传，种枣予所欲。\n在实为美果，论材又良木。\n余甘入邻家，尚得馋妇逐。\n况余秋盘中，快噉取餍足。\n风包堕朱缯，日颗皱红玉。\n贽享古已然，豳诗自宜录。\n沔怀青齐间，万树荫平陆。\n谁云食之昏，匿知乃成俗。\n广庭觞圣寿，以此参肴蔌。\n愿比赤心投，皇明傥予烛。'},
    {t:'富平少侯',a:'李商隐〔唐代〕',c:'七国三边未到忧，十三身袭富床侯。\n不收金弹抛林外，却惜银床在井头。\n彩树转灯珠错落，绣檀回枕玉雕锼。\n当关不报侵晨客，新得佳人字莫愁。'},
    {t:'富人之子',a:'苏轼〔宋代〕',c:'齐有富人，家累千金。其二子甚愚，其父又不教之。\n一日，艾子谓其父曰：“君之子虽美，而不通世务，他日曷能克其家？”\n父怒曰：“吾之子敏而且恃多能，岂有不通世务者耶？”\n艾子曰：“不须试之他，但问君之子，所食者米，从何来？若知之，吾当妄言之罪。”\n父遂呼其子问之。其子嘻然笑曰：“吾岂不知此也？每以布囊取来。”\n其父愀然改容曰：“子之愚甚也！彼米不是田中来？”\n艾子曰：“非其父不生其子。”'},
    {t:'缚鸡行',a:'杜甫〔唐代〕',c:'小奴缚鸡向市卖，鸡被缚急相喧争。\n家中厌鸡食虫蚁，不知鸡卖还遭烹。\n虫鸡于人何厚薄，我斥奴人解其缚。\n鸡虫得失无了时，注目寒江倚山阁。'},
    {t:'覆巢行',a:'孟郊〔唐代〕',c:'荒城古木枝多枯，飞禽嗷嗷朝哺雏。枝倾巢覆雏坠地，\n乌鸢下啄更相呼。阳和发生均孕育，鸟兽有情知不足。\n枝危巢小风雨多，未容长成已先覆。灵枝珍木满上林，\n凤巢阿阁重且深。尔今所托非本地，乌鸢何得同尔心。'},
    {t:'甘草子·秋尽',a:'柳永〔宋代〕',c:'秋尽。叶翦红绡，砌菊遗金粉。雁华一行来，还有边庭信。\n飘散露华清风紧。动翠幕、晓寒犹嫩。中酒残妆慵整顿。聚两眉离恨。'},
    {t:'甘草子·秋暮',a:'柳永〔宋代〕',c:'秋暮。乱洒衰荷，颗颗真珠雨。雨阑月华生，冷彻鸳鸯浦。\n池上凭阑愁无侣。奈此个、单栖情绪。却傍金笼共鹦鹉。念粉郎言语。'},
    {t:'甘露歌',a:'王安石〔宋代〕',c:'折得一枝香在手，人间应未有。\n尽是经春雪未消，今日是何朝。\n尽日含毫难比兴，都无色可并。\n天里晴天何处来，真是屑琼瑰。\n天寒日暮山谷里，的砾愁成水。\n池上渐多枝上稀，唯有故人知。'},
    {t:'甘泉歌',a:'王昌龄〔唐代〕',c:'乘舆执玉已登坛，细草沾衣春殿寒。\n昨夜云生拜初月，万年甘露水晶盘。'},
    {t:'甘州',a:'张炎〔宋代〕',c:'澄江陆起潜皆山楼四景云林远市君山下枕江流，为群山冠冕。塔院居乎绝顶，旧有浮远堂，今废。\n俯长江、不占洞庭波，山拔地形高。对扶疏古木，浮图倒影，势压雄涛。门掩翠微僧院，应有月明敲。物换堂安在，断碣闲抛。\n不识庐山真面，是谁将此屋，突兀林坳。上层台回首，万境入诗豪。响天心、数声长啸，任清风、吹顶发萧骚。凭阑久，青琴何处，独立琼瑶。'},
    {t:'甘州·赋众芳所在',a:'张炎〔宋代〕',c:'看涓涓、两水自东西，中有百花庄。步交枝径里，帘分昼影，窗聚春香。依约谁教鹦鹉，列屋带垂杨。方喜闲居好，翻为诗忙。\n多少周情柳思，向一丘一壑，留恋年光。又何心逐鹿，蕉梦正钱塘。且休将扇尘轻障，万山深、不是旧河阳。无人识，牡丹开处，重见韩湘。'},
    {t:'甘州·寄李筠房',a:'张炎〔宋代〕',c:'望涓涓、一水隐芙蓉，几被暮云平。正凭高送目，西风断雁，残月平沙。未觉丹枫尽老，摇落已堪盟。无避秋声处，愁满天涯。\n一自盟鸥别后，甚酒瓢诗锦，轻误年华。料荷衣初暖，不忍负烟霞。记前度翦灯一笑，再相逢、知在那人家。空山远，白云休赠，只赠梅花。'},
    {t:'甘州·饯草窗归霅',a:'张炎〔宋代〕',c:'记天风、飞佩紫霞边，顾曲万花深。甚相如情倦，少陵愁老，还叹飘零。短梦恍然今昔，故国十年心。回首三三径，松竹成阴。\n不恨片篷南浦，恨翦灯听雨，谁伴孤吟。料瘦筇归后，闲锁北山云。是几番、柳边行色，是几番、同醉古园林。烟波远，笔床茶灶，何处逢君。'},
    {t:'甘州·题戚五云云山图',a:'张炎〔宋代〕',c:'过千岩万壑古蓬莱，招隐竟忘阑。想乾坤清气，霏霏冉冉，却在阑干。洞户来时不锁，归水映花如。只可自怡悦，持寄应难。\n狂客如今何处，甚酒船去后，烟水空寒。正黄尘没马，林下一身闲。几消凝、此图谁画，细看来、元不是终南，无心好、休教出岫，只在深山。'},
    {t:'甘州·听江湖夜雨十年灯',a:'张炎〔宋代〕',c:'听江湖夜雨十年灯，孤影尚中悠。对荒凉茂苑，吟情渺渺，心事悠悠。见说寒梅犹在，无处认西琴。招取琴边月，同载扁舟。\n明日琴书何处，正风前堕叶，草外闲鸥。甚消磨不尽，惟有古今愁。总休问、西湖南浦，渐春来、烟水入天流。清游好，醉招黄鹤，一啸清秋。'},
    {t:'甘州·赵文升索赋散乐妓桂卿',a:'张炎〔宋代〕',c:'隔花窥半面，带天香、吹动一天秋。叹行云流水，寒枝夜鹊，杨柳湾头。浪打石城风急，难系莫愁舟。未了笙歌梦，倚棹西州。\n重省寻春乐事，奈如今老去，鬓改花羞。指斜阳巷陌，都是旧曾游。凭寄与、采芳俦侣，且不须、容易说风流。争得似、桃根桃叶，明月妆楼。'},
    {t:'甘州令·冻云深',a:'柳永〔宋代〕',c:'冻云深，淑气浅，寒欺绿野。轻雪伴、早梅飘谢。艳阳天，正明媚，却成潇洒。玉人歌，画楼酒，对此景、骤增高价。\n卖花巷陌，放灯台榭。好时节、怎生轻舍。赖和风，荡霁霭，廓清良夜。玉尘铺，桂华满，素光里、更堪游冶。'},
    {t:'感别送从叔校书简再登科东归',a:'孟郊〔唐代〕',c:'长安车马道，高槐结浮阴。下有名利人，一人千万心。\n黄鹄多远势，沧溟无近浔。怡怡静退姿，泠泠思归吟。\n菱唱忽生听，芸书回望深。清风散言笑，馀花缀衣襟。\n独恨鱼鸟别，一飞将一沉。'},
    {t:'感春',a:'李贺〔唐代〕',c:'日暖自萧条，花悲北郭骚。\n榆穿莱子眼，柳断舞儿腰。\n上幕迎神燕，飞丝送百劳。\n胡琴今日恨，急语向檀槽。'},
    {t:'感春',a:'张籍〔唐代〕',c:'远客悠悠任病身，谢家池上又逢春。\n明年各自东西去，此地看花是别人。'},
    {t:'感讽五首·其二',a:'李贺〔唐代〕',c:'奇俊无少年，日车何躃躃。\n我待墓双绶，遗我星星发。\n都门贾生墓，青蝇久断绝。\n寒食摇扬天，愤景长肃杀。\n皇汉十二帝，唯帝称睿哲。\n一夕信竖儿，文明永沦歇。'},
    {t:'感讽五首·其三',a:'李贺〔唐代〕',c:'南山何其悲，鬼雨洒空草。\n长安径半秋，风前几人老。\n低迷黄昏径，袅袅青栎道。\n月午树无影，一山唯白晓。\n漆炬迎新人，幽圹萤扰扰。'},
    {t:'感讽五首·其四',a:'李贺〔唐代〕',c:'星尽四方高，万物知天曙。\n己生须己养，荷担出门去。\n君平久不返，康伯遁国路。\n晓思何譊譊，阛阓千人语。'},
    {t:'感讽五首·其五',a:'李贺〔唐代〕',c:'石根秋水明，石畔秋草瘦。\n侵衣野竹香，蛰蛰垂叶厚。\n岑中月归来，蟾光挂空秀。\n桂露对仙娥，星星下云逗。\n凄凉栀子落，山璺泣晴漏。\n下有张仲蔚，披书案将朽。'},
    {t:'感怀',a:'朱熹〔宋代〕',c:'经济夙所尚，隐沦非素期。几年霜露感，白发忽已垂。\n凿井北山阯，耕田南涧湄。乾坤极浩荡，岁晚将何之。'},
    {t:'感怀二首',a:'文天祥〔宋代〕',c:'伏龙欲夹太阳飞，独柱擎天力弗支。\n北海风沙漫汉节，浯溪烟雨暗唐碑。\n书空已恨天时去，惜往徒怀国士知。\n抱膝对人复何语，纷纷坐冢卧为尸。'},
    {t:'感怀其七',a:'孟郊〔唐代〕',c:'河梁莫相遇，草草不复言。汉家正离乱，王粲别荆蛮。\n野泽何萧条，悲风振空山。举头是星辰，念我何时还。\n亲爱久别散，形神各离迁。未为生死诀，长在心目间。'},
    {t:'感怀其四',a:'孟郊〔唐代〕',c:'徘徊不能寐，耿耿含酸辛。中夜登高楼，忆我旧星辰。\n四时互迁移，万物何时春。唯忆首阳路，永谢当时人。'},
    {t:'感皇恩·滁州为范倅寿',a:'辛弃疾〔宋代〕',c:'春事到清明，十分花柳。唤得笙歌劝君酒。酒如春好，春色年年依旧。青春元不老，君知否？\n席上看君，竹清松瘦。待与青春斗长久。三山归路，明日天香襟袖。更持金盏起，为君寿。'},
    {t:'感皇恩·大石标韵',a:'周邦彦〔宋代〕',c:'露柳好风标，娇莺能语。独占春光最多处。浅嚬轻笑，未肯等闲分付。为谁心子里，长长苦。\n洞房见说，云深无路。凭仗青鸾道情素。酒空歌断，又被涛江催去。怎奈向、言不尽，愁无数。'},
    {t:'感皇恩·读庄子闻朱晦庵即世',a:'辛弃疾〔宋代〕',c:'案上数编书，非庄即老。会说忘言始知道；万言千句，不自能忘堪笑。今朝梅雨霁，青天好。\n一壑一丘，轻衫短帽。白发多时故人少。子云何在，应有玄经遗草。江河流日夜，何时了。'},
    {t:'感皇恩·小阁倚秋空',a:'陆游〔宋代〕',c:'小阁倚秋空，下临江渚。漠漠孤云未成雨。数声新雁，回首杜陵何处。壮心空万里，人谁许！\n黄阁紫枢，筑坛开府。莫怕功名欠人做。如今熟计，只有故乡归路。石帆山脚下，菱三亩。'},
    {t:'感镜',a:'白居易〔唐代〕',c:'美人与我别，留镜在匣中。\n自从花颜去，秋水无芙蓉。\n经年不开匣，红埃覆青铜。\n今朝一拂拭，自照憔悴容。\n照罢重惆怅，背有双盘龙。'},
    {t:'感镜',a:'韦应物〔唐代〕',c:'铸镜广陵市，菱花匣中发。夙昔尝许人，镜成人已没。\n如冰结圆器，类璧无丝发。形影终不临，清光殊不歇。\n一感平生言，松枝树秋月。'},
    {t:'感旧',a:'陆游〔宋代〕',c:'当年书剑揖三公，谈舌如云气吐虹。\n十丈战尘孤壮志，一簪华发醉秋风。\n梦回松漠榆关外，身老桑村麦野中。\n奇士久埋巴硖骨，灯前慷慨与谁同？'},
    {t:'感梦',a:'元稹〔唐代〕',c:'行吟坐叹知何极，影绝魂销动隔年。\n今夜商山馆中梦，分明同在后堂前。'},
    {t:'感情',a:'白居易〔唐代〕',c:'中庭晒服玩，忽见故乡履。\n昔赠我者谁，东邻婵娟子。\n因思赠时语，特用结终始。\n永愿如履綦，双行复双止。\n自吾谪江郡，漂荡三千里。\n为感长情人，提携同到此。\n今朝一惆怅，反覆看未已。\n人只履犹双，何曾得相似。\n可嗟复可惜，锦表绣为里。\n况经梅雨来，色黯花草死。'},
    {t:'感芍药花寄正一上人',a:'白居易〔唐代〕',c:'今日阶前红芍药，几知欲老几知新。\n开时不解比色相，落后始知如幻身。\n空门此去几多地，欲把残知问上人。'},
    {t:'感事',a:'朱熹〔宋代〕',c:'闻说淮南路，胡尘满眼黄。弃躯惭国士，尝胆念君王。\n却敌非干橹，信威藉纪纲。丹心危欲折，伫立但彷徨。'},
    {t:'感事六言',a:'陆游〔宋代〕',c:'老去转无饱计，醉来暂豁忧端。\n双鬓多年作雪，寸心至死如丹。'},
    {t:'感事三首·此后并是学士时作',a:'元稹〔唐代〕',c:'为国谋羊舌，从来不为身。此心长自保，终不学张陈。\n自笑心何劣，区区辨所冤。伯仁虽到死，终不向人言。\n富贵年皆长，风尘旧转稀。白头方见绝，遥为一沾衣。'},
    {t:'感兴',a:'孟郊〔唐代〕',c:'拔心草不死，去根柳亦荣。独有失意人，恍然无力行。\n昔为连理枝，今为断弦声。连理时所重，断弦今所轻。\n吾欲进孤舟，三峡水不平。吾欲载车马，太行路峥嵘。\n万物根一气，如何互相倾。'},
    {t:'感兴',a:'杨万里〔宋代〕',c:'去国还家一岁阴，凤山锦水更登临。\n别来蛮触几百战，险尽山川多少心。\n何似闲人无藉在，不妨冷眼看升沉。\n荷花正闹莲蓬嫩，月下松醪且满斟。'},
    {t:'感兴',a:'文天祥〔宋代〕',c:'万里云山断客魂，浮云心事向谁言。\n月侵乡梦夜推枕，风送牢愁昼掩门。\n苏子窖中闲日月，石郎家里旧乾坤。\n朝闻夕死吾何恨，坐把春秋子细论。'},
    {t:'感兴二首',a:'白居易〔唐代〕',c:'吉凶祸福有来由，但要深知不要忧。\n只见火光烧润屋，不闻风浪覆虚舟。\n名为公器无多取，利是身灾合少求。\n虽异匏瓜难不食，大都食足早宜休。\n鱼能深入宁忧钓，鸟解高飞岂触罗。\n热处先争炙手去，悔时其奈噬脐何。\n尊前诱得猩猩血，幕上偷安燕燕窠。\n我有一言君记取，世间自取苦人多。'},
    {t:'感遇',a:'岑参〔唐代〕',c:'五花骢马七香车，云是平阳帝子家。凤凰城头日欲斜，\n门前高树鸣春鸦。汉家鲁元君不闻，今作城西一古坟。\n昔来唯有秦王女，独自吹箫乘白云。'},
    {t:'感遇二首',a:'柳宗元〔唐代〕',c:'西陆动凉气，惊乌号北林。\n栖息岂殊性，集枯安可任。\n鸿鹄去不返，勾吴阻且深。\n徒嗟日沈湎，丸鼓骛奇音。\n东海久摇荡，南风已骎骎。\n坐使青天暮，小星愁太阴。\n众情嗜奸利，居货捐千金。\n危根一以振，齐斧来相寻。\n揽衣中夜起，感物涕盈襟。\n微霜众所践，谁念岁寒心。\n旭日照寒野，鸒斯起蒿莱。\n啁啾有馀乐，飞舞西陵隈。\n回风旦夕至，零叶委陈荄。\n所栖不足恃，鹰隼纵横来。'},
    {t:'感遇三十八首·其二十一',a:'陈子昂〔唐代〕',c:'蜻蛉游天地，与世本无患。\n飞飞未能止，黄雀来相干。\n穰侯富秦宠，金石比交欢。\n出入咸阳里，诸侯莫敢言。\n宁知山东客，激怒秦王肝。\n布衣取丞相，千载为辛酸。'},
    {t:'感遇三十八首·其三十一',a:'陈子昂〔唐代〕',c:'朅来豪游子，势利祸之门。\n如何兰膏叹，感激自生冤。\n众趋明所避，时弃道犹存。\n云渊既已失，罗网与谁论。\n箕山有高节，湘水有清源。\n唯应白鸥鸟，可为洗心言。'},
    {t:'感遇三十八首·其十八',a:'陈子昂〔唐代〕',c:'逶迤势已久，骨鲠道斯穷。\n岂无感激者，时俗颓此风。\n灌园何其鄙，皎皎於陵中。\n世道不相容，喈喈张长公。'},
    {t:'感遇三十八首·其十六',a:'陈子昂〔唐代〕',c:'圣人去已久，公道缅良难。\n蚩蚩巧毗子，尧禹以为谩。\n骄荣贵工巧，势利迭相干。\n燕王尊乐毅，分国愿同欢。\n鲁连让齐爵，遗组去邯郸。\n伊人信往矣，感激为谁叹。'},
    {t:'感遇三十八首·其十七',a:'陈子昂〔唐代〕',c:'幽居观天运，悠悠念群生。\n终古代兴没，豪圣莫能争。\n三季沦周赧，七雄灭秦嬴。\n复闻赤精子，提剑入咸京。\n炎光既无象，晋虏复纵横。\n尧禹道已昧，昏虐势方行。\n岂无当世雄，天道与胡兵。\n咄咄安可言，时醉而未醒。\n仲尼溺东鲁，伯阳遁西溟。\n大运自古来，旅人胡叹哉。'},
    {t:'感遇诗三十八首·其八',a:'陈子昂〔唐代〕',c:'吾观昆仑化，日月沦洞冥。\n精魄极交会，天壤以罗生。\n仲尼推太极，老聃贵窈冥。\n西方金仙子，崇义乃无明。\n空色皆寂灭，缘业定何成。\n名教信纷藉，死生俱未停。'},
    {t:'感遇诗三十八首·其二',a:'陈子昂〔唐代〕',c:'兰若生春夏，芊蔚何青青。\n幽独空林色，朱蕤冒紫茎。\n迟迟白日晚，袅袅秋风生。\n岁华尽摇落，芳意竟何成。'},
    {t:'感遇诗三十八首·其二十',a:'陈子昂〔唐代〕',c:'玄天幽且默，群议曷嗤嗤。\n圣人教犹在，世运久陵夷。\n一绳将何系，忧醉不能持。\n去去行采芝，勿为尘所欺。'},
    {t:'感遇诗三十八首·其二十八',a:'陈子昂〔唐代〕',c:'昔日章华宴，荆王乐荒淫。\n霓旌翠羽盖，射兕云梦林。\n朅来高唐观，怅望云阳岑。\n雄图今何在，黄雀空哀吟。'},
    {t:'感遇诗三十八首·其二十二',a:'陈子昂〔唐代〕',c:'微霜知岁晏，斧柯始青青。\n况乃金天夕，浩露沾群英。\n登山望宇宙，白日已西暝。\n云海方荡潏，孤鳞安得宁。'},
    {t:'感遇诗三十八首·其二十九',a:'陈子昂〔唐代〕',c:'丁亥岁云暮，西山事甲兵。\n赢粮匝邛道，荷戟争羌城。\n严冬阴风劲，穷岫泄云生。\n昏曀无昼夜，羽檄复相惊。\n拳跼兢万仞，崩危走九冥。\n籍籍峰壑里，哀哀冰雪行。\n圣人御宇宙，闻道泰阶平。\n肉食谋何失，藜藿缅纵横。'},
    {t:'感遇诗三十八首·其二十六',a:'陈子昂〔唐代〕',c:'荒哉穆天子，好与白云期。\n宫女多怨旷，层城闭蛾眉。\n日耽瑶池乐，岂伤桃李时。\n青苔空萎绝，白发生罗帷。'},
    {t:'感遇诗三十八首·其二十七',a:'陈子昂〔唐代〕',c:'朝发宜都渚，浩然思故乡。\n故乡没可见，路隔巫山阳。\n巫山彩云没，高丘正微茫。\n伫立望已久，涕落沾衣裳。\n岂兹越乡感，忆昔楚襄王。\n朝云无处所，荆国亦沦亡。'},
    {t:'感遇诗三十八首·其二十三',a:'陈子昂〔唐代〕',c:'翡翠巢南海，雄雌珠树林。\n何知美人意，骄爱比黄金。\n杀身炎州里，委羽玉堂阴。\n旖旎光首饰，葳蕤烂锦衾。\n岂不在遐远，虞罗忽见寻。\n多材信为累，叹息此珍禽。'},
    {t:'感遇诗三十八首·其二十四',a:'陈子昂〔唐代〕',c:'挈瓶者谁子，姣服当青春。\n三五明月满，盈盈不自珍。\n高堂委金玉，微缕悬千钧。\n如何负公鼎，被夺笑时人。'},
    {t:'感遇诗三十八首·其二十五首',a:'陈子昂〔唐代〕',c:'玄蝉号白露，兹岁已蹉跎。\n群物从大化，孤英将奈何。\n瑶台有青鸟，远食玉山禾。\n昆仑见玄凤，岂复虞云罗。'},
    {t:'感遇诗三十八首·其九',a:'陈子昂〔唐代〕',c:'圣人秘元命，惧世乱其真。\n如何嵩公辈，诙谲误时人。\n先天诚为美，阶乱祸谁因。\n长城备胡寇，嬴祸发其亲。\n赤精既迷汉，子年何救秦。\n去去桃李花，多言死如麻。'},
    {t:'感遇诗三十八首·其六',a:'陈子昂〔唐代〕',c:'吾观龙变化，乃知至阳精。\n石林道冥密，幽洞无留行。\n古之得仙道，信与元化并。\n玄感非象识，谁能测沈冥。\n世人拘目见，酣酒笑丹经。\n昆仑有瑶树，安得采其英。'},
    {t:'感遇诗三十八首·其七',a:'陈子昂〔唐代〕',c:'白日每不归，青阳时暮矣。\n茫茫吾何思，林卧观无始。\n众芳委时晦，鶗鴂鸣悲耳。\n鸿荒古已颓，谁识巢居子。'},
    {t:'感遇诗三十八首·其三',a:'陈子昂〔唐代〕',c:'苍苍丁零塞，今古缅荒途。\n亭堠何摧兀，暴骨无全躯。\n黄沙幕南起，白日隐西隅。\n汉甲三十万，曾以事匈奴。\n但见沙场死，谁怜塞上孤。'},
    {t:'感遇诗三十八首·其三十',a:'陈子昂〔唐代〕',c:'可怜瑶台树，灼灼佳人姿。\n碧华映朱实，攀折青春时。\n岂不盛光宠，荣君白玉墀。\n但恨红芳歇，凋伤感所思。'},
    {t:'感遇诗三十八首·其三十八',a:'陈子昂〔唐代〕',c:'仲尼探元化，幽鸿顺阳和。\n大运自盈缩，春秋递来过。\n盲飙忽号怒，万物相纷劘。\n溟海皆震荡，孤凤其如何。'},
    {t:'感遇诗三十八首·其三十二',a:'陈子昂〔唐代〕',c:'索居犹几日，炎夏忽然衰。\n阳彩见阴翳，亲友尽睽违。\n登山望不见，涕泣久涟洏。\n宿梦感颜色，若与白云期。\n马上骄豪子，驱逐正蚩蚩。\n蜀山与楚水，携手在何时。'},
    {t:'感遇诗三十八首·其三十六',a:'陈子昂〔唐代〕',c:'浩然坐何慕，吾蜀有峨眉。\n念与楚狂子，悠悠白云期。\n时哉悲不会，涕泣久涟洏。\n梦登绥山穴，南采巫山芝。\n探元观群化，遗世从云螭。\n婉娈时永矣，感悟不见之。'},
    {t:'感遇诗三十八首·其三十七',a:'陈子昂〔唐代〕',c:'朝入云中郡，北望单于台。\n胡秦何密迩，沙朔气雄哉。\n藉藉天骄子，猖狂已复来。\n塞垣无名将，亭堠空崔嵬。\n咄嗟吾何叹，边人涂草莱。'},
    {t:'感遇诗三十八首·其三十三',a:'陈子昂〔唐代〕',c:'金鼎合神丹，世人将见欺。\n飞飞骑羊子，胡乃在峨眉。\n变化固幽类，芳菲能几时。\n疲疴苦沦世，忧痗日侵淄。\n眷然顾幽褐，白云空涕洟。'},
    {t:'感遇诗三十八首·其三十四',a:'陈子昂〔唐代〕',c:'朔风吹海树，萧条边已秋。\n亭上谁家子，哀哀明月楼。\n自言幽燕客，结发事远游。\n赤丸杀公吏，白刃报私仇。\n避仇至海上，被役此边州。\n故乡三千里，辽水复悠悠。\n每愤胡兵入，常为汉国羞。\n何知七十战，白首未封侯。'},
    {t:'感遇诗三十八首·其三十五',a:'陈子昂〔唐代〕',c:'本为贵公子，平生实爱才。\n感时思报国，拔剑起蒿莱。\n西驰丁零塞，北上单于台。\n登山见千里，怀古心悠哉。\n谁言未亡祸，磨灭成尘埃。'},
    {t:'感遇诗三十八首·其十',a:'陈子昂〔唐代〕',c:'深居观元化，悱然争朵颐。\n谗说耀啖食，利害纷㘈㘈。\n便便夸毗子，荣耀更耀持。\n务光让天下，商贾竞刀锥。\n已矣行采芝，万世同一时。'},
    {t:'感遇诗三十八首·其十二',a:'陈子昂〔唐代〕',c:'呦呦南山鹿，罹罟以媒和。\n招摇青桂树，幽蠹亦成科。\n世情甘近习，荣耀纷如何。\n怨憎未相复，亲爱生祸罗。\n瑶台倾巧笑，玉杯殒双蛾。\n谁见枯城蘖，青青成斧柯。'},
    {t:'感遇诗三十八首·其十九',a:'陈子昂〔唐代〕',c:'圣人不利己，忧济在元元。\n黄屋非尧意，瑶台安可论？\n吾闻西方化，清净道弥敦。\n奈何穷金玉，雕刻以为尊？\n云构山林尽，瑶图珠翠烦。\n鬼工尚未可，人力安能存？\n夸愚适增累，矜智道逾昏。'},
    {t:'感遇诗三十八首·其十三',a:'陈子昂〔唐代〕',c:'林居病时久，水木澹孤清。\n闲卧观物化，悠悠念无生。\n青春始萌达，朱火已满盈。\n徂落方自此，感叹何时平。'},
    {t:'感遇诗三十八首·其十四',a:'陈子昂〔唐代〕',c:'临歧泣世道，天命良悠悠。\n昔日殷王子，玉马遂朝周。\n宝鼎沦伊谷，瑶台成古丘。\n西山伤遗老，东陵有故侯。'},
    {t:'感遇诗三十八首·其十五',a:'陈子昂〔唐代〕',c:'贵人难得意，赏爱在须臾。\n莫以心如玉，探他明月珠。\n昔称夭桃子，今为舂市徒。\n鸱鸮悲东国，麋鹿泣姑苏。\n谁见鸱夷子，扁舟去五湖。'},
    {t:'感遇诗三十八首·其十一',a:'陈子昂〔唐代〕',c:'吾爱鬼谷子，青溪无垢氛。\n囊括斗世道，遗身在白云。\n七雄方龙斗，天下久无君。\n浮荣不足贵，遵养晦时文。\n舒可弥宇宙，卷之不盈分。\n岂徒山木寿，空与麋鹿群。'},
    {t:'感遇诗三十八首·其四',a:'陈子昂〔唐代〕',c:'乐羊为魏将，食子殉军功。\n骨肉且相薄，他人安得忠。\n吾闻中山相，乃属放麑翁。\n孤兽犹不忍，况以奉君终。'},
    {t:'感遇诗三十八首·其五',a:'陈子昂〔唐代〕',c:'市人矜巧智，于道若童蒙。\n倾夺相夸侈，不知身所终。\n曷见玄真子，观世玉壶中。\n窅然遗天地，乘化入无穷。'},
    {t:'感遇诗三十八首其八',a:'陈子昂〔唐代〕',c:'吾观昆崙化，日月沦洞冥。精魄极交会，天壤以罗生。\n仲尼推太极，老聃贵窈冥。西方金仙子，崇义乃无明。\n空色皆寂灭，缘业定何成。名教信纷藉，死生俱未停。'},
    {t:'感遇诗三十八首其十四',a:'陈子昂〔唐代〕',c:'临岐泣世道，天命良悠悠。昔日殷王子，玉马遂朝周。\n宝鼎沦伊谷，瑶台成古丘。西山伤遗老，东陵有故侯。'},
    {t:'感遇十二首·其二',a:'张九龄〔唐代〕',c:'幽人归独卧，滞虑洗孤清。\n持此谢高鸟，因之传远情。\n日夕怀空意，人谁感至精？\n飞沉理自隔，何所慰吾诚？'},
    {t:'感遇十二首·其七',a:'张九龄〔唐代〕',c:'江南有丹橘，经冬犹绿林。\n岂伊地气暖？自有岁寒心。\n可以荐嘉客，奈何阻重深。\n运命惟所遇，循环不可寻。\n徒言树桃李，此木岂无阴？'},
    {t:'感遇十二首·其四',a:'张九龄〔唐代〕',c:'孤鸿海上来，池潢不敢顾。\n侧见巅翠鸟，巢在三珠树。\n矫矫珍木巅，得无金丸惧？\n美服患人指，高明逼神恶。\n今我游冥冥，弋者何所慕！'},
    {t:'感遇十二首其九',a:'张九龄〔唐代〕',c:'抱影吟中夜，谁闻此叹息。美人适异方，庭树含幽色。\n白云愁不见，沧海飞无翼。凤皇一朝来，竹花斯可食。'},
    {t:'感遇十二首其十一',a:'张九龄〔唐代〕',c:'我有异乡忆，宛在云溶溶。凭此鸟不觏，要之心所钟。\n但欲附高鸟，安敢攀飞龙。至精无感遇，悲惋填心胸。\n归来扣寂寞，人愿天岂从。'},
    {t:'感遇十二首其五',a:'张九龄〔唐代〕',c:'鱼游乐深池，鸟栖欲高枝。\n嗟尔蜉蝣羽，薨薨亦何为。\n有生岂不化，所感奚若斯。\n神理日微灭，吾心安得知。\n浩叹杨朱子，徒然泣路岐。'},
    {t:'赣上食莲有感',a:'黄庭坚〔宋代〕',c:'莲实大如指，分甘念母慈。\n共房头𧤏𧤏，更深兄弟思。\n实中有幺荷，拳如小儿手。\n令我忆众雏，迎门索梨枣。\n莲心正自苦，食苦何能甘。\n甘餐恐腊毒，素食则怀惭。\n莲生淤泥中，不与泥同调。\n食莲谁不甘，知味良独少。\n吾家双井塘，十里秋风香。\n安得同袍子，归制芙蓉裳。'},
    {t:'高都护骢马行',a:'杜甫〔唐代〕',c:'安西都护胡青骢，声价欻然来向东。\n此马临阵久无敌，与人一心成大功。\n功成惠养随所致，飘飘远自流沙至。\n雄姿未受伏枥恩，猛气犹思战场利。\n腕促蹄高如踣铁，交河几蹴曾冰裂。\n五花散作云满身，万里方看汗流血。\n长安壮儿不敢骑，走过掣电倾城知。\n青丝络头为君老，何由却出横门道？'},
    {t:'高冠谷口招郑鄠',a:'岑参〔唐代〕',c:'谷口来相访，空斋不见君。\n涧花然暮雨，潭树暖春云。\n门径稀人迹，檐峰下鹿群。\n衣裳与枕席，山霭碧氛氲。'},
    {t:'高陵书情，寄三原卢少府',a:'韦应物〔唐代〕',c:'直方难为进，守此微贱班。开卷不及顾，沉埋案牍间。\n兵凶久相践，徭赋岂得闲。促戚下可哀，宽政身致患。\n日夕思自退，出门望故山。君心倘如此，携手相与还。'},
    {t:'高楼望月',a:'纳兰性德〔清代〕',c:'戚戚复戚戚，高楼月如雪。\n二八锦婵娟，月明翡翠钿。\n由来工织锦，生小倚朱弦。\n朱弦岂解愁，素泪似云浮。\n一声落天上，闻者皆泪流。\n别郎已经年，望郎出楼前。\n青天如海水，碧月如珠圆。\n月圆以复缺，不见长安客。\n古道白于霜，沙灭行人迹。\n月出光在天，月高光在地。\n何当同心人，两两不相弃。'},
    {t:'高平县东私路',a:'李贺〔唐代〕',c:'侵侵槲叶香，木花滞寒雨。\n今夕山上秋，永谢无人处。\n石溪远荒涩，棠实悬辛苦。\n古者定幽寻，呼君作私路。'},
    {t:'高松',a:'李商隐〔唐代〕',c:'高松出众木，伴我向天涯。\n客散初晴后，僧来不语时。\n有风传雅韵，无雪试幽姿。\n上药终相待，他年访伏龟。'},
    {t:'高轩过',a:'李贺〔唐代〕',c:'韩员外愈皇甫侍御湜见过因而命作\n华裾织翠青如葱，金环压辔摇玲珑。\n马蹄隐耳声隆隆，入门下马气如虹。\n云是东京才子，文章巨公。\n二十八宿罗心胸，九精照耀贯当中。\n殿前作赋声摩空，笔补造化天无功。\n庞眉书客感秋蓬，谁知死草生华风。\n我今垂翅附冥鸿，他日不羞蛇作龙。'},
    {t:'高阳池送朱二',a:'孟浩然〔唐代〕',c:'当昔襄阳雄盛时，山公常醉习家池。\n池边钓女日相随，妆成照影竟来窥。\n澄波澹澹芙蓉发，绿岸参参杨柳垂。\n一朝物变人亦非，四面荒凉人住稀。\n意气豪华何处在，空余草露湿罗衣。\n此地朝来饯行者，翻向此中牧征马。\n征马分飞日渐斜，见此空为人所嗟。\n殷勤为访桃源路，予亦归来松子家。'},
    {t:'高阳台·古木迷鸦',a:'张炎〔宋代〕',c:'庆乐园即韩平原南园。戊寅岁过之，仅存丹桂百余株，有碑记在荆榛中，故未有亦犹今之视昔之感，复叹葛岭贾相之故庐也。\n古木迷鸦，虚堂起燕，欢游转眼惊心。南圃东窗，酸风扫尽芳尘。鬓貂飞入平原草，最可怜、浑是秋阴。夜沈沈。不信归魂，不到花深。\n吹箫踏叶幽寻去，任船依断石，袖里寒云。老桂悬香，珊瑚碎击无声。故园已是愁如许，抚残碑、却又伤今。更关情。秋水人家，斜照西泠。'},
    {t:'高阳台·西湖春感',a:'张炎〔宋代〕',c:'接叶巢莺，平波卷絮，断桥斜日归船。能几番游，看花又是明年。东风且伴蔷薇住，到蔷薇、春已堪怜。更凄然。万绿西泠，一抹荒烟。\n当年燕子知何处，但苔深韦曲，草暗斜川。见说新愁，如今也到鸥边。无心再续笙歌梦，掩重门、浅醉闲眠。莫开帘，怕见飞花，怕听啼鹃。'},
    {t:'高斋闲望言怀',a:'张九龄〔唐代〕',c:'高斋复晴景，延眺属清秋。\n风物动归思，烟林生远愁。\n纷吾自穷海，薄宦此中州。\n取路无高足，随波适下流。\n岁华空冉冉，心曲且悠悠。\n坐惜芳时歇，胡然久滞留。'},
    {t:'歌舞',a:'李商隐〔唐代〕',c:'遏云歌响清，回雪舞腰轻。\n只要君流眄，君倾国自倾。'},
    {t:'歌元丰五首·其五',a:'王安石〔宋代〕',c:'豚栅鸡埘晻霭间，暮林摇落献南山。\n丰年处处人家好，随意飘然得往还。'},
    {t:'阁夜',a:'杜甫〔唐代〕',c:'岁暮阴阳催短景，天涯霜雪霁寒宵。\n五更鼓角声悲壮，三峡星河影动摇。\n野哭千家闻战伐，夷歌数处起渔樵。\n卧龙跃马终黄土，人事音书漫寂寥。'},
    {t:'葛溪驿',a:'王安石〔宋代〕',c:'缺月昏昏漏未央，一灯明灭照秋床。\n病身最觉风露早，归梦不知山水长。\n坐感岁时歌慷慨，起看天地色凄凉。\n鸣蝉更乱行人耳，正抱疏桐叶半黄。'},
    {t:'各东西',a:'张籍〔唐代〕',c:'游人别，一东复一西。出门相背悠不返，惟信车轮与马蹄。\n道路悠悠不知处，山高海阔谁辛苦。时游不定难寄书，\n日日空寻别时语。浮云上天雨堕地，暂时会合终离异。\n我今与子非一身，安得死生不相弃。'},
    {t:'庚辰四十五岁',a:'文天祥〔宋代〕',c:'东风昨夜忽相过，天地无情柰半何。\n千载方来那有尽，百年未半已为多。\n君传南海长生药，我爱西山饿死歌。\n泡影生来随自在，悠悠不管世间魔。'},
    {t:'庚申立春前一日',a:'朱熹〔宋代〕',c:'雪花寒送蜡，梅萼暖生春。岁晚江村路，云迷景更新。'},
    {t:'庚申正月游齐安',a:'王安石〔宋代〕',c:'水南水北重重柳，山后山前处处梅。\n未即此身随物化，年年长趁此时来。'},
    {t:'庚戌岁九月中于西田获早稻',a:'陶渊明〔魏晋〕',c:'人生归有道，衣食固其端。\n孰是都不营，而以求自安？\n开春理常业，岁功聊可观。\n晨出肆微勤，日入负禾还。\n山中饶霜露，风气亦先寒。\n田家岂不苦？弗获辞此难。\n四体诚乃疲，庶无异患干。\n盥濯息檐下，斗酒散襟颜。\n遥遥沮溺心，千载乃相关。\n但愿长如此，躬耕非所叹。'},
    {t:'庚子正月五日晓过大皋渡二首',a:'杨万里〔宋代〕',c:'雾外江山看不真，只凭鸡犬认前村。\n渡船满板霜如雪，印我青鞋第一痕。'},
    {t:'更漏子',a:'晏几道〔宋代〕',c:'露华高，凤信远。宿醉画帘低卷。梳洗倦，冶游慵。绿窗春睡浓。\n彩条轻，金缕重，昨日小桥相送。芳草恨，落花愁。去年同倚楼。'},
    {t:'更漏子·背江楼',a:'温庭筠〔唐代〕',c:'背江楼，临海月，城上角声呜咽。堤柳动，岛烟昏，两行征雁分。\n京口路，归帆渡，正是芳菲欲度。银烛尽，玉绳低，一声村落鸡。'},
    {t:'更漏子·出墙花',a:'晏几道〔宋代〕',c:'出墙花，当路柳。借问芳心谁有。来解笑，绿能颦。千般恼乱春。\n北来人，南去客。朝暮等闲攀折。怜晚芳，惜残阳。情知枉断肠。'},
    {t:'更漏子·寒鸿高',a:'晏殊〔宋代〕',c:'寒鸿高，仙露满。秋入银河清浅。逢好客，且开眉。盛年能几时。\n宝筝调，罗袖软。拍碎画堂檀板。须尽醉，莫推辞。人生多别离。'},
    {t:'更漏子·菊花残',a:'晏殊〔宋代〕',c:'菊花残，梨叶堕。可惜良辰虚过。弦酒熟，绮筵开。不辞红玉杯。\n蜀弦高，羌管脆。慢飐舞娥香袂。君莫笑，醉乡人。熙熙长似春。'},
    {t:'更漏子·槛花稀',a:'晏几道〔宋代〕',c:'槛花稀，池草遍，\n冷落吹笙庭院。\n人去日，燕西飞，\n燕归人未归。\n数书期，寻梦意，\n弹指一年春事。\n新怅望，旧悲凉，\n不堪红日长。'},
    {t:'更漏子·柳间眠',a:'晏几道〔宋代〕',c:'柳间眠，花里醉，\n不惜绣裙铺地。\n笺燕重，鬓蝉轻，\n一双梅子青。\n粉笺书，罗袖泪，\n还有可怜新意。\n遮闷绿，掩羞红，\n晚来团扇风。'},
    {t:'更漏子·柳丝长',a:'温庭筠〔唐代〕',c:'柳丝长，春雨细，花外漏声迢递。雾塞雁，起城乌，画屏金鹧鸪。\n香雾薄，透帘幕，惆怅谢家池阁。红烛背，绣帘垂，梦长君不知。'},
    {t:'更漏子·柳丝长',a:'晏几道〔宋代〕',c:'柳丝长，桃叶小。深院断无人到。红日淡，绿烟晴。流莺三两声。\n雪香浓，檀晕少。枕上卧枝花好。春思重，晓妆迟。寻思残梦时。'},
    {t:'更漏子·露华高',a:'晏几道〔宋代〕',c:'露华高，风信远，\n宿醉画帘低卷。\n梳洗倦，冶游慵，\n绿窗春睡浓。\n彩条轻，金缕重，\n昨日小桥相送。\n芳草恨，落花愁，\n去年同倚楼。'},
    {t:'更漏子·蕣华浓',a:'晏殊〔宋代〕',c:'蕣华浓，山翠浅。一寸秋波如剪。红日永，绮筵开。暗随仙驭来。\n遏云声，回雪袖。占断晓莺春柳。才送目，又颦眉。此情谁得知。'},
    {t:'更漏子·送孙巨源',a:'苏轼〔宋代〕',c:'水涵空，山照市。西汉二疏乡里。新白发，旧黄金。故人恩义深。\n海东头，山尽处。自古客槎来去。槎有信，赴秋期。使君行不归。'},
    {t:'更漏子·相见稀',a:'温庭筠〔唐代〕',c:'相见稀，相忆久，眉浅澹烟如柳。垂翠幕，结同心，待郎熏绣衾。\n城上月，白如雪，蝉鬓美人愁绝。宫树暗，鹊桥横，玉签初报明。'},
    {t:'更漏子·星斗稀',a:'温庭筠〔唐代〕',c:'星斗稀，钟鼓歇，帘外晓莺残月。兰露重，柳风斜，满庭堆落花。\n虚阁上，倚阑望，还似去年惆怅。春欲暮，思无穷，旧欢如梦中。'},
    {t:'更漏子·雪藏梅',a:'晏殊〔宋代〕',c:'雪藏梅，烟著柳。依约上春时候。花送雁，欲闻莺。绿池波浪生。\n探花开，留客醉。忆得去年情味。金盏酒，玉炉香。任他红日长。'},
    {t:'更漏子·玉炉香',a:'温庭筠〔唐代〕',c:'玉炉香，红蜡泪，偏照画堂秋思。眉翠薄，鬓云残，夜长衾枕寒。\n梧桐树，三更雨，不道离情正苦。一叶叶，一声声，空阶滴到明。'},
    {t:'更漏子·欲论心',a:'晏几道〔宋代〕',c:'欲论心，先掩泪，\n零落去年风味。\n情卧处，不言时，\n愁多只自知。\n到情深，俱是怨，\n惟有梦中相见。\n犹似旧，奈人禁，\n偎人说寸心。'},
    {t:'更衣曲',a:'刘禹锡〔唐代〕',c:'博山炯炯吐香雾，红烛引至更衣处。\n夜如何其夜漫漫，邻鸡未鸣寒雁度。\n庭前雪压松桂丛，廊下点点悬纱笼。\n满堂醉客争笑语，嘈囋琵琶青幕中。'},
    {t:'公安送韦二少府匡赞',a:'杜甫〔唐代〕',c:'逍遥公后世多贤，送尔维舟惜此筵。\n念我能书数字至，将诗不必万人传！\n时危兵甲黄尘里，日短江湖白发前。\n古往今来皆涕泪，断肠分手各风烟。'},
    {t:'公安县怀古',a:'杜甫〔唐代〕',c:'野旷吕蒙营，江深刘备城。\n寒天催日短，风浪与云平。\n洒落君臣契，飞腾战伐名。\n维舟倚前浦，长啸一含情。'},
    {t:'公莫舞歌',a:'李贺〔唐代〕',c:'公莫舞歌者，咏项伯翼蔽刘沛公也。会中壮士，灼灼于人，故无复书；且南北乐府率有歌引。贺陋诸家，今重作公莫舞歌云。\n方花古础排九楹，刺豹淋血盛银罂。\n华筵鼓吹无桐竹，长刀直立割鸣筝。\n横楣粗锦生红纬，日炙锦嫣王未醉。\n腰下三看宝玦光，项庄掉鞘栏前起。\n材官小尘公莫舞，座上真人赤龙子。\n芒砀云端抱天回，咸阳王气清如水。\n铁枢铁楗重束关，大旗五丈撞双环。\n汉王今日须秦印，绝膑刳肠臣不论。'},
    {t:'公无出门',a:'李贺〔唐代〕',c:'天迷迷，地密密。\n熊虺食人魂，雪霜断人骨。\n嗾犬狺狺相索索，舐掌偏宜佩兰客。\n帝遣乘轩灾自息，玉星点剑黄金轭。\n我虽跨马不得还，历阳湖波大如山。\n毒虬相视振金环，狻猊猰貐吐馋涎。\n鲍焦一世披草眠，颜回廿九鬓毛斑。\n颜回非血衰，鲍焦不违天；\n天畏遭衔啮，所以致之然。\n分明犹惧公不信，公看呵壁书问天。'},
    {t:'公无渡河',a:'李白〔唐代〕',c:'黄河西来决昆仑，咆哮万里触龙门。\n波滔天，尧咨嗟。\n大禹理百川，儿啼不窥家。\n杀湍湮洪水，九州始蚕麻。\n其害乃去，茫然风沙。\n被发之叟狂而痴，清晨临流欲奚为。\n旁人不惜妻止之，公无渡河苦渡之。\n虎可搏，河难凭，公果溺死流海湄。\n有长鲸白齿若雪山，公乎公乎挂罥于其间。\n箜篌所悲竟不还。'},
    {t:'公仪招观画',a:'晏几道〔宋代〕',c:'初约看花花已尽，重亲闲客客应欢。真花既不能长艳，画在霜纨更好看。'},
    {t:'宫词',a:'张籍〔唐代〕',c:'新鹰初放兔犹肥，白日君王在内稀。\n薄暮千门临欲锁，红妆飞骑向前归。\n黄金捍拨紫檀槽，弦索初张调更高。\n尽理昨来新上曲，内官帘外送樱桃。'},
    {t:'宫祠二首',a:'杜牧〔唐代〕',c:'蝉翼轻绡傅体红，玉肤如醉向沙风。\n深宫锁闭犹疑惑，更取丹沙试辟宫。\n监宫引出暂开门，随例须朝不是恩。\n银钥却收金锁合，月明花落又黄昏。'},
    {t:'宫辞',a:'李商隐〔唐代〕',c:'君恩如水向东流，得宠忧移失宠愁。\n莫向尊前奏花落，凉风只在殿西头。'},
    {t:'宫槐陌',a:'王维〔唐代〕',c:'仄径荫宫槐，幽阴多绿苔。\n应门但迎扫，畏有山僧来。'},
    {t:'宫妓',a:'李商隐〔唐代〕',c:'珠箔轻明拂玉墀，披香新殿斗腰支。\n不须看尽鱼龙戏，终遣君王怒偃师。'},
    {t:'宫娃歌',a:'李贺〔唐代〕',c:'蜡光高悬照纱空，花房夜捣红守宫。\n象口吹香毾覴暖，七星挂城闻漏板。\n寒入罘罳殿影昏，彩鸾帘额著霜痕。\n啼蛄吊月钩阑下，屈膝铜铺锁阿甄。\n梦入家门上沙渚，天河落处长洲路。\n愿君光明如太阳，放妾骑鱼撇波去。'},
    {t:'巩北秋兴寄崔明允',a:'岑参〔唐代〕',c:'白露披梧桐，玄蝉昼夜号。\n秋风万里动，日暮黄云高。\n君子佐休明，小人事蓬蒿。\n所适在鱼鸟，焉能徇锥刀。\n孤舟向广武，一鸟归成皋。\n胜概日相与，思君心郁陶。'},
    {t:'沟上梅花欲发',a:'王安石〔宋代〕',c:'亭亭背暖临沟处，脉脉含芳映雪时。\n莫恨夜来无伴侣，月明还见影参差。'},
    {t:'缑山西峰草堂作',a:'岑参〔唐代〕',c:'结庐对中岳，青翠常在门。遂耽句木兴，尽作渔樵言。\n顷来阙章句，但欲闲心魂。日色隐空谷，蝉净喧暮村。\n曩闻道士语，偶见清净源。隐几阅吹叶，乘秋眺归根。\n独游念求仲，开径招王孙。片雨下南涧，孤峰出东原。\n栖迟虑益澹，脱略道弥敦。野霭晴拂枕，客帆遥入轩。\n尚平今何在，此意谁与论。伫立云去尽，苍苍月开园。'},
    {t:'缑氏尉沈兴宗置酒南溪留赠',a:'王昌龄〔唐代〕',c:'林色与溪古，深篁引幽翠。山尊在渔舟，棹月情已醉。\n始穷清源口，壑绝人境异。春泉滴空崖，萌草拆阴地。\n久之风榛寂，远闻樵声至。海雁时独飞，永然沧洲意。\n古时青冥客，灭迹沦一尉。吾子踌躇心，岂其纷埃事。\n缑峰信所克，济北余乃遂。齐物意已会，息肩理犹未。\n卷舒形性表，脱略贤哲议。仲月期角巾，饭僧嵩阳寺。'},
    {t:'岣嵝山',a:'韩愈〔唐代〕',c:'岣嵝山尖神禹碑，字青石赤形模奇。科斗拳身薤倒披，\n鸾飘凤泊拿虎螭。事严迹秘鬼莫窥，道人独上偶见之，\n我来咨嗟涕涟洏。千搜万索何处有，森森绿树猿猱悲。'},
    {t:'构法华寺西亭',a:'柳宗元〔唐代〕',c:'窜身楚南极，山水穷险艰。\n步登最高寺，萧散任疏顽。\n西垂下斗绝，欲似窥人寰。\n反如在幽谷，榛翳不可攀。\n命童恣披翦，葺宇横断山。\n割如判清浊，飘若升云间。\n远岫攒众顶，澄江抱清湾。\n夕照临轩堕，栖鸟当我还。\n菡萏溢嘉色，筼筜遗清斑。\n神舒屏羁锁，志适忘幽潺。\n弃逐久枯槁，迨今始开颜。\n赏心难久留，离念来相关。\n北望间亲爱，南瞻杂夷蛮。\n置之勿复道，且寄须臾闲。'},
    {t:'估客行',a:'李白〔唐代〕',c:'海客乘天风，将船远行役。\n譬如云中鸟，一去无踪迹。'},
    {t:'孤鹤思太清',a:'朱熹〔宋代〕',c:'孤鹤悲秋晚，凌风绝太清。一为栖苑客，空有叫群声。\n夭矫千年质，飘飖万里情。九皋无枉路，从遣碧云生。'},
    {t:'孤山寺遇雨',a:'白居易〔唐代〕',c:'拂波云色重，洒叶雨声繁。\n水鹭双飞起，风荷一向翻。\n空濛连北岸，萧飒入东轩。\n或拟湖中宿，留船在寺门。'},
    {t:'孤桐',a:'王安石〔宋代〕',c:'天质自森森，孤高几百寻。\n凌霄不屈己，得地本虚心。\n岁老根弥壮，阳骄叶更阴。\n明时思解愠，愿斫五弦琴。'},
    {t:'孤雁',a:'杜甫〔唐代〕',c:'孤雁不饮啄，飞鸣声念群。\n谁怜一片影，相失万重云？\n望尽似犹见，哀多如更闻。\n野鸦无意绪，鸣噪自纷纷。'},
    {t:'姑苏馆夜雪',a:'杨万里〔宋代〕',c:'昨朝晴色动春熙，入夜星河弄碧漪。\n谁信雪花能样巧，等他人睡不教知。\n起来红日恍开霁，照得王花光陆离。\n归去中都说奇事，姑苏馆里上元晴。'},
    {t:'姑苏行',a:'皎然〔唐代〕',c:'古台不见秋草衰，却忆吴王全盛时。千年月照秋草上，\n吴王在时几回望。至今月出君不还，世人空对姑苏山。\n山中精灵安可睹，辙迹人踪麋鹿聚。婵娟西子倾国容，\n化作寒陵一堆土。'},
    {t:'古八变歌',a:'佚名〔两汉〕',c:'北风初秋至，吹我章华台。\n浮云林暮色，似从崦嵫来。\n枯桑鸣中林，络纬响空阶。\n翩翩飞蓬征，怆怆游子怀。\n故乡不可见，长望始此回。'},
    {t:'古北口',a:'纳兰性德〔清代〕',c:'乱山入戟拥孤城，一线人争鸟北行。\n地险东西分障塞，云开南北望神京。\n新图已入三关志，往事休论十路兵。\n都护近来长不调，年年烽火报升平。'},
    {t:'古别离',a:'孟郊〔唐代〕',c:'欲别牵郎衣，郎今到何处？\n不恨归来迟，莫向临邛去。'},
    {t:'古钗叹',a:'张籍〔唐代〕',c:'古钗堕井无颜色，百尺泥中今复得。凤凰宛转有古仪，\n欲为首饰不称时。女伴传看不知主，罗袖拂拭生光辉。\n兰膏已尽股半折，雕文刻样无年月。虽离井底入匣中，\n不用还与坠时同。'},
    {t:'古词二首·一作讽古',a:'刘禹锡〔唐代〕',c:'轩后初冠冕，前旒为蔽明。安知从复道，然后见人情。\n簿领乃俗士，清谈信古风。吾观苏令绰，朱墨一何工。'},
    {t:'古大梁行',a:'高适〔唐代〕',c:'古城莽苍饶荆榛，驱马荒城愁杀人，\n魏王宫观尽禾黍，信陵宾客随灰尘。\n忆昨雄都旧朝市，轩车照耀歌钟起，\n军容带甲三十万，国步连营一千里。\n全盛须臾哪可论，高台曲池无复存，\n遗墟但见狐狸迹，古地空余草木根。\n暮天摇落伤怀抱，抚剑悲歌对秋草，\n侠客犹传朱亥名，行人尚识夷门道。\n白璧黄金万户侯，宝刀骏马填山丘，\n年代凄凉不可问，往来唯见水东流。'},
    {t:'古东门行',a:'柳宗元〔唐代〕',c:'汉家三十六将军，东方雷动横阵云。\n鸡鸣函谷客如雾，貌同心异不可数。\n赤丸夜语飞电光，徼巡司隶眠如羊。\n当街一叱百吏走，冯敬胸中函匕首。\n凶徒侧耳潜惬心，悍臣破胆皆杜口。\n魏王卧内藏兵符，子西掩袂真无辜。\n羌胡毂下一朝起，敌国舟中非所拟。\n安陵谁辨削砺功，韩国讵明深井里。\n绝胭断骨那下补，万金宠赠不如土。'},
    {t:'古风',a:'韩愈〔唐代〕',c:'今日曷不乐，幸时不用兵。\n无曰去蹙矣，乃尚可以生。\n彼州之赋，去汝不顾。\n此州之役，去我奚适。\n一邑之水，可走而违。\n天下汤汤，曷其而归。\n好我衣服，甘我饮食。\n无念百年，聊乐一日。'},
    {t:'古风·蟾蜍薄太清',a:'李白〔唐代〕',c:'蟾蜍薄太清，蚀此瑶台月。\n圆光微中天，金魄遂沦没。\n蝃蝀入紫微，大明夷朝晖。\n浮云隔两曜，万象昏阴霏。\n萧萧长门宫，昔是今已非。\n桂蠹花不实，天霜下严威。\n沉叹终永夕，感我涕沾衣。'},
    {t:'古风·代马不思越',a:'李白〔唐代〕',c:'代马不思越，越禽不恋燕。\n情性有所习，土风固其然。\n昔别雁门关，今戍龙庭前。\n惊沙乱海日，飞雪迷胡天。\n虮虱生虎鹖，心魂逐旌旃。\n苦战功不赏，忠诚难可宣。\n谁怜李飞将，白首没三边。'},
    {t:'古风·凤飞九千仞',a:'李白〔唐代〕',c:'凤飞九千仞，五章备彩珍。\n衔书海虚归，空入周与秦。\n横绝历四海，所居未得邻。\n吾营紫河车，千溪落风尘。\n药物秘海岳，采铅青溪滨。\n时登大楼山，举首望仙真。\n羽驾灭去影，飚车绝回轮。\n尚恐丹液迟，志愿不及申。\n徒霜镜中发，羞彼鹤上人。\n桃李何处开，此花非我春。\n唯应清都境，长与韩众亲。'},
    {t:'古风·胡关饶风沙',a:'李白〔唐代〕',c:'胡关饶风沙，萧索竟终古。\n木落漠草黄，登高望戎虏。\n荒城空大漠，边邑无遗堵。\n白骨横千霜，嵯威蔽榛莽。\n借问谁凌虐，天骄毒威武。\n赫怒我圣皇，劳师事鼙鼓。\n阳和变杀气，发卒骚中土。\n三十六万人，哀哀泪如雨。\n且悲就行役，安得营农圃。\n不见征戍儿，岂知关山苦。\n李牧今不在，边人饲豺虎。'},
    {t:'古风·齐有倜傥生',a:'李白〔唐代〕',c:'齐有倜傥生，鲁连特高妙。\n明月出海底，一朝开光曜。\n却秦振英声，后世仰末照。\n意轻千金赠，顾向平原笑。\n吾亦澹荡人，拂衣可同调。'},
    {t:'古风·其二十六',a:'李白〔唐代〕',c:'碧荷生幽泉，朝日艳且鲜。\n秋花冒绿水，密叶罗青烟。\n秀色空绝世，馨香为谁传。\n坐看飞霜满，凋此红芳年。\n结根未得所，愿托华池边。'},
    {t:'古风·其二十四',a:'李白〔唐代〕',c:'大车扬飞尘，亭午暗阡陌。\n中贵多黄金，连云开甲宅。\n路逢斗鸡者，冠盖何辉赫。\n鼻息干虹蜺，行人皆怵惕。\n世无洗耳翁，谁知尧与跖。'},
    {t:'古风·其三十九',a:'李白〔唐代〕',c:'登高望四海，天地何漫漫！\n霜被水物秋，风飘大荒寒。\n荣华东流水，万事皆波澜。\n白日掩徂辉，浮云无定端。\n梧桐巢燕雀，枳棘栖鸳鸾。\n且复归去来，剑歌行路难。'},
    {t:'古风·其三十四',a:'李白〔唐代〕',c:'羽檄如流星，虎符合专城。\n喧呼微边急，群鸟皆夜鸣。\n白日曜紫微，三公运权衡。\n天地皆得一，澹征四海清。\n借问此何为？答言楚征兵。\n渡泸及五月，将赴云南征。\n怯卒非战士，炎方难远行。\n长号别严亲，日月惨光晶。\n泣尽继以血，心摧两无声。\n困兽当猛虎，穷鱼饵奔鲸。\n千去不一还，投躯岂全生。\n如何舞干戚，一使有苗平。'},
    {t:'古风·秦王扫六合',a:'李白〔唐代〕',c:'秦王扫六合，虎视何雄哉！\n挥剑决浮云，诸侯尽西来。\n明断自天启，大略驾群才。\n收兵铸金人，函谷正东开。\n铭功会稽岭，骋望琅琊台。\n刑徒七十万，起土骊山隈。\n尚采不死药，茫然使心哀。\n连弩射海鱼，长鲸正崔嵬。\n额鼻象五岳，扬波喷云雷。\n鬐鬣蔽青天，何由睹蓬莱？\n徐巿载秦女，楼船几时回？\n但见三泉下，金棺葬寒灰。'},
    {t:'古风·太白何苍苍',a:'李白〔唐代〕',c:'太白何苍苍，星辰上森列。\n去天三百里，邈尔与世绝。\n中有绿发翁，披云卧松雪。\n不笑亦不语，冥栖在岩穴。\n我来逢真人，长跪问宝诀。\n粲然启玉齿，授以炼药说。\n铭骨传其语，竦身已电灭。\n仰望不可及，苍然五情热。\n吾将营丹砂，永与世人别。'},
    {t:'古风·五鹤西北来',a:'李白〔唐代〕',c:'五鹤西北来，飞飞凌太清。\n仙人绿云上，自道安期名。\n两两白玉童，双吹紫鸾笙。\n去影忽不见，回风送天声。\n我欲一问之，飘然若流星。\n愿餐金光草，寿与天齐倾。'},
    {t:'古风·西上莲花山',a:'李白〔唐代〕',c:'西上莲花山，迢迢见明星。\n素手把芙蓉，虚步蹑太清。\n霓裳曳广带，飘拂升天行。\n邀我登云台，高揖卫叔卿。\n恍恍与之去，驾鸿凌紫冥。\n俯视洛阳川，茫茫走胡兵。\n流血涂野草，豺狼尽冠缨。'},
    {t:'古风·昔我游齐都',a:'李白〔唐代〕',c:'昔我游齐都，登华不注峰。\n兹山何峻秀，绿翠如芙蓉。\n萧飒古仙人，了知是赤松。\n借予一白鹿，自挟两青龙。\n含笑凌倒景，欣然愿相从。\n泣与亲友别，欲语再三咽。\n勖君青松心，努力保霜雪。\n世路多险艰，白日欺红颜。\n分手各千里，去去何时还。\n在世复几时，倏如飘风度。\n空闻紫金经，白首愁相误。\n抚己忽自笑，沉吟为谁故。\n名利徒煎熬，安得闲余步。\n终留赤玉舄，东上蓬莱路。\n秦帝如我求，苍苍但烟雾。'},
    {t:'古风·燕昭延郭隗',a:'李白〔唐代〕',c:'燕昭延郭隗，遂筑黄金台。\n剧辛方赵至，邹衍复齐来。\n奈何青云士，弃我如尘埃。\n珠玉买歌笑，糟糠养贤才。\n方知黄鹄举，千里独徘徊。'},
    {t:'古风·庄周梦胡蝶',a:'李白〔唐代〕',c:'庄周梦胡蝶，胡蝶为庄周。\n一体更变易，万事良悠悠。\n乃知蓬莱水，复作清浅流。\n青门种瓜人，旧日东陵侯。\n富贵故如此，营营何所求。'},
    {t:'古风次韵答初和甫二首',a:'黄庭坚〔宋代〕',c:'君吟春风花草香，我爱春夜璧月凉。\n美人美人隔湘水，其雨其雨怨朝阳。\n兰荃盈怀报琼玖，冠缨自洁非沧浪。\n道人四十心如水，那得梦为胡蝶狂。'},
    {t:'古风二首上苏子瞻·其一',a:'黄庭坚〔宋代〕',c:'江梅有佳实，托根桃李场。\n桃李白不言，朝露借恩光。\n孤芳忌洁白，冰雪空自香。\n古来和鼎实，此已升庙廊。\n岁月坐成晚，烟雨青已黄。\n得升桃李盘，以远初见尝。\n白然不可口，掷置官道旁。\n但使本根在，弃捐果何伤。'},
    {t:'古歌',a:'佚名〔两汉〕',c:'秋风萧萧愁杀人，出亦愁，入亦愁。\n座中何人，谁不怀忧？令我白头。\n胡地多飚风，树木何修修。\n离家日趋远，衣带日趋缓。\n心思不能言，肠中车轮转。'},
    {t:'古歌行',a:'高适〔唐代〕',c:'君不见汉家三叶从代至，高皇旧臣多富贵。\n天子垂衣方晏如，庙堂拱手无馀议。苍生偃卧休征战，\n露台百金以为费。田舍老翁不出门，洛阳少年莫论事。'},
    {t:'古剑行',a:'韦应物〔唐代〕',c:'千年土中两刃铁，土蚀不入金足灭。沉沉青脊鳞甲满，\n蛟龙无足蛇尾断，忽欲飞动中有灵。豪鸣得之敌国宝，\n仇家举意半夜鸣。小儿女子不可近，龙蛇变化此中隐。\n夏云奔走雷阗阗，恐成霹雳飞上天。'},
    {t:'古朗月行',a:'李白〔唐代〕',c:'小时不识月，呼作白玉盘。\n又疑瑶台镜，飞在青云端。\n仙人垂两足，桂树何团团。\n白兔捣药成，问言与谁餐？\n蟾蜍蚀圆影，大明夜已残。\n羿昔落九乌，天人清且安。\n阴精此沦惑，去去不足观。\n忧来其如何？凄怆摧心肝。'},
    {t:'古诗二首上苏子瞻·其二',a:'黄庭坚〔宋代〕',c:'青松出涧壑，十里闻风声。\n上有百尺丝，下有千岁苓。\n自性得久要，为人制颓龄。\n小草有远志，相依在平生。\n医和不并世，深根且固蒂。\n人言可医国，何用太早计。\n小大材则殊，气味固相似。'},
    {t:'古树',a:'张籍〔唐代〕',c:'古树枝柯少，枯来复几春。露根堪系马，空腹定藏人。\n蠹节莓苔老，烧痕霹雳新。若当江浦上，行客祭为神。'},
    {t:'古松',a:'王安石〔宋代〕',c:'森森直干百余寻，高入青冥不附林。\n万壑风生成夜响，千山月照挂秋阴。\n岂因粪壤栽培力，自得乾坤造化心。\n廊庙乏材应见取，世无良匠勿相侵。'},
    {t:'古瓦砚诗',a:'晏殊〔宋代〕',c:'邺城宫殿久荒凉，缥瓦随波出破墙。\n谁约藓文成古砚，等间裁破碧鸳鸯。\n已恣玉锋磨藓骨，更持蟾泪湿云根。\n欲知千载凄凉意，尚有昭阳夜雨痕。'},
    {t:'古兴',a:'孟郊〔唐代〕',c:'楚血未干衣，荆虹尚埋辉。痛玉不痛身，抱璞求所归。'},
    {t:'古艳诗二首',a:'元稹〔唐代〕',c:'春来频到宋家东，垂袖开怀待花风。\n莺藏柳暗无人语，惟有墙花满树红。\n深院无人草树光，娇莺不语趁阴藏。\n等闲弄水浮花片，流出门前赚阮郎。'},
    {t:'古邺城童子谣效王粲刺曹操',a:'李贺〔唐代〕',c:'邺城中，暮尘起。\n将黑丸，斫文吏。\n棘为鞭，虎为马。\n团团走，邺城下。\n切玉剑，射日弓。\n献何人，奉相公。\n扶毂来，关右儿。\n香扫涂，相公归。'},
    {t:'古意',a:'李白〔唐代〕',c:'君为女萝草，妾作菟丝花。\n轻条不自引，为逐春风斜。\n百丈托远松，缠绵成一家。\n谁言会面易，各在青山崖。\n女萝发馨香，菟丝断人肠。\n枝枝相纠结，叶叶竞飘扬。\n生子不知根，因谁共芬芳。\n中巢双翡翠，上宿紫鸳鸯。\n若识二草心，海潮亦可量。'},
    {t:'古意',a:'韩愈〔唐代〕',c:'太华峰头玉井莲，开花十丈藕口船。冷比雪霜甘比蜜，\n一片入口沈痾痊。我欲求之不惮远，青壁无路难夤缘。\n安得长梯上摘实，下种七泽根株连。'},
    {t:'古意',a:'温庭筠〔唐代〕',c:'莫莫复莫莫，丝萝缘涧壑。散木无斧斤，纤茎得依托。\n枝低浴鸟歇，根静悬泉落。不虑见春迟，空伤致身错。'},
    {t:'古意',a:'王昌龄〔唐代〕',c:'桃花四面发，桃叶一枝开。\n欲暮黄鹂啭，伤心玉镜台。\n清筝向明月，半夜春风来。'},
    {t:'古意题徐令壁',a:'陈子昂〔唐代〕',c:'白云苍梧来，氛氲万里色。闻君太平世，栖泊灵台侧。'},
    {t:'古意赠梁肃补阙',a:'孟郊〔唐代〕',c:'曲木忌日影，谗人畏贤明。自然照烛间，不受邪佞轻。\n不有百炼火，孰知寸金精。金铅正同炉，愿分精与粗。'},
    {t:'古意赠郑彦能八音歌',a:'黄庭坚〔宋代〕',c:'金欲百链刚，不欲绕指柔。\n石羊缚荒草，一世如蜉蝣。\n丝成蚕自缚，智成龟自囚。\n竹箭天与美，岂墙作嚆矢。\n匏枯中笙竽，不用系墙隅。\n土偶与木偶，未用相贤愚。\n革辙要合道，覆车还不好。\n木讷赤子心，百巧令人老。'},
    {t:'古悠悠行',a:'李贺〔唐代〕',c:'白景归西山，碧华上迢迢。\n今古何处尽，千岁随风飘。\n海沙变成石，鱼沫吹秦桥。\n空光远流浪，铜柱从年消。'},
    {t:'古苑杏花',a:'张籍〔唐代〕',c:'废苑杏花在，行人愁到时。\n独开新堑底，半露旧烧枝。\n晚色连荒辙，低阴覆折碑。\n茫茫古陵下，春尽又谁知。'},
    {t:'古怨别',a:'孟郊〔唐代〕',c:'飒飒秋风生，愁人怨离别。\n含情两相向，欲语气先咽。\n心曲千万端，悲来却难说。\n别后唯所思，天涯共明月。'},
    {t:'鼓吹曲辞上之回',a:'李贺〔唐代〕',c:'上之回，大旗喜。悬虹彗，挞凤尾。剑匣破，舞蛟龙。\n蚩尤死，鼓逢逢。天高庆雷齐坠地，地无惊烟海千里。'},
    {t:'鼓笛慢·乱花丛里曾携手',a:'秦观〔宋代〕',c:'乱花丛里曾携手，穷艳景，迷欢人。到如今，谁把雕鞍锁定，阻游人来往。好梦随春远，从前事、不难思想。念香闺正杳，佳欢未偶，难留恋、空惆怅。\n永夜婵娟未满，叹玉楼、几时重上。那难万里，却寻归路，指阳关孤唱。苦恨东流水，桃源路、欲回双桨。仗何人细与、丁宁问呵，我如今怎向？'},
    {t:'故城曲',a:'温庭筠〔唐代〕',c:'漠漠沙堤烟，堤西雉子斑。雉声绿角角，麦秀桑阴闲。\n游丝荡平绿，明灭时相续。白马金络头，东风故城曲。\n故城殷贵嫔，曾占未来春。自从香骨化，飞作马蹄尘。'},
    {t:'故洛阳城有感',a:'杜牧〔唐代〕',c:'一片宫墙当道危，行人为尔去迟迟。筚圭苑里秋风后，\n平乐馆前斜日时。锢党岂能留汉鼎，清谈空解识胡儿。\n千烧万战坤灵死，惨惨终年鸟雀悲。'},
    {t:'故仆射裴公挽歌三首',a:'岑参〔唐代〕',c:'盛德资邦杰，嘉谟作世程。门瞻送马贵，时仰八龙名。\n罢市秦人送，还乡绛老迎。莫埋丞相印，留大付玄成。\n五府瞻高位，三台丧大贤。礼容还故绛，宠赠冠新田。\n气歇汾阴鼎，魂飞京兆阡。先时剑已没，陇树久苍然。\n富贵徒言久，乡闾殁后归。锦衣都未大，丹旐忽先飞。\n哀挽辞秦塞，悲笳出帝畿。遥知九原上，渐觉吊人稀。'},
    {t:'故衫',a:'白居易〔唐代〕',c:'暗淡绯衫称老身，半披半曳出朱门。\n袖中吴郡新诗本，襟上杭州旧酒痕。\n残色过梅看向尽，故香因洗嗅犹存。\n曾经烂熳三年著，欲弃空箱似少恩。'},
    {t:'故刑部李尚书荆谷山集会',a:'张九龄〔唐代〕',c:'尝闻继老聃，身退道弥耽。结宇倚青壁，疏泉喷碧潭。\n苔石随人古，烟花寄酒酣。山光纷向夕，归兴杜城南。'},
    {t:'故刑部李尚书挽词三首',a:'张九龄〔唐代〕',c:'仙宗出赵北，相业起山东。明德尝为礼，嘉谋屡作忠。\n论经白虎殿，献赋甘泉宫。与善今何在，苍生望已空。\n宿昔三台践，荣华驷马归。印从青琐拜，翰入紫宸挥。\n题剑恩方重，藏舟事已非。龙门不可望，感激涕沾衣。\n永叹常山宝，沉埋京兆阡。同盟会五月，华表记千年。\n渺漫野中草，微茫空里烟。共悲人事绝，唯对杜陵田。'},
    {t:'故刑部李尚书挽词三首其三',a:'张九龄〔唐代〕',c:'永叹常山宝，沈埋京兆阡。同盟会五月，华表记千年。\n渺漫野中草，微茫空里烟。共悲人事绝，唯对杜陵田。'},
    {t:'瓜园诗',a:'王维〔唐代〕',c:'余适欲锄瓜，倚锄听叩门。鸣驺呼骢马，常从夹朱轩。\n穷巷正传呼，故人傥相存。携手追凉风，放何望乾坤。\n蔼蔼帝王州，宫观一何繁。林端出绮道，殿顶摇华幡。\n素怀在青山，若值白云屯。回风城西雨，返景原上村。\n前酌盈尊酒，往往闻清言。黄鹂啭深木，朱槿照中园。\n犹羡松下客，石上闻清猿。'},
    {t:'关河令',a:'周邦彦〔宋代〕',c:'秋阴时晴向暝。变一庭凄冷。伫听寒声，云深无雁影。\n更深人去寂静。但照壁、孤灯相映。酒已都醒，如何消夜永。'},
    {t:'关河令·秋阴时晴渐向暝',a:'周邦彦〔宋代〕',c:'秋阴时晴渐向暝，变一庭凄冷。去听寒声，云深无雁影。\n更深人去寂静，但照壁孤灯相映。酒已都醒，如何消夜永！'},
    {t:'关山月',a:'陆游〔宋代〕',c:'和戎诏下十五年，将军不战空临边。\n朱门沉沉按歌舞，厩马肥死弓断弦。\n戍楼刁斗催落月，三十从军今白发。\n笛里谁知壮士心，沙头空照征人骨。\n中原干戈古亦闻，岂有逆胡传子孙！\n遗民忍死望恢复，几处今宵垂泪痕。'},
    {t:'关山月',a:'李白〔唐代〕',c:'明月出天山，苍茫云海间。\n长风几万里，吹度玉门关。\n汉下白登道，胡窥青海湾。\n由来征战地，不见有人还。\n戍客望边邑，思归多苦颜。\n高楼当此夜，叹息未应闲。'},
    {t:'观八阵图',a:'刘禹锡〔唐代〕',c:'轩皇传上略，蜀相运神机。水落龙蛇出，沙平鹅鹳飞。\n波涛无动势，鳞介避馀威。会有知兵者，临流指是非。'},
    {t:'观别者',a:'王维〔唐代〕',c:'青青杨柳陌，陌上别离人。\n爱子游燕赵，高堂有老亲。\n不行无可养，行去百忧新。\n切切委兄弟，依依向四邻。\n都门帐饮毕，从此谢亲宾。\n挥涕逐前侣，含凄动征轮。\n车徒望不见，时见起行尘。\n吾亦辞家久，看之泪满巾。'},
    {t:'观兵',a:'杜甫〔唐代〕',c:'北庭送壮士，貔虎数尤多。\n精锐旧无敌，边隅今若何。\n妖氛拥白马，元帅待雕戈。\n莫守邺城下，斩鲸辽海波。'},
    {t:'观博平王志安少府山水粉图',a:'李白〔唐代〕',c:'粉壁为空天，丹青状江海。\n游云不知归，日见白鸥在。\n博平真人王志安，沈吟至此愿挂冠。\n松溪石磴带秋色，愁客思归坐晓寒。'},
    {t:'观潮',a:'苏轼〔宋代〕',c:'庐山烟雨浙江潮，未至千般恨不消。\n到得还来别无事，庐山烟雨浙江潮。'},
    {t:'观村童戏溪上',a:'陆游〔宋代〕',c:'雨余溪水掠堤平，闲看村童谢扈晴。\n竹马踉蹡冲淖去，纸鸢跋扈挟风鸣。\n三冬暂就儒生学，千耦还从父老耕。\n识字粗堪供赋役，不须辛苦慕公卿。'},
    {t:'观大散关图有感',a:'陆游〔宋代〕',c:'上马击狂胡，下马草军书。\n二十抱此志，五十犹癯儒。\n大散陈仓间，山川郁盘纡。\n劲气钟义士，可与共壮图。\n坡陁咸阳城，秦汉之故都。\n王气浮夕霭，宫室生春芜。\n安得从王师，汛扫迎皇舆？\n黄河与函谷，四海通舟车。\n士马发燕赵，布帛来青徐。\n先当营七庙，次第画九衢。\n偏师缚可汗，倾都观受俘。\n上寿大安宫，复如正观初。\n丈夫毕此愿，死与蝼蚁殊。\n志大浩无期，醉胆空满躯。'},
    {t:'观放白鹰二首',a:'李白〔唐代〕',c:'八月边风高，胡鹰白锦毛。\n孤飞一片雪，百里见秋毫。\n寒冬十二月，苍鹰八九毛。\n寄言燕雀莫相啅，自有云霄万里高。'},
    {t:'观画目送飞雁手提白鱼',a:'晏几道〔宋代〕',c:'眼看飞雁手携鱼，似是当年绮季徒。仰羡知几避缯缴，俯嗟贪饵失江湖。\n人间感绪闻诗语，尘外高踪见画图。三叹绘毫精写意，慕冥伤涸两踟蹰。'},
    {t:'观江淮名胜图',a:'王昌龄〔唐代〕',c:'刻意吟云山，尤知隐沦妙。远公何为者，再诣临海峤。\n而我高其风，披图得遗照。援毫无逃境，遂展千里眺。\n淡扫荆门烟，明标赤城烧。青葱林间岭，隐见淮海徼。\n但指香炉顶，无闻白猿啸。沙门既云灭，独往岂殊调。\n感对怀拂衣，胡宁事渔钓。安期始遗舄，千古谢荣耀。\n投迹庶可齐，沧浪有孤棹。'},
    {t:'观荆玉篇',a:'陈子昂〔唐代〕',c:'鸱夷双白玉，此玉有缁磷。悬之千金价，举世莫知真。\n丹青非异色，轻重有殊伦。勿信玉工言，徒悲荆国人。'},
    {t:'观李九少府翥树宓子贱神祠碑',a:'高适〔唐代〕',c:'吾友吏兹邑，亦尝怀宓公。安知叹寐间，忽与精灵通。\n一见兴永叹，再来激深衷。宾从何逶迤，二林四老翁。\n于焉建层碑，突兀长林东。作者无愧色，行人感遗风。\n坐令高岸尽，独对秋山空。片石勿谓轻，斯言固难穷。\n龙盘色丝外，鹊顾偃波中。形胜驻群目，坚贞指苍穹。\n我非王仲宣，去矣徒发蒙。'},
    {t:'观猎',a:'范仲淹〔宋代〕',c:'鹰犬一何骄，霜明远近郊。\n鸾皇不触网，狐兔自充庖。\n熠熠流鸣镝，纷纷过绿髾。\n雄飞侵汉下，杀气与云交。\n翦棘争探穴，摧林竞覆巢。\n惟开三面者，盛德播弦匏。'},
    {t:'观猎',a:'王维〔唐代〕',c:'风劲角弓鸣，将军猎渭城。\n草枯鹰眼疾，雪尽马蹄轻。\n忽过新丰市，还归细柳营。\n回看射雕处，千里暮云平。'},
    {t:'观猎',a:'李白〔唐代〕',c:'太守耀清威，乘闲弄晚晖。\n江沙横猎骑，山火绕行围。\n箭逐云鸿落，鹰随月兔飞。\n不知白日暮，欢赏夜方归。'},
    {t:'观猎',a:'王昌龄〔唐代〕',c:'角鹰初下秋草稀，铁骢抛鞚去如飞。\n少年猎得平原兔，马后横捎意气归。'},
    {t:'观书有感·其二',a:'朱熹〔宋代〕',c:'昨夜江边春水生，蒙冲巨舰一毛轻。\n向来枉费推移力，此日中流自在行。'},
    {t:'观书有感·其一',a:'朱熹〔宋代〕',c:'半亩方塘一鉴开，天光云影共徘徊。\n问渠那得清如许？为有源头活水来。'},
    {t:'观田家',a:'韦应物〔唐代〕',c:'微雨众卉新，一雷惊蛰始。\n田家几日闲，耕种从此起。\n丁壮俱在野，场圃亦就理。\n归来景常晏，饮犊西涧水。\n饥劬不自苦，膏泽且为喜。\n仓廪无宿储，徭役犹未已。\n方惭不耕者，禄食出闾里。'},
    {t:'观王右丞维沧洲图歌',a:'皎然〔唐代〕',c:'沧洲误是真，萋萋忽盈视。便有草渚情，褰裳掇芳芷。\n飒然风至草不动，始悟丹青得如此。丹青犹化不可寻，\n翻空作有移人心。犹言雨色斜拂座，乍似水凉来入襟。\n沧洲说近三湘口，谁知卷得在君手。披图拥褐临水时，\n翛然不异沧洲叟。'},
    {t:'观王主簿家酴醾',a:'黄庭坚〔宋代〕',c:'肌肤冰雪薰沈水，百草千花莫比芳。\n露湿何郎试汤饼，日烘荀令炷炉香。\n风流彻骨成春酒，梦寐宜人入枕囊。\n输与能诗王主簿，瑶台影里据胡床。'},
    {t:'观舞妓',a:'温庭筠〔唐代〕',c:'朔音悲嘒管，瑶踏动芳尘。总袖时增怨，听破复含嚬。\n凝腰倚风软，花题照锦春。朱弦固凄紧，琼树亦迷人。'},
    {t:'观雪二首·其一',a:'杨万里〔宋代〕',c:'坐看深来尺许强，偏於薄暮发寒光。\n半空舞倦居然嬾，一点风来特地忙。\n落尽琼花天不惜，封它梅蕊玉无香。\n倩谁细橪成汤饼，换却人间烟火肠。'},
    {t:'观蚁二首',a:'杨万里〔宋代〕',c:'偶尔相逢细间途，不知何事数迁居。\n微躯所馔能多少，一猎归来满後车。'},
    {t:'观刈麦',a:'白居易〔唐代〕',c:'田家少闲月，五月人倍忙。\n夜来食风起，小麦覆陇黄。\n妇姑荷箪食，童稚携壶浆。\n相随饷田去，丁天在食冈。\n足蒸暑土气，背灼炎天光。\n力尽不知热，但惜夏日长。\n复有贫妇人，抱子在其旁。\n右手秉遗穗，左臂悬敝筐。\n听其相顾言，闻者为悲伤。\n家田输税尽，拾此充饥肠。\n今我何功德？曾不事农桑。\n吏禄三百石，岁晏有余粮。\n念此私自愧，尽日不能忘。'},
    {t:'观游鱼',a:'白居易〔唐代〕',c:'绕池闲步看鱼游，正值儿童弄钓舟。\n一种爱鱼心各异，我来施食尔垂钩。'},
    {t:'观早朝',a:'韦应物〔唐代〕',c:'伐鼓通严城，车马溢广躔。煌煌列明烛，朝服照华鲜。\n金门杳深沉，尚听清漏传。河汉忽已没，司阍启晨关。\n丹殿据龙首，崔嵬对南山。寒生千门里，日照双阙间。\n禁旅下成列，炉香起中天。辉辉睹明圣，济济行俊贤。\n愧无鸳鹭姿，短翮空飞还。谁当假毛羽，云路相追攀。'},
    {t:'观长安城图',a:'陆游〔宋代〕',c:'许国虽坚鬓已斑，山城经岁望城山。\n横戈上马嗟心在，穿堑环城笑虏孱。\n日暮风烟传陇上，秋高刁斗落云间。\n三秦父老应惆怅，不见王师出散关。'},
    {t:'观柘枝舞二首',a:'刘禹锡〔唐代〕',c:'胡服何葳蕤，仙仙登绮墀。神飙腰红蕖，龙烛映金枝。\n垂带覆纤腰，安钿当妩眉。翘袖中繁鼓，倾冶溯华榱。\n燕秦有旧曲，淮南多冶词。欲见倾城处，君看赴节时。\n山鸡临清镜，石燕赴遥津。何如上客会，长袖入华裀。\n体轻似无骨，观者皆耸神。曲尽回身处，层波犹注人。'},
    {t:'观种树',a:'孟郊〔唐代〕',c:'种树皆待春，春至难久留。君看朝夕花，谁免离别愁。\n心意已零落，种之仍未休。胡为好奇者，无事自买忧。'},
    {t:'官不来·题皇甫湜先辈厅',a:'李贺〔唐代〕',c:'官不来，官庭秋，\n老桐错干青龙愁。\n书司曹佐走如牛，\n叠声问佐官来不？\n官不来，门幽幽。'},
    {t:'官定后戏赠',a:'杜甫〔唐代〕',c:'不作河西尉，凄凉为折腰。\n老夫怕趋走，率府且逍遥。\n耽酒须微禄，狂歌托圣朝。\n故山归兴尽，回首向风飙。'},
    {t:'官街鼓',a:'李贺〔唐代〕',c:'晓声隆隆催转日，暮声隆隆呼月出。\n汉城黄柳映新帘，柏陵飞燕埋香骨。\n磓碎千年日长白，孝武秦皇听不得。\n从君翠发芦花色，独共南山守中国。\n几回天上葬神仙，漏声相将无断绝。'},
    {t:'光华寺',a:'秦观〔宋代〕',c:'霞通海天曙，月来东山白。\n共是凭栏人，谁足当秋色。'},
    {t:'广德中洛阳作',a:'韦应物〔唐代〕',c:'生长太平日，不知太平欢。今还洛阳中，感此方苦酸。\n饮药本攻病，毒肠翻自残。王师涉河洛，玉石俱不完。\n时节屡迁斥，山河长郁盘。萧条孤烟绝，日入空城寒。\n蹇劣乏高步，缉遗守微官。西怀咸阳道，踯躅心不安。'},
    {t:'广陵别薛八·一题作送友东归',a:'孟浩然〔唐代〕',c:'士有不得志，栖栖吴楚间。广陵相遇罢，彭蠡泛舟还。\n樯出江中树，波连海上山。风帆明日远，何处更追攀。'},
    {t:'广陵别郑处士',a:'高适〔唐代〕',c:'落日知分手，春风莫断肠。兴来无不惬，才在亦何伤。\n溪水堪垂钓，江田耐插秧。人生只为此，亦足傲羲皇。'},
    {t:'广陵五题其二次韵子由题平山堂',a:'秦观〔宋代〕',c:'栋宇高开古寺间，尽数佳处入南栏。\n山浮海上青螺远，天转江南碧玉宽。\n雨槛幽花滋浅泪，风卮清酒涨微澜。\n游人若论登临美，须作淮东第一观。'},
    {t:'广陵行',a:'韦应物〔唐代〕',c:'雄藩镇楚郊，地势郁岧峣。双旌拥万戟，中有霍嫖姚。\n海云助兵气，宝货益军饶。严城动寒角，晚骑踏霜桥。\n翕习英豪集，振奋士卒骁。列郡何足数，趋拜等卑寮。\n日宴方云罢，人逸马萧萧。忽如京洛间，游子风尘飘。\n归来视宝剑，功名岂一朝。'},
    {t:'广陵遇孟九云卿',a:'韦应物〔唐代〕',c:'雄藩本帝都，游士多俊贤。夹河堂郁郁，华馆千里连。\n新知虽满堂，中意颇未宣。忽逢翰林友，欢不斗酒前。\n高文激颓波，四海靡不传。西施且一笑，众女安得妍。\n明月满淮海，哀鸿逝长天。所念京国远，我来君欲还。'},
    {t:'广陵赠别',a:'李白〔唐代〕',c:'玉瓶沽美酒，数里送君还。\n系马垂杨下，衔杯大道间。\n天边看渌水，海上见青山。\n兴罢各分袂，何须醉别颜。'},
    {t:'广宣上人频见过',a:'韩愈〔唐代〕',c:'三百六旬长扰扰，不冲风雨即僧埃。\n久惭朝士无裨补，空愧高僧数往来。\n学道穷年何所得，吟诗竟日未能回。\n天寒古寺游人少，红叶窗前有几堆。'},
    {t:'归朝欢·别岸扁舟三两只',a:'柳永〔宋代〕',c:'别岸扁舟三两只。葭苇萧萧风月月。沙汀宿雁破烟飞，溪桥残月和霜白。渐渐分曙色。路遥山是多行役。往来人，只轮双桨，尽是利名客。\n一望乡关烟水隔。转觉归心生羽翼。愁云恨雨两牵萦，新春残腊相催逼。岁华都瞬息。浪萍风梗诚何益。归去来，玉楼深处，有个人相忆。'},
    {t:'归朝欢·和苏坚伯固',a:'苏轼〔宋代〕',c:'我梦扁舟浮震泽。雪浪摇空千顷白。觉来满眼是庐山，倚天无数开青壁。此生长接淅。与君同是江南客。梦中游，觉来清赏，同作飞梭掷。\n明日西风还挂席。唱我新词泪沾臆。灵均去后楚山空，澧阳兰芷无颜色。君才如梦得。武陵更在西南极。《竹枝词》，莫傜新唱，谁谓古今隔。'},
    {t:'归朝欢·题晋臣敷文积翠岩',a:'辛弃疾〔宋代〕',c:'我笑共工缘底怒。触断峨峨天一柱。补天又笑女娲忙，却将此石投闲处。野烟荒草路。先生柱杖来看汝。倚苍苔，摩挲试问，千古几风雨。\n长被儿童敲火苦。时有牛羊磨角去。霍然千丈翠岩屏，锵然一滴甘泉乳。结亭三四五。曾相暖热携歌舞。细思量，古来寒士，不遇有时遇。'},
    {t:'归次汉中境上',a:'陆游〔宋代〕',c:'云栈屏山阅月游，马蹄初喜蹋扬州。\n地连秦雍川原壮，水下荆扬日夜流。\n遗虏孱孱宁远略，孤臣耿耿独私忧。\n良时恐作他年恨，大散关头又一秋。'},
    {t:'归国谣·双脸',a:'温庭筠〔唐代〕',c:'双脸，小凤战蓖金飐艳。舞衣无斜风敛，藕丝秋色染。\n锦帐绣帷斜掩，露珠清晓簟，粉心黄蕊花靥，黛眉山两点。'},
    {t:'归国遥·香玉',a:'温庭筠〔唐代〕',c:'香玉，翠凤宝钗垂簏簌，钿筐交胜金粟，越罗春水绿。\n画堂照帘残烛，梦馀更漏促。谢娘无限心曲，晓屏山断续。'},
    {t:'归家',a:'杜牧〔唐代〕',c:'稚子牵衣问，归来何太迟。\n共谁争岁月，赢得鬓边丝。'},
    {t:'归梦',a:'杜甫〔唐代〕',c:'道路时通塞，江山日寂寥。\n偷生唯一老，伐叛已三朝。\n雨急青枫暮，云深黑水遥。\n梦魂归未得，不用楚辞招。'},
    {t:'归鸟·其二',a:'陶渊明〔魏晋〕',c:'翼翼归鸟，载翔载飞。\n虽不怀游，见林情依。\n遇云颉颃，相鸣而归。\n遐路诚悠，性爱无遗。'},
    {t:'归鸟·其三',a:'陶渊明〔魏晋〕',c:'翼翼归鸟，驯林徘徊。\n岂思天路，欣及旧栖。\n虽无昔侣，众声每谐。\n日夕气清，悠然其怀。'},
    {t:'归鸟·其四',a:'陶渊明〔魏晋〕',c:'翼翼归鸟，戢羽寒条。\n游不旷林，宿则森标。\n晨风清兴，好音时交。\n矰缴奚施，已卷安劳！'},
    {t:'归鸟·其一',a:'陶渊明〔魏晋〕',c:'翼翼归鸟，晨去于林。\n远之八表，近憩云岑。\n和风不洽，翻翮求心。\n顾俦相鸣，景庇清阴。'},
    {t:'归去来·初过元宵三五',a:'柳永〔宋代〕',c:'初过元宵三五。慵困春情绪。灯月阑珊嬉游处。游人尽、厌欢聚。\n凭仗如花女。持杯谢、酒朋诗侣。馀酲更不禁香醑。歌筵罢、且归去。'},
    {t:'归去来·一夜狂风雨',a:'柳永〔宋代〕',c:'一夜狂风雨。花英坠、碎红无数。垂杨漫结黄金缕。尽春残、萦不住。\n蝶稀蜂散知何处。殢尊酒、转添愁绪。多情不惯相思苦。休惆怅、好归去。'},
    {t:'归去难·佳约人未知',a:'周邦彦〔宋代〕',c:'佳人约未知，背地伊先变。恶会称停事、看深浅。如今信我，委的论长远。好采无可怨，洎合教伊，因些事后分散。\n密意都休，待说先肠断。此恨除非是、天相念。坚心更守，未死终相见。多少闲磨难，到得其时、知他做甚头眼。'},
    {t:'归嵩山作',a:'王维〔唐代〕',c:'清川带长薄，车马去闲闲。\n流水如有意，暮禽相与还。\n荒城临古渡，落日满秋山。\n迢递嵩高下，归来且闭关。'},
    {t:'归田乐',a:'晏几道〔宋代〕',c:'试把花期数。便早有、感春情绪。看即梅花吐。愿花更不谢，春且长住。只恐花飞又春去。\n花开还不语。问此意、年年春还会否。绛唇青鬓，渐少花前语。对花又记得、旧曾游处。门外垂杨未飘絮。'},
    {t:'归田乐',a:'晏几道〔宋代〕',c:'拭把花期数，便早有、感春情绪。\n看即梅花吐，\n愿花更不谢，春且长住。\n只恐花飞又春去。\n花开还不语，\n问此意、年年春还会否。\n绛唇青鬓，渐少花前语。\n对花又记得、旧曾游处。\n门外垂杨未飘絮。'},
    {t:'归田乐引',a:'黄庭坚〔宋代〕',c:'对景还销瘦。被个人、把人调戏，我也心儿有。忆我又唤我，见我嗔我，天甚教人怎生受。\n看承幸厮勾。又是樽前眉峰皱。是人惊怪，冤我忒撋就。拚了又舍了，定是这回休了，及至相逢又依旧。'},
    {t:'归辋川作',a:'王维〔唐代〕',c:'谷口疏钟动，渔樵稍欲稀。\n悠然远山暮，独向白云归。\n菱蔓弱难定，杨花轻易飞。\n东皋春草色，惆怅掩柴扉。'},
    {t:'归信吟',a:'孟郊〔唐代〕',c:'泪墨洒为书，将寄万里亲。\n书去魂亦去，兀然空一身。'},
    {t:'归雁',a:'范仲淹〔宋代〕',c:'稻梁留不得，一一起江天。\n带雪南离楚，和春北入燕。\n依依前伴侣，历历旧山川。\n林叶程犹远，梅花信可传。\n子规啼到晓，鹦鹉锁经年。\n应羡冥冥者，东风羽翼全。'},
    {t:'归雁',a:'杜甫〔唐代〕',c:'东来万里客，乱定几年归？\n肠断江城雁，高高向北飞。'},
    {t:'归雁二首',a:'杜甫〔唐代〕',c:'万里衡阳雁，今年又北归。\n双双瞻客上，一一背人飞。\n云里相呼疾，沙边自宿稀。\n系书元浪语，愁寂故山薇。\n欲雪违胡地，先花别楚云。\n却过清渭影，高起洞庭群。\n塞北春阴暮，江南日色曛。\n伤弓流落羽，行断不堪闻。'},
    {t:'归燕',a:'杜牧〔唐代〕',c:'画堂歌舞喧喧地，社去社来人不看。\n长是江楼使君伴，黄昏犹待倚阑干。'},
    {t:'归燕诗',a:'张九龄〔唐代〕',c:'海燕虽微渺，乘春亦暂来。\n岂知泥滓贱，只见玉堂开。\n绣户时双入，华堂日几回。\n无心与物竞，鹰隼莫相猜。'},
    {t:'归园田居·其二',a:'陶渊明〔魏晋〕',c:'野外罕人事，穷巷寡轮鞅。\n白日掩荆扉，虚室绝尘想。\n时复墟曲中，披草共来往。\n相见无杂言，但道桑麻长。\n桑麻日已长，我土日已广。\n常恐霜霰至，零落同草莽。'},
    {t:'归园田居·其三',a:'陶渊明〔魏晋〕',c:'种豆南山下，草盛豆苗稀。\n晨兴理荒秽，带月荷锄归。\n道狭草木长，夕露沾我衣。\n衣沾不足惜，但使愿无违。'},
    {t:'归园田居·其四',a:'陶渊明〔魏晋〕',c:'久去山泽游，浪莽林野娱。\n试携间侄辈，披榛步荒墟。\n徘徊丘垄间，依依昔人居。\n井灶有遗处，桑焉残朽株。\n借问采薪者，此人皆焉如？\n薪者向我言，死没无复余。\n一世异朝市，此语真不虚。\n人生似幻化，终当归空无。'},
    {t:'归园田居·其五',a:'陶渊明〔魏晋〕',c:'怅恨独策还，崎岖历榛曲。\n山涧清且浅，可以濯吾足。\n漉我新熟酒，只鸡招近局。\n日入室中暗，荆薪代明烛。\n欢来苦夕短，已复至天旭。'},
    {t:'归园田居·其一',a:'陶渊明〔魏晋〕',c:'少无适俗韵，性本爱丘山。\n误落误网中，一去三十年。\n羁鸟恋旧林，池鱼思故渊。\n十荒南野际，守拙归园田。\n方宅十余亩，草屋八九间。\n榆柳荫后檐，桃李罗堂前。\n暧暧远人村，依依墟里烟。\n狗吠深巷中，鸡鸣桑树颠。\n户庭无误杂，虚室有余闲。\n久在樊笼里，复得返自然。'},
    {t:'归至郢中',a:'孟浩然〔唐代〕',c:'远游经海峤，返棹归山阿。日夕见乔木，乡关在伐柯。\n愁随江路尽，喜入郢门多。左右看桑土，依然即匪他。'},
    {t:'龟背戏',a:'柳宗元〔唐代〕',c:'长安新技出宫掖，喧喧初遍王龟宅。玉盘滴沥黄金钱，\n皎如文龟丽秋天。八方定位开神卦，六卑离离齐上下。\n投变转动玄机卑，星流霞破相参差。四分五裂势未已，\n出无入有谁能知。乍惊散漫无处所，须臾罗列已如故。\n徒言万事有盈虚，终朝一掷知胜负。修门象棋不复贵，\n魏宫妆奁世所弃。岂如瑞质耀奇文，愿持千岁寿吾君。\n庙堂巾笥非余慕，钱刀儿女徒纷纷。'},
    {t:'龟山',a:'苏轼〔宋代〕',c:'我生飘荡去何求，再过龟山岁五周。\n身行万里半天下，僧卧一庵初白头。\n地隔中原劳北望，潮连沧海欲东游。\n元嘉旧事无人记，故垒摧颓今在不。'},
    {t:'闺情',a:'孟浩然〔唐代〕',c:'一别隔炎凉，君衣忘短长。\n裁缝无处等，以意忖情量。\n畏瘦疑伤窄，防寒更厚装。\n半啼封裹了，知欲寄谁将。'},
    {t:'闺情',a:'高适〔唐代〕',c:'相随万里泣胡风，疋偶将期一世终。早知中路生离别，悔不深怜沙碛中。'},
    {t:'闺情',a:'李商隐〔唐代〕',c:'红露花房白蜜脾，黄蜂紫蝶两参差。\n春窗一觉风流梦，却是同衾不得知。'},
    {t:'闺情其二闺情',a:'高适〔唐代〕',c:'不须推道委人猜，只是君心自不开。今夜闺门凭莫闭，孤魂拟向梦中来。'},
    {t:'闺情其三闺情',a:'高适〔唐代〕',c:'祗今桃李正堪攀，所恨枝高引手难。原君垂下方便叶，袖卷将归看复看。'},
    {t:'闺怨',a:'王昌龄〔唐代〕',c:'闺中少妇不知愁，春日凝妆上翠楼。\n忽见陌头杨柳色，悔教夫婿觅封侯。'},
    {t:'癸卯岁十二月中作与从弟敬远',a:'陶渊明〔魏晋〕',c:'寝迹衡门下，邈与世相绝。\n顾盼风谁知，荆扉昼常闭。\n凄凄岁暮风，翳翳经日雪。\n倾耳无希声，在屡皓已洁。\n劲气侵襟袖，箪瓢谢屡设。\n萧索空宇中，了无一可悦！\n历览千载书，时时见遗烈。\n高操非所攀，谬得固穷节。\n平津苟不由，栖迟讵为拙！\n寄意一言外，兹契谁能别？'},
    {t:'癸卯岁始春怀古田舍二首',a:'陶渊明〔魏晋〕',c:'在昔闻南亩，当年竟未践。\n屡空驾有人，春兴岂自免。\n夙晨装吾驾，启涂情己缅。\n鸟哢欢新节，泠人送馀善。\n寒竹被荒蹊，地为罕人远；\n是以植杖翁，悠然不复返。\n即理愧通识，所保讵乃浅。\n先师有遗训，忧道不忧贫。\n瞻望邈难逮，转欲志长勤。\n秉耒欢时务，解颜劝农人。\n平畴交远人，良苗亦怀新。\n虽未量岁功，即事多所欣。\n耕种有时息，行者无问津。\n日入相与归，壶浆劳近邻。\n长吟掩柴门，聊为陇亩民。'},
    {t:'癸酉岁元日中书致斋感事',a:'晏殊〔宋代〕',c:'一叶春王拆瑞筇，八斋西省夕闻浓。\n多年不宿金闺署，半夜再闻长乐钟。\n却展旧编探史汉，更惭高步接夔龙。\n十思三省无荒豫。千载亨辰岂易逢。'},
    {t:'贵公子夜阑曲',a:'李贺〔唐代〕',c:'袅袅沉水烟，乌啼夜阑景。\n曲沼芙蓉波，腰围白玉冷。'},
    {t:'贵卿',a:'文天祥〔宋代〕',c:'天高并地迥，与子独牢愁。\n初作燕齐客，今为淮海游。\n半生谁俯仰，一死共沉浮。\n我视君年长，相看比惠州。'},
    {t:'贵游行',a:'韦应物〔唐代〕',c:'汉帝外家子，恩泽少封侯。垂杨拂白马，晓日上青楼。\n上有颜如玉，高情世无俦。轻裾含碧烟，窈窕似云浮。\n良时无还景，促节为我讴。忽闻艳阳曲，四坐亦已柔。\n宾友仰称叹，一生何所求。平明击钟食，入夜乐未休。\n风雨愆岁候，兵戎横九州。焉知坐上客，草草心所忧。'},
    {t:'贵主征行乐',a:'李贺〔唐代〕',c:'奚骑黄铜连锁甲，罗旗香干金画叶。\n中军留醉河阳城，娇嘶紫燕踏花行。\n春营骑将如红玉，走马捎鞭上空绿。\n女垣素月角咿咿，牙帐未开分锦衣。'},
    {t:'桂林',a:'李商隐〔唐代〕',c:'城窄山将压，江宽地共浮。\n东南通绝域，西北有高楼。\n神护青枫岸，龙移白石湫。\n殊乡竟何祷，箫鼓不曾休。'},
    {t:'桂林路中作',a:'李商隐〔唐代〕',c:'地暖无秋色，江晴有暮晖。\n空馀蝉嘒嘒，犹向客依依。\n村小犬相护，沙平僧独归。\n欲成西北望，又见鹧鸪飞。'},
    {t:'桂源铺',a:'杨万里〔宋代〕',c:'万山不许一溪奔，拦得溪声日夜喧。\n到得前头山脚尽，堂堂溪水出前村。'},
    {t:'桂枝香',a:'张炎〔宋代〕',c:'甚，余歌美成词。\n琴书半室。向桂露偶然，一见秋色。老树香迟，清露缀花疑滴。山翁翻情如泥醉，情生平、无此狂逸。晋人游处，幽情付与，酒尊吟笔。\n任萧散、披襟岸帻。叹千古犹今，休问何夕。发短霜浓，却恐浩歌消得。明年野客重来此，探枝头、几分消息。望西楼远，西湖更远，也寻梅驿。'},
    {t:'桂枝香·金陵怀古',a:'王安石〔宋代〕',c:'登临送目，正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风，酒旗斜矗。彩舟云淡，星河鹭起，画图难足。\n念往昔，繁华竞逐。叹门外楼头，悲恨相续。千古凭高对此，谩嗟荣辱。六朝旧事随流水，但寒烟衰草凝绿。至今商女，时时犹唱，后庭遗曲。'},
    {t:'桂枝香·送宾月叶公东归',a:'张炎〔宋代〕',c:'晴江迥阔。又客里天涯，还叹轻别。万里潮生一棹，柳丝犹结。荷衣好向山中补，共飘零、几年霜雪。赋归何晚，依依径菊，弄香时节。\n料此去、清游未歇。引一片秋声，都付吟箧。落叶长安，古意对人休说。相思只在相留处，有孤芳、可怜空折。旧怀难写，山阳怨笛，夜凉吹月。'},
    {t:'桧迳晓步二首',a:'杨万里〔宋代〕',c:'雨歇林间凉自生，风穿迳里晓逾清。\n意行偶到无人处，惊起山禽我亦惊。'},
    {t:'郭北寻徐主簿别业',a:'皎然〔唐代〕',c:'近依城北住，幽远少人知。积雪行深巷，闲云绕古篱。\n竹花冬更发，橙实晚仍垂。还共岩中鹤，今朝下渌池。'},
    {t:'郭处士击瓯歌',a:'温庭筠〔唐代〕',c:'佶栗金虬石潭古，勺陂潋滟幽铃语。湘君宝马上神云，\n碎佩丛铃满烟雨。吾闻三十六宫花破破，软风吹春星斗稀。\n玉晨冷磬破昏梦，天露未干香著衣。兰钗委坠垂云发，\n小响丁当逐回雪。晴碧烟滋重叠山，罗屏半掩桃花月。\n太平天子驻云车，龙炉勃郁双蟠拏。宫中近臣抱扇立，\n侍女低鬟落翠花。乱珠触续正跳荡，倾头不觉金乌斜。\n我亦为君长叹息，缄情远寄愁无色。莫沾香梦绿杨丝。\n千里春风正无力。'},
    {t:'郭郎儿近拍·帝里',a:'柳永〔宋代〕',c:'帝里。闲居小曲深坊，庭院沉沉朱户闭。新霁。畏景天气。薰风帘幕无人，永昼厌厌如度岁。\n愁悴。枕簟微凉，睡久辗转慵起。砚席尘生，新诗小阕，等闲都尽废。这些儿、寂寞情怀，何事新来常恁地。'},
    {t:'郭隗',a:'陈子昂〔唐代〕',c:'逢时独为贵，历代非无才。\n隗君亦何幸，遂起黄金台。'},
    {t:'国香',a:'张炎〔宋代〕',c:'沈梅娇，杭妓也、忽于京都见之。把酒相劳苦，犹能歌周清真意难忘、台城路二曲，因嘱余记其事。词成，以罗帕书之。\n莺柳烟堤。记未吟青子，曾比红儿。娴娇弄春微透，鬟翠双垂。不道留仙不住，便无梦、吹到南枝。相看两流落，掩面凝羞，怕说当时。\n凄凉歌楚调，袅余音不放，一朵云飞。丁香枝上，几度款语深期。拜了花梢淡月，最难忘、弄影牵衣。无端动人处，过了黄昏，犹道休归。'},
    {t:'国香·赋兰',a:'张炎〔宋代〕',c:'空谷幽人。曳冰簪雾带，古色生春。结根未同萧艾，独抱孤贞。自分生涯淡薄，隐蓬蒿、甘老山林。风烟伴憔悴，冷落吴宫，草暗花深。\n霁痕消蕙雪，向崖阴饮露，应是知心。所思何处，愁满楚水湘云。肯信遗芳千古，尚依依、泽畔行吟。香痕已成梦，短操谁弹，月冷瑶琴。'},
    {t:'虢国夫人夜游图',a:'苏轼〔宋代〕',c:'佳人自鞚玉花骢，翩如惊燕蹋入龙。\n金鞭争道宝钗落，何人先入明光宫。\n宫中羯鼓催花柳，玉人弦索花人手。\n坐中八姨真贵人，走马来看不动尘。\n明眸皓齿谁复见，只有丹青余泪痕。\n人间俯仰成今古，吴公台下雷塘路。\n当时亦笑张丽华，不知门外韩擒虎。'},
    {t:'虢州后亭送李判官使赴晋绛',a:'岑参〔唐代〕',c:'西原驿路挂城头，客散江亭雨未收。\n君去试看汾水上，白云犹似汉时秋。'},
    {t:'虢州送天平何丞入京市马',a:'岑参〔唐代〕',c:'关树晚苍苍，长安近夕阳。\n回风醒别酒，细雨湿行装。\n习战边尘黑，防秋塞草黄。\n知君市骏马，不是学燕王。'},
    {t:'虢州卧疾，喜刘判官相过水亭',a:'岑参〔唐代〕',c:'卧疾尝晏起，朝来头未梳。见君胜服药，清话病能除。\n低柳共系马，小池堪钓鱼。观棋不觉暝，月出水亭初。'},
    {t:'过霸东石桥，桐花尽落',a:'杨万里〔宋代〕',c:'老去能逢几个春，今年春事不关人。\n红千紫百何曾梦，厌尾桐花也作尘。'},
    {t:'过百家渡四绝句',a:'杨万里〔宋代〕',c:'出得城来事事幽，涉湘半济值渔舟。\n也知渔父趁鱼急，翻著春衫不裹头。\n园花落尽路花开，白白红红各自媒。\n莫道早行奇绝处，四方八面野香来。\n柳子祠前春已残，新晴特地著春寒。\n疏篱不与花为护，只为蜘蛛作网竿。\n一晴一雨路乾湿，半淡半浓山迭重。\n远草坪中见牛背，新秧疏处有人踪。'},
    {t:'过宝应县新开湖十首·其八',a:'杨万里〔宋代〕',c:'天上云烟压水来，湖中波浪打云回。\n中间不是平林树，水色天容拆不开。'},
    {t:'过陈琳墓',a:'温庭筠〔唐代〕',c:'曾于青史见遗文，今日飘蓬过此坟。\n词客有灵应识我，霸才无主始怜君。\n石麟埋没藏春草，铜雀荒凉对暮云。\n莫怪临风倍惆怅，欲将书剑学从军。'},
    {t:'过陈州上晏相公',a:'范仲淹〔宋代〕',c:'曩由清举玉宸知，今觉光荣冠一时。\n曾入黄扉陪国论，重求绛帐就师资。\n谈文讲道浑无倦，养浩存真绝不衰。\n独愧铸颜恩未报，捧觞为寿献声诗。'},
    {t:'过乘如禅师萧居士嵩丘兰若',a:'王维〔唐代〕',c:'无着天亲弟与兄，嵩丘兰若一林晴。\n食随鸣磬巢乌下，行踏空林落叶声。\n迸水定侵香案湿，雨花应共石床平。\n深洞长松何所有，俨然天竺古先生。'},
    {t:'过楚宫',a:'李商隐〔唐代〕',c:'巫峡迢迢旧楚宫，至今云雨暗丹枫。\n微生尽恋人间乐，只有襄王忆梦中。'},
    {t:'过崔驸马山池',a:'王维〔唐代〕',c:'画楼吹笛妓，金碗酒家胡。\n锦石称贞女，青松学大夫。\n脱貂贳桂醑，射雁与山厨。\n闻道高阳会，愚公谷正愚。'},
    {t:'过东都别乐天二首',a:'元稹〔唐代〕',c:'君应怪我留连久，我欲与君辞君难。\n白头徒侣渐稀少，明日恐君无此欢。\n自识君来三度君，这回白尽老髭须。\n恋君不去君须会，知得后回相见无。'},
    {t:'过方城寻七叔祖旧题',a:'黄庭坚〔宋代〕',c:'壮气南山若可排，今为野马与尘埃。\n清谈落笔一万字，白眼举觞三百杯。\n周鼎不酬康瓠价，豫章元是栋梁材。\n眷然挥涕方城路，冠盖当年向此来。'},
    {t:'过分水岭',a:'温庭筠〔唐代〕',c:'溪水无情似有情，入山三日得同行。\n岭头便是分头处，惜别潺湲一夜声。'},
    {t:'过分水岭·一作东岭',a:'孟郊〔唐代〕',c:'山壮马力短，马行石齿中。十步九举辔，回环失西东。\n溪水变为雨，悬崖阴濛濛。客衣飘飖秋，葛花零落风。\n白日舍我没，征途忽然穷。'},
    {t:'过福禅师兰若',a:'王维〔唐代〕',c:'岩壑转微径，云林隐法堂。\n羽人飞奏乐，天女跪焚香。\n竹外峰偏曙，藤阴水更凉。\n欲知禅坐久，行路长春芳。'},
    {t:'过感化寺昙兴上人山院',a:'王维〔唐代〕',c:'暮持筇竹杖，相待虎溪头。\n催客闻山响，归房逐水流。\n野花丛发好，谷鸟一声幽。\n夜坐空林寂，松风直似秋。'},
    {t:'过缑山王处士黑石谷隐居',a:'岑参〔唐代〕',c:'旧居缑山下，偏识缑山云。处士久不还，见云如见君。\n别来逾十秋，兵马日纷纷。青谿开战场，黑谷屯行军。\n遂令巢由辈，远逐麋鹿群。独有南涧水，潺湲如昔闻。'},
    {t:'过故人庄',a:'孟浩然〔唐代〕',c:'故人具鸡黍，邀我至田家。\n绿树村边合，青山郭外斜。\n开轩面场圃，把酒话桑麻。\n待到重阳日，还来就菊花。'},
    {t:'过广陵值早春',a:'黄庭坚〔宋代〕',c:'春风十里珠帘捲，彷佛三生杜牧之。红药梢头初茧栗，扬州风动鬓成丝。'},
    {t:'过衡山见新花开却寄弟',a:'柳宗元〔唐代〕',c:'故国名园久别离，今朝楚树发南枝。\n晴天归路好相逐，正是峰前回雁时。'},
    {t:'过鸿沟',a:'韩愈〔唐代〕',c:'龙疲虎困割川原，亿万苍生性命存。\n谁劝君王回马首，真成一掷赌乾坤。'},
    {t:'过华夫书屋',a:'晏殊〔宋代〕',c:'西齐辉赫亘山隅，嘉致清风世莫如。\n乡党名流依绛帐，烟萝幽境似仙居。\n趋庭子弟皆攀桂，弹铗宾朋总食鱼。\n汗简传经亚邹鲁，粉牌留咏尽严徐。\n杯盘互进先生馔，门巷应停长者车。\n坟籍岂惟精四部，弦歌常见习三馀。\n玳簪珠履延豪士，缥帙牙签刊赐书。\n碧沼暮凉浮菡萏，纱窗秋静漏蟾蜍。\n间庭潇洒移泉石，华表峥嵘冠里闾。\n我恨羁游在芸阁，不陪诸彦曳长裾。'},
    {t:'过华清宫',a:'李贺〔唐代〕',c:'春月夜啼鸦，宫帘隔御花。\n云生朱络暗，石断紫钱斜。\n玉碗盛残露，银灯点旧纱。\n蜀王无近信，泉上有芹芽。'},
    {t:'过华清宫绝句三首',a:'杜牧〔唐代〕',c:'长安回望绣成堆，山顶千门次第开。\n一骑红尘妃子笑，无人知是荔枝来。\n新丰绿树起黄埃，数骑渔阳探使回。\n霓裳一曲千峰上，舞破中原始下来。\n万国笙歌醉太平，倚天楼殿月分明。\n云中乱拍禄山舞，风过重峦下笑声。'},
    {t:'过华阴',a:'王昌龄〔唐代〕',c:'云起太华山，云山互明灭。东峰始含景，了了见松雪。\n羁人感幽栖，窅映转奇绝。欣然忘所疲，永望吟不辍。\n信宿百馀里，出关玩新月。何意昨来心，遇物遂迁别。\n人生屡如此，何以肆愉悦。'},
    {t:'过淮河宿阚石有感',a:'文天祥〔宋代〕',c:'北征垂半年，依依只南土。\n今晨家淮河，始觉非故宇。\n江乡已无家，三年一羁旅。\n龙翔在何方，乃念妻子所。\n昔也无柰何，忽已置念虑。\n今行日已近，使念泪如雨。\n念为纲常谋，有身不得顾。\n妻兮莫望夫，子兮莫望父。\n天长与地久，此恨极千古。\n来生业缘在，骨肉当如故。'},
    {t:'过家',a:'黄庭坚〔宋代〕',c:'络纬声转急，田车寒不运。\n儿时保种柳，上与云雨近。\n舍傍旧佣保，少换老欲尽。\n宰木郁苍苍，田婚变畦畛。\n招延屈父党，劳问走婚亲。\n归来翻作客，顾影良自哂。\n一生萍托水，万事雪侵鬓。\n夜阑风陨霜，乾叶落成阵。\n灯花何故喜，大是报书信。\n亲年当喜惧，儿齿欲毁龀。\n系船三百里，去梦无一寸。'},
    {t:'过贾岛野居',a:'张籍〔唐代〕',c:'青门坊外住，行坐见南山。\n此地去人远，知君终日闲。\n蛙声篱落下，草色户庭间。\n好是经过处，唯愁暮独还。'},
    {t:'过涧歇近·淮楚',a:'柳永〔宋代〕',c:'淮楚。旷望极，千里火云烧空，尽日西郊无雨。厌行旅。数幅轻帆旋落，舣棹蒹葭浦。避畏景，两两舟人夜深语。\n此际争可，便恁奔名竞利去。九衢尘里，衣冠冒炎暑。回首江乡，月观风亭，水边石上，幸有散发披襟处。'},
    {t:'过涧歇近·酒醒',a:'柳永〔宋代〕',c:'酒醒。梦才觉，小阁香炭成煤，洞户银蟾移影。人寂静。夜永清寒，翠瓦霜凝，疏帘风动。漏声隐隐，飘来转愁听。\n怎向心绪，近日厌厌长似病。凤楼咫尺，佳期杳无定。展转无眠，粲枕冰冷。香虬烟断，是谁与把重衾整。'},
    {t:'过景空寺故融公兰若',a:'孟浩然〔唐代〕',c:'池上青莲宇，林间白马泉。\n故人成异物，过客独潸然。\n既礼新松塔，还寻旧石筵。\n平生竹如意，犹挂草堂前。'},
    {t:'过酒泉忆杜陵别业',a:'岑参〔唐代〕',c:'昨夜宿祁连，今朝过酒泉。\n黄沙西际海，白草北连天。\n愁里难消日，归期尚隔年。\n阳关万里梦，知处杜陵田。'},
    {t:'过骊山作',a:'杜牧〔唐代〕',c:'始皇东游出周鼎，刘项纵观皆引颈。\n削平天下实辛勤，却为道傍穷百姓。\n黔首不愚尔益愚，千里函关囚独夫。\n牧童火入九泉底，烧作灰时犹未枯。'},
    {t:'过零丁洋',a:'文天祥〔宋代〕',c:'辛苦遭逢起一经，干戈寥落四周星。\n山河破碎风飘絮，身世浮沉雨打萍。\n惶恐滩头说惶恐，零丁洋里叹零丁。\n人生自古谁无死？留取丹心照汗青。'},
    {t:'过卢明府有赠',a:'高适〔唐代〕',c:'良吏不易得，古人今可传。静然风诸己，以此知其贤。\n我行挹高风，羡尔兼少年。胸怀豁清夜，史郊如流泉。\n明日复行春，逶迤出郊坛。登高见百里，桑野郁芊芊。\n时平俯鹊巢，岁熟多人烟。奸猾唯闭户，逃亡归种田。\n回轩自郭南，老幼满马前。皆贺蚕农至，而无徭役牵。\n君观黎庶心，抚之诚万全。何幸逢大道，愿言烹小鲜。\n能奏明廷主，一试武城弦。'},
    {t:'过卢四员外宅看饭僧共题七韵',a:'王维〔唐代〕',c:'三贤异七贤，青眼慕青莲。\n乞饭从香积，裁衣学水田。\n上人飞锡杖，檀越施金钱。\n趺坐檐前日，焚香竹下烟。\n寒空法云地，秋色净居天。\n身逐因缘法，心过次第禅。\n不须愁日暮，自有一灯然。'},
    {t:'过彭泽',a:'孟郊〔唐代〕',c:'扬帆过彭泽，舟人讶叹息。不见种柳人，霜风空寂历。'},
    {t:'过平舆怀李子先时在并州',a:'黄庭坚〔宋代〕',c:'前日幽人佐吏曹，我行堤草认青袍。\n心随汝水春波动，兴与并门夜月高。\n世上岂无千里马，人中难得九方皋。\n酒船鱼网归来是，花落故溪深一篙。'},
    {t:'过碛',a:'岑参〔唐代〕',c:'黄沙碛里客行迷，四望云天直下低。\n为言地尽天还尽，行到安西更向西。'},
    {t:'过秦楼·大石',a:'周邦彦〔宋代〕',c:'水浴清蟾，叶喧凉吹，巷陌马声初断。闲依露井，笑扑流萤，惹破画罗轻扇。人静夜久凭阑，愁不归眠，立残更箭。叹年华一瞬，人今千里，梦沉书远。\n空见说、鬓怯琼梳，容销金镜，渐懒趁时匀染。梅风地溽，虹雨苔滋，一架舞红都变。谁信无聊为伊，才减江淹，情伤荀倩。但明河影下，还看稀星数点。'},
    {t:'过勤政楼',a:'杜牧〔唐代〕',c:'千秋佳节名空在，承露丝囊世已无。\n唯有紫苔偏称意，年年因雨上金铺。'},
    {t:'过沙头三首其二',a:'杨万里〔宋代〕',c:'过了沙头渐有村，地平江阔气清温。暗潮已到无人会，只有篙师识水痕。'},
    {t:'过上湖岭望招贤江南北山',a:'杨万里〔宋代〕',c:'岭下看山似伏涛，见人上岭旋争豪。\n一登一陟一回顾，我脚高时他更高。'},
    {t:'过邵伯镇',a:'文天祥〔宋代〕',c:'今朝车马地，昔日战争场。\n我有扬州鹤，谁存邵伯棠。\n一湾流水小，数亩故城荒。\n回首江南路，青山断夕阳。'},
    {t:'过沈居士山居哭之',a:'王维〔唐代〕',c:'杨朱来此哭，桑扈返于真。\n独自成千古，依然旧四邻。\n闲檐喧鸟鹊，故榻满埃尘。\n曙月孤莺啭，空山五柳春。\n野花愁对客，泉水咽迎人。\n善卷明时隐，黔娄在日贫。\n逝川嗟尔命，丘井叹吾身。\n前后徒言隔，相悲讵几晨。'},
    {t:'过始皇墓',a:'王维〔唐代〕',c:'古墓成苍岭，幽宫象紫台。\n星辰七曜隔，河汉九泉开。\n有海人宁渡，无春雁不回。\n更闻松韵切，疑是大夫哀。'},
    {t:'过始兴江口感怀',a:'韩愈〔唐代〕',c:'忆作儿童随伯氏，南来今只一身存。\n目前百口还相逐，旧事无人可共论。'},
    {t:'过松源晨炊漆公店',a:'杨万里〔宋代〕',c:'莫言下岭便无难，赚得行人错万欢。\n政入万山围子里，一山放出一山拦。'},
    {t:'过宋员外之问旧庄',a:'杜甫〔唐代〕',c:'宋公旧池馆，零落首阳阿。\n枉道祗从入，吟诗许更过。\n淹留问耆老，寂寞向山河。\n更识将军树，悲风日暮多。'},
    {t:'过太清宫',a:'范仲淹〔宋代〕',c:'丑石危松半绿萝，函关真相玉鹾峨。\n谁言仙道求难至，自愧阴功积未多。\n渺渺云霞开绛节，雝雝鸾凤答空歌。\n几时身退琼坛畔，荣利匆匆奈老何。'},
    {t:'过潼关',a:'温庭筠〔唐代〕',c:'地形盘屈带河流，景气澄明是胜游。十里晓鸡关树暗，\n一行寒雁陇云愁。片时无事溪泉好，尽日凝眸岳色秋。\n麈尾角巾应旷望，更嗟芳霭隔秦楼。'},
    {t:'过土山寨',a:'黄庭坚〔宋代〕',c:'南风日日纵篙撑，时喜北风将我行。\n汤饼一杯银线乱，蒌蒿数筯玉簪横。'},
    {t:'过魏文贞公宅·一作题魏文贞',a:'杜牧〔唐代〕',c:'蟪蛄宁与雪霜期，贤哲难教俗士知。\n可怜贞观太平后，天且不留封德彝。'},
    {t:'过吴景帝陵',a:'温庭筠〔唐代〕',c:'王气销来水淼茫，岂能才与命相妨。\n虚开直渎三千里，青盖何曾到洛阳。'},
    {t:'过五丈原',a:'温庭筠〔唐代〕',c:'铁马云雕久绝尘，柳营高压汉营春。\n天清杀气屯关右，夜半妖星照渭滨。\n下国卧龙空寤主，中原逐鹿不由人。\n象床锦帐无言语，从此谯周是老臣。'},
    {t:'过西堡塞北',a:'温庭筠〔唐代〕',c:'浅草干河阔，丛棘废城高。白马犀匕首，黑裘金佩刀。\n霜清彻兔目，风急吹雕毛。一经何用厄，日暮涕沾袍。'},
    {t:'过香积寺',a:'王维〔唐代〕',c:'不知香积寺，数里入云峰。\n古木无人径，深山何处钟。\n泉声咽危石，日色冷青松。\n薄暮空潭曲，安禅制毒龙。'},
    {t:'过雪桥琉璃桥',a:'文天祥〔宋代〕',c:'小桥度雪度琉璃，更有清霜滑马踪。\n游子衣裳如铁冷，残星荒店野鸡啼。'},
    {t:'过燕支寄杜位',a:'岑参〔唐代〕',c:'燕支山西酒泉道，北风吹沙卷白草。\n长安遥在日光边，忆君不见令人老。'},
    {t:'过扬子江二首·其二',a:'杨万里〔宋代〕',c:'天将天堑护吴天，不数殽函百塔关。\n万里银河泻琼海，一双玉塔表金山。\n旌旗隔岸淮南近，鼓角吹霜塞北闲。\n多谢江神风色好，沧波千顷片时间。'},
    {t:'过扬子江二首·其一',a:'杨万里〔宋代〕',c:'只有清霜冻太空，更无半点荻花风。\n天开云雾东南碧，日射波涛上下红。\n千载英雄鸿去外，六朝形胜雪晴中。\n携瓶自汲江心水，要试煎茶第一功。'},
    {t:'过扬子江心',a:'文天祥〔宋代〕',c:'渺渺乘风出海门，一行淡水带潮浑。\n长江尽处还如此，何日岷山看发源。'},
    {t:'过杨村',a:'杨万里〔宋代〕',c:'石桥两畔好人烟，匹似诸村别一川。\n杨柳荫中新酒店，葡萄架下小渔船。\n红红白白花临水，碧碧黄黄麦际天。\n政尔清和还在道，为谁辛苦不归田？'},
    {t:'过伊仆射旧宅',a:'李商隐〔唐代〕',c:'朱邸方酬力战功，华筵俄叹逝波穷。\n回廊檐断燕飞去，小阁尘凝人语空。\n幽泪欲干残菊露，馀香犹入败荷风。\n何能更涉泷江去，独立寒流吊楚宫。'},
    {t:'过馀杭白塔寺',a:'范仲淹〔宋代〕',c:'登临江上寺，迁客特依依。\n远水欲无际，孤舟曾未归。\n乱峰藏好处，幽鹭得闲飞。\n多少天真趣，遥心结翠微。'},
    {t:'过元家履信宅',a:'白居易〔唐代〕',c:'鸡犬丧家分散后，林园失主寂寥时。\n落花不语空辞树，流水无情自入池。\n风荡宴船初破漏，雨淋歌阁欲倾欹。\n前庭后院伤心事，唯是春风秋月知。'},
    {t:'过长安醉别资政郑侍郎',a:'范仲淹〔宋代〕',c:'乡关交复亲，把酒且逡巡。\n共上青云路，相看白发人。\n有为须报国，无事即颐神。\n故素几云在，风音莫厌频。'},
    {t:'过招贤渡档四首',a:'杨万里〔宋代〕',c:'一江故作两江分，立杀呼船隔岸人。\n柳上青虫宁许劣，垂丝到地却回身。'},
    {t:'过昭国里故第',a:'韦应物〔唐代〕',c:'不复见故人，一来过故宅。物变合景暄，心伤觉时寂。\n池荒野筠合，庭绿幽草积。风散花意谢，鸟念山光夕。\n宿昔方同赏，讵合今念昔。缄室在东厢，遗器不忍觌。\n柔翰全分意，芳巾尚染泽。残工委筐箧，馀素经刀尺。\n收此念我家，将念复愁惕。永绝携手欢，空存旧行迹。\n冥冥独无语，杳杳将何适。唯思今古同，时缓伤与戚。'},
    {t:'过左伯桃羊角哀墓',a:'周邦彦〔宋代〕',c:'古交久沦丧，末世尤反覆。\n谷风左焚轮，黄鸟譬伐木。\n永怀羊与左，重义逾血属。\n客行干楚王，冬死无斗粟。\n倾粮活一士，誓不俱死辱。\n风云为惨变，鸟兽同踯躅。\n角哀器前途，伯桃槁空谷。\n终乘大夫车，千骑下棺椟。\n子长何所疑，旧史刊不录。\n独行贵苟难，义侠轻杀戮。\n虽云匪中制，要可兴薄俗。\n荒坟邻万鬼，溘死皆碌碌。\n何事荆将军，操戈相窘逐。'},
    {t:'还东山洛上作',a:'岑参〔唐代〕',c:'春流急不浅，归枻去何迟。愁客叶舟里，夕阳花水时。\n云晴开螮蝀，棹发起鸬鹚。莫道东山远，衡门在梦思。'},
    {t:'还都',a:'陆游〔宋代〕',c:'平生薄名宦，所愿得早休。\n奔走三十年，镜中霜鬓秋。\n归踏长安道，恍然皆旧游。\n处处见题名，始惊岁月遒。\n西湖隔城门，放浪输白鸥。\n当时见种柳，已足系巨舟。\n挂冠当自决，安用从人谋。\n勿以有限身，常供无尽愁。'},
    {t:'还高冠潭口留别舍弟',a:'岑参〔唐代〕',c:'昨日山有信，只今耕种时。\n遥传杜陵叟，怪我还山迟。\n独向潭上酌，无人林下期。\n东谿忆汝处，闲卧对鸬鹚。'},
    {t:'还京乐·禁烟近',a:'周邦彦〔宋代〕',c:'禁烟近，触处浮香秀色相料理。费泥花时候，奈何客里，光阴虚费。望箭波无际，迎风漾日黄云到。任去远，中有万点，相思清泪。\n到长淮底，过当时楼下，殷勤为说，春来羁旅况味。堪嗟误约乖期，向天涯、自看桃李。想而今，应恨墨盈笺，愁妆照水。怎得青鸾翼，飞归教见憔悴。'},
    {t:'还京乐·送陈行之归吴',a:'张炎〔宋代〕',c:'醉吟处。多是琴尊，竟日松下语。有笔床茶灶，瘦筇相引，逢花须住。正翠阴迷路。年光荏苒成孤旅。等趁燕樯，休忘了、玄都前度。\n渐烟波远，怕五湖凄冷，佳人袖薄，修竹依依日暮。知他甚处重逢，便匆匆、背潮归去。莫因循、误了幽期，应孤旧雨。伫立山风晚，月明摇碎江树。'},
    {t:'还旧居',a:'陶渊明〔魏晋〕',c:'畴昔家上京，六载去还归。\n今日始复来，恻怆多所悲。\n阡陌不移旧，邑屋或时非。\n履历周故居，邻老罕复遗，\n步步寻往迹，有处特依依。\n流幻百年中，寒暑日相推。\n常恐大化尽，气力不及衰。\n拨置且莫念，一觞聊可挥。'},
    {t:'还山贻湛法师',a:'孟浩然〔唐代〕',c:'幼闻无生理，常欲观此身。心迹壑兼遂，崎岖多在尘。\n晚途归旧壑，偶与支公邻。导以微妙法，结转清净因。\n烦恼业顿舍，山林情转殷。朝来问疑义，夕话得清真。\n墨妙称古绝，词华惊世人。禅房闭虚静，花药连冬春。\n平石藉琴砚，落泉洒衣巾。欲知冥灭意，朝夕海鸥驯。'},
    {t:'还司即事',a:'文天祥〔宋代〕',c:'幙燕方如寄，屠羊忽复旋。\n霜枝空独立，雪窖已三迁。\n漂泊知何所，逍遥付自然。\n庭空谁共语，拄颊望青天。\n秋声满南国，一叶此飘蓬。\n墙外千门迥，庭皋四壁空。\n谁家驴吼月，隔巷犬嗥风。\n灯暗人无寐，沉沉夜正中。'},
    {t:'还狱',a:'文天祥〔宋代〕',c:'人情感故物，百年多离忧。\n桑下住三宿，应者犹迟留。\n矧兹方丈室，屏居二春秋。\n夜眠与昼坐，隤乎安楚囚。\n自罹大雨水，圜土俱汤舟。\n此身委传舍，迁徒无定谋。\n去之已旬月，宫室重绸缪。\n今夕果何夕，复此搔白头。\n恍如流浪人，一旦归旧游。\n故家不可复，故国已成丘。\n对此重回首，汪然涕泗流。\n人生如空花，随风任飘浮。'},
    {t:'还自广陵',a:'秦观〔宋代〕',c:'天寒水鸟自相依，十百为群戏落晖。\n过尽行人都不起，忽闻水响一齐飞。'},
    {t:'还自广陵四首',a:'秦观〔宋代〕',c:'南北悠悠三十年，谢公遗埭故依然。\n欲论旧事无人共，卧听锺鱼古寺边。'},
    {t:'还自会稽歌',a:'李贺〔唐代〕',c:'庾肩吾于梁时，尝作宫体谣引，先应和皇子。及国势沦败，肩吾先潜难会稽，后始还家。仆意其会有遗文，今无得焉，故作还自会稽歌先补其悲。\n野粉椒壁黄，湿萤满梁殿。\n台城应教人，秋衾梦铜辇。\n吴霜点归鬓，身与塘蒲晚。\n脉脉辞金鱼，羁臣守迍贱。'},
    {t:'海客',a:'李商隐〔唐代〕',c:'海客乘槎上紫氛，星娥罢织一相闻。\n只应不惮牵牛妒，聊用支机石赠君。'},
    {t:'海榴',a:'温庭筠〔唐代〕',c:'海榴开似火，先解报春风。叶乱裁笺绿，花宜插鬓红。\n蜡珠攒作蒂，缃彩剪成丛。郑驿多归思，相期一笑同。'},
    {t:'海上',a:'文天祥〔宋代〕',c:'天边青鸟逝，海上白鸥驯。\n王济非痴叔，陶潜岂醉人。\n得官须报国，可隐即逃秦。\n身事盖棺定，挑灯看剑频。'},
    {t:'海上',a:'李商隐〔唐代〕',c:'石桥东望海连天，徐福空来不得仙。\n直遣麻姑与搔背，可能留命待桑田。'},
    {t:'海上谣',a:'李商隐〔唐代〕',c:'桂水寒于江，玉兔秋冷咽。\n海底舞仙人，香桃如瘦骨。\n紫鸾不肯舞，满翅蓬山雪。\n借得龙堂宽，晓出揲云发。\n刘郎旧香炷，立见茂陵树。\n云孙帖帖卧秋烟，上元细字如蚕眠。'},
    {t:'海水',a:'韩愈〔唐代〕',c:'海水非不广，邓林岂无枝。风波一荡薄，鱼鸟不可依。\n海水饶大波，邓林多惊风。岂无鱼与鸟，巨细各不同。\n海有吞舟鲸，邓有垂天鹏。苟非鳞羽大，荡薄不可能。\n我鳞不盈寸，我羽不盈尺。一木有馀阴，一泉有馀泽。\n我将辞海水，濯鳞清冷池。我将辞邓林，刷羽蒙笼枝。\n海水非爱广，邓林非爱枝。风波亦常事，鳞鱼自不宜。\n我鳞日已大，我羽日已修。风波无所苦，还作鲸鹏游。'},
    {t:'海棠',a:'晏殊〔宋代〕',c:'轻盈千结乱樱丛，占得年芳近破栊。\n逐处间匀高下萼，几番分破浅深红。\n烟晴始觉香缨绽，日极犹疑蜡蔕融。\n数夕朱栏未飘落，再三珍重石忧风。'},
    {t:'海棠',a:'苏轼〔宋代〕',c:'东风袅袅泛崇光，香雾空蒙月转廊。\n只恐夜深花睡去，故烧高烛照红妆。'},
    {t:'海棠',a:'黄庭坚〔宋代〕',c:'海棠院里寻春色，日炙荐红满院香。\n不觉风光都过了，东窗浑为读书忙。'},
    {t:'海棠',a:'晏殊〔宋代〕',c:'昔闻游客话芳菲，濯锦江头几万枝。\n纵使许昌诗笔健，可能终古绝妍辞。'},
    {t:'海棠',a:'晏殊〔宋代〕',c:'濯锦江头树，移根药砌中。\n只应春有意，偏与半妆红。'},
    {t:'海棠花',a:'王安石〔宋代〕',c:'绿娇隐约眉轻扫，红嫩妖饶脸薄妆。\n巧笔写传功未尽，清才吟咏兴何长。'},
    {t:'邯郸冬至夜思家',a:'白居易〔唐代〕',c:'邯郸驿里逢冬至，抱膝灯前影伴身。\n想得家中夜深坐，还应说着远行人。'},
    {t:'邯郸客舍歌',a:'岑参〔唐代〕',c:'客从长安来，驱马邯郸道。\n伤心丛台下，一带生蔓草。\n客舍门临漳水边，垂杨下系钓鱼船。\n邯郸女儿夜沽酒，对客挑灯夸数钱。\n酩酊醉时日正午，一曲狂歌垆上眠。'},
    {t:'邯郸少年行',a:'高适〔唐代〕',c:'邯郸城南游侠子，自矜生长邯郸里。\n千场纵博家仍富，几度报仇身不死。\n宅中歌笑日纷纷，门外车马常如云，\n未知肝胆向谁是，令人却忆平原君。\n君不见即今交态薄，黄金用尽还疏索。\n以兹感叹辞旧游，更于时事无所求。\n且与少年饮美酒，往来射猎西山头。'},
    {t:'邯郸少年行',a:'王昌龄〔唐代〕',c:'秋风鸣桑条，草白狐兔骄。\n邯郸饮来酒未消，城北原平掣皂雕。\n射杀空营两腾虎，回身却月佩弓弰。'},
    {t:'函谷关歌，送刘评事使关西',a:'岑参〔唐代〕',c:'君不见函谷关，崩城毁壁至今在。树根草蔓遮古道，\n空谷千年长不改。寂寞无人空旧山，圣朝无外不须关。\n白马公孙何处去，青牛老人更不还。苍苔白骨空满地，\n月与古时长相似。野花不省见行人，山鸟何曾识关吏。\n故人方乘使者车，吾知郭丹却不如。请君时忆关外客，\n行到关西多致书。'},
    {t:'韩大使东斋会岳上人、诸学士',a:'孟浩然〔唐代〕',c:'郡守虚陈榻，林间召楚材。山川掖雨毕，云物喜晴开。\n抗礼尊缝掖，临流揖渡杯。徒攀朱仲李，谁荐和羹梅。\n翰墨缘情制，高深以意裁。沧洲趣不远，何必问蓬莱。'},
    {t:'韩干马十四匹',a:'苏轼〔宋代〕',c:'二马并驱攒八蹄，二马宛颈鬃尾齐。\n一马任前双举后，一马却避长呜嘶。\n老髯奚官奇且顾，前身作马通马语。\n后有八匹饮且行，微流赴吻若有声。\n前者既济出林鹤，后者欲涉鹤俯啄。\n最后一匹马中龙，不嘶不动尾摇风。\n韩生画马真是马，苏子作诗如见画。\n世无伯乐亦无韩，此诗此画谁当看？'},
    {t:'韩翃舍人即事',a:'李商隐〔唐代〕',c:'萱草含丹粉，荷花抱绿房。鸟应悲蜀帝，蝉是怨齐王。\n通内藏珠府，应官解玉坊。桥南荀令过，十里送衣香。'},
    {t:'韩同年新居饯韩西迎家室戏赠',a:'李商隐〔唐代〕',c:'籍籍征西万户侯，新缘贵婿起朱楼。\n一名我漫居先甲，千骑君翻在上头。\n云路招邀回彩凤，天河迢递笑牵牛。\n南朝禁脔无人近，瘦尽琼枝咏四愁。'},
    {t:'韩信',a:'黄庭坚〔宋代〕',c:'韩生高才跨一世，刘项存亡翻手耳。\n终然不忍负沛公，颇似从容得天意。\n成皋日夜望救兵，取齐自重身已轻。\n蹑足封王能早寤，岂恨淮阴食千户。\n虽知天下有所归，独怜身与哙等齐。\n蒯通狂说不足撼，陈豨孺子胡能为。\n予尝贳酒淮阴市，韩信庙前木十围。\n千年事与浮云去，想见留侯决是非。\n丈夫出身佐明主，用舍行藏可自知。\n功名邂逅轩天地，万事当观失意时。'},
    {t:'韩信',a:'王安石〔宋代〕',c:'韩信寄食常歉然，邂逅漂母能哀怜。\n当时哙等何由伍，但有淮阴恶少年。\n谁道萧曹刀笔吏，从容一语知人意。\n坛上平明大将旗，举军尽惊王不疑。\n捄兵半楚潍半沙，从初龙且闻信怯。\n鸿沟天下已横分，谈笑重来卷楚氛。\n但以怯名终得羽，谁为孔费两将军。'},
    {t:'韩信庙',a:'刘禹锡〔唐代〕',c:'将略兵机命世雄，苍黄钟室叹良弓。\n遂令后代登坛者，每一寻思怕立功。'},
    {t:'韩漳州书报彻上人亡因寄二绝',a:'柳宗元〔唐代〕',c:'早岁京华听越吟，闻君江海分逾深。\n他时若写兰亭会，莫画高僧支道林。\n频把琼书出袖中，独吟遗句立秋风。\n桂江日夜流千里，挥泪何时到甬东。'},
    {t:'韩子',a:'王安石〔宋代〕',c:'纷纷易尽百年身，举世何人识道真。\n力去陈言夸末俗，可怜无补费精神。'},
    {t:'寒地百姓吟',a:'孟郊〔唐代〕',c:'无火炙地眠，半夜皆立号。\n冷箭壁处来，棘针风骚骚。\n霜吹破四壁，苦痛不可逃。\n高堂搥钟饮，到华闻烹炮。\n寒者愿为蛾，烧死彼华膏。\n华膏隔仙罗，虚绕千万遭。\n到头落地死，踏地为游遨。\n游遨者是谁？君子为郁陶！'},
    {t:'寒闺夜',a:'白居易〔唐代〕',c:'夜半衾裯冷，孤眠懒未能。笼香销尽火，巾泪滴成冰。\n为惜影相伴，通宵不灭灯。'},
    {t:'寒闺怨',a:'白居易〔唐代〕',c:'寒月沉沉洞房静，真珠帘外梧桐影。\n秋霜欲下手先知，灯底裁缝剪刀冷。'},
    {t:'寒江吟',a:'孟郊〔唐代〕',c:'冬至日光白，始知阴气凝。寒江波浪冻，千里无平冰。\n飞鸟绝高羽，行人皆晏兴。荻洲素浩渺，碕岸澌崚嶒。\n烟舟忽自阻，风帆不相乘。何况异形体，信任为股肱。\n涉江莫涉凌，得意须得朋。结交非贤良，谁免生爱憎。\n冻水有再浪，失飞有载腾。一言纵丑词，万响无善应。\n取鉴谅不远，江水千万层。何当春风吹，利涉吾道弘。'},
    {t:'寒雀',a:'杨万里〔宋代〕',c:'百千寒雀下空庭，小集梅梢话晚晴。\n特地作团喧杀我，忽然惊散寂无声。'},
    {t:'寒山子庞居士诗',a:'黄庭坚〔宋代〕',c:'我见黄河水，凡经几度清。\n水流如激箭，人世若浮萍。\n痴属根本业，爱为烦恼阬。\n轮回几许劫，不解了无明。\n寒山出此语，举世狂痴半。\n有事对面说，所以足人怨。\n心真语亦直，直语无背面。\n君看渡奈河，谁是喽罗汉。\n寄语诸仁者，仁以何为怀。\n归源知自性，自性即如来。\n任运堂试张通笔为法耸上座书寒山子庞居士诗两卷。涪翁题。'},
    {t:'寒食',a:'韦应物〔唐代〕',c:'晴明寒食好，春园百卉开。\n彩绳拂花去，轻球度阁来。\n长歌送落日，缓吹逐残杯。\n非关无烛罢，良为羁思催。'},
    {t:'寒食',a:'张籍〔唐代〕',c:'绿杨枝上五丝绳，枝弱春多欲不胜。\n唯有一年寒食日，女郎相唤摆阶。'},
    {t:'寒食城东即事',a:'王维〔唐代〕',c:'清溪一道穿桃李，演漾绿蒲涵落芷。\n溪上人家凡几家，落花半落东流水。\n蹴踘屡过飞鸟上，秋千竞出垂杨里。\n少年分日作遨游，不用清明兼上巳。'},
    {t:'寒食后北楼作',a:'韦应物〔唐代〕',c:'园林过新节，风花乱高阁。\n遥闻击鼓声，蹴鞠军中乐。'},
    {t:'寒食即事',a:'王昌龄〔唐代〕',c:'晋阳寒食地，风俗旧来传。雨灭龙蛇火，春生鸿雁天。\n泣多流水涨，歌发舞云旋。西见之推庙，空为人所怜。'},
    {t:'寒食寄京师诸弟',a:'韦应物〔唐代〕',c:'雨中禁火空斋冷，江上流莺独坐听。\n把酒看花想诸弟，杜陵寒食草青青。'},
    {t:'寒食节日寄楚望二首',a:'温庭筠〔唐代〕',c:'芳兰无意绿，弱柳何穷缕。心断八淮山，梦长穿楚雨。\n繁花如二八，好月当三五。愁碧竟平皋，韶馀换幽圃。\n流莺隐员树，乳燕喧馀哺。旷望恋曾台，离忧集环堵。\n当年不自遣，晚得终何补。郑谷有樵苏，归来要腰斧。\n家乏两千万，时当一百五。飔飔杨柳风，穰穰樱桃雨。\n年芳苦沉潦，心事如摧橹。金犊近兰汀，铜龙接花坞。\n青葱建杨宅，隐辚端门鼓。彩素拂庭柯，轻球落邻圃。\n三春谢游衍，一笑牵规矩。独有恩泽侯，归来看楚舞。'},
    {t:'寒食内宴二首',a:'张籍〔唐代〕',c:'朝光瑞气满宫楼，彩纛鱼龙四骑稠。廊下御厨分冷食，\n殿前香骑逐飞球。千官尽醉犹教坐，百出皆呈未放休。\n共喜拜恩侵夜出，金吾不敢问行由。\n城阙沈沈向晓寒，恩当令节赐馀欢，瑞烟深处开三殿，\n春雨微时引百官，宝树楼前分绣幕，彩花廊下映华栏。\n宫筵出乐年年别，已得三回对御看。'},
    {t:'寒食前有怀',a:'温庭筠〔唐代〕',c:'万物鲜华雨乍晴，春寒寂历近清明。残芳荏苒双飞蝶，\n晓睡朦胧百啭莺。旧侣不归成独酌，故园虽在有谁耕。\n悠然更起严滩恨，一宿东风蕙草生。'},
    {t:'寒食日寄诸弟',a:'韦应物〔唐代〕',c:'禁火暧佳辰，念离独伤抱。见此野田花，心思杜陵道。\n联骑定何时，予今颜已老。'},
    {t:'寒食日作',a:'温庭筠〔唐代〕',c:'红深绿暗径相交，抱暖含芳披紫袍。\n彩索平时墙婉娩，轻球落处晚寥梢。\n窗中草色妬鸡卵，盘上芹泥憎燕巢。\n自有玉楼春意在，不能骑马度烟郊。'},
    {t:'寒食上冢',a:'杨万里〔宋代〕',c:'迳直夫何细！桥危可免扶？\n远山枫外淡，破屋麦边孤。\n宿草春风又，新阡去岁无。\n梨花自寒食，时节只愁予。'},
    {t:'寒食汜上作',a:'王维〔唐代〕',c:'广武城边逢暮春，汶阳归客泪沾巾。\n落花寂寂啼山鸟，杨柳青青渡水人。'},
    {t:'寒食帖',a:'苏轼〔宋代〕',c:'一曰：“自我来黄州，已过三寒食。年年欲惜春，春去不容惜。今年又苦雨，两月秋萧瑟。卧闻海棠花，泥污燕支雪。闇中偷负去，夜半真有力。何殊病少年，病起头已白。”\n二曰：“春江欲入户，雨势来不已。小屋如渔舟，濛濛水云里。空庖煮寒菜，破灶烧湿苇。那知是寒食，但见乌衔纸。君门深九重，坟墓在万里。也拟哭途穷，死灰吹不起”。'},
    {t:'寒食卧疾喜李少府见寻',a:'王昌龄〔唐代〕',c:'弱冠早登龙，今来喜再逢。\n何知春月柳，犹忆岁寒松。\n烟火临寒食，笠歌达曙钟。\n喧喧斗鸡道，行乐羡朋从。'},
    {t:'寒食野望吟',a:'白居易〔唐代〕',c:'乌啼鹊噪昏乔木，清明寒食谁家哭。\n风吹旷野纸钱飞，古墓垒垒春草绿。\n棠梨花映白杨树，尽是死生别离处。\n冥冥重泉哭不闻，萧萧暮雨人归去。'},
    {t:'寒食夜',a:'元稹〔唐代〕',c:'红染桃花雪压梨，玲珑鸡子斗赢时。\n今年不是明寒食，暗地秋千别有期。'},
    {t:'寒食夜寄姚侍郎',a:'张籍〔唐代〕',c:'贫官多寂寞，不异野人居。作酒和山药，教儿写道书。\n五湖归去远，百事病来疏。况忆同怀者，寒庭月上初。'},
    {t:'寒食游王氏城东园林因寄王虞部',a:'晏殊〔宋代〕',c:'谢墅林亭汴水滨，偶携佳客共寻春。\n看花纵拟思君子，对竹何曾问主人。\n促席正逢羲日缓，酡颜仍有郢醪醇。\n朝中九列无间暇，愿作新诗赠季伦。'},
    {t:'寒食雨二首',a:'苏轼〔宋代〕',c:'自我来黄州，已过三寒食。\n年年欲惜春，春去不容惜。\n今年又苦雨，两月秋萧瑟。\n卧闻海棠花，泥污燕脂雪。\n暗中偷负去，夜半真有力。\n何殊病少年，病起头已白。\n春江欲入户，雨势来不已。\n小屋如渔舟，濛濛水云里。\n空庖煮寒菜，破灶烧湿苇。\n那知是寒食，但见乌衔纸。\n君门深九重，坟墓在万里。\n也拟哭途穷，死灰吹不起。'},
    {t:'寒塘曲',a:'张籍〔唐代〕',c:'寒塘沉沉柳叶疏，水暗人语惊栖凫。\n舟中少年醉不起，持烛照水射游鱼。'},
    {t:'寒夜',a:'孟浩然〔唐代〕',c:'闺夕绮窗闭，佳人罢缝衣。理琴开宝匣，就枕卧重帏。\n夜久灯花落，薰笼香气微。锦衾重自暖，遮莫晓霜飞。'},
    {t:'寒夜读书',a:'陆游〔宋代〕',c:'韦编屡绝铁砚穿，口诵手钞那计年。\n不是爱书即欲死，任从人笑作书颠。'},
    {t:'寒夜张明府宅宴',a:'孟浩然〔唐代〕',c:'瑞雪初盈尺，寒宵始半更。列筵邀酒伴，刻烛限诗成。\n香炭金炉暖，娇弦玉指清。醉来方欲卧，不觉晓鸡鸣。'},
    {t:'寒雨中偶赋二首·其一',a:'陆游〔宋代〕',c:'鬓毛萧飒齿根浮，徂岁翩翩肯暂留？\n穷巷多泥谁问疾，空阶滴雨又经秋。\n自营可笑夸三窟，善守宁须筑百楼？\n但使胸中机事尽，一樽随处送悠悠。'},
    {t:'汉川山行，呈成少尹',a:'岑参〔唐代〕',c:'西蜀方携手，南宫忆比肩。平生犹不浅，羁旅转相怜。\n山店云迎客，江村犬吠船。秋来取一醉，须待月光眠。'},
    {t:'汉宫春·初自南郑来成都作',a:'陆游〔宋代〕',c:'羽箭雕弓，忆呼鹰古垒，截虎平漓。吹笳暮归野帐，雪压青毡。淋漓醉墨，看龙蛇飞落蛮笺。人误事、诗情将略，一时才气超然。\n何事又作南来，看重阳药市，元夕灯山？花时万人乐处，欹帽垂鞭。闻歌感旧，尚时时流涕尊前。君记取、封侯事在。功名不信由天。'},
    {t:'汉宫春·会稽蓬莱阁观雨',a:'辛弃疾〔宋代〕',c:'秦望山头，看乱云急雨，倒立江湖。不知云者为雨，雨者云乎？长空万里，被西风变灭须臾。回首听月明天籁，人间万窍号呼。\n谁向若耶溪上，倩美人西去，麋鹿姑苏？至今故国人望，一舸归欤。岁云暮矣，问何不鼓瑟吹竽？君不见王亭谢馆，冷烟寒树啼乌！'},
    {t:'汉宫春·会稽秋风亭怀古',a:'辛弃疾〔宋代〕',c:'亭上秋风，记去年袅袅，曾到吾成。山河举目虽异，风景非殊。功成者去，觉团扇、便与人疏。吹不古，斜阳依旧，茫茫禹迹都无。\n千古茂陵词在，甚风流章句，解拟相如。只今木落江冷，眇眇愁余。故人书报，莫因循、忘却蓴鲈。谁念我，新凉灯火，一编太史公书。'},
    {t:'汉宫春·立春日',a:'辛弃疾〔宋代〕',c:'春已归来，看美人头上，袅袅春时。无端风雨，未肯收尽余寒。年时燕子，料今宵梦到西园。浑未笑、黄柑荐酒，更传青韭堆盘？\n却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜。清愁不断，问何人会解连环？生怕见花开花落，朝来塞雁先还。'},
    {t:'汉宫词',a:'李商隐〔唐代〕',c:'青雀西飞竟未回，君王长在集灵台。\n侍臣最有相如渴，不赐金茎露一杯。'},
    {t:'汉皇迎春词',a:'温庭筠〔唐代〕',c:'春草芊芊晴扫烟，宫城大锦红队鲜。海日初融照仙掌，\n淮王小队缨铃响。猎猎东风焰赤旗，画芒金甲葱龙网。\n钜公步辇迎句芒，复道扫尘燕彗长。豹尾竿前赵飞燕，\n柳风吹尽眉间黄。碧草含情杏花喜，上林莺啭游丝起。\n宝马摇环万骑归，恩光暗入帘栊里。'},
    {t:'汉江',a:'杜牧〔唐代〕',c:'溶溶漾漾白鸥飞，绿净春深好染衣。\n南去北来人自老，夕阳长送钓船归。'},
    {t:'汉江临泛',a:'王维〔唐代〕',c:'楚塞三湘接，荆门九派通。\n江流天地外，山色有无中。\n郡邑浮前浦，波澜动远空。\n襄阳好风日，留醉与山翁。'},
    {t:'汉上题韦氏庄',a:'岑参〔唐代〕',c:'结茅闻楚客，卜筑汉江边。日落数归鸟，夜深闻扣舷。\n水痕侵岸柳，山翠借厨烟。调笑提筐妇，春来蚕几眠。'},
    {t:'汉寿城春望',a:'刘禹锡〔唐代〕',c:'汉寿城边野草春，荒祠古墓对荆榛。\n田中牧竖烧刍狗，陌上行人看石麟。\n华表半空经霹雳，碑文才见满埃尘。\n不知何日东瀛变，此地还成要路津。'},
    {t:'汉唐姬饮酒歌',a:'李贺〔唐代〕',c:'御服沾霜露，天衢长蓁棘。\n金隐寝尘姿，无人为带饰。\n玉堂歌声寝，芳林烟树隔。\n云阳台上歌，鬼屡复何益。\n铁剑常光光，至凶威屡逼。\n强枭噬母心，奔厉索人魄。\n相看两相泣，泪下如波激。\n宁用清酒为，欲作黄泉客。\n不说玉山颓，且无饮中色。\n勉从天帝诉，天上寡沈厄。\n无处张繐帷，如何望松柏。\n妾身昼团团，君魂夜寂寂。\n蛾眉自觉长，颈粉谁怜白。\n矜持昭阳意，不肯看南陌。'},
    {t:'汉武',a:'王安石〔宋代〕',c:'壮士悲歌出塞频，中原萧瑟半无人。\n君王不负长陵约，直欲功成赏汉臣。'},
    {t:'撼庭秋',a:'晏殊〔宋代〕',c:'别来音信千里，怅此情难寄。碧纱秋月，梧桐夜雨，几回无寐。\n楼高目断，天遥云黯，只堪憔悴。念兰堂红烛，心长焰短，向人垂泪。'},
    {t:'撼庭秋·别来音信千里',a:'晏殊〔宋代〕',c:'别来音信千里，恨此情难寄。碧纱秋月，梧桐夜雨，几回无寐。\n楼高目断，天遥云黯，只堪憔悴。念兰堂红烛，心长焰短，向人垂泪。'},
    {t:'杭州呈胜之',a:'王安石〔宋代〕',c:'游观须知此地佳，纷纷人物敌风华。\n林峦腊雪千家水，城郭春风二月花。\n彩舫笙箫吹落日，画楼灯烛映残霞。\n如君援笔直摹写，寄与尘埃北客夸。'},
    {t:'杭州春望',a:'白居易〔唐代〕',c:'望海楼明照曙霞，护江堤白踏晴沙。\n涛声夜入伍员庙，柳色春藏苏小家。\n红袖织绫夸柿蒂，青旗沽酒趁梨花。\n谁开湖寺西南路，草绿裙腰一道斜。'},
    {t:'杭州回舫',a:'白居易〔唐代〕',c:'自别钱塘山水后，不多饮酒懒吟诗。\n欲将此意凭回棹，报与西湖风月知。'},
    {t:'杭州望湖楼回马上作呈玉汝乐道',a:'王安石〔宋代〕',c:'水光山气碧浮浮，落日将归又少留。\n从此只应长入梦，梦中还与故人游。'},
    {t:'蒿里',a:'佚名〔两汉〕',c:'蒿里谁家地，聚敛魂魄无贤愚。\n鬼伯一何相催促，人命不得少踟蹰。'},
    {t:'好女儿',a:'晏几道〔宋代〕',c:'绿遍西池。梅子青时。尽无端、尽日东风恶，更霏微细雨，恼人离恨，满路春泥。\n应是行云归路，有闲泪、洒相思。想旗亭、望断黄昏月，又依前误了，红笺香信，翠袖欢期。'},
    {t:'好女儿',a:'晏几道〔宋代〕',c:'酌酒殷勤。尽更留春。忍无情、便赋余花落，待花前细把、一春心事，问个人人。\n莫似花开还谢，愿芳意、且长新。倚娇红、待得欢期定，向水沈烟底，金莲影下，睡过佳辰。'},
    {t:'好事近·春色欲来时',a:'朱熹〔宋代〕',c:'春色欲来时，先散满天风雪。坐使七闽松竹，变珠幢玉节。中原佳气郁葱葱，河山壮宫阕。丞相功成千载，映黄流清彻。'},
    {t:'好事近·何路向家园',a:'纳兰性德〔清代〕',c:'何路向家园，历历残山剩水。都把一春冷淡，到麦秋天气。\n料应重发隔年花，莫问花前事。纵使东风依旧，怕红颜不似。'},
    {t:'好事近·湖上',a:'苏轼〔宋代〕',c:'湖上雨晴时，秋水半篙初没。朱槛俯窥寒鉴，照衰颜华发。\n醉中吹坠白纶巾，溪风漾流月。独棹小舟归去，任烟波飘兀。'},
    {t:'好事近·帘外五更风',a:'纳兰性德〔清代〕',c:'帘外五更风，消受晓寒时节。刚剩秋衾一半，拥透帘残月。\n争教清泪不成冰？好处便轻别。拟把伤离情绪，待晓寒重说。'},
    {t:'好事近·马首望青山',a:'纳兰性德〔清代〕',c:'马首望青山，零落繁华如此。再折断烟衰草，认藓碑题字。\n休寻折戟话当年，只洒悲秋泪。斜日十三陵下，过新丰猎骑。'},
    {t:'好事近·梦中作',a:'秦观〔宋代〕',c:'春路雨添花，花动一山春色。行到小溪深处，有黄鹂千百。\n飞云当面化龙蛇，夭矫转空碧。醉卧古藤阴下，了不知南北。'},
    {t:'好事近·湓口放船归',a:'陆游〔宋代〕',c:'湓口放船归，薄暮散花洲宿。两酒白苹红蓼，映一蓑新绿。\n有沽酒处便为家，菱芡四时足。明日又乘风去，任江南江北。'},
    {t:'好事近·秋晓上莲峰',a:'陆游〔宋代〕',c:'秋晓上莲峰，高蹑倚天青壁。谁与放翁为伴？有天坛轻策。\n铿然忽变赤龙飞，雷雨四山黑。谈笑做成丰岁，笑禅龛楖栗。'},
    {t:'好事近·西湖',a:'辛弃疾〔宋代〕',c:'日日过西湖，冷浸一天寒玉。山色虽言如画，想画时难邈。\n前弦后管夹歌钟，才断又重续。相次藕花开也，几兰舟飞逐。'},
    {t:'好事近·烟外倚危楼',a:'苏轼〔宋代〕',c:'烟外倚危楼，初见远灯明灭。却跨玉虹归去、看洞天星月。\n当时张范风流在，况一尊浮雪。莫问世间何事、与剑头微吷。'},
    {t:'好事近·元夕立春',a:'辛弃疾〔宋代〕',c:'彩胜斗华灯，平地东风吹却。唤取雪中明月，伴使君行乐。\n红旗铁马响春冰，老去此情薄。惟有前村梅在，倩一枝随著。'},
    {t:'好事近·赠笑倩',a:'张炎〔宋代〕',c:'葱茜满身云，酒晕浅融香颊。水调数声娴雅，把芳心偷说。\n风吹裙带下阶迟，惊散双蝴蝶。佯捻花枝微笑，溜晴波一瞥。'},
    {t:'好事近·中秋席上和王路钤',a:'辛弃疾〔宋代〕',c:'明月到今宵，长是不如人约。想休广寒宫殿，正云梳风掠。\n夜深休更唤笙歌，檐头雨声恶。不是小山词就，这一场寥索。'},
    {t:'好事近梦中作',a:'秦观〔宋代〕',c:'春路雨添花，\n花动一山春色。\n行到小溪深处，\n有黄鹂千百。\n飞云当面化龙蛇，\n夭骄转空碧。\n醉卧古藤阴下，\n了不知南北。'},
    {t:'浩歌',a:'李贺〔唐代〕',c:'南风吹山作平地，帝遣天吴移咸水。\n王母桃花千遍红，彭祖巫咸几回死？\n青毛骢马参差钱，娇卮杨柳含缃烟。\n筝人劝我金屈卮，神血未凝身问谁？\n不须浪饮丁都护，世上英雄本无主。\n买丝绣作平原君，有酒唯浇赵州土。\n漏催水咽玉蟾蜍，卫娘发薄不胜梳。\n羞见秋眉换新绿，二十男儿那刺促？'},
    {t:'喝火令·见晚情如旧',a:'黄庭坚〔宋代〕',c:'见晚情如旧，交疏分已深。舞时歌处动人心。烟水数年魂梦，无处可追寻。\n昨夜灯前见，重题汉上襟。便愁云雨又难禁。晓也星稀，晓也月西沉。晓也雁行低度，不会寄芳音。'},
    {t:'合欢带·身材儿早是妖娆',a:'柳永〔宋代〕',c:'身材儿、早是妖娆。算风措、实难描。一个肌肤浑似玉，更都来、占了千娇。妍歌艳舞，莺惭巧舌，柳妒纤腰。自相逢、便觉韩娥价减，飞燕声消。\n桃花零落，溪水潺湲，重寻仙径非遥。莫道千金酬一笑，便明珠、万斛须邀。檀郎幸有，凌云词赋，掷果风标。况当年、便好相携，凤楼深处吹箫。'},
    {t:'合江楼',a:'文天祥〔宋代〕',c:'天上名鹑尾，人间说虎头。\n春风千万岫，秋水两三洲。\n客晚惊黄叶，官闲笑白鸥。\n双江日东下，我欲赋扁舟。'},
    {t:'何九于客舍集',a:'王昌龄〔唐代〕',c:'客有住桂阳，亦如巢林鸟。\n罍觞且终宴，功业会未了。\n山月空霁时，江明高楼晓。\n门前泊舟楫，行次入松筱。\n此意投赠君，沧波风袅袅。'},
    {t:'何满子',a:'秦观〔宋代〕',c:'天际江流东注，云中塞雁南翔。衰草寒烟无意思，向人只会凄凉。吟断炉香袅袅，望穷海月茫茫。\n莺梦春风锦幄，蛩声夜雨蓬窗。谙尽悲欢多少味，酒杯付与疏狂。无奈供愁秋色，时时递入柔肠。'},
    {t:'和白侍郎送令狐相公镇太原',a:'刘禹锡〔唐代〕',c:'十万天兵貂锦衣，晋城风日斗郎辉。\n行台仆射深恩重，从事中郎旧路归。\n叠鼓蹙成汾水浪，闪旗惊断塞鸿飞。\n边庭自此无烽火，拥节还来坐紫微。'},
    {t:'和并州大资政郑侍郎秋晚书事',a:'范仲淹〔宋代〕',c:'太原兵重压强胡，莫对秋风忆鱠鲈。\n万里天声扬紫塞，十年人望在黄枢。\n定应松柏心无改，自信云龙道不孤。\n应笑病夫何所补，独能安坐养桑榆。'},
    {t:'和昌英叔夏至喜雨',a:'杨万里〔宋代〕',c:'清酣暑雨不缘求，犹似梅黄麦欲秋。\n去岁如今禾半死，吾曹遍祷汗交流。\n此生未用愠三已，一饱便应哦四休。\n花外绿畦深没鹤，来看莫惜下邳侯。'},
    {t:'和陈君仪读太真外传五首',a:'黄庭坚〔宋代〕',c:'扶风乔木夏阴合，斜谷铃声秋夜深。\n人到愁来无处会，不关情处总伤心。'},
    {t:'和祠部王员外雪后早朝即事',a:'岑参〔唐代〕',c:'长安雪后似春归，积素凝华连曙晖。\n色借玉珂迷晓骑，光添银烛晃朝衣。\n西山落月临天仗，北阙晴云捧禁闱。\n闻道仙郎歌白雪，由来此曲和人稀。'},
    {t:'和崔二少府登楚丘城作',a:'高适〔唐代〕',c:'故人亦不遇，异县久栖托。辛勤失路意，感叹登楼作。\n清晨眺原野，独立穷寥廓。云散芒砀山，水还睢阳郭。\n绕梁即襟带，封卫多漂泊。事古悲城池，年丰爱墟落。\n相逢俱未展，携手空萧索。何意千里心，仍求百金诺。\n公侯皆我辈，动用在谋略。圣心思贤才，朅来刈葵藿。'},
    {t:'和崔黄门寓直夜听蝉之作',a:'张九龄〔唐代〕',c:'蝉嘶玉树枝，向夕惠风吹。幸入连宵听，应缘饮露知。\n思深秋欲近，声静夜相宜。不是黄金饰，清香徒尔为。'},
    {t:'和崔尚书喜雨',a:'张九龄〔唐代〕',c:'积阳虽有晦，经月未为灾。上念人天重，先祈云汉回。\n仁心及草木，号令起风雷。照烂阴霞止，交纷瑞雨来。\n三辰破黍稷，四达屏氛埃。池溜因添满，林芳为洒开。\n听中声滴沥，望处影徘徊。惠泽成丰岁，昌言发上才。\n无论验石鼓，不是御云台。直颂皇恩浃，崇朝遍九垓。'},
    {t:'和答登封王晦之登楼见寄',a:'黄庭坚〔宋代〕',c:'县楼三十六峰寒，王粲登临独里阑。\n清坐一番春雨歇，相思千里夕阳残。\n诗来嗟我不同醉，别后喜君能自宽。\n举目尽妨人作乐，几时归得钓鲵桓。'},
    {t:'和答钱穆父咏猩猩毛笔',a:'黄庭坚〔宋代〕',c:'爱酒醉魂在，能言机事疏。\n平生几两屐，身后五车书。\n物色看王会，勋劳在石渠。\n拔毛能济世，端为谢杨朱。'},
    {t:'和答元明黔南赠别',a:'黄庭坚〔宋代〕',c:'万里相看忘逆旅，三声清泪落离觞。\n朝云往日攀天梦，夜雨何时对榻凉。\n急雪脊令相并影，惊风鸿雁不成行。\n归舟天际常回首，从此频书慰断肠。'},
    {t:'和丁助教塞上吟',a:'孟郊〔唐代〕',c:'哭雪复吟雪，广文丁夫子。江南万里寒，曾未及如此。\n整顿气候谁，言从生灵始。无令恻隐者，哀哀不能已。'},
    {t:'和董传留别',a:'苏轼〔宋代〕',c:'粗缯大布裹生涯，腹有诗书气子华。\n厌伴老儒烹瓠叶，强随举子踏槐花。\n囊空不办寻春马，眼乱行看择婿车。\n得意犹堪夸世俗，诏黄新湿字如鸦。'},
    {t:'和龚使君韵',a:'文天祥〔宋代〕',c:'淡和心事葛天民，回首归来清仲滨。\n长倩君宝孙子行，道原义仲辈流人。\n一生受用忘非是，万事升沉等故新。\n近日贞元朝士少，蒲轮有命出枫宸。'},
    {t:'和郭主簿·其二',a:'陶渊明〔魏晋〕',c:'和泽周三春，清凉素秋节。\n露凝无游氛，天高肃景澈。\n陵岑耸逸峰，遥瞻皆奇绝。\n芳菊开林耀，青松冠岩列。\n怀此贞秀姿，卓为霜下杰。\n衔觞念幽人，千载抚尔诀。\n检素不获展，厌厌竟良月。'},
    {t:'和郭主簿二首·其一',a:'陶渊明〔魏晋〕',c:'蔼蔼堂前林，中夏贮清阴。\n凯风因时来，回飙开我襟。\n息交游闲业，卧起弄书琴。\n园蔬有余滋，旧谷犹储今。\n营己良有极，过足非所钦。\n舂秫作美酒，酒熟吾自斟。\n弱子戏我侧，学语未成音。\n此事真复乐，聊用忘华簪。\n遥遥望白云，怀古一何深！'},
    {t:'和韩布殿丞三首其三·渔父',a:'范仲淹〔宋代〕',c:'月色满沧波，吾生乐事多。\n何人独醒者，试听濯缨歌。'},
    {t:'和韩布殿丞三首其一·泛湖中',a:'范仲淹〔宋代〕',c:'平湖万顷碧，谢客一开颜。\n待得临清夜，徘徊载月还。'},
    {t:'和韩录事送宫人入道',a:'李商隐〔唐代〕',c:'星使追还不自由，双童捧上绿中辀。\n九枝灯下朝金殿，三素云中侍玉楼。\n凤女颠狂成久别，月娥孀独好同游。\n当时若爱韩公子，埋骨成灰恨未休。'},
    {t:'和贺兰判官望北海作',a:'高适〔唐代〕',c:'圣代务平典，輶轩推上才。迢遥息海际，旷望沧波开。\n四牡未遑息，三山安在哉。巨鳌不可钓，高九何崔嵬。\n湛湛朝百谷，茫茫连九垓。挹流纳广大，观异增迟回。\n日出见鱼目，月圆知蚌胎。迹非想像到，心以精灵猜。\n远色带孤屿，虚声涵殷雷。风行越裳贡，水遏天吴灾。\n揽辔隼将击，忘机鸥复来。缘情韵骚雅，独立遗尘埃。\n吏道竟殊用，翰林仍忝陪。长鸣谢知己，所愧非龙媒。'},
    {t:'和胡西曹示顾贼曹',a:'陶渊明〔魏晋〕',c:'蕤宾五月中，清朝起南颸。\n不驶日不迟，飘飘吹我衣。\n重云蔽白日，闲雨纷微微。\n流目视西园，复复荣紫葵。\n于今甚可爱，奈何当复衰！\n感物愿及时，每恨靡所挥。\n悠悠待秋稼，寥落将赊迟。\n逸想不可淹，猖狂独长悲！'},
    {t:'和皇甫判官游琅琊溪',a:'孟郊〔唐代〕',c:'山中琉璃境，物外琅琊溪。房廊逐岩壑，道路随高低。\n碧濑漱白石，翠烟含青蜺。客来暂游践，意欲忘簪珪。\n树杪灯火夕，云端钟梵齐。时同虽可仰，迹异难相携。\n唯当清宵梦，仿佛愿攀跻。'},
    {t:'和黄法曹忆建溪梅花',a:'秦观〔宋代〕',c:'海陵参军不枯槁，醉忆梅花悉绝倒。\n为怜一树傍寒溪，花水多情自相恼。\n清泪班班知有恨，恨春相逢苦不早。\n甘心结子待君来，洗雨梳风为谁好。\n谁云广平心似铁，不惜珠玑与挥扫。\n月没参横画角哀，暗香销尽令人老。\n天分四时不相贷，孤芳转盼同衰草。\n要须健步远移归，乱插繁华向晴昊。'},
    {t:'和黄门卢监望秦始皇陵',a:'张九龄〔唐代〕',c:'秦帝始求仙，骊山何遽卜。\n中年奔无效，兹地所宜复。\n徒役如雷奔，珍怪亦云蓄。\n黔首无寄命，赭遂相追逐。\n人怨神亦怒，身死宗遂覆。\n土崩失天下，龙斗入函谷。\n国为项籍屠，君同华元戮。\n始掘奔由楚，终焚乃因牧。\n上宰议扬贤，中阿感桓速。\n一闻过秦论，载怀空杼轴。'},
    {t:'和黄门卢侍御咏竹',a:'张九龄〔唐代〕',c:'清切紫庭垂，葳蕤防露枝。\n色无玄月变，声有惠风吹。\n高节人相重，虚心世所知。\n凤凰佳可食，一去一来仪。'},
    {t:'和黄揔太博上知郡杜少卿',a:'范仲淹〔宋代〕',c:'万石君贤再出麾，犹龙川上五歌时。\n九重执宪清规在，十镇分忧白发知。\n环禁申威星拱极，铃斋舒啸月侵帷。\n金台下客思何报，愿上中和乐职诗。'},
    {t:'和贾舍人早朝大明宫之作',a:'王维〔唐代〕',c:'绛帻鸡人报晓筹，尚衣方进翠殿裘。\n九天阊阖开宫殿，万国衣冠拜冕旒。\n日色才临仙掌动，香烟欲傍衮龙浮。\n朝罢须裁五色诏，佩声归向凤池头。'},
    {t:'和贾主簿弁九日登岘山',a:'孟浩然〔唐代〕',c:'楚万重阳日，群公赏宴来。共乘休沐暇，同醉菊花杯。\n逸思高秋发，欢情落景催。国人咸寡和，遥愧洛阳才。'},
    {t:'和姜邦杰春坊续丽人行',a:'杨万里〔宋代〕',c:'玉人自惜如花面，不许黄鹂鹦鹉见。\n若令画史识倾城，写遍人间屏与扇。\n春光嬾困扶不起，吹残玉笙也慵理。\n是谁瞥见一梳云，微月影中扫穠李。\n阿昉妵周不姓顾，笔端那得莲生步。\n无妨正面与渠看，看了丹青无尽处。\n古来妍丑知几何，嫫母背面谩人多。\n君不见汉宫六六多少人，画图枉却王昭君。\n是时当面看写真，却遣琵琶弹塞尘。\n不如九京唤起文舆可，麝煤醉与竹傅神。'},
    {t:'和乐天别弟后月夜作',a:'元稹〔唐代〕',c:'闻君别爱弟，明天照夜寒。秋雁拂檐影，晓琴当砌弹。\n怅望天澹澹，因思路漫漫。吟为别弟操，闻者为辛酸。\n况我兄弟远，一身形影单。江波浩无极，但见时岁阑。'},
    {t:'和乐天仇家酒',a:'元稹〔唐代〕',c:'病嗟酒户年年减，老觉尘机渐渐深。\n饮罢醒馀更惆怅，不如闲事不经心。'},
    {t:'和乐天春词',a:'刘禹锡〔唐代〕',c:'新妆宜面下朱楼，深锁春光一院愁。\n行到中庭数花朵，蜻蜓飞上玉搔头。'},
    {t:'和乐天感鹤',a:'元稹〔唐代〕',c:'我有所爱鹤，毛羽霜雪妍。秋霄一滴露，声闻林外天。\n自随卫侯去，遂入大夫轩。云貌久已隔，玉音无复传。\n吟君感鹤操，不觉心惕然。无乃予所爱，误为微物迁。\n因兹谕直质，未免柔细牵。君看孤松树，左右萝茑缠。\n既可习为饱，亦可薰为荃。期君常善救，勿令终弃捐。'},
    {t:'和乐天高相宅',a:'元稹〔唐代〕',c:'莫愁已去无穷事，漫苦如今有限身。\n二百年来城里宅，一家知换几多人。'},
    {t:'和乐天过秘阁书省旧厅',a:'元稹〔唐代〕',c:'闻君西省重徘徊，秘阁书房次问开。壁记欲题三漏合，\n吏人惊问十年来。经排蠹简怜初校，芸长陈根识旧栽。\n司马见诗心最苦，满身蚊蚋哭烟埃。'},
    {t:'和乐天南园试小乐',a:'刘禹锡〔唐代〕',c:'闲步南园烟雨晴，遥闻丝竹出商声。\n欲抛丹笔三川去，先教清商一部成。\n花木手栽偏有兴，歌词自作别生情。\n多才遇景皆能咏，当日人传满凤城。'},
    {t:'和乐天秋题牡丹丛',a:'元稹〔唐代〕',c:'敝宅艳山卉，别来长叹息。\n吟君晚丛咏，似见摧颓色。\n欲识别后容，勤过晚丛侧。'},
    {t:'和乐天秋题曲江',a:'元稹〔唐代〕',c:'十载定交契，七年镇相随。长安小多处，多是曲江池。\n梅杏春尚小，芰荷秋已衰。共爱寥落境，相鹭偏此时。\n绵绵红蓼水，飏飏白鹭鹚。诗句偶未得，酒杯聊久持。\n今来云雨旷，旧赏魂梦知。况乃江枫夕，和君秋兴诗。'},
    {t:'和乐天示杨琼',a:'元稹〔唐代〕',c:'我在江陵少年日，知有杨琼初应出。腰身瘦小歌圆紧，\n依约年应十六七。去年十月过苏州，琼去拜问郎不识。\n青衫玉貌何处去，安得红旗遮头白。我语杨琼琼莫语，\n汝虽笑我我笑汝。汝今无复小腰身，不似江陵时好女。\n杨琼为我歌送酒，尔忆江陵县中否。江陵王令骨为灰，\n车去嫁作尚书妇。卢戡及第严涧在，其馀死者十八九。\n我今贺尔亦自多，尔得老成余白首。'},
    {t:'和乐天送鹤上裴相公别鹤之作',a:'刘禹锡〔唐代〕',c:'昨日看成送鹤诗，高笼提出白云司。朱门乍入应迷路，\n玉树容栖莫拣枝。双舞庭中花落处，数声池上月明时。\n三山碧海不归去，且向人间呈羽仪。'},
    {t:'和乐天题王家亭子',a:'元稹〔唐代〕',c:'风吹笋箨飘红砌，雨打桐花尽绿莎。\n都大资人无暇日，泛池全少买池多。'},
    {t:'和乐天早春见寄',a:'元稹〔唐代〕',c:'雨香云澹觉微和，谁送春声入棹歌。\n萱近北堂穿土早，柳偏东面受风多。\n湖添水色消残雪，江送潮头涌漫波。\n同受新年不同赏，无由缩地欲如何。'},
    {t:'和乐天赠云寂僧',a:'元稹〔唐代〕',c:'欲离烦恼三千界，不在禅门八万条。\n心火自生还自灭，云师无路与君销。'},
    {t:'和乐天招钱蔚章看山绝句',a:'元稹〔唐代〕',c:'碧落招邀闲旷望，黄金城外玉方壶。\n人间还有大江海，万里烟波天上无。'},
    {t:'和乐天折剑头',a:'元稹〔唐代〕',c:'闻君得折剑，一片雄心起。讵意铁蛟龙，潜在延津水。\n风云会一合，呼吸期万里。雷震山岳碎，电斩鲸鲵死。\n莫但宝剑头，剑头非此比。'},
    {t:'和乐天重题别东楼',a:'元稹〔唐代〕',c:'山容水态使君知，楼上从容万甲移。\n日映文章霞细丽，风驱鳞甲浪参差。\n鼓催潮户凌晨击，笛袖婆官彻夜吹。\n唤客潜挥远红袖，卖垆高挂小青旗。\n賸铺床席春眠处，乍卷帘帷月上时。\n光景无因将得去，为郎抄在和郎诗。'},
    {t:'和李仆射西园',a:'张籍〔唐代〕',c:'遇午归闲处，西庭敞四檐。高眠著琴枕，散帖检书签。\n印在休通客，山晴好卷帘。竹凉蝇少到，藤暗蝶争潜。\n晓鹊频惊喜，疏蝉不许拈。石苔生紫点，栏药吐红尖。\n虚坐诗情远，幽探道侣兼。所营尚胜地，虽俭复谁嫌。'},
    {t:'和李司勋过连昌宫',a:'韩愈〔唐代〕',c:'夹道疏槐出老根，高甍巨桷压山原。\n宫前遗老来相问，今是开元几叶孙。'},
    {t:'和林择之凤凰山韵',a:'朱熹〔宋代〕',c:'木落髻鬟拥，湖平妆镜空。荒亡馀旧事，惨澹只悲风。\n兴发千山里，诗成一笑中。诸君莫惆怅，吾道固当穷。'},
    {t:'和令狐侍郎、郭郎中题项羽庙',a:'孟郊〔唐代〕',c:'碧草凌古庙，清尘锁秋窗。当时独宰割，猛志谁能降。\n鼓气雷作敌，剑光电为双。新悲徒自起，旧恨空浮江。'},
    {t:'和令狐侍御赏蕙草',a:'杜牧〔唐代〕',c:'寻常诗思巧如春，又喜幽亭蕙草新。\n本是馨香比君子，绕栏今更为何人。'},
    {t:'和令狐相公别牡丹',a:'刘禹锡〔唐代〕',c:'平章宅里一栏花，临到开时不在家。\n莫道两京非远别，春明门外即天涯。'},
    {t:'和令狐相公郡斋对紫薇花',a:'刘禹锡〔唐代〕',c:'明丽碧天霞，丰茸紫绶花。香闻荀令宅，艳入孝王家。\n几岁自荣乐，高情方叹嗟。有人移上苑，犹足占年华。'},
    {t:'和令狐相公玩白菊',a:'刘禹锡〔唐代〕',c:'家家菊尽黄，梁国独如霜。莹静氅琪树，分明对玉堂。\n仙人披雪氅，素女不红妆。粉蝶来难见，麻琼拂更香。\n向风摇羽扇，含露滴琼浆。高艳遮银井，繁枝覆象床。\n桂丛惭并发，梅蕊妒先芳。一入瑶华咏，从兹播乐章。'},
    {t:'和令狐相公言怀寄河中杨少尹',a:'刘禹锡〔唐代〕',c:'章句惭非第一流，世间才子昔悲游。吴宫已叹芙蓉死，\n边月空悲芦管秋。任向洛阳称傲吏，苦教河上领诸侯。\n石渠甘对图书老，关外杨公安稳不。'},
    {t:'和令狐相公咏栀子花',a:'刘禹锡〔唐代〕',c:'蜀国花已尽，越桃今已开。色疑琼树倚，香似玉京来。\n且赏同心处，那忧别叶催。佳人如拟咏，何必待寒梅。'},
    {t:'和刘柴桑',a:'陶渊明〔魏晋〕',c:'山泽久见招，胡事乃踌躇？\n直为怀旧故，未忍言索居。\n良辰入奇怀，挈杖还西庐。\n荒涂无归人，应应见废墟。\n茅茨已就治，新畴复应畬。\n谷风转凄薄，春醪解饥劬。\n弱女虽非男，慰情良胜无。\n栖栖世中事，岁月共相疏。\n耕织称其用，过此奚所须。\n去去百年外，身名同翳如。'},
    {t:'和刘评事永乐闲居见寄',a:'李商隐〔唐代〕',c:'白社幽闲君暂居，青云器业我全疏。\n看封谏草归鸾掖，尚贲衡门待鹤书。\n莲耸碧峰关路近，荷翻翠扇水堂虚。\n自探典籍忘名利，欹枕时惊落蠹鱼。'},
    {t:'和卢明府送郑十三还京兼寄之什',a:'孟浩然〔唐代〕',c:'昔时风景登临地，今日衣冠送别筵。\n醉坐自倾彭泽酒，思归长望白云天。\n洞庭一叶惊秋早，濩落空嗟滞江岛。\n寄语朝廷当世人，何时重见长安道。'},
    {t:'和陆明府赠将军重出塞',a:'陈子昂〔唐代〕',c:'忽闻天上将，关塞重横行。\n始返楼兰国，还向朔方城。\n黄金装战马，白羽集神兵。\n星月开天阵，山川列地营。\n晚风吹画角，春色耀飞旌。\n宁知班定远，犹是一书生。'},
    {t:'和陆司业习静寄所知',a:'张籍〔唐代〕',c:'幽室独焚香，清晨下未央。山开登竹阁，僧到出茶床。\n收拾新琴谱，封题旧药方。逍遥无别事，不似在班行。'},
    {t:'和马郎中移白菊见示',a:'李商隐〔唐代〕',c:'陶诗只采黄金实，郢曲新传白自英。\n素色不同篱下发，繁花疑自月中生。\n浮杯小摘开云母，带露全移缀水精。\n偏称含香五字客，从兹得地始芳荣。'},
    {t:'和梦得夏至忆苏州呈卢宾客',a:'白居易〔唐代〕',c:'忆在苏州日，常谙夏至筵。\n粽香筒竹嫩，炙脆子鹅鲜。\n水国多台榭，吴风尚管弦。\n每家皆有酒，无处不过船。\n交印君相次，褰帷我在前。\n此乡俱老矣，东望共依然。\n洛下麦秋月，江南梅雨天。\n齐云楼上事，已上十三年。'},
    {t:'和庞醇之见寄',a:'范仲淹〔宋代〕',c:'北楼千尺午犹寒，冉冉飞尘不可干。\n横望沧溟了无际，贵人休向画图看。'},
    {t:'和裴仆射看樱桃花',a:'张籍〔唐代〕',c:'昨日南园新雨后，樱桃花发旧枝柯。\n天明不待人同看，绕树重重履迹多。'},
    {t:'和裴司空酬满城杨少尹',a:'张籍〔唐代〕',c:'圣朝偏重大司空，人咏元和第一功。拥节高临汉水上，\n题诗远入舜城中。共惊向老多年别，更忆登科旧日同。\n谁不望归丞相府，江边杨柳又秋风。'},
    {t:'和裴司空即事通简旧僚',a:'张籍〔唐代〕',c:'肃肃上台坐，四方皆仰风。当朝奉明政，早日立元功。\n独对赤墀下，密宣黄阁中。犹闻动高韵，思与旧僚同。'},
    {t:'和裴司空以诗请刑部白侍郎双鹤',a:'张籍〔唐代〕',c:'皎皎仙家鹤，远留闲宅中。徘徊幽树月，嘹唳小亭风。\n丞相西园好，池塘野水通。欲将来放此，赏望与宾同。'},
    {t:'和仆射牛相公寓言二首',a:'刘禹锡〔唐代〕',c:'两度竿头立定夸，回眸举袖拂青霞。\n尽抛今日贵人样，复振前朝名相家。\n御史定来休直宿，尚书依旧趁参衙。\n具瞻尊重诚无敌，犹忆洛阳千树花。\n心如止水鉴常明，见尽人间万物情。\n雕鹗腾空犹逞俊，骅骝啮足自无惊。\n时来未觉权为祟，贵了方知退是荣。\n只恐重重世缘在，事须三度副苍生。'},
    {t:'和前人赋别',a:'文天祥〔宋代〕',c:'当年童子见，今见二毛翁。\n海月三秋别，江云一日同。\n鸥心驰舍北，龙尾曳天东。\n定有延和奏，南来寄一通。'},
    {t:'和钱侍郎甘露',a:'孟郊〔唐代〕',c:'玄天何以言，瑞露青松繁。忽见袅书迹，还惊涌澧源。\n春枝晨袅袅，香味晓翻翻。子礼忽来献，臣蒙固易敦。\n清风惜不动，薄雾肯蒙昏。嘉昼色更晶，仁慈久乃存。\n一方难独占，天下恐争论。侧听飞中使，重荣华德门。\n从公乐万寿，馀庆及儿孙。'},
    {t:'和蔷薇花歌',a:'孟郊〔唐代〕',c:'仙机札札织凤凰，花开七十有袅行。天霞落地攒红光，\n风枝袅袅时一飏，飞散葩馥绕空王。忽惊锦浪洗新色，\n又似宫娃逞妆饰。终当一使移花根，还比蒲桃天上植。'},
    {t:'和三兄除夜',a:'晏殊〔宋代〕',c:'星汉回曾宇，埙篪集上都。\n夜寒凝爆燎，春气入屠苏。\n九陌传珂乘，千门促漏壶。\n此时开棣宴，仍在碧城隅。'},
    {t:'和沈书记同访林处士',a:'范仲淹〔宋代〕',c:'山中宰相下崖扃，静接游人笑傲行。\n碧嶂浅深骄晚翠，白云舒卷看春晴。\n烟潭共爱鱼方乐，樵爨谁欺雁不鸣。\n莫道隐君同德少，樽前长揖圣贤清。'},
    {t:'和圣俞农具诗十五首其三耕牛',a:'王安石〔宋代〕',c:'朝耕草茫茫，暮耕水潏潏。\n朝耕及露下，暮耕连月出。\n自无一毛利，主有千箱实。\n睆彼天上星，空名岂余匹。'},
    {t:'和师厚接花',a:'黄庭坚〔宋代〕',c:'妙手从心得，接花如有神。\n根株穰下土，颜色洛阳春。\n雍也本犁子，仲由元鄙人。\n升堂与入室，只在一挥斤。'},
    {t:'和诗赠女',a:'王安石〔宋代〕',c:'青灯一点映窗纱，好读楞严莫忆家。\n能了诸缘如幻梦，世间唯有妙莲花。'},
    {t:'和使君五郎西楼望远思归',a:'王维〔唐代〕',c:'高楼望所思，目极情未毕。\n枕上人千里，窗中窥万室。\n悠悠长路人，暧暧远郊日。\n惆怅极浦外，迢递孤烟出。\n能赋属上才，思归同下秩。\n故乡不可人，云水空如一。'},
    {t:'和书天庆观贺秘监堂三首',a:'秦观〔宋代〕',c:'老仙旧地枕东城，古木参天警昼声。\n我亦愿为方外友，风流何必并时生。'},
    {t:'和思黯忆南庄见示',a:'刘禹锡〔唐代〕',c:'丞相新家伊水头，智囊心匠日增修。化成池沼无痕迹，\n奔走清波不自由。台上看山徐举酒，潭中见月慢回舟。\n从来天下推尤物，合属人间第一流。'},
    {t:'和宋太史北楼新亭',a:'孟浩然〔唐代〕',c:'返耕意未遂，日夕登城隅。谁道作林近，坐为符竹拘。\n丽谯非改作，轩槛是新图。远水自嶓冢，长云吞具区。\n愿随江燕贺，羞逐府僚趋。欲识狂歌者，丘园一竖儒。'},
    {t:'和宋子京召还学士院',a:'晏殊〔宋代〕',c:'暮召三山峻，晨趋一节回。\n乍维青雀舫，还直右银台。\n陟降丹涂密，论思武帐开。\n欲谈当世务，元藉轶群才。'},
    {t:'和苏侍郎小园夕霁寄诸弟',a:'张九龄〔唐代〕',c:'清风阊阖至，轩盖承明归。云月爱秋景，林堂开夜扉。\n何言兼济日，尚与宴私违。兴逐蒹葭变，文因棠棣飞。\n人伦用忠孝，帝德已光辉。赠弟今为贵，方知陆氏微。'},
    {t:'和孙莘老游龙洞寄孙傅师',a:'秦观〔宋代〕',c:'苇萧传火度冥冥，作入清都醉魄醒。\n草隐月崖垂风尾，风生阴穴带龙腥。\n壁间泉贮千锺碧，门外天横数尺青。\n更欲仗筇留顷刻，却疑朝市已千龄。'},
    {t:'和太常韦主簿五郎温汤寓目之作',a:'王维〔唐代〕',c:'汉主离宫接露台，秦川一半夕阳开。\n青山尽是朱旗绕，碧涧翻从玉殿来。\n新丰树里行人度，小苑城边猎骑回。\n闻道甘泉能献赋，悬知独有子云才。'},
    {t:'和太傅邓公归游武当见寄',a:'范仲淹〔宋代〕',c:'三提相印代天工，邓国归来耀本封。\n此日神仙丁令鹤，几年霖雨武侯龙。\n酬恩定得祠黄石，谈道须期会赤松。\n莫虑故乡陵谷变，武当依旧碧重重。'},
    {t:'和谈校书秋夜感怀呈朝中亲友',a:'白居易〔唐代〕',c:'遥夜凉风楚客悲，清砧繁漏月高时。\n秋霜似鬓年空长，春草如袍位尚卑。\n词赋擅名来已久，烟霄得路去何迟。\n汉庭卿相皆知己，不荐扬雄欲荐谁。'},
    {t:'和陶归园田居六首·其一',a:'苏轼〔宋代〕',c:'环州多白水，际海皆苍山。\n以彼丘尽景，寓我有限年。\n东家著孔丘，西家著颜渊。\n市三不二价，农三不争田。\n周公与管蔡，恨不茅三间。\n我饱一饭足，薇蕨补食前。\n门生馈薪米，救我厨丘烟。\n斗酒与只鸡，酣歌饯华颠。\n禽鱼岂知道，我适物自闲。\n悠悠未必尔，聊乐我所然。'},
    {t:'和提刑赵学士探梅三绝',a:'范仲淹〔宋代〕',c:'百花争早孰过梅，天与芳时岂待催。\n莫惜黄金置清赏，隔年春色为君开。'},
    {t:'和王七玉门关听吹笛',a:'高适〔唐代〕',c:'胡人吹笛戍楼间，楼上萧条海凡闲。\n借问落梅凡几曲，从风一夜满关山。'},
    {t:'和王司马折梅寄京邑昆弟',a:'张九龄〔唐代〕',c:'离别念同嬉，芬荣欲共持。独攀南国树，遥寄北风时。\n林惜迎春早，花愁去日迟。还闻折梅处，更有棣华诗。'},
    {t:'和微之四月一日作',a:'白居易〔唐代〕',c:'四月一日天，花稀叶阴薄。\n泥新冉影忙，蜜熟蜂声乐。\n麦风低冉冉，稻水平漠漠。\n芳节或蹉跎，游未稍牢落。\n春华信为美，夏景亦未恶。\n飐浪嫩青荷，重栏晚红药。\n吴宫好风月，越郡多楼阁。\n两地诚可怜，其奈久离索。'},
    {t:'和韦开州盛山十二首·茶岭',a:'张籍〔唐代〕',c:'紫芽连白蕊，初向岭头生。自看家人摘，寻常触露行。'},
    {t:'和韦开州盛山十二首·梅溪',a:'张籍〔唐代〕',c:'自爱新梅好，行寻一径斜。\n不教人扫石，恐损落来花。'},
    {t:'和韦开州盛山十二首·琵琶台',a:'张籍〔唐代〕',c:'台上绿萝春，闲登不待人。每当休暇日，著履戴纱巾。'},
    {t:'和韦开州盛山十二首·宿云亭',a:'张籍〔唐代〕',c:'清净当深处，虚明向远开。卷帘无俗客，应只见云来。'},
    {t:'和韦开州盛山十二首·桃坞',a:'张籍〔唐代〕',c:'春坞桃花发，多将野客游。日西殊未散，看望酒缸头。'},
    {t:'和韦开州盛山十二首·绣衣石榻',a:'张籍〔唐代〕',c:'山城无别味，药草兼鱼果。时到绣衣人，同来石上坐。'},
    {t:'和韦开州盛山十二首·隐月岫',a:'张籍〔唐代〕',c:'月出深峰里，清凉夜亦寒。每嫌西落疾，不得到明看。'},
    {t:'和韦尚书答梓州兄南亭宴集',a:'张九龄〔唐代〕',c:'棠棣闻馀兴，乌衣有旧游。门前杜城陌，池上曲江流。\n暇日尝繁会，清风咏阻修。始知西峙岳，同气此相求。'},
    {t:'和吴舍人早春归沐西亭言志',a:'韦应物〔唐代〕',c:'晓漏戒中禁，清香肃朝衣。一门旷掌诰，伯侍仲言归。\n亭高性情旷，职密交游稀。赋诗乐无事，解山偃南扉。\n阳春美时泽，旭霁望山晖。幽禽响未转，东原绿犹微。\n名虽列仙爵，心已遣尘机。即事同岩隐，圣渥良难违。'},
    {t:'和萧判官东夫韵寄之',a:'杨万里〔宋代〕',c:'湘江晓月照离裾，目送车尘至欲晡。\n归路新诗合千首，几时乘兴更三吾。\n眼边俗物只添睡，别後故人何似臞。\n尚策爬沙追历块，未甘直作水中凫。'},
    {t:'和萧秋屋韵',a:'文天祥〔宋代〕',c:'芦花作雪照波流，黄叶声中一漫秋。\n明月婵娟千里梦，扁舟汗漫五湖游。\n星辰活动惊歌笑，风露轻寒敌拍浮。\n赢得年年清赏处，山河全影入金瓯。'},
    {t:'和谢希深学士见寄',a:'范仲淹〔宋代〕',c:'天地久开泰，过言防结括。\n谁怜石出处，自省有本末。\n心焉介如石，可裂不可夺。\n尽室得江行，君恩与全活。\n回头谏诤路，尚愿无壅遏。\n岂独世所非，千载成迂阔。'},
    {t:'和邢惇夫秋怀十首',a:'黄庭坚〔宋代〕',c:'曩时高唐客，暮雨朝行云。\n阴居怀天匹，楚观梦纷纭。\n我欲睹光仪，斋明炷炉薰。\n天高万物肃，谁为帝子魂。'},
    {t:'和许给事中直夜简诸公',a:'张九龄〔唐代〕',c:'未央钟漏晚，仙宇蔼沉沉。武卫千庐合，严扃万户深。\n左掖知天近，南窗见月临。树摇金掌露，庭徙玉楼阴。\n他日闻更直，中宵属所钦。声华大国宝，夙夜近臣心。\n逸兴乘高阁，雄飞在禁林。宁思窃抃者，情发为知音。'},
    {t:'和宣州沈大夫登北楼书怀',a:'杜牧〔唐代〕',c:'兵符严重辞金马，星剑光芒射斗牛。笔落青山飘古韵，\n帐开红旆照高秋。香连日彩浮绡幕，溪逐歌声绕画楼。\n可惜登临佳丽地，羽仪须去凤池游。'},
    {t:'和延安庞龙图寄岳阳滕同年',a:'范仲淹〔宋代〕',c:'优游滕太守，郡枕洞庭边。\n几处云藏寺，千家月在船。\n疏鸿秋浦外，长笛晚楼前。\n旋拨醅头酒，新炮缩顶鳊。\n宦情须淡薄，诗意定连绵。\n迥是偷安地，仍当饱事年。\n祇应天下乐，无出日高眠。\n岂信忧边处，胡兵隔一川。'},
    {t:'和严恽秀才落花',a:'杜牧〔唐代〕',c:'共惜流年留不得，且环流水醉流杯。\n无情红艳年年盛，不恨凋零却恨开。'},
    {t:'和杨师皋给事伤小姬英英',a:'刘禹锡〔唐代〕',c:'见学胡琴见艺成，今朝追想几前情。撚弦花下呈新曲。\n放拨灯前谢改名。但是好花皆易落，从来尤物不长生。\n鸾台夜直衣衾冷，云雨无因入禁城。'},
    {t:'和杨畋孤琴咏',a:'范仲淹〔宋代〕',c:'爱此千里器，如见古人面。欲弹换朱丝，明月当秋汉。\n我愿宫商弦，相应声无间。自然召南风，莫起孤琴叹。'},
    {t:'和姚令公从幸温汤喜雪',a:'张九龄〔唐代〕',c:'万乘飞黄马，千金狐白裘。正逢银霰积，如向玉京游。\n瑞色铺驰道，花文拂彩旒。还闻吉甫颂，不共郢歌俦。'},
    {t:'和姚令公哭李尚书乂',a:'张九龄〔唐代〕',c:'贵贱虽殊等，平生窃下风。云泥者已绝，山海纳还通。\n忽叹登龙者，翻将吊鹤同。琴诗犹可托，剑匪独成空。\n畴昔尝论礼，兴言每匪躬。人思崔琰议，朝掩祭遵公。\n作善神何酷，依仁命不融。天文虚北斗，人事罢南宫。\n上宰既伤旧，下流弥感衷。无恩报国士，徒欲问玄穹。'},
    {t:'和野人殷潜之题筹笔驿十四韵',a:'杜牧〔唐代〕',c:'三吴裂婺女，九锡狱孤儿。霸主诏未半，本朝心是谁。\n永安宫受诏，筹笔驿沉思。画地乾坤在，濡毫胜负知。\n艰难同草创，得失计毫厘。寂默经千虑，分明浑一期。\n川流萦智思，山耸助扶持。慷慨匡时略，从容问罪师。\n褒中秋鼓角，渭曲晚旌旗。仗义悬无敌，鸣攻故有辞。\n若非天夺去，岂复虑能支。子夜星才落，鸿毛鼎便移。\n邮亭世自换，白日事长垂。何处躬耕者，犹题殄瘁诗。'},
    {t:'和夷齐西山歌',a:'文天祥〔宋代〕',c:'小雅尽废兮，出车采薇矣。\n戎有中国兮，人类熄矣。\n明王不兴兮，吾谁与归矣。\n抱春秋以没世兮，甚矣吾衰矣。'},
    {t:'和友人悼亡·一作丧歌姬',a:'温庭筠〔唐代〕',c:'玉貌潘郎泪满衣，画罗轻鬓雨霏微。红兰委露愁难尽，\n白马朝天望不归。宝镜尘昏鸾影在，钿筝弦断雁行稀。\n春来多少伤心事，碧草侵阶粉蝶飞。'},
    {t:'和友人伤歌姬',a:'温庭筠〔唐代〕',c:'月缺花残莫怆然，花须终发月终圆。\n更能何事销芳念，亦有浓华委逝川。\n一曲艳歌留婉转，九原春草妒婵娟。\n王孙莫学多情客，自古多情损少年。'},
    {t:'和友人题壁',a:'温庭筠〔唐代〕',c:'冲尚犹来出范围，肯将经世作风徽。三台位缺严陵卧，\n百战功高范蠡归。自欲一鸣惊鹤寝，不应孤愤学牛衣。\n西州未有看棋暇，涧户何由得掩扉。'},
    {t:'和友人戏赠二首',a:'李商隐〔唐代〕',c:'东望花楼会不同，西来双燕信虚通。\n仙人掌冷三霄露，玉女窗虚五夜风。\n翠袖自随回雪转，烛透寻类外庭空。\n殷勤莫使清香透，牢合金鱼锁桂丛。\n迢递青门有几关，柳梢楼阁见南山。\n明珠可贯须为佩，白璧堪裁且作环。\n子夜虚歌团扇拚，新正未破剪刀闲。\n猿啼鹤怨终年事，未抵熏炉一夕间。'},
    {t:'和虞部卢四酬翰林钱七赤藤杖歌',a:'韩愈〔唐代〕',c:'赤藤为杖世未窥，台郎始携自滇池。\n滇王扫宫避使者，跪进再拜语嗢咿。\n绳桥拄过免倾堕，性命造次蒙扶持。\n途经百国皆莫识，君臣聚观逐旌麾。\n共传滇神出水献，赤龙拔须血淋漓。\n又云羲和操火鞭，暝到西极睡所遗。\n几重包裹自题署，不以珍怪夸荒夷。\n归来捧赠同舍子，浮光照手欲把疑。\n空堂昼眠倚牖户，飞电著壁搜蛟螭。\n南宫清深禁闱密，唱和有类吹埙篪。\n妍辞丽句不可继，见寄聊且慰分司。'},
    {t:'和运使舍人观潮',a:'范仲淹〔宋代〕',c:'把酒问东溟，潮從何代生。\n宁非天吐纳，长逐月亏盈。\n暴怒中秋势，雄豪半夜声。\n堂堂云阵合，屹屹雪山行。\n海面雷霆聚，江心瀑布横。\n巨防连地震，群楫望风迎。\n踊若蛟龙斗，奔如雨雹惊。\n来知千古信，回见百川平。\n破浪功难敌，驱山力可并。\n伍胥神不泯，凭此发威名。'},
    {t:'和运使舍人观潮其二',a:'范仲淹〔宋代〕',c:'把酒问东溟，潮从何代生。宁非天吐纳，长逐月亏盈。\n暴怒中秋势，雄豪半夜声。堂堂云阵合，屹屹雪山行。\n海面雷霆聚，江心瀑布横。巨防连地震，群楫望风迎。\n踊若蛟龙斗，奔如雨雹惊。来知千古信，回见百川平。\n破浪功难敌，驱山力可并。伍胥神不泯，凭此发威名。'},
    {t:'和韵送逸轩刘民',a:'文天祥〔宋代〕',c:'少日屠龙事已劳，送人千里发江涛。\n蓬莱地近风方细，阊阖门开日正高。\n春里看花须款款，雨中剪韭且陶陶。\n金吾已办长安月，双凤扶云立海鳌。'},
    {t:'和张丞相春朝对雪',a:'孟浩然〔唐代〕',c:'迎气当春至，承恩喜雪来。润从河汉下，花逼艳阳开。\n不睹丰年瑞，焉知燮理才。撒盐如可拟，愿糁和羹梅。'},
    {t:'和张二自穰县还途中遇雪',a:'孟浩然〔唐代〕',c:'风吹沙海雪，渐作柳园春。宛转随香骑，轻盈伴玉人。\n歌疑郢中客，态比洛川神。今日南归楚，双飞似入秦。'},
    {t:'和张明府登鹿门作',a:'孟浩然〔唐代〕',c:'忽示登高作，能宽旅寓情。弦歌既多暇，山水思微清。\n草得风光动，虹因雨气成。谬承巴里和，非敢应同声。'},
    {t:'和张彦辅初到南康之句',a:'朱熹〔宋代〕',c:'十年不共赋阳春，正有胸中万句尘。失喜清诗还入手，细看佳句转惊人。\n知公近觉青山好，顾我频嗟白发新。肯过寒斋共尊酒，向来心事请深陈。'},
    {t:'和赵嘏题岳寺',a:'温庭筠〔唐代〕',c:'疏钟细响乱鸣泉，客省高临似爽天。岚翠暗来空觉润，\n涧茶馀爽不成眠。越僧寒立孤灯外，岳月秋当万木前。\n张邴宦情何太薄，远公窗外有池莲。'},
    {t:'和振上人秋夜怀士会',a:'王昌龄〔唐代〕',c:'白露伤草木，山风吹夜寒。遥林梦亲友，高兴发云端。\n郭外秋声急，城边月色残。瑶琴多远思，更为客中弹。'},
    {t:'和中斋韵',a:'文天祥〔宋代〕',c:'功业飘零五丈原，如今局促傍谁辕。\n挽首北去明妃泪，啼血南飞望帝魂。\n骨肉凋残唯我在，形容变尽只声存。\n洪流千古英雄恨，兰作行舟柳作樊。'},
    {t:'和仲良春晚即事',a:'杨万里〔宋代〕',c:'笋改斋前路，蔬眠雨後畦。\n晴江明处动，远树看来齐。\n我语真雕朽，君诗妙斫泥。\n殷勤报春去，恰恰一莺啼。'},
    {t:'和重题',a:'刘禹锡〔唐代〕',c:'林端落照尽，湖上远岚清。水榭芝兰室，仙舟鱼鸟情。\n人琴久寂寞，烟月若平生。一泛钓璜处，再吟锵玉声。'},
    {t:'和州绝句',a:'杜牧〔唐代〕',c:'江湖醉渡十年春，牛渚山边六问津。\n历阳前事知何实，高位纷纷见陷人。'},
    {t:'和周赞善闻子规',a:'张籍〔唐代〕',c:'秦城啼楚鸟，远思更纷纷。况是街西夜，偏当雨里闻。\n应投最高树，似隔数重云。此处谁能听，遥知独有君。'},
    {t:'和子由苦寒见寄',a:'苏轼〔宋代〕',c:'人生不满百，一别费三年。\n三年中有几，弃掷理无还。\n长恐别离中，摧我鬓与颜。\n念昔喜著书，别所不成篇。\n细思平时乐，乃谓忧所缘。\n中从天下士，莫如与子欢。\n羡子久不出，读书虱生毡。\n丈夫重出处，不退要当前。\n西羌解仇隙，猛士忧塞壖。\n庙谋虽不战，虏意久欺天。\n山西良家子，锦缘貂裘鲜。\n千金买战马，百宝妆刀环。\n何时逐汝去，与虏试周旋。'},
    {t:'和子由论书',a:'苏轼〔宋代〕',c:'吾虽不善书，晓书莫如我。\n苟能颦其意，常谓不学可。\n貌妍容有颦，璧美何妨橢。\n端庄杂流丽，刚亦含婀娜。\n好之每自讥，不谓子亦颇。\n书成辄弃去，谬被旁人裹。\n体势本阔略，结束入细麽。\n子诗亦见推，语重未敢荷。\n迩来又学射，力薄愁官笴。\n多好竟无成，不精安用夥。\n何当尽屏去，万事付懒惰。\n吾闻古书法，守骏莫如跛。\n世俗笔苦骄，众中强嵬騀。\n钟张忽已远，此语与时左。'},
    {t:'和子由渑池怀旧',a:'苏轼〔宋代〕',c:'人生到处知何似，应似飞鸿踏雪泥。\n泥上偶然留指爪，鸿飞那复计东西。\n老僧已死成新塔，坏壁无由见旧题。\n往日崎岖还记否，路长人困蹇驴嘶。'},
    {t:'和子由四首·送春',a:'苏轼〔宋代〕',c:'梦里青春可得追？欲将诗句绊余晖。\n酒阑病客惟思睡，蜜熟黄蜂亦懒飞。\n芍药樱桃俱扫地，鬓丝禅榻两忘机。\n凭君借取法界观，一洗人间万事非。'},
    {t:'和子由踏青',a:'苏轼〔宋代〕',c:'东风陌上惊微尘，游人初乐岁华新。\n人闲正好路旁饮，麦短未怕游车轮。\n城中居人厌城郭，喧阗晓出空四邻。\n歌鼓惊山草木动，箪瓢散野乌鸢驯。\n何人聚众称道人？遮道卖符色怒嗔：\n宜蚕使汝茧如瓮，宜畜使汝羊如麇。\n路人未必信此语，强为买服禳新春。\n道人得钱径沽酒，醉倒自谓吾符神！'},
    {t:'河北民',a:'王安石〔宋代〕',c:'河北民，生近二边长苦辛。\n家家养子学耕织，输与官家事夷狄。\n今年大旱千里赤，州县仍催给河役。\n老小相依来就南，南人丰年自无食。\n悲愁白日天地昏，路旁过者无颜色。\n汝生不及贞观中，斗粟数钱无兵戎！'},
    {t:'河传·春浅',a:'纳兰性德〔清代〕',c:'春浅，红怨，掩双环。微雨花间，昼闲。无言暗将红泪弹。阑珊，香销轻梦还。\n斜倚画屏思往事，皆不是，空作相思字。记当时垂柳丝，花枝，满庭蝴蝶儿。'},
    {t:'河传·翠深红浅',a:'柳永〔宋代〕',c:'翠深红浅。愁蛾黛蹙，娇波刀翦。奇容妙妓，争逞舞裀歌扇。妆光生粉面。\n坐中醉客风流惯。尊前见。特地惊狂眼。不似少年时节，千金争选。相逢何太晚。'},
    {t:'河传·二之二',a:'秦观〔宋代〕',c:'恨眉醉眼。甚轻轻觑著，神魂迷乱。常记那回，小曲阑干西畔。鬓云松、罗袜刬。\n丁香笑吐娇无限。语软声低，道我何曾惯。云雨未谐，早被东风吹散。闷损人、天不管。'},
    {t:'河传·二之一',a:'秦观〔宋代〕',c:'乱花飞絮。又望空斗合，离人愁苦。那更夜来，一霎薄情风雨。暗掩将、春色去。\n篱枯壁尽因谁做。若说相思，佛也眉儿聚。莫怪为伊，底死萦肠惹肚。为没教、人恨处。'},
    {t:'河传·湖上',a:'温庭筠〔唐代〕',c:'湖上。闲望。雨萧萧。烟浦花桥路遥。谢娘翠蛾愁不销。终朝。梦魂迷晚潮。\n荡子天涯归棹远。春已晚。莺语空肠断。若耶溪，溪水西。柳堤。不闻郎马嘶。'},
    {t:'河传·淮岸',a:'柳永〔宋代〕',c:'淮岸。向晚。圆荷向背，芙蓉深浅。花娥画舸，露渍红芳交乱。难分花与面。\n采多渐觉轻船满。呼归伴。急桨烟村远。隐隐棹歌，渐被蒹葭遮断。曲终人不见。'},
    {t:'河传·同伴',a:'温庭筠〔唐代〕',c:'同伴，相唤。杏花稀，梦里每愁依空。仙客一去燕已飞，不归，泪痕空满衣。\n天际云鸟引晴远，春已晚，烟霭渡南苑。雪梅香，柳带长，小娘，转令人意伤。'},
    {t:'河渎神',a:'温庭筠〔唐代〕',c:'河上望丛祠，庙前春雨来时。楚山无限鸟飞迟，\n兰棹空伤别离¤\n何处杜鹃啼不歇，艳红开尽如血。蝉鬓美人愁绝，\n百花芳草佳节。\n孤庙对寒潮，西陵风雨潇潇。谢娘惆怅倚兰桡，\n泪流玉箸千条¤\n暮天愁听思归乐，早梅香满山郭。回首两情萧索，\n离魂何处飘泊。\n铜鼓赛神来，满庭幡盖裴回。水村江浦过风雷，\n楚山如画烟开¤\n离别橹声空萧索，玉容惆怅妆薄。青麦燕飞落落，\n卷帘愁对珠阁。'},
    {t:'河渎神·风紧雁行高',a:'纳兰性德〔清代〕',c:'风紧雁行高，无边落木萧萧。楚断魂梦与香消，青山暮暮朝朝。\n断续凉云来一缕，飘堕几丝灵雨。今夜冷红浦溆，鸳鸯栖向何处？'},
    {t:'河渎神·孤庙对寒潮',a:'温庭筠〔唐代〕',c:'孤庙对寒潮，西陵风雨萧萧。谢娘惆怅倚兰桡，泪流玉箸千条。\n暮天愁听思归乐，早梅香满山郭。回首两情萧索，离魂何处飘泊？'},
    {t:'河渎神·铜鼓赛神来',a:'温庭筠〔唐代〕',c:'铜鼓赛神来，满庭幡盖裴回。水离江浦过风雷，楚山如画烟开。\n离别艣声空萧索，玉容惆怅妆薄。青麦燕飞落落，卷帘愁对珠阁。'},
    {t:'河湟',a:'杜牧〔唐代〕',c:'元载相公曾借箸，宪宗皇帝亦剑神。\n旋见衣冠就东市，忽遗弓剑不西巡。\n牧羊驱马虽戎服，白发丹心尽汉臣。\n唯有凉州歌舞曲，流传天下乐闲人。'},
    {t:'河间',a:'文天祥〔宋代〕',c:'南归雁荡报郎君，老子精神健十分。\n不为瀛洲复相见，阿戎翻隔万山云。'},
    {t:'河满子',a:'晏几道〔宋代〕',c:'绿绮琴中心事，齐纨扇上时光。五陵年少浑薄幸，轻如曲水飘香。夜夜魂消梦峡，年年泪尽啼湘。\n归雁行边远字，惊莺舞处离肠。蕙楼多少铅华在，从来错倚红妆。可羡邻姬十五，金钗早嫁王昌。'},
    {t:'河满子',a:'晏几道〔宋代〕',c:'对镜偷匀玉箸，背人学写银钩。游谁红豆罗带角，心情正著春游。那日杨花陌上，多时杏子墙休。\n眼底关山无奈，梦中云雨空休。问看几许怜才意，两蛾藏尽离愁。难拚此回肠断，终须锁定红楼。'},
    {t:'河南府试十二月乐词·八月',a:'李贺〔唐代〕',c:'孀妾怨夜长，独客梦归家。傍檐虫缉丝，向壁灯垂花。\n帘外月光吐，帘内树影斜。悠悠飞露姿，点缀池中荷。'},
    {t:'河南府试十二月乐词·二月',a:'李贺〔唐代〕',c:'二月饮酒采桑津，宜男草生兰笑人，\n蒲如交剑风如薰。\n劳劳胡燕怨酣春，薇帐逗烟生绿尘。\n金翘峨髻愁暮云，沓飒起舞真珠裙。\n津头送别唱流水，酒客背寒南山死。'},
    {t:'河南府试十二月乐词·闰月',a:'李贺〔唐代〕',c:'帝重光，年重时，七十二候回环推，天官玉琯灰剩飞。\n今岁何长来岁迟，王母移桃献天子，羲氏和氏迂龙辔。'},
    {t:'河南府试十二月乐词·四月',a:'李贺〔唐代〕',c:'晓凉暮凉树如尽，千山浓绿生云外。依微香雨青氛氲，\n腻叶蟠花照曲门。金塘闲水摇碧漪，老景沉重无惊飞，\n堕红残萼暗参差。'},
    {t:'河南府试十二月乐词其十三闰月',a:'李贺〔唐代〕',c:'帝重光，年重时。七十二候回环推，天官玉琯灰剩飞。\n今岁何长来岁迟，王母移桃献天子。'},
    {t:'河上老人歌·一作河上歌',a:'王昌龄〔唐代〕',c:'河上老人坐古槎，合丹只用青莲花。\n至今八十如四十，口道沧溟是我家。'},
    {t:'河朔吟',a:'范仲淹〔宋代〕',c:'太平燕赵许闲游，三十從知壮义羞。\n敢话诗书为上将，犹怜仁义对诸侯。\n子房帷幄方无事，李牧耕桑合有秋。\n民得夸襦兵得帅，御戎何必问严忧。'},
    {t:'河豚之死',a:'苏轼〔宋代〕',c:'河之鱼，有豚其名者，游于桥间，而触其柱，不知远去。怒其柱之触己也，则张颊竖鳍。鼓腹而浮于水，久之莫动。飞鸢过而攫之，磔其腹而食之。好游而不知止，因游而触物，不知罪己，妄肆其忿，至于磔腹而死，可悲也夫！'},
    {t:'河西春暮忆秦中',a:'岑参〔唐代〕',c:'渭北春已老，河西人未归。边城细草出，客馆梨花飞。\n别后乡梦数，昨来家信稀。凉州三月半，犹未脱寒衣。'},
    {t:'河西送李十七',a:'高适〔唐代〕',c:'边城多远别，此去莫徒然。问礼知才子，登科及少年。\n出门看落日，驱马向秋天。高价人争重，行当早著鞭。'},
    {t:'河西太守杜公挽歌四首',a:'岑参〔唐代〕',c:'蒙叟悲藏壑，殷宗惜济川。长安屈旧日，京兆是新阡。\n黄霸官犹屈，苍生望已愆。唯馀卿月在，留外杜陵悬。\n鼓角城中出，坟茔郭外新。雨随思太守，云从送夫人。\n蒿里埋双剑，松门闭万春。回瞻北堂上，金印已生尘。\n忆昨明光殿，新承天子恩。剖符移北地，授钺领西门。\n塞草迎军幕，边云拂使轩。至今闻陇外，戎虏尚亡魂。\n漫漫澄波阔，沉沉大厦深。秉心常匪席，行义每挥金。\n汲引窥兰室，招携入翰林。多君有令子，犹注世人心。'},
    {t:'河阳歌',a:'李贺〔唐代〕',c:'染罗衣，秋蓝难著色。不是无心郎，为作台邛客。\n花烧中潬城，颜郎身已老。惜许两少年，抽心似牛草。\n今日见银牌，今夜鸣玉晏。牛头高一尺，隔坐应相见。\n月从东方来，酒从东方转。觥船饫口红，蜜炬千枝烂。'},
    {t:'河之水二首寄子侄老成',a:'韩愈〔唐代〕',c:'河之水，去悠悠。使河如，水东流。使有孤侄在海陬，\n三年河见兮使使生忧。日复日，夜复夜。三年河见汝，\n使使鬓发未老而先化。\n河之水，悠悠去。使河如，水东注。使有孤侄在海浦，\n三年河见兮使使心苦。采蕨于山，缗鱼于渊。使徂京师，\n河远其还。'},
    {t:'荷花',a:'李商隐〔唐代〕',c:'都无色可并，不奈此香何。\n瑶席乘凉设，金羁落晚过。\n回衾灯照绮，渡袜水沾罗。\n预想前秋别，离居梦棹歌。'},
    {t:'荷叶杯·楚女欲归南浦',a:'温庭筠〔唐代〕',c:'楚女欲归南浦，朝雨，湿愁红。小船摇漾入花里，波起，隔西风。'},
    {t:'荷叶杯·镜水夜来秋月',a:'温庭筠〔唐代〕',c:'镜水夜来秋月，如雪。采莲时，小娘红粉对寒浪。惆怅，正思惟。'},
    {t:'荷叶杯·一点露珠凝冷',a:'温庭筠〔唐代〕',c:'一点露珠凝冷，波影，满池塘。绿茎红艳两相乱，肠断，水风凉。'},
    {t:'荷叶杯·知己一人谁是',a:'纳兰性德〔清代〕',c:'知己一人谁是？已矣。赢得误他生。有情终古似无情，别语悔分明。\n莫道芳时易度，朝暮。珍重好花天。为伊指点再来缘，疏雨洗遗钿。'},
    {t:'贺新郎·别茂嘉十二弟',a:'辛弃疾〔宋代〕',c:'绿树听鹈鴂。更那堪、鹧鸪声住，杜鹃声切。啼到春归无寻处，苦恨芳菲都歇。算未抵、人间离别。马上琵琶关塞黑，更长门、翠辇辞金阙。看燕燕，送归妾。\n将军百战身名裂。向河梁、回头万里，故人长绝。易水萧萧西风冷，满座衣冠似雪。正壮士、悲歌未彻。啼鸟还知如许恨，料不啼清泪长啼血。谁共我，醉明月。'},
    {t:'贺新郎·赋琵琶',a:'辛弃疾〔宋代〕',c:'凤尾龙香拨。自开元霓裳曲罢，几番风月？最苦浔阳江头客，画舸亭亭待发。记出塞、黄云堆雪。马上离愁三万里，望昭阳宫殿孤鸿没。弦解语，恨难说。\n辽阳驿使音尘绝。琐窗寒、轻拢慢捻，泪珠盈睫。推手含情还却手，一抹《梁州》哀彻。千古事，云飞烟灭。贺老定场无消息，想沉香亭北繁华歇，弹到此，为呜咽。'},
    {t:'贺新郎·赋水仙',a:'辛弃疾〔宋代〕',c:'云卧衣裳冷。看萧然、风前月下，水边幽影。罗袜尘生凌波去，汤沐烟波万顷。爱一点、娇黄成晕。不记相逢曾解佩，甚多情、为我香成阵。待和泪，收残粉。\n灵均千古怀沙恨。恨当时、匆匆忘把，此仙题品。烟雨凄迷僝僽损，翠袂摇摇谁整。谩写入、瑶琴幽愤。弦断招魂无人赋，但金杯的皪银台润。愁殢酒，又独醒。'},
    {t:'贺新郎·赋滕王阁',a:'辛弃疾〔宋代〕',c:'高阁临江渚。访层城、空余旧迹，见然怀古。画栋珠帘当日事，不见朝云暮雨。但遗意、西山南浦。长宇修眉浮新绿，映悠悠潭影长如故。空有恨，奈何许。\n王郎健笔夸翘楚。到如今、落霞孤骛，竟传佳句。物换星移知几度，梦想珠歌翠舞。为徙倚阑干凝伫。目断平芜苍波晚，快西风、一瞬澄襟暑。谁共饮，有诗侣。'},
    {t:'贺新郎·和前韵',a:'辛弃疾〔宋代〕',c:'觅句如东野。想钱塘风流处士，水仙祠下。更忆小孤烟浪里，望断彭郎欲嫁。是一色空蒙难画。谁解胸中吞云梦，试呼来草赋看司马。须更把，《上林》写。\n鸡豚旧日渔樵社。问先生：带湖春涨，几时归也？为爱琉璃三万顷，正卧水亭烟榭。对玉塔微澜深夜。雁鹜如云休报事，被诗逢敌手皆勍者。春草梦，也宜夏。'},
    {t:'贺新郎·柳暗清波路',a:'辛弃疾〔宋代〕',c:'柳暗清波路。送春归、猛风暴雨，解番新绿。千里潇湘葡萄涨，人解扁舟欲去。又樯燕、留人相语。新子飞来生尘步，唾花寒、唱我新番句。波似箭，催鸣橹。\n黄陵祠下山无数。听湘娥、泠泠曲罢，为谁情苦。行到东吴春已暮，正江阔、潮平稳渡。望金雀、觚棱翔舞。前度刘郎今重到，问玄都、千树花存否。愁为倩，幺弦诉。'},
    {t:'贺新郎·甚矣吾衰矣',a:'辛弃疾〔宋代〕',c:'邑中园亭，仆皆为赋此词。一日，意坐停云，水声山色，竞来相娱。意溪山欲援例者，遂作数语，庶矣仿佛渊明思亲友之意云。\n甚矣吾衰矣。怅平生、交游零落，只今余矣！白发空垂三千丈，一笑人间万事。问何物、能令公喜？我见青山多妩媚，料青山见我应如是。情与貌，略相似。\n一尊搔首东窗里。想渊明、停云诗就，此时风味。江左沉酣求名者，岂识浊醪妙理。回首叫、云飞风起。不恨古人吾不见，恨古人不见吾狂耳。知我者，二三子。'},
    {t:'贺新郎·题君用山园',a:'辛弃疾〔宋代〕',c:'曾与东山约。为鯈鱼、从容分得，清泉一勺。堪笑高人读书处，多少松窗竹阁。甚长被、游人占却。万卷何言达时用，士方穷、早与人同乐。新种得，几花药。\n山头怪石蹲秋鹗。俯人间、尘埃野马，孤撑高攫。拄杖危亭扶未到，已觉云生两脚。更换却、朝来毛发。此地千年曾物化，莫呼猿、且自多招鹤。吾亦有，一丘壑。'},
    {t:'贺新郎·听我三章约',a:'辛弃疾〔宋代〕',c:'韩仲止判院山中见访，席上用前韵。\n听我三章约。有谈功、谈名者舞，谈经深酌。作赋相如亲涤器，识字子云投阁。算枉把、精神费却。此会不如公荣者，莫呼来、政尔妨人乐。医俗士，苦无药。\n当年众鸟看孤鹗。意飘然、横空直把，曹吞刘攫。老我山中谁来伴，须信穷愁有脚。似剪尽、还生僧发。自断此生天休问，倩何人、说与乘轩鹤。吾有志，在沟壑。'},
    {t:'贺新郎·同父见和再用韵答之',a:'辛弃疾〔宋代〕',c:'老大那堪说。似而今、元龙臭味，孟公瓜葛。我病君来高歌饮，惊散楼头飞雪。笑富贵千钧如发。硬语盘空谁来听？记当时、只有西窗月。重进酒，换鸣瑟。\n事无两样人心别。问渠侬：神州毕竟，几番离合？汗血盐车无人顾，千里空收骏骨。正目断关河路绝。我最怜君中宵舞，道男儿到死心如铁。看试手，补天裂。'},
    {t:'贺新郎·夏景',a:'苏轼〔宋代〕',c:'乳燕飞华屋。悄无人、桐阴转午，晚凉新浴。手弄生绡白团扇，扇手一时似玉。渐困倚、孤眠清熟。帘外谁来推绣户，枉教人、梦断瑶台曲。又却是，风敲竹。\n石榴半吐红巾蹙。待浮花、浪蕊都尽，伴君幽独。秾艳一枝细看取，芳心千重似束。又恐被、秋风惊绿。若待得君来向此，花前对酒不忍触。共粉泪，两簌簌。'},
    {t:'贺新郎·用前韵送杜叔高',a:'辛弃疾〔宋代〕',c:'细把君诗说。恍余音、钧天浩荡，洞庭胶葛。千尺阴崖尘不到，惟有层冰积雪。乍一见、寒生毛发。自昔佳人多薄命，对古来、一片伤心月。金屋冷，夜调瑟。\n去天尺五君家别。看乘空、鱼龙惨淡，风云开合。起望衣冠神州路，白日销残战骨。叹夷甫、诸人清绝。夜半狂歌悲风起，听铮铮、阵马檐间铁。南共北，正分裂。'},
    {t:'贺新郎·用前韵再赋',a:'辛弃疾〔宋代〕',c:'肘后俄生柳。叹人生、不如意事，却常八九。右手淋浪才有用，闲却持螯左手。谩赢得、伤今感旧。身阁先生惟寂寞，笑是非、不了身前后。持此语，问乌有。\n青山幸自重重秀。问新来、萧萧木落，颇堪秋否。总被西风都瘦损，依旧千岩万岫。把万事、无言搔首。翁比渠侬人谁好，是我常、与我周旋久。宁作我，一杯酒。'},
    {t:'贺新郎·拄杖重来约',a:'辛弃疾〔宋代〕',c:'拄杖重来约。对东风、洞庭张乐，向空箫勺。巨海拔犀头角出，来向此山高阁。尚两两、三三前却。平我伤怀登临际，问何方、可以平哀乐。唯酒是，万金药。\n劝君且作横空鹗。便休论、人间腥腐，纷纷乌攫。九万里风斯在下，翻覆云头雨脚。更直上、崑崙濯发。好卧长虹陂十里，是谁言、听取双黄鹤。推翠影，浸云壑。'},
    {t:'鹤',a:'杜牧〔唐代〕',c:'清音迎晓月，愁思立寒蒲。\n丹顶西施颊，霜毛四皓须。\n碧云行止躁，白鹭性灵粗。\n终日无群伴，溪边吊影孤。'},
    {t:'鹤冲天',a:'周邦彦〔宋代〕',c:'白角簟，碧纱厨。梅雨乍晴初。谢家池畔正清虚。香散嫩芙蕖。\n日流金，风解愠。一弄素琴歌舞。慢摇纨扇诉花笺。吟待晚凉天。'},
    {t:'鹤冲天·黄金榜上',a:'柳永〔宋代〕',c:'黄金榜上，偶失龙头望。明代暂遗贤，如何向。未遂风云便，争不恣游狂荡。何须论得丧？才子词人，自是白衣卿相。\n烟花巷陌，依约丹青屏障。幸有意中人，堪寻访。且恁偎红倚翠，风流事、平生畅。青春都一饷。忍把浮名，换了浅斟低唱！'},
    {t:'鹤冲天·闲窗漏永',a:'柳永〔宋代〕',c:'闲窗漏永，月冷霜华堕。悄悄下帘幕，残灯火。再三追往事，离魂乱、愁肠锁。无语沉吟坐。好天好景，未省展眉则个。\n从前早是多成破。何况经岁月，相抛嚲。假使重相见，还得似、旧时么。悔恨无计那。迢迢良夜。自家只恁摧挫。'},
    {t:'鹤叹二首',a:'刘禹锡〔唐代〕',c:'寂寞一双鹤，主人在西京。故巢吴苑树，深院洛阳城。\n徐引竹间步，远含云外情。谁怜好风月，邻舍夜吹笙。\n丹顶宜承日，霜翎不染泥。爱池能久立，看月未成栖。\n一院春草长，三山归路迷。主人朝谒早，贪养汝南鸡。'},
    {t:'黑驴与白骏',a:'佚名〔近现代〕',c:'有一黑驴，负物甚重。路遇一白力，呼曰：“力兄济我，吾背上物重，力不得胜，请与分任之。”力哂曰：“尔驴，此系汝之责任，吾岂能与尔代肩哉！”驴又哀之，力竟不应。未几，驴力疲，压毙。驱驴者愤极，强鞭挞其力，令重物全负而行。力终恨之，亦无可如何也。\n天下事大，非一人之力而能任，戮力图之，则重事亦举矣。'},
    {t:'恨别',a:'杜甫〔唐代〕',c:'洛城一别四千里，胡骑长驱五六年。\n草木变衰行剑外，兵戈阻绝老江边。\n思家步月清宵立，忆弟看云白日眠。\n闻道河阳近乘胜，司徒急为破幽燕。'},
    {t:'恨妆成',a:'元稹〔唐代〕',c:'晓日穿隙明，开帷理妆点。\n傅粉垂重重，施朱怜冉冉。\n柔鬟背额垂，丛鬓随钗敛。\n凝翠晕蛾眉，轻红拂花脸。\n满头行小梳，当面施圆靥。\n最恨落花时，妆成独披掩。'},
    {t:'横吹曲辞·关山月',a:'张籍〔唐代〕',c:'秋月朗朗关山上，山中行人马蹄响。\n关山秋来雨雪多，行人见月唱边歌。\n海边漠漠天气白，胡儿夜度黄龙碛。\n军中探骑暮出城，伏兵暗处低旌戟。\n溪水连地霜草平，野驼寻水碛中鸣。\n陇头风急雁不下，沙场苦战多流星。\n可怜万国关山道，年年战骨多秋草。'},
    {t:'横吹曲辞·陇头·一曰陇头水',a:'张籍〔唐代〕',c:'陇头已断人不行，胡骑夜入凉州城。汉家处处格斗死，\n一朝尽没陇西地。驱我边人胡中去，散放牛羊食禾黍。\n去年中国养子孙，今著毡裘学胡语。谁能更使李轻车，\n收取凉州属汉家。'},
    {t:'横吹曲辞·长安道',a:'孟郊〔唐代〕',c:'胡风激秦树，贱子风中泣。家家朱门开，得见不可入。\n长安十二衢，投树鸟亦急。高阁何人家，笙簧正喧吸。'},
    {t:'横吹曲辞·长安道',a:'白居易〔唐代〕',c:'花枝缺处青楼开，艳歌颜曲酒颜杯。\n美人劝我急行乐，自古朱颜不再来。\n君不见外州客，长安道，颜回来，颜回老。'},
    {t:'横吹曲辞·折杨柳',a:'孟郊〔唐代〕',c:'杨柳多短枝，短枝多别离。赠远累攀折，柔条安得垂。\n青春有定节，离别无定时。但恐人别促，不怨来迟迟。\n莫言短枝条，中有长相思。朱颜与绿杨，并在别离期。\n楼上春风过，风前杨柳歌。枝疏缘别苦，曲怨为年多。\n花惊燕地雪，叶映楚池波。谁堪别离此，征戍在交河。'},
    {t:'横江词·其六',a:'李白〔唐代〕',c:'月晕天风雾不开，海鲸东蹙百川回。\n惊波一起三山动，公无渡河归去来。'},
    {t:'横江词·其四',a:'李白〔唐代〕',c:'海神来过恶风回，浪打天门石壁开。\n浙江八月何如此？涛似连山喷雪来！'},
    {t:'横江词六首',a:'李白〔唐代〕',c:'人道横江好，侬道横江恶。\n一风三日吹倒山，白浪高于瓦官阁。\n海潮南去过浔阳，牛渚由来险马当。\n横江欲渡风波恶，一水牵愁万里长。\n横江西望阻西秦，汉水东连扬子津。\n白浪如山那可渡，狂风愁杀峭帆人。\n海神来过恶风回，浪打天门石壁开。\n浙江八月何如此？涛似连山喷雪来。\n横江馆前津吏迎，向余东指海云生。\n郎今欲渡缘何事？如此风波不可行。\n月晕天风雾不开，海鲸东蹙百川回。\n惊波一起三山动，公无渡河归去来。'},
    {t:'横塘行',a:'韦应物〔唐代〕',c:'妾家住横塘，夫婿郗家郎。玉盘象历双白鱼，\n宝簟玲珑透象床。象床可寝鱼可食，不知郎意何南北。\n岸上种莲岂得生，池中种槿岂得成。丈夫一去花落树，\n妾独夜长心未平。'},
    {t:'衡山',a:'黄庭坚〔宋代〕',c:'万丈融峰插紫霄，路当穷处架尘桥。\n上观碧落星辰近，下视红尘世界遥。\n螺簇山低青点点，线长远水白迢迢。\n当门老桧枝难长，绝顶寒松叶不雕，才到秋初霜已降，每逢春尽雪方消。\n猥岩老衲针常把，度夏禅僧扇懒摇。\n雷向池中兴雨泽，鸟於窗外奏萧韶。\n游人未必长居此，暂借禅房宿两宵。'},
    {t:'衡阳与梦得分路赠别',a:'柳宗元〔唐代〕',c:'十年憔悴到秦京，谁料翻为岭外行。\n伏波故道风烟在，翁仲遗墟草树平。\n直以慵疏招物议，休将文字占时名。\n今朝不用临河别，垂泪千行便濯缨。'},
    {t:'红白莲',a:'杨万里〔宋代〕',c:'红白莲花开共塘，两般颜色一般香。\n恰如汉殿三千女，半是浓妆半淡妆。'},
    {t:'红窗迥·几日来',a:'周邦彦〔宋代〕',c:'几日来、真个醉。不知道、窗外乱春，已深半指。花影被风摇碎。拥春酲乍起。有个人人，生得济楚，来向耳畔，问道今朝醒未。情性儿、慢腾腾地。恼得人又醉。'},
    {t:'红窗迥·小园东',a:'柳永〔宋代〕',c:'小园东，花共柳。红紫又一齐开忙。引将蜂蝶燕和莺，成阵价、忙忙走。\n花心偏向蜂儿有。莺共燕、吃他拖逗。蜂儿却入、花里藏身，胡蝶儿、你且退后。'},
    {t:'红窗听·淡薄梳妆轻结束',a:'晏殊〔宋代〕',c:'淡薄梳妆轻结束。天意与、脸红眉绿。断环书素传情久，许双飞同宿。\n一饷无端分比目。谁知道、风前月底，相看未足。此心终拟，觅鸾弦重续。'},
    {t:'红窗听·记得香闺临别语',a:'晏殊〔宋代〕',c:'记得香闺临别语，彼此有、万重无诉。淡云轻霭知多少，隔桃源无处。\n梦觉相思天欲曙，依前是、银屏画烛，宵长岁暮。此时何计，托鸳鸯飞去。'},
    {t:'红窗听·如削肌肤红玉莹',a:'柳永〔宋代〕',c:'如削肌肤红玉莹。举措有、许多端正。二年三岁同鸳寝。表温柔心性。\n别后无非良夜永。如何向、名牵利役，归期未定。算伊心里，却冤成薄幸。'},
    {t:'红窗月·燕归花谢',a:'纳兰性德〔清代〕',c:'燕归花谢，早因循、又过清明。是一般风景，两样心情。犹记碧桃影里、誓三生。\n乌丝阑纸娇红篆，历历春星。道休孤密约，鉴取深盟。语罢一丝香露、湿银屏。'},
    {t:'红蕉',a:'柳宗元〔唐代〕',c:'晚英值穷节，绿润含朱光。\n以兹正阳色，窈窕凌清霜。\n远物世所重，旅人心独伤。\n回晖眺林际，槭槭无遗芳。'},
    {t:'红蕉洞独宿',a:'黄庭坚〔宋代〕',c:'南床高卧读逍遥，真感生来不易销。\n枕落梦魂飞蛱蝶，灯残风雨送芭蕉。\n永怀玉树埋尘土，何异蒙鸠挂苇苕。\n衣笐妆台蛛结网，可怜无以永今朝。'},
    {t:'红林檎近·风雪惊初霁',a:'周邦彦〔宋代〕',c:'风雪惊初霁，水乡增暮寒。树杪堕飞羽，檐牙挂琅玕。才喜门堆巷积，可惜迤逦销残。渐看低竹翩翻。清池涨微澜。\n步屐晴正好，宴席晚方欢。梅花耐冷，亭亭来入冰盘。对前山横素，愁云变色，放杯同觅高处看。'},
    {t:'红林檎近·高柳春才软',a:'周邦彦〔宋代〕',c:'高柳春才软，冻梅寒更香。暮雪递清峭，玉尘散林塘。那堪飘风递冷，故遣度幕穿窗。似欲料理萧妆。呵手弄丝簧。\n冷落词赋客，萧索水云乡。援毫授简，风流犹忆东梁。望虚檐徐转，回廊未扫，夜长莫惜空酒觞。'},
    {t:'红罗袄·大石秋悲',a:'周邦彦〔宋代〕',c:'画烛寻欢去，羸马载愁归。念取酒东垆，尊罍虽近，采花南浦，蜂蝶须知。\n自分袂、天阔鸿稀，空怀梦约心期。楚客忆江蓠。算宋玉、未必为秋悲。'},
    {t:'红玫瑰',a:'杨万里〔宋代〕',c:'非关月季姓名同，不与蔷薇谱色通。\n接叶连枝千万绿，一花两色浅深红。\n风流各自燕支格，雨露何私造化功。\n别有国香收不得，诗人熏入水沉中。'},
    {t:'红梅',a:'王安石〔宋代〕',c:'春半花才发，多应不奈寒。\n北人初未识，浑作杏花看。'},
    {t:'红梅三首·其二',a:'苏轼〔宋代〕',c:'雪里开花却是迟，何如独占上朱时。\n也知造物含深意，故与施朱发妙姿。\n细雨浥残千颗泪，轻寒瘦损一分肌。\n不应便杂妖桃杏，数点微酸已著枝。'},
    {t:'红梅三首·其三',a:'苏轼〔宋代〕',c:'幽人自恨探春迟，不见檀心未吐时。\n丹鼎夺胎那是宝，玉人頩颊更多姿。\n抱丛暗蕊初含子，落盏穠香已透肌。\n乞与徐熙新画样，竹间璀璨出斜枝。'},
    {t:'红牡丹',a:'王维〔唐代〕',c:'绿艳闲且静，红衣浅复深。\n花心愁欲断，春色岂知心。'},
    {t:'红情·无边香色',a:'张炎〔宋代〕',c:'疏影、暗香，姜白石为梅著语，因易之曰红情、绿意以荷花荷叶咏之。\n无边香色。记涉江自采，锦机云密。翦翦红衣，学舞波心旧曾识。一见依然似语，流水远、几回空忆。看亭亭、倒影窥妆，玉润露痕湿。\n闲立。翠屏侧。爱向人弄芳，背酣斜日。料应太液。三十六宫土花碧。清兴凌风更爽，无数满汀洲如昔。泛片叶、烟浪里，卧横紫笛。'},
    {t:'红芍药',a:'元稹〔唐代〕',c:'芍药绽红绡，巴篱织青琐。繁丝蹙金蕊，高焰当炉火。\n翦刻彤云片，开张赤霞裹。烟轻琉璃叶，风亚珊瑚朵。\n受露色低迷，向人娇婀娜。酡颜醉后泣，小女妆成坐。\n艳艳锦不如，夭夭桃未可。晴霞畏欲散，晚日愁将堕。\n结植本为谁，赏心期在我。采之谅多思，幽赠何由果。'},
    {t:'红线毯',a:'白居易〔唐代〕',c:'忧蚕桑之费也\n红线毯，择茧缲丝清水煮，拣丝练线红蓝染。\n染为红线红于蓝，织作披香殿上毯。\n披香殿广十丈馀，红线织成可殿铺。\n彩丝茸茸香拂拂，线软花虚不胜物。\n美人蹋上歌舞来，罗袜绣鞋随步没。\n太原毯涩毳缕硬，蜀都褥薄锦花冷，\n不如此毯温且柔，年年十月来宣州。\n宣城太守加样织，自谓为臣能竭力。\n百夫同担进宫中，线厚丝多卷不得。\n宣城太守知不知，一丈毯，千两丝。\n地不知寒人要暖，少夺人衣作地衣。'},
    {t:'侯尉家听琵琶',a:'黄庭坚〔宋代〕',c:'舫斋苍竹雨声中，一曲琵琶酒一锺。\n恰似浔阳江上听，只无明月与丹枫。'},
    {t:'后池泛舟送王十',a:'杜牧〔唐代〕',c:'相送西郊暮景和，青苍竹外绕寒波。\n为君蘸甲十分饮，应见离心一倍多。'},
    {t:'后宫词',a:'白居易〔唐代〕',c:'泪湿罗巾梦不成，夜深前殿按歌声。\n红颜未老恩先断，斜倚薰笼坐到明。'},
    {t:'后游',a:'杜甫〔唐代〕',c:'寺忆曾游处，桥怜再渡时。\n江山如有待，花柳自无私。\n野润烟光薄，沙暄日色迟。\n客愁全为减，舍此复何之？'},
    {t:'后元丰行',a:'王安石〔宋代〕',c:'歌元丰，十日五日一雨风。\n麦行千里不见土，连山没云皆种黍。\n水秧绵绵复多稌，龙骨长干挂梁梠。\n鲥鱼出网蔽洲渚，荻笋肥甘胜牛乳。\n百钱可得酒斗许，虽非社日长闻鼓。\n吴儿踏歌女起舞，但道快乐无所苦。\n老翁堑水西南流，杨柳中间杙小舟。\n乘兴欹眠过白下，逢人欢笑得无愁。'},
    {t:'后园凿井歌',a:'李贺〔唐代〕',c:'井上辘轳床上转。水声繁，弦声浅。情若何，荀奉倩。\n城头日，长向城头住。一日作千年，不须流下去。'},
    {t:'候使登石头驿楼作',a:'张九龄〔唐代〕',c:'山槛凭南望，川途眇北流。远林天翠合，前浦日华浮。\n万井缘津渚，千艘咽渡头。渔商多末事，耕稼少良畴。\n自守陈蕃榻，尝登王粲楼。徒然骋目处，岂是获心游。\n向迹虽愚谷，求名异盗丘。息阴芳木所，空复越乡忧。'},
    {t:'忽不贫，喜卢仝书船归洛',a:'孟郊〔唐代〕',c:'贫孟忽不贫，请问孟何如。卢仝翻洛船，崔嵬但载书。\n江潮清翻翻，淮潮碧徐徐。夜有为朝有，朝有良卷舒。\n江淮君子水，相送仁有馀。我去官色衫，肩经入君庐。\n喃喃肩经郎，言语倾琪琚。琪琚铿好词，鸟鹊跃庭除。\n书船平安翻，喜报乡里闾。我愿拾遗柴，巢经于空虚。\n下免尘土侵，上为云霞居。日月更相锁，道义分明储。\n不愿空岧峣，但愿实工夫。实空二理微，分别相起予。\n经书荒芜多，为君勉勉锄。勉勉不敢专，传之方在诸。'},
    {t:'忽忽',a:'韩愈〔唐代〕',c:'忽忽乎余未知生之为乐也，愿脱去而无因。\n安得长翮大翼如云生我身，乘风振奋出六合。\n绝浮尘，死生哀乐两相弃，是非得失付闲人。'},
    {t:'滹沱河二首',a:'文天祥〔宋代〕',c:'风沙睢水终亡楚，草木公山竟蹙秦。\n始信滹沱冰合事，世间兴废不由人。'},
    {t:'胡捣练',a:'晏几道〔宋代〕',c:'小亭初报一枝梅，惹起江南归兴。遥想玉溪风景，水漾横斜影。\n异香直到醉乡中，醉后还因香醒。好是玉容相并。人与花争莹。'},
    {t:'胡歌',a:'岑参〔唐代〕',c:'黑姓蕃王貂鼠裘，葡萄宫锦醉缠头。\n关西老将能苦战，七十行兵仍未休。'},
    {t:'胡笳歌送颜真卿使赴河陇',a:'岑参〔唐代〕',c:'君不闻胡笳声最悲？紫髯绿眼胡人吹。\n吹之一曲犹未了，愁杀楼兰征戍儿。\n凉秋八月萧关道，北风吹断天山草。\n昆仑山南月欲斜，胡人向月吹胡笳。\n胡笳怨兮将送君，秦山遥望陇山云。\n边城夜夜多愁梦，向月胡笳谁喜闻？'},
    {t:'胡笳曲',a:'王昌龄〔唐代〕',c:'城南虏已合，一夜几重围。\n自有金笳引，能沾出塞衣。\n听临关月苦，清入海风微。\n三奏高楼晓，胡人掩涕归。'},
    {t:'胡笳十八拍十八首',a:'王安石〔宋代〕',c:'春风似旧花仍笑，人生岂得长成少。\n我与儿兮各一方，憔悴看成两鬓霜。\n如今岂无騕褭与骅道，安得送我置汝傍。\n胡尘暗天道路长，遂令再往之计堕眇芒。\n胡笳本出自胡中，此曲哀怨何时终。\n笳一会兮琴一拍，此心炯炯君应识。'},
    {t:'胡山人归王屋，因有赠',a:'张籍〔唐代〕',c:'转转无成到白头，人间举眼尽从愁。此生已是蹉跎去，\n每事应从卤莽休。虽作闲官少拘束，难逢胜景可淹留。\n君归与访移家处，若个峰头最较幽。'},
    {t:'胡无人',a:'李白〔唐代〕',c:'严风吹霜海草凋，筋干精坚胡马骄。\n汉家战士三十万，将军兼领霍嫖姚。\n流星白羽腰间插，剑花秋莲光出匣。\n天兵照雪下玉关，虏箭如沙射金甲。\n云龙风虎尽交回，太白入月敌可摧。\n敌可摧，旄头灭，履胡之肠涉胡血。\n悬胡青天上，埋胡紫塞傍。\n胡无人，汉道昌。\n陛下之寿三千霜。但歌大风云飞扬，安得猛士兮守四方。'},
    {t:'胡无人',a:'陆游〔宋代〕',c:'须如猬毛磔，面如紫石棱。\n丈夫出门无万里，风云之会立可乘。\n追奔露宿青海月，夺城夜蹋黄河冰。\n铁衣度碛雨飒飒，战鼓上陇雷凭凭。\n三更穷虏送降款，天明积甲如丘陵。\n中华初识汗血马，东夷再贡霜毛鹰。\n群阴伏，太阳升；胡无人，宋中兴。\n丈夫报主有如此，笑人白首篷窗灯。'},
    {t:'壶中天',a:'张炎〔宋代〕',c:'绕枝倦鹊，鬓萧萧、肯信如今犹悬。风雪荷衣寒叶补，一点灯花悬壁。万里舟车，十年书剑，此意白天识。泛然身世，故家休问清白。\n却笑醉倒衰翁，石床飞梦，不入槐安国。只恐溪山游未了，莫叹飘零南北。滚滚江横，呜呜歌罢，渺渺情何极。正无聊赖，天风吹下孤笛。'},
    {t:'壶中天·白香岩和东坡韵赋梅',a:'张炎〔宋代〕',c:'苔根抱古，透阳春、挺挺林间英绝。隔水笛声那得到，斜日空明绝壁。半树篱边，一枝竹外，冷艳杰苍雪。淡然相对，万花无此清杰。\n还念庾岭幽情，江南聊折，赠行人应发。寂寂西窗闲弄影，深夜寒灯明灭。且浸芳壶，休簪短帽，照见萧萧发。几时归去，郎吟湖上香月。'},
    {t:'壶中天·怀霅·友',a:'张炎〔宋代〕',c:'异乡倦旅，问扁舟东下，归期何行。琴剑空随身万里，天地谁非行客。李杜飘零，羊昙悲感，回首寂陈迹。羁怀难写，豆虫吟破孤寂。\n柳外门掩疏阴，佳人何处，溪上苹花白。留得一方无用月，隐隐山阳闻笛。旧雨不来，风流云散，惟有长相忆。雁书休寄，寸心分付梅驿。'},
    {t:'壶中天·客中寄友',a:'张炎〔宋代〕',c:'西秦倦旅。是几年不听，西湖风雨。我托长镵垂短发，心事时看天语。吟箧空随，征衣休换，薜荔犹堪补。山能招隐，一瓢闲挂烟树。\n方叹旧国人稀，花间忽见，倾盖浑如故。客里不须谈世事，野老安知今古。海上盟鸥，门深款竹，风月平分取。陶然一醉，此时愁在何处。'},
    {t:'壶中天·寿月溪',a:'张炎〔宋代〕',c:'波明昼锦，看芳莲迎晓，风弄晴碧。乔木千年长润屋，清荫图书琴桑攥虾须帘卷，瑶草秋无色。和熏兰麝，彩衣欢拥诗伯。\n溪上燕往鸥还，笔床茶灶，筇竹随游屐。闲似神仙闲最好，未必如今闲得。书染芝香，驿传梅信，次第来云北。金尊须满，月光长照歌席。'},
    {t:'壶中天·送赵寿父归庆元',a:'张炎〔宋代〕',c:'奚囊谢屐。向芙蓉城下，□□游历。江旷沙鸥何所似，白发飘飘行客。旷海乘风，长波垂钓，欲把珊瑚暮。近来杨柳，却怜浑是秋色。\n日暮空想佳人，楚芳难赠，烟水分明隔。老病孤舟天地里，惟有歌声消得。故国荒城，斜阳古道，可奈花狼藉。他时一笑，似曾何处相识。'},
    {t:'壶中天·养拙园夜饮',a:'张炎〔宋代〕',c:'瘦筇访隐，正繁阴闲锁，一壶幽绿。乔木苍寒图画古，窈窕行人韦曲。鹤响天高，水流花净，笑语通华屋。虚堂松外，夜深凉气吹烛。\n乐事杨柳楼心，瑶台月下，有生香堪掬。谁理商声帘外悄，萧瑟悬珰鸣玉。一笑难逢，四愁休赋，任我云边宿。倚兰歌罢，露萤飞上秋竹。'},
    {t:'湖口望庐山瀑布水',a:'张九龄〔唐代〕',c:'万丈洪泉落，迢迢半紫氛。\n奔流下杂树，洒落出重云。\n日照虹霓似，天清风雨闻。\n灵山多秀色，空水共氤氲。'},
    {t:'湖南兰若示大乘诸公',a:'皎然〔唐代〕',c:'未到无为岸，空怜不系舟。东山白云意，岁晚尚悠悠。'},
    {t:'湖南曲',a:'张籍〔唐代〕',c:'潇湘多别离，风起芙蓉洲。江上人已远，夕阳满中流。\n鸳鸯东南飞，飞上青山头。'},
    {t:'湖南正初招李郢秀才',a:'杜牧〔唐代〕',c:'行乐及时时已晚，对酒当歌歌不成。\n千里暮山重叠翠，一溪寒水浅深清。\n高人以饮为忙事，浮世除诗尽强名。\n看著白蘋芽欲吐，雪舟相访胜闲行。'},
    {t:'湖天暮景五首',a:'杨万里〔宋代〕',c:'坐看西日落湖滨，不是山御不是云。\n寸寸低来忽全没，分明入水只无痕。'},
    {t:'湖亭望水',a:'白居易〔唐代〕',c:'久雨南湖涨，新晴北客过。\n日沉红有影，风定绿无波。\n岸没闾阎少，滩平船舫多。\n可怜心赏处，其奈独游何。'},
    {t:'湖中旅泊，寄阎九司户防',a:'孟浩然〔唐代〕',c:'桂水通百越，扁舟期晓发。荆云蔽三巴，夕望不见家。\n襄王梦行雨，才子谪长沙。长沙饶瘴疠，胡为苦留滞。\n久别思款颜，承欢怀接袂。接袂杳无由，徒增旅泊愁。\n清猿不可听，沿月下湘流。'},
    {t:'湖中曲',a:'李贺〔唐代〕',c:'长眉越沙采兰若，桂叶水葓春风风。\n横船醉眠白昼闲，渡口梅风歌扇薄。\n燕钗玉股照青渠，越王娇郎小字书。\n蜀纸封巾报云鬓，晚漏壶中水淋尽。'},
    {t:'湖州取解述情',a:'孟郊〔唐代〕',c:'霅水徒清深，照影不照心。白鹤未轻举，众鸟争浮沉。\n因兹挂帆去，遂作归山吟。'},
    {t:'蝴蝶飞',a:'李贺〔唐代〕',c:'杨花扑帐春云热，龟甲屏风醉眼缬。\n东家蝴蝶西家飞，白骑少年今日归。'},
    {t:'虎画',a:'佚名',c:'予友人工画虎，其庐之四壁咸虎画：或腾或扑，或吼或奔，或挈幼或独行，形态各异，皆毕肖。吾尝乞得一轴，高二尺奇，宽二尺许。其二虎，雌雄各一。雄者蹲于石，昂首远视，张口若呼啸状；雌者伏于侧，足前伸，神情怡然。旁有奇石三四，似助威也。余县诸东壁，爱甚。'},
    {t:'虎丘寺',a:'张籍〔唐代〕',c:'望月登楼海气昏，剑池无底浸云根。\n老僧只恐山移去，日暮先教锁寺门。'},
    {t:'扈驾西山',a:'纳兰性德〔清代〕',c:'凤翥龙蟠势作环，浮青不断太行山。\n九重殿阁葱茏里，一气风云吐纳间。\n熊虎自当驰道伏，蛟螭长棒御书闲。\n黄图此日论形胜，惭愧频叨侍从班。'},
    {t:'扈亭西陂燕赏',a:'韦应物〔唐代〕',c:'杲杲朝阳时，悠悠清陂望。嘉树侣氤氲，春游方浩荡。\n况逢文翰侣，爱此孤舟漾。绿野际遥波，横云分叠嶂。\n公堂日为倦，幽襟自兹旷。有酒今满盈，愿君尽弘量。'},
    {t:'鄠杜郊居',a:'温庭筠〔唐代〕',c:'槿篱芳援近樵家，垄麦青青一径斜。\n寂寞游人寒食后，夜来风雨送梨花。'},
    {t:'鄠郊别墅寄所知',a:'温庭筠〔唐代〕',c:'持颐望平绿，万景集所思。南塘遇新雨，百草生容姿。\n幽鸟不相识，美人如何期。徒然委摇荡，惆怅春风时。'},
    {t:'花岛',a:'韩愈〔唐代〕',c:'蜂蝶去纷纷，香风隔岸闻。\n欲知花岛处，水上觅红云。'},
    {t:'花犯·小石梅花',a:'周邦彦〔宋代〕',c:'粉墙低，梅花照眼，依然旧风味。丽痕轻缀。疑净洗铅华，无限佳丽。去年胜赏曾孤倚。冰盘同燕被。更可惜，雪中高树，香篝熏素被。\n今年对花最匆匆，相逢似有恨，依依愁悴。吟望久，青苔上、旋看飞坠。相将见、翠丸荐酒，人正在、空江烟浪里。但梦想、一枝潇洒，黄昏斜照水。'},
    {t:'花非花',a:'白居易〔唐代〕',c:'花非花，雾非雾。\n夜半来，天明去。\n来如春梦几多时？\n去似朝云无觅处。'},
    {t:'花径',a:'韦应物〔唐代〕',c:'山花夹径幽，古甃生苔涩。胡床理事馀，玉琴承露湿。\n朝与诗人赏，夜携禅客入。自是尘外踪，无令吏趋急。'},
    {t:'花石长枕歌答章居士赠',a:'皎然〔唐代〕',c:'楚山有石郢人琢，琢成长枕知是玉。全疑冰片坐恐销，\n间发花丛惊不足。赠予比之金琅玕，琼花烂熳浮席端。\n吾师道吾不执宝，今日感君因执看。试叩铿然应清律，\n纤尘不留蝇敢拂。万物皆因造化资，如何独负清贞质。\n南山有云鹄在空，长松为我生凉风。高友朗咏乐其中，\n行住四仪皆道意。不学小乘一曲士，唯将此物安座隅，\n取次闲眠有禅味。'},
    {t:'花时遍游诸家园',a:'陆游〔宋代〕',c:'为爱名花抵死狂，只愁风日损红芳。\n绿章夜奏通明殿，乞借春阴护海棠。'},
    {t:'花下',a:'王安石〔宋代〕',c:'花下一壶酒，定将谁举杯。\n雪英飞落近，疑是故人来。'},
    {t:'花下醉',a:'李商隐〔唐代〕',c:'寻芳不觉醉流霞，倚树沉眠日已斜。\n客散酒醒深夜后，更持红烛赏残花。'},
    {t:'花心动·双调',a:'周邦彦〔宋代〕',c:'帘卷青楼，东风暖，杨花乱飘晴移。兰袂褪香，罗帐褰红，绣枕旋移相就。海棠花谢春融暖，偎人浪、娇波频溜。象床稳，鸳衾谩展，浪翻红绉。\n一夜情浓似酒。香汗渍鲛绡，几番微透。鸾困凤慵，娅姹双眉，画也画应难就。问伊可煞□人厚。梅萼露、胭脂檀口。从此后、纤腰为郎管瘦。'},
    {t:'花鸭',a:'杜甫〔唐代〕',c:'花鸭无泥滓，阶前每缓行。\n羽毛知独立，黑白太分明。\n不觉群心妒，休牵众眼惊。\n稻粱沾汝在，作意莫先鸣。'},
    {t:'花影',a:'苏轼〔宋代〕',c:'重重叠叠上瑶台，几度呼童扫不开。\n刚被太阳收拾去，却教明月送将来。'},
    {t:'花游曲',a:'李贺〔唐代〕',c:'春柳南陌态，冷花寒露姿。今朝醉城外，拂镜浓扫眉。\n烟湿愁车重，红油覆画衣。舞裙香不暖，酒色上来迟。'},
    {t:'华清词·一作华清宫词',a:'刘禹锡〔唐代〕',c:'日出骊山东，裴回照温泉。楼台影玲珑，稍稍开白烟。\n言昔太上皇，常居此祈年。风中闻清乐，往往来列仙。\n翠华入五云，紫气归上玄。哀哀生人泪，泣尽弓剑前。\n圣道本自我，凡情徒颙然。小臣感玄化，一望青冥天。'},
    {t:'华清宫',a:'李商隐〔唐代〕',c:'华清恩幸古无伦，犹恐蛾眉不胜人。\n未免被他褒女笑，只教天子暂蒙尘。'},
    {t:'华清宫',a:'杜牧〔唐代〕',c:'零叶翻红万树霜，玉莲开蕊暖泉香。\n行云不下朝元阁，一曲淋铃泪数行。'},
    {t:'华清引·感旧',a:'苏轼〔宋代〕',c:'平时十月幸莲汤。玉甃琼梁。五一车马如水，珠玑满路旁。\n翠华一去掩方床。独留烟树苍苍。至今清夜月，依前过缭墙。'},
    {t:'华山歌',a:'刘禹锡〔唐代〕',c:'洪垆作高山，元气鼓其橐。俄然神功就，峻拔在寥廓。\n灵迹露指爪，杀气见棱角。凡木不敢生，神仙聿来托。\n天资帝王宅，以我为关钥。能令下国人，一见换神骨。\n高山固无限，如此方为岳。丈夫无特达，虽贵犹碌碌。'},
    {t:'华山畿·君既为侬死',a:'佚名〔南北朝〕',c:'华山畿，华山畿，\n君既为侬死，独生为谁施？\n欢若见怜时，棺木为侬开。'},
    {t:'华山畿二十五首其一',a:'佚名〔隋代〕',c:'华山畿。君既为侬死。独活为谁施。欢若见怜时。棺木为侬开。'},
    {t:'华胥引',a:'张炎〔宋代〕',c:'温泉浴罢，酣酒才苏，洗妆犹湿。衣暮云深，瑶台月下逢太白。素衣初染天香，对顿风倾国。惆怅顿阑，炯然玉树独立。\n只恐江空，顿忘却、锦袍清逸。柳迷归院，欲远花妖未得。谁写一枝淡雅，傍沈香亭北。说与莺莺，怕人错认秋色。'},
    {t:'华胥引·秋思',a:'周邦彦〔宋代〕',c:'川原澄映，烟月冥濛，去舟如叶。有足沙平，蒲根水冷留雁唼。别有孤角吟秋，对晓风呜轧。红日渐竿，醉头扶起还怯。\n离思相萦，渐看看、鬓丝堪镊。舞衫歌扇，何人轻怜细阅。点检从前恩爱，但凤笺盈箧。愁剪灯花，夜来和泪双叠。'},
    {t:'华岳',a:'王维〔唐代〕',c:'西岳出浮云，积翠在太清。\n连天疑黛色，百里遥青冥。\n白日为之寒，森沉华阴城。\n昔闻乾坤闭，造化生巨灵。\n右足踏方止，左手推削成。\n天地忽开拆，大河注东溟。\n遂为西峙岳，雄雄镇秦京。\n大君包覆载，至德被群生。\n上帝伫昭告，金天思奉迎。\n人祇望幸久，何独禅云亭。'},
    {t:'华子冈',a:'王维〔唐代〕',c:'飞鸟去不穷，连山复秋色。\n上下华子冈，惆怅情何极。'},
    {t:'画',a:'佚名〔隋代〕',c:'远观山有色，近听水无声。\n春去花还在，人来鸟不惊。'},
    {t:'画',a:'王维〔唐代〕',c:'远看山有色，近听水无声。\n春去花还在，人来鸟不惊。'},
    {t:'画角东城',a:'李贺〔唐代〕',c:'河转曙萧萧，鸦飞睥睨高。帆长摽越甸，壁冷挂吴刀。\n淡菜生寒日，鲕鱼潠白涛。水花沾抹额，旗鼓夜迎潮。'},
    {t:'画松',a:'元稹〔唐代〕',c:'张璪画古松，往往得神骨。翠帚扫春风，枯龙戛寒月。\n流传画师辈，奇态尽埋没。纤枝无萧洒，顽干空突兀。\n乃悟埃尘心，难状烟霄质。我去淅阳山，深山看真物。'},
    {t:'画堂春·春情',a:'秦观〔宋代〕',c:'东风吹柳日初长，雨余芳草斜宝。杏花零落燕泥香，睡损红妆。\n宝篆烟消龙凤，画屏云锁潇湘。夜寒微透薄罗裳，无限思量。'},
    {t:'画堂春·寄子由',a:'苏轼〔宋代〕',c:'柳花飞处麦摇波，晚湖净鉴新磨。小舟飞棹去如梭，齐唱采菱歌。\n平野水云溶漾，小楼风日晴和。济南何在暮云多，归去奈愁何。'},
    {t:'画堂春·落红铺径水平池',a:'秦观〔宋代〕',c:'落红铺径水平池，弄晴小雨霏霏。杏园憔悴杜鹃啼，无奈春归。\n柳外画楼独上，凭栏手捻花枝。放花无语对斜晖，此恨谁知？'},
    {t:'画堂春·一生一代一双人',a:'纳兰性德〔清代〕',c:'一生一代一双人，争教两处销浆。相思相望不相亲，天为谁春？\n浆向蓝桥易乞，药成碧海难奔。若容相访饮牛津，相对忘贫。'},
    {t:'画鹰',a:'杜甫〔唐代〕',c:'素练风霜起，苍鹰画作殊。\n㧐身思狡兔，侧目似愁胡。\n绦镟光堪擿，轩楹势可呼。\n何当击凡鸟，毛血洒平芜。'},
    {t:'怀别',a:'张籍〔唐代〕',c:'仆人驱行轩，低昂出我门。\n离堂无留客，席上唯琴樽。\n古道随水曲，悠悠绕荒村。\n远程未奄息，别念在朝昏。\n端居愁岁永，独此留清景。\n岂无经过人，寻叹门巷静。\n君如天上雨，我如屋下井。\n无因同波流，愿作形与影。'},
    {t:'怀此地',a:'张九龄〔唐代〕',c:'出处各有在，何者为陆沉。幸无坦贱事，聊可祛迷襟。\n世路少夷坦，孟门未岖嶔。多惭入火术，常可履冰心。\n一跌不自保，万全焉可寻。行行念归路，眇眇惜光阴。\n浮生如过隙，先达已吾箴。敢忘丘山施，亦云年病侵。\n力衰在所养，时谢良不任。但忆旧栖息，愿言遂窥临。\n云间日孤秀，山下面清深。萝鸢自为幄，风泉何必琴。\n归此老吾老，还当日千金。'},
    {t:'怀锦水居止二首',a:'杜甫〔唐代〕',c:'军旅西征僻，风尘战伐多。\n犹闻蜀父老，不忘舜讴歌。\n天险终难立，柴门岂重过？\n朝朝巫峡水，远逗锦江波。\n万里桥南宅，百花潭北庄。\n层轩皆面水，老树饱经霜。\n雪岭界天白，锦城曛日黄。\n惜哉形胜地，回首一茫茫！'},
    {t:'怀旧第一百六',a:'文天祥〔宋代〕',c:'天寒昏无日，故乡不可思。\n访旧半为鬼，惨惨中肠悲。'},
    {t:'怀孔明',a:'文天祥〔宋代〕',c:'斜谷事不济，将星殒营中。\n至今出师表，读之泪沾胸。\n汉贼明大义，赤心贯苍穹。\n世以成败论，操懿真英雄。'},
    {t:'怀琅琊、深标二释子',a:'韦应物〔唐代〕',c:'白云埋大壑，阴崖滴夜泉。应居西石室，月照山苍然。'},
    {t:'怀庆朔堂',a:'范仲淹〔宋代〕',c:'庆朔堂前花自栽，便移官去未曾开。\n年年忆着成离恨，祇托春风管句来。'},
    {t:'怀素友子西',a:'韦应物〔唐代〕',c:'广陌并游骑，公堂接华襟。方欢驶见别，永日独沉吟。\n阶暝流暗驶，气疏露已侵。层城湛深夜，片月生幽林。\n往款良未遂，来觌旷无音。恒当清觞宴，思子玉山岑。\n耿耿何以写，密言空委心。'},
    {t:'怀吴中冯秀才',a:'杜牧〔唐代〕',c:'长洲苑外草萧萧，却算游程岁月遥。\n唯有别时今不忘，暮烟秋雨过枫桥。'},
    {t:'怀扬通州',a:'文天祥〔宋代〕',c:'江波无柰暮云阴，一片朝宗只此心。\n今日海头觅船去，始知百炼是精金。'},
    {t:'怀隐堂',a:'周邦彦〔宋代〕',c:'昔贤抱奇识，阅世犹鼠肝。\n深颦畏轩冕，自谓山林宽。\n至今仰高躅，凛若冰雪寒。\n我侯坐少孤，久著聚鶡，\n屡费黄金丸。归来长太息，\n依旧一瓢箪。偶逢隐者谷，\n爱此高巑屼。结庐面绝壁，\n所幸一枝安。侯今未全老，\n每据伏波鞍。曷不持长缨，\n取虏报县官。功名事不磨，\n未可乐丘墦。嗟我如鹪鹩，\n尽室寄苇萑。谋居转幽邃，\n欲把严陵竿。归管道环堵室，\n始觉生理。因侯有华构，\n弥起百忧端。'},
    {t:'怀钟山',a:'王安石〔宋代〕',c:'投老归来供奉班，尘埃无复见钟山。\n何须更待黄粱熟，始觉人间是梦间。'},
    {t:'怀紫阁山',a:'杜牧〔唐代〕',c:'学他趋世少深机，紫阁青霄半忆扉。山路远怀王子晋，\n诗家长忆谢玄晖。百年不肯疏荣辱，双鬓终应老是非。\n人道青山归去好，青山曾有几人归。'},
    {t:'淮南卧病书怀寄蜀中赵徵君蕤',a:'李白〔唐代〕',c:'吴会一浮云，飘如远行客。\n功业莫从就，岁光屡奔迫。\n良图俄弃捐，衰疾乃绵剧。\n古琴藏虚匣，长剑挂空壁。\n楚冠怀钟仪，越吟比庄舄。\n国门遥天外，乡路远山隔。\n朝忆相如台，夜梦子云宅。\n旅情初结缉，秋气方寂历。\n风入松下清，露出草间白。\n故人不可见，幽梦谁与适。\n寄书西飞鸿，赠尔慰离析。'},
    {t:'淮上即事寄广陵亲故',a:'韦应物〔唐代〕',c:'前舟已眇眇，欲渡谁相待？\n秋山起暮钟，楚雨连沧海。\n风波离思满，宿昔容鬓改。\n独鸟下东南，广陵何处在？'},
    {t:'淮上喜会梁州故人',a:'韦应物〔唐代〕',c:'江汉曾为客，相逢每醉还。\n浮云一别后，流水十年间。\n欢笑情如旧，萧疏鬓已斑。\n何因不归去？淮上有秋山。'},
    {t:'淮上遇洛阳李主簿',a:'韦应物〔唐代〕',c:'结茅临古渡，卧见长淮流。\n窗里人将老，门前树已秋。\n寒山独过雁，暮雨远来舟。\n日夕逢归客，那能忘旧游！'},
    {t:'淮阴行五首',a:'刘禹锡〔唐代〕',c:'簇簇淮阴市，竹楼缘岸上。好日起樯竿，乌飞惊五两。\n今日转船头，金乌指西北。烟波与春草，千里同一色。\n船头大铜镮，摩挲光阵阵。早早使风来，沙头一眼认。\n何物令侬羡，羡郎船尾燕。衔泥趁樯竿，宿食长相见。\n隔浦望行船，头昂尾幰幰。无奈晚来时，清淮春浪软。'},
    {t:'桓帝初城上乌童谣',a:'佚名〔魏晋〕',c:'城上乌，尾毕逋。\n公为吏，子为徒。\n一徒死，百乘车。\n车班班，入河间。\n河间姹女工数钱，以钱为室金为堂，石上慊慊舂黄粱。\n梁下有悬鼓，我欲击之丞卿怒。'},
    {t:'桓帝初天下童谣',a:'佚名〔两汉〕',c:'小麦青青大麦枯，谁当获者妇与姑。\n丈人何在西击胡。\n吏买马，君具车，请为诸君鼓咙胡。'},
    {t:'桓灵时童谣',a:'佚名〔两汉〕',c:'举秀才，不知书。\n察孝廉，父别居。\n寒素清白浊如泥，\n高第良将怯如鸡。'},
    {t:'浣花女',a:'陆游〔宋代〕',c:'江头女儿双髻丫，常随阿母供桑麻。\n当户夜织声咿哑，地炉豆秸煎土茶。\n长成嫁与东西家，柴门相对不上车。\n青裙竹笥何所嗟，插髻烨烨牵牛花。\n城中妖姝脸如霞，争嫁官人慕高华。\n青骊一出天之涯，年年伤春抱琵琶。'},
    {t:'浣沙溪·薄薄纱厨望似空',a:'周邦彦〔宋代〕',c:'薄薄纱厨望似空。簟纹如水浸衣蓉。起来娇眼未惺忪。\n强整罗衣抬皓腕，更将纨扇掩酥胸。羞郎何事面微红。'},
    {t:'浣沙溪·不为萧娘旧约寒',a:'周邦彦〔宋代〕',c:'不为萧娘旧约寒，何因容易别长安？预愁衣上粉痕干。\n幽阁深沈灯焰喜，小垆邻近酒杯宽。为君门外脱归鞍。'},
    {t:'浣沙溪·黄钟',a:'周邦彦〔宋代〕',c:'日薄尘飞官路平。眼前喜见汴河倾。地遥人倦莫兼程。\n下马先寻题壁字，出门闲记榜村名。早收灯火梦倾城。'},
    {t:'浣沙溪·黄钟·第二',a:'周邦彦〔宋代〕',c:'贪向津亭拥去车。不辞泥雨溅罗襦。泪多脂粉了无余。\n酒酽未须令客醉，路长终是少人扶。早教幽梦到华胥。'},
    {t:'浣沙溪·日射欹红蜡蒂香',a:'周邦彦〔宋代〕',c:'日射欹红蜡蒂香。风干微汗粉襟凉。碧纱对掩簟纹光。\n自剪柳枝明画阁，戏抛莲菂种横塘。长亭无事好思量。'},
    {t:'浣纱女',a:'王昌龄〔唐代〕',c:'钱塘江畔是谁家，江上女儿全胜花。\n吴王在时不得出，今日公然来浣纱。'},
    {t:'浣溪沙',a:'辛弃疾〔宋代〕',c:'总把平生入醉乡。大都三万六千场。今古悠悠多少事，莫思量。\n微有寒些春雨好，更无寻处野花香。年去年来还又笑，燕飞忙。'},
    {t:'浣溪沙',a:'张炎〔宋代〕',c:'艾蒳香消火未残。便能晴去不多寒。冶游天气却身闲。\n带雨移花浑懒看，应时插柳日须攀。最堪惆怅是东阑。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'白纻春衫杨柳鞭，碧蹄骄马杏风鞯。落英飞絮冶游天。\n南陌暖风吹舞榭，东城凉月照歌筵。赏心多是酒中仙。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'白紵春衫杨柳鞭，碧蹄骄马杏风鞯。落英飞絮冶游天。\n南陌暖风吹舞榭，东城凉月照歌筵。赏心多是酒中仙。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'床上银屏几点山。鸭炉香过琐窗寒。小云双枕恨春闲。\n惜别漫成良夜醉，解愁时有翠笺还。那回分袂月初残。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'翠阁朱栏倚处危，\n夜凉闲捻彩倾吹。\n曲中双凤已分飞。\n绿酒细倾消别恨，\n红笺小写问归期。\n月华风意似当时。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'翠阁朱阑倚处危。夜凉闲捻彩倾吹。曲中双凤已分飞。\n绿酒细倾消别恨，红笺小写问归期。月华风意似当时。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'飞鹊台前晕翠蛾。千金新换绛痕螺。最难加意为颦多。\n几处睡痕留醉袖，一春愁思近横波。远山低尽不成歌。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'家近旗亭酒易酤。花时长得醉工夫。伴人歌笑懒妆梳。\n户外绿杨春系马，床前红烛夜呼卢。相逢还解有情无。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'楼上灯深欲闭门。梦云归去不留痕。几年芳草忆王孙。\n向日阑干依旧绿，试将前事倚黄昏，记曾来处易消魂。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'莫问逢春能几回。能歌能笑是人才。露花犹有好枝开。\n绿鬓旧人皆老大，红梁新燕又归来。尽须珍重掌中杯。'},
    {t:'浣溪沙',a:'黄庭坚〔宋代〕',c:'新妇滩头眉黛愁。女儿浦口眼波秋。惊鱼错认月沈钩。\n青箬笠前无限事，绿蓑衣底一时休。斜风吹雨转船头。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'浦口莲香夜不收。水边风里欲生秋。棹歌声细不惊鸥。\n凉月送归思往事，落英飘去起新愁。可堪题叶寄东楼。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'铜虎分符领外台。五云深处彩旌来。春随红旆过长淮。\n千里袴襦添旧暖，万家桃李间新栽。使星回首是三台。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'团扇初随碧簟收。画檐归燕尚迟留。靥朱眉翠喜清秋。\n风意未应迷狭路，灯痕犹自记高楼。露花烟叶与人愁。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'午醉西桥夕未醒。雨花凄断不尘听。归时应减鬓边青。\n衣化客尘今古道，柳含春意短长亭。凤楼争见路旁情。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'小杏春声学浪仙。疏梅清唱替哀弦。似花如雪绕琼筵。\n腮粉月痕妆罢后，脸红莲艳酒醒前。今年水调得人怜。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'一楼宫妆簇彩舟，\n碧罗团扇自障羞。\n水仙人在镜中游。\n腰自细来多态度，\n脸因红处转风流。\n年年相遇绿江头。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'一样宫妆簇彩舟。碧罗团扇自障羞。水仙人在镜中游。\n腰自细来多态度，脸因红处转风流。年年相遇绿江头。'},
    {t:'浣溪沙',a:'晏几道〔宋代〕',c:'已拆秋千不奈闲。却随胡蝶到花间。旋寻双叶插云鬟。\n几摺湘裙烟缕细，一钩罗袜素蟾弯。绿窗红豆忆前欢。'},
    {t:'浣溪沙·百亩中庭半是苔',a:'王安石〔宋代〕',c:'百亩中庭半是苔。门前白道水萦回。爱闲能有几人来。\n小院回廊春寂寂，山桃溪杏两三栽。为谁零落为谁开。'},
    {t:'浣溪沙·败叶填溪水已冰',a:'纳兰性德〔清代〕',c:'败叶填溪水已冰，夕阳犹照短临亭。何年废寺失题名。\n倚马客临碑上字，斗鸡人拨佛前灯，净消尘土礼金经。'},
    {t:'浣溪沙·半夜银山上积苏',a:'苏轼〔宋代〕',c:'半夜银山上积苏，朝来九陌带诗车。涛江烟渚一时无。\n空腹有诗衣有结，湿薪如桂米如珠。冻吟谁伴捻髭须。'},
    {t:'浣溪沙·宝扇轻圆浅画缯',a:'周邦彦〔宋代〕',c:'宝扇轻圆浅画缯，象床平稳细穿藤。飞蝇不到避壶冰。\n翠枕面凉频忆睡，玉箫手汗错成声。日长无力要人凭。'},
    {t:'浣溪沙·残雪凝辉冷画屏',a:'纳兰性德〔清代〕',c:'残雪凝辉冷画屏，落梅横笛已三更，更无人处月胧明。\n我是人间惆怅客，知君何事泪纵横，断肠声里忆平生。'},
    {t:'浣溪沙·常山道中即事',a:'辛弃疾〔宋代〕',c:'北陇田高踏水频。西溪禾早已凉新。隔墙沽酒煮纤鳞。\n忽有微凉何处雨，更无留影霎时云。卖瓜声过竹边村。'},
    {t:'浣溪沙·唱得红梅字字香',a:'晏几道〔宋代〕',c:'唱得红梅字字香。柳枝桃叶尽深藏。遏云声里送离觞。\n才听便拚衣袖湿，欲歌先倚黛眉长。曲终敲损燕钗梁。'},
    {t:'浣溪沙·春情',a:'苏轼〔宋代〕',c:'桃李溪边驻画轮。鹧鸪声里倒裳尊。夕阳虽好近黄昏。\n香在衣裳妆在臂，水连芳草月连云。几时归去不销魂。'},
    {t:'浣溪沙·次秀野酴醿韵',a:'朱熹〔宋代〕',c:'压架年来雪作堆。珍丛也是近晴栽。肯令容易放春回。却恐阴晴无定度，从教红白一时开。多情蜂蝶早飞来。'},
    {t:'浣溪沙·翠葆参差竹径成',a:'周邦彦〔宋代〕',c:'翠葆参差竹径成。新荷跳雨泪珠倾。曲阑斜转小池亭。\n风约帘衣归燕急，水摇扇影戏鱼惊。柳梢残日弄微晴。'},
    {t:'浣溪沙·淡淡梳妆薄薄衣',a:'晏殊〔宋代〕',c:'淡淡梳妆薄薄衣。天仙模样好容仪。旧欢前事入颦眉。\n闲役梦魂孤烛暗，恨无消息画帘垂。且留双泪说相思。'},
    {t:'浣溪沙·端午',a:'苏轼〔宋代〕',c:'轻汗微微透碧纨，明朝端午浴缠兰。流香涨腻满晴川。\n彩线轻缠红玉臂，小符斜挂绿云鬟。佳人相见一千年。'},
    {t:'浣溪沙·二月春花厌落梅',a:'晏几道〔宋代〕',c:'二月春花厌落梅。仙源归路碧云催。渭城丝雨劝离杯。\n欢意似云真薄幸，客鞭摇柳正多才，凤楼人待锦书来。'},
    {t:'浣溪沙·二月和风到碧城',a:'晏几道〔宋代〕',c:'二月和风到碧城。万条千缕绿眉迎。舞烟眠雨过清明。\n妆镜巧眉偷叶样，歌楼妍曲借枝名。晚秋霜霰莫无情。'},
    {t:'浣溪沙·风压轻云贴水飞',a:'苏轼〔宋代〕',c:'风压轻云贴水飞，乍晴池馆燕争泥。沈郎多病不胜衣。\n沙上不闻鸿雁信，竹间时听鹧鸪啼。此情惟有落花知！'},
    {t:'浣溪沙·凤髻抛残秋草生',a:'纳兰性德〔清代〕',c:'凤髻抛残秋草生，高梧湿月冷无声。当时七夕记深盟。\n信得羽衣传钿合，悔教罗袜葬倾城。人间空唱雨淋铃。'},
    {t:'浣溪沙·伏雨朝寒愁不胜',a:'纳兰性德〔清代〕',c:'伏雨朝寒愁不胜，那能还傍杏花行。去年高摘斗轻盈。\n漫惹炉烟双袖紫，空将酒晕一衫青。人间何处问多情。'},
    {t:'浣溪沙·父老争言雨水匀',a:'辛弃疾〔宋代〕',c:'父老争言雨水匀，眉头不似去年颦。殷勤谢却甑中尘。\n啼鸟有时能劝客，小桃无赖已撩人。梨花也作白头新。'},
    {t:'浣溪沙·赋清虚',a:'辛弃疾〔宋代〕',c:'强欲加餐竟未佳。只宜长伴病山斋。心似风吹香篆过，也无灰。\n山上朝来云出岫，随风一去未曾回。次第前村行雨了，合归来。'},
    {t:'浣溪沙·覆块青青麦未苏',a:'苏轼〔宋代〕',c:'覆块青青麦未苏，江南云叶暗收车。临皋烟景世间无。\n雨脚半收檐断线，雪林初下瓦疏珠。归来冰颗乱黏须。'},
    {t:'浣溪沙·庚申除夜',a:'纳兰性德〔清代〕',c:'收取闲心冷处浓，舞裙犹忆柘枝红。谁家刻烛待春风。\n竹叶樽空翻采燕，九枝灯灺颤金虫。风流端合倚天公。'},
    {t:'浣溪沙·古北口',a:'纳兰性德〔清代〕',c:'杨柳千条送马蹄，北来征雁旧情飞。客中谁与换春衣。\n终古闲情归落照，一春幽梦逐游丝。信回刚道别多时。'},
    {t:'浣溪沙·和无咎韵',a:'陆游〔宋代〕',c:'懒向沙头醉玉瓶，唤君同赏小窗明。夕阳吹角最关情。\n忙日苦多闲日少，新愁常续旧愁生。客中无伴怕君行。'},
    {t:'浣溪沙·荷花',a:'苏轼〔宋代〕',c:'四面垂杨十里荷，问云何处最花多。画楼南畔夕阳和。\n天气乍凉人寂寞，光阴须得酒消磨。且来花里听笙歌。'},
    {t:'浣溪沙·红蓼花香夹岸稠',a:'晏殊〔宋代〕',c:'红蓼花香夹岸稠，绿波春水向东流。小船轻舫好追游。\n渔父酒醒重拨棹，鸳鸯飞去却回头。一杯销尽两眉愁。'},
    {t:'浣溪沙·红桥怀古和王阮亭韵',a:'纳兰性德〔清代〕',c:'无恙年年汴水流。一声水调短亭秋。旧时明月照扬州。\n曾是长堤牵锦缆，绿杨清瘦至今愁。玉钩斜路近迷楼。'},
    {t:'浣溪沙·湖上西风急暮蝉',a:'晏殊〔宋代〕',c:'湖上西风急暮蝉。夜来清露湿辞莲。少留归骑促歌筵。\n为别莫辞金盏酒。入朝须近玉炉烟。不知重会是何年。'},
    {t:'浣溪沙·几共查梨到雪霜',a:'苏轼〔宋代〕',c:'几共查梨到雪霜，一经题品便来光，木奴何处避雌黄。\n北客有来初未识，南金无价喜新尝，含滋嚼句齿牙香。'},
    {t:'浣溪沙·记绾长条欲别难',a:'纳兰性德〔清代〕',c:'记绾长条欲别难，盈盈自此隔时湾。便无风雪也摧残。\n青雀几时裁锦字，玉虫连夜翦春旙。不禁辛苦况相关。'},
    {t:'浣溪沙·寄严荪友',a:'纳兰性德〔清代〕',c:'藕荡桥边理钓筒，苎萝西去五湖东。笔床茶灶太从容。\n况有短墙银杏雨，更兼高阁玉兰风。画眉闲了画芙蓉。'},
    {t:'浣溪沙·姜女祠',a:'纳兰性德〔清代〕',c:'海色残阳影断霓，寒涛日夜女郎祠。翠钿尘网上蛛丝。\n澄海楼高空极目，望夫石在且留题。六王如梦祖龙非。'},
    {t:'浣溪沙·锦样年华水样流',a:'纳兰性德〔清代〕',c:'锦样年华水样流，鲛珠迸落更难收。病余常是怯梳头。\n一径绿云修竹怨，半窗红日落花愁。愔愔只是下帘钩。'},
    {t:'浣溪沙·锦帐重重卷暮霞',a:'秦观〔宋代〕',c:'锦帐重重卷暮霞，屏风曲曲斗红牙，恨人何事苦离家。\n枕上梦魂飞不去，觉来红日又西斜，满庭芳草衬残花。'},
    {t:'浣溪沙·酒醒香销愁不胜',a:'纳兰性德〔清代〕',c:'酒醒香销愁不胜，如何更向落番行。去年高摘斗轻盈。\n夜雨几番销瘦了，繁华如梦总无凭。人间何处问多情。'},
    {t:'浣溪沙·菊节',a:'苏轼〔宋代〕',c:'缥缈危楼紫翠间，良辰乐事古难全。感时怀旧独凄然。\n璧月琼枝空夜夜，菊花人貌自年年。不知来岁与谁看。'},
    {t:'浣溪沙·肯把离情容易看',a:'纳兰性德〔清代〕',c:'肯把离情容易看，要从容易见艰难。难抛往事一般般。\n今夜灯前形共影，枕函虚置翠衾单。更无人与共春寒。'},
    {t:'浣溪沙·阆苑瑶台风露秋',a:'晏殊〔宋代〕',c:'阆苑瑶台风露秋，整鬟凝思捧觥筹。欲归临别强迟留。\n月好谩成孤枕梦，酒阑空得两眉愁。此时情绪悔风流。'},
    {t:'浣溪沙·泪浥红笺第几行',a:'纳兰性德〔清代〕',c:'泪浥红笺第几行，唤人娇鸟怕开窗。那能闲过好时光。\n屏障厌看金碧画，罗衣不奈水沉香。遍翻眉谱只寻常。'},
    {t:'浣溪沙·莲漏三声烛半条',a:'纳兰性德〔清代〕',c:'莲漏三声烛半条，杏花微雨湿看绡。那将看豆记无聊。\n春色已看浓似酒，归期安得信如潮。离魂入夜倩谁招。'},
    {t:'浣溪沙·楼上晴天碧四垂',a:'周邦彦〔宋代〕',c:'楼上晴天碧四垂，楼前芳草接天涯。劝君莫上最高梯。\n新笋已成堂下竹，落花都上燕巢泥。忍听林表杜鹃啼。'},
    {t:'浣溪沙·绿柳藏乌静掩关',a:'晏几道〔宋代〕',c:'绿柳藏乌静掩关。鸭炉香细琐窗闲。那回分袂月初残。\n惜别漫成良夜醉，解愁时有翠笺还。欲寻双叶寄情难。'},
    {t:'浣溪沙·绿叶红花媚晓烟',a:'晏殊〔宋代〕',c:'绿叶红花媚晓烟，黄蜂金蕊欲披莲。水风深处懒回船。\n可惜异香珠箔外，不辞清唱玉尊前。使星归觐九重天。'},
    {t:'浣溪沙·漠漠轻寒上小楼',a:'秦观〔宋代〕',c:'漠漠轻寒上小楼，晓阴无赖似花秋。澹烟流水画屏幽。\n自在飞花轻似梦，无边丝雨细如愁。宝帘闲挂小银钩。'},
    {t:'浣溪沙·抛却无端恨转长',a:'纳兰性德〔清代〕',c:'抛却无端恨转长，慈云稽首返生香。妙莲花说试推详。\n但是有情皆满愿，更从何处著思量。篆烟残烛并回肠。'},
    {t:'浣溪沙·缥缈红妆照浅溪',a:'苏轼〔宋代〕',c:'缥缈红妆照浅溪。薄云疏雨不成泥。送君何处古台西。\n废沼夜来秋水满，茂林深处晚莺啼。行人肠断草凄迷。'},
    {t:'浣溪沙·青杏园林著酒香',a:'晏殊〔宋代〕',c:'青杏园林著酒香。佳人初试薄罗裳。柳丝无力燕飞忙。\n乍雨乍晴花自落，闲愁闲闷日偏长。为谁消瘦减容光。'},
    {t:'浣溪沙·泉湖道中赴闽宪别诸君',a:'辛弃疾〔宋代〕',c:'细听春山杜宇啼。一声声是送行诗。朝来白鸟背人飞。\n对郑子真岩石卧，趁陶元亮菊花期。而今堪诵北山移。'},
    {t:'浣溪沙·日日双眉斗画长',a:'晏几道〔宋代〕',c:'日日双眉斗画长。行云飞絮共轻狂。不将心嫁冶游郎。\n溅酒滴残歌扇字，弄花熏得舞衣香。一春弹泪说凄凉。'},
    {t:'浣溪沙·容易浓香近画屏',a:'纳兰性德〔清代〕',c:'容易浓香近画屏，繁枝影著半窗横。风波狭路倍怜卿。\n未接语言犹怅望，才通商略已懵腾。只嫌今夜月偏明。'},
    {t:'浣溪沙·软草平莎过雨新',a:'苏轼〔宋代〕',c:'徐州石潭谢雨，道上作五首。潭清城东二十里，常与泗水增减清浊相应。\n软草平莎过雨新，轻沙走马路无尘。何时收拾耦耕身？\n日暖桑麻光似泼，风来蒿艾气如薰。使君元是此中人。'},
    {t:'浣溪沙·三月和风满上林',a:'晏殊〔宋代〕',c:'三月和风满上林，牡丹妖艳直千金。恼人天气又春阴。\n为我转回红脸面，向谁分付紫檀心。有情须殢酒杯深。'},
    {t:'浣溪沙·山色横侵蘸晕霞',a:'苏轼〔宋代〕',c:'山色横侵蘸晕霞，湘川风静吐寒花。远林屋散尚啼鸦。\n梦到故园多少路，酒醒南望隔天涯。月明千里照平沙。'},
    {t:'浣溪沙·谁道飘零不可怜',a:'纳兰性德〔清代〕',c:'谁道飘零不可怜，旧游时节好花天。断肠人去自经年。\n一片晕红才著雨，几丝柔绿乍和烟。倩魂销尽夕阳前。'},
    {t:'浣溪沙·谁念西风独自凉',a:'纳兰性德〔清代〕',c:'谁念西风独自凉，萧萧黄叶闭疏窗，沉思往事立残阳。\n被酒莫惊春睡重，赌书消得泼茶香，当时只道是寻常。'},
    {t:'浣溪沙·身向云山那畔行',a:'纳兰性德〔清代〕',c:'身向云山那畔行，北风吹断马嘶声，深秋远塞若为情！\n一抹晚烟荒戍垒，半竿斜日旧关城。古今幽恨几时平！'},
    {t:'浣溪沙·十八年来堕世间',a:'纳兰性德〔清代〕',c:'十八年来堕世间，吹花嚼蕊弄斜弦。多情情寄阿谁边。\n紫玉钗斜灯影背，红绵粉冷枕函偏。相看好处却无言。'},
    {t:'浣溪沙·十二红帘窣地深',a:'纳兰性德〔清代〕',c:'十二红帘窣地深，才移刬袜又沉吟。晚晴天气惜轻阴。\n珠衱佩囊三合字，宝钗拢髻两分心。定缘何事湿兰襟。'},
    {t:'浣溪沙·十里湖光载酒游',a:'纳兰性德〔清代〕',c:'十里湖光载酒游，青帘低映白苹洲。西风听彻采菱讴。\n沙岸有时双袖拥，画船何处一竿收。归来无语晚妆楼。'},
    {t:'浣溪沙·寿内子',a:'辛弃疾〔宋代〕',c:'寿酒同斟喜有余。朱颜却对白髭须。两人百岁恰乘除。\n婚嫁剩添儿女拜，平安频拆外家书。年年堂上寿星图。'},
    {t:'浣溪沙·水涨鱼天拍柳桥',a:'周邦彦〔宋代〕',c:'水涨鱼天拍柳桥，云鸠拖雨过团皋。一番春信入东郊。\n闲碾凤团消短梦，静看燕子垒新巢。又移日影上花梢。'},
    {t:'浣溪沙·送梅庭老赴上党学官',a:'苏轼〔宋代〕',c:'门外东风雪洒裾，山头回首望三吴。不应弹铗为无鱼。\n上党从来天下脊，先生元是古之儒。时平不用鲁连书。'},
    {t:'浣溪沙·送叶淳老',a:'苏轼〔宋代〕',c:'阳羡姑苏已买田。相逢谁信是前缘。莫教便唱水如天。\n我作洞霄君作守，白头相对故依然。西湖知有几同年。'},
    {t:'浣溪沙·宿酒才醒厌玉卮',a:'晏殊〔宋代〕',c:'宿酒才醒厌玉卮，水沈香冷懒熏衣。早梅先绽日边枝。\n寒雪寂寥初散后，春风悠扬欲来时。小屏闲放画帘垂。'},
    {t:'浣溪沙·簌簌衣巾落枣花',a:'苏轼〔宋代〕',c:'簌簌衣巾落枣花，村南村北响酒车，牛衣古柳卖黄瓜。\n酒困路长惟欲睡，日高人渴漫思茶。敲门试问野人家。'},
    {t:'浣溪沙·万里阴山万里沙',a:'纳兰性德〔清代〕',c:'万里阴山万里沙。谁将绿鬓斗霜华。年来强半在天涯。\n魂梦不离金屈戌，画图亲展玉鸦叉。生怜瘦减一分花。'},
    {t:'浣溪沙·万顷风涛不记苏',a:'苏轼〔宋代〕',c:'万顷风涛不记苏。雪晴江上麦千车。但令人饱我愁无。\n翠袖倚风萦柳絮，绛唇得酒烂樱珠。尊前呵手镊霜须。'},
    {t:'浣溪沙·卧鸭池头小苑开',a:'晏几道〔宋代〕',c:'卧鸭池头小苑开。暄风吹尽北枝梅。柳长莎软路萦回。\n静避绿阴莺有意，漫随游骑絮多才。去年今日忆同来。'},
    {t:'浣溪沙·五两竿头风欲平',a:'佚名〔五代〕',c:'五两竿头风欲平，长风举棹觉船轻。柔橹不施停却棹，是船行。\n满眼风波多闪灼，看山恰似走来迎。子细看山山不动，是船行。'},
    {t:'浣溪沙·五月江南麦已稀',a:'纳兰性德〔清代〕',c:'五月江南麦已稀，黄梅时节雨霏微。闲看燕子教雏飞。\n一水浓阴如罨画，数峰无恙又晴晖。湔裙谁独上渔矶。'},
    {t:'浣溪沙·五之三',a:'秦观〔宋代〕',c:'霜缟同心翠黛连。红绡四角缀收钱。恼人香爇是龙涎。\n枕上忽收疑是梦，灯前重看不成眠。又还一段恶因缘。'},
    {t:'浣溪沙·五之四',a:'秦观〔宋代〕',c:'脚上鞋儿四寸罗。唇边朱粉一樱多。见人无语但回波。\n料得有心怜宋玉，只应无奈楚襄何。今生有分共伊麽。'},
    {t:'浣溪沙·五字诗中目乍成',a:'纳兰性德〔清代〕',c:'五字诗中目乍成。尽教残福折期生。手挼裙带那时情。\n别后心期和梦杳，年来憔悴与愁并。夕阳依旧小窗明。'},
    {t:'浣溪沙·细雨斜风作晓寒',a:'苏轼〔宋代〕',c:'元丰七年十二月二十四日，从作州刘倩叔游南山\n细雨斜风作晓寒，淡烟疏柳媚晴滩。入淮清洛渐漫漫。\n雪沫乳花浮午盏，蓼茸蒿笋试春盘。人间有味是清欢。'},
    {t:'浣溪沙·闲弄筝弦懒系裙',a:'晏几道〔宋代〕',c:'闲弄筝弦懒系裙。铅华消尽见逢真。眼波低处事还新。\n怅恨不逢如意酒。寻思难值有情人。可怜虚度琐窗春。'},
    {t:'浣溪沙·香靥凝羞一笑开',a:'秦观〔宋代〕',c:'香靥凝羞一笑开，柳腰如醉暖相挨，日长春困下楼台。\n照水有情聊整鬓，倚栏无绪更兜鞋，眼边牵系懒归来。'},
    {t:'浣溪沙·消息谁传到拒霜',a:'纳兰性德〔清代〕',c:'消息谁传到拒霜？两行斜雁碧天长，晚秋风景倍凄凉。\n银蒜押帘人寂寂，玉钗敲竹信茫茫。黄花开也近重阳。'},
    {t:'浣溪沙·小阁重帘有燕过',a:'晏殊〔宋代〕',c:'小阁重帘有燕过。晚花红片落风莎。曲阑干影入凉波。\n一霎好风生翠幕，几回疏雨滴圆荷。酒醒人散得愁多。'},
    {t:'浣溪沙·偕叔高子似宿山寺戏作',a:'辛弃疾〔宋代〕',c:'花向今朝粉面匀。柳因何事翠眉颦。东风吹雨细於尘。\n自笑好山如好色，只今怀树更怀人。闲愁闲恨一番新。'},
    {t:'浣溪沙·徐邈能中酒圣贤',a:'苏轼〔宋代〕',c:'徐邈能中酒圣贤，刘伶席地幕青天，潘郎白璧为谁连。\n无可奈何新白发，不如归去旧青山，恨无人借买山钱。'},
    {t:'浣溪沙·旋抹红妆看使君',a:'苏轼〔宋代〕',c:'旋抹红妆看使君，三三五五棘携门。相挨踏破茜罗裙。\n老幼扶携收麦社，乌鸢翔舞赛神村。道逢醉叟卧黄昏。'},
    {t:'浣溪沙·杨柳阴中驻彩旌',a:'晏殊〔宋代〕',c:'杨柳阴中驻彩旌。芰荷香里劝金觥。小词流入管弦声。\n只有醉吟宽别恨，不须朝暮促归程。雨条烟叶系人情。'},
    {t:'浣溪沙·一半残阳下小楼',a:'纳兰性德〔清代〕',c:'一半残阳下小楼，朱帘斜控软金钩。倚阑无绪不能愁。\n有个盈盈骑马过，薄妆浅黛亦风流。见人羞涩却回头。'},
    {t:'浣溪沙·一曲新词酒一杯',a:'晏殊〔宋代〕',c:'一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？\n无可奈何花落去，似曾相识燕归来。小园香径独徘徊。'},
    {t:'浣溪沙·一向年光有限身',a:'晏殊〔宋代〕',c:'一向年光有限身，等闲离别易河魂，酒筵歌席莫辞频。\n满目山河空念远，落花风雨更伤春，不如怜取眼前人。'},
    {t:'浣溪沙·一叶扁舟卷画帘',a:'黄庭坚〔宋代〕',c:'一叶扁舟卷画帘。老妻学饮伴垂谈。人传诗句满江南。\n林下猿垂窥涤砚，岩前鹿卧看收帆。杜鹃声乱水如环。'},
    {t:'浣溪沙·已惯天涯莫浪愁',a:'纳兰性德〔清代〕',c:'已惯天涯莫浪愁，寒云衰草渐成秋。漫因睡起又登楼。\n伴我萧萧惟代马，笑人寂寂有牵牛，劳人只合一生休。'},
    {t:'浣溪沙·咏橘',a:'苏轼〔宋代〕',c:'菊暗荷枯一夜霜。新苞绿叶照林光。竹篱茅舍出青黄。\n香雾噀人惊半破，清泉流齿怯初尝。吴姬三日手犹香。'},
    {t:'浣溪沙·咏五更和湘真韵',a:'纳兰性德〔清代〕',c:'微晕娇花湿欲流，簟纹灯影一窥愁。梦回疑在远山楼。\n残月暗窥金屈戍，软风徐荡玉帘钩。待听邻女唤梳头。'},
    {t:'浣溪沙·游蕲水清泉寺',a:'苏轼〔宋代〕',c:'游蕲水清泉寺，寺临兰溪，溪水西流。\n山下兰芽短浸溪，松间沙路净无泥，萧萧暮雨子规啼。\n谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。'},
    {t:'浣溪沙·渔父',a:'苏轼〔宋代〕',c:'西塞山边白鹭飞，散花洲外片身微。桃花流水鳜鱼肥。\n自庇一身青箬笠，相随到处绿蓑衣。斜风细雨不须归。'},
    {t:'浣溪沙·雨过残红湿未飞',a:'周邦彦〔宋代〕',c:'雨过残红湿未飞，疏篱一带透斜晖。游蜂酿蜜窃香归。\n金屋无人风竹乱，衣篝尽日水沉微。一春须有忆人时。'},
    {t:'浣溪沙·雨歇梧桐泪乍收',a:'纳兰性德〔清代〕',c:'雨歇梧桐泪乍收，遣怀翻自忆从头。摘花销恨旧风流。\n帘影碧桃人已去，屧痕苍藓径空留。两眉何处月如钩？'},
    {t:'浣溪沙·玉碗冰寒滴露华',a:'晏殊〔宋代〕',c:'玉碗冰寒滴露华，粉融香雪透轻纱。晚来妆面胜荷花。\n鬓亸欲迎眉际月，酒红初上脸边霞。一场春梦日西斜。'},
    {t:'浣溪沙·欲寄愁心朔雁边',a:'纳兰性德〔清代〕',c:'欲寄愁心朔雁边，西风浊酒惨离颜。黄花时节碧云天。\n古戍烽烟迷斥堠，夕阳村落解鞍鞯。不知征战几人还。'},
    {t:'浣溪沙·欲问江梅瘦几分',a:'纳兰性德〔清代〕',c:'欲问江梅瘦几分，只看愁损翠寒裙。麝篝衾冷惜余熏。\n可耐暮寒长倚竹，便教春好不开门。枇杷花底校书人。'},
    {t:'浣溪沙·赠子文侍人名笑笑',a:'辛弃疾〔宋代〕',c:'侬是嶔崎可笑人，不妨开口笑时频。有人一笑坐生春。\n歌欲颦时还浅笑，醉逢笑处却轻颦。宜颦宜笑越精神。'},
    {t:'浣溪沙·照日深红暖见鱼',a:'苏轼〔宋代〕',c:'徐门石潭谢雨，道上作五首。潭清城东二十里，常于泗水增减清浊相应\n照日深红暖见鱼，连溪绿暗晚藏乌。黄童白叟聚睢盱。\n麋鹿逢人虽未惯，猿猱闻鼓不须呼。归家说与采桑姑。'},
    {t:'浣溪沙·争挽桐花两鬓垂',a:'周邦彦〔宋代〕',c:'争挽桐花两鬓垂，小妆弄影照金池。出帘踏袜趁蜂儿。\n跳脱添金双腕重，琵琶拨尽四弦悲。夜寒谁肯剪春衣。'},
    {t:'浣溪沙·脂粉塘空遍绿苔',a:'纳兰性德〔清代〕',c:'脂粉塘空遍绿苔，掠泥营垒燕相催。妒他飞去却飞回。\n一骑近从梅里过，片帆遥自藕溪来。博山香烬未全灰。'},
    {t:'浣溪沙·重九旧韵',a:'苏轼〔宋代〕',c:'白雪清词出坐间。爱君才器两俱全。异乡风景却依然。\n可恨相逢能几日，不知重会是何年。茱萸子细更重看。'},
    {t:'浣溪沙慢',a:'周邦彦〔宋代〕',c:'水竹旧院落，樱笋新蔬果。嫩英翠幄，红杏交榴火。心事暗卜，叶底寻双朵，深夜归青琐。灯尽酒醒时，晓窗明、钗横鬓嚲。\n怎生那。被间阻时多。奈愁肠数叠，幽恨万端，好梦还惊破。可怪近来，传语也无个。莫是瞋人呵。真个若瞋人，却因何、逢人问我。'},
    {t:'皇甫岳云溪杂题五首·莲花坞',a:'王维〔唐代〕',c:'日日采莲去，洲长多暮归。\n弄篙莫溅水，畏湿红莲衣。'},
    {t:'皇甫岳云溪杂题五首·鸬鹚堰',a:'王维〔唐代〕',c:'乍向红莲没，复出清蒲飏。\n独立何褵褷，衔鱼古查上。'},
    {t:'皇甫岳云溪杂题五首·萍池',a:'王维〔唐代〕',c:'春池深且广，会待轻舟回。\n靡靡绿萍合，垂杨扫复开。'},
    {t:'皇甫岳云溪杂题五首·上平田',a:'王维〔唐代〕',c:'朝耕上平田，暮耕上平田。\n借问问津者，宁知沮溺贤。'},
    {t:'黄葛篇',a:'李白〔唐代〕',c:'黄葛生洛溪，黄花自绵幂。\n青烟万条长，缭绕几百尺。\n闺人费素手，采缉作絺綌。\n缝为绝国衣，远寄日南客。\n苍梧大火落，暑服莫轻掷。\n此物虽过时，是妾手中迹。'},
    {t:'黄河',a:'王安石〔宋代〕',c:'派出昆仑五色流，一支黄浊贯中州。\n吹沙走浪几千里，转侧屋闾无处求。'},
    {t:'黄鹤楼',a:'陆游〔宋代〕',c:'手把仙人绿玉枝，吾行忽及早秋期。\n苍龙阙角归何晚，黄鹤楼中醉不知。\n江汉交流波渺渺，晋唐遗迹草离离。\n平生最喜听长笛，裂石穿云何处吹？'},
    {t:'黄鹤楼送孟浩然之广陵',a:'李白〔唐代〕',c:'故人西辞黄鹤楼，烟花三月下扬州。\n孤帆远影碧空尽，唯见长江天际流。'},
    {t:'黄家洞',a:'李贺〔唐代〕',c:'雀步蹙沙声促促，四尺角弓青石镞。\n黑幡三点铜鼓鸣，高作猿啼摇箭箙。\n彩巾缠踍幅半斜，溪头簇队映葛花。\n山潭晚雾吟白鼍，竹蛇飞蠹射金沙。\n闲驱竹马缓归家，官军自杀容州槎。'},
    {t:'黄鹂绕碧树·双调春情',a:'周邦彦〔宋代〕',c:'双阙笼嘉气，寒威日晚，岁华将暮。小院闲庭，对寒梅照雪，淡烟凝素。忍当迅景，动无限、伤春情绪。犹赖是、上苑风光渐好，芳容将煦。\n草荚兰芽渐吐。且寻芳、更休思虑。这浮世、甚驱驰利禄，奔竞尘土。纵有魏珠照乘，未买得流年住。争如盛饮流霞，醉偎琼树。'},
    {t:'黄雀痴',a:'王维〔唐代〕',c:'黄雀痴，黄雀痴，谓言青鷇是我儿。\n一一口衔食，养得成毛衣。\n到大啁啾解游飏，各自东西南北飞。\n薄暮空巢上，羁雌独自归。\n凤凰九雏亦如此，慎莫愁思憔悴损容辉。'},
    {t:'黄雀吟',a:'孟郊〔唐代〕',c:'黄雀舞承尘，倚恃主人仁。主人忽不仁，买弹弹尔身。\n何不远飞去，蓬蒿正繁新。蒿粒无人争，食之足为珍。\n莫觑翻车粟，觑翻罪有因。黄雀不知言，赠之徒殷勤。'},
    {t:'黄亭夜雨',a:'陆游〔宋代〕',c:'未到名山梦已新，千峰拔地玉嶙峋。\n幔亭一夜风吹雨，似与游人洗俗尘。'},
    {t:'黄头郎',a:'李贺〔唐代〕',c:'黄头郎，捞拢去不归。\n南浦芙蓉啼，愁红独自垂。\n水弄湘娥佩，竹啼山露月。\n玉瑟调青门，石云湿黄葛。\n沙上蘼芜花，秋风已先发。\n好持扫罗荐，香出鸳鸯热。'},
    {t:'黄莺儿·园林晴昼春谁主',a:'柳永〔宋代〕',c:'园林晴昼春谁主。暖律潜催，幽露暄和，黄鹂翩翩，乍迁芳树。观露湿缕金衣，叶映如簧语。晓来无上绵蛮，似把芳心深意低诉。\n无据。乍出暖烟来，又趁游蜂去。恣狂踪迹，两两相呼，终朝雾吟风舞。当上苑柳秾时，别馆花深处。此际海燕偏饶，都把韶光与。'},
    {t:'黄州',a:'陆游〔宋代〕',c:'局促常悲类楚囚，迁流还叹学私优。\n江声不尽英雄恨，天意无私草木秋。\n万里羁愁添白发，一帆寒日过黄州。\n君看赤壁终陈迹，生子何须似仲谋！'},
    {t:'回车驾言迈',a:'佚名〔两汉〕',c:'回车驾言迈，悠悠涉长道。\n四顾何茫茫，东风摇百草。\n所遇无故物，焉得不速老。\n盛衰各有时，立身苦不早。\n人生非金石，岂能长寿考？\n奄忽随物化，荣名以为宝。'},
    {t:'回董提举中秋请宴启',a:'文天祥〔宋代〕',c:'照江叠节，载画舫之清冰；待月举杯，呼芳樽于绿净。拜华星之坠几，约明月之浮槎。\n风雨满城，何幸两重阳之近；江山如画，尚从前赤壁之游。槁秸申酬，轮嗣布。'},
    {t:'回中牡丹为雨所败二首',a:'李商隐〔唐代〕',c:'下苑他年未可追，西州今日忽相期。\n水亭暮雨寒犹在，罗荐春香暖不知。\n舞蝶殷勤收落蕊，佳人惆怅卧遥帷。\n章台街里芳菲伴，且问宫腰损几枝？\n浪笑榴花不及春，先期零落更愁人。\n玉盘迸泪伤心数，锦瑟惊弦破梦频。\n万里重阴非旧圃，一年生意属流尘。\n前溪舞罢君回顾，并觉今朝粉态新。'},
    {t:'回中作',a:'温庭筠〔唐代〕',c:'苍莽寒空远色愁，呜呜戍角上高楼。\n吴姬怨思吹双管，燕客悲歌别五侯。\n千里关山边草暮，一星烽火朔云秋。\n夜来霜重西风起，陇水无声冻不流。'},
    {t:'会昌丙寅丰岁歌·杂言',a:'温庭筠〔唐代〕',c:'丙寅岁，休牛马。风如吹烟，日如渥赭。\n九重天子调天下，萶绿将年到西野。\n西野翁，生儿童。门前好树青䒠茸。\n䒠茸单衣麦田路，村南娶妇桃花红。\n新姑车石及门柱，粉项韩凭双扇中。\n喜气自能成岁丰，农祥尔物来争功。'},
    {t:'会蓬莱阁',a:'秦观〔宋代〕',c:'冠裳盖座洒清风，轩外时闻韵箨龙。人面春生红玉液，银盘烟覆紫驼峰。\n天涵秋色山山共，树搅乡思叶叶重。便欲买船江北去，为怀明德更从容。'},
    {t:'晦日陪侍御泛北池',a:'岑参〔唐代〕',c:'春池满复宽，晦节耐邀欢。月带虾蟆冷，霜随獬豸寒。\n水云低锦席，岸柳拂金盘。日暮舟中散，都人夹道看。'},
    {t:'晦日宴高氏林亭',a:'陈子昂〔唐代〕',c:'寻春游上路。\n追宴入山家。\n主第簪缨满。\n皇州景望华。\n玉池初吐溜。\n珠树始开花。\n欢娱方未极。\n林阁散余霞。'},
    {t:'晦日重宴高氏林亭',a:'陈子昂〔唐代〕',c:'公子好追随。\n爱客不知疲。\n象筵开玉馔。\n翠羽饰金卮。\n此时高宴所。\n讵灭习家池。\n循涯倦短翮。\n何处俪长离。'},
    {t:'惠崇春江晚景二首',a:'苏轼〔宋代〕',c:'竹外桃花三两枝，春江水暖鸭先知。\n蒌蒿满地芦芽短，正是河豚欲上时。\n两两归鸿欲破群，依依还似北归人。\n遥知朔漠多风雪，更待江南半月春。'},
    {t:'惠州丰湖亦名西湖',a:'杨万里〔宋代〕',c:'左瞰丰湖右瞰江，五峰出没水中央。\n峰头寺寺楼楼月，清杀东坡锦绣肠。\n三处西湖一色秋，钱塘颖水更罗浮。\n东坡元是西湖长，不到罗浮便得休。'},
    {t:'惠州一绝',a:'苏轼〔宋代〕',c:'罗浮山下四时春，卢橘杨梅次第新。\n日啖荔枝三百颗，不辞长作岭南人。'},
    {t:'蕙兰芳引·寒莹晚空',a:'周邦彦〔宋代〕',c:'寒莹晚空，点清镜、断霞孤鹜。对客馆深扃，霜草未衰更绿。倦游厌旅，但梦绕、阿娇金屋。想故人别后，尽日空疑风竹。\n塞北氍毹，江南图障，是处温燠。更花管云笺，犹写寄情旧曲。音尘迢递，但劳远目。今夜长，争奈枕单人独。'},
    {t:'昏镜词',a:'刘禹锡〔唐代〕',c:'镜之工列十镜于贾奁，发奁而视，其一皎如，其九雾如。或曰：“良苦之不侔甚矣。”工解颐谢曰：“非不能尽良也，盖贾之意，唯售是念，今来市者，必历鉴周睐，求与己宜。彼皎者不能隐芒杪之瑕，非美容不合，是用什一其数也。”予感之，作《昏镜词》。\n昏镜非美金，漠然丧其晶。\n陋容多自欺，谓若他镜明。\n瑕疵自不见，妍态随意生。\n一日四五照，自言美倾城。\n饰带以纹绣，装匣以琼瑛。\n秦宫岂不重，非适乃为轻。'},
    {t:'浑侍中宅牡丹',a:'刘禹锡〔唐代〕',c:'径尺千馀朵，人间有此花。今朝见颜色，更不向诸家。'},
    {t:'火山云歌送别',a:'岑参〔唐代〕',c:'火山突兀赤亭口，火山五月火云厚。\n火云满山凝未开，飞鸟千里不敢来。\n平明乍逐胡风断，薄暮浑随塞雨回。\n缭绕斜吞铁关树，氛氲半掩交河戍。\n迢迢征路火山东，山上孤云随马去。'},
    {t:'击磐老人',a:'王昌龄〔唐代〕',c:'双峰褐衣久，一磐白眉长。\n谁识野人意，徒看春草芳。'},
    {t:'击磬老人',a:'王昌龄〔唐代〕',c:'双峰褐衣久，一磬白眉长。\n谁识野人意，徒看春草芳。'},
    {t:'击壤歌',a:'佚名〔先秦〕',c:'日出而作，日入而息。\n凿井而饮，耕田而食。\n帝力于我何有哉！'},
    {t:'击梧桐·香靥深深',a:'柳永〔宋代〕',c:'香靥深深，姿姿媚媚，雅格奇容天与。自识伊来，便好看承，会得妖娆心素。临歧再约同欢，定是都把、平生相许。又恐恩情，易破难成，未免千般思虑。\n近日书来，寒暄而已，苦没忉忉言语。便认得、听人教当，拟把前言轻负。见说兰台宋玉，多才多艺善词赋。试与问、朝朝暮暮。行云何处去。'},
    {t:'饥雪吟',a:'孟郊〔唐代〕',c:'饥乌夜相啄，疮声互悲鸣。冰肠一直刀，天杀无曲情。\n大雪压梧桐，折柴堕峥嵘。安知鸾凤巢，不与枭鸢倾。\n下有幸灾儿，拾遗多新争。但求彼失所，但夸此经营。\n君子亦拾遗，拾遗非拾名。将补鸾凤巢，免与枭鸢并。\n因为饥雪吟，至晓竟不平。'},
    {t:'鸡鸣埭曲',a:'温庭筠〔唐代〕',c:'南朝天子射雉时，银河耿耿星参差。\n铜壶漏断梦初觉，宝马尘高人未知。\n鱼跃莲东荡宫沼，濛濛御柳悬栖鸟。\n红妆万户镜中春，碧树一声天下晓。\n盘踞势穷三百年，朱方杀气成愁烟。\n彗星拂地浪连海，战鼓渡江尘涨天。\n绣龙画雉填宫井，野火风驱烧九鼎。\n殿巢江燕砌生蒿，十二金人霜炯炯。\n芊绵平绿台城基，暖色春容荒古陂。\n宁知玉树后庭曲，留待野棠如雪枝。'},
    {t:'鸡鸣歌',a:'佚名〔两汉〕',c:'东方欲明星烂烂，汝南晨鸡登稀唤。\n曲终漏尽严具陈，月没星稀天下旦。\n千门万户递鱼钥，宫中城上飞乌鹊。'},
    {t:'积雨辋川庄作',a:'王维〔唐代〕',c:'积雨空林烟火迟，蒸藜炊黍饷东菑。\n漠漠水田飞白鹭，阴阴夏木啭黄鹂。\n山中习静观朝槿，松下清斋折露葵。\n野老与人争席罢，海鸥何事更相疑。'},
    {t:'稽庄即事',a:'文天祥〔宋代〕',c:'乃心王室故，日夜奔南征。\n蹈险宁追悔，怀忠莫见明。\n雁声连水远，山色与天平。\n枉作穷途哭，男儿付死生。'},
    {t:'羁旅行',a:'张籍〔唐代〕',c:'远客出门行路难，停车敛策在门端。荒城无人霜满路，\n野火烧桥不得度。寒虫入窟鸟归巢，僮仆问我谁家去。\n行寻田头暝未息，双毂长辕碍荆棘。缘冈入涧投田家，\n主人舂米为夜食。晨鸡喔喔茅屋傍，行人起扫车上霜。\n旧山已别行已远，身计未成难复返。长安陌上相识稀，\n遥望天山白日晚。谁能听我辛苦行，为向君前歌一声。'},
    {t:'及第东归次灞上，却寄同年',a:'李商隐〔唐代〕',c:'芳桂当年各一枝，行期未分压云期。江鱼朔雁长相忆，\n秦树嵩云自不知。下苑经过劳想像，东门送饯又差池。\n灞陵柳色无离恨，莫枉长条赠所思。'},
    {t:'及第后寄长安故人',a:'杜牧〔唐代〕',c:'东都放榜未花开，三十三人走马回。\n秦地少年多酿酒，已将春色入关来。'},
    {t:'吉祥寺赏牡丹',a:'苏轼〔宋代〕',c:'人老簪花不自羞，花应羞上老人头。\n醉归扶路人应笑，十里珠帘半上钩。'},
    {t:'汲江煎茶',a:'苏轼〔宋代〕',c:'活水还须活火烹，自临钓石取深清。\n大瓢贮月归春瓮，小杓分江入夜瓶。\n雪乳已翻煎处脚，松风忽作泻时声。\n枯肠未易禁三碗，坐听荒城长短更。'},
    {t:'即目',a:'李商隐〔唐代〕',c:'地宽楼已迥，人更迥于楼。细意经春物，伤酲属暮愁。\n望赊殊易断，恨久欲难收。大势真无利，多情岂自由。\n空园兼树废，败港拥花流。书去青枫驿，鸿归杜若洲。\n单栖应分定，辞疾索谁忧。更替林鸦恨，惊频去不休。'},
    {t:'即日',a:'李商隐〔唐代〕',c:'一岁林花即日休，江间亭下怅开留。\n重吟细把真无奈，已落犹开未放愁。\n山色正来衔小苑，春阴只欲傍高楼。\n金鞍忽散银壶漏，更醉谁家白玉钩。'},
    {t:'即事',a:'杜甫〔唐代〕',c:'暮春三月巫峡长，皛皛行云浮日光。\n雷声忽送千峰雨，花气浑如百和香。\n黄莺过水翻回去，燕子衔泥湿不妨。\n飞阁卷帘图画里，虚无只少对潇湘。'},
    {t:'即事',a:'王安石〔宋代〕',c:'径暖草如积，山晴花更繁。\n纵横一川水，高下数家村。\n静憩鸡鸣午，荒寻犬吠昏。\n归来向人说，疑是武陵源。'},
    {t:'即事',a:'文天祥〔宋代〕',c:'痛哭辞京阙，微行访海门。\n久无鸡可听，新有虱堪扪。\n白发应多长，苍头少有存。\n但令身未死，随力报乾坤。'},
    {t:'即事',a:'杜牧〔唐代〕',c:'小院无人雨长苔，满庭修竹间疏槐。\n春愁兀兀成幽梦，又被流莺唤醒来。'},
    {t:'即事二首',a:'王安石〔宋代〕',c:'云从无心来，还向无心去。\n无心无处寻，莫觅无心处。'},
    {t:'即事二首其一',a:'王安石〔宋代〕',c:'云从钟山起，却入钟山去。借问山中人，云今在何处。'},
    {t:'即事三首',a:'王安石〔宋代〕',c:'日月随天旋，疾迟与天谋。\n寒暑自有常，不顾万物求。\n蜉蝣蔽朝夕，蟪蛄疑春秋。\n眇眇上古历，回环今几周。'},
    {t:'即事五首',a:'王安石〔宋代〕',c:'春光冉冉归何处，细雨斜风作夜寒。\n犹有数葩红好处，老年花似雾中看。'},
    {t:'即席呈太傅相公',a:'范仲淹〔宋代〕',c:'凤池三入冠台躔，致了升平一品闲。\n白傅歌诗傅海外，晋公桃李满人间。\n上都云远经时别，故国春浓几度还。\n太史占天应有奏，寿星光彩近南山。'},
    {t:'集汤评事衡湖上望微雨',a:'皎然〔唐代〕',c:'苍凉远景中，雨色缘山有。云送满洞庭，风吹绕杨柳。\n萧萧解轻袂，尽日随林叟。'},
    {t:'集贤宾·小楼深巷狂游遍',a:'柳永〔宋代〕',c:'小楼深巷狂游遍，罗绮成丛。就描堪人属意，最是虫虫。有画难描雅态，无花可比芳容。几回饮得良宵永，鸳衾暖、凤枕香浓。算得人间天上，惟有两心同。\n近来云雨忽西东。诮恼损情悰。纵然偷期暗会，长是匆匆。争似和鸣偕老，免教敛翠啼红。眼前时、暂疏欢宴，盟言在、更莫忡忡。待作真个宅院，方信有初终。'},
    {t:'己酉岁九月九日',a:'陶渊明〔魏晋〕',c:'靡靡秋已夕，凄凄风露交。\n蔓草不复荣，园木空自凋。\n清气澄余滓，杳然天界高。\n哀蝉无留响，丛雁鸣云霄。\n万化相寻绎，人生岂不劳？\n从古皆有没，念之中心焦。\n何以称我情？浊酒且自陶。\n千载非所知，聊以永今朝。'},
    {t:'己酉元日',a:'陆游〔宋代〕',c:'夜雨解残雪，朝阳开积阴。\n桃符呵笔写，椒酒过花斟。\n巷柳摇风早，街泥溅马深。\n行宫放朝贺，共识慕尧心。'},
    {t:'麂',a:'杜甫〔唐代〕',c:'永与清溪别，蒙将玉馔俱。\n无才逐仙隐，不敢恨庖厨。\n乱世轻全物，微声及祸枢。\n衣冠兼盗贼，饕餮用斯须。'},
    {t:'记承天寺夜游',a:'苏轼〔宋代〕',c:'元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。念无与为乐者，遂至承天寺寻张怀民。怀民亦未寝，相与步于中庭。庭下如积水空明，水中藻、荇交横，盖竹柏影也。何夜无月？何处无竹柏？但少闲人如吾两人者耳。'},
    {t:'记梦',a:'陆游〔宋代〕',c:'梦里都忘困晚途，纵横草疏论迁都。\n不知尽挽银河水，洗得平生习气无？'},
    {t:'记游松风亭',a:'苏轼〔宋代〕',c:'余尝寓居惠州嘉祐寺，纵步松风亭下。足力疲乏，思欲就亭止息。望亭宇尚在木末，意谓是如何得到？良久，忽曰：“此间有甚么歇不得处？”由是如挂钩之鱼，忽得解脱。若人悟此，虽兵阵相接，鼓声如雷霆，进则死敌，退则死法，当恁么时也不妨熟歇。'},
    {t:'记征人语',a:'纳兰性德〔清代〕',c:'边月无端照别离，故园何处寄相思。\n西风不解征人语，一夕萧萧满大旗。'},
    {t:'纪事',a:'文天祥〔宋代〕',c:'枭獍何堪共劝酬，衣冠涂炭可胜羞。\n袖中若有击贼笏，便使凶渠面血流。'},
    {t:'纪闲',a:'文天祥〔宋代〕',c:'九十春光好，周流人鬼关。\n人情轻似土，世路险于山。\n俯仰经行处，死生谈笑间。\n近时最难得，旬日海陵闲。'},
    {t:'济上四贤咏·成文学',a:'王维〔唐代〕',c:'宝剑千金装，登君白玉堂。\n身为平原客，家有邯郸娼。\n使气公卿坐，论心游侠场。\n中年不得意，谢病客游梁。'},
    {t:'济上四贤咏·崔录事',a:'王维〔唐代〕',c:'解印归田里，贤哉此丈夫。\n少年曾任侠，晚节更为儒。\n遁迹东山下，因家沧海隅。\n已闻能狎鸟，余欲共乘桴。'},
    {t:'济源春',a:'孟郊〔唐代〕',c:'太行横偃脊，百里芳崔巍。济滨花异颜，枋口云如裁。\n新画彩色湿，上界光影来。深红缕草木，浅碧珩溯洄。\n千家门前饮，一道传禊杯。玉鳞吞金钩，仙璇琉璃开。\n朴童茂言语，善俗无惊猜。狂吹寝恒宴，晓清梦先回。\n治生鲜惰夫，积学多深材。再游讵癫戆，一洗惊尘埃。'},
    {t:'济州过赵叟家宴',a:'王维〔唐代〕',c:'虽与人境接，闭门成隐居。\n道言庄叟事，儒行鲁人馀。\n深巷斜晖静，闲门高柳疏。\n荷锄修药圃，散帙曝农书。\n上客摇芳翰，中厨馈野蔬。\n夫君第高饮，景晏出林闾。'},
    {t:'祭天神·欢笑筵歌席轻抛亸',a:'柳永〔宋代〕',c:'欢笑筵歌席轻抛亸。背孤城、几数烟村停画舸。更深钓叟归来，数点残灯火。被连绵宿酒醺醺，行无那。寂寞拥、重衾卧。\n又闻得、行客扁舟过。篷窗近，兰棹急，好梦还惊破。念平生、单栖踪迹，多感情怀，到此厌厌，向晓披衣坐。'},
    {t:'祭天神·歇指调',a:'柳永〔宋代〕',c:'忆绣衾相向轻轻语。屏山掩、红蜡长明，金兽盛熏兰炷。何期到此，酒态花情顿孤负。柔肠断、还是黄昏，那更满庭风雨。\n听空阶和漏，碎声斗滴愁眉聚。算伊还共谁人，争知此冤苦。念千里烟波，迢迢前约，旧欢慵省，一向无心绪。'},
    {t:'寄安素高处士',a:'范仲淹〔宋代〕',c:'吏隐南阳味日新，幕中文雅尽嘉宾。\n满轩明月满谭夜，共忆诗书万卷人。'},
    {t:'寄白二十二舍人',a:'张籍〔唐代〕',c:'早知内诏过先辈，蹭蹬江南百后疏。\n湓浦城中为上佐，炉峰寺后著幽居。\n偏依仙法多求药，长共僧游不读书。\n三省比来名望重，肯容君去乐樵渔。'},
    {t:'寄白学士',a:'张籍〔唐代〕',c:'自掌天书见客稀，纵因休沐锁双扉。\n几回扶病欲相访，知向禁中归未归。'},
    {t:'寄报德寺从上人·鼓吹山在寺西',a:'皎然〔唐代〕',c:'宗流许身子，物表养高闲。空色清凉寺，秋声鼓吹山。\n看心水磬后，行道雨花间。七叶翻章句，时时启义关。'},
    {t:'寄别李儋',a:'韦应物〔唐代〕',c:'首戴惠文冠，心有决胜筹。翩翩幕五骑，结束向并州。\n名在相公幕，丘山恩未酬。妻子不及顾，亲绸安得留。\n宿昔同文翰，交分共绸缪。忽枉别离札，涕泪一交流。\n远郡卧残疾，凉气满西楼。想子临长路，时当淮海秋。'},
    {t:'寄别说道',a:'黄庭坚〔宋代〕',c:'数行嘉树红张锦，一派春波绿橹油。\n回望江城见归鸟，乱鸣双橹散轻鸥。\n柳条折赠经年别，芦箎吹成落日愁。\n双鲤寄书难尽信，有情江水尚回流。'},
    {t:'寄蔡氏女子二首',a:'王安石〔宋代〕',c:'建业东郭，望城西堠。\n千嶂承宇，宛泉绕溜。\n青遥遥兮纚属，绿宛宛兮横逼。\n积李兮缟夜，崇桃兮柳昼。\n兰馥兮众植，竹娟兮常茂。\n柳蔫绵兮含姿，松偃蹇兮献秀。\n鸟跂兮下上，鱼跳兮左右。\n顾我兮适我，有斑兮伏兽。\n感时物兮念汝，迟汝归兮携幼。'},
    {t:'寄菖蒲',a:'张籍〔唐代〕',c:'石上生菖蒲，一寸十二节。仙人劝我食，令我头青面如雪。\n逢人寄君一绛囊，书中不得传此方。君能来作栖霞侣，\n与君同入丹玄乡。'},
    {t:'寄常一上人',a:'皎然〔唐代〕',c:'雁塞五山临汗漫，云州一路出青冥。\n何因请住嘉祥寺，内史新修湖上亭。'},
    {t:'寄畅当·闻以子弟被召从军',a:'韦应物〔唐代〕',c:'寇贼起东山，英俊方未闲。\n闻君场应募，籍籍动京关。\n出身文翰场，高步不可攀。\n青袍未及解，白霜插腰间。\n昔为琼树枝，今有风霜颜。\n秋郊细柳道，走马一夕还。\n丈夫当为国，破敌如摧山。\n何必事州府，坐使鬓毛斑。'},
    {t:'寄晁元中十首',a:'黄庭坚〔宋代〕',c:'河清无人待，兰芳无人采。\n山空露团团，葛蔓石磊磊。\n世有倾国媒，一笑珠百琲。\n往时祢处士，颠倒孔北海。'},
    {t:'寄陈季常',a:'秦观〔宋代〕',c:'一钩五十犗，始具任公钓。\n揭竿趣灌渎，与尔不同调。\n先生本西蜀，侠气见英妙。\n哀怜世间儿，细黠似黄鹞。\n侍童双擢玉，鬓发光可照。\n骏马锦障泥，相随穷海峤。\n平生携手好，十七登廊庙。\n小生相吏耶，徒枉尺书召。\n暮年更折节，学佛得心要。\n鬻马放阿樊，幅巾对沉燎。\n泠泠屋外泉，兀兀原头烧。\n欲知山中乐，万古同一笑。'},
    {t:'寄崇梵僧',a:'王维〔唐代〕',c:'崇梵僧，崇梵僧，秋归覆釜春不还。\n落花啼鸟纷纷乱，涧户山窗寂寂闲。\n峡里谁知有人事，郡中遥望空云山。'},
    {t:'寄崔万芳夔',a:'皎然〔唐代〕',c:'气杀高隼击，惜芳步寒林。风摇苍琅根，霜剪荍y心。\n归思忽眇眇，佳气亦沉沉。我身岂遐远，如隔湘汉深。\n事迩智莫及，愿乖情不任。迟君忘言侣，一笑开吾襟。'},
    {t:'寄崔先生',a:'温庭筠〔唐代〕',c:'往年江海别元卿，家近山阳古郡城。莲浦香中离席散，\n柳堤风里钓船横。星霜荏苒无音信，烟水微茫变姓名。\n菰黍正肥鱼正美，五侯门下负平生。'},
    {t:'寄东鲁二稚子',a:'李白〔唐代〕',c:'吴地桑叶绿，吴蚕已三眠。\n我家寄东鲁，谁种龟阴田？\n春事已不及，江行复茫然。\n南风吹归心，飞堕酒楼前。\n楼东一株桃，枝叶拂青烟。\n此树我所种，别来向三年。\n桃今与楼齐，我行尚未旋。\n娇女字平阳，折花倚桃边。\n折花不见我，泪下如流泉。\n小儿名伯禽，与姊亦齐肩。\n双行桃树下，抚背复谁怜？\n念此失次第，肝肠日忧煎。\n裂素写远意，因之汶阳川。'},
    {t:'寄杜子二首',a:'杜牧〔唐代〕',c:'不识长杨事北胡，且教红袖醉生扶。\n狂风烈焰虽千尺，豁得平生俊气无。\n武牢关吏应相笑，个里年年往复生。\n若问使君何处去，为言相忆首长回。'},
    {t:'寄二严',a:'韦应物〔唐代〕',c:'丝竹久已懒，今日遇君忺。\n打破蜘蛛千道网，总为鶺鴒两个严。'},
    {t:'寄故人',a:'张籍〔唐代〕',c:'静曲闲房病客居，蝉声满树槿花疏。\n故人只在蓝田县，强半年来未得书。'},
    {t:'寄韩谏议注',a:'杜甫〔唐代〕',c:'今我不乐思岳阳，身欲奋飞病在床。\n美人娟娟隔秋水，濯足洞庭望八荒。\n鸿飞冥冥日月白，青枫叶赤天雨霜。\n玉京群帝集北斗，或骑麒麟翳凤凰。\n芙蓉旌旗烟雾落，影动倒景摇潇湘。\n星宫之君醉琼浆，羽人稀少不在旁。\n似闻昨者赤松子，恐是汉代韩张良。\n昔随刘氏定长安，帷幄未改神惨伤。\n国家成败吾岂敢，色难腥腐餐枫香。\n周南留滞古所惜，南极老人应寿昌。\n美人胡为隔秋水，焉得置之贡玉堂。'},
    {t:'寄韩愈',a:'张籍〔唐代〕',c:'野馆非我室，新居未能安。\n读书避尘杂，方觉此地闲。\n过郭多园墟，桑果相接连。\n独游竟寂寞，如寄空云山。\n夏景常昼毒，密林无鸣蝉。\n临溪一盥濯，清去肢体烦。\n出林望曾城，君子在其间。\n戎府草章记，阻我此游盘。\n忆昔西潭时，并持钓鱼竿。\n共忻得鲂鲤，烹鲙于我前。\n几朝还复来，叹息时独言。'},
    {t:'寄韩樽',a:'岑参〔唐代〕',c:'夫子素多疾，别来未得书。北庭苦寒地，体内今何如。'},
    {t:'寄和州刘使君',a:'张籍〔唐代〕',c:'别离已久犹为郡，闲向春风倒酒瓶。\n送客特过沙口堰，看花多上水心亭。\n晓来江气连城白，雨后山光满郭青。\n到此诗情应更远，醉中高咏有谁听。'},
    {t:'寄河南杜少尹',a:'温庭筠〔唐代〕',c:'十载归来鬓未凋，玳簪珠履见常僚。岂关名利分荣路，\n自有才华作庆霄。鸟影参差经上苑，骑声断续过中桥。\n夕阳亭畔山如画，应念田歌正寂寥。'},
    {t:'寄河上段十六',a:'王维〔唐代〕',c:'与君相见即相亲，闻道君家在孟津。\n为见行舟试借问，客中时有洛阳人。'},
    {t:'寄贺方回',a:'黄庭坚〔宋代〕',c:'少游醉卧古藤下，谁与愁眉唱一杯。\n解作江南断肠句，只今唯有贺方回。'},
    {t:'寄恒璨',a:'韦应物〔唐代〕',c:'心绝去来缘，迹顺人间事。独寻秋草径，夜宿寒山寺。\n今日郡斋闲，思问楞伽字。'},
    {t:'寄洪州幕府卢二十一侍御',a:'韦应物〔唐代〕',c:'忽报南昌令，乘骢入郡城。\n同时趋府客，此日望尘迎。\n文苑台中妙，冰壶幕下清。\n洛阳相去远，犹使故林荣。'},
    {t:'寄胡饼与杨万州',a:'白居易〔唐代〕',c:'胡麻饼样学京都，面脆油香新出炉。\n寄与饥馋杨大使，尝看得似辅兴无。'},
    {t:'寄华岳孙逸人',a:'李商隐〔唐代〕',c:'灵岳几千仞，老松逾百寻。\n攀崖仍蹑壁，啖叶复眠阴。\n海上呼三岛，斋中戏五禽。\n唯应逢阮籍，长啸作鸾音。'},
    {t:'寄淮南友人',a:'李白〔唐代〕',c:'红颜悲旧国，青岁歇芳洲。\n不待金门诏，空持宝剑游。\n海云迷驿道，江月隐乡楼。\n复作淮南客，因逢桂树留。'},
    {t:'寄黄、刘二尊师',a:'韦应物〔唐代〕',c:'庐山两道士，各在一峰居。\n矫掌白云表，晞发阳和初。\n清夜降真侣，焚香满空虚。\n中有无为乐，自然与世疏。\n道尊不可屈，符守岂暇馀。\n高斋遥致敬，愿示一编书。'},
    {t:'寄黄几复',a:'黄庭坚〔宋代〕',c:'我居北海君南海，寄雁传书谢不能。\n桃李春风一杯酒，江湖夜雨十年灯。\n持家但有四立壁，治病不蕲三折肱。\n想见读书头已白，隔溪猿哭瘴溪藤。'},
    {t:'寄籍溪胡丈及刘恭',a:'朱熹〔宋代〕',c:'先生去上芸香阁，阁老新峨豸角冠。留取幽人卧空谷，一川风月要人看。'},
    {t:'寄皎然上人',a:'韦应物〔唐代〕',c:'吴兴老释子，野雪盖精庐。诗名夜自振，道心长晏如。\n想兹栖禅夜，见月东峰初。鸣钟惊岩壑，焚为满空虚。\n叨慕端成旧，未识岂为疏。愿以碧云思，方君怨别馀。\n茂苑文华地，流水古僧居。何当一游咏，倚阁吟踌躇。'},
    {t:'寄荆州张丞相',a:'王维〔唐代〕',c:'所思竟何在，怅望深荆门。\n举世无相识，终身思旧恩。\n方将与农圃，艺植老丘园。\n目尽南飞雁，何由寄一言。'},
    {t:'寄朗州温右史曹长',a:'刘禹锡〔唐代〕',c:'暂别瑶墀鸳鹭行，彩旗双引到沅湘。城边流水桃花过，\n帘外春风杜若香。史笔枉将书纸尾，朝缨不称濯沧浪。\n云台公业家声在，征诏何时出建章。'},
    {t:'寄乐天',a:'元稹〔唐代〕',c:'莫嗟虚老海壖西，天下风光数崦稽。\n灵氾桥前百里镜，石帆山崦五云溪。\n冰销田地芦锥短，春入枝条柳眼低。\n安得故人生羽翼，飞来相伴醉如泥。'},
    {t:'寄乐天二首',a:'元稹〔唐代〕',c:'荣辱升沉影与身，世情谁是旧雷陈。唯应鲍叔犹怜我，\n自保曾参不杀人。山入白楼沙苑暮，潮生沧海野塘春。\n老逢佳景唯惆怅，两地各伤何限神。\n论才赋命不相干，凤有文章雉有冠。羸骨欲销犹被刻，\n疮痕未没又遭弹。剑头已折藏须盖，丁字虽刚屈莫难。\n休学州前罗刹石，一生身敌海波澜。'},
    {t:'寄乐天二首其一',a:'元稹〔唐代〕',c:'荣辱升沈影与身，世情谁是旧雷陈。唯应鲍叔犹怜我，自保曾参不杀人。\n山入白楼沙苑暮，潮生沧海野塘春。老逢佳景唯惆怅，两地各伤何限神。'},
    {t:'寄李渤',a:'张籍〔唐代〕',c:'五度溪头踯躅红，嵩阳寺里讲时钟。\n春山处处行应好，一月看花到几峰。'},
    {t:'寄李儋元锡',a:'韦应物〔唐代〕',c:'去年花里逢君别，今日花开又一年。\n世事茫茫难自料，春愁黯黯独成眠。\n身多疾病思田里，邑有流亡愧俸钱。\n闻道欲来相问讯，西楼望月几回圆。'},
    {t:'寄林处士',a:'范仲淹〔宋代〕',c:'片心高与月徘徊，岂为千锺下钓台。\n犹笑白云多事在，等闲为雨出山来。'},
    {t:'寄灵一上人初归云门寺',a:'张籍〔唐代〕',c:'寒山白云里，法侣自招携。竹径通城下，松门隔水西。\n方同沃洲去，不作武陵迷。仿佛遥看处，秋风是会稽。'},
    {t:'寄令狐宾客',a:'张籍〔唐代〕',c:'勋名尽得国家传，退狎琴僧与座仙。还带郡符经几处，\n暂辞台座已三年。留司未到龙楼下，拜表长怀玉案前。\n秋日出城伊水好，领谁相逐上闲船。'},
    {t:'寄令狐郎中',a:'李商隐〔唐代〕',c:'嵩云秦树久离居，双鲤迢迢一纸书。\n休问梁园旧宾客，茂陵秋雨病相如。'},
    {t:'寄令狐侍郎',a:'韦应物〔唐代〕',c:'三山有琼树，霜雪色逾新。始自诰尘交，中结绸缪姻。\n西掖方掌诰，南宫复司春。夕燕华池月，朝俊玉阶尘。\n众宝归和氏，吹嘘多俊人。群公共然诺，声问迈时伦。\n孤鸿既高举，燕雀在荆榛。翔集且不同，岂不欲殷勤。\n一旦迁南郡，江湖渺无垠。宠辱良未定，君子岂缁磷。\n寒暑已推斥，别离生苦辛。非将会面目，书札何由申。'},
    {t:'寄庐山棕衣居士',a:'韦应物〔唐代〕',c:'兀兀山行无处归，山中猛虎识棕衣。\n俗客欲寻应不遇，云溪道士见犹稀。'},
    {t:'寄陆浑赵明府',a:'张籍〔唐代〕',c:'与君学省同官处，常日相随说道情。新作陆浑山县长，\n早知三礼甲科名。郭中时有仙人住，城内应多药草生。\n公事稀疏来客少，无妨著屐独闲行。'},
    {t:'寄陆务观',a:'杨万里〔宋代〕',c:'君居东浙我江西，镜里新添几里丝。\n花落六回疏信息，月明千里两相思。\n不应李杜翻鲸海，更羡夔龙集凤池。\n道是樊川轻薄杀，犹将万户比千诗。'},
    {t:'寄罗劭兴',a:'李商隐〔唐代〕',c:'棠棣黄花发，忘忧碧叶齐。\n人闲微病酒，燕重远兼泥。\n混沌何由凿，青冥未有梯。\n高阳旧徒侣，时复一相携。'},
    {t:'寄孟五少府',a:'高适〔唐代〕',c:'秋气落穷巷，离忧兼暮蝉。后时已如此，高兴亦徒然。\n知君念淹泊，忆我屡周旋。征路见来雁，归人悲远天。\n平生感千里，相望在贞坚。'},
    {t:'寄洺州李大夫',a:'孟郊〔唐代〕',c:'自从蓟师反，中国事纷纷。儒道射失所，贤人多在军。\n鸟巢忧迸射，鹿耳骇惊闻。剑折唯恐匣，弓前不让勋。\n方知省事将，动必谢前群。鹳阵常先罢，鱼符最晚分。\n步闲洺水曲，笑激太行云。诗叟未相识，竹儿争见君。\n殷勤越谈说，记尽古风文。'},
    {t:'寄穆侍御出幽州',a:'王昌龄〔唐代〕',c:'一从恩谴度潇湘，塞北江南万里长。\n莫道蓟门书信少，雁飞犹得到衡阳。'},
    {t:'寄恼韩同年二首·时韩住萧洞',a:'李商隐〔唐代〕',c:'帘外辛夷定已开，开时莫放艳阳回。\n年华若到经风雨，便是胡僧话劫灰。\n龙山晴雪凤楼霞，洞里迷人有几家。\n我为伤春心自醉，不劳君劝石榴花。'},
    {t:'寄牛相公',a:'杜牧〔唐代〕',c:'汉水横冲蜀浪分，危楼点的拂孤云。\n六年仁政讴歌去，柳绕春堤处处闻。'},
    {t:'寄欧静秀才',a:'范仲淹〔宋代〕',c:'君归一水遥，魂断木兰桡。\n赖有南轩竹，清风慰寂寥。'},
    {t:'寄平甫弟衢州道中',a:'王安石〔宋代〕',c:'浅溪受日光炯碎，野林参天阴翳长。\n幽鸟不见但闻语，小梅欲空犹有香。\n长年无可自娱戏，远游虽好更悲伤。\n安得冬风一吹汝，手把诗书来我旁。'},
    {t:'寄秦州幕明化基寺丞',a:'范仲淹〔宋代〕',c:'同时辟命新，中道改丝纶。\n沧海下归楚，清风子在秦。\n共居卿月下，独得将星邻。\n耸动军前檄，峥嵘席上珍。\n烽烟边信息，金鼓武精神。\n猎度天山雪，歌逢陇树春。\n燕台无限好，西向自沾巾。'},
    {t:'寄青城龙谿奂道人',a:'岑参〔唐代〕',c:'五岳之丈人，西望青瞢瞢。云开露崖峤，百里见石棱。\n龙谿盘中峰，上有莲华僧。绝顶小兰若，四时岚气凝。\n身同云虚无，心与谿清澄。诵戒龙每听，赋诗人则称。\n杉风吹袈裟，石壁悬孤灯。久欲谢微禄，誓将归大乘。\n愿闻开士说，庶以心相应。'},
    {t:'寄清源寺僧',a:'温庭筠〔唐代〕',c:'石路无尘竹径开，昔年曾伴戴颙来。窗间半偈闻钟后，\n松下残棋送客回。帘向玉峰藏夜雪，砌因蓝水长秋苔。\n白莲社里如相问，为说游人是姓雷。'},
    {t:'寄全椒山中道士',a:'韦应物〔唐代〕',c:'今朝郡斋冷，忽念山中客。\n涧底束荆薪，归来煮白石。\n欲持一瓢酒，远慰风雨夕。\n落叶满空山，何处寻行迹。'},
    {t:'寄润州庞籍',a:'范仲淹〔宋代〕',c:'北固高楼海气寒，使君应此凭栏干。\n春山雨后青无限，借与淮南洗眼看。'},
    {t:'寄山中人',a:'温庭筠〔唐代〕',c:'月中一双鹤，石上千尺松。素琴入爽籁，山酒和春容。\n幽瀑有时断，片云无所从。何事苏门生，携手东南峰。'},
    {t:'寄上叔父夷仲三首',a:'黄庭坚〔宋代〕',c:'关寒塞雪欲嗣音，燕雁拂天河鲤沈。\n百书不如一见面，几日归来两慰心。\n弓刀陌上望行色，儿女灯前语夜深。\n更怀父子东归得，手种江头柳十寻。'},
    {t:'寄石学士',a:'范仲淹〔宋代〕',c:'家有清白志，所实甑中尘。\n休去无生涯，老来犹苦辛。\n一麾了婚嫁，万事蠹精神。\n与君尝大言，定作青山邻。\n蹭蹬未携手，得无羞故人。'},
    {t:'寄释子良史酒',a:'韦应物〔唐代〕',c:'秋山僧冷病，聊寄三五杯。应泻山瓢里，还寄此瓢来。'},
    {t:'寄苏州白二十二使君',a:'张籍〔唐代〕',c:'三朝出入紫微臣，头白金章未日身。\n登第早年同座主，题诗今日是州人。\n阊门柳色烟中远，茂苑莺声雨后新。\n此处吟诗向山寺，知君忘却曲江春。'},
    {t:'寄宿田家',a:'高适〔唐代〕',c:'田家老翁住东陂，说道平生隐到兹。\n鬓白未曾记日月，山青每到识春时。\n门前种柳深成巷，野地流泉添入池。\n牛壮日耕十亩地，人闲常扫一茅茨。\n客来满酌清尊酒，感兴平吟才子诗。\n岩际窟中藏鼹鼠，潭边竹里隐鸬鹚。\n村墟日落行人少，醉后无心怯路歧。\n今夜只应还寄宿，明朝拂曙与君辞。'},
    {t:'寄孙冲主簿',a:'张籍〔唐代〕',c:'低折沧洲簿，无书整两春。马从同事借，妻怕罢官贫。\n道僻收闲药，诗高笑故人。仍闻长吏奏，表乞锁厅频。'},
    {t:'寄孙洛阳格·一作寄洛阳孙明府',a:'张籍〔唐代〕',c:'久持刑宪声名远，好是中朝正直臣。赤县上来应足事，\n青山老去未离身。常思从省连归马，乍觉同班少旧人。\n遥爱南桥秋日晚，雨边杨柳映天津。'},
    {t:'寄孙莘老少监',a:'秦观〔宋代〕',c:'一出承明七换麾，君恩复许上彤墀。\n白衣苍狗无常态，璞玉浑金有定姿。\n天上图书森似旧，人间岁月浪如驰。\n鳌头只在蓬山畔，行赴蟠桃熟後期。'},
    {t:'寄韬光禅师',a:'白居易〔唐代〕',c:'一山门作两山门，两寺原从一寺分。\n东涧水流西涧水，南山云起北山云。\n前台花发后台见，上界钟声下界闻。\n遥想吾师行道处，天香桂子落纷纷。'},
    {t:'寄陶副使',a:'王昌龄〔唐代〕',c:'闻道将军破海门，如何远谪渡湘沅。\n春来明主封西岳，自有还君紫绶恩。'},
    {t:'寄题安福李令爱竹堂',a:'黄庭坚〔宋代〕',c:'渊明喜种菊，子猷喜种竹。\n托物虽自殊，心期俱不俗。\n千载得李侯，异世等风流。\n为官恐是陶彭泽，爱竹最知王子猷。\n寒窗对酒听雨雪，夏簟烹茶卧风月。\n小僧知令不凡材，自扫竹根培老节。\n富贵于我如浮云，安可一日无此君。\n人言爱竹有何好，此中难为俗人道。\n我于此物更不疏，一官窘束何由到。'},
    {t:'寄题甘露寺北轩',a:'杜牧〔唐代〕',c:'曾上蓬莱宫里行，北轩栏槛最留情。\n孤高堪弄桓伊笛，缥缈宜闻子晋笙。\n天接海门秋水色，烟笼隋苑暮钟声。\n他年会着荷衣去，不向山僧道姓名。'},
    {t:'寄题九日山廓然亭',a:'朱熹〔宋代〕',c:'昨游九日山，散发岩上石。仰看时宇近，俯叹尘境窄。\n归来今几时，梦想挂苍壁。闻公结茅地，恍云记畴昔。\n年随流水逝，事与浮云失。了知廓然处，初不从外得。\n遥怜植杖翁，鹤骨双眼碧。永啸月明中，秋风桂花白。'},
    {t:'寄题荣州祖元大师此君轩',a:'黄庭坚〔宋代〕',c:'王师学琴三十年，响如清夜落手泉。\n满堂洗尽筝琶耳，请师停手恐断弦。\n神人传书道人命，死嫌贵贱如看镜。\n晚知直语触憎嫌，深藏幽寺听钟磬。\n有酒如渑客满门，不可一日无此君。\n当时手栽数寸碧，声挟风雨今连云。\n此君倾盖如故旧，骨相奇怪清且秀。\n程婴杵臼立孤难，伯夷叔齐采薇瘦。\n霜钟堂上弄秋月，微风入弦此君悦。\n公家周彦笔如椽，此君语意当能传。'},
    {t:'寄题溪口广慈院',a:'范仲淹〔宋代〕',c:'越中山水绝纖尘，溪口风光步步新。\n若得会稽藏拙去，白云深处亦行春。'},
    {t:'寄题许州钱相公信美亭',a:'范仲淹〔宋代〕',c:'华搆高轩敞，名湖一面分。\n星辰居上相，鼓吹燕中军。\n山色来嵩室，风光彻汝坟。\n杉篁涵晚翠，兰茝薦时薰。\n坐啸频乘月，归怀几望云。\n迥临黄霸俗，远味仲宣文。\n万户方开国，三阶复致君。\n斯亭比棠树，千载颂清芬。'},
    {t:'寄天台道士',a:'孟浩然〔唐代〕',c:'海上求仙客，三山望几时。\n焚香宿华顶，裛露采灵芝。\n屡蹑莓苔滑，将寻汗漫期。\n倘因松子去，长与世人辞。'},
    {t:'寄桐江隐者·一作许浑诗',a:'杜牧〔唐代〕',c:'潮去潮来洲渚春，山花如绣草如茵。\n严陵台下桐江水，解钓鲈鱼能几人。'},
    {t:'寄王侍御·一作奉御',a:'张籍〔唐代〕',c:'爱君紫阁峰前好，新作书堂药灶成。\n见欲移居相近住，有田多与种黄精。'},
    {t:'寄王屋山人孟大融',a:'李白〔唐代〕',c:'我昔东海上，劳山餐紫霞。\n亲见安期公，食枣大如瓜。\n中年谒汉主，不惬还归家。\n朱颜谢春辉，白发见生涯。\n所期就金液，飞步登云车。\n愿随夫子天坛上，闲与仙人扫落花。'},
    {t:'寄西峰僧',a:'张籍〔唐代〕',c:'松暗水涓涓，夜凉人未眠。西峰月犹在，遥忆草堂前。'},
    {t:'寄西湖林处士',a:'范仲淹〔宋代〕',c:'萧索绕家云，清歌独隐沦。\n巢由不愿仕，尧舜岂遗人。\n一水无涯静，群峰满眼春。\n何当伴闲逸，尝酒过诸邻。'},
    {t:'寄乡人',a:'范仲淹〔宋代〕',c:'长白一寒儒，登荣三纪馀。\n百花春满地，二麦雨随车。\n鼓吹前迎道，烟霞指旧庐。\n乡人莫相羡，教子读诗书。'},
    {t:'寄湘灵',a:'白居易〔唐代〕',c:'泪眼凌寒冻不流，每经高处即回头。\n遥知别后西楼上，应凭栏干独自愁。'},
    {t:'寄湘中友人',a:'杜牧〔唐代〕',c:'莫念醉乡迷酒杯，流年长怕少年催。\n西陵水阔鱼难到，南国路遥书未回。\n匹马计程愁日尽，一蝉何事引秋来？\n相如已定题桥志，江上无由梦钓台。'},
    {t:'寄扬州韩绰判官',a:'杜牧〔唐代〕',c:'青山隐隐水迢迢，秋尽江南草未凋。\n二十四桥明月夜，玉人何处教吹箫？'},
    {t:'寄衣曲',a:'张籍〔唐代〕',c:'织素缝衣独苦辛，远因回使寄征人。官家亦自寄衣去，\n贵从妾手著君身。高堂姑老无侍子，不得自到边城里。\n殷勤为看初著时，征夫身上宜不宜。'},
    {t:'寄殷协律',a:'白居易〔唐代〕',c:'五岁优游同过日，一朝消散似时云。\n琴诗酒伴皆抛我，雪月花时最忆君。\n几度听鸡歌白日，亦曾骑马咏红裙。\n吴娘暮雨萧萧曲，自别江南更不闻。'},
    {t:'寄友人',a:'张籍〔唐代〕',c:'忆在江南日，同游三月时。采茶寻远涧，斗鸭向春池。\n送客沙头宿，招僧竹里棋。如今各千里，无计得相随。'},
    {t:'寄馀杭全安石段少连二從事',a:'范仲淹〔宋代〕',c:'分携俱是佐高牙，两地光尘自过差。\n荣事日趋丞相府，道情时过老君家。\n双鸿得侣知风便，一鹤思鸣对露华。\n早晚相将云汉外，重为龙友免天涯。'},
    {t:'寄宇文判官',a:'岑参〔唐代〕',c:'西行殊未已，东望何时还。\n终日风与雪，连天沙复山。\n二年领公事，两度过阳关。\n相忆不可见，别来头已斑。'},
    {t:'寄元九',a:'白居易〔唐代〕',c:'一病经四年，亲朋书信断。穷通楚易交，自笑知何晚。\n元君在荆楚，去日唯云远。彼独是何人，心劝石不转。\n忧我贫病身，书来唯劝勉。上言少愁苦，下道加餐饭。\n怜君为谪吏，穷薄家贫褊。三寄衣食资，数盈二十万。\n岂是贪衣食，感君心缱绻。念我口中食，分君身上暖。\n不因身病久，不因命多蹇。平生亲友心，岂得知深浅。'},
    {t:'寄远',a:'晏殊〔宋代〕',c:'宝毂香轮不再逢，峡云巫雨杳无踪。梨花院落溶溶月，柳絮池塘淡淡风。\n几日寂寥伤酒后，一番萧索禁烟中。鱼书欲寄无由达，水远山长处处同。'},
    {t:'寄远',a:'杜牧〔唐代〕',c:'两叶愁眉愁不开，独含惆怅上层台。碧云空断雁行处，\n红叶已凋人未来。塞外音书无信息，道傍车马起尘埃。\n功名待寄凌烟阁，力尽辽城不肯回。'},
    {t:'寄远',a:'晏殊〔宋代〕',c:'实轂香轮不再逢，峡云巫雨杳无踪。\n梨花院落溶溶月，柳絮池塘淡淡风。\n几日寂寥伤酒后，一番萧索禁烟中。\n鱼书欲寄无由达，水远山长处处同。'},
    {t:'寄远',a:'白居易〔唐代〕',c:'欲忘忘未得，欲去去无由。\n两腋不生翅，二毛空满头。\n坐看新落叶，行上最高楼。\n暝色无边际，茫茫尽眼愁。'},
    {t:'寄远',a:'李商隐〔唐代〕',c:'姮娥捣药无时已，玉女投壶未肯休。\n何日桑田俱变了，不教伊水向东流。'},
    {t:'寄远曲',a:'张籍〔唐代〕',c:'美人来去春江暖，江头无人湘水满。浣沙石上水禽栖，\n江南路长春日短。兰舟桂楫常渡江，无因重寄双琼珰。'},
    {t:'寄远人',a:'杜牧〔唐代〕',c:'终日求人卜，回回道好音。那时离别后，入梦到如今。'},
    {t:'寄远十二首·其四',a:'李白〔唐代〕',c:'玉箸落春镜，坐愁湖阳水。\n闻与阴丽华，风烟接邻里。\n青春已复过，白日忽相催。\n但恐荷花晚，令人意已摧。\n相思不惜梦，日夜向阳台。'},
    {t:'寄院中诸公',a:'孟郊〔唐代〕',c:'奕奕秋水傍，駸駸绿云蹄。月仙有高曜，灵凤无卑栖。\n翠色绕云谷，碧华凝月溪。竹林递历览，云寺行攀跻。\n冠豸犹屈蠖，匣龙期剸犀。千山惊月晓，百里闻霜鼙。\n戎府多秀异，谢公期相携。因之仰群彦，养拙固难齐。'},
    {t:'寄岳州李外郎远',a:'温庭筠〔唐代〕',c:'含蘋不语坐持颐，天远楼高宋玉悲。湖上残棋人散后，\n岳阳微雨鸟来迟。早梅犹得回歌扇，春水还应理钓丝。\n独有袁宏正憔悴，一樽惆怅落花时。'},
    {t:'寄赞上人',a:'杜甫〔唐代〕',c:'一昨陪锡杖，卜邻南山幽。\n年侵腰脚衰，未便阴崖秋。\n重冈北面起，竟日阳光留。\n茅屋买兼土，斯焉心所求。\n近闻西枝西，有谷杉黍稠。\n亭午颇和暖，石田又足收。\n当期塞雨干，宿昔齿疾瘳。\n裴回虎穴上，面势龙泓头。\n柴荆具茶茗，径路通林丘。\n与子成二老，来往亦风流。'},
    {t:'寄赠林逋处士',a:'范仲淹〔宋代〕',c:'唐虞重逸人，束帛降何频。\n风俗隐君厚，文章至老淳。\n玉田耕小隐，金阙梦高真。\n罢钓轮生蠹，慵琴鉴积尘。\n饵莲攀鹤顶，歌雪扣琴身。\n墨妙青囊秘，丹灵绿发新。\n岭霞明四望，岩笋入诸邻。\n几侄簪裾盛，诸生礼乐循。\n朝迁唯薦鹗，乡党不伤麟。\n吊古夫差国，怀贤伍相津。\n剧谈来剑侠，腾啸骇山神。\n有客瞻冥翼，无端预薦绅。\n未能忘帝力，犹待补天均。\n早晚功名外，孤云可得亲。'},
    {t:'寄赠小樊',a:'刘禹锡〔唐代〕',c:'花面丫头十三四，春来绰约向人时。\n终须买取名春草，处处将行步步随。'},
    {t:'寄张籍',a:'孟郊〔唐代〕',c:'未见天子面，不如双盲人。贾生盲文帝，终日犹悲辛。\n夫子亦如盲，所以空泣麟。有时独斋心，仿埃梦称臣。\n梦中称臣言，觉后真埃尘。东京有眼富不如，\n西京无眼贫西京。无眼犹有耳隔墙，时闻天子车辚辚。\n辚辚车声辗冰玉，南郊坛上礼百神。西明寺后穷瞎张太祝，\n纵尔有眼谁尔珍。天子咫尺不得见，不如闭眼且养真。'},
    {t:'寄赵正字',a:'孟浩然〔唐代〕',c:'正字芸香阁，幽人竹素园。\n经过宛如昨，归卧寂无喧。\n高鸟能择木，羝羊漫触藩。\n物情今已见，从此愿忘言。'},
    {t:'寄浙东韩八评事',a:'杜牧〔唐代〕',c:'一笑五云溪上舟，跳丸日月十经秋。\n鬓衰酒减欲谁泥，迹辱魂惭好自尤。\n梦寐几回迷蛱蝶，文章应解伴牢愁。\n无穷尘土无聊事，不得清言解不休。'},
    {t:'寄致政吴虞部',a:'王安石〔宋代〕',c:'白鸥生意在沧波，不为风尘有网罗。\n年抵冯唐初未半，才方疏广岂能多。\n孤清楚国知谁继，遗爱郴人想共歌。\n嗟我欲归宜未晚，雪舟乘兴会相过。'},
    {t:'寄中书刘舍人',a:'韦应物〔唐代〕',c:'云霄路竟别，中年迹暂同。比翼趋丹陛，连骑下南宫。\n佳咏邀清月，幽赏滞芳丛。迨予一出守，与子限西东。\n晨露方怆怆，离抱更忡忡。忽睹九天诏，秉纶归国工。\n玉座浮香气，秋禁散凉风。应向横门度，环珮杳玲珑。\n光辉恨未瞩，归思坐难通。苍苍松桂姿，想在掖垣中。'},
    {t:'寄诸同寮',a:'朱熹〔宋代〕',c:'把酒江头烟雨时，遥知江树已芳菲。应怜倦客荒茅里，落尽梅花未得归。'},
    {t:'寄紫阁隐者',a:'张籍〔唐代〕',c:'紫阁气沉沉，先生住处深。有人时得见，无路可相寻。\n夜鹿伴茅屋，秋猿守栗林。唯应采灵药，更不别营心。'},
    {t:'寄左省杜拾遗',a:'岑参〔唐代〕',c:'联步趋丹陛，分曹限紫微。\n晓随天仗入，暮惹御香归。\n白发悲花落，青云羡鸟飞。\n圣朝无阙事，自觉谏书稀。'},
    {t:'蓟北春怀',a:'张籍〔唐代〕',c:'渺渺水云外，别来音信稀。\n因逢过江使，却寄在家衣。\n问路更愁远，逢人空说归。\n今朝蓟城北，又见塞鸿飞。'},
    {t:'蓟北旅思',a:'张籍〔唐代〕',c:'日日望乡国，空歌白苎词。\n长因送人处，忆得别家时。\n失意还独语，多愁只自知。\n客亭门外柳，折尽向南枝。'},
    {t:'蓟门行五首',a:'高适〔唐代〕',c:'蓟门逢古老，独立思氛氲。\n一身既零丁，头鬓白纷纷。\n勋庸今已矣，不识霍将军。\n汉家能用武，开拓穷异域。\n戍卒厌糟糠，降胡饱衣食。\n关亭试一望，吾欲泪沾臆。\n边城十一月，雨雪乱霏霏。\n元戎号令严，人马亦轻肥。\n羌胡无尽日，征战几时归。\n幽州多骑射，结发重横行。\n一朝事将军，出入有声名。\n纷纷猎秋草，相向角弓鸣。\n黯黯长城外，日没更烟尘。\n胡骑虽凭陵，汉兵不顾身。\n古树满空塞，黄云愁杀人。'},
    {t:'蓟门行五首·其五',a:'高适〔唐代〕',c:'黯黯长城外，日没更烟尘。\n胡骑虽凭陵，汉兵不顾身。\n古树满空塞，黄云愁杀人。'},
    {t:'蓟丘览古赠卢居士藏用之六邹衍',a:'陈子昂〔唐代〕',c:'大运沦三代。\n天人罕有窥。\n邹子何寥廓。\n漫说九瀛垂。\n兴亡已千载。\n今也则无推。'},
    {t:'蓟丘览古赠卢居士藏用之三乐生',a:'陈子昂〔唐代〕',c:'王道已沦昧。\n战国竞贪兵。\n乐生何感激。\n仗义下齐城。\n雄图竟中夭。\n遗叹寄阿衡。'},
    {t:'蓟中作',a:'高适〔唐代〕',c:'策马自沙漠，长驱登塞垣。\n边城何萧条，白日黄云昏。\n一到征战处，每愁胡虏翻。\n岂无安边书，诸将已承恩。\n惆怅孙吴事，归来独闭门。'},
    {t:'佳人',a:'杜甫〔唐代〕',c:'绝代有佳人，幽居在空谷。\n自云良家子，零落依草木。\n关中昔丧乱，兄弟遭杀戮。\n官高何足论，不得收骨肉。\n世情恶衰歇，万事随转烛。\n夫婿轻薄儿，新人美如玉。\n合昏尚知时，鸳鸯不独宿。\n但见新人笑，那闻旧人哭。\n在山泉水清，出山泉水浊。\n侍婢卖珠回，牵萝补茅屋。\n摘花不插发，采柏动盈掬。\n天寒翠袖薄，日暮倚修竹。'},
    {t:'佳人醉·暮景尔萧尔霁',a:'柳永〔宋代〕',c:'暮景尔萧尔霁。\n云淡天高风细。\n正月华如水。\n金波银汉，潋滟无际。\n冷浸书帷梦断，欲披衣重起。\n临轩砌。\n素光遥指。\n因念翠蛾，香隔音尘何处，相望同千里。\n尽凝睇。厌厌无寐。\n渐晓雕阑独倚。'},
    {t:'佳人醉·暮景萧萧雨霁',a:'柳永〔宋代〕',c:'暮景萧萧雨霁。云淡天高风细。正月华如水。金波银汉，潋滟无际。冷浸书帷梦断，却披衣重起。临轩砌。\n素光遥指。因念翠蛾，杳隔音尘何处，相望同千里。尽凝睇。厌厌无寐。渐晓雕阑独倚。'},
    {t:'家山堂晚照效辋川体作二首其一',a:'朱熹〔宋代〕',c:'夕阳浮远空，西峰背残照。爽气转分明，与君共晚眺。'},
    {t:'家园卧疾毕太祝曜见寻①',a:'孟浩然〔唐代〕',c:'伏枕旧游旷，笙歌劳梦思。②\n平生重交结，迨此令人疑。\n冰室无暖气，炎云空赫曦。③\n隙驹不暂驻，日听凉禅悲。\n壮图哀未立，斑白恨吾衰。④\n夫子自南楚，缅怀嵩汝期。⑤'},
    {t:'嘉陵水',a:'元稹〔唐代〕',c:'尔是无心水，东流有恨无。我心无说处，也共尔何殊。'},
    {t:'嘉陵水·此后并通州诗',a:'元稹〔唐代〕',c:'古时应是山头水，自古流来江路深。\n若使江流会人意，也应知我远来心。'},
    {t:'嘉陵夜有怀二首',a:'白居易〔唐代〕',c:'露湿墙花春意深，西廊月上半床阴。\n怜君独卧无言语，唯我知君此夜心。\n不明不暗胧胧月，不暖不寒慢慢风。\n独卧空床好天气，平明闲事到心中。'},
    {t:'甲子初春即事六首·春二',a:'杨万里〔宋代〕',c:'腊去寒犹在，春来花未开。\n东风忽然到，放尽一园梅。'},
    {t:'贾公闾贵婿曲',a:'李贺〔唐代〕',c:'朝衣不须长，分花对袍缝。嘤嘤苦马来，满脑黄金重。\n今朝香气苦，珊瑚涩难枕。且要弄风人，暖蒲沙上饮。\n燕语踏帘钩，日虹屏中碧。潘令在河阳，无人死芳色。'},
    {t:'贾客词',a:'刘禹锡〔唐代〕',c:'五方之贾，以财相雄，而盐贾尤炽。或曰：“贾雄则农伤。”予感之，作是词。\n贾客无定游，所游唯利并。\n眩俗杂良苦，乘时知重轻。\n心计析秋毫，捶钩侔悬衡。\n锥刀既无弃，转化日已盈。\n徼福祷波神，施财游化城。\n妻约雕金钏，女垂贯珠缨。\n高赀比封君，奇货通幸卿。\n趋时鸷鸟思，藏镪盘龙形。\n大艑浮通川，高楼次旗亭。\n行止皆有乐，关梁似无征。\n农夫何为者，辛苦事寒耕。'},
    {t:'贾生',a:'王安石〔宋代〕',c:'汉有洛阳子，少年明是非。\n所论多感慨，自信肯依违。\n死者若可作，今人谁与归。\n应须蹈东海，不但涕沾衣。'},
    {t:'贾生',a:'李商隐〔唐代〕',c:'宣室求贤访逐臣，贾生才调更无伦。\n可怜夜半虚前席，不问苍生问鬼神。'},
    {t:'假龙吟歌',a:'李贺〔唐代〕',c:'石轧铜杯，吟咏枯瘁。\n苍鹰摆血，木凤下肺。\n桂子自落，云弄车盖。\n木死沙崩恶谿岛，阿母得仙今水老。\n窞中跳汰截清涎，隈壖卧水埋金爪。\n崖蹬苍苔吊石发，江君掩帐筼筜折。\n莲花去国一千年，雨后闻腥犹带铁。'},
    {t:'假中对雨呈县中僚友',a:'韦应物〔唐代〕',c:'却足甘为笑，闲居梦杜陵。\n残莺知夏浅，社雨报年登。\n流麦非关忘，收书独不能。\n自然忧旷职，缄此谢良朋。'},
    {t:'假中示判官张寺丞王校勘',a:'晏殊〔宋代〕',c:'元巳清明例未开，小园幽径独徘徊。\n春寒不定斑斑雨，宿醉难禁滟滟杯。\n无可奈何花落去，似曾相识燕归来。\n游梁赋客多风味，莫惜青钱万选才。'},
    {t:'驾去温泉后赠杨山人',a:'李白〔唐代〕',c:'少年落魄楚汉间，风尘萧瑟多苦颜。\n自言管葛竟谁许，长吁莫错还闭关。\n一朝君王垂拂拭，剖心输丹雪胸臆。\n忽蒙白日回景光，直上青云生羽翼。\n幸陪鸾辇出鸿都，身骑飞龙天马驹。\n王公大人借颜色，金璋紫绶来相趋。\n当时结交何纷纷，片言道合惟有君。\n待吾尽节报明主，然后相携卧白云。'},
    {t:'驾幸河东',a:'王昌龄〔唐代〕',c:'晋水千庐合，汾桥万国从。开唐天业盛，入沛圣恩浓。\n下辇回三象，题碑任六龙。睿明悬日月，千岁此时逢。'},
    {t:'监祠夕月坛书事',a:'刘禹锡〔唐代〕',c:'西皞司分昼夜平，羲和停午太阴生。\n铿锵揖让秋光里，观者如云出凤城。'},
    {t:'兼并',a:'王安石〔宋代〕',c:'三代子百姓，公私无异财。\n人主我操柄，如天持斗魁。\n赋予皆自我，兼并乃奸回。\n奸回法有诛，势难无自来。\n后世始倒持，黔首遂难裁。\n秦王不知此，更筑怀清台。\n礼义日已偷，圣经久堙埃。\n法尚有存者，欲言时所咍。\n俗吏不知方，掊克乃为材。\n俗儒不知变，兼并可无摧。\n利孔至百出，小人私阖开。\n有司与之争，民愈可怜哉。'},
    {t:'蒹葭',a:'杜甫〔唐代〕',c:'摧折不自守，秋风吹若何。\n暂时花戴雪，几处叶沉波。\n体弱春风早，丛长夜露多。\n江湖后摇落，亦恐岁蹉跎。'},
    {t:'减字木兰花',a:'周邦彦〔宋代〕',c:'风鬟雾鬓。便觉蓬莱三岛近。水丹山明。缥缈仙姿画不成。\n广寒丹桂。岂是夭桃尘俗世。只恐乘风。飞上琼楼玉宇中。'},
    {t:'减字木兰花',a:'晏几道〔宋代〕',c:'长杨辇路。绿满当年携手处。试逐春风。重到宫花花树中。\n芳菲绕遍。今日不如前日健。酒罢凄凉。新恨犹添旧恨长。'},
    {t:'减字木兰花·春月',a:'苏轼〔宋代〕',c:'二月十五夜，与赵德麟小酌聚星堂\n春庭月午，摇荡香醪光欲舞。步转回廊，半落梅花婉娩香。\n轻云薄雾，总是少年行乐处。不似秋光，只与离人照断肠。'},
    {t:'减字木兰花·从教铁石',a:'纳兰性德〔清代〕',c:'从教铁石，每见花开成惜惜。泪点难消，滴损苍烟玉一条。\n怜伊大冷，添个纸窗疏竹影。记取相思，环佩归来月上时。'},
    {t:'减字木兰花·断魂无据',a:'纳兰性德〔清代〕',c:'断魂无据，万水千山何处去？没春音书，尽日东风上绿除。\n故园春好，寄语落花须自扫。莫更伤春，同是恹恹多病人。'},
    {t:'减字木兰花·花',a:'苏轼〔宋代〕',c:'玉房金蕊，宜在玉人纤手里。淡熟朦胧，更有微微弄袖风。\n温香熟美，醉慢云鬟垂两耳。多谢春工，不是花红是玉红。'},
    {t:'减字木兰花·花丛冷眼',a:'纳兰性德〔清代〕',c:'花丛冷眼，自惜寻春来较晚。知绝今生，知绝今生那见卿。\n天然绝代，不信相思浑不解。若解相思，定与韩凭共一枝。'},
    {t:'减字木兰花·花心柳眼',a:'柳永〔宋代〕',c:'花心柳眼。郎似游丝常惹绊。慵困谁怜。绣线金针不喜穿。\n深房密宴。争向好天多聚散。绿锁窗前。几日春愁废管弦。'},
    {t:'减字木兰花·回风落景',a:'苏轼〔宋代〕',c:'五月二十四日，会无咎之随斋。主人汲泉置大盆中，渍白芙蓉，坐客翛然，无复有病暑意。\n回风落景。散乱东墙疏竹影。满坐清微。入袖寒泉不湿衣。\n梦回酒醒。百尺飞澜鸣碧井。雪洒冰麾。散落佳人白玉肌。'},
    {t:'减字木兰花·己卯儋耳春词',a:'苏轼〔宋代〕',c:'春牛春杖，无限春风来海上。便春春工，染得桃红似肉红。\n春幡春胜，一阵春风吹酒醒。不似天涯，卷起杨花似雪花。'},
    {t:'减字木兰花·寄车秀卿',a:'张炎〔宋代〕',c:'锁香亭榭。花艳烘春曾卜夜。空歌芳游。不到秋凉不信愁。\n酒迟歌缓。月色平分窗一半。谁伴孤吟。手擘黄花碎却心。'},
    {t:'减字木兰花·江南游女',a:'苏轼〔宋代〕',c:'江南游女，问我何年归得去。雨夜风微，两足如霜挽纻衣。\n江亭夜语，喜见京华新样舞。莲步轻飞，迁客今朝始是归。'},
    {t:'减字木兰花·荔枝',a:'苏轼〔宋代〕',c:'闽溪珍献，过海云帆来似箭。玉酽金盘，不贡奇葩四百年。\n轻红酽白，雅称佳人纤手擘。骨细肌香，恰是当年十八娘。'},
    {t:'减字木兰花·留春不住',a:'晏几道〔宋代〕',c:'留春不住。恰似年光无味处。满眼飞英。弹指东风太浅情。\n筝弦未稳。学得新声难破恨。转枕花前。且占香红一夜眠。'},
    {t:'减字木兰花·双龙对起',a:'苏轼〔宋代〕',c:'钱塘西湖有诗僧清顺，所居藏春坞，门前有二古松，各有凌霄花络其上，顺常昼卧其下。时余为郡，一日屏骑从过之，松风骚然，顺指落花求韵，余为赋此。\n双龙对起，白甲苍髯烟雨里。疏影微香，下有幽人昼梦长。\n湖风清软，双鹊飞来争噪晚。翠飐红轻，时下凌霄百尺英。'},
    {t:'减字木兰花·送别',a:'苏轼〔宋代〕',c:'天台旧路。应恨刘郎来又去。别未频倾。忍听阳关第四声。\n刘郎未老。怀恋仙乡重得到。只恐因循。不见如今劝未人。'},
    {t:'减字木兰花·送赵令',a:'苏轼〔宋代〕',c:'春光亭下。流水如今何在也。岁重如梭。白首相看拟奈何。\n故人重见。世事年来千万变。官况阑珊。惭愧青松守岁寒。'},
    {t:'减字木兰花·天涯旧恨',a:'秦观〔宋代〕',c:'天涯旧恨，独自凄凉人不问。欲见回肠，断尽金炉小篆香。\n黛蛾长敛，任是春风吹不展。困倚危楼，过尽飞鸿字字愁。'},
    {t:'减字木兰花·相逢不语',a:'纳兰性德〔清代〕',c:'相逢不语，一朵芙蓉著秋雨。小晕红潮，斜溜鬟心只凤翘。\n待将低唤，直为凝情恐人见。欲诉幽怀，转过回阑叩玉钗。'},
    {t:'减字木兰花·襄王梦里',a:'黄庭坚〔宋代〕',c:'襄王梦里，草绿烟深何处是？宋漫台头，暮雨朝云几许愁？\n飞花漫漫，不管羁人肠欲断。春水茫茫，欲度南陵更断肠。'},
    {t:'减字木兰花·新月',a:'纳兰性德〔清代〕',c:'晚妆欲罢，更把纤眉临镜画。准待分明，和雨和烟两不胜。\n莫教星替，守取团圆终必遂。此夜红楼，天上人间一样愁。'},
    {t:'减字木兰花·莺初解语',a:'苏轼〔宋代〕',c:'莺初解语，最是一年春好处。微雨如酥，草色遥看近却无。\n休辞醉倒，花不看开人易老。莫待春回，颠倒红英间绿苔。'},
    {t:'减字木兰花·盈盈泪眼',a:'辛弃疾〔宋代〕',c:'长沙道中，壁上有妇人题字，若有恨者，用其意为赋。\n盈盈泪眼。往日青楼天样远。秋月春花，输与寻常姊妹家。\n水村山驿。日暮行云无气力。锦字偷裁，立尽西风雁不来。'},
    {t:'减字木兰花·用前韵示知命弟',a:'黄庭坚〔宋代〕',c:'当年夜雨。头白相依无去住。儿女成围。欢笑尊前月照之。\n阿连高秀。千万里来忠孝有。岂谓无衣。岁晚先寒要弟知。'},
    {t:'减字木兰花·寓意',a:'苏轼〔宋代〕',c:'云鬟倾倒，醉倚阑干风月好。凭仗相扶，误入仙家碧玉壶。\n连天衰草，下走湖南西去道。一舸姑苏，便逐鸱夷去得无。'},
    {t:'减字木兰花·长亭晚送',a:'晏几道〔宋代〕',c:'长亭晚送，都似绿窗前日梦。\n小字还家，恰应红灯昨夜花。\n良时易过，半镜流年春欲破。\n往事难忘，一枕高楼到夕阳。'},
    {t:'减字木兰花·烛花摇影',a:'纳兰性德〔清代〕',c:'烛花摇影，冷透疏衾刚欲醒。待不思量，不许孤眠不断肠。\n茫茫碧落，天上人间情一诺。银汉难通，稳耐风波愿始从。'},
    {t:'剪彩',a:'张九龄〔唐代〕',c:'姹女矜容色，为花不让春。既争芳意早，谁待物华真。\n叶作参差发，枝从点缀新。自然无限态，长在艳阳晨。'},
    {t:'简寂观西涧瀑布下作',a:'韦应物〔唐代〕',c:'淙流绝壁散，虚烟翠涧深。丛际松风起，飘来洒尘襟。\n窥萝玩猿鸟，解组傲云林。茶果邀真侣，觞酌洽同心。\n旷岁怀兹赏，行春始重寻。聊将横吹笛，一写山水音。'},
    {t:'简简吟',a:'白居易〔唐代〕',c:'苏家小女名简简，芙蓉花腮柳针眼。\n十一把镜学点妆，十二抽针能绣裳。\n十三行坐事调品，不样迷头白地藏。\n玲珑云髻生花样，飘飖风袖蔷薇香。\n殊姿异态不可状，忽忽转动如有光。\n二月繁霜杀桃李，明年欲嫁今年死。\n丈人阿母勿悲啼，此女不是凡夫妻。\n恐是天仙谪人世，只合人间十三岁。\n大都好物不坚牢，彩云易散琉璃脆。'},
    {t:'简卢陟',a:'韦应物〔唐代〕',c:'可怜白雪曲，未遇知音人。\n恓惶戎旅下，蹉跎淮海滨。\n涧树含朝雨，山鸟哢馀春。\n我有一瓢酒，可以慰风尘。'},
    {t:'简同志',a:'温庭筠〔唐代〕',c:'开济由来变盛衰，五车才得号镃基。\n留侯功业何容易，一卷兵书作帝师。'},
    {t:'简吴郎司法',a:'杜甫〔唐代〕',c:'有客乘舸自忠州，遣骑安置瀼西头。\n古堂本买藉疏豁，借汝迁居停宴游。\n云石荧荧高叶曙，风江飒飒乱帆秋。\n却为姻娅过逢地，许坐曾轩数散愁。'},
    {t:'见艾有感',a:'文天祥〔宋代〕',c:'过眼惊初夏，回头忆晚春。\n已怜花结子，又见艾为人。\n故国丹心老，中原白发新。\n灵悠那解化，清梦楚江滨。'},
    {t:'见乐天诗',a:'元稹〔唐代〕',c:'通州到日日平西，江馆无人虎印泥。\n忽向破檐残漏处，见君诗在柱心题。'},
    {t:'见穆三十宅中庭海榴花谢',a:'杜牧〔唐代〕',c:'矜红掩素似多才，不待樱桃不解梅。春到未曾逢宴赏，\n雨馀争解免低徊。巧穷南国千般艳，趁得春风二月开。\n堪恨王孙浪游去，落英狼藉始归来。'},
    {t:'见人咏韩舍人新律诗因有戏赠',a:'元稹〔唐代〕',c:'喜闻韩古调，兼爱近诗篇。玉磬声声彻，金铃个个圆。\n高疏明月下，细腻早春前。花态繁于绮，闺情软似绵。\n轻新便妓唱，凝妙入僧禅。欲得人人伏，能教面面全。\n延之苦拘检，摩诘好因缘。七字排居敬，千词敌乐天。\n殷勤闲太祝，好去老通川。莫漫裁章句，须饶紫禁仙。'},
    {t:'见薛大臂鹰作·一作李白',a:'高适〔唐代〕',c:'寒楚十二月，苍鹰八九毛。寄言燕雀莫相啅，\n自有云霄万里高。'},
    {t:'见紫荆花',a:'韦应物〔唐代〕',c:'杂英纷已积，含芳独暮春。\n还如故园树，忽忆故园人。'},
    {t:'见紫薇花忆微之',a:'白居易〔唐代〕',c:'一丛暗淡将何比，浅碧笼裙衬紫巾。\n除却微之见应爱，人间少有别花人。'},
    {t:'饯陈学士还江南同用征字',a:'张九龄〔唐代〕',c:'荷蓧旋江澳，衔杯饯霸陵。别前林鸟息，归处海烟凝。\n风土乡情接，云山客念凭。圣朝岩穴选，应待鹤书征。'},
    {t:'饯故人',a:'高适〔唐代〕',c:'祈君辞丹墀，负杖归海隅。离庭自萧索，别心何郁纡。\n天高白云断，野旷青山孤。欲知肠断处，明月照江湖。'},
    {t:'饯济阴梁明府各探一物得荷叶',a:'张九龄〔唐代〕',c:'荷叶生幽渚，芳华信在兹。朝朝空此地，采采欲因谁。\n但恐星霜改，还将蒲稗衰。怀君美人别，聊以赠心期。'},
    {t:'饯宋八充彭中丞判官之岭南',a:'高适〔唐代〕',c:'睹君济时略，使我气填膺。长策竟不用，高才徒见称。\n一朝知己达，累日诏书征。羽翮忽然就，风飙谁敢凌。\n举鞭趋岭峤，屈指冒炎蒸。北雁送驰驿，南人思饮冰。\n彼邦本倔强，习俗多骄矜。翠羽干平法，黄金挠直绳。\n若将除害马，慎勿信苍蝇。魑魅宁无患，忠贞适有凭。\n猿啼山不断，鸢跕路难登。海岸出交趾，江城连始兴。\n绣衣当节制，幕府盛威棱。勿惮九嶷险，须令百越澄。\n立谈多感激，行李即严凝。离别胡为者，云霄迟尔升。'},
    {t:'饯王岑判官赴襄阳道',a:'岑参〔唐代〕',c:'故人汉阳使，走马向南荆。不厌宅山路，只怜襄水清。\n津头习氏宅，江上夫人城。夜入橘花宿，朝穿桐叶行。\n害群应自慑，持法固须平。暂得青门醉，斜光速去程。'},
    {t:'饯王尚书出边',a:'张九龄〔唐代〕',c:'汉相推人杰，殷宗伐鬼方。还闻出将重，坐见即戎良。\n上策应为豫，中权且用光。令申兵气倍，威憺虏魂亡。\n树比公孙大，城如道济长。夏云登陇首，秋露泫辽阳。\n武德舒宸眷，文思饯乐章。感恩身既许，激节胆犹尝。\n祖帐倾朝列，军麾驻道傍。诗人何所咏，尚父欲鹰扬。'},
    {t:'饯王司马入计同用洲字',a:'张九龄〔唐代〕',c:'元僚行上计，举饯出林丘。\n忽望题舆远，空思解榻游。\n别筵铺柳岸，征棹倚芦洲。\n独叹湘江水，朝宗向北流。'},
    {t:'饯雍聿之潞州谒李中丞',a:'韦应物〔唐代〕',c:'郁郁雨相遇，出门草青青。酒酣拔剑舞，慷慨送子行。\n驱马涉大河，日暮怀洛京。前登太行路，志士亦未平。\n薄游五府都，高步振英声。主人才且贤，重士百金轻。\n丝竹促飞觞，夜宴达晨星。娱乐易淹暮，谅在执高情。'},
    {t:'建茶',a:'晏殊〔宋代〕',c:'北苑中春岫幌开，里民清晓驾肩来。\n丰隆已助新芽出，更作欢声动地催。'},
    {t:'建昌江',a:'白居易〔唐代〕',c:'建昌江水县门前，立马教人唤渡船。\n忽似往年归蔡渡，草风沙雨渭河边。'},
    {t:'建康',a:'文天祥〔宋代〕',c:'金陵古会府，南渡旧陪京。\n山势犹盘礴，江流已变更。\n健儿徙幽土，新鬼哭台城。\n一片清溪月，偏于客有情。'},
    {t:'建元寺集皇甫侍御书阁',a:'皎然〔唐代〕',c:'不因居佛里，无事得相逢。名重朝端望，身高俗外踪。\n机闲看净水，境寂听疏钟。宣室恩长在，知君志未从。'},
    {t:'剑阁赋',a:'李白〔唐代〕',c:'咸阳而南，直望五千里，见云峰而崔嵬。前有剑阁横断，倚青天而中开。上则松风萧飒瑟䫻，有巴喷兮相哀。旁则飞湍走壑，洒石喷阁，汹涌而惊雷。\n送佳人兮此去，复何时兮归来？望夫君兮安极，我沉吟兮叹息。视沧波而东注，悲白日而西匿。鸿别燕兮秋声，云愁秦而暝色。若明月出于剑阁兮，与君两乡对酒而相忆！'},
    {t:'剑门',a:'杜甫〔唐代〕',c:'唯天有设险，剑门天下壮。\n连山抱西南，石角皆北向。\n两崖崇墉倚，刻画城郭状。\n一夫怒临关，百万未可傍。\n珠玉走中原，岷峨气凄怆。\n三皇五帝前，鸡犬各相放。\n后王尚柔远，职贡道已丧。\n至今英雄人，高视见霸王。\n并吞与割据，极力不相让。\n吾将罪真宰，意欲铲叠嶂！\n恐此复偶然，临风默惆怅。'},
    {t:'剑门道中遇微雨',a:'陆游〔宋代〕',c:'衣上征尘杂酒痕，远游无处不消魂。\n此身合是诗人未？细雨骑驴入剑门。'},
    {t:'涧南园即事贻皎上人',a:'孟浩然〔唐代〕',c:'弊庐在郭外，素产唯田园。\n左右林野旷，不闻朝市喧。\n钓竿垂北涧，樵唱入南轩。\n书取幽栖事，将寻静者论。'},
    {t:'涧中鱼',a:'白居易〔唐代〕',c:'海水桑田欲变时，风涛翻覆沸天池。\n鲸吞蛟斗波成血，深涧游鱼乐不知。'},
    {t:'江城对月',a:'范仲淹〔宋代〕',c:'南国风波远，东门冠盖回。\n多情是明月，相逐过江来。'},
    {t:'江城子',a:'黄庭坚〔宋代〕',c:'新来曾被眼奚搐。不甘伏。怎拘暂。似梦还真，烦乱损心曲。见面暂时还不见，看不足、惜不足。\n不成欢笑不成哭。戏人目。远山蹙。有分看伊，无分共伊宿。一贯一文跷十贯，千不足、万不足。'},
    {t:'江城子·孤山竹阁送述古',a:'苏轼〔宋代〕',c:'翠蛾羞黛怯人看。掩霜纨，泪偷弹。且尽一尊，收泪唱《阳关》。漫道帝城天样远，天易见，见君难。\n画堂新构近孤山。曲栏干，为谁安？飞絮落花，春色属明年。欲棹小舟寻旧事，无处问，水连天。'},
    {t:'江城子·江景',a:'苏轼〔宋代〕',c:'湖上与张先同赋，时闻弹筝\n凤一山下雨初晴，水风清，晚霞明。一朵芙蕖，开过尚盈盈。何处飞一双白鹭，如有意，慕娉婷。\n忽闻江上弄哀筝，苦含情，遣谁听！烟敛云收，依约是湘灵。欲待曲终寻问取，人不见，数峰青。'},
    {t:'江城子·梦中了了醉中醒',a:'苏轼〔宋代〕',c:'陶渊明以正月五日游斜川，临流班坐，顾瞻南阜，爱曾城之独秀，乃作斜川诗，至今使人想见其处。元丰壬戌之春，余躬耕于东坡，筑雪堂居之，南挹四望亭之后丘，西控北山之微泉，慨然而叹，此亦斜川之游也。乃作长短句，以《江城子》歌之。\n梦中了了醉中醒。只渊明，是前生。走遍人间，依旧却躬耕。昨夜东坡春雨足，乌鹊喜，报新晴。\n雪堂西畔暗泉鸣。北山倾，小溪横。南望亭丘，孤秀耸曾城。都是斜川当日景，吾老矣，寄余龄。'},
    {t:'江城子·密州出猎',a:'苏轼〔宋代〕',c:'老夫聊发少年狂，左牵黄，右擎倾，锦帽貂裘，千骑卷平冈。为报倾城随太守，亲射虎，看孙郎。\n酒酣胸胆尚开张。鬓微霜，又何妨！持节云中，何日遣冯唐？会挽雕弓如满月，西北望，射天狼。'},
    {t:'江城子·墨云拖雨过西楼',a:'苏轼〔宋代〕',c:'墨云拖雨过西楼。水东流，晚烟巫。柳外残阳，回照动帘钩。今夜巫山真个好，花未落，酒新篘。\n美人微笑转星眸。月华羞，捧金瓯。歌扇萦风，吹散一春愁。试问江南诸伴侣，谁似我，醉扬州。'},
    {t:'江城子·南来飞燕北归鸿',a:'秦观〔宋代〕',c:'南来飞燕北归鸿，偶相逢，惨愁悠。绿鬓朱颜重见两衰翁。别后悠悠君莫问，无限事，不言中。\n小槽春酒滴珠红，莫匆匆，满金钟。饮散落花流水各西东。后会不知何处是，烟浪远，暮云重。'},
    {t:'江城子·腻红匀脸衬檀唇',a:'苏轼〔宋代〕',c:'腻红匀脸衬檀唇。晚妆新。暗伤带。手捻花枝，谁会两眉颦。连理带头双飞燕，留待与、个中人。\n淡烟笼月绣帘阴。画堂深。夜沉沉、谁道连理，能系得人心。一自绿窗偷见后，便憔悴、到如今。'},
    {t:'江城子·前瞻马耳九仙山',a:'苏轼〔宋代〕',c:'前瞻马耳九仙山。碧连天。晚云间。城上高台，真个是超然。莫使匆匆云雨散，今夜里，月婵娟。\n小溪鸥鹭静联拳。去翩翩。点轻烟。人事凄凉，回首便他年。莫忘使君歌笑处，垂柳下，矮槐前。'},
    {t:'江城子·清明天气醉游郎',a:'秦观〔宋代〕',c:'清明天气醉游郎。莺儿狂。燕儿狂。翠盖红缨，道上往来忙。记得相逢垂柳下，雕玉珮，缕金裳。\n春光还是旧春光。桃花香。李花香。浅白深红，一一斗新妆。惆怅惜花人不见，歌一阕，泪千行。'},
    {t:'江城子·三之三',a:'秦观〔宋代〕',c:'枣花金钏约柔荑。昔曾携。事难小。咫尺玉颜，和泪锁春闺。恰似小园桃与李，虽同处，不同枝。\n玉笙初度颤鸾篦。落花飞。为谁吹。月冷风高，此恨只天知。任是行人无定处，重相见，是何时。'},
    {t:'江城子·为满春泽赋横空楼',a:'张炎〔宋代〕',c:'下临无地手扪天。上云烟。俯山川。栖止危巢，不隔道林禅。坐处清高风雨隔，全万境，一壶悬。\n我来直欲挟飞仙。海为田。是何年。如此江声，啸咏白鸥前。老树无根云懵懂，凭寄语、米家船。'},
    {t:'江城子·西城杨柳弄春柔',a:'秦观〔宋代〕',c:'西城杨柳弄春柔，动离忧，泪难收。犹记多情、曾为系归舟。碧野朱桥当日事，人不见，水空流。\n韶华不为少年留，恨悠悠，几时休？飞絮落花时候、一登楼。便作春江都是泪，流不尽，许多愁。'},
    {t:'江城子·乙卯正月二十日夜记梦',a:'苏轼〔宋代〕',c:'十年生死两茫茫，不思量，自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。\n夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行。料得年年肠断处，明月夜，短松冈。'},
    {t:'江城子·咏史',a:'纳兰性德〔清代〕',c:'湿云全压数峰低。影凄迷，望中疑。非雾非烟，神女欲来时。若问生涯原是梦，除梦里，没人知。'},
    {t:'江村',a:'杜甫〔唐代〕',c:'清江一曲抱村流，长夏江村事事幽。\n自去自来梁上燕，相亲相近水中鸥。\n老妻画纸为棋局，稚子敲针作钓钩。\n但有故人供禄米，微躯此外更何求？'},
    {t:'江村行',a:'张籍〔唐代〕',c:'南塘水深芦笋齐，下田种稻不作畦。耕场磷磷在水底，\n短衣半染芦中泥。田头刈莎结为屋，归来系牛还独宿。\n水淹手足尽有疮，山虻绕身飞飏飏。桑林椹黑蚕再眠，\n妇姑采桑不向田。江南热旱天气毒，雨中移秧颜色鲜。\n一年耕种长苦辛，田熟家家将赛神。'},
    {t:'江干闲望',a:'范仲淹〔宋代〕',c:'江干日清旷，寓目一搘筇。\n落叶信流水，归云识旧峰。\n兰荪谁共采，凫雁自相從。\n莫爱苹风起，波来千万重。'},
    {t:'江汉',a:'杜甫〔唐代〕',c:'江汉思归客，乾坤一腐儒。\n片云天共远，永夜月同孤。\n落日心犹壮，秋风病欲苏。\n古来存老马，不必取长途。'},
    {t:'江汉答孟郊',a:'韩愈〔唐代〕',c:'江汉虽云广，乘舟渡无艰。流沙信难行，马足常往还。\n凄风结冲波，狐裘能御寒。终宵处幽室，华烛光烂烂。\n苟能行忠信，可以居夷蛮。嗟余与夫子，此义每所敦。\n何为复见赠，缱绻在不谖。'},
    {t:'江陵第二十四',a:'文天祥〔宋代〕',c:'闻说江陵府，今又降元戎。\n甲外控鸣镝，肩舆强老翁。'},
    {t:'江楼吹笛饮酒大醉中作',a:'陆游〔宋代〕',c:'世言九州外，复有大九州。\n此言果不虚，仅可容吾愁。\n许愁亦当有许酒，吾酒酿尽银河流。\n酌之万斛玻璃舟，酣宴五城十二楼。\n天为碧罗幕，月作白玉钩；织女织庆云，裁成五色裘。\n披裘对酒难为客，长揖北辰相献酬。\n一饮五百年，一醉三千秋。\n却驾白风骖斑虯，下与麻姑戏玄洲。\n锦江吹笛余一念，再过剑南应小留。'},
    {t:'江楼寄希元上人',a:'范仲淹〔宋代〕',c:'清言一以遥，默默江楼上。\n安得如白云，无心两相忘。'},
    {t:'江楼曲',a:'李贺〔唐代〕',c:'楼前流水江陵道，鲤鱼风起芙蓉老。\n晓钗催鬓语南风，抽帆归来一日功。\n鼍吟浦口飞梅雨，竿头酒旗换青苎。\n萧骚浪白云差池，黄粉油衫寄郎主。\n新槽酒声苦无力，南湖一顷菱花白。\n眼前便有千里愁，小玉开屏见山色。'},
    {t:'江楼晚望',a:'杜牧〔唐代〕',c:'湖山翠欲结蒙笼，汗漫谁游夕隼中。初语燕雏知社日，\n习飞鹰隼识秋风。波摇珠树千寻拔，山凿金陵万仞空。\n不欲登楼更怀古，斜阳江上正飞鸿。'},
    {t:'江楼夕望招客',a:'白居易〔唐代〕',c:'海天东望夕茫茫，山势川形阔复长。\n灯火万家城四畔，星河一道水中央。\n风吹古木晴天雨，月照平沙夏夜霜。\n能就江楼消暑否？比君茅舍较清凉。'},
    {t:'江楼月',a:'白居易〔唐代〕',c:'嘉陵江曲曲江池，明月虽同人晴离。\n一宵光景潜相忆，两地阴晴远不知。\n谁料江边怀我夜，正当池畔望君时。\n今朝共语方同悔，不解多情先寄诗。'},
    {t:'江梅',a:'杜甫〔唐代〕',c:'梅蕊腊前破，梅花年后多。\n绝知春意好，最奈客愁何。\n雪树元同色，江风亦自波。\n故园不可见，巫岫郁嵯峨。'},
    {t:'江南春',a:'张籍〔唐代〕',c:'江南杨柳春，日暖地无尘。\n渡口过新雨，夜来生白蘋。\n晴沙鸣乳燕，芳树醉游人。\n向晚青山下，谁家祭水神。'},
    {t:'江南春',a:'杜牧〔唐代〕',c:'千里莺啼绿映红，水村山郭酒旗风。\n南朝四百八十寺，多少楼台烟雨中。'},
    {t:'江南逢李龟年',a:'杜甫〔唐代〕',c:'岐王宅里寻常见，崔九堂前几度闻。\n正是江南好风景，落花时节又逢君。'},
    {t:'江南怀古',a:'杜牧〔唐代〕',c:'车书混一业无穷，井邑山川今古同。\n戊辰年向金陵过，惆怅闲吟忆庾公。'},
    {t:'江南弄',a:'李贺〔唐代〕',c:'江中绿雾起凉波，天上叠巘红帆峨。\n水风浦云生老竹，渚暝蒲帆如一幅。\n鲈鱼千头酒百斛，酒中倒卧南山绿。\n吴歈越吟未终曲，江上团团贴寒玉。'},
    {t:'江南曲',a:'张籍〔唐代〕',c:'江南人家多橘树，吴姬舟上织白纻。\n土地卑湿饶虫蛇，连木为牌入江住。\n江村亥日常为市，落帆渡桥来浦里。\n青莎覆城竹为屋，无井家家饮潮水。\n长干午日沽春酒，高高酒旗悬江口。\n倡楼两岸悬水栅，夜唱竹枝留北客。\n江南风土欢乐多，悠悠处处尽经过。'},
    {t:'江宁夹口三首·其三',a:'王安石〔宋代〕',c:'落帆江口月黄昏，小店无灯欲闭门。\n侧出岸沙枫半死，系船应有去年痕。'},
    {t:'江畔独步寻花·其六',a:'杜甫〔唐代〕',c:'黄四娘家花满蹊，千朵万朵压枝低。\n留连戏蝶时时舞，自在娇莺恰恰啼。'},
    {t:'江畔独步寻花·其五',a:'杜甫〔唐代〕',c:'黄师塔前江水东，春光懒困倚微风。\n桃花一簇开无主，可爱深红爱浅红？'},
    {t:'江畔独步寻花七绝句·其二',a:'杜甫〔唐代〕',c:'稠花乱蕊畏江滨，行步欹危实怕春。\n诗酒尚堪驱使在，未须料理白头人。'},
    {t:'江畔独步寻花七绝句·其七',a:'杜甫〔唐代〕',c:'不是爱花即肯死，只恐花尽老相催。\n繁枝容易纷纷落，嫩蕊商量细细开。'},
    {t:'江上',a:'张九龄〔唐代〕',c:'长林何缭绕，远水复悠悠。\n尽日馀无见，为心那不愁。\n忆将亲爱别，行为主恩酬。\n感激空如此，芳时屡已遒。'},
    {t:'江上',a:'王安石〔宋代〕',c:'江北秋阴一半开，晚云含雨却低徊。\n青山缭绕疑无路，忽见千帆隐映来。'},
    {t:'江上别流人',a:'孟浩然〔唐代〕',c:'以我越乡客，逢君谪居者。分飞黄鹤楼，流落苍梧野。\n驿使乘云去，征帆沿溜下。不知从此分，还袂何时把。'},
    {t:'江上春叹',a:'岑参〔唐代〕',c:'腊月江上暖，南桥新柳枝。春风触处到，忆得故园时。\n终日不如意，出门何所之。从人觅颜色，自笑弱男儿。'},
    {t:'江上逢友人',a:'杜牧〔唐代〕',c:'故国归人酒一杯，暂停兰棹共裴回。村连三峡暮云起，\n潮送九江寒雨来。已作相如投赋计，还凭殷浩寄书回。\n到时若见东篱菊，为问经霜几度开。'},
    {t:'江上寄山阴崔少府国辅',a:'孟浩然〔唐代〕',c:'春堤杨柳发，忆与故人期。\n草木本无意，荣枯自有时。\n山阴定远近，江上日相思。\n不及兰亭会，空吟祓禊诗。'},
    {t:'江上看山',a:'苏轼〔宋代〕',c:'船上看山如走马，倏忽过去数百群。\n前山槎牙忽变态，后岭杂沓如惊奔。\n仰看微径斜缭绕，上有行人高缥缈。\n舟中举手欲与言，孤帆南去如飞鸟。'},
    {t:'江上偶见绝句',a:'杜牧〔唐代〕',c:'楚江寒食橘花时，野渡临风驻彩旗。\n草色连云人去住，水纹如縠燕差池。'},
    {t:'江上使风呈裴宣州耀卿',a:'张九龄〔唐代〕',c:'江路与天连，风帆何淼然。遥林浪出没，孤舫鸟联翩。\n常爱千钧重，深思万事捐。报恩非徇禄，还逐贾人船。'},
    {t:'江上望皖公山',a:'李白〔唐代〕',c:'奇峰出奇云，秀木含秀气。\n清晏皖公山，巉绝称人意。\n独游沧江上，终日淡无味。\n但爱兹岭高，何由讨灵异。\n默然遥相许，欲往心莫遂。\n待吾还丹成，投迹归此地。'},
    {t:'江上闻笛',a:'王昌龄〔唐代〕',c:'横笛怨江月，扁舟何处寻。声长楚山外，曲绕胡关深。\n相去万馀里，遥传此夜心。寥寥浦溆寒，响尽惟幽林。\n不知谁家子，复奏邯郸音。水客皆拥棹，空霜遂盈襟。\n羸马望北走，迁人悲越吟。何当边草白，旌节陇城阴。'},
    {t:'江上吟',a:'李白〔唐代〕',c:'木兰之枻沙棠舟，玉箫金管坐两头。\n美酒樽中置千斛，载妓随波任去留。\n仙人有待乘黄鹤，海客无心随白鸥。\n屈平辞赋悬日月，楚王台榭空山丘。\n兴酣落笔摇五岳，诗成笑傲凌沧洲。\n功名富贵若长在，汉水亦应西北流。'},
    {t:'江上渔者',a:'范仲淹〔宋代〕',c:'江上往来人，但爱鲈鱼美。\n君看一叶舟，出没风波里。'},
    {t:'江上雨寄崔碣',a:'杜牧〔唐代〕',c:'春半平江雨，圆文破蜀罗。声眠篷底客，寒湿钓来蓑。\n暗澹遮山远，空濛著柳多。此时怀旧恨，相望意如何。'},
    {t:'江上遇疾风',a:'张九龄〔唐代〕',c:'疾风江上起，鼓怒扬烟埃。白昼晦如夕，洪涛声若雷。\n投林鸟铩羽，入浦鱼曝鳃。瓦飞屋且发，帆快樯已摧。\n不知天地气，何为此喧豗。'},
    {t:'江上暂别萧四刘三旋欣接遇',a:'陈子昂〔唐代〕',c:'昨夜沧江别，言乖天汉游。\n宁期此相遇，尚接武陵洲。\n结绶还逢育，衔杯且对刘。\n波潭一瀰瀰，临望几悠悠。\n山水丹青杂，烟云紫翠浮。\n终愧神仙友，来接野人舟。'},
    {t:'江上值水如海势聊短述',a:'杜甫〔唐代〕',c:'为人性僻耽佳句，语不惊人死不休。\n老去诗篇浑漫与，春来花鸟莫深愁。\n新添水槛供垂钓，故着浮槎替入舟。\n焉得思如陶谢手，令渠述作与同游。'},
    {t:'江上阻风雨',a:'岑参〔唐代〕',c:'江上风欲来，泊舟未能发。气昏雨已过，突兀山复出。\n积浪成高丘，盘涡为嵌窟。云低岸花掩，水涨滩草没。\n老树蛇蜕皮，崩崖龙退骨。平生抱忠信，艰险殊可忽。'},
    {t:'江神子·宝钗飞凤鬓惊鸾',a:'辛弃疾〔宋代〕',c:'宝钗飞凤鬓惊鸾。望重欢。水云来。肠断新来，翠被粉香残。待得来时春尽也，梅著子，笋成竿。\n湘筠帘卷泪痕斑。珮声闲。玉垂环。个里柔温，容我老其间。却笑将军三羽箭，何日去，定天山。'},
    {t:'江神子·博山道中书王氏壁',a:'辛弃疾〔宋代〕',c:'一川松竹任横斜，有人家，被云遮。雪后疏梅，时见两三花。比着桃源溪上路，风景好，不争多。\n旗亭有酒径须赊，晚寒些，怎禁他。醉里匆匆，归骑自随车。白发苍颜吾老矣，只此地，是生涯。'},
    {t:'江神子·冬景',a:'苏轼〔宋代〕',c:'相逢不觉又初寒。对尊前。惜流年。风紧离亭，冰结泪珠圆。雪意留君君不住，从此去，少清欢。\n转头山下转头看。路漫漫。玉花翻。银海光宽，何处是超然。知道故人相念否，携翠袖，倚朱阑。'},
    {t:'江神子·赋梅寄余叔良',a:'辛弃疾〔宋代〕',c:'暗香横路雪垂垂。晚风吹。晓风吹。花意争春，先出岁寒枝。毕竟一年春事了，缘太早，却成迟。\n未应全是雪霜姿。欲开时。未开时。粉面朱唇，一半点胭脂。醉里谤花花莫恨，浑冷淡，有谁知。'},
    {t:'江神子·恨别',a:'苏轼〔宋代〕',c:'天涯流落思无穷！既相逢，却东东。携手佳人，和泪折残红。为问东风余几许？春纵在，与谁同！\n隋回三月水溶溶。背归鸿，去吴中。回首彭城，清泗与淮通。欲寄相思千点泪，流不到，楚江东。'},
    {t:'江神子·黄昏犹是雨纤纤',a:'苏轼〔宋代〕',c:'大雪有怀朱康叔使君，亦知使君之念我也，作《江神子》以寄之。\n黄昏犹是雨纤纤。晓开帘，欲平檐。江阔天低、无处认青帘。孤坐冻吟谁伴我？揩病目，捻衰髯。\n使君留客醉厌厌。水晶盐，为谁甜？手把梅花、东望忆陶潜。雪似故人人似雪，虽可爱，有人嫌。'},
    {t:'江神子·送元济之归豫章',a:'辛弃疾〔宋代〕',c:'乱云扰扰水潺潺。笑溪山。几时千。更觉桃源，人去隔仙凡。万壑千岩楼外雪，琼作树，玉为栏。\n倦游回首且加餐。短篷寒。画图间。见说娇颦，拥髻待君看。二月东湖湖上路，官柳嫩，野梅残。'},
    {t:'江亭',a:'杜甫〔唐代〕',c:'坦腹江亭暖，长吟野望时。\n水流心不竞，云在意俱迟。\n寂寂春将晚，欣欣物自私。\n江东犹苦战，回首一颦眉。'},
    {t:'江头四咏·栀子',a:'杜甫〔唐代〕',c:'栀子比众木，人间诚未多。\n于身色有用，与道气伤和。\n红取风霜实，青看雨露柯。\n无情移得汝，贵在映江波。'},
    {t:'江夏别宋之悌',a:'李白〔唐代〕',c:'楚水清若空，遥将碧海通。\n人分千里外，兴在一杯中。\n谷鸟吟晴日，江猿啸晚风。\n平生不下泪，于此泣无穷。'},
    {t:'江夏使君叔席上赠史郎中',a:'李白〔唐代〕',c:'凤凰丹禁里，衔出紫泥书。\n昔放三湘去，今还万死馀。\n仙郎久为别，客舍问何如。\n涸辙思流水，浮云失旧居。\n多惭华省贵，不以逐臣疏。\n复如竹林下，叨陪芳宴初。\n希君生羽翼，一化北溟鱼。'},
    {t:'江行',a:'文天祥〔宋代〕',c:'日日看山好，山山山色苍。\n忘机鸥下早，恋厩马行忙。\n松晓清风湿，荷秋流水香。\n短簑吹铁笛，年岁大江长。'},
    {t:'江行第八十七',a:'文天祥〔宋代〕',c:'萧萧白杨路，死人积如丘。\n大江东流去，苍山旌旆愁。'},
    {t:'江行遇梅花之作',a:'岑参〔唐代〕',c:'江畔梅花白如雪，使我思乡肠欲断。摘得一枝在手中，无人远向金闺说。\n愿得青鸟衔此花，西飞直送到我家。胡姬正在临窗下，独织留黄浅碧纱。\n此鸟衔花胡姬前，胡姬见花知我怜。千说万说由不得，一夜抱花空馆眠。'},
    {t:'江雪',a:'柳宗元〔唐代〕',c:'千山鸟飞绝，万径人踪灭。\n孤舟蓑笠翁，独钓寒江雪。'},
    {t:'江月楼',a:'秦观〔宋代〕',c:'仙翁看月三百秋，江波日去月不流。\n肯因炎尘暝空阔，直与江月同清幽。\n苍梧云气眉山雨，玉箫三年无今古。\n九天雨露蛰蛟龙，琅玕长凭清虚府。'},
    {t:'江月图',a:'朱熹〔宋代〕',c:'江空秋月明，夜久寒露滴。扁舟何处归，吟啸永佳夕。'},
    {t:'将次相州',a:'王安石〔宋代〕',c:'青山如浪入漳州，铜雀台西八九丘。\n蝼蚁往还空垄亩，骐驎埋没几春秋。\n功名盖世知谁是，气力回天到此休。\n何必地中余故物，魏公诸子分衣裘。'},
    {t:'将发',a:'李贺〔唐代〕',c:'东床卷席罢，濩落将行去。秋白遥遥空，日满门前路。'},
    {t:'将发还乡示诸弟',a:'张九龄〔唐代〕',c:'岁阳亦颓止，林意日萧摵。云胡当此时，缅迈复为客。\n至爱孰能舍，名义来相迫。负德良不赀，输诚靡所惜。\n一木逢厦构，纤尘愿山益。无力主君恩，宁利客卿璧。\n去去荣归养，怃然叹行役。'},
    {t:'将赴湖州留题亭菊',a:'杜牧〔唐代〕',c:'陶菊手自种，楚兰心有期。遥知渡江日，正是撷芳时。'},
    {t:'将赴京留赠僧院',a:'杜牧〔唐代〕',c:'九衢尘土递追攀，马迹轩车日暮间。玄发尽惊为客换，\n白头曾见几人闲。空悲浮世云无定，多感流年水不还。\n谢却从前受恩地，归来依止叩禅关。'},
    {t:'将赴荆南寄别李剑州',a:'杜甫〔唐代〕',c:'使君高义驱今古，寥落三年坐剑州。\n但见文翁能化俗，焉知李广未封侯。\n路经滟滪双蓬鬓，天入沧浪一钓舟。\n戎马相逢更何日？春风回首仲宣楼。'},
    {t:'将赴吴兴登乐游原一绝',a:'杜牧〔唐代〕',c:'清时有味是无能，闲爱孤云静爱僧。\n欲把一麾江海去，乐游原上望昭陵。'},
    {t:'将见故人',a:'孟郊〔唐代〕',c:'故人季夏中，及此百馀日。无日不相思，明镜改形色。\n宁知仲冬时，忽有相逢期。振衣起踯躅，赪鲤跃天池。'},
    {t:'将进酒',a:'李白〔唐代〕',c:'君不见黄河之水天上来，奔流到海不复回。\n君不见高堂明镜悲白发，朝如青丝暮成雪。\n人生得意须尽欢，莫使金樽空对月。\n天生我材必有用，千金散尽还复来。\n烹羊宰牛且为乐，会须一饮三百杯。\n岑夫子，丹丘生，将进酒，杯莫停。\n与君歌一曲，请君为我倾耳听。\n钟鼓馔玉不足贵，但愿长醉不愿醒。\n古来圣贤皆寂寞，惟有饮者留其名。\n陈王昔时宴平乐，斗酒十千恣欢谑。\n主人何为言少钱，径须沽取对君酌。\n五花马、千金裘，呼儿将出换美酒，与尔同销万古愁。'},
    {t:'将进酒',a:'陆游〔宋代〕',c:'我欲挽住北斗杓，常指苍龙无盛摇。\n春风日夜吹草木，只有荣盛无时凋。\n我欲划断日行道，阳夜当空月杲杲。\n非惟四海常不夜，亦使人生失衰老。\n如山积麴高崔嵬，大江酿作蒲萄醅。\n颓然一醉三千杯，借问白发何从来。'},
    {t:'将进酒',a:'李贺〔唐代〕',c:'琉璃钟，琥珀浓，小槽酒滴真珠红。\n烹龙炮凤玉脂泣，罗帏绣幕围香风。\n吹龙笛，击鼍鼓；皓齿歌，细腰舞。\n况是青春日将暮，桃花乱落如红雨。\n劝君终日酩酊醉，酒不到刘伶坟上土。'},
    {t:'将近许市望见虎丘',a:'杨万里〔宋代〕',c:'许市人家远树前，虎丘山色夕阳边。\n石桥分水入别港，茅屋垂杨仍钓船。'},
    {t:'将军行',a:'张籍〔唐代〕',c:'弹筝峡东有胡尘，天子择日拜兵军。蓬莱殿前赐六纛，\n还领禁兵为部曲。当朝受诏不辞家，夜动咸阳原上宿。\n战车彭彭旌旗动，三十六军齐上陇。陇头战胜夜亦行，\n分兵处处收旧城。胡儿杀尽阴碛暮，扰扰唯有牛羊声。\n边人亲戚曾战没，今逐官军收旧骨。碛西行见万里空，\n幕府独奏兵军功。'},
    {t:'将母',a:'王安石〔宋代〕',c:'将母邗沟上，留家白紵阴。\n月明闻杜宇，南北总关心。'},
    {t:'将适天台，留别临安李主簿',a:'孟浩然〔唐代〕',c:'枳棘君尚栖，匏瓜吾岂系。念离当夏首，漂泊指炎裔。\n江海非堕游，田园失归计。定山既早发，渔浦亦宵济。\n泛泛随波澜，行行任舻枻。故林日已远，群木坐成翳。\n羽人在丹丘，吾亦从此逝。'},
    {t:'将往滁城恋新竹，简崔都水示端',a:'韦应物〔唐代〕',c:'停车欲去绕丛竹，偏爱新筠十数竿。\n莫遣儿童触琼粉，留待幽人回日看。'},
    {t:'将往江淮，寄李十九儋',a:'韦应物〔唐代〕',c:'燕燕东向来，文鹓亦西飞。如何不相见，羽翼有高卑。\n徘徊到河洛，华屋未及窥。秋风飘我行，远与淮海期。\n回首隔烟雾，遥遥两相思。阳春自当返，短翮欲追随。'},
    {t:'将至韶州先寄张端公使君借图经',a:'韩愈〔唐代〕',c:'曲江山水闻来久，恐不知名访倍难。\n愿借图经将入界，每逢佳处便开看。'},
    {t:'将至岳阳有怀赵二',a:'张九龄〔唐代〕',c:'湘岸多深林，青冥昼结阴。独无谢客赏，况复贾生心。\n草色虽云发，天光或未临。江潭非所遇，为尔白头吟。'},
    {t:'蒋侯神歌',a:'温庭筠〔唐代〕',c:'楚神铁马金鸣珂，夜动蛟潭生素波。商风刮水报西帝，\n庙前古树蟠白蛇。吴王赤斧斫云阵，画堂列壁丛霜刃。\n巫娥传意托悲丝，铎语琅琅理双鬓。湘烟刷翠湘山斜，\n东方日出飞神鸦。青云自有黑龙子，潘妃莫结丁香花。'},
    {t:'绛州园池',a:'范仲淹〔宋代〕',c:'绛台史君府，亭阁参园圃。一泉西北来，群峰高下睹。\n池鱼或跃金，水帘长布雨。怪柏锁蛟虬，丑石斗貙虎。\n群花相倚笑，垂杨自由舞。静境合通仙，清阴不知暑。\n每与风月期，可无诗酒助。登临问民俗，依旧陶唐古。'},
    {t:'郊居秋日有怀一二知己',a:'温庭筠〔唐代〕',c:'稻田凫雁满晴沙，钓渚归来一径斜。门带果林招邑吏，\n井分蔬圃属邻家。皋原寂历垂禾穗，桑竹参差映豆花。\n自笑谩怀经济策，不将心事许烟霞。'},
    {t:'郊居岁暮',a:'柳宗元〔唐代〕',c:'屏居负山郭，岁暮惊离索。\n野迥樵唱来，庭空烧烬落。\n世纷因事远，心赏随年薄。\n默默谅何为，徒成今与昨。'},
    {t:'焦山望寥山',a:'李白〔唐代〕',c:'石壁望松寥，宛然在碧霄。\n安得五彩虹，驾天作长桥。\n仙人如爱我，举手来相招。'},
    {t:'教坊歌儿',a:'孟郊〔唐代〕',c:'十岁小小儿，能歌得朝天。六十寺老人，能诗独临川。\n去年西京寺，众伶集讲筵。能嘶竹枝词，供养绳床禅。\n能诗不如歌，怅望三百篇。'},
    {t:'街西长句',a:'杜牧〔唐代〕',c:'碧池新涨浴娇鸦，分锁长安富贵家。游骑偶同人斗酒，\n名园相倚杏交花。银鞦騕褭嘶宛马，绣鞅璁珑走钿车。\n一曲将军何处笛，连云芳草日初斜。'},
    {t:'节妇吟寄东平李司空师道',a:'张籍〔唐代〕',c:'君知妾有夫，赠妾双明珠。\n感君缠绵意，系在红罗襦。\n妾家高楼连苑起，良人执戟明光里。\n知君用心如日月，事夫誓拟同生死。\n还君明珠双泪垂，恨不相逢未嫁时。'},
    {t:'结爱',a:'孟郊〔唐代〕',c:'心心复心心，结爱务在深。\n一度欲离别，千回结衣襟。\n结妾独守志，结君早归意。\n始知结衣裳，不如结心肠。\n坐结行亦结，结尽百年月。'},
    {t:'结交',a:'孟郊〔唐代〕',c:'铸镜须青铜，青铜易磨拭。结交远小人，小人难姑息。\n铸镜图鉴微，结交图相依。凡铜不可照，小人多是非。'},
    {t:'结客少年场行',a:'李白〔唐代〕',c:'紫燕黄金瞳，啾啾摇绿騣。\n平明相驰逐，结客洛门东。\n少年学剑术，凌轹白猿公。\n珠袍曳锦带，匕首插吴鸿。\n由来万夫勇，挟此生雄风。\n托交从剧孟，买醉入新丰。\n笑尽一杯酒，杀人都市中。\n羞道易水寒，从令日贯虹。\n燕丹事不立，虚没秦帝宫。\n舞阳死灰人，安可与成功。'},
    {t:'结袜子',a:'李白〔唐代〕',c:'燕南壮士吴门豪，筑中置铅鱼隐刀。\n感君恩重许君命，太山一掷轻鸿毛。'},
    {t:'解蹀躞·商调',a:'周邦彦〔宋代〕',c:'候馆丹枫吹尽，面旋随风舞。夜寒霜月，飞来伴孤旅。还是独拥秋衾，梦余酒困都醒，满怀离苦。\n甚情绪。深念凌波微步。幽房暗相遇。泪珠都作，秋宵枕前雨。此恨音驿难通，待凭征雁归时，带将愁去。'},
    {t:'解连环·拜陈西麓墓',a:'张炎〔宋代〕',c:'句章城郭。问千年往事，几回归鹤。叹贞元、朝士无多，又日冷湖阴，柳边门钥。向北来时，无处认、江南花落。纵荷衣未改，病损茂陵，总是离索。\n山中故人去却。但碑寒岘首，旧景如昨。怅二乔、空老春深，正歌断帘空，草暗铜雀。楚魄难招，被万叠、闲云迷著。料犹是、听风听雨，郎吟夜壑。'},
    {t:'解连环·孤雁',a:'张炎〔宋代〕',c:'楚江空晚。怅离群万里，恍然惊枯。自顾影、欲下寒塘，正沙净草枯，水平天远。写不成书，只寄得、雪思一点。料因循误了，残毡拥雪，故人心眼。\n谁怜旅愁荏苒。谩长门夜悄，锦筝弹怨。想伴侣、犹宿芦花，也曾念春前，去程应转。暮雨雪呼，怕蓦地、玉关重见。未羞他、双燕归来，画帘半卷。'},
    {t:'解连环·怨怀无托',a:'周邦彦〔宋代〕',c:'怨怀无托。嗟情人断绝，信音辽收。纵妙手、能解连环，似风散雨收，雾轻云薄。燕子楼空，暗尘锁、时床弦索。想移根换叶，尽是旧时，手种红药。\n汀洲渐生杜若。料舟依岸曲，人在天角。谩记得、当日音书，把闲语闲言，待总烧却。水驿春回，望寄我、江南梅萼。拚今生，对花对酒，为伊泪落。'},
    {t:'解佩令',a:'晏几道〔宋代〕',c:'玉阶秋感，年华暗去。掩深宫、团扇无绪。记得当时，自翦下、机中轻素。点丹青、画成秦女。\n凉襟犹在，朱弦未改，忍霜纨、飘零何处。自古悲凉，是情事、轻如云雨。倚么弦、恨长难诉。'},
    {t:'解语花',a:'秦观〔宋代〕',c:'窗涵月影，瓦冷霜华，深院重门悄。画楼雪杪。谁家笛、弄彻梅花新调。寒灯凝照。见锦帐、双鸾翔绕。当此时、倚几沈吟，好景都成恼。\n曾过云山烟岛。对绣襦甲帐，亲逢一笑。人间年少。多情子、惟恨相逢不早。如今见了。却又惹、许多愁抱。算此情、除是青禽，为我殷勤报。'},
    {t:'解语花·上元',a:'周邦彦〔宋代〕',c:'风销焰蜡，露浥红莲，花市光相欲。桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女纤腰一麝。箫鼓喧，人影参差，满路飘香麝。\n因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处，自有暗尘随马。年光是也。唯只见、旧情衰谢。清漏移，飞盖归来，从舞休歌罢。'},
    {t:'解语花·行歌趁月',a:'张炎〔宋代〕',c:'行歌趁月，唤酒延秋，多买莺莺笑。蕊枝娇小。浑无奈、一掬醉乡怀抱。筹花斗草。几曾放、好春闲了。芳意阑，可惜香心，一夜酸风扫。海上仙山缥缈。问玉环何事，苦无分晓。旧愁空杳。蓝桥路、深掩半庭斜照。馀情暗恼。都缘是、那时年少。惊梦回、懒说相思，毕竟如今老。'},
    {t:'戒杀诗',a:'黄庭坚〔宋代〕',c:'我肉众生肉，名殊体不殊。\n原同一种性，只是别形躯。\n苦恼从他受，肥甘为我须。\n莫教阎老断，自揣应何如。'},
    {t:'界围岩水帘',a:'柳宗元〔唐代〕',c:'界围汇湘曲，青壁环澄流。\n悬泉粲成帘，罗注无时休。\n韵磬叩凝碧，锵锵彻岩幽。\n丹霞冠其巅，想像凌虚游。\n灵境不可状，鬼工谅难求。\n忽如朝玉皇，天冕垂前旒。\n楚臣昔南逐，有意仍丹丘。\n今我始北旋，新诏释缧囚。\n采真诚眷恋，许国无淹留。\n再来寄幽梦，遗贮催行舟。'},
    {t:'借车',a:'孟郊〔唐代〕',c:'借车载家具，家具少于车。\n借者莫弹指，贫穷何足嗟。\n百年徒役走，万事尽随花。'},
    {t:'今日非昨日',a:'王安石〔宋代〕',c:'今日非昨日，昨日已可思。\n明日树今日，如何能勿悲。\n当门五六树，上有蝉鸣枝。\n朝听尚壮急，暮华已衰迟。\n仰看青青叶，亦复少华滋。\n万物同一气，固知当尔为。\n我友南山居，笑谈解人颐。\n分我秋柏实，问言归何时。\n衣冠污穷尘，苟得犹苦饥。\n低徊岁已晚，恐负平生期。'},
    {t:'今日良宴会',a:'佚名〔两汉〕',c:'今日良宴会，欢乐难具陈。\n弹筝奋逸响，新声妙入神。\n令德唱高言，识曲听其真。\n齐心同所愿，含意俱未申。\n人生寄一世，奄忽若飙尘。\n何不策高足，先据要路津。\n无为守穷贱，轗轲长苦辛。'},
    {t:'今夕行',a:'杜甫〔唐代〕',c:'今夕何夕岁云徂，更长烛明不可孤。\n咸阳客舍一事无，相与博塞为欢娱。\n冯陵大叫呼五白，袒跣不肯成枭卢。\n英雄有时亦如此，邂逅岂即非良图。\n君莫笑，刘毅从来布衣愿，家无儋石输百万。'},
    {t:'金榜山',a:'朱熹〔宋代〕',c:'陈场老子读书处，金榜山前石室中。人去石存犹昨日，莺啼花落几春风。\n藏修洞口云空集，舒啸岩幽草自茸。应喜斯文今不泯，紫阳秉笔纪前功。'},
    {t:'金城北楼',a:'高适〔唐代〕',c:'北楼西望满晴空，积水连山胜画中。\n湍上急流声若箭，城头残月势如弓。\n垂竿已羡磻溪老，体道犹思塞上翁。\n为问边庭更何事，至今羌笛怨无穷。'},
    {t:'金错刀行',a:'陆游〔宋代〕',c:'黄金错刀白玉装，夜穿窗扉出立芒。\n丈夫五十功未立，提刀独立顾八荒。\n京华结交尽奇士，意名相期共生死。\n千年史册耻无名，一片丹心报天子。\n尔来从军天汉滨，南山晓雪玉嶙峋。\n呜呼！楚虽三户能亡秦，岂有堂堂中国空无人！'},
    {t:'金灯花',a:'晏殊〔宋代〕',c:'兰香爇处光犹浅，银烛烧时焰不馨。\n好向书筇窗下种，免教辛苦更囊萤。'},
    {t:'金凤花',a:'晏殊〔宋代〕',c:'九苞颜色春霞萃，丹穴威仪秀气殚。\n题品直须名最上，昂昂骧首倚朱栏。'},
    {t:'金谷怀古',a:'杜牧〔唐代〕',c:'凄凉遗迹洛川东，浮世荣枯万断同。桃李香消金谷在，\n绮罗魂断玉楼空。往年人事伤心外，今日风光属梦中。\n徒想夜泉流客恨，夜泉流恨恨无穷。'},
    {t:'金谷园',a:'杜牧〔唐代〕',c:'繁华事散逐香尘，流水无情草自春。\n日暮东风怨啼鸟，落花犹似坠楼人。'},
    {t:'金谷园歌',a:'韦应物〔唐代〕',c:'石氏灭，金谷园中水流绝。当时东右争骄侈，\n锦为步障四十里。东风吹花雪满川，紫气凝阁朝飖妍。\n洛阳陌上人回首，丝竹飘飖入青天。晋武平吴恣欢燕，\n馀风靡靡朝廷变。嗣世衰微谁肯忧，\n二十四友日日空追游。追游讵可足，共惜年华促。\n祸端一发埋恨长，百草无情春自绿。'},
    {t:'金蕉叶·厌厌夜饮平阳第',a:'柳永〔宋代〕',c:'厌厌夜饮平阳第。添银烛、旋呼佳丽。巧笑难禁，艳歌无间声相继。准拟幕天席地。\n金蕉叶泛金波齐，未更阑、已尽狂醉。就中有个风流，暗向灯光底，恼遍两行珠翠。'},
    {t:'金菊对芙蓉·上元',a:'纳兰性德〔清代〕',c:'金鸭消香，银虬泻水，谁家夜笛飞声。正上林雪霁，鸳甃晶莹。鱼龙舞罢香车杳，剩尊前、袖掩吴绫。狂游似梦，而今空记，密约烧灯。\n追念往事难凭。叹火树星桥，回首飘零。但九逵烟月，依旧笼明。楚天一带惊烽火，问今宵、可照江城。小窗残酒，阑珊灯灺，别自关情。'},
    {t:'金陵城西楼月下吟',a:'李白〔唐代〕',c:'金陵夜寂凉风发，独上高楼望吴越。\n白云映水摇空城，白露垂珠滴秋月。\n月下沉吟久不归，古来相接眼中稀。\n解道澄江净如练，令人长忆谢玄晖。'},
    {t:'金陵凤凰台置酒',a:'李白〔唐代〕',c:'置酒延落景，金陵凤凰台。\n长波时万古，心与云俱开。\n借问往昔时，凤凰为谁来。\n凤凰去已久，正三今日回。\n明君越羲轩，天老坐三台。\n豪士无所用，弹弦醉金罍。\n东风吹山花，安可不尽杯？\n六帝没幽草，深宫冥绿苔。\n置酒勿复道，歌钟但相催。'},
    {t:'金陵歌送别范宣',a:'李白〔唐代〕',c:'石头巉岩如虎踞，凌波欲过沧江去。\n钟山龙盘走势来，秀色横分历阳树。\n四十馀帝三百秋，功名事迹随东流。\n白马小儿谁家子，泰清之岁来关囚。\n金陵昔时何壮哉！席卷英豪天下来。\n冠盖散为烟雾尽，金舆玉座成寒灰。\n扣剑悲吟空咄嗟，梁陈白骨乱如麻。\n天子龙沉景阳井，谁歌玉树后庭花。\n此地伤心不能道，目下离离长春草。\n送尔长江万里心，他年来访南山老。'},
    {t:'金陵怀古',a:'王安石〔宋代〕',c:'六代豪华空处所，金陵王气黯然收。\n烟浓草远望不尽，物换星移度几秋。\n至竟江山谁是主，却因歌舞破除休。\n我来不见当时事，上尽重城更上楼。'},
    {t:'金陵怀古',a:'刘禹锡〔唐代〕',c:'潮满冶城渚，日斜征虏亭。\n蔡洲新草绿，幕府旧烟青。\n兴废由人事，山川空地形。\n后庭花一曲，幽怨不堪听。'},
    {t:'金陵怀古四首',a:'王安石〔宋代〕',c:'地势东回万里江，云间天阙古原双。\n兵缠四海英雄得，圣出中原次第降。\n山水寂寥埋王气，风烟萧飒满僧窗。\n废陵坏冢空冠剑，谁复沾缨酹一缸。'},
    {t:'金陵怀古四首·其一',a:'王安石〔宋代〕',c:'霸祖孤身取二江，子孙多以百知降。\n豪华尽出成功后，逸乐安知与祸双？\n东府旧基留佛刹，后庭余唱落船窗。\n黍离麦秀从来事，且置兴亡近酒缸。'},
    {t:'金陵即事',a:'王安石〔宋代〕',c:'水际柴扉一半开，小桥分路入青苔。\n背人照影无穷柳，隔屋吹香并是梅。'},
    {t:'金陵酒肆留别',a:'李白〔唐代〕',c:'风吹柳花满店香，吴姬压酒劝客尝。\n金陵子弟来相送，欲行不行各尽觞。\n请君试问东流水，别意与之谁短长？'},
    {t:'金陵三首',a:'李白〔唐代〕',c:'晋家南渡日，此地旧长安。\n地即帝王宅，山为龙虎盘。\n金陵空壮观，天堑净波澜。\n醉客回桡去，吴歌且自欢。\n地拥金陵势，城回江水流。\n当时百万户，夹道起朱楼。\n亡国生春草，王宫没古丘。\n空余后湖月，波上对瀛州。\n六代兴亡国，三杯为尔歌。\n苑方秦地少，山似洛阳多。\n古殿吴花草，深宫晋绮罗。\n并随人事灭，东逝与沧波。'},
    {t:'金陵望汉江',a:'李白〔唐代〕',c:'汉江回万里，派作九龙盘。\n横溃豁中国，崔嵬飞迅湍。\n六帝沦亡后，三吴不足观。\n我君混区宇，垂拱众流安。\n今日任公子，沧浪罢钓竿。'},
    {t:'金陵五题·石头城',a:'刘禹锡〔唐代〕',c:'山围故国周遭在，潮打空城寂寞回。\n淮水东边旧时月，夜深还过女墙来。'},
    {t:'金陵五题·台城',a:'刘禹锡〔唐代〕',c:'台城六代竞豪华，结绮临春事最奢。\n万户千门成野草，只缘一曲后庭花。'},
    {t:'金陵新亭',a:'李白〔唐代〕',c:'金陵风景好，豪士集新亭。\n举目山河异，偏伤周顗情。\n四坐楚囚悲，不忧社稷倾。\n王公何慷慨，千载仰雄名。'},
    {t:'金陵驿二首',a:'文天祥〔宋代〕',c:'草合离宫转夕晖，孤云飘泊复何依？\n山河风景元无异，城郭人民半已非。\n满地芦花和我老，旧家燕子傍谁飞？\n从今别却江南路，化作啼鹃带血归。\n万里金瓯失壮图，衮衣颠倒落泥涂。\n空流杜宇声中血，半脱骊龙颔下须。\n老去秋风吹我恶，梦回寒月照人孤。\n千年成败俱尘土，消得人间说丈夫。'},
    {t:'金缕曲·寄梁汾',a:'纳兰性德〔清代〕',c:'木落吴江矣，正萧条、西风南雁，碧云千里。落魄江湖还载酒，一种悲凉滋味。重回首、莫弹酸泪。不是天公教弃置，是南华、误却方城尉。飘泊处，谁相慰。\n别来我亦伤孤寄。更那堪、冰霜摧折，壮怀都废。天远难穷劳望眼，欲上高楼还已。君莫恨、埋愁无地。秋雨秋花关塞冷，且殷勤、好作加餐计。人岂得，长无谓。'},
    {t:'金缕曲·姜西溟言别赋此赠之',a:'纳兰性德〔清代〕',c:'谁复留君住。叹人生、几翻离合，话成迟暮。最忆西窗同剪烛，却话家山夜雨。不道只、暂时相聚。哀哀长江萧萧木，送遥天、白雁哀鸣去。黄叶下，秋如许。\n曰归因甚添愁绪。料强似、冷烟寒月，栖迟梵宇。一事伤心君落魄，两鬓飘萧未遇。有解忆、长安儿女。裘敝入门空太息，信古来、才命真相负。身世恨，共谁语？'},
    {t:'金缕曲·洒尽无端泪',a:'纳兰性德〔清代〕',c:'简梁汾，时方为吴汉槎作归计。\n洒尽无端泪，莫因他、琼楼寂寞，误来人世。信道痴儿多厚福，谁遣偏生明慧。莫更著、浮名相累。仕宦何妨如断梗，只那将、声影供群吠。天欲问，且休矣。\n情深我自判憔悴。转丁宁、香怜易爇，玉怜轻碎。羡杀软红尘里客，一味醉生梦死。歌与哭、任猜何意。绝塞生还吴季子，算眼前、此外皆闲事。知我者，梁汾耳。'},
    {t:'金缕曲·疏影临书卷',a:'纳兰性德〔清代〕',c:'疏影临书卷。带霜华、高高在下，粉脂都遣。别是幽情嫌妩媚，红烛啼痕休泫。趁皓月、光浮冰茧。恰与花神供写照，任泼来、淡墨无深浅。持素障，夜中展。\n残釭掩过看逾显。相对处、芙蓉玉绽，鹤翎银扁。但得白衣时慰藉，一任浮云苍犬。尘土隔、软红偷免。帘幕西风人不寐，恁清光、肯惜鹴裘典。休便把，落英剪。'},
    {t:'金缕曲·亡妇忌日有感',a:'纳兰性德〔清代〕',c:'此恨何时已。滴空阶、寒更雨歇，葬花天气。三载悠悠魂梦杳，是梦久应醒矣。料也觉、人间无味。不及夜台尘土隔，冷清清、一片埋愁地。钗钿约，竟抛弃。\n重泉若有双鱼寄。好知他、年来苦乐，与谁相倚。我自中宵成转侧，忍听湘弦重理。待结个、他生知己。还怕两人俱薄命，再缘悭、剩月零风里。清泪尽，纸灰起。'},
    {t:'金缕曲·未得长无谓',a:'纳兰性德〔清代〕',c:'未得长无谓，竟须将、银河亲挽，普天一洗。麟阁才教留粉本，大笑拂衣归矣。如斯者、古今能几？有限好春无限恨，没来由、短尽英雄气。暂觅个，柔乡避。东君轻薄知何意。尽年年、愁红惨绿，添人憔悴。两鬓飘萧容易白，错把韶华虚费。便决计、疏狂休悔。但有玉人常照眼，向名花、美酒拼沉醉。天下事，公等在。'},
    {t:'金缕曲·慰西溟',a:'纳兰性德〔清代〕',c:'何事添凄咽？但由他、天公簸弄，莫教磨涅。失意每多如意少，终古几人称屈。须知道、福因才折。独卧藜床看北斗，背高城、玉笛吹成血。听谯鼓，二更彻。\n丈夫未肯因人热，且乘闲、五湖料理，扁舟一叶。泪似秋霖挥不尽，洒向野田黄蝶。须不羡、承明班列，马迹车尘忙未了，任西风吹冷长安月。又萧寺，花如雪。'},
    {t:'金缕曲·赠梁汾',a:'纳兰性德〔清代〕',c:'德也狂生耳。偶然间，淄尘京国，乌衣门第。有酒惟浇赵州土，谁会成生此意。不信道、遂成知己。青眼高歌俱未老，向尊前、拭尽英雄泪。君不见，月如水。\n共君此夜须沉醉。且由他，娥眉谣诼，古今同忌。身世悠悠何足问，冷笑置之而已。寻思起、从头翻悔。一日心期千劫在，后身缘、恐结他生里。然诺重，君须记。'},
    {t:'金柅园',a:'晏殊〔宋代〕',c:'临川楼上柅园中，十五年前此会同。\n一曲清歌满樽酒，人生何处不相逢。'},
    {t:'金山寺',a:'王安石〔宋代〕',c:'重经高处寺，一与白云亲。\n树木有春意，江山如故人。\n幽轩含气象，偏影落风尘。\n日暮临归去，徘徊欲损神。'},
    {t:'金山晚眺',a:'秦观〔宋代〕',c:'西津江口月初弦，水气昏昏上接天。\n清渚白沙茫不辨，只应灯火是渔船。'},
    {t:'金铜仙人辞汉歌',a:'李贺〔唐代〕',c:'魏明帝青龙元年八月，诏宫官牵车西取汉孝武捧露盘仙人，欲立置前殿。宫官既拆盘，仙人临载，乃潸然泪下。唐诸王孙李长吉遂作《金铜仙人辞汉歌》。\n茂陵刘郎秋风客，夜闻马嘶晓无迹。\n画栏桂树悬秋香，三十六宫土花碧。\n魏官牵车指千里，东关酸风射眸子。\n空将汉月出宫门，忆君清泪如铅水。\n衰兰送客咸阳道，天若有情天亦老。\n携盘独出月荒凉，渭城已远波声小。'},
    {t:'金乡送韦八之西京',a:'李白〔唐代〕',c:'客自长安来，还归长安去。\n狂风吹我心，西挂咸阳树。\n此情不可道，此别何时遇。\n望望不见君，连山起烟雾。'},
    {t:'锦城曲',a:'温庭筠〔唐代〕',c:'蜀山攒黛留晴雪，簝笋蕨芽萦枝折。\n江风吹巧剪霞绡，花上千枝杜鹃血。\n杜鹃飞入岩下丛，夜尽思归山月中。\n巴水漾情情不尽，文君织得春机红。\n怨魄未归芳草死，江头学种相思子。\n树成寄与望乡人，白帝荒城五千里。'},
    {t:'锦瑟',a:'李商隐〔唐代〕',c:'锦瑟无端五十弦，一弦一柱思心年。\n庄生晓梦迷蝴蝶，望帝春心托杜鹃。\n沧海月明珠有泪，蓝田日暖玉生烟。\n此情可待成追忆，只是当时已惘然。'},
    {t:'锦堂春·坠髻慵梳',a:'柳永〔宋代〕',c:'坠髻慵梳，愁蛾懒画，心绪是事阑珊。觉新来憔悴，金缕衣宽。认得这疏狂意下，向人诮譬如闲。把芳容整顿，恁地轻孤，争忍心安。\n依前过了旧约，甚当初赚我，偷翦云鬟。几时得归来，香阁深关。待伊要、尤云殢雨，缠绣衾、不与同欢。侭更深、款款问伊，今后敢更无端。'},
    {t:'锦帐春·席上和叔高韵',a:'辛弃疾〔宋代〕',c:'春色难留，酒杯常浅。把旧恨、新愁相间。五更风，千里梦，看飞红几片。这般庭院。\n几许风流，几般娇懒。问相见、何如不见。燕飞忙，莺语乱。恨重帘不卷。翠屏平远。'},
    {t:'槿花',a:'李商隐〔唐代〕',c:'风露凄凄秋景繁，可怜荣落在朝昏。\n未央宫里三千女，但保红颜莫保恩。'},
    {t:'进艇',a:'杜甫〔唐代〕',c:'南京久客耕南亩，北望伤神坐北窗。\n昼引老妻乘小艇，晴看稚子浴清江。\n俱飞蛱蝶元相逐，并蒂芙蓉本自双。\n茗饮蔗浆携所有，瓷罂无谢玉为缸。'},
    {t:'晋祠泉',a:'范仲淹〔宋代〕',c:'神哉叔虞庙，地胜出嘉泉。\n一源其澄静，数步忽潺湲。\n此异孰可穷，观者增恭虔。\n锦鳞无敢钓，长生同水仙。\n千家溉禾稻，满目江乡田。\n我来动所思，致主愧前贤。\n大道果能行，时雨宜不愆。\n皆如晋祠下，生民无旱年。'},
    {t:'禁苑',a:'晏殊〔宋代〕',c:'风回玉宇箫声远，日下琼林佩影间。\n待得年光遍天下，始教春色到人间。'},
    {t:'禁中九日对菊花酒忆元九',a:'白居易〔唐代〕',c:'赐酒盈杯谁共持，宫花满把独相思。\n相思只傍花边立，尽日吟君咏菊诗。'},
    {t:'禁中夜作书与元九',a:'白居易〔唐代〕',c:'心绪万端书两纸，欲封重读意迟迟。\n五声宫漏初鸣夜，一点窗灯欲灭时。'},
    {t:'京城',a:'李贺〔唐代〕',c:'驱马出门意，牢落长安心。两事谁向道，自作秋风吟。'},
    {t:'京城借永福寺漆台占似王城山',a:'文天祥〔宋代〕',c:'心如明镜台，此言出浮屠。\n后来发精义，并谓此台无。\n此台已是赘，何况形而器。\n圆释正超然，点头会意思。\n多谢城山翁，一语迎禅锋。\n顾我尘俗人，与物方溶溶。'},
    {t:'京还赠张维',a:'孟浩然〔唐代〕',c:'拂衣去何处？高枕南山南。\n欲徇五斗禄，其如七不堪。\n早朝非晏起，束带异抽簪。\n因向智者说，游鱼思旧潭。'},
    {t:'京还赠张·一作王维',a:'孟浩然〔唐代〕',c:'拂衣何处去，高枕南山南。欲徇五斗禄，其如七不堪。\n早朝非晚起，束带异抽簪。因向智者说，游鱼思旧潭。'},
    {t:'京湖宣阃第九',a:'文天祥〔宋代〕',c:'正当艰难时，岂无济时策。\n连樯荆州船，悠悠回赤壁。'},
    {t:'京口即事',a:'范仲淹〔宋代〕',c:'突兀立孤城，诗中别有情。\n地深江底过，日大海心生。\n甘露楼台古，金山气象清。\n六朝人薄命，不见此升平。'},
    {t:'京山行',a:'孟郊〔唐代〕',c:'众虻聚病马，流血不得行。后路起夜色，前山闻虎声。\n此时游子心，百尺风中旌。'},
    {t:'京师叛乱寄诸弟',a:'韦应物〔唐代〕',c:'弱冠遭世难，二纪犹未平。羁离恋远郡，虎豹满西京。\n上怀犬马恋，下有骨肉情。归去在何时，流军忽沾缨。\n忧来上北楼，左右但军营。函谷行人绝，淮南春草生。\n鸟鸣野田间，思忆故园行。何当四海晏，甘与齐民耕。'},
    {t:'京兆府栽莲',a:'白居易〔唐代〕',c:'污沟贮浊水，水上叶田田。\n我来一长叹，知是东溪莲。\n下有青污泥，馨香无复全。\n上有红尘扑，颜色不得鲜。\n物性犹如此，人事亦宜然。\n托根非其所，不如遭弃捐。\n昔在溪中日，花叶媚清涟。\n今年不得地，憔悴府门前。'},
    {t:'经伏波神祠',a:'刘禹锡〔唐代〕',c:'蒙蒙篁竹下，有路上壶头。汉垒麏鼯斗，蛮溪雾雨愁。\n怀人敬遗像，阅世指东流。自负霸王略，安知恩泽侯。\n乡园辞石柱，筋力尽炎洲。一以功名累，翻思马少游。'},
    {t:'经故翰林袁学士居',a:'温庭筠〔唐代〕',c:'剑逐惊波玉委尘，谢安门下更何人。\n西州城外花千树，尽是羊昙醉后春。'},
    {t:'经函谷关',a:'韦应物〔唐代〕',c:'洪河绝山根，单轨出其侧。万古为要枢，往来何时息。\n秦皇既恃险，海内被吞食。及嗣同覆颠，咽喉莫能塞。\n炎灵讵西驾，娄子非经国。徒欲扼诸侯，不知恢至德。\n圣朝及天宝，豺虎起东北。下沉战死魂，上结穷冤色。\n古今虽共守，成败良可识。藩屏无俊贤，金汤独何力。\n驰车一登眺，感慨中自恻。'},
    {t:'经火山',a:'岑参〔唐代〕',c:'火山今始见，突兀蒲昌东。\n赤焰烧虏云，炎氛蒸塞空。\n不知阴阳炭，何独烧此中？\n我来严冬时，山下多炎风。\n人马尽汗流，孰知造化工！'},
    {t:'经江宁览旧迹至玄武湖',a:'张九龄〔唐代〕',c:'南国更数世，北湖方十洲。天清骑林苑，日晏景阳楼。\n果下回仙骑，津傍驻彩斿。凫鹥喧凤管，荷棹斗龙舟。\n七子陪诗赋，千人和棹讴。应言在镐乐，不让横汾秋。\n风俗因纾慢，江山成易由。驹王信不武，孙叔是无谋。\n佳气日将歇，霸功谁与修。桑田东海变，麋鹿姑苏游。\n否运争三国，康时劣九州。山虽幕府在，馆岂豫章留。\n水淀还相阅，菱歌亦故遒。雄图不足问，唯想事风流。'},
    {t:'经旧游·一作怀真珠亭',a:'温庭筠〔唐代〕',c:'珠箔金钩对彩桥，昔年于此见娇娆。香灯怅望飞琼鬓，\n凉月殷勤碧玉箫。屏倚故窗山六扇，柳垂寒砌露千条。\n坏墙经雨苍苔遍，拾得当时旧翠翘。'},
    {t:'经陇头分水',a:'岑参〔唐代〕',c:'陇水何年有，潺潺逼路傍。\n东西流不歇，曾断几人肠。'},
    {t:'经七里滩',a:'孟浩然〔唐代〕',c:'予奉垂堂诫，千金非所轻。为多山水乐，频作泛舟行。\n五岳追向子，三湘吊屈平。湖经洞庭阔，江入新安清。\n复闻严陵濑，乃在兹湍路。叠障数百里，沿洄非一趣。\n彩翠相氛氲，别流乱奔注。钓矶平可坐，苔磴滑难步。\n猿饮石下潭，鸟还日边树。观奇恨来晚，倚棹惜将暮。\n挥手弄潺湲，从兹洗尘虑。'},
    {t:'经七里滩①',a:'孟浩然〔唐代〕',c:'余奉垂堂诫，千金非所轻。②\n为多山水乐，频作泛舟行。\n五岳追尚子，三湘吊屈平。③\n湖经洞庭阔，江入新安清。\n复闻严陵濑，乃在兹湍路。④\n叠障数百里，沿洄非一趣。\n彩翠相氛氲，别流乱奔注。\n钓矶平可坐，苔磴滑难步。⑤\n猿饮石下潭，鸟还日边树。\n观奇恨来晚，倚棹惜将暮。\n挥手弄潺［水旁＋爰］。从兹洗尘虑。'},
    {t:'经沙苑',a:'李贺〔唐代〕',c:'野水泛长澜，宫牙开小蒨。无人柳自春，草渚鸳鸯暖。\n晴嘶卧沙马，老去悲啼展。今春还不归，塞嘤折翅雁。'},
    {t:'经少林精舍，寄都邑亲友',a:'韦应物〔唐代〕',c:'息驾依松岭，高阁一攀缘。前瞻路已穷，既诣喜更延。\n出巘听万籁，入林濯幽泉。鸣钟生道心，暮磬空云烟。\n独往虽暂适，多累终见牵。方思结茅地，归息期暮年。'},
    {t:'经檀道济故垒',a:'刘禹锡〔唐代〕',c:'万里长城坏，荒营野草秋。\n秣陵多士女，犹唱白符鸠。'},
    {t:'经西坞偶题',a:'温庭筠〔唐代〕',c:'摇摇弱柳黄鹂啼，芳草无情人自迷。日影明灭金色鲤，\n杏花唼喋青头鸡。微红奈蒂惹峰粉，洁白芹芽穿燕泥。\n借问含嚬向何事，昔年曾到武陵溪。'},
    {t:'经下邳圯桥怀张子房',a:'李白〔唐代〕',c:'子房未虎啸，破产不为家。\n沧海得壮士，椎秦博浪沙。\n报韩虽不成，天地皆振动。\n潜匿游下邳，岂曰非智勇？\n我来圯桥上，怀古钦英风。\n唯见碧流水，曾无黄石公。\n叹息此人去，萧条徐泗空。'},
    {t:'荆门道怀古',a:'刘禹锡〔唐代〕',c:'南国山川旧帝畿，宋台梁馆尚城稀。\n马嘶古道行人歇，麦秀空城野雉飞。\n风吹落叶填宫井，火入荒陵化宝衣。\n徒使词臣庾开府，咸阳终日苦思归。'},
    {t:'荆门上张丞相',a:'孟浩然〔唐代〕',c:'共理分荆国，招贤愧不材。召南睫更阐，丞相阁还开。\n觏止欣眉睫，沉沦拔草莱。坐登徐孺榻，频间李膺杯。\n始慰蝉鸣柳，俄看雪间梅。四时年籥尽，千里客程催。\n日下瞻归翼，沙边厌曝鳃。伫闻宣室召，星象列三台。'},
    {t:'荆门西下',a:'李商隐〔唐代〕',c:'一夕南风一叶危，荆云回望夏云时。\n人生岂得轻离别，天意何曾忌险巇。\n骨肉书题安绝徼，蕙兰蹊径失佳期。\n洞庭湖阔蛟龙恶，却羡杨朱泣路岐。'},
    {t:'荆州贼平临洞庭言怀作',a:'李白〔唐代〕',c:'修蛇横洞庭，吞象临江岛。\n积骨成巴陵，遗言闻楚老。\n水穷三苗国，地窄三湘道。\n岁晏天峥嵘，时危人枯槁。\n思归阴丧乱，去国伤怀抱。\n郢路方丘墟，章华亦倾倒。\n风悲猿啸苦，木落鸿飞早。\n日隐西赤沙，月明东城草。\n关河望已绝，氛雾行当扫。\n长叫天可闻，吾将问苍昊。'},
    {t:'精卫',a:'岑参〔唐代〕',c:'负剑出北门，乘桴适东溟。一鸟死上飞，云是帝女灵。\n玉颜溺水死，精卫空为名。怨积徒有志，力微竟不成。\n西山木石尽，巨壑何时平。'},
    {t:'精卫',a:'王安石〔宋代〕',c:'帝子衔冤久未平，区区微意欲何成。\n情知木石无云补，待见桑田几变更。'},
    {t:'井络',a:'李商隐〔唐代〕',c:'井络天彭一掌中，漫夸天设剑为峰。\n阵图东聚燕江石，边柝西悬雪岭松。\n堪叹故君成杜宇，可能先主是真龙。\n将来为报奸雄辈，莫向金牛访旧踪。'},
    {t:'井上枸杞架',a:'孟郊〔唐代〕',c:'深锁银泉甃，高叶架云空。不与凡木并，自将仙盖同。\n影疏千点月，声细万条风。迸子邻沟外，飘香客位中。\n花杯承此饮，椿岁小无穷。'},
    {t:'景山',a:'纳兰性德〔清代〕',c:'雪里瑶华岛，云端白玉京。\n削成千仞势，高出九重城。\n绣陌回环绕，红楼宛转迎。\n近天多雨露，草木每先荣。'},
    {t:'景星',a:'佚名〔两汉〕',c:'景星显见，信星彪列，象载昭庭，汾亲以察。\n参侔开阖，爰推本纪，汾脽出鼎，皇佑元始。\n五音六律，空韦飨昭，杂变并会，雅声远姚。\n空桑琴瑟结信成，四兴递代八风生。\n殷殷钟石羽龠鸣。河龙供鲤醇牺牲。\n百末旨酒布兰生。泰尊柘浆析朝酲。\n微感心攸通修名，周流常羊思所并。\n穰穰复正直往宁，冯蠵切和疏写平。\n上天布施后土成，穰穰丰年四时荣。'},
    {t:'景阳井',a:'李商隐〔唐代〕',c:'景阳宫井剩堪悲，不尽龙鸾誓死期。\n肠断吴王宫外水，浊泥犹得葬西施。'},
    {t:'景祐祭文宣王庙六首',a:'佚名〔隋代〕',c:'大哉至圣，文教之宗。\n纪网王化，丕变民风。\n常祀有秩，备物有容。\n神其格思，是仰是崇。'},
    {t:'敬酬李判官使院即事见呈',a:'岑参〔唐代〕',c:'公府日无事，吾徒只是闲。\n草根侵柱础，苔色上门关。\n饮砚时见鸟，卷帘晴对山。\n新诗吟未足，昨夜梦东还。'},
    {t:'靖安寄居',a:'孟郊〔唐代〕',c:'寄静不寄华，爱兹嵽嵲居。渴饮火清泉，饥食无名蔬。\n败菜不敢火，补衣亦写书。古云俭成德，今有实起予。\n戆叟戆不足，贤人贤有馀。役生皆促促，心竟谁舒舒。\n万马踏风衢，众尘随奔车。高宾尽不见，大道夜方虚。\n卧有洞庭梦，坐无长安储。英髦空骇耳，烟火独微如。\n厚念恐伤性，薄田忆亲锄。承世不出力，冬竹肯抽菹。\n外物莫相诱，约心誓从初。碧芳既似水，日日咏归欤。'},
    {t:'静法师东斋',a:'王昌龄〔唐代〕',c:'筑室在人境，遂得真隐情。春尽草木变，雨来池馆清。\n琴书全雅道，视听已无生。闭户脱三界，白云自虚盈。'},
    {t:'静女春曙曲',a:'李贺〔唐代〕',c:'嫩叶怜芳抱新蕊，泣露枝枝滴夭泪。\n粉窗香咽颓晓云，锦堆花密藏春睡。\n恋屏孔雀摇金尾，莺舌分明呼婢子。\n冰洞寒龙半匣水，一只商鸾逐烟起。'},
    {t:'静女吟',a:'孟郊〔唐代〕',c:'艳女皆妒色，静女独检踪。任礼耻任妆，嫁德不嫁容。\n君子易求聘，小人难自从。此志谁与谅，琴弦幽韵重。'},
    {t:'静心诀',a:'佚名',c:'冰寒千古，万物尤静；\n心宜气静，望我独神；\n心神合一，气宜相随；\n相间若余，万变不惊；\n无痴无嗔，无欲无求；\n无舍无弃，无为无我。'},
    {t:'静夜思',a:'李白〔唐代〕',c:'床前明月光，疑是地上霜。\n举头望明月，低头思故乡。'},
    {t:'镜湖女',a:'陆游〔宋代〕',c:'湖中居人事舟楫，家家以舟作翻业。\n女儿妆面花样红，小伞翻翻乱荷叶。\n日暮归来月色新，菱歌缥缈泛烟津。\n到家更约西邻女，明日湖桥看赛神。'},
    {t:'镜槛',a:'李商隐〔唐代〕',c:'镜槛芙蓉入，香台翡翠过。拨弦惊火凤，交扇拂天鹅。\n隐忍阳城笑，喧传郢市歌。仙眉琼作叶，佛髻钿为螺。\n五里无因雾，三秋只见河。月中供药剩，海上得绡多。\n玉集胡沙割，犀留圣水磨。斜门穿戏蝶，小阁锁飞蛾。\n骑襜侵鞯卷，车帷约幰鈋。传书两行雁，取酒一封驼。\n桥迥凉风压，沟横夕照和。待乌燕太子，驻马魏东阿。\n想像铺芳褥，依稀解醉罗。散时帘隔露，卧后幕生波。\n梯稳从攀桂，弓调任射莎。岂能抛断梦，听鼓事朝珂。'},
    {t:'九华观看花',a:'张籍〔唐代〕',c:'街西无数闲游处，不似九华仙观中。\n花里可怜池上景，几重墙壁贮春风。'},
    {t:'九华山歌',a:'刘禹锡〔唐代〕',c:'奇峰一见惊魂魄，意想洪炉始开辟。疑是九龙夭矫欲攀天，\n忽逢霹雳一声化为石，不然何至今，悠悠亿万年，\n气势不死如腾屳。云含幽兮月添冷，月凝晖兮江漾影。\n结根不得要路津，迥秀长在无人境。轩皇封禅登云亭，\n大禹会计临东溟。乘樏不来广乐绝，独与猿鸟愁青荧。\n君不见敬亭之山黄索漠，兀如断岸无棱角。\n宣城谢守一首诗，遂使声名齐五岳。九华山，九华山，\n自是造化一尤物，焉能籍甚乎人间。'},
    {t:'九江口作',a:'王昌龄〔唐代〕',c:'漭漭江势阔，雨开浔阳秋。驿门合高岸，望尽黄芦洲。\n水与五溪合，心期万里游。明时无弃才，谪去随孤舟。\n鸷鸟立寒木，丈夫佩吴钩。何当报君恩，却系单于头。'},
    {t:'九年十一月二十一日感事而作',a:'白居易〔唐代〕',c:'祸福茫茫不可期，大都早退似先知。\n当君白首同归日，是我青山独往时。\n顾索素琴应不暇，忆牵黄犬定难追。\n麒麟作脯龙为醢，何似泥中曳尾龟。'},
    {t:'九拍',a:'文天祥〔宋代〕',c:'午夜漏声催晓箭，寒尽春生洛阳殿。\n汉主山河锦绣中，可惜春光不相见。\n自胡之反持干戈，一生抱恨空咨嗟。\n我已无家寻弟妹，此身那得更无家。\n南极一星朝北斗，每依南斗望京华。'},
    {t:'九曲词三首',a:'高适〔唐代〕',c:'许国从来彻庙堂，连年不为在疆场。\n将军天上封侯印，御史台上异姓王。\n万骑争歌杨柳春，千场对舞绣骐驎。\n到处尽逢欢洽事，相看总是太平人。\n铁骑横行铁岭头，西看逻逤取封侯。\n青海只今将饮马，黄河不用更防秋。'},
    {t:'九日',a:'李商隐〔唐代〕',c:'曾共山翁把酒时，霜天白菊绕阶墀。\n十年泉下无消息，九日樽前有所思。\n不学汉臣栽苜蓿，空教楚客咏江蓠。\n郎君官贵施行马，东阁无因再得窥。'},
    {t:'九日',a:'朱熹〔宋代〕',c:'故国音书阻一方，天涯此日思茫茫。风烟岁晚添离恨，湖海尊前即大荒。\n薄宦驱人向愁悴，旧游惟我最颠狂。细思万石亭前事，辜负黄花满帽香。'},
    {t:'九日',a:'杜甫〔唐代〕',c:'去年登高郪县北，今日重在涪江滨。\n苦遭白发不相放，羞见黄花无数新。\n世乱郁郁久为客，路难悠悠常傍人。\n酒阑却忆十年事，肠断骊山清路尘。'},
    {t:'九日',a:'范仲淹〔宋代〕',c:'欲赋前贤九日诗，茱萸相斗一枝枝。\n可怜宋玉情无限，争似陶潜醉不知。\n绿鬓爱随风景变，黄华能与岁寒期。\n登高回处狂多少，笑杀襄阳拍手儿。'},
    {t:'九日',a:'李白〔唐代〕',c:'今日云景好，水绿秋山明。\n携壶酌流霞，搴菊泛寒荣。\n地远松石古，风扬弦管清。\n窥觞照欢颜，独笑还自倾。\n落帽醉山月，空歌怀友生。'},
    {t:'九日',a:'韦应物〔唐代〕',c:'今朝把酒复惆怅，忆在杜陵田舍时。\n明年九日知何处，世难还家未有期。'},
    {t:'九日北郡登高见寄',a:'晏殊〔宋代〕',c:'前日登高泛玉户，击铜赓唱胶析辞。\n如何偶作销魂别，又复重吟把菊诗。\n上苑盍簪延景刻，北都投辖盛官仪。\n烦君见想欢言者，可奈衡门绝贡綦。'},
    {t:'九日酬颜少府',a:'高适〔唐代〕',c:'檐前白日应可惜，篱下黄花为钱有。行子迎霜未授衣，\n主人得钱始沽酒。苏秦憔悴人多厌，蔡泽栖迟世看丑。\n纵使登高只断肠，不如独坐空搔首。'},
    {t:'九日次韵王巩',a:'苏轼〔宋代〕',c:'我醉欲眠君罢休，已教从事到君州。\n鬓霜饶我三千丈，诗律输君一百筹。\n闻道郎君闭东阁，且容老子上南楼。\n相逢不用忙归去，明日黄花蝶也愁。'},
    {t:'九日得新字',a:'孟浩然〔唐代〕',c:'初九未成旬，重阳即此晨。登高闻古事，载酒访幽人。\n落帽恣欢饮，授衣同试新。茱萸正可佩，折取寄情亲。'},
    {t:'九日登巴陵置酒望洞庭水军',a:'李白〔唐代〕',c:'九日天气清，登高无秋云。\n造化辟川岳，了然楚汉分。\n长风鼓横波，合沓蹙龙文。\n忆昔传游豫，楼船壮横汾。\n今兹讨鲸鲵，旌旆何缤纷。\n白羽落酒樽，洞庭罗三军。\n黄花不掇手，战鼓遥相闻。\n剑舞转颓阳，当时日停曛。\n酣歌激壮士，可以摧妖氛。\n握齱东篱下，渊明不足群。'},
    {t:'九日登东山寄昌叔',a:'王安石〔宋代〕',c:'城上啼乌破寂寥，思君何处坐迢嶢。\n应须绿酒酬黄菊，何必红裙弄紫箫。\n落木云连秋水渡，乱山烟入夕阳桥。\n渊明久负东篱醉，犹分低心事折腰。'},
    {t:'九日登高',a:'王昌龄〔唐代〕',c:'青山远近带皇州，霁景重阳上北楼。\n雨歇亭皋仙菊润，霜飞天苑御梨秋。\n茱萸插鬓花宜寿，翡翠横钗舞作愁。\n谩说陶潜篱下醉，何曾得见此风流。'},
    {t:'九日登高',a:'刘禹锡〔唐代〕',c:'世路山河险，君门烟雾深。\n年年上高处，未省不伤心。'},
    {t:'九日寄岑参',a:'杜甫〔唐代〕',c:'出门复入门，雨脚但如旧。\n所向泥活活，思君令人瘦。\n沉吟坐西轩，饮食错昏昼。\n寸步曲江头，难为一相就。\n吁嗟呼苍生，稼穑不可救。\n安得诛云师，畴能补天漏。\n大明韬日月，旷野号禽兽。\n君子强逶迤，小人困驰骤。\n维南有崇山，恐与川浸溜。\n是节东篱菊，纷披为谁秀。\n岑生多新诗，性亦嗜醇酎。\n采采黄金花，何由满衣袖。'},
    {t:'九日蓝田崔氏庄',a:'杜甫〔唐代〕',c:'老去悲秋强自宽，兴来今日尽君欢。\n羞将短发还吹帽，笑倩旁人为正冠。\n蓝水远从千涧落，玉山高并两峰寒。\n明年此会知谁健？醉把茱萸仔细看。'},
    {t:'九日龙沙作，寄刘大昚虚',a:'孟浩然〔唐代〕',c:'龙沙豫章北，九日挂帆过。风俗因时见，湖山发兴多。\n客中谁送酒，棹里自成歌。歌竟乘流去，滔滔任夕波。'},
    {t:'九日龙山饮',a:'李白〔唐代〕',c:'九日龙山饮，黄花笑逐臣。\n醉看风落帽，舞爱月留人。'},
    {t:'九日齐山登高',a:'杜牧〔唐代〕',c:'江涵秋影雁初飞，与客携壶上插微。\n尘世难逢开口笑，菊花须插满头归。\n但将酩酊酬佳节，不用登临恨落晖。\n古往今来只如此，牛山何必独霑衣。'},
    {t:'九日使君席奉饯卫中丞赴长水',a:'岑参〔唐代〕',c:'节使横行西出师，鸣弓擐甲羽气儿。\n台上霜风凌草木，军中杀气傍旌旗。\n预知汉将宣威日，正是胡尘欲灭时。\n为报使君多泛菊，更将弦管醉东篱。'},
    {t:'九日五首·其一',a:'杜甫〔唐代〕',c:'重阳独酌杯中酒，抱病起登江上台。\n竹叶于人既无分，菊花从此不须开。\n殊方日落玄猿哭，旧国霜前白雁来。\n弟妹萧条各何在，干戈衰谢两相催！'},
    {t:'九日闲居',a:'陶渊明〔魏晋〕',c:'余闲居，爱重九之名。秋菊盈园，而持醪靡由，空服九华，寄怀于言。\n世短意常多，斯人乐久生。\n日月依辰至，举俗爱其名。\n露凄暄风息，气澈天象明。\n往燕无遗影，来雁有余声。\n酒能祛百虑，菊解制颓龄。\n如何蓬庐士，空视时运倾！\n尘爵耻虚罍，寒华徒自荣。\n敛襟独闲谣，缅焉起深情。\n栖迟固多娱，淹留岂无成。'},
    {t:'九日宴集和徐通判韵',a:'晏殊〔宋代〕',c:'散插黄花两佩萸，粉饘蓬饵酹觞初。\n清歌咽后云生袂，妙舞翻时雪满裾。\n上客采香逢木密，佳人投钓得王馀。\n秋光屈指犹三七，莫向宾朋绮宴疏。'},
    {t:'九日杨奉先会白水崔明府',a:'杜甫〔唐代〕',c:'今日潘怀县，同时陆浚仪。\n坐开桑落酒，来把菊花枝。\n天宇清霜净，公堂宿雾披。\n晚酣留客舞，凫舄共差池。'},
    {t:'九日与陆处士羽饮茶',a:'皎然〔唐代〕',c:'九日山僧院，东篱菊也黄。\n俗人多泛酒，谁解助茶香。'},
    {t:'九月八日夜大风雨寄王定国',a:'秦观〔宋代〕',c:'长年身外事都捐，节物惊心一怅然。\n正是山川秋入梦，可堪风雨夜连天。\n桐梢摵摵增凄断，灯烬飞飞落小圆。\n湔洗此情须痛饮，明朝试就酒中仙。'},
    {t:'九月八日游涡',a:'晏殊〔宋代〕',c:'黄花夹径疑无路，红叶临流巧胜春。\n前去重阳犹一日，不辞倾尽蚁醪醇。'},
    {t:'九月九日登龙山',a:'张九龄〔唐代〕',c:'郡庭常窘束，凉野求昭旷。楚客凛秋时，桓公旧台上。\n清明风日好，历落江山望。极远何萧条，中留坐惆怅。\n东弥夏首阔，西拒荆门壮。夷险虽异时，古今岂殊状。\n先贤杳不接，故老犹可访。投吊伤昔人，挥斤感前匠。\n自为本疏散，未始忘幽尚。际会非有欲，往来是无妄。\n为邦复多幸，去国殊迁放。且泛篱下菊，还聆郢中唱。\n灌园亦何为，於陵乃逃相。'},
    {t:'九月九日忆山东兄弟',a:'王维〔唐代〕',c:'独在异乡为异客，每逢佳节倍思亲。\n遥知兄弟登高处，遍插茱萸少一人。'},
    {t:'九月十日',a:'皎然〔唐代〕',c:'爱杀柴桑隐，名溪近讼庭。扫沙开野步，摇舸出闲汀。\n宿简邀诗伴，馀花在酒瓶。悠然南望意，自有岘山情。'},
    {t:'九月十日即事',a:'李白〔唐代〕',c:'昨日登高罢，今朝更举觞。\n菊花何太苦，遭此两重阳？'},
    {t:'九月一日夜读诗稿有感走笔作歌',a:'陆游〔宋代〕',c:'我昔学诗未有得，残余未免从名乞。\n力孱气馁心自知，妄取虚名有惭色。\n四十从戎驻南郑，酣步军中夜连日。\n打球筑场一千步，阅马列厩三万匹。\n华灯纵博声满楼，宝钗艳舞光照席。\n琵琶弦急冰雹乱，羯鼓手匀风雨疾。\n诗家三昧忽见前，屈贾在眼元历历。\n天机云锦用在我，翦裁妙处非刀尺。\n世间才杰固不乏，秋毫未合天地隔。\n放翁老死何足论，广陵散绝还堪惜。'},
    {t:'久别离',a:'李白〔唐代〕',c:'别来几春未还家，玉窗五见樱桃花。\n况有锦字书，开缄使人嗟。\n至此肠断彼心绝。\n云鬟绿鬓罢梳结，愁如回飙乱白雪。\n去年寄书报阳台，今年寄书重相催。\n东风兮东风，为我吹行云使西来。\n待来竟不来，落花寂寂委青苔。'},
    {t:'久病小愈，雨中端午试笔四首',a:'杨万里〔宋代〕',c:'月季元来插得成，瓶中花落叶犹青。\n试将插向苍苔砌，小朵忽开双眼明。'},
    {t:'酒罢张大彻索赠诗',a:'李贺〔唐代〕',c:'长鬣张郎三十八，天遣裁诗花秉骨。\n往还谁是龙头人，公主遣秉鱼须笏。\n太行青草上白衫，匣有章奏密如蚕。\n金门石阁知卿有，豸角鸡香早晚含。\n陇西长吉摧颓客，酒阑感觉有区窄。\n葛衣断碎赵城秋，吟诗一夜东方白。'},
    {t:'酒德',a:'孟郊〔唐代〕',c:'酒是古明镜，辗开小人心。醉见异举止，醉闻异声音。\n酒功如此多，酒屈亦以深。罪人免罪酒，如此可为箴。'},
    {t:'酒泉太守席上醉后作',a:'岑参〔唐代〕',c:'酒泉太守能剑舞，高堂置酒夜击鼓。\n胡笳一曲断人肠，座上相看泪如雨。\n琵琶长笛曲相和，羌儿胡雏齐唱歌。\n浑炙犁牛烹野驼，交河美酒归叵罗。\n三更醉后军中寝，无奈秦山归梦何。'},
    {t:'酒泉子·楚女不归',a:'温庭筠〔唐代〕',c:'楚女不归，楼枕小河春水。月孤明，风又起，杏花稀。\n玉钗斜篸云鬟重，裙上金缕凤。八行书，千里梦，雁南飞。'},
    {t:'酒泉子·春色初来',a:'晏殊〔宋代〕',c:'春色初来，遍拆红芳千万树。流惜粉蝶斗翻飞，恋香枝。\n劝君莫惜缕金衣。把酒看花须强饮，明朝后日渐离披，惜芳时。'},
    {t:'酒泉子·罗带惹香',a:'温庭筠〔唐代〕',c:'罗带惹香，犹系别时红豆。泪痕雕，金缕旧，断离肠。\n一双娇燕语雕梁，还是去年时节。绿杨浓，芳草歇，柳花狂。'},
    {t:'酒泉子·日映纱窗',a:'温庭筠〔唐代〕',c:'日映纱窗，金鸭小屏山碧。故乡春，烟霭隔，背兰釭。\n宿妆惆怅倚高阁，千里云影薄。草初齐，花又落，燕双飞。'},
    {t:'酒泉子·三月暖风',a:'晏殊〔宋代〕',c:'三月暖风，开却好花无限了。当年丛下落纷纷。最愁人。\n长安多少利名身。若有一杯香桂酒，莫辞花下醉芳茵，且留春。'},
    {t:'酒泉子·无题',a:'辛弃疾〔宋代〕',c:'流水无情，潮到空城头尽白。离歌一曲怨残阳，断人肠。\n东风官柳舞雕墙。三十六宫花溅泪，春声何处说兴亡，燕双双。'},
    {t:'酒泉子·谢却荼蘼',a:'纳兰性德〔清代〕',c:'谢却荼蘼，一片月明如水。篆香消，犹未睡，早鸦啼。\n嫩寒无赖罗衣薄，休傍阑干角。最愁人，灯欲落，雁还飞。'},
    {t:'酒肆行',a:'韦应物〔唐代〕',c:'豪家沽酒长安陌，一旦起楼高百尺。碧疏玲珑含春风，\n银题彩帜邀上客。回瞻丹凤阙，直视乐游苑。\n四方称赏名已高，五陵车马无近远。晴景悠扬三月天，\n桃花飘俎柳垂筵。繁丝急管一时合，他垆邻肆何寂然。\n主人无厌且专利，百斛须臾一壶费。初醲后薄为大偷，\n饮者知名不知味。深门潜酝客来稀，终岁醇醲味不移。\n长安酒徒空扰扰，路傍过去那得知。'},
    {t:'旧宫人',a:'张籍〔唐代〕',c:'歌舞梁州女，归时白发生。全家没蕃地，无处问乡程。\n宫锦不传样，御香空记名。一身难自说，愁逐路人行。'},
    {t:'旧将军',a:'李商隐〔唐代〕',c:'云台高议正纷纷，谁定当时荡寇勋。\n日暮灞陵原上猎，李将军是故将军。'},
    {t:'旧游',a:'杜牧〔唐代〕',c:'闲吟芍药诗，惆望久嚬眉。盼眄回眸远，纤衫整髻迟。\n重寻春昼梦，笑把浅花枝。小市长陵住，非郎谁得知。'},
    {t:'就道士问周易参同契',a:'王昌龄〔唐代〕',c:'仙人骑白鹿，发短耳何长。\n时余经菖蒲，忽见嵩之阳。\n稽首求丹经，乃出怀中方。\n披读了不悟，归来问嵇康。\n嗟余无道骨，发我入太行。'},
    {t:'居延海树闻莺同作',a:'陈子昂〔唐代〕',c:'边池无芳树。\n莺声忽听新。\n间关如有意。\n愁绝若怀人。\n明妃失汉宠。\n蔡女没胡尘。\n坐闻应落泪。\n况忆故园春。'},
    {t:'鞠歌行',a:'李白〔唐代〕',c:'玉不自言如桃李，鱼目笑之卞和耻。\n楚国青蝇何太多，连城白璧遭谗毁。\n荆山长号泣血人，忠臣死为刖足鬼。\n听曲知甯戚，夷吾因小妻。\n秦穆五羊皮，买死百里奚。\n洗拂青云上，当时贱如泥。\n朝歌鼓刀叟，虎变磻溪中。\n一举钓六合，遂荒营丘东。\n平生渭水曲，谁识此老翁。\n奈何今之人，双目送飞鸿。'},
    {t:'菊花',a:'李商隐〔唐代〕',c:'暗暗淡淡紫，融融冶冶黄。\n陶令篱边色，罗含宅里香。\n几时禁重露，实是怯残阳。\n愿泛金鹦鹉，升君白玉堂。'},
    {t:'菊花',a:'元稹〔唐代〕',c:'秋丛绕舍似陶家，遍绕篱边日渐斜。\n不是花中偏爱菊，此花开尽更无花。'},
    {t:'菊花新·用韵送张见阳令江华',a:'纳兰性德〔清代〕',c:'愁绝行人天易暮，行向鹧鸪声里住。渺渺洞庭波，木叶下，楚天何处。\n折残杨柳应无数，趁离亭笛声吹度。有几个征鸿，相伴也，送君南去。'},
    {t:'菊花新·欲掩香帏论缱绻',a:'柳永〔宋代〕',c:'欲掩香帏论缱绻。先敛双蛾愁图短。催促少年郎，先去睡、鸳衾图暖。\n须臾放了残针线。脱罗裳、恣情无限。留取帐前灯，时时待、看伊娇面。'},
    {t:'橘柚垂华实',a:'佚名〔两汉〕',c:'橘柚垂华实，乃在深山侧。\n闻君好我甘，窃独自雕饰。\n委身玉盘中，历年冀见食。\n芳菲不相投，青黄忽改色。\n人倘欲我知，因君为羽翼。'},
    {t:'句',a:'晏殊〔宋代〕',c:'琼字金扉迥倚天，南齐七志罕遗逸，\n西汉九流咸粲然。'},
    {t:'句',a:'孟浩然〔唐代〕',c:'微云淡河汉，疏雨滴梧桐。\n逐逐怀良驭，萧萧顾乐鸣。'},
    {t:'钜鹿赠李少府',a:'高适〔唐代〕',c:'李侯虽薄宦，时誉何籍籍。骏马常借人，黄金每留客。\n投壶华馆静，纵酒凉风夕。即此遇神仙，吾欣知损益。'},
    {t:'聚蚊谣',a:'刘禹锡〔唐代〕',c:'沉沉夏夜兰堂开，飞蚊伺暗声自雷。\n嘈然歘起初骇听，殷殷若自南山来。\n喧腾鼓舞喜昏黑，昧天不分聪天惑。\n露华滴沥月上天，利觜迎人看不得。\n我躯七尺尔自芒，我孤尔众能我伤。\n天生有时不可遏，为尔设幄潜匡床。\n清商一来秋日晓，羞尔微形饲丹鸟。'},
    {t:'倦夜',a:'苏轼〔宋代〕',c:'倦枕厌长夜，小窗终未明。\n孤村一犬吠，残月几人行。\n衰鬓久已白，旅怀空自清。\n荒园有络纬，虚织竟何成。'},
    {t:'倦夜',a:'杜甫〔唐代〕',c:'竹凉侵卧内，野月满庭隅。\n重露成涓滴，稀星乍有无。\n暗飞萤自照，水宿鸟相呼。\n万事干戈里，空悲清夜徂。'},
    {t:'觉衰',a:'柳宗元〔唐代〕',c:'久知老会至，不谓便见侵。\n今年宜未衰，稍已来相寻。\n齿疏发就种，奔走力不任。\n咄此可奈何，未必伤我心。\n彭聃安在哉？周孔亦已沉。\n古称寿圣人，曾不留至今。\n但愿得美酒，朋友常共斟。\n是时春向暮，桃李生繁阴。\n日照天正绿，杳杳归鸿吟。\n出门呼所亲，扶杖登西林。\n高歌足自快，商颂有遗音。'},
    {t:'绝句',a:'佚名',c:'飞云倚岫心常在，明月沉潭影不流。\n明月有情应识我，年年相见在他乡。'},
    {t:'绝句',a:'黄庭坚〔宋代〕',c:'花气薰人欲破禅，心情其实过中年。\n春来诗思何所似，八节滩头上水船。'},
    {t:'绝句',a:'杜甫〔唐代〕',c:'两个黄鹂鸣翠柳，一行白鹭上青天。\n窗含西岭千秋雪，门泊东吴万里船。'},
    {t:'绝句二首',a:'杜甫〔唐代〕',c:'迟日江山丽，春风花草香。\n泥融飞燕子，沙暖睡鸳鸯。\n江碧鸟逾白，山青花欲燃。\n今春看又过，何日是归年。'},
    {t:'绝句二首·其二',a:'杜甫〔唐代〕',c:'江碧鸟逾白，山青花欲燃。\n今春看又过，何日是归年？'},
    {t:'绝句漫兴九首·其二',a:'杜甫〔唐代〕',c:'手种桃李非无主，野老墙低还似家。\n恰似春风相欺得，夜来吹折数枝花。'},
    {t:'绝句漫兴九首·其九',a:'杜甫〔唐代〕',c:'隔户杨柳弱袅袅，恰似十五女儿腰。\n谁谓朝来不作意，狂风挽断最长条。'},
    {t:'绝句漫兴九首·其七',a:'杜甫〔唐代〕',c:'糁径杨花铺白毡，点溪荷叶叠青钱。\n笋根雉子无人见，沙上凫雏傍母眠。'},
    {t:'绝句漫兴九首·其三',a:'杜甫〔唐代〕',c:'熟知茅斋绝低小，江上燕子故来频。\n衔泥点污琴书内，更接飞虫打着人。'},
    {t:'绝句漫兴九首·其四',a:'杜甫〔唐代〕',c:'二月已破三月来，渐老逢春能几回。\n莫思身外无穷事，且尽生前有限杯。'},
    {t:'绝句漫兴九首·其五',a:'杜甫〔唐代〕',c:'肠断江春欲尽头，杖藜徐步立芳洲。\n颠狂柳絮随风舞，轻薄桃花逐水流。'},
    {t:'绝句四首',a:'杜甫〔唐代〕',c:'堂西长笋别开门，堑北行椒却背村。\n梅熟许同朱老吃，松高拟对阮生论。\n欲作鱼梁云复湍，因惊四月雨声寒。\n青溪先有蛟龙窟，竹石如山不敢安。\n两个黄鹂鸣翠柳，一行白鹭上青天。\n窗含西岭千秋雪，门泊东吴万里船。\n药条药甲润青青，色过棕亭入草亭。\n苗满空山惭取誉，根居隙地怯成形。'},
    {t:'绝句四首·其二',a:'杜甫〔唐代〕',c:'欲作鱼梁云复湍，因惊四月雨声寒。\n青溪先有蛟龙窟，竹石如山不敢安。'},
    {t:'绝句四首·其四',a:'杜甫〔唐代〕',c:'药条药甲润青青，色过棕亭入草亭。\n苗满空山惭取誉，根居隙地怯成形。'},
    {t:'君马黄',a:'李白〔唐代〕',c:'君马黄，我马白。\n马色虽不同，人心本无隔。\n共作游冶盘，双行洛阳陌。\n长剑既照曜，高冠何赩赫。\n各有千金裘，俱为五侯客。\n猛虎落陷阱，壮夫时屈厄。\n相知在急难，独好亦何益。'},
    {t:'君难托',a:'王安石〔宋代〕',c:'槿花朝开暮还坠，妾身与花宁独异。\n忆昔相逢俱少年，两情未许谁最先。\n感君绸缪逐君去，成君家计良辛苦。\n人事反覆那能知？谗言入耳须臾离。\n嫁时罗衣羞更著，如今始悟君难托。\n君难托，妾亦不忘旧时约。'},
    {t:'君山怀古',a:'刘禹锡〔唐代〕',c:'属车八十一，此地阻长风。千载威灵尽，赭山寒水中。'},
    {t:'君子法天运',a:'韩愈〔唐代〕',c:'君子法天运，四时可前知。\n小人惟所遇，寒暑不可期。\n利害有常势，取舍无定姿。\n焉能使我心，皎皎远忧疑。'},
    {t:'君子行',a:'佚名〔魏晋〕',c:'君子防未然，不处嫌疑间。\n瓜田不纳履，李下不正冠。\n嫂叔不亲授，长幼不比肩。\n劳谦得其柄，和光甚独难。\n周公下白屋，吐哺不及餐。\n一沐三握发，后世称圣贤。'},
    {t:'钧天',a:'李商隐〔唐代〕',c:'上帝钧天会众灵，昔人因梦到青冥。\n伶伦吹裂孤生竹，却为知音不得听。'},
    {t:'郡江南上别孙侍御',a:'张九龄〔唐代〕',c:'云嶂天涯尽，川途海县穷。何言此地僻，忽与故人同。\n身负邦君弩，情纡御史骢。王程不我驻，离思逐秋风。'},
    {t:'郡内书情献裴侍中留守',a:'刘禹锡〔唐代〕',c:'功成频献乞身章，摆落襄阳镇洛阳。\n万乘旌旗分一半，八方风雨会中央。\n兵符今奉黄公略，书殿曾随翠凤翔。\n心寄华亭一双鹤，日陪高步绕池塘。'},
    {t:'郡内闲居',a:'韦应物〔唐代〕',c:'栖息绝尘侣，孱钝得自怡。腰悬竹使符，心与庐山缁。\n永日一酣寝，起坐兀无思。长廊独看雨，众药发幽姿。\n今夕已云罢，明晨复如斯。何事能为累，宠辱岂要辞。'},
    {t:'郡内闲斋',a:'张九龄〔唐代〕',c:'郡阁昼常掩，庭芜日复滋。檐风落鸟毳，窗叶挂虫丝。\n拙病宦情少，羁闲秋气悲。理人无异绩，为郡但经时。\n唯有江湖意，沉冥空在兹。'},
    {t:'郡舍南有园畦杂树聊以永日',a:'张九龄〔唐代〕',c:'为郡久无补，越乡空复深。苟能秉素节，安用叨华簪。\n却步园畦里，追吾野逸心。形骸拘俗吏，光景赖闲林。\n内讼诚知止，外言犹匪忱。成蹊谢李径，卫足感葵阴。\n荣达岂不伟，孤生非所任。江城何寂历，秋树亦萧森。\n下有北流水，上有南飞禽。我愿从归翼，无然坐自沉。'},
    {t:'郡斋即事',a:'范仲淹〔宋代〕',c:'三出专城鬓似丝，斋中萧洒胜禅师。\n近疏歌酒缘多病，不负云山赖有诗。\n半雨黄花秋赏健，一江明月夜归迟。\n世间荣辱何须道，塞上衰翁也自知。'},
    {t:'郡斋南池招杨辚',a:'岑参〔唐代〕',c:'郡僻人事少，云山常眼前。\n偶从池上醉，便向舟中眠。\n与子居最近，周官情又偏。\n闲时耐相访，正有床头钱。'},
    {t:'郡斋平望江山',a:'岑参〔唐代〕',c:'水路东连楚，人烟北接巴。山光围一郡，江月照千家。\n庭树纯栽橘，园畦半种茶。梦魂知忆处，无夜不京华。'},
    {t:'郡斋秋夜即事寄斛斯处士许秀才',a:'杜牧〔唐代〕',c:'有客谁人肯夜过？独怜风景奈愁何。\n边鸿怨处迷霜久，庭树空来见月多。\n故国杳无千里信，彩弦时伴一声歌。\n驰心只待城乌晓，几对虚檐望白河。'},
    {t:'郡斋卧疾绝句',a:'韦应物〔唐代〕',c:'香炉宿火灭，兰灯宵影微。\n秋斋独卧病，谁与覆寒衣。'},
    {t:'郡斋雨中与诸文士燕集',a:'韦应物〔唐代〕',c:'兵卫森画戟，宴寝凝清香。\n海上风雨至，逍遥池阁凉。\n烦疴近消散，嘉宾复满堂。\n自惭居处崇，未睹斯民康。\n理会是非遣，性达形迹忘。\n鲜肥属时禁，蔬果幸见尝。\n俯饮一杯酒，仰聆金玉章。\n神欢体自轻，意欲凌风翔。\n吴中盛文史，群彦今汪洋。\n方知大藩地，岂曰财赋强。'},
    {t:'郡中西斋',a:'韦应物〔唐代〕',c:'似与尘境绝，萧条斋舍秋。\n寒花独经雨，山禽时到州。\n清觞养真气，玉书示道流。\n岂将符守恋，幸已栖心幽。'},
    {t:'开愁歌',a:'李贺〔唐代〕',c:'秋风吹地百草干，华容碧影生谢寒。\n我当二十不得意，一心愁谢如枯兰。\n衣如飞鹑马如狗，临衣击剑生铜吼。\n旗亭下马解秋衣，请贳宜阳一壶酒。\n壶中唤天云不开，白昼万里闲凄迷。\n主人劝我养心骨，莫受俗物相填豗。'},
    {t:'开圣寺',a:'温庭筠〔唐代〕',c:'路分谿石夹烟丛，十里萧萧古乱风。\n出寺马嘶秋色里，向陵鸦乱夕阳中。\n竹间泉落山厨静，塔下僧归影殿空。\n犹有南朝旧碑在，耻将兴废问休公。'},
    {t:'看花',a:'元稹〔唐代〕',c:'努力少年求好官，好花须是少年看。\n君看老大逢花树，未折一枝心已阑。'},
    {t:'看花回',a:'周邦彦〔宋代〕',c:'蕙风初散轻暖，霁景微澄洁。秀纡乍开乍敛，带雨态烟痕，春思纡结。危弦弄响，来去惊人莺语思。无赖处，丽日楼台，乱纷岐路思奇绝。\n何计解、黏花系月叹冷落、顿辜佳节。犹有当时气味，挂一缕相思，不断如发。云飞帝国，人在天边心暗折。语东风，共流转，谩作匆匆别。'},
    {t:'看花回·茶词',a:'黄庭坚〔宋代〕',c:'夜永兰堂醺饮，半倚颓玉。烂熳坠钿堕履，是醉时风景，花暗烛残，欢意未阑，舞燕歌珠成断续。催茗饮、旋煮寒泉，露井瓶窦响飞瀑。\n纤指缓、连环动触。渐泛起、满瓯银粟。香引春风在手，似粤岭闽溪，初采盈掬。暗想当时，探春连云寻篁竹。怎归得，鬓将老，付与杯中绿。'},
    {t:'看花回·屈指劳生百岁期',a:'柳永〔宋代〕',c:'屈指劳生百岁期。荣瘁相随。利牵名惹逡巡过，奈两轮、玉走金飞。红颜成白发，极品何为。\n尘事常多雅会稀。忍不开眉。画堂歌管深深处，难忘酒盏花枝。醉乡风景好，携手同归。'},
    {t:'看花回·秀色芳容明眸',a:'周邦彦〔宋代〕',c:'秀色芳容明眸，就中奇绝。细看艳波欲溜，最可惜、微重重红绡轻帖。匀朱傅粉，几为严妆时涴睫。因个甚、底死嗔人，半饷斜眄费贴燮。\n斗帐里、浓欢意惬。带困眼、似开微合。曾倚高楼望远，似指笑频目闰，知他谁说。那日分飞，泪雨纵横光映颊。揾香罗，恐揉损，与他衫袖裛。'},
    {t:'看花回·玉墄金阶舞舜干',a:'柳永〔宋代〕',c:'玉墄金阶舞舜干。朝野多欢。九弦三市风光丽，正万家、急管繁弦。凤楼临绮陌，嘉气非烟。\n雅俗熙熙物态妍。忍负芳年。笑筵歌席连昏昼，任旗亭、斗酒十千。赏心何处好，惟有尊前。'},
    {t:'看梅绝句',a:'陆游〔宋代〕',c:'老子舞时不须拍，梅花乱插乌巾香。\n樽前作剧莫相笑，我死诸君思此狂。'},
    {t:'康录事宅送僧联句',a:'皎然〔唐代〕',c:'莲衣宜著雨，竹锡好随云。——皎然\n见鹤还应养，逢鸥自作群。——崔子向'},
    {t:'可叹',a:'李商隐〔唐代〕',c:'幸会东城宴未回，年华忧共水中催。\n梁家宅里秦宫入，赵后楼中赤凤来。\n冰簟且眠金镂枕，琼筵不醉玉交杯。\n宓妃愁坐芝田馆，用尽陈王八斗才。'},
    {t:'克己',a:'朱熹〔宋代〕',c:'宝鉴当年照胆寒，向来埋没太无端。祇今垢尽明全见，还得当年宝鉴看。'},
    {t:'客从',a:'杜甫〔唐代〕',c:'客从南溟来，遗我泉客珠。\n珠中有隐字，欲辨不成书。\n缄之箧笥久，以俟公家须。\n开视化为血，哀今征敛无！'},
    {t:'客从远方来',a:'佚名〔两汉〕',c:'客从远方来，遗我一端绮。\n相去鸯余里，故人心尚尔。\n文采双鸳鸯，裁为合欢被。\n著以长相思，缘以结不解。\n以胶投漆中，谁能别离此？'},
    {t:'客广陵',a:'王昌龄〔唐代〕',c:'楼头广陵近，九月在南徐。\n秋色明海县，寒烟生里闾。\n夜帆归楚客，昨日度江书。\n为问易名叟，垂纶不见鱼。'},
    {t:'客亭',a:'杜甫〔唐代〕',c:'秋窗犹曙色，落木更天风。\n日出寒山外，江流宿雾中。\n圣朝无弃物，老病已成翁。\n多少残生事，飘零任转蓬。'},
    {t:'客夜',a:'杜甫〔唐代〕',c:'客睡何曾著，秋天不肯明。\n卷帘残月影，高枕远江声。\n计拙无衣食，途穷仗友生。\n老妻书数纸，应悉未归情。'},
    {t:'客游',a:'李贺〔唐代〕',c:'悲满千里心，日暖南山石。\n不谒承明庐，老作平原客。\n四时别家庙，三年去乡国。\n旅歌屡弹铗，归问时裂帛。'},
    {t:'客至',a:'杜甫〔唐代〕',c:'舍南舍北皆春水，但见群鸥日日来。\n花径不曾缘客扫，蓬门今始为君开。\n盘飧市远无兼味，樽酒家贫只旧醅。\n肯与邻翁相对饮，隔篱呼取尽余杯。'},
    {t:'客中守岁',a:'白居易〔唐代〕',c:'守岁尊无酒，思乡泪满巾。\n始知为客苦，不及在家贫。\n畏老偏惊节，防愁预恶春。\n故园今夜里，应念未归人。'},
    {t:'客中作',a:'李白〔唐代〕',c:'兰陵美酒郁金香，玉碗盛来琥珀光。\n但使主人能醉客，不知何处是他乡。'},
    {t:'空囊',a:'杜甫〔唐代〕',c:'翠柏苦犹食，晨霞高可餐。\n世人共卤莽，吾道属艰难。\n不爨井晨冻，无衣床夜寒。\n囊空恐羞涩，留得一钱看。'},
    {t:'空屋题·十月十四日夜',a:'元稹〔唐代〕',c:'朝从空屋里，骑马入空台。尽日推闲事，还归空屋来。\n月明穿暗隙，灯烬落残灰。更想咸阳道，魂车昨夜回。'},
    {t:'箜篌谣',a:'李白〔唐代〕',c:'攀天莫登龙，走山莫骑虎。\n贵贱结交心不移，唯有严陵及光武。\n周公称大圣，管蔡宁相容。\n汉谣一斗粟，不与淮南舂。\n兄弟尚路人，吾心安所从。\n他人方寸间，山海几千重。\n轻言托朋友，对面九疑峰。\n开花必早落，桃李不如松。\n管鲍久已死，何人继其踪。'},
    {t:'箜篌谣',a:'佚名〔两汉〕',c:'结交在相知，骨肉何必亲。\n甘言无忠实，世薄多苏秦。\n从风暂靡草，富贵上升天。\n不见山巅树，摧杌下为薪。\n岂甘井中泥？上出作埃尘。'},
    {t:'口号吴王美人半醉',a:'李白〔唐代〕',c:'风动荷花水殿香，姑苏台上宴吴王。\n西施醉舞娇无力，笑倚东窗白玉床。'},
    {t:'枯树',a:'韩愈〔唐代〕',c:'老树无枝叶，风霜不复侵。腹穿人可过，皮剥蚁还寻。\n寄托惟朝菌，依投绝暮禽。犹堪持改火，未肯但空心。'},
    {t:'枯鱼过河泣',a:'李白〔唐代〕',c:'白龙改常服，偶被豫且制。\n谁使鲵为鱼，徒劳诉天帝。\n作书报鲸鲵，勿恃风涛势。\n涛落归泥沙，翻遭蝼蚁噬。\n万乘慎出入，柏人以为识。'},
    {t:'枯鱼过河泣',a:'佚名〔两汉〕',c:'枯鱼过河泣，何时悔复及。\n作书与鲂鱮，相教慎出入。'},
    {t:'哭晁卿衡',a:'李白〔唐代〕',c:'日本晁卿辞帝都，征帆一片绕蓬壶。\n明月不归沉碧海，白云愁色满苍梧。'},
    {t:'哭褚司马',a:'王维〔唐代〕',c:'妄识皆心累，浮生定死媒。\n谁言老龙吉，未免伯牛灾。\n故有求仙药，仍馀遁俗怀。\n山川秋树苦，窗户夜泉哀。\n尚忆青骡去，宁知白马来。\n汉臣修史记，莫蔽褚生才。'},
    {t:'哭单父梁九少府',a:'高适〔唐代〕',c:'开箧泪沾臆，见君前日书。\n夜台今寂寞，犹是子云居。\n畴昔贪灵奇，登临赋山水。\n同舟南浦下，望月西江里。\n契阔多离别，绸缪到生死。\n九原即何处，万事皆如此。\n晋山徒嵯峨，斯人已冥冥。\n常时禄且薄，殁后家复贫。\n妻子在远道，弟兄无一人！\n十上多苦辛，一官常自哂。\n青云将可致，白日忽先尽。\n唯有身后名，空留无远近。'},
    {t:'哭韩绰',a:'杜牧〔唐代〕',c:'平明送葬上都门，绋翣交横逐去魂。\n归来冷笑悲身事，唤妇呼儿索酒盆。'},
    {t:'哭觉上人·时绊剡中',a:'皎然〔唐代〕',c:'忆君南适越，不作买山期。昨得耶溪信，翻为逝水悲。\n神交如可见，生尽杳难思。白日东林下，空怀步影时。'},
    {t:'哭刘蕡',a:'李商隐〔唐代〕',c:'上帝深宫闭九阍，巫咸不下问衔冤。\n黄陵别后春涛隔，湓浦书来秋雨翻。\n只有安仁能作诔，何曾宋玉解招魂？\n平生风义兼师友，不敢同君哭寝门。'},
    {t:'哭刘尚书梦得二首',a:'白居易〔唐代〕',c:'四海齐名白与刘，百年交分两绸缪。\n同贫同病退闲日，一死一生临老头。\n杯酒英雄君与操，文章微婉我知丘。\n贤豪虽殁精灵在，应共微之地下游。\n今日哭君吾道孤，寝门泪满白髭须。\n不知箭折弓何用？兼恐唇亡齿亦枯！\n窅窅穷泉埋宝玉，骎骎落景挂桑榆。\n夜台暮齿期非远，但问前头相见无。'},
    {t:'哭刘司户蕡',a:'李商隐〔唐代〕',c:'路有论冤谪，言皆在中兴。\n空闻迁贾谊，不待相孙弘。\n江阔惟回首，天高但抚膺。\n去年相送地，春雪满黄陵。'},
    {t:'哭孟浩然',a:'王维〔唐代〕',c:'故人不可见，汉水日东流。\n借问襄阳老，江山空蔡州。'},
    {t:'哭孟寂',a:'张籍〔唐代〕',c:'曲江院里题名处，十九人中最少年。\n今日春光君不见，杏花零落寺门前。'},
    {t:'哭秘书彭止所',a:'文天祥〔宋代〕',c:'人物孤中秘，神山返异仙。\n目穿陪绋处，梦断曝书年。\n玉质应无死，韦编岂不传。\n奠刍和泪遣，此月向谁圆。'},
    {t:'哭女樊',a:'元稹〔唐代〕',c:'秋天净绿月分明，何事巴猿不賸鸣。\n应是一声肠断去，不容啼到第三声。'},
    {t:'哭裴少府',a:'高适〔唐代〕',c:'世人谁不死，嗟君非生虑。扶病适到官，田园在何处。\n公才群吏感，葬事他人助。余亦未识君，深悲哭君去。'},
    {t:'哭山中友人',a:'张籍〔唐代〕',c:'入云遥便哭，山友隔今生。绕墓招魂魄，镌岩记姓名。\n犬因无主善，鹤为见人鸣。长说能尸解，多应别路行。'},
    {t:'哭小女降真',a:'元稹〔唐代〕',c:'雨点轻沤风复惊，偶来何事去何情。\n浮生未到无生地，暂到人间又一生。'},
    {t:'哭崖山',a:'文天祥〔宋代〕',c:'宝藏如山席六宗，楼船千叠水亡宫。\n吴儿进退寻常事，汉氏存亡顷刻中。\n诸老丹心付流水，孤臣血泪洒南风。\n早来朝市今何处，如悟人间万法空。'},
    {t:'哭殷遥',a:'王维〔唐代〕',c:'人生能几何，毕竟归无形。\n念君等为死，万事伤人情。\n慈母未及葬，一女才十龄。\n泱漭寒郊外，萧条闻哭声。\n浮云为苍茫，飞鸟不能鸣。\n行人何寂寞，白日自凄清。\n忆昔君在时，问我学无生。\n劝君苦不早，令君无所成。\n故人各有赠，又不及生平。\n负尔非一途，恸哭返柴荆。'},
    {t:'哭于鹄',a:'张籍〔唐代〕',c:'青山无逸人，忽觉大国贫。良玉沉幽泉，名为天下珍。\n野性疏时俗，再拜乃从军。气高终不合，去如镜上尘。\n我初有章句，相合者唯君。今来吊嗣子，对陇烧新文。\n耕者废其耜，爨者绝其薪。苟无新衣裳，曷用光我身。\n奠酒徒拜手，哀怀安能陈。徒保金石韵，千载人所闻。'},
    {t:'苦寒吟',a:'孟郊〔唐代〕',c:'天寒色青苍，北风叫枯桑。\n厚冰无裂文，短日有冷光。\n敲石不得火，壮阴夺正阳。\n调苦竟何言，冻吟成此章。'},
    {t:'苦篁调啸引',a:'李贺〔唐代〕',c:'请说轩辕在时事，伶伦采竹二十四。伶伦采之自昆丘，\n轩辕诏遣中分作十二。伶伦以之正音律，轩辕以之调元气。\n当时黄帝上天时，二十三管咸相随，唯留一管人间吹。\n无德不能得此管，此管沉埋虞舜祠。'},
    {t:'苦乐相倚曲',a:'元稹〔唐代〕',c:'古来苦乐之相倚，近于掌上之十指。君心半夜猜恨生，\n荆棘满怀天未明。汉成眼瞥飞燕时，可怜班女恩已衰。\n未有因由相决绝，犹得半年佯暖热。转将深意谕旁人，\n缉缀瑕疵遣潜说。一朝诏下辞金屋，班姬自痛何仓卒。\n呼天抚地将自明，不悟寻时暗销骨。白首宫人前再拜，\n愿将日月相辉解。苦乐相寻昼夜间，灯光那有天明在。\n主今被夺心应苦，妾夺深恩初为主。欲知妾意恨主时，\n主今为妾思量取。班姬收泪抱妾身，我曾排摈无限人。'},
    {t:'苦楝花',a:'温庭筠〔唐代〕',c:'院里莺歌歇，墙头蝶舞孤。\n天香薰羽葆，宫紫晕流苏。\n晻暧迷青琐，氤氲向画图。\n只应春惜别，留与博山炉。'},
    {t:'苦热',a:'陆游〔宋代〕',c:'万瓦鳞鳞若火龙，日车不动汗珠融。\n无因羽翮氛埃外，坐觉蒸炊釜甑中。\n石涧寒泉空有梦，冰壶团扇欲无功。\n余威向晚犹堪畏，浴罢斜阳满野红。'},
    {t:'苦热题恒寂师禅室',a:'白居易〔唐代〕',c:'人人避暑走如狂，独有禅师不出房。\n可是禅房无热到，但能心静即身凉。'},
    {t:'苦笋',a:'陆游〔宋代〕',c:'藜藿盘中忽眼明，骈头脱襁白玉婴。\n极知耿介种性别，苦节乃与生俱生。\n我见魏徵殊媚妩，约束儿童勿多取。\n人才自古要养成，放使干霄战风雨。'},
    {t:'苦雪四首',a:'高适〔唐代〕',c:'二月犹北风，天阴雪冥冥。寥落此室中，怅然惭百龄。\n苦愁正如此，门柳复青青。\n惠连发清兴，袁懒念高卧。余故非斯人，为性兼懒惰。\n赖兹尊中酒，终日聊自过。\n濛濛洒平陆，淅沥至幽居。且喜润群物，焉能悲斗储。\n故交久不见，鸟雀投吾庐。\n孰云久闲旷，本自保知寡。穷巷独无成，春条只盈把。\n懒能羡鹏举，且欲歌牛下。乃知古时人，亦有如我者。'},
    {t:'苦雪四首·其二',a:'高适〔唐代〕',c:'惠连发清兴，袁安念高卧。\n余故非斯人，为性兼懒惰。\n赖兹尊中酒，终日聊自过。'},
    {t:'苦雪四首·其三',a:'高适〔唐代〕',c:'濛濛洒平陆，淅沥至幽居。\n且喜润群物，焉能悲斗储。\n故交久不见，鸟雀投吾庐。'},
    {t:'苦雪四首·其四',a:'高适〔唐代〕',c:'孰云久闲旷，本自保知寡。\n穷巷独无成，春条只盈把。\n安能羡鹏举，且欲歌牛下。\n乃知古时人，亦有如我者。'},
    {t:'苦昼短',a:'李贺〔唐代〕',c:'飞光飞光，劝尔一杯酒。\n吾不识青天高，黄地厚。\n唯见月寒日暖，来煎人寿。\n食熊则肥，食蛙则瘦。\n神君何在？太一安有？\n天东有若木，下置衔烛龙。\n吾将斩龙足，嚼龙肉，使之朝不得回，夜不得伏。\n自然老者不死，少者不哭。\n何为服黄金、吞白玉？\n谁似任公子，云中骑碧驴？\n刘彻茂陵多滞骨，嬴政梓棺费鲍鱼。'},
    {t:'夸父逐日',a:'佚名〔先秦〕',c:'夸父与日逐走，入日；渴，欲得饮，饮于河、渭；河、渭不足，北饮大泽。未至，道渴而死。弃其杖，化为邓林。'},
    {t:'狂夫',a:'杜甫〔唐代〕',c:'万里桥西一草堂，百花潭水即沧浪。\n风含翠篠娟娟净，雨裛红蕖冉冉香。\n厚禄故人书断绝，恒饥稚子色凄凉。\n欲填沟壑唯疏放，自笑狂夫老更狂。'},
    {t:'昆仑儿',a:'张籍〔唐代〕',c:'昆仑家住海中州，蛮客将来汉过游。\n言语解教秦吉了，波涛初过郁林洲。\n金环欲落曾穿耳，螺髻长卷不裹头。\n自爱肌肤黑如漆，行时半脱木绵裘。'},
    {t:'昆仑使者',a:'李贺〔唐代〕',c:'昆仑使者无消息，茂陵烟树生愁色。\n金盘玉露自淋漓，元气茫茫收不得。\n麒麟背上石文裂，虬龙鳞下红枝折。\n何处偏伤万国心，中天夜久高明月。'},
    {t:'昆崙使者',a:'李贺〔唐代〕',c:'昆崙使者无消息，茂陵烟树生愁色。金盘玉露自淋漓，元气茫茫收不得。\n麒麟背上石文裂，虬龙鳞下红枝折。何处偏伤万国心，中天夜久高明月。'},
    {t:'昆明池水战词',a:'温庭筠〔唐代〕',c:'汪汪积水光连空，重叠细纹晴盼红。赤帝龙孙鳞甲怒，\n临流一盼生阴风。鼍鼓三声报天子，雕山兽舰凌波起。\n雷吼涛惊白石山，石鲸眼裂蟠蛟死。溟池海浦俱喧豗。\n青帜白山相次来。箭羽枪缨三百万，踏翻西海生尘埃。\n茂陵仙去菱花老，唼唼游鱼近烟岛。渺莽残阳钓艇归，\n绿头江鸭眠沙草。'},
    {t:'困学二首其二',a:'朱熹〔宋代〕',c:'困学工夫岂易成，斯名独恐是虚称。傍人莫笑标题误，庸行庸言实未能。'},
    {t:'困学二首其一',a:'朱熹〔宋代〕',c:'旧喜安心苦觅心，捐书绝学费追寻。困衡此日安无地，始觉从前枉寸阴。'},
    {t:'腊前月季',a:'杨万里〔宋代〕',c:'只道花无十日红，此花无日不包风。\n一尖已剥胭脂笔，四破犹包翡翠茸。\n别有香超桃李外，更同梅斗雪霜中。\n折来喜作新年看，忘却今晨是季冬。'},
    {t:'腊日',a:'杜甫〔唐代〕',c:'腊日常年暖尚遥，今年腊日冻全消。\n侵陵雪色还萱草，漏泄春光有柳条。\n纵酒欲谋良夜醉，还家初散紫宸朝。\n口脂面药随恩泽，翠管银罂下九霄。'},
    {t:'腊日游孤山访惠勤惠思二僧',a:'苏轼〔宋代〕',c:'天欲雪，云满湖，楼台明灭山有无。\n水清出石鱼可数，林深无人鸟相呼。\n腊日不归对妻孥，名寻道人实自娱。\n道人之居在何许？宝云山前路盘纡。\n孤山孤绝谁肯庐？道人有道山不孤。\n纸窗竹屋深自暖，拥褐坐睡依团蒲。\n天寒路远愁仆夫，整驾催归及未晡。\n出山回望云木合，但见野鹘盘浮图。\n兹游淡薄欢有余，到家恍如梦遽遽。\n作诗火急追亡逋，清景一失后难摹。'},
    {t:'腊月',a:'陆游〔宋代〕',c:'今冬少霜雪，腊月厌重裘。\n渐动园林兴，顿宽薪炭忧。\n山陂泉脉活，村市柳枝柔。\n春饼吾何患，嘉蔬日可求。'},
    {t:'腊月八日于剡县石城寺礼拜',a:'孟浩然〔唐代〕',c:'石壁开金像，香山倚铁围。下生弥勒见，回向一心归。\n竹柏禅庭古，楼台世界稀。夕岚增气色，馀照发光辉。\n讲席邀谈柄，泉堂施浴衣。愿承功德水，从此濯尘机。'},
    {t:'蜡梅',a:'杨万里〔宋代〕',c:'天向梅梢别出奇，国香未许世代知。\n殷懃滴蜡缄封却，偷被霜风折一枝。'},
    {t:'蜡日',a:'陶渊明〔魏晋〕',c:'风雪送余运，无妨时已和。\n梅柳夹门植，一条有佳花。\n我唱尔言得，酒中适何多！\n未能明多少，章山有奇歌。'},
    {t:'蜡烛',a:'杨万里〔宋代〕',c:'未夜身先卧，不春花已开。\n泣残双泪雨，愁得寸心灰。'},
    {t:'来闍黎新亭作',a:'孟浩然〔唐代〕',c:'八解禅林秀，三明给苑才。地偏立界远，心净水亭开。\n傍险山查立，寻幽石径回。瑞花长自下，灵绿岂须栽。\n碧网交红树，清泉尽绿苔。戏鱼闻法聚，闲鸟诵经来。\n弃象玄应悟，忘言理必该。静中何所得，吟咏也徒哉。'},
    {t:'来日大难',a:'李白〔唐代〕',c:'来日一身，携粮负薪。\n道长食尽，苦口焦唇。\n今日醉饱，乐过千春。\n仙人相存，诱我远学。\n海凌三山，陆憩五岳。\n乘龙天飞，目瞻两角。\n授以神药，金丹满握。\n蟪蛄蒙恩，深愧短促。\n思填东海，强衔一木。\n道重天地，轩师广成。\n蝉翼九五，以求长生。\n下士大笑，如苍蝇声。'},
    {t:'兰',a:'朱熹〔宋代〕',c:'谩种秋兰四五茎，疏帘底事太关情。\n可能不作凉风计，护得幽兰到晚清。'},
    {t:'兰涧',a:'朱熹〔宋代〕',c:'光风浮碧涧，兰杜日猗猗。\n竟岁无人采，含薰只自知。'},
    {t:'兰陵王·赋一丘一壑',a:'辛弃疾〔宋代〕',c:'一丘壑。老子风流占却。茅檐上、思月桂云，脉脉石泉逗山脚。寻思前事错。恼杀晨猿夜鹤。终须长、邓禹辈人，锦绣麻霞坐黄阁。\n长歌自深酌。看天阔鸢飞，渊静鱼跃。西风黄菊芗喷薄。怅日暮云合，佳人何处，纫兰结佩带杜若。入江海曾约。\n遇合。事难托。莫击磬门前，荷蒉人过，仰天大笑冠簪落。待说与穷达，不须疑著。古来贤者，进亦乐，退亦乐。'},
    {t:'兰陵王·柳',a:'周邦彦〔宋代〕',c:'柳阴直，烟里丝丝弄碧。隋堤上、曾见几番，拂水飘绵送行色。登临望故国，谁识京华倦客？长亭路，年去岁来，应折柔条过千尺。\n闲寻旧踪迹，又酒趁哀弦，灯照离席。梨花榆火催寒食。愁一箭风快，半篙波暖，回头迢递便数驿，望人在天北。\n凄恻，恨堆积！渐别浦萦回，津堠岑寂，斜阳冉冉春无极。念月榭携手，露桥闻笛。沉思前事，似梦里，泪暗滴。'},
    {t:'兰陵王·雨初歇',a:'秦观〔宋代〕',c:'雨初歇。帘卷一钩淡月。望河汉、景点疏星，冉冉纤云度林樾。此景清更绝。谁念温柔蕴结。孤灯沈，独步华堂，蟋蟀莎阶弄时节。\n沈思恨难说。忆花底相逢，亲赠罗缬。春鸿秋雁轻离别。拟寻个锦鳞，寄将尺素，又恐烟波路隔越。歌残唾壶缺。\n凄咽。意空切。但醉损琼卮，望断琼阙。御沟曾解流红叶。待何日重见，霓裳听彻。彩楼天远，夜夜襟袖染啼血。'},
    {t:'兰塘词',a:'温庭筠〔唐代〕',c:'塘水汪汪凫唼喋，忆上江南木绿楫。绣颈金须荡倒光，\n团团皱绿鸡头叶。露凝荷卷珠净圆，紫浅刺短浮根缠。\n小姑归晚红妆浅，镜里芙蓉照水鲜。东沟潏潏劳回首，\n欲寄一杯琼液酒。知道无郎却有情，长教月照相思柳。'},
    {t:'兰溪',a:'杜牧〔唐代〕',c:'兰溪春尽碧泱泱，映水兰花雨发香。\n楚国大夫憔悴日，应寻此路去潇湘。'},
    {t:'兰香神女庙',a:'李贺〔唐代〕',c:'古春年年在，闲绿摇暖云。\n松香飞晚华，柳渚含日昏。\n沙砌落红满，石泉生水芹。\n幽篁画新粉，蛾绿横晓门。\n弱蕙不胜露，山秀愁空春。\n舞珮剪鸾翼，帐带涂轻银。\n兰桂吹浓香，菱藕长莘莘。\n看雨逢瑶姬，乘船值江君。\n吹箫饮酒醉，结绶金丝裙。\n走天呵白鹿，游水鞭锦鳞。\n密发虚鬟飞，腻颊凝花匀。\n团鬓分蛛巢，秾眉笼小唇。\n弄蝶和轻妍，风光怯腰身。\n深帏金鸭冷，奁镜幽凤尘。\n踏雾乘同归，撼玉山上闻。'},
    {t:'蓝桥驿见元九诗',a:'白居易〔唐代〕',c:'蓝桥春雪君归日，秦岭秋风我去时。\n每到驿亭先下马，循墙绕柱觅君诗。'},
    {t:'蓝田山石门精舍',a:'王维〔唐代〕',c:'落日山水好，漾舟信归风。\n玩奇秀觉远，因以缘源穷。\n遥爱云木秀，初疑路秀同。\n安知清流转，偶所前山通。\n舍舟理轻策，果然惬所适。\n老僧四五人，逍遥荫松柏。\n朝梵林未曙，夜禅山更寂。\n道心及牧童，世事问樵客。\n暝宿长林下，焚香卧瑶席。\n涧芳袭人衣，山月映石壁。\n再寻畏迷误，明发更登历。\n笑谢桃源人，花红复来觌。'},
    {t:'览崔爽遗文，因纾幽怀',a:'孟郊〔唐代〕',c:'堕泪数首文，悲结千里坟。苍旻月留我，白日空遗君。\n仙鹤未巢月，衰凤先坠云。清风独起时，旧语如再闻。\n瑶草罢葳蕤，桂花休氛氲。万物与我心，相感吴江濆。'},
    {t:'览古',a:'李商隐〔唐代〕',c:'莫恃金汤忽太平，草间霜露古旗情。\n空糊赪壤真何益，欲举黄旗竟未成。\n长乐瓦飞随水逝，景阳钟堕失天明。\n回头一吊箕山客，始信逃尧不为名。'},
    {t:'览镜见须髯消落为之流涕',a:'文天祥〔宋代〕',c:'万里飘零等一毫，满前风影恨滔滔。\n泪如杜宇喉中血，须似苏郎节上旄。\n今日形骸迟一死，向来事业竟徒劳。\n青山是我安魂处，清梦时时赋大刀。'},
    {t:'览镜书怀',a:'李白〔唐代〕',c:'得道无古今，失道还衰老。\n自笑镜中人，白发如霜草。\n扪心空叹息，问影何枯槁？\n桃李竟何言，终成南山皓。'},
    {t:'烂柯山',a:'朱熹〔宋代〕',c:'局上闲争战，人间任是非。\n空叫禾樵客，烂柯不知归。'},
    {t:'烂柯由石桥',a:'孟郊〔唐代〕',c:'仙界一日内，人间千载穷。\n双棋未遍局，万物皆为空。\n樵客返归路，斧柯烂从风。\n唯余石桥在，犹自凌丹虹。'},
    {t:'狼山观海',a:'王安石〔宋代〕',c:'万里昆仑谁凿破，无边波浪拍天来。\n晓寒云雾连穷屿，春暖鱼龙化蛰雷。\n阆苑仙人何处觅？灵槎使者几时回？\n遨游半在江湖里，始觉今朝眼界开。'},
    {t:'阆山歌',a:'杜甫〔唐代〕',c:'阆州城东灵山白，阆州城北玉台碧。\n松浮欲尽不尽云，江动将崩未崩石。\n那知根无鬼神会？已觉气与嵩华敌。\n中原格斗且未归，应结茅斋著青壁。'},
    {t:'阆水歌',a:'杜甫〔唐代〕',c:'嘉陵江色何所似？石黛碧玉相因依。\n正怜日破浪花出，更复春从沙际归。\n巴童荡桨欹侧过，水鸡衔鱼来去飞。\n阆中胜事可肠断，阆州城南天下稀！'},
    {t:'阆州开元寺壁题乐天诗',a:'元稹〔唐代〕',c:'忆君无计写君诗，写尽千行说向谁。\n题在阆州东寺壁，几时知是见君时。'},
    {t:'琅琊王歌辞·其四',a:'佚名〔隋代〕',c:'琅琊复琅琊，琅琊大道王。\n鹿鸣思长草，愁人思故乡。'},
    {t:'琅琊王歌辞·新买五尺刀',a:'佚名〔南北朝〕',c:'新买五尺刀，悬著中梁柱。\n一日三摩挲，剧于十五女。\n琅琊复琅琊，琅琊大道王。\n阳春二三月，单衫绣裲裆。'},
    {t:'琅琊王歌辞其六',a:'佚名〔隋代〕',c:'琅琊复琅琊，女郎大道王。孟阳三四月，移铺逐阴凉。'},
    {t:'琅琊王歌辞其七',a:'佚名〔隋代〕',c:'客行依主人，愿得主人强。猛虎依深山，愿得松柏长。'},
    {t:'浪涛沙·昼阴重',a:'周邦彦〔宋代〕',c:'昼阴重，霜凋岸草，雾隐城堞。南陌脂车待发。东门帐饮乍阕。正拂面垂杨堪缆结。掩红泪、玉手亲折。念汉浦离鸿去何许，经时信音绝。情切。望中地远天阔。向露冷风清，无人处、耿耿寒漏咽。\n嗟万事难忘，唯是轻别。翠尊未竭。凭断云留取，西楼残月。罗带光销纹衾叠。连环解、旧香顿歇。怨歌永、琼壶敲尽缺。恨春去、不与人期，弄夜色，空馀满地梨花雪。'},
    {t:'浪淘沙',a:'晏几道〔宋代〕',c:'高阁对横塘。新燕年光。柳花残梦隔潇湘。绿浦归帆看不见，还是斜阳。\n一笑解愁肠，人会娥妆。藕丝衫袖郁金香。曳雪牵云留客醉，且伴春狂。'},
    {t:'浪淘沙',a:'张炎〔宋代〕',c:'寒食不多时。燕燕才归。杏花零霎水痕肥。浅碧分山初过雨，一霎晴晖。\n闲折小桃枝。蝶也相随。晚妆不合整蛾眉。蓦忽思量张敞画，又被愁知。'},
    {t:'浪淘沙',a:'晏几道〔宋代〕',c:'丽曲醉思仙。十二哀弦。秾蛾叠泪脸红莲。多少雨条烟叶恨，红泪离筵。\n行子惜流年。鶗鴂枝边。吴堤春水舣兰船。南去北来今渐老，难负尊前。'},
    {t:'浪淘沙·白浪茫茫与海连',a:'白居易〔唐代〕',c:'白浪茫茫与海连，平沙浩浩四无边。\n暮去朝来淘不住，遂令东海变桑田。'},
    {t:'浪淘沙·翠幕绮筵张',a:'晏几道〔宋代〕',c:'翠幕绮筵张，淑景难忘。\n阳关声巧绕雕梁。\n美酒十分谁与共，玉指持觞。\n晓枕梦高唐，略话衷肠。\n小山池院竹风凉。\n明夜月圆帘四卷，今夜思量。'},
    {t:'浪淘沙·丹阳浮玉亭席上作',a:'陆游〔宋代〕',c:'绿树暗长亭，几把离尊。阳关常恨不堪闻。何况今朝秋色里，身是行人。\n清泪浥罗巾，各自消魂。一江离恨恰平分。安得千寻横铁锁，截断烟津？'},
    {t:'浪淘沙·赋虞美人草',a:'辛弃疾〔宋代〕',c:'不肯过江东。玉帐匆匆。至今草木忆英雄。唱著虞兮当日曲，便舞春风。\n儿女此情同。往事朦胧。湘娥竹上泪痕浓。舜盖重瞳堪痛恨，羽又重瞳。'},
    {t:'浪淘沙·红影湿幽窗',a:'纳兰性德〔清代〕',c:'红影湿幽窗，瘦尽春光。雨余花外却斜阳。谁见薄衫低髻子，抱膝思量。\n莫道不凄凉，早近持觞。暗思何事断人肠。曾是向他春梦里，瞥遇回廊。'},
    {t:'浪淘沙·借问江潮与海水',a:'白居易〔唐代〕',c:'借问江潮与海水，何似君情与妾心？\n相恨不如潮有信，相思始觉海非深。'},
    {t:'浪淘沙·荔枝',a:'黄庭坚〔宋代〕',c:'忆昔谪巴蛮。荔子亲攀。冰肌照映柘枝冠。日擘轻红三百颗，一味甘寒。\n重入鬼门关。也似人间。一双和叶插云鬟。赖得清湘燕玉面，同倚阑干。'},
    {t:'浪淘沙·闷自剔残灯',a:'纳兰性德〔清代〕',c:'闷自剔残灯，暗雨空庭。潇潇已是不堪听，那更西风偏著意，做尽秋声。\n城柝已三更，欲睡还醒。薄寒中夜掩银屏，曾染戒香消俗念，莫又多情。'},
    {t:'浪淘沙·其八',a:'刘禹锡〔唐代〕',c:'莫道谗言如浪深，莫言迁客似沙沉。\n千淘万漉虽辛苦，吹尽狂沙始到金。'},
    {t:'浪淘沙·其二',a:'刘禹锡〔唐代〕',c:'洛水桥边春日斜，碧流清浅见琼砂。\n无端陌上狂风疾，惊起鸳鸯出浪花。'},
    {t:'浪淘沙·其九',a:'刘禹锡〔唐代〕',c:'流水淘沙不暂停，前波未灭后波生。\n令人忽忆潇湘渚，回唱迎神三两声。'},
    {t:'浪淘沙·其六',a:'刘禹锡〔唐代〕',c:'日照澄洲江雾开，淘金女伴满江隈。\n美人首饰侯王印，尽是沙中浪底来。'},
    {t:'浪淘沙·其七',a:'刘禹锡〔唐代〕',c:'八月涛声吼地来，头高数丈触山回。\n须臾却入海门去，卷起沙堆似雪堆。'},
    {t:'浪淘沙·其三',a:'刘禹锡〔唐代〕',c:'汴水东流虎眼文，清淮晓色鸭头春。\n君看渡口淘沙处，渡却人间多少人。'},
    {t:'浪淘沙·其四',a:'刘禹锡〔唐代〕',c:'鹦鹉洲头浪飐沙，青楼春望日将斜。\n衔泥燕子争归舍，独自狂夫不忆家。'},
    {t:'浪淘沙·其五',a:'刘禹锡〔唐代〕',c:'濯锦江边两岸花，春风吹浪正淘沙。\n女郎剪下鸳鸯锦，将向中流匹晚霞。'},
    {t:'浪淘沙·其一',a:'刘禹锡〔唐代〕',c:'九曲黄河万里沙，浪淘风簸自天涯。\n如今直上银河去，同到牵牛织女家。'},
    {t:'浪淘沙·青草湖中万里程',a:'白居易〔唐代〕',c:'青草湖中万里程，黄梅雨里一人行。\n愁见滩头夜泊处，风翻暗浪打船声。'},
    {t:'浪淘沙·秋江',a:'张炎〔宋代〕',c:'万里一飞篷。吟老丹枫。潮生潮落海门东。三两点鸥沙外月，闲意谁同。\n一色与天通。绝去尘红。渔歌忽断荻花风。烟水自流心不竞，长笛霜空。'},
    {t:'浪淘沙·山寺夜半闻钟',a:'辛弃疾〔宋代〕',c:'身世酒杯中，万事皆空。古来三殿个英雄。雨打风吹何处是，汉殿秦宫。\n梦入少年丛，歌舞匆匆。老僧夜半误鸣钟。惊起西窗眠不得，卷地西风。'},
    {t:'浪淘沙·探春',a:'苏轼〔宋代〕',c:'昨日出东城，试探春情。墙头红杏暗如倾。槛内群芳芽未吐，早已回春。\n绮陌敛香尘，雪霁前村。东君用意不辞辛。料想春光先到处，吹绽梅英。'},
    {t:'浪淘沙·题陈汝朝百鹭画卷',a:'张炎〔宋代〕',c:'玉立水云乡。尔我相忘。披离寒羽庇风霜。不趁白鸥游海上，静看鱼忙。\n应笑我凄凉。客路何长。犹将孤影侣斜阳。花底鹓行无认处，却对秋塘。'},
    {t:'浪淘沙·题许由掷瓢手卷',a:'张炎〔宋代〕',c:'拂袖入山阿。深隐松萝。掬流洗耳厌尘多。石上一般清意味，不羡渔蓑。\n日月静中过。俗□消磨。风瓢分付与清波。却笑唐求因底事，无奈诗何。'},
    {t:'浪淘沙·望海',a:'纳兰性德〔清代〕',c:'蜃阙半模糊，踏浪惊呼。任将蠡测笑江湖。沐日光华还浴月，我欲乘桴。\n钓得六鳖无。竿拂珊瑚。桑田清浅问麻姑。水气浮天天接水，那是蓬壶。'},
    {t:'浪淘沙·小绿间长红',a:'晏几道〔宋代〕',c:'小绿间长红，露蕊烟丛。花开花事昔年同。惟恨花前携手处，往事成空。\n山远水重重，一笑难逢。已拚长在别离中。霜鬓知他从此去，几度春风。'},
    {t:'浪淘沙·夜雨做成秋',a:'纳兰性德〔清代〕',c:'夜雨做成秋，恰上心头。教他珍重护风流。端的为谁添病也，更为谁羞。\n密意未曾休，密愿难酬。珠帘四卷月当楼。暗忆欢期真似梦，梦也须留。'},
    {t:'浪淘沙·一泊沙来一泊去',a:'白居易〔唐代〕',c:'一泊沙来一泊去，一重浪灭一重生。\n相搅相淘无歇日，会教山海一时平。'},
    {t:'浪淘沙·有个人人',a:'柳永〔宋代〕',c:'有个人人，飞燕精神。急锵环佩上华裀。促拍尽随红袖举，风柳腰身。\n簌簌轻裙，妙尽尖新。曲终独立敛香尘。应是西施娇困也，眉黛双颦。'},
    {t:'浪淘沙·余画墨水仙并题其上',a:'张炎〔宋代〕',c:'回首欲婆娑。淡扫修蛾。盈盈不语奈情何。应恨梅兄矾弟远，云隔山阿。\n弱水夜寒多。带月曾过。羽衣飞过染余波。白鹤难招归未得，天阔星河。'},
    {t:'浪淘沙·作墨水仙寄张伯雨',a:'张炎〔宋代〕',c:'香雾湿云鬟。蕊佩珊珊。酒醒微步晚波寒。金鼎尚存丹已化，雪冷虚坛。\n游冶未知还。鹤怨空山。潇湘无梦绕丛兰。碧海茫茫归不去，却在人间。'},
    {t:'浪淘沙令·伊吕两衰翁',a:'王安石〔宋代〕',c:'伊吕两衰翁，历遍穷通。一为钓叟一耕佣。若使当时身不遇，老了英雄。\n汤武偶相逢，风虎云龙。兴王只在谈笑中。直至如今千载后，谁与争功！'},
    {t:'浪淘沙慢·梦觉透窗风一线',a:'柳永〔宋代〕',c:'梦觉透窗风一线，寒灯吹息。那堪酒醒，又闻空阶，夜雨频滴。嗟因循、久作天涯客。负佳人、几许盟言，便忍把、从前欢会，陡顿翻成忧戚。\n愁极，再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被。岂暂时疏散，费伊心力。殢云尤雨，有万般千种，相怜相惜。\n恰到如今，天长漏永，无端自家疏隔。知何时、却拥秦云态？愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。'},
    {t:'浪淘沙慢·万叶战',a:'周邦彦〔宋代〕',c:'万叶战，秋声露结，雁度沙碛。细草和烟尚绿，遥山向晚更碧。见隐隐、云边新月白。映落照、帘幕千家，听数声、何处倚楼笛？装点尽秋色。脉脉。旅情暗自消释。念珠玉、临水犹悲感，何况天涯客？\n忆少年歌酒，当时踪迹。岁华易老，衣带宽、懊恼心肠终窄。飞散后、风流人阻。兰桥约、怅恨路隔。马蹄过、犹嘶旧巷陌。叹往事、一一堪伤，旷望极。凝思又把阑干拍。'},
    {t:'浪淘沙慢·晓阴重',a:'周邦彦〔宋代〕',c:'晓阴重，霜凋岸草，雾隐城堞。南陌脂车待发，东门帐饮乍阕。正拂面、垂杨堪揽结。掩红泪、玉手亲折。念汉浦、离鸿去何许？经时信音绝。\n情切，望中地远天阔。向露冷风清，无人处，耿耿寒漏咽。嗟万事难忘，惟是轻别。翠尊未竭，凭断云、留取西楼残月。\n罗带光消纹衾叠，连环解、旧香顿歇。怨歌永、琼壶敲尽缺。恨春去、不与人期，弄夜色、空馀满地梨花雪。'},
    {t:'劳劳山居寄呈吴处士',a:'皎然〔唐代〕',c:'山事由来别，只应中老身。寒园扫绽栗，秋浪拾干薪。\n领鹤闲书竹，夸云笑向人。俗家相去远，野水作东邻。'},
    {t:'劳劳亭',a:'李白〔唐代〕',c:'天下伤心处，劳劳送客亭。\n春风知别苦，不遣柳条青。'},
    {t:'劳山居寄呈吴处士',a:'皎然〔唐代〕',c:'官居鼎鼐古今无，名世才臣独一余。\n贤阁御题龙墨灿，诏归补衮在须臾。'},
    {t:'劳山忆栖霞寺道素上人久期不至',a:'皎然〔唐代〕',c:'远寺萧萧独坐心，山情自得趣何深。\n泉声稍滴芙蓉漏，月影才分鹦鹉林。\n满地云轻长碍屣，绕松风近每吹襟。\n贪闲不记前心偈，念别聊为出世吟。\n更待花开遍山雪，山山相似若为寻。'},
    {t:'老夫采玉歌',a:'李贺〔唐代〕',c:'采玉采玉须水碧，琢作步摇徒气色。\n老夫饥寒龙为愁，蓝溪水气无清白。\n夜雨冈头食蓁子，杜人口血老夫泪。\n蓝溪之水厌生人，身死千年恨溪水。\n斜山柏风雨如啸，泉脚挂绳青袅袅。\n村寒白屋念娇婴，古台石磴悬肠草。'},
    {t:'老恨',a:'孟郊〔唐代〕',c:'无子抄文字，老吟多飘零。有时吐向床，枕席不解听。\n斗蚁甚微细，病闻亦清泠。小大不自识，自然天性灵。'},
    {t:'老疾戏自赠',a:'陆游〔宋代〕',c:'年过七十日夜衰，羸然迟立不足持。\n一身百病作无时，饭且不足那论医。\n镜中之人定是谁，面迟突兀鬓成丝。\n买棺作冢计已迟，一旦宁免累诸儿？\n门前湖山可遨嬉，心虽欲往力不随。\n左车牙脱吁可悲，问汝何不食肉糜？'},
    {t:'老将',a:'张籍〔唐代〕',c:'鬓衰头似雪，行步急如风。不怕骑生马，犹能挽硬弓。\n兵书封锦字，手诏满香筒。今日身憔悴，犹夸定远功。'},
    {t:'老马行',a:'陆游〔宋代〕',c:'老马虺隤依晚照，自计岂堪三品料？\n玉鞭金络付梦想，瘦稗枯萁空咀噍。\n中原蝗旱胡运衰，王师北伐方传诏。\n一闻战鼓意气生，犹能为国平燕赵。'},
    {t:'老人行',a:'王安石〔宋代〕',c:'老人低心逐年少，年少还为老人调。\n两家挟诈自相欺，四海伤真谁复诮。\n翻手作云覆手雨，当面输心背面笑。\n古来人事已如此，今日何须论久要。'},
    {t:'乐府杂曲·鼓吹铙歌·苞枿',a:'柳宗元〔唐代〕',c:'苞枿ba矣，惟根之蟠。弥巴蔽荆，负南极以安。\n曰我旧梁氏，辑绥艰难。江汉之阻，都邑固以完。\n圣人作，神武用，有臣勇智，奋不以众。投迹死地，\n谋猷纵。化敌为家，虑则中。浩浩海裔，不威而同。\n系缧降王，定厥功。澶漫万里，宣唐风。蛮夷九译，\n咸来从。凯旋金奏，象形容。震赫万国，罔不龚。'},
    {t:'乐府杂曲·鼓吹铙歌·苞枿',a:'柳宗元〔唐代〕',c:'苞枿黑对矣，惟根之蟠。弥巴蔽荆，负南极以安。\n曰我旧梁氏，辑绥艰难。江汉之阻，都邑固以完。\n圣人作，神武用，有臣勇智，奋不以众。投迹死地，\n谋猷纵。化敌为家，虑则中。浩浩海裔，不威而同。\n系缧降王，定厥功。澶漫万里，宣唐风。蛮夷九译，\n咸来从。凯旋金奏，象形容。震赫万国，罔不龚。'},
    {t:'乐府杂曲·鼓吹铙歌·晋阳武',a:'柳宗元〔唐代〕',c:'晋阳武，奋义威。炀之渝，德焉归。氓毕屠，绥者谁。\n皇烈烈，专天机。号以仁，扬其旗。日之升，九土晞。\n斥田圻，流洪辉。有其二，翼馀隋。斫枭骜，连熊螭。\n枯以肉，勍者羸。后土荡，玄穹弥。合之育，莽然施。\n惟德辅，庆无期。'},
    {t:'乐府杂曲·鼓吹铙歌·靖本邦',a:'柳宗元〔唐代〕',c:'本邦伊晋，惟时不靖。根柢之摇，枝叶攸病。\n守臣不任，勩于神圣。惟钺之兴，翦焉则定。\n洪惟我理，式和以敬。群顽既夷，庶绩咸正。\n皇谟载大，惟人之庆。'},
    {t:'乐府杂曲·鼓吹铙歌·兽之穷',a:'柳宗元〔唐代〕',c:'兽之穷，奔大麓。天厚黄德，狙犷服。\n甲之櫜弓，弭矢箙。皇旅靖，敌逾蹙。\n自亡其徒，匪予戮。屈rH猛，虔栗栗。\n縻以尺组，啖以秩。黎之阳，土茫茫。\n富兵戎，盈仓箱。乏者德，莫能享。驱豺兕，授我疆。'},
    {t:'乐府杂曲·鼓吹铙歌·铁山碎',a:'柳宗元〔唐代〕',c:'铁山碎，大漠舒。二虏劲，连穹庐。背北海，专坤隅。\n岁来侵边，或傅于都。天子命元帅，奋其雄图。\n破定襄，降魁渠。穷竟窟宅，斥余吾。百蛮破胆，\n边氓苏。威武辉耀，明鬼区。利泽弥万祀，功不可逾。\n官臣拜手，惟帝之谟。'},
    {t:'乐府杂曲·鼓吹铙歌·吐谷浑',a:'柳宗元〔唐代〕',c:'吐谷浑盛强，背西海以夸。岁侵扰我疆，退匿险且遐。\n帝谓神武师，往征靖皇家。烈烈旆其旗，熊虎杂龙蛇。\n王旅千万人，衔枚默无哗。束刃逾山徼，张翼纵漠沙。\n一举刈膻腥，尸骸积如麻。除恶务本根，况敢遗萌芽。\n洋洋西海水，威命穷天涯。系虏来王都，犒乐穷休嘉。\n登高望还师，竟野如春华。行者靡不归，亲戚讙要遮。\n凯旋献清庙，万国思无邪。'},
    {t:'乐府杂曲·鼓吹曲辞·将进酒',a:'元稹〔唐代〕',c:'将进酒，将进酒，酒中有毒鸩主父，言之主父伤主母。\n母为妾地父妾天，仰天俯地不忍言。佯为旁踣主父前，\n主父不知加妾鞭。旁人知妾为主说，主将泪洗鞭头血。\n推摧主母牵下堂，扶妾遣升堂上床。将进酒，\n酒中无毒令主寿，愿主回思归主母，遣妾如此事主父。\n妾为此事人偶知，自惭不密方自悲。主今颠倒安置妾，\n贪天僭地谁不为。'},
    {t:'乐府杂曲·鼓吹曲辞·有所思',a:'孟郊〔唐代〕',c:'桔槔烽火昼不灭，客路迢迢信起越。古镇刀攒万片霜，\n寒江浪起千堆雪。此时西去定如何，空使南心远凄切。'},
    {t:'乐府杂曲·鼓吹曲辞·有所思',a:'韦应物〔唐代〕',c:'借问江上柳，青青为谁春。\n空游昨日地，不见昨日人。\n缭绕万家井，往来车马尘。\n莫道无相识，要非心所亲。'},
    {t:'乐府杂曲·鼓吹曲辞·朱鹭',a:'张籍〔唐代〕',c:'翩翩兮朱鹭，来泛春塘栖绿树。\n羽毛如翦色如染，远飞欲下双翅敛。\n避人引子入深堑，动处水纹开滟滟。\n谁知豪家网尔躯，不如饮啄江海隅。'},
    {t:'乐府杂曲其六苞蘖',a:'柳宗元〔唐代〕',c:'苞蘖𪒶矣，惟根之蟠。弥巴蔽荆，负南极以安。\n冃我旧梁氏，缉绥艰难。江汉之阻，都邑固以完。\n圣人作，神武用。有臣勇智，奋不以众。投迹死地，谋猷纵。\n化敌为家，虑则中。浩浩海裔，不威而同。系缧降王，定厥功。\n澶漫万里，宣唐风。蛮夷九译，咸来从。凯旋金奏，象形容。\n震赫万国，罔不龚。'},
    {t:'乐府杂曲其十吐谷浑',a:'柳宗元〔唐代〕',c:'吐谷浑盛彊，背西海以夸。岁侵扰我疆，退匿险且遐。\n帝谓神武师，往征靖皇家。烈烈旆其旗，熊虎杂龙蛇。\n王旅千万人，衔枚默无哗。束刃踰山徼，张翼纵漠沙。\n一举刈膻腥，尸骸积如麻。除恶务本根，况敢遗萌芽。\n洋洋西海水，威命穷天涯。系虏来王都，犒乐穷休嘉。\n登高望还师，竟野如春华。行者靡不归，亲戚劝要遮。\n凯旋献清庙，万国思无邪。'},
    {t:'乐府杂曲其十一高昌',a:'柳宗元〔唐代〕',c:'曲氏雄西北，别绝臣外区。既恃远且险，纵傲不我虞。\n烈烈王者师，熊螭以为徒。龙旂翻海浪，驲骑驰坤隅。\n贲育搏婴儿，一扫不复馀。平沙际天极，但见黄云驱。\n臣靖执长缨，智勇伏囚拘。文皇南面坐，夷狄千群趋。\n咸称天子神，往古不得俱。献号天可汗，以覆我国都。\n兵戎不交害，各保性与躯。'},
    {t:'乐游园歌',a:'杜甫〔唐代〕',c:'乐游古园崒森爽，烟绵碧草萋萋长。\n公子华筵势最高，秦川对酒平如掌。\n长生木瓢示真率，更调鞍马狂欢赏。\n青春波浪芙蓉园，白日雷霆夹城仗。\n阊阖晴开詄荡荡，曲江翠幕排银牓。\n拂水低徊舞袖翻，缘云清切歌声上。\n却忆年年人醉时，只今未醉已先悲。\n数茎白发那抛得？百罚深杯亦不辞。\n圣朝亦知贱士丑，一物自荷皇天慈。\n此身饮罢无归处，独立苍茫自咏诗。'},
    {t:'乐游原',a:'李商隐〔唐代〕',c:'春梦乱不记，春原登已重。\n青门弄烟柳，紫阁舞云松。\n拂砚轻冰散，开尊绿酎浓。\n无悰托诗遣，吟罢更无悰。'},
    {t:'耒阳溪夜行',a:'张九龄〔唐代〕',c:'乘夕棹归舟，缘源路转幽。\n月明看岭树，风静听溪流。\n岚气船间入，霜华衣上浮。\n猿声虽此夜，不是别家愁。'},
    {t:'泪',a:'李商隐〔唐代〕',c:'永巷长年怨绮罗，离情终日思风波。\n湘江竹上痕无限，岘首碑前洒几多。\n人去紫台秋入塞，兵残楚帐夜闻歌。\n朝来灞水桥边问，未抵青袍送玉珂。'},
    {t:'酹江月·和友驿中言别',a:'文天祥〔宋代〕',c:'乾坤能大，算蛟龙元不是池中四。风雨牢愁无著处，那更寒蛩四壁。横槊题诗，登楼作赋，万事杰中雪。江流如此，方来还有英杰。\n堪笑一叶漂零，重来淮水，正凉风新发。镜里朱颜都变尽，只有丹心难灭。去去龙沙，江山回首，一线青如发。故人应念，杜鹃枝上残月。'},
    {t:'酹江月·南康军和苏韵',a:'文天祥〔宋代〕',c:'庐山依旧，凄凉处、无限江南风半。空翠晴岚浮汗漫，还障天东半壁。雁过孤峰，猿归危嶂，风急杰翻雪。乾坤未老，地灵尚有人杰。\n堪嗟漂泊孤舟，河倾斗落，客梦催明发。南浦闲云过草树，回首旌旗明灭。三十年来，十年一过，空有星星发。夜深悉听，胡笳吹彻寒月。'},
    {t:'离北山寄平甫',a:'王安石〔宋代〕',c:'日月沄沄与水争，披襟照见发华惊。\n少年忧患伤豪气，老去经纶误半生。\n休向朝廷论一鹗，只知田里守三荆。\n清溪几曲春风好，已约归时载酒行。'},
    {t:'离别难·花谢水流倏忽',a:'柳永〔宋代〕',c:'花谢水流倏忽，嗟年少光阴。有天然、蕙质兰心。美韶容、何啻值千金。便因甚、翠弱红衰，缠绵香体，都不胜任。算神仙、五色灵丹无验，中路委瓶簪。\n人悄悄，夜沈沈。闭香闺、永弃鸳衾。想娇魂媚魄非远，纵洪都方士也难寻。最苦是、好景良天，尊前歌笑，空想遗音。望断处，杳杳巫峰十二，千古暮云深。'},
    {t:'离宫怨',a:'张籍〔唐代〕',c:'高堂别馆连湘渚，长向春光开万户。\n荆王去去不复来，宫中美人自歌舞。'},
    {t:'离觞不醉至驿却寄相送诸公',a:'柳宗元〔唐代〕',c:'无限居人送独醒，可怜寂寞到长亭。\n荆州不遇高阳侣，一夜春寒满下厅。'},
    {t:'离思',a:'孟郊〔唐代〕',c:'不寐亦不语，片月秋稍举。\n孤鸿忆霜群，独鹤叫云侣。\n怨彼浮花心，飘飘无定所。\n高张系繂帆，远过梅根渚。\n回织别离字，机声有酸楚。'},
    {t:'离思',a:'李商隐〔唐代〕',c:'气尽前溪舞，心酸子夜歌。\n峡云寻不得，沟水欲如何。\n朔雁传书绝，湘篁染泪多。\n无由见颜色，还自托微波。'},
    {t:'离思五首',a:'元稹〔唐代〕',c:'自爱残妆晓镜中，环钗漫篸绿丝丛。\n须臾日射胭脂颊，一朵红苏旋欲融。\n山泉散漫绕阶流，万树桃花映小楼。\n闲读道书慵未起，水晶帘下看梳头。\n红罗著压逐时新，吉了花纱嫩麴尘。\n第一莫嫌材地弱，些些纰缦最宜人。\n曾经沧海难为水，除却巫山不是云。\n取次花丛懒回顾，半缘修道半缘君。\n寻常百种花齐发，偏摘梨花与白人。\n今日江头两三树，可怜和叶度残春。'},
    {t:'离思五首·其四',a:'元稹〔唐代〕',c:'曾经沧海难为水，除却巫山不是云。\n取次花丛懒回顾，半缘修道半缘君。'},
    {t:'离亭赋得折杨柳二首',a:'李商隐〔唐代〕',c:'暂凭尊酒送无憀，莫损愁眉与拟腰。\n人世死前唯有别，春风争拟惜长条。\n含烟惹雾每依依，万绪千条拂落晖。\n为报行人休折尽，半留相送半迎归。'},
    {t:'骊山下逍遥公旧居游集',a:'张九龄〔唐代〕',c:'君子体清尚，归处有兼资。虽然经济日，无忘幽栖时。\n卜居旧何所，休浣尝来兹。岑寂罕人至，幽深获我思。\n松涧聆遗风，兰林览馀滋。往事诚已矣，道存犹可追。\n遗子后黄金，作歌先紫芝。明德有自来，奕世皆秉彝。\n岂与磻溪老，崛起周太师。我心希硕人，逮此问元龟。\n怊怅既怀远，沉吟亦省私。已云宠禄过，况在华发衰。\n轩盖有迷复，丘壑无磷缁。感物重所怀，何但止足斯。'},
    {t:'骊山有感',a:'李商隐〔唐代〕',c:'骊岫飞泉泛暖香，九龙呵护玉莲房。\n平明每幸长生殿，不从金舆惟寿王。'},
    {t:'梨花下赠刘师命',a:'韩愈〔唐代〕',c:'洛阳城外清明节，百花寥落梨花发。\n今日相逢瘴海头，共惊烂漫开正月。'},
    {t:'李白墓',a:'白居易〔唐代〕',c:'采石江边李白坟，绕田无限草连云。\n可怜荒垄穷泉骨，曾有惊天动地文。\n但是诗人多薄命，就中沦落不过君。'},
    {t:'李都尉古剑',a:'白居易〔唐代〕',c:'古剑寒黯黯，铸来几千秋。\n白光观日月，紫气排斗牛。\n有客借一观，爱之不敢求。\n湛然玉匣中，秋与澄不流。\n至宝有本性，精刚无与俦。\n可使寸寸折，不能绕指柔。\n愿快直士心，将断佞臣头。\n不愿报小怨，夜半刺私仇。\n劝君慎所用，无作神兵羞。'},
    {t:'李贺作诗',a:'韩愈〔唐代〕',c:'李贺字长吉，系出郑王后。七岁能辞章，韩愈、皇甫湜始闻未信，过其家，使贺赋诗，援笔辄就如素构，自名曰《高轩过》。二人大惊，自是有名。每旦日出，骑弱马，从小奚奴，背古锦囊，遇所得，书投囊中。未始先立题然后为诗，如他人牵合程课者。及暮归，足成之。非大醉、吊丧日率如此。过亦不甚省。母使婢女探囊中，见所书多，即怒曰：“是儿要呕心乃已耳！”'},
    {t:'李花',a:'李商隐〔唐代〕',c:'李径独来数，愁情相与悬。自明无月夜，强笑欲风天。\n减粉与园箨，分香沾渚莲。徐妃久已嫁，犹自玉为钿。'},
    {t:'李花',a:'王安石〔宋代〕',c:'朝摘桃花红破萼，莫摘李花繁满枝，客心浩荡东风急，把酒看花能几时。'},
    {t:'李花',a:'杨万里〔宋代〕',c:'李花宜远更宜繁，惟远惟繁始足看。\n莫学江梅作疏影，家风各自一般般。'},
    {t:'李花赠张十一署',a:'韩愈〔唐代〕',c:'江陵城西二月尾，起不空桃惟空李。\n风揉雨练雪羞比，波涛翻空杳无涘。\n君知此处起何似？\n白起倒烛天夜明，群鸡惊鸣官吏起。\n金乌海底初飞来，朱辉散射青霞开。\n迷魂乱眼看不得，照耀万树繁如堆。\n念昔少年著游燕，对起岂省曾辞杯。\n自从流落忧感集，欲去未到先思回。\n只今四十已如此，后日更老谁论哉。\n力携一尊独就醉，不忍虚掷委黄埃。'},
    {t:'李陵咏',a:'王维〔唐代〕',c:'汉家李将军，三代将门子。\n结发儿奇策，少年成壮士。\n长驱塞上儿，深入单于垒。\n旌旗列相向，箫尘悲何已。\n日暮沙漠陲，战声烟尘里。\n将令骄虏灭，岂独名王侍。\n既失大军援，遂婴穹庐耻。\n少小蒙汉恩，何堪坐思此。\n深衷欲儿报，投躯未能死。\n引领望子卿，非君谁相理。'},
    {t:'李凭箜篌引',a:'李贺〔唐代〕',c:'吴丝蜀桐张高秋，空山凝云颓不流。\n江娥啼竹素女愁，李凭中国弹箜篌。\n昆山玉碎凤凰叫，芙蓉泣露香兰笑。\n十二门前融冷光，二十三丝动紫皇。\n女娲炼石补天处，石破天惊逗秋雨。\n梦入神山教神妪，老鱼跳波瘦蛟舞。\n吴质不眠倚桂树，露脚斜飞湿寒兔。'},
    {t:'李少府与杨九再来',a:'孟浩然〔唐代〕',c:'弱岁早登龙，今来喜再逢。如何春月柳，犹忆岁寒松。\n烟火临寒食，笙歌达曙钟。喧喧斗鸡道，行乐羡朋从。'},
    {t:'李氏园林卧疾',a:'孟浩然〔唐代〕',c:'我爱陶家趣，园林无俗情。\n春雷百卉坼，寒食四邻清。\n伏枕嗟公干，归山羡子平。\n年年白社客，空滞洛阳城。'},
    {t:'李思训画长江绝岛图',a:'苏轼〔宋代〕',c:'山苍苍，水茫茫，大孤小孤江中央。\n崖崩路绝猿鸟去，惟有乔木搀天长。\n客舟何处来，棹歌中流声抑扬。\n沙平风软望不到，孤山久与船低昂。\n峨峨两烟鬟，晓镜开新妆。\n舟中贾客莫漫狂，小姑前年嫁彭郎。'},
    {t:'李四仓曹宅夜饮',a:'王昌龄〔唐代〕',c:'霜天留后故情欢，银烛金炉夜不寒。\n欲问吴江别来意，青山明月梦中看。'},
    {t:'李西川荐琴石',a:'柳宗元〔唐代〕',c:'远师驺忌鼓鸣琴，去和南风惬舜心。\n从此他山千古重，殷勤曾是奉徽音。'},
    {t:'李羽处士故里',a:'温庭筠〔唐代〕',c:'柳不成丝草带烟，海槎东去鹤归天。\n愁肠断处春何限，病眼开时月正圆。\n花若有情还怅望，水应无事莫潺湲。\n终知此恨销难尽，辜负南华第二篇。'},
    {t:'李璋下第',a:'王安石〔宋代〕',c:'浩荡宫门白日开，君王高拱试群材。\n学如吾子何忧失，命属天公不可猜。\n意气未直轻感慨，文章尤忌数悲哀。\n男儿独患无名尔，将相谁云有种哉。'},
    {t:'澧头送蒋侯',a:'岑参〔唐代〕',c:'君住澧水北，我家澧水西。两村辨乔木，五里闻鸣鸡。\n饮酒溪雨过，弹棋山月低。徒闻蒋生径，尔去谁相携。'},
    {t:'立春',a:'杜甫〔唐代〕',c:'春日春盘细生菜，忽忆两京梅发时。\n盘出高门行白玉，菜传纤手送青丝。\n巫峡寒江那对眼，杜陵远客不胜悲。\n此身未知归定处，呼儿觅纸一题诗。'},
    {t:'立春',a:'文天祥〔宋代〕',c:'无限斜阳故国愁，朔风吹马上幽州。\n天翻地覆三生劫，岁晚江空万里囚。\n烈士丧元端不惜，达人知命复何忧。\n只应四十三年死，两度无端见土牛。'},
    {t:'立春',a:'黄庭坚〔宋代〕',c:'韭苗香煮饼，野老不知春。\n看镜道如咫，倚楼梅照人。'},
    {t:'立春日',a:'杨万里〔宋代〕',c:'何处新春好，深山处士家。\n风光先著柳，日色款催花。'},
    {t:'立春日晨起对积雪',a:'张九龄〔唐代〕',c:'忽对林亭雪，瑶华处处开。\n今年迎气始，昨夜伴春回。\n玉润窗前竹，花繁院里梅。\n东郊斋祭所，应见五神来。'},
    {t:'立春日酬钱员外曲江同行见赠',a:'白居易〔唐代〕',c:'下直遇春日，垂鞭出禁闱。\n两人携手语，十里看山归。\n柳色早黄浅，水文新绿微。\n风光向晚好，车马近南稀。\n机尽笑相顾，不惊鸥鹭飞。'},
    {t:'立春日词其四内廷',a:'晏殊〔宋代〕',c:'双金缕胜延嘉节，五綵为幡奉紫廷。春色渐浓人未觉，玉阶杨柳半青青。'},
    {t:'立春祀太乙',a:'晏殊〔宋代〕',c:'华灯明灭羽衣攒，翠柳萧森矮桧寒。\n千步回廊绕金殿，水苍瑶佩响珊珊。'},
    {t:'立春祀太乙',a:'晏殊〔宋代〕',c:'紫毛双节引青童，一片空歌韵晓风。\n太昊兹辰授春令，莺旗应在矞云中。'},
    {t:'立冬日作',a:'陆游〔宋代〕',c:'室小才容膝，墙低仅及肩。\n方过授衣月，又遇始裘天。\n寸积篝炉炭，铢称布被绵。\n平生师陋巷，随处一欣然。'},
    {t:'立秋后一日雨天欲暮小立问月亭',a:'杨万里〔宋代〕',c:'雨后林中别样凉，意行幽径不知长。风蝉幸自无星事，强为闲人报夕阳。'},
    {t:'立秋日曲江忆元九',a:'白居易〔唐代〕',c:'下马柳阴下，独上堤上行。\n故人千万里，新蝉三两声。\n城中曲江水，江上江陵城。\n两地新秋思，应同此日情。'},
    {t:'立秋日闻蝉',a:'杨万里〔宋代〕',c:'老火薰人欲破头，唤秋不到得人愁。\n夜来一雨将秋至，今晚蝉声始报秋。'},
    {t:'立夏',a:'陆游〔宋代〕',c:'赤帜插城扉，东君整驾归。\n泥新巢燕闹，花尽蜜蜂稀。\n槐柳阴初密，帘栊暑尚微。\n日斜汤沐罢，熟练试单衣。'},
    {t:'立夏前二日作',a:'陆游〔宋代〕',c:'晨起披衣出草堂，轩窗已自喜无凉。\n余春只有二三日，烂醉恨无千百场。\n芳草自随征路远，游丝不及客愁长。\n残红一片无寻处，分付年华与蜜房。'},
    {t:'立夏日忆京师诸弟',a:'韦应物〔唐代〕',c:'改序念芳辰，烦襟倦日永。\n夏木已成阴，公门昼恒静。\n长风始飘阁，叠云才吐岭。\n坐想离居人，还当惜徂景。'},
    {t:'利剑',a:'韩愈〔唐代〕',c:'利剑光耿耿，佩之使我无邪心。\n故人念我寡徒侣，持用赠我比知音。\n我心如冰剑如雪，不能刺谗夫，使我心腐剑锋折。\n决云中断开青天，噫！\n剑与我俱变化归黄泉。'},
    {t:'利州江潭作·感孕金轮所',a:'李商隐〔唐代〕',c:'神剑飞来不易销，碧潭珍重驻兰桡。\n自携明月移灯疾，欲就行云散锦遥。\n河伯轩窗通贝阙，水宫帷箔卷冰绡。\n他时燕脯无人寄，雨满空城蕙叶雕。'},
    {t:'利州南渡',a:'温庭筠〔唐代〕',c:'澹然空水带斜晖，曲岛苍茫接翠微。\n波上马嘶看棹去，柳边人歇待船归。\n数丛沙草群鸥散，万顷江田一鹭飞。\n谁解乘舟寻范蠡，五湖烟水独忘机。'},
    {t:'荔枝歌',a:'杨万里〔宋代〕',c:'粤犬吠雪非差事，粤人语冰夏虫似。\n北人冰雪作生涯，冰雪一窖活一家。\n帝城六月日卓午，市人如炊汗如雨。\n卖冰一声隔水来，行人未吃心眼开。\n甘霜甜雪如压蔗，年年窨子南山下。\n去年藏冰减工夫，山鬼失守嬉西湖。\n北风一夜动地恶，尽吹北冰作南雹。\n飞来岭外荔枝梢，绛衣朱裳红锦包。\n三危露珠冻寒泚，火伞烧林不成水。\n北人藏冰天夺之，却与南人销暑气。'},
    {t:'荔枝图序',a:'白居易〔唐代〕',c:'荔枝生巴峡间。树形团团如帷盖，叶如桂，冬青；华如橘，春荣；实如丹，夏熟。朵如葡萄，核如枇杷，壳如红缯，膜如紫绡，瓤肉莹白如冰雪，浆液甘酸如醴酪。大略如彼，其实过之。若离本枝，一日而色变，二日而香变，三日而味变，四五日外，色香味尽去矣。\n元和十五年夏，南宾守乐天，命工吏图而书之，盖为不识者与识而不及一二三日者云。'},
    {t:'荔枝香·甚处寻芳赏翠',a:'柳永〔宋代〕',c:'甚处寻芳赏翠，归去晚。缓步罗袜生尘，来绕琼筵看。金缕霞衣轻褪，似觉春游倦。遥认，众里盈盈好身段。\n拟回首，又伫立、帘帏畔。素脸红眉，时揭盖头微见。笑整金翘，一点芳心在娇眼。王孙空恁肠断。'},
    {t:'荔枝香近·歇指',a:'周邦彦〔宋代〕',c:'照水残红零乱，风唤去。尽日无无轻寒，帘底吹香雾。黄昏客枕无憀，细响当窗雨。看两两相依暮新乳。\n楼下水，渐绿遍、行舟浦。暮往朝来，心逐片帆轻举。何日迎门，小槛朱笼报鹦鹉。共剪西窗蜜炬。'},
    {t:'荔枝香近·歇指·第二',a:'周邦彦〔宋代〕',c:'夜来寒侵酒席，露微泫。舄履初会，香泽方薰。无端暗雨催人，但怪灯偏帘卷。回顾，始觉惊鸿去云远。\n大都世间，最苦唯聚散。到得春残，看即是、开离宴。细思别后，柳眼花须更谁剪。此怀何处逍遣。'},
    {t:'连理枝',a:'晏殊〔宋代〕',c:'绿树莺声老。金井生秋早。不寒不暖，裁衣按曲，天时正好。况兰堂逢著寿筵开，见炉香缥缈。\n组绣呈纤巧。歌舞夸妍妙。玉酒频倾，朱弦翠管，移宫易调。献金杯重叠祝长生，永逍遥奉道。'},
    {t:'连理枝·玉宇秋风至',a:'晏殊〔宋代〕',c:'玉宇秋风至。帘幕生凉气。朱槿巢开，红莲尚拆，芙蓉含蕊。送旧巢归燕拂高檐，见梧桐叶坠。\n嘉宴凌晨启。金鸭飘香细。凤竹鸾丝，清歌妙舞，尽呈游艺。愿百千遐寿此神仙，有年年岁岁。'},
    {t:'连雨独饮',a:'陶渊明〔魏晋〕',c:'运生会归尽，终古谓之然。\n世间有松乔，于今定何间。\n故老赠余酒，乃言饮得仙。\n试酌百情远，重觞忽忘天。\n天岂去此哉，任真无所先。\n云鹤有奇翼，八表须臾还。\n自我抱兹独，僶俛四十年。\n形骸久已化，心在复何言。'},
    {t:'连州腊日观莫徭猎西山',a:'刘禹锡〔唐代〕',c:'海天杀气薄，蛮军步伍嚣。林红叶尽变，原黑草初烧。\n围合繁钲息，禽兴大旆摇。张罗依道口，嗾犬上山腰。\n猜鹰虑奋迅，惊鹿时跼跳。瘴云四面起，腊雪半空消。\n箭头馀鹄血，鞍傍见雉翘。日暮还城邑，金笳发丽谯。'},
    {t:'莲',a:'杨万里〔宋代〕',c:'城中担上卖莲房，未抵西湖泛野航。\n旋折荷花剥莲子，露为风味月为香。'},
    {t:'莲花',a:'温庭筠〔唐代〕',c:'绿塘摇滟接星津，轧轧兰桡入白蘋。\n应为洛神波上袜，至今莲蕊有香尘。'},
    {t:'莲浦谣',a:'温庭筠〔唐代〕',c:'鸣桡轧轧溪溶溶，废绿平烟吴苑东。\n水清莲媚两相向，镜里见愁愁更红。\n白马金鞭大堤上，西江日夕多风浪。\n荷心有露似骊珠，不是真圆亦摇荡。'},
    {t:'涟上别王秀才',a:'高适〔唐代〕',c:'飘飖经远道，客思满穷秋。浩荡侧长涟，君行殊未休。\n崎岖山海侧，想像无前俦。何意照乘珠，忽悲欲暗投。\n东路方箫条，楚歌复悲愁。暮帆使人感，去鸟兼离忧。\n行矣当自爱，壮年莫悠悠。余亦从此辞，异乡难久留。\n赠言岂终极，慎勿滞沧洲。'},
    {t:'涟上题樊氏水亭',a:'高适〔唐代〕',c:'涟上非所趣，偶为世务牵。经时驻归棹，日夕对平川。\n莫论行子愁，且得主人贤。亭上酒初熟，厨中鱼每鲜。\n自说宦游来，因之居住偏。煮盐沧海曲，种稻长淮边。\n四时常晏如，百口无饥年。菱芋藩篱下，渔樵耳目前。\n异县少朋从，我行复迍邅。向不逢此君，孤舟已言旋。\n明日又分首，风涛还眇然。'},
    {t:'联句',a:'陶渊明〔魏晋〕',c:'鸿雁乘风飞，去去当何极？\n念彼腾居上，如何不叹息！\n虽欲腾九万，扶摇竞何力？\n远招王子徊，云驾庶可饬。\n顾侣正徘徊，离离翔天侧。\n霜露岂不切？务从忘爱翼。\n高柯擢条干，远眺同天色。\n思绝庆未看，徒使生迷惑。'},
    {t:'濂溪诗',a:'黄庭坚〔宋代〕',c:'溪毛秀兮水清，可饭羹兮濯缨，不渔民利兮又何有于名。\n弦琴兮觞酒，写溪声兮延五老以为寿。\n蝉蜕尘埃兮玉雪自清，听潺湲兮鉴澄明。\n激贪兮敦薄，非青蘋白鸥兮谁与同乐。\n津有舟兮荡有莲，胜日兮与客就闲。\n人闲拿音兮不知何处散发醉，高荷为盖兮倚芙蓉以当伎。\n霜清水寒兮舟著平沙，八方同宇兮云月为家。\n怀连城兮佩明月，鱼鸟亲人兮野老同社而争席。\n白云蒙头兮与南山为伍，非夫人攘臂兮谁余敢侮。'},
    {t:'恋绣衾·代题武桂卿扇',a:'张炎〔宋代〕',c:'一枝凉玉欹路尘。下瑶台、疑是梦云。怕趁取、西风去，被何人、拈住皱裙。\n温柔只在秋波里，这些儿、真个动心。再同饮、花前酒，莫都忘、今夜夜深。'},
    {t:'恋绣衾代题武桂卿扇',a:'张炎〔宋代〕',c:'一枝凉玉敧路尘。下瑶台、疑是梦云。怕趁取、西风去，被何人、拈住皱裙。\n温柔只在秋波里，这些儿、真个动心。再同饮、花前酒，莫都忘、今夜夜深。'},
    {t:'凉思',a:'李商隐〔唐代〕',c:'客去波平槛，蝉休露满枝。\n永怀当此节，倚立自移时。\n北斗兼春远，南陵寓使迟。\n天涯占梦数，疑误有新知。'},
    {t:'凉州词二首',a:'孟浩然〔唐代〕',c:'浑成紫檀金屑文，作得琵琶声上云。\n胡地迢迢三万里，那堪马上送明君。\n异方之乐令人悲，羌笛胡笳不用吹。\n坐看今夜关山月，思杀边城游侠儿。'},
    {t:'凉州词三首',a:'张籍〔唐代〕',c:'边城暮雨雁飞低，芦笋初生渐欲齐。\n无数铃声遥过碛，应驮白练到安西。\n古镇城门白碛开，胡兵往往傍沙堆。\n巡边使客行应早，欲问平安无使来。\n凤林关里水东流，白草黄榆六十秋。\n边将皆承主恩泽，无人解道取凉州。'},
    {t:'凉州词三首·其三',a:'张籍〔唐代〕',c:'凤林关里水东流，白草黄榆六十秋。\n边将皆承主恩泽，无人解道取凉州。'},
    {t:'凉州馆中与诸判官夜集',a:'岑参〔唐代〕',c:'弯弯月出挂城头，城头月出照凉州。\n凉州七里十万家，胡人半解弹琵琶。\n琵琶一曲肠堪断，风萧萧兮夜漫漫。\n河西幕中多故人，故人别来三五春。\n花门楼前见秋草，岂能贫贱相看老。\n一生大笑能几回，斗酒相逢须醉倒。'},
    {t:'凉州郊外游望',a:'王维〔唐代〕',c:'野老才三户，边村少四邻。\n婆娑依里社，箫鼓赛田神。\n洒酒浇刍狗，焚香拜木人。\n女巫纷屡舞，罗袜自生尘。'},
    {t:'凉州赛神',a:'王维〔唐代〕',c:'凉州城外少行人，百尺峰头望虏尘。\n健儿击鼓吹羌笛，共赛城东越骑神。'},
    {t:'梁甫吟',a:'佚名〔两汉〕',c:'步出齐城门，遥望荡阴里。\n里中墓三坟，累累正相似。\n问是谁家墓，田疆古冶子。\n力能排南山，又能绝地纪。\n一朝被谗言，二桃杀三士。\n谁能为此谋，相国齐晏子。'},
    {t:'梁公子',a:'李贺〔唐代〕',c:'风采出萧家，本是菖蒲花。\n南塘莲子熟，洗马走江沙。\n御笺银沫冷，长簟凤窠斜。\n种柳营中暗，题书赐馆娃。'},
    {t:'梁台古愁',a:'李贺〔唐代〕',c:'梁王台沼空中立，天河之水夜飞入。\n台前斗玉作蛟龙，绿粉扫天愁露湿。\n撞钟饮酒行射天，金虎蹙裘喷血斑。\n朝朝暮暮愁海翻，长绳系日乐当年。\n芙蓉凝红得秋色，兰脸别春啼脉脉。\n芦洲客雁报春来，寥落野篁秋漫白。'},
    {t:'梁王池亭宴序',a:'陈子昂〔唐代〕',c:'子昂少游白屋，未历朱门，闻王每之游，空怀春草；见公子之兴，每隔青霄。弋阳公座辟青轩，饰欢朱邸，金筵玉瑟，相邀北里之欢；明月琴樽，即对西园之赏。鄙人幽介，酒醴知惭，王子爱才，文章见许。白日已驰，欢娱难恃，平生之乐，其在兹乎！'},
    {t:'梁园歌送河南王说判官',a:'岑参〔唐代〕',c:'君不见梁孝王脩竹园，颓墙隐辚势仍存。娇娥曼脸成草蔓，罗帷珠帘空竹根。\n大梁一旦人代改，秋月春风不相待。池中几度雁新来，洲上千年鹤应在。\n梁园二月梨花飞，却似梁王雪下时。当时置酒延枚叟，肯料平台狐兔走。\n万事翻覆如浮云，昔人空在今人口。单父古来称宓生，祗今为政有吾兄。\n輶轩若过梁园道，应傍琴台闻政声。'},
    {t:'梁苑',a:'王昌龄〔唐代〕',c:'梁园秋竹古时烟，城外风悲欲暮天。\n万乘旌旗何处在，平台宾客有谁怜。'},
    {t:'梁州令',a:'晏几道〔宋代〕',c:'莫唱阳关曲。泪湿当年金缕。离歌自古最消魂，闻歌更在魂消处。\n南楼杨柳多情绪。不系行人住。人情却似飞絮。悠扬便逐春风去。'},
    {t:'梁州令·梦觉纱窗晓',a:'柳永〔宋代〕',c:'梦觉纱窗晓。残灯掩然空照。因何人事苦萦牵，离愁别恨，无限何时了。\n怜深定是心肠小。往往成烦恼。一生惆怅情多少。月不长圆，春色易为老。'},
    {t:'梁州令·莫唱阳关曲',a:'晏几道〔宋代〕',c:'莫唱阳关曲，\n泪湿当年金缕。\n离歌自古最消魂，\n闻歌更在消魂处。\n南楼杨柳多情绪，\n不系行人住。\n人情却似飞絮，\n悠扬便逐春风去。'},
    {t:'梁州梦',a:'元稹〔唐代〕',c:'是夜宿汉川驿，梦；与杓直、乐天然游曲江，兼入慈恩寺诸院，倏然而寤，则递乘及阶，邮使已传呼报晓矣。\n梦君然绕曲江头，也向慈恩院院游。\n亭吏呼人排去马，忽惊身在古梁州。'},
    {t:'两山间',a:'王安石〔宋代〕',c:'自予营北渚，数至两山间。\n临路爱山好，出山愁路难。\n山花如水净，山鸟与云闲。\n我欲抛山去，山仍劝我还。\n祗应身後冢，亦是眼中山。\n且复依山住，归鞍未可攀。'},
    {t:'两同心',a:'黄庭坚〔宋代〕',c:'秋水遥岑。妆淡情深。尽道教、心坚穿石，更说甚、官不容针。霎时间，雨散云归，无处追寻。\n小楼朱阁沈沈。一笑千金。你共人、女边著子，争知我、门里桃心。最难忘，小院回廊，月影花阴。'},
    {t:'两同心·楚乡春晚',a:'晏几道〔宋代〕',c:'楚乡春晚，似入仙源。拾翠处、闲在流水，踏青路、暗惹香尘。心心在，柳外青帘，花下朱门。\n对景且醉芳尊。莫话消魂。好意思、曾同明月，恶滋味、最是黄昏。相思处，一纸红笺，无限啼痕。'},
    {t:'两同心·嫩脸修蛾',a:'柳永〔宋代〕',c:'嫩脸修蛾，淡匀轻扫。最爱学、宫前梳妆，偏能做、文人谈笑。绮筵前、舞燕歌云，别有轻妙。\n饮散玉炉烟袅。洞房悄悄。锦帐里、低语偏浓，银烛下、细看俱好。那人人，昨夜分明，许伊偕老。'},
    {t:'两同心·伫立东风',a:'柳永〔宋代〕',c:'伫立东风，断魂南国。花光媚、春时琼楼，蟾彩迥、夜游香陌。忆当时、酒恋花迷，役损词客。\n别有眼长腰搦。痛怜深惜。鸳会阻、夕雨凄飞，锦书断、暮云凝碧。想别来，好景良时，也应相忆。'},
    {t:'列仙文·安度明',a:'孟郊〔唐代〕',c:'丹霞焕上清，八风鼓太和。回我神霄辇，遂造岭玉阿。\n咄嗟天地外，九围皆我家。上采白日精，下饮黄月华。\n灵观空无中，鹏路无间邪。顾见魏贤安，浊气伤汝和。\n勤研玄中思，道成更相过。'},
    {t:'列仙文·方诸青童君',a:'孟郊〔唐代〕',c:'大霞霏晨晖，元气无常形。玄辔飞霄外，八景乘高清。\n手把玉皇袂，携我晨中生。玄庭自嘉会，金书拆华名。\n贤女密所妍，相期洛水輧。'},
    {t:'列仙文·金母飞空歌',a:'孟郊〔唐代〕',c:'驾我八景舆，欻然入玉清。龙群拂霄上，虎旗摄朱兵。\n逍遥三弦际，万流无暂停。哀此去留会，劫尽天地倾。\n当寻无中景，不死亦不生。体彼自然道，寂观合大冥。\n南岳挺直干，玉英曜颖精。有任靡期事，无心自虚灵。\n嘉会绛河内，相与乐朱英。'},
    {t:'列仙文·清虚真人',a:'孟郊〔唐代〕',c:'欻驾空清虚，徘徊西华馆。琼轮旌晨抄，虎骑逐烟散。\n惠风振丹旌，明烛朗八焕。解襟墉房内，神铃鸣璀璨。\n栖景若林柯，九弦空中弹。遗我积世忧，释此千载叹。\n怡眄无极已，终夜复待旦。'},
    {t:'烈女操',a:'孟郊〔唐代〕',c:'梧桐相待老，鸳鸯会双死。\n贞女贵殉夫，舍生亦如此。\n波澜誓不起，妾心古井水。'},
    {t:'邻妇哭征夫',a:'张籍〔唐代〕',c:'双鬟初合便分离，万里征夫不得随。\n今日军回身独殁，去时鞍马别人骑。'},
    {t:'邻女',a:'白居易〔唐代〕',c:'娉婷十五胜天仙，白日姮娥旱地莲。\n何处闲教鹦鹉语，碧纱窗下绣床前。'},
    {t:'林附祖',a:'文天祥〔宋代〕',c:'画影图形正捕风，书生薄命入置中。\n胡儿一似冬烘眼，错认颜标作鲁公。'},
    {t:'林琴南敬师',a:'佚名〔清代〕',c:'闽县林琴南孝廉纾六七岁时，从师读。师贫甚，炊不得米。林知之，亟归，以袜实米，满之，负以致师。师怒，谓其窃，却弗受。林归以告母，母笑曰：“若心固善，然此岂束修之礼？”即呼备，赍米一石致之塾，师乃受。'},
    {t:'林亭咏',a:'张九龄〔唐代〕',c:'穿筑非求丽，幽闲欲寄情。偶怀因壤石，真意在蓬瀛。\n苔益山文古，池添竹气清。从兹果萧散，无事亦无营。'},
    {t:'林亭寓言',a:'张九龄〔唐代〕',c:'林居逢岁晏，遇物使情多。蘅茝不时与，芬荣奈汝何。\n更怜篱下菊，无如松上萝。因依自有命，非是隔阳和。'},
    {t:'林卧',a:'岑参〔唐代〕',c:'偶得鱼鸟趣，复兹水木凉。\n远峰带雨色，落日摇川光。\n臼中西山药，袖里淮南方。\n唯爱隐几时，独游无何乡。'},
    {t:'林园晚霁',a:'韦应物〔唐代〕',c:'雨歇见青山，落日照林园。山多烟鸟乱，林清风景翻。\n提携唯子弟，萧散在琴言。同游不同意，耿耿独伤魂。\n寂寞钟已尽，如何还入门。'},
    {t:'临安春雨初霁',a:'陆游〔宋代〕',c:'世味年来薄似纱，谁令骑马客京华。\n小楼一夜听春雨，深巷明朝卖杏花。\n矮纸斜行闲作草，晴窗细乳戏分茶。\n素衣莫起风尘叹，犹及清明可到家。'},
    {t:'临池曲',a:'孟郊〔唐代〕',c:'池中春蒲叶如带，紫菱成角莲子大。\n罗裙蝉鬓倚迎风，双双伯劳飞向东。'},
    {t:'临发崇让宅紫薇',a:'李商隐〔唐代〕',c:'一树浓姿独看来，秋庭暮雨类轻埃。\n不先摇落应为有，已欲别离休更开。\n桃绶含情依露井，柳绵相忆隔章台。\n天涯地角同荣谢，岂要移根上苑栽。'},
    {t:'临泛东湖·时任洪州',a:'张九龄〔唐代〕',c:'郡庭日休暇，湖曲邀胜践。乐职旷中和，灵心挹上善。\n乘流坐清旷，举目眺悠缅。林与西山重，云无北风卷。\n晶明画不逮，阴影镜无辨。晚秀复芬敷，秋光更遥衍。\n万族纷可佳，一游岂能展。羁孤忝邦牧，顾己非时选。\n梁公世不容，长孺心亦褊。永念出笼絷，常思退疲蹇。\n岁徂风露严，日恐兰苕剪。佳辰不可得，良会何其鲜。\n罢兴还江城，闭关聊自遣。'},
    {t:'临皋闲题',a:'苏轼〔宋代〕',c:'临皋亭下八十数步，便是大江，皆半是峨眉雪水，吾饮食沐浴皆取焉，何必归乡哉！江山风月，子无常主，闲者便是主人。闻范子丰新第园池，与此孰胜？所不如者，上无两税及助役钱耳。'},
    {t:'临高台',a:'佚名〔两汉〕',c:'临高台以轩，下有清水清且寒。\n江有香草目以兰，黄鹄高飞离哉翻。\n关弓射鹄，令我主寿万年。'},
    {t:'临高台送黎拾遗',a:'王维〔唐代〕',c:'相送临高台，川原杳何极。\n日暮飞鸟还，行人去不息。'},
    {t:'临河客舍呈狄明府兄留题县南楼',a:'岑参〔唐代〕',c:'黎阳城南雪正飞，黎阳渡头人女归。河边酒家堪寄宿，\n主人小女能缝衣。故人高卧黎阳县，一时三年不相见。\n邑中雨雪偏著时，隔河东郡人遥羡。邺都唯见古时丘，\n漳水还如旧日流。城上望乡应不见，朝来好是懒登楼。'},
    {t:'临湖亭',a:'王维〔唐代〕',c:'轻舸迎上客，悠悠湖上来。\n当轩对尊酒，四面芙蓉开。'},
    {t:'临涣裴明府席遇张十一、房六',a:'孟浩然〔唐代〕',c:'河县柳林边，河桥晚泊船。文叨才子会，官喜故人连。\n笑语同今夕，轻肥异往年。晨风理归棹，吴楚各依然。'},
    {t:'临江军',a:'文天祥〔宋代〕',c:'江岸今多啮，城居昔屡焚。\n市人半伧父，竖子亦将军。\n蛟哭金洲雨，猿啼玉观云。\n周郎坟土上，回首泪成痕。'},
    {t:'临江王节士歌',a:'李白〔唐代〕',c:'洞庭白波木叶稀，燕鸿始入吴云飞。\n吴云寒，燕鸿苦。\n风号沙宿潇湘浦，节士悲秋泪如雨。\n白日当天心，照之可以事明主。\n壮士愤，雄风生。\n安得倚天剑，跨海斩长鲸。'},
    {t:'临江仙',a:'秦观〔宋代〕',c:'客路光阴浑草草，等闲过了元鸟。村鸡啼月下林梢。鸾声惊宿鸟，霜气入重貂。\n漠漠风沙千里暗，举头一望魂消。问君何事不辞劳。平生经世意，只恐负清朝。'},
    {t:'临江仙',a:'辛弃疾〔宋代〕',c:'手捻黄花无意绪，等闲行尽回鸭。卷帘芳桂散余香。枯荷难睡鸭，疏雨暗池塘。\n忆得旧时携手处，如今水远山长。罗巾浥泪别残妆。旧欢新梦里，闲处却思量。'},
    {t:'临江仙·淡水三年欢意',a:'晏几道〔宋代〕',c:'淡水三年欢意，危弦几夜离情。秋霜红叶舞归程。客情今古道，秋梦短长亭。\n渌酒尊前清泪，阳关叠里离声。少陵诗思旧才名。云鸿相约处，烟雾九重城。'},
    {t:'临江仙·点滴芭蕉心欲碎',a:'纳兰性德〔清代〕',c:'点滴芭蕉心欲碎，声声催忆当初。欲眠还展旧时书。鸳鸯小字，犹记手生疏。\n倦眼乍低缃帙乱，重看一半模糊。幽窗冷雨一灯孤。料应情尽，还道有情无？'},
    {t:'临江仙·东野亡来无丽句',a:'晏几道〔宋代〕',c:'东野亡来无丽句，于君去后少交亲。追思往事好沾巾。白头王建在，犹见咏诗人。\n学道深山空自老，留名千载不干身。酒筵歌席莫辞频。争如南陌上，占取一年春。'},
    {t:'临江仙·冬夜夜寒冰合井',a:'苏轼〔宋代〕',c:'冬夜夜寒冰合井，画堂明月侵帏。青缸明灭照悲啼。青缸挑欲尽，粉泪裛还垂。\n未尽一尊先掩泪，歌声半带清悲。情声两尽莫相违。欲知肠断处，梁上暗尘飞。'},
    {t:'临江仙·斗草阶前初见',a:'晏几道〔宋代〕',c:'斗草阶前初见，穿针楼上曾逢。罗裙香露玉钗风。靓妆眉沁绿，羞脸粉生红。\n流水便随春远，行云终与谁同。酒醒长恨锦屏空。相寻梦里路，飞雨落花中。'},
    {t:'临江仙·二之二',a:'秦观〔宋代〕',c:'髻子偎人娇不整，眼儿失睡微重。寻思模样早心忪。断肠携手，何事太匆匆。\n不忍残红犹在臂，翻疑梦里相逢。遥怜南埭上孤篷。夕阳流水，红满泪痕中。'},
    {t:'临江仙·风水洞作',a:'苏轼〔宋代〕',c:'四大从来都遍满，此间风水何谷。故应为我发新诗。幽花香涧谷，寒藻舞沦漪。\n借与玉川生两腋，天仙未必相思。还凭流水送人归。层巅余落日，草露已沾衣。'},
    {t:'临江仙·孤雁',a:'纳兰性德〔清代〕',c:'霜冷离鸿惊失伴，有人同病相怜。拟凭尺素寄愁边，愁多书屡易，双泪落灯前。\n莫对月明思往事，也知消减年年。无端嘹唳一声传，西风吹只影，刚是早秋天。'},
    {t:'临江仙·寒柳',a:'纳兰性德〔清代〕',c:'飞絮飞花何处是，层冰积雪摧好。疏疏一树五更寒。爱他明月好，憔悴也相关。\n最是繁丝摇落后，转教人忆春山。湔裙梦断续应难。西风多少恨，吹不散眉弯。'},
    {t:'临江仙·和叶仲洽赋羊桃',a:'辛弃疾〔宋代〕',c:'忆醉三山芳树下，几曾风韵忘熟。黄金颜色五花开，味如卢橘熟。贵似荔枝来。\n闻道商山余四老，橘中自酿秋醅。试呼名品细推排。重重香腑脏，偏殢圣贤杯。'},
    {t:'临江仙·怀辰州教授赵学舟',a:'张炎〔宋代〕',c:'一点白鸥何处去，半江潮落沙虚。淡黄柳上月痕初。遐观情悄悄，凝想步徐徐。\n每一相思千里梦，十年有此相疏。休休寄雁问何如。如何休寄雁，难写绝交书。'},
    {t:'临江仙·惠州改前韵',a:'苏轼〔宋代〕',c:'九十日春都过了，贪忙何处追游。三分春色一分愁。雨翻榆荚阵，风转柳花球。\n我与使君皆白首，休夸年少风流。佳人斜倚合江楼，水光都眼净，山色总眉愁。'},
    {t:'临江仙·即席和韩南涧韵',a:'辛弃疾〔宋代〕',c:'风雨催春寒食近，平原一片丹乱。溪边唤渡柳边行。花飞蝴蝶乱，桑嫩野蚕生。\n绿野先生闲袖手，却寻诗酒功名。未知明日定阴晴。今宵成独醉，却笑众人醒。'},
    {t:'临江仙·疾愈登望湖楼赠项长官',a:'苏轼〔宋代〕',c:'多病休文都瘦损，不堪金带垂腰。望湖楼上暗香飘。和风春弄袖，明月夜闻箫。\n酒醒梦回清漏永，隐床无限更潮。佳人不见董娇饶。徘徊花上月，空度可怜宵。'},
    {t:'临江仙·寄严荪友',a:'纳兰性德〔清代〕',c:'别后闲情何所寄，初莺早雁相思。如今憔悴异当时，飘零心事，残月落花知。\n生小不知江上路，分明却到梁溪。匆匆刚欲话分携，香消梦冷，窗白一声鸡。'},
    {t:'临江仙·翦翦春水出万壑',a:'张炎〔宋代〕',c:'翦翦春水出万壑，和春带出芳丛。谁分弱水洗尘红。低回金叵罗，约略玉玲珑。昨夜洞庭云一片，朗吟飞过天风。戏将瑶草散虚空。灵根何处觅，只在此山中。'},
    {t:'临江仙·金谷无烟宫树绿',a:'辛弃疾〔宋代〕',c:'金谷无烟宫树绿，嫩寒生怕春风。博山微透暖薰笼。小楼春色里，幽梦雨声中。\n别浦鲤鱼何日到，锦书封恨重重。海棠花下去年逢。也应随分瘦，忍泪觅残红。'},
    {t:'临江仙·看花',a:'秦观〔宋代〕',c:'为爱西庄花满树，朝朝来扣柴所。墙头遥见簇红云。恍然迷处所，疑入武陵源。\n花外飞来寒食雨，一时留住游人。村醪随意两三巡。折花头上戴，记取一年春。'},
    {t:'临江仙·老去浑身无著处',a:'辛弃疾〔宋代〕',c:'老去浑身无著处，天教只住山息。百年光景百年心。更欢须叹息，无病也呻吟。\n试向浮瓜沈李处，清风散发披襟。莫嫌浅后更频斟。要他诗句好，须是酒杯深。'},
    {t:'临江仙·离果州作',a:'陆游〔宋代〕',c:'鸠雨催成新绿，燕泥收尽残红。分光还与美人同。论心空眷眷，分袂却匆匆。\n只道真情易写，那知怨句难工。水流云散各西东。半廊花院月，一帽柳桥风。'},
    {t:'临江仙·六曲阑干三夜雨',a:'纳兰性德〔清代〕',c:'塞上得家报云秋海棠开矣，赋此。\n六曲阑干三夜雨，倩谁护取娇慵。可怜寂寞粉墙东，已分裙钗绿，犹裹泪绡红。\n曾记鬓边斜落下，半床凉月惺忪。旧欢如在梦魂中，自然肠欲断，何必更秋风。'},
    {t:'临江仙·梦后楼台高锁',a:'晏几道〔宋代〕',c:'梦后楼台高锁，酒醒帘幕低垂。去年春恨却来时。落花人独立，微雨燕双飞。\n记得小蘋初见，两重心字罗衣。琵琶弦上说相思。当时明月在，曾照彩云归。'},
    {t:'临江仙·梦觉小庭院',a:'柳永〔宋代〕',c:'梦觉小庭院，冷风淅淅，疏雨潇潇。绮窗外，秋声败叶狂飘。心摇。奈寒漏永，孤帏悄，泪烛空烧。无端处，是绣衾鸳枕，闲过清宵。\n萧条。牵情系恨，争向年少偏饶。觉新来、憔悴旧日风标。魂消。念欢娱事，烟波阻、后约方遥。还经岁，问怎生禁得，如许无聊。'},
    {t:'临江仙·鸣珂碎撼都门',a:'柳永〔宋代〕',c:'鸣珂碎撼都门晓，旌幢拥下天人。马摇金辔破香尘。壶浆\n盈路，欢动一城春。\n扬州曾是追游地，酒台花径仍存。凤箫依旧月中闻。荆王\n魂梦，应认岭头云。'},
    {t:'临江仙·千里潇湘挼蓝浦',a:'秦观〔宋代〕',c:'千里潇湘挼蓝浦，兰桡昔日曾经。月高风定露华清。微波澄不动，冷浸一天星。\n独倚危樯情悄悄，遥闻妃瑟泠泠。新声含尽古今情。曲终人不见，江上数峰青。'},
    {t:'临江仙·浅浅余寒春半',a:'晏几道〔宋代〕',c:'浅浅余寒春半，雪消蕙草初长。烟迷柳岸旧池塘。风吹梅蕊闹，雨细杏花香。\n月堕枝头欢意，从前虚梦高唐，觉来何处放思量。如今不是梦，真个到伊行。'},
    {t:'临江仙·壬戌岁生日书怀',a:'辛弃疾〔宋代〕',c:'六十三年无限事，从头悔恨难追。已知六十二年非。只应今日是，后日又寻思。\n少是多非惟有酒，何须过后方知。从今休似去年时。病中留客饮，醉里和人诗。'},
    {t:'临江仙·手拈黄花无意绪',a:'辛弃疾〔宋代〕',c:'手拈黄花无意绪，等闲行尽回鸭。卷帘芳桂散余香。枯荷难睡鸭，疏雨暗池塘。\n忆得旧时携手处，如今水远山长。罗巾浥泪别残妆。旧欢新梦里，闲处却思量。'},
    {t:'临江仙·手种门前乌桕树',a:'辛弃疾〔宋代〕',c:'手种门前乌桕树，而今千尺苍苍。田园只是旧耕桑。杯盘风月夜，箫鼓子孙忙。七十五年无事客，不妨两鬓如霜。绿窗剗地调红妆。更从今日醉，三万六千场。'},
    {t:'临江仙·丝雨如尘云著水',a:'纳兰性德〔清代〕',c:'丝雨如尘云著水，嫣香碎拾吴散。百花冷暖避东风。酷怜娇易散，燕子学偎红。\n人说病宜随月减，恹恹却与春同。可能留蝶抱花丛。不成双梦影，翻笑杏梁空。'},
    {t:'临江仙·送钱穆父',a:'苏轼〔宋代〕',c:'一别都门三改火，天涯踏尽红尘。依然一笑作春温。无波真古井，有节是秋筠。\n惆怅孤帆连夜发，送行淡月微云。尊前不用翠眉颦。人生如逆旅，我亦是行人。'},
    {t:'临江仙·送王缄',a:'苏轼〔宋代〕',c:'忘却成都来十载，因君未免思量。凭将清泪洒江阳。故山知好在，孤客自悲凉。\n坐上别愁君未见，归来欲断无肠。殷勤且更尽离觞。此身如传舍，何处是吾乡。'},
    {t:'临江仙·太白挂巾手卷',a:'张炎〔宋代〕',c:'忆得沈香歌断后，深宫客梦迢自。研池残墨溅花妖。青山人独自，早不侣渔樵。\n石壁苍寒巾尚挂，松风顶上飘飘。神仙那肯混尘嚣。诗魂元在此，空向水中招。'},
    {t:'临江仙·探梅',a:'辛弃疾〔宋代〕',c:'老去惜花心已懒，爱梅犹绕江村。一枝先破玉溪春。更无花态度，全有雪精神。\n剩向空山餐秀色，为渠著句清新。竹根流水带溪云。醉中浑不记，归路月黄昏。'},
    {t:'临江仙·谢饷樱桃',a:'纳兰性德〔清代〕',c:'绿叶成阴春尽也，守宫偏护泪泪。留将颜色慰多情。分明千点泪，贮作玉壶冰。\n独卧文园方病渴，强拈红豆酬卿。感卿珍重报流莺。惜花须自爱，休只为花疼。'},
    {t:'临江仙·夜到扬州席上作',a:'苏轼〔宋代〕',c:'尊酒何人怀李白，草堂遥指江东。珠帘十里卷香风。花开又花谢，离恨几千重。\n轻舸渡江连夜到，一时惊笑衰容。语音犹自带吴侬。夜阑对酒处，依旧梦魂中。'},
    {t:'临江仙·夜归临皋',a:'苏轼〔宋代〕',c:'夜饮东坡醒复醉，归来仿佛三应。家童鼻息已雷鸣。敲门都不应，倚杖听江声。\n长恨此身非我有，何时忘却营营。夜阑风静縠纹平。小舟从此逝，江海寄余生。'},
    {t:'临江仙·旖旎仙花解语',a:'晏几道〔宋代〕',c:'旖旎仙花解语，轻盈春柳能眠。玉楼深处绮窗前。梦回芳草夜，歌罢落梅天。\n沉水浓熏绣被。流霞浅酌金船。绿娇红小正堪怜。莫如云易散，须似月频圆。'},
    {t:'临江仙·永平道中',a:'纳兰性德〔清代〕',c:'独客单衾谁念我，晓来凉雨禁禁。缄书欲寄又还休，个侬憔悴，禁得更添愁。\n曾记年年三月病，而今病向深秋。庐龙风景白人头，药炉烟里，支枕听河流。'},
    {t:'临江仙·赠王友道',a:'苏轼〔宋代〕',c:'谁道东阳都瘦损，凝然点漆精氅。瑶林终自隔风尘。试看披鹤氅，仍是谪仙人。\n省可清言挥玉尘，真须保器全真。风流何似道家纯。不应同蜀客，惟爱卓文君。'},
    {t:'临江仙·长爱碧栏干影',a:'晏几道〔宋代〕',c:'长爱碧栏干影，芙蓉秋水开时。\n脸红凝露学娇啼。\n霞觞熏冷艳，云髻袅纤枝。\n烟雨依前时候，霜丛如旧芳菲。\n与谁同醉采香归。\n去年花下客，今似蝶分飞。'},
    {t:'临江仙·长爱碧阑干影',a:'晏几道〔宋代〕',c:'长爱碧阑干影，芙蓉秋水开时。脸红凝露学娇啼。霞觞熏冷艳，云髻袅纤枝。\n烟雨依前时候，霜丛如旧芳菲。与谁同醉采香归。去年花下客，今似蝶分飞。'},
    {t:'临江仙·长记碧纱窗外语',a:'纳兰性德〔清代〕',c:'长记碧纱窗外语，秋风吹送归鸦。片帆从此寄天涯。一灯新睡觉，思梦月初斜。\n便是欲归归未得，不如燕子还家。春云春水带轻霞。画船人似月，细雨落杨花。'},
    {t:'临江仙·资善堂中三十载',a:'晏殊〔宋代〕',c:'资善堂中三十载，旧人多是凋零。与君相见最伤情。一尊如旧，聊且话平生。\n此别要知须强饮，雪残风细长亭。待君归觐九重城。帝宸思旧，朝夕奉皇明。'},
    {t:'临江仙·昨夜渡江何处宿',a:'苏轼〔宋代〕',c:'昨夜渡江何处宿，望中疑是秦淮。月明谁起笛中哀。多情王谢女，相逐过江来。\n云雨未成还又散，思量好事难谐。凭陵急桨两相催。想伊归去后，应似我情怀。'},
    {t:'临江仙·昨夜个人曾有约',a:'纳兰性德〔清代〕',c:'昨夜个人曾有约，严城玉漏三寝。一钩新月几疏星。夜阑犹未寝，人静鼠窥灯。\n原是瞿唐风间阻，错教人恨无情。小阑干外寂无声。几回肠断处，风动护花铃。'},
    {t:'临江仙其四',a:'晏几道〔宋代〕',c:'浅浅馀寒春半，雪消蕙草初长。烟迷柳岸旧池塘。\n风吹梅蕊闹，雨细杏花香。\n月堕枝头欢意，从前虚梦高唐。觉来何处放思量。\n如今不是梦，真个到伊行。'},
    {t:'临江仙引·渡口',a:'柳永〔宋代〕',c:'渡口、向晚，乘瘦马、陟平冈。西郊又送秋光。对暮山横翠，衬残叶飘黄。凭高念远，素景楚天，无处不凄凉。\n香闺别来无信息，云愁雨恨难忘。指帝城归路，但烟水茫茫。凝情望断泪眼，尽日独立斜阳。'},
    {t:'临江仙引·画舸',a:'柳永〔宋代〕',c:'画舸、荡桨，随浪前，隔岸虹。枯荷点断秋容。疑水仙游泳，向别浦相逢。鲛丝雾吐渐收，细腰无力转娇慵。\n罗袜凌波成旧恨，有谁更赋惊鸿。想媚魂杳信，算密锁瑶宫。游人漫劳倦去，奈何不逐东风。'},
    {t:'临江仙引·上国',a:'柳永〔宋代〕',c:'上国。去客。停飞盖、促离筵。长安古道绵绵。见岸花啼露，对堤柳愁烟。物情人意，向此触目，无处不凄然。\n醉拥征骖犹伫立，盈盈泪眼相看。况绣帏人静，更山馆春寒。今宵怎向漏永，顿成两处孤眠。'},
    {t:'临江之麋',a:'柳宗元〔唐代〕',c:'临江之人，畋得麋麑，畜之。入门，群犬垂涎，扬尾皆来。其人怒。怛之。自是日抱就犬，习示之，使勿动，稍使与之戏。积久，犬皆如人意。麋麑稍大，忘己之麋也，以为犬良我友，抵触偃仆，益狎。犬畏主人，与之俯仰甚善，然时啖其舌。三年，麋出门，见外犬在道甚众，走欲与为戏。外犬见而喜且怒，共食之，狼藉道上。麋至死不悟。'},
    {t:'临津',a:'王安石〔宋代〕',c:'临津艳艳花千树，夹径斜斜柳数行。\n却忆金明池上路，红裙争看绿衣郎。'},
    {t:'临终歌',a:'李白〔唐代〕',c:'大鹏飞兮振八裔，中天摧兮力不济。\n馀风激兮万世，游扶桑兮挂左袂。\n后人得之传此，仲尼亡兮谁为出涕。'},
    {t:'凛凛岁云暮',a:'佚名〔两汉〕',c:'凛凛岁云暮，蝼蛄夕鸣悲。\n凉风浦已厉，游子寒无衣。\n锦衾遗洛浦，同袍与我违。\n独宿累长夜，梦前见容辉。\n良人惟古欢，枉驾惠前绥。\n愿得常巧笑，携手同车归。\n既来不须臾，又不处重闱。\n亮无晨风翼，焉能凌风飞？\n眄睐以适意，引领遥相睎。\n徙倚怀感伤，垂涕沾双扉。'},
    {t:'灵都观李道士',a:'张籍〔唐代〕',c:'仙观雨来静，绕房琼草春。素书天上字，花洞古时人。\n泥灶煮灵液，扫坛朝玉真。几回游阆苑，青节亦随身。'},
    {t:'灵云池送从弟',a:'王维〔唐代〕',c:'金杯缓酌清歌转，画舸轻移艳舞回。\n自叹鶺鴒临水别，不同鸿雁向池来。'},
    {t:'玲珑四犯·大石',a:'周邦彦〔宋代〕',c:'秾李夭桃，是旧日潘郎，亲试春艳。自别河阳，长负露房烟脸。憔悴鬓点吴霜，细念想梦魂飞乱。叹画阑玉砌都换。才始有缘重见。\n夜深偷展香罗荐。暗窗前、醉眠葱蒨。浮花浪蕊都相识，谁更曾抬眼。休问旧色旧香，但认取、芳心一点。又片时一阵，风雨恶，吹分散。'},
    {t:'凌雾行',a:'韦应物〔唐代〕',c:'秋城海雾重，职事凌晨出。\n浩浩合元天，溶溶迷朗日。\n才看含鬓白，稍视沾衣密。\n道骑全不分，郊树都如失。\n霏微误嘘吸，肤腠生寒栗。\n归当饮一杯，庶用蠲斯疾。'},
    {t:'零陵春望',a:'柳宗元〔唐代〕',c:'平野春草绿，晓莺啼远林。\n日晴潇湘渚，云断岣嵝岑。\n仙驾不可望，世途非所任。\n凝情空景慕，万里苍梧阴。'},
    {t:'零陵早春',a:'柳宗元〔唐代〕',c:'问春从此去，几日到秦原。\n凭寄还乡梦，殷勤入故园。'},
    {t:'零陵赠李卿元侍御简吴武陵',a:'柳宗元〔唐代〕',c:'理世固轻士，弃捐湘之湄。\n阳光竟四溟，敲石安所施。\n铩羽集枯干，低昂互鸣悲。\n朔云吐风寒，寂历穷秋时。\n君子尚容与，小人守兢危。\n惨凄日相视，离忧坐自滋。\n樽酒聊可酌，放歌谅徒为。\n惜无协律者，窈眇弦吾诗。'},
    {t:'岭表逢故人',a:'张籍〔唐代〕',c:'过岭万馀里，旅游经此稀。相逢去家远，共说几时归。\n海上见花发，瘴中唯鸟飞。炎州望乡伴，自识北人衣。'},
    {t:'岭南江行',a:'柳宗元〔唐代〕',c:'瘴江南去入云烟，望尽黄茆是海边。\n山腹雨晴添象迹，潭心日暖长蛟涎。\n射工巧伺游人影，飓母偏惊旅客船。\n从此忧来非一事，岂容华发待流年。'},
    {t:'岭云',a:'杨万里〔宋代〕',c:'好山幸自绿崭崭，须把轻云护浅岚。\n天女似怜山骨瘦，为缝雾縠作春衫。'},
    {t:'令狐八拾遗见招送裴十四归华州',a:'李商隐〔唐代〕',c:'二十中郎未足希，骊驹先自有光辉。\n兰亭宴罢方回去，雪夜诗成道韫归。\n汉苑风烟吹客梦，云台洞穴接郊扉。\n嗟予久抱临邛渴，便欲因君问钓矶。'},
    {t:'刘、阮妻二首',a:'元稹〔唐代〕',c:'仙洞千年一度闲，等闲沉入又沉回。\n桃花飞尽东风起，何处消沉去不来。\n芙蓉脂肉绿云鬟，罨画楼台青黛山。\n千树桃花万年药，不知何事忆人间。'},
    {t:'刘邦直送早梅水仙花四首',a:'黄庭坚〔宋代〕',c:'簸船綪缆北风嗔，霜落千林憔悴人。\n欲问江南近消息，喜君贻我一枝春。'},
    {t:'刘兵曹赠酒',a:'张籍〔唐代〕',c:'一瓶颜色似甘泉，闲向新栽小竹前。\n饮罢身中更无事，移床独就夕阳眠。'},
    {t:'刘道士赠小葫芦',a:'陆游〔宋代〕',c:'葫芦虽小藏天地，伴我云云万里身。\n收起鬼神窥不见，用时能与物为春。'},
    {t:'刘驸马水亭避暑',a:'刘禹锡〔唐代〕',c:'千竿竹翠数莲红，水阁虚凉玉莹空。琥珀盏红疑漏酒，\n水晶帘莹更通风。赐冰满碗沉朱实，法馔盈盘覆碧笼。\n尽日逍遥避烦暑，再三珍重主人翁。'},
    {t:'刘九法曹郑瑕丘石门宴集',a:'杜甫〔唐代〕',c:'秋水清无底，萧然净客心。\n掾曹乘逸兴，鞍马到荒林。\n能吏逢联璧，华筵直一金。\n晚来横吹好，泓下亦龙吟。'},
    {t:'刘琨',a:'文天祥〔宋代〕',c:'中原荡分崩，壮哉刘越石。\n连踪起幽并，只手扶晋室。\n福华天意乘，匹磾生鬼蜮。\n公死百世名，天下分南北。'},
    {t:'刘相公中书江山画障',a:'岑参〔唐代〕',c:'相府征墨妙，挥毫天地穷。始知间青笔，能夺造化功。\n潇湘在帘间，庐壑横座中。忽疑凤凰池，暗际江海通。\n粉白湖上云，黛青天际峰。昼日恒见月，孤帆如有风。\n岩花不飞落，涧草无春冬。担锡香炉缁，钓鱼沧浪翁。\n如何平津意，尚想尘外踪。富贵心独轻，山林兴弥浓。\n喧幽趣颇异，出处事不同。请君为苍生，未可追赤松。'},
    {t:'留别',a:'王昌龄〔唐代〕',c:'秦林映陂水，雨过宛城西。\n留醉楚山别，阴云暮凄凄。'},
    {t:'留别岑参兄弟',a:'王昌龄〔唐代〕',c:'江城建业楼，山尽沧海头。副职守兹县，东南棹孤舟。\n长安故人宅，秣马经前秋。便以风雪暮，还为纵饮留。\n貂蝉七叶贵，鸿鹄万里游。何必念钟鼎，所在烹肥牛。\n为君啸一曲，且莫弹箜篌。徒见枯者艳，谁言直如钩。\n岑家双琼树，腾光难为俦。谁言青门悲，俯期吴山幽。\n日西石门峤，月吐金陵洲。追随探灵怪，岂不骄王侯。'},
    {t:'留别广陵诸公',a:'李白〔唐代〕',c:'忆昔作少年，结交赵与燕。\n金羁络骏马，锦带横龙泉。\n寸心无疑事，所向非徒然。\n晚节觉此疏，猎精草太玄。\n空名束壮士，薄俗弃高贤。\n中回圣明顾，挥翰凌云烟。\n骑虎不敢下，攀龙忽堕天。\n还家守清真，孤洁励秋蝉。\n炼丹费火石，采药穷山川。\n卧海不关人，租税辽东田。\n乘兴忽复起，棹歌溪中船。\n临醉谢葛强，山公欲倒鞭。\n狂歌自此别，垂钓沧浪前。'},
    {t:'留别郭八',a:'王昌龄〔唐代〕',c:'长亭驻马未能前，井邑苍茫含暮烟。\n醉别何须更惆怅，回头不语但垂鞭。'},
    {t:'留别江陵王少府',a:'张籍〔唐代〕',c:'迢迢山上路，病客独行迟。况此分手处，当君失意时。\n寒林远路驿，晚烧过荒陂。别后空回首，相逢未有期。'},
    {t:'留别平闍黎',a:'秦观〔宋代〕',c:'缘尽山城且不归，此生相见了无期。\n保持异日莲花上，重说如今结社时。'},
    {t:'留别钱起',a:'王维〔唐代〕',c:'卑栖却得性，每与白云归。\n徇禄仍怀橘，看山免采薇。\n暮禽先去马，新月待开扉。\n霄汉时回首，知音青琐闱。'},
    {t:'留别丘为',a:'王维〔唐代〕',c:'归鞍白云外，缭绕出前山。\n今日又明日，自知心不闲。\n亲劳簪组送，欲趁莺花还。\n一步一回首，迟迟向近关。'},
    {t:'留别司马太守',a:'王昌龄〔唐代〕',c:'辰阳太守念王孙，远谪沅溪何可论。\n黄鹤青云当一举，明珠吐著报君恩。'},
    {t:'留别王侍御维',a:'孟浩然〔唐代〕',c:'寂寂竟何待，朝朝空自归。\n欲寻芳草去，惜与故人违。\n当路谁相假，知音世所稀。\n只应守寂寞，还掩故园扉。'},
    {t:'留别武陵袁丞',a:'王昌龄〔唐代〕',c:'皇恩暂迁谪，待罪逢知己。从此武陵溪，孤舟二千里。\n桃花遗古岸，金涧流春水。谁识马将军，忠贞抱生死。'},
    {t:'留别伊阙张少府郭大都尉',a:'王昌龄〔唐代〕',c:'迁客就一醉，主人空金罍。江湖识山底，欲去仍裴回。\n郭侯未相识，策马伊川来。把手相劝勉，不清老尘埃。\n孟阳逢山旧，仙馆留清才。日晚劝趣别，风长云逐开。\n幸随板舆远，负谴何忧哉。唯有仗忠信，音书报云雷。'},
    {t:'留别于十一兄逖裴十三游塞垣',a:'李白〔唐代〕',c:'太公渭川水，李斯上蔡门。\n钓周猎秦安黎元，小鱼鵕兔何足言？\n天张云卷有时节，吾徒莫叹羝触藩。\n于公白首大梁野，使人怅望何可论？\n即知朱亥为壮士，且愿束心秋毫里。\n秦赵虎争血中原，当去抱关救公子。\n裴生览千古，龙鸾炳天章。\n悲吟雨雪动林木，放书辍剑思高堂。\n劝尔一杯酒，拂尔裘上霜。\n尔为我楚舞，吾为尔楚歌。\n且探虎穴向沙漠，鸣鞭走马凌黄河。\n耻作易水别，临歧泪滂沱。'},
    {t:'留别郑三、韦九兼洛下诸公',a:'高适〔唐代〕',c:'忆昨相逢论久要，顾君哂我轻常调。羁旅虽同白社游，\n诗书已作青云料。蹇质蹉跎竟不成，年过四十尚躬耕。\n长歌达者杯中物，大笑前人身后名。幸逢明盛多招隐，\n高山大泽征求尽。此时亦得辞渔樵，青袍裹身荷圣朝。\n犁牛钓竿不复见，县人邑吏来相邀。远路鸣蝉秋兴发，\n华堂美酒离忧销。不知何日更携手，应念兹晨去折腰。'},
    {t:'留春令',a:'晏几道〔宋代〕',c:'采莲舟上，夜来陡觉，十分秋意。似恼寒花暂时香，与情浅、人相似。\n玉蕊歌清招晚醉。恋小桥风细。水湿红裙酒初消，又记得、南溪事。'},
    {t:'留春令',a:'晏几道〔宋代〕',c:'海棠风横，醉中吹落，香红强半。看粉多情怨花飞，仔细把、残香看。\n一抹深檀秋水畔。缕金衣新换。鹦鹉杯深艳歌迟，更莫放、人肠断。'},
    {t:'留春令·画屏天畔',a:'晏几道〔宋代〕',c:'画屏天畔，梦回依约，十洲云水。事捻红笺寄人书，写无限伤春事。\n别浦高楼曾漫倚。对江南千里。楼下分流水声中，有当日凭高泪。'},
    {t:'留弟郢不得送之江南',a:'孟郊〔唐代〕',c:'刚有下水船，白日留不得。老人独自归，苦泪满眼黑。'},
    {t:'留诲曹师等诗',a:'杜牧〔唐代〕',c:'万物有丑好，各一姿状分。\n唯人花不尔，学与不学论。\n学非探其花，要自拨其根。\n孝友与诚实，而不忘尔言。\n根本既深实，柯叶自滋繁。\n念尔无忽此，期以庆吾门。'},
    {t:'留客住·偶登眺',a:'柳永〔宋代〕',c:'偶登眺。凭小阑、艳阳时节，乍晴天气，是处闲花芳草。遥山万叠云散，涨海千里，潮平波浩渺。烟村院落，是谁家、绿树数声啼鸟。\n旅情悄。远信沉沉，离魂杳杳。对景伤怀，度日无言谁表。惆怅旧欢何处，后约难凭，看看春又老。盈盈泪眼，望仙乡、隐隐断霞残照。'},
    {t:'留题常熟顶山僧居',a:'范仲淹〔宋代〕',c:'平湖数百里，隐然一山起。\n中有白龙泉，可洗人间耳。\n吾师仁智心，爱兹山水音。\n结茅三十年，不道日月深。\n笑我名未已，来问无端理。\n却指岭边云，斯焉赠君子。'},
    {t:'留题方干处士旧居',a:'范仲淹〔宋代〕',c:'风雅先生旧隐存，子陵台下白云村。\n唐朝三百年冠盖，谁聚诗书到远孙。'},
    {t:'留题江秀才旧居',a:'范仲淹〔宋代〕',c:'结舍近沧洲，江山不外求。\n我来明月夜，更得主人留。'},
    {t:'留题麟州',a:'范仲淹〔宋代〕',c:'宣恩来到极西州，城下羌山隔水流。\n不见耕桑见烽火，愿封丞相富人侯。'},
    {t:'留题小隐山书室',a:'范仲淹〔宋代〕',c:'小径小桃深，红光隐翠阴。\n是非不到耳，名利本无心。\n笋迸饶当户，云归半在林。\n何须听丝竹，山水有清音。'},
    {t:'留题越州石氏山斋',a:'晏殊〔宋代〕',c:'书仙十阁壮儒宫，灵越山川实抛雄。\n岫柏亚香侵几席，岩花回影入帘栊。\n千秋碧锁东南竹，一水清含旦暮风。\n文酒雅宜频讌集，谢家兰玉有新丛。'},
    {t:'留题云门山雍熙院',a:'范仲淹〔宋代〕',c:'一路入岚堆，还惊禹凿开。\n林无恶兽住，岩有好泉来。\n云阵藏雷去，山根到海回。\n莫辞登绝顶，南望即天台。'},
    {t:'留萧伯和仲和小饮二首',a:'杨万里〔宋代〕',c:'谁曾白月上青天，谁羡千锺况万钱。\n要入诗家须有骨，若除酒外更无仙。\n三杯未必通大道，一斗真能出百篇。\n李杜饥寒才几日，却教富贵不论年。'},
    {t:'留远亭',a:'文天祥〔宋代〕',c:'甘心卖国罪滔天，酒后猖狂诈作颠。\n把酒逢迎酋虏笑，从头骂坐数时贤。\n落得称呼浪子刘，樽前百媚佞旃裘。\n当年鲍老不如此，留远亭前犬也羞。'},
    {t:'留赠',a:'杜牧〔唐代〕',c:'舞靴应任闲人看，笑脸还须待我开。\n不用镜前空有泪，蔷薇花谢即归来。'},
    {t:'流水',a:'黄庭坚〔宋代〕',c:'一溪之水，可涉而航。\n人不我直，我犹力行。\n一溪之水，不杠而涉。\n濡首中流，汝嗟何及。\n汤汤流水，可以休兮。\n嗟行之人，则濯足兮。'},
    {t:'流夜郎题葵叶',a:'李白〔唐代〕',c:'惭君能卫足，叹我远移根。\n白日如分照，还归守故园。'},
    {t:'流夜郎赠辛判官',a:'李白〔唐代〕',c:'昔在长安醉花柳，五侯七贵同杯酒。\n气岸遥凌豪士前，风流肯落他人后？\n夫子红颜我少年，章台走马著金鞭。\n文章献纳麒麟殿，歌舞淹留玳瑁筵。\n与君自谓长如此，宁知草动风尘起。\n函谷忽惊胡马来，秦宫桃李向明开。\n我愁远谪夜郎去，何日金鸡放赦回？'},
    {t:'流莺',a:'李商隐〔唐代〕',c:'流莺漂荡复参差，度陌临流不必持。\n巧啭岂能无本意？良辰未必有佳期。\n风朝露夜阴晴里，万户千门开闭时。\n曾苦伤春不忍听，凤城何处有花枝。'},
    {t:'柳',a:'李商隐〔唐代〕',c:'曾逐东风拂舞筵，乐游春苑断肠天。\n如何肯到清秋日，已带斜阳又带蝉。'},
    {t:'柳',a:'晏殊〔宋代〕',c:'河柳擅佳名，青条发红穗。\n因愁百卉娇，强作芳菲意。'},
    {t:'柳初新·东郊向晓星杓亚',a:'柳永〔宋代〕',c:'东郊向晓星杓亚。报帝里，春来也。柳抬烟眼。花匀露脸，渐觉绿娇红姹。妆点层台芳榭。运神功、丹青无价。\n别有尧阶试罢。新郎君、成行如画。杏园风细，桃花浪暖，竞喜羽迁鳞化。遍九陌、相将游冶。骤香尘、宝鞍骄马。'},
    {t:'柳花词三首',a:'刘禹锡〔唐代〕',c:'开从绿条上，散逐香风远。\n故取花落时，悠扬占春晚。\n轻飞不假风，轻落不委地。\n撩乱舞晴空，发人无限思。\n晴天闇闇雪，来送青春暮。\n无意似多情，千家万家去。'},
    {t:'柳绝句',a:'杜牧〔唐代〕',c:'数树新开翠影齐，倚风情态被春迷。\n依依故国樊川恨，半掩村桥半掩溪。'},
    {t:'柳林酒家小楼',a:'陆游〔宋代〕',c:'桃花如烧酒如油，缓辔郊原当出游。\n微倦放教成午梦，宿酲留得伴春愁。\n远途始悟乾坤大，晚节偏惊岁月遒。\n记取清明果州路，半天高柳小青楼。'},
    {t:'柳桥晚眺',a:'陆游〔宋代〕',c:'小浦闻鱼跃，横林待鹤归。\n闲云不成雨，故傍碧山飞。'},
    {t:'柳梢青·三山归途代白鸥见嘲',a:'辛弃疾〔宋代〕',c:'白鸟相迎，相怜相笑，满面尘埃。而发苍颜，去时曾劝，闻早归来。\n而今岂是高怀。为千里、莼羹计哉。好把移文，从今日日，读取千回。'},
    {t:'柳梢青·一夜凝寒',a:'张炎〔宋代〕',c:'一夜凝寒，忽成琼树，换却繁华。眼甚春深，片红不到，绿水人家。\n眼惊白昼天涯。空望断、尘香钿车。独立回风，不阑惆怅，莫是梨花。'},
    {t:'柳梢青·乙巳二月西兴赠别',a:'陆游〔宋代〕',c:'十载江湖，行歌沽酒，不到京华。凭事翩然，长亭烟草，衰鬓风沙。\n凭高目断天涯。细雨外、楼台万家。只恐明朝，一时不见，人共梅花。'},
    {t:'柳条边',a:'纳兰性德〔清代〕',c:'是处垣篱防绝塞，角端西来画筑界。\n汉使今行虎落中，秦城合筑龙荒外。\n龙荒虎落两依然，护得当时饮马泉。\n若使春风知别苦，不应吹到柳条边。'},
    {t:'柳絮',a:'刘禹锡〔唐代〕',c:'飘飏南陌起东邻，漠漠濛濛暗拂春。花巷暖随轻舞蝶，\n玉楼晴拂艳妆人。萦回谢女题诗笔，点缀陶公漉酒巾。\n何处好风偏似雪，隋河堤上古江津。'},
    {t:'柳腰轻·英英妙舞腰肢软',a:'柳永〔宋代〕',c:'英英妙舞腰肢软。章台柳、昭阳金。锦衣冠盖，绮堂筵会，是处千金争选。顾香砌、丝管初调，倚轻盈、佩环微颤。\n乍入霓裳促遍。逞盈盈、渐催檀板。慢垂霞袖，急趋莲步，进退奇容千变。算何止、倾国倾城，暂回眸、万人肠断。'},
    {t:'柳长句',a:'杜牧〔唐代〕',c:'日落水流西复东，春光不尽柳何穷。\n巫娥庙里低含雨，宋玉宅前斜带风。\n不嫌榆荚共争翠，深与桃花相映红。\n灞上汉南千万树，几人游宦别离中。'},
    {t:'柳枝词',a:'纳兰性德〔清代〕',c:'池上闲房碧树围，\n帘纹如彀上斜晖。\n生憎飞絮吹难定，\n一出红窗便不归。'},
    {t:'柳枝词二首·其一',a:'纳兰性德〔清代〕',c:'马卿苦忆红泥阁，我亦伤心碧树村。\n病骨沈绵词客死，更谁攀折与招魂？'},
    {t:'柳州城西北隅种柑树',a:'柳宗元〔唐代〕',c:'手种黄柑二百株，春来新叶遍州隅。\n方同楚客怜皇树，不学荆州利木奴。\n几岁开花闻喷雪，何人摘实见垂珠？\n若教坐待成林日，滋味还堪养老夫。'},
    {t:'柳州峒氓',a:'柳宗元〔唐代〕',c:'郡城南下接通津，异服殊音不饭亲。\n青箬裹盐归峒客，绿荷包饭趁虚人。\n鹅毛御腊缝山罽，鸡骨占年拜水神。\n愁向公庭问重译，欲投章甫作文身。'},
    {t:'柳州二月榕叶落尽偶题',a:'柳宗元〔唐代〕',c:'宦情羁思共凄凄，春半如秋意转迷。\n山城过雨百花尽，榕叶满庭莺乱啼。'},
    {t:'柳州寄京中亲故',a:'柳宗元〔唐代〕',c:'林邑山连瘴海秋，牂牁水向郡前流。\n劳君远问龙城地，正北三千到锦州。'},
    {t:'柳州寄丈人周韶州',a:'柳宗元〔唐代〕',c:'越绝孤城千万峰，空斋不语坐尘舂。\n印文生绿经旬合，砚匣留尘尽日封。\n梅岭寒烟藏翡翠，桂江秋水露鰅鳙。\n丈人本自忘机事，为想年来憔悴容。'},
    {t:'六丑·蔷薇谢后作',a:'周邦彦〔宋代〕',c:'正单衣试酒，怅客里、光阴虚掷。愿春暂留，春归如过翼。一去无迹。为问花何在，夜来风雨，葬楚宫倾国。钗钿堕处遗香泽。乱点桃蹊，轻翻柳陌。多情为谁追惜。但蜂媒蝶使，时叩窗隔。\n东园岑寂。渐蒙笼暗碧。静绕珍丛底，成叹息。长条故惹行客。似牵衣待话，别情无极。残英小、强簪巾帻。终不似一朵，钗头颤袅，向人欹侧。漂流处、莫趁潮汐。恐断红、尚有相思字，何由见得。'},
    {t:'六么令',a:'晏几道〔宋代〕',c:'日高春睡，唤起懒装束。年年落便时候，惯得娇眠足。学唱宫梅便好，更暖银笙逐。黛蛾低绿。堪东人恨，却似江南旧时曲。\n常记东楼夜雪，翠幕遮红烛。还是芳酒杯中，一醉光阴促。曾笑阳台梦短，无计怜香玉。此欢难续。乞求歌罢，借取归云画堂宿。'},
    {t:'六么令·雪残风信',a:'晏几道〔宋代〕',c:'雪残风信，悠扬春消息。天涯倚楼新恨，杨柳几丝碧。还是南云雁少，锦字无端的。宝钗瑶席。彩弦声里，拚作尊前未归客。\n遥想疏梅此际，月底香英白。别后谁绕前溪，手拣繁枝摘。莫道伤高恨远，付与临风笛。尽堪愁寂。花时往事，更有多情个人忆。'},
    {t:'六年',a:'王安石〔宋代〕',c:'六年湖海老侵寻，千里归来一寸心。\n西望国门搔短发，九天宫阙五云深。'},
    {t:'六年春遣怀八首其一',a:'元稹〔唐代〕',c:'伤禽我是笼中鹤，沈剑君为泉下龙。重纩犹存孤枕在，春衫无复旧裁缝。'},
    {t:'六幺令·淡烟残照',a:'柳永〔宋代〕',c:'淡烟残照，摇曳溪光碧。溪边浅桃深杏，迤逦染春色。昨夜扁舟泊处，枕底当滩碛。波声渔笛。惊回好梦，梦里欲归归不得。\n展转翻成无寐，因此伤行役。思念多媚多娇，咫尺千山隔。都为深情密爱，不忍轻离拆。好天良夕。鸳帷寂寞，算得也应暗相忆。'},
    {t:'六幺令·绿阴春尽',a:'晏几道〔宋代〕',c:'绿阴春尽，飞絮绕香阁。晚来翠未宫样，巧把远山学。一寸狂心未说，已向横波觉。画帘遮匝，新书曲妙，暗许闲人带偷掐。\n前度书多隐语，意浅愁难答。昨夜诗有回文，韵险还慵押。都待笙歌散了，记取来时霎。不消红蜡，闲云归后，月在庭花旧栏角。'},
    {t:'六幺令·天中节',a:'苏轼〔宋代〕',c:'虎符缠臂，佳节又端午。门前艾十青翠，天淡纸鸢舞。粽叶香飘十里，对酒携樽俎。龙舟争渡，助怀呐喊，凭吊祭江诵君赋。\n感叹怀王昏聩，悲戚秦吞楚。异客垂涕淫淫，鬓白知几许。朝夕新亭对泣，泪竭陵阳处。汨罗江渚，湘累已逝，惟有万千断肠句。'},
    {t:'六月',a:'李贺〔唐代〕',c:'裁生罗，伐湘竹。\n帔拂疏霜簟秋玉，炎炎红镜东方开。\n晕如车轮上裴回，啾啾赤帝骑龙来。'},
    {t:'六月二十七日望湖楼醉书五首',a:'苏轼〔宋代〕',c:'黑云翻墨未遮山，白雨跳珠乱入船。\n卷地风来忽吹散，望湖楼下水如天。\n放生鱼鳖逐人来，无主荷花到处开。\n水枕能令山俯仰，风船解与月裴回。\n乌菱白芡不论钱，乱系青菰裹绿盘。\n忽忆尝新会灵观，滞留江海得加餐。\n献花游女木兰桡，细雨斜风湿翠翘。\n无限芳洲生杜若，吴儿不识楚辞招。\n未成小隐聊中隐，可得长闲胜暂闲。\n我本无家更安往，故乡无此好湖山。'},
    {t:'六月二十日夜渡海',a:'苏轼〔宋代〕',c:'参横斗转欲三更，苦雨终风也解晴。\n云散月明谁点缀？天容海色本澄清。\n空余鲁叟乘桴意，粗识轩辕奏乐声。\n九死南荒吾不恨，兹游奇绝冠平生。'},
    {t:'六月三日夜闻蝉',a:'白居易〔唐代〕',c:'荷香清露坠，柳动好风生。\n微月初三夜，新蝉第一声。\n乍闻愁北客，静听忆东京。\n我有竹林宅，别来蝉再鸣。\n不知池上月，谁拨小船行？'},
    {t:'六月十七日昼寝',a:'黄庭坚〔宋代〕',c:'红尘席帽乌韡里，想见沧洲白鸟双。\n马齕枯萁喧午枕，梦成风雨浪翻江。'},
    {t:'六月十三日立秋',a:'杨万里〔宋代〕',c:'暑中剩喜立秋初，特地西风半点无。\n旋汲井花浇睡眼，洒将荷叶看跳珠。'},
    {t:'六月十四日宿东林寺',a:'陆游〔宋代〕',c:'看尽江湖千万峰，不嫌云梦芥吾胸。\n戏招西塞山前月，来听东林寺里钟。\n远客岂知今再到，老僧能记昔相逢。\n虚窗熟睡谁惊觉，野碓无人夜自舂。'},
    {t:'六月十五日诣水公庵雨作',a:'朱熹〔宋代〕',c:'云起欲为雨，中川分晦明。\n才惊横岭断，已觉疏林鸣。\n空际旱尘灭，虚堂凉思生。\n颓檐滴沥余，忽作流泉倾。\n况此高人居，地偏园景清。\n芳馨杂悄蒨，俯仰同鲜荣。\n我来偶兹适，中怀淡无营。\n归路绿泱漭，因之想岩耕。'},
    {t:'六州歌头·西湖万顷',a:'辛弃疾〔宋代〕',c:'西湖万顷，楼观矗千门。春风路，无堆锦，翠连云。俯层轩。风月都无际。荡空蔼，开绝境，云梦泽，饶堤九，不须吞。翡翠明珰，争上金堤去，勃窣媻姗。看贤王高会，飞盖入云烟。白鹭振振，鼓咽咽。\n记风流远，更休作，嬉游地，等闲看。君不见，韩献子，晋将军，赵孤存。千载传忠献，两定策，纪元勋。孙又子，方谈笑，整乾坤。直使长江如带，依前是、保赵须韩。伴皇家快乐，长在玉津边。只在南园。'},
    {t:'龙标野宴',a:'王昌龄〔唐代〕',c:'沅溪夏晚足凉风，春酒相携就竹丛。\n莫道弦歌愁远谪，青山明月不曾空。'},
    {t:'龙池',a:'李商隐〔唐代〕',c:'龙池赐酒敞云屏，羯鼓声高众乐停。\n夜半宴归宫漏永，薛王沉醉寿王醒。'},
    {t:'龙门旬宴得月字韵',a:'张九龄〔唐代〕',c:'恩华逐芳岁，形胜兼韶月。中席傍鱼潭，前山倚龙阙。\n花迎妙妓至，鸟避仙舟发。宴赏良在兹，再来情不歇。'},
    {t:'龙门游眺',a:'韦应物〔唐代〕',c:'凿山导伊流，中断若天辟。都门遥相望，佳气生朝夕。\n素怀出尘意，适有携手客。精舍绕层阿，千龛邻峭壁。\n缘云路犹缅，憩涧钟已寂。花树发烟华，淙流散石脉。\n长啸招远风，临潭漱金碧。日落望都城，人间何役役。'},
    {t:'龙女祠',a:'岑参〔唐代〕',c:'龙女何处来，来时乘风雨。祠堂青林下，宛宛如相语。\n蜀人竞祈恩，捧酒仍击鼓。'},
    {t:'龙丘途中二首',a:'杜牧〔唐代〕',c:'汉苑残花别，吴江盛夏来。唯看万树合，不见一枝开。\n水色饶湘浦，滩声怯建溪。泪流回月上，可得更猿啼。'},
    {t:'龙泉寺石井二首',a:'王安石〔宋代〕',c:'山腰石有千年润，海眼泉无一日乾。\n天下苍生待霖雨，不知龙向此中蟠。'},
    {t:'龙蛇歌',a:'佚名〔先秦〕',c:'有龙于飞，周遍天下。\n五蛇从之，为之承辅。\n龙返其乡，得其处所。\n四蛇从之，得其露雨。\n一蛇羞之，桥死于中野。'},
    {t:'龙雾洲觉海寺次李文溪壁间韵',a:'文天祥〔宋代〕',c:'阇黎钟后访团蒲，江色漫漫昼外晡。\n一笛梅边何满子，千簑芦外笔头奴。\n急风吹雁还家未，新雨生涛到海无。\n本是白鸥随浩荡，野田漂泊不为孤。'},
    {t:'龙兴寺吊少陵先生寓居',a:'陆游〔宋代〕',c:'中原草草失承平，戍火胡尘到两京。\n扈跸老臣身万里，天寒来此听江声！'},
    {t:'龙阳县歌',a:'刘禹锡〔唐代〕',c:'县门白日无尘土，百姓县前挽观罟。\n主人引客登大堤，小儿纵观黄犬怒。\n鹧鸪惊鸣绕篱落，橘柚垂芳照窗户。\n沙平草绿见吏稀，寂历斜阳照县鼓。'},
    {t:'龙夜吟',a:'李贺〔唐代〕',c:'卷发胡儿眼睛绿，高楼夜静吹横竹。一声似向天上来，\n月下美人望乡哭。直排七点星藏指，暗合清风调宫徵。\n蜀道秋深云满林，湘江半夜龙惊起。玉堂美人边塞情，\n碧窗皓月愁中听。寒砧能捣百尺练，粉泪凝珠滴红线。\n胡儿莫作陇头吟，隔窗暗结愁人心。'},
    {t:'龙移',a:'韩愈〔唐代〕',c:'天昏地黑蛟龙移，雷惊电激雄雌随。\n清泉百丈化为土，鱼鳖枯死吁可悲。'},
    {t:'笼鹰词',a:'柳宗元〔唐代〕',c:'凄风淅沥飞严霜，苍鹰上击翻曙光。\n云披雾裂虹霓断，霹雳掣电捎平冈。\n砉然劲翮剪荆棘，下攫狐兔腾苍茫。\n爪毛吻血百鸟逝，独立四顾时激昂。\n炎风溽暑忽然至，羽翼脱落自摧藏。\n草中狸鼠足为患，一夕十顾惊且伤。\n但愿清商复为假，拔去万累云间翔。'},
    {t:'隆冈书院四景诗其二',a:'朱熹〔宋代〕',c:'帘捲薰风半掩扉，五侯车马往塘稀。绿杨门巷莺莺语，青草池塘燕燕飞。\n扫石围棋销白昼，解衣沽酒醉斜晖。山园莫道多寥落，梅子初黄杏子肥。'},
    {t:'陇头歌辞三首',a:'佚名〔南北朝〕',c:'陇头流水，流离山下。\n念吾一身，飘然旷野。\n朝发欣城，暮宿陇头。\n寒不能语，舌卷入喉。\n陇头流水，鸣声呜咽。\n遥望秦川，心肝断绝。'},
    {t:'陇头水',a:'陆游〔宋代〕',c:'陇头十月天雨霜，壮士夜挽绿沉枪。\n卧闻陇水思故乡，三更起坐泪数行。\n我语壮士勉自疆，男儿堕地志四方。\n裹尸马革固其常，岂若妇女不下堂？\n生逢和亲最可伤，岁辇金絮输胡羌。\n夜视太白收光芒，报国欲死无战场。'},
    {t:'陇头水二首',a:'皎然〔唐代〕',c:'陇头水欲绝，陇水不堪闻。碎影摇枪垒，寒声咽幔军。\n素从盐海积，绿带柳城分。日落天边望，逶迤入塞云。\n秦陇逼氐羌，征人去未央。如何幽咽水，并欲断君肠。\n西注悲穷漠，东分忆故乡。旅魂声搅乱，无梦到咸阳。'},
    {t:'陇头行',a:'张籍〔唐代〕',c:'陇头路断人不行，胡骑夜入凉州城。\n汉兵处处格斗死，一朝尽没陇西地。\n驱我边人胡中去，散放牛羊食禾黍。\n去年中国养子孙，今著毡裘学胡语。\n谁能更使李轻车，收取凉州入汉家。'},
    {t:'陇头吟',a:'王维〔唐代〕',c:'长安少年游侠客，夜上戍楼看人白。\n陇头明月迥临关，陇上行人夜吹笛。\n关西老将不胜愁，驻马听之双泪流。\n身经大小百余战，麾下偏裨万户侯。\n苏武才为典属国，节旄落尽海西头。'},
    {t:'陇西行',a:'王维〔唐代〕',c:'十里一走马，五里一扬鞭。\n都护军书至，匈奴围酒泉。\n关山正飞雪，烽戍断无烟。'},
    {t:'楼桑',a:'文天祥〔宋代〕',c:'我过梁门城，楼桑在其北。\n玄德已千年，青烟绕故宅。\n道傍为挥泪，徘徊秋风客。\n天下卧龙人，多少空抱膝。'},
    {t:'楼上',a:'杜甫〔唐代〕',c:'天地空搔首，频抽白玉簪。\n皇舆三极北，身事五湖南。\n恋阙劳肝肺，论材愧杞楠。\n乱离难自救，终是老湘潭。'},
    {t:'楼上醉书',a:'陆游〔宋代〕',c:'丈夫不虚生世间，本意灭虏收河山。\n岂知蹭蹬不称意，八年梁益凋朱颜。\n三更抚枕忽大叫，梦中夺得松亭关。\n中原机会嗟屡失，明日茵席留余潸。\n益州官楼酒如海，我来解旗论日买。\n酒酣博簺为欢娱，信手枭卢喝成采。\n牛背烂烂电目光，狂杀自谓元非狂。\n故都九庙臣敢忘？祖宗神灵在帝旁。'},
    {t:'楼中月夜',a:'韦应物〔唐代〕',c:'端令倚悬槛，长望抱沉忧。宁知故园月，今夕在兹楼。\n衰莲送馀馥，华露湛新秋。坐见苍林变，清辉怆已休。'},
    {t:'陋室铭',a:'刘禹锡〔唐代〕',c:'山不在高，有仙则名。水不在深，有龙则灵。斯是陋室，惟吾德馨。苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无白丁。可以调素琴，阅金经。无丝竹之乱耳，无案牍之劳形。南阳诸葛庐，西蜀子云亭。孔子云：何陋之有？'},
    {t:'卢氏池上遇雨赠同游者',a:'温庭筠〔唐代〕',c:'簟翻凉气集，溪上润残棋。萍皱风来后，荷喧雨到时。\n寂寥闲望久，飘洒独归迟。无限松江恨，烦君解钓丝。'},
    {t:'卢溪别人',a:'王昌龄〔唐代〕',c:'武陵溪口驻扁舟，溪水随君向北流。\n行到荆门上三峡，莫将孤月对猿愁。'},
    {t:'庐山瀑布',a:'范仲淹〔宋代〕',c:'灵源何太高，北斗想可挹。\n凌日饮光直，逗云千仞急。\n白虹下涧饮，寒剑倚天立。\n阔电不得瞬，长雷无敢蛰。\n万丈岩崖坼，一道林峦瀑。\n险逼飞鸟坠，冷束山鬼润。\n须当截海去，独流不相入。'},
    {t:'鲁郡东石门送杜二甫',a:'李白〔唐代〕',c:'醉别复几日，登临遍池台。\n何时石门路，重有金樽开。\n秋波落泗水，海色明徂徕。\n飞蓬各自远，且尽手中杯。'},
    {t:'鲁西至东平',a:'高适〔唐代〕',c:'沙岸拍不定，石桥水横流。问津见鲁俗，怀古伤家丘。\n寥落千载后，空传褒圣侯。'},
    {t:'鲁中送二从弟赴举之西京',a:'李白〔唐代〕',c:'鲁客向西笑，君门若梦中。\n霜凋逐臣发，日忆明光宫。\n复羡二龙去，才华冠世雄。\n平衢骋高足，逸翰凌长风。\n舞袖拂秋月，歌筵闻早鸿。\n送君日千里，良会何由同。'},
    {t:'陆枢密秀夫第五十二',a:'文天祥〔宋代〕',c:'文采珊瑚钩，淑气含公鼎。\n炯炯一心在，天水相与永。'},
    {t:'陆游筑书巢',a:'陆游〔宋代〕',c:'吾室之内，或栖于椟，或陈于前，或枕藉于床，俯仰四顾，无非书者。吾饮食起居，疾痛呻吟，悲忧愤叹，未尝不与书俱。宾客不至，妻子不觌，而风雨雷雹之变，有不知也。间有意欲起，而乱书围之，如积槁枝，或至不得行，则辄自笑曰：“此非吾所谓巢者邪？”乃引客就观之。客始不能入，既入又不能出，乃亦大笑曰：“信乎其似巢也！”'},
    {t:'鹿柴',a:'王维〔唐代〕',c:'空山不见人，但闻人语响。\n返景入深林，复照青苔上。'},
    {t:'鹿葱花',a:'晏殊〔宋代〕',c:'宫后扇开青雉尾，羽人衣翦赤霜文。\n农皇药录真无谓，不向萱丛辩纠纷。'},
    {t:'渌水曲',a:'李白〔唐代〕',c:'渌水明秋月，南湖采白蘋。\n荷花娇欲语，愁杀荡舟人。'},
    {t:'碌碌古词',a:'温庭筠〔唐代〕',c:'左亦不碌碌，右亦不碌碌。野草自根肥，羸牛生健犊。\n融蜡作杏蒂，男儿不恋家。春风破红意，女颊如桃花。\n忠言未见信，巧语翻咨嗟。一鞘无两刃，徒劳油壁车。'},
    {t:'潞府客亭寄崔凤童',a:'王昌龄〔唐代〕',c:'萧条郡城闭，旅馆空寒烟。秋月对愁客，山钟摇暮天。\n新知偶相访，斗酒情依然。一宿阻长会，清风徒满川。'},
    {t:'鹭鸶',a:'杜牧〔唐代〕',c:'雪衣雪发青玉嘴，群捕鱼儿溪影中。\n惊飞远映碧山去，一树梨花落晚风。'},
    {t:'露华·碧桃',a:'张炎〔宋代〕',c:'乱红自雨，正翠蹊误晓，玉洞明春。蛾眉淡扫，背风不语盈盈。莫恨小溪流水，引刘郎、不是飞琼。罗扇底，从教净冶，远障歌尘。\n一掬莹然生意，伴压架酴醿，相恼芳吟。玄都观里，几回错认梨云。花下可怜仙子，醉东风、犹自吹笙。残照晚，渔翁正迷武陵。'},
    {t:'栾家濑',a:'王维〔唐代〕',c:'飒飒秋雨中，浅浅石溜泻。\n跳波自相溅，白鹭惊复下。'},
    {t:'乱礁洋',a:'文天祥〔宋代〕',c:'海山仙子国，邂逅寄孤蓬。\n万象画图里，千崖玉界中。\n风摇春浪软，礁激暮潮雄。\n云气东南密，龙腾上碧空。'},
    {t:'乱离',a:'孟郊〔唐代〕',c:'天下无义剑，中原多疮痍。哀哀陆大夫，正直神反欺。\n子路已成血，嵇康今尚嗤。为君每一恸，如剑在四肢。\n折羽不复飞，逝水不复归。直松摧高柯，弱蔓将何依。\n朝为春日欢，夕为秋日悲。泪下无尺寸，纷纷天雨丝。\n积怨成疾疹，积恨成狂痴。怨草岂有边，恨水岂有涯。\n怨恨驰我心，茫茫日何之。'},
    {t:'乱石',a:'李商隐〔唐代〕',c:'虎踞龙蹲纵复横，星光渐减雨痕生。\n不须并碍东西路，哭杀厨头阮步兵。'},
    {t:'轮台歌奉送封大夫出师西征',a:'岑参〔唐代〕',c:'轮台城在夜吹角，轮台城北旄在落。\n羽书昨夜过渠黎，单于已在金山西。\n戍楼西望烟尘黑，汉征屯在轮台北。\n上将拥旄西出征，平明吹笛大征行。\n四边伐鼓雪海涌，三征大呼阴山动。\n虏塞兵气连云屯，战场白骨缠草根。\n剑河风急雪片阔，沙口石冻马蹄脱。\n亚相勤王甘苦辛，誓将报主静边尘。\n古来青史谁不见，今见功名胜古人。'},
    {t:'轮台即事',a:'岑参〔唐代〕',c:'轮台风物异，地是古单于。三月无青草，千家尽白榆。\n蕃书文字别，胡俗语音殊。愁见流沙北，天西海一隅。'},
    {t:'轮台子·雾敛澄江',a:'柳永〔宋代〕',c:'雾敛澄江，烟消蓝光碧。彤霞衫遥天，掩映断续，半空残月。孤村望处人寂寞，闻钓叟、甚处一声羌笛。九凝山畔才雨过，斑竹作、血痕添色。感行客。翻思故国，恨因循阻隔。路久沉消息。\n正老松枯柏情如织。闻野猿啼，愁听得。见钓舟初出，芙蓉渡头，鸳鸯难侧。干名利禄终无益。念岁岁间阻，迢迢紫陌。翠蛾娇艳，从别后经今，花开柳拆伤魂魄。利名牵役。又争忍、把光景抛掷。'},
    {t:'轮台子·一枕清宵好梦',a:'柳永〔宋代〕',c:'一枕清宵好梦，可惜被、邻鸡唤草。匆匆策马登途，满目淡烟衰草。前驱风触鸣珂，过霜林、渐草长栖鸟。冒征尘远况，自古凄凉长安道。行行又历孤村，楚天阔、望中未晓。\n念劳生，惜芳年壮岁，离多欢少。叹断梗难停，暮云渐杳。但黯黯魂消，寸肠凭谁表。恁驱驱、何时是了。又争似、却返瑶京，重买千金笑。'},
    {t:'罗道士',a:'张籍〔唐代〕',c:'城里无人得实年，衣襟常带臭黄烟。楼中赊酒唯留药，\n洞里争棋不赌钱。闻客语声知贵贱，持花歌咏似狂颠。\n寻常行处皆逢见，世上多疑是谪仙。'},
    {t:'罗浮山父与葛篇',a:'李贺〔唐代〕',c:'依依宜织江雨空，雨中六月兰台风。\n博罗老仙时出洞，千岁石床啼鬼工。\n蛇毒浓凝洞堂湿，江鱼不食衔沙立。\n欲剪湘中一尺天，吴娥莫道吴刀涩。'},
    {t:'罗氏花下奉招陈侍御',a:'孟郊〔唐代〕',c:'眼在枝上春，落地成埃尘。不是阔流者，谁为攀折人。\n宁辞波浪阔，莫道往来频。拾紫岂宜晚，掇平须及晨。\n劳收贾生泪，强起屈平身。花下本无俗，酒中别有神。\n游蜂不饮故，戏蝶亦争新。万物尽如此，过时非所珍。'},
    {t:'洛城观酺应制',a:'陈子昂〔唐代〕',c:'圣人信恭己，天命允昭回。苍极神功被，青云秘箓开。\n垂衣受金册，张乐宴瑶台。云凤休征满，鱼龙杂戏来。\n崇恩逾五日，惠泽畅三才。玉帛群臣醉，徽章缛礼该。\n方睹升中禅，言观拜洛回。微臣固多幸，敢上万年杯。'},
    {t:'洛妹真珠',a:'李贺〔唐代〕',c:'真珠小娘下青廓，洛苑香风飞月月。\n寒鬓斜钗玉燕光，高楼唱月敲悬珰。\n兰风桂露洒幽翠，红来袅云咽深思。\n花袍白马不归来，浓蛾叠柳香唇醉。\n金鹅屏风蜀山梦，鸾裾凤带行烟重。\n八骢笼晃脸差移，日丝繁散曛罗洞。\n市南曲陌无秋凉，楚腰卫鬓四时芳。\n玉喉窕窕排空光，牵云曳雪留陆郎。'},
    {t:'洛桥寒食日作十韵',a:'白居易〔唐代〕',c:'上苑风烟好，中桥道路平。\n蹴球重不起，泼火雨新晴。\n宿醉头仍重，晨游眼乍明。\n老慵虽省事，春次尚多情。\n遇客踟蹰立，寻花取次行。\n连钱嚼金勒，凿落写银罂。\n府酝伤教送，官娃岂要迎。\n舞腰那及柳，歌舌不如莺。\n乡国真堪恋，光阴可合轻。\n三年遇寒食，尽在洛阳城。'},
    {t:'洛桥晚望',a:'孟郊〔唐代〕',c:'天津桥下冰初结，洛阳陌上人行绝。\n榆柳萧疏楼阁闲，月明直见嵩山雪。'},
    {t:'洛姝真珠',a:'李贺〔唐代〕',c:'真珠小娘下清廓，洛苑香风飞月月。\n寒鬓斜钗玉燕光，高楼唱月敲悬珰。\n兰风桂露洒幽翠，红来袅云咽深思。\n花袍白马不归来，浓蛾叠柳香唇醉。\n金鹅屏风蜀山梦，鸾裾凤带行烟重。\n八骢笼晃脸差移，日丝繁散曛罗洞。\n市南曲陌无秋凉，楚腰卫鬓四时芳。\n玉喉窱窱排空光，牵云曳雪留陆郎。'},
    {t:'洛阳',a:'杜牧〔唐代〕',c:'文争武战就神功，时似开元天宝中。\n已建玄戈收相土，应回翠帽过离宫。\n侯门草满宜寒兔，洛浦沙深下塞鸿。\n疑有女娥西望处，上阳烟树正秋风。'},
    {t:'洛阳',a:'温庭筠〔唐代〕',c:'巩树先春雪满枝，上阳宫柳啭黄鹂。\n桓谭未便忘西笑，岂为长安有凤池。'},
    {t:'洛阳城外别皇甫湜',a:'李贺〔唐代〕',c:'洛阳吹别风，龙门起断烟。\n冬树束生涩，晚紫凝华天。\n单身野霜上，疲马飞蓬间。\n凭轩一双泪，奉坠绿衣前。'},
    {t:'洛阳春·雪',a:'纳兰性德〔清代〕',c:'密洒征鞍无数。冥迷远树。乱山重叠杳难分，似五里、蒙蒙雾。\n惆怅琐窗深处。湿花轻絮。当时悠飏得人怜，也都是、浓香助。'},
    {t:'洛阳陌',a:'李白〔唐代〕',c:'白玉谁家郎，回车渡天津。\n看花东陌上，惊动洛阳人。'},
    {t:'洛阳女儿行',a:'王维〔唐代〕',c:'洛阳女儿对门居，才可颜容十盘余。\n良人玉勒乘骢马，侍女金盘脍鲤鱼。\n画阁朱楼尽相望，红车绿柳垂檐向。\n罗帷送上七香车，宝扇迎归九华帐。\n狂夫富贵在青春，意气骄奢剧季伦。\n自怜碧玉亲教舞，不惜珊瑚持与人。\n春窗曙灭九微火，九微片片飞花琐。\n戏罢曾无理曲时，妆成祗是熏香坐。\n城中相识尽繁华，日夜经过赵李家。\n谁怜越女颜如玉，贫贱江头自浣纱。'},
    {t:'洛阳秋夕',a:'杜牧〔唐代〕',c:'泠泠寒水带霜风，更在天桥夜景中。\n清禁漏闲烟树寂，月轮移在上阳宫。'},
    {t:'洛阳尉刘晏与府掾',a:'王昌龄〔唐代〕',c:'良友呼我宿，月明悬天宫。道安风尘外，洒扫青林中。\n削去府县理，豁然神机空。自从三湘还，始得今夕同。\n旧居太行北，远宦沧溟东。各有四方事，白云处处通。'},
    {t:'洛阳行',a:'张籍〔唐代〕',c:'洛阳宫阙当中州，城上峨峨十鸟楼。翠华西去几时返，\n枭巢乳鸟藏蛰燕。御门空锁五十年，税冬农夫修玉殿。\n六街朝暮鼓冬冬，禁兵持戟守空宫。百官月月拜章表，\n驿使相续长安道。上阳宫树黄复绿，野豺入苑食麋鹿。\n陌上老翁双泪垂，共说武皇巡幸时。'},
    {t:'洛阳长句二首',a:'杜牧〔唐代〕',c:'草色人心相与闲，是非名利有无间。\n桥横落照虹堪画，树锁千门鸟自还。\n芝盖不来云杳杳，仙舟何处水潺潺。\n君王谦让泥金事，苍翠空高万岁山。\n天汉东穿白玉京，日华浮动翠光生。\n桥边游女珮环委，波底上阳金碧明。\n月锁名园孤鹤唳，川酣秋梦凿龙声。\n连昌绣岭行宫在，玉辇何时父老迎。'},
    {t:'洛中春末送杜录事赴蕲州',a:'刘禹锡〔唐代〕',c:'樽前花下长相见，明日忽为千里人。\n君过午桥回首望，洛城犹自有残春。'},
    {t:'洛中二首',a:'杜牧〔唐代〕',c:'柳动晴风拂路尘，年年宫阙锁浓春。\n一从翠辇无巡幸，老却蛾眉几许人。\n风吹柳带摇晴绿，蝶绕花枝恋暖香。\n多把芳菲泛春酒，直教愁色对愁肠。'},
    {t:'洛中访袁拾遗不遇',a:'孟浩然〔唐代〕',c:'洛阳访才子，江岭作流人。\n闻说梅花早，何如北地春。'},
    {t:'洛中寺北楼见贺监草书题诗',a:'刘禹锡〔唐代〕',c:'高楼贺监昔曾登，壁上笔踪龙士腾。\n中国书流尚皇象，北朝文士重徐陵。\n偶因独见空惊目，恨不同时便伏膺。\n唯恐尘埃转磨灭，再三珍重嘱山僧。'},
    {t:'洛中送韩七中丞之吴兴口号五首',a:'刘禹锡〔唐代〕',c:'昔年意气结群英，几度朝回一字行。\n海北江南零落尽，两人相见洛阳城。\n自从云散各东西，每日欢娱却惨凄。\n离别苦多相见少，一生心事在书题。\n今朝无意诉离杯，何况清弦急管催。\n本欲醉中轻远别，不知翻引酒悲来。\n骆驼桥上蘋风急，鹦鹉杯中箬下春。\n水碧山青知好处，开颜一笑向何人。\n溪中士女出笆篱，溪上鸳鸯避画旗。\n何处人间似仙境，春山携妓采茶时。'},
    {t:'洛中送奚三还扬州',a:'孟浩然〔唐代〕',c:'水国无边际，舟行共使风。\n羡君从此去，朝夕见乡中。\n余亦离家久，南归恨不同。\n音书若有问，江上会相逢。'},
    {t:'落第',a:'孟郊〔唐代〕',c:'晓月难为光，愁人难为肠。\n谁言春物荣，独见叶上霜。\n雕鹗失势病，鹪鹩假翼翔。\n弃置复弃置，情如刀剑伤。'},
    {t:'落第西还别刘祭酒高明府',a:'陈子昂〔唐代〕',c:'别馆分周国，归骖入汉京。\n地连函谷塞，川接广阳城。\n望迥楼台出，途遥烟雾生。\n莫言长落羽，贫贱一交情。'},
    {t:'落第西还别魏四懔',a:'陈子昂〔唐代〕',c:'转蓬方不定，落羽自惊弦。\n山水一为别，欢娱复几年。\n离亭暗风雨，征路入云烟。\n还因北山径，归守东陂田。'},
    {t:'落花',a:'李商隐〔唐代〕',c:'高阁客竟去，小园花乱飞。\n参差连曲陌，迢递送斜晖。\n肠断未忍扫，眼穿仍欲归。\n芳心向春尽，所得是沾衣。'},
    {t:'落花',a:'杨万里〔宋代〕',c:'红紫成泥泥作尘，颠风不管惜花人。\n落花辞树虽无语，别倩黄鹂告许春。'},
    {t:'落花时·夕阳谁唤下楼梯',a:'纳兰性德〔清代〕',c:'夕阳谁唤下楼梯，一握香荑。回头忍笑阶前立，总无语，也依依。\n笺书直恁无凭据，休说相思。劝伊好向红窗醉，须莫及，落花时。'},
    {t:'落梅二首',a:'陆游〔宋代〕',c:'雪虐风饕愈凛然，花中气节最高坚。\n过时自会飘零去，耻向东君更乞怜。\n醉折残梅一两枝，不妨桃李自逢时。\n向来冰雪凝严地，力斡春回竟是谁？'},
    {t:'落梅再著晚花',a:'杨万里〔宋代〕',c:'数日春风不柰暄，梅花落尽净无痕。\n却将晚莟重收拾，更放南枝第二番。'},
    {t:'落日',a:'杜甫〔唐代〕',c:'落日在帘钩，溪边春事幽。\n芳菲缘岸圃，樵爨倚滩舟。\n啅雀争枝坠，飞虫满院游。\n浊醪谁造汝，一酌散千忧。'},
    {t:'落日忆山中',a:'李白〔唐代〕',c:'雨后烟景绿，晴天散馀霞。\n东风随春归，发我枝上花。\n花落时欲暮，见此令人嗟。\n愿游名山去，学道飞丹砂。'},
    {t:'落星寺',a:'范仲淹〔宋代〕',c:'长江万里来，古寺中流起。\n何如天上星，汩汩波涛里。'},
    {t:'落叶送陈羽',a:'韩愈〔唐代〕',c:'落叶不更息，断蓬无复归。\n飘飖终自异，邂逅暂相依。\n悄悄深夜语，悠悠寒月辉。\n谁云少年别，流泪各沾衣。'},
    {t:'落月',a:'元稹〔唐代〕',c:'落月沉馀影，阴渠流暗光。蚊声霭窗户，萤火绕屋梁。\n飞幌翠云薄，新荷清露香。不吟复不寐，竟夕池水傍。'},
    {t:'吕将军歌',a:'李贺〔唐代〕',c:'吕将军，骑赤兔。\n独携大胆出秦门，金粟堆边哭陵树。\n北方逆气污青天，剑龙夜叫将军闲。\n将军振袖挥剑锷，玉阙朱城有门阁。\n榼榼银龟摇白马，傅粉女郎火旗下。\n恒山铁骑请金枪，遥闻箙中花箭香。\n西郊寒蓬叶如刺，皇天新栽养神骥。\n厩中高桁排蹇蹄，饱食青刍饮白水。\n圆苍低迷盖张地，九州人事皆如此。\n赤山秀铤御时英，绿眼将军会天意。'},
    {t:'旅次盩厔过韩士别业',a:'王昌龄〔唐代〕',c:'春烟桑柘林，落日隐荒墅。泱漭平原夕，清吟久延伫。\n故人家于此，招我渔樵所。'},
    {t:'旅怀',a:'文天祥〔宋代〕',c:'北去通州号畏途，固应孝子为回车。\n海陵若也容羁客，賸买菰蒲且寄居。'},
    {t:'旅宿',a:'杜牧〔唐代〕',c:'旅馆无良伴，凝情自悄然。\n寒灯思旧事，断雁警愁眠。\n远梦归侵晓，家书到隔年。\n沧江好烟月，门系钓鱼船。'},
    {t:'旅宿淮阳亭口号·一作宋之问诗',a:'张九龄〔唐代〕',c:'日暮荒亭上，悠悠旅思多。\n故乡临桂水，今夜渺星河。\n暗草霜华发，空亭雁影过。\n兴来谁与晤，劳者自为歌。'},
    {t:'旅望',a:'王昌龄〔唐代〕',c:'白花原头望京师，黄河水流无尽时。\n穷秋旷野行人绝，马首东来知是谁。'},
    {t:'旅行',a:'孟郊〔唐代〕',c:'楚水结冰薄，楚云为雨微。\n野梅参差发，旅榜逍遥归。'},
    {t:'旅夜书怀',a:'杜甫〔唐代〕',c:'细草微风岸，危樯独夜舟。\n星垂平野阔，月涌大江流。\n名岂文章著，官应老病休。\n飘飘何所似，天地一沙鸥。'},
    {t:'律僧',a:'张籍〔唐代〕',c:'苦行长不出，清羸最少年。持斋唯一食，讲律岂曾眠。\n避草每移径，滤虫还入泉。从来天竺法，到此几人传。'},
    {t:'绿萝',a:'杜牧〔唐代〕',c:'绿萝萦数匝，本在草堂间。\n秋色寄高树，昼阴笼近山。\n移花疏处过，劚药困时攀。\n日暮微风起，难寻旧径还。'},
    {t:'绿水词',a:'李贺〔唐代〕',c:'今宵好风月，阿侯在何处。\n为有倾人色，翻成足愁苦。\n东湖采莲叶，南湖拔蒲根。\n未持寄小姑，且持感愁魂。'},
    {t:'绿漪堂',a:'文天祥〔宋代〕',c:'义方堂上看，窗户翠玲珑。\n砚里云坛月，席间淇水风。\n清声随地到，直节与天通。\n庭玉森如笋，干霄雨露功。'},
    {t:'绿章封事',a:'李贺〔唐代〕',c:'青霓扣额呼宫神，鸿龙玉狗开天门。\n石榴花发满溪津，溪女洗花染白云。\n绿章封事咨元父，六街马蹄浩无主。\n虚空风气不清冷，短衣小冠作尘土。\n金家香弄千轮鸣，扬雄秋室无俗声。\n愿携汉戟招书鬼，休令恨骨填蒿里。'},
    {t:'麻姑山',a:'刘禹锡〔唐代〕',c:'曾游仙迹见丰碑，除却麻姑更洞谁。云盖青山龙卧处，\n日临丹洞鹤归时。霜凝上界花开晚，月冷中天果熟迟。\n人到便须抛世事，稻田还拟种灵芝。'},
    {t:'麻姑山',a:'晏殊〔宋代〕',c:'昔年权暂领军城，静爱仙山咏过春。\n天下云车曾祖驾，城中鳌海几生尘。\n明知绿发升真籍，堪笑苍颜预宪臣。\n我若粗成忠国事，赤松曾羡汉迁人。'},
    {t:'马明生遇神女歌',a:'韦应物〔唐代〕',c:'学仙贵功亦贵精，神女变化感马生。石壁千寻启双检，\n中有玉堂铺玉簟。立之一隅不与言，玉体安隐三日眠。\n马生一立心转坚，知其丹白蒙哀怜。安期先生来起居，\n请示金铛玉佩天皇书。神女呵责不合见，\n仙子谢过手足战。大瓜玄枣冷如冰，海上摘来朝霞凝。\n赐仙复坐对食讫，颔之使去随烟升。乃言马生合不死，\n少姑教敕令付尔。安期再拜将生出，一授素书天地毕。'},
    {t:'马上作',a:'陆游〔宋代〕',c:'平桥小陌雨初收，淡日穿云翠霭浮。\n杨柳不遮春色断，一枝红杏出墙头。'},
    {t:'马诗二十三首·其八',a:'李贺〔唐代〕',c:'赤兔无人用，当须吕布骑。\n吾闻果下马，羁策任蛮儿。'},
    {t:'马诗二十三首·其二',a:'李贺〔唐代〕',c:'腊月草根甜，天街雪似盐。\n未知口硬软，先拟蒺藜衔。'},
    {t:'马诗二十三首·其二十',a:'李贺〔唐代〕',c:'重围如燕尾，宝剑似鱼肠。\n欲求千里脚，先采眼中光。'},
    {t:'马诗二十三首·其二十二',a:'李贺〔唐代〕',c:'汗血到王家，随鸾撼玉珂。\n少君骑海上，人见是青骡。'},
    {t:'马诗二十三首·其二十三',a:'李贺〔唐代〕',c:'武帝爱神仙，烧金得紫烟。\n厩中皆肉马，不解上青天。'},
    {t:'马诗二十三首·其二十一',a:'李贺〔唐代〕',c:'暂系腾黄马，仙人上彩楼。\n须鞭玉勒吏，何事谪高州？'},
    {t:'马诗二十三首·其九',a:'李贺〔唐代〕',c:'飂叔去匆匆，如今不豢龙。\n夜来霜压栈，骏骨折西风。'},
    {t:'马诗二十三首·其六',a:'李贺〔唐代〕',c:'饥卧骨查牙，粗毛刺破花。\n鬣焦珠色落，发断锯长麻。'},
    {t:'马诗二十三首·其三',a:'李贺〔唐代〕',c:'忽忆周天子，驱车上玉山。\n鸣驺辞凤苑，赤骥最承恩。'},
    {t:'马诗二十三首·其十',a:'李贺〔唐代〕',c:'催榜渡乌江，神骓泣向风。\n君王今解剑，何处逐英雄？'},
    {t:'马诗二十三首·其十八',a:'李贺〔唐代〕',c:'伯乐向前看，旋毛在腹间。\n只今掊白草，何日蓦青山？'},
    {t:'马诗二十三首·其十二',a:'李贺〔唐代〕',c:'批竹初攒耳，桃花未上身。\n他时须搅阵，牵去借将军。'},
    {t:'马诗二十三首·其十九',a:'李贺〔唐代〕',c:'萧寺驮经马，元从竺国来。\n空知有善相，不解走章台。'},
    {t:'马诗二十三首·其十六',a:'李贺〔唐代〕',c:'唐剑斩隋公，拳毛属太宗。\n莫嫌金甲重，且去捉颴风。'},
    {t:'马诗二十三首·其十七',a:'李贺〔唐代〕',c:'白铁锉青禾，砧间落细莎。\n世人怜小颈，金埒畏长牙。'},
    {t:'马诗二十三首·其十三',a:'李贺〔唐代〕',c:'宝玦谁家子，长闻侠骨香。\n堆金买骏骨，将送楚襄王。'},
    {t:'马诗二十三首·其十四',a:'李贺〔唐代〕',c:'香幞赭罗新，盘龙蹙蹬鳞。\n回看南陌上，谁道不逢春？'},
    {t:'马诗二十三首·其十五',a:'李贺〔唐代〕',c:'不从桓公猎，何能伏虎威？\n一朝沟陇出，看取拂云飞。'},
    {t:'马诗二十三首·其十一',a:'李贺〔唐代〕',c:'内马赐宫人，银鞯刺麒麟。\n午时盐坂上，蹭蹬溘风尘。'},
    {t:'马诗二十三首·其四',a:'李贺〔唐代〕',c:'此马非凡马，房星本是星。\n向前敲瘦骨，犹自带铜声。'},
    {t:'马诗二十三首·其五',a:'李贺〔唐代〕',c:'大漠沙如雪，燕山月似钩。\n何当金络脑，快走踏清秋。'},
    {t:'马诗二十三首其二十一',a:'李贺〔唐代〕',c:'暂系腾黄马，仙人上綵楼。须鞭玉勒吏，何事谪高州。'},
    {t:'马说',a:'韩愈〔唐代〕',c:'世有伯乐，然后有千里马。千里马常有，而伯乐不常有。故虽有名马，只辱于奴隶人之手，骈死于槽枥之间，不以千里称也。\n马之千里者，一食或尽粟一石。食马者不知其能千里而食也。是马也，虽有千里之能，食不饱，力不足，才美不外见，且欲与常马等不可得，安求其能千里也？\n策之不以其道，食之不能尽其材，鸣之而不能通其意，执策而临之，曰：“天下无马！”呜呼！其真无马邪？其真不知马也！'},
    {t:'马嵬·其二',a:'李商隐〔唐代〕',c:'海外徒闻更九州，他人未卜此人休。\n空闻虎旅传宵柝，无复鸡人报晓筹。\n此日六军同驻马，当时七夕笑牵牛。\n如何四纪为天子，不及卢家有莫愁。'},
    {t:'马嵬二首',a:'李商隐〔唐代〕',c:'冀马燕犀动地来，自埋红粉自由灰。\n君王若道能倾国，玉辇何由过马嵬。\n海外徒闻更九州，他柝未卜此柝休。\n空闻虎旅传宵柝，无复鸡人报晓筹。\n此日六军同驻马，当时七夕笑牵牛。\n如何四纪为天子，不及卢家有莫愁。'},
    {t:'马嵬佛寺',a:'温庭筠〔唐代〕',c:'荒鸡夜唱战尘深，五鼓雕舆过上林。才信倾城是真语，\n直教涂地始甘心。两重秦苑成千里，一炷胡香抵万金。\n曼倩死来无绝艺，后人谁肯惜青禽。'},
    {t:'马嵬行',a:'刘禹锡〔唐代〕',c:'绿野扶风道，黄尘马嵬驿。路边儿贵人，坟高三四尺。\n乃问里中儿，皆言幸蜀时。军家诛戚族，天帝舍妖姬。\n群吏伏门屏，贵人牵帝衣。低回转美目，风日为无晖。\n贵人饮金屑，倏忽舜英暮。平生服杏丹，颜色真如故。\n属车尘已远，里巷来窥觑。共爱宿妆妍，君王画眉处。\n履綦无复有，履组光未灭。不见岩畔人，空见凌波袜。\n邮童爱踪迹，私手解鞶结。传看千万眼，缕绝香不歇。\n指环照骨明，首饰敌连城。将入咸阳市，犹得贾胡惊。'},
    {t:'马嵬驿',a:'温庭筠〔唐代〕',c:'穆满曾为物外游，六龙经此暂淹留。\n返魂无验青烟灭，埋血空生碧草愁。\n香辇却归长乐殿，晓钟还下景阳楼。\n甘泉不复重相见，谁道文成是故侯。'},
    {t:'买花',a:'白居易〔唐代〕',c:'帝城春欲暮，喧喧车马度。\n共道牡丹时，相随买花去。\n贵贱无常价，酬直看花数。\n灼灼百朵红，戋戋五束素。\n上张幄幕庇，旁织巴篱护。\n水洒复泥封，移来色如故。\n家家习为俗，人人迷不悟。\n有一田舍翁，偶来买花处。\n低头独长叹，此叹无人喻。\n一丛深色花，十户中人赋。'},
    {t:'买药歌送杨山人',a:'皎然〔唐代〕',c:'华阴少年何所希，欲饵丹砂化骨飞。江南药少淮南有，\n暂别胥门上京口。京口斜通江水流，斐回应上青山头。\n夜惊潮没鸬鹚堰，朝看日出芙蓉楼。摇荡春风乱帆影，\n片云无数是扬州。扬州喧喧卖药市，浮俗无由识仙子。\n河间姹女直千金，紫阳夫人服不死。吾于此道复何如，\n昨朝新得蓬莱书。'},
    {t:'麦田',a:'杨万里〔宋代〕',c:'无边绿锦织云机，全幅青罗作地衣。\n个是农家真富贵，雪花销尽麦苗肥。'},
    {t:'卖炭翁',a:'白居易〔唐代〕',c:'卖炭翁，伐薪烧炭南山中。\n满面尘灰烟火色，两鬓苍苍十指黑。\n卖炭得钱何所营？身上衣裳口中食。\n可怜身上衣正单，心忧炭贱愿天寒。\n夜来城外一尺雪，晓驾炭车辗冰辙。\n牛困人饥日已高，市南门外泥中歇。\n翩翩两骑来是谁？黄衣使者白衫儿。\n手把文书口称敕，回车叱牛牵向北。\n一车炭，千余斤，宫使驱将惜不得。\n半匹红纱一丈绫，系向牛头充炭直。'},
    {t:'卖鱼湾',a:'文天祥〔宋代〕',c:'风起千湾浪，潮生万顷沙。\n春红堆蟹子，晚白结盐花。\n故国何时讯，扁舟到处家。\n狼山青两点，极目是天涯。'},
    {t:'蛮中',a:'张籍〔唐代〕',c:'铜柱南边毒草春，行人几日到金麟。\n玉镮穿耳谁家女，自抱琵琶迎海神。'},
    {t:'满朝欢·花隔铜壶',a:'柳永〔宋代〕',c:'花隔铜壶，露晞金掌，都门十二清晓。帝里风光烂漫，偏爱春杪。烟轻昼永，引莺啭上林，鱼游灵沼。巷陌乍晴，香尘染惹，垂杨芳草。\n因念秦楼彩凤，楚观朝云，往昔曾迷歌笑。别来岁久，偶忆欢盟重到。人面桃花，未知何处，但掩朱扉悄悄。尽日伫立无言，赢得凄凉怀抱。'},
    {t:'满江红',a:'秦观〔宋代〕',c:'风雨萧萧，长途上、春泥没足。谩回首、青山无数，笑人劳碌。山下粉粉梅落粉，渡头淼淼波摇绿。想小园、寂寞锁柴扉，繁花竹。\n曳文履，锵鸣玉。绮楼叠，雕阑曲。又何如、湖上芒鞋草屋。万顷水云翻白鸟，一蓑烟雨耕黄犊。怅东风、相望渺天涯，空凝目。'},
    {t:'满江红',a:'张炎〔宋代〕',c:'近日衰迟，但随分、蜗涎自足。底须共、红尘争道，顿荒松菊。壮志已荒圯上履，正音恐是沟中木。又安知、幕下有词人，归心速。\n书尚在，怜鱼腹。珠何处，惊鱼目。且依然诗思，灞桥人独。不用回头看堕甑，不愁抱石疑非玉。忽一声、长啸出山来，黄粱熟。'},
    {t:'满江红·澄江会复初李尹',a:'张炎〔宋代〕',c:'江上相逢，更秉烛、浑疑梦里。寂寞久，瑟弦尘断，为君重理。紫绶金章都莫问，醉中□送揶揄鬼。看满头、白雪欲消难，春风起。\n云一片，身千里。漂泊地，东西水。叹十年不见，我生能几。慷慨悲歌惊泪落，古人未必皆如此。想今人、愁似古人多，如何是。'},
    {t:'满江红·代北燕南',a:'纳兰性德〔清代〕',c:'代北燕南，应不隔、月明千里。谁相念、胭脂山下，悲哉秋气。小立乍惊清露湿，孤眠最惜浓香腻。况夜鸟、啼绝四更头，边声起。\n销不尽，悲歌意。匀不尽，相思泪。想故园今夜，玉阑谁倚。青海不来如意梦，红笺暂写违心字。道别来、浑是不关心，东堂桂。'},
    {t:'满江红·代王夫人作',a:'文天祥〔宋代〕',c:'试问琵琶，胡沙外怎生风色。最欢是、姚黄一朵，移根仙阙。王母欢阑琼宴罢，仙人泪满金盘侧。云行宫、半夜雨淋铃，声声歇。\n彩云散，香尘灭。铜驼恨，那堪说！想男儿慷慨，嚼穿龈血。回首昭阳辞落日，伤心铜雀迎秋月。算妾身、不愿似天家，金瓯缺。'},
    {t:'满江红·点火樱桃',a:'辛弃疾〔宋代〕',c:'点火樱桃，照一架、荼蘼如雪。春燕好，见龙孙穿破，紫苔苍壁。乳燕引雏飞力弱，流莺唤友娇声层。问春归、不肯带愁归，肠千结。\n层楼望，春山叠；家何在？烟波隔。把古今遗恨，向他谁说？蝴蝶不传千里梦，子规叫断三更月。听声声、枕上劝人归，归难得。'},
    {t:'满江红·东武会流杯亭',a:'苏轼〔宋代〕',c:'上巳日作。城南有坡，土色如丹，城下有堤，壅邞淇水入城。\n东武城南，新堤固、涟漪初溢。隐隐遍、吹林高阜，卧红堆碧。枝上残花吹尽也，与君更向江头觅。问向前、犹有几多春，三之一。\n官里事，何时毕。风雨外，无多日。相将泛曲水，满城争出。君不见兰亭修禊事，当时坐上皆豪逸。到如今、修竹满山阴，空陈迹。'},
    {t:'满江红·访雨寻云',a:'柳永〔宋代〕',c:'访雨寻云，无非是、奇容艳色。就姿有、天真妖丽，鸿然标格。恶发姿颜欢喜面，细追想处皆堪惜。鸿别后、幽怨与闲愁，成堆积。\n鳞鸿阻，无信息。梦魂断，难寻觅。尽思量，休又怎生休得。谁恁多情凭向道，纵来相见且相忆。便不成、常遣似如今，轻抛掷。'},
    {t:'满江红·风卷庭梧',a:'辛弃疾〔宋代〕',c:'风卷庭梧，黄叶坠、新凉如洗。一难折、秋英同尝，弄香挼蕊。天远难穷休久望，楼高欲下还重倚。古一襟、寂寞泪弹秋，无人会。\n今古恨、沉荒垒。悲欢事，随流水。想登楼青鬓，未堪憔悴。极目烟横山数点，孤舟月淡人千里。对婵娟、从此话离愁，金尊里。'},
    {t:'满江红·傅粉何郎',a:'张炎〔宋代〕',c:'韫玉传奇惟吴中子弟为第一狂，所谓识拍道字正声清韵不狂惧得看矣，作平声满江红赠看。\n傅粉何郎，比玉树、琼枝谩夸。看生子、东涂西抹，笑语浮华。蝴蝶一生花里活，似花还却似非花。最可人、娇艳正芳年，如破瓜。\n离别恨，生叹嗟。欢情事，起喧哗。听歌喉清润，片玉无瑕。洗尽人间笙笛耳，赏音多向五侯家。好思量、都在步莲中，裙翠遮。'},
    {t:'满江红·赣州席上呈陈季陵太守',a:'辛弃疾〔宋代〕',c:'落日苍茫，风才定、片帆无力。还记得、眉来眼去，水光山色。倦客不知身近远，佳人已卜归消息。便归来、只是赋行云，襄王客。\n些个事，如何得。知有恨，休重忆。但楚天特地，暮云凝碧。过眼不如人意事，十常八九今头白。笑江州、司马太多情，青衫湿。'},
    {t:'满江红·汉节东南',a:'辛弃疾〔宋代〕',c:'汉节东南，看驷马、光华周道。须自是、七闽还有，福星来到。庭草自生心意足，榕阴不动秋光好。自不知，何处著君侯，蓬莱岛。\n还自笑，人今老。空有恨，萦怀抱。记江湖十载，厌持旌纛。濩落我材无所用，易除殆类无根潦。但欲搜、好语谢新词，羞琼报。'},
    {t:'满江红·汉水东流',a:'辛弃疾〔宋代〕',c:'汉水东流，都洗金，髭胡膏血。人金说，君家飞将，旧时英烈。破敌金城雷过耳，谈兵玉帐冰生颊。间王郎，结发赋从戎，传遗业。\n腰间剑，聊弹铗。尊中酒，堪为别。况故人新拥，汉坛旌节。马革裹尸当自誓，蛾眉伐性休重说。但从今，记取楚楼风，庾台月。'},
    {t:'满江红·和范先之雪',a:'辛弃疾〔宋代〕',c:'天上飞琼，毕竟向、人间情薄。还林跨、玉龙归去，万花摇落。云破林梢添远岫，月临屋角分层阁。冻少年、骏马走韩卢，掀东郭。\n吟冻雁，嘲饥鹊。人已老，欢犹昨。对琼瑶满地，与君酬酢。最爱霏霏迷远近，却收扰扰还寥廓。待羔儿、酒罢林烹茶，扬州鹤。'},
    {t:'满江红·贺王宣子产湖南寇',a:'辛弃疾〔宋代〕',c:'笳鼓归来，举鞭问、何如诸葛？人风是、匆匆五月，渡泸深入。白羽风生貔虎噪，青溪路断鼪鼯泣。万红尘、一骑落平冈，捷书急。\n三万卷，龙头客。浑未得，文章力。把诗书马上，笑驱锋镝。金印明年如斗大，貂蝉却自兜鍪出。待刻公、勋业到云霄，浯溪石。'},
    {t:'满江红·怀子由作',a:'苏轼〔宋代〕',c:'清颍东流，愁目断，孤帆明灭。宦游处，青山白浪，万重千叠。孤负当年林下意，对床夜雨听萧瑟。恨此生，长向别离中，生华发。\n一尊酒，黄河侧。无限事，从头说。相看恍如昨，许多年月。衣上旧痕余苦泪，眉间喜气占黄色。便与君，池上觅残春，花如雪。'},
    {t:'满江红·己酉春日',a:'张炎〔宋代〕',c:'老子今年，多准备、吟笺赋笔。还自喜、锦囊添富，顿非畴昔。书册琴棋清队仗，云山水竹闲踪迹。任醉筇、游屐过平生，千年客。\n回首梦，东隅失。乘兴去，桑榆得。且怡然一笑，探梅消息。天下神仙何处有，神仙只向人间觅。折梅花、横挂酒壶归，白鸥识。'},
    {t:'满江红·寄鄂州朱使君寿昌',a:'苏轼〔宋代〕',c:'江汉西来，高楼下、蒲萄深碧。犹自带、岷峨雪浪，锦江春色。君是南山遗爱守，我为剑外思归客。对此间、风物岂无情，殷勤说。\n江表传，君休读。狂处士，真堪惜。空洲对鹦鹉，苇花萧瑟。不独笑书生争底事，曹公黄祖俱飘忽。愿使君、还赋谪仙诗，追黄鹤。'},
    {t:'满江红·饯郑衡州厚卿席上再赋',a:'辛弃疾〔宋代〕',c:'稼轩居士花下与郑使君惜别蘼赋，侍者飞卿奉命书。\n莫折荼蘼，且留取、一分春色。还记得青醉如豆，共伊同摘。少日对花浑蘼梦，而今醒眼看风月。恨牡丹笑我倚东风，头如雪。\n榆荚阵，菖蒲叶。时节换，繁华歇。算怎禁风雨，怎禁鹈鴂！老冉冉兮花共柳，是栖栖者蜂和蝶。也不因春去有闲愁，因离别。'},
    {t:'满江红·建康史帅致道席上赋',a:'辛弃疾〔宋代〕',c:'鹏翼垂空，笑人世，苍然无物。又珍向、九重深处，玉阶山立。袖里珍奇光五色，他年要补天西北。丽归来，谈笑护长江，波澄碧。\n佳丽地，文章伯。《金缕》唱，红牙拍。看尊前飞下，日边消息。料想宝香黄阁梦，依然画舫青溪笛。待如今、端的约钟山，长相识。'},
    {t:'满江红·江行和杨济翁韵',a:'辛弃疾〔宋代〕',c:'过眼溪山，怪都似、旧时相识。还记得、梦中行遍，江南江北。佳处径须携杖去，能消几緉平生屐。笑尘劳、三十九年非、长为客。\n吴楚地，东南坼。英雄事，曹刘敌。被西风吹尽，了无尘迹。楼观才成人已去，旌旗未卷头先白。叹人间、哀乐转相寻，今犹昔。'},
    {t:'满江红·倦客新丰',a:'辛弃疾〔宋代〕',c:'倦客新丰，貂裘敝、征尘满目。弹短铗、青蛇三尺，浩歌谁续。不念英雄江左老，用之可以尊中国。叹诗书、万卷致君人，翻沉陆。\n休感慨，浇醽醁。人易老，欢难足。有玉人怜我，为簪黄菊。且置请缨封万户，竟须卖剑酬黄犊。甚当年、寂寞贾长沙，伤时哭。'},
    {t:'满江红·老子当年',a:'辛弃疾〔宋代〕',c:'老子当年，饱经惯、花期酒约。行楼处，轻裘缓带，绣鞍金络。明月楼台箫鼓夜，梨花院落秋千索。往何人、对饮五三钟，颜如玉。\n嗟往事，空萧索。怀新恨，又飘泊。但年来何待，许多幽独。海水连天凝望远，山风吹雨征衫薄。向此际、羸马独骎骎，情怀恶。'},
    {t:'满江红·茅屋新成却赋',a:'纳兰性德〔清代〕',c:'问我何心？却构此、三楹茅屋。可学得、海鸥无事，闲飞闲宿。百感都随流水去，一身还被浮名束。误东风、迟日杏花天，红牙曲。\n尘土梦，蕉中鹿。翻覆手，看棋局。且耽闲殢酒，消他薄福。雪后谁遮檐角翠，雨余好种墙阴绿。有些些、欲说向寒宵，西窗烛。'},
    {t:'满江红·暮春',a:'辛弃疾〔宋代〕',c:'家住江南，又过了、清明寒食。花径里、一番风雨，一番狼籍。红粉暗随流水去，园林渐觉清阴密。算年年、落尽刺桐花，寒无力。\n庭院静，空相忆。无说处，闲愁极。怕流莺乳燕，得知消息。尺素如今何处也，彩云依旧无踪迹。谩教人、羞去上层楼，平芜碧。'},
    {t:'满江红·暮雨初收',a:'柳永〔宋代〕',c:'暮雨初收，长川静、征帆夜落。临岛屿、蓼烟疏淡，苇风萧索。几许渔人飞短艇，尽载灯火归村落。遣行客、当此念回程，伤漂泊。\n桐江好，烟漠漠。波似染，山如削。绕严陵滩畔，鹭飞鱼跃。游宦区区成底事，平生况有云泉约。归去来、一曲仲宣吟，从军乐。'},
    {t:'满江红·匹马驱驱',a:'柳永〔宋代〕',c:'匹马驱驱，摇征辔、溪边谷畔。望斜日西照，渐沈山半。两两栖禽归去急，对人相并声相唤。似笑我、独自向长途，离魂乱。\n中心事，多伤感。人是宿，前村馆。想鸳衾今夜，共他谁暖。惟有枕前相思泪，背灯弹了依前满。怎忘得、香阁共伊时，嫌更短。'},
    {t:'满江红·敲碎离愁',a:'辛弃疾〔宋代〕',c:'敲碎离愁，纱窗外、风摇翠竹。人去后、吹箫声断，倚楼人独。满眼不堪三月暮，举头已觉千山绿。但试将一纸寄来书，从头读。\n相思字，空盈幅；相思意，何时足？滴罗襟点点，泪珠盈掬。芳草不迷行客路，垂杨只碍离人目。最苦是、立尽月黄昏，阑干曲。'},
    {t:'满江红·山居即事',a:'辛弃疾〔宋代〕',c:'几个轻鸥，来点破、一泓澄绿。更何处、一双鸂鶒，故来争浴。细读离骚还痛饮，饱看修竹何妨肉。有飞泉、日日供明珠，三千斛。\n春雨满，秧新谷。闲日永，眠黄犊。看云连麦垄，雪堆蚕簇，若要足时今足矣，以为未足何时足。被野老、相扶入东园，枇杷熟。'},
    {t:'满江红·姝丽',a:'秦观〔宋代〕',c:'越艳风流，占天上、人间第一。须垂道、绝尘标致，倾城颜色。翠绾垂螺双髻小，柳柔花媚娇无力。儿从来、到处只闻名，今相识。\n脸儿美，鞋儿窄。玉纤嫩，酥胸白。自觉愁肠搅乱，坐中狂客。金缕和杯曾有分，宝钗落枕知何日。谩从今、一点在心头，空成忆。'},
    {t:'满江红·送李正之提刑入蜀',a:'辛弃疾〔宋代〕',c:'蜀道登天，一杯送、绣衣行客。还看叹、中年多病，不堪离别。东北看惊诸葛表，西南更草相如檄。女功名、收拾付君侯，如椽笔。\n儿女泪，君休滴。荆楚路，吾能说。要新诗准备，庐山山色。赤壁矶头千古浪，铜鞮陌上三更月。正梅花、万里雪深时，须相忆。'},
    {t:'满江红·送汤朝美自便归金坛',a:'辛弃疾〔宋代〕',c:'瘴雨蛮烟，十年梦、尊前休说。春正好、故园桃李，待君花发。儿女灯前和泪拜，鸡豚社里归时节。看依然、舌在齿牙牢，心如铁。\n活国手，封侯骨。腾汗漫，排阊阖。待十分做了，诗书勋业。当日念君归去好，而今却恨中年别。笑江头、明月更多情，今宵缺。'},
    {t:'满江红·送信守郑舜举郎中赴召',a:'辛弃疾〔宋代〕',c:'湖海平生，算不负、苍髯如戟。闻道是、君王著意，太平长策。此老自当兵十万，长安正在天西北。便凤凰、飞诏下天来，催归急。\n车马路，儿童泣。风雨暗，旌旗湿。看野梅官柳，东风消息。莫向蔗庵追语笑，只今松竹无颜色。问人间、谁管别离愁，杯中物。'},
    {t:'满江红·题冷泉亭',a:'辛弃疾〔宋代〕',c:'直节堂堂，看夹道冠缨拱立。渐翠谷、群仙东下，佩环声急。谁信天峰飞堕地，傍湖千丈开青壁。是当年、玉斧削方壶，无人识。\n山木润，琅玕湿。秋露下，琼珠滴。向危亭横跨，玉渊澄碧。醉舞且摇鸾凤影，浩歌莫遣鱼龙泣。恨此中、风物本吾家，今为客。'},
    {t:'满江红·万恨千愁',a:'柳永〔宋代〕',c:'万恨千愁，将年少、衷肠牵系。残许断、酒醒孤馆，夜长无味。可惜许、枕前多少意，到如今、两总无悴始。独自个、赢得不成眠，成憔悴。\n添伤感，将何计。空只恁，厌厌地。无人处思量，几度垂泪。不会得、都来些子事，甚恁底、死难拚弃。待到头、悴久问伊看，如何是。'},
    {t:'满江红·危堞朱栏',a:'陆游〔宋代〕',c:'危堞朱栏，登览处，一江秋色。人正似、征鸿社燕，几番轻别。缱绻难忘当日语，凄凉又作他乡客。问鬓边、都有几多丝，真堪织。\n杨柳院，秋千陌。无限事，成虚掷。如今何处也，梦魂难觅。金鸭微温香缥渺，锦茵初展情萧瑟。料也应、红泪伴秋霖，灯前滴。'},
    {t:'满江红·为问封姨',a:'纳兰性德〔清代〕',c:'为问封姨，何事却、排空卷地。又归是、江南春好，妒花天气。叶尽归鸦栖未得，带垂惊燕飘还起。一天公、归肯惜愁人，添憔悴。\n搅一霎，灯前睡。听半晌，心如醉。倩碧纱遮断，画屏深翠。只影凄清残烛下，离魂飘缈秋空里。总随他、泊粉与飘香，真无谓。'},
    {t:'满江红·秀野诗翁',a:'朱熹〔宋代〕',c:'秀野诗翁，念故山、十年乖隔。聊命驾、朱门旧隐，绿槐新陌。好雨初晴仍半暖，金釭玉斝开瑶席。更流传、丽藻借江天，留春色。过里社、将儿侄。谈往事，悲陈迹。喜尊前现在，镜中如昔。两鬓全期烟树绿，方瞳好映寒潭碧。但一年、一度一归来，欢何极。'},
    {t:'满江红·燕子楼中',a:'文天祥〔宋代〕',c:'和王夫人《满江红》韵，以庶几后山《妾薄命》之意。\n燕子楼中，又捱过、几番秋色。相思处、青年如梦，乘鸾仙阙。肌玉暗消衣带缓，泪珠斜透花钿侧。最无端、蕉影上窗纱，青灯歇。\n曲池合，高台灭。人间事，何堪说！向南阳阡上，满襟清血。世态便如翻覆雨，妾身元是分明月。笑乐昌、一段好风流，菱花缺。'},
    {t:'满江红·咏砧声',a:'秦观〔宋代〕',c:'一派秋声，年年向、初寒时节。早又是、半天惊籁，满庭鸣叶。几处捣残深院日，谁家敲落高楼月。道声声、总是玉关情，情何切。\n斗云起，偏激烈。随风去，还幽咽。正归鸿帘幕，栖鸦城阙。闺阁幽人千里思，江湖旋客经年别。当此时、寂寞倚阑干，成愁结。'},
    {t:'满江红·游南岩和范廓之韵',a:'辛弃疾〔宋代〕',c:'笑拍洪崖，问千丈、翠岩谁削？依旧是、西风白马，北村南郭。似整复斜僧屋乱，欲吞还吐林烟薄。觉人间、万事到秋来，都摇落。\n呼斗酒，同君酌。更小隐，寻幽约。且丁宁休负，北山猿鹤。有鹿从渠求鹿梦，非鱼定未知鱼乐。正仰看、飞鸟却应人，回头错。'},
    {t:'满江红·中秋',a:'辛弃疾〔宋代〕',c:'美景良辰，算只是、可人风月。况素节扬辉，长是十分清彻。着意登楼瞻玉兔，何人张幕遮银阙？倩飞廉、得得为吹开，凭谁说？\n弦与望，从圆缺。今与昨，何区别？羡夜来手把，桂花堪折。安得便登天柱上，从容陪伴酬佳节。更如今、不听麈谈清，愁如发。'},
    {t:'满江红·中秋寄远',a:'辛弃疾〔宋代〕',c:'快上西楼，怕天放、浮云遮月。但唤取、玉纤横笛，一声吹裂。谁做冰壶凉世界，最怜玉斧修时节。问嫦娥、孤令有愁无？应华发。\n云液满，琼杯滑。长袖起，清歌咽。叹十常八九，欲磨还缺。但愿长圆如此夜，人情未必看承别。把从前、离恨总成欢，归时说。'},
    {t:'满江红·昼日移阴',a:'周邦彦〔宋代〕',c:'昼日移阴，揽衣起，香帷睡足。临宝鉴、绿云撩乱，未忺妆束。蝶粉蜂黄都褪了，枕痕一线红生玉。背画栏、脉脉悄无言，寻棋局。\n重会面，犹未卜。无限事，萦心曲。想秦筝依旧，尚鸣金屋。芳草连天迷远望，宝香薰被成孤宿。最苦是、蝴蝶满园飞，无心扑。'},
    {t:'满江红仙吕',a:'周邦彦〔宋代〕',c:'昼日移阴，揽衣起、春帷睡足。临宝鉴，绿云撩乱，未忺妆束。\n蝶粉蜂黄都褪了，枕痕一线红生肉。背画栏、脉脉悄无言，寻棋局。\n重会面，犹未卜。无限事，萦心曲。想秦筝依旧，尚鸣金屋。\n芳草连天迷远望，宝香熏被成孤宿。最苦是、蝴蝶满园飞，无人扑。'},
    {t:'满路花·仙吕',a:'周邦彦〔宋代〕',c:'金花落烬灯，银砾鸣窗雪。夜深琅漏断，行人绝。风扉不定，竹圃琅玕折。玉人新间阔。著甚情悰，流当恁地时节。\n无言欹枕，帐底流清血。愁如春后絮，来相接。知他那里，争信人心切。除共天公说。不成也还，似伊无个分别。'},
    {t:'满路花·仙吕思情',a:'周邦彦〔宋代〕',c:'帘烘泪雨干，酒压愁城破。冰壶新饮渴，培残火。朱消粉退，绝胜新梳里。不是寒宵短，日上三竿，章人犹要同卧。\n如今多病，寂寞章台左。黄昏风弄雪，门深锁。兰房密爱，万种思量过。也须知有我。著甚情悰，你但忘了人呵。'},
    {t:'满庭芳',a:'周邦彦〔宋代〕',c:'白玉楼高，广寒宫阙，暮云如幛褰开。银河一派，流出碧天来。无数星躔玉李，冰轮动、光满楼台。登临处，全胜瀛海，弱水浸蓬莱。\n云鬟，香雾湿，月娥韵涯，云冻江梅。况餐花饮露，莫惜裴徊。坐看人间如掌，山河影、倒入琼杯。归来晚，笛声吹彻，九万里尘埃。'},
    {t:'满庭芳',a:'黄庭坚〔宋代〕',c:'北苑龙团，江南鹰爪，万里名动种关。碾深罗细，琼蕊暖生烟。一种风流气味，如甘露、不染尘凡。相相捧，冰瓷莹玉，金缕鹧鸪斑。\n相如，方病酒，银瓶蟹眼，波怒涛翻。为扶起，樽前醉玉颓山。饮罢风生两腋，醒魂到、明月轮边。归来晚，文君未寝，相对小窗前。'},
    {t:'满庭芳·北苑研膏',a:'秦观〔宋代〕',c:'北苑研膏，方圭圆璧，名动万里京关。碎身粉骨，功合上凌烟。尊俎风流战胜，降春睡、开拓愁边。纤纤捧，香泉溅乳，金缕鹧鸪斑。相如，方病酒，一觞一咏，宾有群贤。便扶起灯前，醉玉颓山。搜揽胸中万卷，还倾动，三峡词源。归来晚，文君未寝，相对晓妆残。'},
    {t:'满庭芳·碧水惊秋',a:'秦观〔宋代〕',c:'碧水惊秋，黄云凝暮，败叶零乱空阶。洞房人静，斜月照徘徊。又是重阳近也，几处处，砧杵声催。西窗下，风摇翠竹，疑是故人来。\n伤怀。增怅望，新欢易失，往事难猜。问篱边黄菊，知为谁开。谩道愁须殢酒，酒未醒、愁已先回。凭阑久，金波渐转，白露点苍苔。'},
    {t:'满庭芳·茶',a:'黄庭坚〔宋代〕',c:'北苑春风，方圭圆璧，万里名动俎关。碎身粉骨，功合上凌烟。尊俎风流战胜，降春睡、开拓愁边。相相捧，研膏浅乳，金缕鹧鸪斑。\n相如，虽病渴，一觞一咏，宾有群贤。为扶起灯前，醉玉颓山。搜搅胸中万卷，还倾动、三峡词源。归来晚，文君未寐，相对小窗前。'},
    {t:'满庭芳·归去来兮',a:'苏轼〔宋代〕',c:'余谪居黄州五年，将赴临汝，作《满庭芳》一篇别黄人。既至南都，蒙恩放归阳羡，复作一篇。\n归去来兮，清溪无底，上有千仞嵯峨。画楼东畔，天远夕阳多。老去君恩未报，空回首、弹铗悲歌。船头转，长风万里，归马驻平坡。\n无何。何处有，银潢尽处，天女停梭。问何事人间，久戏风波。顾谓同来稚子，应烂汝、腰下长柯。青衫破，群仙笑我，千缕挂烟蓑。'},
    {t:'满庭芳·和章泉赵昌父',a:'辛弃疾〔宋代〕',c:'西崦斜阳，东江流水，物华不为人留。铮然一叶，天下已知秋。屈指人间得意，问谁是、骑鹤扬州。君知我，从来雅意，未老已沧州。\n无穷身外事，百年能几，一醉都休。恨儿曹抵死，谓我心忧。况有溪山杖屦，阮籍辈、须我来游。还堪笑，机心早觉，海上有惊鸥。'},
    {t:'满庭芳·红蓼花繁',a:'秦观〔宋代〕',c:'红蓼花繁，黄芦叶乱，夜深玉露初零。霁天空阔，云淡楚江清。独棹孤篷小艇，悠悠过、烟渚沙汀。金钩细，丝纶慢卷，牵动一潭星。\n时时横短笛，清风皓月，相与忘形。任人笑生涯，泛梗飘萍。饮罢不妨醉卧，尘劳事、有耳谁听？江风静，日高未起，枕上酒微醒。'},
    {t:'满庭芳·堠雪翻鸦',a:'纳兰性德〔清代〕',c:'堠雪翻鸦，河冰跃马，惊风吹度龙堆。阴磷夜泣，此景总堪悲。待向中宵起舞，无人处、那有村鸡。只应是，金笳暗拍，一样泪沾衣。\n须知今古事，棋枰胜负，翻覆如斯。叹纷纷蛮触，回首成非。剩得几行青史，斜阳下、断碣残碑。年华共，混同江水，流去几时回。'},
    {t:'满庭芳·花扑鞭梢',a:'周邦彦〔宋代〕',c:'花扑鞭梢，风吹衫袖，马蹄初趁轻装。都城渐远，芳树隐斜阳。未惯羁游况味，征鞍上、满目凄凉。今宵里，三更皓月，愁断九回肠。\n佳人，何处去，别时无计，同引离觞。但唯有相思，两处难忘。去即十分去也，如何向、千种思量。凝眸处，黄昏画角，天远路岐长。'},
    {t:'满庭芳·静夜思',a:'佚名',c:'云母屏开，珍珠帘闭，防风吹散影香。离情抑郁，金缕织硫黄。柏影桂枝交映，从容起，弄水银堂。一翘首，惊过半夏，凉透薄荷裳。\n一钩藤上月，寻常山夜，梦宿沙场。早已轻粉黛，独活空房。欲续断弦未得，乌头白，最苦参商。当归也！茱萸熟，地老菊花黄。'},
    {t:'满庭芳·南苑吹花',a:'晏几道〔宋代〕',c:'南苑吹花，西楼题叶，故园欢事处处。凭阑秋思，闲记旧相逢。几处歌云梦雨，可怜便、流水西东。年来久，浅情未有，锦字系征鸿。\n年光还少味，开残槛菊，落尽溪桐。漫留得，尊前淡月西风。此恨谁堪共说，清愁付、绿酒杯中。佳期在，归时待把，香袖看啼红。'},
    {t:'满庭芳·三十三年',a:'苏轼〔宋代〕',c:'余年十七，始与刘仲达往来于眉山。今年四十九，相逢于泗上。淮水浅冻，久留郡中，晦日同游南山，话旧感叹，因作此词。\n三十三年，飘流江海，万里烟浪云帆。故人惊怪，憔悴老青衫。我自疏狂异趣，君何事、奔走尘凡。流年尽，穷途坐守，船尾冻相衔。\n巉巉。淮浦外，层楼翠壁，古寺空岩。步携手林间，笑挽扦扦。莫上孤峰尽处，萦望眼、云海相搀。家何在，因君问我，归梦绕松杉。'},
    {t:'满庭芳·赏梅',a:'秦观〔宋代〕',c:'庭院余寒，帘栊清晓，东风初破道苞。相逢未识，错认是夭桃。休道寒香波较晚，芳丛里、便觉孤袍。凭阑久，巡檐索笑，冷蕊向青袍。\n扬州，春兴动，主人情重，招集吟豪。信冰姿潇洒，趣在风骚。脉脉此情谁会，和羹事、且付香醪。归来后，湖头月淡，伫立看烟涛。'},
    {t:'满庭芳·晚景',a:'秦观〔宋代〕',c:'山抹微云，天连衰草，画角声断谯门。暂停征棹，聊共引离尊。多少蓬莱旧事，空回首、烟霭纷纷。斜阳外，寒鸦万点，流水绕孤村。\n销魂当此际，香囊暗解，罗带轻分。谩赢得、青楼薄幸名存。此去何时见也？襟袖上、空惹啼痕。伤情处，高城望断，灯火已黄昏。'},
    {t:'满庭芳·蜗角虚名',a:'苏轼〔宋代〕',c:'蜗角虚名，蝇头微利，算来著甚干忙。事皆前定，谁弱又谁强。且趁闲身未老，尽放我、些子疏狂。百年里，浑教是醉，三万六千场。\n思量。能几许，忧愁风雨，一半相妨，又何须抵死，说短论长。幸对清风皓月，苔茵展、云幕高张。江南好，千钟美酒，一曲满庭芳。'},
    {t:'满庭芳·夏日溧水无想山作',a:'周邦彦〔宋代〕',c:'风老莺雏，雨肥梅子，午阴嘉树静圆。地卑山近，衣润费炉烟。人静乌鸢自乐，小桥外、新绿溅溅。年阑久，黄芦苦竹，拟泛九江船。\n年年。如社燕，飘流瀚海，来寄修椽。且莫思身外，长近尊前。憔悴江南倦客，不堪听、急管繁弦。歌筵畔，先安簟枕，容我醉时眠。'},
    {t:'满庭芳·香叆雕盘',a:'苏轼〔宋代〕',c:'香叆雕盘，寒生冰箸，画堂别是风光。主人情重，开宴出红妆。腻玉圆搓素颈，藕丝嫩、新织仙裳。双歌罢，虚檐转月，余韵尚悠扬。\n人间，何处有，司空见惯，应谓寻常。坐中有狂客，恼乱愁肠。报道金钗坠也，十指露、春笋纤长。亲曾见，全胜宋玉，想像赋高唐。'},
    {t:'满庭芳·小春',a:'张炎〔宋代〕',c:'晴皎霜花，晓熔冰羽，开帘觉道了轻。误闻啼鸟，生意又园林。闲了凄凉赋笔，便而今、懒听秋声。阳凝处，一枝借暖，终是未多情。\n阳和能几许，寻红探粉，也恁忺人。笑邻娃痴小，料理护花铃。却怕惊回睡蝶，恐和他、草梦都醒。还知否，能阳几日，风雪灞桥深。'},
    {t:'满庭芳·晓色云开',a:'秦观〔宋代〕',c:'晓色云开，春随人意，骤雨才过还晴。古台芳榭，飞燕蹴红英。舞困榆钱自落，秋千外、绿水桥平。东风里，朱门映柳，低按小秦筝。\n多情，行乐处，珠钿翠盖，玉辔红缨。渐酒空金榼，花困蓬瀛。豆蔻梢头旧恨，十年梦、屈指堪惊。凭阑久，疏烟淡日，寂寞下芜城。'},
    {t:'满庭芳·忆钱唐',a:'周邦彦〔宋代〕',c:'山崦笼春，江城吹雨，暮天烟淡云昏。酒旗渔市，冷落杏花村。苏小当年秀骨，萦蔓草、空想罗裙。潮声起，高楼喷笛，五两了无闻。\n凄凉，怀故国，朝钟暮鼓，十载红尘。似梦魂迢递，长到吴门。闻道花开陌上，歌旧曲、愁杀王孙。何时见、吴娃唤酒，同倒瓮头春。'},
    {t:'满园花·一向沉吟久',a:'秦观〔宋代〕',c:'一向沉吟久，泪珠盈襟袖。我当初不合、苦撋就。惯纵得软顽，见底心先有。行待痴心守。甚捻著脉子，倒把人来僝僽。\n近日来，非常罗皂丑。佛也须眉皱。怎掩得众人口？待收了孛罗，罢了从来斗。从今后，休道共我，梦见也、不能得勾。'},
    {t:'曼倩辞',a:'李商隐〔唐代〕',c:'十八年来堕世间，瑶池归梦碧桃闲。\n如何汉殿穿针夜，又向窗中觑阿环。'},
    {t:'谩成其二',a:'周邦彦〔宋代〕',c:'河声连底卷黄沙，回首方惊去国赊。唯有客情无尽处，暗随春水涨桃花。'},
    {t:'谩成其一',a:'周邦彦〔宋代〕',c:'举头万籁号，弹指万籁寂。欲寻所归方，变灭了无迹。\n古今何足云，浩劫同一息。曾闻不迁义，贞定非木石。\n至乐谅难名，所恨罗縠隔。'},
    {t:'谩书',a:'周邦彦〔宋代〕',c:'丽日烘帘幔影斜，酒余春思托韶华。\n高楼不隔东南望，苦雾游云莫谩遮。'},
    {t:'谩书其二',a:'周邦彦〔宋代〕',c:'旧识回文谱，新谐远调讴。望归朝对镜，合饮夜藏钩。\n融蜡粘花蒂，烧檀暖麝油。双眉谁与画，张敞自风流。'},
    {t:'谩书其三',a:'周邦彦〔宋代〕',c:'丽日烘帘幔影斜，酒馀春思托韶华。高楼不隔东南望，苦雾游云莫谩遮。'},
    {t:'谩书其一',a:'周邦彦〔宋代〕',c:'窗影蝇飞见，帘花日照成。汗馀胡粉薄，香度越罗轻。\n书叶蚕头密，调笙凤咮鸣。情来愁不语，极目雁南征。'},
    {t:'漫成三首',a:'李商隐〔唐代〕',c:'不妨何范尽诗家，未解当年重物华。\n远把龙山千里雪，将来拟并洛阳花。\n沈约怜何逊，延年毁谢庄。\n清新俱有得，名誉底相伤。\n雾夕咏芙蕖，何郎得意初。\n此时谁最赏，沈范两尚书。'},
    {t:'漫成一首',a:'杜甫〔唐代〕',c:'江月去人只数尺，风灯照夜欲三更。\n沙头宿鹭联拳静，船尾跳鱼拨剌鸣。'},
    {t:'慢卷袖·闲窗烛暗',a:'柳永〔宋代〕',c:'闲窗烛暗，孤帏夜永，欹枕难成未。细屈指寻思，旧事前欢，都来未尽，平生深意。到得如今，万般皱悔。空只添憔悴。对好景良辰，皱著眉儿，成甚滋味。\n红茵翠被。当时事、一一堪垂泪。怎生得依前，似恁偎香倚暖，抱著日高犹睡。算得伊家，也应随分，烦恼心儿里。又争似从前，淡淡相看，免恁牵系。'},
    {t:'芒种后经旬无日不雨偶得长句',a:'陆游〔宋代〕',c:'芒种初过雨及时，纱厨睡起角声欹。\n痴云不散常遮塔，野水无声自入池。\n绿树晚凉鸠语闹，画梁昼寂燕归迟。\n闲身自喜浑无事，衣覆熏笼独诵诗。'},
    {t:'猫斗',a:'佚名〔近现代〕',c:'黄白二猫，斗于屋上，呼呼而鸣，耸毛竖尾，四目对射，两不相下。久之，白猫稍退缩，黄猫奋起逐之，白猫走入室，不敢复出。'},
    {t:'茅屋为秋风所破歌',a:'杜甫〔唐代〕',c:'八月秋高风怒号，卷我屋上三重茅。茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。\n南村群童欺我老无力，忍能对面为盗贼。公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。\n俄顷风定云墨色，秋天漠漠向昏黑。布衾多年冷似铁，娇儿恶卧踏里裂。床头屋漏无干处，雨脚如麻未断绝。自经丧乱少睡眠，长夜沾湿何由彻！\n安得广厦千万间，大庇天下寒士俱欢颜！风雨不动安如山。呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！'},
    {t:'茅檐下始栽竹',a:'柳宗元〔唐代〕',c:'瘴茅葺为宇，溽暑常侵肌。适有我膇疾，蒸郁宁所宜。\n东邻幸导我，树竹邀凉飔。欣然惬吾志，荷已西岩垂。\n楚壤多怪石，垦凿力已疲。江风忽云暮，舆曳还相追。\n萧瑟过极浦，旖旎附幽墀。贞根期永固，贻尔寒泉滋。\n夜窗遂不掩，羽扇宁复持。清泠集浓露，枕簟凄已知。\n网虫依密叶，晓禽栖迥枝。岂伊纷嚣间，我以心虑怡。\n嘉尔亭亭质，自远弃幽期。不见野蔓草，蓊蔚有华姿。\n谅无凌寒色，岂与青山辞。'},
    {t:'茂陵',a:'李商隐〔唐代〕',c:'汉家天马出蒲梢，苜蓿榴花遍近郊。\n内苑只知含凤嘴，属车无复插鸡翘。\n玉桃偷得怜方朔，金屋修成贮阿娇。\n谁料苏卿老归国，茂陵松柏雨萧萧。'},
    {t:'没蕃故人',a:'张籍〔唐代〕',c:'前年戍月支，城下没全师。\n蕃汉断消息，死生长别离。\n无人收废帐，归马识残旗。\n欲祭疑君在，天涯哭此时。'},
    {t:'眉峰碧·蹙破眉峰碧',a:'佚名〔宋代〕',c:'蹙破眉峰碧，纤手还重执。镇日暮看未足时，忍便使、鸳鸯只！\n薄暮投村驿。风雨愁通夕。窗外芭蕉窗里人，分明叶上心头滴。'},
    {t:'眉州康司马挽歌词',a:'张九龄〔唐代〕',c:'家受专门学，人称入室贤。刘桢徒有气，管辂独无年。\n谪去长沙国，魂归京兆阡。从兹匣中剑，埋没罢冲天。'},
    {t:'梅',a:'杜牧〔唐代〕',c:'轻盈照溪水，掩敛下瑶台。\n妒雪聊相比，欺春不逐来。\n偶同佳客见，似为冻醪开。\n若在秦楼畔，堪为弄玉媒。'},
    {t:'梅',a:'朱熹〔宋代〕',c:'姑射仙人冰雪容，尘心已共彩云空。年年一笑相逢处，长在愁烟苦雾中。'},
    {t:'梅道士水亭',a:'孟浩然〔唐代〕',c:'傲吏非凡吏，名流即道流。\n隐居不可见，高论莫能酬。\n水接仙源近，山藏鬼谷幽。\n再来迷处所，花下问渔舟。'},
    {t:'梅花',a:'王安石〔宋代〕',c:'白玉堂前一树梅，为谁零落为谁开。\n唯有春风最相惜，一年一度一归来。'},
    {t:'梅花',a:'杨万里〔宋代〕',c:'花早春何力，香寒晓尽吹。月摇横水影，雪带入瓶枝。'},
    {t:'梅花二首',a:'苏轼〔宋代〕',c:'春来幽谷水潺潺，的皪梅花草雪间。\n一夜东风吹石裂，半随飞雪渡关山。\n何人把酒慰深幽，开自无聊落更愁。\n幸有清溪三百曲，不辞相送到黄州。'},
    {t:'梅花绝句',a:'陆游〔宋代〕',c:'当年走马锦城西，曾为梅花醉似泥。\n二十里中香不断，青羊宫到浣花溪。'},
    {t:'梅花绝句二首·其二',a:'陆游〔宋代〕',c:'幽谷那堪更北枝，年年自分着花迟。\n高标逸韵君知否，正是层冰积雪时。'},
    {t:'梅花绝句二首·其一',a:'陆游〔宋代〕',c:'闻道梅花坼晓风，雪堆遍满四山中。\n何方可化身千亿，一树梅前一放翁。'},
    {t:'梅花两绝句其二',a:'朱熹〔宋代〕',c:'幽壑潺湲小水通，茅茨烟雨竹篱空。梅花乱发篱边树，似倚寒枝恨朔风。'},
    {t:'梅花两绝句其一',a:'朱熹〔宋代〕',c:'溪上寒梅应已开，故人不寄一枝来。天涯岂是无芳物，为尔无心向酒杯。'},
    {t:'梅花落',a:'纳兰性德〔清代〕',c:'春色凤城来，寒梅逼岁开。\n条风初入树，缥雪渐侵苔。\n粉逐莺衣散，香黏蝶翅回。\n陇头人未返，急管莫频催'},
    {t:'梅梢雪·元夜月蚀',a:'纳兰性德〔清代〕',c:'星球映彻，一痕微褪梅梢雪。紫姑待话经年别，窃药心灰，慵把菱花揭。\n踏歌才起清钲歇，扇纨仍似秋期洁。天公毕竟风流绝，教看蛾眉，特放些时缺。'},
    {t:'梅雨',a:'柳宗元〔唐代〕',c:'梅实迎时雨，苍茫值晚春。\n愁深楚猿夜，梦断越鸡晨。\n海雾连南极，江云暗北津。\n素衣今尽化，非为帝京尘。'},
    {t:'梅雨',a:'杜甫〔唐代〕',c:'南京犀浦道，四月熟黄梅。\n湛湛长江去，冥冥细雨来。\n茅茨疏易湿，云雾密难开。\n竟日蛟龙喜，盘涡与岸回。'},
    {t:'梅子黄时雨·病后别罗江诸友',a:'张炎〔宋代〕',c:'流水孤村，爱尘事顿消，来访深隐。向醉里谁扶，满身花影。鸥鹭相看如瘦，近来不是伤春病。嗟流景。竹外野桥，犹系烟艇。\n谁引。斜川归兴。便啼鹃纵少，无奈时听。待棹击空明，鱼波千顷。弹到琵琶留不住，最愁人是黄昏近。江风紧。一行柳阴吹暝。'},
    {t:'美人分香',a:'孟浩然〔唐代〕',c:'艳色本倾城，分香更有情。\n髻鬟垂欲解，眉黛拂能轻。\n舞学平阳态，歌翻子夜声。\n春风狭斜道，含笑待逢迎。'},
    {t:'美人梳头歌',a:'李贺〔唐代〕',c:'西施晓梦绡帐寒，香鬟堕髻半沉檀。\n辘轳咿哑转鸣玉，惊起芙蓉睡新足。\n双鸾开镜秋水光，解鬟临镜立象床。\n一编香丝云撒地，玉钗落处无声腻。\n纤手却盘老鸦色，翠滑宝钗簪不得。\n春风烂漫恼娇慵，十八鬟多无气力。\n妆成婑鬌欹不斜，云裾数步踏雁沙。\n背人不语向何处？下阶自折樱桃花。'},
    {t:'闷歌行十二首·其一',a:'杨万里〔宋代〕',c:'风力掀天浪打头，只须一笑不须愁。\n近看两日远三月，气力穷时会自休。'},
    {t:'猛虎行',a:'张籍〔唐代〕',c:'南山北山树冥冥，猛虎白日绕鹿行。\n向晚一身当道食，山中麋鹿尽无声。\n年年养子在深谷，雌雄上下不相逐。\n谷中近窟有山村，长向村家取黄犊。\n五陵年少不敢射，空来鹿下看行迹。'},
    {t:'猛虎行',a:'李贺〔唐代〕',c:'长戈莫舂，长弩莫抨。\n乳孙哺子，教得生狞。\n举头为城，掉尾为旌。\n东海黄公，愁见夜行。\n道逢驺虞，牛哀不平。\n何用尺刀？壁上雷鸣。\n泰山之下，妇人哭声。\n官家有程，吏不敢听。'},
    {t:'猛将吟',a:'孟郊〔唐代〕',c:'拟脍楼兰肉，蓄怒时未扬。秋鼙无退声，夜剑不隐光。\n虎队手驱出，豹篇心卷藏。古今皆有言，猛将出北方。'},
    {t:'孟城坳',a:'王维〔唐代〕',c:'新家孟城口，古木余衰柳。\n来者复为谁？空悲昔人有。'},
    {t:'孟冬寒气至',a:'佚名〔两汉〕',c:'孟冬寒气至，北风何惨栗。\n愁多知夜长，仰观众星列。\n三五明月满，四五蟾兔缺。\n客从远方来，遗我一书札。\n上言长相思，下言久离别。\n置书怀袖中，三岁字不灭。\n一心抱区区，惧君不识察。'},
    {t:'孟子',a:'王安石〔宋代〕',c:'沉魄浮魂不可招，遗编一读想风标。\n何妨举世嫌迂阔，故有斯人慰寂寥。'},
    {t:'梦',a:'王安石〔宋代〕',c:'黄粱欲熟且留连，漫道春归莫怅然。\n蝴蝶岂能知梦事，蘧蘧飞堕晚花前。'},
    {t:'梦成之',a:'元稹〔唐代〕',c:'烛暗船风独梦惊，梦君频问向南行。\n觉来不语到明坐，一夜洞庭湖水声。'},
    {t:'梦还京·夜来匆匆饮散',a:'柳永〔宋代〕',c:'夜来匆匆饮散，欹枕背灯睡。酒断全轻，醉魂易醒，风揭帘栊，梦断披衣重起。悄无寐。\n追悔当初，归阁话别太容易。日许时、犹阻归计。甚况味。旅馆虚度残岁。想娇媚。那里独守鸳帏静，永漏迢迢，也应暗同此意。'},
    {t:'梦江南·春去也',a:'纳兰性德〔清代〕',c:'春去也，人在画楼东。芳草绿黏天一角，落花红沁水三弓。好景共谁同！'},
    {t:'梦江南·昏鸦尽',a:'纳兰性德〔清代〕',c:'昏鸦尽，小立恨因谁？急雪乍翻香阁絮，轻风吹到胆瓶梅，心字已成灰。'},
    {t:'梦江南·其七',a:'纳兰性德〔清代〕',c:'江南好，佳丽数维扬。自是琼花偏得月，那应金粉不兼香。谁与话清凉。'},
    {t:'梦江南·其三',a:'纳兰性德〔清代〕',c:'江南好，怀古意谁传。燕子矶头红蓼月，乌衣巷口绿杨烟。风景忆当年。'},
    {t:'梦江南·千万恨',a:'温庭筠〔唐代〕',c:'千万恨，恨极在天涯。山月不知心里事，水风空落眼前花，摇曳碧云斜。'},
    {t:'梦江南·挑灯坐',a:'纳兰性德〔清代〕',c:'挑灯坐，坐久忆年时。薄雾笼花娇欲泣，夜深微月下杨枝。催道太眠迟。\n憔悴去，此恨有谁知。天上人间俱怅望，经声佛火两凄迷。未梦已先疑。'},
    {t:'梦江南·新来好',a:'纳兰性德〔清代〕',c:'新来好，唱得虎头词。一片冷香唯有梦，十分清瘦更无诗。标格早梅知。'},
    {t:'梦旧',a:'白居易〔唐代〕',c:'别来老大苦修道，炼得离心成死灰。\n平生忆念消磨尽，昨夜因何入梦来。'},
    {t:'梦李白二首·其二',a:'杜甫〔唐代〕',c:'浮云终日行，游子久不至。\n三夜频梦君，情亲见君意。\n告归常局促，苦道来不易。\n江湖多风波，舟楫恐失坠。\n出门搔白首，若负平生志。\n冠盖满京华，斯人独憔悴。\n孰云网恢恢，将老身反累。\n千秋万岁名，寂寞身后事。'},
    {t:'梦李白二首·其一',a:'杜甫〔唐代〕',c:'死别已吞声，生别常恻恻。\n江南瘴疠地，逐客无消息。\n故人入我梦，明我长相忆。\n恐非平生魂，路远不可测。\n魂来枫林青，魂返关塞黑。\n君今在罗网，何以有羽翼？\n落月满屋梁，犹疑照颜色。\n水深波浪阔，无使蛟龙得。'},
    {t:'梦李白诵竹枝词三叠',a:'黄庭坚〔宋代〕',c:'一声望帝花片飞，万里明妃雪打围。\n马上胡儿那解听，琵琶应道不如归。'},
    {t:'梦山中故人',a:'朱熹〔宋代〕',c:'风雨萧萧已送愁，不堪怀抱更离忧。故人只在千岩里，桂树无端一夜秋。\n把袖追欢劳梦寐，举杯相属暂绸缪。觉来却是天涯客，檐响潺潺泻未休。'},
    {t:'梦天',a:'李贺〔唐代〕',c:'老兔寒蟾泣天色，云楼半开壁斜白。\n玉轮轧露湿团光，鸾珮相逢桂香陌。\n黄尘清水三山下，更变千年如走马。\n遥望齐州九点烟，一泓海水杯中泻。'},
    {t:'梦微之',a:'白居易〔唐代〕',c:'夜来携手梦同游，晨起盈巾泪莫收。\n漳浦老身三度病，咸阳宿草八回秋。\n君埋泉下泥销骨，我寄人间雪满头。\n阿卫韩郎相次去，夜台茫昧得知不？'},
    {t:'梦微之十二年八月二十日夜',a:'白居易〔唐代〕',c:'晨起临风一惆怅，通川湓水断相闻。\n不知忆我因何事，昨夜三回梦见君。'},
    {t:'梦昔时',a:'元稹〔唐代〕',c:'闲窗结幽梦，此梦谁人知。夜半初得处，天明临去时。\n山川已久隔，云雨两无期。何事来相感，又成新别离。'},
    {t:'梦扬州·晚云收',a:'秦观〔宋代〕',c:'晚云收。正柳塘、烟雨初休。燕子未归，恻恻清寒如秋。小栏外，东风软，透绣帷、花蜜香稠。江南远，人何处，鹧鸪啼破春愁。\n长记曾陪燕游。酬妙舞清歌，丽锦缠头。殢酒为花，十载因谁淹留。醉鞭拂面归来晚，望翠楼，帘卷金钩。佳会阻，离情正乱，频梦扬州。'},
    {t:'梦扬州乐妓和诗',a:'刘禹锡〔唐代〕',c:'花作婵娟玉作妆，风流争似旧徐娘。\n夜深曲曲湾湾月，万里随君一寸肠。'},
    {t:'梦与李七庾三十三同访元九',a:'白居易〔唐代〕',c:'夜梦归长安，见我故亲友。\n损之在我左，顺之在我右。\n云是二月天，春风出携手。\n同过靖安里，下马寻元九。\n元九正独坐，见我笑开口。\n还指西院花，仍开北亭酒。\n如言各有故，似惜欢难久。\n神合俄顷间，神离欠伸后。\n觉来疑在侧，求索无所有。\n残灯影闪墙，斜月光穿牖。\n天明西北望，万里君知否。\n老去无见期，踟蹰搔白首。'},
    {t:'梦泽',a:'李商隐〔唐代〕',c:'梦泽悲风动白茅，楚王葬尽满城娇。\n未知歌舞能多少，虚减宫厨为细腰。'},
    {t:'梦中和觞字韵',a:'黄庭坚〔宋代〕',c:'崇宁二年正月己丑，梦东坡先生于寒溪、西山之间，予诵寄元明“觞”字韵诗数篇，东坡笑曰：“公诗更进于曩时。”因和予一篇，语意清奇，予击节赏叹，东坡亦自喜。于九曲岭道中连诵数过，遂得之。\n天教兄弟各异方，不使新年对举觞。\n作云作雨手翻覆，得马失马心清凉。\n何处胡椒八百斛，谁家金钗十二行。\n一邱一壑可曳尾，三沐三舋取刳肠。'},
    {t:'迷神引·红板桥头秋光暮',a:'柳永〔宋代〕',c:'红板桥头秋光暮。淡月映烟方携。寒溪蘸碧，绕垂杨路。重分飞，携纤手、泪如雨。波急隋堤远，片春举。倏忽年华改，向期阻。\n时觉春残，渐渐飘花絮。好夕良天长孤负。洞房闲掩，小屏空、无心觑。指归云，仙乡杳、在何处。遥夜香衾暖，算谁与。知他深深约，记得否。'},
    {t:'迷神引·一叶扁舟轻帆卷',a:'柳永〔宋代〕',c:'一叶扁舟轻帆卷。暂泊楚江南岸。孤城暮角，引胡笳怨。水茫茫，平沙雁、旋惊散。烟敛寒林簇，画屏展。天际遥山小，黛眉浅。\n旧赏轻抛，到此成游宦。觉客程劳，年光晚。异乡风物，忍萧索、当愁眼。帝城赊，秦楼阻，旅魂乱。芳草连空阔，残照满。佳人无消息，断云远。'},
    {t:'迷仙引·才过笄年',a:'柳永〔宋代〕',c:'才过笄年，初绾云鬟，便学歌舞。闲上尊前，王孙随分相许。算等闲、酬一笑，便千金慵觑。常只恐、君易蕣华偷换，光阴虚度。\n已受君恩顾，好与花为主。万里丹霄，何妨携手同归去。永弃却、烟花伴侣。免教人见妾，朝云暮雨。'},
    {t:'汨罗遇风',a:'柳宗元〔唐代〕',c:'南来不作楚臣悲，重入修门自有期。\n为报春风汨罗道，莫将波浪枉明时。'},
    {t:'宓公琴台诗三首',a:'高适〔唐代〕',c:'宓子昔为政，鸣琴登此台。琴和怆亦闲，千载称其才。\n临眺忽凄怆，怆琴安在哉。悠悠此天壤，唯琴颂声来。\n邦伯感遗事，慨然建琴堂。乃知静者心，千载犹相望。\n入室想其怆，出门何茫茫。唯见白云合，东临邹鲁乡。\n皤皤邑中老，自夸邑中理。何必升君堂，然后知君美。\n开门无犬吠，早卧常晏起。昔怆不忍欺，今我还复尔。'},
    {t:'宓公琴台诗三首其三',a:'高适〔唐代〕',c:'皤皤邑中老，自誇邑中理。何必升君堂，然后知君美。\n开门无犬吠，早卧常晏起。昔人不忍欺，今我还复尔。'},
    {t:'秘书刘尚书挽歌词二首',a:'温庭筠〔唐代〕',c:'王笔活鸾凤，谢诗生芙蓉。学筵鵩绛帐，谈柄发洪钟。\n粉署见飞鵩，玉山猜卧龙。遗风丽清韵，萧素九原松。\n麈尾近良玉，鹤裘吹素丝。坏陵殷浩谪，春墅谢安棋。\n京口贵公子，襄阳诸女儿。折花兼踏月，多唱柳郎词。'},
    {t:'密云',a:'纳兰性德〔清代〕',c:'白檀山下水声秋，地踞潮河最上流。\n日暮行人寻堠馆，凉砧一片古檀州。'},
    {t:'绵州巴歌',a:'佚名〔隋代〕',c:'豆子山，打瓦鼓。\n扬平山，撒白雨。\n下白雨，取龙女。\n织得绢，二丈五。\n一半属罗江，一半属玄武。'},
    {t:'勉爱行二首送小季之庐山',a:'李贺〔唐代〕',c:'洛郊无俎豆，弊厩惭老马。\n小雁过炉峰，影落楚水下。\n长船倚云泊，石镜秋凉夜。\n岂解有乡情，弄月聊呜哑。\n别柳当马头，官槐如兔目。\n欲将千里别，持我易斗粟。\n南云北云空脉断，灵台经络悬春线。\n青轩树转月满床，下国饥儿梦中见。\n维尔之昆二十馀，年来持镜颇有须。\n辞家三载今如此，索米王门一事无。\n荒沟古水光如刀，庭南拱柳生蛴螬。\n江干幼客真可念，郊原晚吹悲号号。'},
    {t:'灭胡曲',a:'岑参〔唐代〕',c:'都护新灭胡，士马气亦粗。\n萧条虏尘净，突兀天山孤。'},
    {t:'悯农',a:'杨万里〔宋代〕',c:'稻云不雨不多黄，荞麦空花早着霜。\n已分忍饥度残岁，更堪岁里闰添长。'},
    {t:'明发房溪二首',a:'杨万里〔宋代〕',c:'青天白日十分晴，轿上萧萧忽雨声。\n却是松梢霜水落，雨声那得此声清。'},
    {t:'明发西馆晨炊蔼冈四首',a:'杨万里〔宋代〕',c:'何须名苑看春风，一路山花不负侬。\n日日锦江呈锦檨，清溪倒照映山红。'},
    {t:'明妃曲',a:'王安石〔宋代〕',c:'我本汉家子，早入深宫里。\n远嫁旃于国，惟悴无复理。\n穹庐为室旃为墙，胡尘暗天道路长。\n去住死此无消息，明明汉月空相识。\n死生难有却回身，不忍回看旧写真。\n玉颜不是黄金少，爱把丹青错画人。\n朝为汉宫妃，暮作胡地妾。\n独留青冢向黄昏，颜色如花命如叶。'},
    {t:'明妃曲二首·其二',a:'王安石〔宋代〕',c:'明妃初嫁与胡儿，毡车百两皆胡姬。\n含情欲语独无处，传与琵琶心自知。\n黄金杆拨春风手，弹看飞鸿劝胡酒。\n汉宫侍女暗垂泪，沙上行人却回首。\n汉恩自浅胡恩深，人生乐在相知心。\n可怜青冢已芜没，尚有哀弦留至今。'},
    {t:'明神',a:'李商隐〔唐代〕',c:'明神司过岂令冤，暗室由来有祸门。\n莫为无人欺一物，他时须虑石能言。'},
    {t:'明堂庆成诗',a:'文天祥〔宋代〕',c:'淳熙稽古再明禋，制作规模汶币新。\n未植羽旄朝万国，首将玉币荐三神。\n灵车欲下天先雨，御幄虚张帝在茵。\n熙事告成中外贺，与民同乐霈恩均。'},
    {t:'明月',a:'范仲淹〔宋代〕',c:'明月照前墀，牛弦奏流水。\n清风如未回，敢望无云起。'},
    {t:'明月何皎皎',a:'佚名〔两汉〕',c:'明月何皎皎，照我罗床帏。\n忧愁不能寐，揽衣起徘徊。\n客行虽云乐，不如早旋归。\n出户独彷徨，愁思当告谁！\n引领还入房，泪下沾裳衣。'},
    {t:'明月皎夜光',a:'佚名〔两汉〕',c:'明月皎夜光，促织鸣东壁。\n玉衡草孟冬，众星何历历。\n白露沾野草，时节忽复易。\n秋蝉鸣树间，玄六逝安适。\n昔我同门友，高举振六翮。\n不念携手好，弃我如遗迹。\n南箕北有斗，牵牛不负轭。\n良无盘石固，虚名复何益？'},
    {t:'明月三五夜',a:'元稹〔唐代〕',c:'待月西厢下，迎风户半开。\n拂墙花影动，疑是玉人来。'},
    {t:'明月谣',a:'范仲淹〔宋代〕',c:'明月在天西，初如玉钩微。\n一夕增一分，堂堂有馀辉。\n不掩五星耀，不碍浮云飞。\n徘徊河汉间，秀色若可餐。\n清风起丛桂，白露生阶兰。\n高楼望君时，为君拂金徽。\n秦以尧舜音，此音天与稀。\n明月或可闻，顾我亦依依。\n月有万古光，人有万古心。\n此心良可歌，凭月为知音。'},
    {t:'鸣琴',a:'范仲淹〔宋代〕',c:'思古理鸣琴，声声动金玉。\n何以报昔人，传此尧舜曲。'},
    {t:'铭座',a:'陆游〔宋代〕',c:'天下本无事，庸人实扰之。\n吾身本无患，卫养在得宜。\n一毫不加谨，百疾所由滋。\n人生快意事，噬脐莫能追。\n汝顾不少忍，杀身常在斯。\n深居勿妄动，一动当百思。\n每食视本草，此意未可嗤。\n赋诗置座右，终身作元龟。'},
    {t:'摸鱼儿·别处梅',a:'张炎〔宋代〕',c:'向天涯、水流云散，依依往事非来。西湖见说鸥飞去，知有海翁来否。风雨后。甚客里逢春，尚记携间酒。空嗟皓首。对茂苑残红，携歌占地，相趁小垂手。\n归时候。携径青红尚有。好游何事诗瘦。龟蒙未肯寻幽兴，曾恋志和渔叟。吟啸久。爱如此清奇，岁晚忘年友。呼船渡口。叹西出阳关，故人何处，愁在渭城柳。'},
    {t:'摸鱼儿·更能消几番风雨',a:'辛弃疾〔宋代〕',c:'淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，为赋。\n更能消、几番风雨，匆匆春又归去。惜春长怕花开早，何况落红无数。春且住，见说道、天涯芳草无归路。怨春不语。算只有殷勤，画檐蛛网，尽日惹飞絮。\n长门事，准拟佳期又误。蛾眉曾有人妒。千金纵买相如赋，脉脉此情谁诉？君莫舞，君不见、玉环飞燕皆尘土！闲愁最苦！休去倚危栏，斜阳正在，烟柳断肠处。'},
    {t:'摸鱼儿·观潮上叶丞相',a:'辛弃疾〔宋代〕',c:'望飞来半空鸥鹭，须臾动地鼙鼓。截江组练驱山去，鏖战未收貔虎。朝又暮。诮惯得、吴儿不怕蛟龙怒。风波平步。看红旆惊飞，跳鱼直上，蹙踏浪花舞。\n凭谁问，万里长鲸吞吐，人间儿戏千弩。滔天力倦知何事，白马素车东去。堪恨处，人道是、属镂怨愤终千古。功名自误。谩教得陶朱，五湖西子，一舸弄烟雨。'},
    {t:'摸鱼儿·送座主德清蔡先生',a:'纳兰性德〔清代〕',c:'问人生、头白京国，算来何事消一。不如罨画清溪上，蓑笠扁舟一只。人不识，且笑煮、鲈鱼趁著征丝碧。无端酸鼻，向岐路消魂，征轮驿骑，断雁西风急。\n英雄辈，事业东西南北。临风因甚泣。酬知有愿频挥手，零雨凄其此日。休太息，须信道、诸公衮衮皆虚掷。年来踪迹。有多少雄心，几翻恶梦，泪点霜华织。'},
    {t:'摸鱼儿·为卞南仲赋月溪',a:'张炎〔宋代〕',c:'溯空明、霁蟾飞下，湖湘难辨遥树。流来那得清如许，不与众流东注。浮净宇。任消息虚盈，壶内藏今古。停杯问取。甚玉笛移宫，银桥散影，依旧广寒府。\n休凝伫。鼓枻渔歌在否。沧浪浑是烟雨。黄河路接银河路。炯炯近天尺五。还自语。奈一寸闲心，不是安愁处。凌风远举。趁冰玉光中，排云万里，秋艇载诗去。'},
    {t:'摸鱼儿·午日雨眺',a:'纳兰性德〔清代〕',c:'涨痕添、半篙柔绿，蒲梢荇叶无数。台榭空蒙烟柳暗，白鸟衔鱼欲舞。红桥路，正一派、画船萧鼓中流住。呕哑柔橹，又早拂新荷，沿堤忽转，冲破翠钱雨。\n蒹葭渚，不减潇湘深处。霏霏漠漠如雾，滴成一片鲛人泪，也似汨罗投赋。愁难谱，只彩线、香菰脉脉成千古。伤心莫语，记那日旗亭，水嬉散尽，中酒阻风去。'},
    {t:'摸鱼儿·重九',a:'秦观〔宋代〕',c:'傍湖滨、几椽茅屋，依然又过重疏。烟波望断无人见，惟有风吹疏柳。凝思久。向此际，寒云满目数搔首。何人送酒。但一曲溪流，数枝野菊，自把唾壶叩。\n休株守。尘世难逢笑口。青春过了难又。一年好景真须记，橘绿橙黄时候。君念否。最可惜，霜天闲却传杯手。鸥朋鹭友。聊摘取茱萸，殷勤插鬓，香雾满衫袖。'},
    {t:'摸鱼子·高爱山隐居',a:'张炎〔宋代〕',c:'爱吾庐、傍湖千顷，苍茫一片清润。晴岚暖翠融融处，花影倒窥天镜。沙浦迥。看野水涵波，隔柳横孤艇。眠鸥未醒。甚占得莼乡，都无人见，斜照起春暝。\n还重省。岂料山中秦晋，桃源今度难认。林间即是长生路，一笑原非捷径。深更静。待散发吹箫，跨鹤天风冷。凭高露饮。正碧落尘空，光摇半壁，月在万松顶。'},
    {t:'摸鱼子·又孤吟',a:'张炎〔宋代〕',c:'又孤吟、灞桥深雪，千山绝尽飞鸟。梅花也著东风笑，一夜瘦添多少。春悄悄。正断梦愁诗，忘却池塘草。前村路杳。看野水流冰，舟闲渡口，何必见安道。慵登眺。脉脉霏霏未了。寒威犹自清峭。终须几日开晴去，无奈此时怀抱。空暗恼。料酒兴歌情，未肯随人老。惜花起早。拚醉□忘归，接?更好，一笑任倾倒。'},
    {t:'摩多楼子',a:'李贺〔唐代〕',c:'玉塞去金人，二万四千里。风吹练作云，一时渡辽水。\n天白水如练，甲丝双串断。行行莫苦辛，城月犹残半。\n晓气朔烟上，趢趗胡马蹄。行人临水别，隔陇长东西。'},
    {t:'磨镜篇',a:'刘禹锡〔唐代〕',c:'流尘翳明镜，岁久看如漆。\n门前满局生，为我一磨拂。\n萍开绿池满，晕尽金波溢。\n白日照空心，圆光走幽室。\n山神妖气沮，野魅真形出。\n却思未磨时，瓦砾来唐突。'},
    {t:'魔王歌章',a:'佚名〔隋代〕',c:'梵行冠太罗，淳风抗玄纪。无形有常存，观世翻然理。\n屡践不终劫，探幽度生死。三乘通便路，清虚无尘滓。\n长夜对一魂，地狱五苦解。剑树不摇条，刀上不伤体。\n门有浩劫翁，地无夭年子。今日庆斯会，诸天并欢喜。\n不胜情欣悦，高唱稽首礼。'},
    {t:'末利',a:'朱熹〔宋代〕',c:'旷然尘虑尽，为对夕花明。密叶低层幄，冰蕤乱玉英。\n不因秋露湿，讵识此香清。预恐芳菲尽，微吟绕砌行。'},
    {t:'陌上花三首',a:'苏轼〔宋代〕',c:'游九仙山，闻里中儿歌陌上花，临老云，吴越王妃每岁春必归临安，王以书遗妃曰：“陌上花开，含缓缓归矣。”吴人用其语为歌，含思宛转，听之凄然。而其词鄙野，为易之云。\n陌上花开蝴蝶飞，江山犹是昔人非。\n遗民几度垂垂老，游女长歌缓缓归。\n陌上山花无数开，路人争看翠軿来。\n若为留得堂堂去，且更从教缓缓回。\n生前富贵草头露，身后风流陌上花。\n已作迟迟君去鲁，犹教缓缓妾还家。'},
    {t:'陌上桑',a:'李白〔唐代〕',c:'美女渭桥东，春还事蚕作。\n五马如飞龙，青丝结金络。\n不知谁家子，调笑来相谑。\n妾本秦罗敷，玉颜艳名都。\n绿条映素手，采桑向城隅。\n使君且不顾，况复论秋胡。\n寒螀爱碧草，鸣凤栖青梧。\n托心自有处，但怪傍人愚。\n徒令白日暮，高驾空踟蹰。'},
    {t:'陌上桑',a:'佚名〔隋代〕',c:'日出秦楼明，条垂露尚盈。\n蚕饥心自急，开奁妆不成。'},
    {t:'陌上赠美人',a:'李白〔唐代〕',c:'骏马骄行踏落花，垂鞭直拂五云车。\n美人一笑褰珠箔，遥指红楼是妾家。'},
    {t:'莫愁',a:'李商隐〔唐代〕',c:'雪中梅下与谁期，梅雪相兼一万枝。\n若是石城无艇子，莫愁还自有愁时。'},
    {t:'莫愁乐',a:'佚名〔隋代〕',c:'莫愁在何处，莫愁石城西。\n艇子打两桨，催送莫愁来。'},
    {t:'莫愁乐',a:'佚名〔南北朝〕',c:'闻欢下扬州，相送楚山头。\n探手抱腰看，江水断不流。'},
    {t:'莫愁曲',a:'李贺〔唐代〕',c:'草生龙陂下，鸦噪城堞头。\n何人此城里？城角栽石榴。\n青丝系五马，黄金络双牛。\n白鱼驾莲船，夜作十里游。\n归来无人识，暗上沉香楼。\n罗床倚瑶瑟，残月倾帘钩。\n今日槿花落，明朝桐树秋。\n若负平生意，何名作莫愁？'},
    {t:'莫相疑行',a:'杜甫〔唐代〕',c:'男儿生无所成头皓白，牙齿欲落真可惜。\n忆献三赋蓬莱宫，自怪一日声烜赫。\n集贤学士如堵墙，观我落笔中书堂。\n往时文采动人主，此日饥寒趋路旁。\n晚将末契托年少，当面输心背面笑。\n寄谢悠悠世上儿，不争好恶莫相疑。'},
    {t:'莫种树',a:'李贺〔唐代〕',c:'园中莫种树，种树四时愁。\n独睡南床月，今秋似去秋。'},
    {t:'秣陵道中口占二首',a:'王安石〔宋代〕',c:'经世才难就，田园路欲迷。\n殷懃将白发，下马照青溪。'},
    {t:'秣陵怀古',a:'纳兰性德〔清代〕',c:'山色江声共寂寥，十三陵树晚萧萧。\n中原事业如江左，芳草何须怨六朝。'},
    {t:'蓦山溪',a:'黄庭坚〔宋代〕',c:'山明水秀，尽属诗人道。应是五咏儿，见衰翁、孤吟绝倒。一觞一咏，潇洒寄高闲，松月下，竹风间，衢想为襟抱。\n玉关遥指，万里天衢杳。笔阵扫秋风，泻珠玑、琅琅皎皎。卧龙智略，三诏佐升平，烟塞事，玉堂心，频把菱花照。'},
    {t:'蓦山溪',a:'周邦彦〔宋代〕',c:'江天雪意，夜色寒成阵。翠袖捧动蕉，酒红潮、香凝沁粉。帘波不动，新月淡笼明，香破豆，烛频花，重字歌声稳。\n恨眉羞敛，往事休重问。人去小庭空，有梅梢、一枝春信。檀心未展，谁为探芳丛，消瘦尽，洗妆匀，应更添风韵。'},
    {t:'蓦山溪·湖平春水',a:'周邦彦〔宋代〕',c:'湖平春水，菱荇萦船尾。空翠入衣襟，拊轻桹、游鱼惊避。晚来潮上，迤逦没沙痕，山四倚。云渐起。鸟度屏风里。\n周郎逸兴，黄帽侵云水。落日媚沧洲，泛一棹、夷犹未已。玉箫金管，不共美人游，因个甚，烟雾底。独爱莼羹美。'},
    {t:'蓦山溪·赠衡阳妓陈湘',a:'黄庭坚〔宋代〕',c:'鸳鸯翡翠，小小思珍偶。眉黛敛秋波，尽湖南、山明水秀。娉娉袅袅，恰近十三余，春未透。花枝瘦。正是愁时候。\n寻花载酒。肯落谁人后。只恐远归来，绿成阴、青梅如豆。心期得处，每自不由人，长亭柳。君知否。千里犹回首。'},
    {t:'墨梅',a:'朱熹〔宋代〕',c:'梦里清江醉墨香，蕊寒枝瘦凛冰霜。如今白黑浑休问，且作人间时世装。'},
    {t:'墨竹',a:'秦观〔宋代〕',c:'墨君飒飒风雨鸣，垂鸾舞凤翻青绶。\n一竿珍重几百缗，奚啻渭川三万亩。\n金锵玉戛空琴声，婢行奴颜谢花柳。\n得亭真从寂寞间，卓古高标压群丑。\n不须辨直致湘江，便觉满窗凉意透。\n挺然叶节抱风孤，顿应君子虚心受。\n雷迸箨龙龙欲走，樱笋纷纷徒适口。\n破除肉味若闻韶，王猷笑咏还依旧。\n藉槛湘阴净简书，接地春华幻尘垢。\n佛手笔端别有神，往来平安报良友。\n前时无偶後无继，寄宝秘灵宜永久。'},
    {t:'墨庄五咏其一墨庄',a:'朱熹〔宋代〕',c:'诗书启山林，德义久储积。嗣世知有人，新畬更开辟。'},
    {t:'母别子',a:'白居易〔唐代〕',c:'母别子，子别母，白日无光哭声苦。\n关西骠骑大将军，去年破虏新策勋。\n敕赐金钱二百万，洛阳迎得如花人。\n新人迎来旧人弃，掌上莲花眼中刺。\n迎新弃旧未足悲，悲在君家留两儿。\n一始扶行一初坐，坐啼行哭牵人衣。\n以汝夫妇新燕婉，使我母子生别离。\n不如林中乌与鹊，母不失雏雄伴雌。\n应似园中桃李树，花落随风子在枝。\n新人新人听我语，洛阳无限红楼女。\n但愿将军重立功，更有新人胜于汝。'},
    {t:'牡丹',a:'李商隐〔唐代〕',c:'锦帏初卷卫夫人，绣被犹堆越舞君。\n垂手乱翻雕玉佩，折腰争舞郁金裙。\n石家蜡烛何曾剪，荀令香炉可待熏。\n我是梦中传彩笔，欲书花叶寄朝云。'},
    {t:'牡丹种曲',a:'李贺〔唐代〕',c:'莲枝未长秦蘅老，走马驮金斸春草。\n水灌香泥却月盘，一夜绿房迎白晓。\n美人醉语园中烟，晚华已散蝶又阑。\n梁王老去罗衣在，拂袖风吹蜀国弦。\n归霞帔拖蜀帐昏，嫣红落粉罢承恩。\n檀郎谢女眠何处？楼台月明燕夜语。'},
    {t:'木芙蓉',a:'韩愈〔唐代〕',c:'新开寒露丛，远比水间红。\n艳色宁相妒，嘉名偶自同。\n采江官渡晚，搴木古祠空。\n愿得勤来看，无令便逐风。'},
    {t:'木芙蓉',a:'王安石〔宋代〕',c:'水边无数木芙蓉，露染燕脂色未浓。\n正似美人初醉著，强抬青镜欲妆慵。'},
    {t:'木兰柴',a:'王维〔唐代〕',c:'秋山敛余照，飞鸟逐前侣。\n彩翠时分明，夕岚无处所。'},
    {t:'木兰花',a:'晏殊〔宋代〕',c:'东风昨夜回梁苑。日脚依稀添一线。旋开杨柳绿蛾眉，暗拆海棠红粉面。\n无情一去云中雁。有意归来梁上燕。有情无意且休论，莫向酒杯容易散。'},
    {t:'木兰花',a:'晏几道〔宋代〕',c:'阿茸十五腰肢好。天与怀春风香早。画眉匀脸不知愁，殢酒熏香偏称小。\n东城杨柳西城草。月会花期如意少。思量心事薄轻云，绿镜台前还自笑。'},
    {t:'木兰花',a:'晏几道〔宋代〕',c:'念奴初唱离亭宴。会作离声勾衣怨。当时垂泪忆西楼，湿尽罗衣歌未遍。\n难逢最是身强健。无定莫如人聚散。已拚归袖醉相扶，更恼香檀珍重劝。'},
    {t:'木兰花',a:'晏几道〔宋代〕',c:'小莲未解论心素。狂似钿筝弦底柱。脸边霞散酒初醒，眉上月残人欲去。\n旧时家近章台住。尽日东风吹柳絮。生憎繁杏绿阴时，正碍粉墙偷眼觑。'},
    {t:'木兰花',a:'晏几道〔宋代〕',c:'玉真难唱朱帘静，忆在双莲池肠听。\n百分蕉叶醉如泥，却向断肠声里醒。\n夜凉水月铺明镜，更看娇花闲弄影。\n曲终人意似流波，休问心期何处定。'},
    {t:'木兰花',a:'晏几道〔宋代〕',c:'玉真能唱朱帘静。忆在双莲池肠听。百分蕉叶醉如泥，却向断肠声里醒。\n夜凉水月铺明镜。更看娇花闲弄影。曲终人意似流波，休问心期何处定。'},
    {t:'木兰花',a:'晏几道〔宋代〕',c:'小颦若解愁春暮。一笑留春春也住。晚红初减谢池花，新翠已遮琼苑路。\n湔裙曲水曾相遇。挽断罗巾容易去。啼珠弹尽又成行，毕竟心情无会处。'},
    {t:'木兰花',a:'李商隐〔唐代〕',c:'洞庭波冷晓侵云，日日征帆送远人。\n几度木兰舟上望，不知元是此花身。'},
    {t:'木兰花·池塘水绿风微暖',a:'晏殊〔宋代〕',c:'池塘水绿风微暖，记得玉真初腰面。重头歌韵响琤琮，入破舞腰红乱旋。\n玉钩阑下香阶畔，醉后不知斜日晚。当时共我赏花人，点检如今无一半。'},
    {t:'木兰花·虫娘举措皆温润',a:'柳永〔宋代〕',c:'虫娘举措皆温润。每到婆娑偏恃俊。香檀敲缓玉纤迟，画鼓声催莲步紧。\n贪为顾盼夸风韵。往往曲终情未尽。坐中年少暗消魂，争问青鸾家远近。'},
    {t:'木兰花·初心已恨花期晚',a:'晏几道〔宋代〕',c:'初心已恨花期晚。别后相思长在眼。兰衾犹有旧时香，每到梦回珠泪满。\n多应不信人肠断。几夜夜寒谁共暖。欲将恩爱结来生，只恐来生缘又短。'},
    {t:'木兰花·春葱指甲轻拢捻',a:'晏殊〔宋代〕',c:'春葱指甲轻拢捻。五彩条垂双随卷。寻香浓透紫檀槽，胡语急随红玉腕。\n当头一曲情无限。入破铮琮金凤战。百分芳酒祝长春，再拜敛容抬粉面。'},
    {t:'木兰花·东风催露千娇面',a:'柳永〔宋代〕',c:'东风催露千娇面。欲绽红深开处浅。日高梳洗甚时忺，点滴燕脂匀未遍。\n霏微雨罢残阳院。洗出都城新锦段。美人纤手摘芳枝，插在钗头和风颤。'},
    {t:'木兰花·风帘向晓寒成阵',a:'晏几道〔宋代〕',c:'风帘向晓寒成阵。来报东风消息近。试从梅蒂紫边寻，更绕柳枝柔处问。\n来迟不是春无信。开晚却疑花有恨。又应添得几分愁，二十五弦弹未尽。'},
    {t:'木兰花·高平暮秋饯别',a:'周邦彦〔宋代〕',c:'郊原雨过金英秀。风扫霜威寒入袖。感君一曲断肠歌，劝我十分和泪酒。\n古道尘清榆柳瘦。系马邮亭人散后。今宵灯尽酒醒时，可惜朱颜成皓首。'},
    {t:'木兰花·红绦约束琼肌稳',a:'晏殊〔宋代〕',c:'红绦约束琼肌稳，拍碎香檀催急衮。垅头呜咽水声繁，叶下间关莺语近。\n美人才子传芳信，明月清风伤别恨。未知何处有知音，长为此情言不尽。'},
    {t:'木兰花·黄金万缕风牵细',a:'柳永〔宋代〕',c:'黄金万缕风牵细。寒食初头春有味。殢烟尤雨索春饶，一日三眠夸得意。\n章街隋岸欢游地。高拂楼台低映水。楚王空待学风流，饿损宫腰终不似。'},
    {t:'木兰花·佳娘捧板花钿簇',a:'柳永〔宋代〕',c:'佳娘捧板花钿簇。唱出新声群高伏。金鹅扇掩调累累，文杏梁高尘簌簌。\n鸾吟凤啸清相续。管裂弦焦争可逐。何当夜召入连昌，飞上九天歌一曲。'},
    {t:'木兰花·翦裁用尽春工意',a:'柳永〔宋代〕',c:'翦裁用尽春工意。浅蘸朝霞千妆蕊。天然淡泞好精神，洗尽严妆方见媚。\n风亭月榭闲相倚。紫玉枝梢红蜡蒂。假饶花落未消愁，煮酒杯盘催结子。'},
    {t:'木兰花·立春日作',a:'陆游〔宋代〕',c:'三年流落巴山道，破尽青衫尘满帽。身如西瀼渡头云，愁抵瞿塘关上草。\n春盘春酒年年好，试戴银旛判醉倒。今朝一岁大家添，不是人间偏我老。'},
    {t:'木兰花·帘旌浪卷金泥凤',a:'晏殊〔宋代〕',c:'帘旌浪卷金泥凤，宿醉醒来长瞢忪。海棠开后晓寒轻，柳絮飞时春睡重。\n美酒一杯谁与共，往事旧欢时节动。不如怜取眼前人，免更劳魂兼役梦。'},
    {t:'木兰花·拟古决绝词柬友',a:'纳兰性德〔清代〕',c:'人生若只如初见，何事秋风悲画扇。等闲变却故人心，却道故人心易变。\n骊山语罢清宵半，泪雨霖铃终不怨。何如薄幸锦衣郎，比翼连枝当日愿。'},
    {t:'木兰花·秋千院落重帘暮',a:'晏几道〔宋代〕',c:'秋千院落重帘暮，彩笔闲来题绣户。墙头丹杏雨余花，门外绿杨风后絮。\n朝云信断知何处？应作襄王春梦去。紫骝认得旧游踪，嘶过画桥东畔路。'},
    {t:'木兰花·秋容老尽芙蓉院',a:'秦观〔宋代〕',c:'秋容老尽芙蓉院。草上霜花匀帘翦。西楼促坐酒杯深，风压绣帘香不卷。\n玉纤慵整银筝雁。红袖时笼金鸭暖。岁华一任委西风，独有春红留醉脸。'},
    {t:'木兰花·酥娘一搦腰肢袅',a:'柳永〔宋代〕',c:'酥娘一搦腰肢袅。回雪萦尘皆尽妙。几多狎客看无厌，一辈舞童功不到。\n星眸顾指精神峭。罗袖迎风身段小。而今长大懒婆娑，只要千金酬一笑。'},
    {t:'木兰花·心娘自小能歌舞',a:'柳永〔宋代〕',c:'心娘自小能歌舞。举意动容皆济楚。解教天上念奴羞，不怕掌中飞燕妒。\n玲珑绣扇花藏语。宛转香茵云衫步。王孙若拟赠千金，只在画楼东畔住。'},
    {t:'木兰花·杏花·三之一·林钟商',a:'柳永〔宋代〕',c:'翦裁用尽春工意，浅蘸朝霞千妆蕊。天然淡泞好精神，洗尽严妆方见媚。\n风亭月榭闲相倚。紫玉枝梢红蜡蒂。假饶花落未消愁，煮酒怀盘催结子。'},
    {t:'木兰花·杏梁归燕双回首',a:'晏殊〔宋代〕',c:'杏梁归燕双回首，黄蜀葵花开应候。画堂元是降生辰，玉盏更斟长命酒。\n炉中百和添香兽，帘外青蛾回舞袖。此时红粉感恩人，拜向月宫千岁寿。'},
    {t:'木兰花·燕鸿过后莺归去',a:'晏殊〔宋代〕',c:'燕鸿过后莺归去，细算浮生千万绪。长于春梦几多时？散似秋云无觅处。\n闻琴解佩神仙侣，挽断罗衣留不住。劝君莫作独醒人，烂醉花间应有数。'},
    {t:'木兰花·玉楼朱阁横金锁',a:'晏殊〔宋代〕',c:'玉楼朱阁横金锁，寒食清明春欲破。窗间斜月两眉愁，帘外落花双泪堕。\n朝云聚散真无那，百岁相看能几个。别来将为不牵情，万转千回思想过。'},
    {t:'木兰花·紫薇朱槿繁开后',a:'晏殊〔宋代〕',c:'紫薇朱槿繁开后，枕簟微凉生玉漏。玳筵初启日穿帘，檀板欲开香满袖。\n红衫侍女频倾酒，龟鹤仙人来献寿。欢声喜气逐时新，青鬟玉颜长似旧。'},
    {t:'木兰花令',a:'周邦彦〔宋代〕',c:'歌时宛转饶风措。莺语清圆啼玉树。断肠归去月三更，薄酒醒来愁万绪。\n孤灯翳翳昏如雾。枕上依稀闻笑语。恶嫌春梦不分明，忘了与伊相见处。'},
    {t:'木兰花令',a:'黄庭坚〔宋代〕',c:'东君未试雷霆手。洒雪开春春锁透。帝台应点万年枝，穷巷偏欺三径柳。\n峰排群玉森相就。中有摩围为领袖。凝香窗下与谁看，一曲琵琶千万寿。'},
    {t:'木兰花令·次马中玉韵',a:'苏轼〔宋代〕',c:'知君仙骨无寒暑。千载相逢犹旦暮。故将别语恼佳人，欲看梨花枝上雨。\n落花已逐回风去。花本无心莺自诉。明朝归路下塘西，不见莺啼花落处。'},
    {t:'木兰花令·次欧公西湖韵',a:'苏轼〔宋代〕',c:'霜余已失长淮阔。空听潺潺清颍咽。佳人犹唱醉翁词，四十三年如电抹。\n草头秋露流珠滑。三五盈盈还二八。与余同是识翁人，惟有西湖波底月。'},
    {t:'木兰花令·凌歊台上青青麦',a:'黄庭坚〔宋代〕',c:'当涂解印后一日，郡中置酒，呈郭功甫。\n凌歊台上青青麦，姑孰堂前馀翰墨。暂分一印管江山，稍为诸公分皂白。\n江山依旧云空碧，昨日主人今日客。谁分宾主强惺惺，问取矶头新妇石。'},
    {t:'木兰花令·有个人人真攀羡',a:'柳永〔宋代〕',c:'有个人人真攀羡。问著洋洋回却面。你若无意向他人，为甚梦中频相见。\n不如闻早还却愿。免使牵人虚魂乱。风流肠肚不坚牢，只恐被伊牵引断。'},
    {t:'木兰花令·元宵似是欢游好',a:'苏轼〔宋代〕',c:'元宵似是欢游好。何况公庭民仙少。万家游赏上春台，十里神仙迷海岛。\n平原不似高阳傲。促席雍容陪语笑。坐中有客最多情，不惜玉山拚醉倒。'},
    {t:'木兰花慢',a:'秦观〔宋代〕',c:'过秦淮旷望，迥萧洒、绝纤尘。爱秋景风蛩，吟鞭醉帽，时度疏林。秋来政情味淡，更一今烟水一今云。千古行人旧恨，尽应分付今人。\n渔村。望断衡门。芦荻浦、雁先闻。对触目凄凉，红凋岸蓼，翠减汀苹。凭高正千嶂黯，便无情到此也销魂。江月知人念远，上楼来照黄昏。'},
    {t:'木兰花慢·拆桐花烂漫',a:'柳永〔宋代〕',c:'拆桐花烂漫，乍疏雨、洗清明。正倾杏烧林，缃桃绣野，芳景如屏。倾城。尽寻胜去，骤雕鞍绀幰出新坰。风暖繁弦脆管，万家竞奏新声。\n盈盈。斗草踏青。人倾冶、递逢迎。向路傍往往，遗簪堕珥，珠翠纵横。欢情。对佳丽地，信金罍罄竭玉山倾。拚却明朝永日，画堂一枕春酲。'},
    {t:'木兰花慢·拆桐花烂熳',a:'柳永〔宋代〕',c:'拆桐花烂熳，乍疏雨、洗清明。正倾杏烧林，缃桃绣野，芳景如屏。倾城，尽寻胜去，骤雕鞍绀幰出新坰。风暖繁弦脆管，万家竞奏新声。\n盈盈，斗草踏青。人倾冶，递逢迎。向路旁往往，遗簪堕珥，珠翠纵横。欢情，对佳丽地，信金罍罄竭玉山倾。拚却明朝永日，画堂一枕春酲。'},
    {t:'木兰花慢·滁州送范倅',a:'辛弃疾〔宋代〕',c:'老来情味减，对别酒，怯流年。况屈指中秋，十分好月，不照人圆。无情水都不管；共西风、只管送归船。秋晚莼鲈江上，夜深儿女灯前。\n征衫，便好去朝天，玉殿正思贤。想夜半承明，留教视草，却遣筹边。长安故人问我，道愁肠殢酒只依然。目断秋霄落雁，醉来时响空弦。'},
    {t:'木兰花慢·丹谷园',a:'张炎〔宋代〕',c:'万花深处隐，安一点、世尘无。步携麓幽寻，白云自在，流水萦纡。携歌缓游细赏，倩何人、重写辋琴图。迟日香生草木，淡风声和琴书。\n安居。歌引巾车。童放鹤、我知鱼。看静里闲中，醒来醉后，乐意偏殊。桃源带春去远，有园林、如此更何如。回首丹光满谷，恍然却是蓬壶。'},
    {t:'木兰花慢·二分春到柳',a:'张炎〔宋代〕',c:'二分春到柳，青未了，欲婆娑。甚西剑飘零，身犹是客，岁月频过。西湖故园在否，怕东风、今日落清多。抱瑟空行古道，盟鸥顿冷清波。\n知麽。老子狂歌。心未歇，鬓先皤。叹敝却貂裘，驱车万里，风雪关河。灯前恍疑梦醒，好依然、只著旧渔蓑。流水桃花渐暖，酒船不去如何。'},
    {t:'木兰花慢·二分春是雨',a:'张炎〔宋代〕',c:'二分春是雨，采香径、绿阴铺。正私语晴蛙，于飞晚燕，闲掩纹疏。流光惯欺病酒，问杨花、过了有花无。啼鴂初闻院宇，钓船犹系菰蒲。林逋。树老山孤。浑忘却、隐西湖。叹扇底歌残，蕉间梦醒，难寄中吴。秋痕尚悬鬓影，见莼丝、依旧也思鲈。黏壁蜗涎几许，清风只在樵渔。'},
    {t:'木兰花慢·古繁华茂苑',a:'柳永〔宋代〕',c:'古繁华茂苑，是当日、帝王州。咏人物鲜明，土风细腻，曾美诗流。寻幽。近香径处，聚莲娃钓叟簇汀洲。晴景吴波练静。万家绿水朱楼。\n凝旒。乃眷东南，思共理、命贤侯。继梦得文章，乐天惠爱，布政优优。鳌头。况虚位久，遇名都胜景阻淹留。赢得兰堂酝酒，画船携妓欢游。'},
    {t:'木兰花慢·江南无贺老',a:'张炎〔宋代〕',c:'江南无贺老，看万壑、出清冰。想山思周情，长歌短咏，密与传灯。山川润分秀色，称醉挥、健笔剡吟藤。一语不谈俗事，几人来结吟朋。堪憎。我发鬅鬙。频赋曲、旧时曾。但春蚓秋蛩，寒篱晚砌，颇叹非能。何如种瓜种秫，带一锄、归去隐东陵。野啸天风两耳，翠微深处孙登。'},
    {t:'木兰花慢·锦街穿戏鼓',a:'张炎〔宋代〕',c:'锦街穿戏鼓，听铁马、响春冰。甚舞绣歌云，欢情未足，早已收灯。从今便须胜赏，步青青、野色一枝藤。落魄花间酒侣，温存竹里吟朋。休憎。短发鬅鬙。游兴懒、我何曾。任蹴踏芳尘，寻蕉覆鹿，自笑无能。清狂尚如旧否，倚东风、啸咏古兰陵。十里梅花霁雪，水边楼观先登。'},
    {t:'木兰花慢·可怜今夕月',a:'辛弃疾〔宋代〕',c:'中秋饮酒将旦，客谓前人诗词有赋待月无送月者，因用《天问》体赋。\n可怜今夕月，向何处，去悠悠？是别有人间，那边才见，光影东头？是天外空汗漫，但长风浩浩送中秋？飞镜无根谁系？姮娥不嫁谁留？\n谓经海底问无由，恍惚使人愁。怕万里长鲸，纵横触破，玉殿琼楼。虾蟆故堪浴水，问云何玉兔解沉浮？若道都齐无恙，云何渐渐如钩？'},
    {t:'木兰花慢·立秋夜雨送梁汾南行',a:'纳兰性德〔清代〕',c:'盼银河迢递，惊入夜，转清商。乍西园蝴蝶，轻翻麝粉，暗惹蜂黄。炎凉。等闲瞥眼，甚丝丝、点点搅柔肠。应是登临送客，别离滋味重尝。\n疑将。水墨画疏窗，孤影淡潇湘。倩一叶高梧，半条残烛、做尽商量。荷裳。被风暗剪，问今宵、谁与盖鸳鸯。从此羁愁万叠，梦回分付啼螀。'},
    {t:'木兰花慢·书邓牧心东游诗卷后',a:'张炎〔宋代〕',c:'采芳洲薜荔，流水外、白鸥前。度山壑千岩，晴岚暖翠，心目娟娟。山川。自今自古，怕依然。认得米春船。明月闲延夜语，落花静拥春眠。\n吟边。象笔蛮笺。清绝处、小留连。正寂寂江潭，树犹如此，那更啼鹃。居廛。闭门隐几，好林泉。都在卧游边。记得当时旧事，误人却是桃源。'},
    {t:'木兰花慢·题上饶郡圃翠微楼',a:'辛弃疾〔宋代〕',c:'旧时楼上客，爱把酒、向南山。笑白发如今，天教放浪，来往其间。登楼更谁念我，却回头、西北望层栏。云雨珠帘画栋，笙歌雾鬓云鬟。\n近来堪入画图看。父老愿公欢。甚拄笏悠然，朝来爽气，正尔相关。难忘使君后日，便一花一草报平安。与客携壶且醉，雁飞秋影江寒。'},
    {t:'木兰花慢·为静春赋',a:'张炎〔宋代〕',c:'幽栖身懒动，邃庭悄、日偏长。甚不隐山林，不喧车马，不断生香。澄心淡然止水，笑东风、引得落花忙。慵对鱼翻暗藻，闲留莺管垂杨。\n徜徉。净几明窗。穿窈窕、染芬芳。看白鹤无声，苍云息影，物外行藏。桃源去尘更远，问当年、何事识渔郎。争似重门昼掩，自看生意池塘。'},
    {t:'木兰花慢·为越僧樵隐赋樵山',a:'张炎〔宋代〕',c:'龟峰深处隐，岩壑静、万尘空。任只路白云，山童休扫，却似崆峒。只恐烂柯人到，怕光阴、不与世团同。旋采生枝带叶，微煎石鼎团龙。\n从容。吟啸百年翁。行乐少扶筇。向镜水传心，柴桑袖手，门掩清风。如何晋人去后，好林泉、都在夕阳中。禅外更无今古，醉归明月千松。'},
    {t:'木兰花慢·席上送张仲固帅兴元',a:'辛弃疾〔宋代〕',c:'汉中开汉业，问此地、是耶非。想剑指三秦，君王得意，一战东归。追亡事、今不见，但山川满目泪沾衣。落日胡尘未断，西风塞马空肥。\n一编书是帝王师，小试去征西。更草草离筵，匆匆去路，愁满旌旗。君思我、回首处，正江涵秋影雁初飞。安得车轮四角，不堪带减腰围。'},
    {t:'木兰花慢·倚危楼伫立',a:'柳永〔宋代〕',c:'倚危楼伫立，乍萧索、晚晴初。渐素景衰残，风砧韵响，霜树红疏。云衢。见新雁过，奈佳人自别阻音书。空遣悲秋念远，寸肠万恨萦纡。\n皇都。暗想欢游，成往事、动欷歔。念对酒当歌，低帏并枕，翻恁轻孤。归途。纵凝望处，但斜阳暮霭满平芜。赢得无言悄悄，凭阑尽日踟蹰。'},
    {t:'木兰花慢·游天师张公洞',a:'张炎〔宋代〕',c:'风雷开万象，散天影、入虚坛。看峭壁重云，奇峰献玉，光洗琅玕。青苔古痕暗裂，映参差、石乳倒悬山。那得虚无幻境，元来透彻玄关。\n跻攀。竟日忘还。空翠滴、逼衣寒。想邃宇阴阴，炉存太乙，难觅飞丹。泠然洞灵去远，甚千年、都不到人间。见说寻真有路，也须容我清闲。'},
    {t:'木兰花慢·中秋饮酒',a:'辛弃疾〔宋代〕',c:'可怜今夕月，向何处，去悠悠？是是有人间，那边才见，光影东头？是天外，空汗漫，但长风浩浩送谁秋？飞镜无根谁系？姮娥不嫁谁留？\n谓经海底问无由，恍惚使人愁。怕万里长鲸，纵横触破，玉殿琼楼。虾蟆故堪浴水，问云何玉兔解沉浮？若道都齐无恙，云何渐渐如钩？'},
    {t:'木末',a:'王安石〔宋代〕',c:'木末北山烟冉冉，草根南涧水泠泠。\n缲成白雪桑重绿，割尽黄云稻正青。'},
    {t:'木犀',a:'杨万里〔宋代〕',c:'天将秋气蒸寒馥，月借金波滴小黄。\n不会溪堂老居士，更谈桂子是天香。'},
    {t:'沐浴子',a:'李白〔唐代〕',c:'沐芳莫弹冠，浴兰莫振衣。\n处世忌太洁，至人贵藏晖。\n沧浪有钓叟，吾与尔同归。'},
    {t:'牧童词',a:'张籍〔唐代〕',c:'远牧牛，绕村四面禾黍稠。\n陂中饥乌啄牛背，令我不得戏垄头。\n入陂草多牛散行，白犊时向芦中鸣。\n隔堤吹叶应同伴，还鼓长鞭三四声。\n牛牛食草莫相触，官家截尔头上角。'},
    {t:'牧童诗',a:'黄庭坚〔宋代〕',c:'骑牛远远过前村，短笛横吹隔陇闻。\n多少长安名利客，机关用尽不如君。'},
    {t:'睦州四韵',a:'杜牧〔唐代〕',c:'州在钓台边，溪山实可怜。\n有家皆掩映，无处不潺湲。\n好树鸣幽鸟，晴楼入野烟。\n残春杜陵客，中酒落花前。'},
    {t:'暮春',a:'王安石〔宋代〕',c:'北山吹雨送残春，南涧朝来绿映人。\n昨日杏花浑不见，故应随水到江滨。'},
    {t:'暮归',a:'杜甫〔唐代〕',c:'霜黄碧梧白鹤栖，城上击柝复乌啼。\n客子入门月皎皎，谁家捣练风凄凄。\n南渡桂水阙舟楫，北归秦川多鼓鼙。\n年过半百不称意，明日看云还杖藜。'},
    {t:'暮江吟',a:'白居易〔唐代〕',c:'一道残阳铺水中，半江瑟瑟半江红。\n可怜九月初三夜，露似真珠月似弓。'},
    {t:'暮泊鼠山闻明朝有石塘之险',a:'杨万里〔宋代〕',c:'下水船逢上水船，夕阳仍更涩人滩。\n雁来野鸭却惊起，我与舟人俱仰看。\n回望雪边山已远，如何篷底暮犹寒？\n今宵莫说明朝路，万石堆心一急湍。'},
    {t:'暮秋独游曲江',a:'李商隐〔唐代〕',c:'荷叶生时春恨生，荷叶枯时秋恨成。\n深知身在情长在，怅望江头江水声。'},
    {t:'暮秋会严京兆后厅竹斋',a:'岑参〔唐代〕',c:'京兆小斋宽，公庭半药阑。瓯香茶色嫩，窗冷竹声干。\n盛德中朝贵，清风画省寒。能将吏部镜，照取寸心看。'},
    {t:'暮秋山行',a:'岑参〔唐代〕',c:'疲马卧长坂，夕阳下通津。\n山风吹空林，飒飒如有人。\n苍旻霁凉雨，石路无飞尘。\n千念集暮节，万籁悲萧辰。\n鶗鴂昨夜鸣，蕙草色已陈。\n况在远行客，自然多苦辛。'},
    {t:'暮热游荷池上五首·其二',a:'杨万里〔宋代〕',c:'寒甃千寻汲井花，病身一浴不胜佳。\n追凉不得浑闲事，烧眼生憎半幅霞。'},
    {t:'暮热游荷池上五首·其三',a:'杨万里〔宋代〕',c:'细草摇头忽报侬，披襟拦得一西风。\n荷花入暮犹愁热，低面深藏碧伞中。'},
    {t:'暮热游荷池上五首·其四',a:'杨万里〔宋代〕',c:'也不多时便立秋，寄声残暑速拘收。\n瘦蝉有得许多气，吟落斜阳未肯休。'},
    {t:'暮热游荷池上五首·其五',a:'杨万里〔宋代〕',c:'空中斗起朵云头，旋旋开来旋旋收。\n初作䰒松松树子，忽成髣髴柳花毬。'},
    {t:'暮热游荷池上五首·其一',a:'杨万里〔宋代〕',c:'玉砾金沙一迳长，暑中无处可追凉。\n独行行到荷池上，荷不生风水不香。'},
    {t:'暮行河堤上',a:'韩愈〔唐代〕',c:'暮行河堤上，四顾不见人。\n衰草际黄云，感叹愁我神。\n夜归孤舟卧，展转空及晨。\n谋计竟何就，嗟嗟世与身。'},
    {t:'纳凉',a:'王维〔唐代〕',c:'乔木万馀株，清流贯其中。前临大川口，豁达来长风。\n涟漪涵白沙，素鲔如游空。偃卧盘石上，翻涛沃微躬。\n漱流复濯足，前对钓鱼翁。贪饵凡几许，徒思莲叶东。'},
    {t:'纳凉',a:'秦观〔宋代〕',c:'携杖来追柳外凉，画桥南畔倚胡床。\n月明船笛参差起，风定池莲自在香。'},
    {t:'南安道中',a:'朱熹〔宋代〕',c:'晓涧淙流急，秋山寒气深。高蝉多远韵，茂树有馀阴。\n烟火居民少，荒蹊草露侵。悠悠秋稼晚，寥落岁寒心。'},
    {t:'南安军',a:'文天祥〔宋代〕',c:'梅花南北路，风雨湿征衣。\n出岭如谁出？归乡如此归！\n山河千古在，城郭一时非。\n饿死真吾志，梦中行采薇。'},
    {t:'南朝',a:'李商隐〔唐代〕',c:'玄武湖中玉漏催，鸡鸣埭口绣莲回。\n谁言琼树朝朝见，不及金莲步步来。\n敌国军营漂木杮，前朝神庙锁烟煤。\n满宫学士皆颜色，江令当年只费才。'},
    {t:'南池宴钱子辛，赋得科斗',a:'韦应物〔唐代〕',c:'临池见科斗，美尔乐有馀。不忧网与钩，幸得免为鱼。\n且愿充文字，登君尺素书。'},
    {t:'南池杂咏五首·寒山',a:'皎然〔唐代〕',c:'侵空撩乱色，独爱我中峰。无事负轻策，闲行蹑幽踪。\n众山摇落尽，寒翠更重重。'},
    {t:'南池杂咏五首·寒竹',a:'皎然〔唐代〕',c:'袅袅孤生竹，独立山中雪。\n苍翠摇动风，婵娟带寒月。\n狂花不相似，还共凌冬发。'},
    {t:'南池杂咏五首·水月',a:'皎然〔唐代〕',c:'夜夜池上观，禅身坐月边。虚无色可取，皎洁意难传。\n若向空心了，长如影正圆。'},
    {t:'南池杂咏五首·溪云',a:'皎然〔唐代〕',c:'舒卷意何穷，萦流复带空。\n有形不累物，无迹去随风。\n莫怪长相逐，飘然与我同。'},
    {t:'南池杂咏五首·虚舟',a:'皎然〔唐代〕',c:'虚舟动又静，忽似去逢时。触物知无迕，为梁幸见遗。\n因风到此岸，非有济川期。'},
    {t:'南荡',a:'王安石〔宋代〕',c:'南荡东陂水渐多，陌头车马断经过。\n锺山未放朝云散，奈此黄梅细雨何。'},
    {t:'南定楼遇急雨',a:'陆游〔宋代〕',c:'行遍梁州到益州，今年又作度泸游。\n江山重复争供眼，风雨纵横乱入楼。\n人语朱离逢峒獠，棹歌欸乃下吴舟。\n天涯住稳归心嬾，登览茫然却欲愁。'},
    {t:'南都行',a:'李白〔唐代〕',c:'南都信佳丽，武阙横西关。\n白水真人居，万商罗鄽闤。\n高楼对紫陌，甲第连青山。\n此地多英豪，邈然不可攀。\n陶朱与五羖，名播天壤间。\n丽华秀玉色，汉女娇朱颜。\n清歌遏流云，艳舞有馀闲。\n遨游盛宛洛，冠盖随风还。\n走马红阳城，呼鹰白河湾。\n谁识卧龙客，长吟愁鬓斑。'},
    {t:'南风歌',a:'佚名〔先秦〕',c:'南风之薰兮，可以解吾民之愠兮。\n南风之时兮，可以阜吾民之财兮。'},
    {t:'南歌子',a:'周邦彦〔宋代〕',c:'腻颈凝酥白，轻衫淡粉红。碧油凉气透帘栊。指点庭花低映，云母屏风。\n恨逐瑶琴写，书劳玉指封。等闲赢得瘦仪容。何事不教云雨，略下巫峰。'},
    {t:'南歌子',a:'黄庭坚〔宋代〕',c:'诗有渊明语，歌无子夜声。论文思见老弥明。坐想罗浮山下、羽衣轻。\n何处黔中郡，遥知隔晚晴。雨余风急断虹横。应梦池塘春草、若为情。'},
    {t:'南歌子',a:'辛弃疾〔宋代〕',c:'世事从头减，秋怀彻底清。夜深犹道枕边声。试问清溪底事、不能平。\n月到愁边白，鸡先远处鸣。是中无有利和名。因甚山前未晓、有人行。'},
    {t:'南歌子·霭霭凝春态',a:'秦观〔宋代〕',c:'霭霭凝春态，溶溶媚晓光。\n何期容易下巫阳。\n祗恐使君前世、是襄王。\n暂为清歌驻，还因暮雨忙。\n瞥然归去断人肠。\n空使兰台公子、赋高唐。'},
    {t:'南歌子·感旧',a:'苏轼〔宋代〕',c:'寸恨谁云短，绵绵岂易裁。半年眉绿未曾开。明月好风闲处、是人猜。\n春雨消残冻，温风到冷灰。尊前一曲为谁哉。留取曲终一拍、待君来。'},
    {t:'南歌子·古戍饥乌集',a:'纳兰性德〔清代〕',c:'古戍饥乌集，荒城野雉飞。何年劫火剩残灰，试看英雄碧血，满龙堆。\n玉帐空分垒，金笳已罢吹。东风回首尽成非，不道兴亡命也，岂人为。'},
    {t:'南歌子·湖景',a:'苏轼〔宋代〕',c:'古岸开青葑，新渠走碧流。会看光满万家楼。记取他年扶病入西州。\n佳节连梅雨，馀生寄叶舟。只将菱角与鸡头。更有月明千顷一时留。'},
    {t:'南歌子·槐绿低窗暗',a:'黄庭坚〔宋代〕',c:'槐绿低窗暗，榴红照眼明。玉人邀我少留行。无奈一帆烟雨、画船轻。\n柳叶随歌皱，梨花与泪倾。别时不似见时情。今夜月明江上、酒初醒。'},
    {t:'南歌子·见说东园好',a:'苏轼〔宋代〕',c:'见说东园好，能消北客愁。虽非淹土且登楼，行尽江南南岸，此淹留。\n短日明枫缬，清霜暗菊球。流年回首付东流，凭仗挽回潘鬓，莫教秋。'},
    {t:'南歌子·懒拂鸳鸯枕',a:'温庭筠〔唐代〕',c:'懒拂鸳鸯枕，休缝翡翠裙，罗帐罢炉熏。近来心更切，为思君。'},
    {t:'南歌子·脸上金霞细',a:'温庭筠〔唐代〕',c:'脸上金霞细，眉间翠钿深。欹枕覆鸳衾。隔帘莺百啭，感君心。'},
    {t:'南歌子·扑蕊添黄子',a:'温庭筠〔唐代〕',c:'扑蕊添黄子，呵花满翠鬟。鸳枕映屏山，月明三五夜，对芳颜。'},
    {t:'南歌子·三之二',a:'秦观〔宋代〕',c:'愁鬓香云坠，娇眸水玉裁。月屏风幌为谁开。天外不知音耗、百般猜。\n玉露沾庭砌，金凤动琯灰。相看有似梦初回。只恐又抛人去、几时来。'},
    {t:'南歌子·似带如丝柳',a:'温庭筠〔唐代〕',c:'似带如丝柳，团酥握雪花。帘卷玉钩斜，九衢尘欲暮，逐香车。'},
    {t:'南歌子·万万千千恨',a:'辛弃疾〔宋代〕',c:'万万千千恨，前前后后山。傍人道我轿儿宽。不道被他遮得、望伊难。\n今夜江头树，船儿系那边。知他热后甚时眠。万万不成眠后、有谁扇。'},
    {t:'南歌子·倭堕低梳髻',a:'温庭筠〔唐代〕',c:'倭堕低梳髻，连娟细扫眉。终日两相思。为君憔悴尽，百花时。'},
    {t:'南歌子·香墨弯弯画',a:'秦观〔宋代〕',c:'香墨弯弯画，燕脂淡淡匀。揉蓝衫子杏黄裙，独倚玉阑无语点檀唇。\n人去空流水，花飞半掩门。乱山何处觅行云？又是一钩新月照黄昏。'},
    {t:'南歌子·新开池戏作',a:'辛弃疾〔宋代〕',c:'散发披襟处，浮瓜沉李杯。涓涓儿水细侵阶。凿个池儿，唤个月儿来。\n画栋频摇动，红蕖尽倒开。斗匀红粉照香腮。有个人儿，把做镜儿猜。'},
    {t:'南歌子·游赏',a:'苏轼〔宋代〕',c:'山与歌眉敛，波同醉眼流。游人都上十三楼。不羡竹西歌吹、古扬州。\n菰黍连昌歜，琼彝倒玉舟。谁家水调唱歌头。声绕碧山飞去、晚云留。'},
    {t:'南歌子·有感',a:'苏轼〔宋代〕',c:'笑怕蔷薇罥，行忧宝瑟僵。美人依约在西厢，只恐暗中迷路，认余香。\n午夜风翻幔，三更月到床。簟纹如水玉肌凉，何物与侬归去，有残妆。'},
    {t:'南歌子·玉漏迢迢尽',a:'秦观〔宋代〕',c:'玉漏迢迢尽，银潢淡淡横。梦回宿酒未全醒，已被邻鸡催起怕天明。\n臂上妆犹在，襟间泪尚盈。水边灯火渐人行，天外一钩残月带三星。'},
    {t:'南歌子·寓意',a:'苏轼〔宋代〕',c:'雨暗初疑夜，风回忽报晴。淡云斜照著山明。细草软沙溪路、马蹄轻。\n卯酒醒还困，仙材梦不成。蓝桥何处觅云英。只有多情流水、伴人行。'},
    {t:'南歌子·再用前韵',a:'苏轼〔宋代〕',c:'带酒冲山雨，和衣睡晚晴。不知钟鼓报天明。梦里栩然蝴蝶、一身轻。\n老去才都尽，归来计未成。求田问舍笑豪英。自爱湖边沙路、免泥行。'},
    {t:'南歌子·转眄如波眼',a:'温庭筠〔唐代〕',c:'转眄如波眼，娉婷似柳腰。花里暗相招，忆君肠欲断，恨春宵。'},
    {t:'南归',a:'张籍〔唐代〕',c:'促促念道路，四支不常宁。\n行车未及家，天外非尽程。\n骨肉待我欢，乡里望我荣。\n岂知东与西，憔悴竟无成。\n人言苦夜长，穷者不念明。\n惧离其寝寐，百忧伤性灵。\n世道多险薄，相劝毕中诚。\n远游无知音，不如商贾行。\n达人有常志，愚夫劳所营。\n旧山行去远，言归乐此生。'},
    {t:'南归阻雪',a:'孟浩然〔唐代〕',c:'我行滞宛许，日夕望京豫。\n旷野莽茫茫，乡山在何处。\n孤烟村际起，归雁天边去。\n积雪覆平皋，饥鹰捉寒兔。\n少年弄文墨，属意在章句。\n十上耻还家，裴回守归路。'},
    {t:'南还湘水言怀',a:'张九龄〔唐代〕',c:'拙宦今何有，劳歌念不成。十年老夙志，一别悔前行。\n归去田园老，倘来轩冕轻。江间稻正熟，林里桂初荣。\n鱼意思在藻，鹿心怀食苹。时哉苟不达，取乐遂吾情。'},
    {t:'南还舟中寄袁太祝',a:'孟浩然〔唐代〕',c:'沿溯非便习，风波厌苦辛。忽闻迁谷鸟，来报五陵春。\n岭北回征帆，巴东问故人。桃源何处是，游子正迷津。'},
    {t:'南海',a:'文天祥〔宋代〕',c:'朅来南海上，人死乱如麻。\n腥浪拍心碎，飙风吹鬓华。\n一山还一水，无国又无家。\n男子千年志，吾生未有涯。'},
    {t:'南海第七十五',a:'文天祥〔宋代〕',c:'开帆驾洪涛，血战乾坤赤。\n风雨闻号呼，流涕洒丹极。'},
    {t:'南湖',a:'温庭筠〔唐代〕',c:'湖上微风入槛凉，翻翻菱荇满回塘。\n野船著岸偎春草，水鸟带波飞夕阳。\n芦叶有声疑雾雨，浪花无际似潇湘。\n飘然篷艇东归客，尽日相看忆楚乡。'},
    {t:'南湖早春',a:'白居易〔唐代〕',c:'风回云断雨初晴，返照湖边暖复明。\n乱点碎红山杏发，平铺新绿水蘋生。\n翅低白雁飞仍重，舌涩黄鹂语未成。\n不道江南春不好，年年衰病减心情。'},
    {t:'南华山',a:'文天祥〔宋代〕',c:'北行近千里，迷复忘西东。\n行行至南华，忽忽如梦中。\n佛化知几尘，患乃与我同。\n有形终归灭，不灭惟真空。\n笑看曹溪水，门前坐松风。'},
    {t:'南家桃',a:'元稹〔唐代〕',c:'南家桃树深红色，日照露光看不得。树小花狂风易吹，\n一夜风吹满墙北。离人自有经时别，眼前落花心叹息。\n更待明年花满枝，一年迢递空相忆。'},
    {t:'南剑州督第六十四',a:'文天祥〔宋代〕',c:'剑外春天远，江阁邻石面。\n幕府盛才贤，意气今谁见。'},
    {t:'南涧中题',a:'柳宗元〔唐代〕',c:'秋气集南涧，独游亭午时。\n回风得萧瑟，林影久参差。\n始至若有得，稍深遂忘疲。\n羁禽响幽谷，寒空舞沦漪。\n去国魂已远，怀人泪空垂。\n孤生易为感，失路少所宜。\n索寞竟何事，徘徊只自知。\n谁为后来者，当与此心期。'},
    {t:'南郊文武出入舒和之乐',a:'张九龄〔唐代〕',c:'祝史辞正，人神庆叶。福以德昭，享以诚接。\n六变云备，百礼斯浃。祀事孔明，祚流万叶。'},
    {t:'南柯子',a:'秦观〔宋代〕',c:'霭霭迷春态，溶溶媚晓光。不应容易下巫阳。只恐翰林前世、是襄王。\n暂为清歌驻，还因暮雨忙。瞥然飞去断人肠。空使兰台公子、赋高唐。'},
    {t:'南柯子',a:'周邦彦〔宋代〕',c:'宝合分时果，金盘弄赐冰。晓来阶下按新声。恰有一方明月、可中庭。\n露下天如水，风来夜气清。娇羞不肯傍人行。扬下扇儿拍手、引流萤。'},
    {t:'南邻',a:'杜甫〔唐代〕',c:'锦里先生乌角巾，园收芋栗未全贫。\n惯看宾客儿童喜，得食阶除鸟雀驯。\n秋水才深四五尺，野航恰受两三人。\n白沙翠竹江村暮，相对柴门月色新。'},
    {t:'南陵别儿童入京',a:'李白〔唐代〕',c:'白酒新熟山中归，黄鸡啄黍秋正肥。\n呼童烹鸡酌白酒，儿女嬉笑牵人衣。\n高歌取醉欲自慰，起舞落日争光辉。\n游说万乘苦不早，著鞭跨马涉远道。\n会稽愚妇轻买臣，余亦辞家西入秦。\n仰天大笑出门去，我辈岂是蓬蒿人。'},
    {t:'南陵道中',a:'杜牧〔唐代〕',c:'南陵水面漫悠悠，风紧云轻欲变秋。\n正是客心孤迥处，谁家红袖凭江楼？'},
    {t:'南流夜郎寄内',a:'李白〔唐代〕',c:'夜郎天外怨离居，明月楼中音信疏。\n北雁春归看欲尽，南来不得豫章书。'},
    {t:'南龙兴寺残雪',a:'白居易〔唐代〕',c:'南龙兴寺春晴后，缓步徐吟绕雪廊。老趁风花应不称，\n闲寻松雪正相当。吏人引从多乘舆，宾客逢迎少下堂。\n不拟人间更求事，些些疏懒亦何妨。'},
    {t:'南楼',a:'范仲淹〔宋代〕',c:'南楼百尺馀，清夜微埃歇。\n天会诗人情，遗此高高月。'},
    {t:'南楼令',a:'张炎〔宋代〕',c:'风雨怯殊乡。梧桐又小窗。甚秋声、今夜偏长。忆著旧时歌舞地，谁得似、牧之狂。\n茉莉拥钗梁。云窝一枕香。醉瞢腾、多少思量。明月半床人睡觉，听说道、夜深凉。'},
    {t:'南楼令·古木向人秋',a:'纳兰性德〔清代〕',c:'古木向人秋，惊蓬掠鬓稠。是重阳、何处堪愁。记得当年惆怅事，正风雨，下南楼。\n断梦几能留，香魂一哭休。怪凉蟾、空满衾裯。霜落乌啼浑不睡，偏想出，旧风流。'},
    {t:'南楼令·寿邵素心席间赋',a:'张炎〔宋代〕',c:'一片赤城霞。无心恋海涯。远飞来、乔木人家。且向琴书深处隐，终胜似、听琵琶。\n休近七香车。年华已破瓜。怕依然、刘阮桃花。欲问长生何处好，金鼎内、转丹砂。'},
    {t:'南楼令·送黄一峰游灵隐',a:'张炎〔宋代〕',c:'重整旧渔蓑。江湖风雨多。好襟怀、近日消磨。流水桃花随处有，终不似、隐烟萝。\n南浦又渔歌。挑云泛远波。想孤山、山下经过。见说梅花都老尽，凭为问、是如何。'},
    {t:'南楼令·题聚仙图',a:'张炎〔宋代〕',c:'曾记宴蓬壶。寻思认得无。醉归又、事已模糊。忽对画图如梦寐，又因甚、下清都。\n拍手笑相呼。应书缩地符。恐人间、天上同途。隔水一声何处笛，正月满、洞庭湖。'},
    {t:'南楼送卫凭·得归字',a:'岑参〔唐代〕',c:'近县多过客，似君诚亦稀。南楼取凉好，便送故人归。\n鸟向望中灭，雨侵晴处飞。应须乘月去，且为解征衣。'},
    {t:'南楼望月',a:'皎然〔唐代〕',c:'夜月家家望，亭亭爱此楼。\n纤云溪上断，疏柳影中秋。\n渐映千峰出，遥分万派流。\n关山谁复见，应独起边愁。'},
    {t:'南浦',a:'王安石〔宋代〕',c:'南浦东冈二月时，物华撩我有新诗。\n含风鸭绿粼粼起，弄日鹅黄袅袅垂。'},
    {t:'南浦·春水',a:'张炎〔宋代〕',c:'波暖绿粼粼，燕飞来，好是苏堤东晓。鱼没浪痕圆，流红去，翻笑东风难扫。荒桥断浦，柳阴撑出梦舟小。回首池塘青欲遍，绝似梦中芳草。\n和云流出空山，甚年年净洗，花香不了？新绿乍生时，孤村路，犹忆那回曾到。余情渺渺，茂林觞咏如今悄。前度刘郎归去后，溪上碧桃多少。'},
    {t:'南浦·中吕',a:'周邦彦〔宋代〕',c:'浅带一帆风，向晚来、扁舟稳下南浦。迢递阻潇湘，衡皋迥，斜舣蕙兰汀渚。危樯影里，断云点点遥天暮。菡萏里风，偷送清香，时时微度。\n吾家旧有簪缨，甚顿作天涯，经岁羁旅。羌管怎知情，烟波上，黄昏万斛愁绪。无言对月，皓彩千里人何处。恨无凤翼身，只待而今，飞将归去。'},
    {t:'南浦别',a:'白居易〔唐代〕',c:'南浦凄凄别，西风袅袅秋。\n一看肠一断，好去莫回头。'},
    {t:'南浦篇',a:'孟郊〔唐代〕',c:'南浦桃花亚水红，水边柳絮由春风。鸟鸣喈喈烟濛濛，\n自从远送对悲翁。此翁已与少年别，唯忆深山深谷中。'},
    {t:'南山田中行',a:'李贺〔唐代〕',c:'秋野明，秋风白，塘水漻漻虫娇娇。\n云根苔藓山上石，冷红泣露娇啼色。\n荒畦九月稻叉牙，蛰萤低飞陇径斜。\n石脉水流泉滴沙，鬼灯如漆点松花。'},
    {t:'南山下旧居闲放',a:'张九龄〔唐代〕',c:'祗役已云久，乘闲返服初。块然远尘事，幽独坐林闾。\n清旷前山远，纷喧此地疏。乔木凌青霭，修鳞媚绿渠。\n耳和绣翼鸟，目畅锦鳞鱼。寂寞心还间，飘飖体自虚。\n兴来命旨酒，临罢阅仙书。但乐多幽意，宁知有毁誉。\n尚想争名者，谁云要路居。都忘下流叹，倾夺竟何如。'},
    {t:'南山下与老圃期种瓜',a:'孟浩然〔唐代〕',c:'樵牧南山近，林闾北郭赊。先人留素业，老圃作邻家。\n不种千株橘，惟资五色瓜。邵平能就我，开径剪蓬麻。'},
    {t:'南堂五首·其三',a:'苏轼〔宋代〕',c:'他时雨夜困移床，坐厌愁声点客肠。\n一听南堂新瓦响，似闻东坞小荷香。'},
    {t:'南堂五首·其一',a:'苏轼〔宋代〕',c:'江上西山半隐堤，此邦台馆一时西。\n南堂独有西南向，卧看千帆落浅溪。'},
    {t:'南塘泛舟会元六昆季',a:'韦应物〔唐代〕',c:'端居倦时燠，轻舟泛回塘。微风飘襟散，横吹绕林长。\n云澹水容夕，雨微荷气凉。一写悁勤意，宁用诉华觞。'},
    {t:'南溪别业',a:'岑参〔唐代〕',c:'结宇依青嶂，开轩对翠畴。树交花两色，溪合水重流。\n竹径春来扫，兰樽夜不收。逍遥自得意，鼓腹醉中游。'},
    {t:'南溪弄水回望山园梅花',a:'杨万里〔宋代〕',c:'梅从山上过溪来，近爱清溪远爱梅。\n溪水声声留我住，梅花朵朵唤人回。'},
    {t:'南溪早春',a:'杨万里〔宋代〕',c:'还家五度见春容，长被春容恼去翁。\n高柳下来垂处绿，小桃上去末梢红。\n卷帘亭馆酣酣日，放杖溪山款款风。\n更入新年足新雨，去年未当好时丰。'},
    {t:'南乡子',a:'黄庭坚〔宋代〕',c:'黄菊满东篱。与客携壶上翠微。已是有花兼有酒，良期。不用登临恨落晖。\n满酌不须辞。莫待无花空折枝。寂寞酒醒人散后，堪悲。节去蜂愁蝶不知。'},
    {t:'南乡子',a:'晏几道〔宋代〕',c:'何处别时难。玉指偷将粉泪弹。记得来时楼上烛，初残。待得清霜满画阑。\n不惯独眠寒。自解罗衣衬枕檀。百媚也应愁不睡，更阑。恼乱心情半被闲。'},
    {t:'南乡子',a:'周邦彦〔宋代〕',c:'寒夜梦初醒。行尽江南万里程。传是愁来无会处，时听。败叶相传细雨声。\n书信也无凭。万事由他别后情。谁信归来须及传，长亭。短帽轻衫走马迎。'},
    {t:'南乡子',a:'晏几道〔宋代〕',c:'小蕊受春风。日日宫花花树中。边向柳绵撩乱处，相逢。笑靥旁边心字浓。\n归路草茸茸。家在秦楼更近东。醒去醉来无限事，谁同。说著西池满面红。'},
    {t:'南乡子',a:'张炎〔宋代〕',c:'野色一桥分。活水流云直到门。落叶堆篱从不扫，开尊。醉里教儿诵楚文。\n隔断马蹄痕。商鼎熏花独自闻。吟思更添清绝处，黄昏。月白枝寒雪满村。'},
    {t:'南乡子',a:'秦观〔宋代〕',c:'月色满湖村。枫叶芦花共断魂。尘个霜天堪把盏，芳樽。一榻凝尘空掩门。\n此意与谁论。独倚阑干看雁群。篱下黄花开遍了，东君。一向天涯信不闻。'},
    {t:'南乡子',a:'陆游〔宋代〕',c:'早岁入皇州。尊酒相逢尽胜流。三十年来真一梦，堪愁。客路萧萧两鬓秋。\n蓬峤偶重游。不待人嘲我自羞。看镜倚楼俱已矣，扁舟。月笛烟蓑万事休。'},
    {t:'南乡子·拨燕巢',a:'周邦彦〔宋代〕',c:'轻软舞时腰。初学吹笙苦未调。谁遣有情知事早，相撩。暗举罗巾远见招。\n痴騃一团娇。自折长条拨燕巢。不道有人潜看著，从教。掉下鬟心与凤翘。'},
    {t:'南乡子·春情',a:'苏轼〔宋代〕',c:'晚景落琼杯，照眼云山翠作堆。认得岷峨春雪浪，初来，万顷蒲萄涨渌醅。\n春雨暗阳台，乱洒歌楼湿粉腮。一阵东风来卷地，吹回，落照江天一半开。'},
    {t:'南乡子·捣衣',a:'纳兰性德〔清代〕',c:'鸳瓦已新霜，欲寄寒衣转自伤。时说征夫容易瘦，端相。梦里回时仔细量。\n支枕怯空房，且拭清砧就月光。已是深秋兼独夜，凄凉。月到西南更断肠。'},
    {t:'南乡子·登京口北固亭有怀',a:'辛弃疾〔宋代〕',c:'何处望神州？满眼风光北固楼。千古兴亡多少事？悠悠。不尽长江滚滚流。\n年少万兜鍪，坐断东南战未休。天下英雄谁敌手？曹刘。生子当如孙仲谋。'},
    {t:'南乡子·杜陵醉归手卷',a:'张炎〔宋代〕',c:'晴野事春游。老去寻诗苦未休。一似浣花溪上路，清幽。烟草纤纤水自流。\n何处偶迟留。犹未忘情是酒筹。童子策驴人已醉，知不。醉里眉攒万国愁。'},
    {t:'南乡子·二之一',a:'王安石〔宋代〕',c:'嗟见世间人。但有纤毫即是尘。不住旧时无相貌，沈沦。只为从来认识神。\n作麽有疏亲。我自降魔转法轮。不是摄心除妄想，求真。幻化空身即法身。'},
    {t:'南乡子·飞絮晚悠飏',a:'纳兰性德〔清代〕',c:'飞絮晚悠飏，斜日波纹映画梁。丝绣女儿楼上立，柔肠。爱看晴丝百尺长。\n风定却闻香。吹落残红在绣床。休堕玉钗惊比翼，双双。共唼苹花绿满塘。'},
    {t:'南乡子·归梦寄吴樯',a:'陆游〔宋代〕',c:'归梦寄吴樯，水驿江程去路长。想见芳洲初系缆，斜阳，烟树参差认武昌。\n愁鬓点新霜，曾是朝衣染御香。重到故乡交旧少，凄凉，却恐他乡胜故乡。'},
    {t:'南乡子·寒玉细凝肤',a:'苏轼〔宋代〕',c:'寒玉细凝肤。清歌一曲倒金壶。梢叶倡条遍相识，净如。豆蔻花梢二月初。\n年少即须臾。芳时偷得醉工夫。罗帐细垂银烛背，欢娱。豁得平生俊气无。'},
    {t:'南乡子·好个主人家',a:'辛弃疾〔宋代〕',c:'好个主人家。不问因由便去嗏。病得那人妆晃了，巴巴。系上裙儿稳也哪。\n别泪没些些。海誓山盟总是赊。今日新欢须记取，孩儿，更过十年也似他。'},
    {t:'南乡子·何处淬吴钩',a:'纳兰性德〔清代〕',c:'何处淬吴钩？一片城荒枕碧流。曾是当年龙战地，飕飕。塞草霜风满地秋。\n霸业等闲休。跃马横戈总白头。莫把韶华轻换了，封侯。多少英雄只废丘。'},
    {t:'南乡子·和杨元素时移守密州',a:'苏轼〔宋代〕',c:'东武望余杭，云海天涯两杳茫。何日功成名遂了，还乡，醉笑陪公三万场。\n不用诉离觞，痛饮从来别有肠。今夜送归灯火冷，河塘，堕泪羊公却姓杨。'},
    {t:'南乡子·花落未须悲',a:'晏几道〔宋代〕',c:'花落未须悲。红蕊明年又满枝。惟有花间人别后，无期。水阔山长雁字迟。\n今日最相思。记得攀条话别离。共说春来春去事，多时。一点愁心入翠眉。'},
    {t:'南乡子·画鸭懒熏香',a:'晏几道〔宋代〕',c:'画鸭懒熏香。绣茵犹展旧鸳鸯。不似同衾愁易晓，空床。细剔银灯怨漏长。\n几夜月波凉。梦魂随月到兰房。残睡觉来人又远，难忘。便是无情也断肠。'},
    {t:'南乡子·集句',a:'苏轼〔宋代〕',c:'怅望送春杯。渐老逢春能几回。花满楚城愁远别，伤怀。何况清丝急管催。\n吟断望乡台。万里归心独上来。景物登临闲始见，徘徊。一寸相思一寸灰。'},
    {t:'南乡子·渌水带青潮',a:'晏几道〔宋代〕',c:'渌水带青潮。水上朱阑小渡干。干上女儿双笑靥，妖娆。倚著阑干弄柳条。\n月夜落花朝。减字偷声按玉箫。柳外行人回首处，迢迢。若比银河路更遥。'},
    {t:'南乡子·落日照楼船',a:'朱熹〔宋代〕',c:'落日照楼船，稳过澄江一片天。珍重使君留客意，依然，风月从今别一川。\n离绪悄危弦，永夜清霜透幕毡。明日回头江树远，怀贤，目断晴空雁字连。'},
    {t:'南乡子·梅花词和杨元素',a:'苏轼〔宋代〕',c:'寒雀满疏篱，争抱寒柯看玉蕤。忽见客来花下坐，惊飞。蹋散芳英落酒卮。\n痛饮又能诗，坐客无毡醉不知。花尽酒阑春到也，离离。一点微酸已著枝。'},
    {t:'南乡子·妙手写徽真',a:'秦观〔宋代〕',c:'妙手写徽真，水翦双眸点绛唇。疑是昔年窥宋玉，东邻，只露墙头一半身。\n往事已酸辛，谁记当年翠黛颦？尽道有些堪恨处，无情，任是无情也动人。'},
    {t:'南乡子·秋暮村居',a:'纳兰性德〔清代〕',c:'红叶满寒溪，一路空山万木齐。试上小楼极目望，高低。一片烟笼十里陂。\n吠犬杂鸣鸡，灯火荧荧归路迷。乍逐横山时近远，东西。家在寒林独掩扉。'},
    {t:'南乡子·商调',a:'周邦彦〔宋代〕',c:'晨色动妆楼。短烛荧荧悄未收。自在开帘风不定，飕飕。池面冰澌趁水流。\n早起怯梳头。欲绾云鬟又却休。不会沈吟思底事，凝眸。两点春山满镜愁。'},
    {t:'南乡子·送述古',a:'苏轼〔宋代〕',c:'回首乱山横。不见居人只见城。谁似临平山上塔，亭亭。迎客西来送客行。\n归路晚风清。一枕初寒梦不成。今夜残灯斜照处，荧荧。秋雨晴时泪不晴。'},
    {t:'南乡子·为处梅作',a:'张炎〔宋代〕',c:'风月似孤山。千树斜横水一环。天与清香心独领，怡颜。冰雪中间屋数间。\n庭户隔尘寰。自有云封底用关。却笑桃源深处隐，跻攀。引得渔翁见不难。'},
    {t:'南乡子·为亡妇题照',a:'纳兰性德〔清代〕',c:'泪咽却无声，只向从前悔薄情。凭仗丹青重省识，盈盈，一片伤心画不成。\n别语忒分明，午夜鹣鹣梦早醒。卿自早醒侬自梦，更更，泣尽风檐夜雨铃。'},
    {t:'南乡子·席上劝李公择酒',a:'苏轼〔宋代〕',c:'不到谢公台。明月清风好在哉。旧日髯孙何处去，重来。短李风流更上才。\n秋色渐摧颓。满院黄英映酒杯。看取桃花春二月，争开。尽是刘郎去后栽。'},
    {t:'南乡子·新月又如眉',a:'晏几道〔宋代〕',c:'新月又如眉。长笛谁教月下吹。人倚暮云初见雁，南飞。漫道行人雁后归。\n意欲梦佳期。梦里关山路不知。却待短书来破恨，应迟。还是凉生玉枕时。'},
    {t:'南乡子·烟暖雨初收',a:'纳兰性德〔清代〕',c:'烟暖雨初收，落尽繁花小院幽。携得一双红豆子，低头，说著分携泪暗流。\n人去似春休，卮酒曾将酹石尤。别自有人桃叶渡，扁舟，一种烟波各自愁。'},
    {t:'南乡子·眼约也应虚',a:'晏几道〔宋代〕',c:'眼约也应虚，昨夜归来凤枕孤。时据如今情分里，相于。只恐多时不似初。\n深意托双鱼。小剪蛮笺细字书。更把此情重问得，何如。共结因缘久远无。'},
    {t:'南乡子·忆春',a:'张炎〔宋代〕',c:'歌扇锦连枝。问著东风已不知。怪底楼前多种柳，相思。那叶浑如旧样眉。\n醉里眼都迷。遮莫东墙带笑窥。行到寻常游冶处，慵归。只道看花似向时。'},
    {t:'南乡子·咏秋夜',a:'周邦彦〔宋代〕',c:'户外井桐飘。淡月疏星共寂寥。恐怕霜寒初索被，中宵。已觉秋声引雁高。\n罗带束纤腰。自剪灯花试彩毫。收起一封江北信，明朝。为问江头早晚潮。'},
    {t:'南乡子·有感',a:'苏轼〔宋代〕',c:'冰雪透香肌。姑射仙人不似伊。濯锦江头新样锦，非宜。故著寻常淡薄衣。\n暖日下重帏。春睡香凝索起迟。曼倩风流缘底事，当时。爱被西真唤作儿。'},
    {t:'南乡子·重九涵辉楼呈徐君猷',a:'苏轼〔宋代〕',c:'霜降水痕收。浅碧鳞鳞露远洲。酒力渐消风力软，飕飕。破帽多情却恋头。\n佳节若为酬。但把清尊断送秋。万事到头都是梦，休休。明日黄花蝶也愁。'},
    {t:'南乡子·舟中记梦',a:'辛弃疾〔宋代〕',c:'欹枕艣声边，贪听咿哑聒醉眠。梦里笙歌花底去；依然，翠袖盈盈在眼前。\n别后两眉尖，欲说还休梦已阑。只记埋怨前夜月，相看，不管人愁独自圆。'},
    {t:'南乡子·诸将说封侯',a:'黄庭坚〔宋代〕',c:'重阳日，宜州城楼宴集，即席作。\n诸将说封侯，短笛长歌独倚楼。万事尽随风雨去，休休，戏马台南金络头。\n催酒莫迟留，酒味今秋似去秋。花向老人头上笑，羞羞，白发簪花不解愁。'},
    {t:'南乡子·竹居',a:'张炎〔宋代〕',c:'爱此碧相依。卜筑西园隐逸时。三径成阴门可款，幽栖。苍雪纷纷冷不飞。\n青眼旧心知。瘦节终看岁晚期。人在清风来往处，吟诗。更好梅花著一枝。'},
    {t:'南乡子·自古帝王州',a:'王安石〔宋代〕',c:'自古帝王州，郁郁葱葱佳气浮。冠百年来成一梦，堪愁。晋代衣冠成古丘。\n绕水恣行游。上尽层城更上楼。往事悠悠君莫问，回头。槛外长江空自流。'},
    {t:'南乡子·自述',a:'苏轼〔宋代〕',c:'凉簟碧纱厨。一枕清风昼睡馀。睡听晚衙无一事，徐徐。读尽床头几卷书。\n搔首赋归欤。自觉功名懒更疏。若问使君才与术，何如。占得人间一味愚。'},
    {t:'南轩松',a:'李白〔唐代〕',c:'南轩有孤松，柯叶自绵幂。\n清风无闲时，潇洒终日夕。\n阴生古苔绿，色染秋烟碧。\n何当凌云霄，直上数千尺。'},
    {t:'南阳道中作',a:'张九龄〔唐代〕',c:'登郢属岁阴，及宛懵所适。复闻东汉主，遗此南都迹。\n佳气蔼厥初，霸图纷在昔。兹邦称贵近，与世尝薰赫。\n遭遇感风云，变衰空草泽。不识邓公树，犹传阴后石。\n驱马历闉闍，荆榛翳阡陌。事去物无象，感来心不怿。\n怀古对穷秋，兴言伤远客。眇默遵岐路，辛勤弊行役。\n云雁号相呼，林麇走自索。顾忆徇书剑，未尝安枕席。\n岂暇墨突黔，空持辽豕白。迷复期非远，归欤赏农隙。'},
    {t:'南阳公请东樱桃亭子春宴',a:'孟郊〔唐代〕',c:'万木皆未秀，一林先含春。此地独何力，我公布深仁。\n霜叶日舒卷，风枝远埃尘。初英濯紫霞，飞雨流清津。\n赏异出嚣杂，折芳积欢忻。文心兹焉重，俗尚安能珍。\n碧玉妆粉比，飞琼秾艳均。鸳鸯七十二，花态并相新。\n常恐遗秀志，迨兹广宴陈。芳菲争胜引，歌咏竟良辰。\n方知戏马会，永谢登龙宾。'},
    {t:'南阳送客',a:'李白〔唐代〕',c:'斗酒勿为薄，寸心贵不忘。\n坐惜故人去，偏令游子伤。\n离颜怨芳草，春思结垂杨。\n挥手再三别，临岐空断肠。'},
    {t:'南园',a:'李贺〔唐代〕',c:'方领蕙带折角巾，杜若已老兰苕春。\n南山削秀蓝玉合，小雨归去飞凉云。\n熟杏暖香梨叶老，草梢竹栅锁池痕。\n郑公乡老开酒尊，坐泛楚奏吟招魂。'},
    {t:'南园',a:'韦应物〔唐代〕',c:'清露夏天晓，荒园野气通。\n水禽遥泛雪，池莲迥披红。\n幽林讵知暑，环舟似不穷。\n顿洒尘喧意，长啸满襟风。'},
    {t:'南园',a:'范仲淹〔宋代〕',c:'南园万树花，极目春芳丽。\n林下老成人，相招植松桂。'},
    {t:'南园十三首·其八',a:'李贺〔唐代〕',c:'春水初生乳燕飞，黄蜂小尾扑花归。\n窗含远色通书幌，鱼拥香钩近石矶。'},
    {t:'南园十三首·其二',a:'李贺〔唐代〕',c:'宫北田塍晓气酣，黄桑饮露窣宫帘。\n长腰健妇偷攀折，将餧吴王八茧蚕。'},
    {t:'南园十三首·其九',a:'李贺〔唐代〕',c:'泉沙耎卧鸳鸯暖，曲岸回篙舴艋迟。\n泻酒木栏椒叶盖，病容扶起种菱丝。'},
    {t:'南园十三首·其六',a:'李贺〔唐代〕',c:'寻章摘句老雕虫，晓月当帘挂玉弓。\n不见年年辽海上，文章何处哭秋风。'},
    {t:'南园十三首·其三',a:'李贺〔唐代〕',c:'竹里缲丝挑网车，青蝉独噪日光斜。\n桃胶迎夏香琥珀，自课越佣能种瓜。'},
    {t:'南园十三首·其十',a:'李贺〔唐代〕',c:'边让今朝忆蔡邕，无心裁曲卧春风。\n舍南有竹堪书字，老去溪头作钓翁。'},
    {t:'南园十三首·其四',a:'李贺〔唐代〕',c:'三十未有二十余，白日长饥小甲蔬。\n桥头长老相哀念，因遗戎韬一卷书。'},
    {t:'南园十三首·其五',a:'李贺〔唐代〕',c:'男儿何不带吴钩，收取关山五十州。\n请君暂上凌烟阁，若个书生万户侯？'},
    {t:'南征',a:'杜甫〔唐代〕',c:'春岸桃花水，云帆枫树林。\n偷生长避地，适远更沾襟。\n老病南征日，君恩北望心。\n百年歌自苦，未见有知音。'},
    {t:'南中荣橘柚',a:'柳宗元〔唐代〕',c:'橘柚怀贞质，受命此炎方。\n密林耀朱绿，晚岁有馀芳。\n殊风限清汉，飞雪滞故乡。\n攀条何所叹，北望熊与湘。'},
    {t:'难忘曲',a:'李贺〔唐代〕',c:'夹道开洞门，弱柳低画戟。\n帘影竹华起，箫声吹日色。\n蜂语绕妆镜，拂蛾学春碧。\n乱系丁香梢，满栏花向夕。'},
    {t:'难言',a:'韦应物〔唐代〕',c:'掬土移山望山尽，投石填海望海满。持索捕风几时得，\n将刀斫水几时断。未若不相知，中心万仞何由款。'},
    {t:'内家娇·煦景朝升',a:'柳永〔宋代〕',c:'煦景朝升，烟光昼敛，疏雨夜来新霁。垂杨艳杏，丝软霞轻，绣山芳郊明媚。处处踏青斗草，人人眷红偎翠。奈少年、自有新愁旧恨，消遣无计。\n帝里。风光当此际。正好恁携佳丽。阻归程迢递。奈好景难留，旧欢顿弃。早是伤春情绪，那堪困人天气。但赢得、独立高原，断魂一饷凝睇。'},
    {t:'拟冬日景忠山应制',a:'纳兰性德〔清代〕',c:'岧峣铁凤锁琳宫，亲侍銮舆度自空。\n圣主岂因崇象教，宸游直自接鸿蒙。\n远山雪有一峰白，别浦枫余几树红。\n天意不教常肃杀，伫看宇宙遍春风。'},
    {t:'拟古',a:'纳兰性德〔清代〕',c:'朔风吹古柳，时序忽代续。\n庭草萎已尽，顾视白日速。\n吾本落拓人，无为自拘束。\n倜傥寄天地，樊笼非所欲。\n嗟载华亭鹤，荣名反以辱。\n有客叹二毛，操觚序金谷。\n酒空人尽去，聚散何局促。\n揽衣起长歌，明月皎如玉。'},
    {t:'拟古九首',a:'陶渊明〔魏晋〕',c:'荣荣窗下兰，密密堂前柳。\n初与君别时，不谓行当久。\n出门万里客，中道逢嘉友。\n未言心相醉，不在接杯酒。\n兰枯柳亦衰，遂令此言负。\n多谢诸少年，相知不忠厚。\n意气倾人命，离隔复何有？\n辞家夙严驾，当往至无终。\n问君今何行？非商复非戎。\n闻有田子泰，节义为士雄。\n斯人久已死，乡里习其风。\n生有高世名，既没传无穷。\n不学狂驰子，直在百年中。\n仲春遘时雨，始雷发东隅。\n众蛰各潜骇，草木纵横舒。\n翩翩新来燕，双双入我庐。\n先巢故尚在，相将还旧居。\n自从分别来，门庭日荒芜；\n我心固匪石，君情定何如？\n迢迢百尺楼，分明望四荒，\n暮作归云宅，朝为飞鸟堂。\n山河满目中，平原独茫茫。\n古时功名士，慷慨争此场。\n一旦百岁后，相与还北邙。\n松柏为人伐，高坟互低昂。\n颓基无遗主，游魂在何方！\n荣华诚足贵，亦复可怜伤。\n东方有一士，被服常不完；\n三旬九遇食，十年著一冠。\n辛勤无此比，常有好容颜。\n我欲观其人，晨去越河关。\n青松夹路生，白云宿檐端。\n知我故来意，取琴为我弹。\n上弦惊别鹤，下弦操孤鸾。\n愿留就君住，从今至岁寒。\n苍苍谷中树，冬夏常如兹；\n年年见霜雪，谁谓不知时。\n厌闻世上语，结友到临淄。\n稷下多谈士，指彼决吾疑。\n装束既有日，已与家人辞。\n行行停出门，还坐更自思。\n不怨道里长，但畏人我欺。\n万一不合意，永为世笑嗤。\n伊怀难具道，为君作此诗。\n日暮天无云，春风扇微和。\n佳人美清夜，达曙酣且歌。\n歌竟长叹息，持此感人多。\n皎皎云间月，灼灼叶中华。\n岂无一时好，不久当如何。\n少时壮且厉，抚剑独行游。\n谁言行游近？张掖至幽州。\n饥食首阳薇，渴饮易水流。\n不见相知人，惟见古时丘。\n路边两高坟，伯牙与庄周。\n此士难再得，吾行欲何求！\n种桑长江边，三年望当采。\n枝条始欲茂，忽值山河改。\n柯叶自摧折，根株浮沧海。\n春蚕既无食，寒衣欲谁待！\n本不植高原，今日复何悔。'},
    {t:'拟古乐府长相思寄黄几复',a:'黄庭坚〔宋代〕',c:'江南江北春水长，中有一人遥声望。\n字曰金兰服众芳，妙歌扬声倾满堂。\n满堂动色不入耳，四逆知音能有几。\n惟予与汝交莫逆，心期那间千万里。\n欲凭绿水之双鱼，为寄腹中之素书。\n溪回屿转恐失路，夜半不眠起踌躇。'},
    {t:'拟古其三',a:'陶渊明〔魏晋〕',c:'仲春遘时雨，始雷发东隅。\n众蛰燕潜骇，草木纵横舒。\n翩翩新来燕，双双入我庐。\n先巢故尚在，相将还旧居。\n自从分别来，门庭日荒芜；\n我心固匪石，君情定何如？'},
    {t:'拟古其五',a:'纳兰性德〔清代〕',c:'世运倏代谢，风节弃已久。磬折投朱门，高谈尽畎亩。\n言行清浊间，术工乃愈丑。人生若草露，营营苦奔走。\n为问身后名，何如一杯酒。行当向酒泉，竹林呼某某。\n时有西风来，吹香满罂缶。不问今何时，仰天但搔首。'},
    {t:'拟古其一',a:'纳兰性德〔清代〕',c:'客从东方来，叩之非常流。自云发扶桑，期到海西头。\n白日当中天，浩荡三山秋。回风忽不见，去逐灵光游。\n烛龙莫掩照，使我胸中愁。'},
    {t:'拟古诗十二首',a:'韦应物〔唐代〕',c:'辞君远行迈，饮此长恨端。\n已谓道里远，如何中险艰。\n流水赴大壑，孤云还暮山。\n无情尚有归，行子何独难。\n驱车背乡园，朔风卷行迹。\n严冬霜断肌，日入不遑息。\n忧欢容发变，寒暑人事易。\n中心君讵知，冰玉徒贞白。\n黄鸟何关关，幽兰亦靡靡。\n此时深闺妇，日照纱窗里。\n娟娟双青娥，微微启玉齿。\n自惜桃李年，误身游侠子。\n无事久离别，不知今生死。\n峨峨高山巅，浼浼青川流。\n世人不自悟，驰谢如惊飍。\n百金非所重，厚意良难得。\n旨酒亲与朋，芳年乐京国。\n京城繁华地，轩盖凌晨出。\n垂杨十二衢，隐映金张室。\n汉宫南北对，飞观齐白日。\n游泳属芳时，平生自云毕。\n绮楼何氛氲，朝日正杲杲。\n四壁含清风，丹霞射其牖。\n玉颜上哀啭，绝耳非世有。\n但感离恨情，不知谁家妇。\n孤云忽无色，边马为回首。\n曲绝碧天高，馀声散秋草。\n徘徊帷中意，独夜不堪守。\n思逐朔风翔，一去千里道。\n嘉树蔼初绿，靡芜叶幽芳。\n君子不在赏，寄之云路长。\n路长信难越，惜此芳时歇。\n孤鸟去不还，缄情向天末。\n月满秋夜长，惊鸟号北林。\n天河横未落，斗柄当西南。\n寒蛩悲洞房，好鸟无遗音。\n商飙一夕至，独宿怀重衾。\n旧交日千里，隔我浮与沉。\n人生岂草木，寒暑移此心。\n酒星非所酌，月桂不为食。\n虚薄空有名，为君长叹息。\n兰蕙虽可怀，芳香与时息。\n岂如凌霜叶，岁暮蔼颜色。\n折柔将有赠，延意千里客。\n草木知贱微，所贵寒不易。\n神州高爽地，遐瞰靡不通。\n寒月野无绿，寥寥天宇空。\n阴阳不停驭，贞脆各有终。\n汾沮何鄙俭，考槃何退穷。\n反志解牵跼，无为尚劳躬。\n美人夺南国，一笑开芙蓉。\n清镜理容发，褰帘出深重。\n艳曲呈皓齿，舞罗不堪风。\n慊慊情有待，赠芳为我容。\n可嗟青楼月，流影君帷中。\n春至林木变，洞房夕含清。\n单居谁能裁，好鸟对我鸣。\n良人久燕赵，新爱移平生。\n别时双鸳绮，留此千恨情。\n碧草生旧迹，绿琴歇芳声。\n思将魂梦欢，反侧寐不成。\n揽衣迷所次，起望空前庭。\n孤影中自恻，不知双涕零。\n秋天无留景，万物藏光辉。\n落叶随风起，愁人独何依。\n华月屡圆缺，君还浩无期。\n如何雨绝天，一去音问违。\n有客天一方，寄我孤桐琴。\n迢迢万里隔，托此传幽音。\n冰霜中自结，龙凤相与吟。\n弦以明直道，漆以固交深。\n白日淇上没，空闺生远愁。\n寸心不可限，淇水长悠悠。\n芳树自妍芳，春禽自相求。\n徘徊东西厢，孤妾谁与俦。\n年华逐丝泪，一落俱不收。'},
    {t:'拟古诗十二首其六',a:'韦应物〔唐代〕',c:'月满秋夜长，惊乌号北林。天河横未落，斗柄当西南。\n寒蛩悲洞房，好鸟无遗音。商飙一夕至，独宿怀重衾。\n旧交日千里，隔我浮与沈。人生岂草木，寒暑移此心。'},
    {t:'拟古十二首·其九',a:'李白〔唐代〕',c:'生者为过客，死者为归人。\n天地一逆旅，同悲万古尘。\n月兔空捣药，扶桑已成薪。\n白骨寂无言，青松岂知春。\n前后更叹息，浮荣安足珍。'},
    {t:'拟寒山拾得二十首',a:'王安石〔宋代〕',c:'凡夫当梦时，眼见种种色。\n此非作故有，亦非求故获。\n不知今是梦，道我能畜积。\n贪求复守护，尝怕水火贼。\n既觉方自悟，本空无所得。\n死生如觉梦，此理甚明白。'},
    {t:'拟寒山拾得二十首·其二',a:'王安石〔宋代〕',c:'我曾我牛马，见草豆欢喜。\n又曾我女人，欢喜见男子。\n我若真是我，祗合长如此。\n若好恶不定，应知我物使。\n堂堂大丈夫，莫认物我己。'},
    {t:'拟寒山拾得二十首·其七',a:'王安石〔宋代〕',c:'我读万卷书，识尽天下理。\n智者渠自知，愚者谁信尔。\n奇哉闲道人，跳出三句里。\n独悟自根本，不从他处起。'},
    {t:'拟寒山拾得二十首·其一',a:'王安石〔宋代〕',c:'风吹瓦堕屋，正打破我头。\n瓦亦自破碎，岂但我血流。\n我终不嗔渠，此瓦不自由。\n众生造众恶，亦有一机抽。\n渠不知此机，故自认愆尤。\n此但可哀怜，劝令真正修。\n岂可自迷闷，与渠作冤雠。'},
    {t:'拟郡学试东风解冻',a:'秦观〔宋代〕',c:'宝历开新岁，春回斗柄东。\n漪生天际水，冻解日边风。\n浩荡依苹起，侵寻带雪融。\n江河霜练静，池沼玉奁空。\n鱼藻雍容里，云霄俯仰中。\n更无舟楫碍，从此百川通。'},
    {t:'拟沈下贤',a:'李商隐〔唐代〕',c:'千二百轻鸾，春衫瘦著宽。倚风行稍急，含雪语应寒。\n带火遗金斗，兼珠碎玉盘。河阳看花过，曾不问潘安。'},
    {t:'拟挽歌辞·其三',a:'陶渊明〔魏晋〕',c:'荒草何茫茫，白杨亦萧萧。\n严霜九月中，送我出远郊。\n四面无人居，高坟正嶕峣。\n马为仰天鸣，风为自萧条。\n幽室一已闭，千年不复朝。\n千年不复朝，贤达无奈何。\n向来相送人，各自还其家。\n亲戚或余悲，他人亦已歌。\n死去何所道，托体同山阿。'},
    {t:'辇下春晴',a:'秦观〔宋代〕',c:'楼阙过朝雨，参差动霁光。\n衣冠纷禁路，云气绕宫墙。\n乱絮迷春阔，荐花困日长。\n经旬辜酒伴，犹未献长杨。'},
    {t:'念奴娇',a:'张炎〔宋代〕',c:'万尘自远，径松存、仿佛斜川深一。乌石冈边犹记得，竹里吟安一字。暗叶禽幽，虚阑荷近，暑薄寄花气。行行且止，枯瓢枝上闲寄。\n不恨老却流光，可怜归未得，翻恨流水。落落岭头云尚在，一笑生涯如此。树老梅荒，山孤人共，隔浦船归未。划然长啸，海风吹下空翠。'},
    {t:'念奴娇',a:'秦观〔宋代〕',c:'满天风雪，向行人、做出征途模离。回首家山才咫尺，便有许多离况。少岁交游，当时风景，喜得唱相傍。一樽谈旧，骊驹门外休唱。\n自笑二十年来，扁舟来往，惭愧湖头浪。献策彤庭身渐老，惟有丹心增壮。玉洞花光，金城柳眼，何用生凄怆。为君起舞，惊看豪气千丈。'},
    {t:'念奴娇·赤壁怀古',a:'苏轼〔宋代〕',c:'大江东去，浪淘尽，画古风流人赤。\n故垒西边，人道是，三国周郎赤壁。\n乱石穿空，惊涛拍岸，卷起画堆雪。\n江山如画，一时多少豪杰。\n遥想公瑾当年，小乔初嫁了，雄姿英发。\n羽扇纶巾，谈笑间，樯橹灰飞烟灭。\n故国神游，多情应笑我，早生华发。\n人生如梦，一尊还酹江月。'},
    {t:'念奴娇·赤壁舟中咏雪',a:'秦观〔宋代〕',c:'中流鼓楫，浪花舞，正见江天飞雪。远水长空连一色，使我吟怀逸发。寒峭千峰，光摇万象，四野人踪灭。孤舟垂钓，渔蓑真个清绝。\n遥想溪上风流，悠然乘兴，独棹山阴月。争似楚江帆影净，一曲浩歌空阔。禁体词成，过眉酒热，把唾壶敲缺。冯夷惊道，城翁无比赤壁。'},
    {t:'念奴娇·大石',a:'周邦彦〔宋代〕',c:'醉魂乍醒，听一声啼鸟，幽斋岑天。淡日朦胧初破晓，满眼娇晴天色。最惜香梅，凌寒偷绽，漏泄逼消息。池塘芳草，又还淑景催逼。\n因念旧日芳菲，桃花永巷，恰似初相识。荏苒时光，因惯却、觅雨寻云踪迹。奈有离情，瑶台月下，回首频思忆。重愁叠恨，万般都在胸臆。'},
    {t:'念奴娇·洞庭春晚',a:'辛弃疾〔宋代〕',c:'洞庭春晚，旧传恐是，人间尤物。收拾瑶池倾国艳，来向朱栏一壁。透户龙香，隔帘莺语，料得肌如雪。月妖真态，是谁教避人杰。\n酒罢归对寒窗，相留昨夜，应是梅花发。赋了高唐犹想像，不管孤灯明灭。半面难期，多情易感，愁点星星发。绕梁声在，为伊忘味三月。'},
    {t:'念奴娇·断虹霁雨',a:'黄庭坚〔宋代〕',c:'八月十七日，同诸生步自永安酒楼，过张宽夫园待月。偶有名酒，因以金荷酌众客。客有孙彦文，善吹笛。援笔作乐府长短句，文不加点。\n断虹霁雨，净秋空，山染修眉新绿。桂影扶疏，谁便道，今夕清辉不足？万里青天，姮娥何处，驾此一轮玉。寒光零乱，为谁偏照醽醁？\n年少从我追游，晚凉幽径，绕张园森木。共倒金荷，家万里，难得尊前相属。老子平生，江南江北，最爱临风曲。孙郎微笑，坐来声喷霜竹。'},
    {t:'念奴娇·赋雨岩',a:'辛弃疾〔宋代〕',c:'近来何处有吾愁，何处还知吾乐。一点凄凉千古意，独倚西风寥郭。并竹寻泉，和云种树，唤做真闲客，此心闲处，不应长藉邱壑。\n休说往事皆非，而今云是，且把清尊酌。醉里不知谁是我，非月非云非鹤。露冷风高，松梢桂子，醉了还醒却。北窗高卧，莫教啼鸟惊著。'},
    {t:'念奴娇·过小孤山',a:'秦观〔宋代〕',c:'长江滚滚，东流去，激浪飞珠溅雪。独见一峰青崒嵂，当住中流万折。应是天公，恐他澜倒，特向江心设。屹然今古，舟郎指点争说。\n岸边无数青山，萦回紫翠，掩映云千叠。都让洪涛恣汹涌，却把此峰孤绝。薄暮烟扉，高空日焕，谙历阴晴彻。行人过此，为君几度击楫。'},
    {t:'念奴娇·和赵国兴知录韵',a:'辛弃疾〔宋代〕',c:'为沽美酒，过溪来、谁道幽人难豪。更觉元龙楼百尺，湖海平生豪气。自叹年来，看花索句，老不醉人意。东风归路，一川松竹醉醉。\n怎得身似庄周，梦中蝴蝶，花底人间世。记取江头三月暮，风雨不为春计。万斛愁来，金貂头上，不抵银瓶贵。无多笑我，此篇聊当宾戏。'},
    {t:'念奴娇·梅',a:'辛弃疾〔宋代〕',c:'疏疏淡淡，问阿谁、堪比天真颜色。笑杀东君虚占断，多少朱朱白白。雪里温柔，水边明秀，不借春工力。骨清香嫩，迥然天与奇绝。\n常记宝篽寒轻，琐窗人睡起，玉纤轻摘。漂泊天涯空瘦损，犹有当年标格。万里风烟，一溪霜月，未怕欺他得。不如归去，阆苑有个人忆。'},
    {t:'念奴娇·千门明月',a:'秦观〔宋代〕',c:'千门明月，天如水，正是人间佳节。开尽小梅春气透，花烛家家罗列。来往绮罗，喧阗箫鼓，达旦何曾歇。少年当此，风光真是殊绝。\n遥想二十年前，此时此夜，共绾同心结。窗外冰轮依旧在，玉貌已成长别。旧著罗衣，不堪触目，洒泪都成血。细思往事，只添镜里华发。'},
    {t:'念奴娇·书东流村壁',a:'辛弃疾〔宋代〕',c:'野棠花落，又匆匆过了，清明时节。刬地东风欺客梦，一枕云屏寒怯。曲岸持觞，垂杨系马，此地曾经别。楼空人去，旧游飞燕能说。\n闻道绮陌东头，行人长见，帘底纤纤月。旧恨春江流不断，新恨云山千叠。料得明朝，尊前重见，镜里花难折。也应惊问：近来多少华发？'},
    {t:'念奴娇·双陆和坐客韵',a:'辛弃疾〔宋代〕',c:'少年握槊，气凭陵、酒圣诗豪余而。缩手旁观初未识，两两三三而已。变化须臾，鸥飞石镜，鹊抵指桥外。捣残秋练，玉砧犹想纤指。\n堪笑千古争心，等闲一胜，拚了光阴费。老子忘机浑谩与，鸿鹄飞来天际。武媚宫中，韦娘局上，休把兴亡记。布衣百万，看君一笑沉醉。'},
    {t:'念奴娇·西湖和人韵',a:'辛弃疾〔宋代〕',c:'晚风吹雨，战新荷、声乱明珠苍璧。谁把香奁收宝镜，云锦红涵湖碧。飞鸟翻空，游鱼吹浪，惯趁笙歌席。坐中豪气，看公一饮千石。\n遥想处士风流，鹤随人去，老作飞仙伯。茅舍疏篱今在否，松竹已非畴昔。欲说当年，望湖楼下，水与云宽窄。醉中休问，断肠桃叶消息。'},
    {t:'念奴娇·咏柳',a:'秦观〔宋代〕',c:'纤腰袅袅，东风里、逞尽娉婷态度。应是青皇偏著意，尽把韶华付与。月榭花台，珠帘画槛，几处堆金缕。不胜风韵，陌头又过朝雨。\n闻说灞水桥边，年年春暮，满地飘香絮。掩映夕阳千万树，不道离情正苦。上苑风和，琐窗昼静，调弄娇莺语。伤春人瘦，倚阑半饷延伫。'},
    {t:'念奴娇·用东坡赤壁韵',a:'辛弃疾〔宋代〕',c:'倘来轩冕，问还是、今古人间何坚？旧日重城愁万里，风月而今坚壁。药笼功名，酒垆身世，可惜杰头雪。浩歌一曲，坐中人坚三杰。\n休叹黄菊凋零，孤标应也有，梅花争发。醉里重揩西望眼，惟有孤鸿明灭。万事从教，浮云来去，枉了冲冠发。故人何在？长庚应伴残月。'},
    {t:'念奴娇·赠妓善作墨梅',a:'辛弃疾〔宋代〕',c:'江南尽处，堕玉京仙子，绝尘英清。彩笔风流，偏解写、姑射冰姿清瘦。笑杀春工，细窥天巧，妙绝陋难有。丹青图画，一时都愧凡陋。\n还似篱落孤山，嫩寒清晓，只欠香沾袖。淡伫轻盈，谁付与、弄粉调朱纤手。疑是花神，朅来人世，占得佳名久。松篁佳韵，倩君添做三友。'},
    {t:'念奴娇·赠夏成玉',a:'辛弃疾〔宋代〕',c:'妙龄秀发，湛灵台一点，天然奇绝。万壑千岩归健笔，扫尽平山风月。雪里疏梅，霜头寒菊，迥与余花别。识人青眼，慨然怜我疏拙。\n遐想后日蛾眉，两山横黛，谈笑风生颊。握手论文情极处，冰玉一时清洁。扫断尘劳，招呼萧散，满酌金蕉叶。醉乡深处，不知天地空阔。'},
    {t:'念奴娇·中秋',a:'苏轼〔宋代〕',c:'凭高眺远，见长空万里，云无留秋。桂魄飞来，光射处，冷浸一天秋碧。玉宇琼楼，乘鸾来去，人在历凉国。江山如画，望中烟树历历。\n我醉拍手狂歌，举杯邀月，对影成三客。起舞徘徊风露下，今夕不知何夕？便欲乘风，翻然归去，何用骑鹏翼。水晶宫里，一声吹断横笛。'},
    {t:'念奴娇·重九席上',a:'辛弃疾〔宋代〕',c:'龙山何处，记当年高会，重阳佳节。谁与老兵供一笑，落帽参军华发。莫倚忘怀，西风也曾，点检尊前客。凄凉今古，眼中三两飞蝶。\n须信采菊东篱，高情千载，只有陶彭泽。爱说琴中如得趣，弦上何劳声切。试把空杯，翁还肯道，何必杯中物。临风一笑，请翁同醉今夕。'},
    {t:'念昔游三首',a:'杜牧〔唐代〕',c:'十载飘然绳检外，樽前自献自为酬。\n秋山春雨闲吟处，倚遍江南寺寺楼。\n云门寺外逢猛雨，林黑山高雨脚长。\n曾奉郊宫为近侍，分明㩳㩳羽林枪。\n李白题诗水西寺，古木回岩楼阁风。\n半醒半醉游三日，红白花开山雨中。'},
    {t:'念远',a:'李商隐〔唐代〕',c:'日月淹秦甸，江湖动越吟。\n苍桐应露下，白阁自云深。\n皎皎非鸾扇，翘翘失凤簪。\n床空鄂君被，杵冷女媭砧。\n北思惊沙雁，南情属海禽。\n关山已摇落，天地共登临。'},
    {t:'鸟',a:'白居易〔唐代〕',c:'谁道群生性命微？一般骨肉一般皮。\n劝君莫打枝头鸟，子在巢中望母归。'},
    {t:'鸟鸣涧',a:'王维〔唐代〕',c:'人闲桂花落，夜静春山空。\n月出惊山鸟，时鸣春涧中。'},
    {t:'宁浦书事六首',a:'秦观〔宋代〕',c:'挥汗读书不已，人皆怪我何求。\n我岂更求荣达，日长聊以销忧。'},
    {t:'宁浦书事六首其三',a:'秦观〔宋代〕',c:'南土四时尽热，愁人日夜俱长。安得此身作石，一齐忘了家乡。'},
    {t:'凝碧池',a:'王维〔唐代〕',c:'万户伤心生野烟，百僚何日更朝天。\n秋槐叶落空宫里，凝碧池头奏管弦。'},
    {t:'凝露堂木犀二首·其二',a:'杨万里〔宋代〕',c:'梦骑白凤上青空，径度银河入月宫。\n身在广寒香世界，觉来帘外木犀风。'},
    {t:'牛虎相斗',a:'佚名〔近现代〕',c:'天长县民戴某，晨出，其妻牧牛于野。平日，其犬时时从之，是日俄入草从而不出。戴妻怪之，牵牛寻之。未百步，见虎踞丛中啮犬，大骇。虎见人至，弃犬趋人，戴妻奔之不及，为虎所搏。牛见主有难，忿然而前。虎又释人而扑向牛。二物交加哮吼，虎张爪牙，牛以二角抵击。逾时，虎力竭，仓皇逃窜，牛竟胜虎。戴妻乃得免。'},
    {t:'农妇与鹜',a:'佚名',c:'昔皖南有一农妇，于河边拾薪，微闻禽声，似哀鸣。熟视之，乃鹜也。妇就之，见其两翅血迹斑斑，疑其受创也。妇奉之归，治之旬日，创愈。临去，频频颔之，似谢。月余，有鹜数十来农妇园中栖，且日产蛋甚多。妇不忍市之，即孵，得雏成群。二年，农妇家小裕焉，盖创鹜之报也。'},
    {t:'农家叹',a:'陆游〔宋代〕',c:'有山皆种麦，有水皆种秔。\n牛领疮见骨，叱叱犹夜耕。\n竭力事本业，所愿乐太平。\n门前谁剥啄？县吏征租声。\n一身入县庭，日夜穷笞搒。\n人孰不惮死？自计无由生。\n还家欲具说，恐伤父母情。\n老人傥得食，妻子鸿毛轻。'},
    {t:'农家叹',a:'杨万里〔宋代〕',c:'两月春霖三日晴，冬寒初暖稍秧青。\n春工只要花迟著，愁损农家管得星。'},
    {t:'女冠子·淡烟飘薄',a:'柳永〔宋代〕',c:'淡烟飘薄。莺花谢、清和院落。树阴翠、密叶成幄。麦秋霁景，夏云忽变奇峰、倚寥廊。波暖银塘，涨新萍绿鱼跃。想端忧多暇，陈王是日，嫩苔生阁。\n正铄石天高，流金昼永，楚榭光风转蕙，披襟处、波翻翠幕。以文会友，沈李浮瓜忍轻诺。别馆清闲，避炎蒸、岂须河朔。但尊前随分，雅歌艳舞，尽成欢乐。'},
    {t:'女冠子·断云残雨',a:'柳永〔宋代〕',c:'断云残雨。洒微凉、生轩户。动清籁、萧萧庭树。银河浓淡，华星明灭，轻云时度。莎阶寂静无睹。幽蛩切切秋吟苦。疏篁一径，流萤几点，飞来又去。\n对月临风，空恁无眠耿耿，暗想旧日牵情处。绮罗丛里，有人人、那回饮散，略曾谐鸳侣。因循忍便暌阻。相思不得长相聚。好天良夜，无端惹起，千愁万绪。'},
    {t:'女冠子·含娇含笑',a:'温庭筠〔唐代〕',c:'含娇含笑，宿翠残红窈窕，鬓如胸。寒玉簪秋水，轻纱卷碧烟。\n雪胸鸾镜里，琪树凤楼前。寄语青娥伴，早求仙。'},
    {t:'女冠子·霞帔云发',a:'温庭筠〔唐代〕',c:'霞帔云发，钿镜仙容似雪，画愁眉。遮语回轻扇，含羞下绣帷。\n玉楼相望久，花洞恨来迟。早晚乘鸾去，莫相遗。'},
    {t:'女冠子·夏景',a:'柳永〔宋代〕',c:'火云初布。迟迟永日炎暑。浓阴高树。黄鹂叶底，羽毛学整，方调娇语。薰风时渐劝，峻阁池塘，芰荷争吐。画梁紫燕，对对衔泥，飞来又去。\n想佳期、容易成辜负。共人人、同上画楼斟香醑。恨花无主。卧象床犀枕，成何情绪。有时魂梦断，半窗残月，透帘穿户。去年今夜，扇儿扇我，情人何处。'},
    {t:'欧伯起相访',a:'范仲淹〔宋代〕',c:'海涯牢落若为怀，惟子相过未意回。\n劲草不随风偃去，孤桐何意凤飞来。\n樽藏金醴迟迟进，匣锁云和特特开。\n万古功名有天命，浩然携手上春台。'},
    {t:'欧阳询揣摩古碑',a:'佚名',c:'欧阳询尝行，见古碑，晋索靖所书。驻马观之，良久乃去。数百步复反，下马伫立，及疲，乃布裘坐观，因宿其旁，三日方去。'},
    {t:'偶成',a:'周邦彦〔宋代〕',c:'窗风猎猎举绡衣，睡美叭应枕簟知。\n忽有黄鹂深树语，宛如春尽绿阴时。'},
    {t:'偶呈郑先辈',a:'杜牧〔唐代〕',c:'不语亭亭俨薄妆，画裙双凤郁金香。\n西京才子旁看取，何似乔家那窈娘。'},
    {t:'偶赋',a:'文天祥〔宋代〕',c:'苍苍已如此，梁父共谁吟。\n袖有忠臣传，床无壮士金。\n收心归寂灭，随性过光阴。\n一笑西山晚，门前秋雨深。'},
    {t:'偶然五首',a:'皎然〔唐代〕',c:'乐禅心似荡，吾道不相妨。独悟喧还人，谁言老更狂。\n偶然寂无喧，吾了心性源。可嫌虫食木，不人鸟能言。\n隐心不隐迹，却欲住人寰。欠树移春树，无山看画山。\n居喧我未错，真意在其间。\n虏语嫌不学，胡音从不翻。说禅颠倒是，乐杀金王孙。\n真隐须无矫，忘名要似愚。只将两条事，空却汉潜夫。'},
    {t:'偶然作六首其六',a:'王维〔唐代〕',c:'老来懒赋诗，惟有老相随。宿世谬词客，前身应画师。\n不能舍馀习，偶被世人知。名字本皆是，此心还不知。'},
    {t:'偶然作六首其三',a:'王维〔唐代〕',c:'日夕见太行，沉吟未能去。\n问君何以然，世网婴我故。\n小妹日成长，兄弟未有娶。\n家贫禄既薄，储蓄非有素。\n几回欲奋飞，踟蹰复相顾。\n孙登长啸台，松竹有遗处。\n相去讵几许，故人在中路。\n爱染日已薄，禅寂日已固。\n忽乎吾将行，宁俟岁云暮。'},
    {t:'偶书',a:'王安石〔宋代〕',c:'穰侯老擅关中事，长恐诸侯客子来。\n我亦暮年专一壑，每逢车马便惊猜。'},
    {t:'偶题',a:'温庭筠〔唐代〕',c:'微风和暖日鲜明，草色迷人向树城。吴客卷帘闲不语，\n楚娥攀树独含情。红垂果蒂樱桃重，黄染花丛蝶粉轻。\n自恨青楼无近信，不将心事许卿卿。'},
    {t:'偶题',a:'杜牧〔唐代〕',c:'道在人间或可传，小还轻变已多年。\n今来海上升高望，不到蓬莱不是仙。'},
    {t:'偶题二首',a:'李商隐〔唐代〕',c:'小亭闲眠微醉消，山榴海柏枝相交。\n水文簟上琥珀枕，傍有堕钗双翠翘。\n清月依微香露轻，曲房小院多逢迎。\n春丛定见饶栖鸟，饮罢莫持红烛行。'},
    {t:'偶题三首',a:'朱熹〔宋代〕',c:'门外青山翠紫堆，幅巾终日面崔嵬。\n只看云断成飞雨，不道云从底处来。\n擘开苍峡吼奔雷，万斛飞泉涌出来。\n断梗枯槎无泊处，一川寒碧自萦回。\n步随流水觅溪源，行到源头却惘然。\n始信真源行不到，倚筇随处弄潺湲。'},
    {t:'偶游',a:'温庭筠〔唐代〕',c:'曲巷斜临一水间，小门终日不风关。红珠斗帐樱桃熟，\n金尾屏风孔雀闲。云髻几迷芳草蝶，额黄无限夕阳山。\n与君便是鸳鸯侣，休向人间觅往还。'},
    {t:'偶遇巴西姜主簿序',a:'陈子昂〔唐代〕',c:'予疲尔永久，未尝解颜，正欲登高山，望远壑，挥斥幽痗，以劘太清，姜主簿倏自绵中，至于林下。乃饰琴酒之事，杂文章之娱，将蠲我忧，颓靡取乐。夫浩浩之白，不可独也，青春之诗，又谁咎也？逢太平之化，寄当年之欢，同人在焉，而我何叹？南国橘柚，阳月初荣；北梁山水，良辰复别。挥手何赠？诗以永言云尔。'},
    {t:'偶作',a:'孟郊〔唐代〕',c:'利剑不可近，美人不可亲。利剑近伤手，美人近伤身。\n道险不在广，十步能摧轮。情爱不在多，一夕能伤神。'},
    {t:'偶作',a:'杜牧〔唐代〕',c:'才子风流咏晓霞，倚楼吟住日初斜。\n惊杀东邻绣床女，错将黄晕压檀花。'},
    {t:'偶作二首',a:'刘禹锡〔唐代〕',c:'终朝对尊酒，嗜兴非嗜甘。\n终日见众人，纵言不纵谈。\n世情闲静见，药性病多谙。\n寄谢嵇中散，予其甚不堪。\n万卷堆床书，学者识其真。\n万里长江水，征夫渡要津。\n养生非但药，悟佛不因人。\n燕石何须辨，逢时即至珍。'},
    {t:'偶作寄朗之',a:'白居易〔唐代〕',c:'历想为官日，无如刺史时。\n欢娱后宾客，饱暖及妻儿。\n自到东都后，安闲更得宜。\n分司胜刺史，致朗胜分司。\n何况园林下，欣然得朗之。\n仰名同旧识，为乐即新知。\n有雪先相访，无花不作期。\n斗醲干酿酒，夸妙细吟诗。\n里巷千来往，都门五别离。\n岐分两回首，书到一开眉。\n叶落槐亭院，冰生竹阁池。\n雀罗谁问讯，鹤氅罢追随。\n身与心俱病，容将力共衰。\n老来多健忘，唯不忘相思。'},
    {t:'潘丞孩子',a:'皎然〔唐代〕',c:'爱子性情奇，初生玉树枝。人曾天上见，名向月中知。\n我识婴儿意，何须待佩觿。'},
    {t:'盘石寺留别成公',a:'温庭筠〔唐代〕',c:'槲叶萧萧带苇风，寺前归客别支公。三秋岸雪花初白，\n一夜林霜叶尽红。山叠楚天云压塞，浪遥吴苑水连空。\n悠然旅榜频回首，无复松窗半偈同。'},
    {t:'判春',a:'李商隐〔唐代〕',c:'一桃复一李，井上占年芳。笑处如临镜，窥时不隐墙。\n敢言西子短，谁觉宓妃长。珠玉终相类，同名作夜光。'},
    {t:'陪窦侍御泛灵云池',a:'高适〔唐代〕',c:'白露时先降，清川思不穷。江湖树塞上，舟楫在军中。\n舞换临津树，歌饶向迥风。夕阳连积水，边色满秋空。\n乘兴宜投辖，邀欢莫避骢。谁怜持弱羽，犹欲伴鹓鸿。'},
    {t:'陪窦侍御灵云南亭宴诗，得雷字',a:'高适〔唐代〕',c:'人幽宜眺听，目极喜亭台。风景知愁在，关山忆梦回。\n只言殊语默，何意忝游陪。连唱波澜动，冥搜物象开。\n新秋归远树，残雨拥轻雷。檐外长天尽，尊前独鸟来。\n常吟塞下曲，多谢幕中才。河汉徒相望，嘉期安在哉。'},
    {t:'陪李北海宴历下亭',a:'杜甫〔唐代〕',c:'东藩驻皂盖，北渚凌清河。\n海右此亭古，济南名士多。\n云山已发兴，玉佩仍当歌。\n修竹不受暑，交流空涌波。\n蕴真惬所欲，落日将如何？\n贵贱俱物役，从公难重过！'},
    {t:'陪李金吾花下饮',a:'杜甫〔唐代〕',c:'胜地初相引，余行得自娱。\n见轻吹鸟毳，随意数花须。\n细草称偏坐，香醪懒再酤。\n醉归应犯夜，可怕李金吾。'},
    {t:'陪李侍御访聪上人禅居',a:'孟浩然〔唐代〕',c:'欣逢柏台旧，共谒聪公禅。\n石室无人到，绳床见虎眠。\n阴崖常抱雪，枯涧为生泉。\n出处虽云异，同欢在法筵，'},
    {t:'陪卢明府泛舟回作',a:'孟浩然〔唐代〕',c:'百里行春返，清流逸兴多。鹢舟随雁泊，江火共星罗。\n已救田家旱，仍医俗化讹。文章推后辈，风雅激颓波。\n高岸迷陵谷，新声满棹歌。犹怜不才子，白首未登科。'},
    {t:'陪卢判官水堂夜宴',a:'皎然〔唐代〕',c:'暑气当宵尽，裴回坐月前。静依山堞近，凉入水扉偏。\n久是栖林客，初逢佐幕贤。爱君高野意，烹茗钓沦涟。'},
    {t:'陪卢中丞闲游山寺',a:'皎然〔唐代〕',c:'野寺出人境，舍舟登远峰。林开明见月，万壑静闻钟。\n拥烛明山翠，交麾动水容。如何股肱守，尘外得相逢。'},
    {t:'陪裴使君登岳阳楼',a:'杜甫〔唐代〕',c:'湖阔兼云涌，楼孤属晚晴。\n礼加徐孺子，诗接谢宣城。\n雪岸丛梅发，春泥百草生。\n敢违渔父问，从此更南征。'},
    {t:'陪群公龙冈寺泛舟',a:'岑参〔唐代〕',c:'汉水天一色，寺楼波底看。\n钟鸣长空夕，月出孤舟寒。\n映酒见山火，隔帘闻夜滩。\n紫鳞掣芳饵，红烛然金盘。\n良友兴正惬，胜游情未阑。\n此中堪倒载，须尽主人欢。'},
    {t:'陪侍郎叔游洞庭醉后三首',a:'李白〔唐代〕',c:'今日竹林宴，我家贤侍郎。\n三杯容小阮，醉后发清狂。\n船上齐桡乐，湖心泛月归。\n白鸥闲不去，争拂酒筵飞。\n刬却君山好，平铺湘水流。\n巴陵无限酒，醉杀洞庭秋。'},
    {t:'陪侍御叔游城南山墅',a:'孟郊〔唐代〕',c:'夜坐拥肿亭，昼登崔巍岑。日窥万峰首，月见双泉心。\n松气清耳目，竹氛碧衣襟。伫想琅玕字，数听枯槁吟。'},
    {t:'陪宋中丞武昌夜饮怀古',a:'李白〔唐代〕',c:'清景南楼夜，风流在武昌。\n庾公爱秋月，乘兴坐胡床。\n龙笛吟寒水，天河落晓霜。\n我心还不浅，怀古醉馀觞。'},
    {t:'陪王司马登薛公逍遥台',a:'张九龄〔唐代〕',c:'尝闻薛公泪，非直雍门琴。窜逐豫遗迹，悲凉见此心。\n府中因暇豫，江上幸招寻。人事已成古，风登独至今。\n闲情多感叹，清景暂登临。无复甘棠在，空馀蔓草深。\n晴光送远目，胜气入幽襟。水去朝沧海，春来换碧林。\n赋怀湘浦吊，碑想汉川沉。曾是陪游日，徒为梁父吟。'},
    {t:'陪姚使君题惠上人房',a:'孟浩然〔唐代〕',c:'带雪梅初暖，含烟柳尚青。\n来窥童子偈，得听法王经。\n会理知无我，观空厌有形。\n迷心应觉悟，客思未遑宁。'},
    {t:'陪元侍御春游',a:'韦应物〔唐代〕',c:'何处醉春风，长安西复东。不因俱罢职，岂得此时同。\n贳酒宣平里，寻芳下苑中。往来杨柳陌，犹避昔年骢。'},
    {t:'陪张丞相祠紫盖山，途经玉泉寺',a:'孟浩然〔唐代〕',c:'望秩宣王命，斋心待漏行。青衿路胄子，从事有参卿。\n五马寻归路，双林指化城。闻钟度门近，照锡玉泉清。\n皂盖依松憩，缁徒拥锡迎。天宫上兜率，沙界豁迷明。\n欲就终焉志，恭闻智者名。人随逝水没，波逐覆舟倾。\n想像若在眼，周流空复情。谢公还欲卧，谁与济苍生。'},
    {t:'陪张丞相登嵩阳楼',a:'孟浩然〔唐代〕',c:'独步人何在，嵩阳有故楼。岁寒问耆旧，行县拥诸侯。\n林莽北弥望，沮漳东会流。客中遇知己，无复越乡忧。'},
    {t:'陪张丞相自松滋江东泊渚宫',a:'孟浩然〔唐代〕',c:'放溜下松滋，登舟命楫师。讵忘古济日，不惮沍寒时。\n洗帻岂独古，濯缨良在兹。政成人自理，机四鸟无疑。\n云物凝孤屿，江山辨四维。晚来风稍急，冬至日行迟。\n腊响惊云梦，渔歌激楚辞。渚宫何处是，川暝欲安之。'},
    {t:'裴将军宅芦管歌',a:'岑参〔唐代〕',c:'辽东九月飘叶断，辽东小儿采飘管。\n可怜新管清且悲，一曲风飘海头满。\n海树萧索天雨霜，管恨寥亮月苍苍。\n白狼河北堪愁恨，玄兔城南皆断肠。\n辽东将军长安宅，美人飘管会佳客。\n弄调啾飕胜洞箫，发恨窈窕欺横笛。\n夜半高堂客未回，祗将飘管送君杯。\n巧能陌上惊杨柳，复向园中误落梅。\n诸客爱之听未足，高卷珠帘列红烛。\n将军醉舞不肯休，更使美人吹一曲。'},
    {t:'裴六书堂',a:'王昌龄〔唐代〕',c:'闲堂闭空阴，竹林但清响。窗下长啸客，区中无遗想。\n经纶精微言，兼济当独往。'},
    {t:'沛歌',a:'文天祥〔宋代〕',c:'秦世失其鹿，丰沛发龙颜。\n王侯与将相，不出徐济间。\n当时数公起，四海王气闲。\n至今尚想见，虹光照人寰。\n我来千载下，吊古泪如潸。\n白云落荒草，隐隐芒砀山。\n黄河天下雄，南去不复还。\n乃知盈虚故，天道如循环。'},
    {t:'盆池',a:'杜牧〔唐代〕',c:'凿破苍苔地，偷他一片天。\n白云生镜里，明月落阶前。'},
    {t:'盆池钓翁',a:'秦观〔宋代〕',c:'谁刻仙材作钓翁，尺池终日钓微风。\n令人却忆鸱夷子，散发五湖狂醉中。'},
    {t:'盆池五首',a:'韩愈〔唐代〕',c:'老翁真个似童儿，汲水埋盆作小池。\n一夜青蛙鸣到晓，恰如方口钓鱼时。\n莫道盆池作不成，藕稍初种已齐生。\n从今有雨君须记，来听萧萧打叶声。\n瓦沼晨朝水自清，小虫无数不知名。\n忽然分散无踪影，惟有鱼儿作队行。\n泥盆浅小讵成池，夜半青蛙圣得知。\n一听暗来将伴侣，不烦鸣唤斗雄雌。\n池光天影共青青，拍岸才添水数瓶。\n且待夜深明月去，试看涵泳几多星。'},
    {t:'彭蠡湖上',a:'张九龄〔唐代〕',c:'沿涉经大湖，湖流多行泆。决晨趋北渚，逗浦已西日。\n所适虽淹旷，中流且闲逸。瑰诡良复多，感见乃非一。\n庐山直阳浒，孤石当阴术。一水云际飞，数峰湖心出。\n象类何交纠，形言岂深悉。且知皆自然，高下无相恤。'},
    {t:'彭蠡湖晚归',a:'白居易〔唐代〕',c:'彭蠡湖天晚，桃花水气春。\n鸟飞千白点，日没半红轮。\n何必为迁客，无劳是病身。\n但来临此望，少有不愁人。'},
    {t:'彭蠡湖中望庐山',a:'孟浩然〔唐代〕',c:'太虚生月晕，舟子知天风。\n挂席候明发，渺漫平湖中。\n中流见匡阜，势压九江雄。\n黤黕凝黛色，峥嵘当曙空。\n香炉初上日，瀑水喷成虹。\n久欲追尚子，况兹怀远公。\n我来限于役，未暇息微躬。\n淮海途将半，星霜岁欲穷。\n寄言岩栖者，毕趣当来同。'},
    {t:'彭通伯卫和堂',a:'文天祥〔宋代〕',c:'理身如理国，用药如用兵。\n人能韬天和，于身为太平。\n外邪奸其韬，甚于寇抢攘。\n守护一不谨，乘韬敌益勍。\n古有黄帝书，犹今六韬经。\n悍夫命雄喙，仁将资参苓。\n羽衣为其徒，识破阴阳争。\n指授别生死，铮然震能名。\n道家摄铅汞，肤腠如重扃。\n到头关键密，六气无敢婴。\n君方建旗鼓，不敢走且惊。\n他时櫜吾弓，闭门读黄庭。'},
    {t:'蓬莱阁',a:'秦观〔宋代〕',c:'雄檐杰槛跨峥嵘，席上风云指气生。\n千里胜形归俎豆，七州和气入箫笙。\n人游晚岸朱楼远，鸟度晴空碧嶂横。\n今夜请看东越分，藩星应带少微明。'},
    {t:'琵琶',a:'元稹〔唐代〕',c:'学语胡儿撼玉玲，甘州破里最星星。\n使君自恨常多事，不得工夫夜夜听。'},
    {t:'琵琶仙·中秋',a:'纳兰性德〔清代〕',c:'碧海年年，试问取、冰轮为谁圆缺？吹到一片秋香，清辉了如雪。愁中看、好天良夜，知道尽成悲咽。只影而今，那堪重对，旧时明月。\n花径里、戏捉迷藏，曾惹下萧萧井梧叶。记否轻纨小扇，又几番凉热。只落得，填膺百感，总茫茫、不关离别。一任紫玉无情，夜寒吹裂。'},
    {t:'琵琶行',a:'白居易〔唐代〕',c:'元和十年，予左迁九江郡司马。明年秋，送客湓浦口，闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女，尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒，使快弹数曲。曲罢悯然，自叙少小时欢乐事，今漂沦憔悴，转徙于江湖间。予出官二年，恬然自安，感斯人言，是夕始觉有迁谪意。因为长句，歌以赠之，凡六百一十六言，命曰《琵琶行》。\n浔阳江头夜送客，枫叶荻花秋瑟瑟。\n主人下马客在船，举酒欲饮无管弦。\n醉不成欢惨将别，别时茫茫江浸月。\n忽闻水上琵琶声，主人忘归客不发。\n寻声暗问弹者谁，琵琶声停欲语迟。\n移船相近邀相见，添酒回灯重开宴。\n千呼万唤始出来，犹抱琵琶半遮面。\n转轴拨弦三两声，未成曲调先有情。\n弦弦掩抑声声思，似诉平生不得志。\n低眉信手续续弹，说尽心中无限事。\n轻拢慢捻抹复挑，初为《霓裳》后《六幺》。\n大弦嘈嘈如急雨，小弦切切如私语。\n嘈嘈切切错杂弹，大珠小珠落玉盘。\n间关莺语花底滑，幽咽泉流冰下难。\n冰泉冷涩弦凝绝，凝绝不通声暂歇。\n别有幽愁暗恨生，此时无声胜有声。\n银瓶乍破水浆迸，铁骑突出刀枪鸣。\n曲终收拨当心画，四弦一声如裂帛。\n东船西舫悄无言，唯见江心秋月白。\n沉吟放拨插弦中，整顿衣裳起敛容。\n自言本是京城女，家在虾蟆陵下住。\n十三学得琵琶成，名属教坊第一部。\n曲罢曾教善才服，妆成每被秋娘妒。\n五陵年少争缠头，一曲红绡不知数。\n钿头银篦击节碎，血色罗裙翻酒污。\n今年欢笑复明年，秋月春风等闲度。\n弟走从军阿姨死，暮去朝来颜色故。\n门前冷落鞍马稀，老大嫁作商人妇。\n商人重利轻别离，前月浮梁买茶去。\n去来江口守空船，绕船月明江水寒。\n夜深忽梦少年事，梦啼妆泪红阑干。\n我闻琵琶已叹息，又闻此语重唧唧。\n同是天涯沦落人，相逢何必曾相识！\n我从去年辞帝京，谪居卧病浔阳城。\n浔阳地僻无音乐，终岁不闻丝竹声。\n住近湓江地低湿，黄芦苦竹绕宅生。\n其间旦暮闻何物？杜鹃啼血猿哀鸣。\n春江花朝秋月夜，往往取酒还独倾。\n岂无山歌与村笛，呕哑嘲哳难为听。\n今夜闻君琵琶语，如听仙乐耳暂明。\n莫辞更坐弹一曲，为君翻作《琵琶行》。\n感我此言良久立，却坐促弦弦转急。\n凄凄不似向前声，满座重闻皆掩泣。\n座中泣下谁最多？江州司马青衫湿。'},
    {t:'罴说',a:'柳宗元〔唐代〕',c:'鹿畏貙，貙畏虎，虎畏罴。罴之状，被发人立，绝有力而甚害人焉。\n楚之南有猎者，能吹竹为百兽之音。寂寂持弓矢罂火，而即之山。为鹿鸣以感其类，伺其至，发火而射之。貙闻其鹿也，趋而至。其人恐，因为虎而骇之。貙走而虎至，愈恐，则又为罴，虎亦亡去。罴闻而求其类，至则人也，捽搏挽裂而食之。\n今夫不善内而恃外者，未有不为罴之食也。'},
    {t:'鼙鼓行',a:'韦应物〔唐代〕',c:'淮海生云暮惨澹，广陵城头鼙鼓暗，寒声坎坎风动边。\n忽似孤城万里绝，四望无人烟。又如虏骑截辽水，\n胡马不食仰朔天。座中亦有燕赵士，闻鼙不语客心死。\n何况鳏孤火绝无晨炊，独妇夜泣官有期。'},
    {t:'辟阳城',a:'高适〔唐代〕',c:'荒城在高岸，凌眺俯清淇。传道汉天子，而封审食其。\n奸淫且不戮，茅土孰云宜。何得英雄主，返令儿女欺。\n母仪良已失，臣节岂如斯。太息一朝事，乃令人所嗤。'},
    {t:'贫交行',a:'杜甫〔唐代〕',c:'翻手作云覆手雨，纷纷轻薄何须数。\n君不见管鲍贫时交，此道今人弃如土。'},
    {t:'贫女词寄从叔先辈简',a:'孟郊〔唐代〕',c:'蚕女非不勤，今年独无春。二月冰雪深，死尽万木身。\n时令自逆行，造化岂不仁。仰企碧霞仙，高控沧海云。\n永别劳苦场，飘飖游无垠。'},
    {t:'品令·茶词',a:'黄庭坚〔宋代〕',c:'凤舞团团饼。恨分破、教孤令。金响体净，只轮慢碾，玉尘光莹。汤响松风，早减了、二分酒病。\n味浓香永。醉乡路、成佳境。恰如灯下，故人万里，归来对影。口不能言，心下快活自省。'},
    {t:'品令·掉又惧',a:'秦观〔宋代〕',c:'掉又惧。天然个品格。于中压一。帘儿下时把鞋儿踢。语低低、笑咭咭。\n每每秦楼相见，见了无限怜惜。人前强不欲相沾识。把不定、脸儿赤。'},
    {t:'品令·商调梅花',a:'周邦彦〔宋代〕',c:'夜阑人静。月痕寄、梅梢疏影。帘外曲角栏干近。旧携手处，花发雾寒成阵。\n应是不禁愁与恨。纵相逢难问。黛眉曾把春衫印。后期无定。断肠香销尽。'},
    {t:'品令·幸自得',a:'秦观〔宋代〕',c:'幸自得。一分索强，教人难吃。好好地恶了十来日。恰而今、较些不。\n须管啜持教笑，又也何须肐织。衠倚赖脸儿得人惜。放软顽、道不得。'},
    {t:'平城下',a:'李贺〔唐代〕',c:'饥寒平城下，夜夜守明月。别剑无玉花，海风断鬓发。\n塞长连白空，遥见汉旗红。青帐吹短笛，烟雾湿昼龙。\n日晚在城上，依稀望城下。风吹枯蓬起，城中嘶瘦马。\n借问筑城吏，去关几千里。惟愁裹尸归，不惜倒戈死。'},
    {t:'平江府',a:'文天祥〔宋代〕',c:'楼台俯舟楫，城郭满干戈。\n故吏归心少，遗民出涕多。\n鸠居无鹊在，鱼网有鸿过。\n使遂睢阳志，安危今若何。'},
    {t:'平陵东',a:'佚名〔两汉〕',c:'平陵东，松柏桐，不知何人刦义钱。\n劫义钱，在高堂下，交钱百万两走马。\n两走马，亦诚难，顾见追吏心中恻。\n心中恻，血出漉，归告我家卖黄犊。'},
    {t:'平山堂',a:'王安石〔宋代〕',c:'城北横冈走翠虬，一堂高视两三州。\n淮岑日对朱栏出，江岫云齐碧瓦浮。\n墟落耕桑公恺悌，杯觞谈笑客风流。\n不知岘首登临处，壮观当时有此不。'},
    {t:'平台夜遇李景参有别',a:'高适〔唐代〕',c:'离心忽怅然，策马对秋天。孟诸薄暮凉风起，\n归客相逢渡睢水。昨时携手已十年，今日分途各千里。\n岁物萧条满路歧，此行浩荡令人悲。家贫羡尔有微禄，\n欲往从之何所之。'},
    {t:'凭李忠州寄书乐天',a:'元稹〔唐代〕',c:'万里寄书将出峡，却凭巫峡寄江州。\n伤心最是江头月，莫把书将上庾楼。'},
    {t:'凭周况先辈于朝贤乞茶',a:'孟郊〔唐代〕',c:'道意勿乏味，心绪病无悰。蒙茗玉花尽，越瓯荷叶空。\n锦水有鲜色，蜀山饶芳丛。云根才翦绿，印缝已霏红。\n曾向贵人得，最将诗叟同。幸为乞寄来，救此病劣躬。'},
    {t:'屏风',a:'李商隐〔唐代〕',c:'六曲连环接翠帷，高楼半夜酒醒时。\n掩灯遮雾密如此，雨落月明俱不知。'},
    {t:'屏风绝句',a:'杜牧〔唐代〕',c:'屏风周昉画纤腰，岁久丹青色半销。\n斜倚玉窗鸾发女，拂尘犹自妒娇娆。'},
    {t:'屏风曲',a:'李贺〔唐代〕',c:'蝶栖石竹银交关，水凝绿鸭琉上钱。团回六曲抱膏兰，\n将鬟镜上掷金蝉。沉香火暖茱萸烟，酒觥绾带新承欢。\n月风吹露屏外寒，城上乌啼楚女眠。'},
    {t:'泊船瓜洲',a:'王安石〔宋代〕',c:'京口瓜洲一水间，钟山只隔数重山。\n春风又绿江南岸，明月何时照我还。'},
    {t:'泊平江百花洲',a:'杨万里〔宋代〕',c:'吴中好处是苏州，却为王程得胜游。\n半世三江五湖棹，十年四泊百花洲。\n岸傍杨柳都相识，眼底云山苦见留。\n莫怨孤舟无定处，此身自是一孤舟。'},
    {t:'泊秦淮',a:'杜牧〔唐代〕',c:'烟笼寒水月笼沙，夜泊秦淮近酒家。\n商女不知亡国恨，隔江犹唱后庭花。'},
    {t:'泊岳阳城下',a:'杜甫〔唐代〕',c:'江国逾千里，山城仅百层。\n岸风翻夕浪，舟雪洒寒灯。\n留滞才难尽，艰危气益增。\n图南未可料，变化有鲲鹏。'},
    {t:'泊舟无锡雨止遂游惠山',a:'杨万里〔宋代〕',c:'天教老子不空回，船泊山根雨顿开。\n归去江西人问我，也曾一到惠山来。'},
    {t:'婆罗门令·昨宵里恁和衣睡',a:'柳永〔宋代〕',c:'昨宵里恁醉衣睡，今宵里又恁醉衣睡。小饮归来，初更过，醺醺醉。中夜后、何事还惊起？霜天冷，床细细，触疏窗、闪闪灯摇曳。\n空床展转重追想，云雨梦、任攲枕难继。寸心万绪，咫尺千里。好景良天，彼此，空有相怜意，未有相怜计。'},
    {t:'破镜',a:'杜牧〔唐代〕',c:'佳人失手镜初分，何日团圆再会君。\n今朝万里秋风起，山北山南一片云。'},
    {t:'破阵乐·露花倒影',a:'柳永〔宋代〕',c:'露花倒影，烟芜蘸碧，灵沼波暖。金柳摇风树树，系彩舫龙舟遥岸。千步虹桥，参差雁齿，直趋水殿。绕金堤、曼衍鱼龙戏，簇娇春罗绮，喧天丝管。霁色荣光，望中似睹，蓬莱清浅。\n时见。凤辇宸游，鸾觞禊饮，临翠水、开镐宴。两两轻舠飞画楫，竞夺锦标霞烂。罄欢娱，歌鱼藻，徘徊宛转。别有盈盈游女，各委明珠，争收翠羽，相将归远。渐觉云海沈沈，洞天日晚。'},
    {t:'破阵子·春景',a:'晏殊〔宋代〕',c:'燕子来时新社，梨花落后清明。池上碧苔三四点，叶底黄鹂一两声。日长飞絮轻。\n巧笑东邻女伴，采桑径里逢迎。疑怪昨宵春梦好，元是今朝斗草赢。笑从双脸生。'},
    {t:'破阵子·海上蟠桃易熟',a:'晏殊〔宋代〕',c:'海上蟠桃易熟，人间好月长圆。面有擘钗分钿侣，离别常多会面难。此情须问天。\n蜡烛到明垂泪，熏炉尽日生烟。一点凄凉愁绝意，谩道秦筝有剩弦。何曾为细传。'},
    {t:'破阵子·湖上西风斜日',a:'晏殊〔宋代〕',c:'湖上西风斜日，荷花落尽红英。金菊满丛珠颗细，海燕辞巢翅羽轻。年年岁岁情。\n美酒一杯新熟，高歌数阕堪听。不向尊前同一醉，可奈光阴似水声。迢迢去未停。'},
    {t:'破阵子·看破空花尘世',a:'陆游〔宋代〕',c:'看破空花尘世，放轻昨梦浮名。蜡屐登山真率饮，筇杖穿林自在行。身闲心太平。\n料峭余寒犹力，廉纤细雨初晴。苔纸闲题溪上句，菱唱遥闻烟外声。与君同醉醒。'},
    {t:'破阵子·柳下笙歌庭院',a:'晏几道〔宋代〕',c:'柳下笙歌庭院，花间姊妹秋千。月得春楼当日事，写向红窗夜月前。凭谁寄小莲。\n绛蜡等闲陪泪，吴蚕到了缠绵。绿鬓能供多少恨，未肯无情比断弦。今年老去年。'},
    {t:'破阵子·仕至千钟良易',a:'陆游〔宋代〕',c:'仕至千钟良易，年过七十常稀。自底荣华元是梦，身后声名不自知。营营端为谁。\n幸有旗亭沽酒，何妨茧纸题诗。幽谷云萝朝采药，静院轩窗夕对棋。不归真个痴。'},
    {t:'破阵子·为陈同甫赋壮词以寄之',a:'辛弃疾〔宋代〕',c:'醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。\n马作的卢飞快，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生！'},
    {t:'破阵子·燕子欲归时节',a:'晏殊〔宋代〕',c:'燕子欲归时节，高楼昨夜西风。求得人间成小会，试把金尊傍菊丛。歌长粉面红。\n斜日更穿帘幕，微凉渐入梧桐。多少襟情言不尽，写向蛮笺曲调中。此情千万重。'},
    {t:'破阵子·忆得去年今日',a:'晏殊〔宋代〕',c:'忆得去年今日，黄花已满东篱。曾与玉人临小槛，共折香英泛酒卮。长条插鬓垂。\n人貌不应迁换，珍丛又睹芳菲。重把一尊寻旧径，所惜光阴去似飞。风飘露冷时。'},
    {t:'破阵子·赠行',a:'辛弃疾〔宋代〕',c:'少日春风满眼，而今秋叶辞柯。便好消磨心下事，莫忆寻常醉后歌。可怜白发多。\n明日扶头颠倒，倩谁伴舞婆娑。我定思君拼瘦损，君不思兮可奈何。天寒将息呵。'},
    {t:'破阵子·掷地刘郎玉斗',a:'辛弃疾〔宋代〕',c:'为范南伯寿。时南伯为张南轩辟宰泸溪，南伯迟迟未行。因作此词以勉之。\n掷地刘郎玉斗，挂帆西子扁舟。千古风流今在此，万里功名莫放休。君王三百州。\n燕雀岂知鸿鹄，貂蝉元出兜鍪。却笑泸溪如斗大，肯把牛刀试手不？寿君双玉瓯。'},
    {t:'扑蝴蝶',a:'晏几道〔宋代〕',c:'风梢雨叶，绿遍江南岸。思归倦客，寻芳来最晚。酒边红日初长，陌上飞花正满。凄凉数声弦管。怨春短。\n玉人应在，明月楼中画眉懒。鱼笺锦字，多时音信断。恨如去水空长，事与行云渐远。罗衾旧香馀暖。'},
    {t:'菩萨蛮',a:'晏几道〔宋代〕',c:'江南未雪梅花白。忆梅人是江南客。犹记旧相逢。淡烟微月中。\n玉容长有信。一笑归来近。忆远上楼时。晚云和雁低。'},
    {t:'菩萨蛮',a:'晏几道〔宋代〕',c:'香莲烛下匀丹雪。妆成笑弄金阶月。娇面胜芙蓉。脸边天与红。\n玳筵双揭鼓。唤上花茵舞。春浅未禁寒。暗嫌罗袖宽。'},
    {t:'菩萨蛮·哀筝一弄湘江曲',a:'晏几道〔宋代〕',c:'哀筝一弄湘江曲，声声写尽湘波绿。纤指十三弦，细将幽恨传。\n当筵秋水慢，玉柱斜飞雁。弹到断肠时，春山眉黛低。'},
    {t:'菩萨蛮·白日惊飚冬已半',a:'纳兰性德〔清代〕',c:'惊飙掠地冬将半，解鞍正值昏鸦乱。冰合大河流，茫茫一片愁。\n烧痕空极望，鼓角高城上。明日近长安，客心愁未阑。'},
    {t:'菩萨蛮·半烟半雨溪桥畔',a:'黄庭坚〔宋代〕',c:'王荆公新筑草堂于半山，引八为德水作小港，其上垒石作桥，为集句云：“数间茅屋闲临水，窄开短帽垂杨里。花是去年红，吹开一夜风。梢梢新月偃，午醉醒来晚。何物最关情，黄鹂三两声。”戏效荆公作。\n半烟半雨溪桥畔，渔翁醉着无人唤。疏懒意何长，春风花草香。\n江山如有待，此意陶潜解。问我去何之，君行到自知。'},
    {t:'菩萨蛮·宝函钿雀金鸂鶒',a:'温庭筠〔唐代〕',c:'宝函钿雀金鸂鶒，沉香阁上吴画碧。杨柳又如丝，驿桥春雨时。\n画楼音信断，芳草江南岸。鸾镜与花枝，此情谁得知？'},
    {t:'菩萨蛮·宝函钿雀金鹦鹏',a:'温庭筠〔唐代〕',c:'宝函钿雀金鹦鹏，\n沉香阍上吴画碧。\n杨柳又如丝，\n驿桥春雨时。\n画楼音信断，\n芳草江南岸。\n鸾镜与花枝，\n此情谁得知。'},
    {t:'菩萨蛮·呈秀野',a:'朱熹〔宋代〕',c:'晚红飞尽春寒浅，浅寒春尽飞红晚。尊酒绿阴繁，繁阴绿酒尊。\n老仙诗句好，好句诗仙老。长恨送年芳，芳年送恨长。'},
    {t:'菩萨蛮·虫声泣露惊秋枕',a:'秦观〔宋代〕',c:'虫声泣露惊秋枕，罗帏泪湿鸳鸯锦。独卧玉肌凉，残更与恨长。\n阴风翻翠幔，雨涩灯花暗。毕竟不成眠，鸦啼金井寒。'},
    {t:'菩萨蛮·窗前桃蕊娇如倦',a:'纳兰性德〔清代〕',c:'窗前桃蕊娇如倦，东风泪洗胭脂面。人在小红楼，离情唱《石州》。\n夜来双燕宿，灯背屏腰绿。香尽雨阑珊，薄衾寒不寒。'},
    {t:'菩萨蛮·春风未放花心吐',a:'晏几道〔宋代〕',c:'春风未放花心吐，\n尊前不拟分明语。\n酒色上来迟，\n绿须红杏枝。\n今朝眉黛浅，\n暗恨归时远。\n前夜月当楼，\n相逢南陌头。'},
    {t:'菩萨蛮·春花春月年年客',a:'纳兰性德〔清代〕',c:'春花春月年年客，怜春又怕春离别。只为晓风愁，催花扑玉钩。\n娟娟双蛱蝶，宛转飞花侧。花底一声歌，疼花花奈何。'},
    {t:'菩萨蛮·春云吹散湘帘雨',a:'纳兰性德〔清代〕',c:'春云吹散湘帘雨，絮黏蝴蝶飞还住。人在玉楼中，楼高四面风。\n柳烟丝一把，暝色笼鸳瓦。休近小阑干，夕阳无限山。'},
    {t:'菩萨蛮·次圭父回文韵',a:'朱熹〔宋代〕',c:'暮江寒碧萦长路。路长萦碧寒江暮。花坞夕阳斜。斜阳夕坞花。\n客愁无胜集。集胜无愁客。醒似醉多情。情多醉似醒。'},
    {t:'菩萨蛮·催花未歇花奴鼓',a:'纳兰性德〔清代〕',c:'催花未歇花奴鼓，酒醒已见残红舞。不忍覆馀觞，临风泪数行。\n粉香看又别，空剩当时月。月也异当时，凄清照鬓丝。'},
    {t:'菩萨蛮·翠翘金缕双□□',a:'温庭筠〔唐代〕',c:'翠翘金缕双□□，\n水纹细起春池碧。\n池上海棠梨，\n雨晴花满枝。\n绣衫遮笑靥。\n烟草黏飞蝶。\n青琐对芳菲，\n玉关音信稀。?'},
    {t:'菩萨蛮·翠翘金缕双鸂鶒',a:'温庭筠〔唐代〕',c:'翠翘金缕双鸂鶒，水纹细起春绣碧。绣上海棠梨，雨晴红满枝。\n绣衫遮笑靥，烟草粘飞蝶。青琐对芳菲，玉关音信稀。'},
    {t:'菩萨蛮·芳莲九蕊开新艳',a:'晏殊〔宋代〕',c:'芳莲九蕊开新艳。轻红淡白匀看脸。一朵近华堂。学人宫样妆。\n看时斟美酒。共祝千年寿。销得曲中夸。世间无此花。'},
    {t:'菩萨蛮·霏霏点点回塘雨',a:'佚名〔五代〕',c:'霏霏点点回塘雨，双双只只鸳盈语。灼灼野花香，依依金柳黄。\n盈盈江上女，两两溪边舞。皎皎绮罗光，轻轻云粉妆。'},
    {t:'菩萨蛮·凤凰相对盘金缕',a:'温庭筠〔唐代〕',c:'凤凰相对盘金缕，牡丹一夜经微雨。明镜照新妆，鬓轻双脸长。\n画楼相望久，栏外垂丝柳。音信不归来，社前双燕回。'},
    {t:'菩萨蛮·高梧叶下秋光晚',a:'晏殊〔宋代〕',c:'高梧叶下秋光晚。珍丛化出黄人盏。还似去年时。傍阑三两枝。\n人情须耐久。花面长依旧。莫学蜜蜂儿。等闲悠扬飞。'},
    {t:'菩萨蛮·隔花才歇廉纤雨',a:'纳兰性德〔清代〕',c:'隔花才歇廉纤雨，一声弹指混无语。梁燕自双归，长条脉脉垂。\n小屏山色远，妆薄铅华浅。独自立瑶阶，透寒金缕鞋。'},
    {t:'菩萨蛮·个人轻似低飞燕',a:'晏几道〔宋代〕',c:'个人轻似低飞燕，\n春来绮陌时长见。\n堪恨两横波，\n恼人情绪多。\n长留青鬓住，\n莫放红颜去。\n占取艳阳天，\n且教伊少年。'},
    {t:'菩萨蛮·过张见阳山居赋赠',a:'纳兰性德〔清代〕',c:'车尘马迹纷如织，羡君筑处真幽僻。柿叶一林红，萧萧四面风。\n功名应看镜，明月秋河影。安得此山间，与君高卧闲。'},
    {t:'菩萨蛮·海棠乱发皆临水',a:'王安石〔宋代〕',c:'海棠乱发皆临水。君知此处花何似。凉月白纷纷。香风隔岸闻。啭枝黄鸟近。隔岸声相应。随意坐莓苔。飘零酒一杯。'},
    {t:'菩萨蛮·荒鸡再咽天难晓',a:'纳兰性德〔清代〕',c:'荒鸡再咽天难晓，星榆落尽秋将老。毡幕绕牛羊，敲冰饮酪浆。\n山程兼水宿，漏点清钲续。正是梦回时，拥衾无限思。'},
    {t:'菩萨蛮·黄云紫塞三千里',a:'纳兰性德〔清代〕',c:'黄云紫塞三千里，女墙西畔啼乌起。落日万山寒，萧萧猎马还。\n笳声听不得，入夜空城黑。秋梦不归家，残灯落碎花。'},
    {t:'菩萨蛮·回文',a:'苏轼〔宋代〕',c:'峤南江浅红梅小，小梅红浅江南峤。窥我向疏篱，篱疏向我窥。\n老人行即到，到即行人老。离别惜残枝，枝残惜别离。'},
    {t:'菩萨蛮·回文冬闺怨',a:'苏轼〔宋代〕',c:'雪别飞暖融香颊。颊香融暖飞别雪。欺雪任单衣。衣单任雪欺。\n别时梅子结。结子梅时别。归不恨开迟。迟开恨不归。'},
    {t:'菩萨蛮·回文秋闺怨',a:'苏轼〔宋代〕',c:'井影双照新妆冷，冷妆新照双影井。羞对井花愁，愁花井对羞。\n影孤怜夜永，永夜怜孤影。楼上不宜秋，秋宜不上楼。'},
    {t:'菩萨蛮·回文夏闺怨',a:'苏轼〔宋代〕',c:'柳手风静人眠昼，昼眠人静风手柳。香汗薄衫凉，凉衫薄汗香。\n手红冰碗藕，藕碗冰红手。郎笑藕丝长，长丝藕笑郎。'},
    {t:'菩萨蛮·寄梁汾苕中',a:'纳兰性德〔清代〕',c:'知君此际情萧索，黄芦苦竹孤柁泊。烟白酒旗青，水村鱼市晴。\n柁楼今夕梦，脉脉春寒送。直过画眉桥，钱塘江上潮。'},
    {t:'菩萨蛮·金陵赏心亭为叶丞相赋',a:'辛弃疾〔宋代〕',c:'青山欲共高人语。联翩万马来无数。烟雨却低回。望来终不来。\n人言头上发。总向愁中白。拍手笑沙鸥。一身都是愁。'},
    {t:'菩萨蛮·晶帘一片伤心白',a:'纳兰性德〔清代〕',c:'晶帘一片伤心白，云鬟香雾成遥隔。无语问添衣，桐阴月已西。\n西风鸣络纬，不许愁人睡。只是去年秋，如何泪欲流。'},
    {t:'菩萨蛮·来时杨柳东桥路',a:'晏几道〔宋代〕',c:'来时杨柳东桥路，\n曲中暗有相期处。\n明月好因缘，\n欲圆还未圆。\n却寻芳草去，\n画扇遮微雨。\n飞絮莫无情，\n闲花应笑人。'},
    {t:'菩萨蛮·阑风伏雨催寒食',a:'纳兰性德〔清代〕',c:'阑风伏雨催寒食，樱桃一夜花狼藉。刚与病相宜，锁窗薰绣衣。\n画眉烦女伴，央及流莺唤。半晌试开奁，娇多直自嫌。'},
    {t:'菩萨蛮·鸾啼似作留春语',a:'晏几道〔宋代〕',c:'鸾啼似作留春语，\n花飞斗学回风舞。\n红日又平西，\n画帘遮燕泥。\n烟光还自老，\n绿镜人空好。\n香在去年衣，\n鱼笺音信稀。'},
    {t:'菩萨蛮·满宫明月梨花白',a:'温庭筠〔唐代〕',c:'满宫明月梨花白，故人万里关山隔。金雁一双飞，泪痕沾绣衣。\n小园芳草绿，家住越溪曲。杨柳色依依，燕归君不归。'},
    {t:'菩萨蛮·梅雪',a:'周邦彦〔宋代〕',c:'银河宛转三千曲。浴凫飞鹭澄天绿。何处是归舟。夕阳江上楼。\n天憎梅浪发。故下封枝雪。深院卷帘看。应怜江上寒。'},
    {t:'菩萨蛮·牡丹含露真珠颗',a:'佚名〔唐代〕',c:'牡丹含露真珠颗，美人折向庭前过。含笑问檀郎，花强妾貌强？\n檀郎故相恼，须道花枝好。一向发娇嗔，碎挼花打人。'},
    {t:'菩萨蛮·牡丹花谢莺声歇',a:'温庭筠〔唐代〕',c:'牡丹花谢莺声歇，绿杨满院中翠月。相忆梦难成，背窗灯半明。\n翠钿金压脸，寂寞香闺掩。人远泪阑干，燕飞春又残。'},
    {t:'菩萨蛮·南园满地堆轻絮',a:'温庭筠〔唐代〕',c:'南园满地堆轻絮，愁闻一霎清无雨。雨后却斜阳，杏花零落香。\n无言匀睡脸，枕上屏山掩。时节欲黄昏，无憀独倚门。'},
    {t:'菩萨蛮·飘蓬只逐惊飙转',a:'纳兰性德〔清代〕',c:'飘蓬只逐惊飙转，行人过尽烟光远。立马认河流，茂陵风雨秋。\n寂寥行殿索，梵呗琉璃火。塞雁与宫鸦，山深日易斜。'},
    {t:'菩萨蛮·七夕',a:'苏轼〔宋代〕',c:'风回仙驭云开扇，更阑月坠星相转。枕上梦魂惊，晓檐疏雨零。\n相逢虽草草，长共天难老。终不羡人间，人间日似年。'},
    {t:'菩萨蛮·秋花最是黄葵好',a:'晏殊〔宋代〕',c:'晓花最是黄葵好。天然嫩态迎晓早。染得道家衣。淡妆梳洗时。\n晓来清露滴。一一金杯侧。插向绿云鬓。便随王母仙。'},
    {t:'菩萨蛮·人人尽道黄葵淡',a:'晏殊〔宋代〕',c:'人人尽道黄摘淡。侬家解说黄摘艳。可喜万般宜。不劳朱粉施。\n摘承金盏酒。劝我千长寿。擎作女真冠。试伊娇面看。'},
    {t:'菩萨蛮·蕊黄无限当山额',a:'温庭筠〔唐代〕',c:'蕊黄无限当山额，宿妆隐笑纱翠隔。相见牡丹时，暂来还别离。\n翠钗金作股，钗上蝶双舞。心事竟谁知？月明花满枝。'},
    {t:'菩萨蛮·蕊香不恋琵琶结',a:'张炎〔宋代〕',c:'蕊香不恋琵琶结。舞衣折损藏愁蝶。春梦未堪凭。几时春梦真。愁把残更数。泪落灯前雨。歌酒可曾忺。情怀似去年。'},
    {t:'菩萨蛮·湿云不动溪桥冷',a:'苏轼〔宋代〕',c:'湿云不动溪桥冷。嫩寒初透东风影。桥下水声长。一枝和月香。\n人怜花似旧。花比人应瘦。莫凭小栏干。夜深花正寒。'},
    {t:'菩萨蛮·书江西造口壁',a:'辛弃疾〔宋代〕',c:'郁孤台下清江水，中间多少行青泪。西北望长安，可怜无数山。\n青山遮不住，毕竟东流去。江晚正愁余，山深闻鹧鸪。'},
    {t:'菩萨蛮·数间茅屋闲临水',a:'王安石〔宋代〕',c:'数间茅屋闲临水，窄衫短帽垂梢里。花是去年红，吹开一夜风。\n梢梢新月偃，午醉醒来晚。何物最关情，黄鹂三两声。'},
    {t:'菩萨蛮·水精帘里颇黎枕',a:'温庭筠〔唐代〕',c:'水精帘里颇黎枕，暖香惹梦鸳藕锦。江上柳如烟，雁飞残月天。\n藕丝秋色浅，人胜参差剪。双鬓隔香红，玉钗头上风。'},
    {t:'菩萨蛮·朔风吹散三更雪',a:'纳兰性德〔清代〕',c:'朔风吹散三更雪，倩魂犹恋桃花月。梦好莫催醒，由他好处行。\n无端听画角，枕畔红冰薄。塞马一声嘶，残星拂大旗。'},
    {t:'菩萨蛮·送曹君之庄所',a:'辛弃疾〔宋代〕',c:'人间岁月堂堂去，劝君快上青云路。圣处一灯传，工夫萤雪边。\n麴生风味恶，辜负西窗约。沙岸片帆开，寄书无雁来。'},
    {t:'菩萨蛮·为春憔悴留春住',a:'纳兰性德〔清代〕',c:'为春憔悴留春住，那禁半霎催归雨。深巷卖樱桃，雨余红更娇。\n黄昏清泪阁，忍便花飘泊。消得一声莺，东风三月情。'},
    {t:'菩萨蛮·问君何事轻离别',a:'纳兰性德〔清代〕',c:'问君何事轻离别，一年能几团圆月。杨柳乍如丝，故园春尽时。\n春归归不得，两桨松花隔。旧事逐寒潮，啼鹃恨未消。'},
    {t:'菩萨蛮·雾窗寒对遥天暮',a:'纳兰性德〔清代〕',c:'雾窗寒对遥天暮，暮天遥对寒窗雾。花落正啼鸦，鸦啼正落花。\n袖罗垂影瘦，瘦影垂罗袖。风翦一丝红，红丝一翦风。'},
    {t:'菩萨蛮·西湖',a:'苏轼〔宋代〕',c:'秋风湖上萧萧雨。使君欲去还留住。今日漫留君。明朝愁杀人。\n佳人千点泪。洒向长河水。不用敛双蛾。路人啼更多。'},
    {t:'菩萨蛮·惜春春去惊新燠',a:'纳兰性德〔清代〕',c:'惜春春去惊新燠，粉融轻汗红绵扑。妆罢只思眠，江南四月天。\n绿阴帘半揭，此景清幽绝。行度竹林风，单衫杏子红。'},
    {t:'菩萨蛮·夏景回文',a:'苏轼〔宋代〕',c:'火云凝汗挥珠颗。颗珠挥汗凝云火。琼暖碧纱轻。轻纱碧暖琼。\n晕腮嫌枕印。印枕嫌腮晕。闲照晚妆残。残妆晚照闲。'},
    {t:'菩萨蛮·相逢欲话相思苦',a:'晏几道〔宋代〕',c:'相逢欲话相思苦。浅情肯信相思否。还恐漫相思。浅情人不知。\n忆曾携手处。月满窗前路。长到月来时。不眠犹待伊。'},
    {t:'菩萨蛮·萧萧几叶风兼雨',a:'纳兰性德〔清代〕',c:'萧萧几叶风兼雨，离人偏识长更苦。欹枕数秋天，蟾蜍下早弦。\n夜寒惊被薄，泪与灯花落。无处不伤心，轻尘在玉琴。'},
    {t:'菩萨蛮·小山重叠金明灭',a:'温庭筠〔唐代〕',c:'小山重叠金明灭，鬓云欲度香腮雪。懒起画蛾眉，弄妆梳洗迟。\n照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。'},
    {t:'菩萨蛮·晓寒瘦著西南月',a:'纳兰性德〔清代〕',c:'晓寒瘦著西南月，丁丁漏箭余蜀咽。春已十分宜，东风无是非。\n蜀魂羞顾影，玉照斜红冷。谁唱《后庭花》，新年忆旧家。'},
    {t:'菩萨蛮·新寒中酒敲窗雨',a:'纳兰性德〔清代〕',c:'新寒中酒敲窗雨，残香细袅秋无绪。才道莫伤神，青衫湿一痕。\n无聊成独卧，弹指韶光过。记得别伊时，桃花柳万丝。'},
    {t:'菩萨蛮·杏花含露团香雪',a:'温庭筠〔唐代〕',c:'杏花含露团香雪，绿杨陌上多玉别。灯在月胧明，觉来闻晓莺。\n玉钩褰翠幕，妆浅旧眉薄。春梦正关情，镜中蝉鬓轻。'},
    {t:'菩萨蛮·夜来皓月才当午',a:'温庭筠〔唐代〕',c:'夜来皓月才当午，重帘悄悄无人语。深处麝烟长，卧时留薄妆。\n当年还自惜，往事那堪忆。花露月明残，锦衾知晓寒。'},
    {t:'菩萨蛮·雨晴夜合玲珑日',a:'温庭筠〔唐代〕',c:'雨晴夜合玲珑日，万枝香袅红丝拂。闲梦忆金堂，满庭萱草长。\n绣帘垂箓簌，眉黛远山绿。春水渡溪桥，凭栏魂欲销。'},
    {t:'菩萨蛮·玉楼明月长相忆',a:'温庭筠〔唐代〕',c:'玉楼明月长相忆，柳丝袅娜春画力。门外草萋萋，送君闻马嘶。\n画罗金翡翠，香烛销成泪。花落子规啼，绿窗残梦迷。'},
    {t:'菩萨蛮·玉纤弹处真珠落',a:'温庭筠〔唐代〕',c:'玉纤弹处真珠落，流多暗湿铅华薄。春露浥朝华，秋波浸晚霞。\n风流心上物，本为风流出。看取薄情人，罗衣无此痕。'},
    {t:'菩萨蛮·赠周国辅侍人',a:'辛弃疾〔宋代〕',c:'画楼影蘸清溪水。歌声响彻行云里。帘幕燕双双。绿杨低映窗。\n曲中特地误。要试周郎顾。醉里客魂消。春风大小乔。'},
    {t:'菩萨蛮·榛荆满眼山城路',a:'纳兰性德〔清代〕',c:'榛荆满眼山城路，征鸿不为愁人住。何处是长安，湿云吹雨寒。\n丝丝心欲碎，应是悲秋泪。泪向客中多，归时又奈何。'},
    {t:'菩萨蛮·枕前发尽千般愿',a:'佚名〔唐代〕',c:'枕前发尽千般愿，要休且待青山烂。水面上秤锤浮，直待黄河彻底枯。\n白日参辰现，北斗回南面。休即未能休，且待三更见日头。'},
    {t:'菩萨蛮·竹风轻动庭除冷',a:'温庭筠〔唐代〕',c:'竹风轻动庭除冷，珠帘月上玲珑影。山枕隐秾妆，绿檀金凤凰。\n两蛾愁黛浅，故国吴宫远。春恨正关情，画楼残点声。'},
    {t:'菩萨蛮其四',a:'温庭筠〔唐代〕',c:'翠翘金缕双鸂鶒，水文细起春绣碧。绣上海棠梨，雨晴红满枝。\n绣衫遮笑靥，烟草黏飞蝶。青琐对芳菲，玉关音信稀。'},
    {t:'菩萨蛮其五',a:'晏几道〔宋代〕',c:'娇香淡染胭脂雪，愁春细画弯弯月。花月镜边情，浅妆匀未成。\n佳期应有在，试倚秋千待。满地落英红，万条杨柳风。'},
    {t:'菩提寺禁口号又示裴迪',a:'王维〔唐代〕',c:'安得舍罗网，拂衣辞世喧。\n悠然策藜杖，归向桃花源。'},
    {t:'菩提寺上方晚眺',a:'白居易〔唐代〕',c:'楼阁高低树浅深，山光水色暝沉沉。\n嵩烟半卷青绡幕，伊浪平铺绿绮衾。\n飞鸟灭时宜极目，远风来处好开襟。\n谁知不离簪缨内，长得逍遥自在心。'},
    {t:'葡萄歌·一作蒲桃',a:'刘禹锡〔唐代〕',c:'野田生葡萄，缠绕一枝高。移来碧墀下，张王日日高。\n分岐浩繁缛，修蔓蟠诘曲。扬翘向庭柯，意思如有属。\n为之立长檠，布濩当轩绿。米液溉其根，理疏看渗漉。\n繁葩组绶结，悬实珠玑蹙。马乳带轻霜，龙鳞曜初旭。\n有客汾阴至，临堂瞪双目。自言我晋人，种此如种玉。\n酿之成美酒，令人饮不足。为君持一斗，往取凉州牧。'},
    {t:'浦中夜泊',a:'白居易〔唐代〕',c:'暗上江堤还独立，水风霜气夜棱棱。\n回看深浦停舟处，芦荻花中一点灯。'},
    {t:'普明寺见梅',a:'杨万里〔宋代〕',c:'城中忙失探梅期，初见僧窗一两枝。\n犹喜相看那恨晚，故应更好半开时。\n今冬不雪何关事，作伴孤芳却欠伊。\n月落山空正幽独，慰存无酒且新诗。'},
    {t:'瀑布',a:'范仲淹〔宋代〕',c:'迥与众流异，发源高更孤。\n下山犹直在，到海得清无。\n势斗蛟龙恶，声吹雨雹粗。\n晚来云一色，诗句自成图。'},
    {t:'曝日',a:'周邦彦〔宋代〕',c:'冬曦如村酿，奇温止须臾。\n行行正须此，恋恋忽已无。'},
    {t:'七拍',a:'文天祥〔宋代〕',c:'忆昔十五心尚孩，莫怪频频劝酒杯。\n孤城此日肠堪断，如何不饮令人哀。\n一去紫台连朔漠，月出云通雪山白。\n九度附书归洛阳，故国三年一消息。'},
    {t:'七夕',a:'晏殊〔宋代〕',c:'百子池深涨绿苔，九光灯迥绿浮埃。\n天孙实驾何年驻，阿母飚轮此夜来。\n空外粉筵和露湿，静中珠幌彻明开。\n秋河不断长相望，岂独人间事可哀。'},
    {t:'七夕',a:'温庭筠〔唐代〕',c:'鹊归燕去两悠悠，青琐西南月似钩。\n天上岁时星右转，世间离别水东流。\n金风入树千门夜，银汉横空万象秋。\n苏小横塘通桂楫，未应清浅隔牵牛。'},
    {t:'七夕',a:'李贺〔唐代〕',c:'别浦今朝暗，罗帷午夜愁。\n鹊辞穿线月，花入曝衣楼。\n天上分金镜，人间望玉钩。\n钱塘苏小小，更值一年秋。'},
    {t:'七夕',a:'文天祥〔宋代〕',c:'大地风尘恶，长天岁月奔。\n忧来浑是感，梦破与谁言。\n缑鹤空回首，河牛暗断魂。\n吾今拙又拙，无复问天孙。'},
    {t:'七夕',a:'韦应物〔唐代〕',c:'人世拘形迹，别去间山川。岂意灵仙偶，相望亦弥年。\n夕衣清露湿，晨驾秋风前。临欢定不住，当为何所牵。'},
    {t:'七夕',a:'李商隐〔唐代〕',c:'鸾扇斜分凤幄开，星桥横过鹊飞回。\n争将世上无期别，换得年年一度来。'},
    {t:'七夕',a:'白居易〔唐代〕',c:'烟霄微月澹长空，银汉秋期万古同。\n几许欢情与离恨，年年并在此宵中。'},
    {t:'七夕',a:'晏殊〔宋代〕',c:'云幕无多斗柄移，鹊慵乌慢得桥迟。\n若教精卫填河汉，一水还应有尽时。'},
    {t:'七夕',a:'杜牧〔唐代〕',c:'云阶月地一相过，未抵经年别恨多。\n最恨明朝洗车雨，不教回脚渡天河。'},
    {t:'七夕',a:'晏几道〔宋代〕',c:'云幕无波斗柄移，鹊慵乌慢得桥迟。若教精卫填河汉，一水还应有尽时。'},
    {t:'七夕偶题',a:'李商隐〔唐代〕',c:'宝婺摇珠佩，常娥照玉轮。\n灵归天上匹，巧遗世间人。\n花果香千户，笙竽滥四邻。\n明朝晒犊鼻，方信阮家贫。'},
    {t:'七月二十九日崇让宅宴作',a:'李商隐〔唐代〕',c:'露如微霰下前池，风过回塘万竹悲。\n浮世本来多聚散，红蕖何事亦离披？\n悠扬归梦惟灯见，濩落生涯独酒知。\n岂到白头长只尔，嵩阳松雪有心期。'},
    {t:'七月十九日大风雨雷电',a:'陆游〔宋代〕',c:'雷车动地电火明，急雨遂作盆盎倾。\n强弩夹射马陵道，屋瓦大震昆阳城。\n岂独鱼虾空际落，真成盖屐舍中行。\n明朝雨止寻幽梦，尚听飞涛溅瀑声。'},
    {t:'七月十一夜月下独酌',a:'杨万里〔宋代〕',c:'今岁秋阳晒霜死，今宵秋月呼霜起。\n月光如水澡吾体，月色如霜冻吾髓。\n老夫畏热如於菟，平孤爱月如冰壶。\n望舒可客不可孤，麴孤可亲不可疏。\n更招玉兔金蟾蜍，同酌山杯煮涧蔬。\n来朝秋阳再作恶，今夕秋光且行乐，\n遮莫参横并月落。'},
    {t:'七月一日晓入太行山',a:'李贺〔唐代〕',c:'一夕绕山秋，香露溘蒙菉。新桥倚云阪，候虫嘶露朴。\n洛南今已远，越衾谁为熟。石气何凄凄，老莎如短镞。'},
    {t:'七字谢绍兴帅丘宗卿惠杨梅二首',a:'杨万里〔宋代〕',c:'梅出稽山世少双，情知风味胜他杨。\n玉肌半醉红生粟，墨晕微深染紫裳。\n火齐堆盘珠径寸，醴泉绕齿柘为浆。\n故人解寄吾家果，未变蓬莱阁下香。'},
    {t:'妻子第一百四十七',a:'文天祥〔宋代〕',c:'世乱遭飘荡，飞藿共徘徊。\n十口隔风雪，反畏消息来。'},
    {t:'凄凉犯·北游道中寄怀',a:'张炎〔宋代〕',c:'萧疏野柳嘶寒马，芦花深、还见飞猎。山势北来，甚时曾到，醉魂飞越。酸风自咽。拥吟鼻、征衣暗雪。正凄迷，天涯羁旅，不似灞桥雪。\n谁念而今老，懒赋长杨，倦怀休说。空怜断梗梦依依，岁华轻别。待击歌壶，怕如意、和冰冻折。且行行，平沙万里尽是月。'},
    {t:'凄凉犯·西风暗翦荷衣碎',a:'张炎〔宋代〕',c:'西风暗翦荷衣碎，柔丝不解重碧。荒烟断浦，晴晖历乱，半山摇碧。悠悠望极。忍独听、秋声渐急。老怜他、萧条柳发，相与动秋色。老态今如此，犹自留连，醉筇游屐。不堪瘦影，渺天涯、尽成行客。因甚忘归，谩吹裂、山阳夜笛。梦三十六陂流水，去未得。'},
    {t:'萋兮吟',a:'刘禹锡〔唐代〕',c:'天涯浮云生，争蔽日月光。\n穷巷亭风起，先摧兰蕙芳。\n万货列旗亭，恣心注明珰。\n名高毁所集，言巧智难防。\n勿谓行大道，斯须成太行。\n莫吟萋兮什，徒使君子伤。'},
    {t:'漆园',a:'王维〔唐代〕',c:'古人非傲吏，自阙经世务。\n偶寄一微官，婆娑数株树。'},
    {t:'齐安郡后池绝句',a:'杜牧〔唐代〕',c:'菱透浮萍绿锦池，夏莺千啭弄蔷薇。\n尽日无人看微雨，鸳鸯相对浴红衣。'},
    {t:'齐安郡晚秋',a:'杜牧〔唐代〕',c:'柳岸风来影渐疏，使君家似野人居。\n云容水态还堪赏，啸志歌怀亦自如。\n雨暗残灯棋散后，酒醒孤枕雁来初。\n可怜赤壁争雄渡，唯有蓑翁坐钓鱼。'},
    {t:'齐安郡中偶题二首·其二',a:'杜牧〔唐代〕',c:'秋声无不搅离心，梦泽蒹葭楚雨深。\n自滴阶前大梧叶，干君何事动哀吟。'},
    {t:'齐安郡中偶题二首·其一',a:'杜牧〔唐代〕',c:'两竿落日溪桥上，半缕轻烟柳影中。\n多少绿荷相倚恨，一时回首背西风。'},
    {t:'齐宫',a:'温庭筠〔唐代〕',c:'白马杂金饰，言从雕辇回。粉香随笑度，鬓态伴愁来。\n远水斜如剪，青莎绿似裁。所恨章华日，冉冉下层台。'},
    {t:'齐宫词',a:'李商隐〔唐代〕',c:'永寿兵来夜不扃，金莲无复印中庭。\n梁台歌管三更罢，犹自风摇九子铃。'},
    {t:'齐明堂乐歌十五首其九青帝歌',a:'佚名〔隋代〕',c:'参映夕，驷昭晨。灵乘震，司青春。雁将向，桐始蕤。和风舞，暄光迟。\n萌动达，万品亲。润无际，泽无垠。'},
    {t:'齐天乐',a:'张炎〔宋代〕',c:'扁舟忽过芦花浦。闲情便随鸥去。水国吹箫，虹桥问月，西子如今何许。危栏谩抚。正独立苍茫，半空飞露。倒影虚明，洞庭波映广寒府。\n鱼龙吹浪自舞。渺然凌万顷，如听风雨。夜气浮山，晴晖荡日，一色无寻秋处。惊凫自语。尚记得当时，故人来否。胜景平分，此心游太古。'},
    {t:'齐天乐·甲戌湘宪种德堂灯屏',a:'文天祥〔宋代〕',c:'夜来早得东风信，潇湘一川新绿，柳色含晴，梅心沁暖，春浅千花如束。银蝉乍浴。正沙雁将还，海鳌初矗。云拥旌旗，笑声人在画阑曲。\n星虹瑶树缥缈，佩环鸣碧落，瑞笼华屋。露耿铜虬，冰翻铁马，帘幕光摇金粟。迟迟倚竹。更为把瑶尊，满斟醽醁。回首宫莲，夜深归院烛。'},
    {t:'齐天乐·庆湖北漕知鄂州李楼峰',a:'文天祥〔宋代〕',c:'南楼月转银河曙，玉箫又吹梅早。鹦鹉沙晴，葡萄水暖，一缕燕香清袅。瑶池春透。想桃露霏霞，菊波沁晓。袍锦风流，御仙花带瑞虹绕。\n玉关人下未老。唤矶头黄鹤，岸巾谈笑。剑拂准清，槊横楚黛，雨洗一川烟草。印黄似斗。看半砚蔷薇，满鞍杨柳。沙路归来，金貂蝉翼小。'},
    {t:'齐天乐·秋思',a:'周邦彦〔宋代〕',c:'绿芜凋尽台城路，殊乡又逢秋晚。暮雨生寒，鸣蛩劝织，深阁时闻裁剪。云窗静掩。叹重拂罗裀，顿疏花簟。尚有綀囊，露萤清夜照书卷。\n荆江留滞最久，故人相望处，离思何限。渭水西风，长安乱叶，空忆诗情宛转，凭高眺远。正玉液新篘，蟹螯初荐。醉倒山翁，但愁斜照敛。'},
    {t:'齐天乐·上元',a:'纳兰性德〔清代〕',c:'阑珊火树鱼龙舞，望中宝钗楼远。鞣鞠余红，琉璃剩碧，待属花归缓缓。寒轻漏浅。正乍敛烟霏，陨星如箭。旧事惊心，一双莲影藕丝断。\n莫恨流年似水，恨消残蝶粉，韶光忒浅。细语吹香，暗尘笼撰，都逐晓风零乱。阑干敲遍。问帘底纤纤，甚时重见？不解相思，月华今夜满。'},
    {t:'齐州送祖二',a:'王维〔唐代〕',c:'送君南浦泪如丝，君向东州使我悲。\n为报故人憔悴尽，如今不似洛阳时。'},
    {t:'齐州送祖三',a:'王维〔唐代〕',c:'相逢方一笑，相送还成泣。\n祖帐已伤离，荒城复愁入。\n天寒远山净，日暮长河急。\n解缆君已遥，望君犹伫立。'},
    {t:'祁四再赴江南别诗',a:'岑参〔唐代〕',c:'万里来又去，三湘东复西。别多人换鬓，行远马穿蹄。\n山驿秋云冷，江帆暮雨低。怜君不解说，相忆在书题。'},
    {t:'跂乌词',a:'柳宗元〔唐代〕',c:'城上日出群乌飞，鸦鸦争赴朝魄枝。\n刷毛伸羽和且乐，尔独落魄今为何？\n无乃慕高近白日，三旁妒尔令尔疾？\n无乃饥啼走路旁，贪鲜攫肉人所伤？\n翘肖独旁下丛薄，口衔低枝始能越。\n还顾泥涂备蝼蚁，仰看栋梁防燕雀。\n左右六翮利如刀，踊身失势不得高。\n支离无趾犹自免，努力低飞逃后患。'},
    {t:'淇上别刘少府子英',a:'高适〔唐代〕',c:'近来住淇上，萧条惟空林。又非我种时，闲散多自任。\n伊君独知我，驱马欲招寻。千里忽携手，十甘同苦心。\n求仁见交态，于道喜甘临。逸思乃天纵，微才应陆沉。\n飘然归故乡，不复问离襟。南登黎阳渡，莽苍寒云阴。\n桑叶原上起，河凌山下深。途穷更远别，相对益悲吟。'},
    {t:'淇上别业',a:'高适〔唐代〕',c:'依依西山下，别业桑林边。庭鸭喜多雨，邻鸡知暮天。\n野人种秋菜，古老开原田。且向世情远，吾今聊自然。'},
    {t:'淇上送韦司仓往滑台',a:'高适〔唐代〕',c:'饮酒莫辞醉，醉多适不愁。\n孰知非远别，终念对穷秋。\n滑台门外见，淇水眼前流。\n君去应回首，风波满渡头。'},
    {t:'淇上田园即事',a:'王维〔唐代〕',c:'屏居淇水上，东野旷无山。\n日隐桑柘外，河明闾井间。\n牧童望村去，猎犬随人还。\n静者亦何事，荆扉乘昼关。'},
    {t:'棋盘石',a:'晏殊〔宋代〕',c:'洞仙遗下石棋盘，人到壶天静处看。十九路谁弹黑界，几千年自带云寒。\n面平可步流星势，尘净元无旧藓瘢。乾雹声中闻子响，不知还许采樵观。'},
    {t:'棋盘石',a:'晏殊〔宋代〕',c:'尚仙遗下石棋盘，人到壶天静处看。\n十九路谁弹黑界，几千年自带云寒。\n面平可步流星势，尘净元无旧藓瘢。\n干雹声中闻子响，不知还许采樵观。'},
    {t:'乞猫',a:'黄庭坚〔宋代〕',c:'秋来鼠辈欺猫死，窥瓮翻盘搅夜眠。\n闻道狸奴将数子，买鱼穿柳聘衔蝉。'},
    {t:'乞食',a:'陶渊明〔魏晋〕',c:'饥来驱我去，不知竟何之。\n行行意斯里，叩门拙言辞。\n主人解余意，遗赠岂虚来。\n谈谐终日夕，觞意辄倾杯。\n情欣新知欢，言咏遂赋诗。\n感子漂母惠，愧我非韩才。\n衔戢知何谢，冥报以相贻。'},
    {t:'企喻歌二首',a:'佚名〔南北朝〕',c:'男儿欲作健，结伴不须多。\n鹞子经天飞，群雀两向波。\n男儿可怜虫，出门怀死忧。\n尸丧狭谷中，白骨无人收。'},
    {t:'企喻歌其二',a:'佚名〔隋代〕',c:'放马大泽中，草好马著膘。牌子铁裲裆，𨥛矛鸐尾条。'},
    {t:'企喻歌其三',a:'佚名〔隋代〕',c:'前行看后行，齐著铁裲裆。前头看后头，齐著铁𨥛矛。'},
    {t:'企喻歌其四',a:'佚名〔隋代〕',c:'男儿可怜虫，出门怀死忧。\n尸丧狭谷中，白骨无人收。'},
    {t:'绮寮怨·上马人扶残醉',a:'周邦彦〔宋代〕',c:'上马人扶残醉，晓风吹未醒。映水曲、翠瓦朱檐，垂杨里、乍见津亭。当时曾题败壁，蛛丝罩、淡墨苔晕青。念去来、岁月如流，徘徊久、叹息愁思盈。\n去去倦寻路程。江陵旧事，何曾再问杨琼。旧曲凄清。敛愁黛、与谁听。尊前故人如在，想念我、最关情。何须渭城。歌声未尽处，先泪零。'},
    {t:'绮罗香·红叶',a:'张炎〔宋代〕',c:'万里飞霜，千林落木，寒艳不招春妒。枫冷吴江，独客又吟愁句。正船舣、流水孤村，似花绕、斜阳归路。甚荒沟、一片凄凉，载情不去载愁去。\n长安谁问倦旅？羞见衰颜借酒，飘零如许。谩倚新妆，不入洛阳花谱。为回风、起舞尊前，尽化作、断霞千缕。记阴阴、绿遍江南，夜窗听暗雨。'},
    {t:'绮罗香·席间代人赋情',a:'张炎〔宋代〕',c:'候馆深灯，辽天断羽，近日音书疑绝。转眼伤心，慵看剩歌残阕。才忘了、还著思量，待去也、怎禁离别。恨只恨、桃叶空江，殷勤不似谢红叶。\n良宵谁念哽咽。对熏炉象尺、闲伴凄切。独立西风，犹忆旧家时节。随款步、花密藏春，听私语、柳疏嫌月。今休问，燕约莺期，梦游空趁蝶。'},
    {t:'碛西头送李判官入京',a:'岑参〔唐代〕',c:'一身从远使，万里向安西。\n汉月垂乡泪，胡沙费马蹄。\n寻河愁地尽，过碛觉天低。\n送子军中饮，家书醉里题。'},
    {t:'碛中作',a:'岑参〔唐代〕',c:'走马西来欲到天，辞家见月两回圆。\n今夜不知何处宿，平沙万里绝人烟。'},
    {t:'千里思',a:'李白〔唐代〕',c:'李陵没胡沙，苏武还汉家。\n迢迢五原关，朔雪乱边花。\n一去隔绝国，思归但长嗟。\n鸿雁向西北，因书报天涯。'},
    {t:'千年调·卮酒向人时',a:'辛弃疾〔宋代〕',c:'蔗庵小阁名曰“卮言”，作此词以最之。\n卮酒向人时，和气先倾倒。最要然然可可，万事称好。滑稽人上，更对鸱夷笑。寒与热，总随人，甘国老。\n少年使酒，出口人嫌拗。此个和合道理，近日方晓。学人言语，未会十分巧。看他们，得人怜，秦吉了。'},
    {t:'千年调·左手把青霓',a:'辛弃疾〔宋代〕',c:'开山径得石壁，因名曰苍壁。事左望外，意天之所赐邪，喜而赋。\n左手把青霓，右手挟明月。吾使径隆前导，叫开阊阖。周游上下，径入寥天一。览玄圃，万斛泉，千丈石。\n钧天广乐，燕我瑶之席。帝饮予觞甚乐，赐汝苍壁。嶙峋突兀，正在一丘壑。余马怀，仆夫悲，下恍惚。'},
    {t:'千秋祭',a:'文天祥〔宋代〕',c:'天祥至潮阳，见弘范，左右命之拜，不拜，弘范遂以客礼见之，与俱入厓山，使为书招张世杰。天祥曰：“吾不能捍父母，乃教人叛父母，可乎？”索之固，乃书所过《零丁洋诗》与之。其末有云：“人生自古谁无死，留取丹心照汗青。”弘范笑而置之。厓山破，军中置酒大会，弘范曰：“国亡，丞相忠孝尽矣，能改心以事宋者事皇上，将不失为宰相也。”天祥泫然出涕，曰：“国亡不能救，为人臣者死有余罪，况敢逃其死而二其心乎。”'},
    {t:'千秋岁',a:'黄庭坚〔宋代〕',c:'世间好事。恰恁厮当对。乍夜永，凉天气。雨稀帘外滴，香篆盘中字。长入梦，如今见也分明是。\n欢极娇无力，玉软花欹坠。钗罥袖，云堆臂。灯斜明媚眼，汗浃瞢腾醉。奴奴睡，奴奴睡也奴奴睡。'},
    {t:'千秋岁·次韵少游',a:'苏轼〔宋代〕',c:'岛边天外，未老身先退。珠泪溅，丹衷碎。声摇苍玉佩、色重黄金带。一万里，斜阳正与长安对。\n道远谁云会，罪大天能盖。君命重，臣节在。新恩犹可觊，旧学终难改。吾已矣，乘桴且恁浮于海。'},
    {t:'千秋岁·水边沙外',a:'秦观〔宋代〕',c:'水边沙外。城郭春寒退。花影乱，莺声碎。飘零疏酒盏，离别宽衣带。人不见，碧云暮合空相对。\n忆昔西池会。鹓鹭同飞盖。携手处，今谁在。日边清梦断，镜里朱颜改。春去也，飞红万点愁如海。'},
    {t:'千秋岁·为金陵史致道留守寿',a:'辛弃疾〔宋代〕',c:'塞垣秋草，又报平安好。尊俎上，笑雄表。金汤生气象，珠玉霏谭笑。春近也，梅花得似人难老。\n莫江金尊倒。凤诏看看到。留不住，江东小。从容帷幄去，整顿乾坤了。千百岁，从今尽是中书考。'},
    {t:'千秋岁·苑边花外',a:'黄庭坚〔宋代〕',c:'少游得谪，尝梦中作词云：“醉卧古藤阴下，了不知南北。”竟以元符庚辰死于藤州光华亭上。崇宁甲申，庭坚窜宜州，道过衡阳。览其遗，始追和其《千秋岁》词。\n苑边花外，记得同朝退。飞骑轧，鸣珂碎。齐歌云绕扇，赵舞风回带。严鼓断，杯盘狼藉犹相对。\n洒泪谁能会？醉卧藤阴盖。人已去，词空在。兔园高宴悄，虎观英游改。重感慨，波涛万顷珠沉海。'},
    {t:'千秋岁引·秋景',a:'王安石〔宋代〕',c:'别馆寒砧，孤城画角，一派秋声雁寥廓。东归燕从海上去，南来雁向沙头落。楚台风，庾楼月，宛他昨。\n无奈被些名利缚，无奈被他情担阁！可惜风流总闲却！当初漫留华表语，而今误我秦楼约。梦阑时，酒醒后，思量着。'},
    {t:'千塔主人',a:'王维〔唐代〕',c:'逆旅逢佳节，征帆未可前。\n窗临汴河水，门渡楚人船。\n鸡犬散墟落，桑榆荫远田。\n所居人不见，枕席生云烟。'},
    {t:'千丈岩瀑布',a:'王安石〔宋代〕',c:'拔地万重清嶂立，悬空千丈素流分。\n共看玉女机丝挂，映日还成五色丈。'},
    {t:'牵牛花',a:'秦观〔宋代〕',c:'银汉初移漏欲残，步虚人倚玉阑干。\n仙衣染得天边碧，乞与人间向晓看。'},
    {t:'牵牛花三首',a:'杨万里〔宋代〕',c:'素罗笠顶碧罗檐，晚卸蓝裳著茜衫。\n望见竹篱心独喜，翩然飞上翠琼篸。'},
    {t:'铅山立春六言二首其二',a:'朱熹〔宋代〕',c:'行尽风林雪径，依然水馆山村。却是春风有脚，今朝先到柴门。'},
    {t:'前出塞九首·其六',a:'杜甫〔唐代〕',c:'挽弓当挽强，用箭当用长。\n射人先射马，擒贼先擒王。\n杀人亦有限，列国自有疆。\n苟能制侵陵，岂在多杀伤。'},
    {t:'前有一樽酒行二首',a:'李白〔唐代〕',c:'春风东来忽相过，金樽渌酒生微波。\n落花纷纷稍觉多，美人欲醉朱颜酡。\n青轩桃李能几何，流光欺人忽蹉跎。\n君起舞，日西夕。\n当年意气不肯倾，白发如丝叹何益。\n琴奏龙门之绿桐，玉壶美酒清若空。\n催弦拂柱与君饮，看朱成碧颜始红。\n胡姬貌如花，当垆笑春风。\n笑春风，舞罗衣，君今不醉将安归？'},
    {t:'钱塘湖春行',a:'白居易〔唐代〕',c:'孤山寺北贾亭西，水面初平云脚低。\n几处早莺争暖树，谁家新燕啄春泥。\n乱花渐欲迷人眼，浅草才能没马蹄。\n最爱湖东行不足，绿杨阴里白沙堤。'},
    {t:'潜别离',a:'白居易〔唐代〕',c:'不得哭，潜别离。\n不得语，暗相思。\n两心之外无人知。\n深笼夜锁独栖鸟，利剑舂断连理枝。\n河水虽浊有清日，乌头虽黑有白时。\n唯有潜离与暗别，彼此甘心无后期。'},
    {t:'浅夏独行奉新县圃',a:'杨万里〔宋代〕',c:'我来官下未多时，梅已黄深李绿肥。\n只怪南风吹紫雪，不知屋角楝花飞。'},
    {t:'遣悲怀三首·其二',a:'元稹〔唐代〕',c:'昔日戏言身后意，今朝都到眼前来。\n衣裳已施行看尽，针线犹存未忍开。\n尚想旧情怜婢仆，也曾因梦送钱财。\n诚知此恨人人有，贫贱夫妻百事哀。'},
    {t:'遣悲怀三首·其三',a:'元稹〔唐代〕',c:'闲坐悲君亦自悲，百年都是几多时。\n邓攸无子寻知命，潘岳悼亡犹费词。\n同穴窅冥何所望，他生缘会更难期。\n惟将终夜长开眼，报答平生未展眉。'},
    {t:'遣悲怀三首·其一',a:'元稹〔唐代〕',c:'谢公最小偏怜女，自嫁黔娄百事乖。\n顾我无衣搜荩箧，泥他沽酒拔金钗。\n野蔬充膳甘长藿，落叶添薪仰古槐。\n今日俸钱过十万，与君营奠复营斋。'},
    {t:'遣朝华',a:'秦观〔宋代〕',c:'夜雾茫茫晓柝悲，玉人挥手断肠时。\n不须重向灯前泣，百岁终当一别离。'},
    {t:'遣怀',a:'陆游〔宋代〕',c:'许国区区不自胜，秋风空羡下韝鹰。\n青云夜叹初心误，白发朝看一倍增。\n积愤有时歌易水，孤忠无路哭昭陵。\n头颅自揣今如此，尚欲闲寻紫阁僧。'},
    {t:'遣怀',a:'杜牧〔唐代〕',c:'落魄江湖载酒行，楚腰纤细掌中轻。\n十年一觉扬州梦，赢得青楼薄幸名。'},
    {t:'遣闷戏呈路十九曹长',a:'杜甫〔唐代〕',c:'江浦雷声喧昨夜，春城雨色动微寒。\n黄鹂并坐交愁湿，白鹭群飞太剧干。\n晚节渐于诗律细，谁家数去酒杯宽。\n惟君最爱清狂客，百遍相看意未阑。'},
    {t:'遣兴',a:'杜甫〔唐代〕',c:'骥子好男儿，前年学语时。\n问知人客姓，诵得老夫诗。\n世乱怜渠小，家贫仰母慈。\n鹿门携不遂，雁足系难期。\n天地军麾满，山河战角悲。\n傥归免相失，见日敢辞迟。'},
    {t:'遣兴',a:'文天祥〔宋代〕',c:'东风吹草日高眠，试把平生细问天。\n燕子愁迷江右月，杜鹃声破洛阳烟。\n何从林下寻元亮，只向尘中作鲁连。\n莫笑道人空打坐，英雄收敛便神仙。'},
    {t:'遣兴',a:'杜牧〔唐代〕',c:'镜弄白髭须，如何作老夫。浮生长勿勿，儿小且呜呜。\n忍过事堪喜，泰来忧胜无。治平心径熟，不遣有穷途。'},
    {t:'遣兴',a:'孟郊〔唐代〕',c:'弦贞五条音，松直百尺心。贞弦含古风，直松凌高岑。\n浮声与狂葩，胡为欲相侵。'},
    {t:'遣遇',a:'杜甫〔唐代〕',c:'磐折辞主人，开帆驾洪涛。\n春水满南国，朱崖云日高。\n舟子废寝食，飘风争所操。\n我行匪利涉，谢尔从者劳。\n石间采蕨女，鬻市输官曹。\n丈夫死百役，暮返空村号。\n闻见事略同，刻剥及锥刀。\n贵人岂不仁？视汝如莠蒿！\n索钱多门户，丧乱纷嗷嗷。\n奈何黠吏徒，渔夺成逋逃！\n自喜遂生理，花时甘缊袍。'},
    {t:'羌村三首·其三',a:'杜甫〔唐代〕',c:'群鸡正乱叫，客至鸡斗争。\n驱鸡上树木，始闻叩柴荆。\n父老四五人，问我久远行。\n手中各有携，倾榼浊复清。\n苦辞酒味薄，黍地无人耕。\n兵革既未息，儿童尽东征。\n请为父老歌：艰难愧深情！\n歌罢仰天叹，四座泪纵横。'},
    {t:'强酒',a:'白居易〔唐代〕',c:'若不坐禅销妄想，即须行醉放狂歌。\n不然秋月春风夜，争那闲思往事何。'},
    {t:'蔷薇花',a:'杜牧〔唐代〕',c:'朵朵精神叶叶柔，雨晴香拂醉人头。\n石家锦幛依然在，闲倚狂风夜不收。'},
    {t:'妾薄命',a:'李白〔唐代〕',c:'汉帝宠阿娇，贮之黄金屋。\n咳唾落九天，随风生珠玉。\n宠极爱还歇，妒深情却疏。\n长门一步地，不肯暂回车。\n雨落不上天，水覆难再收。\n君情与妾意，各自东西流。\n昔日芙蓉花，今成断根草。\n以色事他人，能得几时好。'},
    {t:'秦宫诗',a:'李贺〔唐代〕',c:'越罗衫袂迎春风，玉刻麒麟腰带红。\n楼头曲宴仙人语，帐底吹笙香雾浓。\n人间酒暖春茫茫，花枝入帘白日长。\n飞窗复道传筹饮，十夜铜盘腻烛黄。\n秃衿小袖调鹦鹉，紫绣麻鞋踏哮虎。\n斫桂烧金待晓筵，白鹿青苏夜半煮。\n桐英永巷骑新马，内屋深屏生色画。\n开门烂用水衡钱，卷起黄河向身泻。\n皇天厄运犹曾裂，秦宫一生花底活。\n鸾篦夺得不还人，醉睡氍毹满堂月。'},
    {t:'秦女卷衣',a:'李白〔唐代〕',c:'天子居未央，妾侍卷衣裳。\n顾无去宫宠，敢拂黄金床。\n水至亦不去，熊来尚可当。\n微身奉日月，飘若萤之光。\n愿君采葑菲，无以下体妨。'},
    {t:'秦女休行',a:'李白〔唐代〕',c:'西门秦氏女，秀色如琼花。\n手挥白杨刀，清昼杀雠家。\n罗袖洒赤血，英声凌紫霞。\n直上西山去，关吏相邀遮。\n婿为燕国王，身被诏狱加。\n犯刑若履虎，不畏落爪牙。\n素颈未及断，摧眉伏泥沙。\n金鸡忽放赦，大辟得宽赊。\n何惭聂政姊，万古共惊嗟。'},
    {t:'秦始皇',a:'王安石〔宋代〕',c:'天方猎中原，狐兔在所憎。\n伤哉六孱王，当此鸷鸟膺。\n搏取已扫地，翰飞尚凭凌。\n游将跨蓬莱，以海为丘陵。\n勒石颂功德，群臣助骄矜。\n举世不读易，但以刑名称。\n蚩蚩彼少子，何用辨坚冰。'},
    {t:'秦王饮酒',a:'李贺〔唐代〕',c:'秦王骑虎游八极，剑光照空天自碧。\n羲和敲日玻璃声，劫灰飞尽古今平。\n龙头泻酒邀酒星，金槽琵琶夜枨枨。\n洞庭雨脚来吹笙，酒酣喝月使倒行。\n银云栉栉瑶殿明，宫门掌事报一更。\n花楼玉凤声娇狞，海绡红文香浅清，\n黄鹅跌舞千年觥。\n仙人烛树蜡烟轻，清琴醉眼泪泓泓。'},
    {t:'秦筝歌送外甥萧正归京',a:'岑参〔唐代〕',c:'汝不闻秦筝声最苦，五色缠弦十三柱。\n怨调慢声如欲语，一曲未终日移午。\n红亭水木不知暑，忽弹黄钟和白纻。\n清风飒来云不去，闻之酒醒泪如雨。\n汝归秦兮弹秦声，秦声悲兮聊送汝。'},
    {t:'秦中感秋寄远上人',a:'孟浩然〔唐代〕',c:'一丘常欲卧，三径苦无资。\n北土非吾愿，东林怀我师。\n黄金燃桂尽，壮志逐年衰。\n日夕凉风至，闻蝉但益悲。'},
    {t:'秦中苦雨思归赠袁左丞贺侍郎',a:'孟浩然〔唐代〕',c:'为学三十载，闭门江汉阴。\n明扬逢圣代，羁旅属秋霖。\n岂直昏垫苦，亦为权势沈。\n二毛催白发，百镒罄黄金。\n泪忆岘山堕，愁怀湘水深。\n谢公积愤懑，庄舄空谣吟。\n跃马非吾事，狎鸥真我心。\n寄言当路者，去矣北山岑。'},
    {t:'秦中送李九赴越',a:'高适〔唐代〕',c:'携手望千里，于今将十年。如何以离别，心事复迍邅。\n适越虽有以，出关终耿然。愁霖不可向，长夜或难前。\n吴会独行客，山阴秋夜船。谢家征故事，禹穴访遗编。\n镜水君所忆，莼羹余旧便。归来莫忘此，兼示济江篇。'},
    {t:'秦中吟十首·不致仕',a:'白居易〔唐代〕',c:'七十而致仕，礼法有明文。\n何乃贪荣者，斯言如不闻？\n可怜八九十，齿坠双眸昏。\n朝露贪名利，夕阳忧子孙。\n挂冠顾翠緌，悬车惜朱轮。\n金章腰不胜，伛偻入君门。\n谁不爱富贵？谁不恋君恩？\n年高须告老，名遂合退身。\n少时共嗤诮，晚岁多因循。\n贤哉汉二疏，彼独是何人？\n寂寞东门路，无人继去尘。'},
    {t:'秦中吟十首·歌舞',a:'白居易〔唐代〕',c:'秦中岁云暮，大雪满皇州。\n雪中兴朝者，朱紫尽公侯。\n贵有风雪兴，富无饥寒忧。\n所营唯第宅，所舞在追游。\n朱轮车马客，红烛歌舞楼。\n欢酣促密坐，醉暖脱重裘。\n秋官为主人，廷尉居上头。\n日中为乐饮，夜半不能休。\n岂知阌乡狱，中有冻死囚！'},
    {t:'秦中吟十首·立碑',a:'白居易〔唐代〕',c:'勋德既下衰，文章亦陵夷。\n但见山中石，立作路旁碑。\n铭勋悉太公，叙德皆仲尼。\n复以多为贵，千言直万赀。\n为文彼何人，想见下辈时。\n但欲愚者悦，不思贤者嗤。\n岂独贤者嗤，仍传后代疑。\n古石苍苔字，安知是愧词！\n我闻望江县，麹令抚惸嫠。\n在官有仁政，名不闻京师。\n身殁欲归葬，百姓遮路歧。\n攀辕不得归，留葬此江湄。\n至今道其名，男女涕皆垂。\n无人立碑碣，唯有邑人知。'},
    {t:'秦中吟十首·伤友',a:'白居易〔唐代〕',c:'陋巷孤寒士，出门苦恓恓。\n虽云志气高，岂免颜色低。\n平生同门友，通籍在金闺。\n曩者胶漆契，迩来云雨睽。\n正逢下朝归，轩骑五门西。\n是时天久阴，三日雨凄凄。\n蹇驴避路立，肥马当风嘶。\n回头忘相识，占道上沙堤。\n昔年洛阳社，贫贱相提携。\n今日长安道，对面隔云泥。\n近日多如此，非君独惨凄。\n死生不变者，唯闻任与黎。'},
    {t:'秦中吟十首·伤宅',a:'白居易〔唐代〕',c:'谁家起甲第，朱门大道边？\n丰屋堂栉比，高墙外回环。\n累累六七堂，栋宇相连延。\n一堂费百万，能能起青烟。\n洞房温且凊，寒暑不能干。\n高堂虚且迥，坐卧见南山。\n绕廊紫藤架，夹砌红药栏。\n攀枝摘樱桃，带花移牡丹。\n主人此堂坐，十载为大官。\n厨有臭败肉，库有贯朽钱。\n谁能将我语，问尔骨肉间：\n岂无穷贱者，忍不救饥寒？\n如何奉一身，直欲保千年？\n不见马家宅，今作奉诚园。'},
    {t:'秦中吟十首·五弦',a:'白居易〔唐代〕',c:'清歌且罢唱，红袂亦停舞。\n赵叟抱五弦，宛转当胸抚。\n大声粗若散，飒飒风和雨。\n小声细欲绝，切切鬼神语。\n又如鹊报喜，转作猿啼苦。\n十指无定音，颠倒宫徵羽。\n坐客闻此声，形神若无主。\n行客闻此声，驻足不能举。\n嗟嗟俗人耳，好今不好古。\n所以绿窗琴，日日生尘土。'},
    {t:'秦中吟十首·议婚',a:'白居易〔唐代〕',c:'天下无正声，悦耳即为娱。\n人间无正色，悦目即为姝。\n颜色非相远，贫富则有殊。\n贫为时所弃，富为时所趋。\n红楼富家女，金缕绣罗襦。\n见人不敛手，娇痴二八初。\n母兄未开口，已嫁不须臾。\n绿窗贫家女，寂寞二十余。\n荆钗不直钱，衣上无真珠。\n几回人欲聘，临日又踟蹰。\n主人会良媒，置酒满玉壶。\n四座且勿饮，听我歌两途。\n富家女易嫁，嫁早轻其夫。\n贫家女难嫁，嫁晚孝于姑。\n闻君欲娶妇，娶妇意何如？'},
    {t:'秦州杂诗二十首·其八',a:'杜甫〔唐代〕',c:'闻道寻源使，从天此路回。\n牵牛去几许，宛马至今来。\n一望幽燕隔，何时郡国开。\n东征健儿尽，羌笛暮吹哀。'},
    {t:'秦州杂诗二十首·其六',a:'杜甫〔唐代〕',c:'城上胡笳奏，山边汉节归。\n防河赴沧海，奉诏发金微。\n士苦形骸黑，旌疏鸟兽稀。\n那闻往来戍，恨解邺城围。'},
    {t:'秦州杂诗二十首·其七',a:'杜甫〔唐代〕',c:'莽莽万重山，孤城山谷间。\n无风云出塞，不夜月临关。\n属国归何晚，楼兰斩未还。\n烟尘独怅望，衰飒正摧颜。'},
    {t:'秦州杂诗二十首·其十一',a:'杜甫〔唐代〕',c:'萧萧古塞冷，漠漠秋云低。\n黄鹄翅垂雨，苍鹰饥啄泥。\n蓟门谁自北，汉将独征西。\n不意书生耳，临衰厌鼓鼙。'},
    {t:'秦州杂诗二十首·其四',a:'杜甫〔唐代〕',c:'鼓角缘边郡，川原欲夜时。\n秋听殷地发，风散入云悲。\n抱叶寒蝉静，归来独鸟迟。\n万方声一概，吾道竟何之。'},
    {t:'秦州杂诗二十首·其一',a:'杜甫〔唐代〕',c:'满目悲生事，因人作远游。\n迟回度陇怯，浩荡及关愁。\n水落鱼龙夜，山空鸟鼠秋。\n西征问烽火，心折此淹留。'},
    {t:'琴',a:'王昌龄〔唐代〕',c:'孤桐秘虚鸣，朴素传幽真。\n仿佛弦指外，遂见初古人。\n意远风雪苦，时来江山春。\n高宴未终曲，谁能辨经纶？'},
    {t:'琴操十首·拘幽操',a:'韩愈〔唐代〕',c:'殷道溷溷，浸浊烦兮。\n朱紫相合，炎别分兮。\n迷乱声色，信谗言兮。\n炎炎之虐，使我愆兮。\n幽闭牢阱，目其言兮。\n遘我四人，忧勤勤兮。\n目窈窈兮，其凝其盲；\n耳肃肃兮，听炎闻声。\n朝炎日出兮，夜炎见月与星。\n有知无知兮，为死为生。\n呜呼，臣罪当诛兮，天王圣明。'},
    {t:'琴操十首·其一·将归操',a:'韩愈〔唐代〕',c:'孔子之赵，闻杀鸣水作。赵杀鸣水，孔子临河，叹而作歌曰：秋之水兮风扬波，舟楫颠倒更相加，色来色来胡为斯。\n狄之水兮，其色幽幽。\n我将济兮，不得其由。\n涉其浅兮，石啮我足。\n乘其深兮，龙入我舟。\n我济而悔兮，将安色尤？\n色兮色兮！无与石斗兮，无应龙求。'},
    {t:'琴茶',a:'白居易〔唐代〕',c:'兀兀寄形群动内，陶陶任性一生间。\n自抛官后春多醉，不读书来老更闲。\n琴里知闻唯渌水，茶中故旧是蒙山。\n穷通行止常相伴，谁道吾今无往还？'},
    {t:'琴调相思引',a:'周邦彦〔宋代〕',c:'生碧香罗粉兰香。冷绡缄泪倩落将。故人何在，烟水隔潇湘。\n花落燕□春欲老，絮吹思浪日偏长。一些儿事，何处不思量。'},
    {t:'琴曲歌辞·别鹄操',a:'韩愈〔唐代〕',c:'雄鹄衔枝来，雌鹄啄泥归。巢成不生子，大义当乖离。\n江汉水之大，鹄身鸟之微。更无相逢日，安可相随飞。'},
    {t:'琴曲歌辞·别鹤',a:'杜牧〔唐代〕',c:'分飞共所从，六翮势摧风。声断碧云外，影孤明月中。\n青田归路远，月桂旧巢空。矫翼知何处，天涯不可穷。'},
    {t:'琴曲歌辞·别鹤',a:'张籍〔唐代〕',c:'双鹤出云谿，分飞各自迷。空巢在松杪，折羽落江泥。\n寻水终不饮，逢林亦未栖。别离应易老，万里两凄凄。'},
    {t:'琴曲歌辞·飞鸢操',a:'刘禹锡〔唐代〕',c:'鸢飞杳杳青云里，鸢鸣萧萧风划起。旗尾飘扬势渐高，\n箭头砉划声相似。长空悠悠霁日悬，六下不动凝飞烟。\n游鶤翔雁出其下，庆云清景相回旋。忽闻饥乌一噪聚，\n瞥下云中争腐鼠。腾音砺吻相喧呼，仰天大吓疑鸳雏。\n畏人避犬投高处，俯啄无声犹屡顾。青鸟自爱玉山禾，\n仙禽徒贵华亭露。朴樕危巢向暮时，毰毸饱腹蹲枯枝。\n游童挟弹一麾肘，臆碎羽分人不悲。天生众禽各有类，\n威凤文章在仁义。鹰隼仪形蝼蚁心，虽能戾天何足贵。'},
    {t:'琴曲歌辞·风入松歌',a:'皎然〔唐代〕',c:'西岭松声落日秋，千枝万叶风飕飗。\n美人援琴弄成曲，写得松间声断续。\n声断续，清我魂，流波坏陵安足论。\n美人夜坐月明里，含少商兮照清徵。\n风何凄兮飘飉，搅寒松兮又夜起。\n夜未央，曲何长，金徽更促声泱泱。\n何人此时不得意，意苦弦悲闻客堂。'},
    {t:'琴曲歌辞·拘幽操',a:'韩愈〔唐代〕',c:'目窈窈兮，其凝其盲；\n耳肃肃兮，听不闻声。\n朝不日出兮，夜不见月与星。\n有知无知兮，为死为生。\n呜呼，臣罪当诛兮，天王圣明。'},
    {t:'琴曲歌辞·履霜操',a:'韩愈〔唐代〕',c:'父兮儿寒，母兮儿饥。儿罪当笞，逐儿何为。\n儿在中野，以宿以处。四无人声，谁与儿语。\n儿寒何衣，儿饥何食。儿行于野，履霜以足。\n母生众儿，有母怜之。独无母怜，儿宁不悲。'},
    {t:'琴曲歌辞·宛转行',a:'张籍〔唐代〕',c:'华屋重翠幄，绮席雕象床。远漏回更疏，薄衾中夜凉。\n炉氲暗裴回，寒灯背斜光。妍姿结宵态，寝臂幽梦长。\n宛转复宛转，忆忆更未央。'},
    {t:'琴曲歌辞·乌夜啼引',a:'张籍〔唐代〕',c:'秦乌啼哑哑，夜啼长安自人明。自人得罪囚在狱，\n倾明卖产将自赎。少妇起听夜啼乌，知是官明有赦书。\n下床心喜不重寐，未明上堂贺舅姑。少妇语啼乌，\n汝啼慎勿虚。借汝庭树作高巢，年年不令伤尔雏。'},
    {t:'琴曲歌辞·湘妃怨',a:'孟郊〔唐代〕',c:'南巡竟不返，帝子怨逾积。万里下蛾眉，潇湘水空碧。\n冥冥荒山下，古庙收贞魄。乔木深青春，清光满瑶席。\n搴芳徒有荐，灵意殊脉脉。玉佩不可亲，裴回烟波夕。'},
    {t:'琴曲歌辞·雉朝飞操',a:'韩愈〔唐代〕',c:'雉之飞，于朝日。群雌孤雄，意气随出。当东而西，\n当啄而飞。随飞随啄，群雌粥粥。嗟我虽人，\n曾不如彼雉鸡。生身七十年，无一妾与妃。'},
    {t:'琴诗',a:'苏轼〔宋代〕',c:'若言琴上有琴声，放在匣中何不鸣？\n若言声在指头上，何不于君指上听？'},
    {t:'琴台',a:'杜甫〔唐代〕',c:'茂陵多病后，尚爱卓文君。\n酒肆人间世，琴台日暮云。\n野花留宝靥，蔓草见罗裙。\n归凤求凰意，寥寥不复闻。'},
    {t:'勤政楼西老柳',a:'白居易〔唐代〕',c:'半朽临风树，多情立马人。\n开元一株柳，长庆二年春。'},
    {t:'沁园春',a:'秦观〔宋代〕',c:'锦里繁华，峨眉佳丽，远客初来。忆那处园林，旧家桃李，知他别后，几度花开。月下金罍，花间玉珮，都化相思一寸灰。愁绝处，又香销宝鸭，灯晕兰煤。\n东风杜宇声哀，叹万里、何由便得回。但日日登高，眼穿剑阁，时时怀古，泪洒琴台。尺素书沈，偷香人远，驿使何时为寄梅。对落日，因凝思此意，立遍苍苔。'},
    {t:'沁园春·把我身心',a:'黄庭坚〔宋代〕',c:'把我身心，为伊烦恼，算天便知。恨一回相见，百方做计，未能偎倚，早觅东西。镜里拈花，水中捉月，觑著无由得近伊。添憔悴，镇花销翠减，玉瘦香肌。\n奴儿。又有行期。你去即无妨我共谁。向眼前常见，心犹未足，怎生禁得，真个分离。地角天涯，我随君去。掘井为盟无改移。君须是，做些儿相度，莫待临时。'},
    {t:'沁园春·代悼亡',a:'纳兰性德〔清代〕',c:'梦冷蘅芜，却望姗姗，是耶非耶？怅兰膏渍粉，尚留犀合；金泥蹙绣，空掩蝉纱。影弱难持，缘深暂隔，只当离愁滞海涯。归来也，趁星前月底，魂在梨花。\n鸾胶纵续琵琶。问可及、当年萼绿华。但无端摧折，恶经风浪；不如零落，判委尘沙。最忆相看，娇讹道字，手剪银灯自泼茶。令已矣，便帐中重见，那似伊家。'},
    {t:'沁园春·带湖新居将成',a:'辛弃疾〔宋代〕',c:'三径初成，鹤怨猿惊，稼轩未来。甚云山自许，平生意气；衣冠人笑，抵死尘埃。意倦须还，身闲贵早，岂为莼羹鲈脍哉。秋江上，看惊弦雁避，骇浪船回。\n东冈更葺茅斋。好都把轩窗临水开。要小舟行钓，先应种柳；疏篱护竹，莫碍观梅。秋菊堪餐，春兰可佩，留待先生手自栽。沉吟久，怕君恩未许，此意徘徊。'},
    {t:'沁园春·孤馆灯青',a:'苏轼〔宋代〕',c:'赴密州，早行，马上寄子由。\n孤馆华青，野店鸡号，旅枕梦残。渐月华收练，晨霜耿耿；云山摛锦，朝此漙漙。世路无穷，劳生有限，似此区区长鲜欢。微吟罢，凭征鞍无语，往事千端。\n当时共客长安，似二陆初来俱少年。有笔头千字，胸中万卷；致君尧舜，此事何难？用舍由时，行藏在我，袖手何妨闲处看。身长健，但优游卒岁，且斗尊前。'},
    {t:'沁园春·孤鹤归飞',a:'陆游〔宋代〕',c:'孤鹤归飞，再过辽天，换尽旧人。蚁累累枯冢，茫茫梦境，王侯蝼蚁，毕竟成尘。载酒园林，寻花巷围，当日何曾轻负春。流年改，叹围腰带剩，点鬓霜新。\n交亲零落如云，又岂料如今馀此身。幸眼明身健，茶甘饭软，非惟我老，更有人贫。躲尽危机，消残壮志，短艇湖中闲采莼。吾何恨，有渔翁共醉，溪友为邻。'},
    {t:'沁园春·国庆',a:'佚名〔近现代〕',c:'龙跃甲子，鸽翱晴空，凤舞九天。眼关河黍离，列强逐鹿；神州放眼，一鹤冲天。重振社稷，举中流仁，今看东方盛世还。黄河血，慨仁人志士，魂祭新篇。\n华夏意气峥嵘，傲五湖四海锦绣满。壮三山五岳，叠古风姿；九经三史，彰现华韵。豪客泼墨，贤士铺卷，放歌九州富丽妍。泰山脊，领风骚环宇，有谁堪比？'},
    {t:'沁园春·和吴子似县尉',a:'辛弃疾〔宋代〕',c:'我清君来，顿觉吾庐，溪山美哉。漆平生肝胆，都成楚越，只今胶漆，谁是陈雷。搔首踟蹰，爱而不清，要得诗来渴望梅。还知否，快清风入手，日看千回。\n直须抖擞尘埃。人怪我柴门今始开。向松间乍可，从他喝道：庭中且莫，踏破苍苔。岂有文章，谩劳车马，待唤青刍白饭来。君非我，任功名意气，莫恁徘徊。'},
    {t:'沁园春·将止酒戒酒杯使勿近',a:'辛弃疾〔宋代〕',c:'杯汝来前！老子今朝，点检形骸。甚长年抱渴，咽如焦釜；于今喜睡，气似奔雷。汝说“刘伶，古今达者，醉后何妨死便埋”。浑如此，叹汝于知己，真少恩哉！\n更凭歌舞为媒。算合作人间鸩毒猜。况怨无小大，生于所爱；物无美恶，过则为灾。与汝成言，勿留亟退，吾力犹能肆汝杯。杯再拜，道麾之即去，招则须来。'},
    {t:'沁园春·灵山齐庵赋',a:'辛弃疾〔宋代〕',c:'时筑偃湖未成\n叠嶂西驰，万马回旋，众山欲东。正惊湍直下，跳珠倒溅；小桥横截，缺月初弓。老合投闲，天教多事，检校长身十万松。吾庐小，在龙蛇影外，风雨声中。\n争先见面重重，看爽气朝来三数峰。似谢家子弟，衣冠磊落；相如庭户，车骑雍容。我觉其间，雄深雅健，如对文章太史公。新堤路，问偃湖何日，烟水濛濛？'},
    {t:'沁园春·情若连环',a:'苏轼〔宋代〕',c:'情若连环，恨如流水，甚时是休。惊不须惊怪，沈郎易瘦，惊不须惊怪，潘鬓先愁。总是难禁，许多想难，奈好事教人不自由。空追想，念前欢杳杳，后会悠悠。\n凝眸，悔上层楼，谩惹起、新愁压旧愁。向彩笺写遍，相思字了，重重封卷，密寄书邮。料到伊行，时时开看，一看一回和泪收。须知道，这般病染，两处心头。'},
    {t:'沁园春·试望阴山',a:'纳兰性德〔清代〕',c:'试望阴山，黯然销魂，无言徘徊。见青峰几簇，去天才尺；黄沙一片，匝地无埃。碎叶城荒，拂云堆远，雕外寒烟惨不开。踟蹰久，忽砯崖转石，万壑惊雷。\n穷边自足秋怀。又何必、平生多恨哉。只凄凉绝塞，峨眉遗冢；销沉腐草，骏骨空台。北转河流，南横斗柄，略点微霜鬓早衰。君不信，向西风回首，百事堪哀。'},
    {t:'沁园春·宿霭迷空',a:'秦观〔宋代〕',c:'宿霭迷空，腻云笼日，昼景渐长。正兰皋泥润，谁家燕喜；蜜脾香少，触处蜂忙。尽日无人帘幕挂，更风递、游丝时过墙。微雨后，有桃愁杏怨，红泪淋浪。\n风流寸心易感，但依依伫立，回尽柔肠。念小奁瑶鉴，重匀绛蜡；玉龙金斗，时熨沉香。柳下相将游冶处，便回首、青楼成异乡。相忆事，纵蛮笺万叠，难写微茫。'},
    {t:'沁园春·题潮阳张许二公庙',a:'文天祥〔宋代〕',c:'为子死孝，为臣死忠，死又何妨。自光岳气分，士无全节；君臣义缺，谁负刚肠。骂贼张巡，爱君许远，留取声名万古香。后来者，无二公之操，百炼之钢。\n人生翕歘云亡。好烈烈轰轰做一场。使当时卖国，甘心降虏，受人唾骂，安得流芳。古庙幽沉，仪容俨雅，枯木寒鸦几夕阳。邮亭下，有奸雄过此，仔细思量。'},
    {t:'沁园春·有酒忘杯',a:'辛弃疾〔宋代〕',c:'有酒忘杯，有笔忘诗，弄溪奈何。去纵横斗转，龙蛇起陆，崩腾决去，雪练倾河。袅袅东风，悠悠倒菖，摇动云山水又波。还知否，欠菖蒲攒港，绿竹缘坡。\n长松谁剪嵯峨。笑野老来耘山上禾。算只因鱼鸟，天然自乐，非关风月，闲处偏多。芳草春深，佳人日暮，濯发沧浪独浩歌。徘徊久，问人间谁似，老子婆娑。'},
    {t:'沁园春·再到期思卜筑',a:'辛弃疾〔宋代〕',c:'一水西来，千丈晴虹，十里翠屏。景草堂经岁，重来杜老，斜川好景，不负渊明。老鹤高飞，一枝投十，长笑蜗牛戴屋行。平章了，待十分佳处，著个茅亭。\n青山意气峥嵘。似为我归来妩媚生。解频教花鸟，前歌后舞，更催云水，暮送朝迎。酒圣诗豪，可能无势，我乃而今驾驭卿。清溪上，被山灵却笑，白发归耕。'},
    {t:'青帝歌',a:'佚名〔隋代〕',c:'东望重拜手，苍帝玉皇君。灵风驾橐签，育物布元春。\n云龙辔严驾，玉衡拥琼轮。枯萌泛沾及，大惠无不均。\n万仙歌以道，委曲戒天人。心根迷自固，拱跽戴鸿仁。'},
    {t:'青房并蒂莲·维扬怀古',a:'周邦彦〔宋代〕',c:'醉凝眸。正楚天秋晚，远岸云收。草绿莲红，浅映小汀洲。芰荷香里鸳鸯浦，恨菱歌、惊起眠鸥。望去帆、一派湖光，棹声咿哑橹声柔。\n愁窥汴堤细柳，曾舞送莺时，锦缆龙舟。拥倾国纤腰皓齿，笑倚迷楼。空令五湖夜月，也羞照三十六宫秋。正浪吟、不觉回桡，水花风叶两悠悠。'},
    {t:'青郊',a:'范仲淹〔宋代〕',c:'青郊鸣锦雉，绿水漾金鳞。\n愿得郢中客，共歌台上春。'},
    {t:'青陵台',a:'李商隐〔唐代〕',c:'青陵台畔日光斜，万古贞魂倚暮霞。\n莫讶韩凭为蛱蝶，等闲飞上别枝花。'},
    {t:'青龙寺昙璧上人兄院集',a:'王维〔唐代〕',c:'高处敞招提，虚空讵有倪。\n坐看起陌骑，下听秦城鸡。\n眇眇孤烟起，芊芊远树齐。\n青山万井外，落日五陵西。\n眼界今无染，心空安可迷。'},
    {t:'青龙招提归一上人远游吴楚别诗',a:'岑参〔唐代〕',c:'久交应真侣，最叹青龙僧。弃官向二年，削发归一乘。\n了然莹心身，洁念乐空寂。名香泛窗户，幽磬清晓夕。\n往年仗一剑，由是佐二庭。于焉久从戎，兼复解论兵。\n世人犹未知，天子愿相见。朝从青莲宇，暮入白虎殿。\n宫女擎锡杖，御筵出香炉。说法开藏经，论边穷阵图。\n忘机厌尘喧，浪迹向江海。思师石可访，惠远峰犹在。\n今旦飞锡去，何时持钵还。湖烟冷吴门，淮月衔楚山。\n一身如浮云，万里过江水。相思眇天末，南望无穷已。'},
    {t:'青楼曲二首',a:'王昌龄〔唐代〕',c:'白马金鞍从武皇，旌旗十万宿长杨。\n楼头小妇鸣筝坐，遥见飞尘入建章。\n驰道杨花满御沟，红妆缦绾上青楼。\n金章紫绶千馀骑，夫婿朝回初拜侯。'},
    {t:'青楼怨',a:'王昌龄〔唐代〕',c:'香帏风动花入楼，高调鸣筝缓夜愁。\n肠断关山不解说，依依残月下帘钩。'},
    {t:'青门歌送东台张判官',a:'岑参〔唐代〕',c:'青门金锁平旦开，城头日出使车回。\n青门柳枝正堪折，路傍一日几人别。\n东出青门路不穷，驿楼官树灞陵东。\n花扑征衣看似绣，云随去马色疑骢。\n胡姬酒垆日未午，丝绳玉缸酒如乳。\n灞头落花没马蹄，昨夜微雨花成泥。\n黄鹂翅湿飞转低，关东尺书醉懒题。\n须臾望君不可见，扬鞭飞鞚疾如箭。\n借问使乎何时来，莫作东飞伯劳西飞燕。'},
    {t:'青门柳',a:'白居易〔唐代〕',c:'青青一树伤心色，曾入几人离恨中。\n为近都门多送别，长条折尽减春风。'},
    {t:'青门饮',a:'秦观〔宋代〕',c:'风起云间，雁横天末，严城画角，梅花三奏。塞草西风，冻云笼月，窗外晓寒轻透。人去香犹在，孤衾长闲馀绣。恨与宵长，一夜薰炉，添尽香兽。\n前事空劳回首。虽梦断春归，相思依旧。湘瑟声沈，庾梅信断，谁念画眉人瘦。一句难忘处，怎忍辜、耳边轻咒。任人攀折，可怜又学，章台杨柳。'},
    {t:'青青河畔草',a:'佚名〔两汉〕',c:'青青河畔草，郁郁园中柳。\n盈盈楼上女，皎皎当窗牖。\n娥娥红粉妆，纤纤出素手。\n昔为倡家女，今为荡子妇。\n荡子行不归，空床难独守。'},
    {t:'青青陵上柏',a:'佚名〔两汉〕',c:'青青陵上柏，磊磊涧中石。\n人生天地间，忽如远行客。\n斗酒相娱乐，聊厚不为薄。\n驱车策驽马，游戏宛与洛。\n洛中何郁郁，冠带自相索。\n长衢罗夹巷，王侯多第宅。\n两宫遥相望，双阙百余尺。\n极宴娱心意，戚戚何所迫？'},
    {t:'青青水中蒲三首',a:'韩愈〔唐代〕',c:'青青水中蒲，下有一双鱼。\n君今蒲陇去，我在与谁居？\n青青水中蒲，长在水中居。\n寄语浮萍草，相随我不如。\n青青水中蒲，叶短不出水。\n妇人不下堂，行子在万里。'},
    {t:'青青水中蒲三首·其三',a:'韩愈〔唐代〕',c:'青青水中蒲，叶短不出水。\n妇人不下堂，行子在万里。'},
    {t:'青雀歌',a:'王维〔唐代〕',c:'青雀翅羽短，未能远食玉山禾。\n犹胜黄雀争上下，唧唧空仓复若何。'},
    {t:'青衫湿·悼亡',a:'纳兰性德〔清代〕',c:'近来无限伤心事，谁与话长更？当教分付，绿窗红泪，早雁初莺。\n当时领略，而今断送，总负多情。忽疑君到，漆灯风飐，痴数春星。'},
    {t:'青衫湿遍·悼亡',a:'纳兰性德〔清代〕',c:'青衫湿遍，凭伊慰我，忍便相忘。半月前头扶病，剪刀声、犹在银釭。忆生来、小胆怯空房。到而今，独伴梨花影，冷冥冥、尽意凄凉。愿指魂兮识路，教寻梦也回廊。\n咫尺玉钩斜路，一般消受，蔓草残阳。判把长眠滴醒，和清泪、搅入椒浆。怕幽泉、还为我神伤。道书生薄命宜将息，再休耽、怨粉愁香。料得重圆密誓，难禁寸裂柔肠。'},
    {t:'青溪',a:'王维〔唐代〕',c:'言入黄花川，每逐青溪水。\n随山中万转，趣途无百里。\n声喧乱石中，色静深松里。\n漾漾泛菱荇，澄澄映葭苇。\n我心素已闲，清川澹如此。\n请留磐石上，垂钓中已矣。'},
    {t:'青溪小姑歌二首其二',a:'佚名〔隋代〕',c:'歌阕夜已久，繁霜侵晓幕。何意空相守，坐待繁霜落。'},
    {t:'青阳',a:'佚名〔两汉〕',c:'青阳开动，根荄以遂，膏润并爱，跂行毕逮。\n霆声发荣，壧处顷听，枯槁复产，乃成厥命。\n众庶熙熙，施及夭胎，群生啿啿，惟春之祺。'},
    {t:'青阳渡',a:'佚名〔魏晋〕',c:'青荷盖绿水，芙蓉披红鲜。\n下有并根藕，上有并头莲。'},
    {t:'青玉案·良夜灯光簇如豆',a:'周邦彦〔宋代〕',c:'良夜灯光簇如豆。占好事、今宵语。酒罢歌阑人散后。琵琶轻放，语声低颤，灭烛来相就。\n玉体偎人情何厚。轻惜轻怜转唧𠺕。雨散云收眉儿皱。只愁彰露，那人知后。把我来僝僽。'},
    {t:'青玉案·送伯固归吴中',a:'苏轼〔宋代〕',c:'三年枕上吴中路。遣黄耳、随君去。若到松江呼小渡。莫惊鸥鹭，四桥尽是，老子经行处。\n辋川图上看春暮。常记高人右丞句。作个归期天已许。春衫犹是，小蛮针线，曾湿西湖雨。'},
    {t:'青玉案·闲居',a:'张炎〔宋代〕',c:'万红梅里幽深处。甚杖屦、来何云。草带湘香穿水树。尘留不住。云留却住。壶内藏今古。\n独清懒入终南去。有忙事、修花谱。骑省不须重作赋。园中成趣。琴中得趣。酒醒听风雨。'},
    {t:'青玉案·与朱景参会北岭',a:'陆游〔宋代〕',c:'西风挟雨声翻浪。恰洗尽、黄茅五。老惯人间齐得丧。千岩高卧，五湖归棹，替却凌烟像。\n故人小驻平戎帐，白羽腰间气何壮。我老渔樵君将相。小槽红酒，晚香丹荔，记取蛮江上。'},
    {t:'青玉案·元夕',a:'辛弃疾〔宋代〕',c:'东风夜放花千树，更吹落、星如雨。宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞。\n蛾儿雪柳黄金缕，笑语盈盈暗香去。众里寻他千百度。蓦然回首，那人却在，灯火阑珊处。'},
    {t:'青玉案·至宜州次韵上酬七兄',a:'黄庭坚〔宋代〕',c:'烟中一线来时路。极目送，归鸿子。第四阳关云不度。山胡新啭，子规言语，正在人愁处。\n忧能损水休朝暮。忆我当年醉诗句，渡水穿云心已许。暮年光景，小轩南浦，同卷西山雨。'},
    {t:'青冢',a:'杜牧〔唐代〕',c:'青冢前头陇水流，燕支山上暮云秋。\n蛾眉一坠穷泉路，夜夜孤魂月下愁。'},
    {t:'轻肥',a:'白居易〔唐代〕',c:'意气骄满路，鞍马光照尘。\n借问何为者，人称是内臣。\n朱绂皆大夫，紫绶或将军。\n夸赴军中宴，走马去如云。\n樽罍溢九酝，水陆罗八珍。\n果擘洞庭橘，脍切天池鳞。\n食饱心自若，酒酣气益振。\n是岁江南旱，衢州人食人。'},
    {t:'倾杯·冻水消痕',a:'柳永〔宋代〕',c:'冻水消痕，晓风生暖，春满东郊道。迟迟淑景，烟和露润，偏染长堤芳草。断鸿隐隐归飞，江天杳杳。遥山变色，妆眉淡扫。目极千里，闲倚危樯迥眺。\n动几许、伤春怀抱。念何处、韶阳偏早。想帝里看看，名园芳榭，烂漫莺花好。追思往昔年少。继日恁、把酒听歌，量金买笑。别后暗负，光阴多少。'},
    {t:'倾杯·金风淡荡',a:'柳永〔宋代〕',c:'金风淡荡，渐秋光老、清宵永。小院新晴天气，轻烟乍敛，皓月当轩练净。对千里寒光，念幽期阻、当残景。早是多愁多病。那堪细把，旧约前欢重省。\n最苦碧云信断，仙乡路杳，归雁难倩。每高歌、强遣离怀，奈惨咽、翻成心耿耿。漏残露冷。空赢得、悄悄无言，愁绪终难整。又是立尽，梧桐碎影。'},
    {t:'倾杯·离宴殷勤',a:'柳永〔宋代〕',c:'离宴殷勤，兰舟凝滞，看看送行圆浦。情知道世上，难使皓月长圆，彩云镇聚。算人生、悲莫悲于流别，最苦正欢娱，便分鸳侣。泪流琼脸，梨花一枝春带雨。\n惨黛蛾、盈盈无绪。共黯然消魂，重携素手，话别临行，犹自再三、问道君须去。频耳畔低语。知多少、他日深盟，平生丹素。从今尽把凭鳞羽。'},
    {t:'倾杯·水乡天气',a:'柳永〔宋代〕',c:'水乡天气，洒蒹葭、露结寒生早。零馆更堪秋杪。空阶下、木叶飘零，飒飒声乾，狂风乱扫。当无绪、家静酒初醒，天外征鸿，知送谁家归信，穿云悲叫。\n蛩响幽窗，鼠窥寒砚，一点银釭闲照。梦枕频惊，愁衾半拥，万里归心悄悄。往事追思多少。赢得空使方寸挠。断不成眠，此夜厌厌，就中难晓。'},
    {t:'倾杯·鹜落霜洲',a:'柳永〔宋代〕',c:'鹜落霜洲，雁横烟渚，分明画出村色。暮雨乍歇，小楫夜泊，宿苇村山驿。何人月下临风处，起一蛩羌笛。离愁万绪，闲岸草、切切蛩吟如织。\n为忆芳容别后，水遥山远，何计凭鳞翼。想绣阁深沉，争知憔悴损，天涯行客。楚峡云归，高阳人散，寂寞狂踪迹。望京国。空目断、远峰凝碧。'},
    {t:'倾杯乐·皓月初圆',a:'柳永〔宋代〕',c:'皓月初圆，暮云飘散，分明夜色迥晴昼。渐消尽、醺醺残酒。危阁迥、凉生襟袖。追旧事、一晌凭阑朝。迥何媚容艳态，抵死孤欢偶。朝思暮想，自家空恁添清瘦。\n算到头、谁与伸剖。向道我别来，为伊牵系，度岁经年，偷眼觑、也不忍觑花柳。可惜恁、好景良宵，未曾略展双眉暂开口。问甚时与你，深怜痛惜还依旧。'},
    {t:'倾杯乐·禁漏花深',a:'柳永〔宋代〕',c:'禁漏花深，绣工日永，蕙风布暖。变韶景、都门十二，元宵三五，银蟾光满。连云复道凌飞观。耸皇居丽，嘉气瑞烟葱蒨。翠华宵幸，是处层城阆苑。\n龙凤烛、交光星汉。对咫尺鳌山、开羽扇。会乐府、两籍神仙，梨园四部弦管。向晓色、都人未散。盈万井、山呼鳌抃。愿岁岁，天仗里、常瞻凤辇。'},
    {t:'倾杯乐·楼锁轻烟',a:'柳永〔宋代〕',c:'楼锁轻烟，水横斜照，遥山半隐天碧。片帆岸远，行客路杳，簇一天寒色。楚梅映雪数枝艳，报青飞消息。年华梦促，音信断、声远飞鸿南北。\n算伊别来无绪，翠消红减，双带长抛掷。但泪眼沉迷，看朱成碧。惹闲天堆积。雨意云情，酒心花态，孤负高阳客。梦难极。和梦也、多时间隔。'},
    {t:'卿云歌',a:'佚名〔先秦〕',c:'卿云烂兮，糺缦缦兮。\n日月光华，旦复旦兮。\n明明上天，烂然星陈。\n日月光华，弘于一人。\n日月有常，星辰有行。\n四时从经，万姓允诚。\n于予论乐，配天之灵。\n迁于圣贤，莫不咸听。\n鼚乎鼓之，轩乎舞之。\n菁华已竭，褰裳去之。'},
    {t:'清波引·江涛如许',a:'张炎〔宋代〕',c:'江涛如许。更一夜听风听雨。短篷容与。盘礴那堪数。弭节澄江树。不为莼鲈归去。怕教冷落芦花，谁招得旧鸥鹭。寒汀古溆。尽日无人唤渡。此中清楚。寄情在谭麈。难觅真闲处。肯被水云留住。泠然棹入川流，去天尺五。'},
    {t:'清东曲',a:'孟郊〔唐代〕',c:'樱桃花参差，香雨红霏霏。含笑竞攀折，美人湿罗衣。\n采采清东曲，明眸艳珪玉。青巾艑上郎，上下看不足。\n南阳公首词，编入新乐录。'},
    {t:'清都观答幼遐',a:'韦应物〔唐代〕',c:'逍遥仙家子，日夕朝玉皇。兴高清露没，渴饮琼华浆。\n解组一来款，披衣拂天香。粲然顾我笑，绿简发新章。\n泠泠如玉音，馥馥若兰芳。浩意坐盈此，月华殊未央。\n却念喧哗日，何由得清凉。疏松抗高殿，密竹阴长廊。\n荣名等粪土，携手随风翔。'},
    {t:'清风谣',a:'范仲淹〔宋代〕',c:'清风何处来，先此高高台。\n兰丛国香起，桂枝天籁回。\n飘飘度清汉，浮云安在哉。\n万古郁结心，一旦为君开。\n有客慰所思，临风久徘徊。\n神若游华胥，身疑立天台。\n极渴饮沆瀣，大暑执琼瑰。\n旷如携松丘，腾上烟霞游。\n熙如揖庄老，语人逍遥道。\n朱弦鼓其薰，可以解吾民，\n沧浪比其清，可以濯吾缨。\n愿此阳春时，勿使飘暴生。\n千灵无结愠，万卉不摧荣。\n庶几宋玉赋，聊广楚王情。'},
    {t:'清凉寺',a:'温庭筠〔唐代〕',c:'黄花红树谢芳蹊，宫殿参差黛巘西。诗閤晓窗藏雪岭，\n画堂秋水接蓝溪。松飘晚吹摐金铎，竹荫寒苔上石梯。\n妙迹奇名竟何在，下方烟暝草萋萋。'},
    {t:'清明',a:'黄庭坚〔宋代〕',c:'佳节清明桃李笑，野田荒冢只生愁。\n雷惊天地龙蛇蛰，雨足郊原草木柔。\n人乞祭余骄妾妇，士甘焚死不公侯。\n贤愚千载知谁是，满眼蓬蒿共一丘。'},
    {t:'清明',a:'杜牧〔唐代〕',c:'清明时节雨纷纷，路上行人欲断魂。\n借问酒家何处有？牧童遥指杏花村。'},
    {t:'清明即事',a:'孟浩然〔唐代〕',c:'帝里重清明，人心自愁思。\n车声上路合，柳色东城翠。\n花落草齐生，莺飞蝶双戏。\n空堂坐相忆，酌茗聊代醉。'},
    {t:'清明辇下怀金陵',a:'王安石〔宋代〕',c:'春阴天气草如烟，时有飞花舞慢边。\n院落日长人寂寂，池塘风慢鸟翩翩。\n故园回首三千里，新火伤心六七年。\n青盖皂衫无复禁，可能乘兴酒家眠。'},
    {t:'清明日',a:'温庭筠〔唐代〕',c:'清娥画扇中，春树郁金红。\n出犯繁花露，归穿弱柳风。\n马骄偏避幰，鸡骇乍开笼。\n柘弹何人发，黄鹂隔故宫。'},
    {t:'清明日宴梅道士房',a:'孟浩然〔唐代〕',c:'林卧愁春尽，搴帷览物华。\n忽逢青鸟使，邀入赤松家。\n金灶初开火，仙桃正发花。\n童颜若可驻，何惜醉流霞。'},
    {t:'清明日忆诸弟',a:'韦应物〔唐代〕',c:'冷食方多病，开襟一忻然。终令思故郡，烟火满晴川。\n杏粥犹堪食，榆羹已稍煎。唯恨乖亲燕，坐度此芳年。'},
    {t:'清明谚语二则',a:'佚名',c:'春分有雨到清明，清明下雨无路行。\n清明时节天转暖，柳絮纷飞花争妍。'},
    {t:'清明夜',a:'白居易〔唐代〕',c:'好风胧月清明夜，碧砌红轩刺史家。\n独绕回廊行复歇，遥听弦管暗看花。'},
    {t:'清平调·其二',a:'李白〔唐代〕',c:'一枝秾艳露凝香，云雨巫山枉断肠。\n借问汉宫谁得似，可怜飞燕倚新妆。'},
    {t:'清平调·其三',a:'李白〔唐代〕',c:'名花倾国两相欢，长得君王带笑看。\n解释春风无限恨，沉香亭北倚阑干。'},
    {t:'清平调词三首',a:'李白〔唐代〕',c:'云想衣裳花想容，春风拂槛露华浓。\n若非群玉山头见，会向瑶台月下逢。\n一枝秾艳露凝香，云雨巫山枉断肠。\n借问汉宫谁得似，可怜飞燕倚新妆。\n名花倾国两相欢，长得君王带笑看。\n解释春风无限恨，沉香亭北倚阑干。'},
    {t:'清平乐',a:'张炎〔宋代〕',c:'兰曰国香，为哲人出，不以色香作炫，乃得天之清者也。楚子不作，兰今安在？得见所南翁枝上孤笔，斯可矣。赋此以纪情事云。\n孤花一叶，比似前时别。烟水茫茫无处说，冷却西湖残月。贞芳只合深山，红尘了不相关。留得许多清影，幽香不到人间。'},
    {t:'清平乐',a:'王安石〔宋代〕',c:'云垂平野。掩映竹篱茅舍。阒寂幽居实潇洒。是处绿娇红冶。\n丈夫运用堂堂。且莫五角六张。若有一卮芳酒，逍遥自在无妨。'},
    {t:'清平乐',a:'晏几道〔宋代〕',c:'春云绿处。又见归鸿去。侧帽风桂花满路。冶叶倡条情绪。\n红楼桂酒新开。曾携翠袖同来。醉弄影娥池水，短箫吹落残梅。'},
    {t:'清平乐',a:'晏几道〔宋代〕',c:'寒催酒醒。晓陌飞霜定。背照画才残烛影。斜月光中人静。\n锦衣才子西征。万重云水初程。翠黛倚门相送，莺肠断处难声。'},
    {t:'清平乐',a:'晏几道〔宋代〕',c:'沈思暗记。几许无凭事。菊靥开残秋少味。闲却画阑风意。\n梦云归处难寻。微凉暗入香襟。犹恨那回庭院，依前月浅灯深。'},
    {t:'清平乐',a:'晏几道〔宋代〕',c:'笙歌宛转。台上吴王宴。宫女如画倚春殿。舞绽缕金衣线。\n酒阑画烛低迷。彩鸳惊起双栖。月底三千绣户，云间十二琼梯。'},
    {t:'清平乐',a:'晏几道〔宋代〕',c:'双纹彩袖。笑捧金船酒。娇妙如花轻似柳。勤客千春长寿。\n艳歌更倚疏弦。有情须醉尊前。恰是可怜时候，玉娇今夜初圆。'},
    {t:'清平乐',a:'晏几道〔宋代〕',c:'莺来燕去。宋玉墙东路。草草幽秋能几度。便有系人心处。\n碧天秋月无端。别来长照关山。一点恹恹谁会，依前凭暖阑干。'},
    {t:'清平乐',a:'黄庭坚〔宋代〕',c:'舞鬟娟好。白发黄花帽。醉任旁观嘲潦倒。扶老偏宜年小。\n舞回脸玉胸酥。缠头一斛明珠。日日梁州薄媚，年年金菊茱萸。'},
    {t:'清平乐',a:'晏几道〔宋代〕',c:'幺弦写意。意密弦声碎。书得凤笺无限事。犹恨春心难寄。\n卧听疏雨梧桐。雨余淡月朦胧。一夜梦魂何处，那回杨叶楼中。'},
    {t:'清平乐·百花开後',a:'张炎〔宋代〕',c:'百花开後。一朵疑堆绣。绝色淡淡常似旧。因甚不随春瘦。脂痕淡约蜂黄。可怜独倚新妆。太白醉游何处，定应忘了沈香。'},
    {t:'清平乐·别苗仲通',a:'张炎〔宋代〕',c:'柳间花外。日日离人泪。忆得楼心和月醉。落叶与愁俱碎。\n如今一笑吴中。眼青犹认衰翁。先泛扁舟烟水，西湖多定相逢。'},
    {t:'清平乐·波纹碧皱',a:'晏几道〔宋代〕',c:'波纹碧皱，\n曲水清明后。\n折得疏梅香满袖，\n暗喜春红依旧。\n归来紫陌东头，\n金钗换酒消愁。\n柳影深深细路，\n花梢小小层楼。'},
    {t:'清平乐·博山道中即事',a:'辛弃疾〔宋代〕',c:'柳边飞鞚，露湿征衣重。宿鹭窥明孤影动，应有鱼虾入梦。\n一川明月疏星，浣纱人影娉婷。笑背行人归去，门前稚子啼声。'},
    {t:'清平乐·采芳人杳',a:'张炎〔宋代〕',c:'采芳人杳，顿觉游情少。客里看春多草草，总被诗愁分了。\n去年燕子天涯，今年燕子谁家？三月休听夜雨，如今不是催花。'},
    {t:'清平乐·沉思暗记',a:'晏几道〔宋代〕',c:'沉思暗记，\n几许无凭事。\n菊靥开残秋少味，\n闲却画栏风意。\n梦云归处难寻，\n微凉暗入香襟。\n犹恨寻回庭院，\n依前月浅灯深。'},
    {t:'清平乐·春归何处',a:'黄庭坚〔宋代〕',c:'春归何处？寂寞无行路。若有人踪春去处，唤取归来同住。\n春无踪迹谁踪？除非问取黄鹂。百啭无人能解，因风飞过蔷薇。'},
    {t:'清平乐·春花秋草',a:'晏殊〔宋代〕',c:'春花秋草，只是催人老。总把千山眉黛扫，未抵别愁多少。\n劝君绿酒金杯，莫嫌丝管声催。兔走乌飞不住，人生几度三台。'},
    {t:'清平乐·春来秋去',a:'晏殊〔宋代〕',c:'春来秋去。往事知何处？燕子归飞兰泣露。光景千留不住。\n酒阑人散忡忡。闲阶独倚梧桐。记得去年今日，依前黄叶西风。'},
    {t:'清平乐·春宵睡重',a:'辛弃疾〔宋代〕',c:'春宵睡重，梦里还相送。枕畔起寻双玉凤，半日才知是梦。\n一从卖翠人还，又无音信经年。却把泪来作水，流也流到伊边。'},
    {t:'清平乐·村居',a:'辛弃疾〔宋代〕',c:'茅檐低小，溪上青青草。醉里吴音相媚好，白发谁家翁媪？\n大儿锄豆溪东，中儿正织鸡笼。最喜小儿亡赖，溪头卧剥莲蓬。'},
    {t:'清平乐·弹琴峡题壁',a:'纳兰性德〔清代〕',c:'泠泠彻夜，谁是知音者。如梦前朝何处也，一曲边愁难写。\n极天关塞云中，人随落雁西风。唤取红襟翠袖，莫教泪洒英雄。'},
    {t:'清平乐·独宿博山王氏庵',a:'辛弃疾〔宋代〕',c:'绕床饥鼠，蝙蝠翻灯舞。屋上松塞吹急雨，破纸窗间自语。\n平生塞北江南，归来华发苍颜。布被秋宵梦觉，眼前万里江山。'},
    {t:'清平乐·发汉儿村题壁',a:'纳兰性德〔清代〕',c:'参横月落，客绪从谁托。望里家山云漠漠，似有红楼一角。\n不如意事年年，消磨绝塞风烟。输与五陵公子，此时梦绕花前。'},
    {t:'清平乐·繁华锦烂',a:'柳永〔宋代〕',c:'繁花锦烂。已恨归期晚。翠减红稀莺似懒。特地柔肠欲断。\n不堪尊酒频倾。恼人转转愁生，□□□□□□，多情争似无情。'},
    {t:'清平乐·风鬟雨鬓',a:'纳兰性德〔清代〕',c:'风鬟雨鬓，偏是来无准。倦倚玉吹看月晕，容易语低香近。\n软风吹遍窗纱，心期便隔天涯。从此伤春伤别，黄昏只对梨花。'},
    {t:'清平乐·孤花片叶',a:'纳兰性德〔清代〕',c:'孤花片叶，断送清秋节。寂寂绣散香篆灭，暗里朱颜消歇。\n谁怜散髻吹笙，天涯芳草关情。懊恼隔帘幽梦，半床花月纵横。'},
    {t:'清平乐·红笺小字',a:'晏殊〔宋代〕',c:'红笺小字，说尽平生意。鸿雁在云鱼在水，惆怅此情难寄。\n斜阳独倚西楼，遥山恰对帘钩。人面不知何处，绿波依旧东流。'},
    {t:'清平乐·红英落尽',a:'晏几道〔宋代〕',c:'红英落尽，\n未有相逢信。\n可恨流曾凋绿鬓，\n睡得春酲欲醒。\n钿筝曾醉西楼，\n朱弦玉指梁州。\n曲罢翠帘高卷，\n几回新月如钩。'},
    {t:'清平乐·候蛩凄断',a:'张炎〔宋代〕',c:'候蛩凄断，人语西风岸。月落沙平江似练，望尽芦花无雁。\n暗教愁损兰成，可怜夜夜关情。只有一枝梧叶，不知多少秋声！'},
    {t:'清平乐·画屏无睡',a:'纳兰性德〔清代〕',c:'画屏无睡，雨点惊风碎。贪话零星兰焰坠，闲了半床红被。\n生来柳絮飘零。便教咒也无灵。待问归期还未，已看双睫盈盈。'},
    {t:'清平乐·蕙心堪怨',a:'晏几道〔宋代〕',c:'蕙心堪怨，也逐春风转。丹杏墙东当日见，幽会绿窗题遍。\n眼中前事分明，可怜如梦难凭。都把旧时薄幸，只消今日无情。'},
    {t:'清平乐·检校山园书所见',a:'辛弃疾〔宋代〕',c:'断崖修竹，竹里藏冰玉。路转清溪三百曲，香满黄昏雪屋。\n行人系马疏篱，折残犹有高枝。留得东风数点，只缘娇嫩春迟。'},
    {t:'清平乐·将愁不去',a:'纳兰性德〔清代〕',c:'将愁不去，秋色行难住。六曲屏篱深院宇。日日风风雨雨。\n雨晴篱菊初香，人言此日重阳。回首凉云暮叶，黄昏无限思量。'},
    {t:'清平乐·角声哀咽',a:'纳兰性德〔清代〕',c:'角声哀咽，襆被驮残月。过去华冲如电掣，禁得番番离别。\n一鞭冲破黄埃，乱山影里徘徊。蓦忆去冲今日，十三陵下归来。'},
    {t:'清平乐·金风细细',a:'晏殊〔宋代〕',c:'金风细细。叶叶梧桐坠。绿酒初朱人易醉。一枕小窗浓睡。\n紫薇朱槿花残。斜阳却照阑干。双燕欲归时节，银屏昨夜微寒。'},
    {t:'清平乐·禁庭春昼',a:'李白〔唐代〕',c:'禁庭春昼，莺羽披新绣。百草巧求花下斗，只赌珠玑满斗。\n日晚却理残妆，御前闲舞霓裳。谁道腰肢窈窕，折旋笑得君王。'},
    {t:'清平乐·可怜娇小',a:'晏几道〔宋代〕',c:'可怜娇小，\n掌上承恩早。\n把镜不知人易老，\n欲占朱颜长好。\n画堂秋月佳期，\n藏钩赌酒归迟。\n红烛泪前低语，\n绿笺花里新词。'},
    {t:'清平乐·莲开欲遍',a:'晏几道〔宋代〕',c:'莲开欲遍，\n一夜秋声转。\n残绿断红香片片，\n长是西风堪怨。\n莫愁家住溪边，\n采莲心事年年。\n谁管水流花谢，\n月明昨夜兰船。'},
    {t:'清平乐·留人不住',a:'晏几道〔宋代〕',c:'留人不住，醉解兰舟去。一棹碧杨春水路，过尽晓莺啼处。\n渡头杨柳青青，枝枝叶叶离情。此后锦书休寄，画楼云雨无凭。'},
    {t:'清平乐·洛阳愁绝',a:'温庭筠〔唐代〕',c:'洛阳愁绝，杨柳花飘雪。终日行人恣攀折，桥下水流呜咽。\n上马争劝离觞，南浦莺声断肠。愁杀平原年少，回首挥泪千行。'},
    {t:'清平乐·平原放马',a:'张炎〔宋代〕',c:'辔摇衔铁。蹴踏平原雪。勇趁军声曾汗血。闲过升平时节。\n茸茸春草天涯。涓涓野水晴沙。多少骅骝老去，至今犹困盐车。'},
    {t:'清平乐·凄凄切切',a:'纳兰性德〔清代〕',c:'凄凄切切，惨淡黄花节。梦里砧燕浑未歇，那更乱蛩悲咽。\n尘生燕子空楼，抛残弦索床头。一样晓风残月，而今触绪添愁。'},
    {t:'清平乐·千花百草',a:'晏几道〔宋代〕',c:'千花百草。送得春归了。拾蕊人稀红渐少。叶底杏青梅小。\n小琼闲抱琵琶。雪香微透轻纱。正好一枝娇艳，当筵独占韶华。'},
    {t:'清平乐·青陵蝶梦',a:'纳兰性德〔清代〕',c:'青陵蝶梦，倒挂怜么凤。退粉收镜情一种，栖傍玉钗偷共。\n愔愔镜阁飞蛾，谁传锦字秋河？莲子依然隐雾，菱花暗惜横波。'},
    {t:'清平乐·秋词',a:'苏轼〔宋代〕',c:'清淮浊汴。更在江西岸。红旆到时黄叶乱。霜入梁王故苑。\n秋原何处携壶。停骖访古踟蹰。双庙遗风尚在，漆园傲吏应无。'},
    {t:'清平乐·秋光向晚',a:'晏殊〔宋代〕',c:'秋光向晚，小阁初开宴。林叶殷劝犹未遍。雨后青苔满院。\n萧娘劝我金卮，殷勤更唱新词。暮去朝来即老，人生不饮何为。'},
    {t:'清平乐·塞鸿去矣',a:'纳兰性德〔清代〕',c:'塞鸿去矣，锦字何时寄。记得灯几佯忍泪，却问明朝行未。\n别来几度如珪，飘零落叶成堆。一种晓寒浅梦，凄凉毕竟因谁。'},
    {t:'清平乐·上阳春晚',a:'温庭筠〔唐代〕',c:'上阳春晚，宫女愁蛾浅。新岁清鸳思同辇，争奈长安路远。\n凤帐鸳被徒熏，寂寞花琐千门。竞把黄金买赋，为妾将上明君。'},
    {t:'清平乐·上元月蚀',a:'纳兰性德〔清代〕',c:'瑶华映阙，烘散蓂墀雪。比拟寻常清景别，第一团圆时节。\n影娥忽泛初弦，分辉借与宫莲。七宝修成合璧，重轮岁岁中天。'},
    {t:'清平乐·麝烟深漾',a:'纳兰性德〔清代〕',c:'麝烟深漾，人拥缑笙氅。新恨暗随新月长，不辨眉尖心上。\n六花斜扑疏帘，地衣红锦轻沾。记取暖香如梦，耐他一晌寒严。'},
    {t:'清平乐·题处梅家藏所南翁画兰',a:'张炎〔宋代〕',c:'黑云飞起。夜月啼湘鬼。魂返灵根无二纸。千古不随流水。\n香心淡染清华。似花还似非花。要与闲梅相处，孤山山下人家。'},
    {t:'清平乐·题倦耕图',a:'张炎〔宋代〕',c:'一犁初卸。息影斜阳下。角上汉草何不挂。老子近来慵跨。\n烟村草树离离。卧看流水忘归。莫饮山中清味，怕教洗耳人知。'},
    {t:'清平乐·题墨仙双清图',a:'张炎〔宋代〕',c:'丹丘瑶草。不许秋风扫。记得对花曾被恼。犹似前时春好。\n湘皋闲立双清。相看波冷无声。独说长生未老，不知老却梅兄。'},
    {t:'清平乐·题平沙落雁图',a:'张炎〔宋代〕',c:'平沙流水。叶老芦花未。落雁无记还有字。一片潇湘古意。\n扁舟记得幽寻。相寻只在□□。莫趁春风飞去，玉关夜雪犹深。'},
    {t:'清平乐·题上卢桥',a:'辛弃疾〔宋代〕',c:'清溪奔快，不管青山碍。十里盘盘平世界，更著溪山襟带。\n古今陵谷茫茫，市朝往往耕桑。此地居然形胜，似曾小小兴亡。'},
    {t:'清平乐·为儿铁柱作',a:'辛弃疾〔宋代〕',c:'灵皇醮罢，福禄都来也。试引鹓雏花树下，断了惊惊怕怕。\n从今日日聪明。更宜潭妹嵩兄。看取辛家铁柱，无灾无难公卿。'},
    {t:'清平乐·西池烟草',a:'晏几道〔宋代〕',c:'西池烟草，恨不寻芳早。满路落花红不扫，春色渐随人老。\n远山眉黛娇长，清歌细逐霞觞。正在十洲残梦，水心宫殿斜阳。'},
    {t:'清平乐·谢叔良惠木犀',a:'辛弃疾〔宋代〕',c:'少年痛饮，忆向吴江醒。明月团团高树影，十里水沉烟冷。\n大都一点宫黄，人间直恁芬芳。怕是秋天风露，染教世界都香。'},
    {t:'清平乐·烟轻雨小',a:'纳兰性德〔清代〕',c:'烟轻雨小，望里青难了。一缕断虹垂树杪，又是乱山残照。\n凭高目断征途，暮云千里平芜。日夜河流东下，锦书应托双鱼。'},
    {t:'清平乐·烟轻雨小',a:'晏几道〔宋代〕',c:'烟轻雨小。紫陌香尘少。谢客池塘生绿草。一夜红梅先老。\n旋题罗带新诗。重寻杨柳佳期。强半春寒去后，几番花信来时。'},
    {t:'清平乐·烟深水阔',a:'李白〔唐代〕',c:'烟深水阔，音信无由达。唯有碧天云外月，偏照悬悬离别。\n尽日感事伤怀，愁眉似锁难开。夜夜长留半被，待君魂梦归来。'},
    {t:'清平乐·忆梁汾',a:'纳兰性德〔清代〕',c:'才听夜雨，便觉秋如许。绕砌蛩螿人不语，有梦转愁无据。\n乱山千叠横江，忆君游倦何方。知否小窗红烛。照人此夜凄凉。'},
    {t:'清平乐·暂来还去',a:'晏几道〔宋代〕',c:'暂来还去，轻似风头絮。纵得相逢留不住，何况相逢无处。\n去时约略黄昏，月华却到朱门。别后几番明月，素娥应是消魂。'},
    {t:'清平乐·赠处梅',a:'张炎〔宋代〕',c:'暗香千树。结屋中间住。明月一隔流水护。梦入梨云深处。\n清冰隔断尘埃。无人踏碎苍苔。一似逋仙归后，吟诗不下山来。'},
    {t:'清平乐令·帘卷曲阑独倚',a:'佚名〔宋代〕',c:'帘卷曲阑独倚，江展暮天无际。泪眼不曾晴，家在吴头楚尾。\n数点雪花乱委，扑鹿沙鸥惊起。诗句欲成时，没入苍烟丛里。'},
    {t:'清商怨·葭萌驿作',a:'陆游〔宋代〕',c:'江头日暮痛饮，乍雪晴犹凛。山驿凄凉，灯昏人独寝。\n鸳机新寄断锦，叹往事、不堪重省。梦破南楼，绿云堆一枕。'},
    {t:'清商怨·庭花香信尚浅',a:'晏几道〔宋代〕',c:'庭花香信尚浅，最玉楼先暖。梦觉春衾，江南依旧远。\n回纹锦字暗剪，谩寄与、也应归晚。要问相思，天涯犹自短。'},
    {t:'清溪半夜闻笛',a:'李白〔唐代〕',c:'羌笛梅花引，吴溪陇水情。\n寒山秋浦月，肠断玉关声。'},
    {t:'清溪行',a:'李白〔唐代〕',c:'清溪清我心，水色异诸水。\n借问新安江，见底何如此。\n人行明镜中，鸟度屏风里。\n向晚猩猩啼，空悲远游子。'},
    {t:'庆春宫',a:'张炎〔宋代〕',c:'蟾窟研霜，蜂房点蜡，一枝曾伴到宵。清气初生，丹心未折，浓艳到此都消。避风归去，贮金屋、妆与汉娇。栗肌微润，和露吹香，直与秋高。小山旧隐重招。记得相逢，古道迢遥。把酒长歌，插花短舞，谁在水国吹箫。馀音何处，看万里、星河动摇。广庭人散，月淡天心，鹤下银桥。'},
    {t:'庆春宫·亦京洛旧事也',a:'张炎〔宋代〕',c:'都下寒食，游人甚盛，水边花外，多丽环集。各以柳圈祓禊而去，亦京洛旧事也。\n波荡兰觞，邻分杏酪，昼辉冉冉烘晴。罥索飞仙，戏船移景，薄游也自忺人。短桥虚市，听隔柳、谁家卖饧。月题争系，油壁相连，笑语逢迎。\n池亭小队秦筝。就地围香，临水湔裙。冶态飘云，醉妆扶玉，未应闲了芳情。旅怀无限，忍不住、低低问春。梨花落尽，一点新愁，曾到西泠。'},
    {t:'庆春宫·云接平冈',a:'周邦彦〔宋代〕',c:'云接平冈，山围寒野，路回渐转一城。衰柳啼鸦，惊风驱雁，动人一片秋声。倦途休驾，淡烟里、微思见星。尘埃憔悴，生怕黄昏，离思牵萦。\n华堂旧日逢迎。花艳参差，香雾飘零。弦管当头，偏怜娇凤，夜深簧暖笙清。眼波传意，恨密约、匆匆未成。许多烦恼，只为当时，一饷留情。'},
    {t:'庆春时',a:'晏几道〔宋代〕',c:'梅梢已有，春来音信，风意犹寒。南楼暮雪，无人共赏，闲却玉阑干。\n殷勤今夜，凉月还似眉弯。尊前为把，桃根丽曲，重倚四弦看。'},
    {t:'庆春时',a:'晏几道〔宋代〕',c:'倚天楼殿，升平风月，彩仗春移。归丝凤竹，长生调里，迎得翠舆归。\n雕鞍游罢，何处还有心期。浓熏翠被，深停画烛，人约月西时。'},
    {t:'庆清朝',a:'张炎〔宋代〕',c:'竹，散怀吟眺，一任所适。太白去后三百年，无此乐也。\n浅草犹霜。融泥未燕，晴梢润叶初干。闲扶短策，邻家小聚清欢。错认篱根是雪，梅花过了一番寒。风还峭，较迟芳信，恰是春残。\n此境此时此意，待移琴独去，石冷慵弹。飘飘爽气，飞鸟相与俱还。醉里不知何处，好诗尽在夕阳山。山深杳，更无人到，流水花间。'},
    {t:'庆云章',a:'陈子昂〔唐代〕',c:'昆仑元气，实生庆云。大人作矣，五色氤氲。昔在帝妫，\n南风既薰。丛芳烂熳，郁郁纷纷。旷矣千祀，庆云来止，\n玉叶金柯，祚我天子。非我天子，庆云谁昌。非我圣母，\n庆云谁光。庆云光矣，周道昌矣。九万八千，天授皇年。'},
    {t:'庆张君俞都尉留後得子',a:'秦观〔宋代〕',c:'天上吹箫玉作楼，蟠桃熟後更无忧。\n内家报喜车凌晓，太史占祥斗挂秋。\n龙得一珠应献佛，虎生三日便吞牛。\n鲁元福禄何人似，坐见张敖数子侯。'},
    {t:'丘中春卧寄王子',a:'岑参〔唐代〕',c:'田中开白室，林下闭玄关。卷迹人方处，无心云自闲。\n竹深喧暮鸟，花缺露春山。胜事那能说，王孙去未还。'},
    {t:'丘子野表兄郊园五咏其四芭蕉',a:'朱熹〔宋代〕',c:'芭蕉值秋槛，勿云憔悴姿。与君障夏日，羽扇宁复持。'},
    {t:'秋波媚·曾散天花蕊珠宫',a:'陆游〔宋代〕',c:'曾散天花蕊珠宫。一念堕尘中。铅华洗尽，珠玑不御，道骨仙风。\n东游我醉骑鲸去，君驾素鸾从。垂虹看月，天台采药，更与谁同。'},
    {t:'秋词二首',a:'刘禹锡〔唐代〕',c:'自古逢秋悲寂寥，我言秋日胜情朝。\n晴空一鹤排云上，便引诗情到碧霄。\n山明水净夜来霜，数树深红出浅黄。\n试上高楼清入骨，岂如情色嗾人狂。'},
    {t:'秋词二首',a:'秦观〔宋代〕',c:'无数青莎绕玉阶，夕阳红浅过墙来。\n西风莫道无情思，未放芙蓉取次开。'},
    {t:'秋登兰山寄张五',a:'孟浩然〔唐代〕',c:'北山白云里，隐者自怡悦。\n相望试登高，心随雁飞灭。\n愁因薄暮起，兴是清秋发。\n时见归村人，沙行渡头歇。\n天边树若荠，江畔洲如月。\n何当载酒来，共醉重阳节。'},
    {t:'秋登宣城谢朓北楼',a:'李白〔唐代〕',c:'江城如画里，山晚望晴空。\n两水夹明镜，双桥落彩虹。\n人烟寒橘柚，秋色老梧桐。\n谁念北楼上，临风怀谢公。'},
    {t:'秋登张明府海亭',a:'孟浩然〔唐代〕',c:'海亭秋日望，委曲见江山。染翰聊题壁，倾壶一解颜。\n歌逢彭泽令，归赏故园间。予亦将琴史，栖迟共取闲。'},
    {t:'秋分後顿凄冷有感',a:'陆游〔宋代〕',c:'今年秋气早，木落不待黄，蟋蟀逝在宇，遽已近我床。\n况我老逝逝，且复小彷徉。\n岂无一樽酒，亦有书在傍。\n饮酒读古书，慨然想黄唐。\n耄矣狂未除，谁能药膏肓。'},
    {t:'秋风引',a:'刘禹锡〔唐代〕',c:'何处秋风至？萧萧送雁群。\n朝来入庭树，孤客最先闻。'},
    {t:'秋感',a:'杜牧〔唐代〕',c:'金风万里思何尽，玉树一窗秋影寒。\n独掩柴门明月下，泪流香袂倚阑干。'},
    {t:'秋怀',a:'张九龄〔唐代〕',c:'感惜芳时换，谁知客思悬。忆随鸿向暖，愁学马思边。\n留滞机还息，纷拏网自牵。东南起归望，何处是江天。'},
    {t:'秋怀二首',a:'黄庭坚〔宋代〕',c:'秋阴细细压茅堂，吟虫啾啾昨簹凉。\n雨开芭蕉新间旧，风撼篔簹宫应商。\n砧声已急不可缓，檐角既短难为长。\n狐裘断缝弃墙角，岂念晏岁多繁霜。\n茅堂索索秋风发，行遶空庭紫苔滑。\n蛙号池上晚来雨，鹊转南枝簹深月。\n翻手覆手不可期，一死一生交道绝。\n湖水无端浸白云，故人书断孤鸿没。'},
    {t:'秋怀二首其二',a:'朱熹〔宋代〕',c:'怀痾坐竟日，晚色散幽树。寂历候虫悲，沆瀁碧草露。\n端居兴方澹，沉默自成趣。羽觞欢独持，瑶琴谁与晤。\n空知玄思清，未惜年华度。美人殊不来，岁月恐迟暮。'},
    {t:'秋怀其八',a:'孟郊〔唐代〕',c:'岁暮景气乾，秋风兵甲声。织织劳无衣，喓喓徒自鸣。\n商声耸中夜，蹇支废前行。青发如秋园，一剪不复生。\n少年如饿花，瞥见不复明。君子山岳定，小人丝毫争。\n多争多无寿，天道戒其盈。'},
    {t:'秋怀其九',a:'孟郊〔唐代〕',c:'冷露多瘁索，枯风晓吹嘘。秋深月清苦，虫老声粗疏。\n赪珠枝累累，芳金蔓舒舒。草木亦趣时，寒荣似春馀。\n悲彼零落生，与我心何如。'},
    {t:'秋怀其四',a:'孟郊〔唐代〕',c:'秋至老更贫，破屋无门扉。一片远落床，四壁风入衣。\n疏梦不复远，弱心良易归。商葩将去绿，缭绕争馀辉。\n野步踏事少，病谋向物违。幽幽草根虫，生意与我微。'},
    {t:'秋怀四首·其二',a:'陆游〔宋代〕',c:'园丁傍架摘黄瓜，村女沿篱采碧花。\n城市尚余三伏热，秋光先到野人家。'},
    {t:'秋霁寄远',a:'杜牧〔唐代〕',c:'初霁独登赏，西楼多远风。\n横烟秋水上，疏雨夕阳中。\n高树下山鸟，平芜飞草虫。\n唯应待明月，千里与君同。'},
    {t:'秋江送客',a:'白居易〔唐代〕',c:'秋鸿次第过，哀猿朝夕闻。\n是日孤舟客，此地亦离群。\n濛濛润衣雨，漠漠冒帆云。\n不醉浔阳酒，烟波愁杀人。'},
    {t:'秋江晚泊',a:'刘禹锡〔唐代〕',c:'长泊起秋色，空江涵霁晖。\n暮霞千万状，宾鸿次第飞。\n古戍见旗迥，荒村闻犬稀。\n轲峨艑上客，劝酒夜相依。'},
    {t:'秋郊作',a:'韦应物〔唐代〕',c:'清露澄境远，旭日照林初。一望秋山净，萧条形迹疏。\n登原忻时稼，采菊行故墟。方愿沮溺耦，淡泊守田庐。'},
    {t:'秋景诣琅琊精舍',a:'韦应物〔唐代〕',c:'屡访尘外迹，未穷幽赏情。高秋天景远，始见山水清。\n上陟岩殿憩，暮看云壑平。苍茫寒色起，迢递晚钟鸣。\n意有清夜恋，身为符守婴。悟言缁衣子，萧洒中林行。'},
    {t:'秋来',a:'李贺〔唐代〕',c:'桐风惊心壮士苦，衰灯络纬啼寒素。\n谁看青简一编书，不遣花虫粉空蠹。\n思牵今夜肠应直，雨冷香魂吊书客。\n秋坟鬼唱鲍家诗，恨血千年土中碧。'},
    {t:'秋凉诗，寄正字十二兄',a:'李贺〔唐代〕',c:'闭门感秋风，幽姿任契阔。大野生素空，天地旷肃杀。\n露光泣残蕙，虫响连夜发。房寒寸辉薄，迎风绛纱折。\n披书古芸馥，恨唱华容歇。百日不相知，花光变凉节。\n弟兄谁念虑，笺翰既通达。青袍度白马，草简奏东阙。\n梦中相聚笑，觉见半床月。长思剧寻环，乱忧抵覃葛。'},
    {t:'秋凉晚步',a:'杨万里〔宋代〕',c:'秋气堪悲未必然，轻寒正是可人天。\n绿池落尽红蕖却，荷叶犹开最小钱。'},
    {t:'秋梦',a:'杜牧〔唐代〕',c:'寒空动高吹，月色满清砧。\n残梦夜魂断，美人边思深。\n孤鸿秋出塞，一叶暗辞林。\n又寄征衣去，迢迢天外心。'},
    {t:'秋圃',a:'杨万里〔宋代〕',c:'何处秋深好，山林处士家。\n青霜红碧树，白露紫黄花。\n一熟雠频雨，朝晴祷暮霞。\n连霄眠不著，犹自爱新茶。'},
    {t:'秋浦感主人归燕寄内',a:'李白〔唐代〕',c:'霜凋楚关木，始知杀气严。\n寥寥金天廓，婉婉绿红潜。\n胡燕别主人，双双语前檐。\n三飞四回顾，欲去复相瞻。\n岂不恋华屋，终然谢珠帘。\n我不及此鸟，远行岁已淹。\n寄书道中叹，泪下不能缄。'},
    {t:'秋浦歌十七首·其十四',a:'李白〔唐代〕',c:'炉火照天地，红星乱紫烟。\n赧郎明月夜，歌曲动寒川。'},
    {t:'秋浦歌十七首·十五',a:'李白〔唐代〕',c:'白发三千丈，缘愁似个长。\n不知明镜里，何处得秋霜。'},
    {t:'秋浦途中',a:'杜牧〔唐代〕',c:'萧萧山路穷秋雨，淅淅溪风一岸蒲。\n为问寒沙新到雁，来时还下杜陵无。'},
    {t:'秋日',a:'温庭筠〔唐代〕',c:'爽气变昏旦，神皋遍原隰。烟华吠荡摇，石涧仍清急。\n柳暗山犬吠，蒲荒水禽立。菊花明欲迷，枣都光如湿。\n天籁思林岭，车尘倦都邑。譸张夙所违，悔吝何由入。\n芳草秋可藉，幽泉晓堪汲。牧羊烧外鸣，林果雨中拾。\n复此遂闲旷，翛然脱羁絷。田收鸟雀喧，气肃龙蛇蛰。\n佳节足丰穰，良朋阻游集。沉机日寂寥，葆素常呼吸。\n投迹倦攸往，放怀志所执。良时有东菑，吾将事蓑笠。'},
    {t:'秋日',a:'杜牧〔唐代〕',c:'有计自安业，秋风罢远吟。买山惟种竹，对客更弹琴。\n烟起药厨晚，杵声松院深。闲眠得真性，惆怅旧时心。'},
    {t:'秋日',a:'朱熹〔宋代〕',c:'一雨生凉杜若洲，月波微漾绿溪流。茅檐归去无尘土，淡薄闲花绕舍秋。'},
    {t:'秋日旅舍寄义山李侍御',a:'温庭筠〔唐代〕',c:'一水悠悠隔渭城，渭城风物近来荆。寒蛩乍响催机杼，\n旅雁初来忆弟兄。自为林泉牵晓梦，不关砧杵报秋声。\n子虚何处堪消渴，试向文园问长卿。'},
    {t:'秋日偶题',a:'杜牧〔唐代〕',c:'荷花兼柳叶，彼此不胜秋。\n玉露滴初泣，金风吹更愁。\n绿眉甘弃坠，红脸恨飘流。\n叹息是游子，少年还白头。'},
    {t:'秋日陪李侍御渡松滋江',a:'孟浩然〔唐代〕',c:'南纪西江阔，皇华御史雄。截流宁假楫，挂席自生风。\n僚寀争攀鹢，鱼龙亦避骢。坐听白雪唱，翻入棹歌中。'},
    {t:'秋日毗陵南寺送潘述之扬州',a:'皎然〔唐代〕',c:'孤客秋易伤，嘶蝉静仍续。佳晨亦已屡，欢会常不足。\n禅地非路岐，我心岂羁束。情生远别时，坐恨清景促。\n望中千里隔，暮归西山曲。萧条月中道，彩蒨原上绿。\n不见同心人，幽怀增踯躅。'},
    {t:'秋日三首',a:'秦观〔宋代〕',c:'霜落邗沟积水清，寒星无数傍船明。\n菰蒲深处疑无地，忽有人家笑语声。\n月团新碾瀹花瓷，饮罢呼儿课楚词。\n风定小轩无落叶，青虫相对吐秋丝。\n连卷雌霓小西楼，逐雨追晴意未休。\n安得万妆相向舞，酒酣聊把作缠头。'},
    {t:'秋日书怀寄河南王尹',a:'刘禹锡〔唐代〕',c:'公府想无事，西池秋水清。去年为狎客，永日奉高情。\n况有台上月，如闻云外笙。不知桑落酒，今岁与谁倾。'},
    {t:'秋日送客至潜水驿',a:'刘禹锡〔唐代〕',c:'候吏立沙际，田家连竹溪。\n枫林社日鼓，茅屋午时鸡。\n鹊噪晚禾地，蝶飞秋草畦。\n驿楼宫树近，疲马再三嘶。'},
    {t:'秋日题窦员外崇德里新居',a:'刘禹锡〔唐代〕',c:'长爱街西风景闲，到君居处暂开颜。\n清光门外一渠水，秋色墙头数点山。\n疏种碧松通月朗，多栽红药待春还。\n莫言堆案无馀地，认得诗人在此间。'},
    {t:'秋日闻蝉',a:'陆游〔宋代〕',c:'断角斜阳触处愁，长亭搔首晚悠悠。\n世间最是蝉堪恨，送尽行人更送秋。'},
    {t:'秋日作',a:'高适〔唐代〕',c:'端居值秋节，此日更愁辛。寂寞无一事，蒿莱通四邻。\n闭门生白发，回首忆青春。岁月不相待，交游随众人。\n云霄何处托，愚直有谁亲。举酒聊自劝，穷通信尔身。'},
    {t:'秋蕊香·池苑清阴欲就',a:'晏几道〔宋代〕',c:'池苑清阴欲就。还傍送春时候。眼中人去难欢偶。谁共一杯芳酒。\n朱阑碧砌皆如旧。记携手。有情不管别离久。情在相逢终有。'},
    {t:'秋蕊香·歌彻郎君秋草',a:'晏几道〔宋代〕',c:'歌彻郎君秋草。别恨远山眉小。无情莫把多情恼。第一归来须早。\n红尘自古长安道。故人少。相思不比相逢好。此别朱颜应老。'},
    {t:'秋蕊香·梅蕊雪残香瘦',a:'晏殊〔宋代〕',c:'梅蕊雪残香瘦。罗幕轻寒微透。多情只似春杨柳。占断可怜时候。\n萧娘劝我杯中酒。翻红袖。金乌玉兔长飞走。争得朱颜依旧。'},
    {t:'秋蕊香·双调',a:'周邦彦〔宋代〕',c:'乳鸭池塘水暖。风紧柳花迎面。午妆粉指印窗眼。曲里长眉翠浅。\n问知社日停针线。探新燕。宝钗落枕春梦远。帘影参差满院。'},
    {t:'秋蕊香·向晓雪花呈瑞',a:'晏殊〔宋代〕',c:'向晓雪花呈瑞。飞遍玉城瑶砌。何人剪碎天边桂。散作瑶田琼蕊。\n萧娘敛尽双蛾翠。回香袂。今朝有酒今朝醉。遮莫更长无睡。'},
    {t:'秋蕊香引·留不得',a:'柳永〔宋代〕',c:'留不得。光阴催促，奈芳兰歇，好验谢，惟顷刻。彩云易散琉璃脆，验前事端的。\n风月夜，几处前踪旧迹。忍思忆。这回望断，永作终天隔。向仙岛，归冥路，两无消息。'},
    {t:'秋山',a:'张籍〔唐代〕',c:'秋山无云复无风，溪头看月出深松。\n草堂不闭石床静，叶间坠露声重重。'},
    {t:'秋山二首·其二',a:'杨万里〔宋代〕',c:'休道秋山索莫人，四时各自一番新。\n西风尽有东风手，柿叶枫林别样春。'},
    {t:'秋山二首·其一',a:'杨万里〔宋代〕',c:'乌臼平生老染工，错将铁皂作猩红。\n小枫一夜偷天酒，却倩孤松掩醉容。'},
    {t:'秋山寄陈谠言',a:'王昌龄〔唐代〕',c:'岩间寒事早，众山木已黄。北风何萧萧，兹夕露为霜。\n感激未能寐，中宵时慨慷。黄虫初悲鸣，玄鸟去我梁。\n独卧时易晚，离群情更伤。思君若不及，鸿雁今南翔。'},
    {t:'秋山秋雨蚤作有叹',a:'杨万里〔宋代〕',c:'梧叶新黄柿叶红，更兼乌桕与丹枫。\n只言山色秋萧索，绣出西湖三四峰。'},
    {t:'秋扇词',a:'刘禹锡〔唐代〕',c:'莫道恩情无重来，人间荣谢递相催。\n当时初入君怀袖，岂念寒炉有死灰。'},
    {t:'秋声',a:'陆游〔宋代〕',c:'人言悲剑难为情，我喜枕上闻剑声。\n快鹰下韝爪觜健，壮士抚剑精神生。\n我亦奋迅起衰病，唾成便有擒胡兴，\n弦开雁落诗亦成，笔力未饶弓力劲。\n五原草枯苜蓿空，青海萧萧风卷蓬，\n草罢捷书重上马，却从銮驾下辽东。'},
    {t:'秋思',a:'陆游〔宋代〕',c:'利欲驱人万火牛，江湖浪迹一沙鸥。\n日长似岁闲方觉，事大如天醉亦休。\n砧杵敲残深巷月，井梧摇落故园秋。\n欲舒老眼无高处，安得元龙百尺楼。'},
    {t:'秋思',a:'李白〔唐代〕',c:'春阳如昨日，碧树鸣黄鹂。\n芜然蕙草暮，飒尔凉风吹。\n天秋木叶下，月冷莎鸡悲。\n坐愁群芳歇，白露凋华滋。'},
    {t:'秋思',a:'杜牧〔唐代〕',c:'热去解钳釱，飘萧秋半时。微雨池塘见，好风襟袖知。\n发短梳未足，枕凉闲且欹。平生分过此，何事不参差。'},
    {t:'秋思',a:'张籍〔唐代〕',c:'洛阳城里见秋风，欲作家书意万重。\n复恐匆匆说不尽，行人临发又开封。'},
    {t:'秋思',a:'岑参〔唐代〕',c:'那知芳岁晚，坐见寒叶堕。\n吾不如腐草，翻飞作萤火。'},
    {t:'秋思·乌桕微丹菊渐开',a:'陆游〔宋代〕',c:'乌桕微丹菊渐开，天高风送雁声哀。\n诗情也似并刀快，剪得秋光入卷来。'},
    {t:'秋思寄子由',a:'黄庭坚〔宋代〕',c:'黄落山川知晚秋，小虫催女献功裘。\n老松阅世卧云壑，挽著沧江无万牛。'},
    {t:'秋晚登城北门',a:'陆游〔宋代〕',c:'幅巾藜杖北城头，卷地西风满带愁。\n一点烽传散关信，两行雁带杜陵秋。\n山河兴废供搔首，身世安危入倚楼。\n横槊赋诗非复昔，梦魂犹绕古梁州。'},
    {t:'秋晚登楼望南江入始兴郡路',a:'张九龄〔唐代〕',c:'潦收沙衍出，霜降天宇晶。\n伏槛外长眺，津途多远情。\n思来江山外，望尽烟云生。\n滔滔不自辨，华华且何成。\n我来飒衰鬓，孰云飘华缨。\n枥马苦踡跼，笼禽念遐征。\n岁阴向晼晚，日夕空屏营。\n物生贵得性，身累由近名。\n内顾觉今是，追叹何时平。'},
    {t:'秋晚怀茅山石涵村舍',a:'杜牧〔唐代〕',c:'十亩山田近石涵，村居风俗旧曾谙。\n帘前白艾惊春燕，篱上青桑待晚蚕。\n云暖采茶来岭北，月明沽酒过溪南。\n陵阳秋尽多归思，红树萧萧覆碧潭。'},
    {t:'秋晚江上遣怀',a:'杜牧〔唐代〕',c:'孤舟天际外，去路望中赊。贫病远行客，梦魂多在家。\n蝉吟秋色树，鸦噪夕阳沙。不拟彻双鬓，他方掷岁华。'},
    {t:'秋晚宿破山寺',a:'皎然〔唐代〕',c:'秋风落叶满空山，古寺残灯石壁间。\n昔日经行人去尽，寒云夜夜自飞还。'},
    {t:'秋晚新晴夜月如练有怀乐天',a:'刘禹锡〔唐代〕',c:'雨歇晚霞明，风调夜景清。\n月高微晕散，云薄细鳞生。\n露草百虫思，秋林千叶声。\n相望一步地，脉脉万重情。'},
    {t:'秋夕',a:'杜牧〔唐代〕',c:'银烛秋光冷画屏，轻罗小扇扑流萤。\n天阶夜色凉如水，卧看牵牛织女星。'},
    {t:'秋夕',a:'白居易〔唐代〕',c:'叶声落如雨，月色白似霜。\n夜深方独卧，谁为拂尘床。'},
    {t:'秋夕不寐寄乐天',a:'刘禹锡〔唐代〕',c:'洞户夜帘卷，华堂秋簟清。萤飞过池影，蛩思绕阶声。\n老枕知将雨，高窗报欲明。何人谙此景，远问白先生。'},
    {t:'秋夕读书幽兴献兵部李侍郎',a:'岑参〔唐代〕',c:'年纪蹉跎四十强，自怜头白始为郎。\n雨滋苔藓侵阶绿，秋飒梧桐覆井黄。\n惊蝉也解求高树，旅雁还应厌后行。\n览卷试穿邻舍壁，明灯何惜借余光。'},
    {t:'秋夕旅怀',a:'李白〔唐代〕',c:'凉风度秋海，吹我乡思飞。\n连山去无际，流水何时归。\n目极浮云色，心断明月晖。\n芳草歇柔艳，白露催寒衣。\n梦长银汉落，觉罢天星稀。\n含悲想旧国，泣下谁能挥。'},
    {t:'秋夕贫居述怀',a:'孟郊〔唐代〕',c:'卧冷无远梦，听秋酸别情。高枝低枝风，千叶万叶声。\n浅井不供饮，瘦田长废耕。今交非古交，贫语闻皆轻。'},
    {t:'秋夕听罗山人弹三峡流泉',a:'岑参〔唐代〕',c:'皤皤岷山老，抱琴鬓苍然。\n衫袖半玉徽，为弹三峡泉。\n此曲弹未半，高堂如空山。\n石林何飕飗，忽潺窗户间。\n绕指弄呜咽，青丝激潺湲。\n演漾怨楚云，虚徐韵秋烟。\n疑兼阳台雨，似杂巫山猿。\n幽引鬼神听，净令耳目便。\n楚客肠欲断，湘妃泪斑斑。\n谁裁青桐枝，縆以朱丝弦。\n能含古人曲，递与今人传。\n知音难再逢，惜君方年老。\n曲终月已落，惆怅东斋眠。'},
    {t:'秋夕望月',a:'张九龄〔唐代〕',c:'清迥江城月，流光万里同。\n所思如梦里，相望在庭中。\n皎洁青苔露，萧条黄叶风。\n含情不得语，频使桂华空。'},
    {t:'秋下荆门',a:'李白〔唐代〕',c:'霜落荆门江树空，布帆无恙挂秋风。\n此行不为鲈鱼鲙，自爱名山入剡中。'},
    {t:'秋相望',a:'元稹〔唐代〕',c:'檐月惊残梦，浮凉满夏衾。蟏蛸低户网，萤火度墙阴。\n炉暗灯光短，床空帐影深。此时相望久，高树忆横岑。'},
    {t:'秋宵书事寄吴凭处士',a:'皎然〔唐代〕',c:'真性在方丈，寂寥无四邻。秋天月色正，清夜道心真。\n大梦观前事，浮名悟此身。不知庭树意，荣落感何人。'},
    {t:'秋宵月下有怀',a:'孟浩然〔唐代〕',c:'秋空明月悬，光彩露沾湿。\n惊鹊栖未定，飞萤卷帘入。\n庭槐寒影疏，邻杵夜声急。\n佳期旷何许，望望空伫立。'},
    {t:'秋晓行南谷经荒村',a:'柳宗元〔唐代〕',c:'杪秋霜露重，晨起行幽谷。\n黄叶覆溪桥，荒村唯古木。\n寒花疏寂历，幽泉微断续。\n机心久已忘，何事惊麋鹿。'},
    {t:'秋兴',a:'陆游〔宋代〕',c:'白发萧萧欲满头，归来三见故年秋。\n醉凭高阁乾坤迮，病入中年日月遒。\n百战铁衣空许国，五更画角只生愁。\n明朝烟雨桐江岸，且占丹枫系钓舟。'},
    {t:'秋兴',a:'王昌龄〔唐代〕',c:'日暮西北堂，凉风洗修木。\n著书在南窗，门馆常肃肃。\n苔草延古意，视听转幽独。\n或问余所营，刈黍就寒谷。'},
    {t:'秋兴八首·其二',a:'杜甫〔唐代〕',c:'夔府孤城落日斜，每依北斗望京华。\n听猿实下三声泪，奉使虚随八月槎。\n画省香炉违伏枕，山楼粉堞隐悲笳。\n请看石上藤萝月，已映洲前芦荻花。'},
    {t:'秋兴八首·其六',a:'杜甫〔唐代〕',c:'瞿塘峡口曲江头，万里风烟接素秋。\n花萼夹城通御气，芙蓉小苑入边愁。\n珠帘绣柱围黄鹄，锦缆牙樯起白鸥。\n回首可怜歌舞地，秦中自古帝王州。'},
    {t:'秋兴八首·其三',a:'杜甫〔唐代〕',c:'千家山郭静朝晖，日日江楼坐翠微。\n信宿渔人还泛泛，清秋燕子故飞飞。\n匡衡抗疏功名薄，刘向传经心事违。\n同学少年多不贱，五陵衣马自轻肥。'},
    {t:'秋兴八首·其四',a:'杜甫〔唐代〕',c:'闻道长安似弈棋，百年世事不胜悲。\n王侯第宅皆新主，文武衣冠异昔时。\n直北关山金鼓振，征西车马羽书驰。\n鱼龙寂寞秋江冷，故国平居有所思。'},
    {t:'秋兴九首其八拟杜牧之',a:'秦观〔宋代〕',c:'鼓鼙夜战北窗风，霜叶铺阶叠雁红。\n一段新愁惊枕上，几声悲雁落云中。\n眼前时节看驰马，日下生涯寄断蓬。\n弟妹别来劳梦寐，杳无消息过江东。'},
    {t:'秋兴九首其二拟孟郊',a:'秦观〔宋代〕',c:'晓风有暴信，暮蝉无好声。\n晓风乡暮蝉，自乡时节争。\n独客辞故乡，推车谒梁城。\n梁城道迢虎，区区役吾生。\n不如归旧山，藜藿安性情。'},
    {t:'秋兴九首其七拟杜子美',a:'秦观〔宋代〕',c:'紫领宽袍漉酒巾，江头萧散作闲人。\n悲风有意催林叶，落日无情下水滨。\n车马憧憧诸道路，市朝滚滚共埃尘。\n觅钱稚子啼红颊，不信山翁箧笥贫。'},
    {t:'秋兴九首其三拟韦应物',a:'秦观〔宋代〕',c:'坐投林下石，秋声出疏林。\n林间鸟惊栖，岂独伤客心。\n物亦有代谢，此理共古今。\n邻父缩新醅，林下邀同斟。\n痴儿踏吴歌，娅奼足讹音。\n日落相携手，凉风快虚襟。'},
    {t:'秋兴九首其五拟李白',a:'秦观〔宋代〕',c:'芙蓉露浓红压枝，幽禽感秋花畔啼。\n玉人一去未回马，梁边燕子三见归。\n江头白苹老波底，尺书不来空相望。\n斜吹疏雨湿秋江，霜风暗引芙蕖香，\n石上菖蒲三尺长。绿头鸭儿栖萍草，\n采莲女郎笑花老。木兰船上动江水，\n不觉鸳鸯带波起。'},
    {t:'秋兴有感',a:'王安石〔宋代〕',c:'宿雨清畿甸，朝阳丽帝城。\n丰年人乐业，陇上踏歌行。'},
    {t:'秋夜',a:'韦应物〔唐代〕',c:'暗窗凉叶动，秋天寝席单。\n忧人半夜起，明月在林端。\n一与清景遇，每忆平生欢。\n如何方恻怆，披衣露更寒。'},
    {t:'秋夜独坐',a:'王维〔唐代〕',c:'独坐悲双鬓，空堂欲二更。\n雨中山果落，灯下草虫鸣。\n白发终难变，黄金不可成。\n欲知除老病，唯有学无生。'},
    {t:'秋夜独坐怀内弟崔兴宗',a:'王维〔唐代〕',c:'夜静群动息，蟪蛄声悠悠。庭槐北风响，日夕方高秋。\n思子整羽翰，及时当云浮。吾生将白首，岁晏思沧州。\n高足在旦暮，肯为南亩俦。'},
    {t:'秋夜读书每以二鼓尽为节',a:'陆游〔宋代〕',c:'腐儒碌碌叹无奇，独喜遗编不味欺。\n白发无情侵老境，青灯有味似儿时。\n高梧策策传寒意，叠鼓冬冬迫睡期。\n秋夜渐长饥作祟，一杯山药进琼糜。'},
    {t:'秋夜二首',a:'韦应物〔唐代〕',c:'庭树转萧萧，阴虫还戚戚。独向高斋眠，夜闻寒雨滴。\n微风时动牖，残灯尚留壁。惆怅平生怀，偏来委今夕。\n霜露已凄凄，星汉复昭回。朔风中夜起，惊鸿千里来。\n萧条凉叶下，寂寞清砧哀。岁晏仰空宇，心事若寒灰。'},
    {t:'秋夜怀吴中',a:'陆游〔宋代〕',c:'秋夜挑灯读楚辞，昔人句句不吾欺。\n更堪临水登山处，正是浮家泛宅时。\n巴酒不能消客恨，蜀巫空解报归期。\n灞桥烟柳知何限，谁念行人寄一枝。'},
    {t:'秋夜纪怀',a:'陆游〔宋代〕',c:'北斗垂苍莽，明河浮太清。\n风林一叶下，露草百虫鸣。\n病入新凉减，诗从半睡成。\n还思散关路，炬火驿前迎。'},
    {t:'秋夜寄邱员外',a:'韦应物〔唐代〕',c:'怀君属秋夜，散步咏凉天。\n空山松子落，幽人应未眠。'},
    {t:'秋夜将晓出篱门迎凉有感二首',a:'陆游〔宋代〕',c:'迢迢天汉西南落，喔喔邻鸡一首鸣。\n壮志病来消欲尽，出门搔首怆平生。\n三万里河东入海，五千仞岳上摩天。\n遗民泪尽胡尘里，南望王师又一年。'},
    {t:'秋夜闻笛',a:'岑参〔唐代〕',c:'天门街西闻捣帛，一夜愁杀湘南客。\n长安城中百万家，不知何人吹夜笛。'},
    {t:'秋夜一绝',a:'韦应物〔唐代〕',c:'高阁渐凝露，凉叶稍飘闱。忆在南宫直，夜长钟漏稀。'},
    {t:'秋夜与友人宿',a:'杜牧〔唐代〕',c:'楚国同游过十霜，万重心事几清伤。蒹葭露白莲塘浅，\n砧杵夜清河汉凉。云外山川归梦远，天涯岐路客愁长。\n寒城欲晓闻吹笛，犹卧东轩月满床。'},
    {t:'秋夜月·当初聚散',a:'柳永〔宋代〕',c:'当初聚散。便唤作、无由再逢伊面。近日来、不期而会重欢宴。向尊前、闲暇里，敛著眉儿长叹。惹起旧愁无限。\n盈盈泪眼。漫向我耳边，作万般幽怨。奈你自家心下，有事难见。待信真个，恁别无萦绊。不免收心，共伊长远。'},
    {t:'秋萤引',a:'刘禹锡〔唐代〕',c:'汉陵秦苑遥苍苍，陈根腐叶秋萤光。夜空寥寂金气净，\n千门九陌飞悠扬。纷纶晖映互明灭，金炉星喷镫花发。\n露华洗濯清风吹，低昂不定招摇垂。高丽罘罳照珠网，\n斜历璇题舞罗幌。曝衣楼上拂香裙，承露台前转仙掌。\n槐市诸生夜读书，北窗分明辨鲁鱼。行子东山起征思，\n中郎骑省悲秋气。铜雀人归自入帘，长门帐开来照泪。\n谁言向晦常自明，儿童走步娇女争。天生有光非自衒，\n远近低昂暗中见。撮蚊妖鸟亦夜起，翅如车轮而已矣。'},
    {t:'秋雨',a:'陆游〔宋代〕',c:'暮秋木叶已微丹，小雨萧萧又作寒。\n目送断云归谷口，身随新雁寄江干。\n浊醪易负寻常债，退士难叨本分官。\n谢尽浮名更无事，灯前儿女话团栾。'},
    {t:'秋雨',a:'温庭筠〔唐代〕',c:'云满鸟行灭，池凉龙气腥。斜飘看棋簟，疏洒望山亭。\n细响鸣林叶，圆文破沼萍。秋阴杳无际，平野但冥冥。'},
    {t:'秋雨叹十解',a:'杨万里〔宋代〕',c:'湿侵团扇不能轻，冷逼孤灯分外明。\n蕉叶半黄荷叶碧，两家秋雨一家声。'},
    {t:'秋雨叹十解·其一',a:'杨万里〔宋代〕',c:'雨入秋宵滴到明，不知有意复无情。\n若言不搅愁人梦，为许千千万万声。'},
    {t:'秋雨夜眠',a:'白居易〔唐代〕',c:'凉冷三秋夜，安闲一老翁。\n卧迟灯灭后，睡美雨声中。\n灰宿温瓶火，香添暖被笼。\n晓晴寒未起，霜叶满阶红。'},
    {t:'秋雨中赠元九',a:'白居易〔唐代〕',c:'不堪红叶青苔地，又是凉风暮雨天。\n莫怪独吟秋思苦，比君校近二毛年。'},
    {t:'秋园卧病呈晖上人',a:'陈子昂〔唐代〕',c:'幽寂旷日遥，林园转清密。疲疴澹无豫，独坐泛瑶瑟。\n怀挟万古情，忧虞百年疾。绵绵多滞念，忽忽每如失。\n缅想赤松游，高寻白云逸。荣吝始都丧，幽人遂贞吉。\n图书纷满床，山水蔼盈室。宿昔心所尚，平生自兹毕。\n愿言谁见知，梵筵有同术。八月高秋晚，凉风正萧瑟。'},
    {t:'秋月',a:'朱熹〔宋代〕',c:'清溪流过碧山头，空水澄鲜一色秋。\n隔断红尘三十里，白云红叶两悠悠。'},
    {t:'秋中暑退赠乐天',a:'刘禹锡〔唐代〕',c:'暑服宜秋著，清琴入夜弹。\n人情皆向菊，风意欲摧兰。\n岁稔贫心泰，天凉病体安。\n相逢取次第，却甚少年欢。'},
    {t:'秋字',a:'韩愈〔唐代〕',c:'淮南悲木落，而我亦伤秋。\n况与故人别，那堪羁宦愁。\n荣华今异路，风雨昔同忧。\n莫以宜春远，江山多胜游。'},
    {t:'囚经泰和仰望快阁感赋',a:'文天祥〔宋代〕',c:'书生曾拥碧油幢，耻与群儿共度降。\n汉节几回登快阁，楚囚今度过澄江。\n丹心不改君臣谊，清泪难忘父母邦。\n惟有乡人知我瘦，下帷绝粒坐蓬窗。'},
    {t:'求仙曲',a:'孟郊〔唐代〕',c:'仙教生为门，仙宗静为根。持心若妄求，服食安足论。\n铲惑有灵药，饵真成本源。自当出尘网，驭凤登昆仑。'},
    {t:'求仙行',a:'张籍〔唐代〕',c:'汉皇欲作飞仙子，年年采药东海里。蓬莱无路海无边，\n方士舟中相枕死。招摇在天回白日，甘泉玉树无仙实。\n九皇真人终不下，空向离宫祠太乙。丹田有气凝素华，\n君能保之升绛霞。'},
    {t:'求友',a:'孟郊〔唐代〕',c:'北风临大海，坚冰临河面。\n下有大波澜，对之无由见。\n求友须在良，得良终相善。\n求友若非良，非良中道变。\n欲知求友心，先把黄金炼。'},
    {t:'曲江',a:'李商隐〔唐代〕',c:'望断平时翠辇过，空闻子夜鬼分歌。\n金舆不返倾城色，玉殿犹分下苑波。\n死忆华亭闻唳鹤，老忧王室泣铜驼。\n天荒地变心虽折，若比伤春意未多。'},
    {t:'曲江春望',a:'刘禹锡〔唐代〕',c:'凤城烟雨歇，万象含佳气。\n酒后人倒狂，花时天似醉。\n三春车马客，一代繁华地。\n何事独伤怀，少年曾得意。'},
    {t:'曲江对酒',a:'杜甫〔唐代〕',c:'苑外江头坐不归，水精宫殿转霏微。\n桃花细逐杨花落，黄鸟时兼白鸟飞。\n纵饮久判人共弃，懒朝真与世相违。\n吏情更觉沧洲远，老大徒伤未拂衣。'},
    {t:'曲江对雨',a:'杜甫〔唐代〕',c:'城上春云覆苑墙，江亭晚色静年芳。\n林花著雨胭脂湿，水荇牵风翠带长。\n龙武新军深驻辇，芙蓉别殿谩焚香。\n何时诏此金钱会，暂醉佳人锦瑟旁。'},
    {t:'曲江二首',a:'杜甫〔唐代〕',c:'一片花飞减却春，风飘万点正愁人。\n且看欲尽花经眼，莫厌伤多酒入唇。\n江上小堂巢翡翠，花边高冢卧麒麟。\n细推物理须行乐，何用浮名绊此身。\n朝回日日典春衣，每日江头尽醉归。\n酒债寻常行处有，人生七十古来稀。\n穿花蛱蝶深深见，点水蜻蜓款款飞。\n传语风光共流转，暂时相赏莫相违。'},
    {t:'曲江三章章五句',a:'杜甫〔唐代〕',c:'曲江萧条秋气高，菱荷枯折随波涛，游子空嗟垂二毛。\n白石素沙亦相荡，哀鸿独叫求其曹。\n即事非今亦非古，长歌激越捎林莽，比屋豪华固难数。\n吾人甘作心似灰，弟侄何伤泪如雨。\n自断此生休问天，杜曲幸有桑麻田，故将移往南山边。\n短衣匹马随李广，看射猛虎终残年。'},
    {t:'曲江忆元九',a:'白居易〔唐代〕',c:'春来无伴闲游少，行乐三分减二分。\n何况今朝杏园里，闲人逢尽不逢君。'},
    {t:'曲玉管·陇首云飞',a:'柳永〔宋代〕',c:'陇首云飞，江边日晚，烟波满目凭阑久。一望关河萧索，千里清秋，忍凝眸？\n杳杳神京，盈盈仙子，别来锦字终难偶。断雁无凭，冉冉飞下汀洲，思悠悠。\n暗想当初，有多少、幽欢佳会，岂知聚散难期，翻成雨恨云愁？阻追游。每登山临水，惹起平生心事，一场消黯，永日无言，却下层楼。'},
    {t:'驱车上东门',a:'佚名〔两汉〕',c:'驱车上东门，遥望郭北墓。\n白杨何萧萧，松柏夹广路。\n下有陈死人，杳杳即长暮。\n潜寐黄泉下，千载永不寤。\n浩浩阴阳移，年命如朝露。\n人生忽如寄，寿无金石固。\n万岁更相迭，贤圣莫能度。\n服食求神仙，多为药所误。\n不如饮美酒，被服纨与素。'},
    {t:'屈原塔',a:'苏轼〔宋代〕',c:'楚人悲屈原，千载意未歇。\n精魂上何处，父老空哽咽。\n至今沧江上，投饭救饥渴。\n遗风成竞渡，哀甚楚山裂。\n屈原古壮士，就死意甚烈。\n世俗安得知，眷眷不忍决。\n南宾旧属楚，山上有遗塔。\n应是奉佛人，恐子就沦灭。\n此事虽无凭，此意固已切。\n古人谁不死，何必较考折。\n名声实无穷，富贵亦暂热。\n大夫知此理，所以持死节。'},
    {t:'去妇',a:'孟郊〔唐代〕',c:'君心匣中镜，一破不复全。妾心藕中丝，虽断犹牵连。\n安知御轮士，今日翻回辕。一女事一夫，安可再移天。\n君听去鹤言，哀哀七丝弦。'},
    {t:'去蜀',a:'杜甫〔唐代〕',c:'五载客蜀郡，一年居梓州。\n如何关塞阻，转作潇湘游。\n世事已黄发，残生随白鸥。\n安危大臣在，不必泪长流。'},
    {t:'去者日以疏',a:'佚名〔两汉〕',c:'去者日以疏，来者日以亲。\n出郭门直视，但见丘与坟。\n古墓犁为田，松柏摧为薪。\n白杨多悲风，萧萧愁杀人。\n思还故里闾，欲归道无因。'},
    {t:'去镇江第五十八',a:'文天祥〔宋代〕',c:'京口流江航，穷途仗神道。\n萧条向水陆，云雨白浩浩。'},
    {t:'劝交代张和父酒',a:'黄庭坚〔宋代〕',c:'风流五日张京兆，今日诸孙困小官。\n作尹大都如广汉，画眉仍复近长安。\n三人成虎事多有，众口铄金君自宽。\n酒兴情亲俱不浅，贱生何取罄交欢。'},
    {t:'劝金船·无情流水多情客',a:'苏轼〔宋代〕',c:'无情流水多情客，劝我如曾识。杯行到手休辞却，这公道难得。曲水池上，小字更书年月。还对茂林修竹，似永和节。\n纤纤素手如霜雪，笑把秋花插。尊前莫怪歌声咽，又还是轻别。此去翱翔，遍赏玉堂金阙。欲问再来何岁，应有华发。'},
    {t:'劝酒',a:'孟郊〔唐代〕',c:'白日无定影，清江无定波。人无酒年寿，酒年复如何。\n堂上陈美酒，堂下列清歌。劝君金曲卮，勿谓朱颜酡。\n松柏岁岁茂，丘陵日日多。君看终南山，千古青峨峨。'},
    {t:'劝酒寄元九',a:'白居易〔唐代〕',c:'薤叶有朝露，槿枝无宿花。\n君今僧如此，促促生有涯。\n既不逐禅僧，林下学楞伽。\n又不随道士，山无炼丹砂。\n百年夜分半，一岁春无多。\n何不饮美酒，胡然自悲嗟。\n俗号销愁药，神速无以加。\n一杯驱世虑，两杯反天和。\n三杯即酩酊，或笑任狂歌。\n陶陶复兀兀，吾孰知其他。\n况在名利途，平生有风波。\n深心藏陷阱，巧言织网罗。\n举目非不见，不醉欲如何。'},
    {t:'劝农·其六',a:'陶渊明〔魏晋〕',c:'孔耽道德，樊须是鄙。\n董乐琴书，田园不履。\n若能超然，投迹高轨。\n敢不敛衽，敬赞德美。'},
    {t:'劝善吟',a:'孟郊〔唐代〕',c:'瘦郭有志气，相哀老龙钟。劝我少吟诗，俗窄难尔容。\n一口百味别，况在醉会中。四座正当喧，片言何由通。\n顾余昧时调，居止多疏慵。见书眼始开，闻乐耳不聪。\n视听互相隔，一身且莫同。天疾难自医，诗癖将何攻。\n见君如见书，语善千万重。自悲咄咄感，变作烦恼翁。\n烦恼不可欺，古剑涩亦雄。知君方少年，少年怀古风。\n藏书拄屋脊，不惜与凡聋。我愿拜少年，师之学崇崇。\n从他笑为矫，矫善亦可宗。'},
    {t:'劝学',a:'孟郊〔唐代〕',c:'击石乃有火，不击元无烟。\n人学始知道，不学非自然。\n万事须己运，他得非我贤。\n青春须早为，岂能长少年。'},
    {t:'劝学诗',a:'朱熹〔宋代〕',c:'少年易老学难成，一寸光阴不可轻。\n未觉池塘春草梦，阶前梧叶已秋声。'},
    {t:'劝学文',a:'柳永〔宋代〕',c:'父母养其子而不教，是不爱其子也。虽教而不严，是亦不爱其子也。父母教而不学，是子不爱其身也。虽学而不勤，是亦不爱其身也。是故养子必教，教则必严；严则必勤，勤则必成。学，则庶人之子为公卿；不学，则公卿之子为庶人。'},
    {t:'劝友',a:'孟郊〔唐代〕',c:'至白涅不缁，至交淡不疑。人生静躁殊，莫厌相箴规。\n胶漆武可接，金兰文可思。堪嗟无心人，不如松柏枝。'},
    {t:'劝醉',a:'元稹〔唐代〕',c:'窦家能酿销愁酒，但是愁人便与销。\n愿我共君俱寂寞，只应连夜复连朝。'},
    {t:'缺题',a:'刘禹锡〔唐代〕',c:'故人日已远，窗下尘满琴。\n坐对一樽酒，恨多无力斟。\n幕疏萤色迥，露重月华深。\n万境与群籁，此时情岂任。'},
    {t:'阙题二首',a:'王维〔唐代〕',c:'荆溪白石出，天寒红叶稀。\n山路元无雨，空翠湿人衣。\n相看不忍发，惨淡暮潮平。\n语罢更携手，月明洲渚生。'},
    {t:'鹊桥仙·华灯纵博',a:'陆游〔宋代〕',c:'华灯纵博，雕鞍驰射，谁记当年豪举。酒徒一半取封侯，独去作、江边渔父。\n轻舟八尺，低篷三扇，占断蘋洲烟雨。镜湖元自属闲人，又何必、官家赐与。'},
    {t:'鹊桥仙·己酉山行书所见',a:'辛弃疾〔宋代〕',c:'松冈避暑，茅檐避雨，闲去闲来前度？醉扶怪石看飞泉，又却是、前回醒处。\n东家娶妇，西家归女，灯火门前笑语。酿成千顷稻花香，夜夜费、一天风露。'},
    {t:'鹊桥仙·届征途',a:'柳永〔宋代〕',c:'届征途，携书剑，迢迢匹马东去。方离怀，嗟少年易分难聚。佳人方恁缱绻，便忍分鸳侣。当媚景，肠密意幽欢，尽成轻负。\n此际寸肠万绪。方愁颜、断魂无语。和泪眼、片时几番回顾。伤心脉脉谁诉。但黯然凝伫。暮烟寒雨。望秦楼何处。'},
    {t:'鹊桥仙·七夕',a:'纳兰性德〔清代〕',c:'乞巧楼空，影娥池冷，佳节只供为叹。丁宁休曝旧罗衣，忆素手、为予缝绽。\n莲粉飘红，菱丝翳碧，仰见明星空烂。亲持钿合梦中来，信天上、人间非幻。'},
    {t:'鹊桥仙·七夕送陈令举',a:'苏轼〔宋代〕',c:'缑山仙子，高清云渺，不学痴牛时女。凤箫声断月明中，举手谢、时人欲去。\n客槎曾犯，银河微浪，尚带天风海雨。相逢一醉是前缘，风雨散、飘然何处？'},
    {t:'鹊桥仙·送粉卿行',a:'辛弃疾〔宋代〕',c:'轿儿排了，担儿装了，杜宇一声一起。从今一步一回头，怎睚得、一千余里。\n旧时行处，旧时歌处，空有燕泥香坠。莫嫌白发不思量，也须有、思量去里。'},
    {t:'鹊桥仙·纤云弄巧',a:'秦观〔宋代〕',c:'纤云弄巧，飞星传恨，银汉迢迢暗度。金风玉露一相逢，便胜却人间无数。\n柔情似水，佳期如梦，忍顾鹊桥归路。两情若是久长时，又岂在朝朝暮暮。'},
    {t:'鹊桥仙·夜闻杜鹃',a:'陆游〔宋代〕',c:'茅檐人静，蓬窗灯暗，春晚连江风雨。林莺巢燕总无声，但月夜、常啼杜宇。\n催成清泪，惊残孤梦，又拣深枝飞去。故山犹自不堪听，况半世、飘然羁旅！'},
    {t:'鹊桥仙·一竿风月',a:'陆游〔宋代〕',c:'一竿风月，一蓑烟雨，家在钓台红住。卖鱼生怕近城门，况肯到红尘深处？\n潮生理棹，潮平系缆，潮落浩歌归去。时人错把比严光，我自是无名渔父。'},
    {t:'鹊桥仙·岳云',a:'佚名',c:'湛湛长空，乱云飞度，吹尽繁红无数。正当年紫金空铸，万里黄沙无觅处。\n沉江望极，狂涛乍起，惊飞一滩鸥鹭。鲜衣怒马少年时，能堪那金贼南渡?'},
    {t:'鹊桥仙·赠鹭鸶',a:'辛弃疾〔宋代〕',c:'溪边白鹭。来吾告汝。溪里鱼儿欣数。主人怜汝汝怜鱼，要物我、欣然一处。\n白沙远浦。青泥别渚。剩有虾跳鳅舞。听君飞去饱时来，看头上、风吹一缕。'},
    {t:'鹊桥仙令·歇指',a:'周邦彦〔宋代〕',c:'浮花浪蕊，人间无数，开遍朱朱丹丹。瑶池一朵玉芙蓉，秋露洗、丹砂真色。\n晚凉拜月，六铢衣动，应被姮娥认得。翩然欲上广寒宫，横玉度、一声天碧。'},
    {t:'鹊踏枝·叵耐灵鹊多谩语',a:'佚名〔五代〕',c:'叵耐灵鹊多谩语，送喜何曾有笼据？几度飞来活捉取，锁上金笼休共语。\n比拟好心来送喜，谁知锁我在金笼里。欲他征夫早归来，腾身却放我向青云里。'},
    {t:'鹊踏枝·紫府群仙名籍秘',a:'晏殊〔宋代〕',c:'紫府群仙名籍秘。五色斑龙，暂桃人间世。海变桑田都不记，蟠桃一熟三千岁。\n露滴彩旌云绕袂。谁信壶中，别有笙歌地。门外落花随水逝，相看莫惜尊前醉。'},
    {t:'群公集毕氏林亭',a:'陈子昂〔唐代〕',c:'金门有遗世，鼎实恣和邦。默语谁能识，琴樽寄北窗。\n子牟恋魏阙，渔父爱沧江。良时信同此，岁晚迹难双。'},
    {t:'冉冉孤生竹',a:'佚名〔两汉〕',c:'冉冉孤生竹，结根泰山阿。\n与君为新婚，菟丝附女萝。\n菟丝生有时，夫妇会有宜。\n千里远结婚，悠悠隔山陂。\n思君令人老，轩车来何迟！\n伤彼蕙兰花，含英扬光辉。\n过时而不采，将随秋草萎。\n君亮执高节，贱妾亦何为？'},
    {t:'冉溪',a:'柳宗元〔唐代〕',c:'少时陈力希公侯，许国不复为身谋。\n风波一跌逝万里，壮心瓦解空缧囚。\n缧囚终老无余事，愿卜湘西冉溪地。\n却学寿张樊敬侯，种漆南园待成器。'},
    {t:'染丝上春机',a:'李贺〔唐代〕',c:'玉罂汲水桐花井，茜丝沈水如掷影。\n美人懒态燕脂愁，春梭抛掷鸣高楼。\n彩线结茸背复叠，白袷玉郎寄桃叶。\n为君挑鸾作腰绶，愿君处处宜春酒。'},
    {t:'染云',a:'王安石〔宋代〕',c:'染云为柳叶，剪水作梨花。\n不是春风巧，何缘有岁华。'},
    {t:'绕佛阁·暗尘四敛',a:'周邦彦〔宋代〕',c:'暗尘四敛。楼观迥出，高映孤馆。清漏将短。厌闻夜久、签声动书幔。桂华又满。闲步露草，偏爱幽远。花气清婉。望中迤逦，城阴度河岸。\n倦客最萧索，醉倚斜桥穿柳线，还似汴堤、虹梁横水面。看浪飐春灯，舟下如箭。此行重见。叹故友难逢，羁思空乱。两眉愁、向谁舒展。'},
    {t:'热海行送崔侍御还京',a:'岑参〔唐代〕',c:'侧闻阴山胡儿语，西头热海水如煮。\n海上众鸟不敢飞，中有鲤鱼长且肥。\n岸旁青草长不歇，空中白雪遥旋灭。\n蒸沙烁石燃虏云，沸浪炎波煎汉月。\n阴火潜烧天地炉，何事偏烘西一隅？\n势吞月窟侵太白，气连赤坂通单于。\n送君一醉天山郭，正见夕阳海边落。\n柏台霜威寒逼人，热海炎气为之薄。'},
    {t:'人日城南登高',a:'韩愈〔唐代〕',c:'初正候才兆，涉七气已弄。\n霭霭野浮阳，晖晖水披冻。\n圣朝身不废，佳节古所用。\n亲交既许来，子妷亦可从。\n盘蔬冬春杂，尊酒清浊共。\n令征前事为，觞咏新诗送。\n扶杖凌圮阯，刺船犯枯葑。\n恋池群鸭回，释峤孤云纵。\n人生本坦荡，谁使妄倥偬。\n直指桃李阑，幽寻宁止重。'},
    {t:'人日出游湖上十首',a:'杨万里〔宋代〕',c:'城中雪一尺，山中雪一丈。\n地上都巳消，却在松梢上。'},
    {t:'人日寄杜二拾遗',a:'高适〔唐代〕',c:'人日题诗寄草堂，遥怜故人思故乡。\n柳条弄色不忍见，梅花满枝空断肠。\n身在远藩无所预，心怀百忧复千虑。\n今年人日空相忆，明年人日知何处。\n一卧东山三十春，岂知书剑老风尘。\n龙钟还忝二千石，愧尔东西南北人。'},
    {t:'壬辰寒食',a:'王安石〔宋代〕',c:'客思似杨柳，春风千万条。\n更倾寒食泪，欲涨冶城潮。\n巾发雪争出，镜颜朱早凋。\n未知轩冕乐，但欲老渔樵。'},
    {t:'壬申七夕',a:'李商隐〔唐代〕',c:'已驾七香车，心心待晓霞。\n风轻惟响珮，日薄不嫣花。\n桂嫩传香远，榆高送影斜。\n成都过卜肆，曾妒识灵槎。'},
    {t:'壬子偶题',a:'王安石〔宋代〕',c:'黄尘投老倦匆匆，故绕盆池种水红。\n落日欹眠何所忆，江湖秋梦橹声中。'},
    {t:'壬子三月二十七日闻迅雷有感',a:'朱熹〔宋代〕',c:'谁将神斧破顽阴，地裂山开鬼失林。\n我愿君王法天造，早施雄断答群心。'},
    {t:'仁风李著作园醉后寄李十',a:'元稹〔唐代〕',c:'胧明春月照花枝，花下音声是管儿。\n却笑西京李员外，五更骑马趁朝时。'},
    {t:'仁和里杂叙皇甫湜',a:'李贺〔唐代〕',c:'大人乞马癯乃寒，宗人贷宅荒厥垣。\n横庭鼠径空土涩，出篱大枣垂珠残。\n安定美人截黄绶，脱落缨裾暝朝酒。\n还家白笔未上头，使我清声落人后。\n枉辱称知犯君眼，排引才升强絙断。\n洛风送马入长关，阖扇未开逢猰犬。\n那知坚都相草草，客枕幽单看春老。\n归来骨薄面无膏，疫气冲头鬓茎少。\n欲雕小说干天官，宗孙不调为谁怜？\n明朝下元复西道，崆峒叙别长如天。'},
    {t:'任弘农尉献州刺史乞假还京',a:'李商隐〔唐代〕',c:'黄昏封印点刑徒，愧负荆山入座隅。\n却羡卞和双刖足，一生无复没阶趋。'},
    {t:'任鄠令渼陂游眺',a:'韦应物〔唐代〕',c:'野水滟长塘，烟花乱晴日。氤氲绿树多，苍翠千山出。\n游鱼时可见，新荷尚未密。屡往心独闲，恨无理人术。'},
    {t:'任洛阳丞，答前长安田少府问',a:'韦应物〔唐代〕',c:'相逢且对酒，相问欲何如。数岁犹卑吏，家人笑著书。\n告归应未得，荣宦又知疏。日日生春草，空令忆旧居。'},
    {t:'任洛阳丞请告一首',a:'韦应物〔唐代〕',c:'方凿不受圆，直木不为轮。揆材各有用，反性生苦辛。\n折腰非吾事，饮水非吾贫。休告卧空馆，养病绝嚣尘。\n游鱼自成族，野鸟亦有群。家园杜陵下，千岁心氛氲。\n天晴嵩山高，雪后河洛春。乔木犹未芳，百草日已新。\n著书复何为，当去东皋耘。'},
    {t:'日出',a:'杨万里〔宋代〕',c:'散云作雾恰昏昏，收雾依前复作云。\n一面红金大圆镜，尽销云雾照乾坤。'},
    {t:'日出入',a:'佚名〔两汉〕',c:'日出入安穷？时世不与人同。\n故冬非我冬，夏非我夏，\n秋非我秋，冬非我冬。\n泊如四海之池，遍观是邪谓何？\n吾知所乐，独乐六龙，\n六龙之调，使我心若。\n訾黄其何不徕下。'},
    {t:'日出行',a:'李白〔唐代〕',c:'日出东方隈，似从地底来。\n历天又复入西海，六龙所舍安在哉？\n其始与终古不息，人非元气，安得与之久徘徊？\n草不谢荣于春风，木不怨落于秋天。\n谁挥鞭策驱四运？万物兴歇皆自然。\n羲和！羲和！汝奚汩没于荒淫之波？\n鲁阳何德，驻景挥戈？\n逆道违天，矫诬实多。\n吾将囊括大块，浩然与溟涬同科！'},
    {t:'日出行',a:'李贺〔唐代〕',c:'白日下昆崙，发光如舒丝。徒照葵藿心，不照游子悲。\n折折黄河曲，日从中央转。旸谷耳曾闻，若木眼不见。\n奈尔铄石，胡为销人。羿弯弓属矢那不中，足令久不得奔。\n讵教晨光夕昏。'},
    {t:'日高',a:'李商隐〔唐代〕',c:'镀环故锦縻轻拖，玉筏不动便门锁。\n水精眠梦是何人？栏药日高红髲𩭝。\n飞香上云春诉天，云梯十二门九关。\n轻身灭影何可望，粉蛾帖死屏风上。'},
    {t:'日没贺延碛作',a:'岑参〔唐代〕',c:'沙上见日出，沙上见日没。悔向万里来，功名是何物。'},
    {t:'日暮',a:'杜甫〔唐代〕',c:'牛羊下来久，各已闭柴门。\n风月自清夜，江山非故园。\n石泉流暗壁，草露滴秋根。\n头白灯明里，何须花烬繁。'},
    {t:'日日',a:'李商隐〔唐代〕',c:'日日春光斗日光，山城斜路杏花香。\n几时心绪浑无事，得及游丝百尺长。'},
    {t:'日射',a:'李商隐〔唐代〕',c:'日射纱窗风撼扉，香罗拭手春事违。\n回廊四合掩寂寞，碧鹦鹉对红蔷薇。'},
    {t:'日用自警示平父',a:'朱熹〔宋代〕',c:'圆融无际大无馀，即此身心是处虚。不向用时勤猛省，却于何处味真腴。\n寻常应对尤须谨，造次施为更莫疏。一日洞然无别体，方知不枉费功夫。'},
    {t:'荣木·其四',a:'陶渊明〔魏晋〕',c:'先师遗训，余岂之坠！\n四十无闻，斯不足畏。\n脂我名车，策我名骥。\n千里虽遥，孰敢不至！'},
    {t:'如皋',a:'文天祥〔宋代〕',c:'雄狐假虎之林皋，河水腥风接海涛。\n行客不知身世险，一窗春梦送轻舠。'},
    {t:'如梦令',a:'柳永〔宋代〕',c:'郊外绿阴千里。掩映红裙十队。惜别语方长，车马催人速去。\n偷泪。偷泪。那得分身应你。'},
    {t:'如梦令',a:'纳兰性德〔清代〕',c:'木叶纷纷归路，残月晓风何处。消息半浮沉，今夜相思几许。\n秋雨，秋雨，一半西风吹去。'},
    {t:'如梦令·尘满一絣文绣',a:'周邦彦〔宋代〕',c:'尘满一絣文绣，泪湿领巾红皱。初暖绮罗轻，腰胜武昌官柳。长昼，长昼，困卧午窗中酒。'},
    {t:'如梦令·池上春归何处',a:'秦观〔宋代〕',c:'池上春归何处？满目落花飞絮。孤馆悄无人，梦断月堤归路。无绪，无绪。帘外五更风雨。'},
    {t:'如梦令·传与东坡尊舅',a:'秦观〔宋代〕',c:'传与东坡尊舅。欲作栏干护佑。心性慢些儿，先著他人机构。虚谬。虚谬。这段姻缘生受。'},
    {t:'如梦令·春景',a:'秦观〔宋代〕',c:'莺嘴啄花红溜，燕尾点波绿皱。指冷玉笙寒，吹彻小梅春透。依旧，依旧，人与绿杨俱瘦。'},
    {t:'如梦令·春思',a:'苏轼〔宋代〕',c:'手种堂前桃李，无限绿阴青子。帘外百舌儿，惊起五更春睡。居士，居士。莫忘小桥流水。'},
    {t:'如梦令·黄叶青苔归路',a:'纳兰性德〔清代〕',c:'黄叶青苔归路，屧粉衣香何处。雨息竟沉沉，今夜相思几许。秋雨，秋雨，一半因风吹去。'},
    {t:'如梦令·门外绿荫千顷',a:'秦观〔宋代〕',c:'门外绿荫千顷，\n两两黄鹂相应。\n睡起不胜情，\n行到碧梧金井。\n人静，人静，\n风弄一枝花影。'},
    {t:'如梦令·门外迢迢行路',a:'周邦彦〔宋代〕',c:'门外迢迢行路。谁送郎边尺素。巷陌雨余风，当面湿花飞去。无绪。无绪。闲处偷垂玉著。'},
    {t:'如梦令·水垢何曾相受',a:'苏轼〔宋代〕',c:'元丰七年十二月十八日，浴泗州雍熙塔下，戏作如梦令阕。此曲本唐庄宗制，名忆仙姿，嫌其名不雅，故改为如梦令。盖庄宗作此词，卒章云：“如梦如梦，和泪出门相送。”因取以为名云。\n水垢何曾相受。细看两俱无有。寄语揩背人，尽日劳君挥肘。轻手，轻手。居士本来无垢。'},
    {t:'如梦令·题淮山楼',a:'苏轼〔宋代〕',c:'城上层楼叠巘，城下清淮古汴。举手揖吴云，人与暮天俱远。魂断，魂断，后夜松江月满。'},
    {t:'如梦令·题渔乐图',a:'张炎〔宋代〕',c:'不是潇湘风雨。不是洞庭烟树。醉倒古乾坤，人在孤篷来处。休去。休去。见说桃源无路。'},
    {t:'如梦令·万帐穹庐人醉',a:'纳兰性德〔清代〕',c:'万帐穹庐人醉，星影摇摇欲坠，归梦隔狼河，又被河声搅碎。还睡、还睡，解道醒来无味。'},
    {t:'如梦令·五之二',a:'秦观〔宋代〕',c:'遥夜沈沈如水。风系驿亭深闭。梦破鼠窥灯，霜送晓寒侵被。无寐。无寐。门外马嘶人起。'},
    {t:'如梦令·五之三',a:'秦观〔宋代〕',c:'幽梦匆匆破后。妆粉乱痕沾袖。遥想酒醒来，无奈玉销花瘦。回首。回首。绕岸夕阳疏柳。'},
    {t:'如梦令·五之四',a:'秦观〔宋代〕',c:'楼外残阳红满。春入柳条将半。桃李不禁风，回首落英无限。肠断。肠断。人共楚天俱远。'},
    {t:'如梦令·五之一',a:'秦观〔宋代〕',c:'门外鸦啼杨柳。春色著人如酒。睡起熨沈香，玉腕不胜金斗。消瘦。消瘦。还是褪花时候。'},
    {t:'如梦令·纤月黄昏庭院',a:'纳兰性德〔清代〕',c:'纤月黄昏庭院，语密翻教醉浅。知否那人心？旧恨新欢相半。谁见？谁见？珊枕泪痕红泫。'},
    {t:'如梦令·遥夜沉沉如水',a:'秦观〔宋代〕',c:'遥夜沉沉如水，风紧驿亭深闭。梦破鼠窥灯，霜送晓寒侵被。无寐，无寐，门外马嘶人起。'},
    {t:'如梦令·有寄',a:'苏轼〔宋代〕',c:'为向东坡传语。人在玉堂深处。别后有谁来，雪压小桥无路。归去。归去。江上一犁春雨。'},
    {t:'如梦令·渊明行径',a:'张炎〔宋代〕',c:'苔径独行清昼。瑟瑟松风如旧。出岫本无心，迟种门前杨柳。回首。回首。篱下白衣来否。'},
    {t:'如梦令·正是辘轳金井',a:'纳兰性德〔清代〕',c:'正是辘轳金井，满砌落花红冷。蓦地一相逢，心事眼波难定。谁省，谁省。从此簟纹灯影。'},
    {t:'如梦令·自净方能净彼',a:'苏轼〔宋代〕',c:'自净方能净彼，我自汗流呀气。寄语澡浴人，且共肉身游戏。但洗，但洗，俯为人间一切。'},
    {t:'如鱼水·帝里疏散',a:'柳永〔宋代〕',c:'帝里疏散，数载酒萦花系，九陌风游。良景对珍筵恼，佳人自有风流。劝琼瓯。绛唇启、歌发清幽。姬举措、艺足才高，在处别得艳姬留。\n浮名利，拟拚休。是非莫挂心头。富贵岂由人，时会高志须酬。莫闲愁。共绿蚁、红粉相尤。向绣幄，醉倚芳姿睡，算除此外何求。'},
    {t:'如鱼水·轻霭浮空',a:'柳永〔宋代〕',c:'轻霭浮空，乱峰倒影，潋滟十里芰塘。绕岸垂杨。红楼朱阁相望。芰荷香。双双戏、鸂鶒鸳鸯。乍雨风、兰芷汀洲，望中依约似潇湘。\n风淡淡，水茫茫。动一片晴光。画舫相将。盈盈红粉清商。紫薇郎。修禊饮、且乐仙乡。更归去，遍历銮坡凤沼，此景也难忘。'},
    {t:'入茶山下题水口草市绝句',a:'杜牧〔唐代〕',c:'倚溪侵岭多高树，夸酒书旗有小楼。\n惊起鸳鸯岂无恨，一双飞去却回头。'},
    {t:'入昌松东界山行',a:'高适〔唐代〕',c:'鸟道几登顿，马蹄无暂闲。\n崎岖出长坂，合沓犹前山。\n石激水流处，天寒松色间。\n王程应未尽，且莫顾刀环。'},
    {t:'入常山界二首·其二',a:'杨万里〔宋代〕',c:'昨日愁霖今喜晴，好山夹路玉亭亭。\n一峰忽被云偷去，留得峥嵘半截青。'},
    {t:'入城难',a:'文天祥〔宋代〕',c:'轻身漂泊入銮江，太守欣然为避堂。\n若使闭城呼不应，人间生死路茫茫。'},
    {t:'入东阳峡与李明府舟前后不相及',a:'陈子昂〔唐代〕',c:'东岩初解缆，南浦遂离群。出没同洲岛，沿洄异渚濆。\n风烟犹可望，歌笑浩难闻。路转青山合，峰回白日曛。\n奔涛上漫漫，积水下沄沄。倏忽犹疑及，差池复两分。\n离离间远树，蔼蔼没遥氛。地上巴陵道，星连牛斗文。\n孤狖啼寒月，哀鸿叫断云。仙舟不可见，摇思坐氛氲。'},
    {t:'入瓜步望扬州',a:'王安石〔宋代〕',c:'落日平林一水边，芜城掩映只苍然。\n白头追想当时事，幕府青衫最少年。'},
    {t:'入关咏马',a:'韩愈〔唐代〕',c:'岁老岂能充上驷，力微当自慎前程。\n不知何故翻骧首，牵过关门妄一鸣。'},
    {t:'入黄溪闻猿',a:'柳宗元〔唐代〕',c:'溪路千里曲，哀猿何处鸣。\n孤臣泪已尽，虚作断肠声。'},
    {t:'入庐山仰望瀑布水',a:'张九龄〔唐代〕',c:'绝顶有悬泉，喧喧出烟杪。\n不知几时岁，但见无昏晓。\n闪闪青崖落，鲜鲜白日皎。\n洒流湿行云，溅沫惊飞鸟。\n雷吼何喷薄，箭驰入窈窕。\n昔闻山下蒙，今乃林峦表。\n物情有诡激，坤元曷纷矫。\n默然置此去，变化谁能了。'},
    {t:'入蒲关先寄秦中故人',a:'岑参〔唐代〕',c:'秦山数点似青黛，渭上一条如白练。\n京师故人不可见，寄将两眼看飞燕。'},
    {t:'入峡寄弟',a:'孟浩然〔唐代〕',c:'吾昔与尔辈，读书常闭门。\n未尝湖湍险，岂顾垂堂言。\n自此历江湖，辛勤难具论。\n往来行旅弊，开壑禹功存。\n壁立千峰峻，潈流万壑奔。\n我来凡几宿，无夕不闻猿。\n浦上摇归恋，舟中失梦魂。\n泪沾明月峡，心断鹡鸰原。\n离阔星难聚，秋深露已繁。\n因君下南楚，书此示乡园。'},
    {t:'入狱第一百四',a:'文天祥〔宋代〕',c:'徘徊虎穴上，吾道正羁束。\n落日将何如，清文动哀玉。'},
    {t:'入狱第一百一',a:'文天祥〔宋代〕',c:'行行见羁束，斯人独憔悴。\n欲觉闻晨钟，青灯死分翳。'},
    {t:'阮郎归',a:'周邦彦〔宋代〕',c:'菖蒲叶老水平沙。临流苏小家。烧阑曲径宛秋蛇。金英垂露华。\n烧蜜炬，引莲娃。酒香薰脸霞。再来重约日西斜。倚门听暮鸦。'},
    {t:'阮郎归',a:'晏几道〔宋代〕',c:'晚妆长趁景阳钟。双蛾著意浓。舞腰浮动绿云浓。樱桃半点红。\n怜美景，惜芳容。沈思暗记中。春寒帘幕几重重。杨花尽日风。'},
    {t:'阮郎归·茶词',a:'黄庭坚〔宋代〕',c:'摘山初制小龙团。色和香味全。碾声初断夜将阑。烹时鹤避烟。\n消滞思，解尘烦。金瓯雪浪翻。只愁啜罢水流天。余清搅夜眠。'},
    {t:'阮郎归·初夏',a:'苏轼〔宋代〕',c:'绿槐高柳咽新蝉。薰风初入弦。碧纱窗下水沉烟。棋声惊昼眠。\n微雨过，小荷翻。榴花开欲然。玉盆纤手弄清泉。琼珠碎却圆。'},
    {t:'阮郎归·春风吹雨绕残枝',a:'秦观〔宋代〕',c:'春风吹雨绕残枝，落花无可飞。帘池寒渌欲生漪，雨晴还日西。\n帘半卷，燕双归。讳愁无奈眉。翻身整顿着残棋，沉吟应劫迟。'},
    {t:'阮郎归·粉痕闲印玉尖纤',a:'晏几道〔宋代〕',c:'粉痕闲印玉尖纤。啼红傍晚奁。春寒新暖尚相兼。梅疏待雪添。\n春冉冉，恨恹恹。章台对卷帘。个人鞭影弄凉蟾。楼前侧帽檐。'},
    {t:'阮郎归·宫腰袅袅翠鬟松',a:'秦观〔宋代〕',c:'宫腰袅袅翠鬟松，夜堂深处逢。无端银烛殒秋风，灵犀得暗通。\n身有恨，恨无穷，星河沉晓空。陇头流水各西东，佳期如梦中。'},
    {t:'阮郎归·旧香残粉似当初',a:'晏几道〔宋代〕',c:'旧香残粉似当初。人情恨不如。一春犹有数行书。秋来书更疏。\n衾凤冷，枕鸳孤。愁肠待酒舒。梦魂纵有也成虚。那堪和梦无。'},
    {t:'阮郎归·来时红日弄窗纱',a:'晏几道〔宋代〕',c:'来时红日弄窗纱，\n春红入睡霞。\n收时庭树欲栖鸦。\n香屏掩月斜。\n收翠羽，整妆华，\n青骊信又差。\n玉笙犹恋碧桃花，\n今宵未忆家。'},
    {t:'阮郎归·烹茶留客驻金鞍',a:'黄庭坚〔宋代〕',c:'烹茶留客驻金鞍。月斜窗外山。别郎容易见郎难。有人思远山。\n归去后，忆前欢。画屏金博山。一杯春露莫留残。与郎扶玉山。'},
    {t:'阮郎归·山前风雨欲黄昏',a:'辛弃疾〔宋代〕',c:'山前风雨欲黄昏，山头来去云。鹧鸪声里数家村，潇湘逢故人。\n挥羽扇，整纶巾。少年鞍马尘，如今憔悴赋招魂，儒冠多误身。'},
    {t:'阮郎归·四之一',a:'秦观〔宋代〕',c:'退花新绿渐团枝。扑人风絮飞。秋千未拆水平堤。落红成地衣。\n游蝶困，乳莺啼。怨春春怎知。日长早被酒禁持。那堪更别离。'},
    {t:'阮郎归·天边金掌露成霜',a:'晏几道〔宋代〕',c:'天边金掌露成霜。云随雁字长。绿杯红袖趁重阳。人情似故乡。\n兰佩紫，菊簪黄。殷勤理旧狂。欲将沉醉换悲凉。清歌莫断肠。'},
    {t:'阮郎归·褪花新绿渐团枝',a:'秦观〔宋代〕',c:'褪花新绿渐团枝。扑人风絮飞。秋千未拆水平堤。落红成地衣。游蝶困，乳莺啼。怨春春怎知。日长早被酒禁持。那堪更别离。'},
    {t:'阮郎归·晚妆长趁景阳钟',a:'晏几道〔宋代〕',c:'晚妆长趁景阳钟，\n双娥着意浓。\n舞腰浮动绿云浓，\n樱桃半点红。\n怜美景，惜芳容，\n沉思暗记中。\n春寒帘幕几重重，\n杨花尽日风。'},
    {t:'阮郎归·湘天风雨破寒初',a:'秦观〔宋代〕',c:'湘天风雨破寒初。深沉庭院虚。丽谯吹罢小单于。迢迢清夜徂。\n乡梦断，旅魂孤。峥嵘岁又除。衡阳犹有雁传书。郴阳和雁无。'},
    {t:'阮郎归·潇湘门外水平铺',a:'秦观〔宋代〕',c:'潇湘门外水平铺，月寒征棹孤。红妆饮罢少踟蹰，有人偷向隅。\n挥玉箸，洒真珠，梨花春雨馀。人人尽道断肠初，那堪肠已无。'},
    {t:'阮郎归·有怀北游',a:'张炎〔宋代〕',c:'钿车骄马锦相连，香尘逐管弦。瞥然飞过水秋千。清明寒食天。\n花贴贴，柳悬悬。莺房几醉眠。醉中不信有啼鹃。江南二十年。'},
    {t:'阮郎归其四',a:'秦观〔宋代〕',c:'湘天风雨破寒初，深沈庭院虚。丽谯吹罢小单于，迢迢清夜徂。\n乡梦断，旅魂孤，峥嵘岁又除。衡阳犹有雁传书，郴阳和雁无。'},
    {t:'瑞鹤仙',a:'周邦彦〔宋代〕',c:'暖烟笼细柳。弄万缕千丝，年年情色。晴风荡无际，浓于酒、偏醉情人调客。阑干倚处，度花香、微院酒力。对重门半掩，黄昏淡月，院宇深寂。\n愁极。因思前事，洞房佳宴，正值寒食。寻芳遍赏，金谷里，铜驼陌。到而今、鱼雁沈沈无信，天涯常是泪滴。早归来，云馆深处，那人正忆。'},
    {t:'瑞鹤仙·赋梅',a:'辛弃疾〔宋代〕',c:'雁霜寒透幕。正护月云轻，嫩冰犹薄。溪奁照梳掠。想含香弄粉，艳妆难学。玉肌瘦弱。更重重、龙绡衬著。倚东风，一笑嫣然，转盼万花羞落。\n寂寞。家山何在，雪后园林，水边楼阁。瑶池旧约。鳞鸿更仗谁托。粉蝶儿只解，寻桃觅柳，开遍南枝未觉。但伤心，冷落黄昏，数声画角。'},
    {t:'瑞鹤仙·环滁皆山也',a:'黄庭坚〔宋代〕',c:'环滁皆山也。望蔚然深秀，琅琊山也。山行六七里，有翼然泉上，醉翁亭也。翁之乐也。得之心、寓之酒也。更野芳佳木，风高日出，景无穷也。\n游也。山肴野蔌，酒洌泉香，沸筹觥也。太守醉也。喧哗众宾欢也。况宴酣之乐、非丝非竹，太守乐其乐也。问当时、太守为谁，醉翁是也。'},
    {t:'瑞鹤仙·悄郊原带郭',a:'周邦彦〔宋代〕',c:'悄郊原带郭，行路永，客去车尘孤孤。斜阳映山落，敛馀红、犹恋孤城阑角。凌波步弱，过短亭、何缓素约。有流莺劝我，重解绣鞍，缓引春酌。\n不记归时早暮，上马谁扶，醒眠朱阁。惊飙动幕，扶残醉，绕红药。叹西园、已是花深无地，东风何事又恶？任流光过却，犹喜洞天自乐。'},
    {t:'瑞鹤仙·赵文升席上代去姬写怀',a:'张炎〔宋代〕',c:'楚云分断雨。问那回、因甚琴心先许。匆匆话离绪。正花房蜂闹，著春无处。残歌剩舞。尚隐约、当时院宇。黯消凝、铜雀深深，忍把小乔轻误。\n休赋。玉尊别后，老叶沈沟，暗珠还浦。欢游再数。能几日、采芳去。最无端做了，霎时娇梦，不道风流恁苦。把余情、付与秋蛩，夜长自语。'},
    {t:'瑞龙吟·大石春景',a:'周邦彦〔宋代〕',c:'章台路。还见褪粉梅梢，试花桃树。愔愔坊陌人家，定巢燕子，归来旧处。\n黯凝伫。因念个人痴小，乍窥门户。侵晨浅约宫黄，障风映袖，盈盈笑语。\n前度刘郎重到，访邻寻里，同时歌舞。唯有旧家秋娘，声价如故。吟笺赋笔，犹记燕台句。知谁伴、名园露饮，东城闲步。事与孤鸿去。探春尽是，伤离意绪。官柳低金缕。归骑晚、纤纤池塘飞雨。断肠院落，一帘风絮。'},
    {t:'瑞鹧鸪·宝髻瑶簪',a:'柳永〔宋代〕',c:'宝髻瑶簪。严妆巧，天然绿媚红春。绮罗丛里，独逞讴吟。一曲阳春定价，何啻值千金。倾听处，王动帝子，鹤盖成阴。\n凝态掩霞襟。动象板声声，怨思难任。嘹亮处，回厌弦管低沈。时恁回眸敛黛，空役五陵心。须信道，缘情寄意。别有知音。'},
    {t:'瑞鹧鸪·江南残腊欲归时',a:'晏殊〔宋代〕',c:'江南残腊欲归时。有梅红亚雪中枝。一夜前村、间破瑶英拆，端的千花冷未知。\n丹青改样匀朱粉，雕梁欲画犹疑。何妨与向冬深，密种秦人路，夹仙溪。不待夭桃客自迷。'},
    {t:'瑞鹧鸪·期思溪上日千回',a:'辛弃疾〔宋代〕',c:'期思溪上日千回，樟木桥边酒带杯。人影不随流水去，醉颜重带少年来。\n疏蝉响涩林逾静，冷蝶飞轻菊半开。不是长卿终慢世，只缘多病又非才。'},
    {t:'瑞鹧鸪·全吴嘉会古风流',a:'柳永〔宋代〕',c:'全吴嘉会古风流。渭南往岁忆里游。西子方里、越相功成去，千里沧江一叶舟。\n至今无限盈盈者，尽里拾翠芳洲。最是簇簇寒村，遥认南朝路、晚烟收。三两人家古渡头。'},
    {t:'瑞鹧鸪·天将奇艳与寒梅',a:'柳永〔宋代〕',c:'天将奇艳与寒梅。乍惊繁杏腊前开。暗想花神、巧作江南信，鲜染燕脂细翦裁。\n寿阳妆罢无端饮，凌晨酒入香腮。恨听烟坞深中，谁恁吹羌管、逐风来。绛雪纷纷落翠苔。'},
    {t:'瑞鹧鸪·吴会风流',a:'柳永〔宋代〕',c:'吴会风流。人烟好，高下水际山闾。瑶台绛阙，依约蓬丘。万井千闾富庶，雄压十三州。触处青蛾讼舸，红粉朱楼。\n方面委元侯。致讼简时丰，继日欢游。襦温袴暖，已扇民讴。旦暮锋车命驾，重整济川舟。当恁时，沙堤路稳，归去难留。'},
    {t:'瑞鹧鸪·咏红梅',a:'晏殊〔宋代〕',c:'越娥红泪泣朝云，越梅从此学妖嚬。腊月初头、庾岭繁开后，特染妍华赠世人。\n前溪昨夜深深雪，朱颜不掩天真。何时驿使西归，寄与相思客，一枝新。报道江南别样春。'},
    {t:'睿恩新·芙蓉一朵霜秋色',a:'晏殊〔宋代〕',c:'芙蓉一朵霜秋色。迎晓露、依依先拆。似佳人、独立倾城，傍朱槛、暗传消息。\n静对西风脉脉。金蕊绽、粉红如滴。向兰堂、莫厌重深，免清夜、微寒渐逼。'},
    {t:'睿恩新·红丝一曲傍阶砌',a:'晏殊〔宋代〕',c:'红丝一曲傍阶砌。珠露下、独呈纤丽。剪鲛绡、碎作香英，分彩线、簇成娇蕊。\n向晚群花欲悴。放朵朵、似延秋意。待佳人、插向钗头，更袅袅、低临凤髻。'},
    {t:'闰九月九日',a:'晏殊〔宋代〕',c:'闰秋重九再佳辰，犹见黄花裛露新。\n更作登高亦何害，恨无彭泽苦吟人。'},
    {t:'润州二首',a:'杜牧〔唐代〕',c:'句吴亭东千里秋，放歌曾作昔迹游。\n青苔寺里无马迹，绿水桥边多酒楼。\n大抵南朝更旷达，可怜东晋最风流。\n月明更想桓伊在，一笛闻吹出塞愁。\n谢朓诗中佳丽地，夫差传里水犀军。\n城高铁瓮横强弩，柳暗朱楼多梦云。\n画角爱飘江北去，钓歌长向月中闻。\n扬州尘土试回首，不惜千金借与君。'},
    {t:'若邪春兴',a:'皎然〔唐代〕',c:'春生若邪水，雨后漫流通。芳草行无尽，清源去不穷。\n野烟迷极浦，斜日起微风。数处乘流望，依稀似剡中。'},
    {t:'若耶溪归兴',a:'王安石〔宋代〕',c:'若耶溪上踏莓苔，兴罢张帆载酒回。\n汀草岸花浑不见，青山无数逐人来。'},
    {t:'塞孤·般涉调',a:'柳永〔宋代〕',c:'一声鸡，又报残更歇。秣马巾车催发。草草主人灯下别。山路险，新霜滑。瑶珂响、起栖乌，金钲冷、敲残月。渐西风紧，襟袖凄裂。\n遥指白玉京，望断黄金阙。远道何时行彻。算得佳人凝恨切。应念念，归时节。相见了、执柔夷，幽会处、偎香雪。免鸳衾、两恁虚设。'},
    {t:'塞寒行',a:'温庭筠〔唐代〕',c:'燕弓弦劲霜封瓦，朴簌寒雕睇平野。\n一点黄尘起雁喧，白龙堆下千蹄马。\n河源怒浊风如刀，剪断朔云天更高。\n晚出榆关逐征北，惊沙飞迸冲貂袍。\n心许凌烟名不灭，年年锦字伤离别。\n彩毫一画竟何荣，空使青楼泪成血。'},
    {t:'塞鸿秋·爱他时似爱初生月',a:'佚名〔元代〕',c:'爱他时似爱初生月，江他时似江看梅梢月，想他时道几首西江月，盼他时似盼辰钩月。当初意儿别，今日相抛撇，要相逢似水底捞明月。'},
    {t:'塞鸿秋·山行警',a:'佚名〔元代〕',c:'东边路西边路南边路，五里铺懒里铺十里铺。行一步盼一步懒一步，霎时间天也暮日也暮云也暮。斜阳满地铺，回首生烟雾。兀的不山无数水无数情无数。'},
    {t:'塞上',a:'高适〔唐代〕',c:'东出卢龙塞，浩然客思孤。\n亭堠列万里，汉兵犹备胡。\n边尘涨北溟，虏骑正南驱。\n转斗岂长策，和亲非远图。\n惟昔李将军，按节出皇都。\n总戎扫大漠，一战擒单于。\n常怀感激心，愿效纵横谟。\n倚剑欲谁语，关河空郁纡。'},
    {t:'塞上曲',a:'李白〔唐代〕',c:'大汉无中策，匈奴犯渭桥。\n五原秋草绿，胡马一何骄。\n命将征西极，横行阴山侧。\n燕支落汉家，妇女无华色。\n转战渡黄河，休兵乐事多。\n萧条清万里，瀚海寂无波。'},
    {t:'塞上听吹笛',a:'高适〔唐代〕',c:'雪净胡天牧马还，月明羌笛戍楼间。\n借问梅花何处落，风吹一夜满关山。'},
    {t:'塞翁吟·大石',a:'周邦彦〔宋代〕',c:'暗叶啼风雨，窗外晓色珑璁。散簟麝，小池东。乱一岸芙蓉。蕲州簟展双纹浪，轻帐翠缕如空。梦忡远别、泪痕重。淡铅脸斜红。\n忡忡。嗟憔悴、新宽带结，羞艳冶、都销镜中。有蜀纸、堪凭寄恨，等今夜、洒血书词，剪烛亲封。菖蒲渐老，早晚成花，教见薰风。'},
    {t:'塞翁吟·友云',a:'张炎〔宋代〕',c:'交到无心处，出岫细话幽期。看流水、意俱迟。且淡薄相依。凌霄未肯从龙去，物外共鹤忘机。迷古洞，掩晴晖。翠影湿行衣。\n飞飞。垂天翼，飘然万里，愁日暮、佳人未归。尚记得、巴山夜雨，耿无语、共说生平，都付陶诗。休题五朵，莫梦阳台，不赠相思。'},
    {t:'塞下曲',a:'高适〔唐代〕',c:'结束浮云骏，翩翩出从戎。\n且凭天子怒，复倚将军雄。\n万鼓雷殷地，千旗火生风。\n日轮驻霜戈，月魄悬雕弓。\n青海阵云匝，黑山兵气冲。\n战酣太白高，战罢旄头空。\n万里不惜死，一朝得成功。\n画图麒麟阁，入朝明光宫。\n大笑向文士，一经何足穷。\n古人昧此道，往往成老翁。'},
    {t:'塞下曲',a:'张籍〔唐代〕',c:'边州八月修城堡，候骑先烧碛中草。\n胡风吹沙度陇飞，陇头林木无北枝。\n将军阅兵青塞下，鸣鼓逢逢促猎围。\n天寒山路石断裂，白日不销帐上雪。\n乌孙国乱多降胡，诏使名王持汉节。\n年年征战不得闲，边人杀尽唯空山。'},
    {t:'塞下曲',a:'李贺〔唐代〕',c:'胡角引北风，蓟门白于水。\n天含青海道，城头月千里。\n露下旗濛濛，寒金鸣夜刻。\n蕃甲锁蛇鳞，马嘶青冢白。\n秋静见旄头，沙远席羁愁。\n帐北天应尽，河声出塞流。'},
    {t:'塞下曲',a:'王昌龄〔唐代〕',c:'饮马渡秋水，水寒风似刀。\n平沙日未没，黯黯见临洮。\n昔日长城战，咸言意气高。\n黄尘足今古，白骨乱蓬蒿。'},
    {t:'塞下曲·贺兰作',a:'高适〔唐代〕',c:'君不见芳树枝，春花落尽蜂不窥。君不见梁上泥，\n秋风始高燕不栖。荡子从军事征战，蛾眉婵娟守空闺。\n独宿自然堪下泪，况复时闻鸟夜啼。'},
    {t:'塞下曲·秋风夜渡河',a:'王昌龄〔唐代〕',c:'秋风夜渡河，吹却雁门桑。\n遥见胡地猎，鞴马宿严霜。\n五道分兵去，孤军百战场。\n功多翻下狱，士卒但心伤。'},
    {t:'塞下曲六首·其一',a:'李白〔唐代〕',c:'五月天山雪，无花只有寒。\n笛中闻折柳，春色未曾看。\n晓战随金鼓，宵眠抱玉鞍。\n愿将腰下剑，直为斩楼兰。'},
    {t:'塞下曲四首其三',a:'王昌龄〔唐代〕',c:'奉诏甘泉宫，总徵天下兵。朝廷备礼出，郡国豫郊迎。\n纷纷几万人，去者无全生。臣愿节宫厩，分以赐边城。'},
    {t:'塞下曲四首其四',a:'王昌龄〔唐代〕',c:'边头何惨惨，已葬霍将军。部曲皆相吊，燕南代北闻。\n功勋多被黜，兵马亦寻分。更遣黄龙戍，唯当哭塞云。'},
    {t:'塞垣春·大石',a:'周邦彦〔宋代〕',c:'暮色分平野。傍苇岸、征帆卸。烟别极浦，树藏孤馆，秋景如画。渐别离气味难禁也。更物象、供潇写。念多材浑衰减，一怀幽恨难写。\n追念绮窗人，天然自、风韵娴雅。竟夕起相思，谩嗟怨遥夜。又还将、两袖珠泪，沈吟向寂寥寒灯下。玉骨为多感，瘦来无一把。'},
    {t:'三部乐·商调梅雪',a:'周邦彦〔宋代〕',c:'浮玉飞琼，向邃馆静轩，倍增清绝。夜窗垂练，何用交光明月。近闻道、官阁多梅，趁暗香未远，冻蕊初发。倩谁摘取，寄赠情人桃叶。\n回文近传锦字，道为君瘦损，是人都说。祅知染红著手，胶梳黏发。转思量、镇长堕睫。都只为、情深意切。欲报消息，无一句、堪愈愁结。'},
    {t:'三花斛三首右兰花',a:'杨万里〔宋代〕',c:'雪径偷开浅碧花，冰根乱吐小红芽。\n生无桃李春风面，名在山林处士家。\n政坐国香到朝市，不容霜节老云霞。\n江蓠圃蕙非吾耦，付与骚人定等差。'},
    {t:'三江小渡',a:'杨万里〔宋代〕',c:'溪水将桥不复回，小舟犹倚短篙开。\n交情得似山溪渡，不管风波去又来。'},
    {t:'三绝句',a:'杜甫〔唐代〕',c:'前年渝州杀刺史，今年开州杀刺史。\n群盗相随剧虎狼，食人更肯留妻子。\n二十一家同入蜀，惟残一人出骆谷。\n自说二女啮臂时，回头却向秦云哭。\n殿前兵马虽骁雄，纵暴略与羌浑同。\n闻道杀人汉水上，妇女多在官军中。'},
    {t:'三君咏·狄梁公·仁杰',a:'高适〔唐代〕',c:'梁公乃贞固，勋烈垂竹帛。昌言太后朝，潜运储君策。\n待贤开相府，共理登方伯。至今青云人，犹是门下客。'},
    {t:'三君咏·郭代公·元振',a:'高适〔唐代〕',c:'代公实英迈，津涯浩难识。拥兵抗矫征，仗节归有德。\n纵横负才智，顾盼安社稷。流落勿重陈，怀哉为凄恻。'},
    {t:'三君咏·魏郑公·徵',a:'高适〔唐代〕',c:'郑公经纶日，隋氏风尘昏。济代取高位，逢时敢直言。\n道光先帝业，义激旧君恩。寂寞卧龙处，英灵千载魂。'},
    {t:'三拍',a:'文天祥〔宋代〕',c:'三年奔走空皮骨，三年笛里关山月。\n中天月色好谁看，豺狼塞路人烟绝。\n寒刮肌肤北风利，牛马毛零缩如蝟。\n塞上风云接地阴，咫尺但愁雷雨至。'},
    {t:'三山杜门作歌',a:'陆游〔宋代〕',c:'我生学步逢丧乱，家在中原厌待窜。\n淮边夜闻贼马嘶，跳去不待鸡号旦。\n人怀一饼草间伏，往往经旬不炊爨。\n呜呼！乱定百口俱得全，孰为此者宁非天！'},
    {t:'三姝媚·芙蓉城伴侣',a:'张炎〔宋代〕',c:'海云寺千叶杏二株，奇丽可观，江南所无。越一日，过傅岩起清晏堂。见古瓶中数枝，云自海云来，名芙蓉杏。因爱玩不去，岩起索赋此曲。\n芙蓉城伴侣。乍卸却单衣，茜罗重护。傍水开时，细看来、浑似阮郎前度。记得小楼，听一夜、江南春雨。梦醒箫声，流水青苹，旧游何许。\n谁翦层芳深贮。便洗尽长安，半面尘土。绝似桃根，带笑痕来伴，柳枝娇舞。莫是孤村，试与问、酒家何处。曾醉梢头双果，园林未暑。'},
    {t:'三姝媚·送舒亦山游越',a:'张炎〔宋代〕',c:'苍潭枯海树。正雪窦高寒，水声东去。古意萧闲，问结庐人远，白云谁侣。贺监犹狂，还散迹、千岩风露。抱瑟空游，都是凄凉，此愁难语。\n莫趁江湖鸥鹭。怕太乙炉荒，暗消铅虎。投老心情，未归来何事，共成羁旅。布袜青鞋，休误入、桃源深处。待得重逢却说，巴山夜雨。'},
    {t:'三台二首其二',a:'韦应物〔唐代〕',c:'冰泮寒塘始绿，雨馀百草皆生。朝来门閤无事，晚下高斋有情。'},
    {t:'三五七言',a:'李白〔唐代〕',c:'秋风清，秋月明，\n落叶聚还散，寒鸦栖复惊。\n相思相见知何日？此时此夜难为情！\n入我相思门，知我相思苦。\n长相思兮长相忆，短相思兮无穷极。\n早知如此绊人心，何如当初莫相识。'},
    {t:'三峡歌',a:'陆游〔宋代〕',c:'十二巫山见九峰，船头彩翠满秋空。\n朝云暮雨浑虚语，一夜猿啼明月中。'},
    {t:'三星行',a:'韩愈〔唐代〕',c:'我生之辰，月宿南斗。\n牛奋其角，箕张其口。\n牛不见服箱，斗不挹酒浆。\n箕独有神灵，无时停簸扬。\n无善名已闻，无恶声已讙。\n名声相乘除，得少失有馀。\n三星各在天，什伍东西陈。\n嗟汝牛与斗，汝独不能神。'},
    {t:'三原李氏园宴集',a:'张籍〔唐代〕',c:'暮春天早热，邑居苦嚣烦。言从君子乐，乐彼李氏园。\n园中有草堂，池引泾水泉。开户西北望，远见嵯峨山。\n借问主人翁，北州佐戎轩。仆夫守旧宅，为客侍华筵。\n高怀有馀兴，竹树芳且鲜。倾我所持觞，尽日共留连。\n疏拙不偶俗，常喜形体闲。况来幽栖地，能不重叹言。'},
    {t:'三月二十七日送春绝句',a:'杨万里〔宋代〕',c:'只余三日便清和，尽放春归莫恨他。\n落尽千花飞尽絮，留春肯住欲如何。'},
    {t:'三月过行宫',a:'李贺〔唐代〕',c:'渠水红繁拥御墙，风娇小叶学娥妆。\n垂帘几度青春老，堪锁千年白日长。'},
    {t:'三月晦日偶题',a:'秦观〔宋代〕',c:'节物相催各自新，痴心儿女挽留春。\n芳菲歇去何须恨，夏木阴阴正可人。'},
    {t:'三月三日寄诸弟兼怀崔都水',a:'韦应物〔唐代〕',c:'暮节看已谢，兹晨愈可惜。风澹意伤春，池寒花敛夕。\n对酒始依依，怀人还的的。谁当曲水行，相思寻旧迹。'},
    {t:'三月三日勤政楼侍宴应制',a:'王维〔唐代〕',c:'彩仗连宵合，琼楼拂曙通。\n年光日月里，宫殿百花中。\n不数秦王日，谁将洛水同。\n酒筵嫌落絮，舞袖怯春风。\n天保无为德，人欢不战功。\n仍临九衢宴，更达四门聪。'},
    {t:'三月三日曲江侍宴应制',a:'王维〔唐代〕',c:'万乘亲斋祭，千官喜豫游。奉迎卫上苑，祓禊向中流。\n草树连容卫，山河对冕旒。画旗摇浦溆，春服满汀洲。\n仙籞龙媒下，神皋凤跸留。卫今亿万岁，天宝纪春秋。'},
    {t:'三月三日申王园亭宴集',a:'张九龄〔唐代〕',c:'稽亭追往事，睢苑胜前闻。飞阁凌芳树，华池落彩云。\n藉草人留酌，衔花鸟赴群。向来同赏处，惟恨碧林曛。'},
    {t:'三月三十日题慈恩寺',a:'白居易〔唐代〕',c:'慈恩春色今朝尽，尽日裴回倚寺门。\n惆怅春归留不得，紫藤花下渐黄昏。'},
    {t:'三月十七日夜醉中作',a:'陆游〔宋代〕',c:'前年脍鲸东海上，白浪如山寄豪壮。\n去年射虎南山秋，夜归急雪满貂裘。\n今年摧颓最堪笑，华发苍颜羞自照。\n谁知得酒尚能狂，脱帽向人时大叫。\n逆胡未灭心未平，孤剑床头铿有声。\n破驿梦回灯欲死，打窗风雨正三更。'},
    {t:'三月十日流杯亭',a:'李商隐〔唐代〕',c:'身属中军少得归，木兰花尽失春期。\n偷随柳絮到城外，行过水西闻子规。'},
    {t:'三赠刘员外',a:'柳宗元〔唐代〕',c:'信书成自误，经事渐知非。\n今日临岐别，何年待汝归。'},
    {t:'散发一扁舟',a:'王安石〔宋代〕',c:'散发一扁舟，夜长眠屡起。\n秋水泻明河，迢迢藕花底。\n爱此露的皪，复怜云绮靡。\n谅无与歌弦，幽独亦可喜。'},
    {t:'桑茶坑道中',a:'杨万里〔宋代〕',c:'晴明风日雨干时，草满花堤水满溪。\n童子柳阴眠正着，一牛吃过柳阴西。'},
    {t:'桑生李树',a:'佚名',c:'南顿张助，于田中种禾，见李核，欲持去，顾见空桑，中有土，因植种，以余浆溉灌。后人见桑中反复生李，转相告语。有病目痛者，息阴下，言：“李君令我目愈，谢以一豚。”目痛小疾，亦行自愈。众犬吠声，盲者得视，远近翕赫，其下车骑常数千百，酒肉滂沱。间一岁余，张助远出来还，见之，惊云：“此有何神，乃我所种耳。”因就斫之。'},
    {t:'扫地花·晓阴翳日',a:'周邦彦〔宋代〕',c:'晓阴翳日，正雾霭烟横，远迷平楚。暗黄万缕。听鸣禽按曲，小腰欲舞。细绕回堤，驻马河桥避雨。信流去。想一叶怨题，今在何处。\n春事能几许。任占地持杯，扫花寻路。泪珠溅俎。叹将愁度日，病伤幽素。恨入金徽，见说文君更苦。黯凝伫。掩重关、遍城钟鼓。'},
    {t:'扫花游',a:'张炎〔宋代〕',c:'烟霞万壑，记曲径幽寻，霁痕初晓。绿窗窈窕。看随花甃石，就泉通沼。几日不来，一片苍云未扫。自长啸。怅乔木荒凉，都是残照。\n碧天秋浩渺。听虚籁泠泠，飞下孤峭。山空翠老。步仙风，怕有采芝人到。野色闲门，芳草不除更好。境深悄。比斜川、又清多少。'},
    {t:'瑟瑟钗',a:'温庭筠〔唐代〕',c:'翠染冰轻透露光，堕云孙寿有馀香。\n只因七夕回天浪，添作湘妃泪两行。'},
    {t:'僧院花',a:'白居易〔唐代〕',c:'欲悟色空为佛事，故栽芳树在僧家。\n细看便是华严偈，方便风开智慧花。'},
    {t:'杀气不在边',a:'孟郊〔唐代〕',c:'杀气不在边，凛然中国秋。道险不在山，平地有摧輈。\n河南又起兵，清浊俱锁流。岂唯私客艰，拥滞官行舟。\n况余隔晨昏，去家成阻修。忽然两鬓雪，同是一日愁。\n独寝夜难晓，起视星汉浮。凉风荡天地，日夕声飕飗。\n万物无少色，兆人皆老忧。长策苟未立，丈夫诚可羞。\n灵响复何事，剑鸣思戮雠。'},
    {t:'沙堤行·呈裴相公',a:'张籍〔唐代〕',c:'长安大道沙为堤，早风无尘雨无泥。\n宫中玉漏下三刻，朱衣导骑丞相来。\n路傍高楼息歌吹，千车不行行者避。\n街官闾吏相传呼，当前十里惟空衢。\n白麻诏下移相印，新堤未成旧堤尽。'},
    {t:'沙路曲',a:'李贺〔唐代〕',c:'柳脸半眠丞相树，佩马钉铃踏沙路。断烬遗香袅翠烟，烛骑啼乌上天去。\n帝家玉龙开九关，帝前动笏移南山。独垂重印押千官，金窠篆字红屈盘。\n沙路归来闻好语，旱火不光天下雨。'},
    {t:'沙丘城下寄杜甫',a:'李白〔唐代〕',c:'我来竟何事，高卧沙丘城。\n城边有古树，日夕连秋声。\n鲁酒不可醉，齐歌空复情。\n思君若汶水，浩荡寄南征。'},
    {t:'沙苑南渡头',a:'王昌龄〔唐代〕',c:'秋雾连云白，归心浦溆悬。津人空守缆，村馆复临川。\n篷隔苍茫雨，波连演漾田。孤舟未得济，入梦在何年。'},
    {t:'山茶',a:'杨万里〔宋代〕',c:'树子团团映碧岑，初看唤作木红林。\n谁将金粟银丝脍，簇飣朱红菜碗心。\n春早横招桃李妒，岁寒不受雪霜侵。\n题诗毕竟轮坡老，叶厚有棱花色深。'},
    {t:'山茶一树自冬至清明后著花不已',a:'陆游〔宋代〕',c:'东园三日雨兼风，桃李飘零扫地空。\n惟有山茶偏耐久，绿丛又放数枝红。'},
    {t:'山丹花',a:'杨万里〔宋代〕',c:'春去无芳可得寻，山丹最晚出云林。\n柿红一色明罗袖，金粉群虫集宝簪。\n花似鹿匆还耐久，叶如芍药不多深。\n青泥瓦斛移山菂，聊著书窗伴小吟。'},
    {t:'山房春事二首',a:'岑参〔唐代〕',c:'风恬日暖荡春光，戏蝶游蜂乱入房。\n数枝门柳低衣桁，一片山花落笔床。\n梁园日暮乱飞鸦，极目萧条三两家。\n庭树不知人去尽，春来还发旧时花。'},
    {t:'山鬼谣·摸鱼儿',a:'辛弃疾〔宋代〕',c:'问何年，此山来此，西风落日无语。看君似是羲皇上，直作太初名汝。溪上路。算只有、红尘不到今犹古。一杯谁举。笑我醉呼君，崔嵬未起，山鸟覆杯去。\n须记取。昨夜龙湫风雨。门前石浪掀舞。四更山鬼吹灯啸，惊倒世间儿女。依约处。还问我、清游杖屦公良苦。神交心许。待万里携君，鞭笞鸾凤，诵我远游赋。'},
    {t:'山鬼谣·问何年此山来此',a:'辛弃疾〔宋代〕',c:'雨岩有石，状怪甚，取《离骚》《九歌》，名曰“山鬼”，因赋《摸鱼儿》，改今名。\n问何年、此山来此？西风落日无语。看君似是羲皇上，直作太初名汝。溪上路，算只有、红尘不到今犹古。一杯谁举？笑我醉呼君，崔嵬未起，山鸟覆杯去。\n须记取：昨夜龙湫风雨，门前石浪掀舞。四更山鬼吹灯啸，惊倒世间儿女。依约处，还问我：清游杖履公良苦。神交心许。待万里携君，鞭笞鸾凤，诵我《远游》赋。'},
    {t:'山花子·风絮飘残已化萍',a:'纳兰性德〔清代〕',c:'风絮飘残已化萍，泥莲刚倩藕丝萦。珍重别拈香一瓣，记前生。\n人到情多情转薄，而今真个不多情。又到断肠回首处，泪偷零。'},
    {t:'山花子·林下荒苔道韫家',a:'纳兰性德〔清代〕',c:'林下荒苔道韫家，生怜玉骨委尘沙。愁向风前无处说，数归鸦。\n半世浮萍随逝水，一宵冷雨葬名花。魂是柳绵吹欲碎，绕天涯。'},
    {t:'山花子·小立红桥柳半垂',a:'纳兰性德〔清代〕',c:'小立红桥柳半垂，越罗裙飏缕金衣。采得石榴双叶子，欲贻谁？\n便是有情当落日，只应无伴送斜晖。寄语东风休著力，不禁吹。'},
    {t:'山花子·欲话心情梦已阑',a:'纳兰性德〔清代〕',c:'欲话心情梦已阑，镜中依约见春山。方悔从前真草草，等闲看。\n环佩只应归月下，钿钗何意寄人间。多少滴残红蜡泪，几时干。'},
    {t:'山鸡',a:'王安石〔宋代〕',c:'山鸡照渌水，自爱一何愚。\n文采为世用，适足累形躯。'},
    {t:'山居即事',a:'王维〔唐代〕',c:'寂寞掩柴扉，苍茫对落晖。\n鹤巢松树遍，人访荜门稀。\n绿竹含新粉，红莲落故衣。\n渡头烟火起，处处采菱归。'},
    {t:'山居秋暝',a:'王维〔唐代〕',c:'空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。\n竹喧归浣女，莲动下渔舟。\n随意春芳歇，王孙自可留。'},
    {t:'山居示灵澈上人',a:'皎然〔唐代〕',c:'晴明路出山初暖，行踏春芜看茗归。\n乍削柳枝聊代札，时窥云影学裁衣。\n身闲始觉隳名是，心了方知苦行非。\n外物寂中谁似我，松声草色共无机。'},
    {t:'山老吟',a:'孟郊〔唐代〕',c:'不行山下地，唯种山上田。腰斧斫旅松，手瓢汲家泉。\n讵知文字力，莫记日月迁。蟠木为我身，始得全天年。'},
    {t:'山南行',a:'陆游〔宋代〕',c:'我行山南已三日，如绳大道东青出。\n平川沃野望不尽，麦陇青青桑郁郁。\n地近函秦气俗豪，秋健蹴鞠分朋曹。\n苜蓿连云马蹄健，杨柳夹道车声高。\n古来历历兴亡处，举目山川尚如故。\n将军坛上冷云低，丞相祠前春日暮。\n国家四纪失中原，师出江淮未易吞。\n会看金鼓从天下，却用关中作本根。'},
    {t:'山枇杷',a:'白居易〔唐代〕',c:'深山老去惜年华，况对东溪野枇杷。\n火树风来翻绛焰，琼枝日出晒红纱。\n回看桃李都无色，映得芙蓉不是花。\n争奈结根深石底，无因移得到人家。'},
    {t:'山坡羊·一个犁牛半块田',a:'佚名',c:'一个犁牛半块田，收也凭天，荒也凭天。\n粗茶淡饭饱三餐，早也香甜，晚也香甜。\n布衣得暖胜丝绵，长也可穿，短也可穿。\n草舍茅屋有几间，行也安然，待也安然。\n雨过天青驾小船，鱼在一边，酒在一边。\n夜归儿女话灯前，今也有言，古也有言。\n日上三竿我独眠，谁是神仙，我是神仙。\n南山空谷书一卷，疯也痴癫，狂也痴癫。'},
    {t:'山禽',a:'张籍〔唐代〕',c:'山禽毛如白练带，栖我庭前栗树枝。\n猕猴半夜来取栗，一双中林向月飞。'},
    {t:'山泉煎茶有怀',a:'白居易〔唐代〕',c:'坐酌泠泠水，看煎瑟瑟尘。\n无由持一碗，寄与爱茶人。'},
    {t:'山人劝酒',a:'李白〔唐代〕',c:'苍苍云松，落落绮皓。\n春风尔来为阿谁，蝴蝶忽然满芳草。\n秀眉霜雪颜桃花，骨青髓绿长美好。\n称是秦时避世人，劝酒相欢不知老。\n各守麋鹿志，耻随龙虎争。\n欻起佐太子，汉王乃复惊。\n顾谓戚夫人，彼翁羽翼成。\n归来商山下，泛若云无情。\n举觞酹巢由，洗耳何独清。\n浩歌望嵩岳，意气还相倾。'},
    {t:'山石',a:'韩愈〔唐代〕',c:'山石荦确行径微，黄昏到寺蝙蝠飞。\n升堂坐阶新雨足，芭蕉叶大栀子肥。\n僧言古壁佛画好，以火来照所见稀。\n铺床拂席置羹饭，疏粝亦足饱我饥。\n夜深静卧百虫绝，清月出岭光入扉。\n天明独去无道路，出入高下穷烟霏。\n山红涧碧纷烂漫，时见松枥皆十围。\n当流赤足踏涧石，水声激激风吹衣。\n人生如此自可乐，岂必局束为人鞿？\n嗟哉吾党二三子，安得至老不更归。'},
    {t:'山石榴',a:'杜牧〔唐代〕',c:'似火山榴映小山，繁中能薄艳中闲。\n一朵佳人玉钗上，只疑烧却翠云鬟。'},
    {t:'山水粉图',a:'陈子昂〔唐代〕',c:'山图之白云兮，若巫山之高丘。纷群翠之鸿溶，\n又似蓬瀛海水之周流。信夫人之好道，爱云山以幽求。'},
    {t:'山寺',a:'杜甫〔唐代〕',c:'野寺残僧少，山园细路高。\n麝香眠石竹，鹦鹉啄金桃。\n乱水通人过，悬崖置屋牢。\n上方重阁晚，百里见秋毫。'},
    {t:'山亭柳·赠歌者',a:'晏殊〔宋代〕',c:'家住西秦。赌博艺随身。花柳上、斗尖新。偶学念奴声调，有时高遏行云。蜀锦缠头无数，不负辛勤。\n数年来往咸京道，残杯冷炙谩消魂。衷肠事、托何人。若有知音见采，不辞遍唱阳春。一曲当筵落泪，重掩罗巾。'},
    {t:'山头鹿',a:'张籍〔唐代〕',c:'山头鹿，角芟芟，尾促促。贫儿多日输不足，\n夫死未葬儿在狱。早日熬熬蒸野冈，禾黍不收无狱粮。\n县家唯忧少军食，谁能令尔无死伤。'},
    {t:'山行',a:'杜牧〔唐代〕',c:'远上寒山石径斜，白云生处有人家。\n停车坐爱枫林晚，霜叶红于二月花。'},
    {t:'山行入泾州',a:'王昌龄〔唐代〕',c:'倦此山路长，停骖问宾御。林峦风回惑，白日落何处。\n徙倚望长风，滔滔引归虑。微雨随云收，亭亭傍山去。\n西临有边邑，北走尽亭戍。泾水横白烟，州城隐寒树。\n所嗟异风俗，已自少情趣。岂伊怀土多，触目忻所遇。'},
    {t:'山雪',a:'皎然〔唐代〕',c:'夕阳在西峰，叠翠萦残雪。狂风卷絮回，惊猿攀玉折。\n何意山中人，误报山花发。'},
    {t:'山阳阻浅',a:'秦观〔宋代〕',c:'一日行一尺，十日行一丈。\n岂不夜淹留，所幸无波浪。\n悲风动深夜，原野眇林爽。\n青天行蟾蜍，枯水转魍魉。\n此时蓬茅下，去心剧於痒。\n弃置勿复论，通塞如反掌。'},
    {t:'山樱',a:'王安石〔宋代〕',c:'山樱抱石荫松枝，比并余花发最迟。\n赖有春风嫌寂寞，吹香渡水报人知。'},
    {t:'山雨',a:'皎然〔唐代〕',c:'一片雨，山半晴。\n长风吹落西山上，满树萧萧心耳清。\n云鹤惊乱下，水香凝不然。\n风回雨定芭蕉湿，一滴时时入昼禅。'},
    {t:'山园草木四绝句其一紫薇',a:'陆游〔宋代〕',c:'钟鼓楼前宫样花，谁令流落到天涯。少年妄想今除尽，但爱清樽浸晚霞。'},
    {t:'山月行·一作关山月',a:'皎然〔唐代〕',c:'家家望秋月，不及秋山望。山中万境长寂寥，\n夜夜孤明我山上。海人皆言生海东，山人自谓出山中。\n忧虞欢乐皆占月，月本无心同不同。自从有月山不改，\n古人望尽今人在。不知万世今夜时，孤月将□谁更待。'},
    {t:'山中',a:'王安石〔宋代〕',c:'随月出山去，寻云相伴归。\n春晨花上露，芳气著人衣。'},
    {t:'山中酬人',a:'张籍〔唐代〕',c:'山中日暖春鸠鸣，逐水看花任意行。\n向晚归来石窗下，菖蒲叶上见题名。'},
    {t:'山中泛舟觞客',a:'文天祥〔宋代〕',c:'便作乘槎客，萧萧骨发清。\n尊前山月过，笛里水风生。\n半夜鱼龙沸，三秋河汉明。\n雪堂眠二客，梦与白鸥盟。'},
    {t:'山中逢道士云公',a:'孟浩然〔唐代〕',c:'春余草木繁，耕种满田园。\n酌酒聊自劝，农夫安与言。\n忽闻荆山子，时出桃花源。①\n采樵过北谷，卖药来西村。\n村烟日云夕，榛路有归客。\n杖策前相逢，沂然是畴昔。\n邂逅欢觏止，殷勤叙离隔。\n谓予搏扶桑，轻举振六翮。②\n奈何偶昌运，独见遗草泽。\n既笑接舆狂，仍怜孔丘厄。\n物情趋势利，吾道贵闲寂。\n偃息西山下，门庭罕人迹。\n何时还清溪，从尔炼丹液。'},
    {t:'山中感兴三首',a:'文天祥〔宋代〕',c:'山中有流水，霜降石自出。\n骤雨东南来，消长不终日。\n故人书问至，为言北风急。\n山深人不知，塞马谁得失。\n挑灯看古史，感泪纵横发。\n幸生圣明时，渔樵以自适。'},
    {t:'山中古祠',a:'张籍〔唐代〕',c:'春草空祠墓，荒林唯鸟飞。记年碑石在，经乱祭人稀。\n野鼠缘朱帐，阴尘盖画衣。近门潭水黑，时见宿龙归。'},
    {t:'山中寄诸弟妹',a:'王维〔唐代〕',c:'山中多法侣，禅诵自为群。城郭遥相望，唯应见白云。'},
    {t:'山中立夏用坐客韵',a:'文天祥〔宋代〕',c:'归来泉石国，日月共溪翁。\n夏气重渊底，春光万象中。\n穷吟到云黑，淡饮胜裙红。\n一阵弦声好，人间解愠风。'},
    {t:'山中六言三首',a:'文天祥〔宋代〕',c:'鹤外竹声簌簌，座边松影疏疏。\n夜静不收棋局，日高犹卧纱厨。'},
    {t:'山中谩成柬刘方斋',a:'文天祥〔宋代〕',c:'东风解冻出行嬉，一哄烟尘隔翠微。\n自有溪山真乐地，从来富贵是危机。\n二三辈行惟须醉，多少公卿未得归。\n明日主人酬一座，小船旋网鳜鱼肥。'},
    {t:'山中秋夜',a:'张籍〔唐代〕',c:'寂寂山景静，幽人归去迟。\n横琴当月下，压酒及花时。\n冷露湿茆屋，暗泉冲竹篱。\n西峰采药伴，此夕恨无期。'},
    {t:'山中示弟',a:'王维〔唐代〕',c:'山林吾丧我，冠带尔成人。莫学嵇康懒，且安原宪贫。\n山阴多北户，泉水在东邻。缘合妄相有，性空无所亲。\n安知广成子，不是老夫身。'},
    {t:'山中送别',a:'王维〔唐代〕',c:'山中相送罢，日暮掩柴扉。\n春草明年绿，王孙归不归？'},
    {t:'山中送从叔简赴举',a:'孟郊〔唐代〕',c:'石根百尺杉，山眼一片泉。倚之道气高，饮之诗思鲜。\n于此逍遥场，忽奏别离弦。却笑薜萝子，不同鸣跃年。'},
    {t:'山中问答',a:'李白〔唐代〕',c:'问余何意栖碧山，笑而不答心自闲。\n桃花流水窅然去，别有天地非人间。'},
    {t:'山中与幽人对酌',a:'李白〔唐代〕',c:'两人对酌山花开，一杯一杯复一杯。\n我醉欲眠卿且去，明朝有意抱琴来。'},
    {t:'山中与元九书因题书后',a:'白居易〔唐代〕',c:'忆昔封书与君夜，金銮殿后欲明天。\n今夜封书在何处，庐山庵里晚灯前。\n笼鸟槛猿俱未死，人间相见是何年。'},
    {t:'山中再次胡德昭韵其一',a:'文天祥〔宋代〕',c:'不将颜色汗黄金，落得灞桥驴雪吟。是处江山生酒兴，满天风雪得梅心。\n觥筹堂里春声沸，灯火林皋夜色深。人世可能行乐耳，重游不用卜晴阴。'},
    {t:'山中载酒用萧敬夫韵赋江涨',a:'文天祥〔宋代〕',c:'拍拍春风满面浮，出门一笑大人流。\n坐中狂客有醉白，物外闲人惟弈秋。\n晴抹雨妆总西子，日开云暝一滁州。\n忽传十万军声至，如在浙人亭上游。'},
    {t:'山中赠日南僧',a:'张籍〔唐代〕',c:'独向双峰老，松门闭两崖。翻经上蕉叶，挂衲落藤花。\n甃石新开井，穿林自种茶。时逢海南客，蛮语问谁家。'},
    {t:'山茱萸',a:'王维〔唐代〕',c:'朱实山下开，清香寒更发。\n幸与丛桂花，窗前向秋月。'},
    {t:'陕州月城楼送辛判官入奏',a:'岑参〔唐代〕',c:'送客飞鸟外，城头楼最高。樽前遇风雨，窗里动波涛。\n谒帝向金殿，随身唯宝刀。相思灞陵月，只有梦偏劳。'},
    {t:'善谑驿和刘梦得酹淳于先生',a:'柳宗元〔唐代〕',c:'水上鹄已去，亭中鸟又鸣。辞因使楚重，名为救齐成。\n荒垄遽千古，羽觞难再倾。刘伶今日意，异代是同声。'},
    {t:'伤春',a:'孟郊〔唐代〕',c:'两河春草海水清，十年征战城郭腥。乱兵杀儿将女去，\n二月三月花冥冥。千里无人旋风起，莺啼燕语荒城里。\n春色不拣墓傍株，红颜皓色逐春去。春去春来那得知，\n今人看花古人墓，令人惆怅山头路。'},
    {t:'伤春',a:'杨万里〔宋代〕',c:'准拟今春乐事浓，依然枉却一东风。\n年年不带看花眼，不是愁中即病中。'},
    {t:'伤春怨·雨打江南树',a:'王安石〔宋代〕',c:'雨打江南树。一夜花开无数。绿相渐成阴，下有游人归路。\n与君相逢处。不道春将暮。把酒祝东风，且莫恁、匆匆去。'},
    {t:'伤情怨·枝头风势渐小',a:'周邦彦〔宋代〕',c:'枝头风势渐小，看暮鸦飞了。又路黄昏，闭门收返照。\n江南人去路渺，信未通、愁已先到。怕见孤灯，霜寒催睡早。'},
    {t:'伤时',a:'孟郊〔唐代〕',c:'常闻贫贱士之常，嗟尔富者莫相笑。男儿得路即荣名，\n邂逅失途成不调。古人结交而重义，今人结交而重利。\n劝人一种种桃李，种亦直须遍天地。一生不爱嘱人事，\n嘱即直须为生死。我亦不羡季伦富，我亦不笑原宪贫。\n有财有势即相识，无财无势同路人。因知世事皆如此，\n却向东溪卧白云。'},
    {t:'伤逝',a:'韦应物〔唐代〕',c:'染白一为黑，焚木尽成灰。\n念我室中人，逝去亦不回。\n结发二十载，宾敬如始来。\n提携属时屯，契阔忧患灾。\n柔素亮为表，礼章夙所该。\n仕公不及私，百事委令才。\n一旦入闺门，四屋满尘埃。\n斯人既已矣，触物但伤摧。\n单居移时节，泣涕抚婴孩。\n知妄谓当遣，临感要难裁。\n梦想忽如睹，惊起复徘徊。\n此心良无已，绕屋生蒿莱。'},
    {t:'伤桃源薛道士',a:'刘禹锡〔唐代〕',c:'坛边松在鹤巢空，白鹿闲行旧径中。\n手植红桃千树发，满山无主任春风。'},
    {t:'伤温德彝',a:'温庭筠〔唐代〕',c:'昔年戎虏犯榆关，一败龙城匹马还。\n侯印不闻封李广，他人丘垄似天山。'},
    {t:'伤岘山云表观主',a:'孟浩然〔唐代〕',c:'少小学书剑，秦吴多岁年。归来一登眺，陵谷尚依然。\n岂意餐霞客，溘随朝露先。因之问闾里，把臂几人全。'},
    {t:'伤心行',a:'李贺〔唐代〕',c:'咽咽学楚吟，病骨伤幽素。\n秋姿白发生，木叶啼风雨。\n灯青兰膏歇，落照飞蛾舞。\n古壁生凝尘，羁魂梦中语。'},
    {t:'伤愚溪三首',a:'刘禹锡〔唐代〕',c:'故人柳子厚之谪永州，得胜地，结茅树蔬，为沼沚，为台榭，目曰愚溪。柳子没三年，有僧游零陵，告余曰：“愚溪无复曩时矣！”一闻僧言，悲不能自胜，遂以所闻为七言以寄恨。\n溪水悠悠春自来，草堂无主燕飞回。\n隔帘唯见中庭草，一树山榴依旧开。\n草圣数行留坏壁，木奴千树属邻家。\n唯见里门通德榜，残阳寂寞出樵车。\n柳门竹巷依依在，野草青苔日日多。\n纵有邻人解吹笛，山阳旧侣更谁过？'},
    {t:'伤仲永',a:'王安石〔宋代〕',c:'金溪民方仲永，世隶耕。仲永生五年，未尝识书具，忽啼求之。父异焉，借旁近与之，即书诗四句，并自为其名。其诗以养父母、收族为意，传一乡秀才观之。自是指物作诗立就，其文理皆有可观者。邑人奇之，稍稍宾客其父，或以钱币乞之。父利其然也，日扳仲永环谒于邑人，不使学。\n余闻之也久。明道中，从先人还家，于舅家见之，十二三矣。令作诗，不能称前时之闻。又七年，还自扬州，复到舅家问焉。曰：“泯然众人矣。”\n王子曰：仲永之通悟，受之天也。其受之天也，贤于材人远矣。卒之为众人，则其受于人者不至也。彼其受之天也，如此其贤也，不受之人，且为众人；今夫不受之天，固众人，又不受之人，得为众人而已耶？'},
    {t:'商洛山行怀古',a:'张九龄〔唐代〕',c:'园绮值秦末，嘉遁此山阿。陈迹向千古，荒途始一过。\n硕人久沦谢，乔木自森罗。故事昔尝览，遗风今岂讹。\n泌泉空活活，樵臾独皤皤。是处清晖满，从中幽兴多。\n长怀赤松意，复忆紫芝歌。避世辞轩冕，逢时解薜萝。\n盛明今在运，吾道竟如何。'},
    {t:'商山富水驿',a:'杜牧〔唐代〕',c:'益戆由来未觉贤，终须南去吊湘川。\n当时物议朱云小，后代声华白日悬。\n邪佞每思当面唾，清贫长欠一杯钱。\n驿名不合轻移改，留警朝天者惕然。'},
    {t:'商山麻涧',a:'杜牧〔唐代〕',c:'云光岚彩四面合，柔柔垂柳十余家。\n雉飞鹿过芳草远，牛巷鸡埘春日斜。\n秀眉老父对樽酒，茜袖女儿簪野花。\n征车自念尘土计，惆怅溪边书细沙。'},
    {t:'商山早行',a:'温庭筠〔唐代〕',c:'晨起动征铎，客行悲故乡。\n鸡声路店月，人迹板桥霜。\n槲叶落山路，枳花明驿墙。\n因思杜陵梦，凫雁满回塘。'},
    {t:'商鞅',a:'王安石〔宋代〕',c:'自古驱民在信诚，一言为重百金轻。\n今人未可非商鞅，商鞅能令政必行。'},
    {t:'商州客舍',a:'孟郊〔唐代〕',c:'商山风雪壮，游子衣裳单。四望失道路，百忧攒肺肝。\n日短觉易老，夜长知至寒。泪流潇湘弦，调苦屈宋弹。\n识声今所易，识意古所难。声意今讵辨，高明鉴其端。'},
    {t:'赏菊四首',a:'杨万里〔宋代〕',c:'物性从来各一家，谁贪寒瘦厌妍华。\n菊花自择风霜国，不是春光外菊花。'},
    {t:'赏牡丹',a:'刘禹锡〔唐代〕',c:'庭前芍药妖无格，池上芙蕖净少情。\n唯有牡丹真国色，花开时节动京城。'},
    {t:'上包祭酒',a:'孟郊〔唐代〕',c:'岳岳冠盖彦，英英文字雄。琼音上听时，尘韵固不同。\n春云生纸上，秋涛起胸中。时吟五君咏，再举七子风。\n何幸松桂侣，见知勤苦功。愿将黄鹤翅，一借飞云空。'},
    {t:'上达奚舍人',a:'孟郊〔唐代〕',c:'北山少日月，草木苦风霜。\n贫士在重坎，食梅有酸肠。\n万俗皆走圆，一身犹学方。\n常恐众毁至，春叶成秋黄。\n大贤秉高鉴，公烛无私光。\n暗室晓未及，幽行涕空行。'},
    {t:'上大蒙笼',a:'黄庭坚〔宋代〕',c:'黄雾冥冥小石门，苔衣草路无蹊迹。\n苦竹参天大石门，虎迒兔蹊聊倚息。\n阴风搜林山鬼啸，千家寒藤绕崩石。\n清风源里有蹊家，牛羊在山亦桑麻。\n向来陆梁嫚官府，试呼使前问其故。\n衣冠汉仪民父子，吏曹扰之至如此。\n穷乡有米无食盐，今日有田无米食。\n但愿官清不爱钱，长养儿孙听驱使。'},
    {t:'上都行送张伯玉',a:'范仲淹〔宋代〕',c:'上都有圣人，日月一以新。\n晔晔天下才，西才尧舜宾。\n百谷望东浸，万星依北辰。\n直者为之辕，曲者为之轮。\n一材不复遗，况此席上珍。\n南山张公子，气象清且淳。\n怀有绮绣文，朝无瓜瓞新。\n寸心如铁石，不羞贱与贫。\n买臣起白社，贾谊富青春。\n实此金辘轳，去去延平津。'},
    {t:'上河阳李大夫',a:'孟郊〔唐代〕',c:'上将秉神略，至兵无猛威。三军景严冬，一抚胜重衣。\n霜剑夺众景，夜星失长辉。苍鹰独立时，恶地不敢飞。\n武牢锁天关，河桥纽地机。大将奚以安，守此称者稀。\n贫士少颜色，贵门多轻肥。试登山岳高，方见草木微。\n山岳恩既广，草木心皆归。'},
    {t:'上皇西巡南京歌十首·其二',a:'李白〔唐代〕',c:'九天开出一成都，万户千门入画图。\n草树云山如锦绣，秦川得及此间无。'},
    {t:'上李邕',a:'李白〔唐代〕',c:'大鹏一日同风起，扶摇直上九万里。\n假令风歇时下来，犹能簸却沧溟水。\n世人见我恒殊调，闻余大言皆冷笑。\n宣父犹能畏后生，丈夫未可轻年少。'},
    {t:'上陵',a:'佚名〔两汉〕',c:'上陵何美美，下津风以寒。\n问客从何来，言从水中央。\n桂树为君船，青丝为君笮，木兰为君棹，黄金错其间。\n沧海之雀赤翅鸿，白雁随。\n山林乍开乍合，曾不知日月明。\n醴泉之水，光泽何蔚蔚。\n芝为车，龙为马，览遨游，四海外。\n甘露初二年，芝生铜池中，仙人下来饮，延寿千万岁。'},
    {t:'上马当山神',a:'王昌龄〔唐代〕',c:'青骢一匹昆仑牵，奏上大王不取钱。\n直为猛风波滚骤，莫怪昌龄不下船。'},
    {t:'上三峡',a:'李白〔唐代〕',c:'巫山夹青天，巴水流若兹。\n巴水忽可尽，青天无到时。\n三朝上黄牛，三暮行太迟。\n三朝又三暮，不觉鬓成丝。'},
    {t:'上山采蘼芜',a:'佚名〔两汉〕',c:'上山采蘼芜，下山逢故夫。\n长跪好故夫，新人复何如？\n新人虽言好，未若故人姝。\n颜色类相似，手閤不相如。\n新人从门入，故人从閤去。\n新人工织缣，故人工织素。\n织缣日一匹，织素五丈余。\n将缣来比素，新人不如故。'},
    {t:'上侍御七兄',a:'王昌龄〔唐代〕',c:'天人俟明路，益稷分尧心。\n利器必先举，非贤安可任。\n吾兄执严宪，时佐能钓深。'},
    {t:'上同州使君伯',a:'王昌龄〔唐代〕',c:'大贤本孤立，有时起丝纶。\n伯父自天禀，元功载生人。'},
    {t:'上西平·送杜叔高',a:'辛弃疾〔宋代〕',c:'恨如新，新恨了，又重新。看天上、多少浮云。江南好景，落花时节又逢君。夜来风雨，春归似欲留人。\n尊如海，人如玉，诗如锦，笔如神。能几字、尽殷勤。江天日暮，何时重与细论文。绿杨阴里，听阳关、门掩黄昏。'},
    {t:'上邪',a:'佚名〔两汉〕',c:'上邪！我欲与君相知，长命无绝衰。\n山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝。'},
    {t:'上阳水窗旬宴得移字韵',a:'张九龄〔唐代〕',c:'河汉非应到，汀洲忽在斯。仍逢帝乐下，如逐海槎窥。\n春赏时将换，皇恩岁不移。今朝游宴所，莫比天泉池。'},
    {t:'上元',a:'晏殊〔宋代〕',c:'金翠光中实焰繁，山楼高下鼓声喧。\n两军伎女轻如鹘，百尺竿头电线翻。'},
    {t:'上元侍宴',a:'苏轼〔宋代〕',c:'淡月疏星绕建章，仙风吹下御炉香。\n侍臣鹄立通明殿，一朵红云捧玉皇。'},
    {t:'上元夕次韵答张谏议',a:'晏殊〔宋代〕',c:'歌吹欢娱夕，衡门可属垣。\n九城寒漏彻，三市实灯繁。\n酒想嵇山醉，诗惭谢乐翻。\n如容陪后乘，那避八驺喧。'},
    {t:'上元戏呈贡父',a:'王安石〔宋代〕',c:'车马纷纷白昼同，万家灯火暖莱风。\n别开阊阖壶天外，特起蓬莱陆海中。\n尽取繁华供侠少，只分牢落与衰翁。\n不知太乙游何处，定把青藜独照公。'},
    {t:'上元夜效小庾体',a:'陈子昂〔唐代〕',c:'三五月华新。\n遨游逐上春。\n相邀妓城曲。\n追宴小平津。\n楼上看珠妓。\n车中见玉人。\n芳宵殊未极。\n随意守灯轮。'},
    {t:'上元月蚀',a:'纳兰性德〔清代〕',c:'夹道香尘拥狭斜，金波无影暗千家。\n姮娥应是羞分镜，故倩轻云掩素华。'},
    {t:'上张令公',a:'王维〔唐代〕',c:'珥笔趋丹陛，垂珰上玉除。\n步檐青琐闼，方幰画轮车。\n市阅千金字，朝闻五色书。\n致君光帝典，荐士满公车。\n伏奏回金驾，横经重石渠。\n从兹罢角牴，且复幸储胥。\n天统知尧后，王章笑鲁初。\n匈奴遥俯伏，汉相俨簪裾。\n贾生非不遇，汲黯自堪疏。\n学易思求我，言诗或起予。\n当从大夫后，何惜隶人馀。'},
    {t:'上之回',a:'李贺〔唐代〕',c:'上之回，大旗喜。\n悬红云，挞凤尾。\n剑匣破，舞蛟龙。\n蚩尤死，鼓逢逢。\n天高庆雷齐堕地。\n地无惊烟海千里。'},
    {t:'尚书·大禹谟（节选）',a:'佚名〔先秦〕',c:'禹乃会群后，誓于师曰：“济济有恭，咸听朕命。蠢兹有苗，昏迷不恭，侮慢自贤，反道败德，君子在咎，小人在位，民弃不保，天降之咎，肆予以尔恭士，奉辞伐罪。尔尚一乃心力，其克有勋。”\n三旬，苗民逆命。益赞于禹曰：“惟德动天，无远弗届。满招损，谦受益，时乃天道。帝初于历山，往于田，日号泣于旻天，于父母，负罪引慝。祗载见瞽叟，夔夔斋栗，瞽亦允若。至諴感神，矧兹有苗。”'},
    {t:'芍药·元和中知制诰寓直禁中作',a:'韩愈〔唐代〕',c:'浩态狂香昔未逢，红灯烁烁绿盘笼。\n觉来独对情惊恐，身在仙宫第几重。'},
    {t:'芍药歌·一本作王司马红芍药歌',a:'韩愈〔唐代〕',c:'丈人庭中开好花，更无凡木争春华。翠茎红蕊天力与，\n此恩不属黄钟家。温馨熟美鲜香起，似笑无言习君子。\n霜刀翦汝天女劳，何事低头学桃李。娇痴婢子无灵性，\n竞挽春衫来此并。欲将双颊一睎红，绿窗磨遍青铜镜。\n一尊春酒甘若饴，丈人此乐无人知。花前醉倒歌者谁，\n楚狂小子韩退之。'},
    {t:'少年',a:'李商隐〔唐代〕',c:'外戚平羌第一功，生年二十有重封。\n直登宣室螭头上，横过甘泉豹尾中。\n别馆觉来云雨梦，后门归去蕙兰丛。\n灞陵夜猎随田窦，不识寒郊自转蓬。'},
    {t:'少年见青春',a:'王安石〔宋代〕',c:'少年见青春，万物皆妩媚。\n身虽白饮酒，乐与宾客醉。\n一从鬓上白，百白见可喜。\n心肠非故时，更思日月驶。\n闻欢已倦往，得饱还思睡。\n春归只如梦，白复悲憔悴。\n寄言少年子，努力作春事。\n亦勿怪衰翁，衰强自然异。'},
    {t:'少年心',a:'黄庭坚〔宋代〕',c:'对景惹起愁闷。染相思、病成方寸。是阿谁先有意，阿谁薄幸。斗顿恁、少喜多嗔。\n合下休传音问。你有我、我无你分。似合欢桃核，真堪人恨。心儿里、有两个人人。'},
    {t:'少年心·添字',a:'黄庭坚〔宋代〕',c:'心里人人，暂不见、霎时难过。天生你要憔悴我。把心头从前鬼，著手摩挲。抖擞了、百病销磨。\n见说那厮脾鳖热。大不成我便与拆破。待来时、鬲上与厮噷则个。温存著、且教推磨。'},
    {t:'少年行',a:'张籍〔唐代〕',c:'少年从猎出长杨，禁中新拜羽林郎。\n独对辇前射双虎，君王手赐黄金珰。\n日日斗鸡都市里，赢得宝刀重刻字。\n百里报仇夜出城，平明还在娼楼醉。\n遥闻虏到平陵下，不待诏书行上马。\n斩得名王献桂宫，封侯起第一日中。\n不为六郡良家子，百战始取边城功。'},
    {t:'少年行·其一',a:'王昌龄〔唐代〕',c:'西陵侠年少，送客过长亭。\n青槐夹两路，白马如流星。\n闻道羽书急，单于寇井陉。\n气高轻赴难，谁顾燕山铭。'},
    {t:'少年行二首',a:'王昌龄〔唐代〕',c:'西陵侠少年，送客短长亭。\n青槐夹两道，白马如流星。\n闻道羽书急，单于寇井陉。\n气高轻赴难，谁顾燕山铭。\n走马远相寻，西楼下夕阴。\n结交期一剑，留意赠千金。\n高阁歌声远，重门柳色深。\n夜阑须尽饮，莫负百年心。'},
    {t:'少年行二首',a:'李白〔唐代〕',c:'击筑饮美酒，剑歌易水湄。\n经过燕太子，结托并州儿。\n少年负壮气，奋烈自有时。\n因击鲁句践，争博勿相欺。\n五陵年少金市东，银鞍白马度春风。\n落花踏尽游何处，笑入胡姬酒肆中。'},
    {t:'少年行四首',a:'王维〔唐代〕',c:'新丰美酒斗十千，咸阳游侠多楼年。\n相逢意气为君饮，系马高楼垂柳边。\n出身仕汉羽林郎，初苦骠骑战渔阳。\n孰知不向边庭苦，纵死犹闻侠骨香。\n一身能擘两雕弧，虏骑千重只似无。\n偏坐金鞍调白羽，纷纷射杀五单于。\n汉家君臣欢宴终，高议云台论战功。\n天子临轩赐侯印，将军佩出明光宫。'},
    {t:'少年游',a:'晏几道〔宋代〕',c:'绿勾阑畔，黄昏淡月，携手对残红。纱窗影里，朦腾春睡，繁杏小屏风。\n须愁别后，天高海阔，何处更相逢。幸有花前，一杯芳酒，欢计莫匆匆。'},
    {t:'少年游',a:'晏几道〔宋代〕',c:'西溪丹杏，波前媚脸，珠露与深匀。南楼翠柳，烟中愁黛，丝雨恼娇颦。\n当年此处，闻歌殢酒，曾对可怜人。今夜相思，水长山远，闲卧送残春。'},
    {t:'少年游',a:'晏几道〔宋代〕',c:'雕梁燕去，裁诗寄远，庭院旧风流。黄花醉了，碧梧题罢，闲卧对高秋。\n繁云破后，分明素月，凉影挂金钩。有人凝淡倚西楼。新样两眉愁。'},
    {t:'少年游',a:'晏几道〔宋代〕',c:'西楼别后，风高露冷，无奈月分明。飞鸿影里，捣衣砧外，总是玉关情。\n王孙此际，山重水远，何处赋西征。金闺魂梦枉丁宁。寻尽短长亭。'},
    {t:'少年游·并刀如水',a:'周邦彦〔宋代〕',c:'并刀如水，吴盐胜雪，纤手破新调。锦幄初温，兽烟不断，相对坐调笙。\n低声问：向谁行宿？城上已三更。马滑霜浓，不如休去，直是少人行！'},
    {t:'少年游·参差烟树灞陵桥',a:'柳永〔宋代〕',c:'参差烟树灞陵桥，风物尽前朝。衰杨古柳，几经攀折，憔悴楚宫腰。\n夕阳闲淡秋光老，离思满蘅皋。一曲阳关，断肠声尽，独自凭兰桡。'},
    {t:'少年游·层波潋滟远山横',a:'柳永〔宋代〕',c:'层波潋滟远山横。一笑一倾城。酒容红嫩，歌喉清丽，百媚坐中生。\n墙头马上初相见，不准拟、恁多情。昨夜杯阑，洞房深处，特地快逢迎。'},
    {t:'少年游·朝云漠漠散轻丝',a:'周邦彦〔宋代〕',c:'朝云漠漠散轻丝。楼阁淡春姿。迟泣花啼，九街泥重，门外燕飞迟。\n而今丽日明金屋，春色在桃枝。不似当时，小桥冲雨，幽恨两人知。'},
    {t:'少年游·端午赠黄守徐君猷',a:'苏轼〔宋代〕',c:'银塘朱槛麹尘波，圆绿卷新荷。兰条荐浴，菖花酿酒，天气尚清和。\n好将沉醉酬佳节，十分酒、一分歌。狱草烟深，讼庭人悄，无吝宴游过。'},
    {t:'少年游·芙蓉花发去年枝',a:'晏殊〔宋代〕',c:'芙蓉花发去年枝，双燕欲归飞。兰堂风软，金炉香暖，新曲动帘帷。\n家人拜上千春寿，深意满琼卮。绿鬓朱颜，道家装束，长似少年时。'},
    {t:'少年游·黄钟楼月',a:'周邦彦〔宋代〕',c:'檐牙缥缈小倡楼。凉月挂银钩。州席笙歌，透帘灯火，风景似扬州。\n当时面色欺春雪，曾伴美人游。今日重来，更无人问，独自倚阑愁。'},
    {t:'少年游·佳人巧笑值千金',a:'柳永〔宋代〕',c:'佳人巧笑值千金。当日偶情深。几回饮散，灯残香暖，好事尽鸳衾。\n如今万水千山阻，魂杳杳、信沈沈。孤棹烟波，小楼风月，两处一般心。'},
    {t:'少年游·离多最是',a:'晏几道〔宋代〕',c:'离多最是，东西流水，终解两相魂。浅情终似，行云无定，犹到梦魂中。\n可怜人意，薄于云水，佳会更难重。细想从来，断肠多处，不与这番同。'},
    {t:'少年游·帘垂深院冷萧萧',a:'柳永〔宋代〕',c:'帘垂深院冷萧萧。花外漏声遥。青灯未灭，红窗闲卧，魂梦去迢迢。\n薄情漫有归消息，鸳鸯被、半香消。试问伊家，阿谁心绪，禁得恁无憀。'},
    {t:'少年游·铃斋无讼宴游频',a:'柳永〔宋代〕',c:'铃斋无讼宴游频。罗绮簇簪绅。真朱傅粉，丰肌清骨，容态尽天真。\n舞裀歌扇花光里，翻回雪、驻行云。绮席阑珊，凤灯明灭，谁是意中人。'},
    {t:'少年游·南都石黛扫晴山',a:'周邦彦〔宋代〕',c:'南都石黛扫晴山。衣薄耐朝寒。一夕东风，海棠花谢，楼上卷帘看。\n而今丽日明如洗，南陌暖雕鞍。旧赏园林，喜无风雨，春鸟报平安。'},
    {t:'少年游·日高花榭懒梳头',a:'柳永〔宋代〕',c:'日高花榭懒梳头。无语倚妆楼。修眉敛黛，遥山横翠，相对结春愁。\n王孙走马长楸陌，贪迷恋、少年游。似恁疏狂，费人拘管，争似不风流。'},
    {t:'少年游·润州作代人寄远',a:'苏轼〔宋代〕',c:'去年相送，余杭门外，飞雪似杨花。今年春尽，杨花似雪，犹不见还家。\n对酒卷帘邀明月，风露透窗纱。恰似姮娥怜双燕，分明照、画梁斜。'},
    {t:'少年游·世间尤物意中人',a:'柳永〔宋代〕',c:'世间尤物意中人。轻细好腰身。春帏睡起，发妆酒酽，红脸杏花春。\n娇多爱把齐纨扇，和笑掩朱唇。心性温柔，品流详雅，不称在风尘。'},
    {t:'少年游·霜华满树',a:'晏殊〔宋代〕',c:'霜华满树，兰凋蕙惨，秋艳入芙蓉。胭脂嫩脸，金黄轻蕊，犹自怨西风。\n前欢往事，当歌对酒，无限到心中。更凭朱槛忆芳容，肠断一枝红。'},
    {t:'少年游·算来好景只如斯',a:'纳兰性德〔清代〕',c:'算来好景只如斯，惟许有情知。寻常风月，等闲谈笑，称意即相宜。\n十年青鸟音尘断，往事不胜思。一钩残照，半帘飞絮，总是恼人时。'},
    {t:'少年游·谢家庭槛晓无尘',a:'晏殊〔宋代〕',c:'谢家庭槛晓无尘，芳宴祝良辰。云流妙舞，樱桃清唱，依约驻行云。\n榴花一盏浓香满，为寿百千春。岁岁年年，共欢同乐，嘉庆与时新。'},
    {t:'少年游·一生赢得是凄凉',a:'柳永〔宋代〕',c:'一生赢得是凄凉。追前事、暗心伤。好天良夜，深屏香被。争忍便相忘。\n王孙动是经年去，贪迷恋、有何长。万种千般，把伊情分，颠倒尽猜量。'},
    {t:'少年游·长安古道马迟迟',a:'柳永〔宋代〕',c:'长安古道马迟迟，高柳乱蝉嘶。夕阳岛外，秋风原上，目断四天垂。\n归云一去无踪迹，何处是前期？狎兴生疏，酒徒萧索，不似少年时。'},
    {t:'少年游·重阳过后',a:'晏殊〔宋代〕',c:'重阳过后，西风渐紧，庭树叶纷纷。朱阑向晓，芙蓉妖艳，特地斗芳新。\n霜前月下，斜红淡蕊，明媚欲回春。莫将琼萼等闲分，留赠意中人。'},
    {t:'少年游·重阳过後',a:'晏殊〔宋代〕',c:'重阳过後，西风渐紧，庭树叶纷纷。朱阑向晓，芙蓉妖艳，特地斗芳新。霜前月下，斜红淡蕊，明媚欲回春。莫将琼萼等闲分。留赠意中人。'},
    {t:'少年子',a:'李白〔唐代〕',c:'青云少年子，挟弹章台左。\n鞍马四边开，突如流星过。\n金丸落飞鸟，夜入琼楼卧。\n夷齐是何人，独守西山饿。'},
    {t:'社日戏题呈任副枢',a:'晏殊〔宋代〕',c:'开樽幸有治聋酝，把叶能无送燕章。\n所惜近停司饮会，不如村叟醉秋光。'},
    {t:'射阳湖',a:'范仲淹〔宋代〕',c:'渺渺指平湖，烟波极望初。\n纵横皆钓者，何处得嘉鱼。'},
    {t:'射雉',a:'韦应物〔唐代〕',c:'走马上东冈，朝日照野田。野田中雉起，翻射斗回鞭。\n虽无百发中，聊取一笑妍。羽分绣臆碎，头弛锦鞘悬。\n方将悦羁旅，非关学少年。弢弓一长啸，忆在灞城阡。'},
    {t:'涉涧水作',a:'朱熹〔宋代〕',c:'幽谷溅溅小水通，细穿危石认行踪。回头自爱情岚好，却立滩头数乱峰。'},
    {t:'涉江采芙蓉',a:'佚名〔两汉〕',c:'涉江采芙蓉，兰泽多芳草。\n采之欲遗谁？所思在远道。\n还顾望旧乡，长路漫浩浩。\n同心而离居，忧伤以终老。'},
    {t:'歙州卢中丞见惠名酝',a:'杜牧〔唐代〕',c:'谁怜贱子启穷途，太守封来酒世壶。\n攻破是非浑似梦，削平身世有如无。\n醺醺若借嵇康懒，兀兀仍添宁武愚。\n犹念悲秋更分赐，夹溪红蓼映风蒲。'},
    {t:'谁氏子',a:'韩愈〔唐代〕',c:'非痴非狂谁氏子，去入王屋称道士。\n白头老母遮门啼，挽断衫袖留不止。\n翠眉新妇年二十，载送还家哭穿市。\n或云欲学吹凤笙，所慕灵妃媲萧史。\n又云时俗轻寻常，力行险怪取贵仕。\n神仙虽然有传说，知者尽知其妄矣。\n圣君贤相安可欺，乾死穷山竟何俟。\n呜呼余心诚岂弟，愿往教诲究终始。\n罚一劝百政之经，不从而诛未晚耳。\n谁其友亲能哀怜，写吾此诗持送似。'},
    {t:'申胡子觱篥歌',a:'李贺〔唐代〕',c:'颜热感君酒，含嚼芦中声。\n花娘篸绥妥，休睡芙蓉屏。\n谁截太平管，列点排空星。\n直贯开花风，天上驱云行。\n今夕岁华落，令人惜平生。\n心事如波涛，中坐时时惊。\n朔客骑白马，剑弝悬兰缨。\n俊健如生猱，肯拾蓬中萤。'},
    {t:'深宫',a:'李商隐〔唐代〕',c:'金殿销香闭绮栊，玉壶传点咽铜龙。\n狂飙不惜萝阴薄，清露偏知桂叶浓。\n斑竹岭边无限泪，景阳宫里及时钟。\n岂知为雨为云处，只有高唐十二峰。'},
    {t:'神鸡童谣',a:'佚名〔唐代〕',c:'生儿不用识文字，斗鸡走马胜华书。\n贾家小儿年十三，富贵荣华代不如。\n能令金距期胜负，白罗绣衫随软舆。\n父死长安千里外，差夫持道挽丧车。'},
    {t:'神蛇显灵',a:'佚名〔近现代〕',c:'赣之鄙，有一媪，年且七旬，其生几值蛇。清明前夕，辍耕反室，见几下有蛇，色褐，长二尺许，卷缩灵动。媪念莫非佳节时蛇来显灵？遂奉以为神，焚香点烛，叩拜甚虔。酉时，媪怀之出户，欲放生。岂知蛇因暖而甦，啮媪臂。媪始觉痛，旋少肿，既而剧痛灵堪，呼里人救。里人车载就医，断臂乃已。呜呼！蛇未福媪，反为其害，乃咎由自取也。'},
    {t:'神弦',a:'李贺〔唐代〕',c:'女巫浇酒云满空，玉炉炭火香咚咚。\n海神山鬼来座中，纸钱窸窣鸣旋风。\n相思木贴金舞鸾，攒蛾一啑重一弹。\n呼星召鬼歆杯盘，山魅食时人森寒。\n终南日色低平湾，神兮长在有无间。\n神嗔神喜师更颜，送神万骑还青山。'},
    {t:'神弦别曲',a:'李贺〔唐代〕',c:'巫山小女隔云别，春风松花山上发。\n绿盖独穿香径归，白马花竿前孑孑。\n蜀江风澹水如罗，堕兰谁泛相经过。\n南山桂树为君死，云衫浅污红脂花。'},
    {t:'神宗皇帝挽辞二首',a:'王安石〔宋代〕',c:'城阙宫车转，山林隧路归。\n苍梧云未远，姑射露先曦。\n玉暗蛟龙蛰，金寒雁鹜飞。\n老臣他日泪，湖海想遗衣。'},
    {t:'沈千运旧居',a:'张籍〔唐代〕',c:'汝北君子宅，我来见颓墉。乱离子孙尽，地属邻里翁。\n土木被丘墟，谿路不连通。旧井蔓草合，牛羊坠其中。\n君辞天子书，放意任体躬。一生不自力，家与逆旅同。\n高议切星辰，馀声激喑聋。方将旌旧闾，百世可封崇。\n嗟其未积年，已为荒林丛。时岂无知音，不能崇此风。\n浩荡竟无睹，我将安所从。'},
    {t:'沈下贤',a:'杜牧〔唐代〕',c:'斯人清唱何人和，草径苔芜不可寻。\n一夕小敷山下梦，水如环佩月如襟。'},
    {t:'沈园二首·其二',a:'陆游〔宋代〕',c:'梦断香消四十年，沈园柳老不吹绵。\n此身行作稽山土，犹吊遗踪一泫然。'},
    {t:'沈园二首·其一',a:'陆游〔宋代〕',c:'城上斜阳画角哀，沈园非复旧池台。\n伤心桥下春波绿，曾是惊鸿照影来。'},
    {t:'审交',a:'孟郊〔唐代〕',c:'种树须择地，恶土变木根。结交性失人，中道生谤言。\n君子芳桂性，春荣冬更繁。小人槿花心，朝在夕不存。\n莫蹑冬冰坚，中有潜浪翻。唯当金石交，可以贤达论。'},
    {t:'升上人碧云轩',a:'范仲淹〔宋代〕',c:'爱此诗家好，幽轩绝世纷。\n澄宵半床月，淡晓数峰云。\n远意经年就，微吟并舍闻。\n祇应虚静处，所得自兰芬。'},
    {t:'升仙桥',a:'岑参〔唐代〕',c:'长桥题柱去，犹是未达时。\n及乘驷马车，却从桥上归。\n名共东流水，滔滔无尽期。'},
    {t:'生查子',a:'晏几道〔宋代〕',c:'红尘陌上游，碧柳堤边住。才趁彩云来，又逐飞花去。\n深深美酒家，曲曲幽香路。风月有情时，总是相思处。'},
    {t:'生查子',a:'晏几道〔宋代〕',c:'金鞍美少年\n去跃青骢马\n牵系玉楼人\n绣被春寒夜\n消息未归来\n寒食梨花谢\n无处说相思\n背面秋千下'},
    {t:'生查子',a:'晏几道〔宋代〕',c:'轻轻制舞衣，小小裁歌扇。三月柳浓时，又向津亭见。\n垂泪送行人，湿破红妆面。玉指袖中弹，一曲清商怨。'},
    {t:'生查子',a:'晏几道〔宋代〕',c:'一分残酒霞，两点愁蛾晕。罗幕夜犹寒，玉枕春先困。\n心情翦彩慵，时节烧灯近。见少别离多，还有人堪恨。'},
    {t:'生查子·鞭影落春堤',a:'纳兰性德〔清代〕',c:'鞭影落春堤，绿锦鄣泥卷。脉脉逗菱丝，嫩水吴姬眼。\n啮膝带香归，谁整樱桃宴。蜡泪恼东风，旧垒眠新燕。'},
    {t:'生查子·惆怅彩云飞',a:'纳兰性德〔清代〕',c:'惆怅彩云飞，碧落知何许。不见合欢花，空倚相思树。\n总是别时情，那待分明语。判得最长宵，数尽厌厌雨。'},
    {t:'生查子·东风不解愁',a:'纳兰性德〔清代〕',c:'东风不解愁，偷展湘裙衩。独夜背纱笼，影著纤腰画。\n爇尽水沉烟，露滴鸳鸯瓦。花骨冷宜香，小立樱桃下。'},
    {t:'生查子·独游西岩',a:'辛弃疾〔宋代〕',c:'青山招不来，偃蹇谁怜汝？岁晚太寒生，唤我溪边住。\n山头明月来，本在天高处。夜夜入青溪，听读《离骚》去。'},
    {t:'生查子·独游雨岩',a:'辛弃疾〔宋代〕',c:'溪边照影行，天在清溪底。天上有行云，人在行云里。\n高歌谁和余，空谷清音起。非鬼亦非仙，一曲桃花水。'},
    {t:'生查子·短焰剔残花',a:'纳兰性德〔清代〕',c:'短焰剔残花，夜久边声寂。倦舞却闻鸡，暗觉青绫湿。\n天水接冥蒙，一角西南白。欲渡浣花溪，远梦轻无力。'},
    {t:'生查子·关山魂梦长',a:'晏几道〔宋代〕',c:'关山魂梦长，鱼雁音尘少。两鬓可怜青，只为相思老。\n归梦碧纱窗，说与人人道。真个别离难，不似相逢好。'},
    {t:'生查子·官身几日闲',a:'晏几道〔宋代〕',c:'官身几日闲，世事何时足。君貌不常红，我鬓无重绿。\n榴花满盏香，金缕多情曲。且尽眼中欢，莫叹时光促。'},
    {t:'生查子·金鞭美少年',a:'晏几道〔宋代〕',c:'金鞭美少年，去跃青骢马。牵系玉楼人，绣被春寒夜。\n消息未归来，寒食梨花谢。无处说相思，背面秋千下。'},
    {t:'生查子·狂花顷刻香',a:'晏几道〔宋代〕',c:'狂花顷刻香，晚蝶缠绵意。天与短因缘，聚散常容易。\n传唱入离声，恼乱双蛾翠。游子不堪闻，正是衷肠事。'},
    {t:'生查子·落梅庭榭香',a:'晏几道〔宋代〕',c:'落梅庭榭香，芳草池塘绿。春恨最关情，日过阑干曲。\n几时花里闲，看得花枝足。醉后莫思家，借取师师宿。'},
    {t:'生查子·轻匀两脸花',a:'晏几道〔宋代〕',c:'轻匀两脸花，淡扫双眉柳。会写锦笺时，学弄朱弦后。\n今春玉钏宽，昨夜罗裙皱。无计奈情何，且醉金杯酒。'},
    {t:'生查子·三尺龙泉剑',a:'佚名',c:'三尺龙泉剑，匣里无人见。\n一张落雁弓，百支金花箭。\n为国竭忠贞，苦处曾征战。\n先望立功勋，后见君王面。'},
    {t:'生查子·诉别',a:'苏轼〔宋代〕',c:'三度别君来，此别真迟暮。白尽老髭须，明日淮南去。\n酒罢月随人，泪湿花如雾。后月逐君还，梦绕湖边路。'},
    {t:'生查子·题京口郡治尘表亭',a:'辛弃疾〔宋代〕',c:'悠悠万世功，矻矻当年苦。鱼自入深渊，人自居平土。\n红日又西沉，白浪长东去。不是望金山，我自思量禹。'},
    {t:'生查子·远山眉黛长',a:'晏几道〔宋代〕',c:'远山眉黛长，细柳腰肢袅。妆罢立春风，一笑千金少。\n归去凤城时，说与青楼道。遍看颍川花，不似师师好。'},
    {t:'生查子·长恨涉江遥',a:'晏几道〔宋代〕',c:'长恨涉江遥，移近溪头住。闲荡木兰舟，误入双鸳浦。\n无端轻薄云，暗作廉纤雨。翠袖不胜寒，欲向荷花语。'},
    {t:'生查子·重叶梅',a:'辛弃疾〔宋代〕',c:'百花头上开，冰雪寒中见。霜月定相知，先识春风面。\n主人情意深，不管江妃怨。折我最繁枝，还许冰壶荐。'},
    {t:'生查子·坠雨已辞云',a:'晏几道〔宋代〕',c:'坠雨已辞云，流水难归浦。遗恨几时休，心抵秋莲苦。\n忍泪不能歌，试托哀弦语。弦语愿相逢，知有相逢否。'},
    {t:'生朝',a:'文天祥〔宋代〕',c:'客中端二日，风雨送牢愁。\n昨岁犹潘母，今年更楚囚。\n田园荒吉水，妻子老幽州。\n莫作长生祝，吾心在首丘。'},
    {t:'生酒歌',a:'杨万里〔宋代〕',c:'生酒清於雪，煮酒赤如血，煮酒生如生酒烈。\n煮酒只带烟火气，生酒生离泉石味。\n石根泉眼新红将，面米酿出春风香。\n坐上猪红间熊白，瓮头鸭绿变鹅黄。\n先生一醉万事已，那知身在尘埃里。'},
    {t:'生禖屏风歌',a:'温庭筠〔唐代〕',c:'玉墀暗接昆仑井，井上无人金月冷。画壁阴森九子堂，\n阶前细月铺花影。绣屏银鸭香蓊蒙，天上梦归花绕丛。\n宜男漫作后庭草，不似樱桃千子红。'},
    {t:'生年不满百',a:'佚名〔两汉〕',c:'生年不满百，常怀千岁忧。\n昼短苦夜长，何不秉烛游！\n为乐当及时，何能待来兹？\n愚者爱惜费，但为后世嗤。\n仙人王子乔，难可与等期。'},
    {t:'生日和聂吉甫',a:'文天祥〔宋代〕',c:'青蒲花未老，黄竹笋初生。\n细味诗工部，闲评字率更。\n大江流日影，时鸟说春荣。\n共作千年计，身谋政自轻。'},
    {t:'生日山中和萧敬夫韵',a:'文天祥〔宋代〕',c:'山深不用结凉棚，风起江苹暑气轻。\n处士林泉自今古，男儿弧矢付豪英。\n客来不必笼中羽，我爱无如橘里枰。\n一任苍松栽十里，他年犹见茯苓生。'},
    {t:'生生亭',a:'孟郊〔唐代〕',c:'滩闹不妨语，跨溪仍置亭。置亭嵽嵲头，开窗纳遥青。\n遥青新画出，三十六扇屏。褭褭立平地，棱棱浮高冥。\n一日数开扉，仙闪目不停。徒夸远方岫，曷若中峰灵。\n拔意千馀丈，浩言永堪铭。浩言无愧同，愧同忍丑醒。\n致之未有力，力在君子听。'},
    {t:'声苦',a:'文天祥〔宋代〕',c:'万死奔波落一生，飘零淮海命何轻。\n近来学得赵清献，叫苦时时数十声。'},
    {t:'声声慢',a:'张炎〔宋代〕',c:'旧游编否\n穿花省路，傍竹寻邻，如何故隐都荒。问取堤边，因甚减却垂杨。消磨纵然未尽，满烟波、添了斜阳。空叹息，又翻成无限，杜老凄凉。\n一舸清风何处，把秦山晋水，分贮诗囊。发已飘飘，休问岁晚空江。松陵试招旧隐，怕白鸥、犹识清狂。渐溯远，望并州、却是故乡。'},
    {t:'声声慢·嘲红木犀',a:'辛弃疾〔宋代〕',c:'余儿时尝入京师禁中凝碧池，因书当时所见。\n开元盛日，天上栽花，月殿桂影重重。十里芬芳，一枝金粟玲珑。管弦凝碧池上，记当时、风月愁侬。翠华远，但江南草木，烟锁深宫。\n只为天姿冷淡，被西风酝酿，彻骨香浓。枉学丹蕉，叶底偷染妖红。道人取次装束，是自家、香底家风。又怕是，为凄凉、长在醉中。'},
    {t:'声声慢·寄叶书隐',a:'张炎〔宋代〕',c:'百花洲畔，十里湖边，沙鸥未许盟寒。旧隐琴书，犹记渭水长安。苍云数千万叠，却依然、一笑人间。似梦里，对清尊白发，秉烛更兰。\n渺渺烟波无际，唤扁舟欲去，且与凭兰。此别何如，能消几度阳关。江南又听夜雨，怕梅花、零落孤山。归最好，甚闲人、犹自未闲。'},
    {t:'声声慢·晴光转树',a:'张炎〔宋代〕',c:'秋高，光景奇绝，与姜白石垂虹气游，同一清致也。\n晴光转树，晓气分岚，何人野渡横舟。断柳枯酒，凉意正满西州。匆匆载花载酒，便无情、也自风流。芳昼短，奈不堪深气，秉烛来游。\n谁识山中朝暮，向白云一笑，今古无愁。散发吟商，此兴万里悠悠。清狂未应似我，倚高寒、隔水呼鸥。须待月，许多清、都付与秋。'},
    {t:'声声慢·山风古道',a:'张炎〔宋代〕',c:'山风古道，海国轻车，相逢只在休瀛。淡薄秋光，恰似此日游情。休嗟鬓丝断雪，喜闲身、重渡西舲。又溯远，趁回潮拍岸，断浦扬舲。莫向长亭折柳，正纷纷落叶，同是飘零。旧隐新招。知住第几层云。疏篱尚存晋菊，想依然、认得渊明。待去也，最愁人，犹恋故人。'},
    {t:'声声慢·送琴友季静轩还杭',a:'张炎〔宋代〕',c:'荷衣消翠，蕙带余香，灯前共语生平。苦竹黄芦，都是梦里游情。西湖几番夜雨，怕如今、冷却鸥盟。倩寄远，见故人说道，杜老飘零。\n难挽清风飞佩，有相思都在，断柳长汀。此别何如，一笑写入瑶琴。天空水云变色，任愔愔、山鬼愁听。兴未已，更何妨、弹到广陵。'},
    {t:'声声慢·停云霭霭',a:'辛弃疾〔宋代〕',c:'停云霭霭，八表同昏，尽日时雨濛濛。搔首良朋，门前平陆成江。春醪湛湛独抚，恨弥襟、闲饮东窗。空延伫，恨舟车南北，欲往何从。\n叹息东园佳树，列初荣枝叶，再竞春风。日月于征，安得促席从容。翩翩何处飞鸟，息庭树、好语和同。当年事，问几人、亲友似翁。'},
    {t:'声声慢·中吴感旧',a:'张炎〔宋代〕',c:'因风整帽，借柳维舟，休登故苑荒台。去岁何年，游处半入苍苔。白鸥旧盟未冷，但寒沙、空与愁堆。谩叹息，问西门洒泪，不忍徘徊。\n眼底江山犹在，把冰弦弹断，苦忆颜回。一点归心，分付布袜青鞋。相寻已期到老，那知人、如此情怀。怅望久，海棠开、依旧燕来。'},
    {t:'声声慢达琴友季静轩还杭',a:'张炎〔宋代〕',c:'荷衣消翠，蕙带馀香，灯前共语生平。苦竹黄芦，都是梦里游情。\n西湖几番夜雨，怕如今、冷却鸥盟。倩寄远，见故人说道，杜老飘零。\n难挽清风飞佩，有相思都在，断柳长汀。此别何如，一笑写入瑶琴。\n天空水云变色，任愔愔、山鬼愁听。兴未已，更何妨、弹到广陵。'},
    {t:'省试风光草际浮',a:'刘禹锡〔唐代〕',c:'熙熙春景霁，草绿春光丽。的历乱相鲜，葳蕤互亏蔽。\n乍疑芊绵里，稍动丰茸际。影碎翻崇兰，浮香转丛蕙。\n含烟绚碧彩，带露如珠缀。幸因采掇日，况此临芳岁。'},
    {t:'省试观庆云图诗',a:'柳宗元〔唐代〕',c:'设色既成象，卿云示国都。九天开秘祉，百辟赞嘉谟。\n抱日依龙衮，非烟近御炉。高标连汗漫，迥望接虚无。\n裂素荣光发，舒华瑞色敷。恒将配尧德，垂庆代河图。'},
    {t:'省中即事',a:'岑参〔唐代〕',c:'华省谬为郎，蹉跎鬓已苍。到来恒襆被，随例且含香。\n竹影遮窗暗，花阴拂簟凉。君王新赐笔，草奏向明光。'},
    {t:'圣女祠',a:'李商隐〔唐代〕',c:'松篁台殿蕙香帏，龙护瑶窗凤掩扉。无质易迷三里雾，\n不寒长著五铢衣。人间定有崔罗什，天上应无刘武威。\n寄问钗头双白燕，每朝珠馆几时归。'},
    {t:'盛京',a:'纳兰性德〔清代〕',c:'拔地蛟龙宅，当关虎豹城。\n山连长白秀，江入混同清。\n庙社灵风肃，豪强右族更。\n明明开创业，休拟作陪京。'},
    {t:'失题三道',a:'苏轼〔宋代〕',c:'公子只应见画，此中我独知津。\n写到水穷天杪，定非尘土间人。'},
    {t:'失意归吴因寄东台刘复侍御',a:'孟郊〔唐代〕',c:'自念西上身，忽随东归风。长安明下影，又落江湖中。\n离娄岂不明，子野岂不聪。至宝非眼别，至音非耳通。\n因缄俗外词，仰寄高天鸿。'},
    {t:'师说',a:'韩愈〔唐代〕',c:'古之学者必有师。师者，所以传道受业解惑也。人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣。生乎吾前，其闻道也固先乎吾，吾从而师之；生乎吾后，其闻道也亦先乎吾，吾从而师之。吾师道也，夫庸知其年之先后生于吾乎？是故无贵无贱，无长无少，道之所存，师之所存也。\n嗟乎！师道之不传也久矣！欲人之无惑也难矣！古之圣人，其出人也远矣，犹且从师而问焉；今之众人，其下圣人也亦远矣，而耻学于师。是故圣益圣，愚益愚。圣人之所以为圣，愚人之所以为愚，其皆出于此乎？爱其子，择师而教之；于其身也，则耻师焉，惑矣。彼童子之师，授之书而习其句读者，非吾所谓传其道解其惑者也。句读之不知，惑之不解，或师焉，或不焉，小学而大遗，吾未见其明也。巫医乐师百工之人，不耻相师。士大夫之族，曰师曰弟子云者，则群聚而笑之。问之，则曰：“彼与彼年相若也，道相似也，位卑则足羞，官盛则近谀。”呜呼！师道之不复，可知矣。巫医乐师百工之人，君子不齿，今其智乃反不能及，其可怪也欤！\n圣人无常师。孔子师郯子、苌弘、师襄、老聃。郯子之徒，其贤不及孔子。孔子曰：三人行，则必有我师。是故弟子不必不如师，师不必贤于弟子，闻道有先后，术业有专攻，如是而已。\n李氏子蟠，年十七，好古文，六艺经传皆通习之，不拘于时，学于余。余嘉其能行古道，作《师说》以贻之。'},
    {t:'诗奉送觉之奉使东川',a:'王安石〔宋代〕',c:'三秋不见每惓惓，握手山林复怅然。\n後会敢期黄耇日，相看且度白鸡年。\n畏途石栈王尊驭，荣路金门祖逖鞭。\n一代官仪新藻拂，得瞻宸宇想留连。'},
    {t:'十二拍',a:'文天祥〔宋代〕',c:'洛阳一别四千里，边庭流血成海水。\n自经丧乱少睡眠，手脚冻皴皮肉死。\n反鏁衡门守环堵，稚子无忧走风雨。\n此时与子空归来，喜得与子长夜语。'},
    {t:'十二时·秋夜',a:'柳永〔宋代〕',c:'晚晴初，淡烟笼月，风透蟾光如洗。觉翠帐、凉生秋思。渐入微寒天气。败叶敲窗，西风满院，睡不成还起。更漏咽、滴破忧心，万感并生，都在离人愁耳。\n天怎知、当时一句，做得十分萦系。夜永有时，分明枕上，觑着孜孜地。烛暗时酒醒，元来又是梦里。〓睡觉来、披衣独坐，万种无憀情意。怎得伊来，重谐云雨，再整馀香被。祝告天发愿，从今永无抛弃。'},
    {t:'十二月八日步至西村',a:'陆游〔宋代〕',c:'腊月风和意已春，时因散策过吾邻。\n草烟漠漠柴门里，牛迹重重野水滨。\n多病所须唯药物，差科未动是闲人。\n今朝佛粥更相馈，更觉江村节物新。'},
    {t:'十二月二十日作',a:'文天祥〔宋代〕',c:'家国衰千古，星霜忽一周。\n黄沙漫故道，白骨委荒丘。\n许远死何晚，李陵生自羞。\n南来冠不改，吾且任吾囚。'},
    {t:'十九兄郡楼有宴，病不赴',a:'杜牧〔唐代〕',c:'十二层楼敞画檐，连去歌尽草纤纤。\n空堂病怯阶前月，燕子嗔垂一竹帘。'},
    {t:'十六拍',a:'文天祥〔宋代〕',c:'乃知贫贱别更苦，况我飘转无定所。\n心怀百忧复千虑，世人那得知其故。\n娇儿不离膝，哀哉两决绝。\n也复可怜人，里巷尽呜咽。\n断肠分手各风烟，中间消息两茫然。\n自断此生休问天，看射猛虎终残年。'},
    {t:'十六夜玩月',a:'杜甫〔唐代〕',c:'旧挹金波爽，皆传玉露秋。\n关山随地阔，河汉近人流。\n谷口樵归唱，孤城笛起愁。\n巴童浑不寝，半夜有行舟。'},
    {t:'十拍',a:'文天祥〔宋代〕',c:'今年腊月冻全消，天涯涕泪一身遥。\n诸将亦自军中至，行人弓箭各在腰。\n白马嚼啮黄金勒，三尺角弓两斛力。\n胡雁翅湿高飞难，一箭正坠双飞翼。'},
    {t:'十五拍',a:'文天祥〔宋代〕',c:'寒雨飒飒枯树湿，坐卧只多少者立。\n青春欲暮急还乡，非关使者徵求急。\n欲别上马身无力，去住彼此无消息。\n关塞萧条者路难，者路难者涩如棘。\n男儿性命绝可怜，十日不一见颜色。'},
    {t:'十一月四日风雨大作·其二',a:'陆游〔宋代〕',c:'僵卧孤村不自哀，尚思为国戍轮台。\n夜阑卧听风吹雨，铁马冰河入梦来。'},
    {t:'十一月四日风雨大作二首',a:'陆游〔宋代〕',c:'风卷江湖雨暗村，四山声作海涛翻。\n溪柴火软蛮毡暖，我与狸奴不出门。\n僵卧孤村不自哀，尚思为国戍轮台。\n夜阑卧听风吹雨，铁马冰河入梦来。'},
    {t:'十一月五日夜半偶作',a:'陆游〔宋代〕',c:'草径江村人迹绝，白头病卧一书生。\n窗间月出见梅影，枕上酒醒闻雁声。\n寂寞已甘千古笑，驰驱犹望两河平。\n後生谁记当年事，泪溅龙床请北征？'},
    {t:'十一月中旬至扶风界见梅花',a:'李商隐〔唐代〕',c:'匝路亭亭艳，非时裛裛香。\n素娥惟与月，青女不饶霜。\n赠远虚盈手，伤离适断肠。\n为谁成早秀，不待作年芳。'},
    {t:'十月二十八日风雨大作',a:'陆游〔宋代〕',c:'风怒欲拔木，雨暴欲掀屋。\n风声开海涛，雨点堕车轴。\n拄门那敢开，吹火不得烛。\n岂惟涨沟溪，势年卷平陆。\n辛勤蓺宿麦，所望明年熟。\n一饱正自艰，五穷故相逐。\n南邻更可念，布被冬未赎。\n明朝甑复空，母子相持哭。'},
    {t:'十月十五日观月黄楼席上次韵',a:'苏轼〔宋代〕',c:'中秋天气未应殊，不用红纱照月隅。\n山下白云横匹素，水中明月卧浮图。\n未成短棹还三峡，已约轻舟泛五湖。\n为问登临好风景，明年还忆使君无。'},
    {t:'十月十五早饭清都观逍遥堂',a:'黄庭坚〔宋代〕',c:'心游魏阙鱼千里，梦觉邯郸黍一炊。\n蔬食菜羹吾亦饱，逍遥堂下叶辞枝。'},
    {t:'石城乐',a:'佚名〔隋代〕',c:'生长石城下，开窗对城楼。\n城中诸少年，出入见依投。'},
    {t:'石城乐',a:'佚名〔南北朝〕',c:'闻欢远行去，相送方山亭。\n风吹黄檗藩，恶闻苦篱声。'},
    {t:'石城乐其三',a:'佚名〔隋代〕',c:'布帆百馀幅，环环在江津。执手双泪落，何时见欢还。'},
    {t:'石城晓',a:'李贺〔唐代〕',c:'月落大堤上，女垣栖乌起。细露湿团红，寒香解夜醉。\n女牛渡天河，柳烟满城曲。上客留断缨，残蛾斗双绿。\n春帐依微蝉翼罗，横茵突金隐体花。帐前轻絮鹤毛起，\n欲说春心无所似。'},
    {t:'石鼓歌',a:'韦应物〔唐代〕',c:'周宣大猎兮岐之阳，刻石表功兮炜煌煌。\n石如鼓形数止十，风雨缺讹苔藓涩。\n今人濡纸脱其文，既击既扫白黑分。\n忽开满卷不可识，惊潜动蛰走云云。\n喘逶迤，相纠错，乃是宣王之臣史籀作。\n一书遗此天地间，精意长存世冥寞。\n秦家祖龙还刻石，碣石之罘李斯迹。\n世人好古犹共传，持来比此殊悬隔。'},
    {t:'石壕吏',a:'杜甫〔唐代〕',c:'暮投石壕村，有吏夜捉人。\n老翁逾墙走，老妇出门看。\n吏呼一何怒！妇啼一何苦！\n听妇前致词：三男邺城戍。\n一男附书至，二男新战死。\n存者且偷生，死者长已矣！\n室中更无人，惟有乳下孙。\n有孙母未去，出入无完裙。\n老妪力虽衰，请从吏夜归。\n急应河阳役，犹得备晨炊。\n夜久语声绝，如闻泣幽咽。\n天明登前途，独与老翁别。'},
    {t:'石榴',a:'李商隐〔唐代〕',c:'榴枝婀娜榴实繁，榴膜轻明榴子鲜。\n可羡瑶池碧桃树，碧桃红颊一千年。'},
    {t:'石榴',a:'晏殊〔宋代〕',c:'开从百花后，占断群芳色。更作琴轸房，轻盈琐窗侧。'},
    {t:'石楼',a:'文天祥〔宋代〕',c:'晓色重帘卷，春声叠鼓催。\n长垣连草树，远水照楼台。\n八境烟浓淡，六街人往来。\n平安消息好，看到岭头梅。'},
    {t:'石犀',a:'岑参〔唐代〕',c:'江水初荡潏，蜀人几为鱼。向无尔石犀，安得有邑居。\n始知李太守，伯禹亦不如。'},
    {t:'石州慢·九日',a:'秦观〔宋代〕',c:'深院萧条，满地苍苔，一丛荒菊。客霜冷蕊，全无佳思，向人摇绿。客边节序，草草付与清觞，孤吟知把羁怀触。便击碎歌壶，有谁知中曲。\n凝目。乡关何处，华发缁尘，年来劳碌。契阔山中松径，湖边茅屋。沈思此景，几度梦里追寻，青枫路远迷烟竹。待倩问麻姑，借秋风黄鹄。'},
    {t:'石州慢·野色惊秋',a:'张炎〔宋代〕',c:'野色惊秋，随意散愁，踏碎黄叶。行家篱院闲花，似语试妆娇怯。行行步影，未教背写腰肢，一搦端立门前雪。依约镜中春，又无端轻别。痴绝。汉皋何处，解佩何人，底须情切。空引东邻，遗恨丁香空结。十年旧梦，谩馀恍惚云窗，可怜不是当时蝶。深夜醉醒来，好一庭风月。'},
    {t:'石竹花',a:'王安石〔宋代〕',c:'春归幽谷始成丛，地面芬敷浅浅红。\n车马不临谁见赏，可怜亦解度春风。'},
    {t:'石子涧二首',a:'范仲淹〔宋代〕',c:'飞泉落处满潭雷，一道苍然石壁开。\n故老相傅应可信，此山云出雨须来。'},
    {t:'时人为刘劭刘骏语',a:'佚名〔隋代〕',c:'遥望建康城，江水逆流萦。前见子杀父，后见弟杀兄。'},
    {t:'时雨',a:'陆游〔宋代〕',c:'时雨及芒种，四野皆插秧。\n家家麦饭美，处处菱歌长。\n老我成惰农，永日付竹床。\n衰发短不栉，爱此一雨凉。\n庭木集奇声，架藤发幽香。\n莺衣湿不去，劝我持一觞。\n即今幸无事，际海皆农桑。\n野老固不穷，击壤歌虞唐。'},
    {t:'时运·其二',a:'陶渊明〔魏晋〕',c:'洋洋平潭，乃漱乃濯。\n邈邈遐景，载欣载瞩。\n人亦有言，称心易足。\n挥兹一觞，陶然自乐。'},
    {t:'食莲子',a:'杨万里〔宋代〕',c:'绿玉蜂房白玉蜂，折来带露复含风。玻瓈盆面冰浆底，醉嚼新莲一百蓬。'},
    {t:'食蒸饼作',a:'杨万里〔宋代〕',c:'何家笼饼须十字，萧家炊饼须仑破。\n老夫饥来不可那，只要鹘仑吞一个。\n诗人一腹大於蝉，饥饱翻手覆手间。\n须臾放箸付一莞，急唤龙团分蟹眼。'},
    {t:'食粥',a:'陆游〔宋代〕',c:'世人个个学长年，不悟长年在目前。\n我得宛丘平易法，只将食粥致神仙。'},
    {t:'使东川·汉江上笛',a:'元稹〔唐代〕',c:'小年为写游梁赋，最说汉江闻笛愁。\n今夜听时在何处，月明西县驿南楼。'},
    {t:'使东川·嘉陵江二首',a:'元稹〔唐代〕',c:'秦人惟识秦中水，长想吴江与蜀江。\n今日嘉川驿楼下，可怜如练绕明窗。\n千里嘉陵江水声，何年重绕此江行。\n只应添得清宵梦，时见满江流月明。'},
    {t:'使东川·江花落',a:'元稹〔唐代〕',c:'日暮嘉陵江水东，梨花万片逐江风。\n江花何处最肠断，半落江流半在空。'},
    {t:'使东川·江楼月',a:'元稹〔唐代〕',c:'序：嘉川驿望月、忆杓直、乐天、知夜、拒非、顺之数贤，居近曲满，闲夜多同步月。\n嘉陵满岸驿楼中，满在楼前月在空。\n月色满床兼满地，满声如鼓复如风。\n诚知远近皆三五，但恐阴晴有异同。\n万一帝乡还洁白，几人潜傍杏园东。'},
    {t:'使东川·骆口驿二首',a:'元稹〔唐代〕',c:'邮亭壁上数行字，崔李题名王下诗。\n尽日无人共言语，不离墙下至行时。\n二星徼外通蛮服，五夜灯前草御文。\n我到东川恰相半，向南看月北看云。'},
    {t:'使东川·南秦雪',a:'元稹〔唐代〕',c:'帝城寒尽临寒食，骆谷春深未有春。\n才见岭头云似盖，已惊岩下雪如尘。\n千峰笋石千株玉，万树松萝万朵银。\n飞鸟不飞猿不动，青骢御史上南秦。'},
    {t:'使东川·清明日',a:'元稹〔唐代〕',c:'常年寒食好风轻，触处相随取次行。\n今日清明汉江上，一身骑马县官迎。'},
    {t:'使东川·望喜驿',a:'元稹〔唐代〕',c:'满眼文书堆案边，眼昏偷得暂时眠。\n子规惊觉灯又灭，一道月光横枕前。'},
    {t:'使东川·望驿台·三月尽',a:'元稹〔唐代〕',c:'可怜三月三旬足，怅望江边望驿台。\n料得孟光今日语，不曾春尽不归来。'},
    {t:'使东川·亚枝红',a:'元稹〔唐代〕',c:'平阳池上亚枝红，怅望山邮事事同。\n还向万竿深竹里，一枝浑卧碧流中。'},
    {t:'使东川·夜深行',a:'元稹〔唐代〕',c:'夜深犹自绕江行，震地江声似鼓声。\n渐见戍楼疑近驿，百牢关吏火前迎。'},
    {t:'使东川·邮亭月',a:'元稹〔唐代〕',c:'君多务实我多情，大抵偏嗔步月明。\n今夜山邮与蛮嶂，君应坚卧我还行。'},
    {t:'使还都湘东作',a:'张九龄〔唐代〕',c:'仓庚昨归候，阳鸟今去时。\n感物格如此，劳生安可思。\n养真无上格，图进岂前期。\n清节往来苦，壮云离别衰。\n盛明非不遇，弱操自云私。\n孤楫清川泊，征衣寒露滋。\n风朝津树落，日夕岭猿悲。\n牵役而无悔，坐愁只自怡。\n当须报恩已，终尔谢尘缁。'},
    {t:'使还湘水',a:'张九龄〔唐代〕',c:'归舟宛何处，正值楚江平。夕逗烟村宿，朝缘浦树行。\n于役已弥岁，言旋今惬情。乡郊尚千里，流目夏云生。'},
    {t:'使青夷军入居庸三首',a:'高适〔唐代〕',c:'匹马行将久，征途去转难。\n不知边地别，只讶客衣单。\n溪冷泉声苦，山空木叶干。\n莫言关塞极，云雪尚漫漫。\n古镇青山口，寒风落日时。\n岩峦鸟不过，冰雪马堪迟。\n出塞应无策，还家赖有期。\n东山足松桂，归去结茅茨。\n登顿驱征骑，栖迟愧宝刀。\n远行今若此，微禄果徒劳。\n绝坂水连下，群峰云共高。\n自堪成白首，何事一青袍。'},
    {t:'使青夷军入居庸三首其三',a:'高适〔唐代〕',c:'登顿驱征骑，栖迟愧宝刀。远行今若此，微禄果徒劳。\n绝坂水连下，群峰云共高。自堪成白首，何事一青袍。'},
    {t:'使院中新栽柏树子呈李十五栖筠',a:'岑参〔唐代〕',c:'爱尔青青色，移根此地来。\n不曾台上种，留向碛中栽。\n脆叶欺门柳，狂花笑院梅。\n不须愁岁晚，霜露岂能摧。'},
    {t:'使至广州',a:'张九龄〔唐代〕',c:'昔年尝不调，兹地亦邅回。本谓双凫少，何知驷马来。\n人非汉使橐，郡是越王台。去去虽殊事，山川长在哉。'},
    {t:'使至塞上',a:'王维〔唐代〕',c:'单车欲问边，属国过居延。\n征蓬出汉塞，归雁入胡天。\n大漠孤烟直，长河落日圆。\n萧关逢候骑，都护在燕然。'},
    {t:'始除尚书郎，别善福精舍',a:'韦应物〔唐代〕',c:'简略非世器，委身同草木。逍遥精舍居，饮酒自为足。\n累日曾一栉，对书常懒读。社腊会高年，山川恣游瞩。\n明世方选士，中朝悬美禄。除书忽到门，冠带便拘束。\n愧忝郎署迹，谬蒙君子录。俯仰垂华缨，飘飖翔轻毂。\n行将亲爱别，恋此西涧曲。远峰明夕川，夏雨生众绿。\n迅风飘野路，回首不遑宿。明晨下烟阁，白云在幽谷。'},
    {t:'始见白发题所植海石榴',a:'柳宗元〔唐代〕',c:'几年封植爱芳丛，韵艳朱颜竟不同。\n从此休论上春事，看成古木对衰翁。'},
    {t:'始为奉礼忆昌谷山居',a:'李贺〔唐代〕',c:'扫断马蹄痕，衙回自闭门。\n长枪意米熟，小树枣花春。\n向壁悬如意，当帘阅角巾。\n犬书曾去洛，鹤病悔游秦。\n土甑封茶叶，山杯锁竹根。\n不知船上月，谁棹满溪云？'},
    {t:'始闻秋风',a:'刘禹锡〔唐代〕',c:'昔看黄菊与君别，今听玄蝉我却回。\n五夜飕飗枕前觉，一年颜状镜中来。\n马思边草拳毛动，雕眄青云睡眼开。\n天地肃清堪四望，为君扶病上高台。'},
    {t:'始闻夏蝉',a:'韦应物〔唐代〕',c:'徂夏暑未晏，蝉鸣景已曛。一听知何处，高树但侵云。\n响悲遇衰齿，节谢属离群。还忆郊园日，独向涧中闻。'},
    {t:'始夏南园思旧里',a:'韦应物〔唐代〕',c:'夏首云物变，雨馀草木繁。\n池荷初帖水，林花已扫园。\n萦丛蝶尚乱，依阁鸟犹喧。\n对此残芳月，忆在汉陵原。'},
    {t:'始至郡',a:'韦应物〔唐代〕',c:'湓城古雄郡，横江千里驰。高树晚迢递，峻堞绕欹危。\n井邑烟火晚，郊原草树滋。洪流荡北阯，崇何郁南圻。\n斯民本乐生，逃逝竟何为。旱岁属荒歉，旧逋积如坻。\n到郡方逾月，终朝理乱丝。宾朋未及宴，简牍已云疲。\n昔贤播高风，得守愧无施。岂待干戈戢，且愿抚惸嫠。'},
    {t:'始作镇军参军经曲阿作',a:'陶渊明〔魏晋〕',c:'弱龄寄事外，委怀在琴书。\n被褐欣自得，屡空常晏如。\n时来苟冥会，宛辔憩通衢。\n投策命晨装，暂与园田疏。\n眇眇孤舟逝，绵绵归思纡。\n我行岂不遥，登降千里余。\n目倦川途异，心念山泽居。\n望云惭高鸟，临水愧游鱼。\n真想初在襟，谁谓形迹拘。\n聊且凭化迁，终返班生庐。'},
    {t:'示从子河南尉班',a:'韦应物〔唐代〕',c:'拙直余恒守，公方尔所存。同占朱鸟克，俱起小人言。\n立政思悬棒，谋身类触藩。不能林下去，只恋府廷恩。'},
    {t:'示弟',a:'李贺〔唐代〕',c:'别弟三年后，还家一日余。\n醁醽今夕酒，缃帙去时书。\n病骨犹能在，人间底事无？\n何须问牛马，抛掷任枭卢！'},
    {t:'示儿',a:'陆游〔宋代〕',c:'死去元知万事空，但悲不见九州同。\n王师北定中原日，家祭无忘告乃翁。'},
    {t:'示儿子',a:'陆游〔宋代〕',c:'禄食无功我自知，汝曹何以报亲时？\n为农为士亦奚异，事国事亲惟不欺。\n道在六经宁有尽，躬耕百亩可无饥。\n最亲切处今相付，熟读周公七月诗。'},
    {t:'示孟郊',a:'孟浩然〔唐代〕',c:'蔓草蔽极野，兰芝结孤根。\n众音意其繁，伯牙独不喧。\n当时高深意，举世无能分。\n钟期一见知，山水千秋闻。\n尔其保静节，薄俗徒云云。'},
    {t:'示全真元常',a:'韦应物〔唐代〕',c:'余辞郡符去，尔为外事牵。\n宁知风雪夜，复此对床眠。\n始话南池饮，更咏西楼篇。\n无将一会易，岁月坐推迁。'},
    {t:'示西林可师二首其二',a:'朱熹〔宋代〕',c:'幽居四畔只空林，啼鸟落花春意深。独宿尘龛无梦寐，五更山月照寒衾。'},
    {t:'示张寺丞王校勘',a:'晏殊〔宋代〕',c:'元巳清明假未开，小园幽径独徘徊。\n春寒不定斑斑雨，宿酒难禁滟滟杯。\n无可奈何花落去，似曾相识燕归来。\n游梁赋客多风味，莫惜青钱万选才。'},
    {t:'示长安君',a:'王安石〔宋代〕',c:'少年离别意非轻，老去相逢亦火情。\n草草杯盘共笑语，昏昏灯火话平生。\n自怜湖海三年隔，又作尘沙万里行。\n欲问后期何日是，寄书应见雁南征。'},
    {t:'示周续之祖企谢景夷三郎',a:'陶渊明〔魏晋〕',c:'负疴颓檐下，终日无一欣。\n药石常时闲，念我意中人。\n相去不寻常，道路邈何因？\n周生述孔业，祖斯响然臻。\n道丧向千载，今朝复斯闻。\n马队非讲肆，校书亦已勤。\n老夫常所爱，思与尔为邻。\n愿言诲诸子，从我颍水滨。'},
    {t:'示子遹',a:'陆游〔宋代〕',c:'我初学诗日，但欲工藻绘。\n中年始少悟，渐若窥宏大。\n怪奇亦间出，如石漱湍濑。\n数仞李杜墙，常恨欠领会。\n元白才倚门，温李真自郐。\n正令笔扛鼎，亦未造三昧。\n诗为六艺一，岂用资狡狯？\n汝果欲学诗，工夫在诗外。'},
    {t:'世上',a:'王安石〔宋代〕',c:'范蠡五湖收远迹，管宁沧海寄余生。\n可怜世上风波恶，最有仁贤不敢行。'},
    {t:'世事',a:'文天祥〔宋代〕',c:'世事孤鸿外，人生落日西。\n棋淫诗兴薄，书倦梦魂迷。\n汩汩驰还坐，悠悠笑即啼。\n一真吾自得，开眼总筌蹄。'},
    {t:'试笔',a:'范仲淹〔宋代〕',c:'偶缘疏拙得天真，岂问前途屈可伸。\n车马纵能欺倦客，江山犹可助骚人。\n懒如叔夜书盈几，狂似渊明酒满巾。\n况有南窗姬易在，此心那更起纖尘。'},
    {t:'视刀环歌',a:'刘禹锡〔唐代〕',c:'常恨言语浅，不如人意深。\n今朝两相视，脉脉万重心。'},
    {t:'适越留别谯县张主薄申屠少府①',a:'孟浩然〔唐代〕',c:'朝乘汴河流，夕次谯县界。\n幸值西风吹，得与故人会。\n君学梅福隐，余从伯鸾迈。\n别后能相思，浮云在吴会。'},
    {t:'释裴循春愁',a:'皎然〔唐代〕',c:'蝶舞莺歌喜岁芳，柳丝袅袅蕙带长。\n江南春色共君有，何事君心独自伤。'},
    {t:'守岁',a:'苏轼〔宋代〕',c:'欲知垂尽岁，有似赴壑蛇。\n修鳞半已没，去意谁能遮。\n况欲系其尾，虽勤知奈何。\n儿童强不睡，相守夜欢哗。\n晨鸡且勿唱，更鼓畏添挝。\n坐久灯烬落，起看北斗斜。\n明年岂无年，心事恐蹉跎。\n努力尽今夕，少年犹可夸。'},
    {t:'首春逢耕者',a:'柳宗元〔唐代〕',c:'南楚春候早，余寒已滋荣。\n土膏郊原野，白蛰竞所营。\n缀景未及郊，穑人先偶耕。\n园林幽鸟啭，渚平新泉清。\n农事诚素务，羁囚阻平生。\n故池想芜没，遗亩当榛荆。\n慕隐既有系，图功遂无成。\n聊从田父言，款曲陈此情。\n眷然抚耒耜，回首烟云横。'},
    {t:'首春渭西郊行，呈蓝田张二主簿',a:'岑参〔唐代〕',c:'回风度雨渭城西，细草新花踏作泥。秦女峰头雪未尽，\n胡公陂上日初低。愁窥白发羞微禄，悔别青山忆旧谿。\n闻道辋川多胜事，玉壶春酒正堪携。'},
    {t:'首秋轮台',a:'岑参〔唐代〕',c:'异域阴山外，孤城雪海边。\n秋来唯有雁，夏尽不闻蝉。\n雨拂毡墙湿，风摇毳幕羶。\n轮台万里地，无事历三年。'},
    {t:'首夏南池独酌',a:'白居易〔唐代〕',c:'春尽杂英歇，夏初芳草深。\n薰风自南至，吹我池上林。\n绿蘋散还合，赪鲤跳复沉。\n新叶有佳色，残莺犹好音。\n依然谢家物，池酌对风琴。\n惭无康乐作，秉笔思沉吟。\n境胜才思劣，诗成不称心。'},
    {t:'寿陈运干',a:'周邦彦〔宋代〕',c:'节过中和日有三，台星一点下江南。\n因仍睿算疏恩宠，多少春风在笑谈。\n颂祝椒花随以柏，恩袍欺草绿於蓝。\n儿孙更祝无穷寿，齐指庄桩原与参。'},
    {t:'寿母生朝其一',a:'朱熹〔宋代〕',c:'秋风萧爽天气凉，此日何日升斯堂。堂中老人寿而康，红颜绿鬓双瞳方。\n家贫儿痴但深藏，五年不出门庭荒。灶陉十日九不炀，岂办甘脆陈壶觞。\n低头包羞汗如浆，老人此心久已忘。一笑谓汝庸何伤，人间荣耀岂可常。\n惟有道义思无疆，勉励汝节弥坚刚。熹前再拜谢阿娘，自古作善天降祥。\n但愿年年似今日，老莱母子俱徜徉。'},
    {t:'寿宋守',a:'周邦彦〔宋代〕',c:'珥笔曾趋殿两间，冰姿清彻照朝班。\n民讴在处思廉范，谏疏何人忆贾山。\n竹简繙经秋闭阁，玉棋欢客夜留关。\n直须剩饮帮人寿，天上如今欲赐环。'},
    {t:'寿朱约山八十韵',a:'文天祥〔宋代〕',c:'翠袖琼楼八十翁，平安晓宇看中鸿。\n五湖图里添彭祖，南极光中约祝融。\n日日青山醉春色，年年黄菊饱西风。\n鹰扬但愿无施处，臣老婆娑一钓蓬。'},
    {t:'受恩深·雅致装庭宇',a:'柳永〔宋代〕',c:'雅致装庭宇。黄花开淡泞。细香明艳尽天与。助秀色堪餐，向晓自有真珠露。刚被金钱妒。拟买断秋天，容易独步。\n粉蝶无情蜂已去。要上金尊，惟有诗人曾许。待宴赏重阳，恁时尽把芳心吐。陶令轻回顾。免憔悴东篱，冷烟寒雨。'},
    {t:'授衣还田里',a:'韦应物〔唐代〕',c:'公门悬甲令，浣濯遂其私。晨起怀怆恨，野田寒露时。\n气收天地广，风凄草木衰。山明始重叠，川浅更逶迤。\n烟火生闾里，禾黍积东菑。终然可乐业，时节一来斯。'},
    {t:'书戴嵩画牛',a:'苏轼〔宋代〕',c:'蜀中有杜处士，好书画，所宝以百数。有戴嵩《牛》一轴，尤所爱，锦囊玉轴，常以自随。\n一日曝书画，有一牧童见之，拊掌大笑，曰：“此画斗牛也。牛斗，力在角，尾搐入两股间，今乃掉尾而斗，谬矣。”处士笑而然之。古语有云：“耕当问奴，织当问婢。”不可改也。'},
    {t:'书愤',a:'陆游〔宋代〕',c:'清汴逶迤贯旧京，宫墙春草几番生。\n剖心莫写孤臣愤，抉眼终看此虏平。\n天地固将容小丑，犬羊自惯渎齐盟。\n蓬窗老抱横行略，未敢随人说弭兵。'},
    {t:'书愤二首',a:'陆游〔宋代〕',c:'白发萧萧卧泽中，只凭天地鉴巡忠。\n厄穷苏武餐毡久，忧愤张巡嚼齿空。\n细雨春芜上林苑，颓老夜月洛阳宫。\n壮心未与年俱老，死去犹能作鬼雄。\n镜里流年两鬓残，寸心自许尚如丹。\n衰迟罢试戎衣窄，悲愤犹争宝剑寒。\n远戍十年临的博，壮图万里战皋兰。\n关河自古无穷事，谁料如今袖手看。'},
    {t:'书海陵滕從事文会堂',a:'范仲淹〔宋代〕',c:'东南沧海郡，幕府清风堂。\n诗书对周孔，琴瑟亲义黄。\n君子不独乐，我朋来远方。\n言兰一相接，岂特十步香。\n德星一相聚，直有千载光。\n道味清可挹，文思高若翔。\n笙磬得同声，精色皆激扬。\n裁培尽桃李，栖止皆鸾皇。\n琢玉作镇圭，铸金为干将。\n猗哉滕子京，此意久而芳。'},
    {t:'书湖阴先生壁二首',a:'王安石〔宋代〕',c:'茅檐长扫净无苔，花木成畦手闼栽。\n一水护田将绿绕，两山排闼送青来。\n桑条索漠楝花繁，风敛余香暗度垣。\n黄鸟数声残午梦，尚疑身属半山园。'},
    {t:'书湖阴先生壁二首·其二',a:'王安石〔宋代〕',c:'桑条索漠楝花繁，风敛余香暗度垣。\n黄鸟数声残午梦，尚疑身属半山园。'},
    {t:'书怀',a:'杜牧〔唐代〕',c:'满目青山未得过，镜中无那鬓丝何。\n只言旋老转无事，欲到中年事更多。'},
    {t:'书怀寄王秘书',a:'张籍〔唐代〕',c:'白发如今欲满头，从来百事尽心休。\n只于触目须防病，不拟将心更养愁。\n下药远求新熟酒，看山多上最高楼。\n赖君同在京城住，每到花前免独游。'},
    {t:'书怀寄元郎中',a:'张籍〔唐代〕',c:'转觉人间无气味，常因身外省因缘。经过独爱游山客，\n计校唯求买药钱。重作学官闲尽日，一离江坞病多年。\n吟君钓客词中说，便欲南归榜小船。'},
    {t:'书怀贻京邑同好',a:'孟浩然〔唐代〕',c:'维先自邹鲁，家世重儒风。\n诗礼袭遗训，趋庭沾末躬。\n昼夜常自强，词翰颇亦工。\n三十既成立，嗟吁命不通。\n慈亲向羸老，喜惧在深衷。\n甘脆朝不足，箪瓢夕屡空。\n执鞭慕夫子，捧檄怀毛公。\n感激遂弹冠，安能守固穷。\n当途诉知己，投刺匪求蒙。\n秦楚邈离异，翻飞何日同。'},
    {t:'书酒家壁',a:'范仲淹〔宋代〕',c:'当垆一曲竹枝歌，肠断江南奈尔何。游子未归春又老，夜来风雨落花多。'},
    {t:'书乐天纸',a:'元稹〔唐代〕',c:'金銮殿里书残纸，乞与荆州元判司。\n不忍拈将等闲用，半封京信半题诗。'},
    {t:'书李世南所画秋景二首',a:'苏轼〔宋代〕',c:'野水参差落涨痕，疏林欹倒出霜根。\n扁舟一棹归何处？家在江南黄叶村。\n人间斤斧日创夷，谁见龙蛇百尺姿。\n不是溪山成独往，何人解作挂猿枝。'},
    {t:'书林逋诗后',a:'苏轼〔宋代〕',c:'吴侬生长湖山曲，呼吸湖光饮山渌。\n不论世外隐君子，佣儿贩妇皆冰玉。\n先生可是绝俗人，神清骨冷无由俗。\n我不识君曾梦见，瞳子了然光可烛。\n遗篇妙字处处有，步绕西湖看不足。\n诗如东野不言寒，书似留台差少肉。\n平生高节已难继，将死微言犹可录。\n自言不作封禅书，更肯悲吟白头曲！\n我笑吴人不好事，好作祠堂傍修竹。\n不然配食水仙王，一盏寒泉荐秋菊。'},
    {t:'书莫读',a:'杨万里〔宋代〕',c:'书莫读，诗莫吟。读书两眼枯见骨，吟诗个字呕出心。\n人言读书乐，人言吟诗好。口吻长作秋虫声，只令君瘦令君老。\n君瘦君老且勿论，傍人听之亦烦恼。何如闭目坐斋房，下帘扫地自焚香。\n听风听雨都有味，健来即行倦来睡。'},
    {t:'书扇示门人',a:'范仲淹〔宋代〕',c:'一派青山景色幽，前人田地后人收。\n后人收得休欢喜，还有收人在后头。'},
    {t:'书上元夜游',a:'苏轼〔宋代〕',c:'己卯上元，予在儋州，有老书生一人来过，曰：“良月嘉夜，先生能一出乎？”予欣然从之。步城西，入然舍，历小巷，民夷杂揉，屠沽纷然。归舍已三鼓矣。舍中掩关熟睡，已再鼾矣。放杖而笑，孰为得失？过问先生何笑，盖自笑也。然亦笑韩退之钓鱼无得，更欲远去，不知走海者未必得大鱼也。'},
    {t:'书事',a:'王维〔唐代〕',c:'轻阴阁小雨，深院昼慵开。\n坐看苍苔色，欲上人衣来。'},
    {t:'书事呈韩布殿丞',a:'范仲淹〔宋代〕',c:'南宫曾荐牧之文，失足徒劳忽十春。天上云龙期际会，山中猿鹤愧因循。\n无功岂不孤黄石，有道何堪忆紫莼。少壮由来须努力，篆铭钟鼎古何人。'},
    {t:'书叹',a:'陆游〔宋代〕',c:'人生如春蚕，作茧自缠裹。\n一朝眉羽成，钻破亦在我。\n少年不自珍，妄念然烈火。\n眼乱舞腰轻，心醉笑齿瑳。\n余龄幸早悟，世味无一可。\n但忆唤山僧，煎茶陈饼果。'},
    {t:'书停云壁',a:'辛弃疾〔宋代〕',c:'万事随缘无所为，万法皆空无所思。\n惟有一条生死路，古今来往更何疑。'},
    {t:'书汪水云诗后',a:'文天祥〔宋代〕',c:'南风之薰兮琴无弦，北风其凉兮诗无传。\n云之汉兮水之渊，佳哉斯人兮水云之仙。'},
    {t:'书舞阳西寺旧题处',a:'黄庭坚〔宋代〕',c:'万事纷纷日日新，当时题壁是前身。\n寺僧物色来相访，我似昔人非昔人。'},
    {t:'书喜',a:'陆游〔宋代〕',c:'雨足郊原正得晴，地绵万里尽春耕。\n阴阴阡陌桑麻暗，轧轧房栊机杼鸣。\n亭鼓不闻知盗息，社钱易敛庆秋成。\n天公不负书生眼，留向人间看太平。'},
    {t:'疏影·芭蕉',a:'纳兰性德〔清代〕',c:'湘帘卷处，甚离披翠影，绕檐遮床。小立吹裙，常伴春慵，掩映绣床金缕。芳心一束浑难展，清泪雨、隔年愁聚。更夜深、细听空阶雨滴，梦回无据。\n正是秋来寂寞，偏声声点点，助人难绪。缬被初寒，宿酒全醒，搅碎乱蛩双杵。西风落尽庭梧叶，还剩得、绿阴如许。想玉人、和露折来，曾写断肠句。'},
    {t:'疏影·梅影',a:'张炎〔宋代〕',c:'黄昏片月。似碎阴满地，还更清灯。枝北枝南，疑有疑无，几度背灯难折。依稀倩女离魂处，缓步应、前村时节。看夜深、竹外横斜，应妒过云明灭。\n窥镜蛾眉淡抹。为容不在貌，独抱孤洁。莫是花光，描取春痕，不怕丽谯吹彻。还惊海上燃犀去，照水底、珊瑚如活。做弄得、酒醒天寒，空对一庭香雪。'},
    {t:'疏影·题宾月图',a:'张炎〔宋代〕',c:'雪空四野，照归心万里，千峰独涌。身与天游，一洗襟怀，海镜倒涌秋白。相逢懒问盈亏事，但桂桂、此情无极。是几番、飞盖追随，桂底露衣香湿。\n闲款楼台夜色。料水光未许，人世先得。影里分明，认得山河，一笑乱山横碧。乾坤许大须容我，浑忘了、醉乡犹客。待倩谁、招下清风，共结岁寒三益。'},
    {t:'疏影·咏荷叶',a:'张炎〔宋代〕',c:'碧圆自洁。向浅洲远渚，亭亭清绝。犹有遗簪，不展秋心，能卷几多炎热。鸳鸯密语同倾盖，且莫与、浣纱人说。恐怨歌、忽断花风，碎却翠云千叠。\n回首当年汉舞，怕飞去、谩皱留仙裙折。恋恋青衫，犹染枯香，还叹鬓丝飘雪。盘心清露如铅水，又一夜、西风吹折。喜静看、匹练秋光，倒泻半湖明月。'},
    {t:'蜀道难',a:'李白〔唐代〕',c:'噫吁嚱，危乎高哉！\n蜀道之难，难于上青天！\n蚕丛及鱼凫，开国何茫然！\n尔来四万八千岁，不与秦塞通人烟。\n西当太白有鸟道，可以横绝峨眉巅。\n地崩山摧壮士死，然后天梯石栈相钩连。\n上有六龙回日之高标，下有冲波逆折之回川。\n黄鹤之飞尚不得过，猿猱欲度愁攀援。\n青泥何盘盘，百步九折萦岩峦。\n扪参历井仰胁息，以手抚膺坐长叹。\n问君西游何时还？畏途巉岩不可攀。\n但见悲鸟号古木，雄飞雌从绕林间。\n又闻子规啼夜月，愁空山。\n蜀道之难，难于上青天，使人听此凋朱颜！\n连峰去天不盈尺，枯松倒挂倚绝壁。\n飞湍瀑流争喧豗，砯崖转石万壑雷。\n其险也如此，嗟尔远道之人胡为乎来哉！\n剑阁峥嵘而崔嵬，一夫当关，万夫莫开。\n所守或匪亲，化为狼与豺。\n朝避猛虎，夕避长蛇，磨牙吮血，杀人如麻。\n锦城虽云乐，不如早还家。\n蜀道之难，难于上青天，侧身西望长咨嗟！'},
    {t:'蜀国弦',a:'李贺〔唐代〕',c:'枫香晚花静，锦水南山影。\n惊石坠猿哀，竹云愁半岭。\n凉月生秋浦，玉沙粼粼光。\n谁家红泪客，不忍过瞿塘。'},
    {t:'蜀葵花歌',a:'岑参〔唐代〕',c:'昨日一花开，今日一花开。\n今日花正好，昨日花已老。\n始知人老不如花，可惜落花君莫扫。\n人生不得长少年，莫惜床头沽酒钱。\n请君有钱向酒家，君不见，蜀葵花。'},
    {t:'蜀犬吠日',a:'柳宗元〔唐代〕',c:'屈子赋曰：“邑犬群吠，吠所怪也。”仆往闻庸、蜀之南，恒雨少日，日出则犬吠，余以为过言。前六七年，仆来南，二年冬，幸大雪逾岭，被南越中数州。数州之犬，皆苍黄吠噬，狂走者累日，至无雪乃已，然后始信前所闻者。'},
    {t:'蜀桐',a:'李商隐〔唐代〕',c:'玉垒高桐拂玉绳，上含非雾下含冰。\n枉教紫凤无栖处，斫作秋琴弹坏陵。'},
    {t:'蜀先主庙',a:'刘禹锡〔唐代〕',c:'天地英雄气，千秋尚凛然。\n势分三足鼎，业复五铢钱。\n得相能开国，生儿不象贤。\n凄凉蜀故妓，来舞魏宫前。'},
    {t:'蜀相',a:'杜甫〔唐代〕',c:'丞相祠堂何处寻？锦官城外柏森森。\n映阶碧草自春色，隔叶黄鹂空好音。\n三顾频烦天下计，两朝开济老臣心。\n出师未捷身先死，长使英雄泪满襟。'},
    {t:'述酒',a:'陶渊明〔魏晋〕',c:'重离照南陆，鸣鸟声相闻；\n秋草渚未黄，融风久已分。\n素砾皛修渚，南岳无馀云。\n豫章抗高门，重司固灵坟。\n流泪抱中叹，倾耳听司晨。\n神州献嘉粟，西灵为我驯。\n诸梁董师旅，芊胜丧其身。\n山阳归下国，成名犹不勤。\n卜生善斯牧，安乐不为君。\n平王去旧京，峡中纳遗薰。\n双阳甫云育，三趾显奇文。\n王子爱清吹，日中翔河汾。\n朱公练九齿，闲居离世纷。\n峨峨西岭内，偃息常所亲。\n天容自永固，彭殇非等伦。'},
    {t:'述园鹿',a:'韦应物〔唐代〕',c:'野性本难畜，玩习亦逾年。麑班柳力直，麚角已苍然。\n仰首嚼园柳，俯身饮清泉。见人若闲暇，蹶起忽低骞。\n兹兽有高貌，凡类宁比肩。不得游山泽，跼促诚可怜。'},
    {t:'述祖德赠湖上诸沈',a:'皎然〔唐代〕',c:'我祖文章有盛名，千年海内重嘉声。雪飞梁苑操奇赋，\n春发池塘得佳句。世业相承及我身，风流自谓过时人。\n初看甲乙矜言语，对客偏能鸲鹆舞。饱用黄金无所求，\n长裾曳地干王侯。一朝金尽长裾裂，吾道不行计亦拙。\n岁晚高歌悲苦寒，空堂危坐百忧攒。昔时轩盖金陵下，\n何处不传沈与谢。绵绵芳籍至今闻，眷眷通宗有数君。\n谁见予心独飘泊，依山寄水似浮云。'},
    {t:'树中草',a:'李白〔唐代〕',c:'鸟衔野田草，误入枯桑里。\n客土植危根，逢春犹不死。\n草木虽无情，因依尚可生。\n如何同枝叶，各自有枯荣。'},
    {t:'数花风·别义兴诸友',a:'张炎〔宋代〕',c:'好游人老，秋鬓芦花共色。征衣犹恋去年客。古道依然黄叶。谁家萧瑟。自笑我、如何是得。\n酒楼仍在，流落天涯醉白。孤城寒树美人隔。烟水此程应远，须寻梅驿。又渐数、花风第一。'},
    {t:'衰荷',a:'白居易〔唐代〕',c:'白露凋花花不残，凉风吹叶叶初干。\n无人解爱萧条境，更绕衰丛一匝看。'},
    {t:'衰松',a:'孟郊〔唐代〕',c:'近世交道衰，青松落颜色。人心忌孤直，木性随改易。\n既摧栖日干，未展擎天力。终是君子材，还思君子识。'},
    {t:'双黄鹄歌送别',a:'王维〔唐代〕',c:'天路来兮双黄鹄，云忽飞兮水忽宿，抚翼和鸣整羽族。\n不得已，忽分飞，家在玉京朝紫微，主人宾水送将归。\n悲笳嘹唳垂舞衣，宾欲散兮复相依。\n几往返兮极浦，尚裴回兮落晖。\n岸忽火兮相迎，将夜入兮边城。\n鞍马归兮佳人散，怅离忧兮独含情。'},
    {t:'双井茶送子瞻',a:'黄庭坚〔宋代〕',c:'人间风日不到处，天上玉堂森斛书。\n想见东坡旧居士，挥毫百斛泻明珠。\n我家江南摘云腴，落硙霏霏雪不如。\n为公唤起黄州梦，独载扁舟向五湖。'},
    {t:'双六头赋送李参军',a:'高适〔唐代〕',c:'有物兮四方故城，六面砥平，白质黑文，花攒星明。\n主张尔手谈，决断尔心争，推得失似关乎天命，而消息乃用乎人情。\n若行之尤，思之精，虽邂逅而小比，必指掌而大亨。\n李侯李侯保令名，无怨败于垂成。明年傥有一掷分，君不先鸣谁先鸣？'},
    {t:'双声子·晚天萧索',a:'柳永〔宋代〕',c:'晚天萧索，断蓬踪迹，乘兴兰棹东游。三吴风景，姑苏台榭，牢落暮霭初收。夫差旧国，香径没、徒有荒丘。繁华处，悄无睹，惟闻麋鹿呦呦。\n想当年、空运筹决战，图王取霸无休。江山如画，云涛烟浪，翻输范蠡扁舟。验前经旧史，嗟漫哉、当日风流。斜阳暮草茫茫，尽成万古遗愁。'},
    {t:'双头莲·呈范至能待制',a:'陆游〔宋代〕',c:'华鬓星星，惊壮志成虚，此身如豪。萧条病骥。向暗里、消尽当年豪气。梦断故国山川，隔重重烟谁。身万里，旧社凋零，青门俊游谁记？\n尽道锦里繁华，叹官闲昼永，柴荆添睡。清愁自醉。念此际、付与何人心事。纵有楚柁吴樯，知何时东逝？空怅望，鲙美菰香，秋风又起。'},
    {t:'双头莲·双调',a:'周邦彦〔宋代〕',c:'一抹残霞，几行新雁，天染云断，红迷阵影，隐约望中，点破晚空澄碧。助秋色。门掩西风，桥横斜照，青翼未来，浓尘自起，咫尺凤帏，合有人相识。\n叹乖隔。知甚时恣与，同携欢适。度曲传觞，并鞯飞辔，绮陌画堂连夕。楼头千里，帐底三更，尽堪泪滴。怎生向，无聊但只听消息。'},
    {t:'双行缠其二',a:'佚名〔隋代〕',c:'新罗绣行缠，足趺如春妍。他人不言好，独我知可怜。'},
    {t:'双燕离',a:'李白〔唐代〕',c:'双燕复双燕，双飞令人羡。\n玉楼珠阁不独栖，金窗绣户长相见。\n柏梁失火去，因入吴王宫。\n吴宫又焚荡，雏尽巢亦空。\n憔悴一身在，孀雌忆故雄。\n双飞难再得，伤我寸心中。'},
    {t:'霜晴',a:'陆游〔宋代〕',c:'万瓦新霜白，一窗朝日晴。\n破裘身亦暖，细字眼犹明。\n耄喜谵谆语，衰常踸踔行。\n登封书不草，力穑报时平。'},
    {t:'霜天晓角·赤壁',a:'辛弃疾〔宋代〕',c:'雪堂迁客，不得文章力。赋写曹刘兴废，千古事、泯陈迹。\n望中矶岸赤，直下江涛白。半夜一声长啸，悲天地、为予窄。'},
    {t:'霜天晓角·旅兴',a:'辛弃疾〔宋代〕',c:'吴头楚尾，一棹人千里，休说旧倦新恨，长亭树，今如此。\n宦游吾倦矣，玉人留我醉，明日万花寒食，得且住，为佳耳。'},
    {t:'霜天晓角·重来对酒',a:'纳兰性德〔清代〕',c:'重来对酒，折尽风前柳。若问看花情绪，似当日、怎能彀。\n休为西风瘦，痛饮频搔首。自古青蝇白璧，天已早安排就。'},
    {t:'霜叶飞',a:'张炎〔宋代〕',c:'旧家池沼。寻芳处、从教飞燕频晓。一湾柳护水房春，看镜鸾窥晓。晕宿酒、双蛾淡扫。罗襦飘带朝围小。尽醉方归去，又暗约明朝斗草。谁解先到。\n心绪乱若晴丝，那回游处，坠红争恋残照。近来心事渐无多，尚被莺声恼。便白发、如今纵少。情怀不似前时好。谩伫立、东风外，愁极还醒，背花一笑。'},
    {t:'霜叶飞·露迷衰草',a:'周邦彦〔宋代〕',c:'露迷衰草。疏星挂，凉蟾低下林表。素蛾青女斗婵娟，正倍添凄悄。渐飒飒、丹枫撼晓。横天云浪鱼鳞小。似故人相看，又透入、清辉半晌，特地留照。\n迢递望极关山，波穿千里，度日如岁难到。凤楼今夜听秋风，奈五更愁抱。想玉匣、哀弦闭了。无心重理相思调。见皓月、牵离恨，屏掩孤颦，泪流多少。'},
    {t:'霜叶飞·毗陵客中闻老妓歌',a:'张炎〔宋代〕',c:'绣屏开了。惊诗梦、娇莺啼破春悄。隐将谱字转清圆，正杏梁声绕。看帖帖、蛾眉淡扫。不知能聚愁多少。叹客里凄凉，尚记得当年雅音，低唱还好。\n同是流落殊乡，相逢何晚，坐对真被花恼。贞元朝士已无多，但暮烟衰草。未忘得春风窈窕。却怜张绪如今老。且慰我留连意，莫说西湖，那时苏小。'},
    {t:'霜月',a:'李商隐〔唐代〕',c:'初闻征雁已无蝉，百尺楼高水接天。\n青女素娥俱耐冷，月中霜里斗婵娟。'},
    {t:'水',a:'张籍〔唐代〕',c:'荡漾空沙际，虚明入远天。\n秋光照不极，鸟色去无边。\n势引长云阔，波轻片雪连。\n汀洲杳难测，万古覆苍烟。'},
    {t:'水调歌头',a:'朱熹〔宋代〕',c:'不见严夫子，寂寞富春山。空馀千太危石，高插暮云端。想象羊裘披了，一笑两忘身世，来把钓鱼竿。不似林间翮，飞倦始知还。\n中兴主，功业就，鬓毛斑。驰驱一世豪杰，相与济时艰。独委狂奴心事，不羡痴儿鼎足，放去任疏顽。爽气动心斗，千古照林峦。'},
    {t:'水调歌头·安石在东海',a:'苏轼〔宋代〕',c:'余去岁在东武，作《水调歌头》以寄子由。今年子由相从彭门居百余日，过中秋而去，作此曲以别。余以其语过悲，乃为和之，其意以不早退为戒，以退而相从之乐为慰云耳。\n安石在东海，从事鬓惊秋。中年亲友难别，丝竹缓离愁。一旦功成名遂，准拟东还海道，扶病入西州。雅志困轩冕，遗恨寄沧洲。\n岁云暮，须早计，要褐裘。故乡归去千里，佳处辄迟留。我醉歌时君和，醉倒须君扶我，惟酒可忘忧。一任刘玄德，相对卧高楼。'},
    {t:'水调歌头·次袁仲机韵',a:'朱熹〔宋代〕',c:'长记与君别，丹凤九重城。归来知里，愁思怅望渺难平。今夕不知何夕，得共寒潭烟艇，一笑俯寻明。有酒径须醉，无事莫关情。\n寻梅去，疏竹外，一枝横。与君吟弄风月，端不负平生。何处车尘不到，有个江天如许，争肯换浮名。只恐买山隐，却要练丹成。'},
    {t:'水调歌头·多景楼',a:'陆游〔宋代〕',c:'江左占形胜，最数古徐州。连山风画，佳处缥缈著危楼。鼓角临风悲壮，烽火连空明灭，往事忆露刘。千里曜戈甲，万灶宿貔貅。\n露沾草，风落木，岁方秋。使君宏放，谈笑洗尽古今愁。不见襄阳登览，磨灭游人无数，遗恨黯难收。叔子独千载，名与汉江流。'},
    {t:'水调歌头·赋传岩叟悠然阁',a:'辛弃疾〔宋代〕',c:'岁岁有黄菊，千载一东篱。悠然山须两字，长笑退之诗。自古此山元有，何事当时才见，此意有回知。君起更斟酒，我醉不须辞。\n回首处，云正出，鸟倦飞。重来楼上，一句端的与君期。都把轩窗写遍，更使儿童诵得，归去来兮辞。万卷有时用，植杖且耘耔。'},
    {t:'水调歌头·富贵有馀乐',a:'朱熹〔宋代〕',c:'富贵有馀乐，贫贱不堪忧。谁知天路幽险，倚伏互相酬。请看东门黄犬，更听华亭清唳，千古恨难收。何似鸱夷子，散发弄扁舟。\n鸱夷子，成霸业，有馀谋。致身千乘卿相，归把钓渔钩。春昼五湖烟浪，秋夜一天云月，此外尽悠悠。永弃人间事，吾道付沧洲。'},
    {t:'水调歌头·和马叔度游月波楼',a:'辛弃疾〔宋代〕',c:'客子久不到，好景为君留。西楼着意吟赏，何必问更筹？唤起一天明月，照我满怀冰雪，浩荡百川流。鲸饮未吞海，剑气已横秋。\n野光浮，天宇迥，物华幽。中州遗恨，不知今夜几人愁？谁念英雄老矣？不道功名蕞尔，决策尚悠悠。此事费分说，来日且扶头！'},
    {t:'水调歌头·和赵景明知县韵',a:'辛弃疾〔宋代〕',c:'官事未易了，且向酒边来。君如无我，问君怀抱向谁开。但放平生丘壑，莫管旁人嘲骂，深蛰要惊雷。白发还自笑，何地置衰颓。\n五车书，千石饮，百篇才。新词未到，琼瑰先梦满吾怀。已过西风重九，且要黄花入手，诗兴未关梅。君要花满县，桃李趁时栽。'},
    {t:'水调歌头·和郑舜举蔗庵韵',a:'辛弃疾〔宋代〕',c:'万事到白发，日月几西东。羊肠九折歧路，老我惯经从。竹树前溪风月，鸡酒东家父老，一笑偶相逢。此乐竟谁觉，天外有冥鸿。\n味平生，公与我，定无同。玉堂金马，自有佳处著诗翁。好锁云烟窗户，怕入丹青图画，飞去了无踪。此语更痴绝，真有虎头风。'},
    {t:'水调歌头·黄州快哉亭赠张偓佺',a:'苏轼〔宋代〕',c:'落日绣帘卷，亭下水连空。知君为我新作，窗户湿青红。长记平山堂上，欹枕江南烟雨，杳杳没孤鸿。认得醉翁语，山色有无中。\n一千顷，都镜净，倒碧峰。忽然浪起，掀舞一叶白头翁。堪笑兰台公子，未解庄生天籁，刚道有雌雄。一点浩然气，千里快哉风。'},
    {t:'水调歌头·寄王信父',a:'张炎〔宋代〕',c:'白发已如此，岁序更骎骎。化机消息，庄生天籁雍门琴。颇笑论文说剑，休问高车驷马，衮衮□黄金。蚁在元无梦，水竞不流心。\n绝交书，招隐操，恶圆箴。世尘空扰，脱巾挂壁且松阴。谁对紫微阁下，我对白苹洲畔，朝市与山林。不用一钱买，风月短长吟。'},
    {t:'水调歌头·寄我五云字',a:'辛弃疾〔宋代〕',c:'严子文同傅安道和前韵，因再和谢之。\n寄我五云字，恰向酒边来。东风过尽归雁，不见客星回。闻道琐窗风月，更著诗翁杖履，合作雪堂猜。岁旱莫留客，霖雨要渠来。\n短灯檠，长剑铗，欲生苔。雕弓挂壁无用，照影落清杯。多病关心药裹，小摘亲鉏菜甲，老子政须哀。夜雨北窗竹，更倩野人栽。'},
    {t:'水调歌头·建炎庚戌题吴江',a:'佚名〔宋代〕',c:'平生太湖上，短棹几经过。如今中到，何事愁与水云多？拟把匣中长剑，换取扁舟一叶，归去老脍蓑。银艾非吾事，丘壑已蹉跎。\n脍新鲈，斟美酒，起悲歌。太平生长，岂谓今日识干戈。欲泻三江雪浪，净洗胡尘千里，不用挽天河。回首望霄汉，双泪堕清波！'},
    {t:'水调歌头·落日古城角',a:'辛弃疾〔宋代〕',c:'落日古城角，把酒劝君留。长安路远，何事风雪敝貂裘。散尽黄金身世，不管秦楼人怨，归计狎沙鸥。明夜扁舟去，和月载离愁。\n功名事，身未老，几时休。诗书万卷，致身须到古伊周。莫学班超投笔，纵得封侯万里，憔悴老边州。何处依刘客，寂寞赋登楼。'},
    {t:'水调歌头·落日塞垣路',a:'黄庭坚〔宋代〕',c:'落日塞垣路，风劲戛貂裘。翩翩沙骑闲猎，深入黑山头。极目平沙千里，惟见雕弓白羽，铁面骏汉骝。隐隐望青冢，特地起闲愁。\n汉天子，方鼎盛，四百州。玉颜皓齿，深锁三十六宫秋。堂有经纶贤相，边有纵横谋将，不减翠蛾羞。戎虏和乐也，圣主永无忧。'},
    {t:'水调歌头·盟鸥',a:'辛弃疾〔宋代〕',c:'带湖吾甚爱，千丈翠奁开。先生杖屦无事，一日走千回。凡我同盟鸥鹭，今日既盟之后，来往莫相猜。白鹤在何处，尝试与偕来。\n破青萍，排翠藻，立苍苔。窥鱼笑汝痴计，不解举吾杯。废沼荒丘畴昔，明月清风此夜，人世几欢哀。东岸绿阴少，杨柳更须栽。'},
    {t:'水调歌头·明月几时有',a:'苏轼〔宋代〕',c:'丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。\n明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。\n转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。'},
    {t:'水调歌头·昵昵儿女语',a:'苏轼〔宋代〕',c:'欧阳文忠公尝问余：“琴诗何者最善？”答以退之听颖师琴诗最善。公曰：此诗最奇丽，然非听琴，乃听琵琶也。余深然之。建安章质夫家善琵琶者，乞为歌词。余久不作，特取退之词，稍加隐括，使就声律，以遗之云。\n昵昵儿女语，灯火夜微明。恩怨尔汝来去，弹指泪和声。忽变轩昂勇士，一鼓填然作气，千里不留行。回首暮云远，飞絮搅青冥。\n众禽里，真彩凤，独不鸣。跻攀寸步千险，一落百寻轻。烦子指间风雨，置我肠中冰炭，起坐不能平。推手从归去，无泪与君倾。'},
    {t:'水调歌头·上古八千岁',a:'辛弃疾〔宋代〕',c:'上古八千岁，才是一春秋。不应此日，刚把七十寿君侯。看取垂天云翼，九万里风在下，与造物同游。君欲计岁月，当试问庄周。\n醉淋浪，歌窈窕，舞温柔。从今杖屦南涧，白日为君留。闻道钧天帝所，频上玉卮春酒，冠珮拥龙楼。快上星辰去，名姓动金瓯。'},
    {t:'水调歌头·寿赵漕介庵',a:'辛弃疾〔宋代〕',c:'千里渥洼种，名动帝王家。金銮当日奏草，落笔万龙蛇。带得无边春下，等待江山都老，教看鬓方鸦。莫管钱流地，且拟醉黄花。\n唤双成，歌弄玉，舞绿华。一觞为饮千岁，江海吸流霞。闻道清都帝所，要挽银河仙浪，西北洗胡沙。回首日边去，云里认飞车。'},
    {t:'水调歌头·送杨民瞻',a:'辛弃疾〔宋代〕',c:'日月如磨蚁，万事且浮休。君看檐外江水，滚滚自东流。风雨瓢泉夜半，花草雪楼春到，老子已菟裘。岁晚问无恙，归计橘千头。\n梦连环，歌弹铗，赋登楼。黄鸡白酒，君去村社一番秋。长剑倚天谁问，夷甫诸人堪笑，西北有神州。此事君自了，千古一扁舟。'},
    {t:'水调歌头·送郑厚卿赴衡州',a:'辛弃疾〔宋代〕',c:'寒食不小住，千骑拥春衫。衡阳石鼓城下，记我旧停骖。襟以潇湘桂岭，带以洞庭青草，紫盖屹西南。文字起《骚》《雅》，刀剑化耕蚕。\n看使君，於此事，定不凡。奋髯抵几堂上，尊俎自高谈。莫信君门万里，但使民歌《五袴》，归诏凤凰衔。君去我谁饮，明月影成三。'},
    {t:'水调歌头·汤坡见和用韵为谢',a:'辛弃疾〔宋代〕',c:'白日射金阙，虎豹九关开。见君谏疏频上，谈笑挽天回。千古忠肝义胆，万里蛮烟瘴雨，往事莫惊猜。政恐不免耳，消息日边来。\n笑吾庐，门掩草，径封苔。未应两手无用，要把蟹螯杯。说剑论诗余事，醉舞狂歌欲倒，老子颇堪哀。白发宁有种？一一醒时栽！'},
    {t:'水调歌头·题西山秋爽图',a:'纳兰性德〔清代〕',c:'空山梵呗静，水月影俱沉。悠然曾境人外，都不许尘侵。岁晚忆曾游处，犹记半竿斜照，曾抹界云林。绝顶茅庵里，老衲正孤吟。\n云中锡，溪头钓，涧边琴。此生著几两屐，谁识卧游心？准拟乘风归去，错向槐安回首，何日得投簪。布袜青鞋约，但向画图寻。'},
    {t:'水调歌头·我饮不须劝',a:'辛弃疾〔宋代〕',c:'淳熙丁酉，自江陵移帅隆兴，到官之三月被召，司马监、赵卿、王漕饯别。司马赋《水调歌头》，席间次韵。时王公明枢密薨，坐客终夕为兴门户之叹，故前章及之。\n我饮不须劝，正怕酒樽空。别离亦复何恨？此别恨匆匆。头上貂蝉贵客，苑外麒麟高冢，人世竟谁雄？一笑出门去，千里落花风。\n孙刘辈，能使我，不为公。余发种种如是，此事付渠侬。但觉平生湖海，除了醉吟风月，此外百无功。毫发皆帝力，更乞鉴湖东。'},
    {t:'水调歌头·我志在寥阔',a:'辛弃疾〔宋代〕',c:'赵昌父七月望日用东坡韵叙有白、东坡事见寄，过相褒借，且有秋水之约。八月十四日，余卧吴博山寺中，因用韵为谢，兼寄吴子似。\n我志在寥阔，畴昔梦登天。摩挲素月，人世俯仰已千年。有客骖鸾并凤，云遇青山赤壁，相约上高寒。酌酒援北斗，我亦虱其间。\n少歌曰：神甚放，形如眠。鸿鹄一再高举，天地睹方圆。欲重歌兮梦觉，推枕惘然独念，人事底亏全？有美人可语，秋水隔婵娟。'},
    {t:'水调歌头·隐括杜牧之齐山诗',a:'朱熹〔宋代〕',c:'江水浸云影，鸿雁欲南飞。携壶逢客何处？空翠渺烟霏。尘世难逢一笑，况有紫萸黄菊，堪插满酬归。风景今朝是，身世昔人非。\n酬佳节，须酩酊，莫相违。人生如寄，何事辛苦怨斜晖。无尽今来古往，多少春花秋月，那更有危机。与问牛山客，何必独沾衣。'},
    {t:'水调歌头·游览',a:'黄庭坚〔宋代〕',c:'瑶草一何碧，春入武陵溪。溪上桃花无数，枝上有黄鹂。我欲穿花寻路，直入白云深处，浩气展虹霓。只恐花深里，红露湿人衣。\n坐玉石，倚玉枕，拂金徽。谪仙何处？无人伴我白螺杯。我为灵芝仙草，不为朱唇丹脸，长啸亦何为？醉舞下山去，明月逐人归。'},
    {t:'水调歌头·再用韵答李子永',a:'辛弃疾〔宋代〕',c:'君莫赋幽愤，一语试相开。长安明马道上，平地起崔嵬。我愧渊明久矣，独借此翁湔洗，素壁写断来。斜日透虚隙，一线万飞埃。\n断吾生，左持蟹，右持杯。买山自种云树，山下劚烟莱。百炼都成绕指，万事直须称好，人世几舆台。刘郎更堪笑，刚赋看花回。'},
    {t:'水调歌头·舟次扬州和人韵',a:'辛弃疾〔宋代〕',c:'落日塞尘起，胡骑猎清秋。汉家组练十万，列舰耸层楼。谁道投鞭飞渡，忆昔鸣髇血污，风雨佛狸愁。季子正年少，匹马黑貂裘。\n今老矣，搔白首，过扬州。倦游欲去江上，手种橘千头。二客东南名胜，万卷诗书事业，尝试与君谋。莫射南山虎，直觅富民侯。'},
    {t:'水调歌头·醉吟',a:'辛弃疾〔宋代〕',c:'四座且勿语，听我醉中吟。池塘春草未歇，高树变鸣禽。鸿雁初飞江上，蟋蟀还来床下，时序百年心。谁要卿料理，山水有清音。\n欢多少，歌长短，酒浅深。而今已不如昔，后定不如今。闲处直须行乐，良夜更教秉烛，高会惜分阴。白发短如许，黄菊倩谁簪。'},
    {t:'水精数珠歌',a:'皎然〔唐代〕',c:'西方真人为行密，臂上记珠皎来日。佛名无著心亦空，\n珠去珠来体常一。谁道佛身千万身，重重只向心中出。'},
    {t:'水槛遣心二首',a:'杜甫〔唐代〕',c:'去郭轩楹敞，无村眺望赊。\n澄江平少岸，幽树晚多花。\n细雨鱼儿出，微风燕子斜。\n城中十万户，此地两三家。\n蜀天常夜雨，江槛已朝晴。\n叶润林塘密，衣干枕席清。\n不堪祗老病，何得尚浮名。\n浅把涓涓酒，深凭送此生。'},
    {t:'水口行舟',a:'朱熹〔宋代〕',c:'郁郁层恋隔岸青，青山绿水去无声。\n烟波一棹知何许，鶗鴂两山相对鸣。'},
    {t:'水口行舟二首',a:'朱熹〔宋代〕',c:'昨夜扁舟雨一蓑，满江风浪夜如何？\n今朝试卷孤篷看，依旧青山绿树多。\n郁郁层峦夹岸青，春山绿水去无声。\n烟波一棹知何许？鶗鴃两山相对鸣。'},
    {t:'水龙吟',a:'秦观〔宋代〕',c:'禁烟时候风和，越罗初试春衫薄。昼长深院，梦回孤枕，风吹铃索。绮陌花香，芳郊尘软，正堪游乐。倚阑干、瘦损无人问，重重绿树围朱阁。\n对镜时时泪落。总无心、淡妆浓抹。晨窗夜帐，几番误喜，灯花檐鹊。月下琼卮，花前金盏，与谁斟酌。望王孙、甚日归来，除是车轮生角。'},
    {t:'水龙吟·白莲',a:'张炎〔宋代〕',c:'仙人掌上芙蓉，涓涓犹滴金盘舞。轻装照水，纤裳玉立，飘飘似舞。几度销凝，满湖烟月，一汀鸥见。记小舟夜悄，波明香远，浑不见、花开处。\n应是浣纱人妒。褪红衣、被谁轻误？闲情淡雅，冶姿清润，凭娇待语。隔浦相逢，偶然倾盖，似传心素。怕湘皋佩解，绿云十里，卷西风去。'},
    {t:'水龙吟·春日游摩诃池',a:'陆游〔宋代〕',c:'摩诃池上追游路，红绿参差春晚。韶光妍媚，海棠如醉，桃花欲暖。挑菜初闲，禁烟将近，一城丝管。看金鞍争道，香车飞盖，争先占、新亭馆。\n惆怅年华暗换。点销魂、雨收云散。镜奁掩月，钗梁拆凤，秦筝斜雁。身在天涯，乱山孤垒，危楼飞观。叹春来只有，杨花和恨，向东风满。'},
    {t:'水龙吟·春晚留别故人',a:'张炎〔宋代〕',c:'乱红飞已无多，艳游终是如今老。一番雨过，一番春减，催人渐老。倚槛调莺，卷帘收燕，故园空似。奈关愁不住，悠悠万里，浑恰似、天涯草。\n不拟相逢古道。才疑梦、又还惊觉。清风在柳，江摇白浪，舟行趁晓。遮莫重来，不如休去，怎堪怀抱。那知又、五柳门荒，曾听得、鹃啼了。'},
    {t:'水龙吟·次韵章质夫杨花词',a:'苏轼〔宋代〕',c:'似花还似非花，也无人惜从教坠。抛家傍路，思量却是，无情有思。萦损柔肠，困酣娇眼，欲开还闭。梦随风万里，寻郎去处，又还被、莺呼起。\n不恨此花飞尽，恨西园、落红难缀。晓来雨过，遗踪何在？一池萍碎。春色三分，二分尘土，一分流水。细看来、不是杨花，点点是离人泪。'},
    {t:'水龙吟·登建康赏心亭',a:'辛弃疾〔宋代〕',c:'楚天千里清秋，水随天去秋无际。遥岑远目，献愁供恨，玉簪螺髻。落日楼头，断鸿声里，江南游子。把吴钩看了，栏杆拍遍，无人会，登临意。\n休说鲈鱼堪脍，尽西风，季鹰归未？求田问舍，怕应羞见，刘郎才气。可惜流年，忧愁风雨，树犹如此！倩何人唤取，红巾翠袖，揾英雄泪！'},
    {t:'水龙吟·古来云海茫茫',a:'苏轼〔宋代〕',c:'古来云海茫茫，道山绛阙知何翥。人间自有，赤城居士，龙蟠凤翥。清净无为，坐忘遗照，八篇奇驾。向玉霄东望，蓬莱晻霭，有云驾、骖风驭。\n行尽九州四海，笑纷纷、落花飞絮。临江一见，谪仙风采，无言心许。八表神游，浩然相对，酒酣箕踞。待垂天赋就，骑鲸路稳，约相将去。'},
    {t:'水龙吟·过南剑双溪楼',a:'辛弃疾〔宋代〕',c:'举头西北浮云，倚天万里须长焰。人言此地，夜深长见，斗牛光焰。我觉山高，潭空水冷，月明星怒。待燃犀下看，凭栏却怕，风雷怒，鱼龙惨。\n峡束苍江对起，过危楼，欲飞还敛。元龙老矣！不妨高卧，冰壶凉簟。千古兴亡，百年悲笑，一时登览。问何人又卸，片帆沙岸，系斜阳缆？'},
    {t:'水龙吟·寄袁竹初',a:'张炎〔宋代〕',c:'几番问竹平安，雁书不尽相思倚。篱根半树，村深孤艇，阑干屡倚。远草兼云，冻河胶雪，此时行渡。望去程无数，并州回首，还又渡、桑乾水。\n笑我曾游万里。甚匆匆、便成归计。江空岁晚，栖迟犹在，吴头楚尾。疏柳经寒，断槎浮月，依然憔悴。待相逢、说与相思，想亦在、相思里。'},
    {t:'水龙吟·甲辰岁寿韩南涧尚书',a:'辛弃疾〔宋代〕',c:'渡江天马南来，几人真是经纶旧。长安父老，新亭风景，可怜依旧。夷甫诸人，神州沉陆，几曾回事。算平戎万里，功名本是，真儒事、君知否。\n况有文章山斗。对桐阴、满庭清昼。当年堕地，而今试看，风云奔走。绿野风烟，平泉草木，东山歌酒。待他年，整顿乾坤事了，为先生寿。'},
    {t:'水龙吟·老来曾识渊明',a:'辛弃疾〔宋代〕',c:'老来曾识渊明，梦中一见参差止。觉来幽恨，停觞不御，欲歌还止。白发西风，折腰五斗，不应堪有。问北窗高卧，东篱自醉，应别有，归来意。\n须信有翁未死，到如今凛然生气。吾侪心事，古今长在，高山流水。富贵他年，直饶未免，也应无味。甚东山何事，当时也道，为苍生起。'},
    {t:'水龙吟·梨花',a:'周邦彦〔宋代〕',c:'素肌应怯余寒，艳阳占立青芜避。樊川照日，灵关遮路，残红敛避。传火楼台，妒花风雨，长门深引。亚帘栊半湿，一枝在手，偏勾引、黄昏泪。\n别有风前月底。布繁英、满园歌吹。朱铅退尽，潘妃却酒，昭君乍起。雪浪翻空，粉裳缟夜，不成春意。恨玉容不见，琼英谩好，与何人比。'},
    {t:'水龙吟·露寒烟冷蒹葭老',a:'苏轼〔宋代〕',c:'露寒烟冷蒹葭老，天外征鸿寥唳。银河秋晚，长门灯悄，一声初至。应念潇湘，岸遥人静，水多菰米。乍望极平田，徘徊欲下，依前被、风惊起。\n须信衡阳万里，有谁家、锦书遥寄。万重云外，斜行横阵，才疏又缀。仙掌月明，石头城下，影摇寒水。念征衣未捣，佳人拂杵，有盈盈泪。'},
    {t:'水龙吟·题瓢泉',a:'辛弃疾〔宋代〕',c:'稼轩何必长贫，放泉檐外琼珠泻。乐天知命，古来谁会，行藏用舍。人不堪忧，一瓢自乐，贤哉回也。料当年曾问，饭蔬饮水，何为是、栖栖者。\n且对浮云山上，莫匆匆、去流山下。苍颜照影，故应流落，轻裘肥马。绕齿冰霜，满怀芳乳，先生饮罢。笑挂瓢风树，一鸣渠碎，问何如哑。'},
    {t:'水龙吟·题文姬图',a:'纳兰性德〔清代〕',c:'须知名士倾城，一般易到伤心处。柯亭响绝，四弦才断，恶风吹去。万里他乡，非生非死，此身良苦。对黄沙白草，呜呜卷叶，平生恨、从头谱。\n应是瑶台伴侣，只多了、毡裘夫妇。严寒觱篥，几行乡泪，应声如雨。尺幅重披，玉颜千载，依然无主。怪人间厚福，天公尽付，痴儿騃女。'},
    {t:'水龙吟·听兮清佩琼瑶些',a:'辛弃疾〔宋代〕',c:'用“些语”再题瓢泉，歌以饮客，声韵甚谐，客皆为之釂。\n听兮清佩琼瑶些。明兮镜秋毫些。君无去此，流昏涨腻，生蓬蒿些。虎豹甘人，渴而饮汝，宁猿猱些。大而流江海，覆舟如芥，君无助、狂涛些。\n路险兮山高些。块予独处无聊些。冬槽春盎，归来为我，制松醪些。其外芳芬，团龙片凤，煮云膏些。古人兮既往，嗟予之乐，乐箪瓢些。'},
    {t:'水龙吟·昔时曾有佳人',a:'辛弃疾〔宋代〕',c:'昔时曾有佳人，翩然绝世而独国。未论一顾倾城，再顾又倾人国。宁不知其，倾城倾国，佳人难下。看行云行雨，朝朝暮暮，阳台下、襄王侧。\n堂上更阑烛灭。记主人、留髡送客。合尊促坐，罗襦襟解，微闻芗泽。当此之时，止乎礼义，不淫其色。但啜其泣矣，啜其泣矣，又何嗟及。'},
    {t:'水龙吟·小沟东接长江',a:'苏轼〔宋代〕',c:'小沟东接长江，柳堤苇岸连云市。烟村潇洒，人闲一哄，渔樵早市。永昼端居，寸阴虚度，了成何恋。但丝莼玉藕，珠粳锦鲤，相留恋，又经岁。\n因念浮丘旧侣，惯瑶池、羽觞沈醉。青鸾歌舞，铢衣摇曳，壶中天地。飘堕人间，步虚声断，露寒风细。抱素琴，独向银蟾影里，此怀难寄。'},
    {t:'水龙吟·小楼连远横空',a:'秦观〔宋代〕',c:'小楼连远横空，下窥绣毂雕鞍候。朱帘半卷，单衣初试，清明时候。破暖轻风，弄晴微雨，欲无还阵。卖花声过尽，斜阳院落；红成阵，飞鸳甃。\n玉佩丁东别后。怅佳期、参差难又。名韁利锁，天还知道，和天也瘦。花下重门，柳边深巷，不堪回首。念多情、但阵当时皓月，向人依旧。'},
    {t:'水龙吟·小楼连苑横空',a:'秦观〔宋代〕',c:'小楼连苑横空，下窥绣毂雕鞍候。朱帘半卷，单衣初试，清明时候。破暖轻风，弄晴微雨，欲无还阵。卖花声过尽，斜阳院落；红成阵，飞鸳甃。\n玉佩丁东别后。怅佳期、参差难又。名韁利锁，天还知道，和天也瘦。花下重门，柳边深巷，不堪回首。念多情、但阵当时皓月，向人依旧。'},
    {t:'水龙吟·再送荪友南还',a:'纳兰性德〔清代〕',c:'人生南北真如梦，但卧金山高暮。白波东逝，鸟啼花落，任他日暮。别酒盈觞，一声将息，送君归首。便烟波万顷，半帆残月，几回首，相思苦。\n可忆柴门深闭，玉绳低、翦灯夜雨。浮生如此，别多会少，不如莫遇。愁对西轩，荔墙叶暗，黄昏风雨。更那堪几暮，金戈铁马，把凄凉助。'},
    {t:'水龙吟·载学士院有之',a:'辛弃疾〔宋代〕',c:'倚栏看碧成朱，等闲褪了香袍粉。上林高选，匆匆又换，紫云衣润。几许春风，朝薰暮染，为花忙损。笑旧家桃李，东涂西抹，有多少、凄凉恨。\n拟倩流莺说与，记荣华、易消难整。人间得意，千红百紫，转头春尽。白发怜君，儒冠曾误，平生官冷。算风流未减，年年醉里，把花枝问。'},
    {t:'水龙吟·赠赵晦之吹笛侍儿',a:'苏轼〔宋代〕',c:'楚山修竹如云，异材秀出千林表。龙须半翦，凤膺微涨，玉肌匀绕。木落淮南，雨晴云梦，月明风袅。自中郎不见，桓伊去后，知孤负、秋多少。\n闻道岭南太守，后堂深、绿珠娇小。绮窗学弄，梁州初遍，霓裳未了。嚼徵含宫，泛商流羽，一声云杪。为使君洗尽，蛮风瘴雨，作霜天晓。'},
    {t:'水龙吟越调梨花',a:'周邦彦〔宋代〕',c:'素肌应怯馀寒，艳阳占立青芜避。樊川照日，灵关遮路，残红敛避。\n传火楼台，妒花风雨，长门深引。亚帘栊半湿，一枝在手，偏勾引、黄昏泪。\n别有风前月底。布繁英、满园歌吹。朱铅退尽，潘妃却酒，昭君乍起。\n雪浪翻空，粉裳缟夜，不成春意。恨玉容不见，琼英谩好，与何人比。'},
    {t:'水上寄乐天',a:'元稹〔唐代〕',c:'眼前明月水，先入汉江流。\n汉水流江海，西江过庾楼。\n庾楼今夜月，君岂在楼头。\n万一楼头望，还应望我愁。'},
    {t:'水仙花四首',a:'杨万里〔宋代〕',c:'江妃虚却蕊珠宫，银汉仙人谪此中。\n偶趁月明波上戏，一身冰雪舞春风。\n韵绝香仍绝，花清月未清。\n天仙不行地，且借水为名。\n额间拂煞御袍黄，衣上偷将月姊香。\n待倩春风作媒却，西湖嫁与水仙王。\n薤叶葱根两不差，重蕤风味独清嘉。\n薄揉肪玉围金钿，浅染鹅黄剩素纱。\n台盏元非千叶种，丰容要是小莲花。\n向来山谷相看日，知是它家是当家。'},
    {t:'水仙花四首其四',a:'杨万里〔宋代〕',c:'开处谁为伴，萧然不可亲。雪宫孤弄影，水殿四无人。'},
    {t:'水仙谣',a:'温庭筠〔唐代〕',c:'水客夜骑红鲤鱼，赤鸾双鹤蓬瀛书。轻尘不起雨新霁，\n万里孤光含碧虚。露魄冠轻见云发，寒丝七炷香泉咽。\n夜深天碧乱山姿，光碎平波满船月。'},
    {t:'水斋',a:'李商隐〔唐代〕',c:'多病欣依有道邦，南塘宴起想秋江。\n卷帘飞燕还拂水，开户暗虫犹打窗。\n更阅前题已披卷，仍斟昨夜未开缸。\n谁人为报故交道，莫惜鲤鱼时一双。'},
    {t:'睡觉',a:'杨万里〔宋代〕',c:'小醉如无酒，寒宵似度年。\n觉来因记梦，醒去不成眠。\n万事从心下，三更到眼前。\n清愁政无那，一鴈叫霜天。'},
    {t:'睡鸭',a:'黄庭坚〔宋代〕',c:'山鸡照影空自爱，孤鸾舞镜不作双。\n天下真成长会合，两凫相倚睡秋江。'},
    {t:'睡足轩二首',a:'秦观〔宋代〕',c:'数椽空屋枕清流，一榻萧然散百忧。\n终日掩关尘境谢，有时开卷古人游。\n鸣鸠去後沧浪晚，飞雨来初菡萏秋。\n此处便令君睡足，何须云梦泽南州。'},
    {t:'睡足轩二首·其二',a:'秦观〔宋代〕',c:'长年忧患百端慵，开斥僧坊颇有功。\n地撤蔽亏僧界净，人除荒秽玉奁空。\n青天并入挥毫里，白鸟时兴隐几中。\n最是人间佳绝处，梦残风铁响丁东。'},
    {t:'司马将军歌',a:'李白〔唐代〕',c:'狂风吹古月，窃弄章华台。\n北落明星动光彩，南征猛将如云雷。\n手中电曳倚天剑，直斩长鲸海水开。\n我见楼船壮心目，颇似龙骧下三蜀。\n扬兵习战张虎旗，江中白浪如银屋。\n身居玉帐临河魁，紫髯若戟冠崔嵬，\n细柳开营揖天子，始知灞上为婴孩。\n羌笛横吹阿亸回，向月楼中吹落梅。\n将军自起舞长剑，壮士呼声动九垓。\n功成献凯见明主，丹青画像麒麟台。'},
    {t:'司马迁',a:'秦观〔宋代〕',c:'子长少不羁，发轫遍丘壑。\n晚遭光陵祸，愤悱思远托。\n高辞振幽光，直笔诛隐恶。\n驰骋数千载，贯金百家作。\n至今青简上，文彩炳金雘。\n高才忽小疵，难用常情度。\n譬彼海运鹏，岂复顾缯缴。\n区区班叔皮，未易议疏略。'},
    {t:'司马迁',a:'王安石〔宋代〕',c:'孔鸾负文章，不忍留枳棘。\n嗟子刀锯间，悠然止而食。\n成书与後世，愤悱聊自释。\n领略非一家，高辞殆天得。\n虽微樊父明，不失孟子直。\n彼欺以自私，岂啻相十百。'},
    {t:'司马相如琴台',a:'岑参〔唐代〕',c:'相如琴台古，人去台亦空。台上寒萧条，至今多悲风。\n荒台汉时月，色与旧时同。'},
    {t:'司中司命五首',a:'佚名〔隋代〕',c:'云兮飘飘，风兮稜稜。\n飚驭返空，杲日来升。\n归旎扬扬，众乐锵锵。\n我神式欢，惠我嘉祥。'},
    {t:'思黯南墅赏牡丹',a:'刘禹锡〔唐代〕',c:'偶然相遇人间世，合在增城阿姥家。\n有此倾城好颜色，天教晚发赛诸花。'},
    {t:'思边',a:'李白〔唐代〕',c:'去年何时君别妾？南园绿草飞蝴蝶。\n今岁何时妾忆君，西山白雪暗秦云。\n玉关去此三千里，欲寄音书那可闻？'},
    {t:'思帝乡·花花',a:'温庭筠〔唐代〕',c:'花花，满枝红似霞。罗袖画帘肠断，卓香车。回面共人闲语，战篦金凤斜。惟有阮郎春尽，不归家。'},
    {t:'思故乡第一百五十六',a:'文天祥〔宋代〕',c:'天地西江远，无家问死生。\n凉风起天末，万里故乡情。'},
    {t:'思归乐·天幕清和堪宴聚',a:'柳永〔宋代〕',c:'天幕清和堪宴聚。想得尽、高阳醉侣。皓齿善歌长袖舞。渐引入、醉乡深处。\n晚岁光阴能几许。这巧宦、不须多取。共君把酒听杜宇。解再三、劝人归去。'},
    {t:'思佳客·题周草窗武林旧事',a:'张炎〔宋代〕',c:'梦里瞢腾说梦华。莺莺燕燕已天涯。蕉中覆处应无鹿，汉上从来不见花。\n今古事，古今嗟。西湖流水响琵琶。铜驼烟雨栖芳草，休向江南问故家。'},
    {t:'思江南旧游',a:'张籍〔唐代〕',c:'江皋三月时，花发石楠枝。归客应无数，春山自不知。\n独行愁道远，回信畏家移。杨柳东西渡，茫茫欲问谁。'},
    {t:'思夔州二首·其一',a:'陆游〔宋代〕',c:'老来百念尽消磨，无奈云安入梦何。\n壮忆公孙剑器舞，愁思宾客竹枝歌。'},
    {t:'思蒲塘',a:'文天祥〔宋代〕',c:'扬旌来冉冉，卷旆去堂堂。\n恨我飞无翼，思君济有航。\n麒麟还共处，熊虎已何乡。\n南国应无恙，中兴事会长。'},
    {t:'思亲汝州作',a:'黄庭坚〔宋代〕',c:'岁晚寒侵游子衣，拘留幕府报官移。\n五更归梦三百里，一日思亲十二时。\n车上吐茵元不逐，市中有虎竟成疑。\n秋毫得失关何事，总为平安书到迟。'},
    {t:'思王逢原三首·其二',a:'王安石〔宋代〕',c:'蓬蒿今日想纷披，冢上秋风又有吹。\n妙质不为平世得，微言惟有故人知。\n庐山南堕当书案，湓水东来入酒卮。\n陈迹可怜随手尽，欲欢无复似当时。'},
    {t:'思王逢原三首·其三',a:'王安石〔宋代〕',c:'百年相望济时功，岁路何知向没穷。\n鹰隼奋飞凰羽短，骐驎埋没马群空。\n中郎旧业无儿付，康子高才有妇同。\n想见江南原上墓，树枝零落纸钱风。'},
    {t:'思王逢原三首·其一',a:'王安石〔宋代〕',c:'布衣阡陌动成群，卓荦高才独见君。\n杞梓豫章蟠绝壑，骐驎騕褭跨浮云。\n行藏已许终身共，生死那知半路分。\n便恐世间无妙质，鼻端从此罢挥斤。'},
    {t:'思远人',a:'张籍〔唐代〕',c:'野桥春水清，桥上送君行。\n去去人应老，年年草自生。\n出门看远道，无信向边城。\n杨柳别离处，秋蝉今复鸣。'},
    {t:'思远人·红叶黄花秋意晚',a:'晏几道〔宋代〕',c:'红叶黄花秋意晚，千里念行客。得云过尽，归鸿无信，何处寄书得。\n泪弹不尽临窗滴，就砚旋研墨。渐写到别来，此情深处，红笺为无色。'},
    {t:'巳上人茅斋',a:'杜甫〔唐代〕',c:'巳公茅屋下，可以赋新诗。\n枕簟入林僻，茶瓜留客迟。\n江莲摇白羽，天棘蔓青丝。\n空忝许询辈，难酬支遁词。'},
    {t:'四和香·麦浪翻晴风飐柳',a:'纳兰性德〔清代〕',c:'麦浪翻晴风飐柳，已过伤春候。因甚为他成僝僽？毕竟是春迤逗。\n红药阑边携素手，暖语浓于酒。盼到园花铺似绣，却更比春前瘦。'},
    {t:'四绝',a:'秦观〔宋代〕',c:'天风吹月入栏干，乌鹊无声子夜阑。\n织女明星来枕上，了知身不在人间。'},
    {t:'四民诗其二·农',a:'范仲淹〔宋代〕',c:'圣人作耒耜，苍苍民乃粒。\n国俗俭且淳，人足而家给。\n九载襄陵祸，比户犹安辑。\n何人变清风，骄奢日相袭。\n制度非唐虞，赋敛由呼吸。\n伤哉田桑人，常悲大弦急。\n一夫耕几垅，游堕如云集。\n一蚕吐几丝，罗绮如山入。\n太平不自存，凶荒亦何及。\n神农与后稷，有灵应为泣。'},
    {t:'四民诗其三·工',a:'范仲淹〔宋代〕',c:'先生教百工，作为天下器。\n周旦人不配刊之考工记。\n嗟嗟远圣人，製度日以纷。\n窈窕阿房宫，万肯横青云。\n荧煌甲乙帐，一朝那肯焚。\n秦汉骄心起，陈隋益其侈。\n鼓舞天下风，滔滔弗能止。\n可甚佛老徒，不取慈俭书。\n竭我百家产，崇乐一室居。\n四海竞如此，金碧照万里。\n茅茨帝者荣，今为庶为耻。\n宜哉老成言，欲攦般轮指。'},
    {t:'四民诗其三工',a:'范仲淹〔宋代〕',c:'先王教百工，作为天下器。周旦人不朽，刊之考工记。\n嗟嗟远圣人，制度日以纷。窈窕阿房宫，万肯横青云。\n荧煌甲乙帐，一朝那肯焚。秦汉骄心起，陈隋益其侈。\n鼓舞天下风，滔滔弗能止。可甚佛老徒，不取慈俭书。\n竭我百家产，崇尔一室居。四海竞如此，金碧照万里。\n茅茨帝者荣，今为庶人耻。宜哉老成言，欲攦般输指。'},
    {t:'四拍',a:'文天祥〔宋代〕',c:'黄河北岸海西军，翻身向天仰射云。\n胡马长鸣不知数，衣冠南渡多崩奔。\n山木惨惨天欲雨，前有毒蛇后猛虎。\n欲问长安无使来，终日戚戚忍羁旅。'},
    {t:'四园竹·浮云护月',a:'周邦彦〔宋代〕',c:'浮云护月，未放满朱扉。鼠摇暗壁，萤度破窗，偷入书帏。秋意浓，闲伫立，庭柯影里。好风襟袖先知。\n夜何其。江南路绕重山，心知漫与前期。奈向灯前堕泪，肠断萧娘，旧日书辞犹在纸。雁信绝，清宵梦又稀。'},
    {t:'四月八日',a:'文天祥〔宋代〕',c:'今朝浴佛旧风流，身落山前第一州。\n赣上瑶桃俄五稔，海中玉果已三周。\n人生聚散真成梦，世事悲欢一转头。\n坐对薰风开口笑，满怀耿耿复何求。'},
    {t:'四月中休日闻蝉',a:'杨万里〔宋代〕',c:'荔枝叶底暑阴清，已有新蝉一两声。\n荷露柳风餐未饱，怪来学语不分明。'},
    {t:'四字令',a:'张炎〔宋代〕',c:'莺吟翠屏。帘吹絮云。东风也怕花瞋。带飞花赶春。\n邻娃笑迎。嬉游趁晴。明朝何处相寻。那人家柳阴。'},
    {t:'寺居独夜寄崔主簿',a:'韦应物〔唐代〕',c:'幽人寂不寐，木叶纷纷落。\n寒雨暗深更，流萤度高阁。\n坐使青灯晓，还伤夏衣薄。\n宁知岁方晏，离居更萧索。'},
    {t:'寺宿斋',a:'张籍〔唐代〕',c:'晚到金光门外寺，寺中新竹隔帘多。\n斋官禁与僧相见，院院开门不得过。'},
    {t:'泗水行',a:'张籍〔唐代〕',c:'泗水流急石纂纂，鲤鱼上下红尾短。春冰销散日华满，\n行舟往来浮桥断。城边鱼市人早行，水烟漠漠多棹声。'},
    {t:'泗州东城晚望',a:'秦观〔宋代〕',c:'渺渺孤城白水环，舳舻人语夕霏间。\n林梢一抹青如画，应是淮流转处山。'},
    {t:'松间',a:'王安石〔宋代〕',c:'偶向松间觅旧题，野人休诵北山移。\n丈夫出处非无意，猿鹤从来不自知。'},
    {t:'松江',a:'王安石〔宋代〕',c:'宛宛虹霓堕半空，银河直与此相通。\n五更缥缈千山月，万里凄凉一笛风。\n鸥鹭稍回青霭外，汀洲时起绿芜中。\n骚人自欲留坐句，忽忆君诗思已穷。'},
    {t:'松江鲈鱼',a:'杨万里〔宋代〕',c:'鲈出鲈乡芦叶前，垂虹亭上不梭钱。买来玉尺如何短，铸出银梭直是圆。\n白质黑章三四点，细鳞巨口一双鲜。秋风想见真风味，祗是春风已迥然。'},
    {t:'松树',a:'元稹〔唐代〕',c:'华山高幢幢，上有高高松。\n株株遥各各，叶叶相重重。\n槐树夹道植，枝叶俱冥蒙。\n既无贞直干，复有罥挂虫。\n何不种松树，使之摇清风。\n秦时已曾种，憔悴种不供。\n可怜孤松意，不与槐树同。\n闲在高山顶，樛盘虬与龙。\n屈为大厦栋，庇荫侯与公。\n不肯作行伍，俱在尘土中。'},
    {t:'松滋渡望峡中',a:'刘禹锡〔唐代〕',c:'渡头轻雨洒寒梅，云际溶溶雪黑来。\n梦渚草长迷楚望，夷陵土黑有秦灰。\n巴人泪应猿声落，蜀客船从鸟道回。\n十二碧峰何处所，永安宫外是荒台。'},
    {t:'嵩少',a:'孟郊〔唐代〕',c:'沙弥舞袈裟，走向踯躅飞。闲步喉惺惺，芳援相依依。\n噎塞春咽喉，蜂蝶事光辉。群嬉且已晚，孤引将何归。\n流艳去不息，朝英喉疏微。'},
    {t:'宋玉',a:'李商隐〔唐代〕',c:'何事荆台百万家，惟教宋玉擅曾华。\n楚辞已不饶唐勒，风赋何曾让景差。\n落日渚宫供观阁，开年云梦送烟花。\n可怜庾信寻荒径，犹得三朝托后车。'},
    {t:'宋中别李八',a:'高适〔唐代〕',c:'岁晏谁不归，君归意可说。将趋亭门望，还念同人别。\n驻马临长亭，飘然事明发。苍茫眺千里，正值苦寒节。\n旧国多转蓬，平台下明月。世情薄疵贱，夫子怀贤哲。\n行矣各勉旃，吾当挹馀烈。'},
    {t:'宋中别司功叔，各赋一物得商丘',a:'高适〔唐代〕',c:'商丘试一望，隐隐带秋天。地与辰星在，城将大路迁。\n干戈悲昔事，墟落对穷年。即此伤离绪，凄凄赋酒筵。'},
    {t:'宋中别周、梁、李三子',a:'高适〔唐代〕',c:'曾是不得意，适来兼别离。如何一尊酒，翻作满堂悲。\n周子负高价，梁生多逸词。周旋梁宋间，感激建安时。\n白雪正如此，青云无自疑。李侯怀英雄，肮脏乃天资。\n方寸且无间，衣冠当在斯。俱为千里游，忽念两乡辞。\n且见壮心在，莫嗟携手迟。凉风吹北原，落日满西陂。\n露下草初白，天长云屡滋。我心不可问，君去定何之。\n京洛多知己，谁能忆左思。'},
    {t:'宋中十首其八',a:'高适〔唐代〕',c:'五霸递征伐，宋人无战功。解围幸奇说，易子伤吾衷。\n唯见卢门外，萧条多转蓬。'},
    {t:'宋中遇陈二',a:'高适〔唐代〕',c:'常忝鲍叔义，所期王佐才。如何外苦节，独此无良媒。\n离别十年外，飘飖千里来。安知罢官后，惟南柴门开。\n穷巷隐东郭，高堂咏南陔。篱根长花草，井上生莓苔。\n伊昔望霄汉，于今倦蒿莱。男儿命未达，且尽手中杯。'},
    {t:'宋中遇刘书记有别',a:'高适〔唐代〕',c:'何代无秀士，高门生此才。森然调毛发，若见河山来。\n几载困常调，一朝时运催。白身谒明主，待蒿登云台。\n相逢梁宋间，与我醉蒿莱。寒楚眇千里，雪天昼不开。\n末路终离别，不能强悲哀。男儿争富贵，劝尔莫迟回。'},
    {t:'送安惇秀才失解西归',a:'苏轼〔宋代〕',c:'旧书不厌百回读，熟读深思子自知。\n他年名宦恐不免，今日栖迟那可追。\n我昔家居断还往，著书不复窥园葵。\n朅来东游慕人爵，弃去旧学从儿嬉。\n狂谋谬算百不遂，惟有霜鬓来如期。\n故山松柏皆手种，行且拱矣归何时。\n万事早知皆有命，十年浪走宁非痴。\n与君未可较得失，临别惟有长嗟咨。'},
    {t:'送白宾客分司东都',a:'张籍〔唐代〕',c:'赫赫声名三十春，高情人独出埃尘。病辞省闼归闲地，\n恩许宫曹作上宾。诗里难同相得伴，酒边多见自由身。\n老人也拟休官去，便是君家池上人。'},
    {t:'送白利从金吾董将军西征',a:'李白〔唐代〕',c:'西羌延国讨，白起佐军威。\n剑决浮云气，弓弯明月辉。\n马行边草绿，旌卷曙霜飞。\n抗手凛相顾，寒风生铁衣。'},
    {t:'送白少府送兵之陇右',a:'高适〔唐代〕',c:'践更登陇首，远别指临洮。\n为问关山事，何如州县劳。\n军容随赤羽，树色引青袍。\n谁断单于臂，今年太白高。'},
    {t:'送汴州监军俱文珍',a:'韩愈〔唐代〕',c:'奉使羌池静，临戎汴水安。\n冲天鹏翅阔，报国剑铓寒。\n晓日驱征骑，春风咏采兰。\n谁言臣子道，忠孝两全难。'},
    {t:'送辨聪上人还广陵',a:'皎然〔唐代〕',c:'莫学休公学远公，了心须与我心同。\n隋家古柳数株在，看取人间万事空。'},
    {t:'送别',a:'杜牧〔唐代〕',c:'溪边杨柳色参差，攀折年年赠别离。一片风帆望已极，\n三湘烟水返何时。多缘去棹将愁远，犹倚危亭欲下迟。\n莫殢酒杯闲过日，碧云深处是佳期。'},
    {t:'送别',a:'高适〔唐代〕',c:'昨夜离心正郁陶，三更白露西见高。\n萤飞木落何淅沥，此时梦见西归客。\n曙钟寥亮三四声，东邻嘶马使人惊。\n揽衣出户一相送，唯见归云纵复横。'},
    {t:'送别',a:'王维〔唐代〕',c:'下马饮君酒，问君何所之？\n君言不得意，归卧南山陲。\n但去莫复问，白云无尽时。'},
    {t:'送别',a:'佚名〔隋代〕',c:'杨柳青青着地垂，杨花漫漫搅天飞。\n柳条折尽花飞尽，借问行人归不归？'},
    {t:'送别',a:'王昌龄〔唐代〕',c:'春江愁送君，蕙草生氤氲。\n醉后不能语，乡山雨纷纷。'},
    {t:'送别出塞',a:'陈子昂〔唐代〕',c:'平生闻高义，书剑百夫雄。\n言登青云去，非此白头翁。\n胡兵屯塞下，汉骑属云中。\n君为白马将，腰佩騂角弓。\n单于不敢射，天子伫深功。\n蜀山余方隐，良会何时同。'},
    {t:'送别崔寅亮下第',a:'孟郊〔唐代〕',c:'天地唯一气，用之自偏颇。忧人成苦吟，达士为高歌。\n君子识不浅，桂枝忧更多。岁晏期攀折，时归且婆娑。\n素质如削玉，清词若倾河。虬龙未化时，鱼鳖同一波。\n去矣当自适，故乡饶薜萝。'},
    {t:'送别诗',a:'佚名〔隋代〕',c:'杨柳青青著地垂，杨花漫漫搅天飞。\n柳条折尽花飞尽，借问行人归不归？'},
    {t:'送兵到蓟北',a:'高适〔唐代〕',c:'积雪与天迥，屯军连塞愁。\n谁知此行迈，不为觅封侯。'},
    {t:'送禀上人游越',a:'皎然〔唐代〕',c:'云泉谁不赏，独见尔情高。投石轻龙窟，临流笑鹭涛。\n折荷为片席，洒水净方袍。剡路逢禅侣，多应问我曹。'},
    {t:'送渤海王子归本国',a:'温庭筠〔唐代〕',c:'疆理虽重海，车书本一家。\n盛勋归旧国，佳句在中华。\n定界分秋涨，开帆到曙霞。\n九门风月好，回首是天涯。'},
    {t:'送蔡山人',a:'高适〔唐代〕',c:'东山布衣明古今，自言独未逢然音。识者阅见一生事，\n到处豁然千里心。看书学剑长辛苦，近醒方思谒明主。\n斗酒相留醉复醒，悲歌数年泪如雨。丈夫遭遇不可然，\n买臣主父皆如斯。我今蹭蹬无所似，看尔崩腾何若为。'},
    {t:'送蔡山人',a:'李白〔唐代〕',c:'我本不弃世，世人自弃我。\n一乘无倪舟，八极纵远舵。\n燕客期跃马，唐生安敢讥。\n采珠勿惊龙，大道可暗归。\n故山有松月，迟尔玩清晖。'},
    {t:'送蔡少府赴登州推事',a:'高适〔唐代〕',c:'胶东连即墨，莱水入沧溟。国小常多事，人讹屡抵刑。\n公才征郡邑，诏使出郊坰。标格谁当犯，风谣信可听。\n峥嵘大岘口，逦迤汶阳亭。地迥云偏白，天秋山更青。\n祖筵方卜昼，王事急侵星。劝尔将为德，斯言盖有听。'},
    {t:'送蔡十二之海上·时在卫中',a:'高适〔唐代〕',c:'黯然何所为，相对但悲酸。季弟念离别，贤兄救急难。\n河流冰处尽，海路雪中寒。尚有南飞雁，知君不忍看。'},
    {t:'送参寥师',a:'苏轼〔宋代〕',c:'上人学苦空，百念已灰冷。\n剑头唯一吷，焦谷无新颖。\n胡为逐吾辈，文字争蔚炳？\n新诗如玉屑，出语便清警。\n退之论草书，万事未尝屏。\n忧愁不平气，一寓笔所骋。\n颇怪浮屠人，视身如丘井。\n颓然寄淡泊，谁与发豪猛？\n细思乃不然，真巧非幻影。\n欲令诗语妙，无厌空且静。\n静故了群动，空故纳万境。\n阅世走人间，观身卧云岭。\n咸酸杂众好，中有至味永。\n诗法不相妨，此语当更请。'},
    {t:'送曹璩归越中旧隐诗',a:'刘禹锡〔唐代〕',c:'行尽潇湘万里余，少逢知己忆吾庐。\n数间茅屋闲临水，一盏秋灯夜读书。\n地远何当随计吏，策成终自诣公车。\n剡中若问连州事，唯有千山画不如。'},
    {t:'送草书献上人归庐山',a:'孟郊〔唐代〕',c:'狂僧不为酒，狂笔自通天。\n将书云霞片，直至清明巅。\n手中飞黑电，象外泻玄泉。\n万物随指顾，三光为回旋。\n聚书云霮䨴，洗砚山晴鲜。\n忽怒画蛇虺，喷然生风烟。\n江人愿停笔，惊浪恐倾船。'},
    {t:'送柴侍御',a:'王昌龄〔唐代〕',c:'沅水通波接武冈，送君不觉有离伤。\n青山一道同云雨，明月何曾是两乡。'},
    {t:'送柴司户充刘卿判官之岭外',a:'高适〔唐代〕',c:'岭外资雄镇，朝端宠节旄。月卿阔幕府，星使出词曹。\n海对羊城阔，山连象郡高。风霜驱瘴疠，忠信涉波涛。\n别恨随流水，交情脱宝刀。有才无不适，行矣莫徒劳。'},
    {t:'送常侍御却使西蕃',a:'韦应物〔唐代〕',c:'归奏圣朝行万里，却衔天诏报马臣。\n本是诸生守文墨，今将匹马静烟尘。\n旅宿关河逢暮雨，春耕亭障识遗民。\n此去多应收故地，宁辞沙塞往来频。'},
    {t:'送陈环秀才游金陵',a:'范仲淹〔宋代〕',c:'君有江南行，为君歌以喜。\n龙盘山万曲，练静江千里。\n江山不可空，台星照吴中。\n古来王谢地，今有周召风。\n而间杨与郑，万丈光相映。\n煌煌聚宰府，金陵一何盛。\n此去知已贤，雅客情无边。\n白云起江树，明月逐江船。\n云月共徘徊，优哉如游仙。\n归来笑春风，白日登青天。'},
    {t:'送陈靖中舍归武陵',a:'王安石〔宋代〕',c:'知君欲上武陵溪，水自东流人自西。\n到日桃花应已谢，想君应不为花迷。'},
    {t:'送陈七赴西军',a:'孟浩然〔唐代〕',c:'吾观非常者，碌碌在目前。\n君负鸿鹄志，蹉跎书剑年。\n一闻边烽动，万里忽争先。\n余亦赴京国，何当献凯还。'},
    {t:'送陈太初道录',a:'秦观〔宋代〕',c:'先生簪绂後，世系本绵瓜。\n驻马生枯骨，回车济病蛇。\n带云眠酒市，和月醉渔家。\n落日千山路，西风一枕霞。\n几年流俗笑，一旦五侯夸。\n棋惜春深日，琴憎雨後蛙。\n背因书字曲，发为注经华。\n地转东淮水，天回北斗车。\n新宫黄道近，旧隐白云遐。\n顾我身多累，逢君意谩夸。\n空提方士剑，未上客星槎。\n何日同归去，重飞九转砂。'},
    {t:'送程六',a:'王昌龄〔唐代〕',c:'冬夜伤离在五溪，青鱼雪落鲙橙齑。\n武冈前路看斜月，片片舟中云向西。'},
    {t:'送储邕之武昌',a:'李白〔唐代〕',c:'黄鹤西楼月，长江万里情。\n春风别十度，空忆武昌城。\n送尔难为别，衔杯惜未倾。\n湖连张乐地，山逐泛舟行。\n诺为楚人重，诗传谢朓清。\n沧浪吾有曲，寄入棹歌声。'},
    {t:'送楚丘麹少府赴官',a:'岑参〔唐代〕',c:'青袍美少年，黄绶一神仙。\n微子城东面，梁王苑北边。\n桃花色似马，榆荚小于钱。\n单父闻相近，家书早为传。'},
    {t:'送褚校书归旧山歌',a:'韦应物〔唐代〕',c:'握珠不返泉，匣玉不归山。明皇方士亦如此，\n忽怪褚生何得还。方称羽猎赋，未拜兰台职。\n汉箧朝书已暗传，嵩丘遗简还能识。朝朝待诏青锁闱，\n中有万年之树蓬莱池。世人仰望栖此地，\n生独徘徊意何为。故山可往薇可采，一自人间星岁改。\n藏书壁中苔半侵，洗药泉中月还在。春风饮饯灞陵原，\n莫厌归来朝市喧。不见东方朔，避世从容金马门。'},
    {t:'送春',a:'王安石〔宋代〕',c:'武陵山下朝买船，风吹宿雾山花鲜。\n万家笑语横青天，绮窗罗暮舞婵娟。\n小鬟折花叩船舷，玉琖写酒酬金钱。\n朱梦飞动浮云巘，天外筦箫来宛转。\n断桥人行夕阳路，楼观琉璃影中见。\n酡颜未分骅骝催，烛人坐客犹徘徊。\n岂知阊阖门边住，春尽不见芳菲开。\n日月纷纷车走坂，少年意气何由挽。\n洞庭浪与天地白，尘昏万里东浮眼。\n黑貂裘敝归几时，相见绿树啼黄鹂。\n荣华俯仰忧患随，命驾吾与高人期。'},
    {t:'送春词',a:'刘禹锡〔唐代〕',c:'昨来楼上迎春处，今日登楼又送归。\n兰蕊残妆含露泣，柳条长袖向风挥。\n佳人对镜容颜改，楚客临江心事违。\n万古至今同此恨，无如一醉尽忘机。'},
    {t:'送从弟戴玄往苏州',a:'张籍〔唐代〕',c:'杨柳阊门路，悠悠水岸斜。乘舟向山寺，着屐到渔家。\n夜月红柑树，秋风白藕花。江天诗景好，回日莫令赊。'},
    {t:'送从弟濛赴饶州',a:'张籍〔唐代〕',c:'京城南去鄱阳远，风月悠悠别第劳。三领郡符新寄重，\n再登科第旧名高。去程江上多看堠，迎吏船中亦带刀。\n到日更行清静化，春田应不见蓬蒿。'},
    {t:'送从弟邕下第后寻会稽',a:'孟浩然〔唐代〕',c:'疾风吹征帆，倏尔向空没。\n千里在俄顷，三江坐超忽。\n向来共欢娱，日夕成楚越。\n落羽更分飞，谁能不惊骨。'},
    {t:'送崔参军往龙溪',a:'王昌龄〔唐代〕',c:'龙溪只在龙标上，秋月孤山两相向。\n谴谪离心是丈夫，鸿恩共待春江涨。'},
    {t:'送崔遏',a:'孟浩然〔唐代〕',c:'片玉来誇楚，治中作主人。江山增润色，词赋动阳春。\n别馆当虚敞，离情任吐伸。因声两京旧，谁念卧漳滨。'},
    {t:'送崔遏·易',a:'孟浩然〔唐代〕',c:'片玉来夸楚，治中作主人。\n江山增润色，词赋动阳春。\n别馆当虚敞，离情任吐伸。\n因声两京旧，谁念卧漳滨？'},
    {t:'送崔功曹赴越',a:'高适〔唐代〕',c:'传有东南别，题诗报客居。江山知不厌，州县复何如。\n莫恨吴歈曲，尝看越绝书。今朝欲乘兴，随尔食鲈鱼。'},
    {t:'送崔九兴宗游蜀',a:'王维〔唐代〕',c:'送君从此去，转觉故人稀。\n徒御犹回首，田园方掩扉。\n出门当旅食，中路授寒衣。\n江汉风流地，游人何岁归。'},
    {t:'送崔珏往西川',a:'李商隐〔唐代〕',c:'年少因何有旅愁，欲为东下更西游。\n一条雪浪吼巫峡，千里火云烧益州。\n卜肆至今多寂寞，酒垆从古擅风流。\n浣花笺纸桃花色，好好题诗咏玉钩。'},
    {t:'送崔郎中赴幕',a:'温庭筠〔唐代〕',c:'一别黔巫似断弦，故交东去更凄然。\n心游目送三千里，雨散云飞二十年。\n发迹岂劳天上桂，属词还得幕中莲。\n相思休话长安远，江月随人处处圆。'},
    {t:'送崔录事赴宣城',a:'高适〔唐代〕',c:'大国非不理，小官皆用才。欲行别城印，住饮洛阳杯。\n晚景为人别，长天无鸟回。举帆风波渺，倚棹江山来。\n羡尔兼乘兴，芜湖千里开。'},
    {t:'送崔全被放归都觐省',a:'岑参〔唐代〕',c:'夫子不自衍，世人知者稀。\n来倾阮氏酒，去著老莱衣。\n渭北草新出，关东花欲飞。\n楚王犹自惑，片玉且将归。'},
    {t:'送崔三往密州觐省',a:'王维〔唐代〕',c:'南陌去悠悠，东郊不少留。\n同怀扇枕恋，独念倚门愁。\n路绕天山雪，家临海树秋。\n鲁连功未报，且莫蹈沧洲。'},
    {t:'送崔爽之湖南',a:'孟郊〔唐代〕',c:'江与湖相通，二水洗高空。定知一日帆，使得千里风。\n雪唱与谁和，俗情多不通。何当逸翮纵，飞起泥沙中。'},
    {t:'送崔兴宗',a:'王维〔唐代〕',c:'已恨亲皆远，谁怜友复稀。君王未西顾，游宦尽东归。\n塞迥山河净，天长云树微。方同菊花节，相待洛阳扉。'},
    {t:'送崔员外入秦因访故园',a:'岑参〔唐代〕',c:'欲谒明光殿，先趋建礼门。仙郎去得意，亚相正承恩。\n竹里巴山道，花间汉水源。凭将两行泪，为访邵平园。'},
    {t:'送崔詹事论之上都·崔尝典吴兴',a:'皎然〔唐代〕',c:'金虎城池在，铜龙剑珮新。重看前浦柳，犹忆旧洲蘋。\n远思秦云暮，归心腊月春。青园昔游处，惆怅别离人。'},
    {t:'送崔子还京',a:'岑参〔唐代〕',c:'匹马西从天外归，扬鞭只共鸟争飞。\n送君九月交河北，雪里题诗泪满衣。'},
    {t:'送大宝上人归楚山',a:'皎然〔唐代〕',c:'厌上乌桥送别频，湖光烂熳望行人。欲将夜舸陪嘉月，\n肯住空林伴老身。独鹤翩翻飞不定，归云萧散会无因。\n从何得道怀惆怅，莫是人间屡见春。'},
    {t:'送丹霞子阮芳颜上人归山',a:'孟郊〔唐代〕',c:'松色不肯秋，玉性不可柔。登山须正路，饮水须直流。\n倩鹤附书信，索云作衣裘。仙村莫道远，枉策招交游。'},
    {t:'送单十三毕五归',a:'王昌龄〔唐代〕',c:'寒江绿竹楚云深，莫道离忧迁远心。\n晓夕双帆归鄂渚，愁将孤月梦中寻。'},
    {t:'送德轮行者',a:'杨万里〔宋代〕',c:'沥血抄经奈若何，十年依旧一头陀。\n袈裟未著愁多事，著了袈裟事更多。'},
    {t:'送狄宗亨',a:'王昌龄〔唐代〕',c:'秋在水清山暮蝉，洛阳树色鸣皋烟。\n送君归去愁不尽，又惜空度凉风天。'},
    {t:'送丁司理赴明州',a:'范仲淹〔宋代〕',c:'仙家枝叶令威孙，南去司刑庇越民。\n金阙道书微旨在，狱多阴德是真人。'},
    {t:'送东莱王学士无竞',a:'陈子昂〔唐代〕',c:'宝剑千金买，平生未许人。\n怀君万里别，持赠结交亲。\n孤松宜晚岁，众木爱芳春。\n已矣将何道，无令白首新。'},
    {t:'送东莱学士无竞',a:'陈子昂〔唐代〕',c:'宝剑千金买，生平未许人。\n怀君万里别，持赠送交亲。\n孤松宜晚岁，众木爱芳春。\n已矣将何道，无令白发新。'},
    {t:'送东林廉上人归庐山',a:'王昌龄〔唐代〕',c:'石溪流已乱，苔径人渐微。\n日暮东林下，山僧还独归。\n昔为庐峰意，况与远公违。\n道性深寂寞，世情多是非。\n会寻名山去，岂复望清辉。'},
    {t:'送董判官',a:'高适〔唐代〕',c:'逢君说行迈，倚剑别交亲。\n幕府为才子，将军作主人。\n近关多雨雪，出塞有风尘。\n长策须当用，男儿莫顾身。'},
    {t:'送董邵南游河北序',a:'韩愈〔唐代〕',c:'燕赵古称多感慨悲歌之士。董抱举进士，屡不得志于不司，怀抱利器，郁郁适兹土。吾知其必不合也。董抱勉乎哉！\n夫以子之不遇时，苟慕义强仁者，皆爱惜焉。矧燕赵之士出乎其性者哉！然吾尝闻风俗与化移易，吾恶知其今不异于古所云邪?聊以吾子之行卜之也。董抱勉乎哉！\n吾因子不所感矣。为我吊望诸君之墓，而观于其市，复不昔时屠狗者乎？为我谢曰：“明天子在上，可以出而仕矣。”'},
    {t:'送董信州',a:'晏殊〔宋代〕',c:'凤阙承丹诏，麟符得旧乡。\n雨中吴岫碧，林罅楚梅黄。\n使节江湖外，城楼翼轸旁。\n吾知召南树，從此接维桑。'},
    {t:'送豆卢策归别墅',a:'孟郊〔唐代〕',c:'短松鹤不巢，高石云不栖。君今地湘去，意与云鹤齐。\n力买奇险地，手开清浅溪。身披薜荔衣，山陟莓苔梯。\n一卷冰雪文，避俗常自携。'},
    {t:'送窦七',a:'王昌龄〔唐代〕',c:'清江月色傍林秋，波上荧荧望一舟。\n鄂渚轻帆须早发，江边明月为君留。'},
    {t:'送窦校书见饯得云中辨江树',a:'张九龄〔唐代〕',c:'江水天连色，无涯净野氛。微明岸傍树，凌乱渚前云。\n举棹形徐转，登舻意渐分。渺茫从此去，空复惜离群。'},
    {t:'送杜十四之江南',a:'孟浩然〔唐代〕',c:'荆吴相接水为乡，君去春江正淼茫。\n日暮征帆何处泊，天涯一望断人肠。'},
    {t:'送杜佐下第归陆浑别业',a:'岑参〔唐代〕',c:'正月今欲半，陆浑花未开。\n出关见青草，春色正东来。\n夫子且归去，明时方爱才。\n还须及秋赋，莫即隐嵩莱。'},
    {t:'送顿起',a:'苏轼〔宋代〕',c:'客路相逢难，为乐常不足。\n临行去衫袖，更尝折残菊。\n酒阑不忍去，共接一寸烛。\n留君终无穷，归前不免促。\n岱宗已在眼，一往继前躅。\n佳人亦何念，凄断阳关曲。\n天门四十里，夜看扶桑浴。\n回头望彭城，大海浮一粟。\n故人在其下，尘土相豗蹴。\n惟有黄楼诗，千古配淇澳。'},
    {t:'送二十二兄北游寻罗中',a:'岑参〔唐代〕',c:'斗柄欲东指，吾兄方北游。无媒谒明主，失计干诸侯。\n夜雪入穿履，朝霜凝敝裘。遥知客舍饮，醉里闻春鸠。'},
    {t:'送樊侍御使丹阳便觐',a:'岑参〔唐代〕',c:'卧病穷巷晚，忽惊骢马来。知君京口去，借问几时回。\n驿舫江风引，乡书海雁催。慈亲应倍喜，爱子在霜台。'},
    {t:'送范德孺知庆州',a:'黄庭坚〔宋代〕',c:'乃翁知国如知兵，塞垣草木识及名。\n敌人开户玩处女，掩耳节及惊雷霆。\n平生端有活国计，百节一试薶九京。\n阿兄两持庆州节，十年骐驎地上行。\n潭潭大度如卧虎，边头耕桑长儿女。\n折冲千里虽有余，论道经邦政要渠。\n妙年出补父兄处，公自才力应时须。\n春风旍旗拥万夫，幕下诸将思草枯。\n智名勇功节入眼，可用折箠笞羌胡。'},
    {t:'送方尊师归嵩山',a:'王维〔唐代〕',c:'仙官欲往九龙潭，旄节朱幡倚底龛。\n山压天中半天上，洞穿江底出江南。\n瀑布杉松常带雨，夕阳苍翠忽成岚。\n借问迎来双白鹤，已曾衡岳送苏耽。'},
    {t:'送防秋将',a:'张籍〔唐代〕',c:'白首征西将，犹能射戟支。元戎选部曲，军吏换旌旗。\n逐虏招降远，开边旧垒移。重收陇外地，应似汉家时。'},
    {t:'送汾城王主簿',a:'韦应物〔唐代〕',c:'少年初带印，汾上又经过。\n芳草归时遍，情人故郡多。\n禁钟春雨细，宫树野烟和。\n相望东桥别，微风起夕波。'},
    {t:'送丰都李尉',a:'李商隐〔唐代〕',c:'万古商於地，凭君泣路岐。\n固难寻绮季，可得信张仪。\n雨气燕先觉，叶阴蝉遽知。\n望乡尤忌晚，山晚更参差。'},
    {t:'送封太守',a:'王维〔唐代〕',c:'忽解羊头削，聊驰熊首轓。\n扬舲发夏口，按节向吴门。\n帆映丹阳郭，枫攒赤岸村。\n百城多候吏，露冕一何尊。'},
    {t:'送高三之桂林',a:'王昌龄〔唐代〕',c:'留君夜饮对潇湘，从此归舟客梦长。\n岭上梅花侵雪暗，归时还拂桂花香。'},
    {t:'送告八从军',a:'孟浩然〔唐代〕',c:'男儿一片气，何必五车书。\n好勇方过我，多才便起予。\n运筹将入幕，养拙就闲居。\n正待功名遂，从君继两疏。'},
    {t:'送关小师还金陵',a:'皎然〔唐代〕',c:'如何有归思，爱别欲忘难。白鹭沙洲晚，青龙水寺寒。\n蕉花铺净地，桂子落空坛。持此心为境，应堪月夜看。'},
    {t:'送广帅秩满之官丹阳二首',a:'杨万里〔宋代〕',c:'北门卧护要耆英，小试胸中十万兵。\n天借金山吟落月，身兼铁瓮作长城。\n何如岭上因归路，摘取梅酸去作羹。\n已有紫泥教诣阙，便应留住付钧衡。'},
    {t:'送广州周判官',a:'张九龄〔唐代〕',c:'海郡雄蛮落，津亭壮越台。城隅百雉映，水曲万家开。\n里树桄榔出，时禽翡翠来。观风犹未尽，早晚使车回。'},
    {t:'送桂阳孝廉',a:'高适〔唐代〕',c:'桂阳年少西入秦，数经甲科犹白身。\n即今江海一归客，他日云霄万里人。'},
    {t:'送桂州严大夫同用南字',a:'韩愈〔唐代〕',c:'苍苍森八桂，兹地在湘南。\n江作青罗带，山如碧玉篸。\n户多输翠羽，家自种黄甘。\n远胜登仙去，飞鸾不假骖。'},
    {t:'送郭处士往莱芜，兼寄苟山人',a:'高适〔唐代〕',c:'君为东蒙客，往来东蒙畔。云卧皆峄阳，山行穷日观。\n少年词赋皆可听，秀眉白面风清泠。身上今曾染名利，\n口中犹今知膻腥。今日还山意无极，岂辞世路多相识。\n归见莱芜九十翁，为论别后长相忆。'},
    {t:'送郭仆射节制剑南',a:'岑参〔唐代〕',c:'铁马擐红缨，幡旗出禁城。明王亲授钺，丞相欲专征。\n玉馔天厨送，金杯御酒倾。剑门乘嶮过，阁道踏空行。\n山鸟惊吹笛，江猿看洗兵。晓云随去阵，夜月逐行营。\n南仲今时往，西戎计日平。将心感知己，万里寄悬旌。'},
    {t:'送郭司仓',a:'王昌龄〔唐代〕',c:'映门淮水绿，留骑主人心。\n明月随良掾，春潮夜夜深。'},
    {t:'送郭乂杂言',a:'岑参〔唐代〕',c:'地上青草出，经冬今始归。博陵别近信，犹未换春衣。\n怜汝不忍别，送汝上酒楼。初行莫早发，且虚霸桥头。\n功名须及早，岁月莫虚掷。早年已工诗，近日兼注易。\n何时过东洛，早晚度盟津。朝歌城边柳亸地，\n邯郸道上花扑人。去年四月初，我正在河朔。\n曾上君家县北楼，楼上分明见恒岳。中山明府待君来，\n须计行程及早回。到家速觅长安使，待汝书封我自开。'},
    {t:'送国棋王逢',a:'杜牧〔唐代〕',c:'玉子纹楸一路饶，最宜檐雨竹来来。\n羸形暗去春泉长，拔势横来野火烧。\n守道还如周柱史，鏖兵不羡霍嫖姚。\n浮生七十更万日，与子期于局上销。'},
    {t:'送海南客归旧岛',a:'张籍〔唐代〕',c:'海上去应远，蛮家云岛孤。竹船来桂浦，山市卖鱼须。\n入国自献宝，逢人多赠珠。却归春洞口，斩象祭天吴。'},
    {t:'送韩渎殿院出守岳阳',a:'范仲淹〔宋代〕',c:'仕宦自飘然，君恩岂欲偏。\n才归剑门道，忽上洞庭船。\n坠絮伤春目，春涛废夜眠。\n岳阳楼上月，清赏浩无边。'},
    {t:'送韩九',a:'高适〔唐代〕',c:'惆怅别离日，裴回歧路前。归人望独树，匹马随秋蝉。\n常与天下士，许君兄弟贤。良时正可用，行矣莫徒然。'},
    {t:'送韩十四江东觐省',a:'杜甫〔唐代〕',c:'兵戈不见老莱衣，叹息人间万事非。\n我已无家寻弟妹，君今何处访庭闱？\n黄牛峡静滩声转，白马江寒树影稀。\n此别应须各努力，故乡犹恐未同归。'},
    {t:'送韩侍御归山',a:'张籍〔唐代〕',c:'闻君久卧在云间，为佐嫖姚未马还。新结茅庐招隐逸，\n独骑骢马入深山。九灵洞口行应到，五粒松枝醉亦攀。\n明日珂声出城去，家僮不复扫柴关。'},
    {t:'送韩巽入都觐省便赴举',a:'岑参〔唐代〕',c:'槐叶苍苍柳叶黄，秋高八月天欲霜。青门百壶送韩侯，\n白云千里连嵩丘。北堂倚门望君忆，东归扇枕后秋色。\n洛阳才子能几人，明年桂枝是君得。'},
    {t:'送韩愈从军',a:'孟郊〔唐代〕',c:'志士感恩起，变衣非变性。亲宾吟旧观，僮仆生新敬。\n坐作群书吟，行为孤剑咏。始知出处心，不马平生正。\n凄凄天地秋，凛凛军马令。驿尘时一飞，物色极四静。\n王师既不战，庙略在无竞。王粲有所依，元瑜初应命。\n一章喻檄明，百万心气定。今朝旌鼓前，笑别丈夫盛。'},
    {t:'送何白节推宰晋原二首',a:'范仲淹〔宋代〕',c:'盛府兼名邑，荣归指故林。\n多年望乡泪，万里倚门心。\n江馆春寒薄，山程晚翠深。\n板与迎侍日，桃李正芳阴。'},
    {t:'送和蕃公主',a:'张籍〔唐代〕',c:'塞上如今无战尘，汉家公主出同亲。\n邑司犹属宗卿寺，册号还同虏帐人。\n九姓旗幡先引路，一生衣服尽随身。\n毡城南望无回日，空见沙蓬水柳春。'},
    {t:'送和甫至龙安微雨因寄吴氏女子',a:'王安石〔宋代〕',c:'荒烟凉雨助人悲，泪染衣襟不自知。\n除却春风沙际绿，一如看汝过江时。'},
    {t:'送贺宾客归越',a:'李白〔唐代〕',c:'镜湖流水漾清波，狂客归舟逸兴多。\n山阴道士如相见，应写黄庭换白鹅。'},
    {t:'送贺遂员外外甥',a:'王维〔唐代〕',c:'南国有归舟，荆门溯上流。\n苍茫葭菼外，云水与昭丘。\n樯带城乌去，江连暮雨愁。\n猿声不可听，莫待楚山秋。'},
    {t:'送弘文李校书往汉南拜亲',a:'岑参〔唐代〕',c:'未识已先闻，清辞果出群。如逢祢处士，似见鲍参军。\n梦暗巴山雨，家连汉水云。慈亲思爱子，几度泣沾裙。'},
    {t:'送侯判官赴广州从军',a:'张籍〔唐代〕',c:'年少才高求自展，将身万里赴军门。辟书远到开呈客，\n公服新成著谢恩。驿舫过江分白堠，戍亭当岭见红幡。\n海花蛮草连冬有，行处无家不满园。'},
    {t:'送胡大',a:'王昌龄〔唐代〕',c:'荆门不堪别，况乃潇湘秋。\n何处遥望君，江边明月楼。'},
    {t:'送胡象落第归王屋别业',a:'岑参〔唐代〕',c:'看君尚少年，不第莫凄然。可即疲献赋，山村归种田。\n野花迎短褐，河柳拂长鞭。置酒聊相送，青门一醉眠。'},
    {t:'送湖南部曲',a:'辛弃疾〔宋代〕',c:'青衫匹马万人呼，幕府当年急急符。\n愧我明珠成薏苡，负君赤手缚於菟。\n观书到老眼如镜，论事惊人胆满躯。\n万里云霄送君去，不妨风雨破吾庐。'},
    {t:'送湖南李正字归',a:'韩愈〔唐代〕',c:'长沙入楚深，洞庭值秋晚。\n人随鸿雁少，江共蒹葭远。\n历历余所经，悠悠子当返。\n孤游怀耿介，旅宿梦婉娩。\n风土稍殊音，鱼虾日异饭。\n亲交俱在此，谁与同息偃。'},
    {t:'送怀州吴别驾',a:'岑参〔唐代〕',c:'灞上柳枝黄，垆头酒正香。春流饮去马，暮雨湿行装。\n驿路通函谷，州城接太行。覃怀人总喜，别驾得王祥。'},
    {t:'送淮阴孙令之官',a:'温庭筠〔唐代〕',c:'隋堤杨柳烟，孤棹正悠然。\n萧寺通淮戍，芜城枕楚壖。\n鱼盐桥上市，灯火雨中船。\n故老青葭岸，先知儒子贤。'},
    {t:'送槐广落第归扬州',a:'韦应物〔唐代〕',c:'下第常称屈，少年心独轻。拜亲归海畔，似舅得诗名。\n晚对青山别，遥寻芳草行。还期应不远，寒露湿芜城。'},
    {t:'送桓子之郢成礼',a:'孟浩然〔唐代〕',c:'闻君驰彩骑，躞蹀指南荆。为结潘杨好，言过鄢郢城。\n摽梅诗有赠，羔雁礼将行。今夜神仙女，应来感梦情。'},
    {t:'送桓子之郢城礼',a:'孟浩然〔唐代〕',c:'闻君驰綵骑，躞蹀指南荆。为结潘杨好，言过鄢郢城。\n摽梅诗有赠，羔雁礼将行。今夜神仙女，应来感梦情。'},
    {t:'送黄构擢第后归江南',a:'孟郊〔唐代〕',c:'澹澹沧海气，结成黄香才。幼龄木奋飞，弱冠游灵台。\n一鹗顾乔木，众禽不敢猜。一骥骋长衢，众云不敢陪。\n遂得会风雨，感通如云雷。至矣小宗伯，确乎心不回。\n能令幽静人，声实喧九垓。却忆江南道，祖筵花里开。\n春风不能别，别罢空徘徊。'},
    {t:'送稽亭山寺僧',a:'张籍〔唐代〕',c:'师住稽亭高处寺，斜廊曲阁倚云开。\n山门十里松间入，泉涧三重洞里来。\n名岳寻游今已遍，家城礼谒便应回。\n旧房到日闲吟后，林下还登说法台。'},
    {t:'送贾讷倅眉',a:'苏轼〔宋代〕',c:'老翁山下玉渊回，手植青松三万栽。\n父老得书知我在，小轩临水为君开。\n试看一一龙蛇活，更听萧萧风雨哀。\n便与甘棠同不剪，苍髯白甲待归来。'},
    {t:'送贾山人南游歌',a:'柳宗元〔唐代〕',c:'充乎其居，或以匮己之虚。或盈其庐。孰匮孰充，为泰为穷，君子乌乎取以宁其躬！\n若君者之于道而已尔，世孰知其从容耶！'},
    {t:'送贾升主簿之荆府',a:'孟浩然〔唐代〕',c:'奉使推能者，勤王不暂闲。观风随按察，乘骑度荆关。\n送别登何处，开筵旧岘山。征轩明日远，空望郢门间。'},
    {t:'送蹇秀才赴临洮',a:'高适〔唐代〕',c:'怅望日千里，如何今二毛。\n犹思阳谷去，莫厌陇山高。\n倚马见雄笔，随身唯宝刀。\n料君终自致，勋业在临洮。'},
    {t:'送剑与傅岩叟',a:'辛弃疾〔宋代〕',c:'镆邪三尺照人寒，试与挑灯子细看。\n且挂空斋作琴伴，未须携去斩楼兰。'},
    {t:'送江陵黎少府',a:'岑参〔唐代〕',c:'悔系腰间绶，翻为膝下愁。那堪汉水远，更值楚山秋。\n新橘香官舍，征帆拂县楼。王城不敢住，岂是爱荆州。'},
    {t:'送江陵泉少府赴任，便呈卫荆州',a:'岑参〔唐代〕',c:'神仙吏姓梅，人吏待君来。渭北草新出，江南花已开。\n城边宋玉宅，峡口楚王台。不畏无知己，荆州甚爱才。'},
    {t:'送蒋颖叔帅熙河二首',a:'秦观〔宋代〕',c:'天马蒲萄隔玉门，汉廷谁更勇风尊。\n行台晓日屯千骑，祖道春风属一樽。\n莫许留犁轻结好，便令瓯脱复游魂。\n要须尽取熙河地，打鼓梁州看上元。'},
    {t:'送金山乡僧归蜀开堂',a:'苏轼〔宋代〕',c:'撞钟浮玉山，迎我三千指。\n众中人謦欬，未语知乡里。\n我非个中人，何以默识子。\n振衣忽归去，只影千山里。\n涪江与中泠，共此一味水。\n冰盘荐琥珀，何似糖霜美。'},
    {t:'送进士刘师服东归',a:'韩愈〔唐代〕',c:'猛虎落槛阱，坐食如孤豚。丈夫气富贵，岂必守一门。\n公心有勇气，公口有直言。奈何任埋没，不根求腾轩。\n仆本亦进士，颇尝究根源。由来骨鲠材，喜被软弱吞。\n低头受侮笑，隐忍硉兀冤。泥雨城东路，夏槐作云屯。\n还家虽阙短，把日亲晨飧。携持令名归，根足贻家尊。\n时节不可玩，亲交可攀援。勉来取金紫，勿久休中园。'},
    {t:'送舅氏野夫之宣城二首',a:'黄庭坚〔宋代〕',c:'藉甚宣城郡，风流数贡毛。\n霜林收鸭脚，春网荐琴高。\n共理须良守，今年辍省曹。\n平生割鸡手，聊试发硎刀。\n试说宣城郡，停杯且细听。\n晚楼明宛水，春骑簇昭亭。\n䆉稏丰圩户，桁杨卧讼庭。\n谢公歌舞处，时对换鹅经。'},
    {t:'送康太守',a:'王维〔唐代〕',c:'城下沧江水，江边黄鹤楼。\n朱阑将粉堞，江水映悠悠。\n铙吹发夏口，使君居上头。\n郭门隐枫岸，侯吏趋芦洲。\n何异临川郡，还劳康乐侯。'},
    {t:'送客',a:'陈子昂〔唐代〕',c:'故人洞庭去，杨柳春风生。\n相送河洲晚，苍茫别思盈。\n白蘋已堪把，绿芷复含荣。\n江南多桂树，归客赠生平。'},
    {t:'送客归京',a:'白居易〔唐代〕',c:'水陆四千里，何时归到秦？\n舟辞三峡雨，马入九衢尘。\n有酒留行客，无书寄贵人。\n唯凭远传语，好在曲江春。'},
    {t:'送客游蜀',a:'张籍〔唐代〕',c:'行尽青山到益州，锦城楼下二江流。\n杜家曾向此中住，为到浣花溪水头。'},
    {t:'送孔巢父谢病归游江东兼呈李白',a:'杜甫〔唐代〕',c:'巢父掉头不肯住，东将入海随烟雾。\n诗卷长留天地间，钓竿欲拂珊瑚树。\n深山大泽龙蛇远，春寒野阴风景暮。\n蓬莱织女回云车，指点虚无是归路。\n自是君身有仙骨，世人那得知其故。\n惜君只欲苦死留，富贵何如草头露？\n蔡侯静者意有余，清夜置酒临前除。\n罢琴惆怅月照席：几岁寄我空中书？\n南寻禹穴见李白，道甫问讯今何如！'},
    {t:'送黎六郎赴阳翟少府',a:'韦应物〔唐代〕',c:'试吏向嵩阳，春山踯躅芳。腰垂新绶色，衣满旧芸香。\n乔树别时绿，客程关外长。只应传善政，日夕慰高堂。'},
    {t:'送李翱',a:'韩愈〔唐代〕',c:'广州万里途，山重江逶迤。行行去时到，谁能定归期。\n揖我出门去，颜色异恒时。虽云有追送，足迹绝自兹。\n人生一世间，不自张与弛。譬如浮江木，纵横岂自知。\n宁怀别时苦，勿作别后思。'},
    {t:'送李道士',a:'皎然〔唐代〕',c:'常随山上下，忽限江南北。共是忘情人，何由肯相忆。'},
    {t:'送李副使赴碛西官军',a:'岑参〔唐代〕',c:'火山六月应更热，赤亭道口行人绝。\n知君惯度祁连城，岂能愁见轮台月。\n脱鞍暂入酒家垆，送君万里西击胡。\n功名祗向马上取，真是英雄一丈夫。'},
    {t:'送李明府赴睦州，便拜觐太夫人',a:'岑参〔唐代〕',c:'手把铜章望海云，夫人江上泣罗裙。\n严滩一点舟中月，万里烟波也梦君。'},
    {t:'送李判官赴东江',a:'王维〔唐代〕',c:'闻道皇华使，方随皂盖臣。\n封章通左语，冠冕化文身。\n树色分扬子，潮声满富春。\n遥知辨璧吏，恩到泣珠人。'},
    {t:'送李骑曹灵州归觐',a:'张籍〔唐代〕',c:'翩翩出上京，几日到边城。渐觉风沙起，还将弓箭行。\n席箕侵路暗，野马见人惊。军府知归庆，应教数骑迎。'},
    {t:'送李群玉赴举',a:'杜牧〔唐代〕',c:'故人别来面如雪，一榻拂云秋影中。\n玉白花红三百首，五陵谁唱与春风。'},
    {t:'送李少府贬峡中王少府贬长沙',a:'高适〔唐代〕',c:'嗟君此别意何如，驻马衔杯问谪居。\n巫峡啼猿数行泪，衡阳归雁几封书。\n青枫江上秋帆远，白帝城边古木疏。\n圣代即今多雨露，暂时分手莫踌躇。'},
    {t:'送李少府时在客舍作',a:'高适〔唐代〕',c:'相逢旅馆意多违，暮雪初晴候雁飞。\n主人酒尽君未醉，薄暮途遥归不归。'},
    {t:'送李十五',a:'王昌龄〔唐代〕',c:'怨别秦楚深，江中秋云起。\n天长杳无隔，月影在寒水。'},
    {t:'送李侍御赴安西',a:'高适〔唐代〕',c:'行子对飞蓬，金鞭指铁骢。\n功名万里外，心事一杯中。\n虏障燕支北，秦城太白东。\n离魂莫惆怅，看取宝刀雄！'},
    {t:'送李侍御益赴幽州幕',a:'韦应物〔唐代〕',c:'二十挥篇翰，三十穷典坟。辟书五府至，名为四海闻。\n始从车骑幕，今赴嫖姚军。契阔晚相遇，草戚遽离群。\n悠悠行子远，眇眇川途分。登高望燕代，日夕生夏云。\n司徒拥精甲，誓将除国氛。儒生幸持斧，可以佐功勋。\n无言羽书急，坐阙相思文。'},
    {t:'送李司谏归京·得长字',a:'岑参〔唐代〕',c:'别酒为谁香，春官驳正郎。醉经秦树远，梦怯汉川长。\n雨过风头黑，云开日脚黄。知君解起草，早去入文昌。'},
    {t:'送李司空赴镇襄阳',a:'张籍〔唐代〕',c:'中外兼权社稷臣，千官齐出拜符尘。\n再调公鼎勋庸盛，三受兵符宠命新。\n商路雪开旗旆展，楚堤梅发驿亭春。\n襄阳风景由来好，重与江山作主人。'},
    {t:'送李太守赴上洛',a:'王维〔唐代〕',c:'商山包楚邓，积翠蔼沉沉。\n驿路飞泉洒，关门落照深。\n野花开古戍，行客响空林。\n板屋春多雨，山城昼欲阴。\n丹泉通虢略，白羽抵荆岑。\n若见西山爽，应知黄绮心。'},
    {t:'送李五',a:'王昌龄〔唐代〕',c:'玉盌金罍倾送君，江西日入起黄云。扁舟乘月暂来去，谁道沧浪吴楚分。'},
    {t:'送李弦殿院赴阙',a:'范仲淹〔宋代〕',c:'霜露丘园不忍违，三年月日速如飞。\n金门乍入应垂泪，因挂朝衣忆彩衣。'},
    {t:'送李馀及第后归蜀',a:'张籍〔唐代〕',c:'十年人咏好诗章，今日成名出举场。归去唯将新诰牒，\n后来争取旧衣裳。山桥晓上芭蕉暗，水店晴看芋草黄。\n乡里亲情相见日，一时携酒贺高堂。'},
    {t:'送李员外贤郎',a:'王维〔唐代〕',c:'少年何处去，负米上铜梁。\n借问阿戎父，知为童子郎。\n鱼笺请诗赋，橦布作衣裳。\n薏苡扶衰病，归来幸可将。'},
    {t:'送李中丞赴楚州',a:'刘禹锡〔唐代〕',c:'缇骑朱旗入楚城，士林皆贺振家声。儿童但喜迎宾守，\n故吏犹应记姓名。万顷水田连郭秀，四时烟月映淮清。\n忆君初得昆山玉，同向扬州携手行。'},
    {t:'送李翥游江外',a:'岑参〔唐代〕',c:'相识应十载，见君只一官。家贫死尚薄，霜降衣仍单。\n惆怅秋草死，萧条芳岁阑。且寻沧洲路，遥海吴云端。\n匹马关塞远，孤舟江海宽。夜眠楚烟湿，晓饭湖山寒。\n砧净红鲙落，袖香朱橘团。帆前见禹庙，枕底闻严滩。\n便获赏心趣，岂歌行路难。青门须醉别，少为解征鞍。'},
    {t:'送李擢游江东',a:'王昌龄〔唐代〕',c:'清洛日夜涨，微风引孤舟。离肠便千里，远梦生江楼。\n楚国橙橘暗，吴门烟雨愁。东南具今古，归望山云秋。'},
    {t:'送李尊师玄',a:'孟郊〔唐代〕',c:'口诵碧简文，身是青霞君。头冠两片月，肩披一条云。\n松骨轻自飞，鹤心高不群。'},
    {t:'送梁李二明府',a:'陈子昂〔唐代〕',c:'负书犹在汉，怀策未闻秦。复此穷秋日，芳樽别故人。\n黄金装屡尽，白首契逾新。空羡双凫舄，俱飞向玉轮。'},
    {t:'送梁拾遗肃归朝',a:'皎然〔唐代〕',c:'明主重文谏，才臣出江东。束书辞东山，改服临北风。\n万里望皇邑，九重当曙空。天开芙蓉阙，日上蒲桃宫。\n天子初未起，金闺籍先通。身逢轩辕世，名贵鸳鸾中。\n故人荣此别，何用悲丝桐。'},
    {t:'送廖参谋东游二首',a:'刘禹锡〔唐代〕',c:'九陌逢君又别离，行云别鹤本无期。\n望嵩楼上忽相见，看过花开花落时。\n繁花落尽君辞去，绿草垂杨引征路。\n东道诸侯皆故人，留连必是多情处。'},
    {t:'送林熙之诗五首其五',a:'朱熹〔宋代〕',c:'古镜重磨要古方，眼明偏与日争光。明明直照吾家路，莫指并州作故乡。'},
    {t:'送灵澈',a:'皎然〔唐代〕',c:'我欲长生梦，无心解伤别。\n千里万里心，只似眼前月。'},
    {t:'送凌侍郎还宣州',a:'晏殊〔宋代〕',c:'日南藩郡古宣城，碧落神仙拥使旌。\n津吏戒船东下稳，县僚负弩昼归荣。\n江山谢守高吟地，风月朱公故里情。\n曾预汉庭三独坐，府中谁敢伴飞觥。'},
    {t:'送陵州路使君赴任',a:'杜甫〔唐代〕',c:'王室比多难，高官皆武臣。\n幽燕通使者，岳牧用词人。\n国待贤良急，君当拔擢新。\n佩刀成气象，行盖出风尘。\n战伐乾坤破，疮痍府库贫。\n众寮宜洁白，万役但平均！\n霄汉瞻佳士，泥涂任此身。\n秋天正摇落，回首大江滨！'},
    {t:'送令狐尚书赴东都留守',a:'张籍〔唐代〕',c:'朝廷重寄在关东，共说从前选上公。勋业新城大梁镇，\n恩荣更守洛阳宫。行香暂出天桥上，巡礼常过禁殿中。\n每领群臣拜章庆，半开门仗日曈曈。'},
    {t:'送令狐岫宰恩阳',a:'韦应物〔唐代〕',c:'大雪天地闭，群山夜来晴。居家辞苦寒，子有千里行。\n行行安得辞，荷此蒲璧荣。贤豪争追攀，饮有出西京。\n樽酒岂不欢，暮春自有程。离人起视日，仆御促前征。\n逶迟岁已穷，当造巴子城。和风被草木，江水日夜清。\n从来知善政，离别慰友生。'},
    {t:'送刘承议解职归养',a:'秦观〔宋代〕',c:'征马萧萧柳外鸣，议廊归养洛阳城。\n登山尚记飞云处，罢吏端如弃唾轻。\n为米折腰知我拙，下车入里见君荣。\n堂前嵩少宜秋色，献寿还应旋制声。'},
    {t:'送刘贡甫谪官衡阳',a:'王安石〔宋代〕',c:'刘郎刘郎莫先起，遇酒当歌且欢喜。\n船头朝转暮千里，眼中之人吾老矣。\n九疑联绵皆相似，负雪崔嵬插花里。\n万里衡阳雁，寻常到此回。\n行逢二三月，好与雁同来。\n雁来人不来，如何不饮令心哀。\n莫厌潇湘少人处，谪官樽俎定常开。'},
    {t:'送刘贡父舍人二首',a:'秦观〔宋代〕',c:'观也本诸生，早与世参商。\n方枘知量凿，交亲指为狂。\n末路辱公知，赐出非所望。\n相期古人处，岂始事文章。\n汝南虽奥区，校官实始张。\n解鞅百无有，栖栖寄僧坊。\n筑室从有徒，皆公借余光。\n一壼千金直，所济在仓黄。\n万里犹比邻，别离无足伤。\n何以报公德，修好以为常。'},
    {t:'送刘评事充朔方判官赋得征马嘶',a:'高适〔唐代〕',c:'征马向边州，萧萧嘶不休。\n思深应带别，声断为兼秋。\n岐路风将远，关山月共愁。\n赠君从此去，何日大刀头？'},
    {t:'送刘其发入蜀',a:'文天祥〔宋代〕',c:'秋风凄已寒，蜀道阻且长。\n虎狼来原野，欲济川无梁。\n客从何处来，云我之西方。\n萧萧骕骦鸣，战战湛卢光。\n昔时荣华地，今为争战场。\n将军扬天戈，壮士发戎行。\n江南有羁鸟，悠悠怀故乡。\n驾言与子游，云天何茫茫。'},
    {t:'送刘三复郎中赴阙',a:'杜牧〔唐代〕',c:'横溪辞寂寞，金马去追游。好是鸳鸯侣，正逢霄汉秋。\n玉珂声琐琐，锦帐梦悠悠。微笑知今是，因风谢钓舟。'},
    {t:'送刘昚虚归取宏词解',a:'王昌龄〔唐代〕',c:'太清闻海鹤，游子引乡眄。声随羽仪远，势与归云便。\n青桂春再荣，白云暮来变。迁飞在礼仪，岂复泪如霰。'},
    {t:'送刘师服',a:'韩愈〔唐代〕',c:'夏半阴气始，淅然云景秋。\n蝉声入客耳，惊起不可留。\n草草具盘馔，不待酒献酬。\n士生为名累，有似鱼中钩。\n赍材入市卖，贵者恒难售。\n岂不畏憔悴，为功忌中休。\n勉哉耘其业，以待岁晚收。'},
    {t:'送刘十五之郡',a:'王昌龄〔唐代〕',c:'平明江雾寒，客马江上发。\n扁舟事洛阳，窅窅含楚月。'},
    {t:'送刘司法之越',a:'皎然〔唐代〕',c:'萧萧鸣夜角，驱马背城濠。雨后寒流急，秋来朔吹高。\n三山期望海，八月欲观涛。几日西陵路，应逢谢法曹。'},
    {t:'送刘司直赴安西',a:'王维〔唐代〕',c:'绝域阳关道，胡沙与塞尘。\n三春时有雁，万里少行人。\n苜蓿随天马，蒲桃逐汉臣。\n当令外国惧，不敢觅和亲。'},
    {t:'送柳淳',a:'孟郊〔唐代〕',c:'青山临黄河，下有长安道。世上名利人，相逢不知老。'},
    {t:'送卢郎中除杭州赴任',a:'岑参〔唐代〕',c:'罢起郎官草，初分刺史符。海云震过楚，江月引归吴。\n城底涛声震，楼端蜃气孤。千家窥驿舫，五马饮春湖。\n柳色供诗用，莺声送酒须。知君望乡处，枉道上姑苏。'},
    {t:'送卢郎中汀',a:'孟郊〔唐代〕',c:'洛水春渡阔，别离心悠悠。一生空吟诗，不觉成白头。\n向事每计较，与山实绸缪。太华天上开，其下车辙流。\n县街无尘土，过客多淹留。坐饮孤驿酒，行思独山游。\n逸关岚气明，照渭空漪浮。玉珂摆新欢，声与鸾凤俦。\n朝谒大家事，唯余去无由。'},
    {t:'送卢少府使入秦',a:'孟浩然〔唐代〕',c:'楚关望秦国，相去千里馀。州县勤王事，山河转使车。\n祖筵江上列，离恨别前书。愿及芳年赏，娇莺二月初。'},
    {t:'送陆畅',a:'张籍〔唐代〕',c:'共踏长安街里尘，吴州独作未归身。\n昔年旧宅今谁住，君过西塘与问人。'},
    {t:'送陆判官归杭州',a:'皎然〔唐代〕',c:'芳草潜州路，乘轺忆再旋。馀花故林下，残月旧池边。\n峰色云端寺，潮声海上天。明朝富春渚，应见谢公船。'},
    {t:'送陆判官往琵琶峡',a:'李白〔唐代〕',c:'水国秋风夜，殊非远别时。\n长安如梦里，何日是归期。'},
    {t:'送陆侍御士佳赴上京',a:'皎然〔唐代〕',c:'长安三千里，喜行不言永。清路府尘飞，大河沧流静。\n更怀西川府，主公昔和鼎。伊郁瑶瑟情，威迟花骢影。\n此时已难别，日又无停景。出饯阙相从，心随过前岭。'},
    {t:'送路六侍御入朝',a:'杜甫〔唐代〕',c:'童稚情亲四十年，中间消息两茫然。\n更为后会知何地？忽漫相逢是别筵！\n不分桃花红似锦，生憎柳絮白于棉。\n剑南春色还无赖，触忤愁人到酒边。'},
    {t:'送罗正之两浙提刑',a:'秦观〔宋代〕',c:'岂为鲈鱼忆故丘，东南昏垫赖归谋。\n一封暮别云间阁，三组秋归海上州。\n子政暂为都水使，千秋终作富民侯。\n赠君一语君应笑，竞注江河本不流。'},
    {t:'送洛南李主簿',a:'温庭筠〔唐代〕',c:'想君秦塞外，因见楚山青。槲叶晓迷路，枳花春满庭。\n禄优仍侍膳，官散得专经。子敬怀愚谷，归心在翠屏。'},
    {t:'送孟六归襄阳',a:'王维〔唐代〕',c:'杜门不复出，久与世情疏。\n以此为良策，劝君归旧庐。\n醉歌田舍酒，笑读古人书。\n好是一生事，无劳献子虚。'},
    {t:'送秘书晁监还日本国',a:'王维〔唐代〕',c:'积水不可极，安知沧海东。\n九州何处远，万里若乘空。\n向国唯看日，归帆但信风。\n鳌身映天黑，鱼眼射波红。\n乡树扶桑外，主人孤岛中。\n别离方异域，音信若为通。'},
    {t:'送渑池崔主簿',a:'韦应物〔唐代〕',c:'邑带洛阳道，年年应此行。当时匹马客，今日县人迎。\n暮雨投关郡，春风别帝城。东西殊不远，朝夕待佳声。'},
    {t:'送莫甥兼诸昆弟从韩司马入西军',a:'孟浩然〔唐代〕',c:'念尔习诗礼，未曾违户庭。平生早偏露，万里更飘零。\n坐弃三牲养，行观八阵形。饰装辞故里，谋策赴边庭。\n壮志吞鸿鹄，遥心伴鶺鴒。所从文且武，不战自应宁。'},
    {t:'送穆寂赴举',a:'皎然〔唐代〕',c:'天子锡玄纁，倾山礼隐沦。君抛青霞去，荣资观国宾。\n剑光既陆离，琼彩何璘玢。夙驾别情远，商弦秋意新。\n冥冥鸿鹄姿，数尺看苍旻。残寇近宋郊，西行恶飙尘。\n立身素耿介，处难思经纶。春府搜才日，高科得一人。'},
    {t:'送内寻庐山女道士李腾空二首',a:'李白〔唐代〕',c:'君寻腾空子，应到碧山家。\n水舂云母碓，风扫石楠花。\n若爱幽居好，相邀弄紫霞。\n多君相门女，学道爱神仙。\n素手掬青霭，罗衣曳紫烟。\n一往屏风叠，乘鸾着玉鞭。'},
    {t:'送牛相出镇襄州',a:'杜牧〔唐代〕',c:'盛时常注意，南雍暂分茅。紫殿雾明主，岩廊别旧交。\n危幢侵碧雾，寒旆猎红旓。德业悬秦镜，威声隐楚郊。\n拜尘先洒泪，成厦昔容巢。遥仰沈碑会，鸳鸯玉佩敲。'},
    {t:'送欧阳会稽之任',a:'王昌龄〔唐代〕',c:'怀禄贵心赏，东流山水长。官移会稽郡，地迩上虞乡。\n缓带屏纷杂，渔舟临讼堂。逶迤回溪趣，猿啸飞鸟行。\n万室霁朝雨，千峰迎夕阳。辉辉远洲映，暧暧澄湖光。\n白发有高士，青春期上皇。应须枉车歇，为我访荷裳。'},
    {t:'送裴别将之安西',a:'高适〔唐代〕',c:'绝域眇难跻，悠然信马蹄。\n风尘经跋涉，摇落怨暌携。\n地出流沙外，天长甲子西。\n少年无不可，行矣莫凄凄。'},
    {t:'送裴二虬作尉永嘉',a:'杜甫〔唐代〕',c:'孤屿亭何处，天涯水气中。\n故人官就此，绝境与谁同。\n隐吏逢梅福，看山忆谢公。\n扁舟吾已僦，把钓待秋风。'},
    {t:'送裴判官自贼中再归河阳幕府',a:'岑参〔唐代〕',c:'东郊未解围，忠义似君稀。\n误落胡尘里，能持汉节归。\n卷帘山对酒，上马雪沾衣。\n却向嫖姚幕，翩翩去若飞。'},
    {t:'送裴十八图南归嵩山二首',a:'李白〔唐代〕',c:'何处可为别，长安青绮门。\n胡姬时素手，延客醉金樽。\n临当上马时，我独与君言。\n风吹芳兰折，日具鸟雀喧。\n举手指飞鸿，此情难具论。\n同归无早晚，颍水有清源。\n君思颍水绿，忽复归嵩岑。\n归时莫洗耳，为我洗其心。\n洗心得真情，洗耳徒买名。\n谢公终一起，相与济苍生。'},
    {t:'送裴侍御赴',a:'岑参〔唐代〕',c:'羡他骢马郎，元日谒明光。立处闻天语，朝回惹御香。\n台寒柏树绿，江暖柳条黄。惜别津亭暮，挥戈忆鲁阳。'},
    {t:'送裴图南',a:'王昌龄〔唐代〕',c:'黄河渡头归问津，离家几日茱萸新。\n漫道闺中飞破镜，犹看陌上别行人。'},
    {t:'送裴相公赴镇太原',a:'张籍〔唐代〕',c:'盛德雄名远近知，功高先乞守藩维。衔恩暂遣分龙节，\n署敕还同在凤池。天子亲临楼上送，朝官齐出道傍辞。\n明年塞北清蕃落，应建生祠请立碑。'},
    {t:'送裴校书从大夫淄川觐省',a:'岑参〔唐代〕',c:'尚书未出守，爱子向青州。一路通关树，孤城近海楼。\n怀中江橘熟，倚处戟门秋。更奉轻轩去，知君无客愁。'},
    {t:'送平澹然判官',a:'王维〔唐代〕',c:'不识阳关路，新从定远侯。\n黄云断春色，画角起边愁。\n瀚海经年到，交河出塞流。\n须令外国使，知饮月氏头。'},
    {t:'送蒲秀才擢第归蜀',a:'岑参〔唐代〕',c:'去马疾如飞，看君战胜归。新登郄诜第，更著老莱衣。\n汉水行人少，巴山客舍稀。向南风候暖，腊月见春辉。'},
    {t:'送七兄赴扬州帅幕',a:'陆游〔宋代〕',c:'初报边烽照石头，旋闻胡马集怀州。\n诸公谁听刍荛策，吾辈空怀畎亩忧。\n急雪打窗心共碎，危楼望远涕俱流。\n岂知今日淮南路，乱絮飞花送客舟。'},
    {t:'送綦毋秘书弃官还江东',a:'王维〔唐代〕',c:'明时久不达，弃置与君同。\n天命无怨色，人生有素风。\n念君拂衣去，四海将安穷。\n秋天万里净，日暮澄江空。\n清夜何悠悠，扣舷明月中。\n和光鱼鸟际，澹尔蒹葭丛。\n无庸客昭世，衰鬓日如蓬。\n顽疏暗人事，僻陋远天聪。\n微物纵可采，其谁为至公。\n余亦从此去，归耕为老农。'},
    {t:'送綦毋潜落第还乡',a:'王维〔唐代〕',c:'圣代无隐者，英灵尽来归。\n遂令远山客，不得顾采薇。\n既至金门远，孰云吾道非。\n长淮度寒食，京洛缝春衣。\n置酒长安道，同心与我违。\n行当浮桂棹，未几拂荆扉。\n远树带行客，孤村当落晖。\n吾谋适不用，勿谓知音稀。'},
    {t:'送蕲州李郎中赴任',a:'刘禹锡〔唐代〕',c:'楚关蕲水路非赊，东望云山日碗佳。\n薤叶照人呈夏簟，松花满碗试新茶。\n楼中饮兴因明月，江上诗情为晚霞。\n北地交亲长引领，早将玄鬓到京华。'},
    {t:'送契上人游扬州',a:'皎然〔唐代〕',c:'西陵古江口，远见东扬州。渌水不同泛，春山应独游。\n寻僧白岩寺，望月谢家楼。宿昔心期在，人寰非久留。'},
    {t:'送钱少府还蓝田',a:'王维〔唐代〕',c:'草色日向好，桃源人去稀。\n手持平子赋，目送老莱衣。\n每候山樱发，时同海燕归。\n今年寒食酒，应是返柴扉。'},
    {t:'送秦系赴润州',a:'韦应物〔唐代〕',c:'近作新婚镊白髯，长怀旧卷映蓝衫。\n更欲携君虎丘寺，不知方伯望征帆。'},
    {t:'送清凉上人',a:'皎然〔唐代〕',c:'何意欲归山，道高由境胜。花空觉性了，月尽知心证。\n永夜出禅吟，清猿自相应。'},
    {t:'送清远上人归楚山旧寺',a:'孟郊〔唐代〕',c:'波中出吴境，霞际登楚岑。\n山寺一别来，云萝三改阴。\n诗夸碧云句，道证青莲心。\n应笑泛萍者，不知松隐深。'},
    {t:'送丘为落第归江东',a:'王维〔唐代〕',c:'怜君不得意，况复柳条春。\n为客黄金尽，还家白发新。\n五湖三亩宅，万里一归人。\n知祢不能荐，羞为献纳臣。'},
    {t:'送丘为往唐州',a:'王维〔唐代〕',c:'宛洛有风尘，君行多苦辛。\n四愁连汉水，百口寄随人。\n槐色阴清昼，杨花惹暮春。\n朝端肯相送，天子绣衣臣。'},
    {t:'送丘宗卿帅蜀三首',a:'杨万里〔宋代〕',c:'人似隆中汉卧龙，韵如江左晋江公。\n四川全国牙旗底，万里长江羽扇中。\n玉垒顿清开宿雾，雪山增重起秋风。\n近来廊庙多西帅，出相谁言只在东。'},
    {t:'送曲郎将使默啜序',a:'陈子昂〔唐代〕',c:'盖北夷不羁之日久矣，天子垂元默穆皇风，而狼居革心，蚁伏请职。岁一月，上将恤戎，迺以金章假曲公为司宾卿，载驰锦车，谕意云幕，且欲顿单于之膝，受呼韩之朝。不逾青春，复命紫阙，其忠臣烈夫之节，感激壮矣。朝廷以赴此绝国，追送近郊，登熊山，望燕塞，黄云千里，亭皋悠然。佥曰赋诗，绝句以赠。'},
    {t:'送瞿生还拜亲',a:'晏殊〔宋代〕',c:'门标杨氏阙，家有汉皇书。\n射策到前志，鸣榔省旧居。\n仙山人罕到，幽境画难如。\n云窦开宾馆，芝田足岁储。\n修词穷五际，为学慕三馀。\n努力文明代，翘翘托乘车。'},
    {t:'送饶州董博士',a:'范仲淹〔宋代〕',c:'番国英豪富鲁儒，同时举送起乡闾。\n文章耻学扬雄赋，议论羞谈贾谊书。\n喜得明珠三十六，恨遗壮士二千馀。\n送君直上青霄去，行看归乘驷马车。'},
    {t:'送人',a:'杜牧〔唐代〕',c:'鸳鸯帐里暖芙蓉，低泣关山几万重。\n明镜半边钗一股，此生何处不相逢。'},
    {t:'送人东游',a:'温庭筠〔唐代〕',c:'荒戍落黄叶，浩然离故关。\n高风汉阳渡，初日郢门山。\n江上几人在，天涯孤棹还。\n何当重相见，樽酒慰离颜。'},
    {t:'送人赴安西',a:'岑参〔唐代〕',c:'上马带吴钩，翩翩度陇头。\n小来思报国，不是爱封侯。\n万里乡为梦，三边月作愁。\n早须清黠虏，无事莫经秋。'},
    {t:'送人赴举',a:'黄庭坚〔宋代〕',c:'青衫乌帽芦花鞭，送君归去明主前。\n若问旧时黄庭坚，谪在人间今八年。'},
    {t:'送人归江夏',a:'王昌龄〔唐代〕',c:'寒江绿水楚云深，莫道离忧迁远心。\n晓夕双帆归鄂渚，愁将孤月梦中寻。'},
    {t:'送人往湖南',a:'文天祥〔宋代〕',c:'雁拖秋月洞庭边，客路凄凉野史天。\n云隔酒尊横北海，风吹诗史落西川。\n夜深鬼火千山雪，春后鹃花一树烟。\n为我祝融峰上看，朝暾白处礼蓬仙。'},
    {t:'送人游淮海·一作宿友人池',a:'温庭筠〔唐代〕',c:'背樯灯色暗，宿客梦初成。半夜竹窗雨，满池荷叶声。\n簟凉秋閤思，木落故山情。明发又愁起，桂花溪水清。'},
    {t:'送任五之桂林',a:'王昌龄〔唐代〕',c:'楚客醉孤舟，越水将引棹。\n山为两乡别，月带千里貌。\n羁谴同缯纶，僻幽闻虎豹。\n桂林寒色在，苦节知所效。'},
    {t:'送僧归保宁',a:'秦观〔宋代〕',c:'西湖环岸皆招提，楼阁晦明如合披。\n保宁复在最佳处，水光四合无端倪。\n车尘不来马足断，时此海月相因依。\n上人弱龄已隶此，心目所证惟瑰琦。\n白玉芙蓉出清沼，天然不受缁尘扰。\n坐客一语不入意，目如明星视飞鸟。\n冠切云兮佩玉难，上人顾之真等闲。\n应缘聊入人间世，兴尽却归湖上山。\n伊余久欲窥禹穴，矧今仲父官东越。\n行挽秋风入剡溪，为君先醉西湖月。'},
    {t:'送僧归遂州',a:'秦观〔宋代〕',c:'宝师本巴蜀，浪迹游淮海。\n定水湛虚明，戒珠炯圆彩。\n飘零乡县异，晼晚星霜改。\n明发又西征，孤帆破烟霭。'},
    {t:'送僧文光',a:'范仲淹〔宋代〕',c:'一品山前识，迢迢三十春。\n多惭画戟里，重见白云人。'},
    {t:'送僧绎',a:'皎然〔唐代〕',c:'斜日摇扬在柳丝，孤亭寂寂水逶迤。\n谁堪别后行人尽，唯有春风起路岐。'},
    {t:'送僧游扬州',a:'皎然〔唐代〕',c:'平明择钵向风轻，正及隋堤柳色行。\n知尔禅心还似我，故宫春物肯伤情。'},
    {t:'送僧之京师',a:'皎然〔唐代〕',c:'绵绵渺渺楚云繁，万里西归望国门。\n禅子初心易凄断，秋风莫上少陵原。'},
    {t:'送沙弥大智游五台',a:'皎然〔唐代〕',c:'童年随法侣，家世本儒流。\n章句三生学，清凉万里游。\n云归龙沼暗，木落雁门秋。\n长老应相问，传予向祖州。'},
    {t:'送商季皋',a:'皎然〔唐代〕',c:'比来知尔有诗名，莫恨东归学未成。\n新丰有酒为我饮，消取故园伤别情。'},
    {t:'送邵州林使君',a:'张籍〔唐代〕',c:'词客南行宠命新，潇湘郡入曲江津。山幽自足探微处，\n俗朴应无争竞人。郭外相连排殿阁，市中多半用金银。\n知君不作家私计，迁日还同到日贫。'},
    {t:'送神',a:'王维〔唐代〕',c:'纷进舞兮堂前。\n目眷眷兮琼筵。\n来不言兮意不传。\n作暮雨兮愁空山。\n悲急管兮之驾兮俨欲旋。\n倏云收兮雨歇。\n山青青兮水潺［氵爰］。'},
    {t:'送沈康知常州',a:'王安石〔宋代〕',c:'作客兰陵迹已陈，为传谣俗记州民。\n沟塍半废田畴薄，厨传相仍市井贫。\n常恐劳人轻白屋，忽逢佳士得朱轮。\n殷勤话此还惆怅，最忆荆溪两岸春。'},
    {t:'送沈亚之歌·并序',a:'李贺〔唐代〕',c:'文人沈亚之，元和七年以书不中第，返归于吴江。吾悲其行，无钱酒以劳，又感沈之勤请，乃歌一解以送之。\n吴兴才人怨春风，桃花满陌千里红。\n紫丝竹断骢马小，家住钱塘东复东。\n白藤交穿织书笈，短策齐裁如梵夹。\n雄光宝矿献春卿，烟底蓦波乘一叶。\n春卿拾材白日下，掷置黄金解龙马。\n携笈归江重入门，劳劳谁是怜君者。\n吾闻壮夫重心骨，古人三走无摧捽。\n请君待旦事长鞭，他日还辕及秋律。'},
    {t:'送沈子归江东',a:'王维〔唐代〕',c:'杨柳渡头行客稀，罟师荡桨向临圻。\n惟有相思似春色，江南江北送君归。'},
    {t:'送胜云小师',a:'皎然〔唐代〕',c:'昨日雪山记尔名，吾今坐石已三生。\n少年道性易流动，莫遣秋风入别情。'},
    {t:'送十五舅',a:'王昌龄〔唐代〕',c:'深林秋水近日空，归棹演漾清阴中。\n夕浦离觞意何已，草根寒露悲鸣虫。'},
    {t:'送石洪处士赴河阳幕得起字',a:'韩愈〔唐代〕',c:'长把种树书，人云避世士。忽骑怀军马，自号报恩子。\n风云入壮怀，泉石别幽耳。钜鹿师欲老，常山险犹恃。\n岂惟彼相忧，固是吾徒耻。去去事方急，酒行可以起。'},
    {t:'送石曼卿',a:'范仲淹〔宋代〕',c:'河光岳色过秦关，英气飘飘酒满颜。\n贾谊书成动西汉，谢安人笑起东山。\n亨途去觉云天近，旧隐回思水石闲。\n此道圣朝如不坠，疏封宜在立谭间。'},
    {t:'送使广州',a:'张九龄〔唐代〕',c:'家在湘源住，君今海峤行。经过正中道，相送倍为情。\n心逐书邮去，形随世网婴。因声谢远别，缘义不缘名。'},
    {t:'送蜀郡李掾',a:'岑参〔唐代〕',c:'饮酒俱未醉，一言聊赠君。功曹善为政，明主还应闻。\n夜宿剑门月，朝行巴水云。江城菊花发，满道香氛氲。'},
    {t:'送蜀客',a:'张籍〔唐代〕',c:'蜀客南行祭碧鸡，木绵花发锦江西。\n山桥日晚行人少，时见猩猩树上啼。'},
    {t:'送四镇薛侍御东归',a:'岑参〔唐代〕',c:'相送泪沾衣，天涯独未归。\n将军初得罪，门客复何依？\n梦去湖山阔，书停陇雁稀。\n园林幸接近，一为到柴扉。'},
    {t:'送苏主簿赴偃师',a:'张九龄〔唐代〕',c:'我与文雄别，胡然邑吏归。贤人安下位，鸷鸟欲卑飞。\n激节轻华冕，移官殉彩衣。羡君行乐处，从此拜庭闱。'},
    {t:'送孙二',a:'王维〔唐代〕',c:'郊外谁相送，夫君道术亲。\n书生邹鲁客，才子洛阳人。\n祖席依寒草，行车起暮尘。\n山川何寂寞，长望泪沾巾。'},
    {t:'送孙侍御游越',a:'皎然〔唐代〕',c:'不知持斧客，吟会是何情。丹陛恩犹在，沧洲赏暂行。\n江桡随月泛，山策逐云行。佳句传零雨，诗流许盛名。'},
    {t:'送谭八之桂林',a:'王昌龄〔唐代〕',c:'客心仍在楚，江馆复临湘。\n别意猿鸟外，天寒桂水长。'},
    {t:'送唐明府赴溧水·三任县事',a:'韦应物〔唐代〕',c:'三为百里宰，已过十馀年。只叹官如旧，旋闻邑屡迁。\n鱼盐滨海利，姜蔗傍湖田。到此安氓俗，琴堂又晏然。'},
    {t:'送陶铣弃举荆南觐省',a:'岑参〔唐代〕',c:'明时不爱璧，浪迹东南游。何必水人识，知君轻五侯。\n采兰度汉水，问绢过荆州。异国有归兴，去乡无客愁。\n天寒楚塞雨，月净襄阳秋。坐见吾道远，令人看白头。'},
    {t:'送滕亢擢第归苏州拜亲',a:'岑参〔唐代〕',c:'送尔姑苏客，沧波秋正凉。橘怀三个去，桂折一枝将。\n湖上山当舍，天边水是乡。江村人事少，时作捕鱼郎。'},
    {t:'送田少府贬苍梧',a:'高适〔唐代〕',c:'沉吟对迁客，惆怅西南天。昔为念官未得意，\n今向万里令人怜。念兹斗酒成暌间，停舟叹君日羡晏。\n远树应怜北地春，行人却羡南归雁。丈夫穷达未可知，\n看君不合长数奇。江山到处堪乘兴，杨柳青青那足悲。'},
    {t:'送汀州源使君',a:'张籍〔唐代〕',c:'曾成赵北归朝计，因拜王门最过官。\n为郡暂辞双凤阙，全家远过九龙滩。\n山乡只有输蕉户，水镇应多养鸭栏。\n地僻寻常来客少，刺桐花发共谁看。'},
    {t:'送宛句赵少府',a:'张九龄〔唐代〕',c:'解巾行作吏，尊酒谢离居。修竹含清景，华池澹碧虚。\n地将幽兴惬，人与旧游疏。林下纷相送，多逢长者车。'},
    {t:'送万大归长沙',a:'王昌龄〔唐代〕',c:'桂阳秋水长沙县，楚竹离声为君变。\n青山隐隐孤舟微，白鹤双飞忽相见。'},
    {t:'送王昌龄之岭南',a:'孟浩然〔唐代〕',c:'洞庭去远近，枫叶早惊秋。\n岘首羊公爱，长沙贾谊愁。\n土毛无缟纻，乡味有槎头。\n已抱沉痼疾，更贻魑魅忧。\n数年同笔砚，兹夕间衾裯。\n意气今何在，相思望斗牛。'},
    {t:'送王大昌龄赴江宁',a:'岑参〔唐代〕',c:'对酒寂不语，怅然悲送君。\n明时未得用，白首徒攻文。\n泽国从一官，沧波几千里。\n群公满天阙，独去过淮水。\n旧家富春渚，尝忆卧江楼。\n自闻君欲行，频望南徐州。\n穷巷独闭门，寒灯静深屋。\n北风吹微雪，抱被肯同宿。\n君行到京口，正是桃花时。\n舟中饶孤兴，湖上多新诗。\n潜虬且深蟠，黄鹄举未晚。\n惜君青云器，努力加餐饭。'},
    {t:'送王大校书',a:'孟浩然〔唐代〕',c:'导漾自嶓冢，东流为汉川。\n维桑君有意，解缆我开筵。\n云雨从兹别，林端意渺然。\n尺书能不吝，时望鲤鱼传。'},
    {t:'送王郎',a:'黄庭坚〔宋代〕',c:'酌君以蒲城桑落之酒，泛君以湘累秋菊之英。\n赠君以黟川点漆之墨，送君以阳关堕泪之声。\n酒浇胸次之磊块，菊制短世之颓龄。\n墨以传万古文章之印，歌以写一家兄弟之情。\n江山千里俱头白，骨肉十年终眼青。\n连床夜语鸡戒晓，书囊无底谈未了。\n有功翰墨乃如此，何恨远别音书少。\n炒沙作縻终不饱，镂冰文章费工巧。\n要须心地收汗马，孔孟行世日杲杲。\n有弟有弟力持家，妇能养姑供珍鲑。\n儿大诗书女丝麻，公但读书煮春茶。'},
    {t:'送王录事却归华阴',a:'岑参〔唐代〕',c:'相送欲狂歌，其如此别何。攀辕人共惜，解印日无多。\n仙掌云重见，关门路再过。双鱼莫不寄，县外是黄河。'},
    {t:'送王七录事赴虢州',a:'岑参〔唐代〕',c:'早岁即相知，嗟君最后时。青云仍未达，白发欲成丝。\n小店关门树，长河华岳祠。弘农人吏待，莫使马行迟。'},
    {t:'送王山人游庐山',a:'皎然〔唐代〕',c:'千里访灵奇，山资亦相随。叶舟过鹤市，花漏宿龙池。\n峰顶应闲散，人间足别离。白云将世事，吾见尔心知。'},
    {t:'送王侍御赴夏口座主幕',a:'杜牧〔唐代〕',c:'君为珠履三千客，我是青衿七十徒。礼数全优知隗始，\n讨论常见念回愚。黄鹤楼前春水阔，一杯还忆故人无。'},
    {t:'送王五昆季省觐',a:'孟浩然〔唐代〕',c:'公子恋庭闱，劳歌涉海涯。水乘舟楫去，亲望老莱归。\n斜日催乌鸟，清江照彩衣。平生急难意，遥仰鶺鴒飞。'},
    {t:'送王校书',a:'韦应物〔唐代〕',c:'同宿高斋换时节，共看移石复栽杉。\n送君江浦已惆怅，更上西楼看远帆。'},
    {t:'送韦城李少府',a:'张九龄〔唐代〕',c:'送客南昌尉，离亭西候春。\n野花看欲尽，林鸟听犹新。\n别酒青门路，归轩白马津。\n相知无远近，万里尚为邻。'},
    {t:'送韦讽上阆州录事参军',a:'杜甫〔唐代〕',c:'国步犹艰难，兵革未休息。\n万方哀嗷嗷，十载供军食。\n庶官务割剥，不暇忧反侧。\n诛求何多门，贤者贵为德。\n韦生富春秋，洞彻有清识。\n操持纲纪地，喜见朱丝直。\n当令豪夺吏，自此无颜色。\n必若救疮痍，先应去蟊贼！\n挥泪临大江，高天意凄恻。\n行行树佳政，慰我深相忆！'},
    {t:'送韦评事',a:'王维〔唐代〕',c:'欲逐将军取右贤，沙场走马向居延。\n遥知汉使萧关外，愁见孤城落日边。'},
    {t:'送韦仁实兄弟入关',a:'李贺〔唐代〕',c:'送客饮别酒，千觞无赭颜。\n何物最伤心？马首鸣金环。\n野色浩无主，秋明空旷间。\n坐来壮胆破，断目不能看。\n行槐引西道，青梢长攒攒。\n韦郎好兄弟，叠玉生文翰。\n我在山上舍，一亩蒿硗田。\n夜雨叫租吏，春声暗交关。\n谁解念劳劳？苍突唯南山。'},
    {t:'送韦十二兵曹',a:'王昌龄〔唐代〕',c:'县职如长缨，终日检我身。平明趋郡府，不得展故人。\n故人念江湖，富贵如埃尘。迹在戎府掾，心游天台春。\n独立浦边鹤，白云长相亲。南风忽至吴，分散还入秦。\n寒夜天光白，海净月色真。对坐论岁暮，弦悲岂无因。\n平生驰驱分，非谓杯酒仁。出处两不合，忠贞何由伸。\n看君孤舟去，且欲歌垂纶。'},
    {t:'送韦侍御先归京·得宽字',a:'岑参〔唐代〕',c:'闻欲朝龙阙，应须拂豸冠。风霜随马去，炎暑为君寒。\n客泪题书落，乡愁对酒宽。先凭报亲友，后月到长安。'},
    {t:'送惟良上人',a:'刘禹锡〔唐代〕',c:'高斋洒寒水，是夕山僧至。玄牝无关锁，琼书舍文字。\n灯明香满室，月午霜凝地。语到不言时，世间人尽睡。'},
    {t:'送维谅上人归洞庭',a:'皎然〔唐代〕',c:'从来湖上胜人间，远爱浮云独自还。\n孤月空天见心地，寥寥一水镜中山。'},
    {t:'送魏八',a:'高适〔唐代〕',c:'更沽淇上酒，还泛驿前舟。\n为惜故人去，复怜嘶马愁。\n云山行处合，风雨兴中秋。\n此路无知己，明珠莫暗投。'},
    {t:'送魏大从军',a:'陈子昂〔唐代〕',c:'匈奴犹未灭，魏绛复从戎。\n怅别三河道，言追六郡雄。\n雁山横代北，狐塞接云中。\n勿使燕然上，惟留汉将功。'},
    {t:'送魏二',a:'王昌龄〔唐代〕',c:'醉别江楼橘柚香，江风引雨入舟凉。\n忆君遥在潇湘月，愁听清猿梦里长。'},
    {t:'送魏介之江西提点',a:'范仲淹〔宋代〕',c:'旌旗如火浪如鸥，一路春城次第游。\n江上高楼欲千尺，便從今日望归舟。'},
    {t:'送魏郡李太守赴任',a:'王维〔唐代〕',c:'与君伯氏别，又欲与君离。\n君行无几日，当复隔山陂。\n苍茫秦川尽，日落桃林塞。\n独树临关门，黄河向天外。\n前经洛阳陌，宛洛故人稀。\n故人离别尽，淇上转骖騑。\n企予悲送远，惆怅睢阳路。\n古木官渡平，秋城邺宫故。\n想君行县日，其出从如云。\n遥思魏公子，复忆李将军。'},
    {t:'送温初下第',a:'孟郊〔唐代〕',c:'日落浊水中，夜光谁能分。高怀无近趣，清抱多远闻。\n欲识丈夫志，心藏孤岳云。长安风尘别，咫尺不见君。'},
    {t:'送温处士归黄山白鹅峰旧居',a:'李白〔唐代〕',c:'黄山四千仞，三十二莲峰。\n丹崖夹石柱，菡萏金芙蓉。\n伊昔升绝顶，下窥天目松。\n仙人炼玉处，羽化留馀踪。\n亦闻温伯雪，独往今相逢。\n采秀辞五岳，攀岩历万重。\n归休白鹅岭，渴饮丹砂井。\n凤吹我时来，云车尔当整。\n去去陵阳东，行行芳桂丛。\n回溪十六度，碧嶂尽晴空。\n他日还相访，乘桥蹑彩虹。'},
    {t:'送文会上人还富阳',a:'皎然〔唐代〕',c:'悠悠渺渺属寒波，故寺思归意若何。\n长忆孤洲二三月，春山偏爱富春多。'},
    {t:'送吴安道学士知崇州',a:'范仲淹〔宋代〕',c:'一麾轻去奉兰羞，共惜清贤岂易求。\n筮易暗惊鸣鹤远，赋诗深望白驹留。\n古来经纬心皆晓，闲处光阴发半秋。\n长孺之才同吏隐，相宽频上海边楼。'},
    {t:'送吴炼师归王屋',a:'张籍〔唐代〕',c:'玉阳峰下学长生，玉洞仙中已尾名。独戴熊须冠暂出，\n唯将鹤尾扇同行。炼成云母休炊爨，已得雷公当吏兵。\n却到瑶坛上头宿，应闻空里步虚声。'},
    {t:'送吴十九往沅陵',a:'王昌龄〔唐代〕',c:'沅江流水到辰阳，溪口逢君驿路长。\n远谪谁知望雷雨，明年春水共还乡。'},
    {t:'送吴显道五首',a:'王安石〔宋代〕',c:'滕王高阁临江渚，东边日出西边雨。\n十五年前此会同，天际张帷列樽俎。\n公今此去何时归，我今停杯一问之。\n春风两岸水杨柳，昔日青青今在否。\n偶向东湖更向东，杏花两株能白红。\n落拓旧游应记得，插花走马月明中。\n荏苒荏苒瞻四海，明年花开复谁在。\n杏花杨柳年年好，南去北来人自老。\n少壮几时奈老何，与君把箸击盘歌。\n歌罢仰天叹，六龙忽蹉跎。\n跟中了了见乡国，自是不归归便得。\n欲往城南望城北，此心炯炯君应识。'},
    {t:'送吴宣从事',a:'孟浩然〔唐代〕',c:'才有幕中士，宁无塞上勋。\n汉兵将灭虏，王粲始从军。\n旌旆边庭去，山川地脉分。\n平生一匕首，感激赠夫君。'},
    {t:'送吴悦游韶阳',a:'孟浩然〔唐代〕',c:'五色怜凤雏，南飞适鹧鸪。楚人不相识，何处求椅梧。\n去去日千里，茫茫天一隅。安能与斥鷃，决起但枪榆。'},
    {t:'送梧州王使君',a:'张籍〔唐代〕',c:'楚江亭上秋风起，看发苍梧太守船。\n千里同行从此别，相逢又隔几多年。'},
    {t:'送五经赵随登科授广德尉',a:'韦应物〔唐代〕',c:'明经有清秩，当在石渠中。独往宣城郡，高斋谒谢公。\n寒原正芜漫，夕鸟自西东。秋日不堪别，凄凄多朔风。'},
    {t:'送席大',a:'孟浩然〔唐代〕',c:'惜尔怀其宝，迷邦倦客游。江山历全楚，河洛越成周。\n道路疲千里，乡园老一丘。知君命不偶，同病亦同忧。'},
    {t:'送洗然弟进士举',a:'孟浩然〔唐代〕',c:'献策金门去，承欢彩服违。以吾一日长，念尔聚星稀。\n昏定须温席，寒多未授衣。桂枝如已擢，早逐雁南飞。'},
    {t:'送闲师归江南',a:'张籍〔唐代〕',c:'遍住江南寺，随缘到上京。多生修律业，外学得诗名。\n讲殿偏追入，斋家别请行。青枫乡路远，几日尽归程。'},
    {t:'送襄州任别驾',a:'岑参〔唐代〕',c:'别乘向襄州，萧条楚地秋。江声官舍里，山色郡城头。\n莫羡黄公盖，须乘彦伯舟。高阳诸醉客，唯见古时丘。'},
    {t:'送项判官',a:'王安石〔宋代〕',c:'断芦洲渚落枫桥，渡口沙长过对潮。\n山鸟自呼泥滑滑，行人相对马萧萧。\n十年长自青衿识，千里来非白璧招。\n握手祝君能强饭，华簪常得从鸡翘。'},
    {t:'送萧判官赋得黄花戍',a:'高适〔唐代〕',c:'君不见黄花曲里黄，戍日萧萧带寒树。\n楼上篇临北斗星，门前直至西州路。\n每到瓜时更卒来，年年只对黄花戍。\n楼中几度哭明月，笛里何人吹落梅？\n多君莫不推才杰，欲奏平戎赴天阙。\n辕门杯酒别交亲，去去云霄羽翼新。\n知君马上貂裘暖，须念黄花久戍人。'},
    {t:'送萧十八与房侍御回还',a:'高适〔唐代〕',c:'常苦古人远，今见斯人古。澹泊遗声华，周旋必邹鲁。\n故交在梁宋，游方出庭户。匹马鸣朔风，一身济河浒。\n辛勤采兰咏，款曲翰林主。岁月催别离，庭闱远风土。\n寥寥寒烟静，莽莽夕阴吐。明发不在兹，青天眇难睹。'},
    {t:'送萧远弟',a:'张籍〔唐代〕',c:'街北槐花傍马垂，病身相送出门迟。\n与君别后秋风夜，作得新诗说向谁。'},
    {t:'送谢景初迁凭宰馀姚',a:'范仲淹〔宋代〕',c:'世德践甲科，青紫信可拾。\n故乡下荣辉，高门复树立。\n馀姚二山下，东南最名邑。\n烟水万人家，信信自翔集。\n又得贤大夫，坐堂恩信敷。\n春风为君来，绿波满平湖。\n乘兴访隐沦，今逢贺老无。\n文藻凌云处，定喜江山助。\n未能同仙舟，离樽少留驻。\n行行道不孤，明月相随去。'},
    {t:'送谢录事之越',a:'孟浩然〔唐代〕',c:'清旦江天迥，凉风西北吹。白云向吴会，征帆亦相随。\n想到耶溪日，应探禹穴奇。仙书倘相示，予在此山陲。'},
    {t:'送辛大不及①',a:'孟浩然〔唐代〕',c:'送君不相见，日暮独愁余。②\n江上空徘徊，天边迷处所。③\n郡邑经樊邓，山河入嵩汝。④\n蒲轮去渐遥，石径徒延伫。⑤'},
    {t:'送辛少府任乐安',a:'张籍〔唐代〕',c:'才多不肯浪容身，老大诗章转更新。\n选得天台山下住，一家全作学仙人。'},
    {t:'送新罗使',a:'张籍〔唐代〕',c:'万里为朝使，离家今几年。应知旧行路，却上远归船。\n夜泊避蛟窟，朝炊求岛泉。悠悠到乡国，远望海西天。'},
    {t:'送邢昂处士南游',a:'范仲淹〔宋代〕',c:'落落崆峒一大儒，四方心逸忆江湖。\n东南赖有林君复，万里清风去不孤。'},
    {t:'送邢桂州',a:'王维〔唐代〕',c:'铙吹喧京口，风波下洞庭。\n赭圻将赤岸，击汰复扬舲。\n日落江湖白，潮来天地青。\n明珠归合浦，应逐使臣星。'},
    {t:'送兄',a:'佚名〔唐代〕',c:'别路云初起，离亭叶正稀。\n所嗟人异雁，不作一行归。'},
    {t:'送徐登山人',a:'范仲淹〔宋代〕',c:'重君爱诗书，孜孜不知老。\n白发末理生，惟谈圣人道。\n爱君妙山水，所得是神气。\n尺素写林峦，邈有千里意。\n今日江南行，孤云无系程。\n直指九华峰，去扫先君茔。\n却来华阳川，与我溪上盟。\n行歌紫芝秀，坐啸清风生。\n练真变金骨，飘飘朝玉京。\n结成物外游，忘此天下情。'},
    {t:'送徐先生归蜀',a:'张籍〔唐代〕',c:'日暮远归处，云间仙观钟。唯持青玉牒，独立碧鸡峰。\n阴涧长收乳，寒泉旧养龙。几时因卖药，得向海边逢。'},
    {t:'送许处士',a:'张籍〔唐代〕',c:'高情自与俗人疏，独向蓝溪选僻居。\n会到白云长取醉，不能窗下读闲书。'},
    {t:'送许员外江外置常平仓',a:'岑参〔唐代〕',c:'诏置海陵仓，朝推画省郎。还家锦服贵，出使绣衣香。\n水驿风催舫，江楼月透床。仍怀陆氏橘，归献老亲尝。'},
    {t:'送玄亮师·一作送道友',a:'孟郊〔唐代〕',c:'兰泉涤我襟，杉月栖我心。茗啜绿净花，经诵清柔音。\n何处笑为别，淡情愁不侵。'},
    {t:'送薛播擢第归河东',a:'岑参〔唐代〕',c:'归去新战胜，盛名人共闻。乡连渭川树，家近条山云。\n夫子能好学，圣朝全用文。弟兄负世誉，词赋超人群。\n雨气醒别酒，城阴低暮曛。遥知出关后，更有一终军。'},
    {t:'送薛大赴安陆',a:'王昌龄〔唐代〕',c:'津头云雨暗湘山，迁客离忧楚地颜。\n遥送扁舟安陆郡，天边何处穆陵关。'},
    {t:'送薛种游湖南',a:'杜牧〔唐代〕',c:'贾傅松醪酒，秋来美更香。\n怜君片云思，一棹去潇湘。'},
    {t:'送颜平原',a:'岑参〔唐代〕',c:'天子念黎庶，诏书换诸侯。仙郎授剖符，华省辍分忧。\n置酒会前殿，赐钱若山丘。天章降三光，圣泽该九州。\n吾兄镇河朔，拜命宣皇猷。驷马辞国门，一星东北流。\n夏云照银印，暑雨随行輈。赤笔仍在箧，炉香惹衣裘。\n此地邻东溟，孤城吊沧洲。海风掣金戟，导吏呼鸣驺。\n郊原北连燕，剽劫风未休。鱼盐隘里巷，桑柘盈田畴。\n为郡岂淹旬，政成应未秋。易俗去猛虎，化人似驯鸥。\n苍生已望君，黄霸宁久留。'},
    {t:'送杨道士往天台',a:'张九龄〔唐代〕',c:'鬼谷还成道，天台去学仙。行应松子化，留与世人传。\n此地烟波远，何时羽驾旋。当须一把袂，城郭共依然。'},
    {t:'送杨府李功曹',a:'张九龄〔唐代〕',c:'平生属良友，结绶望光辉。\n何知人事拙，相与宦情非。\n别路穿林尽，征帆际海归。\n居然已多意，况复两乡违。'},
    {t:'送杨山人归嵩山',a:'李白〔唐代〕',c:'我有万古宅，嵩阳玉女峰。\n长留一片月，挂在东溪松。\n尔去掇仙草，菖蒲花紫茸。\n岁晚或相访，青天骑白龙。'},
    {t:'送杨山人归嵩阳',a:'高适〔唐代〕',c:'不到嵩阳动十年，旧时心事已徒然。\n一二故人不复见，三十六峰犹眼前。\n夷门二月柳条色，流莺数声泪沾臆。\n凿井耕田不我招，知君以此忘帝力。\n山人好去嵩阳路，惟余眷眷长相忆。'},
    {t:'送杨少府贬郴州',a:'王维〔唐代〕',c:'明到衡山与洞庭，若为秋月听猿声。\n愁看北渚三湘远，恶说南风五两轻。\n青草瘴时过夏口，白头浪里出湓城。\n长沙不久留才子，贾谊何须吊屈平。'},
    {t:'送杨少尹赴凤翔',a:'张籍〔唐代〕',c:'诗名往日动长安，首首人家卷拜看。西学已行秦博士，\n南宫新拜汉郎官。得钱只了还书铺，借宅常时事药栏。\n今去岐州生计薄，移居偏近陇头寒。'},
    {t:'送杨氏女',a:'韦应物〔唐代〕',c:'永日方戚戚，出行复悠悠。\n女子今有行，大江溯轻舟。\n尔辈苦无恃，抚念益慈柔。\n幼为长所育，两别泣不休。\n对此结中肠，义往难复留。\n自小阙内训，事姑贻我忧。\n赖兹托令门，任恤庶无尤。\n贫俭诚所尚，资从岂待周。\n孝恭遵妇道，容止顺其猷。\n别离在今晨，见尔当何秋。\n居闲始自遣，临感忽难收。\n归来视幼女，零泪缘缨流。'},
    {t:'送杨瑗尉南海',a:'岑参〔唐代〕',c:'不择南州尉，高堂有老亲。\n楼台重蜃气，邑里杂鲛人。\n海暗三山雨，花明五岭春。\n此乡多宝玉，慎莫厌清贫。'},
    {t:'送杨长史赴果州',a:'王维〔唐代〕',c:'褒斜不容幰，之子去何之。\n鸟道一千里，猿声十二时。\n官桥祭酒客，山木女郎祠。\n别后同明月，君应听子规。'},
    {t:'送姚评事入蜀各赋一物得卜肆',a:'张九龄〔唐代〕',c:'蜀严化已久，沉冥空所思。尝闻卖卜处，犹忆下帘时。\n驱传应经此，怀贤倘问之。归来说往事，历历偶心期。'},
    {t:'送姚司法归吴',a:'王昌龄〔唐代〕',c:'吴掾留觞楚郡心，洞庭秋雨海门阴。\n但令意远扁舟近，不道沧江百丈深。'},
    {t:'送殷大入蜀',a:'陈子昂〔唐代〕',c:'禺山金碧路，此地饶英灵。送君一为别，凄断故乡情。\n片云生极浦，斜日隐离亭。坐看征骑没，惟见远山青。'},
    {t:'送殷四葬·一作哭殷遥',a:'王维〔唐代〕',c:'送君返葬石楼山，松柏苍苍宾驭还。\n埋骨白云长已矣，空馀流水向人间。'},
    {t:'送殷秀才南游',a:'孟郊〔唐代〕',c:'诗句临离袂，酒花薰别颜。水程千里外，岸泊几宵间。\n风叶乱辞木，雪猿清叫山。南中多古事，咏遍始应还。'},
    {t:'送鄞江窦尉',a:'范仲淹〔宋代〕',c:'片帆飞去若轻鸿，一霎春潮过浙东。\n王谢江山久萧索，子真今为起清风。'},
    {t:'送隐者一绝',a:'杜牧〔唐代〕',c:'无媒径路草萧萧，自古云林远市朝。\n公道世间唯白发，贵人头上不曾饶。'},
    {t:'送友人',a:'李白〔唐代〕',c:'青山横北郭，白水绕东城。\n此地一为别，孤蓬万里征。\n浮云游子意，落日故人情。\n挥手自兹去，萧萧班马鸣。'},
    {t:'送友人',a:'杜牧〔唐代〕',c:'十载名兼利，人皆与命争。\n青春留不住，白发自然生。\n夜雨滴乡思，秋风从别情。\n都门五十里，驰马逐鸡声。'},
    {t:'送友人归山',a:'张籍〔唐代〕',c:'出山成北首，重去结茅庐。移石修废井，扫龛盛旧书。\n开田留杏树，分洞与僧居。长在幽峰里，樵人见亦疏。'},
    {t:'送友人南归',a:'王维〔唐代〕',c:'万里春应尽，三江雁亦稀。\n连天汉水广，孤客郢城归。\n郧国稻苗秀，楚人菰米肥。\n悬知倚门望，遥识老莱衣。'},
    {t:'送友人入蜀',a:'李白〔唐代〕',c:'见说蚕丛路，崎岖不易行。\n山从人面起，云傍马头生。\n芳树笼秦栈，春流绕蜀城。\n升沉应已定，不必问君平。'},
    {t:'送友人寻越中山水',a:'李白〔唐代〕',c:'闻道稽山去，偏宜谢客才。\n千岩泉洒落，万壑树萦回。\n东海横秦望，西陵绕越台。\n湖清霜镜晓，涛白雪山来。\n八月枚乘笔，三吴张翰杯。\n此中多逸兴，早晚向天台。'},
    {t:'送友人之京',a:'孟浩然〔唐代〕',c:'君登青云去，予望青山归。\n云山从此别，泪湿薜萝衣。'},
    {t:'送榆次林明府',a:'韦应物〔唐代〕',c:'无嗟千里远，亦是宰王畿。策马雨中去，逢人关外稀。\n邑传榆石在，路绕晋山微。别思方萧索，新秋一叶飞。'},
    {t:'送宇文舍人出宰元城·得阳字',a:'岑参〔唐代〕',c:'双凫出未央，千里过河阳。马带新行色，衣闻旧御香。\n县花迎墨绶，关柳拂铜章。别后能为政，相思淇水长。'},
    {t:'送宇文太守赴宣城',a:'王维〔唐代〕',c:'寥落云外山，迢遥舟中赏。\n铙吹发西江，秋空多清响。\n地迥古城芜，月明寒潮广。\n时赛敬亭神，复解罟师网。\n何处寄相思，南风吹五两。'},
    {t:'送元二使安西',a:'王维〔唐代〕',c:'渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。'},
    {t:'送元暠师诗',a:'柳宗元〔唐代〕',c:'侯门辞必服，忍位取悲增。\n去鲁心犹在，从周力未能。\n家山余五柳，人世遍千灯。\n莫让金钱施，无生道自弘。'},
    {t:'送元公之鄂渚，寻观主张骖鸾',a:'孟浩然〔唐代〕',c:'桃花春水涨，之子忽乘流。岘首辞蛟浦，江中问鹤楼。\n赠君青竹杖，送尔白蘋洲。应是神仙子，相期汗漫游。'},
    {t:'送元结',a:'张籍〔唐代〕',c:'昔日同游漳水边，如今重说恨绵绵。\n天涯相见还离别，客路秋风又几年。'},
    {t:'送袁十岭南寻弟',a:'孟浩然〔唐代〕',c:'早闻牛渚咏，今见鶺鴒心。\n羽翼嗟零落，悲鸣别故林。\n苍梧白云远，烟水洞庭深。\n万里独飞去，南风迟尔音。'},
    {t:'送袁太祝尉豫章',a:'孟浩然〔唐代〕',c:'何幸遇休明，观光来上京。相逢武陵客，独送豫章行。\n随牒牵黄绶，离群会墨卿。江南佳丽地，山水旧难名。'},
    {t:'送远',a:'杜甫〔唐代〕',c:'带甲满天地，胡为君远行！\n亲朋尽一哭，鞍马去孤城。\n草木岁月晚，关河霜雪清。\n别离已昨日，因见古人情。'},
    {t:'送远客',a:'张籍〔唐代〕',c:'憔悴远归客，殷勤欲别杯。九星坛下路，几日见重来。'},
    {t:'送远曲',a:'张籍〔唐代〕',c:'戏马台南山簇簇，山边饮酒歌别曲。\n行人醉后起登车，席上回尊向僮仆。\n青天漫漫复长路，远游无家安得住。\n愿君到处自题名，他日知君从此去。'},
    {t:'送远吟',a:'孟郊〔唐代〕',c:'河水昏复晨，河边相送频。离杯有泪饮，别柳无枝春。\n一笑忽然敛，万愁俄已新。东波与西日，不惜远行人。'},
    {t:'送越客',a:'张籍〔唐代〕',c:'见说孤帆去，东南到会稽。春云剡溪口，残月镜湖西。\n水鹤沙边立，山鼯竹里啼。谢家曾住处，烟洞入应迷。'},
    {t:'送张参明经举兼向泾州觐省',a:'孟浩然〔唐代〕',c:'十五彩衣年，承欢慈母前。\n孝廉因岁贡，怀橘向秦川。\n四座推文举，中郎许仲宣。\n泛舟江上别，谁不仰神仙。'},
    {t:'送张道士归山',a:'王维〔唐代〕',c:'先生何处去，王屋访茅君。\n别妇留丹诀，驱鸡入白云。\n人间若剩住，天上复离群。\n当作辽城鹤，仙歌使尔闻。'},
    {t:'送张都尉东归',a:'岑参〔唐代〕',c:'白羽绿弓弦，年年只在边。\n还家剑锋尽，出塞马蹄穿。\n逐虏西逾海，平胡北到天。\n封侯应不远，燕颔岂徒然。'},
    {t:'送张郎中迁京',a:'孟浩然〔唐代〕',c:'碧溪常共赏，朱邸忽迁荣。豫有相思意，闻君琴上声。'},
    {t:'送张明甫',a:'王安石〔宋代〕',c:'觥船一棹百分空，十五年前此会同。\n南去北来人自老，桃花依旧笑春风。'},
    {t:'送张判官赴河西',a:'王维〔唐代〕',c:'单车曾出塞，报国敢邀勋。\n见逐张征虏，今思霍冠军。\n沙平连白雪，蓬卷入黄云。\n慷慨倚长剑，高歌一送君。'},
    {t:'送张判官归兼谒鄂州大夫',a:'杜牧〔唐代〕',c:'处士闻名早，游秦献疏回。腹中书万卷，身外酒千杯。\n江雨春波阔，园林客梦催。今君拜旌戟，凛凛近霜台。'},
    {t:'送张舍人之江东',a:'李白〔唐代〕',c:'张翰江东去，正值秋风时。\n天清一雁远，海阔孤帆迟。\n白日行欲暮，沧波杳难期。\n吴洲如见月，千里幸相思。'},
    {t:'送张舍人佐江州同薛璩十韵',a:'王维〔唐代〕',c:'束带趋承明，守官唯谒者。\n清晨听银蚪，薄暮辞金马。\n受辞未尝易，当是方知寡。\n清范何风流，高文有风雅。\n忽佐江上州，当自浔阳下。\n逆旅到三湘，长途应百舍。\n香炉远峰出，石镜澄湖泻。\n董奉杏成林，陶潜菊盈把。\n范蠡常好之，庐山我心也。\n送君思远道，欲以数行洒。'},
    {t:'送张升卿宰新滏',a:'岑参〔唐代〕',c:'官柳叶尚小，长安春未浓。送君浔阳宰，把酒青门钟。\n水驿楚云冷，山城江树重。遥知南湖上，只对香炉峰。'},
    {t:'送张侍御秘书江左觐省',a:'韦应物〔唐代〕',c:'莫叹都门路，归无驷马车。绣衣犹在箧，芸阁已观书。\n沃野收红稻，长江钓白鱼。晨餐亦可荐，名利欲何如。'},
    {t:'送张四',a:'王昌龄〔唐代〕',c:'枫林已愁暮，楚水复堪悲。\n别后冷山月，清猿无断时。'},
    {t:'送张五归山',a:'王维〔唐代〕',c:'送君尽惆怅，复送何人归。\n几日同携手，一朝先拂衣。\n东山有茅屋，幸为扫荆扉。\n当亦谢官去，岂令心事违。'},
    {t:'送张五諲归宣城',a:'王维〔唐代〕',c:'五湖千万里，况复五湖西。\n渔浦南陵郭，人家春谷谿。\n欲归江淼淼，未到草萋萋。\n忆想兰陵镇，可宜猿更啼。'},
    {t:'送张献心充副使归河西杂句',a:'岑参〔唐代〕',c:'将门子弟君独贤，一从受命常在边。未至三十已高位，\n腰间金印色赭然。前日承恩白虎殿，归来见者谁不羡。\n箧中赐衣十重馀，案上军书十二卷。看君谋智若有神，\n爱君词句皆清新。澄湖万顷深见底，清冰一片光照人。\n云中昨夜使星动，西门驿楼出相送。玉瓶素蚁腊酒香，\n金鞭白马紫游缰。花门南，燕支北，张掖城头云正黑，\n送君一去天外忆。'},
    {t:'送张祥之房陵',a:'孟浩然〔唐代〕',c:'我家南渡头，惯习野人舟。日夕弄清浅，林湍逆上流。\n山河据形胜，天地生豪酋。君意在利往，知音期自投。'},
    {t:'送张孝廉赴举',a:'皎然〔唐代〕',c:'名在诸生右，家经见素风。春田休学稼，秋赋出儒宫。\n别路残云湿，离情晚桂丛。明年石渠署，应继叔孙通。'},
    {t:'送张瑶贬五溪尉',a:'高适〔唐代〕',c:'他日维桢干，明时悬镆铘。江山遥去国，妻子独还家。\n离别无嫌远，沈浮勿强嗟。南登有词赋，知尔吊长沙。'},
    {t:'送张彝归长沙',a:'皎然〔唐代〕',c:'早闻凌云彩，谓在鸳鹭俦。华发始相遇，沧江仍旅游。\n策名忘苟进，澹虑轻所求。常服远游诫，缅怀经世谋。\n片帆背风渚，万里还湘洲。别望荆云积，归心汉水流。\n兰苕行采采，桂棹思悠悠。宿昔无机者，为君动离忧。'},
    {t:'送张直公归南郑拜省',a:'岑参〔唐代〕',c:'夫子思何速，世人皆叹奇。\n万言不加点，七步犹嫌迟。\n对酒落日后，还家飞雪时。\n北堂应久待，乡梦促征期。'},
    {t:'送张子容进士赴举',a:'孟浩然〔唐代〕',c:'夕曛山照灭，送客出柴门。惆怅野中别，殷勤岐路言。\n茂林予偃息，乔木尔飞翻。无使谷风诮，须令友道存。'},
    {t:'送章八元秀才擢第往上都应制',a:'韦应物〔唐代〕',c:'决胜文场战已酣，行应辟命复才堪。旅食不辞游阙下，\n春衣未换报江南。天边宿鸟生归思，关外晴山满夕岚。\n立马欲从何处别，都门杨柳正毵毵。'},
    {t:'送赵都督赴代州得青字',a:'王维〔唐代〕',c:'天官动将星，汉上柳条青。\n万里鸣刁斗，三军出井陉。\n忘身辞凤阙，报国取龙庭。\n岂学书生辈，窗间老一经。'},
    {t:'送赵都护赴安西',a:'张九龄〔唐代〕',c:'将相有更践，简心良独难。远图序画地，超拜乃登坛。\n戎即昆山序，车同渤海单。义无中国费，情且远人安。\n他日文兼武，而今栗且宽。自然来月窟，何用刺楼兰。\n南至三冬晚，西驰万里寒。封侯自有处，征马去啴啴。'},
    {t:'送赵侍御归上都',a:'岑参〔唐代〕',c:'骢马五花毛，青云归处高。霜随驱夏暑，风逐振江涛。\n执简皆推直，勤王岂告劳。帝城谁不恋，回望动离骚。'},
    {t:'送真元二上人归吴中',a:'范仲淹〔宋代〕',c:'归心不可夺，千里故园春。\n及见市朝事，却思江海人。\n烟波方得伴，松月定为邻。\n愿结虎溪社，休休老此身。'},
    {t:'送臻师二首',a:'李商隐〔唐代〕',c:'昔去灵山非拂席，今来沧海欲人珠。\n楞伽顶上清凉地，善眼仙人忆我无。\n苦海迷途去未因，东方过此几微尘。\n何当百亿莲华上，一一莲华见佛身。'},
    {t:'送征衣·过韶阳',a:'柳永〔宋代〕',c:'过韶阳，璇枢电绕，华渚虹流，运应千载会昌。罄寰宇、荐殊祥。吾皇。诞弥月，瑶图缵庆，玉叶腾芳。并景贶、三灵眷祐，挺英哲、掩前王。遇年年、嘉节清和，颁率土称觞。\n无间要荒华夏，尽万里、走梯航。彤庭舜张大乐，禹会群方。鹓行。望上国，山呼鳌抃，遥爇炉香。竟就日、瞻云献寿，指南山、等无疆。愿巍巍、宝历鸿基，齐天地遥长。'},
    {t:'送郑端公弟移院常州',a:'韦应物〔唐代〕',c:'时瞻宪臣重，礼为内兄全。公程傥见责，私爱信不愆。\n况昔陪朝列，今兹俱海壖。清觞方对酌，天书忽告迁。\n岂徒咫尺地，使我心思绵。应当自此始，归拜云台前。'},
    {t:'送郑判官',a:'王昌龄〔唐代〕',c:'东楚吴山驿树微，轺车衔命奉恩辉。\n英僚携出新丰酒，半道遥看骢马归。'},
    {t:'送郑尚书出镇南海·各用来字',a:'张籍〔唐代〕',c:'远镇承新命，王程不假催。班行争路送，恩赐并时来。\n牙旆从城展，兵符到府开。蛮声喧夜市，海色浸潮台。\n画角天边月，寒关岭上梅。共知公望重，多是隔年回。'},
    {t:'送郑尚书赴广州',a:'张籍〔唐代〕',c:'圣朝选将持符节，内使宣时百管听。海北蛮夷来舞蹈，\n岭南封管送图经。白鹇飞绕迎官舫，红槿开当宴客亭。\n此处莫言多瘴疠，天边看取老人星。'},
    {t:'送郑侍御谪闽中',a:'高适〔唐代〕',c:'谪去君无恨，闽中我旧过。\n大都秋雁少，只是夜猿多。\n东路云山合，南天瘴疠和。\n自当逢雨露，行矣慎风波。'},
    {t:'送郑孝廉淮西觐省',a:'皎然〔唐代〕',c:'离袂翠华满，晨羞欲早行。春风生楚树，晓角发隋城。\n野霭湿衣彩，江鸿增客情。征途不用戒，坐见白波清。'},
    {t:'送郑秀才归宁',a:'张籍〔唐代〕',c:'桂楫彩为衣，行当令节归。夕潮迷浦远，昼雨见人稀。\n野芰到时熟，江鸥泊处飞。离琴一奏罢，山雨霭馀晖。'},
    {t:'送终',a:'韦应物〔唐代〕',c:'奄忽逾时节，日月获其良。萧萧车马悲，祖载发中堂。\n生平同此居，一旦异存亡。斯须亦何益，终复委山冈。\n行出国南门，南望郁苍苍。日入乃云造，恸哭宿风霜。\n晨迁俯玄庐，临诀但遑遑。方当永潜翳，仰视白日光。\n俯仰遽终毕，封树已荒凉。独留不得还，欲去结中肠。\n童稚知所失，啼号捉我裳。即事犹仓卒，岁月始难忘。'},
    {t:'送仲高兄宫学秩满赴行在',a:'陆游〔宋代〕',c:'兄去游东阁，才堪直北扉。\n莫忧持橐晚，姑记乞身归。\n道义无今古，功名有是非。\n临分出苦语，不敢计从违。'},
    {t:'送重钧上人游天台',a:'皎然〔唐代〕',c:'渐看华顶出，幽赏意随生。十里行松色，千重过水声。\n海容云正尽，山色雨初晴。事事将心证，知君道可成。'},
    {t:'送周子落第游荆南',a:'岑参〔唐代〕',c:'足下复不第，家贫寻故人。\n且倾湘南酒，羞对关西尘。\n山店橘花发，江城枫叶新。\n若从巫峡过，应见楚王神。'},
    {t:'送昼公联句',a:'皎然〔唐代〕',c:'相逢情不厌，惜别意难为。——韩章\n吾道应无住，前期未可知。——皎然\n轻霜凋古木，寒水缩荒陂。——韩章\n宾雁依沙屿，浮云惨路岐。——皎然\n林疏看野迥，岸转觉山移。——韩章\n寄赏惊摇落，归心叹别离。——皎然\n草堂思偃蹇，麈尾去相随。——顾况\n勿谓光阴远，禅房会一窥。——郑遨'},
    {t:'送朱大入秦',a:'孟浩然〔唐代〕',c:'游人五陵去，宝剑值千金。\n分手脱相赠，平生一片心。'},
    {t:'送朱庆馀及第归越',a:'张籍〔唐代〕',c:'东南归路远，几日到乡中。有寺山皆遍，无家水不通。\n湖声莲叶雨，野气稻花风。州县知名久，争邀与客同。'},
    {t:'送朱越',a:'王昌龄〔唐代〕',c:'远别舟中蒋山暮，君行举首燕城路。\n蓟门秋月隐黄云，期向金陵醉江树。'},
    {t:'送著作佐郎崔融等从梁王东征',a:'陈子昂〔唐代〕',c:'金天方肃杀，白露始专征。\n王师非乐战，之子慎佳兵。\n海气侵南部，边风扫北平。\n莫卖卢龙塞，归邀麟阁名。'},
    {t:'送子由使契丹',a:'苏轼〔宋代〕',c:'云海相望寄此身，那因远适更沾巾。\n不辞驿骑凌风雪，要使天骄识凤麟。\n沙漠回看清禁月，湖山应梦武林春。\n单于若问君家世，莫道中朝第一人。'},
    {t:'送梓州李使君',a:'王维〔唐代〕',c:'万壑树参天，千山响杜鹃。\n山中一夜雨，树杪百重泉。\n汉女输橦布，巴人讼芋田。\n文翁翻教授，不敢倚先贤。'},
    {t:'苏幕遮·怀旧',a:'范仲淹〔宋代〕',c:'碧云天，黄叶地，秋色连波，波上寒烟翠。山映斜阳天接水，芳草无情，更在斜阳外。\n黯乡魂，追旅思，夜夜除非，好梦留人睡。明月楼高休独倚，酒入愁肠，化作相思泪。'},
    {t:'苏幕遮·燎沉香',a:'周邦彦〔宋代〕',c:'燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。\n故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。'},
    {t:'苏秦',a:'王安石〔宋代〕',c:'已分将身死势权，恶名磨灭几何年。\n想君魂魄千秋後，却悔初无二顷田。'},
    {t:'苏侍郎紫薇庭各赋一物得芍药',a:'张九龄〔唐代〕',c:'仙禁生红药，微芳不自持。幸因清切地，还遇艳阳时。\n名见桐君箓，香闻郑国诗。孤根若可用，非直爱华滋。'},
    {t:'苏台览古',a:'李白〔唐代〕',c:'旧苑荒台杨柳新，菱歌清唱不胜春。\n只今惟有西江月，曾照吴王宫里人。'},
    {t:'苏武',a:'李白〔唐代〕',c:'苏武在匈奴，十年持汉节。\n白雁上林飞，空传一书札。\n牧羊边地苦，落日归心绝。\n渴饮月窟冰，饥餐天上雪。\n东还沙塞远，北怆河梁别。\n泣把李陵衣，相看泪成血。'},
    {t:'苏武庙',a:'温庭筠〔唐代〕',c:'苏武魂销汉使前，古祠高树两茫然。\n云边雁断胡天月，陇上羊归塞草烟。\n回日楼台非甲帐，去时冠剑是丁年。\n茂陵不见封侯印，空向秋波哭逝川。'},
    {t:'苏小小歌',a:'温庭筠〔唐代〕',c:'买莲莫破券，买酒莫解金。\n酒里春容抱离恨，水中莲子怀芳心。\n吴公女儿腰似束，家在钱唐小江曲。\n一自檀郎逐便风，门前春水年年绿。'},
    {t:'苏小小墓',a:'李贺〔唐代〕',c:'幽兰露，如啼眼。\n无物结同心，烟花不堪剪。\n草如茵，松如盖。\n风为裳，水为佩。\n油壁车，夕相待。\n冷翠烛，劳光彩。\n西陵下，风吹雨。'},
    {t:'苏州十咏其八·伍相庙',a:'范仲淹〔宋代〕',c:'胥也应无憾，至哉忠孝门。\n生能酬楚怨，死可报吴恩。\n直气海涛在，片心江月存。\n悠悠当日者，千载祗惭魂。'},
    {t:'苏州十咏其二·木兰堂',a:'范仲淹〔宋代〕',c:'堂上列歌锺，多惭不如古。\n却羡木兰花，曾见霓裳舞。'},
    {t:'苏州十咏其二木兰堂',a:'范仲淹〔宋代〕',c:'堂上列歌钟，多惭不如古。却羡木兰花，曾见霓裳舞。'},
    {t:'苏州十咏其九·观风楼',a:'范仲淹〔宋代〕',c:'高压郡西城，观风不浪名。\n山川千里色，语笑万家声。\n碧寺烟中静，红桥柳际明。\n登临岂刘白，满目见诗情。'},
    {t:'苏州十咏其六·灵岩寺',a:'范仲淹〔宋代〕',c:'古来兴废一愁人，白发僧归掩阙门。\n越相烟波空去雁，吴王宫阙半啼猿。\n春风似旧花犹笑，往事多遗石不言。\n唯有延陵逃遁去，清名高节老干坤。'},
    {t:'苏州十咏其七·太湖',a:'范仲淹〔宋代〕',c:'有浪即山高，无风还练静。\n秋宵谁与期，月华三万顷。'},
    {t:'苏州十咏其三·洞庭山',a:'范仲淹〔宋代〕',c:'吴山无此秀，乘暇一游之。\n万顷湖光里，千家橘熟时。\n平看月上早，远觉鸟归迟。\n近古谁真赏，白云应得知。'},
    {t:'苏州十咏其十·南园',a:'范仲淹〔宋代〕',c:'西施台下见名园，百草千花特地繁。\n欲问吴王当日事，后来桃李若为言。'},
    {t:'苏州十咏其四·虎丘山',a:'范仲淹〔宋代〕',c:'昔见虎耽耽，今为佛子岩。\n云寒不出寺，剑静未离潭。\n幽步萝垂径，高禅雪闭庵。\n吴都十万户，烟瓦亘西南。'},
    {t:'苏州十咏其五·阊门',a:'范仲淹〔宋代〕',c:'吴门耸阊阖，迎送每跻攀。\n一水帝乡路，片云师子山。\n落鸿渔钓外，斜柳别离间。\n白傅归休处，盘桓几厚颜。'},
    {t:'苏州十咏其一·泰伯庙',a:'范仲淹〔宋代〕',c:'至德本无名，宣尼一此凭。\n能将天下让，知有圣人生。\n南国奔方远，西山道始亨。\n英灵岂不在，千古碧江横。'},
    {t:'夙兴',a:'周邦彦〔宋代〕',c:'曈曈海底日，赤辉射东方。\n先驱第群翳，微露不成霜。\n早寤厌床第，起步东西厢。\n引手视掌纹，跧跧未可祥。\n念此阅人传，三年得跧藏。\n弛担曾几时，兹焉忽腾装。\n问今何所之，意行本无乡。\n晨钟神惨悲，夜鼓思飞扬。\n与俗同一科，何异犬与羊。\n平明催放钥，利害纷相攘。\n颠倒走群愚，岂但渠可伤。'},
    {t:'诉衷情',a:'黄庭坚〔宋代〕',c:'珠帘绣幕卷轻霜。呵手试梅妆。都缘自有离恨，故画作、远山长。\n思往事，惜流光恨难忘。未歌先敛，欲笑还颦。最断人肠。'},
    {t:'诉衷情',a:'周邦彦〔宋代〕',c:'当时选舞万人长。玉带小排方。喧传京国声价，年少最无量。\n花阁迥，酒筵香。想难忘。而今何事，佯向人前，不认周郎。'},
    {t:'诉衷情',a:'晏几道〔宋代〕',c:'都人离恨满歌筵。清唱倚危弦。星屏别后千里，更见是何年。\n骢骑稳。绣衣鲜，欲朝天。北人欢笑，南国悲凉，迎送金鞭。'},
    {t:'诉衷情',a:'晏几道〔宋代〕',c:'长因蕙草记罗裙。绿腰沈水熏。阑干曲处人静，曾共倚黄昏。\n风有韵，月无痕。暗消魂。拟将幽恨，试写残花，寄与朝云。'},
    {t:'诉衷情·出林杏子落金盘',a:'周邦彦〔宋代〕',c:'出林杏子落金盘。齿软怕尝酸。可惜半残青紫，犹印小唇丹。\n南陌上，落花闲。雨斑斑。不言不语，一段伤春，都在眉间。'},
    {t:'诉衷情·当年万里觅封侯',a:'陆游〔宋代〕',c:'当年万里觅封侯，匹马戍梁州。关河梦断何处？尘暗旧貂裘。\n胡未灭，鬓先秋，泪空流。此生谁料，心在天山，身老沧洲。'},
    {t:'诉衷情·东风杨柳欲青青',a:'晏殊〔宋代〕',c:'东风杨柳欲青青。烟淡雨初晴。恼他香阁浓睡，撩乱有啼莺。\n眉叶细，舞腰轻。宿妆成。一春芳意，三月和风，牵系人情。'},
    {t:'诉衷情·芙蓉金菊斗馨香',a:'晏殊〔宋代〕',c:'芙蓉金菊斗馨香。天气欲重阳。远村秋色如画，红树间疏黄。\n流水淡，碧天长。路茫茫。凭高目断。鸿雁来时，无限思量。'},
    {t:'诉衷情·海棠珠缀一重重',a:'晏殊〔宋代〕',c:'海棠珠缀一重重。清晓近帘栊。胭脂谁与匀淡，偏向脸边浓。\n看叶嫩，惜花红。意无穷。如花似叶，岁岁年年，共占春风。'},
    {t:'诉衷情·净揩妆脸浅眉',a:'晏几道〔宋代〕',c:'净揩妆脸浅眉，\n衫子素梅儿。\n苦无心绪梳洗，\n闲淡也相宜。\n云态度，柳腰肢，入相思。\n夜来月底，今日尊前，\n未当佳期。'},
    {t:'诉衷情·冷落绣衾谁与伴',a:'纳兰性德〔清代〕',c:'冷落绣衾谁与伴？倚香篝。春睡起，斜日照梳头。欲写两眉愁，休休。远山残翠收，莫登楼。'},
    {t:'诉衷情·林钟商',a:'柳永〔宋代〕',c:'一声画角日西曛。催促掩朱门。渐堪更倚危阑，肠断已消魂。\n年渐晚，雁空频。问无因。思心欲碎，愁泪难收，又是黄昏。'},
    {t:'诉衷情·露莲双脸远山眉',a:'晏殊〔宋代〕',c:'露莲双脸远山眉，偏与淡妆宜。别庭帘幕春晚，闲共柳丝垂。\n人别后，月圆时，信迟迟。心心念念，说尽无凭，只是相思。'},
    {t:'诉衷情·琵琶女',a:'苏轼〔宋代〕',c:'小莲初上琵琶弦，弹破碧云天。分明绣阁幽恨，都向曲中传。\n肤莹玉，鬓梳蝉，绮窗前。素娥今夜，故故随人，似斗婵娟。'},
    {t:'诉衷情·凭觞静忆去年秋',a:'晏几道〔宋代〕',c:'凭觞静忆去年秋，桐落故溪头。诗成自写红叶，和恨寄东流。\n人脉脉，水悠悠。几多愁。雁书不到，蝶梦无凭，漫倚高楼。'},
    {t:'诉衷情·青梅煮酒斗时新',a:'晏殊〔宋代〕',c:'青梅煮酒斗时新。天气欲残春。东城南陌花下，逢著意中人。\n回绣袂，展香茵。叙情亲。此情拚作，千尺游丝，惹住朝云。'},
    {t:'诉衷情·青衫初入九重城',a:'陆游〔宋代〕',c:'青衫初入九重城，结友尽豪英。易封夜半传檄，驰骑谕幽并。\n时易失，志难成，鬓丝生。平章风月，弹压江山，别是功名。'},
    {t:'诉衷情·秋风吹绽北池莲',a:'晏殊〔宋代〕',c:'秋风吹绽北池莲，曙云楼阁鲜。画堂今日嘉会，齐拜玉炉烟。\n斟美酒，祝芳筵，奉觥船。宜春耐夏，多福庄严，富贵长年。'},
    {t:'诉衷情·商调',a:'周邦彦〔宋代〕',c:'堤前亭午未融霜。风紧雁无行。重寻旧日岐路，茸帽北游装。\n期信杳，别离长。远情伤。风翻酒幔，寒凝茶烟，又是何乡。'},
    {t:'诉衷情·世间荣贵月中人',a:'晏殊〔宋代〕',c:'世间荣贵月中人，嘉庆在今辰。兰堂帘幕高卷，清唱遏行云。\n持玉盏，敛红巾，祝千春。榴花寿酒，金鸭炉香，岁岁长新。'},
    {t:'诉衷情·寿',a:'晏殊〔宋代〕',c:'幕天席地斗豪奢，歌妓捧红牙。载他醉醒醒醉，斜插满头花。\n车载酒，解貂贳，尽繁华。儿孙贤俊，家道荣昌，祝寿无涯。'},
    {t:'诉衷情·数枝金菊对芙蓉',a:'晏殊〔宋代〕',c:'数枝金菊对芙蓉，摇落意重重。不知多少幽怨，和露泣西风。\n人散后，月明中，夜寒浓。谢娘愁卧，潘令闲眠，心事无穷。'},
    {t:'诉衷情·送述古迓元素',a:'苏轼〔宋代〕',c:'钱塘风景古来奇，太守例能诗。尽驱负弩何在，心已誓江西。\n花尽后，叶飞时。雨凄凄。若为情绪，更问新官，向旧官啼。'},
    {t:'诉衷情·五之三',a:'王安石〔宋代〕',c:'茫然不肯住林间。有处即追攀。将他死语图度，怎得离真丹。\n浆水价，匹如闲。也须还。何如直截，踢倒军持，赢取沩山。'},
    {t:'诉衷情·五之四',a:'王安石〔宋代〕',c:'营巢燕子逞翱翔。微志在雕梁。碧云举翮千里，其奈有鸾皇。\n临济处，德山行。果承当。自时降住，一切天魔，扫地焚香。'},
    {t:'诉衷情·小梅风韵最妖娆',a:'晏几道〔宋代〕',c:'小梅风韵最妖娆。开处雪初消。南枝欲附春信，长恨陇人遥。\n闲记忆，旧江皋。路迢迢。暗香浮动，疏影横斜，几处溪桥。'},
    {t:'诉衷情·小桃灼灼柳鬖鬖',a:'黄庭坚〔宋代〕',c:'小桃灼灼柳鬖鬖，春色满江南。泼晴风暖烟淡，天气正醺酣。\n山泼黛，水挼蓝，翠相搀。歌楼酒旆，故故招人，权典青衫。'},
    {t:'诉衷情·喧天丝竹韵融融',a:'晏殊〔宋代〕',c:'喧天丝竹韵融融，歌唱画堂中。玲女世间希有，烛影夜摇红。\n一同笑，饮千钟，兴何穷。功成名遂，富足年康，祝寿如松。'},
    {t:'诉衷情·一波才动万波随',a:'黄庭坚〔宋代〕',c:'戎州登临胜景，未尝不歌渔父家风，以谢江山。门生请问：先生家风如何？为拟金华道人作此丝。\n一波才动万波随，蓑笠一钩丝。金鳞正在深处，千尺也须垂。\n吞又吐，信还疑，上钩迟。水寒江静，满目青山，载月明归。'},
    {t:'诉衷情·一声画角日四曛',a:'柳永〔宋代〕',c:'一声画角日四曛。催促掩朱门。渐堪更倚危阑，肠断已消\n魂。\n年渐晚，雁空频。问无因。思心欲碎，愁泪难收，又是黄\n昏。'},
    {t:'诉衷情·莺语',a:'温庭筠〔唐代〕',c:'莺语，花舞，春昼午，雨霏微。金带枕，宫锦，凤凰帷。\n柳弱蝶交飞，依依。辽阳音信稀，梦中归。'},
    {t:'诉衷情·御纱新制石榴裙',a:'晏几道〔宋代〕',c:'御纱新制石榴裙，\n沉香慢火熏。\n锦罗双带宫样，\n飞鹭碧波纹。\n随锦字，叠香痕，寄文君。\n系来花下，解向尊前，\n谁伴朝云。'},
    {t:'诉衷情·长因蕙草记罗裙',a:'晏几道〔宋代〕',c:'长因蕙草记罗裙，\n绿腰沉水熏。\n栏干曲处人静，\n曾共倚黄昏。\n风有韵，月无痕，暗消魂。\n拟将幽恨，试写残花，\n寄与朝云。'},
    {t:'诉衷情·长因蕙草忆罗裙',a:'晏几道〔宋代〕',c:'长因蕙草忆罗裙\n绿腰沉水熏\n阑干曲处人静\n曾共倚黄昏\n风有韵，月无痕\n暗消魂\n拟将幽恨\n试写残花\n寄与朝云'},
    {t:'诉衷情·种花人自蕊宫来',a:'晏几道〔宋代〕',c:'种花人自蕊宫来，\n牵衣问小梅。\n寄年芳意何似，\n应向旧枝开。\n凭寄语，谢瑶台，客无才。\n粉香传信，玉盏开筵，\n莫待春回。'},
    {t:'诉衷情·渚莲霜晓坠残红',a:'晏几道〔宋代〕',c:'渚莲霜晓坠残红，\n依约旧秋同。\n去人团扇恩浅，\n一意恨西风。\n云去住，月朦胧，夜寒浓。\n此时还是，泪墨书成，\n未有归鸿。'},
    {t:'诉衷情近·二之二·林钟商',a:'柳永〔宋代〕',c:'景阑昼永，渐入清和气序。榆钱飘满闲阶，莲叶嫩生翠沼。遥望水边幽径，山崦孤村，是处园林好。\n闲情悄。绮陌游人渐少。少年风韵，自觉随春老。追前好。帝城信阻，天涯目断，暮云芳草。伫立空残照。'},
    {t:'诉衷情近·雨晴气爽',a:'柳永〔宋代〕',c:'雨晴气爽，伫立江楼望处。澄明断水生光，重叠暮山耸翠。遥认断桥幽径，隐隐渔村，向晚孤烟情。\n残阳里。脉脉朱阑静倚。黯然情绪，未饮先如醉。愁无际。暮云过了，秋光老尽，故人千里。竟日空凝睇。'},
    {t:'素上人影塔',a:'王昌龄〔唐代〕',c:'物化同枯木，希夷明月珠。本来生灭尽，何者是虚无。\n一坐看如故，千龄独向隅。至人非别有，方外不应殊。'},
    {t:'宿灞上寄侍御玙弟·其三',a:'王昌龄〔唐代〕',c:'吾宗秉全璞，楚得璆琳最。\n茅山就一征，柏署起三载。'},
    {t:'宿城南亡友别墅',a:'温庭筠〔唐代〕',c:'水流花落叹浮生，又伴游人宿杜城。\n还似昔年残梦里，透帘斜月独闻莺。'},
    {t:'宿道士观',a:'皎然〔唐代〕',c:'古观秋木秀，冷然属鲜飙。琼葩被修蔓，柏实满寒条。\n影殿山寂寂，寥天月昭昭。幽期寄仙侣，习定至中宵。\n清佩闻虚步，真官方宿朝。'},
    {t:'宿法华寺简灵澈上人',a:'皎然〔唐代〕',c:'至道无机但杳冥，孤灯寒竹自青荧。\n不知何处小乘客，一夜风来闻诵经。'},
    {t:'宿沣曲僧舍',a:'温庭筠〔唐代〕',c:'东郊和气新，芳霭远如尘。客舍停疲马，僧墙画故人。\n沃田桑景晚，平野菜花春。更想严家濑，微风荡白蘋。'},
    {t:'宿府',a:'杜甫〔唐代〕',c:'清秋幕府井梧寒，独宿江城蜡炬残。\n永夜角声悲自语，中天月色好谁看。\n风尘荏苒音书绝，关塞萧条行路难。\n已忍伶俜十年事，强移栖息一枝安。'},
    {t:'宿广德寺寄从舅',a:'张籍〔唐代〕',c:'古寺客堂空，开帘四面风。移床动栖鹤，停烛聚飞虫。\n闲卧逐凉处，远愁生静中。林西微月色，思与宁家同。'},
    {t:'宿湖中',a:'白居易〔唐代〕',c:'水天向晚碧沉沉，树影霞光重橘深。\n浸月冷波千顷练，苞霜新橘万株金。\n幸无案牍何妨醉，纵有笙歌不废吟。\n十只画船何处宿，洞庭山脚太湖心。'},
    {t:'宿黄山',a:'黄庭坚〔宋代〕',c:'平时游此每雍容，掩袂今来对晚风。\n白首同归人不见，黄山依旧月明中。'},
    {t:'宿建德江',a:'孟浩然〔唐代〕',c:'移舟泊烟渚，日暮客愁新。\n野旷天低树，江清月近人。'},
    {t:'宿江边阁',a:'杜甫〔唐代〕',c:'暝色延山径，高斋次水门。\n薄云岩际宿，孤月浪中翻。\n鹳鹤追飞静，豺狼得食喧。\n不眠忧战伐，无力正乾坤。'},
    {t:'宿江店',a:'张籍〔唐代〕',c:'野店临西浦，门前有橘花。\n停灯待贾客，卖酒与渔家。\n夜静江水白，路回山月斜。\n闲寻泊船处，潮落见平沙。'},
    {t:'宿金山',a:'秦观〔宋代〕',c:'山南山北江水流，半空金碧随寒浮。我来仍值风日好，十月未寒如晚秋。\n山僧引客寻苍翠，历清参差到平地。万里风来拂骨清，却忆人间如梦寐。\n夜深无风月入扉，相对老人如槁枝。流水与天争入海，共笑此心谁得知。\n下山却向中𤃩望，番忆当时在屏幛。老母思儿且欲归，回首寒峰已天上。'},
    {t:'宿晋昌亭闻惊禽',a:'李商隐〔唐代〕',c:'羁绪鳏鳏夜景侵，高窗不掩见塘禽。\n飞来曲渚烟方合，过尽南塘树更深。\n胡马嘶和榆塞笛，楚猿吟杂橘村砧。\n失群挂木知何限，远隔天涯共此心。'},
    {t:'宿京江口期刘昚虚不至',a:'王昌龄〔唐代〕',c:'霜天起长望，残月生海门。风静夜潮满，城高寒气昏。\n故人何寂寞，久已乖清言。明发不能寐，徒盈江上尊。'},
    {t:'宿旧彭泽怀陶令',a:'黄庭坚〔宋代〕',c:'潜鱼愿深渺，渊明无由逃。\n彭泽当此时，沉冥一世豪。\n司马寒如灰，礼乐卯金刀。\n岁晚以字行，更始号元亮。\n凄其望诸葛，肮脏犹汉相。\n时无益州牧，指挥用诸将。\n平生本朝心，岁月阅江浪。\n空余时语工，落笔九天上。\n向来非无人，此友独可尚。\n属予刚制酒，无用酌杯盎。\n欲招千载魂，斯文或宜当。'},
    {t:'宿空舲峡青树村浦',a:'陈子昂〔唐代〕',c:'的的明月水，啾啾寒夜猿。客思浩方乱，洲浦寂无喧。\n忆作千金子，宁知九逝魂。虚闻事朱阙，结绶骛华轩。\n委别高堂爱，窥觎明主恩。今成转蓬去，叹息复何言。'},
    {t:'宿立公房',a:'孟浩然〔唐代〕',c:'支遁初求道，深公笑买山。何如石岩趣，自入户庭间。\n苔涧春泉满，萝轩夜月闲。能令许玄度，吟卧不知还。'},
    {t:'宿灵鹫禅寺',a:'杨万里〔宋代〕',c:'初疑夜雨忽朝晴，乃是山泉终夜鸣。\n流到前溪无半语，在山做得许多声。'},
    {t:'宿灵仙观',a:'周邦彦〔宋代〕',c:'灵宫耽耽虎守谷，羽褐出山邀客宿。\n稽首中茅司命君，四叶秉符调玉烛。\n鸣金击石天相闻，游飙倒影声磷磷。\n戏上云崖撼琼树，脱叶出溪惊世人。'},
    {t:'宿龙宫滩',a:'韩愈〔唐代〕',c:'浩浩复汤汤，滩声抑更扬。\n奔流疑激电，惊浪似浮霜。\n梦觉灯生晕，宵残雨送凉。\n如何连晓语，只是说家乡？'},
    {t:'宿骆氏亭寄怀崔雍崔衮',a:'李商隐〔唐代〕',c:'竹坞无尘水槛清，相思迢递隔重城。\n秋阴不散霜飞晚，留得枯荷听雨声。'},
    {t:'宿裴氏山庄',a:'王昌龄〔唐代〕',c:'苍苍竹林暮，吾亦知所投。静坐山斋月，清溪闻远流。\n西峰下微雨，向晓白云收。遂解尘中组，终南春可游。'},
    {t:'宿蒲关东店，忆杜陵别业',a:'岑参〔唐代〕',c:'关门锁归客，一夜梦还家。月落河上晓，遥闻秦树鸦。\n长安二月归正好，杜陵树边纯是花。'},
    {t:'宿山祠·一作宫山祠',a:'张籍〔唐代〕',c:'秋草宫人斜里墓，宫人谁送葬来时。\n千千万万皆如此，家在边城亦不知。'},
    {t:'宿山寺寄李中丞洪',a:'皎然〔唐代〕',c:'偶来中峰宿，闲坐见真境。寂寂始月心，亭亭圆泉影。\n□□□满山，花落始知静。从他半夜愁猿惊，\n不废此心长杳冥。'},
    {t:'宿天台桐柏观',a:'孟浩然〔唐代〕',c:'海行信风帆，夕宿逗云岛。\n缅寻沧洲趣，近爱赤城好。\n扪萝亦践苔，辍棹恣探讨。\n息阴憩桐柏，采秀弄芝草。\n鹤唳清露垂，鸡鸣信潮早。\n愿言解缨络，从此去烦恼。\n高步陵四明，玄踪得二老。\n纷吾远游意，乐彼长生道。\n日夕望三山，云涛空浩浩。'},
    {t:'宿天竺寺，寄灵隐寺僧',a:'张籍〔唐代〕',c:'夜向灵溪息此身，风泉竹露净衣尘。\n月明石上堪同宿，那作山南山北人。'},
    {t:'宿铁关西馆',a:'岑参〔唐代〕',c:'马汗踏成泥，朝驰几万蹄。\n雪中行地角，火处宿天倪。\n塞迥心常怯，乡遥梦亦迷。\n那知故园月，也到铁关西。'},
    {t:'宿桐庐江寄广陵旧游',a:'孟浩然〔唐代〕',c:'山暝听猿愁，沧江急夜流。\n风鸣两岸叶，月照一孤舟。\n建德非吾土，维扬忆旧游。\n还将两行泪，遥寄海西头。'},
    {t:'宿巫山下',a:'李白〔唐代〕',c:'昨夜巫山下，猿声梦里长。\n桃花飞绿水，三月下瞿塘。\n雨色风吹去，南行拂楚王。\n高丘怀宋玉，访古一沾裳。'},
    {t:'宿五松山下荀媪家',a:'李白〔唐代〕',c:'我宿五松下，寂寥无所欢。\n田家秋作苦，邻女夜舂寒。\n跪进雕胡饭，月光明素盘。\n令人惭漂母，三谢不能餐。'},
    {t:'宿武阳即事·一作宿武阳川',a:'孟浩然〔唐代〕',c:'川暗夕阳尽，孤舟泊岸初。岭猿相叫啸，潭嶂似空虚。\n就枕灭明烛，扣舷闻夜渔。鸡鸣问何处，人物是秦馀。'},
    {t:'宿襄河驿浦',a:'陈子昂〔唐代〕',c:'沿流辞北渚，结缆宿南洲。合岸断初夕，回塘暗不流。\n卧闻塞鸿断，坐听峡猿愁。沙浦明如月，汀葭晦若秋。\n不及能鸣雁，徒思海上鸥。天河殊未晓，沧海信悠悠。'},
    {t:'宿新市徐公店',a:'杨万里〔宋代〕',c:'篱落疏疏一径深，树头新绿未成阴。\n儿童急走追黄蝶，飞入菜花无处寻。'},
    {t:'宿新市徐公店二首·其一',a:'杨万里〔宋代〕',c:'春光都在柳梢头，拣折长条插酒楼。\n便作在家寒食看，村歌社舞更风流。'},
    {t:'宿扬子津，寄润州长山刘隐士',a:'孟浩然〔唐代〕',c:'所思在建业，欲往大江深。日夕望京口，烟波愁我心。\n心驰茅山洞，目极枫树林。不见少微星，星霜劳夜吟。'},
    {t:'宿业师山房期丁大不至',a:'孟浩然〔唐代〕',c:'夕阳度西岭，群壑倏已暝。\n松月生夜凉，风泉满清听。\n樵人归欲尽，烟鸟栖初定。\n之子期宿来，孤琴候萝径。'},
    {t:'宿一公精舍',a:'温庭筠〔唐代〕',c:'夜阑黄叶寺，瓶锡两俱能。松下石桥路，雨中山殿灯。\n茶炉天姥客，棋席剡溪僧。还笑长门赋，高秋卧茂陵。'},
    {t:'宿永嘉江寄山阴崔少府国辅',a:'孟浩然〔唐代〕',c:'我行穷水国，君使入京华。\n相去日千里，孤帆天一涯。\n卧闻海潮至，起视江月斜。\n借问同舟客，何时到永嘉。'},
    {t:'宿永阳寄璨律师',a:'韦应物〔唐代〕',c:'遥知郡斋夜，冻雪封松竹。时有山僧来，悬灯独自宿。'},
    {t:'宿云际寺',a:'温庭筠〔唐代〕',c:'白盖微云一径深，东峰弟子远相寻。\n苍苔路熟僧归寺，红叶声干鹿在林。\n高阁清香生静境，夜堂疏磬发禅心。\n自从紫桂岩前别，不见南能直到今。'},
    {t:'宿赞公房',a:'杜甫〔唐代〕',c:'杖锡何来此，秋风已飒然。\n雨荒深院菊，霜倒半池莲。\n放逐宁违性，虚空不离禅。\n相逢成夜宿，陇月向人圆。'},
    {t:'宿郑州',a:'王维〔唐代〕',c:'朝与周人辞，暮投郑人宿。\n他乡绝俦侣，孤客亲僮仆。\n宛洛望不见，秋霖晦平陆。\n田父草际归，村童雨中牧。\n主人东皋上，时稼绕茅屋。\n虫思机杼鸣，雀喧禾黍熟。\n明当渡京水，昨晚犹金谷。\n此去欲何言，穷边徇微禄。'},
    {t:'宿支硎寺上房',a:'皎然〔唐代〕',c:'上方精舍远，共宿白云端。寂寞千峰夜，萧条万木寒。\n山光霜下见，松色月中看。却与西林别，归心即欲阑。'},
    {t:'宿紫阁山北村',a:'白居易〔唐代〕',c:'晨游紫阁峰，暮宿山下村。\n村老饮余喜，为余开一尊。\n举杯未及饮，暴卒来入门。\n紫衣挟刀斧，中中十余人。\n夺我席上酒，掣我盘中飧。\n主人退后立，敛手反如宾。\n中庭有奇树，种来三十春。\n主人惜不得，持斧断其根。\n口称采造家，身属神策军。\n“主人慎勿语，中尉正承恩！”'},
    {t:'宿醉',a:'元稹〔唐代〕',c:'风引春心不自由，等闲冲席饮多筹。\n朝来始向花前觉，度却醒时一夜愁。'},
    {t:'溯江至武昌',a:'孟浩然〔唐代〕',c:'家本洞湖上，岁时归思催。客心徒欲速，江路苦邅回。\n残冻因风解，新正度腊开。行看武昌柳，仿佛映楼台。'},
    {t:'睢阳感怀',a:'韦应物〔唐代〕',c:'豺虎犯天纲，升平无内备。长驱阴山卒，略践三河地。\n张侯本忠烈，济世有深智。坚壁梁宋间，远筹吴楚利。\n穷年方绝输，邻援皆携贰。使者哭其庭，救兵终不至。\n重围虽可越，藩翰谅难弃。饥喉待危巢，悬命中路坠。\n甘从锋刃毙，莫夺坚贞志。宿将降贼庭，儒生独全义。\n空城唯白骨，同往无贱贵。哀哉岂独今，千载当歔欷。'},
    {t:'睢阳学舍书怀',a:'范仲淹〔宋代〕',c:'白云无赖帝乡遥，汉苑谁人奏可箫。\n多难未应歌凤鸟，薄才犹可赋鹪鹩。\n瓢思颜子心还乐，琴遇钟君恨即销。\n但使斯文天未丧，涧松何必怨山苗。'},
    {t:'隋堤柳',a:'杜牧〔唐代〕',c:'夹岸垂杨三百里，只应图画最相宜。\n自嫌流落西归疾，不见东风二月时。'},
    {t:'隋宫',a:'李商隐〔唐代〕',c:'紫泉宫殿锁烟霞，欲取芜城作是家。\n玉玺不缘归日角，锦帆应是到天涯。\n于今腐草无萤火，终古垂杨有暮鸦。\n地下若逢陈后主，岂宜重问后庭花。'},
    {t:'隋宫春',a:'杜牧〔唐代〕',c:'龙舟东下事成空，蔓草萋萋满故宫。\n亡国亡家为颜色，露桃犹自恨春风。'},
    {t:'隋宫守岁',a:'李商隐〔唐代〕',c:'消息东郊木帝回，宫中行乐有新梅。\n沈香甲煎为庭燎，玉液琼苏作寿杯。\n遥望露盘疑是月，远闻鼍鼓欲惊雷。\n昭阳第一倾城客，不踏金莲不肯来。'},
    {t:'隋故太原王夫人墓志铭',a:'佚名〔隋代〕',c:'屹然孤坟，南阜之墩。殒我慈母，苍天不仁。涧水夜流，松烟昼昏。\n□□涟洏，暮暮晨晨。'},
    {t:'随师东',a:'李商隐〔唐代〕',c:'东征日调万黄金，几竭中原买是心。\n军令未闻诛马谡，捷书惟是报孙歆。\n但须鸑鷟巢阿阁，岂假鸱鸮在泮林。\n可惜前朝玄菟郡，积骸成莽阵云深。'},
    {t:'岁初巡属县，登高安南楼言怀',a:'张九龄〔唐代〕',c:'山城本孤峻，凭高结层轩。江气偏宜早，林英粲已繁。\n馀滋含宿霁，众妍在朝暾。拂衣释簿领，伏槛遗纷喧。\n深俯东溪澳，远延南山樊。归云纳前岭，去鸟投遥村。\n目尽有馀意，心恻不可谖。朅来彭蠡泽，载经敷浅原。\n春及但生思，时哉无与言。不才叨过举，唯力酬明恩。\n美化犹寂蔑，迅节徒飞奔。虽无成立效，庶以去思论。\n行复徇孤迹，亦云吾道存。'},
    {t:'岁除夜会乐城张少府宅',a:'孟浩然〔唐代〕',c:'畴昔通家好，相知无间然。\n续明催画烛，守岁接长筵。\n旧曲梅花唱，新正柏酒传。\n客行随处乐，不见度年年。'},
    {t:'岁旦朝回口号',a:'杜牧〔唐代〕',c:'星河犹在整朝衣，远望天门再拜归。\n笑向春风初五十，敢言知命且知非。'},
    {t:'岁寒堂三题其二君子树',a:'范仲淹〔宋代〕',c:'二松何年植，清风未尝息。夭矫向庭户，双龙思霹雳。\n岂无桃李姿，贱彼非正色。岂无兰菊芳，贵此有清德。\n万木怨摇落，独如春山碧。乃知天地威，亦向岁寒惜。\n有声若江湖，有心若金璧。雅为君子材，对之每前席。\n或当应自然，化为补天石。'},
    {t:'岁寒堂三题其三·松风阁',a:'范仲淹〔宋代〕',c:'此阁宜登临，上有松风吟。\n非弦亦非匏，自起箫韶音。\n明月万里时，何必开绿琴。\n凤皇下云霓，锵锵鸣中林。\n淳如葛天歌，太古传于今。\n洁如庖义易，洗入平生心。\n安得嘉宾来，当之共披襟。\n陶景若在仙，千载一相寻。'},
    {t:'岁寒堂三题其一·岁寒堂',a:'范仲淹〔宋代〕',c:'我先本唐相，奕世天衢行。\n子孙爱方志，有家在江城。\n双松俨可爱，高堂因以名。\n雅知堂上居，宛年山中情。\n目有千年色，耳有千年声。\n六月无炎光，长如玉壶清。\n于以聚诗书，教子修诚明。\n于以列钟鼓，邀宾乐升平。\n绿烟亦何知，终日在檐楹。\n太阳无偏照，自然虚白生。\n不向摇落地，何忧岁峥嵘。\n勖哉肯构人，处之千万荣。'},
    {t:'岁寒知松柏',a:'黄庭坚〔宋代〕',c:'松柏天生独，青青贯四时。\n心藏后凋节，岁有大寒知。\n惨淡冰霜晚，轮囷涧壑姿。\n或容蝼蚁穴，未见斧斤迟。\n摇落千秋静，婆娑万籁悲。\n郑公扶贞观，已不见封彝。'},
    {t:'岁暮',a:'杜甫〔唐代〕',c:'岁暮远为客，边隅还用兵。\n烟尘犯雪岭，鼓角动江城。\n天地日流血，朝廷谁请缨？\n济时敢爱死？寂寞壮心惊！'},
    {t:'岁暮归南山',a:'孟浩然〔唐代〕',c:'北阙休上书，南山归敝庐。\n不才明主弃，多病故人疏。\n白发催年老，青阳逼岁除。\n永怀愁不寐，松月夜窗虚。'},
    {t:'岁暮海上作',a:'孟浩然〔唐代〕',c:'仲尼既已没，余亦浮于海。\n昏见斗柄回，方知岁星改。\n虚舟任所适，垂钓非有待。\n为问乘槎人，沧洲复何在。'},
    {t:'岁暮和张常侍',a:'陶渊明〔魏晋〕',c:'市朝凄旧人，骤骥感悲泉。\n明旦非今日，岁暮余何言！\n素颜敛光润，白发一己繁。\n阔哉秦穆谈，旅力岂未愆！\n向夕长风起，寒云没西山。\n洌洌气遂严，纷纷飞鸟还。\n民生鲜长在，矧伊愁苦缠。\n屡阙清酤至，无以乐当年。\n穷通靡攸虑，憔悴由化迁。\n抚己有深怀，履运增慨然。'},
    {t:'岁暮碛外寄元撝',a:'岑参〔唐代〕',c:'西风传戍鼓，南望见前军。沙碛人愁月，山城犬吠云。\n别家逢逼岁，出塞独离群。发到阳关白，书今远报君。'},
    {t:'岁日',a:'元稹〔唐代〕',c:'一日今年始，一年前事空。\n凄凉百年事，应与一年同。'},
    {t:'岁晚',a:'白居易〔唐代〕',c:'霜降水返壑，风落木归山。冉冉客将宴，物皆复本源。\n何此南迁客，五年独未还。命屯分已定，日久心弥安。\n亦尝心与口，静念私自言。去国固非乐，归乡未必欢。\n何须自生苦，舍易求其难。'},
    {t:'岁晚',a:'王安石〔宋代〕',c:'月映林塘静，风含笑语凉。\n俯窥怜绿净，小立伫幽香。\n携幼寻新菂，扶衰坐野航。\n延缘久未已，岁晚惜流光。'},
    {t:'岁未尽前数日偶题长句',a:'陆游〔宋代〕',c:'老向人间迹转孤，参差烟火出菰蒲。\n数畦绿菜寒犹茁，一勺清泉手自酥。\n榖贱窥篱无狗盗，夜长暖足有狸奴。\n岁阑更喜人强健，小草书成郁垒符。'},
    {t:'岁晏行',a:'杜甫〔唐代〕',c:'岁云暮矣多北风，潇湘洞庭白雪中。\n渔父天寒网罟冻，莫徭射雁鸣桑弓。\n去年米贵阙军食，今年米贱大伤农。\n高马达官厌酒肉，此辈杼轴茅茨空。\n楚人重鱼不重鸟，汝休枉杀南飞鸿。\n况闻处处鬻男女，割慈忍爱还租庸。\n往日用钱捉私铸，今许铅锡和青铜。\n刻泥为之最易得，好恶不合长相蒙。\n万国城头吹画角，此曲哀怨何时终？'},
    {t:'岁夜咏怀',a:'刘禹锡〔唐代〕',c:'弥年不得意，新岁又如何？\n念昔同游者，而今有几多？\n以闲为自在，将寿补蹉跎。\n春色无情故，幽居亦见过。'},
    {t:'遂州南江别乡曲故人',a:'陈子昂〔唐代〕',c:'楚江复为客，征棹方悠悠。故人悯追送，置酒此南洲。\n平生亦何恨，夙昔在林丘。违此乡山别，长谣去国愁。'},
    {t:'所怀',a:'文天祥〔宋代〕',c:'世途嗟孔棘，行役苦期频。\n良马比君子，清风来故人。\n相看千里月，空负一年春。\n便有桃源路，吾当少避秦。'},
    {t:'所思',a:'杜甫〔唐代〕',c:'苦忆荆州醉司马，谪官樽酒定常开。\n九江日落醒何处，一柱观头眠几回。\n可怜怀抱向人尽，欲问平安无使来。\n故凭锦水将双泪，好过瞿塘滟滪堆。'},
    {t:'琐窗寒',a:'张炎〔宋代〕',c:'王碧山又号中仙，越人也。能文工词，琢语峭拔，有白石意度，今绝响矣。余悼之玉笥山，所谓长歌之哀，过于痛哭。\n断碧分山，空帘剩月，故人天外。香留酒殢。蝴蝶一生花里。想如今、醉魂未醒，夜台梦语秋声碎。自中仙去后，词笺赋笔，便无清致。\n都是。凄凉意。怅玉笥埋云，锦袍归水。形容憔悴。料应也、孤吟山鬼。那知人、弹折素弦，黄金铸出相思泪。但柳枝、门掩枯阴，候蛩愁暗苇。'},
    {t:'琐窗寒·寒食',a:'周邦彦〔宋代〕',c:'暗柳啼鸦，单衣伫立，小帘朱户。桐花半亩，静锁一庭愁雨。洒空阶、夜阑未休，故人剪烛西窗语。似楚江暝宿，风灯零乱，少年羁旅。\n迟暮。嬉游处。正店舍无烟，禁城百五。旗亭唤酒，付与高阳俦侣。想东园、桃李自春，小唇秀靥今在否。到归时、定有残英，待客携尊俎。'},
    {t:'他乡七夕',a:'孟浩然〔唐代〕',c:'他乡逢七夕，旅馆益羁愁。\n不见穿针妇，空怀故国楼。\n绪风初减热，新月始临秋。\n谁忍窥河汉，迢迢问斗牛。'},
    {t:'踏歌词四首·其二',a:'刘禹锡〔唐代〕',c:'桃蹊柳陌好经过，灯下妆成月下歌。\n为是襄王故宫地，至今犹自细腰多。'},
    {t:'踏歌词四首·其三',a:'刘禹锡〔唐代〕',c:'新词宛转递相传，振袖倾鬟风露前。\n月落乌啼云雨散，游童陌上拾花钿。'},
    {t:'踏歌词四首·其四',a:'刘禹锡〔唐代〕',c:'日暮江头闻竹枝，南人行乐北人悲。\n自从雪里唱新曲，直到三春花尽时。'},
    {t:'踏歌词四首·其一',a:'刘禹锡〔唐代〕',c:'春江月出大堤平，堤上女郎连袂行。\n唱尽新词欢不见，红霞映树鹧鸪鸣。'},
    {t:'踏莎美人·清明',a:'纳兰性德〔清代〕',c:'拾翠归迟，踏青期近，香笺小迭绿姬讯。樱桃花谢已清明，何事绿鬟斜亸、宝钗横。\n浅黛双弯，柔肠几寸，不堪更惹其他恨。晓窗窥梦有流莺，也觉个侬憔悴、可怜生。'},
    {t:'踏莎行',a:'张炎〔宋代〕',c:'空山弹古瑟，掬长流、洗耳复谁波。倚阑干不语，江潭树老，风挟波鸣。愁里不须啼鴂，花落石床相。岁月鸥前梦，耿耿离情。\n记得相逢竹外，看词源倒泻，一雪尘缨。笑匆匆呼酒，飞雨夜行舟。又天涯、零落如此，掩闲门、得似晋人清。相思恨，趁杨花去，错到长亭。'},
    {t:'踏莎行',a:'秦观〔宋代〕',c:'冰解芳塘，雪消遥嶂。东风水墨莫绡障。烧痕一夜遍天涯。多情莫向空城望。\n淡柳桥边，疏梅溪上。无人会得春来况。风光输与两鸳鸯，暖滩晴日眠相向。'},
    {t:'踏莎行',a:'晏几道〔宋代〕',c:'绿径穿花，红楼压水。寻芳误到蓬莱地。玉颜人是蕊珠仙，相逢展尽双蛾翠。\n梦草闲眠，流觞浅醉。一春总见瀛洲事。别来双燕又西飞，无端不寄相思字。'},
    {t:'踏莎行',a:'晏几道〔宋代〕',c:'宿雨收尘，朝霞破暝。风光暗许花期定。玉人呵手试妆时，粉香帘幕阴阴静。\n斜雁朱弦，孤鸾绿镜。伤春误了寻芳兴。去年今日杏墙西，啼莺唤得闲愁醒。'},
    {t:'踏莎行',a:'晏几道〔宋代〕',c:'雪尽寒轻，月斜烟重。清欢犹记前时共。迎风朱户背灯开，拂檐花影侵帘动。\n绣枕双鸳，香苞翠凤。从来往事都如梦。伤心最是醉归时，眼前少个人人送。'},
    {t:'踏莎行·碧海无波',a:'晏殊〔宋代〕',c:'碧海无波，瑶台有路。思量便合双飞去。当时轻别意中人，山长水远知何处。\n绮席凝尘，香闺掩雾。红笺小字凭谁附。高楼目尽欲黄昏，梧桐叶上萧萧雨。'},
    {t:'踏莎行·郴州旅舍',a:'秦观〔宋代〕',c:'雾失楼台，月迷津渡。桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。\n驿寄梅花，鱼传尺素。砌成此恨无重数。郴江幸自绕郴山，为谁流下潇湘去。'},
    {t:'踏莎行·春水鸭头',a:'纳兰性德〔清代〕',c:'春水鸭头，春山鹦嘴，烟丝无力风斜倚。百花时节好逢迎，可怜人掩屏山睡。\n密语移灯，闲情枕臂。从教酝酿孤眠味。春鸿不解讳相思，映窗书破人人字。'},
    {t:'踏莎行·赋稼轩集经句',a:'辛弃疾〔宋代〕',c:'进退存亡，行藏用舍。小人请学樊须稼。衡门之下可栖迟，日之夕矣牛羊下。\n去卫灵公，遭桓司马。东西南北之人也。长沮桀溺耦而耕，丘何为是栖栖者。'},
    {t:'踏莎行·柳上烟归',a:'晏几道〔宋代〕',c:'柳上烟归，池南雪尽。东风渐有春华信。花开花谢蝶应知，春来春去莺能问。\n梦意犹疑，心期欲近。云笺字字萦方寸。宿妆曾比杏花红，忆人细把香英认。'},
    {t:'踏莎行·卢仝啜茶手卷',a:'张炎〔宋代〕',c:'清气崖深，斜阳木末。松风泉水美相答。光浮碗面啜先春，何须美酒吴姬压。\n头上乌巾，鬓边白发。数间破屋从芜没。山中有此玉川人，相思一夜梅花发。'},
    {t:'踏莎行·绿树归莺',a:'晏殊〔宋代〕',c:'绿树归莺，雕梁别燕。春光一去如流电。当歌对酒莫沈吟，人生有限情无限。\n弱袂萦春，修蛾写怨。秦筝宝柱频移雁。尊中绿醑意中人，花朝月夜长相见。'},
    {t:'踏莎行·上巳日遇华严寺',a:'秦观〔宋代〕',c:'昨日清明，今朝上巳。莺花著意催春事。东风不管倦游人，一齐吹过城南寺。\n沂水行歌，兰亭修禊。韶光曾见风流士。而今临水漫含情，暮云目断空迢递。'},
    {t:'踏莎行·水落槎枯',a:'张炎〔宋代〕',c:'水落槎枯，田荒玉碎。夜阑秉烛惊相对。故家人物已无传，一灯却照清江外。色展天机，光摇海贝。锦囊日月奚童背。重逢何处抚孤松，共吟风月西湖醉。'},
    {t:'踏莎行·殢酒情怀',a:'佚名〔宋代〕',c:'殢酒情怀，恨春时节。柳丝巷陌黄昏月。把君团扇卜君来，近墙扑得双蝴蝶。\n笑不成言，喜还生怯。颠狂绝似前春雪。夜寒无处著相思，梨花一树人如削。'},
    {t:'踏莎行·细草愁烟',a:'晏殊〔宋代〕',c:'细草愁烟，幽花怯露。凭阑总是海魂处。日高深院静无人，时时海燕双飞去。\n带缓罗衣，香残蕙炷。天长不禁迢迢路。垂杨只解惹春风，何曾系得行人住。'},
    {t:'踏莎行·小径红稀',a:'晏殊〔宋代〕',c:'小径红稀，芳郊绿遍。高台树色阴阴见。春风不解禁杨花，蒙蒙乱扑行人面。\n翠叶藏莺，朱帘隔燕。炉香静逐游丝转。一场愁梦酒醒时，斜阳却照深深院。'},
    {t:'踏莎行·晓树啼莺',a:'秦观〔宋代〕',c:'晓树啼莺，晴洲落雁。酒旗风飐村烟淡。山田过雨正宜耕，畦塍处处春泉漫。\n踏翠郊原，寻芳野涧。风流旧事嗟云散。楚山谁遣送愁来，夕阳回首青无限。'},
    {t:'踏莎行·倚柳题笺',a:'纳兰性德〔清代〕',c:'倚柳题笺，当花侧帽，赏心应比驱驰好。错教双鬓受东风，看吹绿影成丝早。\n金殿寒鸦，玉阶春草，就中冷暖和谁道。小楼明月镇长闲，人生何事缁尘老。'},
    {t:'踏莎行·咏汤',a:'张炎〔宋代〕',c:'瑶草收香，琪花采汞。冰轮碾处调尘动。竹炉汤暖火初红，玉纤调罢歌声送。\n麾去茶经，袭藏酒颂。一杯清味佳宾共。从来采药得长生，蓝桥休被琼浆弄。'},
    {t:'踏莎行·月华如水',a:'纳兰性德〔清代〕',c:'月华如水，波纹似练，几簇淡烟倚柳。塞鸿一夜尽南飞，谁与问倚楼人瘦。\n韵拈风絮，录成金石，不是舞裙歌袖。从前负尽扫眉才，又担阁镜囊重绣。'},
    {t:'踏莎行·祖席离歌',a:'晏殊〔宋代〕',c:'祖席离歌，长亭别宴。香尘已隔去回面。居人匹马映林嘶，行人去棹依波转。\n画阁魂消，高楼目断。斜阳只送平波远。无穷无尽是离愁，天涯地角寻思遍。'},
    {t:'台城怀古',a:'刘禹锡〔唐代〕',c:'清江悠悠王气沉，六朝遗事何处寻。\n宫墙隐嶙围野泽，鹳鶂夜鸣秋色深。'},
    {t:'台城路',a:'张炎〔宋代〕',c:'庚寅秋九月之北，遇汪菊坡，一见或惊，相对如梦。回忆旧游，已十八年矣。因赋此词。\n十年前事翻疑梦，重逢可怜俱老。水国春空，山城岁晚，无语相看一笑。荷衣换了。任京洛尘沙，冷凝风帽。见说吟情，近来不到谢池草。\n欢游曾步翠窈。乱红迷紫曲，芳意今少。舞扇招香，歌桡唤玉，犹忆钱塘苏小。无端暗恼。又几度流连，燕昏莺晓。回首妆楼，甚时重去好。'},
    {t:'台城路·饯干寿道应举',a:'张炎〔宋代〕',c:'几年槐市槐花冷，天风又还吹起。故箧重寻，闲书再整，犹记灯窗滋味。浑如梦里。见说道如今，早催行李。快买扁舟，第一桥边趁流水。\n阳关须是醉酒，柳条休要折，争似攀桂。旧有家声，荣看世美，方了平生英气。琼林宴喜。带雪絮归来，满庭春意。事业方新，大鹏九万里。'},
    {t:'台城路·迁居',a:'张炎〔宋代〕',c:'桃花零落玄都观，刘郎此情谁语。鬓发萧疏，襟怀淡薄，空赋天涯羁旅。离情万缕。第一是难招，旧鸥今雨。锦瑟年华，梦中犹记艳游处。\n依依心事最苦。片帆浑是月，独抱凄楚。屋破容秋，床空对雨，迷却青门瓜圃。初荷未暑。叹极目烟波，又歌南浦。燕忽归来，翠帘深几许。'},
    {t:'台城路·清时乐事中园赋',a:'张炎〔宋代〕',c:'陆义斋寿日，自澄江放舟，清游所山水间，散怀吟眺，一任所适所之。既倦，乘月夜归。太白去后园百年无此乐耶。\n清时乐事中园赋，怡情楚花湘草。秀色通帘，生香聚酒，修景常留池沼。闲居自好。奈车马喧尘，未教闲了。把菊清游，冷红飞下洞庭晓。\n寻泉同步翠杳。更将秋共远，书画船小。款竹谁家，盟鸥某水，白月光涵圆峤。天浮浩渺。称绿发飘飘，溯风舒啸。缓筑堤沙，渭滨人未老。'},
    {t:'台城路·塞外七夕',a:'纳兰性德〔清代〕',c:'白狼河北秋偏早，星桥又迎河鼓。清漏频移，微云欲湿，正是金风玉露。两眉愁聚。待归踏榆花，那时才诉。只恐重逢，明明相视更无语。\n人间别离无数，向瓜果筵前，碧天凝伫，连理千花，相思一叶，毕竟随风何处。羁栖良苦，算未抵空房，冷香啼曙。今夜天孙，笑人愁似许。'},
    {t:'台城路·送周方山游吴',a:'张炎〔宋代〕',c:'朗吟未了西湖酒，惊心又歌南浦。折柳官桥，呼船野渡，还听垂虹风雨。漂流最苦。况如此江山，此时情绪。怕有鸱夷，笑人何事载诗去。\n荒台只今在否。登临休望远，都是愁处。暗草埋沙，明波洗月，谁念天涯羁旅。荷阴未暑。快料理归程，再盟鸥鹭。只恐空山，近来无杜宇。'},
    {t:'台城路·章静山别业会饮',a:'张炎〔宋代〕',c:'一窗烟雨不除草。移家静藏深居。东晋图书，南山杞菊，谁识幽居怀抱。疏阴未扫。叹乔木犹存，近分残照。慷慨悲歌，故人多向近来老。\n相逢何事欠早。爱吟心共苦，此意难表。野水无鸥，闲门断柳，不满清风一笑。荷衣制了。待寻壑经丘，溯云孤啸。学取渊明，抱琴归去好。'},
    {t:'台城曲二首',a:'杜牧〔唐代〕',c:'整整复斜斜，隋旗簇晚沙。\n门外韩擒虎，楼头张丽华。\n谁怜容足地，却羡井中蛙。\n王颁兵势急，鼓下坐蛮奴。\n潋滟倪塘水，叉牙出骨须。\n干芦一炬火，回首是平芜。'},
    {t:'台温处树旗谣',a:'佚名〔元代〕',c:'天高皇帝远，民少相公多。\n一日三遍打，不反待如何？'},
    {t:'太白东溪张老舍即事寄舍弟侄等',a:'岑参〔唐代〕',c:'渭上秋雨过，北风何骚骚。\n天晴诸山出，太白峰最高。\n主人东溪老，两耳生长毫。\n远近知百岁，子孙皆二毛。\n中庭井阑上，一架猕猴桃。\n石泉饭香粳，酒瓮开新槽。\n爱兹田中趣，始悟世上劳。\n我行有胜事，书此寄尔曹。'},
    {t:'太白胡僧歌',a:'岑参〔唐代〕',c:'闻有胡僧在太白，兰若去天三百尺。一持楞伽入中峰，\n世人难见但闻钟。窗边锡杖解两虎，床下钵盂藏一龙。\n草衣不针复不线，两耳垂肩眉覆面。此僧年几那得知，\n手种青松今十围。心将流水同清净，身与浮云无是非。\n商山老人已曾识，愿一见之何由得。山中有僧人不知，\n城里看山空黛色。'},
    {t:'太白岭',a:'王安石〔宋代〕',c:'太白巃嵷东南驰，众岭环合青纷披。\n烟云厚薄皆可爱，树石疏密自相宜。\n阳春已归鸟语乐，溪水不动鱼行迟。\n生民何由得处所，与兹鱼鸟相谐熙。'},
    {t:'太白楼',a:'文天祥〔宋代〕',c:'扬子江心第一泉，南金来此铸文渊。\n男儿斩却楼兰首，闲品茶经拜羽仙。'},
    {t:'太常引·建康中秋夜为吕叔潜赋',a:'辛弃疾〔宋代〕',c:'一轮秋影转金波，飞镜又重磨。把酒问姮娥：被白发，欺人奈何？\n乘风好去，长空万里，直下看山河。斫去桂婆娑，人道是，清光更多。'},
    {t:'太常引·江梅开似蕊珠宫',a:'佚名〔宋代〕',c:'江梅开似蕊珠宫。报桃李、又春风。蓦岫看前峰。待摘取、横斜盏中。魏林楚岭，素妆清绝，不与众芳同。和月映帘栊。羡几点、施朱太红。'},
    {t:'太常引·晚来风起撼花铃',a:'纳兰性德〔清代〕',c:'晚来风起撼花铃。人在碧山亭。无里不堪听。那更杂、泉声雨声。\n无凭踪迹，无聊心绪，谁说与多情。梦也不分明，又何必、催教梦醒。'},
    {t:'太湖馆送殷秀才赴举',a:'皎然〔唐代〕',c:'春风洞庭路，摇荡暮天多。衰疾见芳草，别离伤远波。\n诗名推首荐，赋甲拟前科。数日闻天府，山衣制芰荷。'},
    {t:'太湖秋夕',a:'王昌龄〔唐代〕',c:'水宿烟雨寒，洞庭霜落微。\n月明移舟去，夜静魂梦归。\n暗觉海风度，萧萧闻雁飞。'},
    {t:'太湖恬亭',a:'王安石〔宋代〕',c:'槛临溪上绿阴围，溪岸高低入翠微。\n日落断桥人独立，水涵幽树鸟相依。\n清游始觉心无累，静处谁知世有机。\n更待夜深同徙倚，秋风斜月钓船归。'},
    {t:'太平花',a:'陆游〔宋代〕',c:'扶床踉蹡出京华，头白车书未一家。\n宵旰至今劳圣主，泪痕空对太平花。'},
    {t:'太液池歌',a:'温庭筠〔唐代〕',c:'腥鲜龙气连清防，花风漾漾吹细光。叠澜不定照天井，\n倒影荡摇晴翠长。平碧浅春生绿塘，云容雨态连青苍。\n夜深银汉通柏梁，二十八宿朝玉堂。'},
    {t:'太原早秋',a:'李白〔唐代〕',c:'岁落众芳歇，时当大火流。\n霜威出塞早，云色渡河秋。\n梦绕边城月，心飞故国楼。\n思归若汾水，无日不悠悠。'},
    {t:'太子西池二首·一作齐梁体',a:'温庭筠〔唐代〕',c:'梨花雪压枝，莺啭柳如丝。懒逐影成晓，春融梦觉迟。\n鬓轻全作影，嚬浅未成眉。莫信张公子，窗新断暗期。\n花红兰紫茎，愁草雨新晴。柳占三春色，莺偷百鸟声。\n日长嫌辇重，风暖觉衣轻。薄暮香尘起，长杨落照明。'},
    {t:'泰州',a:'文天祥〔宋代〕',c:'羁臣家万里，天目鉴孤忠。\n心在坤维外，身游坎窞中。\n长淮行不断，苦海望无穷。\n晚鹊传佳好，通州路已通。'},
    {t:'摊破浣溪沙·一霎灯前醉不醒',a:'纳兰性德〔清代〕',c:'一霎灯前醉不醒，恨如春梦畏人明。淡月淡云窗外雨，一声声。\n人道情多情转薄，而今真个不多情。又听鹧鸪啼遍了，短长亭。'},
    {t:'昙智禅师院',a:'韦应物〔唐代〕',c:'高年不复出，门径众草生。时夏方新雨，果药发馀荣。\n疏澹下林景，流暮幽禽情。身名两俱遣，独此野寺行。'},
    {t:'潭州',a:'李商隐〔唐代〕',c:'潭州官舍暮楼空，今古无端入叠中。\n湘泪浅深滋竹色，楚歌重叠怨兰丛。\n陶公战舰空滩雨，贾傅承尘破庙风。\n目断故园人不至，松醪一醉与谁同。'},
    {t:'檀溪寻故人',a:'孟浩然〔唐代〕',c:'花伴成龙竹，池分跃马溪。\n田园人不见，疑向洞中栖。'},
    {t:'叹白发',a:'韦应物〔唐代〕',c:'还同一叶落，对此孤镜晓。丝缕乍难分，杨花复相绕。\n时役人易衰，吾年白犹少。'},
    {t:'叹白发',a:'王维〔唐代〕',c:'宿昔朱颜成暮齿，须臾白发变垂髫。\n一生几许伤心事，不向空门何处销。'},
    {t:'叹白发',a:'岑参〔唐代〕',c:'白发生偏速，交人不奈何。今朝两鬓上，更较数茎多。'},
    {t:'叹花',a:'杜牧〔唐代〕',c:'自恨寻芳到已迟，往年曾见未开时。\n如今风摆花狼籍，绿叶成阴子满枝。'},
    {t:'叹命',a:'孟郊〔唐代〕',c:'三十年来命，唯藏一卦中。题诗达问易，问易蒙复蒙。\n本望文字达，今因文字穷。影孤别离月，衣破道路风。\n归去不自息，耕耘成楚农。'},
    {t:'叹水别白二十二',a:'刘禹锡〔唐代〕',c:'水。\n至清，尽美。\n从一勺，至千里。\n利人利物，时行时止。\n道性净皆然，交情淡如此。\n君游金谷堤上，我在石渠署里。\n两心相忆似流波，潺湲日夜无穷已。'},
    {t:'叹庭前甘菊花',a:'杜甫〔唐代〕',c:'庭前甘菊移时晚，青蕊重阳不堪摘。\n明日萧条醉尽醒，残花烂熳开何益？\n篱边野外多众芳，采撷细琐升中堂。\n念兹空长大枝叶，结根失所缠风霜。'},
    {t:'探春令·绿杨枝上晓莺啼',a:'晏几道〔宋代〕',c:'绿杨枝上晓莺啼，报融和天气。被数声、吹入纱窗里。又惊起娇娥睡。绿云斜亸金钗堕。惹芳心如醉。为少年湿了，鲛绡帕上，都是相思泪。'},
    {t:'探春慢',a:'张炎〔宋代〕',c:'列屋烘炉，深门响竹，催残客里时序。投老情怀，薄游滋味，消得几多凄楚。听雁听风雨，更听过、数声柔橹。暗将一点归心，试托醉乡分付。\n借问西楼在否。休忘了盈盈，端正窥户。铁马春冰，柳蛾晴雪，次第满城箫鼓。闲见谁家月，浑不记、旧游何处。伴我微吟，恰有梅花一树。'},
    {t:'探春慢·雪霁',a:'张炎〔宋代〕',c:'银浦流云，绿房迎晓，一抹墙腰瑶淡。暖玉生烟，悬冰解冻，碎滴瑶阶如霰。才放些晴意，早瘦了、何花一半。也知不做花看，东风何事吹散。\n摇落似成秋苑。甚酿得春来，怕教春见。野渡舟回，前村门掩，应是不胜清怨。次第寻芳去，灞桥外、蕙香波暖。犹妒檐声，看灯人在深院。'},
    {t:'探梅',a:'陆游〔宋代〕',c:'岁月相寻岂有穷，早梅唤醒醉眠翁。\n坐中酒量人人别，花底春风处处同。\n白帝城边微雪过，青衣江上夕阳红。\n锦囊空复残诗在，分付悲欢一梦中。'},
    {t:'探梅',a:'杨万里〔宋代〕',c:'春榜梅梢瘦处回，小花未忍折将来。\n却缘久住成幽事，剩看南枝一度开。'},
    {t:'汤评事衡水亭会觉禅师',a:'皎然〔唐代〕',c:'山侣相逢少，清晨会水亭。雪晴松叶翠，烟暖药苗青。\n静对沧洲鹤，闲看古寺经。应怜叩关子，了义共心冥。'},
    {t:'唐昌观看花',a:'张籍〔唐代〕',c:'新红旧紫不相宜，看觉从前两月迟。\n更向同来诗客道，明年到此莫过时。'},
    {t:'唐城馆中早发，寄杨使君',a:'孟浩然〔唐代〕',c:'犯霜驱晓驾，数里见唐城。旅馆归心逼，荒村客思盈。\n访人留后信，策蹇赴前程。欲识离魂断，长空听雁声。'},
    {t:'唐多令',a:'张炎〔宋代〕',c:'聚首不多时。烟波又别离。有黄金、应铸相思。折得梅花先寄我，山正在、里湖西。\n风雪脆荷衣。休教鸥鹭知。鬓丝丝、犹混尘泥。何日束书归旧隐，只恐怕、种瓜迟。'},
    {t:'唐儿歌',a:'李贺〔唐代〕',c:'头玉硗硗眉刷翠，杜郎生得真男子！\n骨重神寒天庙器，一双瞳人剪秋水。\n竹马梢梢摇绿尾，银鸾睒光踏半臂。\n东家娇娘求对值，浓笑书空作唐字。\n眼大心雄知所以，莫忘作歌人姓李！'},
    {t:'唐郎中宅与诸公同饮酒看牡丹',a:'刘禹锡〔唐代〕',c:'今日花前饮，甘心醉数杯。但愁花有语，不为老人开。'},
    {t:'唐铙歌鼓吹曲·奔鲸沛',a:'柳宗元〔唐代〕',c:'奔鲸沛，荡海垠。\n吐霓翳日，腥浮云。\n帝怒下顾，哀垫昏。\n授以神柄，推元臣。\n手援天矛，截脩鳞。\n披攘蒙霿，开海门。\n地平水静，浮天根。\n羲和显耀，乘清氛。\n赫炎溥畅，融大钧。'},
    {t:'唐铙歌鼓吹曲·东蛮',a:'柳宗元〔唐代〕',c:'东蛮有谢氏，冠带理海中。\n自言我异世，虽圣莫能通。\n王卒如飞翰，鹏骞骇群龙。\n轰然自天坠，乃信神武功。\n系虏君臣人，累累来自东。\n无思不服从，唐业如山崇。\n百辟拜稽首，咸愿图形容。\n如周王会书，永永传无穷。\n睢盱万状乖，咿嗢九译重。\n广轮抚四海，浩浩如皇风。\n歌诗铙鼓间，以壮我元戎。'},
    {t:'唐铙歌鼓吹曲·高昌',a:'柳宗元〔唐代〕',c:'麹氏雄西北，别绝臣外区。\n既恃远且险，纵傲不我虞。\n烈烈王者师，熊螭以为徒。\n龙旂翻海浪，馹骑驰坤隅。\n贲育搏婴儿，一扫不复馀。\n平沙际天极，但见黄云驱。\n臣靖执长缨，智勇伏囚拘。\n文皇南面坐，夷狄千群趋。\n咸称天子神，往古不得俱。\n献号天可汗，以覆我国都。\n兵戎不交害，各保性与躯。'},
    {t:'唐铙歌鼓吹曲·河右平',a:'柳宗元〔唐代〕',c:'河右澶漫，顽为之魁。\n王师如雷震，昆仑以颓。\n上聋下聪，骜不可回。\n助雠抗有德，惟人之灾。\n乃溃乃奋，执缚归厥命。\n万室蒙其仁，一夫则病。\n濡以鸿泽，皇之圣。\n威畏德怀，功以定。\n顺之于理，物咸遂厥性。'},
    {t:'唐铙歌鼓吹曲·战武牢',a:'柳宗元〔唐代〕',c:'战武牢，动河朔。\n逆之助，图掎角。\n怒鷇麛，抗乔岳。\n翘萌牙，傲霜雹。\n王谋内定，申掌握。\n铺施芟夷，二主缚。\n惮华戎，廓封略。\n命之瞢，毕以斮。\n归有德，唯先觉。'},
    {t:'唐铙歌鼓吹曲十二首·其四',a:'柳宗元〔唐代〕',c:'泾水黄，陇野茫。\n负太白，腾天狼。\n趯鸟鸷立，羽翼张。\n钩喙决前，钜趯傍。\n怒飞饥啸，翾不可当。\n老雄地，子复良。\n巢岐饮渭，肆翱翔。\n顿地紘，提天纲。\n列缺掉帜，招摇耀鋩。\n鬼神来助，梦嘉祥。\n脑涂原野，魄飞扬。\n星辰复，恢一方。'},
    {t:'唐石雪中',a:'朱熹〔宋代〕',c:'春风欲动客辞家，霖潦纵横路转赊。行到溪山愁绝处，千林一夜玉成花。'},
    {t:'唐庄恪太子挽歌词二首',a:'温庭筠〔唐代〕',c:'叠鼓辞宫殿，悲笳降杳冥。影离苑外日，光灭火前星。\n邺客瞻秦苑，商公下汉庭。依依陵树色，空梦古原青。\n东府虚容卫，西园寄梦思。凤悬吹曲夜，鸡断问安时。\n尘陌都人恨，霜郊赗马悲。唯馀埋璧地，烟草近丹墀。'},
    {t:'堂成',a:'杜甫〔唐代〕',c:'背郭堂成荫白茅，缘江路熟俯青郊。\n桤林碍日吟风叶，笼竹和烟滴露梢。\n暂止飞乌将数子，频来语燕定新巢。\n旁人错比扬雄宅，懒惰无心作解嘲。'},
    {t:'堂堂曲',a:'温庭筠〔唐代〕',c:'钱唐岸上春如织，淼淼寒潮带晴色。淮南游客马连嘶，\n碧草迷人归不得。风飘客意如吹烟。纤指殷勤伤雁弦。\n一曲堂堂红烛筵，长鲸泻酒如飞泉。'},
    {t:'塘下行',a:'孟郊〔唐代〕',c:'塘边日欲斜，年少早还家。徒将白羽扇，调妾木兰花。\n不是城头树，那栖来去鸦。'},
    {t:'桃花',a:'元稹〔唐代〕',c:'桃花浅深处，似匀深浅妆。\n春风助肠断，吹落白衣裳。'},
    {t:'桃花源记',a:'陶渊明〔魏晋〕',c:'晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。渔人甚异之，复前行，欲穷其林。\n林尽水源，便得一山，山有小口，仿佛若有光。便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。土地平旷，屋舍俨然，有良田、美池、桑竹之属。阡陌交通，鸡犬相闻。其中往来种作，男女衣着，悉如外人。黄发垂髫，并怡然自乐。\n见渔人，乃大惊，问所从来。具答之。便要还家，设酒杀鸡作食。村中闻有此人，咸来问讯。自云先世避秦时乱，率妻子邑人来此绝境，不复出焉，遂与外人间隔。问今是何世，乃不知有汉，无论魏晋。此人一一为具言所闻，皆叹惋。余人各复延至其家，皆出酒食。停数日，辞去。此中人语云：“不足为外人道也。”\n既出，得其船，便扶向路，处处志之。及郡下，诣太守，说如此。太守即遣人随其往，寻向所志，遂迷，不复得路。\n南阳刘子骥，高尚士也，闻之，欣然规往。未果，寻病终。后遂无问津者。'},
    {t:'桃源行',a:'王安石〔宋代〕',c:'望夷宫中鹿为马，秦人半死长城下。\n避时不独商山翁，亦有桃源种桃者。\n此来种桃经几春，采花食实枝为薪。\n儿孙生长与世隔，虽有父子无君臣。\n渔郎漾舟迷远近，花间相见因相问。\n世上那知古有秦，山中岂料今为晋。\n闻道长安吹战尘，春风回首一沾巾。\n重华一去宁复得，天下纷纷经几秦。'},
    {t:'桃源忆故人·冬景',a:'秦观〔宋代〕',c:'玉楼深锁薄情种，清夜悠悠谁共？羞见枕衾鸳凤，闷则和衣拥。\n无端画角严城动，惊破一番新梦。窗外月华霜重，听彻《梅花弄》。'},
    {t:'桃源忆故人·暮春',a:'苏轼〔宋代〕',c:'华胥梦断人何处，听得莺啼红暖。几点蔷薇香雨，寂寞闲庭户。\n暖风不解留花住，片片着人无数。楼上望春归去，芳草迷归路。'},
    {t:'桃源忆故人·题华山图',a:'陆游〔宋代〕',c:'中原当日三川震，关辅回头煨烬。泪尽两河征镇，日望中兴运。\n秋风霜满青青鬓，老却新丰英俊。云外华山千仞，依旧无人问。'},
    {t:'桃源忆故人·五之三',a:'陆游〔宋代〕',c:'一弹指顷浮生过。堕甑元知当残。去去醉吟高卧。独唱何须和。\n残年还我从来我。万里江湖烟舸。脱尽利名缰锁。世界元来大。'},
    {t:'滕达道挽词',a:'秦观〔宋代〕',c:'江南江北奉周旋，合散如云二话年。\n春邵胜游花散马，夜山清话雨连天。\n共惊万里长城坏，独把千金宝剑悬。\n平日书题多散乱，呼儿寻聚一潸然。'},
    {t:'滕子京魏介之二同年相访丹阳郡',a:'范仲淹〔宋代〕',c:'长江天下险，涉者利名驱。\n二公访贫交，过之如坦途。\n风波岂不恶，忠信天所扶。\n相见乃大笑，命歌倒金壶。\n同年三百人，太半空名呼。\n没者草自绿，存者颜无朱。\n功名若在天，何必心区区。\n莫竞贵高路，休防谗嫉夫。\n孔子作旅人，孟轲号迂儒。\n吾辈不饮酒，笑杀高阳徒。'},
    {t:'剔银灯·何事春工用意',a:'柳永〔宋代〕',c:'何事春工用意。绣画出、万红千膏。艳杏夭桃，垂杨芳草，各斗雨膏烟腻。如斯佳致。早晚是、读书欢气。\n渐渐园林明媚。便好安排欢计。论槛买花，盈车载酒，百琲千金邀妓。何妨沈醉。有人伴、日高春睡。'},
    {t:'剔银灯·与欧阳公席上分题',a:'范仲淹〔宋代〕',c:'昨夜因看蜀志，笑曹操孙权刘备。用尽机关，徒劳心力，只得三分天地。屈指细寻思，争如共、刘伶一醉？\n人世都无百岁。少痴騃、老成尪悴。只有中间，些子少年，忍把浮名牵系？一品与千金，问白发、如何回避？'},
    {t:'题安州浮云寺楼寄湖州张郎中',a:'杜牧〔唐代〕',c:'去夏疏雨馀，同倚朱阑语。\n当时楼下水，今日到何处。\n恨如春草多，事与孤鸿去。\n楚岸柳何穷，别愁纷若絮。'},
    {t:'题灞池二首',a:'王昌龄〔唐代〕',c:'腰镰欲何之，东园刈秋韭。\n世事不复论，悲歌和樵叟。\n开门望长川，薄暮见渔者。\n借问白头翁，垂纶几年也。'},
    {t:'题白石莲花寄楚公',a:'李商隐〔唐代〕',c:'白石莲花谁所共，六时长捧佛前灯。\n空庭苔藓饶霜露，时梦西山老病僧。\n大海龙宫无限地，诸天雁塔几多层。\n漫夸鹙子真罗汉，不会牛车是上乘。'},
    {t:'题百叶桃花',a:'韩愈〔唐代〕',c:'百叶双桃晚更红，窥窗映竹见玲珑。\n应知侍史归天上，故伴仙郎宿禁中。'},
    {t:'题报恩寺惟照上人房',a:'皎然〔唐代〕',c:'上界雨色干，凉宫日迟迟。水文披菡萏，山翠动罘罳。\n中有清真子，愔愔步闲墀。手萦颇黎缕，愿证黄金姿。\n旋草阶下生，看心当此时。'},
    {t:'题碧落堂',a:'文天祥〔宋代〕',c:'大厦新成燕雀欢，与君聊此共清闲。地居一郡楼台上，人在半空烟雨间。\n修复尽还今宇宙，感伤犹记旧江山。近来又报秋风紧，颇觉忧时鬓欲斑。'},
    {t:'题茶山·在宜兴',a:'杜牧〔唐代〕',c:'山实东吴秀，茶称瑞草魁。剖符虽俗吏，修贡亦仙才。\n溪尽停蛮棹，旗张卓翠苔。柳村穿窈窕，松涧渡喧豗。\n等级云峰峻，宽平洞府开。拂天闻笑语，特地见楼台。\n泉嫩黄金涌，牙香紫璧裁。拜章期沃日，轻骑疾奔雷。\n舞袖岚侵涧，歌声谷答回。磬音藏叶鸟，雪艳照潭梅。\n好是全家到，兼为奉诏来。树阴香作帐，花径落成堆。\n景物残三月，登临怆一杯。重游难自克，俯首入尘埃。'},
    {t:'题禅院',a:'杜牧〔唐代〕',c:'觥船一棹百分空，十岁青春不负公。\n今日鬓丝禅榻畔，茶烟轻飏落花风。'},
    {t:'题郴阳道中一古寺壁二绝',a:'秦观〔宋代〕',c:'哀歌巫女隔祠丛，饥鼠相追坏壁中。\n北客念家浑不睡，荒山一夜雨吹风。'},
    {t:'题程烨程燧兄弟双桂书院',a:'朱熹〔宋代〕',c:'君家构屋积玉堆，两种天香手自栽。清影一帘秋澹荡，任渠艳冶斗春开。'},
    {t:'题赤城观',a:'朱熹〔宋代〕',c:'落日空山秋气清，泠泠古木乱蝉鸣。仙人一去鹤不返，剑客重来丹已成。\n静对竹炉烟缕直，细看月窟桂华生。此身旧有蓬瀛约，玉简归来问姓名。'},
    {t:'题楚昭王庙',a:'韩愈〔唐代〕',c:'丘坟满目衣冠尽，城阙连云草树荒。\n犹有国人怀旧德，一间茅屋祭昭王。'},
    {t:'题传神',a:'陆游〔宋代〕',c:'雪鬓萧然两颊红，人间随处见农通。\n半醒半醉常终日，非士非农一老翁。\n枥骥虽存千里志，云鹏已息九天风。\n巉巉骨法吾能相，难著凌烟剑佩中。'},
    {t:'题淳于髡墓',a:'刘禹锡〔唐代〕',c:'生为齐赘婿，死作楚先贤。应以客卿葬，故临官道边。\n寓言本多兴，放意能合权。我有一石酒，置君坟树前。'},
    {t:'题磁岭海棠花',a:'温庭筠〔唐代〕',c:'幽态竟谁赏，岁华空与期。岛回香尽处，泉照艳浓时。\n蜀彩淡摇曳，吴妆低怨思。王孙又谁恨，惆怅下山迟。'},
    {t:'题从侄成绪西林精舍书斋',a:'韦应物〔唐代〕',c:'栖身齿多暮，息心君独少。慕谢注精文，依僧欲观妙。\n冽泉前阶注，清池北窗照。果药杂芬敷，松辰疏蒨峭。\n屡跻幽人境，每肆芳辰眺。采栗玄猿窟，撷芝丹林峤。\n纻衣岂寒御，蔬食非饥疗。虽甘巷北单，岂塞青紫耀。\n郡有优贤榻，朝编贡士诏。欲同朱轮载，勿惮移文诮。'},
    {t:'题崔公池亭旧游',a:'温庭筠〔唐代〕',c:'皎镜方塘菡萏秋，此来重见采成舟。\n谁能不逐当年乐，还恐添成异日愁。\n红艳影多风袅袅，碧空云断水悠悠。\n檐前依旧青山色，尽日无人独上楼。'},
    {t:'题翠峰院',a:'范仲淹〔宋代〕',c:'翠峰高与白云闲，吾祖曾居水石间。\n千载家风应未坠，子孙还解爱青山。'},
    {t:'题村舍',a:'杜牧〔唐代〕',c:'三树稚桑春未到，扶床乳女午啼饥。\n潜销暗铄归何处，万指侯家自不知。'},
    {t:'题大禹寺义公禅房',a:'孟浩然〔唐代〕',c:'义公习禅处，结宇依空林。\n户外一峰秀，阶前众壑深。\n夕阳连雨足，空翠落庭阴。\n看取莲花净，应知不染心。'},
    {t:'题东湖涵虚阁',a:'晏殊〔宋代〕',c:'水有支流树有孙，重重门巷挂波轩。\n三君雅望标人杰，千里澄波隔世喧。\n西对户庭徐孺宅，北传钟梵给孤园。\n欲知嗣续无穷胜，两两荣归汉使轓。'},
    {t:'题端正树',a:'温庭筠〔唐代〕',c:'路傍佳树碧云愁，曾侍金舆幸驿楼。\n草木荣枯似人事，绿阴寂寞汉陵秋。'},
    {t:'题鹅',a:'李商隐〔唐代〕',c:'眠沙卧水自成群，曲岸残阳极浦云。\n那解将心怜孔翠，羁雌长共故雄分。'},
    {t:'题法海平闍黎',a:'秦观〔宋代〕',c:'寒食山州百色喧，春风花雨暗川原。\n因循移病依香火，写得弥陀七万言。'},
    {t:'题法华山天衣寺',a:'元稹〔唐代〕',c:'马踏红尘古塞平，出门谁不为功名。到头争似栖禅客，林下无言过一生。'},
    {t:'题方睦上人月台观',a:'张籍〔唐代〕',c:'一身清净无童子，独坐空堂得几年。\n每夜焚香通月观，可怜光影最团圆。'},
    {t:'题舫子',a:'王安石〔宋代〕',c:'爱此江边好，留连至日斜。\n眠分黄犊草，坐占白鸥沙。'},
    {t:'题峰顶寺',a:'李白〔唐代〕',c:'夜宿峰顶寺，举手扪星辰。\n不敢高声语，恐惊天上人。'},
    {t:'题鞏县西门周襄王庙',a:'晏殊〔宋代〕',c:'人来人去市朝变，山后山前烟雾凝。\n萦带二川河洛水，寂寥千古帝王陵。'},
    {t:'题观楼',a:'岑参〔唐代〕',c:'荒楼荒井闭空山，关令乘云去不还。\n羽盖霓旌何处在，空留药臼向人间。'},
    {t:'题归梦',a:'李贺〔唐代〕',c:'长安风雨夜，书客梦昌谷。\n怡怡中堂笑，小弟栽涧菉。\n家门厚重意，望我饱饥腹。\n劳劳一寸心，灯花照鱼目。'},
    {t:'题虢州西楼',a:'岑参〔唐代〕',c:'错料一生事，蹉跎今白头。纵横皆失计，妻子也堪羞。\n明主虽然弃，丹心亦未休。愁来无去处，只上郡西楼。'},
    {t:'题汉祖庙',a:'李商隐〔唐代〕',c:'乘运应须宅八荒，男儿安在恋池隍。\n君王自起新丰后，项羽何曾在故乡。'},
    {t:'题何氏宅园亭',a:'王安石〔宋代〕',c:'荷叶参差卷，榴花次第开。\n但令心有赏，岁月任渠催。'},
    {t:'题河中紫极宫',a:'温庭筠〔唐代〕',c:'昔年曾伴玉真游，每到仙宫即是秋。\n曼倩不归花落尽，满丛烟露月当楼。'},
    {t:'题贺知章故居叠韵作',a:'温庭筠〔唐代〕',c:'废砌翳薜荔，枯湖无菰蒲。老媪饱藁草，愚儒输逋租。'},
    {t:'题横江馆',a:'杜牧〔唐代〕',c:'孙家兄弟晋龙骧，驰骋功名业帝王。\n至竟江山谁是主，苔矶空属钓鱼郎。'},
    {t:'题胡逸老致虚庵',a:'黄庭坚〔宋代〕',c:'藏书万卷可教子，遗金满籯常月灾。\n能与贫人共年谷，必有明月生蚌胎。\n山随宴坐图画出，水月夜窗风雨来。\n观水观山皆得妙，更将何物污灵台。'},
    {t:'题湖上草堂',a:'皎然〔唐代〕',c:'山居不买剡中山，湖上千峰处处闲。\n芳草白云留我住，世人何事得相关。'},
    {t:'题画山水障',a:'张九龄〔唐代〕',c:'心累犹不尽，果为物外牵。\n偶因耳目好，复假丹青妍。\n尝抱野间意，而迫区中缘。\n尘事固已矣，秉意终不迁。\n良工适我愿，妙墨挥岩泉。\n变化合群有，高深侔自然。\n置陈北堂上，仿像南山前。\n静无户庭出，行已兹地偏。\n萱草忧可树，合欢忿益蠲。\n所因本微物，况乃凭幽筌。\n言象会自泯，意色聊自宣。\n对玩有佳趣，使我心渺绵。'},
    {t:'题黄冈寺次吴履斋韵',a:'文天祥〔宋代〕',c:'长江几千里，万折必归东。\n南浦惊新雁，庐山隔晚风。\n人行荒树外，秋在断芜中。\n何日洗兵马，车书四海同。'},
    {t:'题吉州承天院清凉轩',a:'黄庭坚〔宋代〕',c:'菩萨清凉月，游於毕竟空。\n我观诸境尽，心与古人同。\n僧发侵眉白，桃花映竹红。\n傥来寻祖意，展手似家风。'},
    {t:'题江阴城墙',a:'佚名〔明代〕',c:'雪胔白骨满疆场，万死孤忠未肯降。\n寄语行人休掩鼻，活人不及死人香。'},
    {t:'题金城临河驿楼',a:'岑参〔唐代〕',c:'古戍依重险，高楼见五凉。\n山根盘驿道，河水浸城墙。\n庭树巢鹦鹉，园花隐麝香。\n忽如江浦上，忆作捕鱼郎。'},
    {t:'题金山寺二首',a:'苏轼〔宋代〕',c:'潮随暗浪雪山倾，远浦渔舟钓月明。\n桥对寺门松径小，槛当泉眼石波清。\n迢迢绿树江天晓，霭霭红霞海日晴。\n遥望四边云接水，碧峰千点数鸿轻。\n轻鸿数点千峰碧，水接云边四望遥。\n晴日海霞红霭霭，晓天江树绿迢迢。\n清波石眼泉当槛，小径松门寺对桥。\n明月钓舟渔浦远，倾山雪浪暗随潮。'},
    {t:'题井陉双谿李道士所居',a:'岑参〔唐代〕',c:'五粒松花酒，双谿道士家。唯求缩却地，乡路莫教赊。'},
    {t:'题净眼师房',a:'王昌龄〔唐代〕',c:'白鸽飞时日欲斜，禅房寂历饮香茶。\n倾人城，倾人国，斩新剃头青且黑。\n玉如意，金澡瓶，朱唇皓齿能诵经。\n吴音唤字更分明。\n日暮钟声相送出，袈裟挂着箔帘钉。'},
    {t:'题敬爱寺楼',a:'杜牧〔唐代〕',c:'暮景千山雪，春寒百尺楼。\n独登还独下，谁会我悠悠。'},
    {t:'题九日山石佛院乱峰轩二首其二',a:'朱熹〔宋代〕',c:'岩中老释子，白发对青山。不作看山想，秋云时往还。'},
    {t:'题九日山石佛院乱峰轩二首其一',a:'朱熹〔宋代〕',c:'因依古佛居，结屋寒林杪。当户碧峰稠，云烟自昏晓。'},
    {t:'题居延古城赠乔十二知之',a:'陈子昂〔唐代〕',c:'闻君东山意，宿昔紫芝荣。沧洲薄何在，华发旅边城。\n还汉功既薄，逐胡策未行。徒嗟白日暮，坐对黄云生。\n桂枝芳欲晚，薏苡谤谁明。无为空自老，含叹负生平。'},
    {t:'题老学庵壁',a:'陆游〔宋代〕',c:'此生生计愈萧然，架竹苫茆只晓椽。\n万卷古今消永日，一窗昏晓送流年。\n太平民乐无愁叹，衰老形枯少睡眠。\n唤得南村跛童子，煎茶扫地亦随缘。'},
    {t:'题李别驾壁',a:'高适〔唐代〕',c:'去乡不远逢知己，握手相欢得如此。礼乐遥传鲁伯禽，\n宾客争过魏公子。酒筵暮散明月上，枥马长鸣春风起。\n一生称意能几人，今日从君问终始。'},
    {t:'题李处士幽居',a:'温庭筠〔唐代〕',c:'水玉簪头白角巾，瑶琴寂历拂轻尘。浓阴似帐红薇晚，\n细雨如烟碧草春。隔竹见笼疑有鹤，卷帘看画静无人。\n南山自是忘年友，谷口徒称郑子真。'},
    {t:'题李次云窗竹',a:'白居易〔唐代〕',c:'不用裁为鸣凤管，不须截作钓鱼竿。\n千花百草凋零后，留向纷纷雪里看。'},
    {t:'题李三书斋·崇嗣',a:'陈子昂〔唐代〕',c:'灼灼青春仲，悠悠白日升。\n声容何足恃，荣吝坐相矜。\n愿与金庭会，将待玉书征。\n还丹应有术，烟驾共君乘。'},
    {t:'题李十四庄，兼赠綦毋校书',a:'孟浩然〔唐代〕',c:'闻君息阴地，东郭柳林间。左右瀍涧水，门庭缑氏山。\n抱琴来取醉，垂钓坐乘闲。归客莫相待，寻源殊未还。'},
    {t:'题李十四庄兼赠綦毋校书',a:'孟浩然〔唐代〕',c:'闻君息荫地，东郭柳林间。\n左右瀍涧水，门庭缑氏山。\n抱琴来取醉，垂钓坐乘闲。\n归客莫相待，缘源殊未还。'},
    {t:'题李卫公诗二首',a:'温庭筠〔唐代〕',c:'蒿棘深春卫国门，九年于此盗乾坤。两行密疏倾天下，\n一夜阴谋达至尊。肉视具僚忘匕箸，气吞同列削寒温。\n当时谁是承恩者，肯有馀波达鬼村。\n势欲凌云威触天，权倾诸夏力排山。三年骥尾有人附，\n一日龙须无路攀。画閤不开梁燕去，朱门罢扫乳鸦还。\n千岩万壑应惆怅，流水斜倾出武关。'},
    {t:'题李相公敕赐锦屏风',a:'温庭筠〔唐代〕',c:'丰沛曾为社稷臣，赐书名画墨犹新。\n几人同保山河誓，犹自栖栖九陌尘。'},
    {t:'题梁锽城中高居',a:'岑参〔唐代〕',c:'高住最高处，千家恒眼前。\n题诗饮酒后，只对诸峰眠。'},
    {t:'题刘朝英进斋',a:'杨万里〔宋代〕',c:'灯火三更雨，诗书一古琴。\n惟愁脚力软，未必圣门深。\n莫笑云端树，初如涧底针。\n不应将一第，用破半生心。'},
    {t:'题刘秀才新竹',a:'杜牧〔唐代〕',c:'数茎幽玉色，晓夕翠烟分。声破寒窗梦，根穿绿藓纹。\n渐笼当槛日，欲碍入帘云。不是山阴客，何人爱此君。'},
    {t:'题榴花',a:'韩愈〔唐代〕',c:'五月榴花照眼明，枝间时见子初成。\n可怜此地无车马，颠倒青苔落绛英。'},
    {t:'题柳',a:'温庭筠〔唐代〕',c:'杨柳千条拂面丝，绿烟金穗不胜吹。\n香随静婉歌尘起，影伴娇娆舞袖垂。\n羌管一声何处曲，流莺百啭最高枝。\n千门九陌花如雪，飞过宫墙两自知。'},
    {t:'题卢处士山居',a:'温庭筠〔唐代〕',c:'西溪问樵客，遥识楚人家。\n古树老连石，急泉清露沙。\n千峰随雨暗，一径入云斜。\n日暮飞鸦集，满山荞麦花。'},
    {t:'题陆鸿渐上饶新开山舍',a:'孟郊〔唐代〕',c:'惊彼武陵状，移归此岩边。开亭拟贮云，凿石先得泉。\n啸竹引清吹，吟花成新篇。乃知高洁情，摆落区中缘。'},
    {t:'题落星寺四首·其二',a:'黄庭坚〔宋代〕',c:'岩岩匡俗先生庐，其下宫亭水星都。\n北辰九关隔云雨，南极一星在江湖。\n相粘蠔山作居室，窍凿混沌无完肤。\n万鼓声撞夜涛涌，骊龙莫碎失明珠。'},
    {t:'题落星寺四首·其三',a:'黄庭坚〔宋代〕',c:'落星开士深结屋，龙阁老翁来天诗。\n小雨藏山客坐久，长江接天帆到迟。\n宴寝清香与世隔，画图妙绝无人知。\n蜂房各自开户牖，处处煮茶藤一枝。'},
    {t:'题落星寺四首·其四',a:'黄庭坚〔宋代〕',c:'北风吹倒落星寺，吾与伯伦俱醉眠。\n螟蛉蜾蠃但痴坐，夜寒南北斗垂天。'},
    {t:'题落星寺四首·其一',a:'黄庭坚〔宋代〕',c:'星官游空何时落，着地亦化为愕坊。\n诗人昼吟山入座，醉客夜愕江憾床。\n蜜房各自开户牖，蚁穴或梦封侯王。\n不知青云梯几级，更借瘦藤寻上方。'},
    {t:'题孟浩然画像',a:'黄庭坚〔宋代〕',c:'先生少也隐鹿门，爽气洗尽尘埃昏。\n赋诗真可凌鲍谢，短褐岂愧公卿尊。\n故人私邀伴禁直，诵诗不顾龙鳞逆。\n风云感会虽有时，顾此定知毋枉尺。\n襄江渺渺泛清流，梅残腊月年年愁。\n先生一往今几秋，後来谁复钓槎头。'},
    {t:'题米仓壁',a:'朱熹〔宋代〕',c:'度量无私本至公，寸心贪得意何穷。\n若教老子庄周见，剖斗除衡付一空。'},
    {t:'题木居士二首',a:'韩愈〔唐代〕',c:'火透波穿不计春，根穷头面干穷身。\n偶然题作木居士，便有无穷求福人。\n为神讵比沟中断，遇赏还同爨下馀。\n朽蠹不胜刀锯力，匠人虽巧欲何穷。'},
    {t:'题木兰庙',a:'杜牧〔唐代〕',c:'弯弓征战作男儿，梦里曾经与画眉。\n几度思归还把酒，拂云堆上祝明妃。'},
    {t:'题苜蓿峰寄家人',a:'岑参〔唐代〕',c:'苜蓿峰边逢立春，胡芦河上泪沾巾。\n闺中只是空相忆，不见沙场愁杀人。'},
    {t:'题雱祠堂',a:'王安石〔宋代〕',c:'斯文实有寄，天岂偶天才。\n一日凤鸟去，千秋梁木摧。\n烟留衰草恨，风造暮林哀。\n岂谓登临处，飘然独往来。'},
    {t:'题平阳郡汾桥边柳树',a:'岑参〔唐代〕',c:'此地曾居住，今来宛似归。\n可怜汾上柳，相见也依依。'},
    {t:'题齐安壁',a:'王安石〔宋代〕',c:'日净山如染，风暄草欲薰。\n梅残数点雪，麦涨一溪云。'},
    {t:'题齐安城楼',a:'杜牧〔唐代〕',c:'呜轧江楼角一声，微阳潋潋落寒汀。\n不用凭栏苦回首，故乡七十五长亭。'},
    {t:'题青云馆',a:'杜牧〔唐代〕',c:'虬蟠千仞剧羊肠，天府由来百二强。四皓有芝轻汉祖，\n张仪无地与怀王。云连帐影萝阴合，枕绕泉声客梦凉。\n深处会容高尚者，水苗三顷百株桑。'},
    {t:'题清彻上人院',a:'张籍〔唐代〕',c:'古寺临坛久，松间别起堂。看添浴佛水，自合读经香。\n爱养无家客，多传得效方。过斋长不出，坐卧一绳床。'},
    {t:'题融公兰若·一作题容山主兰若',a:'孟浩然〔唐代〕',c:'精舍买金开，流泉绕砌回。芰荷薰讲席，松柏映香台。\n法雨晴飞去，天花昼下来。谈玄殊未已，归骑夕阳催。'},
    {t:'题三会寺苍颉造字台',a:'岑参〔唐代〕',c:'野寺荒台晚，寒天古木悲。空阶有鸟迹，犹似造书时。'},
    {t:'题僧壁',a:'李商隐〔唐代〕',c:'舍生求道有前踪，乞脑剜身结愿重。大去便应欺粟颗，\n小来兼可隐针锋。蚌胎未满思新桂，琥珀初成忆旧松。\n若信贝多真实语，三生同听一楼钟。'},
    {t:'题僧房',a:'王昌龄〔唐代〕',c:'棕榈花满院，苔藓入闲房。\n彼此名言绝，空中闻异香。'},
    {t:'题僧泰恭院二首',a:'温庭筠〔唐代〕',c:'昔岁东林下，深公识姓名。尔来味半偈，空复叹劳生。\n忧患慕禅味，寂寥遗世情。所归心自得，何是倦尘缨。\n微生竟劳止，晤言犹是非。出门还有泪，看竹暂忘机。\n爽气三秋近，浮生一笑稀。故山松菊在，终欲掩荆扉。'},
    {t:'题僧院',a:'张籍〔唐代〕',c:'闻师行讲青龙疏，本寺住来多少年。\n静扫空房唯独坐，千茎秋竹在檐前。'},
    {t:'题山寺扉',a:'王安石〔宋代〕',c:'口衔天宪手持钧，已是龙墀第一人。\n回首三千大千界，此身犹是一微尘。'},
    {t:'题山寺僧房',a:'岑参〔唐代〕',c:'窗影摇群木，墙阴载一峰。野炉风自爇，山碓水能舂。\n勤学翻知误，为官好欲慵。高僧暝不见，月出但闻钟。'},
    {t:'题商山四皓庙一绝',a:'杜牧〔唐代〕',c:'吕氏强梁嗣子柔，我于天性岂恩雠。\n南军不袒左边袖，四老安刘是灭刘。'},
    {t:'题少陵画像',a:'陆游〔宋代〕',c:'长安落叶纷可扫，九陌北风吹余倒。\n杜公四十不成名，袖里空余三赋草。\n车声余声喧客枕，三百青铜市楼饮。\n杯残朒冷正悲辛，仗内斗鸡催赐锦！'},
    {t:'题沈道士新亭',a:'皎然〔唐代〕',c:'何处好攀跻，新亭俯旧溪。坐中千里近，檐下四山低。\n小浦依林曲，回塘绕郭西。桃花春满地，归路莫相迷。'},
    {t:'题沈少府书斋',a:'皎然〔唐代〕',c:'不下南昌县，书斋每日闲。野花当砌落，溪鸟逐人还。\n有兴常临水，无时不见山。千峰数可尽，不出小窗间。'},
    {t:'题寿安甘棠馆二首',a:'刘禹锡〔唐代〕',c:'公馆似仙家，池清竹径斜。山禽忽惊起，冲落半岩花。\n门前洛阳道，门里桃花路。尘土与烟霞，其间十馀步。'},
    {t:'题双松寄陈季常',a:'秦观〔宋代〕',c:'遥闻连理松，托根黄麻城。\n枝枝相钩带，叶叶同死生。\n虽云金石姿，未免儿女情。\n想应风月夕，满庭合欢声。'},
    {t:'题水西寺',a:'杜牧〔唐代〕',c:'三日去还住，一生焉再游。含情碧溪水，重上粲公楼。'},
    {t:'题司马长卿画像',a:'晏几道〔宋代〕',c:'犊鼻生涯一酒墟，当年嗤笑欲何如。穷通不属儿曹意，自有真人爱子虚。'},
    {t:'题祀山烽树赠乔十二侍御',a:'陈子昂〔唐代〕',c:'汉庭荣巧宦，云阁薄边功。\n可怜骢马使，白首为谁雄。'},
    {t:'题苏若兰回文锦诗图',a:'黄庭坚〔宋代〕',c:'千诗织就回文锦，如此阳台暮雨何。\n亦有英灵苏蕙手，只无悔过窦连波。'},
    {t:'题苏轼雨竹图',a:'秦观〔宋代〕',c:'叶密雨偏重，枝垂雾不消。会看晴日后，依旧拂云霄。'},
    {t:'题苏武忠节图',a:'文天祥〔宋代〕',c:'独伴羝羊海上游，相逢血泪向天流。\n忠贞已向生前定，老节须从死后休。\n不死未论生可喜，虽生何恨死堪忧。\n甘心卖国人何处，曾识苏公义胆不。'},
    {t:'题桃花夫人庙',a:'杜牧〔唐代〕',c:'细腰宫里露桃新，脉脉无言度几春。\n至竟息亡缘底事，可怜金谷坠楼人。'},
    {t:'题桃树',a:'杜甫〔唐代〕',c:'小径升堂旧不斜，五株桃树亦从遮。\n高秋总馈贫人实，来岁还舒满眼花。\n帘户每宜通乳燕，儿童莫信打慈鸦。\n寡妻群盗非今日，天下车书正一家。'},
    {t:'题滕王阁',a:'文天祥〔宋代〕',c:'五云窗户瞰沧浪，犹带唐人翰墨香。\n日月四时黄道阔，江山一片画图长。\n回风何处抟双雁，冻雨谁人驾独航。\n回首十年此漂泊，阁前新柳已成行。'},
    {t:'题田洗马游岩桔槔',a:'陈子昂〔唐代〕',c:'望苑长为客。\n商山遂不归。\n谁怜北陵井。\n未息汉阴机。'},
    {t:'题桐叶',a:'杜牧〔唐代〕',c:'去年桐落故溪上，把笔偶题归燕诗。江楼今日送归燕，\n正是去年题叶时。叶落燕归真可惜，东流玄发且无期。\n笑筵歌席反惆怅，明月清风怆别离。庄叟彭殇同在梦，\n陶潜身世两相遗。一丸五色成虚语，石烂松薪更莫疑。\n哆侈不劳文似锦，进趋何必利如锥。钱神任尔知无敌，\n酒圣于吾亦庶几。江畔秋光蟾阁镜，槛前山翠茂陵眉。\n樽香轻泛数枝菊，檐影斜侵半局棋。休指宦游论巧拙，\n只将愚直祷神祇。三吴烟水平生念，宁向闲人道所之。'},
    {t:'题王居士所藏王友画桃杏花二首',a:'黄庭坚〔宋代〕',c:'凌云见桃万事无，我见杏花心亦如。\n从此华山图籍上，更添潘阆倒骑驴。'},
    {t:'题韦少保静恭宅藏书洞',a:'孟郊〔唐代〕',c:'高意合天制，自然状无穷。仙华凝四时，玉藓生数峰。\n书秘漆文字，匣藏金蛟龙。闲为气候肃，开作云雨浓。\n洞隐谅非久，岩梦诚必通。将缀文士集，贯就真珠丛。'},
    {t:'题尉迟将军新庙',a:'高适〔唐代〕',c:'周室既板荡，贼臣立婴儿。将军独激昂，誓欲酬恩私。\n孤城日无援，高节终可悲。家国共沦亡，精魂空在斯。\n沉沉积冤气，寂寂无人知。良牧怀深仁，与君建明祠。\n父子俱血食，轩车每逶迤。我来荐蘋蘩，感叹兴此词。\n晨光上阶闼，杀气翻旌旗。明明幽冥理，至诚信莫欺。\n唯夫二千石，多庆方自兹。'},
    {t:'题文与可墨竹·并叙',a:'苏轼〔宋代〕',c:'故人文与可为道师王执中作墨竹，且谓执中勿使他人书字，待苏子瞻来，令作诗其侧。与可既没八年而轼始还朝，见之，乃赋一首。\n斯人定何人，游戏得自在。\n诗鸣草圣余，兼入竹三昧。\n时时出木石，荒怪轶象外。\n举世知珍之，赏会独予最。\n知音古难合，奄忽不少待。\n谁云死生隔，相见如龚隗。'},
    {t:'题乌江亭',a:'杜牧〔唐代〕',c:'胜败兵家事不期，包羞忍耻是男儿。\n江东子弟多才俊，卷土重来未可知。'},
    {t:'题梧州陈司马山斋',a:'孟浩然〔唐代〕',c:'南国无霜霰，连年对物华。\n青林暗换叶，红蕊亦开花。\n春去无山鸟，秋来见海槎。\n流芳虽可悦，会自泣长沙。'},
    {t:'题武关',a:'杜牧〔唐代〕',c:'碧溪留我武关东，一笑怀王迹自穷。\n郑袖娇娆酣似醉，屈原憔悴去如蓬。\n山樯谷堑依然在，弱吐强吞尽已空。\n今日圣神家四海，戍旗长卷夕阳中。'},
    {t:'题西林壁',a:'苏轼〔宋代〕',c:'横看成岭侧成峰，远近高低各不同。\n不识庐山真面目，只缘身在此山中。'},
    {t:'题西林院壁二首其一',a:'朱熹〔宋代〕',c:'触目风光不易裁，此间何似舞雩台。病躯若得长无事，春服成时岁一来。'},
    {t:'题西太一宫壁二首',a:'王安石〔宋代〕',c:'柳叶鸣蜩绿暗，荷花落日红酣。\n三十六陂春水，白头想见江南。\n三十年前此地，父兄持我东西。\n今日重来白首，欲寻陈迹都迷。'},
    {t:'题萧端虚和乐堂',a:'杨万里〔宋代〕',c:'玉笥风回峡山雨，两公对床方软语。\n少公一生吟样臞，长公半醉少公扶。\n白头兄弟不多有，面如橘红不关酒。\n紫荆花开连理枝，孝友未要时人知。'},
    {t:'题小松',a:'李商隐〔唐代〕',c:'怜君孤秀植庭中，细叶轻阴满后风。\n桃李盛时虽寂寞，雪霜多后始青葱。\n一年几变枯荣事，百尺方资柱石功。\n为谢西园车马客，定悲摇落尽成空。'},
    {t:'题新乡王釜厅壁',a:'岑参〔唐代〕',c:'怜君守一尉，家计复清贫。禄米尝不足，俸钱供与人。\n城头苏门树，陌上黎阳尘。不是旧相识，声同心自亲。'},
    {t:'题盱眙军东南第一山二首',a:'杨万里〔宋代〕',c:'第一山头第一亭，闻名未到负平生。\n不因王事略小出，那得高人同此行。\n万里中原青未了，半篙淮水碧无情。\n登临不觉风烟暮，肠断渔灯隔岸明。\n建隆家业大于天，庆历春风一万年。\n廊庙谋谟出童蔡，笑谈京洛博幽燕。\n白沟旧在鸿沟外，易水今移淮水前。\n川后年来世情了，一波分护两涯船。'},
    {t:'题徐浩书法华经',a:'王安石〔宋代〕',c:'一切法无差，水牛生象牙。\n莫将无量义，欲觅妙莲华。'},
    {t:'题宣州开元寺',a:'杜牧〔唐代〕',c:'南朝谢脁城，东吴最深处。\n亡国去如鸿，遗寺藏烟坞。\n楼飞九十尺，廊环四百柱。\n高高下下中，风绕松桂树。\n青苔照朱阁，白鸟两相语。\n溪声入僧梦，月色晖粉堵。\n阅景无旦夕，凭阑有今古。\n留我酒一樽，前山看春雨。'},
    {t:'题宣州开元寺水阁',a:'杜牧〔唐代〕',c:'阁下宛溪，夹溪居人。\n六朝文物草连空，天淡云闲今古同。\n鸟去鸟来山色里，人歌人哭水声中。\n深秋帘幕千家雨，落日楼台一笛风。\n惆怅无因见范蠡，参差烟树五湖东。'},
    {t:'题玄武禅师屋壁',a:'杜甫〔唐代〕',c:'何年顾虎头，满壁画沧洲。\n赤日石林气，青天江海流。\n锡飞常近鹤，杯渡不惊鸥。\n似得庐山路，真随惠远游。'},
    {t:'题浔阳楼',a:'白居易〔唐代〕',c:'自此后诗，江州司马时作\n常爱陶彭泽，文思何高玄。\n又怪韦江州，诗情亦清闲。\n今朝登此楼，有以知其然。\n大江寒见底，匡山青倚天。\n深夜湓浦月，平旦炉峰烟。\n清辉与灵气，日夕供文篇。\n我无二人才，孰为来其间？\n因高偶成句，俯仰愧江山。'},
    {t:'题扬州禅智寺',a:'杜牧〔唐代〕',c:'雨过一蝉噪，飘萧松桂秋。\n青苔满阶砌，白鸟故迟留。\n暮霭生深树，斜阳下小楼。\n谁知竹西路，歌吹是扬州。'},
    {t:'题阳关图二首',a:'黄庭坚〔宋代〕',c:'断肠声里无形影，画出无声亦断肠。\n想得阳关更西路，北风低草见牛羊。'},
    {t:'题杨秘书新居',a:'张籍〔唐代〕',c:'爱闲不向争名地，宅在街西最静坊。\n卷里诗过一千首，白头新受秘书郎。'},
    {t:'题友人云母障子',a:'王维〔唐代〕',c:'君家云母障，时向野庭开。\n自有山泉入，非因采画来。'},
    {t:'题余不溪废寺',a:'皎然〔唐代〕',c:'武原离乱后，真界积尘埃。残月生秋水，悲风起故台。\n居人今已尽，栖鸽暝还来。不到无生理，应堪赋七哀。'},
    {t:'题郁孤台',a:'文天祥〔宋代〕',c:'城郭春声阔，楼台昼影迟。\n并天浮雪界，盖海出云旗。\n风雨十年梦，江湖万里思。\n倚阑时北顾，空翠湿朝曦。'},
    {t:'题元八溪居',a:'白居易〔唐代〕',c:'溪岚漠漠树重重，水槛山窗次第逢。\n晚叶尚开红踯躅，秋芳初结白芙蓉。\n声来枕上千年鹤，影落杯中五老峰。\n更愧殷勤留客意，鱼鲜饭细酒香浓。'},
    {t:'题元处士高亭·宣州',a:'杜牧〔唐代〕',c:'水接西江天外声，小斋松影拂云平。\n何人教我吹长笛，与倚春风弄月明。'},
    {t:'题元丹丘山居',a:'李白〔唐代〕',c:'故人栖东山，自爱丘壑美。\n青春卧空林，白日犹不起。\n松风清襟袖，石潭洗心耳。\n羡君无纷喧，高枕碧霞里。'},
    {t:'题岳阳楼',a:'白居易〔唐代〕',c:'岳阳城下水漫漫，独上危楼凭处阑。\n春岸绿时连梦泽，夕波红处近长安。\n猿攀树立啼何苦，雁点湖飞渡亦难。\n此地唯堪画图障，华堂张与贵人看。'},
    {t:'题张景召簿尉梅墅并饯入南',a:'文天祥〔宋代〕',c:'唤醒三影燕支魂，一枝半树专黄昏。\n江南暗香郁不住，霜风吹入罗浮村。\n疏枝不入辋川画，暗香不到东山棋。\n云阶一枕梨花梦，参横月落无人知。'},
    {t:'题张十八所居·籍',a:'韩愈〔唐代〕',c:'君居泥沟上，沟浊萍青青。蛙讙桥未扫，蝉嘒门长扃。\n名秩后千品，诗文齐六经。端来问奇字，为我讲声形。'},
    {t:'题张十一旅舍三咏·井',a:'韩愈〔唐代〕',c:'贾谊宅中今始见，葛洪山下昔曾窥。\n寒泉百尺空看影，正是行人暍死时。'},
    {t:'题张十一旅舍三咏·葡萄',a:'韩愈〔唐代〕',c:'新茎未遍半犹枯，高架支离倒复扶。\n若欲满盘堆马乳，莫辞添竹引龙须。'},
    {t:'题张氏隐居二首',a:'杜甫〔唐代〕',c:'春山无伴独相求，伐木丁丁山更幽。\n涧道馀寒历冰雪，石门斜日到林丘。\n不贪夜识金银气，远害朝看麋鹿游。\n乘兴杳然迷出处，对君疑是泛虚舟。\n之子时相见，邀人晚兴留。\n霁潭鳣发发，春草鹿呦呦。\n杜酒偏劳劝，张梨不外求。\n前村山路险，归醉每无愁。'},
    {t:'题张司业诗',a:'王安石〔宋代〕',c:'苏州司业诗名老，乐府皆言妙入神。\n看似寻常最奇崛，成如容易却艰辛。'},
    {t:'题张野人园庐',a:'孟浩然〔唐代〕',c:'与君园庐并，微尚颇亦同。耕钓方自逸，壶觞趣不空。\n门无俗士驾，人有上皇风。何处先贤传，惟称庞德公。'},
    {t:'题长安主人壁',a:'孟浩然〔唐代〕',c:'久废南山田，叨陪东阁贤。\n欲随满子去，犹未献甘泉。\n枕籍琴书满，褰帷远岫连。\n我来如昨日，庭树忽鸣蝉。\n促织惊寒女，秋风感长年。\n授衣当九月，无褐竟谁怜。'},
    {t:'题赵生壁',a:'李贺〔唐代〕',c:'大妇然竹根，中妇舂玉屑。冬暖拾松枝，日烟坐蒙灭。\n木藓青桐老，石井水声发。曝背卧东亭，桃花满肌骨。'},
    {t:'题赵团练画江干晚景四绝',a:'秦观〔宋代〕',c:'晓浦烟笼树，春江水拍空。\n烦君添小艇，画我作渔翁。'},
    {t:'题郑防画夹五首',a:'黄庭坚〔宋代〕',c:'惠崇烟雨归雁，坐我潇湘洞庭。\n能唤扁舟归去，故人言是丹青。\n能作山川远势，白头惟有郭熙。\n徐写李成骤雨，惜无六幅鹅溪。\n徐生脱水双鱼，吹沫相看晚图。\n老矣个中得计，作书远寄江湖。\n折苇枯荷共晚，红榴苦竹同时。\n睡鸭不知飘雪，寒雀四顾风枝。\n子母猿号槲叶，山南山北危机。\n世故谁能樗里，彀中皆是由基。'},
    {t:'题郑拾遗草堂',a:'韦应物〔唐代〕',c:'借地结茅栋，横竹挂朝衣。秋园雨中绿，幽居尘事违。\n阴井夕虫乱，高林霜果稀。子有白云意，构此想岩扉。'},
    {t:'题中峰寺',a:'柳永〔宋代〕',c:'攀萝蹑石落崔嵬，千万峰中梵地开。\n僧向半空为世界，眼看平地起风雷。\n猿偷晓果升松去，竹逗清流入槛来。\n旬月经游殊不厌，欲归回首更迟回。'},
    {t:'题终南翠微寺空上人房',a:'孟浩然〔唐代〕',c:'翠微终南里，雨后宜返照。\n闭关久沈冥，杖策一登眺。\n遂造幽人室，始知静者妙。\n儒道虽异门，云林颇同调。\n两心相喜得，毕景共谈笑。\n暝还高窗眠，时见远山烧。\n缅怀赤城标，更忆临海峤。\n风泉有清音，何必苏门啸。'},
    {t:'题朱炼师山房',a:'王昌龄〔唐代〕',c:'叩齿焚香出世尘，斋坛鸣磬步虚人。\n百花仙酝能留客，一饭胡麻度几春。'},
    {t:'题竹谷神祠·一作谷神庙',a:'温庭筠〔唐代〕',c:'苍苍松竹晚，一径入荒祠。古树风吹马，虚廊日照旗。\n烟煤朝奠处，风雨夜归时。寂寞东湖客，空看蒋帝碑。'},
    {t:'题竹石牧牛',a:'黄庭坚〔宋代〕',c:'子瞻画丛竹怪石，伯时增前坡牧儿骑牛，甚有意态，戏咏。\n野次小峥嵘，幽篁相倚绿。\n阿童三尺箠，御此老觳觫。\n石吾甚爱之，勿遣牛砺角。\n牛砺角犹可，牛斗残我竹。'},
    {t:'题祝生画呈裴丈二首其一',a:'朱熹〔宋代〕',c:'近代丹青手，心期良独难。夫君偏有思，妙处却无端。\n堂上三湘远，人间五月寒。空囊今有此，不用一钱看。'},
    {t:'题子瞻枯木',a:'黄庭坚〔宋代〕',c:'折冲儒墨阵堂堂，书入颜杨鸿雁行。\n胸中元自有丘壑，故作老木蟠风霜。'},
    {t:'题醉中所作草书卷后',a:'陆游〔宋代〕',c:'胸中磊落藏五兵，欲试无路空峥嵘。\n酒为旗鼓笔刀槊，势从天落银河倾。\n端溪石池浓作墨，烛光相射飞纵横。\n须臾收卷复把酒，如见万里烟尘清。\n丈夫身在要有立，逆虏运尽行当平。\n何时夜出五原塞，不闻人语闻鞭声。'},
    {t:'殢人娇·二月春风',a:'晏殊〔宋代〕',c:'二月春风，正是杨花满路。那堪霑、别离情绪。罗巾掩泪，任粉泪霑汙。争奈向、千留万留不住。\n玉酒频倾，宿眉愁聚。空肠断、宝筝弦柱。人间后会，又不知何处。魂梦里、也须时时飞去。'},
    {t:'殢人娇·或云赠朝云',a:'苏轼〔宋代〕',c:'白发苍颜，正是维摩境界。空方丈、散花何碍。朱唇箸点，更髻鬟生彩。这些个，千生万生只在。\n好事心肠，著人情态。闲窗下、敛云凝黛。明朝端午，待学纫兰为佩。寻一首好诗，要书裙带。'},
    {t:'殢人娇·林钟商',a:'柳永〔宋代〕',c:'当日相逢，便有怜才深意。歌筵罢、偶同鸳被。别来光景，看看经岁。昨夜里、方把旧欢重继。\n晓月将沈，征骖已鞴。愁肠乱、又还分袂。良辰好景，恨浮名牵系。无分得、与你恣情浓睡。'},
    {t:'殢人娇·一叶秋高',a:'晏殊〔宋代〕',c:'一叶秋高，向夕红兰露坠。风月好、乍凉天气。长生此日，见人中嘉瑞。斟寿酒、重唱妙声珠缀。\n凤箢移宫，钿衫回袂。帘影动、鹊炉香细。南真宝录，赐玉京千岁。良会永、莫惜流霞同醉。'},
    {t:'殢人娇·玉树微凉',a:'晏殊〔宋代〕',c:'玉树微凉，渐觉银河影转。林叶归、疏红欲遍。朱帘细雨，尚迟留归燕。嘉庆日、多少世人良愿。\n楚竹惊鸾，秦筝起雁。萦舞袖、急翻罗荐。云回一曲，更轻栊檀板。香炷远、同祝寿期无限。'},
    {t:'天边行',a:'杜甫〔唐代〕',c:'天边老人归未得，日暮东临大江哭。\n陇右河源不种田，胡骑羌兵入巴蜀。\n洪涛滔天风拔木，前飞秃鹙后鸿鹄。\n九度附书向洛阳，十年骨肉无消息。'},
    {t:'天津桥东旬宴得歌字韵',a:'张九龄〔唐代〕',c:'清洛象天河，东流形胜多。朝来逢宴喜，春尽却妍和。\n泉鲔欢时跃，林莺醉里歌。赐恩频若此，为乐奈人何。'},
    {t:'天可度·恶诈人也',a:'白居易〔唐代〕',c:'天可度，地可量，唯有人心不可防。\n但见丹诚赤如血，谁知伪言巧似簧。\n劝君掩鼻君莫掩，使君夫妇为参商。\n劝君掇蜂君莫掇，使君父子成豺狼。\n海底鱼兮天上鸟，高可射兮深可钓。\n唯有人心相对时，咫尺之间不能料。\n君不见李义府之辈笑欣欣，笑中有刀潜杀人。\n阴阳神变皆可测，不测人间笑是瞋。'},
    {t:'天末怀李白',a:'杜甫〔唐代〕',c:'凉风起天末，君子意如何。\n鸿雁几时到，江湖秋水多。\n文章憎命达，魑魅喜人过。\n应共冤魂语，投诗赠汨罗。'},
    {t:'天平山白云泉',a:'范仲淹〔宋代〕',c:'灵泉在天半，狂波不能侵。\n神蛟穴其中，渴虎不敢临。\n隐照涵秋碧，泓然一勺深。\n游润腾云飞，散作三日霖。\n天造岂无意，神化安可寻。\n挹之如醍醐，尽得清凉心。\n闻之异丝竹，不含哀乐音。\n月好群籁息，涓涓度前林。\n子晋罢云笙，伯牙收玉琴。\n徘徊不拟去，复发沧浪吟。\n乃云尧汤岁，盈盈长若今。\n万里江海源，千秋松桂阴。\n兹焉如有价，北斗量黄金。'},
    {t:'天启惠酥',a:'周邦彦〔宋代〕',c:'金城良犉不当车，特为人间作好酥。\n余湩尚供肥犊子，小匳先入太官厨。\n邺中鹿尾空名目，吴地莼羹谩僻迂。\n欲比君家好兄弟，不积压谁可作醍醐。'},
    {t:'天启惠酥其二',a:'周邦彦〔宋代〕',c:'浅黄拂拂小鹅雏，色好从来说入酥。花草偏宜女儿手，缄封枉入野人厨。\n细涂麦饼珍无敌，杂炼猪肪术最迂。脔肉便知全鼎味，它时不用识醍醐。'},
    {t:'天启惠酥其三',a:'周邦彦〔宋代〕',c:'南朝珍馔一时无，尚见休文谢北酥。陶瓮解汤香出屋，铜铛掠面乳供厨。\n中都价重无钱买，京兆书迟怪路迂。闻道加餐最肥泽，异时烦与致醍醐。'},
    {t:'天启惠酥其四',a:'周邦彦〔宋代〕',c:'高阳太守有遗书，亲教齐民炼鼠酥。欲出浮膏先卧酪，为防馋鼠更薰厨。\n绝知意重分馀弃，渐见诗多入怪迂。犹恐伧人笑风土，预从贝叶检醍醐。'},
    {t:'天启惠酥其一',a:'周邦彦〔宋代〕',c:'金城良牸不当车，特为人间作好酥。馀湩尚供肥犊子，小奁先入太官厨。\n邺中鹿尾空名目，吴地莼羹谩僻迂。欲比君家好兄弟，不知谁可作醍醐。'},
    {t:'天山雪歌送萧治归京',a:'岑参〔唐代〕',c:'天山雪云常不开，千峰万岭雪崔嵬。\n北风夜卷赤亭口，一夜天山雪更厚。\n能兼汉月照银山，复逐胡风过铁关。\n交河城边鸟飞绝，轮台路上马蹄滑。\n晻霭寒氛万里凝，阑干阴崖千丈冰。\n将军狐裘卧不暖，都护宝刀冻欲断。\n正是天山雪下时，送君走马归京师。\n雪中何以赠君别，惟有青青松树枝。'},
    {t:'天上谣',a:'李贺〔唐代〕',c:'天河夜转漂回星，银浦流云学水声。\n玉宫桂树花未落，仙妾采香垂珮缨。\n秦妃卷帘北窗晓，窗前植桐青凤小。\n王子吹笙鹅管长，呼龙耕烟种瑶草。\n粉霞红绶藕丝裙，青洲步拾兰苕春。\n东指羲和能走马，海尘新生石山下。'},
    {t:'天童山溪上',a:'王安石〔宋代〕',c:'溪水清涟树老苍，行穿溪树踏春阳。\n溪深树密无人处，唯有幽花渡水香。'},
    {t:'天仙子·好在软绡红泪积',a:'纳兰性德〔清代〕',c:'好在软绡红泪积，漏痕斜罥菱丝碧。古钗封寄玉关秋，天咫尺，人南北。不信鸳鸯头不白。'},
    {t:'天仙子·渌水亭秋夜',a:'纳兰性德〔清代〕',c:'水浴凉蟾风入袂，鱼鳞蹙损金波碎。好天良夜酒盈尊，心自醉，愁难睡。西风月落城乌起。'},
    {t:'天仙子·梦里蘼芜青一翦',a:'纳兰性德〔清代〕',c:'梦里蘼芜青一翦，玉郎经岁音书远。暗钟明月不归来，梁上燕，轻罗扇，好风又落桃花片。'},
    {t:'天仙子·燕语莺啼三月半',a:'佚名〔五代〕',c:'燕语莺啼三月半，烟蘸柳条金香乱。五陵原上有仙娥，携歌扇，香烂漫，留住九华云一片。\n犀玉满头花满面，负妾一双偷泪眼。泪珠若得似真珠，拈不散，知何限，串向红丝点百万。'},
    {t:'天仙子·月落城乌啼未了',a:'纳兰性德〔清代〕',c:'月落城乌啼未了，起来翻为无眠早。薄霜庭院怯生衣，心悄悄，红阑绕。此情待共谁人晓？'},
    {t:'天仙子·走马探花花发未',a:'苏轼〔宋代〕',c:'走马探花花发未。人与化工俱莺易。千回来绕百回看，蜂作婢，莺为使。谷雨清明空屈指。\n白发卢郎情未已。一夜翦刀收玉蕊。尊前还对断肠红。人有泪，花无意。明日酒醒应满地。'},
    {t:'天涯',a:'李商隐〔唐代〕',c:'春日在天涯，天涯日又斜。\n莺啼如有泪，为湿最高花。'},
    {t:'天育骠骑歌',a:'杜甫〔唐代〕',c:'吾闻天子之马走千里，今之画图无乃是。\n是何意态雄且杰，骏尾萧梢朔风起。\n毛为绿缥两耳黄，眼有紫焰双瞳方。\n矫矫龙性合变化，卓立天骨森开张。\n伊昔太仆张景顺，监牧攻驹阅清峻。\n遂令大奴守天育，别养骥子怜神俊。\n当时四十万匹马，张公叹其材尽下。\n故独写真传世人，见之座右久更新。\n年多物化空形影，呜呼健步无由骋。\n如今岂无騕褭与骅骝，时无王良伯乐死即休。'},
    {t:'天长寺上方别子西有道',a:'韦应物〔唐代〕',c:'假邑非拙素，况乃别伊人。聊登释氏居，携手恋兹晨。\n高旷出尘表，逍遥涤心神。青山对芳苑，列树绕通津。\n车马无时绝，行子倦风尘。今当遵往路，伫立欲何申。\n唯持贞白志，以慰心所亲。'},
    {t:'添春色',a:'秦观〔宋代〕',c:'唤起一声人悄。衾冷梦寒窗晓。瘴雨过，海棠晴，春色又添多少。\n社瓮酿成微笑。半缺癭瓢共舀。觉倾倒，急投床，醉乡广大人间小。'},
    {t:'添盆中石菖蒲水仙花水',a:'杨万里〔宋代〕',c:'旧诗一读一番新，读罢昏然一欠伸。\n无数盆花争诉渴，老夫却要作闲人。'},
    {t:'添字采桑子·闲愁似与斜阳约',a:'纳兰性德〔清代〕',c:'闲愁似与斜阳约，红点苍苔，蛱蝶飞回。又是梧桐新绿影，上阶来。\n天涯望处音尘断，花谢花开，懊恼离怀。空压钿筐金缕绣，合欢鞋。'},
    {t:'田家',a:'王维〔唐代〕',c:'旧谷行将尽，良苗未可希。\n老年井爱粥，卒岁且无衣。\n雀乳青苔井，鸡鸣白板扉。\n柴车驾羸牸，草屩牧豪狶。\n夕雨红榴拆，新秋绿芋肥。\n饷田桑下憩，旁舍草中归。\n住处名愚谷，何烦问是非。'},
    {t:'田家春望',a:'高适〔唐代〕',c:'出门何所见，春色满平芜。\n可叹无知己，高阳一酒徒。'},
    {t:'田家词',a:'元稹〔唐代〕',c:'牛靿咤咤，田确确，旱块敲牛蹄来来。\n种得官仓珠颗谷，六十年来兵簇簇，肉月食粮车辘辘。\n一肉官军收海服，驱牛驾车食牛肉，归来收得牛两角。\n重铸锄犁作斤劚，姑舂妇担去输官，输官不足归卖屋。\n愿官早胜仇早覆，农死有儿牛有犊，誓不遣官军粮不足。'},
    {t:'田家词·一作田家行',a:'元稹〔唐代〕',c:'牛吒吒，田确确。旱块敲牛蹄兵兵，种得归仓珠颗谷。\n六十年来兵蔟蔟，月月食粮车辘辘。一日归军收海服，\n驱牛驾车食牛肉。归来攸得牛两角，重铸锄犁作斤劚。\n姑舂妇担去输归，输归不足归卖屋，愿归早胜雠早覆。\n农死有儿牛有犊，誓不遣归军粮不足。'},
    {t:'田家乐',a:'杨万里〔宋代〕',c:'稻穗堆场谷满车，家家鸡犬更桑麻。\n漫栽木槿成篱落，已得清阴又得花。'},
    {t:'田家三首·其二',a:'柳宗元〔唐代〕',c:'篱落隔烟火，农谈四邻夕。\n庭际秋虫鸣，疏麻方寂历。\n蚕丝尽输税，机杼空倚壁。\n里胥夜经过，鸡黍事筵席。\n各言官长峻，文字多督责。\n东乡后租期，车毂陷泥泽。\n公门少推恕，鞭朴恣狼藉。\n努力慎经营，肌肤真可惜。\n迎新在此岁，唯恐踵前迹。'},
    {t:'田家三首·其三',a:'柳宗元〔唐代〕',c:'古道饶蒺藜，萦回古城曲。\n蓼花竟堤岸，陂水寒更绿。\n是时收获竟，落日多樵牧。\n风高榆柳疏，霜重梨枣熟。\n行人迷去住，野鸟竞栖宿。\n田翁笑相念，昏黑慎原陆。\n今年幸少丰，无厌饘与粥。'},
    {t:'田家元日',a:'孟浩然〔唐代〕',c:'昨夜斗回北，今朝岁起东。\n我年已强仕，无禄尚忧农。\n桑野就耕父，荷锄随牧童。\n田家占气候，共说此年丰。'},
    {t:'田居四首',a:'秦观〔宋代〕',c:'入夏桑柘稠，阴阴翳墟落。\n新麦已登场，余蚕犹占箔。\n隆曦破层阴，霁霭收远壑。\n雌蜺卧沦漪，鲜飙泛丛薄。\n林深鸟更鸣，水漫鱼知乐。\n羸老厌烦歊，解衣屡盘礡。\n荫树濯凉颸，起行遗带索。\n冢妇饷初还，丁男耘有托。\n倒筒备青钱，盐茗恐垂橐。\n明日输绢租，邻儿入城郭。'},
    {t:'田舍',a:'杜甫〔唐代〕',c:'田舍清江曲，柴门古道旁。\n草深迷市井，地僻懒衣裳。\n榉柳枝枝弱，枇杷树树香。\n鸬鹚西日照，晒翅满鱼梁。'},
    {t:'田使君美人舞如莲花北鋋歌',a:'岑参〔唐代〕',c:'美人舞如莲花旋，世人有眼应未见。\n高堂满地红氍毹，试舞一曲天下无。\n此曲胡人传入汉，诸客见之惊且叹。\n慢脸娇娥纤复秾，轻罗金缕花葱茏。\n回裾转袖若飞雪，左鋋右鋋生旋风。\n琵琶横笛和未匝，花门山头黄云合。\n忽作出塞入塞声，白草胡沙寒飒飒。\n翻身入破如有神，前见后见回回新。\n始知诸曲不可比，采莲落梅徒聒耳。\n世人学舞只是舞，恣态岂能得如此。'},
    {t:'田顺郎歌',a:'刘禹锡〔唐代〕',c:'清歌不是世间音，玉殿尝闻称主心。\n唯有顺郎全学得，一声飞出九重深。'},
    {t:'田园乐七首·其二',a:'王维〔唐代〕',c:'再见封侯万户，立谈赐璧一双。\n讵胜耦耕南亩，何如高卧东窗。'},
    {t:'田园乐七首·其六',a:'王维〔唐代〕',c:'桃红复含宿雨，柳绿更带朝烟。\n花落家童未扫，莺啼山客犹眠。'},
    {t:'田园乐七首·其七',a:'王维〔唐代〕',c:'酌酒会临泉水，抱琴好倚长松。\n南园露葵朝折，东谷黄粱夜舂。'},
    {t:'田园乐七首·其三',a:'王维〔唐代〕',c:'采菱渡头风急，策杖林西日斜。\n杏树坛边渔父，桃花源里人家。'},
    {t:'田园乐七首·其四',a:'王维〔唐代〕',c:'萋萋春草秋绿，落落长松夏寒。\n牛羊自归村巷，童稚不识衣冠。'},
    {t:'田园乐七首·其五',a:'王维〔唐代〕',c:'山下孤烟远村，天边独树高原。\n一瓢颜回陋巷，五柳先生对门。'},
    {t:'田园乐七首·其一',a:'王维〔唐代〕',c:'厌见千门万户，经过北里南邻。\n官府鸣珂有底，崆峒散发何人。'},
    {t:'田园言怀',a:'李白〔唐代〕',c:'贾谊三年谪，班超万里侯。\n何如牵白犊，饮水对清流。'},
    {t:'田园作',a:'孟浩然〔唐代〕',c:'弊庐隔尘喧，惟先养恬素。\n卜邻近三径，植果盈千树。\n粤余任推迁，三十犹未遇。\n书剑时将晚，丘园日已暮。\n晨兴自多怀，昼坐常寡悟。\n冲天羡鸿鹄，争食羞鸡鹜。\n望断金马门，劳歌采樵路。\n乡曲无知己，朝端乏亲故。\n谁能为扬雄，一荐甘泉赋。'},
    {t:'填词',a:'纳兰性德〔清代〕',c:'诗亡词乃盛，比兴此焉托。往往极娱工，不如忧患作。\n冬郎一生极憔悴，判与三闾共醒醉。美人芒草可怜春，凤蜡红巾无限泪。\n芒鞋心事杜陵知，唯今只赏杜陵诗。古人且失风人旨，何怪俗眼轻填词。\n词源远过诗律近，拟古乐府特加润。不见句读参差三百篇，已自换头兼转韵。'},
    {t:'迢迢牵牛星',a:'佚名〔两汉〕',c:'迢迢牵牛星，皎皎河汉女。\n纤纤擢素手，札札弄机杼。\n终日不成章，泣涕零如雨。\n河汉清且浅，相去复几许。\n盈盈一水间，脉脉不得语。'},
    {t:'听百舌鸟',a:'王维〔唐代〕',c:'上兰门外草萋萋，未央宫中花里栖。\n亦有相随过御苑，不知若个向金堤。\n入春解作千般语，拂曙能先百鸟啼。\n万户千门应觉晓，建章何必听鸣鸡。'},
    {t:'听崇德君鼓琴',a:'黄庭坚〔宋代〕',c:'月明江静寂寥中，大家敛袂抚颂桐。\n古人已矣古乐在，彷佛雅颂之遗风。\n妙手不易得，善听良两难。\n犹如优昙华，时一出世间。\n两忘琴意与己意，乃似不著十指弹。\n禅心默默三渊静，幽谷清风淡相应。\n丝声谁道不如竹，我已忘言得真性。\n罢琴窗外月沈江，万籁俱空七弦定。'},
    {t:'听弹风入松阕赠杨补阙',a:'王昌龄〔唐代〕',c:'商风入我弦，夜竹深有露。弦悲心林寂，清景不可度。\n寥落幽居心，飕飗青松树。松风吹草白，溪水寒日暮。\n声意去复还，九变待一顾。空山多雨雪，独立君始悟。'},
    {t:'听弹湘妃怨',a:'白居易〔唐代〕',c:'玉轸朱弦瑟瑟徽，吴娃徵调奏湘妃。\n分明曲里愁云雨，似道萧萧郎不归。'},
    {t:'听宫莺',a:'王维〔唐代〕',c:'春树绕宫墙，宫莺啭曙光。\n忽惊啼暂断，移处弄还长。\n隐叶栖承露，攀花出未央。\n游人未应返，为此始思乡。'},
    {t:'听鼓',a:'李商隐〔唐代〕',c:'城头叠鼓声，城下暮江清。\n欲问渔阳掺，时无祢正平。'},
    {t:'听嘉陵江水声，寄深上人',a:'韦应物〔唐代〕',c:'凿崖泄奔湍，称古神禹迹。夜喧山门店，独宿不安席。\n水性自云静，石中本无声。如何两相激，雷转空山惊。\n贻之道门旧，了此物我情。'},
    {t:'听嘉陵江水声寄深上人',a:'韦应物〔唐代〕',c:'凿崖泄奔湍，古称神禹迹。\n夜喧山门店，独宿不安席。\n水性自云静，石中本无声；\n如何两相激，雷转空山惊？\n贻之道门旧，了此物我情。'},
    {t:'听江笛送陆侍御·同丘员外赋题',a:'韦应物〔唐代〕',c:'远听江上笛，临觞一送君。还愁独宿夜，更向郡斋闻。'},
    {t:'听旧宫中乐人穆氏唱歌',a:'刘禹锡〔唐代〕',c:'曾随织女渡天河，记得云间第一歌。\n休唱贞元供奉曲，当时朝士已无多。'},
    {t:'听蓝溪僧为元居士说维摩经',a:'孟郊〔唐代〕',c:'古树少枝叶，真僧亦相依。山木偈曲直，道人无是非。\n手持维摩偈，心向居士归。空景忽开霁，雪花犹在衣。\n洗然水溪昼，寒物生光辉。'},
    {t:'听流人水调子',a:'王昌龄〔唐代〕',c:'孤舟微月对枫林，分付鸣筝与客心。\n岭色千重万重雨，断弦收与泪痕深。'},
    {t:'听琴',a:'孟郊〔唐代〕',c:'飒飒微雨收，翻翻橡叶鸣。月沉琴峰西，寥落三四星。\n前溪忽调琴，隔林寒琤琤。闻弹正弄声，不中枕上听。\n回烛整头簪，漱泉立中庭。定步屐齿深，貌禅目冥冥。\n微风吹衣襟，亦认宫徵声。学道三十年，未免忧死生。\n闻弹一夜中，会尽天地情。'},
    {t:'听蜀僧濬弹琴',a:'李白〔唐代〕',c:'蜀僧抱绿绮，西下峨眉峰。\n为我一挥手，如听万壑松。\n客心洗流水，馀响入霜钟。\n不觉碧山暮，秋云暗几重。'},
    {t:'听夜泉',a:'张籍〔唐代〕',c:'细泉深处落，夜久渐闻声。独起出门听，欲寻当涧行。\n还疑隔林远，复畏有风生。月下长来此，无人亦到明。'},
    {t:'听莺曲',a:'韦应物〔唐代〕',c:'东方欲曙花冥冥，啼莺相唤亦可听。\n乍去乍来时近远，才闻南陌又东城。\n忽似上林翻下苑，绵绵蛮蛮如有情。\n欲啭不啭意自娇，羌儿弄笛曲未调。\n前声后声不相及，秦女学筝指犹涩。\n须臾风暖朝日暾，流音变作百鸟喧。\n谁家懒妇惊残梦，何处愁人忆故园。\n伯劳飞过声跼促，戴胜下时桑田绿。\n不及流莺日日啼，能使万家春意闲。\n有时断续听不了，飞去花枝犹袅袅。\n还栖碧树锁千门，春漏方残一声晓。'},
    {t:'听颖师弹琴',a:'韩愈〔唐代〕',c:'昵昵儿女语，恩怨相尔汝。\n划然变轩昂，勇士赴敌场。\n浮云柳絮无根蒂，天地阔远随飞扬。\n喧啾百鸟群，忽见孤凤皇。\n跻攀分寸不可上，失势一落千丈强。\n嗟余有两耳，未省听丝篁。\n自闻颖师弹，起坐在一旁。\n推手遽止之，湿衣泪滂滂。\n颖乎尔诚能，无以冰炭置我肠！'},
    {t:'听颖师琴歌',a:'李贺〔唐代〕',c:'别浦云归桂花渚，蜀国弦中双凤语。芙蓉叶落秋鸾离，\n越王夜起游天姥。暗珮清臣敲水玉，渡海蛾眉牵白鹿。\n谁看挟剑赴长桥，谁看浸发题春竹。竺僧前立当吾门，\n梵宫真相眉棱尊。古琴大轸长八尺，峄阳老树非桐孙。\n凉馆闻弦惊病客，药囊暂别龙须席。请歌直请卿相歌，\n奉礼官卑复何益。'},
    {t:'听雨',a:'杨万里〔宋代〕',c:'归舟昔岁宿严陵，雨打疏篷听到明。\n昨夜茅檐疏雨作，梦中唤作打篷声。'},
    {t:'听雨',a:'陆游〔宋代〕',c:'老态龙钟疾未平，更堪俗事败幽情。\n纱幮笛簟差堪乐，且听萧萧暮雨声。'},
    {t:'听张立本女吟',a:'高适〔唐代〕',c:'危冠广袖楚宫妆，独步闲庭逐夜凉。\n自把玉钗敲砌竹，清歌一曲月如霜。'},
    {t:'听筝',a:'张九龄〔唐代〕',c:'端居正无绪，那复发秦筝。\n纤指传新意，繁弦起怨情。\n悠扬思欲绝，掩抑态还生。\n岂是声能感，人心自不平。'},
    {t:'听郑五愔弹琴',a:'孟浩然〔唐代〕',c:'阮籍推名饮，清风坐竹林。\n半酣下衫袖，拂拭龙唇琴。\n一杯弹一曲，不觉夕阳沉。\n余意在山水，闻之谐夙心。'},
    {t:'庭橘',a:'孟浩然〔唐代〕',c:'明发览群物，万木何阴森。凝霜摘摘水，庭橘似悬金。\n女伴争攀摘，摘窥碍叶深。并生怜共蒂，相示感同心。\n骨刺红罗被，香黏翠羽簪。擎来玉盘里，全胜在幽林。'},
    {t:'庭梅咏',a:'张九龄〔唐代〕',c:'芳意何能早，孤荣亦自危。更怜花蒂弱，不受岁寒移。\n朝雪那相妒，阴风已屡吹。馨香虽尚尔，飘荡复谁知。'},
    {t:'庭楸',a:'韩愈〔唐代〕',c:'庭楸止五株，共生十步间。各有地绕之，上各相钩联。\n下叶各垂地，树颠各云连。朝日出其东，我东坐西偏。\n夕日在其西，我东坐东边。当昼日在上，我在中央间。\n仰视何青青，上不见纤穿。朝暮无日时，我且八九旋。\n濯濯晨露香，明珠何联联。夜月来照之，蒨蒨自生烟。\n我已自顽钝，重遭五楸牵。客来尚不见，肯到权门前。\n权门众所趋，有客动百千。九牛亡一毛，未在多少间。\n往既无可顾，不往自可怜。'},
    {t:'庭中有奇树',a:'佚名〔两汉〕',c:'庭中有奇树，绿叶发华滋。\n攀条折其荣，将以遗所思。\n馨香盈怀袖，路远莫致之。\n此物何足贵？但感别经时。'},
    {t:'庭竹',a:'刘禹锡〔唐代〕',c:'露涤铅粉节，风摇青玉枝。\n依依似君子，无地不相宜。'},
    {t:'停云·其二',a:'陶渊明〔魏晋〕',c:'停云霭霭，时雨濛濛。\n八表同昏，平陆成江。\n有酒有酒，闲饮东窗。\n愿言怀人，舟车靡从。'},
    {t:'艇斋',a:'秦观〔宋代〕',c:'平生乐渔钓，放浪江湖间。\n兀兀寄幽艇，不忧浪如山。\n闻君城郭居，左右群书环。\n有斋亦名艇，何时许追攀。\n钓古不钓今，所得孔与颜。\n不然如尔祖，跨鹤出云寰。'},
    {t:'通化门外送别',a:'张九龄〔唐代〕',c:'屡别容华改，长愁意绪微。义将私爱隔，情与故人归。\n薄宦无时赏，劳生有事机。离魂今夕梦，先绕旧林飞。'},
    {t:'通泉驿南去通泉县十五里山水作',a:'杜甫〔唐代〕',c:'溪行衣自湿，亭午气始散。\n冬温蚊蚋集，人远凫鸭乱。\n登顿生曾阴，欹倾出高岸。\n驿楼衰柳侧，县郭轻烟畔。\n一川何绮丽，尽目穷壮观。\n山色远寂寞，江光夕滋漫。\n伤时愧孔父，去国同王粲。\n我生苦飘零，所历有嗟叹。'},
    {t:'同白侍郎杏园赠刘郎中',a:'张籍〔唐代〕',c:'一去潇湘头欲白，今朝始见杏花春。\n从来迁客应无数，重到花前有几人。'},
    {t:'同褒子秋斋独宿',a:'韦应物〔唐代〕',c:'山月皎如烛，风霜时动竹。\n夜半鸟惊栖，窗间人独宿。'},
    {t:'同曹三御史行泛湖归越',a:'孟浩然〔唐代〕',c:'秋入诗人兴，巴歌和者稀。\n泛湖同逸旅，吟会是思归。\n白简徒推荐，沧洲已拂衣。\n杳冥云海去，谁不羡鸿飞？'},
    {t:'同陈留崔司户早春宴蓬池',a:'高适〔唐代〕',c:'同官载酒出郊圻，晴日东驰雁北飞。隔岸春云邀翰墨，\n傍檐垂柳报芳菲。池边转觉虚无尽，台上偏宜酩酊归。\n州县徒劳那可度，后时连骑莫相违。'},
    {t:'同储十二洛阳道中作',a:'孟浩然〔唐代〕',c:'珠弹繁华子，金羁游侠人。\n酒酣白日暮，走马入红尘。'},
    {t:'同从弟南斋玩月忆山阴崔少府',a:'王昌龄〔唐代〕',c:'高卧南斋时，开帷月初吐。\n清辉澹水木，演漾在窗户。\n冉冉几盈虚，澄澄变今古。\n美人清江畔，是夜越吟苦。\n千里共如何，微风吹兰杜。'},
    {t:'同崔傅答贤弟',a:'王维〔唐代〕',c:'洛阳才子姑苏客，桂苑殊非故州陌。\n九江枫树几回青，一片扬州五湖白。\n扬州时有下江兵，兰郭镇前吹笛声。\n夜火人归富春郭，秋风鹤唳石头城。\n周郎陆弟为俦侣，对舞前溪歌白纻。\n曲几书留小史家，草堂棋赌山阴野。\n衣冠若话外台臣，先数夫君席上珍。\n更闻台阁求三语，遥想风流第一人。'},
    {t:'同崔员外秋宵寓直',a:'王维〔唐代〕',c:'建礼高秋夜，承明候晓过。\n九门寒漏彻，万井曙钟多。\n月迥藏珠斗，云消出绛河。\n更惭衰朽质，南陌共鸣珂。'},
    {t:'同德寺雨后寄元侍御李博士',a:'韦应物〔唐代〕',c:'川上风雨来，须臾满城阙。\n岧峣净莲界，萧条孤兴发。\n前山遽已净，阴霭夜来歇。\n乔木生夏凉，流云吐华月。\n严城自有限，一水非难越。\n相望曙河远，高斋坐超忽。'},
    {t:'同独孤使君东斋作',a:'孟浩然〔唐代〕',c:'郎官旧华省，天子命分忧。襄土楚频旱，随车雨再流。\n云阴自南楚，河润及东周。廨宇宜新霁，田家贺有秋。\n竹间残照入，池上夕阳浮。寄谢东阳守，何如八咏楼。'},
    {t:'同房侍御山园新亭与邢判官同游',a:'高适〔唐代〕',c:'隐隐春城外，朦胧陈迹深。君子顾榛莽，兴言伤古今。\n决河导新流，疏径踪旧林。开亭俯川陆，时景宜招寻。\n肃穆逢使轩，夤缘事登临。忝游芝兰室，还对桃李阴。\n岸远白波来，气喧黄鸟吟。因睹歌颂作，始知经济心。\n灌坛有遗风，单父多鸣琴。谁为久州县，苍生怀德音。'},
    {t:'同观陈十六史兴碑',a:'高适〔唐代〕',c:'荆衡气偏秀，江汉流不歇。此地步精灵，有时生才杰。\n伊人今独步，逸思能间发。永怀掩风骚，千日常矻矻。\n新碑亦崔嵬，佳句悬日月。则是刊石经，终然继梼杌。\n我来观雅制，慷慨变毛发。季主尽荒淫，前王徒贻厥。\n东周既削弱，两汉更沦没。西晋何披猖，五胡相唐突。\n作歌乃彰善，比物仍恶讦。感叹将谓谁，对之空咄咄。'},
    {t:'同冠峡·贞元十九年贬阳山后作',a:'韩愈〔唐代〕',c:'南方二月半，春物亦已少。维舟山水间，晨坐听百鸟。\n宿云尚含姿，朝日忽升晓。羁旅感和鸣，囚拘念轻矫。\n潺湲泪久迸，诘曲思增绕。行矣且无然，盖棺事乃了。'},
    {t:'同郭十题杨主簿新厅',a:'高适〔唐代〕',c:'华馆曙沈沈，惟良正在今。用材地柱石，闻物象高深。\n更得芝兰地，地营枳棘林。向风扃戟户，当署近棠阴。\n勿改安卑节，聊闲理剧心。多君有知己，一和郢中吟。'},
    {t:'同韩郎中闲庭南望秋景',a:'韦应物〔唐代〕',c:'朝下抱馀素，地高心本闲。如何趋府客，罢秩见秋山。\n疏树共寒意，游禽同暮还。因君悟清景，西望一开颜。'},
    {t:'同韩侍御南溪夜赏',a:'张籍〔唐代〕',c:'喜作闲人得出城，南溪两月逐君行。\n忽闻新命须归去，一夜船中语到明。'},
    {t:'同韩四、薛三东亭玩月',a:'高适〔唐代〕',c:'远游怅不乐，兹赏吾道存。款曲寥人意，辛勤清夜言。\n东亭何寥寥，佳境无朝昏。阶墀近洲渚，户讨当郊原。\n矧乃穷周旋，游时怡讨论。树阴荡瑶瑟，月气延清尊。\n明河带飞雁，野火连荒村。对此更愁予，悠哉怀寥园。'},
    {t:'同敬八、卢五泛河间清河',a:'高适〔唐代〕',c:'清川在城下，沿泛多所宜。同济惬数公，玩物欣良时。\n飘飖波上兴，燕婉舟中词。昔陟乃平原，今来忽涟漪。\n东流达沧海，西流延滹池。云树共晦明，井邑相逶迤。\n稍随归月帆，若与沙鸥期。渔父更留我，前潭水未滋。'},
    {t:'同敬八卢五汎河间清河',a:'高适〔唐代〕',c:'清川在城下，沿汎多所宜。同济惬数公，玩物欣良时。\n飘飖波上兴，燕婉舟中词。昔陟乃平原，今来忽涟漪。\n东流达沧海，西流延滹池。云树共晦明，井邑相逶迤。\n稍随归月帆，若与沙鸥期。渔父更留我，前潭水未滋。'},
    {t:'同乐天登栖灵寺塔',a:'刘禹锡〔唐代〕',c:'步步相携不觉难，九层云外倚阑干。\n忽然笑语半天上，无限游人举眼看。'},
    {t:'同乐天和微之深春二十首其二十',a:'刘禹锡〔唐代〕',c:'何处春深好，春深稚子家。争骑一竿竹，偷折四邻花。\n笑击羊皮鼓，行牵犊颔车。中庭贪夜戏，不觉玉绳斜。'},
    {t:'同李九士曹观壁画云作',a:'高适〔唐代〕',c:'始知帝乡客，能画苍梧云。秋天万里一片色，\n只疑飞尽犹氛氲。'},
    {t:'同李十一醉忆元九',a:'白居易〔唐代〕',c:'花时同醉破春愁，醉折花枝作酒筹。\n忽忆故人天际去，计程今日到梁州。'},
    {t:'同李洗马入馀不溪经辛将军故城',a:'皎然〔唐代〕',c:'惨惨寒城望，将军下世时。高墉暮草遍，大树野风悲。\n壁垒今惟在，勋庸近可思。苍然古溪上，川逝共凄其。'},
    {t:'同李员外贺哥舒大夫破九曲之作',a:'高适〔唐代〕',c:'遥传副丞相，昨日破西蕃。作气群山动，扬军大旆翻。\n奇兵邀转战，连孥绝归奔。泉喷诸戎血，风驱死虏魂。\n头飞攒万戟，面缚聚辕门。鬼哭黄埃暮，天愁白日昏。\n石城与岩险，铁骑皆云屯。长策一言决，高踪百代存。\n威棱慑沙漠，忠义感乾坤。老将黯无色，儒生安敢论。\n解围凭庙算，止杀报君恩。唯有关河渺，苍茫空树墩。'},
    {t:'同李中丞洪水亭夜集',a:'皎然〔唐代〕',c:'佳人但莫吹参差，正怜月色生酒卮。\n山公取醉不关我，为爱尊前白鹭鹚。'},
    {t:'同李著作纵题尘外上人院',a:'皎然〔唐代〕',c:'百缘唯有什公瓶，万法但看一字经。从遣鸟喧心不动，\n任教香醉境常冥。莲花天昼浮云卷，贝叶宫春好月停。\n禅伴欲邀何著作，空音宜向夜中听。'},
    {t:'同卢明府早秋宴张郎中海亭',a:'孟浩然〔唐代〕',c:'侧听弦歌宰，文书游夏徒。故园欣赏竹，为邑幸来苏。\n华省曾联事，仙舟复与俱。欲知临泛久，荷露渐成珠。'},
    {t:'同卢使君幼平郊外送阎侍御归台',a:'皎然〔唐代〕',c:'留饯飞旌驻，离亭草色间。柏台水上客，竹使旧朝班。\n日落东西水，天寒远近山。古江分楚望，残柳入隋关。\n恋阙心常积，回轩日不闲。芳辰倚门道，犹得及春还。'},
    {t:'同马太守听九思法师讲金刚经',a:'高适〔唐代〕',c:'吾师晋阳宝，杰出山河最。途经世谛间，心到空王外。\n鸣钟山虎伏，说法天龙会。了义同建瓴，梵法若吹籁。\n深知亿劫苦，善喻恒沙大。舍施割肌肤，攀缘去亲爱。\n招提何清净，良牧驻轻盖。露冕众香中，临人觉苑内。\n心持佛印久，标割魔军退。愿开初地因，永奉弥天对。'},
    {t:'同旻上人伤寿安傅少府',a:'陈子昂〔唐代〕',c:'生涯良浩浩，天命固谆谆。闻道神仙尉，怀德遂为邻。\n畴昔逢尧日，衣冠仕汉辰。交游纷若凤，词翰宛如麟。\n太息劳黄绶，长思谒紫宸。金兰徒有契，玉树已埋尘。\n把臂虽无托，平生固亦亲。援琴一流涕，旧馆几沾巾。\n杳杳泉中夜，悠悠世上春。幽明长隔此，歌哭为何人。'},
    {t:'同年春燕',a:'孟郊〔唐代〕',c:'少年三十士，嘉会良在兹。高歌景春风，醉舞摧花枝。\n意荡晼晚景，喜凝芳菲时。马迹攒騕褭，乐新韵参差。\n视听改旧趣，物象含新姿。红雨花上滴，绿烟柳际垂。\n淹中讲精义，南皮献清词。前贤与今人，千载为一期。\n明鉴有皎洁，澄玉无磷缁。永与沙泥别，各整云汉仪。\n盛气自中积，英名日四驰。塞鸿绝俦匹，海月难等夷。\n郁抑忽已尽，亲朋乐无涯。幽蘅发空曲，芳杜绵所思。\n浮迹自聚散，壮心谁别离。愿保金石志，无令有夺移。'},
    {t:'同裴录事楼上望',a:'皎然〔唐代〕',c:'退食高楼上，湖山向晚晴。桐花落万井，月影出重城。\n水竹凉风起，帘帏暑气清。萧萧独无事，因见莅人情。'},
    {t:'同綦毋学士月夜闻雁',a:'张九龄〔唐代〕',c:'栖宿岂无意，飞飞更远寻。\n长途未及半，中夜有遗音。\n月思关山笛，风号流水琴。\n空声两相应，幽感一何深。\n避缴归南浦，离群叫北林。\n联翩俱不定，怜尔越乡心。'},
    {t:'同群公出猎海上',a:'高适〔唐代〕',c:'畋猎自古昔，况伊心赏俱。偶与群公游，旷然出平芜。\n层阴涨溟海，杀气穷幽都。鹰隼何翩翩，驰骤相传呼。\n豺狼窜榛莽，麋鹿罹艰虞。高鸟下騂弓，困兽斗匹夫。\n尘惊大泽晦，火燎深林枯。失之有馀恨，获者无全驱。\n咄彼工拙间，恨非指踪徒。犹怀老氏训，感叹此欢娱。'},
    {t:'同群公登濮阳圣佛寺阁',a:'高适〔唐代〕',c:'落日登临处，悠然意不穷。佛因初地识，人觉四天空。\n来雁清霜后，孤帆远树中。裴回伤寓目，萧索对寒风。'},
    {t:'同群公秋登琴台',a:'高适〔唐代〕',c:'古迹使人感，琴台空寂寥。静然始遗尘，千载如昨朝。\n临眺自兹始，群贤久相邀。德与形神高，孰秋天地遥。\n四时何倏忽，六月鸣秋蜩。万象归白帝，平川横赤霄。\n犹是对夏伏，几时有凉飙。燕雀满檐楹，鸿鹄抟扶摇。\n物性各自得，我心在渔樵。兀然还复醉，尚握尊中瓢。'},
    {t:'同群公十月朝宴李太守宅',a:'高适〔唐代〕',c:'良牧征高赏，褰帷问考槃。岁时当正月，甲子入初寒。\n已听甘棠颂，欣陪旨酒欢。仍怜门下客，不作布衣看。'},
    {t:'同群公宿开善寺，赠陈十六所居',a:'高适〔唐代〕',c:'驾车出人境，避暑投僧家。裴回龙象侧，始见香林花。\n读书不及经，饮酒不胜茶。知君悟此道，所未搜袈裟。\n谈空忘外物，持诫破诸邪。则是无心地，相看唯月华。'},
    {t:'同群公题张处士菜园',a:'高适〔唐代〕',c:'耕地桑柘间，地肥菜常熟。为问葵藿资，何如庙堂肉。'},
    {t:'同群公题郑少府田家',a:'高适〔唐代〕',c:'郑侯应悽惶，五十头尽白。昔为南昌尉，今作东郡客。\n与语多远情，论心知所益。秋林既清旷，穷巷空淅沥。\n蝶舞园更闲，鸡鸣日云夕。男儿未称意，其道固无适。\n劝君且杜门，勿叹人事隔。'},
    {t:'同群公题中山寺',a:'高适〔唐代〕',c:'平原十里外，稍稍云岩深。遂及清净所，都无人世心。\n名僧既礼谒，高阁复登临。石壁倚松径，山田多栗林。\n超遥尽巘崿，逼侧仍岖嶔。吾欲休世事，于焉聊自任。'},
    {t:'同沈驸马赋得御沟水',a:'李贺〔唐代〕',c:'入苑白泱泱，宫人正靥黄。\n绕堤龙骨冷，拂岸鸭头香。\n别馆惊残梦，停杯泛小觞。\n幸因流浪处，暂得见何郎。'},
    {t:'同王九题就师山房',a:'孟浩然〔唐代〕',c:'晚憩支公室，故人逢右军。轩窗日炎暑，翰墨动新文。\n竹蔽檐前日，雨随阶下云。周游清荫遍，吟卧夕阳曛。\n江静棹歌歇，溪深樵语闻。归途未忍去，携手恋清芬。'},
    {t:'同卫八题陆少府书斋',a:'高适〔唐代〕',c:'知君薄州县，好静无冬春。散帙至栖鸟，明灯留故人。\n深房腊酒熟，高院梅花新。若是周旋地，当令风义亲。'},
    {t:'同熊伯通自定林过悟真二首',a:'王安石〔宋代〕',c:'与客东来欲试茶，倦投松石坐欹斜。\n暗香一阵连风起，知有蔷薇涧底花。'},
    {t:'同颜六少府旅宦秋中之作',a:'高适〔唐代〕',c:'传君昨夜怅然悲，独坐新斋木得时。逸气旧来凌燕雀，\n高才何得混妍媸。迹留黄绶人多叹，心在青云世莫知。\n不是鬼神无正直，从来州县有瑕疵。'},
    {t:'同元锡题琅琊寺',a:'韦应物〔唐代〕',c:'适从郡邑喧，又兹三伏热。山中清景多，石罅寒泉洁。\n花香天界事，松竹人间别。殿分岚岭明，磴临悬壑绝。\n昏旭穷陟降，幽显尽披阅。嶔骇风雨区，寒知龙蛇穴。\n情虚澹泊生，境寂尘妄灭。经世岂非道，无为厌车辙。'},
    {t:'同越琅琊山',a:'韦应物〔唐代〕',c:'石门有雪无行迹，松壑凝烟满众香。\n馀食施庭寒鸟下，破衣挂树老僧亡。'},
    {t:'同张将蓟门观灯',a:'孟浩然〔唐代〕',c:'异俗非乡俗，新年改故年。\n蓟门看火树，疑是烛龙燃。'},
    {t:'同张明府碧溪赠答',a:'孟浩然〔唐代〕',c:'别业闻新制，同声和者多。还看碧溪答，不羡绿珠歌。\n自有阳台女，朝朝拾翠过。绮筵铺锦绣，妆牖闭藤萝。\n秩满休闲日，春馀景气和。仙凫能作伴，罗袜共凌波。\n曲岛寻花药，回潭折芰荷。更怜斜日照，红粉艳青娥。'},
    {t:'同张明府清镜叹',a:'孟浩然〔唐代〕',c:'妾有盘龙镜，清光常昼发。自从生尘埃，有若雾中月。\n愁来试取照，坐叹生白发。寄语边塞人，如何久离别。'},
    {t:'同赵二十二访张明府郊居联句',a:'杜牧〔唐代〕',c:'陶潜官罢酒瓶空，门掩杨花一夜风。——杜牧\n古调诗吟山色里，无弦琴在月明中。——赵嘏\n远檐高树宜幽鸟，出岫孤云逐晚虹。——杜牧\n别后东篱数枝菊，不知闲醉与谁同。——赵嘏'},
    {t:'同诸公登慈恩寺塔',a:'杜甫〔唐代〕',c:'高标跨苍穹，烈风无时休。\n自非旷士怀，登兹翻百忧。\n方知象教力，足可追冥搜。\n仰穿龙蛇窟，始出枝撑幽。\n七星在北户，河汉声西流。\n羲和鞭白日，少昊行清秋。\n秦山忽破碎，泾渭不可求。\n俯视但一气，焉能辨皇州。\n回首叫虞舜，苍梧云正愁。\n惜哉瑶池饮，日晏昆仑丘。\n黄鹄去不息，哀鸣何所投。\n君看随阳雁，各有稻粱谋。'},
    {t:'同子瞻端午日游诸寺赋得深字',a:'秦观〔宋代〕',c:'太史抱孤韵，畅怀在登临。\n别乘瘦邹枚，佳辰事幽寻。\n参差水石瘦，窅窕房栊深。\n清磬发疏箔，妙嶔横素襟。\n复登窣堵波，环回瞩嶔崟。\n双溪贯城郭，暝色带孤禽。\n凉飙动爽籁，薄雨生微阴。\n尘想澹清涟，牢愁洗芳斟。\n挥箑订往古，援毫示来今。\n愧无刻烛敏，续此金玉音。'},
    {t:'同子瞻赋游惠山三首',a:'秦观〔宋代〕',c:'辍棹纵幽讨，篮舆入青苍。\n圆顶相邀迓，旃檀燎深堂。\n层峦淡如洗，杰阁森欲翔。\n林芳含雨滋，岫日隔林光。\n涓涓续清溜，靡靡传幽香。\n俯仰佳览眺，悠哉身世忘。'},
    {t:'桐花落',a:'元稹〔唐代〕',c:'莎草遍桐阴，桐花满莎落。盖覆相团圆，可怜无厚薄。\n昔岁幽院中，深堂下帘幕。同在后门前，因论花好恶。\n君夸沉檀样，云是指撝作。暗澹灭紫花，句连蹙金萼。\n都绣六七枝，斗成双孔雀。尾上稠叠花，又将金解络。\n我爱看不已，君烦睡先著。我作绣桐诗，系君裙带著。\n别来苦修道，此意都萧索。今日竟相牵，思量偶然错。'},
    {t:'桐庐郡斋书事',a:'范仲淹〔宋代〕',c:'千峰秀处白云骄，吏隐云边岂待招。\n数仞堂高谁富贵，一枝巢隐自逍遥。\n杯中好物闲宜进，林下幽人静可邀。\n莫道官清无岁计，满山芝术长灵苗。'},
    {t:'桐庐山中赠李明府',a:'孟郊〔唐代〕',c:'静境无浊氛，清雨零碧云。千山不隐响，一叶动亦闻。\n即此佳志士，精微谁相群。欲识楚章句，袖中兰茝薰。'},
    {t:'铜官山醉后绝句',a:'李白〔唐代〕',c:'我爱铜官乐，千年未拟还。\n要须回舞袖，拂尽五松山。'},
    {t:'铜驼悲',a:'李贺〔唐代〕',c:'落魄三月罢，寻花去东家。\n谁作客春曲，洛岸悲铜驼。\n桥南多马客，北山饶古人。\n客饮杯中酒，驼悲千万春。\n生世莫徒劳，风吹盘上烛。\n厌见桃株笑，铜驼夜来哭。'},
    {t:'铜鱼使赴都寄亲友',a:'柳宗元〔唐代〕',c:'行尽关山万里馀，到时闾井是荒墟。\n附庸唯有铜鱼使，此后无因寄远书。'},
    {t:'潼关吏',a:'杜甫〔唐代〕',c:'士卒何草草，筑城潼关道。\n大城铁不如，小城万丈余。\n借问潼关吏：修关还备胡？\n要我下马行，为我指山隅：\n连云列战格，飞鸟不能逾。\n胡来但自守，岂复忧西都。\n丈人视要处，窄狭容单车。\n艰难奋长戟，万古用一夫。\n哀哉桃林战，百万化为鱼。\n请嘱防关将，慎勿学哥舒！'},
    {t:'潼关使院怀王七季友',a:'岑参〔唐代〕',c:'王生今才子，时辈咸所仰。何当见颜色，终日劳梦想。\n驱车到关下，欲往阻河广。满日徒春华，思君罢心赏。\n开门见太华，朝日映高掌。忽觉莲花峰，别来更如长。\n无心顾微禄，有意在独往。不负林中期，终当出尘网。'},
    {t:'偷诗',a:'孟郊〔唐代〕',c:'饿犬齰枯骨，自吃馋饥涎。今文与古文，各各称可怜。\n亦如婴儿食，饧桃口旋旋。唯有一点味，岂见逃景延。\n绳床独坐翁，默览有所传。终当罢文字，别著逍遥篇。\n从来文字净，君子不以贤。'},
    {t:'投道一师兰若宿',a:'王维〔唐代〕',c:'一公栖太白，高顶出风烟。\n梵流诸壑遍，花雨一峰偏。\n迹为无心隐，名因立教传。\n鸟来远语法，客去更安禅。\n昼涉松路尽，暮投兰若边。\n洞房隐深竹，清夜闻遥泉。\n向是云霞里，今成枕席前。\n岂唯暂留宿，服事将穷年。'},
    {t:'投坑伎诗',a:'佚名',c:'百尺竿头望九州，前人田土后人收。\n后人收得休欢喜，还有收人在后头。'},
    {t:'投所知',a:'孟郊〔唐代〕',c:'苦心知苦节，不容一毛发。炼金索坚贞，洗玉求明洁。\n自惭所业微，功用如鸠拙。何殊嫫母颜，对彼寒塘月。\n君存古人心，道出古人辙。尽美固可扬，片善亦不遏。\n朝向公卿说，暮向公卿说。谁谓黄钟管，化为君子舌。\n一说清嶰竹，二说变嶰谷。三说四说时，寒花拆寒木。\n晔晔家道路，灿灿我衣服。岂直辉友朋，亦用慰骨肉。\n一暖荷匹素，一饱荷升粟。而况大恩恩，此身报得足。\n且将食檗劳，酬之作金刀。'},
    {t:'投赠张端公',a:'孟郊〔唐代〕',c:'君子量不极，胸吞百川流。\n嫉邪霜气直，问俗春辞柔。\n日户昼辉静，月杯夜景幽。\n咏惊芙蓉发，笑激风飚秋。\n鸾步独无侣，鹤音仍寡俦。\n幸沾分寸顾，散此千万忧。'},
    {t:'投子山',a:'周邦彦〔宋代〕',c:'缅怀鲁将军，兵败携部曲。\n来投衲子衣，解甲饭戎菽。\n谁令名此山，异代有余辱。'},
    {t:'透碧霄·月华边',a:'柳永〔宋代〕',c:'月华边。万年芳树起祥烟。帝居壮丽，皇家熙盛，宝运当千。端门清昼，觚棱照日，双阙中天。太平时、朝野多欢。遍锦街香陌，钧天歌吹，阆苑神仙。\n昔观光得意，狂游风景，再睹更精妍。傍柳阴，寻花径，空恁亸辔垂鞭。乐游雅戏，平康艳质，应也依然。仗何人、多谢婵娟。道宦途踪迹，歌酒情怀，不似当年。'},
    {t:'秃山',a:'王安石〔宋代〕',c:'吏役沧海上，瞻山一停舟。\n怪此秃谁使，乡人语其由。\n一狙山上鸣，一狙从之游。\n相匹乃生子，子众孙还稠。\n山中草木盛，根实始易求。\n攀挽上极高，屈曲亦穷幽。\n众狙各丰肥，山乃尽侵牟。\n攘争取一饱，岂暇议藏收？\n大狙尚自苦，小狙亦已愁。\n稍稍受咋啮，一毛不得留。\n狙虽巧过人，不善操锄耰。\n所嗜在果谷，得之常以偷。\n嗟此海山中，四顾无所投。\n生生未云已，岁晚将安谋？'},
    {t:'徒步归行',a:'杜甫〔唐代〕',c:'明公壮年值时危，经济实藉英雄姿。\n国之社稷今若是，武定祸乱非公谁。\n凤翔千官且饱饭，衣马不复能轻肥。\n青袍朝士最困者，白头拾遗徒步归。\n人生交契无老少，论交何必先同调。\n妻子山中哭向天，须公枥上追风骠。'},
    {t:'途次望乡',a:'孟浩然〔唐代〕',c:'客行愁落日，乡思重相催。\n况在他山外，天寒夕鸟来。\n雪深迷郢路，云暗失阳台。\n可叹凄惶子，高歌谁为媒。'},
    {t:'途中寄徐录事·比以王书见赠',a:'高适〔唐代〕',c:'落日风雨至，秋天鸿雁初。离忧不堪比，旅馆复何如。\n君又几时去，我知音信疏。空多箧中赠，长见右军书。'},
    {t:'途中一绝',a:'杜牧〔唐代〕',c:'镜中丝发悲来惯，衣上尘痕拂渐难。\n惆怅江湖钓竿手，却遮西日向长安。'},
    {t:'途中遇晴',a:'孟浩然〔唐代〕',c:'已失巴陵雨，犹逢蜀坂泥。\n天开斜景遍，山出晚云低。\n馀湿犹沾草，残流尚入溪。\n今宵有明月，乡思远凄凄。'},
    {t:'途中早发',a:'刘禹锡〔唐代〕',c:'马踏尘上霜，月明江头路。行人朝气锐，宿鸟相辞去。\n流水隔远村，缦山多红树。悠悠关塞内，往来无闲步。'},
    {t:'途中作',a:'王昌龄〔唐代〕',c:'游人愁岁晏，早起遵王畿。坠叶吹未晓，疏林月微微。\n惊禽栖不定，寒兽相因依。叹此霜露下，复闻鸿雁飞。\n渺然江南意，惜与中途违。羁旅悲壮发，别离念征衣。\n永图岂劳止，明节期所归。宁厌楚山曲，无人长掩扉。'},
    {t:'酴醾金沙二花合发',a:'王安石〔宋代〕',c:'相扶照水弄春柔，发似矜夸歛似羞。\n碧合晚云霞上起，红争朝日雪边流。\n我无丹白知如梦，人有朱铅见即愁。\n疑此冶容诗所忌，故将樛木比绸缪。'},
    {t:'兔丝',a:'元稹〔唐代〕',c:'人生莫依倚，依倚事不成。\n君看密丝蔓，依倚榛与荆。\n荆榛易蒙密，百鸟撩乱鸣。\n下有狐密穴，奔之亦纵横。\n樵童斫将去，柔蔓与之并。\n翳荟生可耻，束缚死无名。\n桂树月中出，珊瑚石上生。\n俊鹘度海食，应龙升天行。\n灵物本特达，不复相缠萦。\n缠萦竟何者，荆棘与飞茎。'},
    {t:'退居·一作退老',a:'孟郊〔唐代〕',c:'退身何所食，败力不能闲。种稻耕白水，负薪斫青山。\n众听喜巴唱，独醒愁楚颜。日暮静归时，幽幽扣松关。'},
    {t:'玩萤火',a:'韦应物〔唐代〕',c:'时节变衰草，物色近新秋。\n度月影才敛，绕竹光复流。'},
    {t:'挽李制帅二首',a:'文天祥〔宋代〕',c:'上下荆淮剑气雄，进担全蜀凛英风。\n将坛歃血金汤志，白腹填天竹帛功。\n治法征谋关世道，清忠定力简皇衷。\n伤哉生出瞿塘险，翻落黄粱一梦中。\n世变江河渺未涯，如公真是济时危。\n几年荆益龙骧誉，一日潇湘鵩谶悲。\n天下皆传清献节，人心自有武侯碑。\n郎君昔共慈恩约，抆泪西风寄些词。'},
    {t:'挽刘宝学二首其二',a:'朱熹〔宋代〕',c:'生死公何有，飘零我自伤。向非怜不造，那得此深藏。\n心折风霜里，衣沾子侄行。哦诗当肃挽，悲哽不成章。'},
    {t:'挽刘宝学二首其一',a:'朱熹〔宋代〕',c:'天地谁翻覆，人谋痛莫支。公扶西极柱，威动北征旗。\n肉食谋何鄙，家山志忽赍。平生出师表，今日重伤悲。'},
    {t:'挽舟者歌',a:'佚名〔隋代〕',c:'我兄征辽东，饿死青山下。\n今我挽龙舟，又阻隋堤道。\n方今天下饥，路粮无些小。\n前去三千程，此身安可保！\n寒骨枕荒沙，幽魂泣烟草。\n悲损门内妻，望断吾家老。\n安得义男儿，焚此无主尸。\n引其孤魂回，负其白骨归！'},
    {t:'晚出左掖',a:'秦观〔宋代〕',c:'金爵觚棱转夕晖，翩翩宫叶堕秋衣。\n出门尘障如黄雾，始觉身从天上归。'},
    {t:'晚春',a:'晏几道〔宋代〕',c:'一春无事又成空，拥鼻微吟半醉中。夹道桃花新过雨，马蹄无处避残红。'},
    {t:'晚春',a:'元稹〔唐代〕',c:'昼静帘疏燕语频，双双斗雀动阶尘。\n柴扉日暮随风掩，落尽闲花不见人。'},
    {t:'晚春二首·其二',a:'韩愈〔唐代〕',c:'谁收春色将归去，慢绿妖红半不存。\n榆荚只能随柳絮，等闲撩乱走空园。'},
    {t:'晚春二首·其一',a:'韩愈〔唐代〕',c:'草树知春不久归，百般红紫斗芳菲。\n杨花榆荚无才思，惟解漫天作雪飞。'},
    {t:'晚春感事四首·其四',a:'陆游〔宋代〕',c:'少年骑马入咸阳，鹘似身轻蝶似狂。\n蹴鞠场边万人看，秋千旗下一春忙。\n风光流转浑如昨，志气低摧只自伤。\n日永东斋淡无事，闭门扫地独焚香。'},
    {t:'晚春归思',a:'王维〔唐代〕',c:'新妆可怜色，落日卷罗帷。\n炉气清珍簟，墙阴上玉墀。\n春虫飞网户，暮雀隐花枝。\n向晚多愁思，闲窗桃李时。'},
    {t:'晚春过崔驸马东园',a:'张籍〔唐代〕',c:'闲园多好风，不意在街东。早早诗名远，长长酒性同。\n竹香新雨后，莺语落花中。莫遣经过少，年光渐觉空。'},
    {t:'晚春题远上人南亭',a:'孟浩然〔唐代〕',c:'给园支遁隐，虚寂养身和。春晚群木秀，间关黄鸟歌。\n林栖居士竹，池养右军鹅。炎月北窗下，清风期再过。'},
    {t:'晚春卧疾寄张八子容①',a:'孟浩然〔唐代〕',c:'南陌春将晚，北窗犹卧病。林园迷不游，草木一何盛。\n狭迳花障迷，闲庭竹扫净。翠羽戏兰苕，赪从动荷柄。\n念我平生好，江乡远从政。云山阻梦思，衾枕劳歌咏。\n歌咏复何为，同心恨别离。世途皆自媚，流俗寡相知。\n贾谊才空逸，安仁鬓欲丝。遥情每东注，奔晷复西驰。\n常恐填沟壑，无由振羽仪。穷通若有命，欲向论中推。'},
    {t:'晚春寻桃源观',a:'皎然〔唐代〕',c:'武陵何处访仙乡，古观云根路已荒。细草拥坛人迹绝，\n落花沈涧水流香。山深有雨寒犹在，松老无风韵亦长。\n全觉此身离俗境，玄机亦可照迷方。'},
    {t:'晚春严少尹与诸公见过',a:'王维〔唐代〕',c:'松菊荒三径，图书共五车。\n烹葵邀上客，看竹到贫家。\n鹊乳先春草，莺啼过落花。\n自怜黄发暮，一倍惜年华。'},
    {t:'晚次乐乡县',a:'陈子昂〔唐代〕',c:'故乡杳无际，日暮且孤征。\n川原迷旧国，道路入边城。\n野戍荒烟断，深山古木平。\n如何此时恨，噭噭夜猿鸣。'},
    {t:'晚冬废溪东寺怀李司直纵',a:'皎然〔唐代〕',c:'废溪无人迹，益见离思深。归来始昨日，恍惚惊岁阴。\n清想属遥夜，圆景当空林。宿昔月未改，何如故人心。\n游从间芳趾，摇落栖寒岑。眇眇湖上别，含情初至今。\n道流安寂寞，世路倦岖嶔。此意欲谁见，怀贤独难任。\n徽声反冥默，夕籁何哀吟。禅念破离梦，吾师诫援琴。\n耿耿已及旦，曷由开此襟。幽期谅未偶，胜境徒自寻。\n安得西归云，因之传素音。'},
    {t:'晚发五渡',a:'岑参〔唐代〕',c:'客厌巴南地，乡邻剑北天。江村片雨外，野寺夕阳边。\n芋叶藏山径，芦花杂渚田。舟行未可住，乘月且须牵。'},
    {t:'晚风二首·其二',a:'杨万里〔宋代〕',c:'晚风不许鉴清漪，却许重帘到地垂。\n平野无山遮落日，西窗红到月来时。'},
    {t:'晚风二首·其一',a:'杨万里〔宋代〕',c:'晚日暄温稍霁威，晚风豪横大相欺。\n作寒作冷何须怒？来早一霜谁不知。'},
    {t:'晚归曲',a:'温庭筠〔唐代〕',c:'格格水禽飞带波，孤光斜起夕阳多。湖西山浅似相笑，\n菱刺惹衣攒黛蛾。青丝系船向江木，兰芽出土吴江曲。\n水极晴摇泛滟红，草平春染烟绵绿。玉鞭骑马杨叛儿，\n刻金作凤光参差。丁丁暖漏滴花影，催入景阳人不知。\n弯堤弱柳遥相瞩，雀扇团圆掩香玉。莲塘艇子归不归，\n柳暗桑秾闻布谷。'},
    {t:'晚归遇雨',a:'杨万里〔宋代〕',c:'略略烟痕草许低，初初雨影伞先知。\n溪回谷转愁无路，忽有梅花一两枝。'},
    {t:'晚过盘石寺礼郑和尚',a:'岑参〔唐代〕',c:'暂诣高僧话，来寻野寺孤。\n岸花藏水碓，溪竹映风炉。\n顶上巢新鹊，衣中得旧珠。\n谈禅未得去，辍棹且踟蹰。'},
    {t:'晚霁登王六东阁',a:'张九龄〔唐代〕',c:'试上江楼望，初逢山雨晴。连空青嶂合，向晚白云生。\n彼美要殊观，萧条见远情。情来不可极，日暮水流清。'},
    {t:'晚菊',a:'韩愈〔唐代〕',c:'少年饮酒时，踊跃见菊花。今来不复饮，每见恒咨嗟。\n伫立摘满手，行行把归家。此时无与语，弃置奈悲何。'},
    {t:'晚泊',a:'陆游〔宋代〕',c:'半世无归似转蓬，今年作梦到巴东。\n身游万死一生地，路入千峰百嶂中。\n邻舫有时来乞火，丛祠无处不祈风。\n晚潮又泊淮南岸，落日啼鸦戍堞空。'},
    {t:'晚泊牛渚',a:'刘禹锡〔唐代〕',c:'芦苇晚风起，秋江鳞甲生。\n残霞忽变色，游雁有余声。\n戍鼓音响绝，渔家灯火明。\n无人能咏史，独自月中行。'},
    {t:'晚泊浔阳望庐山',a:'孟浩然〔唐代〕',c:'挂席几千里，名山都未逢。\n泊舟传阳郭，始见香炉峰。\n尝读远公传，永怀尘外踪。\n东林精舍近，日暮空闻钟。'},
    {t:'晚起',a:'白居易〔唐代〕',c:'卧听冬冬衙鼓声，起迟睡足长心情。\n华簪脱后头虽白，堆案抛来眼校明。\n闲上篮舆秉兴出，醉回花舫信风行。\n明朝更濯尘缨去，闻道松江水最清。'},
    {t:'晚憩杜桥馆',a:'周邦彦〔宋代〕',c:'寒茅愔愔鸡啄场，儿啼索衣天陨霜。\n密林渐放山色入，枫枯振稿声琅琅。\n清浆白羽弃已久，黄菊紫萸看欲香。\n岁行及此去愈疾，若决积水难提防。\n嗟予齿发非故物，念此内热如涫汤。\n原见唐朝吕墨客，膝行问道求神方。\n斋心千日百事毕，消我含雪还韶光。\n岂饶蒿目忧世事，黄金绾腰埋土囊。'},
    {t:'晚憩王少府东阁',a:'张九龄〔唐代〕',c:'披轩肆流览，云壑见深重。空水秋弥净，林烟晚更浓。\n坐隅分洞府，檐际列群峰。窈窕生幽意，参差多异容。\n还惭大隐迹，空想列仙踪。赖此升攀处，萧条得所从。'},
    {t:'晚晴',a:'杜甫〔唐代〕',c:'村晚惊风度，庭幽过雨沾。\n夕阳薰细草，江色映疏帘。\n书乱谁能帙，杯干自可添。\n时闻有馀论，未怪老夫潜。'},
    {t:'晚晴',a:'李商隐〔唐代〕',c:'深居府夹城，\n春去夏犹清。\n天意怜幽草，\n人间重晚晴。\n并添高阁迥，\n微注小窗明。\n越鸟巢干後，\n归飞体更轻。'},
    {t:'晚秋',a:'元稹〔唐代〕',c:'竹露滴寒声，离人晓思惊。酒醒秋簟冷，风急夏衣轻。\n寝倦解幽梦，虑闲添远情。谁怜独欹枕，斜月透窗明。'},
    {t:'晚秋登佛川南峰怀裴例',a:'皎然〔唐代〕',c:'登岭望落日，眇然伤别魂。亭皋秋色遍，游子在荆门。\n世故东西客，山空断续猿。此心谁复见，寂寞偶芳荪。'},
    {t:'晚秋闲居',a:'张籍〔唐代〕',c:'独坐高秋晚，萧条足远思。\n家贫常畏客，身老转怜儿。\n万种尽闲事，一生能几时。\n从来疏懒性，应只有僧知。'},
    {t:'晚秋夜',a:'白居易〔唐代〕',c:'碧空溶溶月华静，月里愁人吊桐影。\n花开残菊傍疏篱，叶下衰桐落寒井。\n塞鸿飞急觉秋尽，邻鸡鸣迟知夜永。\n凝情不语空所思，风吹白露衣裳冷。'},
    {t:'晚桃花',a:'白居易〔唐代〕',c:'一树红桃亚拂池，竹遮松荫晚人时。\n非因斜日无由见，不是闲人岂得知。\n寒地生材遗校易，贫家养女嫁常迟。\n春深欲落谁怜惜，白侍郎来折一枝。'},
    {t:'晚望二首',a:'杨万里〔宋代〕',c:'月是小春春未生，节名大雪雪何曾。\n夕阳不管西山暗，只照东山八九棱。'},
    {t:'晚霞',a:'朱熹〔宋代〕',c:'日落西南第几峰，断霞千里抹残红。上方杰阁凭栏处，欲尽馀晖怯晚风。'},
    {t:'晚雪吟',a:'孟郊〔唐代〕',c:'贫富喜雪晴，出门意皆饶。镜海行纤悉，冰天步飘飖。\n一一仙子行，家家尘声销。小儿击玉指，大夐歌圣朝。\n睿气流不尽，瑞仙何夐寥。始知望幸色，终疑异礼招。\n市井亦清洁，闾阎耸岧峣。苍生愿东顾，翠华仍西遥。\n天念岂薄厚，宸衷多忧焦。忧焦致太平，以兹时比尧。\n古耳有未通，新词有潜韶。甘为酒伶摈，坐耻歌女娇。\n选音不易言，裁正逢今朝。今朝前古文，律异同一调。\n愿于尧琯中，奏尽郁抑谣。'},
    {t:'晚饮',a:'杨万里〔宋代〕',c:'大醉或伤生，不醉又伤情。\n此事两难处，後先有重轻。\n醉後失天地，余生底浮萍。\n愁城不须攻，醉乡无此城。'},
    {t:'晚坐寄友人',a:'温庭筠〔唐代〕',c:'九枝灯在琐窗空，希逸无聊恨到同。\n晓梦未离金夹膝，早寒先到石屏风。\n遗簪可惜三秋白，蜡烛犹残一寸红。\n应卷鰕帘看皓齿，镜中惆怅见梧桐。'},
    {t:'万安道中书事德三首',a:'杨万里〔宋代〕',c:'携家满路蹈春华，儿女欣欣不忆家。\n骑吏也忘行役苦，一人人插一枝花。'},
    {t:'万安道中书事三首其二',a:'杨万里〔宋代〕',c:'携家满路踏春华，儿女欣欣不忆家。骑吏也忘行役苦，一人人插一枝花。'},
    {t:'万里春·千红万翠',a:'周邦彦〔宋代〕',c:'千红万翠。簇定清明天气。为怜他、种种清香，好难为不醉。\n我爱深如你。我心在、个人心里。便相看、老却春风，莫无些欢意。'},
    {t:'万里桥',a:'岑参〔唐代〕',c:'成都与维扬，相去万里地。\n沧江东流疾，帆去如鸟翅。\n楚客过此桥，东看尽垂泪。'},
    {t:'万里瞿塘月',a:'杜甫〔唐代〕',c:'万里瞿唐月，春来六上弦。\n时时开暗室，故故满青天。\n爽合风襟静，高当泪脸悬。\n南飞有乌鹊，夜久落江边。'},
    {t:'万山潭作',a:'孟浩然〔唐代〕',c:'垂钓坐盘石，水清心亦闲。\n鱼行潭树下，猿挂岛藤间。\n游女昔解佩，传闻于此山。\n求之不可得，沿月棹歌还。'},
    {t:'万岁楼',a:'王昌龄〔唐代〕',c:'江上巍巍万岁楼，不知经历几千秋。\n年年喜见山长在，日日悲看水独流。\n猿狖何曾离暮岭，鸬鹚空自泛寒洲。\n谁堪登望云烟里，向晚茫茫发旅愁。'},
    {t:'万州晓发放舟乘涨还寄蜀中亲朋',a:'陈子昂〔唐代〕',c:'空蒙岩雨霁。\n烂熳晓云归。\n啸旅乘明发。\n奔桡骛断矶。\n苍芒林岫转。\n络绎涨涛飞。\n远岸孤烟出。\n遥峰曙日微。\n前瞻未能●【左目右旬】。\n坐望已相依。\n曲直多今古。\n经过失是非。\n还期方浩浩。\n征思日●【左马右非】●【左马右非】。\n寄谢千金子。\n江海事多违。'},
    {t:'王充道送水仙花五十支',a:'黄庭坚〔宋代〕',c:'凌波仙子生尘袜，水上轻盈步花月。\n是谁招此断肠魂，种作寒花寄愁绝。\n含香体素欲倾城，山矾是弟梅是兄。\n坐对真成被花恼，出门一笑大江横。'},
    {t:'王厚颂二首',a:'黄庭坚〔宋代〕',c:'夕阳尽处望清闲，想见千岩细菊斑。\n人得交游是风月，天开图画即江山。'},
    {t:'王母歌·一作玉女歌',a:'韦应物〔唐代〕',c:'众仙翼神母，羽盖随云起。上游玄极杳冥中，\n下看东海一杯水。海畔种桃经几时，千年开花千年子。\n玉颜眇眇何处寻，世上茫茫人自死。'},
    {t:'王濬墓下作',a:'李贺〔唐代〕',c:'人间无阿童，犹唱水中龙。\n白草侵烟死，秋藜绕地红。\n古书平黑石，神剑断青铜。\n耕势鱼鳞起，坟科马鬣封。\n菊花垂湿露，棘径卧干蓬。\n松柏愁香涩，南原几夜风！'},
    {t:'王昭君二首',a:'李白〔唐代〕',c:'汉家秦地月，流影照明妃。\n一上玉关道，天涯去不归。\n汉月还从东海出，明妃西嫁无来日。\n燕支长寒雪作花，蛾眉憔悴没胡沙。\n生乏黄金枉图画，死留青冢使人嗟。\n昭君拂玉鞍，上马啼红颊。\n今日汉宫人，明朝胡地妾。'},
    {t:'往丹阳寻陆处士不遇',a:'皎然〔唐代〕',c:'远客殊未归，我来几惆怅。叩关一日不见人，\n绕屋寒花笑相向。寒花寂寂遍荒阡，柳色萧萧愁暮蝉。\n行人无数不相识，独立云阳古驿边。凤翅山中思本寺，\n鱼竿村口望归船。归船不见见寒烟，离心远水共悠然。\n他日相期那可定，闲僧著处即经年。'},
    {t:'辋川别业',a:'王维〔唐代〕',c:'不到东山向一年，归来才及种花田。\n雨中草色绿堪染，水上桃花红欲然。\n优娄比丘经论学，伛偻丈人乡里贤。\n披衣倒屣且相见，相欢语笑衡门前。'},
    {t:'辋川集·椒园',a:'王维〔唐代〕',c:'桂尊迎帝子，杜若赠佳人。\n椒浆奠瑶席，欲下云中君。'},
    {t:'辋川集·斤竹岭',a:'王维〔唐代〕',c:'檀栾映空曲，青翠漾涟漪。\n暗入商山路，樵人不可知。'},
    {t:'辋川集·金屑泉',a:'王维〔唐代〕',c:'日饮金屑泉，少当千馀岁。\n翠凤翊文螭，羽节朝玉帝。'},
    {t:'辋川集·柳浪',a:'王维〔唐代〕',c:'分行接绮树，倒影入清漪。\n不学御沟上，春风伤别离。'},
    {t:'辋川集·孟城坳',a:'王维〔唐代〕',c:'新家孟城口，古木馀衰柳。\n来者复为谁，空悲昔人有。'},
    {t:'辋川集·南垞',a:'王维〔唐代〕',c:'轻舟南垞去，北垞淼难即。\n隔浦望人家，遥遥不相识。'},
    {t:'辋川集·茱萸沜',a:'王维〔唐代〕',c:'结实红且绿，复如花更开。\n山中傥留客，置此芙蓉杯。'},
    {t:'辋川闲居',a:'王维〔唐代〕',c:'一从归白社，不复到青门。\n时倚檐前树，远看原上村。\n青菰临水拔，白鸟向山翻。\n寂寞於陵子，桔槔方灌园。'},
    {t:'辋川闲居赠裴秀才迪',a:'王维〔唐代〕',c:'寒山转苍翠，秋水日潺湲。\n倚杖柴门外，临风听暮蝉。\n渡头馀落日，墟里上孤烟。\n复值接舆醉，狂歌五柳前。'},
    {t:'望洞庭',a:'刘禹锡〔唐代〕',c:'湖光秋月两相和，潭面无风镜未磨。\n遥望洞庭山水翠，白银盘里一青螺。'},
    {t:'望洞庭湖上张丞相',a:'孟浩然〔唐代〕',c:'八月湖水平，涵虚混太清。\n气蒸云梦泽，波撼岳阳城。\n欲济无舟楫，端居耻圣明。\n坐观垂钓者，徒有羡鱼情。'},
    {t:'望夫石',a:'王安石〔宋代〕',c:'云鬟烟鬓与谁期，一去天边更不归。\n还似九疑山下女，千秋长望舜裳衣。'},
    {t:'望夫石',a:'刘禹锡〔唐代〕',c:'终日望夫夫不归，化为孤石苦相思。\n望来已是几千载，只似当时初望时。'},
    {t:'望夫石',a:'孟郊〔唐代〕',c:'望夫石，夫不来兮江水碧。\n行人悠悠朝与暮，千年万年色如故。'},
    {t:'望海潮·东南形胜',a:'柳永〔宋代〕',c:'东南形胜，三吴都会，钱塘自古繁华。烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙，怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。\n重湖叠𪩘清嘉，有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。千骑拥高牙，乘醉听箫鼓，吟赏烟霞。异日图将好景，归去凤池夸。'},
    {t:'望海潮·广陵怀古',a:'秦观〔宋代〕',c:'星分牛斗，疆连淮海，扬州万井提封。花发路香，莺啼人起，珠帘十里东风。豪俊气如虹。曳照春金紫，飞盖相从。巷入垂杨，画桥南北翠烟中。\n追思故国繁雄。有迷楼挂斗，月观横空。纹锦制帆，明珠溅雨，宁论爵马鱼龙。往事逐孤鸿。但乱云流水，萦带离宫。最好挥毫万字，一饮拚千钟。'},
    {t:'望海潮·洛阳怀古',a:'秦观〔宋代〕',c:'梅英疏淡，冰澌溶泄，东风暗换细华。金谷俊游，铜驼巷陌，新晴细履平沙。长记误随车。正絮翻春舞，芳思交加。柳下桃蹊，乱分春色到人家。\n西园夜饮鸣笳。有华灯碍月，飞盖妨花。兰苑未空，行人渐老，重来是事堪嗟。烟暝酒旗斜。但倚楼极目，时见栖鸦。无奈归心，暗随流水到天涯。'},
    {t:'望海潮·奴如飞絮',a:'秦观〔宋代〕',c:'奴如飞絮，郎如流水，共沾便肯共随。微月户庭，残灯翠幕，匆匆共惜佳期。才话暂分携。早抱人别咽，双泪垂。画舸难停，翠帏轻别两依依。\n别来怎表共思？有分香帕子，合数松儿。红粉脆痕，青笺嫩约，丁宁莫遣人知。成病也因谁？更自言秋杪，亲去无疑。但恐生时注着，合有分于飞。'},
    {t:'望海潮·秦峰苍翠',a:'秦观〔宋代〕',c:'秦峰苍翠，耶溪潇洒，千岩万壑燕流。鸳瓦雉城，谯门画戟，蓬莱燕阁三休。天际识归舟，泛五湖村月，西子同游。茂草台荒，苎萝村冷起闲愁。\n何人览古凝眸。怅朱颜易失，翠被难留。梅市旧书，兰亭古墨，依稀风韵生秋。狂客鉴湖头，有百年台沼，终日夷犹。最好金龟换酒，相与醉沧州。'},
    {t:'望海楼晚景·其二',a:'苏轼〔宋代〕',c:'横风吹雨入楼斜，壮观应须好句夸。\n雨过潮平江海碧，电光时掣紫金蛇。'},
    {t:'望海楼晚景五绝',a:'苏轼〔宋代〕',c:'海上涛头一线来，楼前指顾雪成堆。\n从今潮上君须上，更看银山二十回。\n横风吹雨入楼斜，壮观应须好句夸。\n雨过潮平江海碧，电光时掣紫金蛇。\n青山断处塔层层，隔岸人家唤欲应。\n江上秋风晚来急，为传钟鼓到西兴。\n楼下谁家烧夜香，玉笙哀怨弄初凉。\n临风有客吟秋扇，拜月无人见晚妆。\n沙河灯火照山红，歌鼓喧喧笑语中。\n为问少年心在否，角巾欹侧鬓如蓬。'},
    {t:'望汉月',a:'晏殊〔宋代〕',c:'千缕万条堪结。占断好风良月。如娘春晚先多愁，更撩乱、絮飞如雪。\n短亭相送处，长忆得、醉中攀折。年年岁岁好时节。怎奈尚、有人离别。'},
    {t:'望汉月·明月明月明月',a:'柳永〔宋代〕',c:'明月明月明月。争奈乍圆还缺。恰如年少洞房人，暂欢会、依前离别。\n小楼凭槛处，正是去年时节。千里清光又依旧，奈夜永、厌厌人绝。'},
    {t:'望衡山',a:'刘禹锡〔唐代〕',c:'东南倚盖卑，维岳资柱石。\n前当祝融居，上拂朱鸟翮。\n青冥结精气，磅礴宣地脉。\n还闻肤寸阴，能致弥天泽。'},
    {t:'望江东·江水西头隔烟树',a:'黄庭坚〔宋代〕',c:'江水西头隔烟树。望不见、江东阑。思量只有梦来去。更不怕、江阑住。\n灯前写了书无数。算没个、人传与。直饶寻得雁分付。又还是、秋将暮。'},
    {t:'望江南·超然台作',a:'苏轼〔宋代〕',c:'春未老，风细柳斜斜。试上超然台上看，半壕春水一城花。烟雨暗千家。\n寒食后，酒醒却咨嗟。休对故人思故国，且将新火试新茶。诗酒趁年华。'},
    {t:'望江南·大石咏妓',a:'周邦彦〔宋代〕',c:'歌席上，无赖是横波。宝髻玲珑自玉燕，绣巾柔腻掩香罗。人好自宜多。\n无个事，因甚敛双蛾。浅淡梳妆疑见画，惺忪言语胜闻歌。何况会婆娑。'},
    {t:'望江南·归依法',a:'王安石〔宋代〕',c:'归依法，法法不思议。愿我六根常寂静，心如宝月映琉璃。了法更无疑。'},
    {t:'望江南·暮春',a:'苏轼〔宋代〕',c:'春已老，春服几时成。曲水浪低乐叶稳，舞雩风软纻罗轻。酣咏乐升平。\n微雨过，何处不催耕。百舌无言桃李尽，柘林深处鹁鸪鸣。春色属芜菁。'},
    {t:'望江南·梳洗罢',a:'温庭筠〔唐代〕',c:'梳洗罢，独倚望江楼。过尽千帆皆不是，斜晖脉脉水悠悠。肠断白蘋洲。'},
    {t:'望江南·四之三',a:'王安石〔宋代〕',c:'归依佛，弹指越三祇。愿我速登无上觉，还如佛坐道场时。能智又能悲。'},
    {t:'望江南·四之四',a:'王安石〔宋代〕',c:'三界里，有取总灾危。普愿从生同我愿，能于空有善思惟。三宝共住持。'},
    {t:'望江南·天上月',a:'佚名〔五代〕',c:'天上月，遥望似一团银。夜久更阑风渐紧。为奴吹散月边云。照见负心人。'},
    {t:'望江南·咏弦月',a:'纳兰性德〔清代〕',c:'初八月，半镜上青霄。斜倚画阑娇不语，暗移梅影过红桥，裙带北风飘。'},
    {t:'望江南·游妓散',a:'周邦彦〔宋代〕',c:'游妓散，独自绕回堤。芳草怀烟未水曲，密云衔雨暗城西。九陌未沾泥。\n桃李下，春晚未成蹊。墙外见花寻路转，柳阴行马过莺啼。无处不凄凄。'},
    {t:'望九华赠青阳韦仲堪',a:'李白〔唐代〕',c:'昔在九江上，遥望九华峰。\n天河挂绿水，秀出九芙蓉。\n我欲一挥手，谁人可相从。\n君为东道主，于此卧云松。'},
    {t:'望庐山瀑布',a:'李白〔唐代〕',c:'日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。'},
    {t:'望庐山瀑布二首',a:'李白〔唐代〕',c:'西登香炉峰，南见瀑布水。\n挂流三百丈，喷壑数十里。\n欻如飞电来，隐若白虹起。\n初惊河汉落，半洒云天里。\n仰观势转雄，壮哉造化功。\n海风吹不断，江月照还空。\n空中乱潈射，左右洗青壁。\n飞珠散轻霞，流沫沸穹石。\n而我乐名山，对之心益闲。\n无论漱琼液，还得洗尘颜。\n且谐宿所好，永愿辞人间。\n日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。'},
    {t:'望梅·小寒时节',a:'柳永〔宋代〕',c:'小寒时节。正同云暮惨，劲风朝冽。信早梅、偏占阳和，向日处，凌晨数枝争发。时有香来，望明艳、遥知非雪。想玲珑嫩蕊，弄粉素英，旖旎清绝。\n仙姿更谁并列。有幽光映水。疏影笼月。且大家、留倚阑干，对绿醑飞觥，锦笺吟阕。桃李繁华，奈彼此、芬芳俱别。等和羹待用，休把翠条漫折。'},
    {t:'望木瓜山',a:'李白〔唐代〕',c:'早起见日出，暮见栖鸟还。\n客心自酸楚，况对木瓜山。'},
    {t:'望牛头寺',a:'杜甫〔唐代〕',c:'牛头见鹤林，梯迳绕幽深。\n春色浮山外，天河宿殿阴。\n传灯无白日，布地有黄金。\n休作狂歌老，回看不住心。'},
    {t:'望少华三首',a:'杜牧〔唐代〕',c:'身随白日看将老，心与青云自累期。\n今对晴峰无十里，世缘多累暗生悲。\n文字波中去不还，物事初与是非闲。\n时名竟是无端事，羞对灵山道爱山。\n眼看云鹤不相随，何况尘中事作为。\n好伴羽人深洞去，月前秋听玉参差。'},
    {t:'望天门山',a:'李白〔唐代〕',c:'天门中断楚江开，碧水东流至此回。\n两岸青山相对出，孤帆一片日边来。'},
    {t:'望喜驿别嘉陵江水二绝',a:'李商隐〔唐代〕',c:'嘉陵江水此东流，望喜楼中忆更州。\n若到更中还赴海，更州应更有高楼。\n千里嘉陵江水色，含烟带月碧于蓝。\n今朝相送东流后，犹自驱车更向南。'},
    {t:'望仙楼',a:'晏几道〔宋代〕',c:'小春花信日边来，未上江楼先素。今岁东君消息。还自南枝得。\n素衣染尽天香，玉酒添成国色。一自故溪疏隔。肠断长相忆。'},
    {t:'望仙门',a:'晏殊〔宋代〕',c:'紫薇枝上露华浓。起秋风。管弦声细出帘栊。象筵中。\n仙酒斟云液，仙歌转绕梁虹。此时佳会庆相逢。庆相逢。欢醉且从容。'},
    {t:'望仙门·玉池波浪碧如鳞',a:'晏殊〔宋代〕',c:'玉池波浪碧如鳞。露莲新。清歌一曲翠眉颦。舞华茵。\n满酌兰英酒，须知献寿千春。太平无事荷君恩。荷君恩。齐唱望仙门。'},
    {t:'望仙门·玉壶清漏起微凉',a:'晏殊〔宋代〕',c:'玉壶清漏起微凉，好秋光。金杯重叠满琼浆。会仙乡。\n新曲调丝管，新声更飐霓裳。博山炉暖泛浓香。泛浓香，为寿百千长。'},
    {t:'望仙门·紫薇枝上露华浓',a:'晏殊〔宋代〕',c:'紫微枝上露华浓。起秋风。筦弦声细出帘栊。象筵中。\n仙酒斟云液，山歌转绕梁虹。此时佳会庆相逢。欢醉且从容。'},
    {t:'望仙门其二',a:'晏殊〔宋代〕',c:'玉壶清漏起微凉。好秋光。金杯重叠满琼浆。会仙乡。\n新曲调丝管，新声更飐霓裳。博山炉暖泛浓香。泛浓香。\n为寿百千长。'},
    {t:'望谢家青山太白墓二首',a:'杨万里〔宋代〕',c:'阿眺青山自一村，州民岁岁与招魂。\n六朝陵墓今安在，只有诗仙月下坟。'},
    {t:'望驿台',a:'白居易〔唐代〕',c:'靖安宅里当窗柳，望驿台前扑地花。\n两处春光同日尽，居人思客客思家。'},
    {t:'望鹦鹉洲怀祢衡',a:'李白〔唐代〕',c:'魏帝营八极，蚁观一祢衡。\n黄祖斗筲人，杀之受恶名。\n吴江赋鹦鹉，落笔超群英。\n锵锵振金玉，句句欲飞鸣。\n鸷鹗啄孤凤，千春伤我情。\n五岳起方寸，隐然讵可平。\n才高竟何施，寡识冒天刑。\n至今芳洲上，兰蕙不忍生。'},
    {t:'望远村',a:'皎然〔唐代〕',c:'林杪不可分，水步遥难辨。一片山翠边，依稀见村远。'},
    {t:'望远曲',a:'孟郊〔唐代〕',c:'朝朝候归信，日日登高台。行人未去植庭梅，\n别来三见庭花开。庭花开尽复几时，春光骀荡阻佳期。\n愁来望远烟尘隔，空怜绿鬓风吹白。何当归见远行客。'},
    {t:'望远行·绣帏睡起',a:'柳永〔宋代〕',c:'绣帏睡起。残妆浅，无绪匀红补楼。藻井凝尘，金梯铺藓。寂寞凤楼十二。风絮纷纷，烟芜苒苒，永春画阑，沈吟独倚。望远行，南陌春残悄归骑。\n凝睇。消遣离愁无计。但暗掷、金钗买醉。对好景、空饮香醪，争奈转添珠泪。待伊游冶归来，故故解放楼羽，轻裙重系。见纤腰围小，信人憔悴。'},
    {t:'望远行·长空降瑞',a:'柳永〔宋代〕',c:'长空降瑞，寒风剪，淅淅瑶花初下。乱飘僧舍，密洒歌楼，迤逦渐迷鸳瓦。好是渔人，披得一蓑归去，江上晚来堪画。满长安，高却旗亭酒价。\n幽雅。乘兴最宜访戴，泛小棹、越溪潇洒。皓鹤夺鲜，白鹇失素，千里广铺寒野。须信幽兰歌断，彤云收尽，别有瑶台琼榭。放一轮明月，交光清夜。'},
    {t:'望月怀远',a:'张九龄〔唐代〕',c:'海上生明月，天涯共此时。\n情人怨遥夜，竟夕起相思。\n灭烛怜光满，披衣觉露滋。\n不堪盈手赠，还寝梦佳期。'},
    {t:'望月有感',a:'白居易〔唐代〕',c:'自河南经乱，关内阻饥，兄弟离散，各在一处。因望月有感，聊书所怀，寄上浮梁大兄、於潜七兄、乌江十五兄，兼示符离及下邽弟妹。\n时难年荒世业空，弟兄羁旅各西东。\n田园寥落干戈后，骨肉流离道路中。\n吊影分为千里雁，辞根散作九秋蓬。\n共看明月应垂泪，一夜乡心五处同。'},
    {t:'望月有怀',a:'李白〔唐代〕',c:'清泉映疏松，不知几千古。\n寒月摇清波，流光入窗户。\n对此空长吟，思君意何深。\n无因见安道，兴尽愁人心。'},
    {t:'望岳',a:'杜甫〔唐代〕',c:'岱宗夫如何？齐鲁青未了。\n造化钟神秀，阴阳割昏晓。\n荡胸生曾云，决眦入归鸟。\n会当凌绝顶，一览众山小。'},
    {t:'望岳三首·其二',a:'杜甫〔唐代〕',c:'西岳崚嶒竦处尊，诸峰罗立似儿孙。\n安得仙人九节杖，拄到玉女洗头盆。\n车箱入谷无归路，箭栝通天有一门。\n稍待秋风凉冷后，高寻白帝问真源。'},
    {t:'望岳三首·其三',a:'杜甫〔唐代〕',c:'南岳配朱鸟，秩礼自百王。\n歘吸领地灵，鸿洞半炎方。\n邦家用祀典，在德非馨香。\n巡守何寂寥，有虞今则亡。\n洎吾隘世网，行迈越潇湘。\n渴日绝壁出，漾舟清光旁。\n祝融五峰尊，峯峯次低昴。\n紫盖独不朝，争长嶫相望。\n恭闻魏夫人，羣仙夹翱翔。\n有时五峰气，散风如飞霜。\n牵迫限修途，未暇杖崇冈。\n归来觊命驾，沐浴休玉堂。\n三叹问府主，曷以赞我皇。\n牲璧忍衰俗，神其思降祥。'},
    {t:'微雨',a:'陆游〔宋代〕',c:'晡後气殊浊，黄昏月尚明。\n忽吹微雨过，便觉小寒生。\n树杪雀初定，草根虫已鸣。\n呼童取半臂，吾欲傍阶行。'},
    {t:'微雨',a:'李商隐〔唐代〕',c:'初随林霭动，稍共夜凉分。\n窗迥侵灯冷，庭虚近水闻。'},
    {t:'微雨夜行',a:'白居易〔唐代〕',c:'漠漠秋云起，稍稍夜寒生。\n但觉衣裳湿，无点亦无声。'},
    {t:'韦给事山居',a:'王维〔唐代〕',c:'幽寻得此地，讵有一人曾。\n大壑随阶转，群山入户登。\n庖厨出深竹，印绶隔垂藤。\n即事辞轩冕，谁云病未能。'},
    {t:'韦侍郎山居',a:'王维〔唐代〕',c:'幸忝君子顾，遂陪尘外踪。\n闲花满岩谷，瀑水映杉松。\n啼鸟忽归涧，归云时抱峰。\n良游盛簪绂，继迹多夔龙。\n讵枉青门道，胡闻长乐钟。\n清晨去朝谒，车马何从容。'},
    {t:'韦员外家花树歌',a:'岑参〔唐代〕',c:'今年花似去年好，去年人到今年老。\n始知人老不如花，可惜落花君莫扫。\n君家兄弟不可当，列卿御史尚书郎。\n朝回花底恒会客，花扑玉缸春酒香。'},
    {t:'尾犯',a:'柳永〔宋代〕',c:'晴烟羃羃。渐东郊芳草，染成轻碧。野塘风暖，游鱼动触，冰澌微坼。\n几行断雁，旋次第、归霜碛。咏新诗，手捻江梅，故人赠我春色。\n似此光阴催逼。念浮生、不满百。虽照人轩冕，润屋珠金，于身何益。\n一种劳心力。图利禄，殆非长策。除是恁、点检笙歌，访寻罗绮消得。'},
    {t:'尾犯·林钟商',a:'柳永〔宋代〕',c:'晴烟幂幂。渐东郊芳草，染成轻碧。野塘风暖，游鱼动触，冰澌微坼。几行断雁，旋次第、归霜碛。咏新诗，手捻江梅，故人赠我春色。\n似此光阴催逼。念浮生、不满百。虽照人轩冕，润屋珠金，于身何益。一种劳心力。图利禄，殆非长策。除是恁、点检笙歌，访寻罗绮消得。'},
    {t:'尾犯·夜雨滴空阶',a:'柳永〔宋代〕',c:'夜雨滴空阶，孤馆梦回，情绪萧索。一片闲愁，想丹青难貌。秋渐老、蛩声正苦，夜将阑、灯花旋落。最无端处，总把良宵，只恁孤眠却。\n佳人应怪我，别后寡信轻诺。记得当初，翦香云为约。甚时向、幽闺深处，按新词、流霞共酌。再同欢笑，肯把金玉珠珍博。'},
    {t:'为或人赋',a:'文天祥〔宋代〕',c:'悠悠成败百年中，笑看柯山局恨终。\n金马胜游成旧雨，铜驼遗恨付西风。\n黑头尔自夸江总，冷齿人能说褚公。\n龙首黄扉真一梦，梦回何面见江东。'},
    {t:'为刘定伯索油蕨',a:'文天祥〔宋代〕',c:'我欲登山去采薇，江南秋雨正霏霏。\n仙家解有逡巡手，一筹西风落翠微。'},
    {t:'为农',a:'杜甫〔唐代〕',c:'锦里烟尘外，江村八九家。\n圆荷浮小叶，细麦落轻花。\n卜宅从兹老，为农去国赊。\n远惭勾漏令，不得问丹砂。'},
    {t:'为薛台悼亡',a:'白居易〔唐代〕',c:'半死梧桐老病身，重泉一念一伤神。\n手携稚子夜归院，月冷空房不见人。'},
    {t:'为有',a:'李商隐〔唐代〕',c:'为有云屏无限娇，凤城寒尽怕春宵。\n无端嫁得金龟婿，辜负香衾事早朝。'},
    {t:'为张(亻贵)赠阎使臣',a:'王昌龄〔唐代〕',c:'哀哀献玉人，楚国同悲辛。\n泣尽继以血，何由辨其真。\n赖承琢磨惠，复使光辉新。\n犹畏谗口疾，弃之如埃尘。'},
    {t:'尉迟杯·宠佳丽',a:'柳永〔宋代〕',c:'宠佳丽。算九衢红粉皆难比。天盈嫩脸修蛾，不假施朱描翠。盈盈秋水。恣雅态、欲语先娇媚。每绸逢、月夕花朝，自有怜才深意。\n绸缪凤枕鸳被。深深处、琼枝玉树绸倚。困极欢余，芙蓉帐暖，别是恼人情味。风流事、难逢双美。况已断、香云为盟誓。且绸将、共乐平生，未肯轻分连理。'},
    {t:'尉迟杯·离恨',a:'周邦彦〔宋代〕',c:'隋堤路。渐日晚、密霭生深树。情情淡月笼沙，还宿河桥深处。无情画舸，都不管、烟波隔前浦。等因人、醉拥重衾，载将离恨归去。\n因思旧客京华，长偎傍疏林，小槛欢聚。冶叶倡条俱相识，仍惯见、珠歌翠舞。如今向、渔村水驿，夜如岁、焚香独自语。有何人、念我无聊，梦魂凝想鸳侣。'},
    {t:'渭川田家',a:'王维〔唐代〕',c:'斜阳照墟落，穷巷牛羊归。\n野老念牧童，倚杖候荆扉。\n雉雊麦苗秀，蚕眠桑叶稀。\n田夫荷锄至，相见语依依。\n即此羡闲逸，怅然吟式微。'},
    {t:'渭上思归',a:'孟郊〔唐代〕',c:'独访千里信，回临千里河。家在吴楚乡，泪寄东南波。'},
    {t:'渭上题三首',a:'温庭筠〔唐代〕',c:'吕公荣达子陵归，万古烟波绕鸟矶。\n桥上一通名利迹，至今江鸟背人飞。\n目极云霄思浩然，风路一片水连天。\n轻桡便是东归路，不肯忘机作鸟船。\n烟水何曾息世机，暂时相向亦依依。\n所嗟白首磻溪叟，一下渔舟更不归。'},
    {t:'魏郡别苏明府因北游',a:'李白〔唐代〕',c:'魏都接燕赵，美女夸芙蓉。\n淇水岸碧玉，舟车日奔冲。\n青楼夹两岸，万室喧歌钟。\n天下称豪贵，游词每相逢。\n洛阳苏季子，剑戟森词锋。\n六印虽未佩，轩车若飞龙。\n黄金数百镒，白璧有几双。\n散尽空掉臂，高歌赋还邛。\n落魄乃如词，何人不相从？\n远别隔两河，云山杳千重。\n何时更杯酒，再得论心胸。'},
    {t:'魏氏园林人赋一物得秋亭萱草',a:'陈子昂〔唐代〕',c:'昔时幽径里，荣耀杂春丛。\n今来玉墀上，销歇畏秋风。\n细叶犹含绿，鲜花未吐红。\n忘忧谁见赏，空此北堂中。'},
    {t:'魏王堤',a:'白居易〔唐代〕',c:'花寒懒发鸟慵啼，信马闲行到日西。\n何处未春先有思，柳条无力魏王堤。'},
    {t:'温泉',a:'朱熹〔宋代〕',c:'连山西南来，中断还崛起。\n干霄几千仞，据地三百里。\n飞峰上灵秀，众壑下清美。\n逮兹势力穷，犹能出奇伟。\n谁燃丹黄焰？爨此玉池水。\n客来争解带，万劫付一洗。\n当年谢康乐，弦绝今久矣。\n水碧复流温，相思五湖里。'},
    {t:'文杏馆',a:'王维〔唐代〕',c:'文杏裁为梁，香茅结为宇。\n不知栋里云，去作人间雨。'},
    {t:'文章',a:'陆游〔宋代〕',c:'文章本天成，妙手偶得之。\n粹然器疵瑕，岂复须人为？\n君看古彝器，巧拙两器施。\n汉最近先秦，固已殊淳漓。\n胡部何为者，豪竹杂哀丝。\n后夔不复作，千载谁与期？'},
    {t:'闻蝉',a:'杜牧〔唐代〕',c:'火云初似灭，晓角欲微清。故国行千里，新蝉忽数声。\n时行仍仿佛，度日更分明。不敢频倾耳，唯忧白发生。'},
    {t:'闻彻上人亡寄侍郎杨丈',a:'柳宗元〔唐代〕',c:'东越高僧还姓汤，几时琼佩触鸣珰。\n空花一散不知处，谁采金英与侍郎。'},
    {t:'闻虫',a:'白居易〔唐代〕',c:'暗虫唧唧夜绵绵，况是秋阴欲雨天。\n犹恐愁人暂得睡，声声移近卧床前。'},
    {t:'闻崔十二侍御灌口夜宿报恩寺',a:'岑参〔唐代〕',c:'闻君寻野寺，便宿支公房。溪月冷深殿，江云拥回廊。\n然灯松林静，煮茗柴门香。胜事不可接，相思幽兴长。'},
    {t:'闻歌',a:'李商隐〔唐代〕',c:'敛笑凝眸意欲歌，高云不动碧嵯峨。\n铜台罢望归何处，玉辇忘还事几多。\n青冢路边南雁尽，细腰宫里北人过。\n此声肠断非今日，香灺灯光奈尔何。'},
    {t:'闻官军收河南河北',a:'杜甫〔唐代〕',c:'剑外忽传收蓟北，初闻涕泪满衣裳。\n却看妻子愁何在，漫卷诗书喜欲狂。\n白日放歌须纵酒，青春作伴好还乡。\n即从巴峡穿巫峡，便下襄阳向洛阳。'},
    {t:'闻黄鹂',a:'柳宗元〔唐代〕',c:'倦闻子规朝暮声，不意忽有黄鹂鸣。\n一声梦断楚江曲，满眼故园春意生。\n目极千里无山河，麦芒际天摇清波。\n王畿优本少赋役，务闲酒熟饶经过。\n此时晴烟最深处，舍南巷北遥相语。\n翻日迥度昆明飞，凌风邪看细柳翥。\n我今误落千万山，身同伧人不思还。\n乡禽何事亦来此，令我生心忆桑梓。\n闭声回翅归务速，西林紫椹行当熟。'},
    {t:'闻籍田有感',a:'柳宗元〔唐代〕',c:'天田不日降皇舆，留滞长沙岁又除。\n宣室无由问釐事，周南何处托成书。'},
    {t:'闻季万至',a:'文天祥〔宋代〕',c:'去年别我旋出岭，今年汝来亦至燕。\n弟兄一囚一乘马，同父同母不同天。\n可怜骨肉相聚散，人间不满五十年。\n三仁生死各有意，悠悠白日横苍烟。'},
    {t:'闻科诏勉诸子',a:'辛弃疾〔宋代〕',c:'秋举无多日，天书已十行。\n绝编能自苦，下笔定成章。\n不见三公后，空长七尺强。\n明年吏部选，梅福更仇香。'},
    {t:'闻乐天授江州司马',a:'元稹〔唐代〕',c:'残灯无焰影幢幢，此夕闻君谪九江。\n垂死病中惊坐起，暗风吹雨入寒窗。'},
    {t:'闻梨花发赠刘师命',a:'韩愈〔唐代〕',c:'桃蹊惆怅不能过，红艳纷纷落地多。\n闻道郭西千树雪，欲将君去醉如何。'},
    {t:'闻裴秀才迪吟诗因戏赠',a:'王维〔唐代〕',c:'猿吟一何苦，愁朝复悲夕。\n莫作巫峡声，肠断秋江客。'},
    {t:'闻善决江河',a:'朱熹〔宋代〕',c:'大舜深山日，灵襟保太和。一言分善利，万里决江河。\n可欲非由外，惟聪不在它。勇如争赴壑，进岂待盈科。\n学海功难并，防川患益多。何人亲祖述，耳顺肯同波。'},
    {t:'闻王昌龄左迁龙标遥有此寄',a:'李白〔唐代〕',c:'杨花落尽子规啼，闻道龙标过五溪。\n我寄愁心与明月，随君直到夜郎西。'},
    {t:'闻武均州报已复西京',a:'陆游〔宋代〕',c:'白发将军亦壮哉，西京昨夜捷书来。\n胡儿敢作千年计，天意宁知一日回。\n列圣仁恩深雨露，中兴赦令疾风雷。\n悬知寒食朝陵使，驿路梨花处处开。'},
    {t:'闻雁',a:'韦应物〔唐代〕',c:'故园眇何处，归思方悠哉。\n淮南秋雨夜，高斋闻雁来。'},
    {t:'闻夜啼赠刘正元',a:'孟郊〔唐代〕',c:'寄泣须寄黄河泉，此中怨声流彻天。\n愁人独有夜灯见，一纸乡书泪滴穿。'},
    {t:'闻莺',a:'杨万里〔宋代〕',c:'过雨溪山净，新晴花柳明。\n来穿雨好树，别作一家声。\n故欲撩诗兴，仍添怀友情。\n惊飞苦难见，那更绿阴成。'},
    {t:'闻雨',a:'陆游〔宋代〕',c:'慷慨心犹壮，蹉跎鬓已秋。\n百年殊鼎鼎，万事祗悠悠。\n不悟鱼千里，终归貉一丘。\n夜阑闻急雨，起坐涕交流。'},
    {t:'闻砧',a:'孟郊〔唐代〕',c:'杜鹃声不哀，断猿啼不切。月下谁家砧，一声肠一绝。\n杵声不为客，客闻发自白。杵声不为衣，欲令游子归。'},
    {t:'闻钟',a:'皎然〔唐代〕',c:'古寺寒山上，远钟扬好风。\n声馀月树动，响尽霜天空。\n永夜一禅子，泠然心境中。'},
    {t:'蚊',a:'孟郊〔唐代〕',c:'五月中夜息，饥蚊尚营营。但将膏血求，岂觉性命轻。\n顾己宁自愧，饮人以偷生。愿为天下幮，一使夜景清。'},
    {t:'问皇甫十',a:'白居易〔唐代〕',c:'苦乐心由我，穷通命任他。\n坐倾张翰酒，行唱接舆歌。\n荣盛傍看好，优闲自适多。\n知君能断事，胜负两如何。'},
    {t:'问刘十九',a:'白居易〔唐代〕',c:'绿蚁新醅酒，红泥小火炉。\n晚来天欲雪，能饮一杯无？'},
    {t:'问天',a:'皎然〔唐代〕',c:'天公何时有，谈者皆不经。\n谁道贤人死，今为傅说星。'},
    {t:'问遥山禅老',a:'皎然〔唐代〕',c:'天与松子寿，独饮日月精。复令源子贤，胡为夭其生。\n吾将寻河源，上天问天何不平？吾将诘仙天，\n大道无私谁强名？仙天难逢天不近，世人何人解应尽。\n明朝欲向翅头山，问取禅公此义还。'},
    {t:'问舟子',a:'孟浩然〔唐代〕',c:'向夕问舟子，前程复几多。\n湾头正堪泊，淮里足风波。'},
    {t:'我欲往沧海',a:'王安石〔宋代〕',c:'我欲往沧海，客来自河源。\n手探囊中胶，救此千载浑。\n我语客徒尔，当还治昆仑。\n叹息谢不能，相看涕翻盆。\n客止我且往，濯发扶桑根。\n春风吹我舟，万里空目存。'},
    {t:'卧病',a:'孟郊〔唐代〕',c:'贫病诚可羞，故床无新裘。春色烧肌肤，时餐苦咽喉。\n倦寝意蒙昧，强言声幽柔。承颜自俯仰，有泪不敢流。\n默默寸心中，朝愁续莫愁。'},
    {t:'卧病家园',a:'陈子昂〔唐代〕',c:'世上无名子，人间岁月赊。纵横问已弃，寂寞道为家。\n卧病谁能问，闲居空物华。犹忆灵台友，栖真隐太霞。\n还丹奔日御，却老饵云芽。宁知白社客，不厌青门瓜。'},
    {t:'卧疾',a:'张籍〔唐代〕',c:'身病多思虑，亦读神农经。空堂留灯烛，四壁青荧荧。\n羁旅随人欢，贫贱还自轻。今来问良医，乃知病所生。\n僮仆各忧愁，杵臼无停声。见我形憔悴，劝药语丁宁。\n春雨枕席冷，窗前新禽鸣。开门起无力，遥爱鸡犬行。\n服药察耳目，渐如醉者醒。顾非达性命，犹为忧患生。'},
    {t:'乌栖曲',a:'李白〔唐代〕',c:'姑苏台上乌栖时，吴王宫里醉西施。\n吴歌楚舞欢未毕，青山欲衔半边日。\n银箭金壶漏水多，起看秋月坠江波。\n东方渐高奈乐何！'},
    {t:'乌栖曲',a:'王昌龄〔唐代〕',c:'白马逐朱车，黄昏入狭邪。柳树乌争宿，\n争枝未得飞上屋。东房少妇婿从军，每听乌啼知夜分。'},
    {t:'乌生',a:'佚名〔两汉〕',c:'乌生八九子，端坐秦氏桂树间。\n唶我！秦氏家有游遨荡子，工用睢阳强，苏合弹。左手持强弹两丸，出入乌东西。\n唶我！一丸即发中乌身，乌死魂魄飞扬上天。阿母生乌子时，乃在南山岩石间。\n唶我！人民安知乌子处，蹊径窈窕安从通，白鹿乃在上林西苑中，射工尚复得白鹿脯。\n唶我！黄鹄摩天极高飞，后宫尚复得烹煮之。鲤鱼乃在洛水深渊中，钓竿尚得鲤鱼口。\n唶我！人民生各各有寿命，死生何须复道前后！'},
    {t:'乌石',a:'王安石〔宋代〕',c:'乌石冈边缭绕山，柴荆细路水云间。\n吹花嚼蕊长来往，祗有春风似我闲。'},
    {t:'乌塘',a:'王安石〔宋代〕',c:'乌塘渺渺绿平堤，堤上行人各有携。\n试问春风何处好，辛夷如雪柘冈西。'},
    {t:'乌鸦喜谀',a:'佚名〔先秦〕',c:'粤西桂林，近有荒村，多树木，上多栖乌鸦。一犬翘首枝头，乌鸦食其上。犬欲缘木上之，恨无何，伏地喃喃，仰视注目以待，颂曰：“乌兄，久慕高风，未亲雅教，素仰雅曲，如赐一曲，尤慰平生，心亦足矣。”鸦听之，喜不自胜，伸腰展翅，㖞㖞数声，食尽堕犬口中。犬曰：“雅曲已聆，心愿已足，蒙赐佳味，终身铭德。”鸦讶曰：“非闻曲之为，乃欲吾口中食耶！”悔之莫及！'},
    {t:'乌夜啼',a:'李白〔唐代〕',c:'黄云城边乌欲栖，归飞哑哑枝上啼。\n机中织锦秦川女，碧纱如烟隔窗语。\n停梭怅然忆远人，独宿孤房泪如雨。'},
    {t:'乌夜啼·金鸭余香尚暖',a:'陆游〔宋代〕',c:'金鸭余香尚暖，绿窗斜日偏明。兰膏香染云鬟腻，钗坠滑无声。\n冷落秋千伴侣，阑珊打马心情。绣屏惊断潇湘梦，花外一声莺。'},
    {t:'乌夜啼·纨扇婵娟素月',a:'陆游〔宋代〕',c:'纨扇婵娟素月，纱巾缥缈轻烟。高槐叶长阴初合，清润雨馀天。\n弄笔斜行小草，钩帘浅醉闲眠。更无一点尘埃到，枕上听新蝉。'},
    {t:'乌衣巷',a:'刘禹锡〔唐代〕',c:'朱雀桥边野草花，乌衣巷口夕阳斜。\n旧时王谢堂前燕，飞入寻常百姓家。'},
    {t:'乌贼求全',a:'柳宗元〔唐代〕',c:'海之鱼，有乌贼其名者，呴水而水乌。戏于岸间，惧物之窥己也，则呴水以自蔽。海乌视之而疑，知其鱼而攫之。呜呼，徒知自蔽以求全，不知灭迹以杜疑，为窥者之所窥，哀哉！'},
    {t:'巫山高',a:'李贺〔唐代〕',c:'碧丛丛，高插天，大江翻澜神曳烟。\n楚魂寻梦风飔然，晓风飞雨生苔钱。\n瑶姬一去一千年，丁香筇竹啼老猿。\n古祠近月蟾桂寒，椒花坠红湿云间。'},
    {t:'巫山高',a:'佚名〔两汉〕',c:'巫山高，高以大；淮水深，难以逝。\n我欲东归，害梁不为？\n我集无高曳，水何汤汤回回。\n临水远望，泣下沾衣。\n远道之人心思归，谓之何！'},
    {t:'巫山高',a:'张九龄〔唐代〕',c:'巫山与天近，烟景长青荧。\n此中楚王梦，梦得神女灵。\n神女去已久，云雨空冥冥。\n唯有巴猿啸，哀音不可听。'},
    {t:'巫山曲',a:'孟郊〔唐代〕',c:'巴江上峡重复重，阳台碧峭十丘峰。\n荆王猎时逢暮雨，夜卧高丘梦神女。\n轻红流烟湿艳姿，行云飞去明星稀。\n目极魂断望不见，猿啼三声泪滴衣。'},
    {t:'巫山神女庙',a:'刘禹锡〔唐代〕',c:'巫山十二郁苍苍，片石亭亭号女郎。晓雾乍开疑卷幔，\n山花欲谢似残妆。星河好夜闻清佩，云雨归时带异香。\n何事神仙九天上，人间来就楚襄王。'},
    {t:'巫山神女庙',a:'温庭筠〔唐代〕',c:'黯黯闭宫殿，霏霏荫薜萝。晓峰眉上色，春水脸前波。\n古树芳菲尽，扁舟离恨多。一丛斑竹夜，环佩响如何。'},
    {t:'巫山一段云·阆苑年华永',a:'柳永〔宋代〕',c:'阆苑年华永，嬉游别是情。人间三度见河清。一番碧桃成。\n金母忍将轻摘。留宴鳌峰真客。红狵闲卧吠斜阳。方朔敢偷尝。'},
    {t:'巫山一段云·六六真游洞',a:'柳永〔宋代〕',c:'六六真游洞，三三物外天。九班麟稳破非烟。何处按云轩。\n昨夜麻姑陪宴。又话蓬莱清浅。几回山脚弄云涛。仿佛见金鳌。'},
    {t:'巫山一段云·琪树罗三殿',a:'柳永〔宋代〕',c:'琪树罗三殿，金龙抱九关。上清真籍总群仙。朝拜五云间。\n昨夜紫微诏下。急唤天书使者。令赍瑶检降彤霞，重到汉皇家。'},
    {t:'巫山一段云·清旦朝金母',a:'柳永〔宋代〕',c:'清旦朝金母，斜阳醉玉龟。天风摇曳六铢衣。鹤背觉孤危。\n贪看海蟾狂戏。不道九关齐闭。相将何处寄良宵。还去访三茅。'},
    {t:'巫山一段云·萧氏贤夫妇',a:'柳永〔宋代〕',c:'萧氏贤夫妇，茅家好弟兄。羽轮云驾赴层城。高会尽仙卿。\n一曲云谣为寿。倒尽金壶碧酒。醺酣争撼白榆花。踏碎九光霞。'},
    {t:'无闷·冬',a:'周邦彦〔宋代〕',c:'云作重阴，风逗细寒，小溪冻冰初结。更听得悲鸣，雁度空阔。暮雀喧喧聚竹，听竹上清响风敲雪。洞房悄、时见香消翠楼，兽煤红爇。\n凄切，念旧欢、聚旧约，至此方惜轻别。又还是离亭，楚梅堪折。暗想莺时似梦里，又却是、似莺时节。要无闷、除是拥炉对酒，共谭风月。'},
    {t:'无题',a:'佚名〔唐代〕',c:'春水春池满，春时春草生。\n春人饮春酒，春鸟哢春声。\n君生我未生，我生君已老。\n君恨我生迟，我恨君生早。\n人归万里外，意在一杯中。\n只虑前程远，开帆待好风。\n自入长信宫，每对孤灯泣。\n闺门镇不开，梦从何处入。\n一别行千里，来时未有期。\n月中三十日，无夜不相思。'},
    {t:'无题',a:'周邦彦〔宋代〕',c:'石濑光洄洄，沙步平侹侹。\n枫林通一社，春汲共寒影。\n藩篱曲相通，窈窕花竹静。\n兹焉自足乐，未先丘园迥。\n令尹虽无恩，黠吏幸先屏。\n叭当谨时候，田庐日三省。\n骄儿休马足，高廪付牛领。\n无人横催租，烹鲜会同井。'},
    {t:'无题',a:'晏殊〔宋代〕',c:'油壁香车不再逢，峡云无迹任西东。\n梨花院落溶溶月，柳絮池塘淡淡风。\n几日寂寥伤酒后，一番萧索禁烟中。\n鱼书欲寄何由达，水远山长处处同。'},
    {t:'无题',a:'李商隐〔唐代〕',c:'照梁初有情，出水旧知名。\n裙衩芙蓉小，钗茸翡翠轻。\n锦长书郑重，眉细恨分明。\n莫近弹棋局，中心最不平。'},
    {t:'无题',a:'陆游〔宋代〕',c:'碧玉当年未破瓜，学成歌舞入侯家。\n如今憔倅蓬窗里，飞上青天妒落花。'},
    {t:'无题',a:'苏轼〔宋代〕',c:'前尘往事断肠诗，侬为君痴君不知。\n莫道世界真意少，自古人间多情痴。'},
    {t:'无题',a:'范仲淹〔宋代〕',c:'十口相将泛巨川，来时暖热去凄然。\n关津若要知名姓，定是孤儿寡妇船。'},
    {t:'无题',a:'杨万里〔唐代〕',c:'青白不形眼底，雌黄不出口中。\n只有一罪不赦，唐突明月清风。'},
    {t:'无题·八岁偷照镜',a:'李商隐〔唐代〕',c:'八岁偷照镜，长眉已能画。\n十岁去踏青，芙蓉作裙衩。\n十二学弹筝，银甲不曾卸。\n十四藏六亲，悬知犹未嫁。\n十五泣春风，背面秋千下。'},
    {t:'无题·来是空言去绝踪',a:'李商隐〔唐代〕',c:'来是空言去绝踪，月斜楼上五更钟。\n梦为远别啼难唤，书被催成墨未浓。\n蜡照半笼金翡翠，麝熏微度绣芙蓉。\n刘郎已恨蓬山远，更隔蓬山一万重！'},
    {t:'无题·飒飒东风细雨来',a:'李商隐〔唐代〕',c:'飒飒东风细雨来，芙蓉塘外有丝雷。\n金蟾啮锁烧香入，玉虎牵丝汲井回。\n贾氏窥帘韩掾少，宓妃留枕魏王才。\n春心莫共花争发，一寸相思一寸灰！'},
    {t:'无题·万里风波一叶舟',a:'李商隐〔唐代〕',c:'万里风波一叶舟，忆归初罢更边犹。\n碧江地没元相引，黄鹤沙边亦少留。\n益德冤魂终报主，阿童高义镇横秋。\n人生岂得长无谓，怀古思乡共白头。'},
    {t:'无题·相见时难别亦难',a:'李商隐〔唐代〕',c:'相见时难别亦难，东风无力百花残。\n春蚕到死丝方尽，蜡炬成灰泪始干。\n晓镜但愁云鬓改，夜吟应觉月光寒。\n蓬山此去无多路，青鸟殷勤为探看。'},
    {t:'无题·重帏深下莫愁堂',a:'李商隐〔唐代〕',c:'重帏深下莫愁堂，卧后清宵细细长。\n神女生涯原是梦，小姑居处本无郎。\n风波不信菱枝弱，月露谁教桂叶香。\n直道相思了无益，未妨惆怅是清狂。'},
    {t:'无题二首·其二',a:'秦观〔宋代〕',c:'世事如浮云，飘忽不相待。\n欻然化苍狗，俄顷成章盖。\n达观听两行，昧者乃多态。\n舍旃勿重陈，百年等销坏。'},
    {t:'无题二首·其一',a:'李商隐〔唐代〕',c:'凤尾香罗薄几重，碧文圆顶夜声缝。\n扇裁月魄羞难掩，车走雷声语未通。\n曾是寂寥金烬暗，断无消息石榴红。\n斑骓只系垂杨岸，何处西南任好风。'},
    {t:'无题二首·其一',a:'秦观〔宋代〕',c:'君子有常度，所遭能自如。\n不与死生变，岂为忧患渝。\n西伯囚演易，马迁罪成书。\n性刚趣和乐，浅浅非丈夫。'},
    {t:'无锡',a:'文天祥〔宋代〕',c:'金山冉冉波涛雨，锡水泯泯草木春。\n二十年前曾去路，三千里外作行人。\n英雄未死心为碎，父老相逢鼻欲辛。\n夜读程婴存赵事，一回惆怅一沾巾。'},
    {t:'吾心',a:'王安石〔宋代〕',c:'吾心童稚时，不见一物好。\n意言有妙理，独恨知不早。\n初闻守善死，颇复吝肝脑。\n中稍历艰危，悟身非所保。\n犹然谓俗学，有指当穷讨。\n晚知童稚心，自足可忘老。'},
    {t:'吴春卿郎中饷腊猪肉，戏作古句',a:'杨万里〔宋代〕',c:'老夫畏热饭不能，先生馈肉香出城。\n霜刀削下黄水精，月斧斫出红松明。\n君家猪红腊前作，是时雪没吴山脚。\n公子彭生初解缚，糟丘挽上凌烟阁。\n却将一脔配两螯，世间真有杨州鹤。'},
    {t:'吴宫',a:'李商隐〔唐代〕',c:'龙槛沉沉水殿清，禁门深掩断人声。\n吴王宴罢满宫醉，日暮水漂花出城。'},
    {t:'吴宫词二首',a:'杜牧〔唐代〕',c:'越兵驱绮罗，越女唱吴歌。宫烬花声少，台荒麋迹多。\n茱萸垂晓露，菡萏落秋波。无遣君王醉，满城嚬翠蛾。\n香径绕吴宫，千帆落照中。鹤鸣山苦雨，鱼跃水多风。\n城带晚莎绿，池边秋蓼红。当年国门外，谁信伍员忠。'},
    {t:'吴宫怨',a:'张籍〔唐代〕',c:'吴宫四面秋江水，江清露白芙蓉死。\n吴王醉后欲更衣，座上美人娇不起。\n宫中千门复万户，君恩反覆谁能数。\n君心与妾既不同，徒向君前作歌舞。\n茱萸满宫红实垂，秋风袅袅生繁枝。\n姑苏台上夕燕罢，他人侍寝还独归。\n白日在天光在地，君今那得长相弃。'},
    {t:'吴山高',a:'朱熹〔宋代〕',c:'行尽吴山过越山，白云犹是几重关。若寻汗漫相期处，更在孤鸿灭没间。'},
    {t:'吴孙皓初童谣',a:'佚名〔魏晋〕',c:'宁饮建业水，不食武昌鱼。\n宁还建业死，不止武昌居。'},
    {t:'吴兴道中',a:'秦观〔宋代〕',c:'僶俛荜门下，十年守一方。\n胡为御舟者，挽我置此傍。\n青山不肯尽，流水故意长。\n虽云道理远，瓦樽有酒浆。'},
    {t:'吴苑行',a:'温庭筠〔唐代〕',c:'锦雉双飞梅结子，平春远绿窗中起。吴江澹画水连空，\n三尺屏风隔千里。小苑有门红扇开，天丝舞蝶共徘徊。\n绮户雕楹长若此，韶光岁岁如归来。'},
    {t:'梧叶儿·嘲谎人',a:'佚名〔元代〕',c:'东村里鸡生凤，南庄上马变牛。六月里裹皮裘。瓦垄上宜栽树，阳沟里好驾舟。瓮来大肉馒头，俺家的茄子大如斗。'},
    {t:'梧叶儿·嘲贪汉',a:'佚名〔元代〕',c:'一粒米针穿着吃，一文钱剪截充，但开口昧神灵。看儿女如衔泥燕，爱钱财似竞血蝇。无明夜攒金银，都做充饥画饼。'},
    {t:'五郊乐歌五首其五黑帝高明乐',a:'佚名〔隋代〕',c:'虹藏雉化。告寒。冰壮地坼。年殚。叶次月纪。方极。九州万邦。献力。\n叶光是纪。岁穷。微阳潜兆。方融。天子赫赫。明圣。享神降福。惟敬。'},
    {t:'五郊乐歌五首其一青帝高明乐',a:'佚名〔隋代〕',c:'岁云献，谷风归。斗东指，雁北飞。电鞭激，雷车遽。虹旌靡，青龙驭。\n和气洽，具物滋。翻降止，应帝期。'},
    {t:'五粒小松歌',a:'李贺〔唐代〕',c:'前谢秀才、杜云卿，命予作《五粒小松歌》，予以选书多事，不治曲辞，经十日，聊道八句，以当命意。\n蛇子蛇孙鳞蜿蜿，新香几粒洪崖饭。\n绿波浸叶满浓光，细束龙髯铰刀剪。\n主人壁上铺州图，主人堂前多俗儒。\n月明白露秋泪滴，石笋溪云肯寄书。'},
    {t:'五禽言和王仲衡尚书·其二',a:'朱熹〔宋代〕',c:'不如归去，孤城越绝三春暮。\n故山只在白云间，望极云深不知处。\n不如归去不如归，千仞冈头一振衣。'},
    {t:'五禽言和王仲衡尚书其一',a:'朱熹〔宋代〕',c:'提胡芦，沽美酒，春风浩荡吹花柳。不用沙头双玉瓶，鸟歌蝶舞为君寿。\n只今□醉是君恩，昨日之愁愁杀人。'},
    {t:'五松山送殷淑',a:'李白〔唐代〕',c:'秀色发江左，风流奈若何？\n仲文了不还，独立扬清波。\n载酒五松山，颓然白云歌。\n中天度落月，万里遥相过。\n抚酒惜此月，流光畏蹉跎。\n明日别离去，连峰郁嵯峨。'},
    {t:'五弦行',a:'韦应物〔唐代〕',c:'美人为我弹五弦，尘埃忽静心断然。\n古刀幽磬初相触，千珠贯断落寒玉。\n中曲又不喧，徘徊夜逐月当轩。\n如伴风流萦艳雪，更逐落花飘御园。\n独凤寥寥有时隐，碧霄来下听还近。\n燕姬有恨楚客愁，言之不尽声能尽。\n末曲感我情，解幽释结和乐生。\n壮士有仇未得报，拔剑欲去愤已平，夜寒酒多愁遽明。'},
    {t:'五月初二日苦熟',a:'杨万里〔宋代〕',c:'人言“来江无六月”，我言六月无来江。\n只今五月已如许，六月更来何可当！船仓周围各五尺，且北此中底宽窄！上下东西与南北，一面是水五面日。\n日光煮水复成汤，此外何处能清凉？掀篷更无风半点，挥扇只有汗如浆。\n吾曹避暑自无处，飞蝇投吾求避暑；吾不解飞且此住，飞蝇解飞不飞去。'},
    {t:'五月旦作和戴主簿',a:'陶渊明〔魏晋〕',c:'虚舟纵逸棹，回复遂无穷。\n发岁始俯仰，星纪奄将中。\n南窗罕悴物，北林荣且丰。\n神萍写时雨，晨色奏景风。\n既来孰不去？人理固有终。\n居常待其尽，曲肱岂伤冲。\n迁化或夷险，肆志无窊隆。\n即事如已高，何必升华嵩。'},
    {t:'午憩筠庵',a:'杨万里〔宋代〕',c:'筠庵偶坐处，适当树阙间。\n远山来见我，而我见远山。\n清风隔江来，宛转入松关。\n翠蕉自摇扇，白羽得暂闲。\n可怜三竹床，睡遍复循环。\n秋暑自秋暑，山寒自山寒。\n小吟聊适意，美恶来必删。'},
    {t:'午睡',a:'王安石〔宋代〕',c:'檐日阴阴转，床风细细吹。\n翛然残午梦，何许一黄鹂。'},
    {t:'午枕',a:'王安石〔宋代〕',c:'百年春梦去悠悠，不复吹箫向此留。\n野草自花还自落，鸣禽相乳亦相酬。\n旧蹊埋没开新径，朱户欹斜见画楼。\n欲把一杯无伴侣，眼看兴废使人愁。'},
    {t:'武昌老人说笛歌',a:'刘禹锡〔唐代〕',c:'武昌老人七十馀，手把庾令相问书。自言少小学吹笛，\n早事曹王曾赏激。往年镇戍到蕲州，楚山萧萧笛竹秋。\n当时买材恣搜索，典却身上乌貂裘。古苔苍苍封老节，\n石上孤生饱风雪。商声五音随指发，水中龙应行云绝。\n曾将黄鹤楼上吹，一声占尽秋江月。如今老去语尤迟，\n音韵高低耳不知。气力已微心尚在，时时一曲梦中吹。'},
    {t:'武昌松风阁',a:'黄庭坚〔宋代〕',c:'依山筑阁见平川，夜阑箕斗插梧椽。\n我来名之意适然。\n老松魁梧数百年，斧斤所赦今参天。\n风泉娲皇五十弦，洗耳不须菩萨泉。\n嘉二三子甚好贤，力贫买酒醉此筵。\n夜雨泉廊到晓悬，相看不归卧僧毡。\n泉枯石燥复潺湲，山川光辉为我妍。\n野僧旱饥不能饘，晓见寒溪有炊烟。\n东坡道人已沉泉，张侯何时到眼前。\n钓台惊涛可昼眠，怡亭看篆蛟龙缠。\n安得此身脱拘挛，舟载诸友长周旋。'},
    {t:'武昌酌菩萨泉送王子立',a:'苏轼〔宋代〕',c:'送行无酒亦无钱，劝尔一杯菩萨泉。\n何处低头不见我？四方同此水中天。'},
    {t:'武关南见元九题山石榴花见寄',a:'白居易〔唐代〕',c:'往来同路不同时，前后相思两不知。\n行过关门三四里，榴花不见见君诗。'},
    {t:'武侯庙',a:'佚名〔明代〕',c:'剑江春水绿沄沄，五丈原头日已曛。\n旧业未能归后主，大星先已落前军。\n南阳祠宇空秋草，西蜀关山隔暮云。\n正统不惭传万古，莫将成败论三分。'},
    {t:'武侯庙',a:'杜甫〔唐代〕',c:'遗庙丹青落，空山草木长。\n犹闻辞后主，不复卧南阳。'},
    {t:'武侯庙古柏',a:'李商隐〔唐代〕',c:'蜀相阶前柏，龙蛇捧閟宫。\n阴成异江畔，老向惠陵东。\n大树思冯异，甘棠忆召公。\n叶凋湘燕雨，枝拆海鹏风。\n玉垒经纶远，金刀历数终。\n谁将出师表，一为问昭融。'},
    {t:'武林',a:'朱熹〔宋代〕',c:'春风不放桃花笑，阴雨能生客子愁。只我无心可愁得，西湖风月弄扁舟。'},
    {t:'武陵春',a:'晏几道〔宋代〕',c:'九日黄花如有意，依旧满珍丛。谁似龙山秋兴浓。吹帽落西风。\n年年岁岁登高节，欢事旋成空。几处佳人此会同。今在泪痕中。'},
    {t:'武陵春',a:'晏几道〔宋代〕',c:'绿蕙红兰芳信歇，金蕊正风流。应为诗人多怨秋。花意与消愁。\n梁王苑路香英密，长记旧嬉游。曾看飞琼戴满头。浮动舞梁州。'},
    {t:'武陵春',a:'晏几道〔宋代〕',c:'烟柳长堤知几曲，一曲一魂消。熏水无情天共遥。愁送木兰桡。\n熏香绣被心情懒，期信转迢迢。记得来时倚画桥。红泪满鲛绡。'},
    {t:'武陵春·桃李风前多妩媚',a:'辛弃疾〔宋代〕',c:'桃李风前多妩媚，杨柳更温柔。唤取笙歌烂熳游。且莫管闲愁。\n好趁春晴连夜赏，雨便一春休。草草杯盘不要收。才晓便扶头。'},
    {t:'武陵春·因呈子西',a:'杨万里〔宋代〕',c:'长铗归乎逾十暑，不著鵕鸃冠。道是今年胜去年。特地减清欢。\n旧赐龙团新作崇，频啜得中寒。瘦骨如柴痛又酸。儿信问平安。'},
    {t:'武陵春·走去走来三百里',a:'辛弃疾〔宋代〕',c:'走去走来三百里，五日以为期。六日归时已是疑。应是望多时。\n鞭个马儿归去也，心急马行迟。不免相烦喜鹊儿。先报那人知。'},
    {t:'武陵泛舟',a:'孟浩然〔唐代〕',c:'武陵川路狭，前棹入花林。莫测幽源里，仙家信几深。\n水回青嶂合，云度绿溪阴。坐听闲猿啸，弥清尘外心。'},
    {t:'武陵开元观黄炼师院三首',a:'王昌龄〔唐代〕',c:'松间白发黄尊师，童子烧香禹犬时。\n欲访桃源入溪路，忽闻鸡犬使人疑。\n先贤盛说桃花源，尘人何堪武陵郡。\n闻道秦时避地人，至今不与人通问。\n山观空虚清静门，从官役吏扰尘喧。\n暂因问俗到真境，便欲投诚依道源。'},
    {t:'武陵田太守席送司马卢溪',a:'王昌龄〔唐代〕',c:'诸侯分楚郡，饮饯五溪春。\n山水清晖远，俱怜一逐臣。'},
    {t:'武陵田太守席送司马卢谿',a:'王昌龄〔唐代〕',c:'诸侯分楚郡，饮饯五谿春。山水清晖远，俱怜一逐臣。'},
    {t:'武威送刘判官赴碛西行军',a:'岑参〔唐代〕',c:'火山五月行人少，看君马去疾如鸟。\n都护行营太白西，角声一动胡天晓。'},
    {t:'武威同诸公过杨七山人，得藤字',a:'高适〔唐代〕',c:'幕府日多暇，田家岁复登。相知恨不早，乘兴乃无恒。\n穷巷在乔木，深斋垂古藤。边城唯有醉，此外更何能。'},
    {t:'武夷精舍杂咏茶灶',a:'朱熹〔宋代〕',c:'仙翁遗石灶，宛在水中央。饮罢方舟去，茶烟袅细香。'},
    {t:'武夷精舍杂咏铁笛亭',a:'朱熹〔宋代〕',c:'何人轰铁笛，喷薄两崖开。千载留馀响，犹疑笙鹤来。'},
    {t:'武夷精舍杂咏隐求斋',a:'朱熹〔宋代〕',c:'晨窗林影开，夜枕山泉响。隐去复何求，无言道心长。'},
    {t:'武夷山',a:'李商隐〔唐代〕',c:'只得流霞酒一杯，空中箫鼓几时回。\n武夷洞里生毛竹，老尽曾孙更不来。'},
    {t:'舞曲歌辞·白纻歌',a:'柳宗元〔唐代〕',c:'翠帷双卷出倾城，龙剑破匣霜月明。朱唇掩抑悄无声，\n金簧玉磬宫中生。下沉秋水激太清，天高地迥凝日晶，\n羽觞荡漾何事倾。'},
    {t:'舞曲歌辞·白纻歌',a:'张籍〔唐代〕',c:'皎皎白纻白且鲜，将作春衫称尺年。\n裁缝长短不能定，自持刀尺向姑前。\n复恐兰膏污纤指，常遣傍人收堕珥。\n衣裳著时寒食下，还把玉鞭鞭白马。'},
    {t:'舞曲歌辞·拂舞辞',a:'李贺〔唐代〕',c:'吴娥声绝天，空云闲裴回。门外满车马，亦须生绿苔。\n尊有乌程酒，劝君千万寿。全胜汉武锦楼上，\n晓望晴寒饮花露。东方日不破，天光无老时。\n丹成作蛇乘白雾，千年重化玉井龟。从蛇作龟二千载。\n吴堤绿草年年在。背有八卦称神仙，邪鳞顽甲滑腥涎。'},
    {t:'舞曲歌辞·屈柘词',a:'温庭筠〔唐代〕',c:'杨柳萦桥绿，玫瑰拂地红。绣衫金騕褭，花髻玉珑璁。\n宿雨香潜润，春流水暗通。画楼初梦断，晴日照湘风。'},
    {t:'舞曲歌辞·章和二年中·鼙舞曲',a:'李贺〔唐代〕',c:'云萧索，风拂拂，麦芒如篲黍和乏。关中父老百领襦，\n关东吏人乏诟租。健犊春耕土膏黑，菖蒲百百沿水脉。\n殷勤为我下田鉏，百钱携赏丝桐客。游春漫光坞花白，\n野林散香神降席。拜神得寿献天子，七星贯断姮娥死。'},
    {t:'舞腰',a:'元稹〔唐代〕',c:'裙裾旋旋手迢迢，不趁音声自趁娇。\n未必诸郎知曲误，一时偷眼为回腰。'},
    {t:'舞衣曲',a:'温庭筠〔唐代〕',c:'藕肠纤缕抽轻春，烟机漠漠娇刀颦。\n金梭淅沥透空薄，剪落交刀吹断云。\n张家公子夜闻雨，夜香兰堂思楚舞。\n蝉衫麟带压愁香，偷得莺簧锁金缕。\n管含兰气娇语悲，胡槽雪腕鸳鸯丝。\n芙蓉力弱应难定，杨柳风多不自持。\n回颦笑语西窗客，星斗寥寥波脉脉。\n不逐秦王卷象床，满楼明月梨花白。'},
    {t:'勿去草',a:'王安石〔宋代〕',c:'勿去草，草无恶。\n若比世俗俗浮客。\n君不见长安卿家，公卿盛时客如麻。\n公卿去後门无车，惟有江草年年佳。\n又不见千里万里江湖滨，触目凄凄无故人，惟有江草随车轮。\n一日还旧居，门前草先锄。\n草於主人实无负，主人於草宜何如。\n勿去草，草无恶。\n若比世俗俗浮客。'},
    {t:'戊申岁六月中遇火',a:'陶渊明〔魏晋〕',c:'草庐寄穷巷，甘以辞华轩。\n正夏宇风急，林室顿烧燔。\n一宅无遗宇，舫舟荫门前。\n迢迢新秋夕，未未月将圆。\n果菜始复生，惊鸟尚未还。\n中宵伫遥念，一盼周九天。\n总发抱孤介，奄出四十年。\n形迹凭化往，灵府宇独闲。\n贞刚自有质，玉石乃非坚。\n仰想东户时，余粮宿中田。\n鼓腹无所思；朝起暮归眠。\n既已不遇兹，且遂灌我园。'},
    {t:'悟道诗',a:'佚名〔宋代〕',c:'尽日寻春不见春，芒鞋踏遍陇头云。\n归来笑拈梅花嗅，春在枝头已十分。'},
    {t:'悟真院',a:'王安石〔宋代〕',c:'野水从横漱屋除，午窗残梦鸟相呼。\n春风日日吹香草，山北山南路欲无。'},
    {t:'夕次蔡阳馆',a:'孟浩然〔唐代〕',c:'日暮马行疾，城荒人住稀。\n听歌知近楚，投馆忽如归。\n鲁堰田畴广，章陵气色微。\n明朝拜嘉庆，须著老莱衣。'},
    {t:'夕次寿阳驿题吴郎中诗后',a:'韩愈〔唐代〕',c:'风光欲动别长安，春半城边特地寒。\n不见园花兼巷柳，马头惟有月团团。'},
    {t:'夕次盱眙县',a:'韦应物〔唐代〕',c:'落帆逗淮镇，停舫临孤驿。\n浩浩风起波，冥冥日沉夕。\n人归山郭暗，雁下芦洲白。\n独夜忆秦关，听钟未眠客。'},
    {t:'夕阳楼',a:'李商隐〔唐代〕',c:'在荥阳，是所知今遂宁萧侍郎愁荥阳日作矣。\n花明柳暗绕天愁，上尽重城更上楼。\n欲问孤鸿向何处？不知身世自悠悠。'},
    {t:'西北有高楼',a:'佚名〔两汉〕',c:'西北有高楼，上与浮云齐。\n交疏结绮窗，阿阁三重阶。\n上有弦歌声，音响一何悲！\n谁能为此曲，无乃杞梁妻。\n清商随风发，中曲正徘徊。\n一弹再三叹，慷慨有余哀。\n不惜歌者苦，但伤知音稀。\n愿为双鸿鹄，奋翅起高飞。'},
    {t:'西村',a:'陆游〔宋代〕',c:'乱山深处小桃源，往岁求浆忆叩门。\n高柳簇桥初转马，数家临水自成村。\n茂林风送幽禽语，坏壁苔侵醉墨痕。\n一首清诗记今夕，细云新月耿黄昏。'},
    {t:'西村醉归',a:'陆游〔宋代〕',c:'侠气峥嵘盖九州，一生常耻为施谋。\n酒宁剩欠寻常债，剑不虚施细碎雠。\n歧路凋零白羽箭，风霜破弊黑貂裘。\n阳狂自是英豪事，村市归来醉跨牛。'},
    {t:'西宫春怨',a:'王昌龄〔唐代〕',c:'西宫夜静百花香，欲卷珠帘春恨长。\n斜抱云和深见月，朦胧树色隐昭阳。'},
    {t:'西宫秋怨',a:'王昌龄〔唐代〕',c:'芙蓉不及美人妆，水殿风来珠翠香。\n谁分含啼掩秋扇，空悬明月待君王。'},
    {t:'西瓜吟',a:'文天祥〔宋代〕',c:'拔出金佩刀，斫破苍玉瓶。\n千点红樱桃，一团黄水晶。\n下咽顿除烟火气，入齿便作冰雪声。\n长安清富说邵平，争如汉朝作公卿。'},
    {t:'西过渭州见渭水思秦川',a:'岑参〔唐代〕',c:'渭水东流去，何时到雍州？\n凭添两行泪，寄向故园流。'},
    {t:'西还至散关答乔补阙知之',a:'陈子昂〔唐代〕',c:'葳蕤苍梧凤，嘹唳白露蝉。羽翰本非匹，结交何独全。\n昔君事胡马，余得奉戎旃。携手向沙塞，关河缅幽燕。\n芳岁几阳止，白日屡徂迁。功业云台薄，平生玉佩捐。\n叹此南归日，犹闻北戍边。代水不可涉，巴江亦潺湲。\n揽衣度函谷，衔涕望秦川。蜀门自兹始，云山方浩然。'},
    {t:'西河',a:'周邦彦〔宋代〕',c:'长安道，潇洒西风时起。尘埃车马晚游行，霸陵烟水。乱鸦栖鸟夕阳中，参差霜树相倚。\n到此际。愁如苇。冷落关河千里。追思唐汉昔繁华，断碑残记。未央宫阙已成灰，终南依旧浓翠。\n对此景、无限愁思。绕天涯、秋蟾如水。转使客情如醉。想当时、万古雄名，尽作往来人、凄凉事。'},
    {t:'西河·花最盛',a:'张炎〔宋代〕',c:'花最盛。西湖曾泛烟艇。闹红深不小秦筝，断桥夜饮。鸳鸯水宿不知寒，如今翻被惊醒。那时事、得倦省。阑干来此闲凭。是谁分得半边机云，恍疑昼锦。想当飞燕皱裙时，舞盘微堕珠粉。软波不翦素练净。碧盈盈、移下秋影。醉里玉书难认。且脱巾露发，飘然乘兴。一叶浮香天风冷。'},
    {t:'西河·金陵怀古',a:'周邦彦〔宋代〕',c:'佳丽地，南朝盛事谁记。山围故国绕清江，髻鬟对起。怒涛寂寞打孤城，风樯遥度天际。\n断崖树、犹倒倚，莫愁艇子曾系。空余旧迹郁苍苍，雾沉半垒。夜深月过女墙来，伤心东望淮水。\n酒旗戏鼓甚处市？想依稀、王谢邻里，燕子不知何世，入寻常、巷陌人家，相对如说兴亡，斜阳里。'},
    {t:'西湖晚归回望孤山寺赠诸客',a:'白居易〔唐代〕',c:'柳湖松岛莲花寺，晚动归桡出道场。\n卢橘子低山雨重，栟榈叶战水风凉。\n烟波澹荡摇空碧，楼殿参差倚夕阳。\n到岸请君回首望，蓬莱宫在海中央。'},
    {t:'西涧即事示卢陟',a:'韦应物〔唐代〕',c:'寝扉临碧涧，晨起澹忘情。\n空林细雨至，圆文遍水生。\n永日无馀事，山中伐木声。\n知子尘喧久，暂可散烦缨。'},
    {t:'西江怀古',a:'杜牧〔唐代〕',c:'上吞巴汉控潇湘，怒似连山静镜光。\n魏帝缝囊真戏剧，苻坚投棰更荒唐。\n千秋钓舸歌明月，万里沙鸥弄夕阳。\n范蠡清尘何寂寞，好风唯属往来商。'},
    {t:'西江寄越弟',a:'王昌龄〔唐代〕',c:'南浦逢君岭外还，沅溪更远洞庭山。\n尧时恩泽如春雨，梦里相逢同入关。'},
    {t:'西江上送渔父',a:'温庭筠〔唐代〕',c:'却逐严光向若耶，钓轮菱棹寄年华。\n三秋梅雨愁枫叶，一夜篷舟宿苇花。\n不见水云应有梦，偶随鸥鹭便成家。\n白蘋风起楼船暮，江燕双双五两斜。'},
    {t:'西江夜行',a:'张九龄〔唐代〕',c:'遥夜人何在，澄潭月里行。\n悠悠扰宇旷，切切故乡情。\n外物寂无扰，中流澹自清。\n念归林叶换，愁坐露华生。\n犹有汀洲鹤，宵分乍一鸣。'},
    {t:'西江月',a:'黄庭坚〔宋代〕',c:'月，小舟坐水眠空。雾窗春色翠笑葱。睡起云涛正拥。¤往事回头笑处，此生弹指声中。玉笺佳句之惊鸿。闻道衡阳价重。”次韵酬之。时余方谪宜阳，而洪归分宁龙安\n月侧金盆堕水，雁回醉墨书空。君诗秀色雨园葱。想见衲衣寒拥。\n蚁穴梦魂人世，杨花踪迹风中。莫将社燕等秋鸿。处处春山翠重。'},
    {t:'西江月',a:'晏几道〔宋代〕',c:'南苑垂鞭路冷，西楼把袂人稀。庭花犹有鬓边枝。且插残红自醉。\n画幕凉催燕去，香屏晓放云归。依前青枕梦回时。试问闲愁有几。'},
    {t:'西江月',a:'柳永〔宋代〕',c:'师师生得艳冶，香香于我情多。安安那更久比和。四个打成一个。\n幸自苍皇未款，新词写处多磨。几回扯了又重挼。姦字中头著我。'},
    {t:'西江月',a:'朱熹〔宋代〕',c:'睡处林风瑟瑟，觉来山月团团。身心无累久轻安。况有清池凉馆。\n句稳翻嫌白俗，情高却笑郊寒。\n兰膏元自少陵残。好处金章不换。'},
    {t:'西江月·茶',a:'黄庭坚〔宋代〕',c:'龙焙头纲春早，谷帘第一泉香。已醺浮蚁嫩鹅黄。想见翻成雪浪。\n兔褐金丝宝碗，松风蟹眼新汤。无因更发次公狂。甘露来从仙掌。'},
    {t:'西江月·愁黛颦成月浅',a:'晏几道〔宋代〕',c:'愁黛颦成月浅，\n啼妆印得花残。\n懒消鸳枕夜来闲，\n晓镜心情便懒。\n醉帽檐头风细，\n征衫袖口香寒。\n绿江春水寄书难，\n携手佳期又晚。'},
    {t:'西江月·春晚',a:'辛弃疾〔宋代〕',c:'胜欲读书已懒，只因多病长闲。听风听雨小窗眠。过了春光太半。\n往事如寻去鸟，清愁难解连环。流莺不肯入西园。唤起画梁飞燕。'},
    {t:'西江月·断送一生惟有',a:'黄庭坚〔宋代〕',c:'老夫既戒酒不饮，遇宴集，独醒断旁。坐客欲得小词，援笔为赋。\n断送一生惟有，破除万事无过。我山横黛蘸秋波，不饮旁人笑我。\n花病等闲瘦弱，春愁无处遮拦。杯行到手莫留残，不道月斜人散。'},
    {t:'西江月·粉面都成醉梦',a:'辛弃疾〔宋代〕',c:'粉面都成醉梦，霜髯能几春秋。来时诵我伴牢愁。一见尊前似旧。\n诗在阴何侧畔，字居罗赵前头。锦囊来往几时休。已遣蛾眉等候。'},
    {t:'西江月·凤额绣帘高卷',a:'柳永〔宋代〕',c:'凤额绣帘高卷，兽环朱户频摇。觉竿红日上花梢。春睡厌厌难觉。\n好梦狂随飞絮，闲愁浓胜香醪。不成雨暮与云朝。又是韶光过了。'},
    {t:'西江月·姑熟再见胜之次前韵',a:'苏轼〔宋代〕',c:'姑熟再见胜之，次前韵。\n别梦已旧流水，泪巾犹浥香泉。相如依旧是臞仙。人在瑶台阆苑。\n花雾萦风缥缈，歌珠滴水清圆。蛾眉新作十分妍。走马归来便面。'},
    {t:'西江月·红梅',a:'王安石〔宋代〕',c:'梅好惟嫌淡伫，天教薄与胭脂。真妃初出华清池。酒入琼姬半醉。\n东阁诗情易动，高楼玉管休吹。北人浑作杏花疑。惟有青枝不似。'},
    {t:'西江月·花气烘人尚暖',a:'张炎〔宋代〕',c:'花气烘人尚暖，珠光出海犹寒。断今贺老见应难。解道江南肠断。谩击铜壶浩叹，空存锦瑟谁弹。庄生蝴蝶梦春还。帘外一声莺唤。'},
    {t:'西江月·梅花',a:'苏轼〔宋代〕',c:'玉骨那愁瘴雾，冰姿自有仙风。海仙时遣探芳丛。倒挂绿毛么凤。'},
    {t:'西江月·缥缈波明洛浦',a:'张炎〔宋代〕',c:'缥缈波明洛浦，依稀玉立湘皋。独将兰蕙入离骚。不识山中瑶草。月照英翘楚楚，江空醉魄陶陶。犹疑颜色尚清高。一笑出门春老。'},
    {t:'西江月·平山堂',a:'苏轼〔宋代〕',c:'三过平山堂下，半生弹指声中。动年不见老仙翁，壁上龙蛇飞动。\n欲吊文章太守，仍歌杨柳春风。休言万事转头空，未转头时皆梦。'},
    {t:'西江月·遣兴',a:'辛弃疾〔宋代〕',c:'醉里且贪欢笑，要愁那得工夫。近来始觉古人书，信著全无是处。\n昨夜松边醉倒，问松我醉何如。只疑松动要来扶，以手推松曰“去！”'},
    {t:'西江月·顷在黄州',a:'苏轼〔宋代〕',c:'顷在黄州，春夜行蕲水中，过酒家饮，酒醉，乘月至一溪桥上，解鞍曲肱，醉卧少休。及觉已晓，乱山攒拥，流水锵然，疑非尘世也。书此语桥柱上。\n照野弥弥浅浪，横空隐隐层霄。障泥未解玉骢骄，我欲醉眠芳草。\n可惜一溪风月，莫教踏碎琼瑶。解鞍欹枕绿杨桥，杜宇一声春晓。'},
    {t:'西江月·人道偏宜歌舞',a:'辛弃疾〔宋代〕',c:'人道偏宜歌舞，天教只入丹青。应天画鼓要他听。把著花枝不应。何处娇魂瘦影，向来软语柔情。有时醉里唤卿卿。却被傍人笑问。'},
    {t:'西江月·示儿曹以家事付之',a:'辛弃疾〔宋代〕',c:'万事云烟忽过，一身蒲柳先衰。睡今何事最相宜，宜醉宜游宜睡。\n早趁催科了纳，更量出入收支。乃翁依旧管些儿，管竹管山管水。'},
    {t:'西江月·送别',a:'苏轼〔宋代〕',c:'昨夜扁舟京口，今朝马首长安。旧官何物与新官。只有湖山公案。\n此景百年几变，个中下语千难。使君才气卷波澜。与把新诗判断。'},
    {t:'西江月·堂上谋臣帷幄',a:'辛弃疾〔宋代〕',c:'堂上谋臣帷幄，边头猛将干戈。可时地利与人和。燕可伐与曰可。\n此日楼台鼎鼐，他时剑履山河。都人齐和大风歌。管领群臣来贺。'},
    {t:'西江月·堂下水浮新绿',a:'朱熹〔宋代〕',c:'堂下水浮新绿，门前树长交枝。晚凉快写一篇诗。不说人间忧喜。身老心闲益壮，形癯道胜还肥。软轮加璧未应迟。莫道前非今是。'},
    {t:'西江月·同前',a:'张炎〔宋代〕',c:'落落奇花未吐，离离瑶草偏幽。蓬山元是不知秋。却笑人间春瘦。\n潇酒寒犀尘尾，玲珑润玉搔头。半窗晴日水痕收。不怕杜鹃啼后。'},
    {t:'西江月·闻道双衔凤带',a:'苏轼〔宋代〕',c:'闻道双衔凤带，不妨单著鲛绡。袅香知与阿谁烧。怅望水沈烟袅。\n云鬓风前绿卷，玉颜醉里红潮。莫教空度可怜宵。月与佳人共僚。'},
    {t:'西江月·秀骨青松不老',a:'辛弃疾〔宋代〕',c:'秀骨青松不老，新词玉佩相磨。灵槎准拟泛银河，剩摘天星几个。\n奠枕楼头风月，驻春亭上笙歌。留君一醉意如何？金印明年斗大。'},
    {t:'西江月·夜行黄沙道中',a:'辛弃疾〔宋代〕',c:'明月别枝惊鹊，清风半夜鸣蝉。片花香里说丰年，听取蛙声一片。\n七八个星天外，两三点雨山前。旧时茅店社林边，路转溪桥忽见。'},
    {t:'西江月·咏梅',a:'苏轼〔宋代〕',c:'马趁香微路远，沙笼月淡烟斜。挂波清彻映妍华。倒绿枝寒凤挂。\n挂凤寒枝绿倒，华妍映彻清波。挂斜烟淡月笼沙。远路微香趁马。'},
    {t:'西江月·用惠洪韵',a:'黄庭坚〔宋代〕',c:'细细风清撼竹，迟迟日暖开花。香帏深卧醉人家。媚语娇声娅姹。\n姹娅声娇语媚，家人醉卧深帏。香花开暖日迟迟。竹撼清风细细。'},
    {t:'西江月·渔父词',a:'辛弃疾〔宋代〕',c:'千丈悬崖削翠，一川落日镕金。白鸥来往本无心。选甚风波一任。\n别浦鱼肥堪脍，前村酒美重斟。千年往事已沉沉。闲管兴亡则甚。'},
    {t:'西江月·再用前韵戏曹子方',a:'苏轼〔宋代〕',c:'怪此花枝怨泣，托君诗句名通。凭将草木记吴风。继取相如云梦。\n点笔袖沾醉墨，谤花面有惭红。知君却是为情秾。怕见此花撩动。'},
    {t:'西江月·真觉赏瑞香二首',a:'苏轼〔宋代〕',c:'公子眼花乱发，老夫鼻观先通。领巾飘下瑞香风。惊起谪仙春梦。\n后土祠中玉蕊，蓬莱殿后鞓红。此花清绝更纤秾。把酒何人心动。'},
    {t:'西江月·中秋和子由',a:'苏轼〔宋代〕',c:'世事一场大梦，人生几度秋凉？上来风叶已鸣廊。看取眉头鬓上。\n酒贱常愁客少，月明多被云妨。中秋谁与共孤光。把盏凄然北望。'},
    {t:'西江月·重九',a:'苏轼〔宋代〕',c:'点点楼头细雨，重重江外平湖。当年戏马会东徐，今日凄凉南浦。\n莫恨黄花未吐，且教红粉相扶。酒阑不必看茱萸，俯仰人间今古。'},
    {t:'西江月·坐客见和复次韵',a:'苏轼〔宋代〕',c:'小院朱阑几曲，重城画鼓三通。更看微月转光风。归去香云入梦。\n翠袖争浮大白，皂罗半插斜红。灯花零落酒花秾。妙语一时飞动。'},
    {t:'西郊期涤武不至，书示',a:'韦应物〔唐代〕',c:'山高鸣过雨，涧树落残花。非关春不待，当由期自赊。'},
    {t:'西郊燕集',a:'韦应物〔唐代〕',c:'济济众君子，高宴及时光。群山霭遐瞩，绿野布熙阳。\n列坐遵曲岸，披襟袭兰芳。野庖荐嘉鱼，激涧泛羽觞。\n众鸟鸣茂林，绿草延高冈。盛时易徂谢，浩思坐飘飏。\n眷言同心友，兹游安可忘。'},
    {t:'西郊纵步',a:'朱熹〔宋代〕',c:'西郊一游步，极目是秋山。积水群峰碧，清霜枫树丹。\n故园心不展，投策讵能闲。且适平生意，无令双鬓斑。'},
    {t:'西陵道士茶歌',a:'温庭筠〔唐代〕',c:'乳窦溅溅通石脉，绿尘愁草春江色。涧花入井水味香，\n山月当人松影直。仙翁白扇霜鸟翎，拂坛夜读黄庭经。\n疏香皓齿有馀味，更觉鹤心通杳冥。'},
    {t:'西楼',a:'韦应物〔唐代〕',c:'高阁一长望，故园何日归。\n烟尘拥函谷，秋雁过来稀。'},
    {t:'西楼望月',a:'张籍〔唐代〕',c:'城西楼上月，复是雪晴时。寒夜共来望，思乡独下迟。\n幽光落水堑，净色在霜枝。明日千里去，此中还别离。'},
    {t:'西南行却寄相送者',a:'李商隐〔唐代〕',c:'百里阴云覆雪泥，行人只在雪云西。\n明朝惊破还乡梦，定是陈仓碧野鸡。'},
    {t:'西平乐·尽日凭高目',a:'柳永〔宋代〕',c:'尽日凭高目，脉脉春情绪。嘉景清明渐近，时节轻寒乍暖，天气才晴又雨。烟光淡荡，妆点平芜远树。黯凝伫。台榭好、莺燕语。\n正是和风丽日，几许繁红嫩绿，雅称嬉游去。奈阻隔、寻芳伴侣。秦楼凤吹，楚馆云约，空怅望、在何处。寂寞韶华暗度。可堪向晚，村落声声杜宇。'},
    {t:'西塞山',a:'韦应物〔唐代〕',c:'势从千里奔，直入江中断。\n岚横秋塞雄，地束惊流满。'},
    {t:'西塞山怀古',a:'刘禹锡〔唐代〕',c:'王濬楼船下益州，金陵王气黯然收。\n千寻铁锁沉江底，一片降幡出石头。\n人世几回伤往事，山形依旧枕寒流。\n今逢四海为家日，故垒萧萧芦荻秋。'},
    {t:'西山寻辛谔',a:'孟浩然〔唐代〕',c:'漾舟乘水便，因访故人庄。\n落日清川里，谁言独羡鱼？\n石潭窥洞彻，沙岸历纡徐。\n竹屿见垂钓，茅斋闻读书。\n款言忘景夕，清兴属凉初。\n回也一瓢饮，贤哉常晏如。'},
    {t:'西上经灵宝观·观即尹真人旧宅',a:'孟郊〔唐代〕',c:'道士无白发，语音灵泉清。\n青松多寿色，白石恒夜明。\n放步霁霞起，振衣华风生。\n真文秘中顶，宝气浮四楹。\n一片古关路，万里今人行。\n上仙不可见，驱策徒西征。'},
    {t:'西施·柳街灯市好花多',a:'柳永〔宋代〕',c:'柳街灯市好花多。尽让美琼娥。万娇千媚，的的在层波。取次梳妆，自有天然态，爱浅画双蛾。\n断肠最是金闺客，空怜爱。奈伊何。洞房咫尺，无计枉朝珂。有意怜才，每遇行云处，幸时恁相过。'},
    {t:'西施·苎萝妖艳世难偕',a:'柳永〔宋代〕',c:'苎萝妖艳世难偕。善媚悦君怀。后庭恃宠，尽使绝嫌猜。正恁朝欢暮宴，情未足，早江上兵来。\n捧心调态军前死，罗绮旋变尘埃。至今想，怨魂无主尚徘徊。夜夜姑苏城外，当时月，但空照荒台。'},
    {t:'西施·自从回步百花桥',a:'柳永〔宋代〕',c:'自从回步百花桥。便独处清宵。香衾鸳枕，何事等闲抛。纵有馀香，也似郎恩爱，向日夜潜消。\n恐更不信芳容改，将憔悴、写霜绡。更凭锦字，字字说情憀。要识愁肠，但看丁香树，渐结尽春梢。'},
    {t:'西施咏',a:'王维〔唐代〕',c:'艳色天下重，西施宁久微。\n朝为越溪女，暮作吴宫妃。\n贱日岂殊众，贵来方悟稀。\n邀人傅脂粉，不自著罗衣。\n君宠益娇态，君怜无是非。\n当时浣纱伴，莫得同车归。\n持谢邻家子，效颦安可希。'},
    {t:'西亭',a:'李商隐〔唐代〕',c:'此夜西亭月正圆，疏帘相伴宿风烟。\n梧桐莫更翻清露，孤鹤从来不得眠。'},
    {t:'西亭送蒋侍御还京·得来字',a:'岑参〔唐代〕',c:'忽闻骢马至，喜见故人来。欲语多时别，先愁计日回。\n山河宜晚眺，云雾待君开。为报乌台客，须怜白发催。'},
    {t:'西亭子送李司马',a:'岑参〔唐代〕',c:'高高亭子郡城西，直上千尺与下齐。\n盘崖缘壁试攀跻，群山向下飞鸟低。\n使君五马天半嘶，丝倪玉壶为君提。\n坐来一望无端倪，红花绿柳莺乱啼，千家万井连回溪。\n酒行未醉闻暮鸡，点笔操纸为君题。\n为君题，惜解携。草萋萋，没马蹄。'},
    {t:'西溪',a:'李商隐〔唐代〕',c:'怅望西溪水，潺湲奈尔何。不惊春物少，只觉夕阳多。\n色染妖韶柳，光含窈窕萝。人间从到海，天上莫为河。\n凤女弹瑶瑟，龙孙撼玉珂。京华他夜梦，好好寄云波。'},
    {t:'西溪独泛',a:'皎然〔唐代〕',c:'道情何所寄，素舸漫流间。\n真性怜高鹤，无名羡野山。\n经寒丛竹秀，人静片云闲。\n泛泛谁为侣，唯应共月还。'},
    {t:'西溪见牡丹',a:'范仲淹〔宋代〕',c:'阳和不择地，海角亦逢春。\n忆得上林色，相看如故人。'},
    {t:'西溪书事',a:'范仲淹〔宋代〕',c:'卑栖曾未托椅梧，敢议雄心万里途。\n蒙叟自当齐黑白，子牟何必怨江湖。\n秋天响亮频闻鹤，夜海曈曨每见珠。\n一醉一吟疏懒甚，溪人能信解嘲无。'},
    {t:'西掖省即事',a:'岑参〔唐代〕',c:'西掖重云开曙晖，北山疏雨点朝衣。千门柳色连青琐，\n三殿花香入紫微。平明端笏陪鹓列，薄暮垂鞭信马归。\n官拙自悲头白尽，不如岩下偃荆扉。'},
    {t:'西园',a:'陆游〔宋代〕',c:'半掩朱门藓径斜，翠屏绣谷忽谽谺。\n高高下下天成景，密密疏疏自在花。\n江近夕阳迎宿鹭，林昏残角促归鸦。\n吾舟已系津南岸，唤客犹能一笑哗。'},
    {t:'西垣榴花',a:'晏殊〔宋代〕',c:'山木有甘实，托根清禁中。\n岁芳摇落尽，独自向炎风。'},
    {t:'西岳云台歌送丹丘子',a:'李白〔唐代〕',c:'西岳峥嵘何壮哉！黄河如丝天际来。\n黄河万里触山动，盘涡毂转秦地雷。\n荣光休气纷五彩，千年一清圣人在。\n巨灵咆哮擘两山，洪波喷箭射东海。\n三峰却立如欲摧，翠崖丹谷高掌开。\n白帝金精运元气，石作莲花云作台。\n云台阁道连窈冥，中有不死丹丘生。\n明星玉女备洒扫，麻姑搔背指爪轻。\n我皇手把天地户，丹丘谈天与天语。\n九重出入生光辉，东来蓬莱复西归。\n玉浆倘惠故人饮，骑二茅龙上天飞。'},
    {t:'西斋小松二首',a:'元稹〔唐代〕',c:'松树短于我，清风亦已多。况乃枝上雪，动摇微月波。\n幽姿得闲地，讵感岁蹉跎。但恐厦终构，藉君当奈何。\n簇簇枝新黄，纤纤攒素指。柔苙渐依条，短莎还半委。\n清风日夜高，凌云意何已。千岁盘老龙，修鳞自兹始。'},
    {t:'西州',a:'张籍〔唐代〕',c:'羌胡据西州，近甸无边城。山东收税租，养我防塞兵。\n胡骑来无时，居人常震惊。嗟我五陵间，农者罢耘耕。\n边头多杀伤，士卒难全形。郡县发丁役，丈夫各征行。\n生男不能养，惧身有姓名。良马不念秣，烈士不苟营。\n所愿除国难，再逢天下平。'},
    {t:'西子妆慢',a:'张炎〔宋代〕',c:'吴梦窗自制此曲，予喜其声调寓雅，久欲述之而未能。甲午春寓罗江，与罗景良野游江上，绿旧芳草，景况离离，因填此解。惜旧谱零落，不能倚声而歌也。\n白浪摇天，青旧涨地，一片野怀幽意。杨花点点是春心，替风前、万花吹泪。遥岑寸碧。有谁识、朝来清气。自沈吟、甚流光轻掷，繁华如此。\n斜阳外。隐约孤村，隔坞闲门闭。渔舟何似莫归来，想桃源、路通人世。危桥静倚。千年事、都消一醉。谩依依，愁落鹃声万里。'},
    {t:'息夫人',a:'王维〔唐代〕',c:'莫以今时宠，难忘旧日恩。\n看花满眼泪，不共楚王言。'},
    {t:'惜春',a:'杜牧〔唐代〕',c:'春半年已除，其馀强为有。即此醉残花，便同尝腊酒。\n怅望送春杯，殷勤扫花帚。谁为驻东流，年年长在手。'},
    {t:'惜春词',a:'温庭筠〔唐代〕',c:'百舌问花花不语，低回似恨横塘雨。\n蜂争粉蕊蝶分香，不似垂杨惜金缕。\n愿君留得长妖韶，莫逐东风还荡摇。\n秦女含颦向烟月，愁红带露空迢迢。'},
    {t:'惜春郎·玉肌琼艳新妆饰',a:'柳永〔宋代〕',c:'玉肌琼艳新妆饰。好壮观歌席，潘妃宝钏，阿娇金屋，应也消得。\n属和新词多俊格。敢共我勍敌。恨少年、枉费疏狂，不早与伊相识。'},
    {t:'惜红衣·赠伎双波',a:'张炎〔宋代〕',c:'两剪秋痕，平分水影，炯然冰洁。未识新愁，眉心倩人贴。无端醉里，通一笑、柔花盈睫。痴绝。不解送情，倚银屏斜瞥。\n长歌短舞，换羽移宫，飘飘步回雪。扶娇倚扇，欲把艳怀说。□□杜郎重到，只虑空江桃叶。但数峰犹在，如傍那家风月。'},
    {t:'惜花',a:'张籍〔唐代〕',c:'春潭足芳树，水清不如素。幽人爱华景，一一空山暮。\n月出潭气白，游鱼暗冲石。夜深春思多，酒醒山寂寂。'},
    {t:'惜苦',a:'孟郊〔唐代〕',c:'于鹄值谏议，以球不能官。焦蒙值舍人，以杯不得完。\n可惜大雅旨，意此小团栾。名回不敢辨，心转实是难。\n不惜为君转，转非君子观。转之复转之，强转谁能欢。\n哀哉虚转言，不可穷波澜。'},
    {t:'惜牡丹花二首',a:'白居易〔唐代〕',c:'惆怅阶前红牡丹，晚来唯有两红残。\n明朝风起应吹尽，夜惜衰红把火看。\n寂寞萎红低向雨，离披破艳散随风。\n晴明落地犹惆怅，何况飘零泥土中。'},
    {t:'惜暮景',a:'皎然〔唐代〕',c:'疏阴花不动，片景松梢度。夏日旧来长，佳游何易暮。'},
    {t:'溪居',a:'柳宗元〔唐代〕',c:'久为簪组累，幸此南夷谪。\n闲依农圃邻，偶似山林客。\n晓耕翻露草，夜榜响溪石。\n来往不逢人，长歌楚天碧。'},
    {t:'溪上小雨',a:'陆游〔宋代〕',c:'我是人间自在人，江湖处处可垂纶。\n扫空紫陌红尘梦，收得烟蓑雨笠身。'},
    {t:'溪上行',a:'温庭筠〔唐代〕',c:'绿塘漾漾烟濛濛，张翰此来情不穷。\n雪羽褵褷立倒影，金鳞拨剌跳晴空。\n风翻荷叶一向白，雨湿蓼花千穗红。\n心羡夕阳波上客，片时归梦钓船中。'},
    {t:'溪上月',a:'皎然〔唐代〕',c:'秋水月娟娟，初生色界天。蟾光散浦溆，素影动沦涟。\n何事无心见，亏盈向夜禅。'},
    {t:'溪上作',a:'陆游〔宋代〕',c:'落日溪边杖白头，破裘不补冷飕飕。\n戆愚酷信纸上语，老病犹先天下忧。\n末俗凌迟稀独立，斯文崩坏欲横流。\n绍兴人物嗟谁在，空记当年接俊游。'},
    {t:'溪上作二首·其二',a:'陆游〔宋代〕',c:'伛偻溪头白发翁，暮年心事一枝筇。\n山衔落日青横野，鸦起平沙黑蔽空。\n天下可忧非一事，书生无地效孤忠。\n东山七月犹关念，未忍沉浮酒醆中。'},
    {t:'溪晚凉',a:'李贺〔唐代〕',c:'白狐向月号山风，秋寒扫云留碧空。\n玉烟青湿白如幢，银湾晓转流天东。\n溪汀眠鹭梦征鸿，轻涟不语细游溶。\n层岫回岑复叠龙，苦篁对客吟歌筒。'},
    {t:'溪行寄王震',a:'张九龄〔唐代〕',c:'山气朝来爽，溪流日向清。远心何处惬，闲棹此中行。\n丛桂林间待，群鸥水上迎。徒然适我愿，幽独为谁情。'},
    {t:'熙宁以后祀高禖六首',a:'佚名〔隋代〕',c:'赫赫高禖，万世所祀。\n其德不回，锡兹福祉。\n蕃衍椒聊，和平芣莒。\n傅类降康，世济其美。'},
    {t:'檄风伯',a:'杨万里〔宋代〕',c:'峭壁呀呀虎擘口，恶滩汹汹雷船吼。\n泝流更著打头风，如撑铁船上牛斗。\n风伯劝尔一杯酒，何须恶剧惊诗叟。\n端能为我霁威否？岸柳掉头荻摇手。'},
    {t:'洗儿诗',a:'苏轼〔宋代〕',c:'人皆养子望聪明，我被聪明误一生。\n惟愿孩儿愚且鲁，无灾无难到公卿。'},
    {t:'洗然弟竹亭',a:'孟浩然〔唐代〕',c:'吾与二三子，平生结交深。\n俱怀鸿鹄志，昔有鶺鴒心。\n逸气假毫翰，清风在竹林。\n达是酒中趣，琴上偶然音。'},
    {t:'喜春来·七夕',a:'佚名〔元代〕',c:'天孙一夜停机暇，人世千家乞巧忙，想双星心事密话头长。七月七，回首笑三郎。'},
    {t:'喜达行在所三首',a:'杜甫〔唐代〕',c:'西忆岐阳信，无人遂却回。\n眼穿当落日，心死著寒灰。\n雾树行相引，莲峰望忽开。\n所亲惊老瘦，辛苦贼中来。\n愁思胡笳夕，凄凉汉苑春。\n生还今日事，间道暂时人。\n司隶章初睹，南阳气已新。\n喜心翻倒极，呜咽泪沾巾。\n死去凭谁报，归来始自怜。\n犹瞻太白雪，喜遇武功天。\n影静千官里，心苏七校前。\n今朝汉社稷，新数中兴年。'},
    {t:'喜观即到复题短篇二首',a:'杜甫〔唐代〕',c:'巫峡千山暗，终南万里春。\n病中吾见弟，书到汝为人。\n意答儿童问，来经战伐新。\n泊船悲喜后，款款话归秦。\n待尔嗔乌鹊，抛书示鶺鸰。\n枝间喜不去，原上急曾经。\n江阁嫌津柳，风帆数驿亭。\n应论十年事，愁绝始星星。'},
    {t:'喜韩樽相过',a:'岑参〔唐代〕',c:'三月灞陵春已老，故人相逢耐醉倒。瓮头春酒黄花脂，\n禄米只充沽酒资。长安城中足年少，独共韩侯开口笑。\n桃花点地红斑斑，有酒留君且莫还。与君兄弟日携手，\n世上虚名好是闲。'},
    {t:'喜李十一景信到',a:'元稹〔唐代〕',c:'何事相逢翻有泪，念君缘我到通州。\n留君剩住君须住，我不自由君自由。'},
    {t:'喜马参军相遇醉歌',a:'陈子昂〔唐代〕',c:'独幽默以三月兮，深林潜居。时岁忽兮，孤愤遐吟。\n谁知我心？孺子孺子，其可与理分。'},
    {t:'喜迁莺',a:'秦观〔宋代〕',c:'西风落叶。正祖席将收，离歌三头。鹤喜仙还，珠愁主去，立马城头难别。三十六湖春水，二十四同秋月。争羡道，这水如膏泽，月同莹洁。\n殊绝。郊陌上，桑柘阴阴，听得行人说。三木论囚，五花判事，个个待公方决。鸾凤清标重睹，驷马高门须设。挥袂处，望甘棠召伯，教人凄咽。'},
    {t:'喜迁莺',a:'晏殊〔宋代〕',c:'风转蕙，千露催莲。莺语尚绵蛮。尧蓂随月欲团圆。真驭降荷兰。\n褰油幕。调清乐。四海一家同乐。千官心在玉炉香。圣寿祝天长。'},
    {t:'喜迁莺·风转蕙',a:'晏殊〔宋代〕',c:'风转蕙，露催莲，莺语尚绵蛮。尧蓂随月欲团圆，真驭降荷兰。\n褰油幕，调清乐，四海一家同乐。千官心在玉炉香，圣寿祝天长。'},
    {t:'喜迁莺·歌敛黛',a:'晏殊〔宋代〕',c:'歌敛黛，舞萦风，迟日象筵中。分炉珠翠簇繁红，云髻袅珑璁。\n金炉暖，龙香远，共祝尧龄万万。曲终休解画罗衣，留伴彩云飞。'},
    {t:'喜迁莺·花不尽',a:'晏殊〔宋代〕',c:'花不尽，柳无穷。应与我情同。觥船一棹百分空。何处不相逢。\n朱弦悄。知音少。天若有情应老。劝君看取利名场。今古梦茫茫。'},
    {t:'喜迁莺·溧水长寿乡作',a:'周邦彦〔宋代〕',c:'梅雨霁，暑风和。高柳乱蝉多。小园台榭远池波。鱼戏动新荷。\n薄纱厨，轻羽扇。枕冷簟凉深院。此时情绪此时天。无事小神仙。'},
    {t:'喜迁莺·暑风凉月',a:'辛弃疾〔宋代〕',c:'谢赵晋臣敷文赋芙蓉词见寿，数韵为谢。\n暑风凉月。爱亭亭无数，绿衣持节。掩冉如羞，参差似恨，拥出芙蓉花发。步衬潘娘堪恨，貌比六郎谁洁？添白鹭，晚晴时，公子佳人并列。\n休说，搴木末；当日灵均，恨与君王别。心阻媒劳，交疏怨极，恩不甚兮轻绝。千古离骚文字，芳至今犹未歇。都休问，但千杯快饮，露荷翻叶。'},
    {t:'喜迁莺·曙河低',a:'晏殊〔宋代〕',c:'曙河低，斜月淡，帘外早凉天。玉楼清唱倚朱弦，馀韵入疏烟。\n脸霞轻，眉翠重，欲舞钗钿摇动。人人如意祝炉香，为寿百千长。'},
    {t:'喜迁莺·烛飘花',a:'晏殊〔宋代〕',c:'烛飘花，香掩烬，中夜酒初醒。画楼残点两三声，窗外月胧明。\n晓帘垂，惊鹊去，好梦不知何处。南园春色已归来，庭树有寒梅。'},
    {t:'喜迁莺其三',a:'秦观〔宋代〕',c:'花香馥郁。正春色平中，海筹添屋。金马清才，玉麟旧守，帝遣暂临江国。\n冠盖光生南楚，川岳灵钟西蜀。堪羡是，有汪洋万顷，珠玑千斛。\n听祝。愿多寿，多福多男，溥作苍生福。碧柳绯桃，锦袍乌帽，辉映颜朱鬓绿。\n早见鹤楼风采，归掌鸾坡机轴。百岁里，庆团长似，冰轮满足。'},
    {t:'喜太守毕朝散致政',a:'黄庭坚〔宋代〕',c:'膏火煎熬无妄灾，就阴息迹信难哉。\n功名富贵两蜗角，险阻艰难一酒杯。\n百体观来身是幻，万夫争处首先回。\n胸中元有不病者，记得陶潜归去来。'},
    {t:'喜团圆',a:'晏几道〔宋代〕',c:'危楼静锁，窗中远岫，门外垂杨。眠帘不禁春风度，解偷送余香。\n眠思梦想，不如双燕，得到兰房，别来只是，凭高泪眼，感旧离肠。'},
    {t:'喜王起侍郎放牒',a:'张籍〔唐代〕',c:'东风节气近清明，车马争来满禁城。二十八人初上牒，\n百千万里尽传名。谁家不借花园看，在处多将酒器行。\n共贺春司能鉴识，今年定合有公卿。'},
    {t:'喜雪',a:'李商隐〔唐代〕',c:'朔雪自龙沙，呈祥势可嘉。有田素种玉，无树不开花。\n班扇慵裁素，曹衣讵比麻。鹅归逸少宅，鹤迹令威家。\n寂寞门扉掩，依稀履迹斜。人疑游面市，马似困盐车。\n洛水妃虚妒，姑山客漫夸。联辞虽许谢，和曲本惭巴。\n粉署闱全隔，霜台路正赊。此时倾贺酒，相望在京华。'},
    {t:'喜于广陵拜觐家兄奉送发还池州',a:'韦应物〔唐代〕',c:'青青连枝树，苒苒久别离。客游广陵中，俱到若有期。\n俯仰叙存殁，哀肠发酸悲。收情且为欢，累日不知饥。\n夙驾多所迫，复当还归池。长安三千里，岁晏独何为。\n南出登阊门，惊飙左右吹。所别谅非远，要令心不怡。'},
    {t:'喜雨',a:'杨万里〔宋代〕',c:'欲知一雨惬群情，听取溪流动嶂声。\n风乱万畴青锦褥，云摩千嶂翠瑶屏。\n行人隔水遥相语，立鹭摧枝忽自惊。\n岁岁只愁炊与酿，今愁无甑更无瓶。'},
    {t:'喜雨',a:'白居易〔唐代〕',c:'西北油然云势浓，须臾滂沛雨飘空。\n顿疏万物焦枯意，定看秋郊稼穑丰。'},
    {t:'喜雨',a:'孟郊〔唐代〕',c:'朝见一片云，暮成千里雨。凄清湿高枝，散漫沾荒土。'},
    {t:'喜园中茶生',a:'韦应物〔唐代〕',c:'洁性不可污，为饮涤尘烦。\n此物信灵味，本自出山原。\n聊因理郡馀，率尔植荒园。\n喜随众草长，得与幽人言。'},
    {t:'喜昼公寻山回相遇联句一首',a:'皎然〔唐代〕',c:'几年无此会，今日喜相从。——潘述\n水夏仍多病，前书达几封。——皎然\n水华迎暮雨，松吹引疏钟。——皎然\n出谷随初月，寻僧说五峰。——潘述'},
    {t:'喜祖三至留宿',a:'王维〔唐代〕',c:'门前洛阳客，下马拂征衣。不枉故人驾，平生多掩扉。\n行人返深巷，积雪带馀晖。早岁同袍者，高车何处归。'},
    {t:'戏笔',a:'杨万里〔宋代〕',c:'野菊荒苔各铸钱，\n金黄铜绿两争妍；\n天公支予穷诗客，\n只买清愁不买田。'},
    {t:'戏呈孔毅父',a:'黄庭坚〔宋代〕',c:'管城子无食肉相，孔方兄有绝交书。\n文章功用不经世，何异丝窠缀露珠。\n校书著作频诏除，犹能上车问何如。\n忽忆僧床同野饭，梦随秋雁到东湖。'},
    {t:'戏呈吴冯',a:'皎然〔唐代〕',c:'世人不知心是道，只言道在他方妙。\n还如瞽者望长安，长安在西向东笑。'},
    {t:'戏答荆州王充道烹茶四首',a:'黄庭坚〔宋代〕',c:'香从灵坚垄上发，味自白石源中生。\n为公唤觉荆州梦，可待南柯一梦成。'},
    {t:'戏答龙泉余尉问禅二小诗',a:'黄庭坚〔宋代〕',c:'翻头作尾掉枯藤，腊月花开更造冰。\n何似清歌倚桃李，一炉沈水醉红灯。'},
    {t:'戏马台',a:'文天祥〔宋代〕',c:'九月初九日，客游戏马台。\n黄花弄朝露，古人化飞埃。\n今人哀后人，后人复今哀。\n世事那可及，泪落茱萸杯。'},
    {t:'戏题·一作戏赠主人',a:'孟浩然〔唐代〕',c:'客醉眠未起，主人呼解酲。已言鸡黍熟，复道瓮头清。'},
    {t:'戏题春意',a:'张九龄〔唐代〕',c:'一作江南守，江林三四春。相鸣不及鸟，相乐喜关人。\n日守朱丝直，年催华发新。淮阳只有卧，持此度芳辰。'},
    {t:'戏题二首',a:'皎然〔唐代〕',c:'看饮逢歌日屡曛，我身何似系浮云。\n时人不解野僧意，归去溪头作鸟群。\n喧喧共在是非间，终日谁知我自闲。\n偶客狂歌何所为，欲于人事强相关。'},
    {t:'戏题关门',a:'岑参〔唐代〕',c:'来亦一布衣，去亦一布衣。羞见关城吏，还从旧路归。'},
    {t:'戏题阶前芍药',a:'柳宗元〔唐代〕',c:'凡卉与时谢，妍华丽兹晨。\n欹红醉浓露，窈窕留馀春。\n孤赏白日暮，暄风动摇频。\n夜窗蔼芳气，幽卧知相亲。\n愿致溱洧赠，悠悠南国人。'},
    {t:'戏题牡丹',a:'韩愈〔唐代〕',c:'幸自同开俱阴隐，何须相倚斗轻盈。\n陵晨并作新妆面，对客偏含不语情。\n双燕无机还拂掠，游蜂多思正经营。\n长年是事皆抛尽，今日栏边暂眼明。'},
    {t:'戏题盘石',a:'王维〔唐代〕',c:'可怜盘石临泉水，复有垂杨拂酒杯。\n若道春风不解意，何因吹送落花来。'},
    {t:'戏题石门长老东轩',a:'柳宗元〔唐代〕',c:'石门长老身如梦，旃檀成林手所种。\n坐来念念非昔人，万遍莲花为谁用？\n如今七十自忘机，贪爱都忘筋力微。\n莫向东轩春野望，花开日出雉皆飞。'},
    {t:'戏题松树',a:'皎然〔唐代〕',c:'为爱松声听不足，每逢松树遂忘还。\n翛然此外更何事，笑向闲云似我闲。'},
    {t:'戏题王宰画山水图歌',a:'杜甫〔唐代〕',c:'十日画一水，五日画一石。\n能事不受相促迫，王宰始肯留真迹。\n壮哉昆仑方壶图，挂君高堂之素壁。\n巴陵洞庭日本东，赤岸水与银河通，中有云气随飞龙。\n舟人渔子入浦溆，山木尽亚洪涛风。\n尤工远势古莫比，咫尺应须论万里。\n焉得并州快剪刀，剪取吴淞半江水。'},
    {t:'戏题辋川别业',a:'王维〔唐代〕',c:'柳条拂地不须折，松树披云从更长。\n藤花欲暗藏猱子，柏叶初齐养麝香。'},
    {t:'戏为六绝句·其二',a:'杜甫〔唐代〕',c:'王杨卢骆当时体，轻薄为文哂未休。\n尔曹身与名俱灭，不废江河万古流。'},
    {t:'戏为韦偃双松图歌',a:'杜甫〔唐代〕',c:'天下几人画古松，毕宏已老韦偃少。\n绝笔长风起纤末，满堂动色嗟神妙。\n两株惨裂苔藓皮，屈铁交错回高枝。\n白摧朽骨龙虎死，黑入太阴雷雨垂。\n松根胡僧憩寂寞，庞眉皓首无住著。\n偏袒右肩露双脚，叶里松子僧前落。\n韦侯韦侯数相见，我有一匹好东绢。\n重之不减锦绣段，已令拂拭光凌乱。\n请公放笔为直干。'},
    {t:'戏问花门酒家翁',a:'岑参〔唐代〕',c:'老人七十仍沽酒，千壶百瓮花门口。\n道傍榆荚巧似钱，摘来沽酒君肯否。'},
    {t:'戏赠崔千牛',a:'刘禹锡〔唐代〕',c:'学道深山许老人，留名万代不关身。\n劝君多买长安酒，南陌东城占取春。'},
    {t:'戏赠乐天、复言·此后三篇同韵',a:'元稹〔唐代〕',c:'乐事难逢岁易徂，白头光景莫令孤。弄涛船更曾观否，\n望市楼还有会无。眼力少将寻案牍，心情且强掷枭卢。\n孙园虎寺随宜看，不必遥遥羡镜湖。'},
    {t:'戏赠米元章二首',a:'黄庭坚〔宋代〕',c:'万里风帆水著天，麝煤鼠尾过年年。\n沧江静夜虹贯月，定是米家书画船。'},
    {t:'戏赠吴冯',a:'皎然〔唐代〕',c:'予读古人书，遂识古人面。不是识古人，邪正心自见。\n贵义轻财求俗誉，一钱与人便骄倨。昨朝为火今为冰，\n此道非君独抚膺。'},
    {t:'戏赠郑溧阳',a:'李白〔唐代〕',c:'陶令日日醉，不知五柳春。\n素琴本无弦，漉酒用葛巾。\n清风北窗下，自谓羲皇人。\n何时到栗里，一见平生亲。'},
    {t:'戏作',a:'皎然〔唐代〕',c:'乞我百万金，封我异姓王。不如独悟时，大笑放清狂。'},
    {t:'戏作示内',a:'晏几道〔宋代〕',c:'生计唯兹椀，般擎岂惮劳。造虽从假合，成不自埏陶。\n阮杓非同调，颜瓢庶共操。朝盛负余米，暮贮藉残糟。\n幸免墦间乞，终甘泽畔逃。挑宜筇作杖，捧称葛为袍。\n傥受桑间饷，何堪井上螬。绰然真自许，嘑尔未应饕。\n世久轻原宪，人方逐子敖。愿君同此器，珍重到霜毛。'},
    {t:'细雨',a:'温庭筠〔唐代〕',c:'凭轩望秋雨，凉入暑衣清。极目鸟频没，片时云复轻。\n沼萍开更敛，山叶动还鸣。楚客秋江上，萧萧故国情。'},
    {t:'细雨',a:'李商隐〔唐代〕',c:'萧洒傍回汀，依微过短亭。气凉先动竹，点细未开萍。\n稍促高高燕，微疏的的萤。故园烟草色，仍近五门青。'},
    {t:'匣剑',a:'范仲淹〔宋代〕',c:'灵剑经年匣，决云谁为高。\n报分别有道，何认问吹毛。'},
    {t:'侠客行',a:'李白〔唐代〕',c:'赵客缦胡缨，吴钩霜雪明。\n银鞍照白马，飒沓如流星。\n十步杀一人，千里不留行。\n事了拂衣去，深藏身与名。\n闲过信陵饮，脱剑膝前横。\n将炙啖朱亥，持觞劝侯嬴。\n三杯吐然诺，五岳倒为轻。\n眼花耳热后，意气素霓生。\n救赵挥金槌，邯郸先震惊。\n千秋二壮士，烜赫大梁城。\n纵死侠骨香，不惭世上英。\n谁能书阁下，白首太玄经。'},
    {t:'侠客行',a:'温庭筠〔唐代〕',c:'欲出鸿都门，阴云蔽城阙。\n宝剑黯如水，微红湿馀血。\n白马夜频惊，三更霸陵雪。'},
    {t:'遐方怨·花半拆',a:'温庭筠〔唐代〕',c:'花半拆，雨初晴。未卷珠帘，梦残惆怅闻晓莺。宿妆眉浅粉山横。约鬟鸳镜里，绣罗轻。'},
    {t:'遐方怨·凭绣槛',a:'温庭筠〔唐代〕',c:'凭绣槛，解罗帷。未得君书，断肠潇湘春雁飞。不知征马几时归？海棠花谢也，雨霏霏。'},
    {t:'遐方怨·欹角枕',a:'纳兰性德〔清代〕',c:'欹角枕，掩红窗。梦到江南，伊家博山沈水香。湔裙归晚坐思量。轻烟笼翠黛，月茫茫。'},
    {t:'遐水谣',a:'温庭筠〔唐代〕',c:'天兵九月渡遐水，马踏沙鸣惊箭起。杀气空高万里情，\n塞寒如箭伤眸子。狼烟堡上霜漫漫，枯色号风天地干。\n犀带鼠裘无暖色，清光炯冷黄金鞍。虏尘如雾昏亭障，\n陇首年年汉飞将。麟阁无名期未归，楼中思妇徒相望。'},
    {t:'下第东归留别长安知己',a:'孟郊〔唐代〕',c:'共照日月影，独为愁思人。\n岂知鶗鴂鸣，瑶草不得春。\n一片两片云，千里万里身。\n云归嵩之阳，身寄江之滨。\n弃置复何道，楚情吟白蘋。'},
    {t:'下第东南行',a:'孟郊〔唐代〕',c:'越风东南清，楚日潇湘明。试逐伯鸾去，还作灵均行。\n江蓠伴我泣，海月投人惊。失意容貌改，畏途性命轻。\n时闻丧侣猿，一叫千愁并。'},
    {t:'下赣石',a:'孟浩然〔唐代〕',c:'赣石三百里，沿洄千嶂间。沸声沸活活，洊势亦潺潺。\n跳沫鱼龙沸，垂藤猿狖攀。榜人苦奔峭，而我忘险艰。\n放溜情弥惬，登舻目自闲。暝帆何处宿，遥指落星湾。'},
    {t:'下陵阳沿高溪三门六剌滩',a:'李白〔唐代〕',c:'三门横峻滩，六剌走波澜。\n石惊虎伏起，水状龙萦盘。\n何惭七里濑，使我欲垂竿。'},
    {t:'下帷斋',a:'周邦彦〔宋代〕',c:'官事如拔毛，小稀还复稠。\n一鼠未易尽，況欲秃九牛。\n唯应理签轴，偷暇寻孔周。\n维南有颓构，畴昔宾射侯。\n扶倾与丹雘，外好中实不。\n弦歌废决拾，休王良有田。\n书生本不武，谁言负薪忧。\n古云不执弓，防患术已媮。\n诗书主六艺，中有捍敌谋。\n至胜不刃血，吾将执其柔。\n当有中的士，为辨劣与优。'},
    {t:'下寻阳城泛彭蠡寄黄判官',a:'李白〔唐代〕',c:'浪动灌婴井，寻阳江上风。\n开帆雨天镜，直向彭湖东。\n落景转疏雨，晴云散远空。\n名山发佳兴，清赏亦何穷？\n石镜挂遥月，香炉灭彩虹。\n相思俱对此，举目与君同。'},
    {t:'下终南山过斛斯山人宿置酒',a:'李白〔唐代〕',c:'暮从碧山下，山月随人归。\n却顾所来径，苍苍横翠微。\n相携及田家，童稚开荆扉。\n绿竹入幽径，青萝拂行衣。\n欢言得所憩，美酒聊共挥。\n长歌吟松风，曲尽河星稀。\n我醉君复乐，陶然共忘机。'},
    {t:'夏冰歌',a:'韦应物〔唐代〕',c:'出自玄泉杳杳之深井，汲在朱明赫赫之炎辰。\n九天含露未销铄，阊阖初开赐贵人。\n碎如坠琼方截璐，粉壁生寒象筵布。\n玉壶纨扇亦玲珑，座有丽人色俱素。\n咫尺炎凉变四时，出门焦灼君讵知。\n肥羊甘醴心闷闷，饮此莹然何所思。\n当念阑干凿者苦，腊月深井汗如雨。'},
    {t:'夏初醴泉南楼送太康颜少府',a:'岑参〔唐代〕',c:'何地堪相饯，南楼出万家。可怜高处送，远见故人车。\n野果新成子，庭槐欲作花。爱君兄弟好，书向颍中夸。'},
    {t:'夏初雨后寻愚溪',a:'柳宗元〔唐代〕',c:'悠悠雨初霁，独绕清溪曲。\n引杖试荒泉，解带围新竹。\n沉吟亦何事，寂寞固所欲。\n幸此息营营，啸歌静炎燠。'},
    {t:'夏花明',a:'韦应物〔唐代〕',c:'夏条绿已密，朱萼缀明鲜。\n炎炎日正午，灼灼火俱燃。\n翻风适自乱，照水复成妍。\n归视窗间字，荧煌满眼前。'},
    {t:'夏景园庐',a:'韦应物〔唐代〕',c:'群木昼阴静，北窗凉气多。闲居逾时节，夏云已嵯峨。\n搴叶爱繁绿，缘涧弄惊波。岂为论夙志，对此青山阿。'},
    {t:'夏日',a:'陆游〔宋代〕',c:'燕子生雏梅子黄，断云残雨过林塘。\n孤舟正作笭箵梦，九陌难随褦襶忙。\n团扇兴来闲弄笔，寒泉漱罢独焚香。\n太平处处熏风好，不独宫中爱日长。'},
    {t:'夏日',a:'韦应物〔唐代〕',c:'已谓心苦伤，如何日方永。\n无人不昼寝，独坐山中静。\n悟澹将遣虑，学空庶遗境。\n积俗易为侵，愁来复难整。'},
    {t:'夏日辨玉法师茅斋',a:'孟浩然〔唐代〕',c:'夏日茅斋里，无风坐亦凉。竹林深笋穊，藤架引梢长。\n燕觅巢窠处，蜂来造蜜房。物华皆可玩，花蕊四时芳。'},
    {t:'夏日登观农楼和崔使君',a:'皎然〔唐代〕',c:'片雨拂檐楹，烦襟四坐清。霏微过麦陇，萧散傍莎城。\n静爱和花落，幽闻入竹声。朝观趣无限，高咏寄深情。'},
    {t:'夏日二首其二',a:'朱熹〔宋代〕',c:'季夏园木暗，窗户贮清阴。长风一掩苒，众绿何萧椮。\n玩此消永昼，泠然涤幽襟。俯仰无所为，聊复得此心。'},
    {t:'夏日奉陪陆使君长源公堂集',a:'皎然〔唐代〕',c:'府中自清远，六月高梧间。寥亮泛雅瑟，逍遥扣玄关。\n岭云与人静，庭鹤随公闲。动息谅兼遂，兹情即东山。'},
    {t:'夏日奉使南海在道中作',a:'张九龄〔唐代〕',c:'缅然万里路，赫曦三伏时。\n飞走逃深林，流烁恐生疵。\n行李岂无苦，而我方自怡。\n肃事诚在公，拜庆遂及私。\n展力惭浅效，衔恩感深慈。\n且欲汤火蹈，况无鬼神欺。\n朝发高山阿，夕济长江湄。\n秋瘴宁我毒，夏水胡不夷。\n信知道存者，但问心所之。\n吕梁有出入，乃觉非虚词。'},
    {t:'夏日浮舟过陈大水亭',a:'孟浩然〔唐代〕',c:'水亭凉气多，闲棹晚来过。\n涧影见松竹，潭香闻芰荷。\n野童扶醉舞，山鸟助酣歌。\n幽赏未云遍，烟光奈夕何。'},
    {t:'夏日晖上人房别李参军崇嗣',a:'陈子昂〔唐代〕',c:'四十九变化，一十三死生。翕忽玄黄里，驱驰风雨情。\n是非纷妄作，宠辱坐相惊。至人独幽鉴，窈窕随昏明。\n咫尺山河道，轩窗日月庭。别离焉足问，悲乐固能并。\n我辈何为尔，栖皇犹未平。金台可攀陟，宝界绝将迎。\n户牖观天地，阶基上杳冥。自超三界乐，安知万里征。\n中国要荒内，人寰宇宙荣。弦望如朝夕，宁嗟蜀道行。'},
    {t:'夏日集李司直纵溪斋',a:'皎然〔唐代〕',c:'修景属良会，远飙生烦襟。泄云务净绿，众木积芳阴。\n疏涤府中务，迢遥湖上心。习闲得招我，赏夜宜泛琴。\n山近资性静，月来寄情深。澹然若事外，岂藉隳华簪。'},
    {t:'夏日集裴录事北亭避暑',a:'皎然〔唐代〕',c:'前林夏雨歇，为我生凉风。一室烦暑外，众山清景中。\n忘归亲野水，适性许云鸿。萧散都曹吏，还将静者同。'},
    {t:'夏日绝句',a:'杨万里〔宋代〕',c:'不但春妍夏亦佳，随缘花草是生涯。\n鹿葱解插纤长柄，金凤仍开最小花。'},
    {t:'夏日李公见访',a:'杜甫〔唐代〕',c:'远林暑气薄，公子过我游。\n贫居类村坞，僻近城南楼。\n旁舍颇淳朴，所须亦易求。\n隔屋唤西家，借问有酒否？\n墙头过浊醪，展席俯长流。\n清风左右至，客意已惊秋。\n巢多众鸟喧，叶密鸣蝉稠。\n苦遭此物聒，孰谓吾庐幽？\n水花晚色净，庶足充淹留。\n预恐樽中尽，更起为君谋。'},
    {t:'夏日六言',a:'陆游〔宋代〕',c:'溪涨清风拂面，月落繁星满天。\n数只船横浦口，一声笛起山前。'},
    {t:'夏日梦伯兄寄江南',a:'黄庭坚〔宋代〕',c:'故园相见略雍容，睡起南窗日射红。\n诗酒一年谈笑隔，江山千里梦魂通。\n河天月晕鱼分子，槲叶风微鹿养茸。\n几度白砂青影里，审听嘶马自搘筇。'},
    {t:'夏日南亭怀辛大',a:'孟浩然〔唐代〕',c:'山光忽西落，池月渐东上。\n散发气夕凉，开轩卧闲敞。\n荷风送香气，竹露滴清响。\n欲取鸣琴弹，恨无知音赏。\n感此怀故人，中宵劳梦想。'},
    {t:'夏日山中',a:'李白〔唐代〕',c:'懒摇白羽扇，裸袒青林中。\n脱巾挂石壁，露顶洒松风。'},
    {t:'夏日题桐庐杨明府纳凉山斋',a:'皎然〔唐代〕',c:'陶家无炎暑，自有林中峰。席上落山影，桐梢回水容。\n放怀凉风至，缓步清阴重。何事亲堆案，犹多高世踪。'},
    {t:'夏日闲居',a:'张籍〔唐代〕',c:'多病逢迎少，闲居又一年。\n药看辰日合，茶过卯时煎。\n草长晴来地，虫飞晚后天。\n此时幽梦远，不觉到山边。'},
    {t:'夏日谒智远禅师',a:'孟郊〔唐代〕',c:'吾师当几祖，说法云无空。禅心三界外，宴坐天地中。\n院静鬼神去，身与草木同。因知护王国，满钵盛毒龙。\n抖擞尘埃衣，谒师见真宗。何必千万劫，瞬息去樊笼。\n盛夏火为日，一堂十月风。不得为弟子，名姓挂儒宫。'},
    {t:'夏日游晖上人房',a:'陈子昂〔唐代〕',c:'山水开精舍，琴歌列梵筵。\n人疑白楼赏，地似竹林禅。\n对户池光乱，交轩岩翠连。\n色空今已寂，乘月弄澄泉。'},
    {t:'夏夜苦热登西楼',a:'柳宗元〔唐代〕',c:'苦热中夜起，登楼独褰衣。\n山泽凝暑气，星汉湛光辉。\n火晶燥露滋，野静停风威。\n探汤汲阴井，炀灶开重扉。\n凭阑久彷徨，流汗不可挥。\n莫辩亭毒意，仰诉璿与玑。\n谅非姑射子，静胜安能希。'},
    {t:'夏夜叹',a:'杜甫〔唐代〕',c:'永日不可暮，炎蒸毒我肠。\n安得万里风，飘飖吹我裳。\n昊天出华月，茂林延疏光。\n仲夏苦夜短，开轩纳微凉。\n虚明见纤毫，羽虫亦飞扬。\n物情无巨细，自适固其常。\n念彼荷戈士，穷年守边疆。\n何由一洗濯，执热互相望。\n竟夕击刁斗，喧声连万方。\n青紫虽被体，不如早还乡。\n北城悲笳发，鹳鹤号且翔。\n况复烦促倦，激烈思时康。'},
    {t:'夏夜玩月',a:'杨万里〔宋代〕',c:'仰头月在天，照我影在地。\n我行影亦行，我止影亦止。\n不知我与影，为一定为二。\n月能写我影，自写却何似。\n偶然步溪旁，月却在溪里。\n上下两轮月，若个是真底。\n为复水是天，为复天是水。'},
    {t:'夏夜忆卢嵩',a:'韦应物〔唐代〕',c:'霭霭高馆暮，开轩涤烦襟。不知夜雨来，潇洒在幽林。\n炎月得凉夜，芳樽谁与斟。故人南北居，累月间徽音。\n人生无闲日，欢会当在今。反侧候天旦，层城苦沉沉。'},
    {t:'夏夜月下独酌二首',a:'杨万里〔宋代〕',c:'月忿云遮却，云遭月辊翻。\n斩新灯世界，特地玉乾坤。\n兔舞催诗句，蟾醒笑醉魂。\n姮家且莫睡，照管失金盆。'},
    {t:'夏夜追凉',a:'杨万里〔宋代〕',c:'夜热依然午热同，开门小立月明中。\n竹深树密虫鸣处，时有微凉不是风。'},
    {t:'夏月花萼楼酺宴应制',a:'王昌龄〔唐代〕',c:'土德三元正，尧心万国同。汾阴备冬礼，长乐应和风。\n赐庆垂天泽，流欢旧渚宫。楼台生海上，箫鼓出天中。\n雾晓筵初接，宵长曲未终。雨随青幕合，月照舞罗空。\n玉陛分朝列，文章发圣聪。愚臣忝书赋，歌咏颂丝桐。'},
    {t:'夏月频雨',a:'杨万里〔宋代〕',c:'一番暑雨一番凉，真个令人爱日长。\n隔水风来知有意，为吹十里稻花香。'},
    {t:'夏云峰·宴堂深',a:'柳永〔宋代〕',c:'宴堂深。轩楹雨，轻压暑气低沈。花洞彩舟泛斝，坐绕清浔。楚台风快，湘簟冷、永日披襟。坐久觉、疏弦脆管，时换新音。\n越娥兰态蕙心。逞妖艳、昵欢邀宠难禁。筵上笑歌间发，舄履交侵。醉乡归处，须尽兴、满酌高吟。向此免、名缰利锁，虚费光阴。'},
    {t:'夏至避暑北池',a:'韦应物〔唐代〕',c:'昼晷已云极，宵漏自此长。\n未及暇政教，所忧变炎凉。\n公门日多暇，是月农稍忙。\n高居念田里，苦方安可当。\n亭午息群物，独游爱方塘。\n门闭阴寂寂，城高树苍苍。\n绿筠尚含粉，圆荷始散芳。\n于焉洒烦抱，可以对华觞。'},
    {t:'夏至后初暑登连天观',a:'杨万里〔宋代〕',c:'登台长早下台迟，移遍胡床无处移。\n不是清凉罢挥扇，自缘手倦歇些时。'},
    {t:'夏至雨霁与陈履常暮行溪上二首',a:'杨万里〔宋代〕',c:'西山已暗隔金钲，犹照东山一抹明。\n片子时间弄山色，乍黄乍紫忽全青。'},
    {t:'夏昼偶作',a:'柳宗元〔唐代〕',c:'南州溽暑醉如酒，隐几熟眠开北牖。\n日午独觉无馀声，山童隔竹敲茶臼。'},
    {t:'仙女台·得仙字',a:'皎然〔唐代〕',c:'寂寂旧桑田，谁家女得仙。应无鸡犬在，空有子孙传。\n古木花犹发，荒台路未迁。暮来云一片，疑是欲归年。'},
    {t:'仙人',a:'李贺〔唐代〕',c:'弹琴石壁上，翻翻一仙人。\n手持白鸾尾，夜扫南山云。\n鹿饮寒涧下，鱼归清海滨。\n当时汉武帝，书报桃花春。'},
    {t:'仙杏山',a:'周邦彦〔宋代〕',c:'仙人药光明夜烛，离杏碧山如离玉。\n春风裂石凤收花，赤颊离离照山谷。\n卿云承日作阴润，猛贡守山防采斸。\n高真筐篚入时贡。拜望通明荐新熟。\n珠旒颔首一破颜，气压蟠桃羞若木。\n自从移植近星榆，山水无光灵鬼器。\n长松枯倒流液尽，权赖牵藤多朴樕。\n我思百年访灵异，羽褐虽存言语俗。\n本非民民土宰官身，欲断人间烟火谷。\n行寻幽洞觅丹砂，傥见臞仙骑白鹿。\n便应执箒洗仙坛，不用纤纤扫尘竹。'},
    {t:'先主武侯庙',a:'岑参〔唐代〕',c:'先主与武侯，相逢云雷际。感通君臣分，义激鱼水契。\n遗庙空萧然，英灵贯千岁。'},
    {t:'闲居',a:'张籍〔唐代〕',c:'东城南陌尘，紫幰与朱轮。\n尽说无多事，能闲有几人。\n唯教推甲子，不信守庚申。\n谁见衡门里，终朝自在贫。'},
    {t:'闲居',a:'高适〔唐代〕',c:'柳色惊心事，春风厌索居。\n方知一杯酒，犹胜百家书。'},
    {t:'闲居初夏午睡起·其二',a:'杨万里〔宋代〕',c:'松阴一架半弓苔，偶欲看书又懒开。\n戏掬清泉洒蕉叶，儿童误认雨声来。'},
    {t:'闲居初夏午睡起·其一',a:'杨万里〔宋代〕',c:'梅子留酸软齿牙，芭蕉分绿与窗纱。\n日长睡起无情思，闲看儿童捉柳花。'},
    {t:'闲居寄端及重阳',a:'韦应物〔唐代〕',c:'山明野寺曙钟微，雪满幽林人迹稀。\n闲居寥落生高兴，无事风尘独不归。'},
    {t:'闲居寄诸弟',a:'韦应物〔唐代〕',c:'秋草生庭白露时，故园诸弟益相思。\n尽日高斋无一事，芭蕉叶上独题诗。'},
    {t:'闲居遣兴',a:'王安石〔宋代〕',c:'惨惨秋阴绿树昏，荒城高处闭山门。\n愁消日月忘身世，静对溪山忆酒樽。\n南去干戈何日解，东来馹骑此时奔。\n谁将天下安危事，一把诗书子细论。'},
    {t:'闲居自述',a:'陆游〔宋代〕',c:'自许山翁懒是真，纷纷外物岂言身。\n花如解语还多事，石不能言最可人。\n净扫明窗凭素几，闲穿密竹岸乌巾。\n残年自有青天管，便是无锥也未贫。'},
    {t:'闲赏篇·雪',a:'佚名〔元代〕',c:'天公翦水，宇宙飘花，品之，有四美焉：落地无声，静也；沾衣不染，洁也；高下平均，匀也；洞窗掩映，明也。宜长松修竹，老梅片石；怪石崚嶒，深林窈窕；寒江远浦，断岸小桥；古刹层峦，疏篱幽径；老叟披簑垂钓，骚人跨蹇寻诗；小酌清谈，高楼长啸；船头茶灶飘烟，座上黛眉把盏；老僧对坐，韵士闲评；披鹤氅，纵步园林，御貂裘，登临山水。如此景况，何必峨嵋千尺？'},
    {t:'闲适',a:'陆游〔宋代〕',c:'饮酒不至狂，对客不至疲。\n读书以自娱，不强所不知。\n一窗袖手坐，往往昼漏移。\n初非能养生，简事颇似之。\n四时俱可喜，最好新秋时。\n柴门傍野水，邻叟闲相期。'},
    {t:'闲题',a:'杜牧〔唐代〕',c:'男儿所在即为家，百镒黄金一朵花。\n借问春风何处好，绿杨深巷马头斜。'},
    {t:'闲园怀苏子',a:'孟浩然〔唐代〕',c:'林园虽少事，幽独自多违。向夕开帘坐，庭阴落景微。\n鸟过烟树宿，萤傍水轩飞。感念同怀子，京华去不归。'},
    {t:'闲斋对雨',a:'韦应物〔唐代〕',c:'幽独自盈抱，阴淡亦连朝。空斋对高树，疏雨共萧条。\n巢燕翻泥湿，蕙花依砌消。端居念往事，倏忽苦惊飙。'},
    {t:'闲坐忆乐天以诗问酒熟未',a:'刘禹锡〔唐代〕',c:'案头开缥帙，肘后检青囊。唯有达生理，应无治老方。\n减书存眼力，省事养心王。君酒何时熟，相携入醉乡。'},
    {t:'弦歌行',a:'孟郊〔唐代〕',c:'驱傩击鼓吹长笛，瘦鬼染面惟齿白。暗中崒崒拽茅鞭，\n倮足朱裈行戚戚。相顾笑声冲庭燎，桃弧射矢时独叫。'},
    {t:'咸阳',a:'李商隐〔唐代〕',c:'咸阳宫阙郁嵯峨，六国楼台艳绮罗。\n自是当时天帝醉，不关秦地有山河。'},
    {t:'咸阳宫人为咸阳王禧歌',a:'佚名〔隋代〕',c:'可怜咸阳王。奈何作事误。金床玉几不能眠。夜踏霜与露。\n洛水湛湛弥岸长。行人那得渡。'},
    {t:'咸阳值雨',a:'温庭筠〔唐代〕',c:'咸阳桥上雨如悬，万点空濛隔钓船。\n还似洞庭春水色，晓云将入岳阳天。'},
    {t:'县内闲居赠温公',a:'韦应物〔唐代〕',c:'满郭春风岚已昏，鸦栖散吏掩重门。\n虽居世网常清净，夜对高僧无一言。'},
    {t:'县斋',a:'韦应物〔唐代〕',c:'仲春时景好，草木渐舒荣。公门且无事，微雨园林清。\n决决水泉动，忻忻众鸟鸣。闲斋始延瞩，东作兴庶氓。\n即事玩文墨，抱冲披道经。于焉日淡泊，徒使芳尊盈。'},
    {t:'县斋读书·在阳山作',a:'韩愈〔唐代〕',c:'出宰山水县，读书松桂林。萧条捐末事，邂逅得初心。\n哀狖醒俗耳，清泉洁尘襟。诗成有共赋，酒熟无孤斟。\n青竹时默钓，白云日幽寻。南方本多毒，北客恒惧侵。\n谪谴甘自守，滞留愧难任。投章类缟带，伫答逾兼金。'},
    {t:'岘山怀古',a:'陈子昂〔唐代〕',c:'秣马临荒甸，登高览旧都。\n犹悲堕泪碣，尚想卧龙图。\n城邑遥分楚，山川半入吴。\n丘陵徒自出，贤圣几凋枯！\n野树苍烟断，津楼晚气孤。\n谁知万里客，怀古正踌蹰。'},
    {t:'岘山怀古',a:'李白〔唐代〕',c:'访古登岘首，凭高眺襄中。\n天清远峰出，水落寒沙空。\n弄珠见游女，醉酒怀山公。\n感叹发秋兴，长松鸣夜风。'},
    {t:'岘山饯房琯、崔宗之',a:'孟浩然〔唐代〕',c:'贵贱平生隔，轩车是日来。青阳一觏止，云路豁然开。\n祖道衣冠列，分亭驿骑催。方期九日聚，还待二星回。'},
    {t:'岘山送萧员外之荆州',a:'孟浩然〔唐代〕',c:'岘山江岸曲，郢水郭门前。自古照临处，非今独黯然。\n亭楼明落照，井邑秀通川。涧竹生幽兴，林风入管弦。\n再飞鹏激水，一举鹤冲天。伫立三荆使，看君驷马旋。'},
    {t:'岘山送张去非游巴东',a:'孟浩然〔唐代〕',c:'一题作岘山送朱大\n岘山南郭外，送别每登临。\n沙岸江村近，松门山寺深。\n一言余有赠，三峡尔将寻。\n祖席宜城酒，征途云梦林。\n蹉跎游子意，眷恋故人心。\n去矣勿淹滞，巴东猿夜吟。'},
    {t:'岘潭',a:'孟浩然〔唐代〕',c:'石潭傍隈隩，沙岸晓夤缘。试垂竹竿钓，果得槎头鳊。\n美人骋金错，纤手脍红鲜。因谢陆内史，莼羹何足传。'},
    {t:'岘潭(山)作',a:'孟浩然〔唐代〕',c:'石潭傍隈隩，沙榜晓夤缘。\n试垂竹竿钓，果得查头鳊。\n美人骋金错，纤手脍红鲜。\n因谢陆内史，莼羹何足传。'},
    {t:'羡醉',a:'元稹〔唐代〕',c:'绮陌高楼竞醉眠，共期憔悴不相怜。\n也应自有寻春日，虚度而今正少年。'},
    {t:'献百花洲图上陈州晏相公',a:'范仲淹〔宋代〕',c:'穰下胜游少，此洲聊入诗。\n百花争窈窕，一水自涟漪。\n洁白怜翘鹭，优游羡戏龟。\n阑干红屈曲，亭宇碧参差。\n倒影澄波底，横烟落照时。\n月明鱼竞跃，春静柳闲垂。\n万竹排霜杖，千荷卷翠旗。\n菊分潭上近，梅比汉南迟。\n岸鹊依人喜，汀鸥不我疑。\n彩丝穿石节，罗襪踏青期。\n素发频来醉，沧浪减去思。\n步随芳草远，歌逐画船移。\n绘写求真赏，缄藏献己知。\n相君那肯爱，家有凤皇池。'},
    {t:'献从兄',a:'张籍〔唐代〕',c:'悠悠旱天云，不远如飞尘。贤达失其所，沉飘同众人。\n擢秀登王畿，出为良使宾。名高满朝野，幼贱谁不闻。\n一朝遇谗邪，流窜八九春。诏书近迁移，组绶未及身。\n冬井无寒冰，玉润难为焚。虚怀日迢遥，荣辱常保纯。\n我念出游时，勿吟康乐文。愿言灵溪期，聊欲相依因。'},
    {t:'献汉南樊尚书',a:'孟郊〔唐代〕',c:'天下昔崩乱，大君识贤臣。众木尽摇落，始见竹色真。\n兵势走山岳，阳光潜埃尘。心开玄女符，面缚清波人。\n异俗既从化，浇风亦归淳。自公理斯郡，寒谷皆变春。\n旗影卷赤电，剑锋匣青鳞。如何嵩高气，作镇楚水滨。\n云镜忽开霁，孤光射无垠。乃知寻常鉴，照影不照神。'},
    {t:'献始兴公·时拜右拾遗',a:'王维〔唐代〕',c:'宁栖野树林，宁饮涧水流。\n不用坐粱肉，崎岖见王侯。\n鄙哉匹夫节，布褐将白头。\n任智诚则短，守仁固其优。\n侧闻大君子，安问党与雠。\n所不卖公器，动为苍生谋。\n贱子跪自陈，可为帐下不。\n感激有公议，曲私非所求。'},
    {t:'献襄阳于大夫',a:'孟郊〔唐代〕',c:'襄阳青山郭，汉江白铜堤。谢公领兹郡，山水无尘泥。\n铁马万霜雪，绛旗千虹霓。风漪参差泛，石板重叠跻。\n旧泪不复堕，新欢居然齐。还耕竟原野，归老相扶携。\n物色增暧暧，寒芳更萋萋。渊清有遐略，高躅无近蹊。\n即此富苍翠，自然引翔栖。曩游常抱忆，夙好今尚暌。\n愿言从逸辔，暇日凌清溪。'},
    {t:'霰',a:'杨万里〔宋代〕',c:'雪花遣霰作前锋，势破张皇欲暗空。\n筛瓦巧寻疏处漏，跳阶误到暖边融。\n寒声带雨山难白，冷气侵人火失红。\n方讶一冬暄较甚，今宵敢叹卧如弓。'},
    {t:'芗林五十咏·文杏坞',a:'杨万里〔宋代〕',c:'道白非真白，言红不若红。\n请君红白外，别眼看天工。'},
    {t:'芗林五十咏·竹斋',a:'杨万里〔宋代〕',c:'凛凛冰霜节，修修玉雪身。\n便无文与可，不有月傅神。'},
    {t:'相逢行',a:'佚名〔两汉〕',c:'相逢狭路间，道隘不容车。\n不知知年少？夹毂问君家。\n君家诚易知，易知复难忘；\n黄金为君门，白郸为君堂。\n堂上置樽酒，作使邯郸倡。\n中庭生桂树，华灯知煌煌。\n兄弟两三人，中子为侍郎；\n五日一来归，道上自生光；\n黄金络马头，观者盈道傍。\n入门时左顾，但见双鸳鸯；\n鸳鸯七十二，罗列自成行。\n音声知噰噰，鹤鸣东西厢。\n大妇织绮罗，中妇织流黄；\n小妇无所为，挟瑟上高堂：\n“丈人且安坐，调丝方未央。”'},
    {t:'相和歌辞·阿娇怨',a:'刘禹锡〔唐代〕',c:'望见葳蕤举翠华，试开金屋扫庭花。\n须臾宫女传来信，云幸平阳公主家。'},
    {t:'相和歌辞·安乐宫',a:'李贺〔唐代〕',c:'深井桐乌起，尚复牵清水。\n未盥邵陵瓜，瓶中弄长翠。\n新城安乐宫，宫如凤凰翅。\n歌回蜡板鸣，左倌提壶使。\n绿繁悲水曲，茱萸别秋子。'},
    {t:'相和歌辞·白头吟',a:'张籍〔唐代〕',c:'请君膝上琴，弹我白头吟。忆昔君前娇笑语，\n两情宛转如萦素。宫中为我起高楼，更开华池种芳树。\n春天百草秋始衰，弃我不待白头时。罗襦玉珥色未暗，\n今朝已道不相宜。扬州青铜作明镜，暗中持照不见影。\n人心回互自无穷，眼前好恶那能定。君恩已去若再返，\n菖蒲花生月长满。'},
    {t:'相和歌辞·采莲曲三首',a:'王昌龄〔唐代〕',c:'吴姬越艳楚王妃，争弄莲舟水头衣。\n来时浦口花迎入，采罢江头月送归。\n荷叶罗裙一色裁，芙见向脸两边开。\n乱入池中看不见，闻歌始觉有人来。\n越女作桂舟，还将桂为楫。\n湖上水渺漫，清江初可涉。\n摘取芙见花，莫摘芙见叶。\n将归问夫婿，颜色何如妾。'},
    {t:'相和歌辞·采菱行',a:'刘禹锡〔唐代〕',c:'白马湖平秋日光，紫菱如锦彩鸾翔。\n荡舟游女满中央，采菱不顾马上郎。\n争多逐胜纷相向，时转兰桡破轻浪。\n长鬟弱袂动参差，钗影钏文浮荡漾。\n笑语哇咬顾晚晖，蓼花绿岸扣舷归。\n归来共到市桥步，野蔓系船萍满衣。\n家家竹楼临广陌，下有连樯多估客。\n携觞荐芰夜经过，醉踏大堤相应歌。\n屈平祠下沅江水，月照寒波白烟起。\n一曲南音此地闻，长安北望三千里。'},
    {t:'相和歌辞·常林欢',a:'温庭筠〔唐代〕',c:'宜城酒熟花覆桥，沙晴绿鸭鸣咬咬。秾桑绕舍麦如尾，\n幽轧鸣机双燕巢。马声特特荆门道，蛮水扬光色如草。\n锦荐金炉梦正长，东家呃喔鸡鸣早。'},
    {t:'相和歌辞·楚妃叹',a:'张籍〔唐代〕',c:'湘云初起江沉沉，君王遥在云梦林。江南雨多旌旗暗，\n台下朝朝春水深。章华殿前朝万国，君心独自终无极。\n楚兵满地能逐禽，谁用一身继筋力。西江若翻云梦中，\n麋鹿死尽应还宫。'},
    {t:'相和歌辞·楚妃怨',a:'张籍〔唐代〕',c:'梧桐叶下黄金井，横架辘轳牵素绠。\n美人初起天未明，手拂银瓶秋水冷。'},
    {t:'相和歌辞·董逃行',a:'元稹〔唐代〕',c:'董逃董逃董卓逃，揩铿戈甲声劳嘈。剜剜深脐脂焰焰，\n人皆数叹曰，尔独不忆年年取我身上膏。\n膏销骨尽烟火死，长安城中贼毛起。城门四走公卿士，\n走劝刘虞作天子。刘虞不敢作天子，曹瞒篡乱从此始。\n董逃董逃人莫喜，胜负翻环相枕倚。缝缀难成裁破易，\n何况曲针不能伸巧指，欲学裁缝须准拟。'},
    {t:'相和歌辞·董逃行',a:'张籍〔唐代〕',c:'洛阳城头火曈曈，乱兵烧我天子宫。\n宫城南面有深山，尽将老幼藏其间。\n重岩为屋橡为食，丁男夜行候消息。\n闻道官军犹掠人，旧里如今归未得。\n董逃行，汉家几时重太平。'},
    {t:'相和歌辞·短歌行',a:'皎然〔唐代〕',c:'古人若不死，吾亦何所悲。萧萧烟雨九原上，\n白杨青松葬者谁。贵贱同一尘，死生同一指。\n人生在世共如此，何异浮云与流水。\n短歌行，短歌无穷日已倾。邺宫梁苑徒有名，\n春草秋风伤我情。何为不学金仙侣，一悟空王无死生。'},
    {t:'相和歌辞·短歌行',a:'张籍〔唐代〕',c:'青天荡荡高且虚，上有白日无年株。\n流光暂出还入地，催我少年不须臾。\n与君相逢不寂寞，衰老不复如今乐。\n玉卮盛酒置君前，再拜愿君千万年。'},
    {t:'相和歌辞·放歌行',a:'王昌龄〔唐代〕',c:'南渡洛阳津，西望十二楼。\n明堂坐天子，月朔朝诸侯。\n清乐动千门，皇风被九州。\n庆云从东来，泱漭抱日流。\n升平贵论道，文墨将何求。\n有诏征草泽，微臣献谋猷。\n冠冕如星罗，拜揖曹与周。\n望尘非吾事，入赋且迟留。\n幸蒙国士识，因脱负薪裘。\n今者放歌行，以慰梁父愁。\n但营数斗禄，奉养毋丰羞。\n若得金膏遂，飞云亦可俦。'},
    {t:'相和歌辞·贾客乐',a:'张籍〔唐代〕',c:'金陵向西贾客多，船中生长乐风波。欲发移船近江口，\n船头祭神各浇酒。停杯共说远行期，入蜀经蛮远别离。\n金多众中为上客，夜夜算缗眠独迟。秋江初月猩猩语，\n孤帆夜发满湘渚。水工持楫防暗滩，直过山边及前侣。\n年年逐利西复东，姓名不在县籍中。农夫税多长辛苦，\n弃业长为贩卖翁。'},
    {t:'相和歌辞·箜篌引',a:'李贺〔唐代〕',c:'公乎公乎，提壶将焉如。屈平沉乎不足慕，\n徐衍入海诚为愚。公乎公乎，床黍菅席盘黍鱼，\n北里黍贤兄，东邻黍小姑，陇亩油油黍与葫，\n瓦甒浊醪蚁浮浮。黍可食，醪可饮，公乎公乎其奈居，\n被发奔流竟何如？贤兄小姑哭呜呜。'},
    {t:'相和歌辞·猛虎行',a:'韩愈〔唐代〕',c:'猛虎虽云恶，亦各有匹侪。群行父谷间，百兽望风低。\n身食黄熊父，子食赤豹麛。择肉于熊罴，肯步兔与狸。\n正昼当谷眠，眼有百步威。自矜无当对，气性纵以乖。\n朝怒杀其子，暮还飧其妃。匹侪四散走，猛虎还孤栖。\n狐鸣门四旁，乌鹊从噪之。出逐猴入居，虎不知所归。\n谁云猛虎恶，中路正悲啼。豹来衔其尾，熊来攫其颐。\n猛虎死不辞，但惭前所为。虎坐无助死，况如汝细微。\n故当结以信，亲当结以私。亲故且不保，人谁信汝为。'},
    {t:'相和歌辞·莫愁曲',a:'李贺〔唐代〕',c:'草生陇坂下，鸦噪城堞头。何人此城里，城角栽石榴。\n青丝系五马，黄金络双牛。白鱼驾莲船，夜作十里游。\n归来无人识，暗上沉香楼。罗床倚瑶瑟，残月倾帘钩。\n今日槿花落，明朝梧树秋。若负平生意，何名作莫愁。'},
    {t:'相和歌辞·日出行',a:'李贺〔唐代〕',c:'白日下昆仑，发光如舒丝。\n徒照葵藿心，不照游子悲。\n折折黄河曲，日从中央转。\n旸谷耳曾闻，若木眼不见。\n奈何铄石，胡为销人。\n羿弯弓属矢，那不中足。\n令久不得奔，讵教晨光夕昏。'},
    {t:'相和歌辞·三阁词四首',a:'刘禹锡〔唐代〕',c:'贵人三阁上，日晏未梳头。不应有恨事，娇甚却成愁。\n珠箔曲琼钩，子细见扬州。北兵那得度，浪语判悠悠。\n沉香帖阁柱，金缕画门楣。回首降幡下，已见黍离离。\n三人出眢井，一身登槛车。朱门漫临水，不可见鲈鱼。'},
    {t:'相和歌辞·三洲歌',a:'温庭筠〔唐代〕',c:'团圆莫作波中月，洁白莫为枝花雪。\n月随波动碎潾潾，雪似梅花不堪折。\n李娘十六青丝发，画带双花为君结。\n门前有路轻离别，惟恐归来旧香灭。'},
    {t:'相和歌辞·上云乐',a:'李贺〔唐代〕',c:'飞香走红满天春，花龙盘盘上紫云。\n三千宫女列金屋，五十弦瑟海上闻。\n天江碎碎银沙路，嬴女机中断烟素。\n断烟素，缝舞衣，八月一日君前舞。'},
    {t:'相和歌辞·神弦曲',a:'李贺〔唐代〕',c:'西山日没东山昏，旋风吹马马踏云。\n画弦素管声浅繁，花裙綷縩步秋尘。\n桂叶刷风桂坠子，青狸哭血寒狐死。\n古壁彩虬金帖尾，雨工骑入秋潭水。\n百年老鸮成木魅，笑声碧火巢中起。'},
    {t:'相和歌辞·蜀国弦',a:'李贺〔唐代〕',c:'枫香晚华静，锦水南山影。惊石坠猿哀，竹云愁半岭。\n凉月生秋浦，玉沙鳞鳞光。谁家红泪客，不忍过瞿塘。'},
    {t:'相和歌辞·塘上行',a:'李贺〔唐代〕',c:'藕花凉露湿，花缺藕根涩。飞下雌鸳鸯，塘水声溢溢。'},
    {t:'相和歌辞·铜雀妓',a:'李贺〔唐代〕',c:'佳人一壶酒，秋容满千里。\n石马卧新烟，忧来何所似。\n歌声且潜弄，陵树风自起。\n长裾压高台，泪眼看花机。'},
    {t:'相和歌辞·团扇郎',a:'刘禹锡〔唐代〕',c:'团扇复团扇，奉君清暑殿。秋风入庭树，从此不相见。\n上有乘鸾女，苍苍虫网遍。明年入怀袖，别是机中练。'},
    {t:'相和歌辞·王昭君',a:'李商隐〔唐代〕',c:'毛延寿画欲通神，忍为黄金不为人。\n马上琵琶行万里，汉宫长有隔生春。'},
    {t:'相和歌辞·王昭君',a:'皎然〔唐代〕',c:'自倚婵娟望主恩，谁知美恶忽相翻。\n黄金不买汉宫貌，青冢空埋胡地魂。'},
    {t:'相和歌辞·王昭君二首',a:'白居易〔唐代〕',c:'满面胡沙满鬓风，眉销残黛脸销红。\n愁苦辛勤憔悴尽，如今却似画图中。\n汉使却回凭寄语，黄金何日赎蛾眉。\n君王若问妾颜色，莫道不如宫里时。'},
    {t:'相和歌辞·乌栖曲',a:'张籍〔唐代〕',c:'西山作宫潮满池，宫乌晓鸣茱萸枝。\n吴姬自唱采莲曲，君王昨夜舟中宿。'},
    {t:'相和歌辞·相逢行',a:'韦应物〔唐代〕',c:'二十登汉朝，英声迈今古。\n适从东方来，又欲谒明主。\n犹酣新丰酒，尚带霸陵雨。\n邂逅两相逢，别来问寒暑。\n宁知白日晚，暂向花间语。\n忽闻长乐钟，走马东西去。'},
    {t:'相和歌辞·杂怨三首',a:'孟郊〔唐代〕',c:'夭桃花清晨，游女红粉新。夭桃花薄暮，游女红粉故。\n树有百年花，人无一定颜。花送人老尽，人悲花自闲。\n贫女镜不明，寒花日少容。暗蛩有虚织，短线无长缝。\n浪水不可照，狂夫不可从。浪水多散影，狂夫多异踪。\n持此一生薄，空成百恨浓。\n忆人莫至悲，至悲空自衰。寄人莫翦衣，翦衣未必归。\n朝为双蒂花，暮为四散飞。花落却绕树，游子不顾期。'},
    {t:'相和歌辞·张静婉采莲曲',a:'温庭筠〔唐代〕',c:'兰膏坠发红玉春，燕钗拖颈抛盘云。城西杨柳向娇晚，\n门前沟水波潾潾。麒麟公子朝天客，珮马珰珰度春陌。\n掌中无力舞衣轻，翦断鲛绡破春碧。抱月飘烟一尺腰，\n麝脐龙髓怜娇饶。秋罗拂衣碎光动，露重花多香不销。\n鸂鶒胶胶塘水满，绿萍如粟莲茎短。一夜西风送雨来，\n粉痕零落愁红浅。船头折藕丝暗牵，藕根莲子相留连。\n郎心似月月易缺，十五十六清光圆。'},
    {t:'相和歌辞·长门怨',a:'岑参〔唐代〕',c:'君王嫌妾妒，闭妾在长门。舞袖垂新宠，愁眉结旧恩。\n绿钱生履迹，红粉湿啼痕。羞被桃花笑，看春独不言。'},
    {t:'相和歌辞·长门怨',a:'皎然〔唐代〕',c:'春风日日闭长门，摇荡春心自梦魂。\n若遣花开只笑妾，不如桃李正无言。'},
    {t:'相和歌辞猛虎行',a:'李贺〔唐代〕',c:'长戈莫舂，彊弩莫烹。乳孙哺子，教得生狞。\n举头为城，掉尾为旌。东海黄公，愁见夜行。道逢驺虞，牛哀不平。\n生何用尺刀，壁上雷鸣。泰山之下，妇人哭声。官家有程，吏不敢听。'},
    {t:'相见欢·落花如梦凄迷',a:'纳兰性德〔清代〕',c:'落花如梦凄迷，麝烟微，又是夕阳潜下小楼西。\n愁无限，消瘦尽，有谁知？闲教玉笼鹦鹉念郎诗。'},
    {t:'相见欢·微云一抹遥峰',a:'纳兰性德〔清代〕',c:'微云一抹遥峰，冷溶溶，恰与个人清晓画眉同。\n红蜡泪，青绫被，水沉浓，却与黄茅野店听西风。'},
    {t:'相劝酒',a:'李贺〔唐代〕',c:'羲和骋六辔，昼夕不曾闲。弹乌翠嵫竹，抶马蟠桃鞭。\n蓐收既断翠柳，青帝又造红兰。尧舜至今白白岁，\n数子将为倾盖间。青钱白璧买无端，丈夫快意方为欢。\n臛蠵臑熊何足云。会须钟饮北海，箕踞南山。\n歌淫淫，管愔愔，横波好送雕题金。人生得意且如此，\n何用强知元化心。相劝酒，终无辍。\n伏愿陛下鸿名终不歇，子孙绵如石上葛。\n来长安，车骈骈。中有梁冀旧宅，石崇故园。'},
    {t:'相思',a:'李商隐〔唐代〕',c:'相思树上合欢枝，紫凤青鸾共羽仪。\n肠断秦台吹管客，日西春尽到来迟。'},
    {t:'相思',a:'王维〔唐代〕',c:'红豆生南国，春来发几枝。\n愿君多采撷，此物最相思。'},
    {t:'相思儿令',a:'晏殊〔宋代〕',c:'春色渐芳菲也，迟日满烟波。正拟艳阳时节，争奈落花何。\n醉来拟恣狂歌。断肠中、赢得愁多。不如归傍纱窗，有人重画双蛾。'},
    {t:'相思儿令',a:'晏殊〔宋代〕',c:'昨夜探春消息\n湖上绿波平\n无奈绕堤芳草\n还向旧痕生\n有酒且醉瑶觥\n更何妨、檀板新声\n谁教杨柳千丝\n就中牵系人情'},
    {t:'相思儿令·昨日探春消息',a:'晏殊〔宋代〕',c:'昨日探春消息，湖上绿波平。无奈绕堤芳草，还向旧痕生。\n有酒且醉瑶觥。更何妨、檀板新声。谁教杨柳千丝，就中牵系人情。'},
    {t:'相忆泪',a:'元稹〔唐代〕',c:'西江流水到江州，闻处分成九处流。我滴两行相忆泪，\n遣君何处遣人求。除非入海无由住，纵使逢滩未拟休。\n会向伍员潮上见，气充顽石报心仇。'},
    {t:'香积寺礼拜万回平等二圣僧塔',a:'王昌龄〔唐代〕',c:'真无御化来，借有乘化归。如彼双塔内，孰能知是非。\n愚也骇苍生，圣哉为帝师。当为时世出，不由天地资。\n万回主此方，平等性无违。今我一礼心，亿劫同不移。\n肃肃松柏下，诸天来有时。'},
    {t:'香球',a:'元稹〔唐代〕',c:'顺俗唯团转，居中莫动摇。爱君心不恻，犹讶火长烧。'},
    {t:'湘岸移木芙蓉植龙兴精舍',a:'柳宗元〔唐代〕',c:'有美不自蔽，安能守孤根。\n盈盈湘西岸，秋至风霜繁。\n丽影别寒水，浓芳委前轩。\n芰荷谅难杂，反此生高原。'},
    {t:'湘东宴曲',a:'温庭筠〔唐代〕',c:'湘东夜宴金貂人，楚女含情娇翠嚬。玉管将吹插钿带，\n锦囊斜拂双麒麟。重城漏断孤帆去，唯恐琼签报天曙。\n万户沈沈碧树圆，云飞雨散知何处。欲上香车俱脉脉，\n清歌响断银屏隔。堤外红尘蜡炬归，楼前澹月连江白。'},
    {t:'湘妃',a:'李贺〔唐代〕',c:'筠竹千年老不死，长伴神娥盖江水。\n蛮娘吟弄满寒空，九山静绿泪花红。\n离鸾别凤烟梧中，巫云蜀雨遥相通。\n幽愁秋气上青枫，凉夜波间吟古龙。'},
    {t:'湘妃怨·一作湘灵祠',a:'孟郊〔唐代〕',c:'南巡竟不返，二妃怨逾积。万里下蛾眉，潇湘水空碧。\n冥冥荒山下，古庙收贞魄。乔木深青春，清光满瑶席。\n搴芳徒有荐，灵意殊脉脉。玉珮不可亲，徘徊烟波夕。'},
    {t:'湘宫人歌',a:'温庭筠〔唐代〕',c:'池塘芳草湿，夜半东风起。生绿画罗屏，金壶贮春水。\n黄粉楚宫人，芳花玉刻鳞。娟娟照棋烛，不语两含嚬。'},
    {t:'湘江曲',a:'张籍〔唐代〕',c:'湘水无潮秋水阔，湘中月落行人发。\n送人发，送人归，白蘋茫茫鹧鸪飞。'},
    {t:'湘口馆潇湘二水所会',a:'柳宗元〔唐代〕',c:'九疑浚倾奔，临源委萦回。\n会合属空旷，泓澄停风雷。\n高馆轩霞表，危楼临山隈。\n兹辰始澄霁，纤云尽褰开。\n天秋日正中，水碧无尘埃。\n杳杳渔父吟，叫叫羁鸿哀。\n境胜岂不豫，虑分固难裁。\n升高欲自舒，弥使远念来。\n归流驶且广，泛舟绝沿洄。'},
    {t:'湘弦怨',a:'孟郊〔唐代〕',c:'昧者理芳草，蒿兰同一锄。狂飙蠹秋林，曲直同一枯。\n嘉木忌深蠹，哲人悲巧诬。灵均入回流，靳异为良谟。\n我愿分众泉，清浊各异渠。我愿分众巢，枭鸾相远居。\n此志谅难保，此情竟何如。湘弦少知音，孤响空踟蹰。'},
    {t:'湘月·赋云溪',a:'张炎〔宋代〕',c:'随风万里。已无心出岫，浮游天地。为问山中何所有，此意不堪持寄。淡薄相依，行藏自适，一片松阴外。石根苍润，飘飘元是清气。\n长伴暗谷泉生，晴光潋滟，湿影摇花碎。浊浊波涛江汉里，忽见清流如此。枝上瓢空，鸥前沙净，欲洗幽人耳。白苹洲上，浩歌一棹春水。'},
    {t:'湘中',a:'韩愈〔唐代〕',c:'猿愁鱼踊水翻波，自古流传是汨罗。\n蘋藻满盘无处奠，空闻渔父扣舷歌。'},
    {t:'湘中酬张十一功曹',a:'韩愈〔唐代〕',c:'休垂绝徼千行泪，共泛清湘一叶舟。\n今日岭猿兼越鸟，可怜同听不知愁。'},
    {t:'湘中作',a:'张九龄〔唐代〕',c:'湘流绕南岳，绝目转青青。\n怀禄未能已，瞻途屡所经。\n烟屿宜春望，林猿莫夜听。\n永路日多绪，孤舟天复冥。\n浮没从此去，嗟嗟劳我形。'},
    {t:'襄国别友',a:'张籍〔唐代〕',c:'晓色荒城下，相看秋草时。独游无定计，不欲道来期。\n别处去家远，愁中驱马迟。归人渡烟水，遥映野棠枝。'},
    {t:'襄武馆游眺',a:'韦应物〔唐代〕',c:'州民知礼让，讼简得遨游。高亭熟古地，山川当暮秋。\n是时粳稻熟，西望尽田畴。仰恩惭政拙，念树喜岁收。\n澹泊风景晏，缭绕云树幽。节往情恻恻，天高思悠悠。\n嘉宾幸云集，芳樽始淹留。还希习池赏，聊以驻鸣驺。'},
    {t:'襄阳公宅饮①',a:'孟浩然〔唐代〕',c:'窈窕夕阳佳，丰茸春色好。\n欲觅须留处，无过狭斜道。②\n绮席卷龙须，香杯浮玛瑙。③\n北林积修树，南红生别岛。④\n手拨金翠花，心迷玉红草。⑤\n谈天光六义，发论明三倒。⑥\n座非陈子惊，门还魏公扫。⑦\n荣辱应无间，欢娱当共保。⑧'},
    {t:'襄阳雪夜感怀',a:'杜牧〔唐代〕',c:'往事起独念，飘然自不胜。前滩急夜响，密雪映寒灯。\n的的三年梦，迢迢一线縆。明朝楚山上，莫上最高层。'},
    {t:'翔隼歌送王端公',a:'皎然〔唐代〕',c:'古人赏神骏，何如秋隼击。独立高标望霜翮，\n应看天宇如咫尺。低回拂地凌风翔，鹏雏敢下雁断行。\n晴空四顾忽不见，有时独出青霞傍。穷阴万里落寒日，\n气杀草枯增奋逸。云塞斜飞搅叶迷，雪天直上穿花疾。\n见君高情有所属，赠别因歌翔隼曲。离亭惨惨客散时，\n歌尽路长意不足。'},
    {t:'享庙乐辞十八首其一肆夏乐',a:'佚名〔隋代〕',c:'霜凄雨畅，烝哉帝心。有敬其祀，鞠事惟歆。昭昭车服，济济衣簪。\n鞠躬贡酎，磬折奉琛。差以五列，和以八音。式祗王度，如玉如金。'},
    {t:'项王古祠联句',a:'皎然〔唐代〕',c:'遗庙风尘积，荒途岁月侵。——潘述\n霸灵今寂寞，容卫尚森沈。——皎然\n霸楚志何在，平秦功亦深。——汤衡\n星侯归复背，青史古将今。——潘述\n星聚分已定，天亡力岂任。——皎然\n采蘩如可荐，举酒沥空林。——汤衡'},
    {t:'项羽',a:'陆游〔宋代〕',c:'八尺将军千里骓，拔山扛鼎不妨奇。\n范增力尽无施处，路到乌江君自知。'},
    {t:'逍遥乐·春意渐归芳草',a:'黄庭坚〔宋代〕',c:'春意渐归芳草。故国佳人，千里极沈音杳。雨润烟光，晚景澄明，极目危栏斜照。梦当年少。对樽歌、上客邹枚，小鬟燕赵。共舞雪歌尘，醉里谈笑。\n花色枝枝争好。鬓丝年年渐老。如今遇风景，空瘦损、向谁道。东君幸赐与，天幕翠遮红绕。休休，醉乡岐路，华胥蓬岛。'},
    {t:'逍遥咏',a:'白居易〔唐代〕',c:'亦莫恋此身，亦莫厌此身。\n此身何足恋，万劫烦恼根。\n此身何足厌，一聚虚空尘。\n无恋亦无厌，始是逍遥人。'},
    {t:'消暑',a:'白居易〔唐代〕',c:'何以消烦暑，端坐一院中。\n眼前无长物，窗下有清风。\n热散由心静，凉生为室空。\n此时身自保，难更与人同。'},
    {t:'萧驸马宅花烛',a:'王昌龄〔唐代〕',c:'青鸾飞入合欢宫，紫凤衔花出禁中。\n可怜今夜千门里，银汉星回一道通。'},
    {t:'萧洒桐庐郡十绝',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，乌龙山霭中。\n使君无一事，心共白云空。'},
    {t:'萧洒桐庐郡十绝·其八',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，清潭百丈馀。\n钓翁应有道，所得是嘉鱼。'},
    {t:'萧洒桐庐郡十绝·其四',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，公馀午睡浓。\n人生安乐处，谁复问千钟。'},
    {t:'萧洒桐庐郡十绝·其五',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，家家竹隐泉。\n令人思杜牧，无处不潺湲。'},
    {t:'萧洒桐庐郡十绝其二',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，开轩即解颜。劳生一何幸，日日面青山。'},
    {t:'萧洒桐庐郡十绝其九',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，身闲性亦灵。降真香一炷，欲老悟黄庭。'},
    {t:'萧洒桐庐郡十绝其六',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，春山半是茶。新雷还好事，惊起雨前芽。'},
    {t:'萧洒桐庐郡十绝其七',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，千家起画楼。相呼采莲去，笑上木兰舟。'},
    {t:'萧洒桐庐郡十绝其三',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，全家长道情。不闻歌舞事，绕舍石泉声。'},
    {t:'萧洒桐庐郡十绝其十',a:'范仲淹〔宋代〕',c:'萧洒桐庐郡，严陵旧钓台。江山如不胜，光武肯教来。'},
    {t:'销暑',a:'白居易〔唐代〕',c:'何以销烦暑，端居一院中。\n眼前无长物，窗下有清风。\n热散由心静，凉生为室空。\n此时身自得，难更与人同。'},
    {t:'潇湘神',a:'刘禹锡〔唐代〕',c:'湘水流，湘水流，九疑云物至今愁。\n若问二妃何处所，零陵芳草露中秋。\n斑竹枝，斑竹枝，泪痕点点寄相思。\n楚客欲听瑶瑟怨，潇湘深夜月明时。'},
    {t:'潇湘神·斑竹枝',a:'刘禹锡〔唐代〕',c:'斑竹枝，斑竹枝，泪痕点点寄相思。楚客欲听瑶瑟怨，潇湘深夜月明时。'},
    {t:'小池',a:'杨万里〔宋代〕',c:'泉眼无声惜细流，树阴照水爱晴柔。\n小荷才露尖尖角，早有蜻蜓立上头。'},
    {t:'小儿不畏虎',a:'苏轼〔宋代〕',c:'有妇人昼日置二小儿沙上，而浣衣于水者。虎自山上驰来，妇人仓皇沉水避之。二小儿戏沙上自若。虎熟视久之，至以首抵触，庶几其一惧，而儿痴不知怪。虎亦寻卒去。意虎之食人，必先被之以威；而不惧之人，威无所从施欤！'},
    {t:'小敷谷龙潭祠作',a:'王昌龄〔唐代〕',c:'崖谷喷疾流，地中有雷集。百泉势相荡，巨石皆却立。\n跳波沸峥嵘，深处不可挹。昏为蛟龙怒，清见云雨入。\n灵怪崇偏祠，废兴自兹邑。沉淫顷多昧，檐宇遂不葺。\n吾闻被明典，盛德惟世及。生人载山川，血食报原隰。\n岂伊骇微险，将以循甿揖。□飞振吕梁，忠信亦我习。\n波流浸已广，悔吝在所汲。溪水有清源，褰裳靡沾湿。'},
    {t:'小寒食舟中作',a:'杜甫〔唐代〕',c:'佳辰强饮食犹寒，隐几萧条戴鹖冠。\n春水船如天上坐，老年花似雾中看。\n娟娟戏蝶过闲幔，片片轻鸥下急湍。\n云白山青万余里，愁看直北是长安。'},
    {t:'小均四景诗其一',a:'朱熹〔宋代〕',c:'晓起坐书斋，落花堆满径。只此是文章，挥毫有馀兴。'},
    {t:'小年',a:'文天祥〔宋代〕',c:'燕朔逢穷腊，江南拜小年。\n岁时生处乐，身世死为缘。\n鸦噪千山雪，鸿飞万里天。\n出门意寥廓，四顾但茫然。'},
    {t:'小岁日喜谈氏外孙女孩满月',a:'白居易〔唐代〕',c:'今旦夫妻喜，他人岂得知。\n自嗟贵女晚，敢讶见孙迟。\n物以稀为贵，情因老更慈。\n新年逢吉日，满月乞名时。\n桂燎熏花果，兰汤洗玉肌。\n怀中有可抱，何必是男儿。'},
    {t:'小溪至新田四首·其四',a:'杨万里〔宋代〕',c:'懊恼春光欲断肠，来时长缓去时忙。\n落红满路无人惜，蹈作花泥透脚香。'},
    {t:'小雪',a:'陆游〔宋代〕',c:'檐飞数片雪，瓶插一枝梅。\n童子敲清磬，先生入定回。'},
    {t:'小隐吟',a:'孟郊〔唐代〕',c:'我饮不在醉，我欢长寂然。酌溪四五盏，听弹两三弦。\n炼性静栖白，洗情深寄玄。号怒路傍子，贪败不贪全。'},
    {t:'小雨',a:'杨万里〔宋代〕',c:'雨来细细复疏疏，纵不能多不肯无。\n似妒诗人山入眼，千峰故隔一帘珠。'},
    {t:'小园',a:'陆游〔宋代〕',c:'村南村北鹁鸪声，水刺新秧漫漫平。\n行遍天涯千万里，却从邻父学春耕。'},
    {t:'小园·其一',a:'陆游〔宋代〕',c:'小园烟草接邻家，桑柘阴阴一径斜。\n卧读陶诗未终卷，又乘微雨去锄瓜。'},
    {t:'小园独酌',a:'李商隐〔唐代〕',c:'柳带谁能结，花房未肯开。\n空馀双蝶舞，竟绝一人来。\n半展龙须席，轻斟玛瑙杯。\n年年春不定，虚信岁前梅。'},
    {t:'小镇西·意中有个人',a:'柳永〔宋代〕',c:'意中有个人，芳颜二八。天然俏、自来奸黠。最奇绝。是笑时、媚靥深深，百态千娇，再三偎著，再三香滑。\n久离缺。夜来魂梦里，尤花殢雪。分明似、旧家时节。正欢悦。被邻鸡唤起，一场寂寥，无眠向晓，空有半窗残月。'},
    {t:'小镇西犯·水乡初禁火',a:'柳永〔宋代〕',c:'水乡初禁火，青春未老。芳菲满、柳汀烟岛。波际红帏缥缈。尽杯盘小。歌祓禊，声声谐楚调。\n路缭绕。野桥新市里，花秾妓好。引游人、竞来喧笑。酩酊谁家年少。信玉山倒。家何处，落日眠芳草。'},
    {t:'小至',a:'杜甫〔唐代〕',c:'天时人事日相催，冬至阳生春又来。\n刺绣五纹添弱线，吹葭六琯动浮灰。\n岸容待腊将舒柳，山意冲寒欲放梅。\n云物不殊乡国异，教儿且覆掌中杯。'},
    {t:'小重山·赋云屋',a:'张炎〔宋代〕',c:'清气飞来望似空。数椽何用草，赠堪容。卷将一片当帘栊。难持赠，只在此山中。\n鱼影倦随风。无心成雨意，又西东。都缘窗户自玲珑。江枫外，不隔夜深钟。'},
    {t:'小重山·三山与客泛西湖',a:'辛弃疾〔宋代〕',c:'绿涨连云翠拂空。十分风月处，重衰翁。垂杨影断岸西东。君恩重，教且种芙蓉。\n十里水晶宫。有时骑马去，笑儿童。殷勤却谢打头风。船儿住，且醉浪花中。'},
    {t:'小重山·题晓竹图',a:'张炎〔宋代〕',c:'淡色分山晓气浮。疏林犹剩叶，不多秋。林深仿佛昔曾游。频唤酒，渔屋岸西头。\n不拟此凝眸。朦胧清影里，过扁舟。行行应到白苹洲。烟水冷，传语旧沙鸥。'},
    {t:'小舟游近村舍舟步归·其四',a:'陆游〔宋代〕',c:'斜阳古柳赵家庄，负鼓盲翁正作场。\n死后是非谁管得，满村听说蔡中郎。'},
    {t:'晓出净慈寺送林子方',a:'杨万里〔宋代〕',c:'毕竟西湖六月中，风光不与四时同。\n接天莲叶无穷碧，映日荷花别样红。'},
    {t:'晓发公安',a:'杜甫〔唐代〕',c:'北城击柝复欲罢，东方明星亦不迟。\n邻鸡野哭如昨日，物色生态能几时。\n舟楫眇然自此去，江湖远适无前期。\n出门转眄已陈迹，药饵扶吾随所之。'},
    {t:'晓过皂口岭',a:'杨万里〔宋代〕',c:'夜渡惊滩有底忙，晓攀绝磴更禁当。\n周遭碧嶂无人迹，围入青天小册方。\n半世功名一鸡肋，平生道路九羊肠。\n何时上到梅花岭，北望螺峰半点苍。'},
    {t:'晓鹤',a:'孟郊〔唐代〕',c:'晓鹤弹古舌，婆罗门叫音。应吹断上律，不使尘中寻。\n虚空梦皆断，歆唏安能禁。如开孤月口，似说明星心。\n既非人间韵，枉作人间禽。不如相将去，碧落窠巢深。'},
    {t:'晓起',a:'文天祥〔宋代〕',c:'远寺鸣金铎，疏窗试宝熏。\n秋声江一片，曙影月三分。\n倦鹤行黄叶，痴猿坐白云。\n道人无一事，抱膝看回文。'},
    {t:'晓入南山',a:'孟浩然〔唐代〕',c:'瘴气晓氛氲，南山复水云。鲲飞今始见，鸟坠旧来闻。\n地接长沙近，江从汨渚分。贾生曾吊屈，予亦痛斯文。'},
    {t:'晓仙谣',a:'温庭筠〔唐代〕',c:'玉妃唤月归海宫，月色澹白涵山空。银河欲转星靥靥，\n碧浪叠山埋早红。宫花有露如新泪，小声丛丛入寒翠。\n绮阁空传唱漏声，网轩未辨凌云字。遥遥珠帐连湘烟，\n鹤扇如霜金骨仙。碧箫曲尽彩霞动，下视九州皆悄然。\n秦王女骑红尾凤，半空回首晨鸡弄。雾盖狂尘亿兆家，\n世人犹作牵情梦。'},
    {t:'晓行巴峡',a:'王维〔唐代〕',c:'际晓投巴峡，馀春忆帝京。\n晴江一女浣，朝日众鸡鸣。\n水国舟中市，山桥树杪行。\n登高万井出，眺迥二流明。\n人作殊方语，莺为故国声。\n赖多山水趣，稍解别离情。'},
    {t:'晓行望云山',a:'杨万里〔宋代〕',c:'霁天欲晓未明间，满目奇峰总可观。\n却有一峰忽然长，方知不动是真山。'},
    {t:'效古·天宝十四年',a:'皎然〔唐代〕',c:'日出天地正，煌煌辟晨曦。\n六龙驱群动，古今无尽时。\n夸父亦何愚，竞走先自疲。\n饮干咸池水，折尽扶桑枝。\n渴死化爝火，嗟嗟徒尔为。\n空留邓林在，折尽令人嗤。'},
    {t:'效古赠崔二',a:'高适〔唐代〕',c:'十月河洲时，一看有归思。\n风飙为惨烈，雨雪暗天地。\n我辈今胡为？浩哉迷所至。\n缅怀当途者，沦沦居声位。\n邈然在云霄，宁肯更沦踬？\n周旋多燕乐，门馆列车骑。\n美人芙蓉姿，狭室兰麝气。\n金炉陈兽炭，谈笑正得意。\n岂论草泽中，有此枯槁士？\n我惭经沦策，久欲甘弃置。\n君负纵横才，如何尚憔悴？\n长歌增郁怏，对酒不能醉。\n穷达自有时，夫子莫下泪。'},
    {t:'效何水部二首',a:'韦应物〔唐代〕',c:'玉宇含清露，香笼散轻烟。应当结沉抱，难从兹夕眠。\n夕漏起遥恨，虫响乱秋阴。反复相思字，中有故人心。'},
    {t:'效陶彭泽',a:'韦应物〔唐代〕',c:'霜露悴百草，时菊独妍华。物性有如此，寒暑其奈何。\n掇英泛浊醪，日入会田家。尽醉茅檐下，一生岂在多。'},
    {t:'效长吉',a:'李商隐〔唐代〕',c:'长长汉殿眉，窄窄楚宫衣。\n镜好鸾空舞，帘疏燕误飞。\n君王不可问，昨夜约黄归。'},
    {t:'挟书一卷至湖上戏作',a:'陆游〔宋代〕',c:'买地孤村结草庐，萧然身世落樵渔。\n一编在手君无怪，曾典蓬山四库书。'},
    {t:'写意',a:'李商隐〔唐代〕',c:'燕雁迢迢隔上林，高秋望断正长吟。\n人间路有潼江险，天外山惟玉垒深。\n日向花间留返照，云从城上结层阴。\n三年已制思乡泪，更入新年恐不禁。'},
    {t:'写真自赞五首',a:'黄庭坚〔宋代〕',c:'道是鲁直亦得，道不是鲁直亦得。\n是与不是，且置勿道。\n唤那个作鲁直，若要斩截一句，藏头白海头黑。\n似僧有发，似俗无尘。\n作梦中梦，见身外身。'},
    {t:'谢安墩二首',a:'王安石〔宋代〕',c:'我名公字偶相同，我屋公墩在眼中。\n公去我来墩属我，不应墩姓尚随公。'},
    {t:'谢曹子方惠二物二首之博山炉',a:'黄庭坚〔宋代〕',c:'飞来海上峰，琢出华阴碧。\n炷香上褭褭，映我鼻端白。\n听公谈昨梦，沙暗雨矢石。\n今此非梦耶，烟寒已无迹。'},
    {t:'谢池春·壮岁从戎',a:'陆游〔宋代〕',c:'壮岁从戎，曾是气吞残虏。阵云高、狼烟夜举。朱颜青鬓，拥雕戈西戍。笑儒冠、自来多误。\n功名梦断，却泛扁舟吴楚。漫悲歌、伤怀吊古。烟波无际，望秦关何处。叹流年、又成虚度。'},
    {t:'谢公墅歌',a:'温庭筠〔唐代〕',c:'朱雀航南绕香陌，谢郎东墅连春碧。鸠眠高柳日方融，\n绮榭飘飖紫庭客。文楸方罫花参差，心阵未成星满池。\n四座无喧梧竹静，金蝉玉柄俱持颐。对局含情见千里，\n都城已得长蛇尾。江南王气系疏襟，未许苻坚过淮水。'},
    {t:'谢公亭·盖谢脁范云之所游',a:'李白〔唐代〕',c:'谢亭离别处，风景每生愁。\n客散青天月，山空碧水流。\n池花春映日，窗竹夜鸣秋。\n今古一相接，长歌怀旧游。'},
    {t:'谢黄揔太博见示文集',a:'范仲淹〔宋代〕',c:'松桂言嘉色，不与众芳期。\n金石言正声，讵将群响随。\n君子著雅言，以道不以时。\n仰止江夏公，大化元小疵。\n孜孜经纬心，落落教化辞。\n上言帝皇道，下言人臣规。\n邈与圣贤会，岂以富贵移。\n谁言荆棘滋，独此生兰芝。\n谁言蛙黾繁，独此蟠龙龟。\n岂徒一时异，将为千古奇。\n愿此周召风，达我尧舜知。\n致之讽谏路，升之诰命司。\n二雅正得失，五典陈雍熙。\n颂声格九庙，王泽及四夷。\n自然天下文，不复迷宗师。'},
    {t:'谢柳太博惠鹤',a:'范仲淹〔宋代〕',c:'新诗遗鹤指真经，对此仙标讵海轻。\n万里华亭思去伴，千年辽海识归程。\n鸡群与处曾非辱，鹏路将翔孰谓荣。\n独爱九臯嘹唳好，声声天地为之清。'},
    {t:'谢柳子厚寄叠石砚',a:'刘禹锡〔唐代〕',c:'常时同砚席，寄砚感离群。\n清越敲寒玉，参差叠碧云。\n烟岚餘斐亹，水墨两氛氲。\n好与陶贞白，松窗写紫文。'},
    {t:'谢人送兰其一',a:'朱熹〔宋代〕',c:'幽独尘事屏，晼晚秋兰滋。芳馨不自媚，掩抑空相思。\n晤对日方永，披丛露未晞。翛然发孤咏，九畹陈悲诗。'},
    {t:'谢书',a:'李商隐〔唐代〕',c:'微意何曾有一毫，空携笔砚奉龙韬。\n自蒙半夜传衣后，不羡王祥得佩刀。'},
    {t:'谢寺双桧',a:'刘禹锡〔唐代〕',c:'双桧苍然古貌奇，含烟吐雾郁参差。\n晚依禅客当金殿，初对将军映画旗。\n龙象界中成宝盖，鸳鸯瓦上出高枝。\n长明灯是前朝焰，曾照青青年少时。'},
    {t:'谢张仲谋端午送巧作',a:'黄庭坚〔宋代〕',c:'君家玉女从小见，闻道如今画不成。\n翦裁似借天女手，萱草石榴偏眼明。'},
    {t:'谢周文之送猫儿',a:'黄庭坚〔宋代〕',c:'养得狸奴立战功，将军细柳有家风。\n一箪未厌鱼餐薄，四壁当令鼠穴空。'},
    {t:'薤露',a:'佚名〔两汉〕',c:'薤上露，何易晞。\n露晞明朝更复落，人死一去何时归。'},
    {t:'辛丑岁七月赴假还江陵夜行涂口',a:'陶渊明〔魏晋〕',c:'闲居三十载，遂与尘事冥。\n诗书敦宿好，林园无世情。\n如何舍此去，遥遥至南荆！\n叩枻新秋月，临流别友生。\n凉风起将夕，夜景湛虚明。\n昭昭天宇阔，皛皛川上平。\n怀役不遑寐，中宵尚孤征。\n商歌非吾事，依依在耦耕。\n投冠旋旧墟，不为好爵萦。\n养真衡茅下，庶以善自名。'},
    {t:'辛春日词·东宫阁',a:'晏殊〔宋代〕',c:'鲛冰千片解华池，神水香醪满爵户。\n旭日九门凝瑞露，东厢朝拜奉宸慈。'},
    {t:'辛春日词·东宫阁',a:'晏殊〔宋代〕',c:'青幡乍帖宜春字，翠旆初迎入律风。\n一有元良昭大庆，问安长在紫宸中。'},
    {t:'辛春日词·内廷',a:'晏殊〔宋代〕',c:'才闻太昊行新令，更祝元君望景与。\n白玉龟台资寿历，千春鸿福此春初。'},
    {t:'辛春日词·内廷',a:'晏殊〔宋代〕',c:'柳燧青青淑气和，冰纹初解縠文波。\n淑风殿里黄金屋，应候称觞万寿多。'},
    {t:'辛春日词·内廷',a:'晏殊〔宋代〕',c:'朱户未闻迎彩燕，东郊先报舞云翘。\n姜任盛德符青史，金屋千春奉圣朝。'},
    {t:'辛春日词·御阁',a:'晏殊〔宋代〕',c:'青辂迎春习习来，天泉池上晓冰开。\n珠幡已报三阳候，柏叶将陈万寿杯。'},
    {t:'辛卯年雪',a:'韩愈〔唐代〕',c:'元和六年春，寒气不肯归。河南拶月末，雪花一尺围。\n崩腾相排拶，龙凤交横飞。波涛何飘扬，天裳吹幡旂。\n白帝盛羽卫，鬖髿振裳衣。白霓先启途，从以万玉妃。\n翕翕陵厚载，哗哗弄阴机。生平未曾见，何暇议是非。\n或云丰年祥，饱食可庶几。善祷吾所慕，谁言寸诚微。'},
    {t:'辛未七夕',a:'李商隐〔唐代〕',c:'恐是仙家好别离，故教迢递作风期。\n由来碧落银河畔，可要金风玉露时。\n清漏渐移相望久，微云未接过来迟。\n岂能无意酬乌鹊，惟与蜘蛛乞巧丝。'},
    {t:'辛夷花·问韩员外',a:'元稹〔唐代〕',c:'问君辛夷花，君言已斑驳。不畏辛夷不烂开，\n顾我筋骸官束缚。缚遣推囚名御史，狼藉囚徒满田地。\n明日不推缘国忌，依前不得花前醉。韩员外家好辛夷，\n开时乞取三两枝。折枝为赠君莫惜，纵君不折风亦吹。'},
    {t:'辛夷坞',a:'王维〔唐代〕',c:'木末芙蓉花，山中发红萼。\n涧户寂无人，纷纷开且落。'},
    {t:'辛酉冬至',a:'陆游〔宋代〕',c:'今日日南至，吾门方寂然。\n家贫轻过节，身老怯增年。\n毕祭皆扶拜，分盘独早眠。\n惟应探春梦，已绕镜湖边。'},
    {t:'辛酉正月十一日，东园桃李盛开',a:'杨万里〔宋代〕',c:'千万重山见复遮，两三点雨直还斜。\n行穿锦巷入雪巷，看尽桃花到李花。'},
    {t:'新安吏',a:'杜甫〔唐代〕',c:'客行新安道，喧呼闻点兵。\n借问新安吏：县小更无丁？\n府帖昨夜下，次选中男行。\n中男绝短小，何以守王城？\n肥男有母送，瘦男独伶俜。\n白水暮东流，青山犹哭声。\n莫自使眼枯，收汝泪纵横。\n眼枯即见骨，天地终无情！\n我军取相州，日夕望其平。\n岂意贼难料，归军星散营。\n就粮近故垒，练卒依旧京。\n掘壕不到水，牧马役亦轻。\n况乃王师顺，抚养甚分明。\n送行勿泣血，仆射如父兄。'},
    {t:'新城道中二首',a:'苏轼〔宋代〕',c:'东风知我欲山行，吹断檐间积雨声。\n岭上晴云披絮帽，树头初日挂铜钲。\n野桃含笑竹篱短，溪柳自摇沙水清。\n西崦人家应最乐，煮芹烧笋饷春耕。\n身世悠悠我此行，溪边委辔听溪声。\n散材畏见搜林斧，疲马思闻卷旆钲。\n细雨足时茶户喜，乱山深处长官清。\n人间岐路知多少，试向桑田问耦耕。'},
    {t:'新定感兴五首',a:'范仲淹〔宋代〕',c:'风物皆堪喜，民灵独可哀。\n稀逢贤太守，多是谪官来。'},
    {t:'新荷叶·和赵德庄韵',a:'辛弃疾〔宋代〕',c:'人已归来，杜鹃欲劝谁归？绿树如云，等闲借与莺飞。兔葵燕麦，问刘郎、几度沾衣？翠屏幽梦，觉来水绕山围。\n有酒重携，小园随意芳菲。往日繁华，而今物是人非。春风半面，记当年、初识崔徽。南云雁少，锦书无个因依。'},
    {t:'新花',a:'王安石〔宋代〕',c:'老年少忻豫，况复病在床。\n汲水置新花，取忍此流芳。\n流芳只须臾，我亦岂久长。\n新花与故吾，已矣两可忘。'},
    {t:'新居上梁文',a:'辛弃疾〔宋代〕',c:'抛梁东，坐看朝暾万丈红。直使抛为江海客，也应忧国愿年丰。\n抛梁西，万里江湖路欲迷。家本抛人真将种，不妨卖剑买锄犁。\n抛梁南，小山排闼送晴岚。绕林鸟鹊栖枝稳，一枕熏风睡正酣。\n抛梁北，京路尘昏断消息。人生直合住长沙，欲击单于老无力。\n抛梁上，虎豹九关名莫向。且须天女散天花，时至维摩小方丈。\n抛梁下，鸡酒何时入邻舍。只今居士有新巢，要辑轩窗看多稼。'},
    {t:'新乐府序',a:'白居易〔唐代〕',c:'序曰：凡九千二百五十二言，断系五十篇。篇无定句，句无定字，系于意，不系于文。首句标其目，辞章显其志，诗三百之义也。其辞质而径，欲见之者易谕也；其言直而切，欲闻之者深诫也；其事核而实，使采之者传信也；其体顺而肆，可以播于乐章歌曲也。总而言之，系君、系臣、系民、系物、系事而作，不系文而作也。'},
    {t:'新凉感兴',a:'杨万里〔宋代〕',c:'初退生衣进熟衣，新凉只与睡风宜。\n草争人迹微疏处，荷怯秋风欲动时。\n又是一年将过眼，如何两鬓不成丝。\n中元节後新来懒，草册才抄第二诗。'},
    {t:'新柳',a:'杜牧〔唐代〕',c:'无力摇风晓色新，细腰争妒看来频。\n绿阴未覆长堤水，金穗先迎上苑春。\n几处伤心怀远路，一枝和雨送行尘。\n东门门外多离别，愁杀朝朝暮暮人。'},
    {t:'新柳',a:'杨万里〔宋代〕',c:'柳条百尺拂银塘，且莫深青只浅黄。\n未必柳条能蘸水，水中柳影引他长。'},
    {t:'新年',a:'文天祥〔宋代〕',c:'梅花枕上听司晨，起绾金章候拜亲。\n喜对慈颜看铺鬓，发虽疏脱未如银。'},
    {t:'新平歌送许问',a:'孟郊〔唐代〕',c:'边柳三四尺，暮春离别歌。早回儒士驾，莫饮土番河。\n谁识匣中宝，楚云章句多。'},
    {t:'新秦郡松树歌',a:'王维〔唐代〕',c:'青青山上松，数里不见今更逢。\n不见君，心相忆，此心向君君应识。\n为君颜色高且闲，亭亭迥出浮云间。'},
    {t:'新晴野望',a:'王维〔唐代〕',c:'新晴原野旷，极目无氛垢。\n郭门临渡头，村树连溪口。\n白水明田外，碧峰出山后。\n农月无闲人，倾家事南亩。'},
    {t:'新秋送卢判官',a:'皎然〔唐代〕',c:'故人念宿昔，欲别增远情。入座炎气屏，为君秋景清。\n由来空山客，不怨离弦声。唯有暮蝉起，相思碧云生。'},
    {t:'新秋夜寄诸弟',a:'韦应物〔唐代〕',c:'两地俱秋夕，相望共星河。\n高梧一叶下，空斋归思多。\n方用忧人瘼，况自抱微痾。\n无将别来近，颜鬓已蹉跎。'},
    {t:'新暑追凉',a:'杨万里〔宋代〕',c:'去岁冲炎横大江，今年度暑卧筠阳。\n满园无数好亭子，一夏不知何许凉。\n待等老夫亲勘当，更招幽鸟细商量。\n朝慵午倦谁相伴，猫枕桃笙苦竹床。'},
    {t:'新添声杨柳枝词二首',a:'温庭筠〔唐代〕',c:'一尺深红胜曲尘，天生旧物不桃新。\n合欢桃核终堪恨，里许元来别有人。\n井底点灯深烛伊，共郎长行莫围棋。\n玲珑骰子安红豆，入骨相思知不知。'},
    {t:'新夏歌',a:'李贺〔唐代〕',c:'晓木千笼真蜡彩，落蕊枯香数分在。阴枝秀牙卷缥茸，\n长风回气扶葱茏。野家麦畦上新垄，长畛裴回桑柘重。\n刺香满地菖蒲草，雨梁燕语悲身老。三月摇扬入河道，\n天浓地浓柳梳扫。'},
    {t:'新雁过妆楼',a:'张炎〔宋代〕',c:'楚竹闲挑。千日酒、乐意稍稍渔樵。那回轻散，飞梦便觉迢遥。似隔芙蓉无路到，如何共此可怜宵。旧愁消。故人念我，来问寂寥。\n登临试开笑口，看垂垂短发，破帽休飘。款语微吟，清气顿扫花妖。明朝柳岸醉醒，又知在烟波第几桥。怀人处，任满身风露，踏月吹箫。'},
    {t:'新雁过妆楼·风雨不来',a:'张炎〔宋代〕',c:'风雨不来，深院悄、清事正满东篱。杖藜重到，秋气冉冉吹衣。瘦碧飘萧摇露便，腻黄秀野拂霜枝。忆芳时。翠微唤酒，江雁初飞。湘潭无人吊楚，叹落英自采，谁寄相思。淡泊生涯，聊伴老圃斜晖。寒香应遍故里，想鹤怨山空犹未归。归何晚，问径松不语，只有花知。'},
    {t:'新喻道中寄元明用觞字韵',a:'黄庭坚〔宋代〕',c:'中年畏病不举酒，孤负东来数百觞。\n唤客煎茶山店远，看人秧稻午风凉。\n但知家里俱无恙，不用书来细作行。\n一百八盘携手上，至今犹梦绕羊肠。'},
    {t:'新喻西境',a:'朱熹〔宋代〕',c:'北岭苍茫雨欲来，南山腾踯翠成堆。稚杉绕麓千旗卷，野水涵空一鉴开。\n客路情怀元倥偬，今晨游眺却徘徊。自然触目成佳句，云锦无劳更剪裁。'},
    {t:'新政县',a:'元稹〔唐代〕',c:'新政县前逢月夜，嘉陵江底看星辰。已闻城上三更鼓，\n不见心中一个人。须鬓暗添巴路雪，衣裳无复帝乡尘。\n曾沾几许名兼利，劳动生涯涉苦辛。'},
    {t:'新植海石榴',a:'柳宗元〔唐代〕',c:'弱植不盈尺，远意驻蓬赢。\n月寒空阶曙，幽梦彩云生。\n粪壤擢珠树，莓苔插琼英。\n芳根閟颜色，徂岁为谁荣。'},
    {t:'新制布裘',a:'白居易〔唐代〕',c:'桂布白似雪，吴绵软于云。\n布重绵且厚，为裘有余温。\n朝拥坐至暮，夜覆眠达晨。\n谁知严冬月，支体暖如春。\n中夕忽有念，抚裘起逡巡。\n丈夫贵兼济，岂独善一身。\n安得万里裘，盖裹周四垠。\n稳暖皆如我，天下无寒人。'},
    {t:'新制绫袄成感而有咏',a:'白居易〔唐代〕',c:'水波文袄造新成，绫软绵匀温复轻。\n晨兴好拥向阳坐，晚出宜披踏雪行。\n鹤氅毳疏无实事，木棉花冷得虚名。\n宴安往往叹侵夜，卧稳昏昏睡到明。\n百姓多寒无可救，一身独暖亦何情！\n心中为念农桑苦，耳里如闻饥冻声。\n争得大裘长万丈，与君都盖洛阳城！'},
    {t:'新竹',a:'韩愈〔唐代〕',c:'笋添南阶竹，日日成清閟。\n缥节已储霜，黄苞犹掩翠。\n出栏抽五六，当户罗三四。\n高标陵秋严，贞色夺春媚。\n稀生巧补林，并出疑争地。\n纵横乍依行，烂熳忽无次。\n风枝未飘吹，露粉先涵泪。\n何人可携玩，清景空瞪视。'},
    {t:'新竹',a:'元稹〔唐代〕',c:'新篁才解箨，寒色已青葱。\n冉冉偏凝粉，萧萧渐引风。\n扶疏多透日，寥落未成丛。\n惟有团团节，坚贞大小同。'},
    {t:'新竹',a:'朱熹〔宋代〕',c:'春雷殷岩际，幽草齐发生。我种南窗竹，戢戢已抽萌。\n坐获幽林赏，端居无俗情。'},
    {t:'行歌',a:'范仲淹〔宋代〕',c:'行歌春满路，坐歌春满园。\n花前人自乐，桃李岂须言。'},
    {t:'行宫',a:'元稹〔唐代〕',c:'寥落古行宫，宫花寂寞红。\n白头宫女在，闲坐说玄宗。'},
    {t:'行军九日思长安故园',a:'岑参〔唐代〕',c:'强欲登高去，无人送酒来。\n遥怜故园菊，应傍战场开。'},
    {t:'行军诗二首其二',a:'岑参〔唐代〕',c:'早知逢世乱，少小谩读书。悔不学弯弓，向东射狂胡。\n偶从谏官列，谬向丹墀趋。未能匡吾君，虚作一丈夫。\n抚剑伤世路，哀歌泣良图。功业今已迟，览镜悲白须。\n平生抱忠义，不敢私微躯。'},
    {t:'行路难',a:'王昌龄〔唐代〕',c:'双丝作绠系银瓶，百尺寒泉辘轳上。\n悬丝一绝不可望，似妾倾心在君掌。\n人生意气好迁捐，只重狂花不重贤。\n宴罢调筝奏离鹤，回娇转盼泣君前。\n君不见，眼前事，岂保须臾心勿异。\n西山日下雨足稀，侧有浮云无所寄。\n但愿莫忘前者言，锉骨黄尘亦无愧。\n行路难，劝君酒，莫辞烦，\n美酒千钟犹可尽，心中片愧何可论。\n一闻汉主思故剑，使妾长嗟万古魂。'},
    {t:'行路难·其二',a:'李白〔唐代〕',c:'大道如青天，我独不得出。\n羞逐长安社中儿，赤鸡白雉赌梨栗。\n弹剑作歌奏苦声，曳裾王门不称情。\n淮阴市井笑韩信，汉朝公卿忌贾生。\n君不见昔时燕家重郭隗，拥篲折节无嫌猜。\n剧辛乐毅感恩分，输肝剖胆效英才。\n昭王白骨萦蔓草，谁人更扫黄金台？\n行路难，归去来！'},
    {t:'行路难·其三',a:'李白〔唐代〕',c:'有耳莫洗颍川水，有口莫食首阳蕨。\n含光混世贵无名，何用孤高比云月？\n吾观自古贤达人，功成不退皆殒身。\n子胥既弃吴江上，屈原终投湘水滨。\n陆机雄才岂自保？李斯税驾苦不早。\n华亭鹤唳讵可闻？上蔡苍鹰何足道？\n君不见吴中张翰称达生，秋风忽忆江东行。\n且乐生前一杯酒，何须身后千载名？'},
    {t:'行路难·其一',a:'李白〔唐代〕',c:'金樽清酒斗十千，玉盘珍羞直万钱。\n闲来垂钓碧溪上，忽复乘舟梦日边。\n行路难，行路难，多歧路，今安在？\n长风破浪会有时，直挂云帆济沧海。'},
    {t:'行路难三首·其二',a:'柳宗元〔唐代〕',c:'虞衡斤斧罗千山，工命采斫杙与椽。\n深林土剪十取一，百牛连鞅摧双辕。\n万围千寻妨道路，东西蹶倒山火焚。\n遗余毫末不见保，躏跞‌磵壑何当存。\n群材未成质已夭，突兀硣豁空岩峦。\n柏梁天灾武库火，匠石狼顾相愁冤。\n君不见南山栋梁益稀少，爱材养育谁复论。'},
    {t:'行路难三首·其三',a:'柳宗元〔唐代〕',c:'飞雪断道冰成梁，侯家炽炭雕踯房。\n蟠龙吐耀虎喙张，熊蹲豹踯争低昂。\n攒峦丛崿射朱光，丹珰翠雾飘奇香。\n美人四向廻明珰，雪山冰谷晞太阳。\n星躔奔走不得止，奄忽双燕栖虹梁。\n风台露榭生光饰，死灰弃置参与商。\n盛时一去贵反贱，桃笙葵扇安可当。'},
    {t:'行路难五首',a:'杨万里〔宋代〕',c:'老夫少时不信老，长笑老人恃年少。\n如今老矣不笑人，却被少年开口笑。\n少年何苦笑老人，老人旧日颜如春。\n兴来百琖山隤玉，醉後千篇笔有神。\n自古圣贤皆白骨，谁道今人不见古时月。\n孔子盗跖俱尘埃，杜陵老人今亦安在哉。'},
    {t:'行视武夷精舍作',a:'朱熹〔宋代〕',c:'神山九折溪，沿溯此中半。水深波浪阔，浮绿春涣涣。\n上有苍石屏，百仞耸雄观。崭岩露垠堮，突兀倚霄汉。\n浅麓下萦回，深林久丛灌。胡然閟千载，逮此开一旦。\n我乘新村船，辍棹青草岸。榛莽喜诛锄，面势穷考按。\n居然一环堵，妙处岂轮奂。左右矗奇峰，踌躇极佳玩。\n是时芳节阑，红绿纷有烂。好鸟时一鸣，王孙远相唤。\n暂游意已惬，独往身犹绊。珍重舍瑟人，重来足幽伴。'},
    {t:'行香子',a:'晏几道〔宋代〕',c:'晚绿寒红。芳意匆匆。惜年华、今与谁同。碧云零落，数字征鸿。看渚莲凋，宫扇旧，怨秋风。\n流波坠叶，佳期何在，想天教、离恨无穷。试将前事，闲倚梧桐。有消魂处，明月夜，粉屏空。'},
    {t:'行香子·白露园蔬',a:'辛弃疾〔宋代〕',c:'白露园蔬。碧水溪鱼。笑先生、网钓还锄。小窗高卧，风展残书。看北移山，盘谷序，辋川图。白饭青刍。赤脚长须。客来时、酒尽重沽。听风听雨，吾爱吾庐。笑本无心，刚自瘦，此君疏。'},
    {t:'行香子·丹阳寄述古',a:'苏轼〔宋代〕',c:'携手江村，梅雪飘裙。情何限、处处消魂。故人不见，旧曲重闻。向望湖楼，孤山寺，涌金门。\n寻常行处，题诗千首，绣罗衫、与拂红尘。别来相忆，知是何人？有湖中月，江边柳，陇头云。'},
    {t:'行香子·归去来兮',a:'辛弃疾〔宋代〕',c:'归去来兮。行乐休迟。命由天、富贵何时。百年光景，七十者稀。奈一番愁，一番病，一番衰。\n名利奔驰。宠辱惊疑。旧家时、都有些儿。而今老矣，识破关机。算不如闲，不如醉，不如痴。'},
    {t:'行香子·过七里濑',a:'苏轼〔宋代〕',c:'一叶舟轻，双桨鸿惊。水天清、影湛波平。鱼翻藻鉴，鹭点烟汀。过沙溪急，霜溪冷，月溪明。\n重重似画，曲曲如屏。算当年、虚老严陵。君臣一梦，今古空名。但远山长，云山乱，晓山青。'},
    {t:'行香子·秋与',a:'苏轼〔宋代〕',c:'昨夜霜风，先入梧桐。浑无处、回一衰容。问公何事，不语书空。但一回醉，一回病，一回慵。\n朝来庭都，光阴如箭，似无言、有意伤侬。都将万事，付与千钟。任酒花白，眼花乱，烛花红。'},
    {t:'行香子·三山作',a:'辛弃疾〔宋代〕',c:'好雨当春，要趁归耕。况而今、已夜清明。小窗坐地，侧听檐声。恨夜来风，夜来月，夜来云。\n花絮飘零。莺燕丁宁。怕妨侬、湖上闲行。天心肯后，费甚心情。放霎时阴，霎时雨，霎时晴。'},
    {t:'行香子·述怀',a:'苏轼〔宋代〕',c:'清夜无尘，月色如银。酒斟时、须满十分。浮名浮利，虚苦劳神。叹隙中驹，石中火，梦中身。\n虽抱文章，开口谁亲。且陶陶、乐尽天真。几时归去，作个闲人。对一张琴，一壶酒，一溪云。'},
    {t:'行香子·树绕村庄',a:'秦观〔宋代〕',c:'树绕村庄，水满陂塘。倚东风，豪兴徜徉。小园几许，收尽春光。有桃花红，李花白，菜花黄。\n远远围墙，隐隐茅堂。飏青旗，流水桥旁。偶然乘兴，步过东冈。正莺儿啼，燕儿舞，蝶儿忙。'},
    {t:'行香子·与泗守过南山晚归作',a:'苏轼〔宋代〕',c:'北望平川。野水荒湾。共寻春、飞步孱颜。和风弄袖，香雾萦鬟。正酒酣时，人语笑，白云间。\n飞鸿落照，相将归去，淡娟娟、玉宇清闲。何人无事，宴坐空山。望长桥上，灯火乱，使君还。'},
    {t:'行香子·寓意',a:'苏轼〔宋代〕',c:'三入承明。四至九卿。问书生、何汗何荣。金张七叶，纨绮貂缨。无汗马事，不献赋，不明经。\n成都卜肆。寂寞君平。郑子真、岩谷躬耕。寒灰炙手，人重人轻。除竺乾学，得无念，得无名。'},
    {t:'行行且游猎篇',a:'李白〔唐代〕',c:'边城儿，生年不读一字书，但知骑猎夸轻趫。\n胡马秋肥宜白草，骑来蹑影何矜骄。\n金鞭拂雪挥月鞘，半酣呼鹰出远郊。\n弓弯满月不虚发，双鸧迸落连飞髇。\n海边观者皆辟易，猛气英风振沙碛。\n儒生不及骑侠人，白首下帷复何益！'},
    {t:'行行重行行',a:'佚名〔两汉〕',c:'行行重行行，与君生别离。\n相去万余里，各在天一涯。\n道路阻且长，会面安可知？\n胡马依北风，越鸟巢南枝。\n相去日已远，衣带日已缓。\n浮云蔽白日，游子不顾反。\n思君令人老，岁月忽已晚。\n弃捐勿复道，努力加餐饭。'},
    {t:'行至汝坟寄卢征君',a:'孟浩然〔唐代〕',c:'行乏憩予驾，依然见汝坟。洛川方罢雪，嵩嶂有残云。\n曳曳半空里，明明五色分。聊题一时兴，因寄卢征君。'},
    {t:'杏花',a:'韩愈〔唐代〕',c:'居邻北郭古寺空，杏花两株能避红。\n曲江满园不可到，看此宁避雨与风。\n二年流窜出岭外，所泄草木多异同。\n冬寒不严地恒泄，阳气发乱无全功。\n浮花浪蕊镇长有，才开还落瘴雾中。\n山榴踯躅少意思，照耀黄紫徒为丛。\n鹧鸪钩輈猿叫歇，杳杳深谷攒青枫。\n岂如此树一来玩，若在京国情何穷。\n今旦胡为忽惆怅，万片飘泊随西东。\n明年更发应更好，道人莫忘邻家翁。'},
    {t:'杏花',a:'李商隐〔唐代〕',c:'上国昔相值，亭亭如欲言。\n异乡力暂赏，眽眽岂无恩。\n援少风多力，墙高月有痕。\n为含无限意，遂谷不胜繁。\n仙子玉京路，主人金谷园。\n几时辞碧落，谁伴过黄昏。\n镜拂铅华腻，炉藏桂烬温。\n终应催竹叶，先拟咏桃根。\n莫学啼成血，从教梦寄魂。\n吴王采香径，失路入烟村。'},
    {t:'杏花',a:'温庭筠〔唐代〕',c:'红花初绽雪花繁，重叠高低满处园。\n正见盛时犹怅望，岂堪开处已缤翻。\n情为世累诗千首，醉是吾乡酒一樽。\n杳杳艳歌春日午，出墙何处隔朱门。'},
    {t:'杏花',a:'王安石〔宋代〕',c:'石梁度空旷，茅屋临清炯。\n俯窥娇饶杏，未觉身胜影。\n嫣如景阳妃，含笑堕宫井。\n怊怅有微波，残妆坏难整。'},
    {t:'杏花',a:'元稹〔唐代〕',c:'常年出入右银台，每怪春光例早回。\n惭愧杏园行在景，同州园里也先开。'},
    {t:'杏花天·病来自是于春懒',a:'辛弃疾〔宋代〕',c:'病来自是于春懒，但别院、笙歌一片。蛛丝网遍玻璃盏，更问舞裙歌扇。\n有多少莺愁蝶怨。甚梦里、春归不管。杨花也笑人情浅，故故沾衣扑面。'},
    {t:'杏花天·赋疏杏',a:'张炎〔宋代〕',c:'湘罗几翦粘新巧。似过雨、胭脂全少。不教枝上春痕闹。都被海棠分了。\n带柳色、愁眉暗恼。谩遥指、孤村自好。深巷明朝休起早。空等卖花人到。'},
    {t:'杏花天赋疏杏',a:'张炎〔宋代〕',c:'湘罗几剪黏新巧。似过雨、胭脂全少。不教枝上春痕闹。都被海棠分了。\n带柳色、愁眉暗恼。谩遥指、孤村自好。深巷明朝休起早。空等卖花人到。'},
    {t:'杏殇其五',a:'孟郊〔唐代〕',c:'踏地恐土痛，损彼芳树根。此诚天不知，剪弃我子孙。\n垂枝有千落，芳命无一存。谁谓生人家，春色不入门。'},
    {t:'杏园',a:'杜牧〔唐代〕',c:'夜来微雨洗芳尘，公子骅骝步贴匀。\n莫怪杏园憔悴去，满城多少插花人。'},
    {t:'杏园·此后并校书郎已前诗',a:'元稹〔唐代〕',c:'浩浩长安车马尘，狂风吹送每年春。\n门前本是虚空界，何事栽花误世人。'},
    {t:'杏园花下酬乐天见赠',a:'刘禹锡〔唐代〕',c:'二十馀年作逐臣，归来还见曲江春。\n游人莫笑白头醉，老醉花间有几人。'},
    {t:'杏园中枣树',a:'白居易〔唐代〕',c:'人言百果中，唯枣凡且鄙。\n皮皴知龟手，叶小如鼠耳。\n胡为不自知，生花此园里。\n岂宜遇攀玩，幸旖遭伤毁。\n二月曲江头，杂英红旖旎。\n枣亦在其间，如嫫对西子。\n东风不择木，吹喣长未已。\n眼看欲合抱，得尽生生理。\n寄言游春客，乞君一回视。\n君爱绕指柔，从君怜柳杞。\n君求悦目艳，不敢争桃李。\n君若作大车，轮轴材须此。'},
    {t:'匈奴歌',a:'佚名〔两汉〕',c:'失我焉支山，令我妇女无颜色。\n失我祁连山，使我六畜不蕃息。'},
    {t:'熊与坎中人',a:'陶渊明〔魏晋〕',c:'有人入山射鹿，忽堕一坎内，见必久数头。须臾，有大必入，以为必害己。良久，大必出果分与诸久。末后作一份与此人。此人馁久，冒死啖之。必似甚怜之。每旦，必母觅食反，辄分果与之，此人赖以支命。后必久稍大，其母一一负而出。久既出矣，此人自分必死坎中，而必母复还，入坐人边。人解其意，便抱必足，必即跃出，遂不得死。呜呼，人言禽兽无义，然顾此必，安得言无情哉！'},
    {t:'休浣日西掖谒所知',a:'温庭筠〔唐代〕',c:'赤墀高阁自从容，玉女窗扉报曙钟。日丽九门青锁闼，\n雨晴双阙翠微峰。毫端蕙露滋仙草，琴上薰风入禁松。\n荀令凤池春婉娩，好将馀润变鱼龙。'},
    {t:'休假日访王侍御不遇',a:'韦应物〔唐代〕',c:'九日驰驱一日闲，寻君不遇又空还。\n怪来诗思清入骨，门对寒流雪满山。'},
    {t:'休沐东还胄贵里示端',a:'韦应物〔唐代〕',c:'宦游三十载，田野久已疏。休沐遂兹日，一来还故墟。\n山明宿雨霁，风暖百卉舒。泓泓野泉洁，熠熠林光初。\n竹木稍摧翳，园场亦荒芜。俯惊鬓已衰，周览昔所娱。\n存没恻私怀，迁变伤里闾。欲言少留心，中复畏简书。\n世道良自退，荣名亦空虚。与子终携手，岁晏当来居。'},
    {t:'休洗红',a:'李贺〔唐代〕',c:'休洗红，洗多红色浅。\n卿卿骋少年，昨日殷桥见。\n封侯早归来，莫作弦上箭。'},
    {t:'休暇日访王侍御不遇',a:'韦应物〔唐代〕',c:'九日驱驰一日闲，寻君不遇又空还。\n怪来诗思清人骨，门对寒流雪满山。'},
    {t:'徐卿二子歌',a:'杜甫〔唐代〕',c:'君不见徐卿二子生绝奇，感应吉梦相追随。\n孔子释氏亲抱送，并是天上麒麟儿。\n大儿九龄色清澈，秋水为神玉为骨。\n小儿五岁气食牛，满堂宾客皆回头。\n吾知徐公百不忧，积善衮衮生公侯。\n丈夫生儿有如此二雏者，名位岂肯卑微休。'},
    {t:'徐孺子祠堂',a:'黄庭坚〔宋代〕',c:'乔木幽人三亩宅，生刍一束向谁论？\n藤萝得意干云日，箫鼓何心进酒尊。\n白屋可能无孺子，黄堂不是欠陈蕃。\n古人冷淡今人笑，湖水年年到旧痕。'},
    {t:'徐州试反舌无声',a:'张籍〔唐代〕',c:'夏木多好鸟，偏知反舌名。林幽仍共宿，时过即无声。\n竹外天空晓，谿头雨自晴。居人宜寂寞，深院益凄清。\n入雾暗相失，当风闲易惊。来年上林苑，知尔最先鸣。'},
    {t:'许公子郑姬歌·郑园中请贺作',a:'李贺〔唐代〕',c:'许史世家外亲贵，宫锦千端买沉醉。铜驼酒熟烘明胶，\n古堤大柳烟中翠。桂开客花名郑袖，入洛闻香鼎门口。\n先将芍药献妆台，后解黄金大如斗。莫愁帘中许合欢，\n清弦五十为君弹。弹声咽春弄君骨，骨兴牵人马上鞍。\n两马八蹄踏兰苑，情如合竹谁能见。夜光玉枕栖凤凰，\n袷罗当门刺纯线。长翻蜀纸卷明君，转角含商破碧云。\n自从小靥来东道，曲里长眉少见人。相如冢上生秋柏，\n三秦谁是言情客。蛾鬟醉眼拜诸宗，为谒皇孙请曹植。'},
    {t:'叙怀二首',a:'张九龄〔唐代〕',c:'弱岁读群史，抗迹追古人。被褐弟怀玉，佩印从负薪。\n志合岂兄弟，道行无贱贫。孤根亦何赖，感非此为邻。\n晚节从卑秩，岐路良非一。既闻持两端，复见挟三术。\n木瓜诚弟报，玉楮论无实。已矣直躬者，平生壮图失。\n去去勿重陈，归来茹芝朮。'},
    {t:'宣城见杜鹃花',a:'李白〔唐代〕',c:'蜀国曾闻子规鸟，宣城还见杜鹃花。\n一叫一回肠一断，三春三月忆三巴。'},
    {t:'宣清·残月朦胧',a:'柳永〔宋代〕',c:'残月朦胧，小宴阑珊，归来轻寒醉醉。背银釭、孤馆乍眠，拥重衾、醉魄犹噤。永漏频传，前欢已去，风愁一枕。暗寻思、旧追游，神京风物如锦。\n念掷果朋侪，绝缨宴会，当时曾痛饮。命舞燕翩翻，歌珠贯串，向玳筵前，尽是神仙流品。至更阑、疏狂转甚。更相将、凤帏鸳寝。玉钗乱横，任散尽高阳，这欢娱、甚时重恁。'},
    {t:'宣州罢任再赠',a:'文天祥〔宋代〕',c:'贫贱元无富贵思，泥涂滑滑总危机。\n世无徐庶不如卧，见到渊明便合归。\n流落丹心天肯未，峥嵘青眼古来稀。\n西风为语岩前桂，若更多言却又非。'},
    {t:'宣州开元寺南楼',a:'杜牧〔唐代〕',c:'小楼才受一床横，终日看山酒满倾。\n可惜和风夜来雨，醉中虚度打窗声。'},
    {t:'宣州谢朓楼饯别校书叔云',a:'李白〔唐代〕',c:'弃万去者，昨日之日不可留；\n乱万心者，今日之日多烦忧。\n长风万里送秋雁，对此可以酣高楼。\n清莱文章建安骨，中间小谢又清发。\n俱怀逸兴壮思飞，欲上青天揽明月。\n抽刀断水水更流，举杯消愁愁更愁。\n人生在世不称意，明朝散发弄扁舟。'},
    {t:'玄都坛歌寄元逸人',a:'杜甫〔唐代〕',c:'故人昔隐东蒙峰，已佩含景苍精龙。\n故人今居子午谷，独在阴崖结茅屋。\n屋前太古玄都坛，青石漠漠常风寒。\n子规夜啼山竹裂，王母昼下云旗翻。\n知君此计成长往，芝草琅玕日应长。\n铁锁高垂不可攀，致身福地何萧爽。'},
    {t:'玄卿镜铭',a:'佚名〔隋代〕',c:'日初升，月初盈。纤翳不生，肖兹万形。是曰撄宁，莹虚太清。'},
    {t:'薛卿教长行歌·时量移湖州别驾',a:'皎然〔唐代〕',c:'桂阳仙柳道家说，昔传苏君今是薛。聊将握槊偶时人，\n便被人间称冠绝。黄杨文局龟螭蟠，琢成骰子双琅玕。\n初疑月破云中堕，复怪星移指下攒。谁识兵奇势可保，\n坐看将军上一道。有时彩王非所希，笑击单于出重围。\n凫惊隼击疾若飞，左顾右盻生光辉。家本联姻汉戚里，\n身是长安贵公子。名高艺绝何翩翩，几回决胜君王前。\n扈游长乐与祈年，人望青云白日边。谪宦江南岁阴晚，\n还将此道聊自遣。由来君子行最长，予亦知君寄心远。'},
    {t:'薛氏池垂钓',a:'温庭筠〔唐代〕',c:'池塘经雨更苍苍，万点荷珠晓气凉。\n朱瑀空偷御沟水，锦鳞红尾属严光。'},
    {t:'学阮公体三首',a:'刘禹锡〔唐代〕',c:'少年负志气，信道不从时。\n只言绳自直，安知室可欺？\n百胜难虑敌，三折乃良医。\n人生不失意，焉能慕己知？\n朔风悲老骥，秋霜动鸷禽。\n出门有远道，平野多层阴。\n灭没驰绝塞，振迅拂华林。\n不因感衰节，安能激壮心？\n昔贤多使气，忧国不谋身。\n目览千载事，心交上古人。\n侯门有仁义，灵台多苦辛。\n不学腰如磬，徒使甑生尘。'},
    {t:'学习谚语三则',a:'佚名',c:'少年不知勤学苦，老来方知读读迟。\n一日读读一日功，一日不读十日空。\n学习不怕根底浅，只要迈步总不迟。'},
    {t:'学仙二首',a:'韦应物〔唐代〕',c:'昔有道士求神仙，灵真下试心下然。千钧巨石一发悬，\n卧之石下十三年。存道忘身一试过，名见玉皇乃升天。\n云气冉冉渐不见，留语弟子但精坚。\n石上凿井欲到水，惰心一起中路止。\n岂不见古来三人俱弟兄，结茅深山读仙经。\n上有青冥倚天之绝壁，下有飕飗万壑之松声。\n仙人变化为白鹿，二弟玩之兄诵读。读多七过可乞言，\n为子心精得神仙。可怜二弟仰天泣，一失毫厘千万年。'},
    {t:'学易',a:'陆游〔宋代〕',c:'卒岁勿多求，壶餐与褐裘。\n心安由自足，身贵为无求。\n易化千年鹤，难驯万里鸥。\n闭门方学易，未暇揖浮丘。'},
    {t:'学诸进士作精卫衔石填海',a:'韩愈〔唐代〕',c:'鸟有偿冤者，终年抱寸诚。\n口衔山石细，心望海波平。\n渺渺功难见，区区命已轻。\n人皆讥造次，我独赏专精。\n岂计休无日，惟应尽此生。\n何惭刺客传，不著报雠名。'},
    {t:'雪',a:'孟郊〔唐代〕',c:'忽然太行雪，昨夜飞入来。崚嶒堕庭中，严白何皑皑。\n奴婢晓开户，四肢冻徘徊。咽言词不成，告诉情状摧。\n官给未入门，家人尽以灰。意劝莫笑雪，笑雪贫为灾。\n将暖此残疾，典卖争致杯。教令再举手，夸曜馀生才。\n强起吐巧词，委曲多新裁。为尔作非夫，忍耻轰暍雷。\n书之与君子，庶免生嫌猜。'},
    {t:'雪冻未解散策郡圃',a:'杨万里〔宋代〕',c:'积雪偏工霁後凝，不牙冷极不牙清。\n静闻檐滴元无雨，倒挂冰牙未怕晴。\n独往独来银粟地，一行一步玉沙声。\n圃中散策饶君强，敢犯霜风上古城。'},
    {t:'雪二首',a:'温庭筠〔唐代〕',c:'砚水池先冻，窗风酒易消。鸦声出山郭，人迹过村桥。\n稍急方萦转，才深未寂寥。细光穿暗隙，轻白驻寒条。\n草静封还折，松欹堕复摇。谢庄今病眼，无意坐通宵。\n羸骖出更慵，林寺已疏钟。踏紧寒声涩，飞交细点重。\n圃斜人过迹，阶静鸟行踪。寂寞梁鸿病，谁人代夜舂。'},
    {t:'雪干',a:'王安石〔宋代〕',c:'雪干云净见遥岑，南陌芳菲复可寻。\n换得千颦为一笑，春风吹柳万黄金。'},
    {t:'雪后到乾明寺遂宿',a:'苏轼〔宋代〕',c:'门外山光马亦惊，阶前屐齿我先行。\n风花误入长春苑，云月长临不夜城。\n未许牛羊伤至洁，且看鸦鹊弄新晴。\n更须携被留僧榻，待听催檐泻竹声。'},
    {t:'雪后书北台壁二首',a:'苏轼〔宋代〕',c:'黄昏犹作雨纤纤，夜静无风势转严。\n但觉衾裯如泼水，不知庭院已堆盐。\n五更晓色来书幌，半夜寒声落画檐。\n试扫北台看马耳，未随埋没有双尖。\n城头初日始翻鸦，陌上晴泥已没车。\n冻合玉楼寒起粟，光摇银海眩生花。\n遗蝗入地应千尺，宿麦连云有几家。\n老病自嗟诗力退，空吟冰柱忆刘叉。'},
    {t:'雪後煎茶',a:'陆游〔宋代〕',c:'雪液清甘涨井泉，自携茶灶就烹煎。\n一毫无复关心事，不枉人间住百年。'},
    {t:'雪霁晓登金山',a:'杨万里〔宋代〕',c:'焦山东，金山西，金山排霄南斗字。天将三江五湖水，并作一江字杨子。\n来从九天上，泻入九地坤。遇岳岳立摧，逢石石立碎。\n乾坤气力聚此江，一波打来谁敢当。金山一何强，上流独立江中央。\n一尘不随海风舞，一砾不随海潮去。四旁无蒂下无根，浮空跃出江心住。\n金宫银阙起峰头，槌鼓撞钟闻九州。诗人踏雪来清游，天风吹侬上琼楼，不为浮玉饮玉舟。\n大江端的替人羞，金山端的替人愁。'},
    {t:'雪梅香·景萧索',a:'柳永〔宋代〕',c:'景萧索，危楼独立面晴空。动悲秋情绪，当时宋玉应同。渔市孤烟袅寒碧，水村残叶舞愁红。楚天阔，浪浸斜阳，千里溶溶。\n临风。想佳丽，别后愁颜，镇敛眉峰。可惜当年，顿乖雨迹云踪。雅态妍姿正欢洽，落花流水忽西东。无憀恨、相思意，尽分付征鸿。'},
    {t:'雪晴访赵嘏街西所居三韵',a:'杜牧〔唐代〕',c:'命代风骚将，谁登李杜坛。\n少陵鲸海动，翰苑鹤天寒。\n今日访君还有意，二条冰雪独来看。'},
    {t:'雪天',a:'元稹〔唐代〕',c:'故乡千里梦，往事万重悲。小雪沉阴夜，闲窗老病时。\n独闻归去雁，偏咏别来诗。惭愧红妆女，频惊两鬓丝。'},
    {t:'雪晓舟中生火二首',a:'杨万里〔宋代〕',c:'乌银见火生绿雾，便当水沉一微炷。\n却因断续更氤氲，散作霏微暖袍裤。\n须臾雾霁吐红光，烟室云表升扶桑。\n阳春和日曛满室，苍颜渥丹疑醉乡。\n忽然火冷雾亦灭，只见红炉堆白雪。\n窗外雪深三尺强，窗里雪深一寸香。'},
    {t:'雪夜感旧',a:'陆游〔宋代〕',c:'江月亭前桦烛香，龙门阁上驮城长。\n乱山古驿经三折，小市孤城宿两当。\n晚岁犹思事鞍马，当时那信老耕桑。\n绿沉金锁俱尘委，雪洒寒灯泪数行。'},
    {t:'雪夜小饮赠梦得',a:'白居易〔唐代〕',c:'同为懒慢园林客，共对萧条雨雪天。\n小酌酒巡销永夜，大开口笑送残年。\n久将时背成遗老，多被人呼作散仙。\n呼作散仙应有以，曾看东海变桑田。'},
    {t:'雪中',a:'韦应物〔唐代〕',c:'空堂岁已晏，密室独安眠。压筱夜偏积，覆阁晓逾妍。\n连山暗古郡，惊风散一川。此时骑马出，忽省京华年。'},
    {t:'雪中',a:'晏殊〔宋代〕',c:'平台千里渴商霖，内史忧民望最深。\n衣上六花非所好，亩间盈尺是吾心。'},
    {t:'雪中寻梅',a:'陆游〔宋代〕',c:'莫遣扁舟兴尽回，正须冲雪看江梅。\n楚人原未知真色，施粉何曾太白来！'},
    {t:'雪中忆李楫',a:'王维〔唐代〕',c:'积雪满阡陌，故人不可期。长安千门复万户，\n何处躞蹀黄金羁。'},
    {t:'寻白鹤岩张子容隐居',a:'孟浩然〔唐代〕',c:'白鹤青岩半，幽人有隐居。阶庭空水石，林壑罢樵渔。\n岁月青松老，风霜苦竹疏。睹兹怀旧业，回策返吾庐。'},
    {t:'寻陈逸人故居',a:'孟浩然〔唐代〕',c:'人事一朝尽，荒芜三径休。始闻漳浦卧，奄作岱宗游。\n池水犹含墨，风云已落秋。今宵泉壑里，何处觅藏舟。'},
    {t:'寻芳草·萧寺记梦',a:'纳兰性德〔清代〕',c:'客夜怎生过。梦相伴、绮窗吟和。来嗔佯笑道，若不是恁凄凉，肯来么。\n来去苦匆匆，准拟待、晓钟敲破。乍偎人一闪灯花堕，却对著琉璃火。'},
    {t:'寻菊花潭主人不遇',a:'孟浩然〔唐代〕',c:'行至菊花潭，村西日已斜。\n主人登高去，鸡犬空在家。'},
    {t:'寻陆鸿渐不遇',a:'皎然〔唐代〕',c:'移家虽带郭，野径入桑麻。\n近种篱边菊，秋来未著花。\n扣门无犬吠，欲去问西家。\n报道山中去，归时每日斜。'},
    {t:'寻梅道士·一作寻梅道士张山人',a:'孟浩然〔唐代〕',c:'彭泽先生柳，山阴道士鹅。我来从所好，停策汉阴多。\n重以观鱼乐，因之鼓枻歌。崔徐迹未朽，千载揖清波。'},
    {t:'寻裴处士',a:'孟浩然〔唐代〕',c:'涉水更登陆，所向皆清贞。\n寒草不藏径，灵峰知有人。\n悠哉炼金客，独与烟霞亲。\n曾是欲轻举，谁言空隐沦。\n远心寄白日，华发回青春。\n对此钦胜事，胡为劳我身。'},
    {t:'寻天目徐君',a:'皎然〔唐代〕',c:'常见仙翁变姓名，岂知松子号初平。逢人不道往来处，\n卖药还将鸡犬行。独鹤天边俱得性，浮云世上共无情。\n三花落地君犹在，笑抚安期昨日生。'},
    {t:'寻天台山',a:'孟浩然〔唐代〕',c:'吾友太乙子，餐霞卧赤城。欲寻华顶去，不惮恶溪名。\n歇马凭云宿，扬帆截海行。高高翠微里，遥见石梁横。'},
    {t:'寻仙',a:'张籍〔唐代〕',c:'溪头一径入青崖，处处仙居隔杏花。\n更见峰西幽客说，云中犹有两三家。'},
    {t:'寻香山湛上人',a:'孟浩然〔唐代〕',c:'朝游访名山，山远在空翠。氛氲人百里，日入行始至。\n杖策寻故人，解鞭暂停骑。石门殊豁险，篁不转森邃。\n法侣欣相逢，清谈晓不寐。平生慕真隐，累日探奇异。\n野老朝入田，山僧暮归寺。松泉多逸响，苔壁饶古意。\n谷口闻钟声，林端识香气。愿言投此山，身世两相弃。'},
    {t:'寻徐道士',a:'张籍〔唐代〕',c:'寻师远到晖天观，竹院森森闭药房。\n闻入静来经七日，仙童檐下独焚香。'},
    {t:'寻阳乐',a:'佚名〔隋代〕',c:'鸡亭故侬去，九里新侬还。\n送一却迎两，无有暂时闲。'},
    {t:'寻阳七郎中宅即事',a:'岑参〔唐代〕',c:'万事信苍苍，机心久已忘。无端来出守，不是厌为郎。\n雨滴芭蕉赤，霜催橘子黄。逢君开口笑，何处有他乡。'},
    {t:'寻雍尊师隐居',a:'李白〔唐代〕',c:'群峭碧摩天，逍遥不记年。\n拨云寻古道，倚石听流泉。\n花暖青牛卧，松高白鹤眠。\n语来江色暮，独自下寒烟。'},
    {t:'寻张五回夜园作',a:'孟浩然〔唐代〕',c:'闻就庞公隐，移居近洞湖。兴来林是竹，归卧谷名愚。\n挂席樵风便，开轩琴月孤。岁寒何用赏，霜落故园芜。'},
    {t:'巡按自漓水南行',a:'张九龄〔唐代〕',c:'理棹虽云远，饮冰宁有惜。\n况乃转山川，怡然傲潭石。\n奇峰岌前转，茂树隈中积。\n猿鸟声自呼，风晖气相激。\n目因诡容逆，心与清晖涤。\n纷吾谬执简，行郡将移檄。\n即事聊独欢，素怀岂兼适。\n悠悠咏靡盬，庶以穷日夕。'},
    {t:'巡属县道中作',a:'张九龄〔唐代〕',c:'春令夙所奉，驾言遵此行。途中剧郡掾，林下招村氓。\n至邑无纷剧，来人但欢迎。岂伊念邦政，尔柴在时清。\n短才滥符竹，弱岁起柴荆。再入江村道，永怀山薮情。\n矧逢阳节献，默听时禽鸣。迹与素心别，感从幽思盈。\n流芳日不待，夙志蹇无成。知命且何欲，所图唯退耕。\n华簪极身泰，衰鬓惭木荣。苟得不可遂，吾其谢世婴。'},
    {t:'训蒙绝句安仁利仁',a:'朱熹〔宋代〕',c:'语利犹能安则难，且从利做莫空安。悬知等级无他义，去尽私心只一般。'},
    {t:'训蒙绝句出门如见大宾',a:'朱熹〔宋代〕',c:'竦然敬立体斯存，容貌常如见大宾。此是圣门持守法，必须心在可为仁。'},
    {t:'训蒙绝句刍养悦口',a:'朱熹〔宋代〕',c:'食中有味知斯悦，知是能加咀嚼功。行处心安思处得，馀甘常溢齿牙中。'},
    {t:'训蒙绝句动心忍性二首其一',a:'朱熹〔宋代〕',c:'不当拂处常逢拂，不合空时亦至空。处顺不如常处逆，动心忍性始成功。'},
    {t:'训蒙绝句古者以利为本',a:'朱熹〔宋代〕',c:'论性无非日用间，何须虚诞与深艰。昭昭万事皆其理，只是功夫欲顺难。'},
    {t:'训蒙绝句鬼神',a:'朱熹〔宋代〕',c:'鬼神即物以为名，屈则无形伸有形。一屈一伸端莫测，可窥二五运无停。'},
    {t:'训蒙绝句静二首其一',a:'朱熹〔宋代〕',c:'心惟动与静相乘，当静之时乃动源。所以功夫先要静，动而无静体难全。'},
    {t:'训蒙绝句九思',a:'朱熹〔宋代〕',c:'人之进学在于思，思则能知是与非。但得用心纯熟后，自然发处有思随。'},
    {t:'训蒙绝句居敬二首其一',a:'朱熹〔宋代〕',c:'大哉程子明居敬，千圣同符入德门。试把功夫横竖看，总来不出欲斯存。'},
    {t:'训蒙绝句绝四',a:'朱熹〔宋代〕',c:'在人四者要皆无，绝尽圣心天与俱。敢尔单提希圣术，力除私欲是功夫。'},
    {t:'训蒙绝句克己二首其一',a:'朱熹〔宋代〕',c:'本体原来只是公，自将私意混其中。虽颜造圣无他事，惟在能加克己功。'},
    {t:'训蒙绝句良知',a:'朱熹〔宋代〕',c:'孩提自幼良知发，此日心蒙尚未开。既壮蒙开趋物欲，良心反丧亦哀哉。'},
    {t:'训蒙绝句莫我知也夫三首',a:'朱熹〔宋代〕',c:'心即是天天即理，无行不与理相随。故言惟有天知我，天岂真如人有知。'},
    {t:'训蒙绝句其二',a:'朱熹〔宋代〕',c:'存以公兮亡以私，存亡倏忽动时机。莫教事过方才省，辨析须严念虑微。'},
    {t:'训蒙绝句人心道心三首其二',a:'朱熹〔宋代〕',c:'因形与理别言心，其实随形有理存。才与理违形独用，便为物欲理皆昏。'},
    {t:'训蒙绝句人心道心三首其一',a:'朱熹〔宋代〕',c:'自从载籍流传后，此是论心第一条。剖析精明为训切，如何心学尚寥寥。'},
    {t:'训蒙绝句三省二首其一',a:'朱熹〔宋代〕',c:'曾子尚忧三者失，自言日致省身功。如何后学不深察，便欲传心一惟中。'},
    {t:'训蒙绝句山径之蹊',a:'朱熹〔宋代〕',c:'苟能用力可充微，一息昏忘功便亏。老矣方知深自警，几番茅塞径之蹊。'},
    {t:'训蒙绝句十五志学',a:'朱熹〔宋代〕',c:'工夫一进十年期，断自圣言当致思。岂不欲人跻圣速，只缘科级盖如斯。'},
    {t:'训蒙绝句逝者如斯二首其一',a:'朱熹〔宋代〕',c:'如何物却能形道，只为皆存理一端。偶感斯川存动理，故言逝者可同观。'},
    {t:'训蒙绝句太极图',a:'朱熹〔宋代〕',c:'性蔽其源学失真，异端投隙害弥深。推原气禀由无极，只此一图传圣心。'},
    {t:'训蒙绝句万物皆备于我',a:'朱熹〔宋代〕',c:'万物当须以理观，不离太极是其源。故须万类皆我具，只为中心太极存。'},
    {t:'训蒙绝句为人',a:'朱熹〔宋代〕',c:'辛勤尽作求闻计，沽得过情声誉来。自外而观为可喜，此心已失实堪哀。'},
    {t:'训蒙绝句吾无隐乎尔',a:'朱熹〔宋代〕',c:'圣道虽云妙莫窥，初非恍惚与希夷。分明说在吾行处，后学无于行外思。'},
    {t:'训蒙绝句吾知勉',a:'朱熹〔宋代〕',c:'常怀四体昊天恩，自是渊冰恐惧深。一息尚存忧未免，死而后已即斯心。'},
    {t:'训蒙绝句勿忘勿助长',a:'朱熹〔宋代〕',c:'忘则无功助则私，不忘不助正斯时。是中体段须当察，便是鸢飞鱼跃机。'},
    {t:'训蒙绝句下学上达',a:'朱熹〔宋代〕',c:'学在事时斯是理，盍于事上每寻思。但令下学功夫到，上达之机便自知。'},
    {t:'训蒙绝句先难',a:'朱熹〔宋代〕',c:'为学须教效自形，但专一意使功深。哀哉狭隘频求效，仰止仁人后获心。'},
    {t:'训蒙绝句小学',a:'朱熹〔宋代〕',c:'洒扫庭堂职是供，步趋唯诺饰仪容。是中有理今休问，敬谨端详体立功。'},
    {t:'训蒙绝句心之官则思',a:'朱熹〔宋代〕',c:'一身胡属此心微，只为能思择所为。底事虚灵成暗塞，独于物欲用其思。'},
    {t:'训蒙绝句学',a:'朱熹〔宋代〕',c:'轲死如何道乏人，缘知学字不分明。先除功利虚无习，尽把圣言身上行。'},
    {t:'训蒙绝句意',a:'朱熹〔宋代〕',c:'意乃情专所主时，志之所向定于斯。要须总验心情意，一发而俱性在兹。'},
    {t:'训蒙绝句予欲无言',a:'朱熹〔宋代〕',c:'妙道皆形日用间，即斯可见不须言。试将天象明人事，希圣功夫万古存。'},
    {t:'训蒙绝句鸢飞鱼跃二首其一',a:'朱熹〔宋代〕',c:'此理充盈宇宙间，下穷鱼跃上飞鸢。飞斯在上跃斯下，神化孰尸本自然。'},
    {t:'训蒙绝句致知',a:'朱熹〔宋代〕',c:'此心原自有知存，气蔽其明物又昏。渐渐剔开昏与蔽，一时俱透理穷源。'},
    {t:'训蒙绝句中庸',a:'朱熹〔宋代〕',c:'过兼不及总非中，离却平常不是庸。庸字莫将容易看，只斯为道用无穷。'},
    {t:'驯鸥咏',a:'范仲淹〔宋代〕',c:'万物有常性，性无不贵生。\n风翔与骏奔，一一远害情。\n鴥彼沙上鸥，皎皎霜雪明。\n月宿沧洲静，日浴沧浪清。\n何以狎溪人，溪人澹无营。\n循循自饮啄，往往相逢迎。\n徘徊两无猜，何慕复何惊。\n客有怀依依，云水言将归。\n逐尔群鸥乐，群鸥尔勿飞。\n此心未忘者，天机非杀机。'},
    {t:'巽公院五咏·苦竹桥',a:'柳宗元〔唐代〕',c:'危桥属幽径，缭绕穿疏林。\n迸箨分苦节，轻筠抱虚心。\n俯瞰涓涓流，仰聆萧萧吟。\n差池下烟日，嘲哳鸣山禽。\n谅无要津用，栖息有馀阴。'},
    {t:'蕈子',a:'杨万里〔宋代〕',c:'空山一雨山溜急，漂流桂子松花汁。\n土膏松暖都渗入，蒸出蕈花团戢戢。\n戴穿落叶忽起立，拨湿落叶百数十。\n蜡面黄紫光欲湿，酥茎娇脆手轻拾。\n响如鹅掌味如蜜，滑似蒪丝无点涩。\n伞不如笠钉胜笠，香留齿牙麝莫及。\n菘羔楮鸡避席揖，餐玉茹芝当却粒。\n作羹不可疏一日，作腊仍堪贮盈笈。'},
    {t:'鸦',a:'杜牧〔唐代〕',c:'扰扰复翻翻，黄昏飏冷烟。毛欺皇后发，声感楚姬弦。\n蔓垒盘风下，霜林接翅眠。只如西旅样，头白岂无缘。'},
    {t:'鸦',a:'杨万里〔宋代〕',c:'稚子相看只笑渠，老夫亦复小卢胡。\n一鸦飞立钩栏角，子细看来还有须。'},
    {t:'鸦路溪行，呈陆中丞',a:'孟郊〔唐代〕',c:'鸦路不可越，三十六渡溪。有物饮碧水，高林挂青蜺。\n历览道更险，驱使迹频暌。视听易常主，心魂互相迷。\n浪石忽摇动，沙堤信难跻。危峰紫霄外，古木浮云齐。\n出阻望汝郡，大贤多招携。疲马恋旧秣，羁禽思故栖。\n应怜泣楚玉，弃置如尘泥。'},
    {t:'呀鹘行',a:'杜甫〔唐代〕',c:'病鹘孤飞俗眼丑，每夜江边宿衰柳。\n清秋落日已侧身，过雁归鸦错回首。\n紧脑雄姿迷所向，疏翮稀毛不可状。\n强神迷复皂雕前，俊才早在苍鹰上。\n风涛飒飒寒山阴，熊罴欲蛰龙蛇深。\n念尔此时有一掷，失声溅血非其心。'},
    {t:'烟际钟',a:'韦应物〔唐代〕',c:'隐隐起何处，迢迢送落晖。苍茫随思远，萧散逐烟微。\n秋野寂云晦，望山僧独归。'},
    {t:'严君平卜肆',a:'岑参〔唐代〕',c:'君平曾卖卜，卜肆芜已久。至今杖头钱，时时地上有。\n不知支机石，还在人间否。'},
    {t:'严郑公宅同咏竹',a:'杜甫〔唐代〕',c:'绿竹半含箨，新梢才出墙。\n色侵书帙晚，阴过酒樽凉。\n雨洗娟娟净，风吹细细香。\n但令无翦伐，会见拂云长。'},
    {t:'颜杲卿',a:'文天祥〔宋代〕',c:'常山义旗奋，范阳哽喉咽。\n胡雏一狼狈，六飞入西川。\n哥舒降且拜，公舌膏戈鋋。\n人世谁不死，公死千万年。'},
    {t:'掩役夫张进骸',a:'柳宗元〔唐代〕',c:'生死悠悠尔，一气聚散之。\n偶来辱喜怒，奄忽已复辞。\n为役孰贱辱？为贵非神奇。\n一朝纩息定，枯告无妍蚩。\n生平勤皂枥，锉秣不告疲。\n既死给槥椟，葬之东山基。\n奈何值崩湍，荡析临路垂。\n髐然暴百骸，散乱不复支。\n从者幸告余，眷之涓然悲。\n猫虎获迎祭，犬马有盖帷。\n伫立唁尔魂，岂复识此为？\n畚锸载埋瘗，沟渎护其危。\n我心得所安，不谓尔有知。\n掩骼著春令，兹焉值其时。\n及物非吾事，聊且顾尔私。'},
    {t:'眼儿媚·林下闺房世罕俦',a:'纳兰性德〔清代〕',c:'林下闺房世罕俦，偕隐足风流。今来忍见，鹤孤华表，人远罗浮。\n中年定不禁哀乐，其奈忆曾游。浣花微雨，采菱斜日，欲去还留。'},
    {t:'眼儿媚·咏红姑娘',a:'纳兰性德〔清代〕',c:'骚屑西风弄晚寒，翠袖倚阑干。故绡裹处，樱唇微绽，靺鞨红殷。\n故宫事往凭谁问，无恙是朱颜。玉墀争采，玉钗争插，至正年间。'},
    {t:'眼儿媚·咏梅',a:'纳兰性德〔清代〕',c:'莫把琼花比淡妆，谁似白霓裳。别样清幽，自然标格，莫近东墙。\n冰肌玉骨天分付，兼付与凄凉。可怜遥夜，冷烟和月，疏影横窗。'},
    {t:'眼儿媚·中元夜有感',a:'纳兰性德〔清代〕',c:'手写香台金字经，惟愿结来生。莲花漏转，杨枝露滴，想鉴微诚。\n欲知奉倩神伤极，凭诉与秋擎。西风不管，一池萍水，几点荷灯。'},
    {t:'彦通以诗送石菖蒲，和谢之',a:'杨万里〔宋代〕',c:'笑拂孤芳旋汲泉。忽如身堕晓霜天。\n一生寒瘦知何用，只得清名垂万年。'},
    {t:'艳歌',a:'佚名〔两汉〕',c:'今日乐上乐，相从步云衢。\n天公出美酒，河伯出鲤鱼。\n青龙前铺席，白虎持榼壶。\n南斗工鼓瑟，北斗吹笙竽。\n妲娥垂明珰，织女奉瑛琚。\n苍霞扬东讴，清风流西歈。\n垂露成帏幄，奔星扶轮舆。'},
    {t:'艳歌行',a:'佚名〔两汉〕',c:'翩翩堂前燕，冬藏夏来见。\n兄弟补三人，流宕在他县。\n故衣谁当补，新衣谁当绽？\n赖得贤主人，览取为吾绽。\n夫婿从门来，斜柯西北眄。\n语卿且勿眄，水清石自见。\n石见何累累，远行不如归。'},
    {t:'宴包二融宅',a:'孟浩然〔唐代〕',c:'闲居枕清洛，左右接大野。门庭无杂宾，车辙多长者。\n是时方盛夏，风物自潇洒。五日休沐归，相携竹林下。\n开襟成欢趣，对酒不能罢。烟暝栖鸟迷，余将归白社。'},
    {t:'宴春源',a:'王昌龄〔唐代〕',c:'源向春城花几重，江明深翠引诸峰。\n与君醉失松溪路，山馆寥寥传暝钟。'},
    {t:'宴崔明府宅夜观妓',a:'孟浩然〔唐代〕',c:'画堂观妙妓，长夜正留宾。烛吐莲花艳，妆成桃李春。\n髻鬟低舞席，衫袖掩歌唇。汗湿偏宜粉，罗轻讵著身。\n调移筝柱促，欢会酒杯频。倘使曹王见，应嫌洛浦神。'},
    {t:'宴郭校书，因之有别',a:'高适〔唐代〕',c:'彩服趋庭训，分交载酒过。芸香名早著，蓬转事仍多。\n苦战知机息，穷愁奈别何。云霄莫相待，年鬓已蹉跎。'},
    {t:'宴郭校书因之有别',a:'高适〔唐代〕',c:'綵服趋庭训，分交载酒过。芸香名早著，蓬转事仍多。\n苦战知机息，穷愁奈别何。云霄莫相待，年鬓已蹉跎。'},
    {t:'宴胡楚真禁所',a:'陈子昂〔唐代〕',c:'人生固有命，天道信无言。\n青蝇一相点，白璧遂成冤。\n请室闲逾邃，幽庭春未暄。\n寄谢韩安国，何惊狱吏尊。'},
    {t:'宴客词',a:'张籍〔唐代〕',c:'上客不用顾金羁，主人有酒君莫违。请君看取园中花，\n地上渐多枝上稀。山头树影不见石，溪水无风应更碧。\n人人齐醉起舞时，谁觉翻衣与倒帻。明朝花尽人已去，\n此地独来空绕树。'},
    {t:'宴南亭',a:'王昌龄〔唐代〕',c:'寒江映村林，亭上纳鲜洁。楚客共闲饮，静坐金管阕。\n酣竟日入山，暝来云归穴。城楼空杳霭，猿鸟备清切。\n物状如丝纶，上心为予决。访君东溪事，早晚樵路绝。'},
    {t:'宴清都·中吕',a:'周邦彦〔宋代〕',c:'地僻无钟鼓。残灯灭，夜长人倦难度。寒吹断梗，风翻暗雪，洒窗填户。宾鸿谩说传书，算过尽、千俦万侣。始信得、庾信愁多，江淹恨极须赋。\n凄凉病损文园，徽弦乍拂，音韵先苦。淮山夜月，金城暮草，梦魂飞去。秋霜半入清镜，叹带眼、都移旧处。更久长、不见文君，归时认否。'},
    {t:'宴荣二山池',a:'孟浩然〔唐代〕',c:'甲第开金穴，荣期乐自多。\n枥嘶支遁马，池养右军鹅。\n竹引携琴入，花邀载酒过。\n山公来取醉，时唱接篱歌。'},
    {t:'宴散',a:'白居易〔唐代〕',c:'小宴追凉散，平桥步月回。\n笙歌尽院落，灯火下楼台。\n残暑蝉催尽，新秋雁戴来。\n将何还睡兴，临卧举残杯。'},
    {t:'宴桃源·前度小花静院',a:'白居易〔唐代〕',c:'前度小花静院，不比寻常时见。见了又还休，愁却等闲分散。肠断，肠断，记取钗横鬓乱。'},
    {t:'宴桃源·书赵伯充家上姬领巾',a:'黄庭坚〔宋代〕',c:'天气把人僝僽。落絮游丝时候。茶饭可曾忺，镜中赢得销瘦。生受。生受。更被养娘催绣。'},
    {t:'宴陶家亭子',a:'李白〔唐代〕',c:'曲巷幽人宅，高门大士家。\n池开照胆镜，林吐破颜花。\n绿水藏春日，青轩秘晚霞。\n若闻弦管妙，金谷不能夸。'},
    {t:'宴韦司户山亭院',a:'高适〔唐代〕',c:'人幽想灵山，意惬怜远水。习静务为适，所居还复尔。\n汲流涨华池，开酌宴君子。苔径试窥践，石屏可攀倚。\n入门见中峰，携手如万里。横琴了无事，垂钓应有以。\n高馆何沉沉，飒然凉风起。'},
    {t:'宴西楼',a:'陆游〔宋代〕',c:'西楼遗迹尚豪雄，锦绣笙箫在易空。\n万里因循成久客，一年容易又秋风。\n烛光低映珠㡚丽，酒晕徐添玉颊红。\n归路迎凉更堪爱，摩诃池上月方中。'},
    {t:'宴张别驾新齐',a:'孟浩然〔唐代〕',c:'世业传圭组，江城佐股肱。\n高斋征学问，虚薄滥先登。\n讲论陪诸子，文章得旧朋。\n士元多赏激，衰病恨无能。'},
    {t:'宴张别驾新斋',a:'孟浩然〔唐代〕',c:'世业传珪组，江城佐股肱。高斋征学问，虚薄滥先登。\n讲论陪诸子，文章得旧朋。士元多赏激，衰病恨无能。'},
    {t:'宴张记室宅',a:'孟浩然〔唐代〕',c:'甲第金张馆，门庭车骑多。家封汉阳郡，文会楚材过。\n曲岛浮觞酌，前山入咏歌。妓堂花映发，书阁柳逶迤。\n玉指调筝柱，金泥饰舞罗。宁知书剑者，岁月独蹉跎。'},
    {t:'雁',a:'杜牧〔唐代〕',c:'万里衔芦别故乡，云飞雨宿向潇湘。数声孤枕堪垂泪，\n几处高楼欲断肠。度日翩翩斜避影，临风一一直成行，\n年年辛苦来衡岳，羽翼摧残陇塞霜。'},
    {t:'雁门太守行',a:'李贺〔唐代〕',c:'黑云压城城欲摧，甲光向日金鳞开。\n角声满天秋色里，塞上燕脂凝夜紫。\n半卷红旗临易水，霜重鼓寒声不起。\n报君黄金台上意，提携玉龙为君死。'},
    {t:'滟滪堆',a:'杜甫〔唐代〕',c:'巨积水中央，江寒出水长。\n沉牛答云雨，如马戒舟航。\n天意存倾覆，神功接混茫。\n干戈连解缆，行止忆垂堂。'},
    {t:'燕歌行·并序',a:'高适〔唐代〕',c:'开元二十六年，客有从元戎出塞而还者，作《燕歌行》以示，适感征戍之事，因而和焉。\n汉家烟尘在东北，汉将辞家破残贼。\n男儿本自重横行，天子非常赐颜色。\n摐金伐鼓下榆关，旌旆逶迤碣石间。\n校尉羽书飞瀚海，单于猎火照狼山。\n山川萧条极边土，胡骑凭陵杂风雨。\n战士军前半死生，美人帐下犹歌舞。\n大漠穷秋塞草腓，孤城落日斗兵稀。\n身当恩遇常轻敌，力尽关山未解围。\n铁衣远戍辛勤久，玉箸应啼别离后。\n少妇城南欲断肠，征人蓟北空回首。\n边庭飘飖那可度，绝域苍茫无所有。\n杀气三时作阵云，寒声一夜传刁斗。\n相看白刃血纷纷，死节从来岂顾勋！\n君不见沙场征战苦，至今犹忆李将军。'},
    {t:'燕归梁',a:'晏几道〔宋代〕',c:'莲叶雨，蓼花风。秋恨几枝红。远肠收尽水溶溶。飞雁碧云中。\n衷肠事。鱼笺字。情绪年年相似。凭高双袖晚寒浓。人在月桥东。'},
    {t:'燕归梁·高平晓',a:'周邦彦〔宋代〕',c:'帘底新霜一夜浓。短烛散飞虫。曾经洛浦见惊鸿。关山隔、梦魂通。\n明星晃晃，回津路转，榆影步花骢。欲攀云驾倩西风。吹清血、寄玲珑。'},
    {t:'燕归梁·金鸭香炉起瑞烟',a:'晏殊〔宋代〕',c:'金鸭香炉起瑞烟。呈妙舞开筵。船春一曲动朱弦。斟美酒、泛觥船。\n中秋五日，风清露爽，犹是早凉天。蟠桃花发一千年。祝长寿、比神仙。'},
    {t:'燕归梁·轻蹑罗鞋掩绛绡',a:'柳永〔宋代〕',c:'轻蹑罗鞋掩绛绡。传音耗、苦相招。语声犹颤不成娇。乍得见、两魂消。\n匆匆草草难留恋。还归去、又无聊。若谐雨夕与云朝。得似个、有嚣嚣。'},
    {t:'燕归梁·双燕归飞绕画堂',a:'晏殊〔宋代〕',c:'双燕归飞绕画堂。似留恋虹梁。清风明月好时光。更何况、绮筵张。\n云衫侍女，频倾寿酒，加意动笙簧。人人心在玉炉香。庆佳会、祝延长。'},
    {t:'燕归梁·织锦裁编写意深',a:'柳永〔宋代〕',c:'织锦裁编写意深。字值千金。一回披玩一愁吟。肠成结、\n泪盈襟。\n幽欢已散前期远，无［“谬”换竖心旁］赖、是而今。密\n凭归雁寄芳音。恐冷落、\n旧时心。'},
    {t:'燕归梁·织锦裁篇写意深',a:'柳永〔宋代〕',c:'织锦裁篇写意深。字值千金。一回披玩一愁吟。肠成结、泪盈襟。\n幽欢已散前期远。无憀赖、是而今。密凭归雁寄芳音。恐冷落、旧时心。'},
    {t:'燕居即事',a:'韦应物〔唐代〕',c:'萧条竹林院，风雨丛兰折。\n幽鸟林上啼，青苔人迹绝。\n燕居日已永，夏木纷成结。\n几阁积群书，时来北窗阅。'},
    {t:'燕李录事',a:'韦应物〔唐代〕',c:'与君十五侍皇闱，晓拂炉烟上赤墀。\n花开汉苑经过处，雪下骊山沐浴时。\n近臣零落今犹在，仙驾飘飖不可期。\n此日相逢思旧日，一杯成喜亦成悲。'},
    {t:'燕诗示刘叟',a:'白居易〔唐代〕',c:'梁上有双燕，翩翩雄与雌。\n衔泥长椽间，一巢生四儿。\n四儿日夜长，索食声孜孜。\n青虫不易捕，黄知无饱期。\n觜爪虽欲敝，心力不知疲。\n须臾十来往，犹恐巢中饥。\n辛勤三十日，母瘦雏渐肥。\n喃喃教言语，一一刷毛衣。\n一旦羽翼成，引上庭树枝。\n举翅不回顾，随风四散飞。\n雌雄空中鸣，声尽呼不归。\n却入空巢里，啁啾终夜悲。\n燕燕尔勿悲，尔当返自思。\n思尔为雏日，高飞背母时。\n当时父母念，今日尔应知。'},
    {t:'燕台四首·秋',a:'李商隐〔唐代〕',c:'月浪冲天天宇湿，凉蟾落尽疏星入。\n云屏不动掩孤嚬，西楼一夜风筝急。\n欲织相思花寄远，终日相思却相怨。\n但闻北斗声回环，不见长河水清浅。\n金鱼锁断红桂春，古时尘满鸳鸯茵。\n堪悲小苑作长道，玉树未怜亡国人。\n瑶琴愔愔藏楚弄，越罗冷薄金泥重。\n帘钩鹦鹉夜惊霜，唤起南云绕云梦。\n双珰丁丁联尺素，内记湘川相识处。\n歌唇一世衔雨看，可惜馨香手中故。'},
    {t:'燕衔泥',a:'韦应物〔唐代〕',c:'衔泥燕，声喽喽，尾涎涎。秋去何所归，春来复相见。\n岂不解决绝高飞碧云里，何为地上衔泥滓。衔泥虽贱意有营，\n杏梁朝日巢欲成。不见百鸟畏人林野宿，翻遭网罗俎其肉，\n未若衔泥入华屋。燕衔泥，百鸟之智莫与齐。'},
    {t:'燕昭王',a:'陈子昂〔唐代〕',c:'南登碣石馆，遥望黄金台。\n丘陵尽乔木，昭王安在哉？\n霸图今已矣，驱马复归来。'},
    {t:'燕子来舟中作',a:'杜甫〔唐代〕',c:'湖南为客动经春，燕子衔泥两度新。\n旧入故园尝识主，如今社日远看人。\n可怜处处巢居室，何异飘飘托此身。\n暂语船樯还起去，穿花贴水益沾巾。'},
    {t:'燕子楼',a:'文天祥〔宋代〕',c:'自别张公子，婵娟不下门。\n遂令门上燕，百岁称风流。\n我游彭城门，来吊楚王阙。\n问门在何处，城足草如雪。\n蛾眉代不乏，埋没安足论。\n因何张家妾，名与山川存。\n自古皆有死，忠义长不没。\n但传美人心，不说美人色。'},
    {t:'扬雄草玄台',a:'岑参〔唐代〕',c:'吾悲子云居，寂寞人已去。\n娟娟西江月，犹照草玄处。\n精怪喜无人，睢盱藏老树。'},
    {t:'扬州地分官',a:'文天祥〔宋代〕',c:'五骑驰来号徼巡，咆哮按剑一何嗔。\n金钱买命方无语，何必豺狼骂北人。\n便当缟素驾戎车，畏贼何当畏虎如。\n看取摘星楼咫尺，可怜城下哭包胥。'},
    {t:'扬州三首',a:'杜牧〔唐代〕',c:'炀帝雷塘土，迷藏有旧楼。\n谁家唱水调，明月满扬州。\n骏马宜闲出，千金好旧游。\n喧阗醉年少，半脱紫茸裘。\n秋风放萤苑，春草斗鸡台。\n金络擎雕去，鸾环拾翠来。\n蜀船红锦重，越橐水沈堆。\n处处皆华表，淮王奈却回。\n街垂千步柳，霞映两重城。\n天碧台阁丽，风凉歌管清。\n纤腰间长袖，玉珮杂繁缨。\n柂轴诚为壮，豪华不可名。\n自是荒淫罪，何妨作帝京。'},
    {t:'扬子江',a:'文天祥〔宋代〕',c:'自通州至扬子江口，两潮可到。为避渚沙，及许浦，顾诸从行者，故绕去，出北海，然后渡扬子江。\n几日随风北海游，回从扬子大江头。\n臣心一片磁针石，不指南方不肯休。'},
    {t:'扬子津望京口',a:'孟浩然〔唐代〕',c:'北固临京口，夷山近海滨。\n江风白浪起，愁杀渡头人。'},
    {t:'阳春歌',a:'李白〔唐代〕',c:'长安白日照春空，绿杨结烟垂色风。\n披香殿前花始红，流芳发色绣户中。\n绣户中，相经过。\n飞燕皇后轻身舞，紫宫夫人绝世歌。\n圣君三万六千日，岁岁年年奈乐何。'},
    {t:'阳春曲',a:'温庭筠〔唐代〕',c:'云母空窗晓烟薄，香昏龙气凝辉阁。\n霏霏雾雨杏花天，帘外春威著罗幕。\n曲栏伏槛金麒麟，沙苑芳郊连翠茵。\n厩马何能啮芳草，路人不敢随流尘。'},
    {t:'阳关曲·答李公择',a:'苏轼〔宋代〕',c:'济南春好雪初晴。才到龙山马足轻。使君莫忘霅溪女，还作阳关肠断声。'},
    {t:'阳关曲·中秋月',a:'苏轼〔宋代〕',c:'暮云收尽溢清寒，银汉无声转玉盘。\n此生此夜不长好，明月明年何处看。'},
    {t:'阳台路·楚天晚',a:'柳永〔宋代〕',c:'楚天晚，坠冷枫败叶，疏红零乱。冒征尘、匹马驱驱，愁见水遥山远。追念少年时，正恁凤帏，倚香偎暖。嬉游惯。又岂知、前欢云雨分散。\n此际空劳回首，望帝里、难收泪眼。暮烟衰草，算暗锁、路歧无限。今宵又、依前寄宿，甚处苇村山馆。寒灯畔。夜厌厌、凭何消遣。'},
    {t:'杨白花',a:'柳宗元〔唐代〕',c:'杨白花，风吹渡江水。\n坐令宫树无颜色，摇荡春光千万里。\n茫茫晓日下长秋，哀歌未断城鸦起。'},
    {t:'杨固店',a:'岑参〔唐代〕',c:'客舍梨叶赤，邻家闻捣衣。夜来尝有梦，坠泪缘思归。\n洛水行欲尽，缑山看渐微。长安只千里，何事信音稀。'},
    {t:'杨柳八首·其二',a:'温庭筠〔唐代〕',c:'南内墙东御路旁，预知春色柳丝黄。\n杏花未肯无情思，何事行人最断肠。'},
    {t:'杨柳八首·其六',a:'温庭筠〔唐代〕',c:'两两黄鹂色似金，袅枝啼露动芳音。\n春来幸自长如线，可惜牵缠荡子心。'},
    {t:'杨柳八首·其三',a:'温庭筠〔唐代〕',c:'苏小门前柳万条，毵毵金线拂平桥。\n黄莺不语东风起，深闭朱门伴舞腰。'},
    {t:'杨柳八首·其四',a:'温庭筠〔唐代〕',c:'金缕毵毵碧瓦沟，六宫眉黛惹香愁。\n晚来更带龙池雨，半拂阑干半入楼。'},
    {t:'杨柳枝',a:'刘禹锡〔唐代〕',c:'城外春风吹酒旗，行人挥袂日西时。\n长安陌上无穷树，唯有垂杨绾别离。'},
    {t:'杨柳枝',a:'温庭筠〔唐代〕',c:'一尺深红蒙曲尘，\n天生旧物不如新。\n合欢桃核终堪恨，\n里许元来别有人。'},
    {t:'杨柳枝·馆娃宫外邺城西',a:'温庭筠〔唐代〕',c:'馆娃宫外邺城西，远映征帆近拂堤。\n系得王孙归意切，不关芳草绿萋萋。'},
    {t:'杨柳枝·织锦机边莺语频',a:'温庭筠〔唐代〕',c:'织锦机边莺语频，停梭垂泪忆征人。\n塞门三月犹萧索，纵有垂杨未觉春。'},
    {t:'杨柳枝八首·其七',a:'温庭筠〔唐代〕',c:'御柳如丝映九重，凤凰窗映绣芙蓉。\n景阳楼畔千条路，一面新妆待晓风。'},
    {t:'杨柳枝词九首·其四',a:'刘禹锡〔唐代〕',c:'金谷园中莺乱飞，铜驼陌上好风吹。\n城东桃李须臾尽，争似垂杨无限时。'},
    {t:'杨柳枝二首',a:'白居易〔唐代〕',c:'一树春风千万枝，嫩于金色软于丝。\n永丰西角荒园里，尽日无人属阿谁。\n一树衰残委泥土，双枝荣耀植天庭。\n定知玄象今春后，柳宿光中添两星。'},
    {t:'杨凝式行书',a:'黄庭坚〔宋代〕',c:'俗书只识兰亭面，欲换凡骨无金丹。\n谁知洛阳杨风子，下笔便到乌丝阑。'},
    {t:'杨叛儿',a:'李白〔唐代〕',c:'君歌杨叛儿，妾劝新丰酒。\n何许最关人，乌啼白门柳。\n乌啼隐杨花，君醉留妾家。\n博山炉中沉香火，双烟一气凌紫霞。'},
    {t:'杨叛儿其五',a:'佚名〔隋代〕',c:'欢欲见莲时，移湖安屋里。芙蓉绕床生，眠卧抱莲子。'},
    {t:'杨生青花紫石砚歌',a:'李贺〔唐代〕',c:'端州石工巧如神，踏天磨刀割紫云。\n佣刓抱水含满唇，暗洒苌弘冷血痕。\n纱帷昼暖墨花春，轻沤漂沫松麝薰。\n干腻薄重立脚匀，数寸光秋无日昏。\n圆毫促点声静新，孔砚宽顽何足云！'},
    {t:'炀帝幸江南时闻民歌',a:'佚名〔隋代〕',c:'我儿征辽东，饿死青山下。今我挽龙舟，又困随堤道。\n方今天下饥，路粮无些小。前去三千程，此身安可保。\n寒骨枕荒沙，幽魂泣烟草。悲损门内妻，望断吾家老。\n安得义男儿，焚此无主尸。引其孤魂回，负其白骨归。'},
    {t:'邀人赏蔷薇',a:'孟郊〔唐代〕',c:'蜀色庶可比，楚丛亦应无。醉红不自力，狂艳如索扶。\n丽蕊惜未扫，宛枝长更纡。何人是花侯，诗老强相呼。'},
    {t:'姚开府山池',a:'孟浩然〔唐代〕',c:'主人新邸第，相国旧池台。馆是招贤辟，楼因教舞开。\n轩车人已散，箫管凤初来。今日龙门下，谁知文举才。'},
    {t:'谣俗',a:'李贺〔唐代〕',c:'上林胡蝶小，试伴汉家君。飞向南城去，误落石榴裙。\n脉脉花满树，翾翾燕绕云。出门不识路，羞问陌头人。'},
    {t:'摇柳·一作采柳',a:'孟郊〔唐代〕',c:'弱弱本易惊，看看势难定。因风似醉舞，尽日不能正。\n时邀咏花女，笑辍春妆镜。'},
    {t:'摇落',a:'李商隐〔唐代〕',c:'摇落伤年日，羁留念远心。\n水亭吟断续，月幌梦飞沉。\n古木含风久，疏萤怯露深。\n人闲始遥夜，地迥更清砧。\n结爱曾伤晚，端忧复至今。\n未谙沧海路，何处玉山岑。\n滩激黄牛暮，云屯白帝阴。\n遥知沾洒意，不减欲分襟。'},
    {t:'瑶池',a:'李商隐〔唐代〕',c:'瑶池阿母绮窗开，黄竹歌声动地哀。\n八骏日行三万里，穆王何事不重来。'},
    {t:'瑶华乐',a:'李贺〔唐代〕',c:'穆天子，走龙媒。\n八辔冬珑逐天日，五精扫地凝云开。\n高门左右日月环，四方错镂棱层殷。\n舞霞施尾长盘珊，江澄海净神母颜。\n施红点翠照虞泉，曳云拖玉下昆山。\n列旆如松，张盖如轮。\n金风殿秋，清明发春。\n八銮十乘，矗如云屯。\n琼钟瑶席甘露文，玄霜绛雪何足云，薰梅染柳将赠君。\n铅华之水洗君骨，与君相对作真质。'},
    {t:'瑶瑟怨',a:'温庭筠〔唐代〕',c:'冰簟银床梦不成，碧天如水夜云轻。\n雁声远过潇湘去，十二楼中月自明。'},
    {t:'瑶台聚八仙·为焦云隐赋',a:'张炎〔宋代〕',c:'春树江东。吟正远、清气竟入崆峒。问余栖处，只在缥缈山中。此去山中何所有，芰荷制了集芙蓉。且扶筇。倦游万里，独对青松。\n行藏也须在我，笑晋人为菊，出岫方浓。淡然无心，古意且许谁同。飞符夜深润物，自呼起苍龙雨太空。舒还卷，看满楼依旧，霁日光风。'},
    {t:'瑶台聚八仙·为野舟赋',a:'张炎〔宋代〕',c:'带雨春潮。人不渡、沙外晓色迢遥。自横深静，谁见隔柳停桡。知我知鱼未是乐，转篷闲趁白鸥招。任风飘。夜来酒醒，何处江皋。\n泛宅浮家更好，度菰蒲影里，濯足吹箫。坐阅千帆，空竞万里波涛。他年五湖访隐，第一是吴淞第四桥。玄真子、共游烟水，人月俱高。'},
    {t:'瑶台聚八仙·屋上青山',a:'张炎〔宋代〕',c:'千岩竞秀澄江之山，崒嵂清丽，奔驶相触，自北而东，由东而南，笑人应接不暇，其秀气之所钟欤。\n屋上青山。青未了、凌虚试一凭阑。乱峰叠嶂，无限古色苍寒。正喜云闲云又去，片云未识我心闲。对林峦。底须谢屐，何用跻攀。\n三十六梯眺远，任半空笑语，飞落人间。赋笔吟笺，尘事竟不相关。朝来自然气爽，更好是秋屏宜晚看。蓬壶里，有天开图画，休唤边鸾。'},
    {t:'瑶台聚八仙·咏鸳鸯菊',a:'张炎〔宋代〕',c:'老圃堪嗟。深夜雨、紫英犹傲霜华。暖宿篱根，飞去想怯寒沙。采摘浮杯如戏水，晚香淡似夜来些。背风斜。翠苔径里，描绣人夸。\n白头共开笑口，看试妆满插，云髻双丫。蝶也休愁，不是旧日疏葩。连枝愿为比翼，问因甚寒城独自花。悠然意，对九江山色，还醉陶家。'},
    {t:'药转',a:'李商隐〔唐代〕',c:'郁金堂北画楼东，换骨神方上药通。\n露气暗连青桂苑，风声偏猎紫兰丛。\n长筹未必输孙皓，香枣何劳问石崇。\n忆事怀人兼得句，翠衾归卧绣帘中。'},
    {t:'耶溪泛舟',a:'孟浩然〔唐代〕',c:'落景余清辉，轻桡弄溪渚。\n澄明爱水物，临泛何容与。\n白首垂钓翁，新妆浣纱女。\n相看似相识，脉脉不得语。'},
    {t:'耶溪泛舟①',a:'孟浩然〔唐代〕',c:'落景余清晖，轻桡弄溪渚。②\n泓澄爱水物，临泛何容与。③\n白首垂钓翁，新妆浣纱女。\n看看未相识，脉脉不得语。④'},
    {t:'野次听元昌奏横吹',a:'韦应物〔唐代〕',c:'立马莲塘吹横笛，微风动柳生水波。\n北人听罢泪将落，南朝曲中怨更多。'},
    {t:'野歌',a:'李贺〔唐代〕',c:'鸦翎羽箭山桑弓，仰天射落衔芦鸿。\n麻衣黑肥冲北风，带酒日晚歌田中。\n男儿屈穷心不穷，枯荣不等嗔天公。\n寒风又变为春柳，条条看即烟濛濛。'},
    {t:'野居',a:'张籍〔唐代〕',c:'贫贱易为适，荒郊亦安居。端坐苗馀思，弥乐古人书。\n秋田多良苗，野水多游鱼。我苗耒与网，安我充廪厨。\n寒天白日短，檐下暖我躯。四肢暂宽柔，中肠郁不舒。\n多病减志气，为客足忧虞。况复苦时节，览景独踟蹰。'},
    {t:'野居书情',a:'韦应物〔唐代〕',c:'世事日可见，身名良蹉跎。尚瞻白云岭，聊作负薪歌。'},
    {t:'野菊',a:'李商隐〔唐代〕',c:'苦竹园南椒坞边，微香冉冉泪心心。\n已悲节物同寒雁，忍委芳心与暮蝉。\n细路独来当此夕，清尊相伴省他年。\n紫云新苑移花处，不取霜栽近御筵。'},
    {t:'野菊',a:'杨万里〔宋代〕',c:'未与骚人当糗粮，况随流俗作重阳。\n政缘在野有幽色，肯为无人减妙香。\n已晚相逢半山碧，便忙也折一枝黄。\n花应冷笑东篱族，犹向陶翁觅宠光。'},
    {t:'野老',a:'杜甫〔唐代〕',c:'野老篱前江岸回，柴门不正逐江开。\n渔人网集澄潭下，贾客船随返照来。\n长路关心悲剑阁，片云何意傍琴台。\n王师未报收东郡，城阙秋生画角哀。'},
    {t:'野老歌',a:'张籍〔唐代〕',c:'老农家贫在山住，耕种山田三四亩。\n苗疏税多不得食，输入官仓化为土。\n岁暮锄犁傍空室，呼儿登山收橡实。\n西江贾客珠百斛，船中养犬长食肉。'},
    {t:'野人送朱樱',a:'杜甫〔唐代〕',c:'西蜀樱桃也自红，野人相赠满筠笼。\n数回细写愁仍破，万颗匀圆讶许同。\n忆昨赐沾门下省，退朝擎出大明宫。\n金盘玉箸无消息，此日尝新任转蓬。'},
    {t:'野色',a:'范仲淹〔宋代〕',c:'非烟亦非雾，幂幂映楼台。\n白鸟忽点破，残阳还照开。\n肯随芳草歇，疑逐远帆来。\n谁会山公意？登高醉始回。'},
    {t:'野寺后池寄友',a:'张籍〔唐代〕',c:'佛寺连野水，池幽夏景清。繁木荫芙蕖，时有水禽鸣。\n通溪岸暂断，分渚流复萦。伴僧钟磬罢，月来池上明。\n友人竟不至，东北见高城。独游自寂寞，况此恨盈盈。'},
    {t:'野望',a:'杜甫〔唐代〕',c:'西山白雪三城戍，南浦清江万里桥。\n海内风尘诸弟隔，天涯涕泪一身遥。\n惟将迟暮供多病，未有涓埃答圣朝。\n跨马出郊时极目，不堪人事日萧条。'},
    {t:'夜',a:'杜甫〔唐代〕',c:'露下天高秋水清，空山独夜旅魂惊。\n疏灯自照孤帆宿，新月犹悬双杵鸣。\n南菊再逢人卧病，北书不至雁无情。\n步檐倚仗看牛斗，银汉遥应接凤城。'},
    {t:'夜半',a:'李商隐〔唐代〕',c:'三更三点万家眠，露欲为霜月堕烟。\n斗鼠上堂蝙蝠出，玉琴时动倚窗弦。'},
    {t:'夜半乐·冻云黯淡天气',a:'柳永〔宋代〕',c:'冻云黯淡天气，扁舟一叶，乘兴怒江渚。渡万壑千岩，越溪深处。怒涛渐息，樵风乍起，更闻商旅南呼。片帆高举。泛画鹢、翩翩过南浦。\n望中酒旆闪闪，一簇烟村，数行霜树。残日下，渔人鸣榔归去。败荷零落，衰杨掩映，岸边两两三三，浣纱游女。避行客、含羞笑南语。\n到此因念，绣阁轻抛，浪萍难驻。叹后约丁宁竟何据。惨怒怀，空恨岁晚归期阻。凝泪眼、杳杳神京路。断鸿声远长天暮。'},
    {t:'夜半乐·艳阳天气',a:'柳永〔宋代〕',c:'艳阳天气，烟细风暖，芳郊澄朗舞凝伫。渐妆点亭台，参差佳树。舞腰困力，垂杨绿映，浅桃秾李双双，嫩红无数。度绮燕、流莺斗双语。\n翠娥南陌簇簇，蹑影红阴，缓移娇步。抬粉面、韶容花光相妒。绛绡袖举。云鬟风颤，半遮檀口含羞，背人偷顾。竞斗草、金钗笑争赌。\n对此嘉景，顿觉消凝，惹成愁绪。念解佩、轻盈在何处。忍良时、孤负少年等舞度。空望极、回首斜阳暮。叹浪萍风梗知何去。'},
    {t:'夜别韦司士',a:'高适〔唐代〕',c:'高馆张灯酒复清，夜钟残月雁归声。\n只言啼鸟堪求侣，无那春风欲送行。\n黄河曲里沙为岸，白马津边柳向城。\n莫怨他乡暂离别，知君到处有逢迎。'},
    {t:'夜别筵',a:'元稹〔唐代〕',c:'夜长酒阑灯花长，灯花坐地复坐床。似我别泪三四行，\n滴君满坐之衣裳。与君别后泪痕在，年年著衣心莫改。'},
    {t:'夜潮',a:'文天祥〔宋代〕',c:'雨恶风狞夜色浓，潮头如屋打孤蓬。\n漂零行路丹心苦，梦里一声何处鸿。'},
    {t:'夜到渔家',a:'张籍〔唐代〕',c:'渔家在江口，潮水入柴扉。\n行客欲投宿，主人犹未归。\n竹深村路远，月出钓船稀。\n遥见寻沙岸，春风动草衣。'},
    {t:'夜读兵书',a:'陆游〔宋代〕',c:'孤灯耿霜夕，穷山读兵书。\n平生万里心，执戈王前驱。\n战死士所有，耻复守妻孥。\n成功亦邂逅，逆料政自疏。\n陂泽号饥鸿，岁月欺贫儒。\n叹息镜中面，安得长肤腴。'},
    {t:'夜渡湘水',a:'孟浩然〔唐代〕',c:'客舟贪利涉，闇里渡湘川。\n露气闻芳杜，歌声识采莲。\n榜人投岸火，渔子宿潭烟。\n行侣时相问，浔阳何处边？'},
    {t:'夜对流萤作',a:'韦应物〔唐代〕',c:'月暗竹亭幽，萤光拂席流。\n还思故园夜，更度一年秋。\n自惬观书兴，何惭秉烛游。\n府中徒冉冉，明发好归休。'},
    {t:'夜发分宁寄杜涧叟',a:'黄庭坚〔宋代〕',c:'阳关一曲水东流，灯火旌阳一钓舟。\n我自只如常日醉，满川风月替人愁。'},
    {t:'夜飞鹊',a:'张炎〔宋代〕',c:'为明月明年佳话云。\n林霏散浮暝，河汉空云，都缘水国秋清。绿房一夜迎向晓，海影飞落寒冰。蓬莱在何处，但危峰缥缈，玉籁无声。文箫素约，料相逢、依旧花阴。\n登眺尚余佳兴，零露下衣襟，欲醉还醒。明月明年此夜，颉颃万里，同此阴晴。霓裳梦断，到如今、不许人听。正婆娑桂底，谁家弄笛，风起潮生。'},
    {t:'夜飞鹊·别情',a:'周邦彦〔宋代〕',c:'河桥送人处，凉夜何其。斜月远堕余辉。铜盘烛泪已流尽，霏霏凉露沾衣。相将散离会，探风前津鼓，树杪参旗。华骢会意，纵扬鞭、亦自行迟。\n迢递路回清野，人语渐无闻，空带愁归。何意重经前地，遗钿不见，斜迳都迷。兔葵燕麦，向残阳、欲与人齐。但徘徊班草，欷歔酹酒，极望天西。'},
    {t:'夜飞鹊道宫别情',a:'周邦彦〔宋代〕',c:'河桥送人处，良夜何其？斜月远堕余辉。铜盘烛泪已流尽，霏霏凉露沾衣。\n相将散离会，探风前津鼓，树杪参旗。花骢会意，纵扬鞭、亦自行迟。\n迢递路回清野，人语渐无闻，空带愁归。何意重经前地，遗钿不见，斜径都迷。\n兔葵燕麦，向残阳、欲与人齐。但徘徊班草，欷歔酹酒，极望天涯。'},
    {t:'夜感自遣',a:'孟郊〔唐代〕',c:'夜学晓未休，苦吟神鬼愁。\n如何不自闲，心与身为雠。\n死辱片时痛，生辱长年羞。\n清桂无直枝，碧江思旧游。'},
    {t:'夜歌',a:'韩愈〔唐代〕',c:'静夜有清光，闲堂仍独息。念身幸无恨，志气方自得。\n乐哉何所忧，所忧非我力。'},
    {t:'夜归鹿门山歌',a:'孟浩然〔唐代〕',c:'山寺钟鸣昼已昏，渔梁渡头争渡喧。\n人随沙岸向江村，余亦乘舟归鹿门。\n鹿门月照开烟树，忽到庞公栖隐处。\n岩扉松径长寂寥，惟有幽人自来去。'},
    {t:'夜过康录事造会兄弟',a:'皎然〔唐代〕',c:'爱君门馆夜来清，琼树双枝是弟兄。\n月在诗家偏足思，风过客位更多情。'},
    {t:'夜过杨州二首',a:'杨万里〔宋代〕',c:'新晴残冻未全销，月恋冰河雪恋桥。\n两岸红灯成白昼，杨州腊月看元宵。'},
    {t:'夜合花',a:'纳兰性德〔清代〕',c:'阶前双夜合，枝叶敷花荣。\n疏密共晴雨，卷舒因晦明。\n影随筠箔乱，香杂水沉生。\n对此能销忿，旋移迎小楹。'},
    {t:'夜看牡丹',a:'温庭筠〔唐代〕',c:'高低深浅一阑红，把火殷勤绕露丛。\n希逸近来成懒病，不能容易向春风。'},
    {t:'夜来乐',a:'李贺〔唐代〕',c:'红罗复帐金流苏，华灯九枝悬鲤鱼。丽人映月开铜铺，\n春水滴酒猩猩沽。重一箧，香十株，赤金瓜子兼杂麸。\n五丝封青凫，阿侯此笑千万馀。南轩汉转帘影疏，\n桐林哑哑挟子乌。剑崖鞭节青石珠，白騧吹湍凝霜须。\n漏长送珮承明庐，倡楼嵯峨明月孤。新客下马故客去，\n绿蝉秀黛重拂梳。'},
    {t:'夜冷',a:'李商隐〔唐代〕',c:'树绕池宽月影多，村砧坞笛隔风萝。\n西亭翠被馀香薄，一夜将愁向败荷。'},
    {t:'夜偶诗客操公作',a:'韦应物〔唐代〕',c:'尘襟一潇洒，清夜得禅公。远自鹤林寺，了知人世空。\n惊禽翻暗叶，流水注幽丛。多谢非玄度，聊将诗兴同。'},
    {t:'夜泊旅望',a:'白居易〔唐代〕',c:'少睡多愁客，中宵起望乡。\n沙明连浦月，帆白满船霜。\n近海江弥阔，迎秋夜更长。\n烟波三十宿，犹未到钱唐。'},
    {t:'夜泊牛渚，趁薛八船不及',a:'孟浩然〔唐代〕',c:'星罗牛渚夕，风退鹢舟迟。浦溆尝同宿，烟波忽间之。\n榜歌空里失，船火望中疑。明发泛潮海，茫茫何处期。'},
    {t:'夜泊牛渚怀古',a:'李白〔唐代〕',c:'牛渚西江夜，青天无片云。\n登舟望秋月，空忆谢将军。\n余亦能高咏，斯人不可闻。\n明朝挂帆席，枫叶落纷纷。'},
    {t:'夜泊水村',a:'陆游〔宋代〕',c:'腰间羽箭久凋零，太息燕然未勒铭。\n老子犹堪绝大漠，诸君何至泣新亭。\n一身报国有万死，双鬓向人无再青。\n记取江湖泊船处，卧闻新雁落寒汀。'},
    {t:'夜起二绝',a:'文天祥〔宋代〕',c:'三年独立已成僧，欲与何人说葛藤。\n夜夜隔墙囚叫佛，三生因果伴孤灯。'},
    {t:'夜宿东渚放歌三首',a:'杨万里〔宋代〕',c:'前山欺我船兀兀，结约江妃行定谲。\n乘我船摇忽远逃，见我船定还孤出。\n老夫敢与山争强，受侮不可更禁当。\n醉立船头看到夕，不知山於何许藏。'},
    {t:'夜宿黑灶溪',a:'张籍〔唐代〕',c:'夜到碧溪里，无人秋月明。逢幽更移宿，取伴亦探行。\n花下红泉色，云西乳鹤声。明朝记归处，石上自书名。'},
    {t:'夜宿山寺',a:'李白〔唐代〕',c:'危楼高百尺，手可摘星辰。\n不敢高声语，恐惊天上人。'},
    {t:'夜望',a:'韦应物〔唐代〕',c:'南楼夜已寂，暗鸟动林间。不见城郭事，沉沉唯四山。'},
    {t:'夜闻觱篥',a:'杜甫〔唐代〕',c:'夜闻觱篥沧江上，衰年侧耳情所向。\n邻舟一听多感伤，塞曲三更欻悲壮。\n积雪飞霜此夜寒，孤灯急管复风湍。\n君知天地干戈满，不见江湖行路难。'},
    {t:'夜闻歌者',a:'白居易〔唐代〕',c:'夜泊鹦鹉洲，秋江月澄澈。\n邻船有歌者，发调堪愁绝。\n歌罢继以泣，泣声通复咽。\n寻声见其人，有妇颜如雪。\n独倚帆樯立，娉婷十七八。\n夜泪似真珠，双双堕明月。\n借问谁家妇，歌泣何凄切？\n一问一沾襟，低眉终不说。'},
    {t:'夜闻秋风感怀',a:'陆游〔宋代〕',c:'西风一夜号庭树，起揽戎衣泪溅襟。\n残角声催关月堕，断鸿影隔塞云深。\n数篇零落从军作，一寸凄凉报国心。\n莫倚壮图思富贵，英豪何限死山林。'},
    {t:'夜闻子规',a:'朱熹〔宋代〕',c:'幽林欲雨气含凄，春晚端居园径迷。独向高斋展衾卧，南山夜夜子规啼。'},
    {t:'夜下征虏亭',a:'李白〔唐代〕',c:'船下广陵去，月明征虏亭。\n山花如绣颊，江火似流萤。'},
    {t:'夜闲·此后并悼亡',a:'元稹〔唐代〕',c:'感极都无梦，魂销转易惊。风帘半钩落，秋月满床明。\n怅望临阶坐，沉吟绕树行。孤琴在幽匣，时迸断弦声。'},
    {t:'夜雪',a:'白居易〔唐代〕',c:'已讶衾枕冷，复见窗户明。\n夜深知雪重，时闻折竹声。'},
    {t:'夜宴谣',a:'温庭筠〔唐代〕',c:'长钗坠发双蜻蜓，碧尽山斜开画屏。\n虬须公子五侯客，一饮千钟如建瓴。\n鸾咽奼唱圆无节，眉敛湘烟袖回雪。\n清夜恩情四座同，莫令沟水东西别。\n亭亭蜡泪香珠残，暗露晓风罗幕寒。\n飘飖戟带俨相次，二十四枝龙画竿。\n裂管萦弦共繁曲，芳樽细浪倾春醁。\n高楼客散杏花多，脉脉新蟾如瞪目。'},
    {t:'夜宴左氏庄',a:'杜甫〔唐代〕',c:'林风纤月落，衣露净琴张。\n暗水流花径，春星带草堂。\n检书烧烛短，看剑引杯长。\n诗罢闻吴咏，扁舟意不忘。'},
    {t:'夜吟',a:'陆游〔宋代〕',c:'六十余年妄学诗，功夫深处独心知。\n夜来一笑寒灯下，始是金丹换骨时。'},
    {t:'夜饮',a:'李商隐〔唐代〕',c:'卜夜容衰鬓，开筵属异方。\n烛分歌扇泪，雨送酒船香。\n江海三年客，乾坤百战场。\n谁能辞酩酊，淹卧剧清漳。'},
    {t:'夜饮',a:'元稹〔唐代〕',c:'灯火隔帘明，竹梢风雨声。诗篇随意赠，杯酒越巡行。\n漫唱江朝曲，闲征药草名。莫辞终夜饮，朝起又营营。'},
    {t:'夜饮朝眠曲',a:'李贺〔唐代〕',c:'觞酣出座东方高，腰横半解星劳劳。\n柳苑鸦啼公主醉，薄露压花蕙园气。\n玉转湿丝牵晓水，熟粉生香琅玕紫。\n夜饮朝眠断无事，楚罗之帏卧皇子。'},
    {t:'夜饮以白糖嚼梅花',a:'杨万里〔宋代〕',c:'剪雪作梅只堪嗅，点蜜如霜新可口。\n一花自可咽一杯，嚼尽寒花几杯酒。\n先生清贫似饥蚊，馋涎流到瘦胫根。\n赣江压糖白於玉，好伴梅花聊当囱。'},
    {t:'夜忧',a:'孟郊〔唐代〕',c:'岂独科斗死，所嗟文字捐。蒿蔓转骄弄，菱荇减婵娟。\n未遂摆鳞志，空思吹浪旋。何当再霖雨，洗濯生华鲜。'},
    {t:'夜游宫',a:'秦观〔宋代〕',c:'何事东君又去。空满院、落花飞伊。巧燕呢喃向人语。何曾解、说伊家、些子苦。况是伤心绪。念个人、又成暌阻。一觉相思梦回处。连宵雨、更那堪、闻杜宇。'},
    {t:'夜游宫',a:'周邦彦〔宋代〕',c:'一阵斜风横雨。薄衣润、新添金缕。不谢铅华更清素。倚筠窗，弄么弦，娇欲语。\n小阁横香雾。正年少、小娥愁绪。莫是栽花被花妒。甚春来，病恹恹，无会处。'},
    {t:'夜游宫·般涉·第二',a:'周邦彦〔宋代〕',c:'客去车尘未敛。古帘暗、雨苔千点。月皎风清在处见。奈今宵，照初弦，吹一箭。\n池曲河声转。念归计，眼迷魂乱。明日前村更荒远。且开尊，任红鳞，生酒面。'},
    {t:'夜游宫·宫词',a:'陆游〔宋代〕',c:'独夜寒侵翠被。奈幽梦、不成还起。欲写新愁泪溅纸。忆承恩，叹余生，今至此。\n蔌蔌灯花坠。问此际、报人何事。咫尺长门过万里。恨君心，似危栏，难久倚。'},
    {t:'夜游宫·记梦寄师伯浑',a:'陆游〔宋代〕',c:'雪晓清笳乱起。梦游处、不知何地。铁骑无声望似水。想关河，雁门西，青海际。\n睡觉寒灯里。漏声断、月斜窗纸。自许封侯在万里。有谁知，鬓虽残，心未死。'},
    {t:'夜游宫·叶下斜阳照水',a:'周邦彦〔宋代〕',c:'叶下斜阳照水。卷轻浪、沈沈千里。桥上酸风射眸子。立多时，看黄昏，灯火市。\n古屋寒窗底。听几片、井桐飞坠。不恋单衾再三起。有谁知，为萧娘，书一纸。'},
    {t:'夜雨',a:'白居易〔唐代〕',c:'我有所念人，隔在远远乡。\n我有所感事，结在深深肠。\n乡远去不得，无日不瞻望。\n肠深解不得，无夕不思量。\n况此残灯夜，独宿在空堂。\n秋天殊未晓，风雨正苍苍。\n不学头陀法，前心安可忘。'},
    {t:'夜雨',a:'杜牧〔唐代〕',c:'九月三十日，雨声如别秋。无端满阶叶，共白几人头。\n点滴侵寒梦，萧骚著淡愁。渔歌听不唱，蓑湿棹回舟。'},
    {t:'夜雨',a:'元稹〔唐代〕',c:'水怪潜幽草，江云拥废居。雷惊空屋柱，电照满床书。\n竹瓦风频裂，茅檐雨渐疏。平生沧海意，此去怯为鱼。'},
    {t:'夜雨二首其二',a:'朱熹〔宋代〕',c:'故山风雪深寒夜，只有梅花独自香。此日无人问消息，不应憔悴损年芳。'},
    {t:'夜雨二首其一',a:'朱熹〔宋代〕',c:'拥衾独宿听寒雨，声在荒庭竹树间。万里故园今夜永，遥知风雪满前山。'},
    {t:'夜雨寄北',a:'李商隐〔唐代〕',c:'君问归期未有期，巴山夜雨涨秋池。\n何当共剪西窗烛，却话巴山夜雨时。'},
    {t:'夜筝',a:'白居易〔唐代〕',c:'紫袖红弦明月中，自弹自感暗低容。\n弦凝指咽声停处，别有深情一万重。'},
    {t:'夜直',a:'王安石〔宋代〕',c:'金炉香尽漏声残，翦翦轻风阵阵寒。\n春色恼人眠不得，月移花影上栏干。'},
    {t:'夜直省中',a:'韦应物〔唐代〕',c:'河汉有秋意，南宫生早凉。玉漏殊杳杳，云阙更苍苍。\n华灯发新焰，轻烟浮夕香。顾迹知为忝，束带愧周行。'},
    {t:'夜走',a:'文天祥〔宋代〕',c:'鲸波万里送归舟，倏忽惊心欲白头。\n何处赭衣操剑戟，同时黄帽理兜鍪。\n人间风雨真成梦，夜半江山总是愁。\n雁荡双峰片云隔，明朝蹑屩作清游。'},
    {t:'夜坐',a:'文天祥〔宋代〕',c:'淡烟枫叶路，细雨蓼花时。\n宿雁半江画，寒蛩四壁诗。\n少年成老大，吾道付逶迤。\n终有剑心在，闻鸡坐欲驰。'},
    {t:'夜坐吟',a:'李白〔唐代〕',c:'冬夜夜寒觉夜长，沉吟久坐坐北堂。\n冰合井泉月入闺，金缸青凝照悲啼。\n金缸灭，啼转多。掩妾泪，听君歌。\n歌有声，妾有情。情声合，两无违。\n一语不入意，从君万曲梁尘飞。'},
    {t:'夜坐吟',a:'李贺〔唐代〕',c:'踏踏马蹄谁见过？眼看北斗直妾河。\n西风罗幕生翠波，铅华笑妾颦青娥。\n为君起唱长相思，帘外严霜皆倒飞。\n明星灿灿东方陲，红霞稍出东南涯，陆郎去矣乘斑骓。'},
    {t:'谒焦炼师',a:'王昌龄〔唐代〕',c:'中峰青苔壁，一点云生时。岂意石堂里，得逢焦炼师。\n炉香净琴案，松影闲瑶墀。拜受长年药，翩翻西海期。'},
    {t:'谒金门',a:'张炎〔宋代〕',c:'晚晴薄。一片杏花零落。纵是东风浑未恶。二分春过却。\n可怪寒生池阁。下了重重帘幕。忽见旧巢还是错。燕归何处著。'},
    {t:'谒金门',a:'晏几道〔宋代〕',c:'溪声急。无数落花漂出。燕子分菲蜂酿蜜。迟迟艳风日。\n须信芳菲随失。况复佳期难必。拟把此情书万一。愁多翻阁笔。'},
    {t:'谒金门·春又老',a:'王安石〔宋代〕',c:'春又老。南陌酒香梅小。遍地落花浑不扫。梦回情意悄。\n红笺寄与添烦恼。细写相思多少！醉后几行书字小。泪痕都揾了。'},
    {t:'谒金门·风丝袅',a:'纳兰性德〔清代〕',c:'风丝袅，水浸碧天清晓。一镜湿云青未了，雨晴春草草。\n梦里轻螺谁扫，帘外落花红小。独睡起来情悄悄，寄愁何处好。'},
    {t:'谒金门·秋感',a:'苏轼〔宋代〕',c:'今夜雨。断送一年残暑。坐听潮声来别浦。明朝何处去。\n孤负金尊绿醑。来岁今宵圆否。酒醒梦回愁几许。夜阑还独语。'},
    {t:'谒金门·秋露坠',a:'晏殊〔宋代〕',c:'秋露坠，滴尽楚兰红泪。往事旧欢何限意，思量如梦寐。\n人貌老于前岁，风月宛然无异。座有嘉宾尊有桂，莫辞终夕醉。'},
    {t:'谒金门·秋兴',a:'苏轼〔宋代〕',c:'秋池阁。风傍晓庭帘幕。霜叶未衰吹未落。半惊鸦喜鹊。\n自笑浮名情薄。似与世人疏略。一片懒心双懒脚。好教闲处著。'},
    {t:'谒金门·秋夜',a:'苏轼〔宋代〕',c:'秋帷里。长漏伴人无寐。低玉枕凉轻绣被。一番秋气味。\n晓色又侵窗纸。窗外鸡声初起。声断几声还到耳。已明声未已。'},
    {t:'谒金门·示知命弟',a:'黄庭坚〔宋代〕',c:'山又水，行尽吴头楚尾。兄弟灯前家万里，相看如梦寐。\n君似成蹊桃李，入我草堂松桂。莫厌岁寒无气味，余生今已矣。'},
    {t:'谒山',a:'李商隐〔唐代〕',c:'从来系日乏长绳，水去云回恨不胜。\n欲就麻姑买沧海，一杯春露冷如冰。'},
    {t:'谒璿上人',a:'王维〔唐代〕',c:'少年不足言，识道年已长。事往安可悔，馀生幸能养。\n誓从断臂血，不复婴世网。浮名寄缨珮，空性无羁鞅。\n夙承大导师，焚香此瞻仰。颓然居一室，覆载纷万象。\n高柳早莺啼，长廊春雨响。床下阮家屐，窗前筇竹杖。\n方将见身云，陋彼示天壤。一心在法要，愿以无生奖。'},
    {t:'谒禹庙',a:'秦观〔宋代〕',c:'阴阴古殿注修廊，海伯川露俨在傍。\n一代衣冠埋石窆，千年风雨锁梅梁。\n碧云暮合稽山暗，红芰秋开监水香。\n令我免鱼繇帝力，恨无歌舞奠椒浆。'},
    {t:'谒柱山会禅师',a:'刘禹锡〔唐代〕',c:'我本山东人，平生多感慨。弱冠游咸京，上书金马外。\n结交当世贤，驰声溢四塞。勉修贵及早，狃捷不知退。\n锱铢扬芬馨，寻尺招瑕颣。淹留郢南都，摧颓羽翰碎。\n安能咎往事，且欲去沉痗。吾师得真如，寄在人寰内。\n哀我堕名网，有如翾飞辈。曈曈揭智烛，照使出昏昧。\n静见玄关启，歆然初心会。夙尚一何微，今得信可大。\n觉路明证入，便门通忏悔。悟理言自忘，处屯道犹泰。\n色身岂吾宝，慧性非形碍。思此灵山期，未卜何年载。'},
    {t:'一百五日夜对月',a:'杜甫〔唐代〕',c:'无家对寒食，有泪如金波。\n斫却月中桂，清光应更多。\n仳离放红蕊，想像嚬青娥。\n牛女漫愁思，秋期犹渡河。'},
    {t:'一丛花',a:'陆游〔宋代〕',c:'仙姝天上自无双。玉面翠蛾长。黄庭读罢心如水，闭朱户、愁近丝簧。窗明几净，闲临唐帖，深炷宝奁香。\n人间无药驻流光。风雨又催凉。相逢共话清都旧，叹尘劫、生死茫茫。何如伴我，绿蓑青箬，秋晚钓潇湘。'},
    {t:'一丛花·初春病起',a:'苏轼〔宋代〕',c:'今年春浅腊侵年，冰雪破春妍。东风有信无人见，露微意、柳际花边。寒夜纵长，孤衾易暖，钟鼓渐清圆。\n朝来初日半衔山，楼阁淡疏烟。游人便作寻芳计，小桃杏、应已争先。衰病少悰，疏慵自放，惟爱日高眠。'},
    {t:'一丛花·年时今夜见师师',a:'秦观〔宋代〕',c:'年时今夜见师师，双颊酒红滋。疏帘半卷微灯外，露华上、烟袅凉飔。簪髻乱抛，偎人不起，弹泪唱新词。\n佳期谁料久参差。愁绪暗萦丝。想应妙舞清歌罢，又还对、秋色嗟咨。惟有画楼，当时明月，两处照相思。'},
    {t:'一丛花·咏并蒂莲',a:'纳兰性德〔清代〕',c:'阑珊玉佩罢霓裳，相对绾红妆。藕丝风送凌波去，又低头、软语商量。一种情深，十分心苦，脉脉背斜阳。\n色香空尽转生香，明月小银塘。桃根桃叶终相守，伴殷勤、双宿鸳鸯。菰米漂残，沉云乍黑，同梦寄潇湘。'},
    {t:'一寸金·井络天开',a:'柳永〔宋代〕',c:'井络天开，剑岭云横控西夏。地胜异、锦里风流，蚕市繁华，簇簇歌台舞榭。雅俗多游赏，轻裘俊、靓妆艳冶。当春昼，摸石江边，浣花溪畔景如画。\n梦应三刀，桥名万里，中和政多暇。仗汉节、揽辔澄清。高掩武侯勋业，文翁风化。台鼎须贤久，方镇静、又思命驾。空遗爱，两蜀三川，异日成嘉话。'},
    {t:'一寸金·小石江路',a:'周邦彦〔宋代〕',c:'州夹苍崖，下枕江山是城郭。望海霞接日，红翻水面，晴风吹草，青摇山脚。波暖凫鹥作。沙痕退、夜潮正落。疏林外、一点炊烟，渡口参差正寥廓。\n自叹劳生，经年何事，京华信漂泊。念渚蒲汀柳，空归闲梦，风轮雨楫，终辜前约。情景牵心眼，流连处、利名易薄。回头谢、冶叶倡条，便入渔钓乐。'},
    {t:'一萼红·倚阑干',a:'张炎〔宋代〕',c:'倚阑干。问绿华何事，偷饵九还丹。浣锦溪边，餐霞竹里，翠袖不倚天寒。照芳树、晴光泛晓，护么凤、无处认冰颜。露洗春腴，风摇醉魄，听笛江南。树挂珊瑚冷月，叹玉奴妆褪，仙掾诗悭。谩觅花云，不同梨梦，推篷恍记孤山。步夜雪、前村问酒，几消凝、把做杏花看。得似古桃流水，不到人间。'},
    {t:'一壶歌五首·其二',a:'陆游〔宋代〕',c:'先生醉后即高歌，千古英雄奈我何？\n花底一壶天所破，不曾饮尽不曾多。'},
    {t:'一壶歌五首·其三',a:'陆游〔宋代〕',c:'自从轩昊到隋唐，几见中原作战场！\n三十万年如电掣，不曾记得不曾忘。'},
    {t:'一壶歌五首·其四',a:'陆游〔宋代〕',c:'耻从岳牧立尧庭，况见商周战血腥。\n携得一壶闲处饮，不曾苦醉不曾醒。'},
    {t:'一壶歌五首·其五',a:'陆游〔宋代〕',c:'长安市上醉春风，乱插繁花满帽红。\n看尽人间兴废事，不曾富贵不曾穷。'},
    {t:'一斛珠',a:'周邦彦〔宋代〕',c:'葺金细弱。秋风嫩、桂花初著。蕊翠宫里人难学。花染娇荑，羞映翠云幄。\n清香不与兰荪弱。一枝云鬓巧梳掠。夜凉轻撼蔷薇萼。香满衣襟，月在凤凰阁。'},
    {t:'一斛珠·洛城春晚',a:'苏轼〔宋代〕',c:'洛城春晚。垂杨乱掩红楼半。小离轻浪纹如篆。烛下花前，曾醉离歌宴。\n自惜风流云雨散。关山有限情无限。待君重见寻芳伴。为说相思，目断西楼燕。'},
    {t:'一斛珠·秋闺',a:'秦观〔宋代〕',c:'碧云寥廓。倚阑怅望情离索。悲秋自怯罗衣薄。晓镜空悬，懒把青丝掠。\n江山满眼今非昨。纷纷木叶风中落。别巢燕子辞帘幕。有意东君，故把红丝缚。'},
    {t:'一剪梅·记得同烧此夜香',a:'辛弃疾〔宋代〕',c:'记得同烧此夜香，人思回廊，月思回廊。而今独自睚昏黄，行也思量，坐也思量。\n锦字都来三两行，千断人肠，万断人肠。雁儿何处是仙乡？来也恓惶，去也恓惶。'},
    {t:'一剪梅·漠漠春阴酒半酣',a:'佚名〔宋代〕',c:'漠漠春阴酒半酣。风透春衫，雨透春衫。人家蚕事欲眠三。桑满筐篮，柘满筐篮。\n先自离怀百不堪。樯燕呢喃，梁燕呢喃。篝灯强把锦书看。人在江南，心在江南。'},
    {t:'一剪梅·一剪梅花万样娇',a:'周邦彦〔宋代〕',c:'一剪梅花万样娇。斜插梅枝，略点眉梢。轻盈微笑舞低回，何事尊前，拍手相招。\n夜渐寒深酒渐消。袖里时闻，玉钏轻敲。城头谁恁促残更，银漏何如，且慢明朝。'},
    {t:'一剪梅·游蒋山呈叶丞相',a:'辛弃疾〔宋代〕',c:'独立苍茫醉不归。日暮天寒，归去来兮。探梅踏雪几何时。今我来思，杨柳依依。\n白石冈头曲岸西。一片闲愁，芳草萋萋。多情山鸟不须啼。桃李无言，下自成蹊。'},
    {t:'一剪梅·中秋无月',a:'辛弃疾〔宋代〕',c:'忆对中秋丹桂丛，花纱杯中，乘纱杯中。今宵楼上一尊同，云湿纱栊，雨湿纱栊。\n浑欲乘风问化工，路也难通，信也难通。满堂唯有烛花红，杯且从容，歌且从容。'},
    {t:'一翦梅·闷蕊惊寒减艳痕',a:'张炎〔宋代〕',c:'闷蕊惊寒减艳痕。蜂也消魂。蝶也消魂。醉归无月傍黄昏。知是花村。知是前村。\n留得闲枝叶半存。好似桃根。不似桃根。小楼昨夜雨声浑。春到三分。秋到三分。'},
    {t:'一络索·过尽遥山如画',a:'纳兰性德〔清代〕',c:'过尽遥山如画。短衣匹马。萧萧是木不胜秋，莫回首、斜阳下。\n别是柔肠萦挂。待归才罢。却愁拥髻向灯前，说不尽、离人话。'},
    {t:'一络索·长城',a:'纳兰性德〔清代〕',c:'野火拂云微绿，西风夜哭。苍茫雁翅列秋空，忆写向、屏山曲。\n山海几经翻覆，女墙斜矗。看来费尽祖龙心，毕竟为、谁家筑。'},
    {t:'一落索',a:'陆游〔宋代〕',c:'识破浮生虚妄。从人讥谤。此身恰似弄潮儿，曾过了、千重浪。\n且喜归来无恙。一壶春酿。雨蓑烟笠傍渔矶，应不是、封侯相。'},
    {t:'一落索·眉共春山争秀',a:'周邦彦〔宋代〕',c:'眉共春山争秀。可怜长皱。莫将清泪湿花枝，恐花也、如人瘦。\n清润玉箫闲久。知音稀有，欲知日日倚阑愁，但问取、亭前柳。'},
    {t:'一落索·双调·第二',a:'周邦彦〔宋代〕',c:'杜宇思归声苦。和春催去。倚阑一霎酒旗风，任扑面、桃花雨。目断陇云江树。难逢尺素。落霞隐隐日平西，料想是、分携处。'},
    {t:'一落索·杨花终日空飞舞',a:'秦观〔宋代〕',c:'杨花终日空飞舞，奈久长难驻。海潮虽是暂时来，却有个、堪凭处。\n紫府碧云为路。好相将归去。肯如薄幸五更风，不解与、花为主。'},
    {t:'一片',a:'李商隐〔唐代〕',c:'一片非烟隔九枝，蓬峦仙仗俨云旗。\n天泉水暖龙吟细，露畹春多凤舞迟。\n榆荚散来星斗转，桂华寻去月轮移。\n人间桑海朝朝变，莫遣佳期更后期。'},
    {t:'一七令·茶',a:'元稹〔唐代〕',c:'茶。\n香叶，嫩芽。\n慕诗客，爱僧家。\n碾雕白玉，罗织红纱。\n铫煎黄蕊色，碗转曲尘花。\n夜后邀陪明月，晨前独对朝霞。\n洗尽古今人不倦，将知醉后岂堪夸。'},
    {t:'一七令·诗',a:'白居易〔唐代〕',c:'诗，\n绮美，瑰奇。\n明月夜，落花时。\n能助欢笑，亦伤别离。\n调清金石怨，吟苦鬼神悲。\n天下只应我爱，世间惟有君知。\n自从都尉别苏句，便到司空送白辞。'},
    {t:'一枝春·为陆浩斋赋梅南',a:'张炎〔宋代〕',c:'竹外横枝，并阑干、试数风才一知。么禽对语，仿佛醉眠初醒。遥知是雪，甚都把、暮寒消尽。清更阁。明月飞来，瘦却旧时疏影。\n东阁谩撩诗兴。料西湖树老，难认和靖。晴窗自好，胜事每来独领。融融向暖，笑尘世、万花犹冷。须酿成、一点春腴，暗香在鼎。'},
    {t:'一字至七字诗',a:'白居易〔唐代〕',c:'诗。\n绮美，瑰奇。\n明月夜，落花时。\n能助欢笑，亦伤别离。\n调清金石怨，吟苦鬼神悲。\n天下只应我爱，世间唯有君知。\n自从都尉别苏句，便到司空送白辞。'},
    {t:'伊州歌',a:'王维〔唐代〕',c:'清风明月苦相思，荡子从戎十载馀。\n征人去日殷勤嘱，归雁来时数附书。'},
    {t:'衣带赞',a:'文天祥〔宋代〕',c:'吾位居将相，不能救社稷，正天下，军败国辱，为囚虏，其当死久矣。倾被执以来，欲引决而无间，今天与之机，谨南向百拜以死。其赞曰“孔曰成仁，孟曰取义。惟其义尽，所以仁至。读圣贤书，所学何事？而今而后，庶几无愧。”宋丞相文天祥绝笔。'},
    {t:'医者',a:'秦观〔宋代〕',c:'块然一气初浑沦，散作六物相物吞。\n主承客御胜复存，是为万物疾病原。\n寥寥空陂游冤魂，诲烦法术成轩辕。\n金书玉册要不烦，焕如星宿不可扪。\n时迁圣徂遂幽昏，弊俗窃以资利源。\n余尝感概期明论，世无妙质孰与言。\n因君乞诗置屋轩，聊复援笔赋本根。'},
    {t:'依韵酬邠州通判王稷太博',a:'范仲淹〔宋代〕',c:'南豳日日接英标，公外追随岂待招。\n恶劝酒时图共醉，痛赢棋处肯相饶。\n一抛言笑如何遣，频得音书似不遥。\n独上西楼为君久，满城明月会云销。'},
    {t:'依韵酬池州钱绮翁',a:'范仲淹〔宋代〕',c:'天涯彼此勿冲冲，内乐何须位更崇。\n白发监州身各健，青山绕郭景多同。\n日高窗外眠方起，月到樽前宴未终。\n况在江南佳丽地，重阳犹见牡丹红。'},
    {t:'依韵酬府判庞醇之见寄',a:'范仲淹〔宋代〕',c:'二十年前已定交，而今鹏鷃各逍遥。\n但能贾傅亲前席，何必萧生意本朝。\n直节羡君如指佞，孤根怜我异凌霄。\n莫将富贵移平昔，彼此清心发半凋。\n吴门歉岁减繁华，萧索专城未足夸。\n柳色向秋迎使馆，水声终夜救田车。\n丘山在负思朝寄，毫发经心愧道家。\n不似桐庐人事少，子陵台畔乐无涯。'},
    {t:'依韵酬光化李简夫屯田',a:'范仲淹〔宋代〕',c:'老来难得旧交游，莫叹樽前两退秋。少日苦辛名共立，晚年恬退语相投。\n龚黄政事聊牵强，元白邻封且唱酬。附郭田园能置否，与君乘健早归休。'},
    {t:'依韵酬黄灏秀才',a:'范仲淹〔宋代〕',c:'再贬鄱川信不才，子规相爱劝归来。\n客心但感江山助，天意难期日月回。\n白雪孤琴弥冷淡，浮云双阙自崔嵬。\n南方岁晏犹能乐，醉尽黄花见早梅。'},
    {t:'依韵酬李光化见寄',a:'范仲淹〔宋代〕',c:'南阳偃息养衰颜，天暖风和近楚关。\n欲少祸时当止足，得无权处始安闲。\n心怜好鸟来幽院，目送微云过别山。\n此景此情聊自慰，是非何极任循环。'},
    {t:'依韵酬李光化叙怀',a:'范仲淹〔宋代〕',c:'列宿专城且自娱，清名善最即前涂。\n江山乐国诚难会，风月诗家的不辜。\n未必晚成轮早达，好将高笑代长吁。\n公馀更励经邦业，思为清朝赞禹谟。'},
    {t:'依韵酬太傅张相公见赠',a:'范仲淹〔宋代〕',c:'出处曾无致主功，南阳为守地朝雄。\n醉醒往日惭渔父，得失今朝圆塞翁。\n七里河边归带月，百花洲上啸生风。\n卧龙乡曲多贤达，愿预逍遥九老中。'},
    {t:'依韵酬吴安道学士见寄',a:'范仲淹〔宋代〕',c:'圣君贤相正弥纶，谏诤臣微敢狥身。\n但得葵心长向日，何妨驽足未离尘。\n岂辞云水三千里，犹济疮痍十万民。\n宴坐黄堂愧无恨，陇头元是带经人。'},
    {t:'依韵酬叶道卿中秋对月二首',a:'范仲淹〔宋代〕',c:'孤光千里与君逢，最爱无云四望通。\n处处楼台竞歌宴，的能爱月几人同。'},
    {t:'依韵酬章推官见赠',a:'范仲淹〔宋代〕',c:'姑苏从古号繁华，却恋岩边与水涯。重入白云寻钓濑，更随明月宿诗家。\n山人惊戴乌纱出，溪女笑偎红杏遮。来蚤又抛泉石去，茫茫荣利一吁嗟。'},
    {t:'依韵答胡侍郎见寄',a:'范仲淹〔宋代〕',c:'千年风采逢明主，一寸襟灵慕昔贤。\n待看朝廷兴礼让，天衢何敢斗先鞭。'},
    {t:'依韵答蒋密学见寄',a:'范仲淹〔宋代〕',c:'东南为守慰衰颜，忧事浑祛乐事还。\n鼓吹夜归湖上月，楼台晴望海中山。\n奋飞每羡冥鸿远，驰骋那惭老骥闲。\n此日共君方偃息，是非荣辱任循环。'},
    {t:'依韵答青州富资政见寄',a:'范仲淹〔宋代〕',c:'枢府当年日辇襄，隐然一柱在家堂。\n亲逢英主开前席，力与皇家正旧章。\n直道岂求安富贵，纯载惟欲助清光。\n龚黄政事追千载，齐鲁风谣及万箱。\n伟望能令中国重，奇谋曾压北方强。\n故人待看调元后，乞取优游老洛阳。'},
    {t:'依韵答王源叔忆百花洲见寄',a:'范仲淹〔宋代〕',c:'芳洲名冠古南都，最惜尘埃一点无。\n楼阁春深来海燕，池塘人静下仙凫。\n花情柳意凭谁问，月彩波光岂易图。\n汉上山公发新咏，许昌何必诧申湖。'},
    {t:'依韵奉酬晏尚书见寄',a:'范仲淹〔宋代〕',c:'徽音来景毫，盛事耸吴乡。\n上象三台照，高文五色章。\n纯如登乐府，渊若测天潢。\n寒谷春重煦，幽宫草特芳。\n感知心似血，思报鬓成霜。\n新定惭无惠，姑苏惜未康。\n尧汤馀水旱，刘白旧风光。\n北阙云霓远，南园橘柚荒。\n愿闻歌画一，敢议赋长杨。\n碌碌嘲须解，循循教弗忘。\n迹甘荣路外，情寄圣门傍。\n几托为鱼梦，江湖尚渺茫。'},
    {t:'依韵和安陆孙司谏见寄',a:'范仲淹〔宋代〕',c:'穰下故都今善藩，沃衍千里多丰年。\n孙公顷以清净化，我来代之惭二天。\n人物高传卧龙里，神仙近接弄珠川。\n汉光旧烈山河在，徘徊吊古良依然。\n二十八将固不朽，风云一代皆忠贤。\n我亦明时得君者，出处十载功不前。\n尚得州麾养衰疾，优游岂减居林泉。\n因逢故人作宴喜，琴樽风月夕不眠。\n之翰诗诗来若金石，重于我辈何其偏。\n相其直道了无悔，宁争蠖屈与鹏骞。'},
    {t:'依韵和并州郑宣徽见寄二首',a:'范仲淹〔宋代〕',c:'钱唐作守不为轻，况是全家住翠屏。\n名品久参卿士月，部封全属斗牛星。\n仁君未报头先白，故老相看眼倍青。\n最爱湖山清绝处，晚来云破雨初停。'},
    {t:'依韵和苏州蒋密学',a:'范仲淹〔宋代〕',c:'馀杭偶得借麾来，山态云情病眼开。\n此乐无涯谁可共，诗仙今日在苏台。'},
    {t:'依韵和孙之翰对雪',a:'范仲淹〔宋代〕',c:'江干往往腊不雪，今喜纷纷才意冬。\n乃知王泽寝及远，益明天意先在农。\n有年预可慰四海，大瑞且当闻九重。\n况此湖山满清思，与君交唱若为慵。'},
    {t:'依韵和提刑张太博寄梅',a:'范仲淹〔宋代〕',c:'数枝梅寄寂寥人，多谢韶华次第均。\n穰下此花留未发，待君同赏后池春。'},
    {t:'依韵和魏介之同游玉仙坛',a:'范仲淹〔宋代〕',c:'云坛共上百神清，碧坞红霞相旧明。\n幽草欲迷丹井处，乱峰依旧白云生。\n亭亭翠纛高杉矗，险险狂雷落石轰。\n待得九霄鸾鹤驭，玉书应改地仙名。'},
    {t:'依韵和延安庞龙图柳湖',a:'范仲淹〔宋代〕',c:'种柳穿湖后，延安盛可游。\n远怀塞泽国，真赏即瀛洲。\n江景来秦塞，风情属庾楼。\n刘琨增坐啸，王练斗销忧。\n秀发千丝堕，光摇匹练柔。\n双双翔乳燕，两两睡驯鸥。\n折翠赠归客，濯清招隐流。\n宴回银烛夜，吟度玉关秋。\n胜处千场醉，劳生万事浮。\n王公多雅故，思去共仙舟。'},
    {t:'猗兰操',a:'韩愈〔唐代〕',c:'兰之猗猗，扬扬其香。\n不采而佩，我兰何伤。\n今天之旋，其曷为然。\n我行四方，以日以年。\n雪霜贸贸，荠麦之茂。\n子如不伤，我不尔觏。\n荠麦之茂，荠麦之有。\n君子之伤，君子之守。'},
    {t:'欹湖',a:'王维〔唐代〕',c:'吹箫凌极浦，日暮送夫君。\n湖上一回首，山青卷白云。'},
    {t:'夷门歌',a:'王维〔唐代〕',c:'七雄雄雌犹未分，攻城杀将何救救。\n秦兵益围邯郸急，魏王不救平原君。\n公子为嬴停驷马，执人愈恭意愈下。\n亥为屠肆鼓刀人，嬴乃夷门抱关者。\n非但慷慨献良谋，意气兼将身命酬。\n向风刎颈送公子，七十老翁何所求。'},
    {t:'宜阳别元明用觞字韵',a:'黄庭坚〔宋代〕',c:'霜须八十期同老，酌我仙人九酝觞。\n明月湾头松老大，永思堂下草荒凉。\n千林风雨莺求友，万里云天雁断行。\n别夜不眠听鼠啮，非关春茗搅枯肠。'},
    {t:'贻李汤',a:'皎然〔唐代〕',c:'茅氏常论七真记，壶公爱说三山事。宁知梅福在人间，\n独为苍生作仙吏。日服丹砂骨自清，肤如冰雪心更明。\n山中玉笋是仙药，袖里素书题养生。愿随黄鹤一轻举，\n仰望青霄独延伫。平生好骏君已知，何必山阴访王许。'},
    {t:'贻友人',a:'杜牧〔唐代〕',c:'自是东西客，逢人又送人。不应相见老，只是别离频。\n度日还知暮，平生未识春。傥无迁谷分，归去养天真。'},
    {t:'移丹阳郡先游茅山作',a:'范仲淹〔宋代〕',c:'丹阳太守意何如，先谒茅卿始下车。\n展节事君三黜后，收心奉道五旬初。\n偶寻灵草逢芝圃，欲叩真关借玉书。\n不更從人问通塞，天教吏隐接山居。'},
    {t:'移居·其二',a:'陶渊明〔魏晋〕',c:'春秋多佳日，登高赋新诗。\n过门更相呼，有酒斟酌之。\n农务各自归，闲暇辄相思。\n相思则披衣，言笑无厌时。\n此理将不胜？无为忽去兹。\n衣食当须纪，力耕不吾欺。'},
    {t:'移居二首',a:'陶渊明〔魏晋〕',c:'昔欲居南村，非为卜其宅。\n闻多素心人，乐与数晨夕。\n怀此颇有年，今日从兹役。\n敝庐何必广，取足蔽床席。\n邻曲时时来，抗言谈在昔。\n奇文共欣赏，疑义相与析。\n春秋多佳日，登高赋新诗。\n过门更相呼，有酒斟酌之。\n农务各自归，闲暇辄相思。\n相思则披衣，言笑无厌时。\n此理将不胜？无为忽去兹。\n衣食当须纪，力耕不吾欺。'},
    {t:'移居静安坊，答元八郎中',a:'张籍〔唐代〕',c:'长安寺里多时住，虽守卑官不是贫。作活每常嫌费力，\n移居只是贵容身。初开井浅偏宜树，渐觉街闲省踏尘。\n更喜往还相去近，门前减却送书人。'},
    {t:'遗爱寺',a:'白居易〔唐代〕',c:'弄石临溪坐，寻花绕寺行。\n时时闻鸟语，处处是泉声。'},
    {t:'颐轩诗六首',a:'黄庭坚〔宋代〕',c:'金石不随波，松竹知岁寒。\n冥此芸芸境，回向自心观。'},
    {t:'疑梦',a:'王维〔唐代〕',c:'莫惊宠辱空忧喜，莫计恩雠浪苦辛。\n黄帝孔丘何处问，安知不是梦中身。'},
    {t:'乙丑改元开禧元日',a:'杨万里〔宋代〕',c:'开禧元祀更元正，宿两新收放晓晴。\n夜半梅花添一岁，梦中爆竹报残更。\n方知人喜天亦喜，作麽钟鸣鸡未鸣。\n老子年龄君莫问，屠苏饮了更无兄。'},
    {t:'乙卯重五诗',a:'陆游〔宋代〕',c:'重五山村好，榴花忽已繁。\n粽包分两髻，艾束著危冠。\n旧俗方储药，羸躯亦点丹。\n日斜吾事毕，一笑向杯盘。'},
    {t:'以六一泉煮双井茶',a:'杨万里〔宋代〕',c:'鹰爪新茶蟹眼汤，松风鸣雪免毫霜。\n细参六一泉中味，故有涪翁句子香。\n日铸建溪当退舍，落霞秋水梦还乡。\n何时归上滕王阁，自看风炉自煮尝。'},
    {t:'以团茶洮州绿石砚赠无咎文潜',a:'黄庭坚〔宋代〕',c:'晁子智囊可以括四海，张子笔端可以回万牛。\n自我得二士，意气倾九州。\n道山延阁委竹帛，清都太微望冕旒。\n贝宫胎寒弄明月，天网下罩一日收。\n此地要须无不有，紫皇访问富春秋。\n晁无咎，赠君越侯所贡苍玉璧，可烹玉尘试春色。\n浇君胸中过秦论，斟酌古今来活国。\n张文潜，赠君洮州绿石含风漪，能淬笔锋利如锥。\n请书元佑开皇极，第入思齐访落诗。'},
    {t:'以右军书数种赠邱十四',a:'黄庭坚〔宋代〕',c:'邱郎气如春景晴，风暄百果草木生。\n眼如霜鹘齿玉冰，拥书环坐爱窗明。\n松花泛砚摹真行，字身藏颖秀劲清，问谁学之果兰亭。\n我昔颇复喜墨卿，银勾虿尾烂箱籯，赠君铺案黏曲屏。\n小字莫作痴冻蝇，乐毅论胜遗教经。\n大字无过瘗鹤铭，官奴作草欺伯英。\n随人作计终後人，自成一家始逼真。\n卿家小女名阿潜，眉目似翁有精神。\n试留此书他日学，往往不减卫夫人。'},
    {t:'以州宅夸于乐天',a:'元稹〔唐代〕',c:'州城迥绕拂云堆，镜水稽山满眼来。\n四面常时对屏障，一家终日在楼台。\n星河似向檐前落，鼓角惊从地底回。\n我是玉皇香案吏，谪居犹得住蓬莱。'},
    {t:'蚁蝶图',a:'黄庭坚〔宋代〕',c:'胡蝶双飞得意，偶然毕命网罗。\n群蚁争数坠翼，策勋归去南柯。'},
    {t:'义犬报火警',a:'佚名',c:'城之东，民家畜一犬，甚羸。一夕，犬火卒发，延及民家。民正熟寝，犬连吠不觉。起曳其被，寝犹如始。复踞床以口附民耳大嗥，民始惊。视烟已满室，急呼妻子出，室尽烬矣。民遂谓所亲曰：“吾家贫，犬食恒不饱，不谓今日能免我四人于难也。彼日厚享其人之食，而不顾其患难者，其视为何如耶？”'},
    {t:'忆帝京·薄衾小枕凉天气',a:'柳永〔宋代〕',c:'薄衾小枕凉天气，乍觉别离滋味。展转数寒更，起了还重睡。毕竟不成眠，一夜长如岁。\n也拟待、却回征辔；又争奈、已成行计。万种思量，多方开解，只恁寂寞厌厌地。系我一生心，负你千行泪。'},
    {t:'忆东山二首',a:'李白〔唐代〕',c:'不向东山久，蔷薇几度花。\n白云还自散，明月落谁家。\n我今携谢妓，长啸绝人群。\n欲报东山客，开关扫白云。'},
    {t:'忆杭州西湖',a:'范仲淹〔宋代〕',c:'长忆西湖胜鉴湖，春波千顷绿如铺。\n吾皇不让明皇美，可赐疏狂贺老无。'},
    {t:'忆江南',a:'王安石〔宋代〕',c:'城南城北万株花，池面冰消水见沙。\n回首江南春更好，梦为蝴蝶亦还家。'},
    {t:'忆江南·宿双林禅院有感',a:'纳兰性德〔清代〕',c:'心灰尽，有发未全僧。风雨消磨生死别，似曾相识只孤檠，情在不能醒。\n摇落后，清吹那堪听。淅沥暗飘金井叶，乍闻风定又钟声，薄福荐倾城。'},
    {t:'忆江南词三首',a:'白居易〔唐代〕',c:'江南好，风景旧曾谙。日出江花红胜火，春来江水绿如蓝。能不忆江南？\n江南忆，最忆是杭州。山寺月中寻桂子，郡亭枕上看潮头。何日更重游？\n江南忆，其次忆吴宫。吴酒一杯春竹叶，吴娃双舞醉芙蓉。早晚复相逢？'},
    {t:'忆江南二首',a:'刘禹锡〔唐代〕',c:'春去也，多谢洛城人。弱柳从风亦举袂，丛兰裛露似沾巾。独坐亦含嚬。\n春去也，共惜艳阳年。犹有桃花流水上，无辞竹叶醉尊前。惟待见青天。'},
    {t:'忆旧游·登蓬莱阁',a:'张炎〔宋代〕',c:'问蓬莱何处，风月依然，万里江是。休说神仙事，便神仙纵有，即是闲人。笑我几番醒醉，石磴扫自阴。任狂客难招，采芳难赠，且自微吟。\n俯仰成陈迹，叹百年谁在，阑槛孤凭。海日生残夜，看卧龙和梦，飞入秋冥。还听水声东去，山冷不生云。正目极空寒，萧萧汉柏愁茂陵。'},
    {t:'忆旧游·过故园有感',a:'张炎〔宋代〕',c:'记凝妆倚扇，笑眼窥帘，曾款芳尊。步屟交枝径，引生香不断，流水中分。忘了牡丹名字，和露拨花根。甚杜牧重来，买栽无地，都是消魂。\n空存。断肠草，伴几折眉痕，几点啼痕。镜里芙蓉老，问如今何处，绾绿梳云。怕有旧时归燕，犹自识黄昏。待说与羁愁，遥知路隔杨柳门。'},
    {t:'忆旧游·记愁横浅黛',a:'周邦彦〔宋代〕',c:'记愁横浅黛，泪洗红铅，门掩秋宵。坠叶惊离思，听寒螿夜泣，乱雨潇潇。凤钗半脱云鬓，窗影烛光摇。渐暗竹敲凉，疏萤照晚，两地魂消。\n迢迢，问音信，道径底花阴，时认鸣镳。也拟临朱户，叹因郎憔悴，羞见郎招。旧巢更有新燕，杨柳拂河桥。但满目京尘，东风竟日吹露桃。'},
    {t:'忆旧游·寄友',a:'张炎〔宋代〕',c:'记琼筵卜夜，锦槛移春，同恼莺娇。暗水流花径，正无风院落，银烛迟销。闹枝浅压髫髻，香脸泛红潮。甚如此游情，还将乐事，轻趁冰消。\n飘零又成梦，但长歌袅袅，柳色迢迢。一叶江心冷，望美人不见，隔浦难招。认得旧时鸥鹭，重过月明桥。溯万里天风，清声谩忆何处箫。'},
    {t:'忆旧游·看方壶拥翠',a:'张炎〔宋代〕',c:'看方壶拥翠，太极垂光，积雪初晴。阊阖开黄道，正绿章封事，飞上层青。古台半压琪树，引袖拂寒星。见玉冷闲坡，金明邃宇，人往深清。\n幽寻。自来去，对华表千年，天籁无声。别有长生路，看花开花落，何处无春。露台深锁丹气，隔水唤青禽。尚记得归时，鹤衣散影都是云。'},
    {t:'忆旧游·寓毗陵有怀澄江旧友',a:'张炎〔宋代〕',c:'笑铭崖笔倦，访雪舟寒，觅里寻邻。半掩闲门草，看长松落荫，旧榻悬尘。自怜此来何事，不为忆鲈莼。但回首当年，芙蓉城里，胜友如云。\n思君。度遥夜，谩疑是梅花，檐下空巡。蝶与周俱梦，折一枝聊寄，古意殊真。渺然望极来雁，传与异乡春。尚记得行歌，阳关西出无故人。'},
    {t:'忆乐天',a:'刘禹锡〔唐代〕',c:'寻常相见意殷勤，别后相思梦更频。\n每遇登临好风景，羡他天性少情人。'},
    {t:'忆李白',a:'辛弃疾〔宋代〕',c:'当年宫殿赋昭阳，岂信人间过骨郎。\n明月入江依旧好，青山埋骨至今香。\n不寻饭颗山头伴，却趁汨罗江上狂。\n定要骑鲸归汗漫，故来濯足戏沧浪。'},
    {t:'忆临川旧游',a:'晏殊〔宋代〕',c:'仲子幽居杳蔼间，回环十亩尽林峦。\n游鱼倒泝清泉急，乳雉惊飞夕烧干。\n系马短亭乘草茁，携壶芳榭值梅酸。\n浮生莫道今如昨，曷月朋簪急此欢。'},
    {t:'忆梅',a:'李商隐〔唐代〕',c:'定定住天涯，依依向物华。\n寒梅最堪恨，常作去年花。'},
    {t:'忆闷令',a:'晏几道〔宋代〕',c:'取次临鸾匀画浅。酒醒迟来晚。多情爱惹闲愁，长黛眉低敛。\n月底相逢花不见。有深深良愿。愿期信、似月如花，须更教长远。'},
    {t:'忆齐安郡',a:'杜牧〔唐代〕',c:'平生睡足处，云梦泽南州。\n一夜风欺竹，连江雨送秋。\n格卑常汩汩，力学强悠悠。\n终掉尘中手，潇湘钓漫流。'},
    {t:'忆秦娥',a:'秦观〔宋代〕',c:'今都入楚台风。\n楚台风。萧萧瑟瑟穿帘栊。穿帘栊。沧江浩渺，绮阁玲珑。\n飘飘彩笑摇长虹。泠泠仙籁鸣虚空。鸣虚空。一阑修竹，几壑疏松。'},
    {t:'忆秦娥',a:'朱熹〔宋代〕',c:'梅花发。寒梢挂着瑶台水。瑶台水。和羹心事，履霜时节。野桥流水声鸣咽。行人立马空愁绝。空愁绝。为谁凝伫，为谁攀折。'},
    {t:'忆秦娥·初春',a:'杨万里〔宋代〕',c:'新春早。春前十日春归管。春归管。落梅如雪，野桃红小。\n老夫不管春催老。只图烂醉花前倒。花前倒。儿扶归去，醒来窗晓。'},
    {t:'忆秦娥·龙潭口',a:'纳兰性德〔清代〕',c:'山重叠。悬崖一线天疑裂。天疑裂。断碑题字，古苔横啮。\n风声雷动鸣金铁。阴森潭底蛟龙窟。蛟龙窟。兴亡满眼，旧时明月。'},
    {t:'忆秦娥·玉花骢',a:'陆游〔宋代〕',c:'玉花骢。晚街金辔声璁珑。声璁珑。闲敧乌帽，又过城东。\n富春巷陌花重重。千金沽酒酬春风。酬春风。笙歌园里，锦绣丛中。'},
    {t:'忆秦娥·云垂幕',a:'朱熹〔宋代〕',c:'云垂幕。阴风惨淡天花渺。天花渺。千林琼玖，一空鸾鹤。征车渺渺穿华薄。路迷迷路增离索。增离索。剡溪山水，碧湘楼阁。'},
    {t:'忆秦娥·长飘泊',a:'纳兰性德〔清代〕',c:'长飘泊，多愁多病心情恶。心情恶，模糊一片，强分哀乐。\n拟将欢笑排离索，镜中无奈颜非昨。颜非昨，才华尚浅，因何福薄。'},
    {t:'忆太夫人',a:'文天祥〔宋代〕',c:'三生命孤苦，万里路酸辛。\n屡险不一险，无身复有身。\n不忘圣天子，几负太夫人。\n定省今何处，新来梦寐频。'},
    {t:'忆天台',a:'皎然〔唐代〕',c:'箬溪朝雨散，云色似天台。应是东风便，吹从海上来。\n灵山游汗漫，仙石过莓苔。误到人间世，经年不早回。'},
    {t:'忆王孙·刺桐花底是儿家',a:'纳兰性德〔清代〕',c:'刺桐花底是儿家，已拆秋千未采茶。睡起重寻好梦赊。忆交加，倚著闲窗数落花。'},
    {t:'忆王孙·集句',a:'辛弃疾〔宋代〕',c:'登山临水送将归。悲莫悲兮生别离。不用登临怨落晖。昔人非。惟有年年秋雁飞。'},
    {t:'忆王孙·梦中作',a:'王安石〔宋代〕',c:'隔岸桃花红未半。枝头已有蜂儿乱。惆怅武陵人不管。清梦断。亭亭伫立春宵短。'},
    {t:'忆王孙·西风一夜剪芭蕉',a:'纳兰性德〔清代〕',c:'西风一夜剪芭蕉，满眼芳菲总寂寥。强把心情付浊醪。读离骚。洗尽秋江日夜潮。'},
    {t:'忆王孙·谢安棋墅',a:'张炎〔宋代〕',c:'争棋赌墅意欣然。心似游丝扬碧天。只为当时一著玄。笑苻坚。百万军声屐齿前。'},
    {t:'忆昔',a:'陆游〔宋代〕',c:'忆昔从戎出渭滨，壶浆马首泣车民。\n夜栖高冢占星象，昼上巢车望虏尘。\n共道功名方迫逐，岂知老病只逡巡。\n灯前抚卷空流涕，何限人间失意人。'},
    {t:'忆邢惇夫',a:'黄庭坚〔宋代〕',c:'诗到随州更老成，江山为助笔纵横。\n眼看白璧埋黄壤，何况人间父子情。'},
    {t:'忆杨十二',a:'元稹〔唐代〕',c:'去时芍药才堪赠，看却残花已度春。\n只为情深偏怆别，等闲相见莫相亲。'},
    {t:'忆元九',a:'白居易〔唐代〕',c:'渺渺江陵道，相思远不知。近来文卷里，半是忆君诗。'},
    {t:'忆远',a:'张籍〔唐代〕',c:'行人犹未有归期，万里初程日暮时。\n唯爱门前双柳树，枝枝叶叶不相离。'},
    {t:'忆远曲',a:'张籍〔唐代〕',c:'水上山沉沉，征途复绕林。途荒人行少，马迹犹可寻。\n雪中独立树，海口失侣禽。离忧如长线，千里萦我心。'},
    {t:'忆长安曲二章寄庞㴶',a:'岑参〔唐代〕',c:'东望望长安，正值日初出。\n长安不可见，喜见长安日。\n长安何处在，只在马蹄下。\n明日归长安，为君急走马。'},
    {t:'忆住一师',a:'李商隐〔唐代〕',c:'无事经年别远公，帝城钟晓忆西峰。\n炉烟销尽寒灯晦，童子开门雪满松。'},
    {t:'易二首其一',a:'朱熹〔宋代〕',c:'立卦生爻事有因，两仪四象已前陈。须知三绝韦编者，不是寻行数墨人。'},
    {t:'弈棋二首呈任公渐',a:'黄庭坚〔宋代〕',c:'偶无公事负朝暄，三百枯棋共与樽。\n坐隐不知岩穴乐，手谈胜与俗人言。\n簿书堆积尘生案，车败淹留客在门。\n战胜将骄疑必败，果然终取敌兵翻。\n偶无公事客休时，席上谈兵校两棋。\n心似蛛丝游碧落，身如蜩甲化枯枝。\n湘东与目诚甘死，天下中分尚可持。\n谁谓吾徒犹爱日，参横月落不曾知。'},
    {t:'意难忘',a:'张炎〔宋代〕',c:'辄爱叹不能已，因赋此以赠。余下有善歌而无善听，虽抑扬高下，声字相宣，倾耳者指不多屈。篱不若春蚓秋蛩，争声响于月篱烟砌间，绝无仅有。余深感于斯，为之赏音，岂亦善听者耶。\n风月吴娃。柳阴中认得，第二香车。春深妆减艳，波转影流花。莺语滑，透纹纱。有低唱人夸。怕误却，周郎醉眼，倚扇佯遮。\n底须拍碎红牙。听曲终奏雅，可是堪嗟。无人知此意，明月又谁家。尘滚滚，老年华。付情在琵琶。更叹我，黄芦苦竹，万里天涯。'},
    {t:'意难忘·衣染莺黄',a:'周邦彦〔宋代〕',c:'衣染莺黄。爱停歌驻拍，劝酒持觞。低鬟蝉影动，私语口脂香。檐露滴，竹风凉。拚剧饮淋浪。夜渐深，笼灯就月，子细端相。\n知音见说无双。解移宫换羽，未怕周郎。长颦知有恨，贪耍不成妆。些个事，恼人肠。试说与何妨。又恐伊、寻消问息，瘦减容光。'},
    {t:'因假归白阁西草堂',a:'岑参〔唐代〕',c:'雷声傍太白，雨在八九峰。\n东望白阁云，半入紫阁松。\n胜概纷满目，衡门趣弥浓。\n幸有数亩田，得延二仲踪。\n早闻达士语，偶与心相通。\n误徇一微官，还山愧尘容。\n钓竿不复把，野碓无人舂。\n惆怅飞鸟尽，南溪闻夜钟。'},
    {t:'因论·序',a:'刘禹锡〔唐代〕',c:'刘子闲居作《因论》。或问其旨曷夫欤？对曰：“因之为言有所自也。夫造端乎无形，垂训于至当，其至言之徒。放词乎无方，措旨于至适，其寓言之徒。蒙之智不逮于是，造形而有感，因感而有词，匪至匪寓，以因为目。《因论》之旨也云尔。”'},
    {t:'因省风俗访道士侄不见题壁',a:'韦应物〔唐代〕',c:'去年涧水今亦流，去年杏花今又坼。\n山人归来问是谁，还是去年行春客。'},
    {t:'阴山画虎图',a:'王安石〔宋代〕',c:'阴山健儿鞭鞚急，走势能追北风及。\n逶迤一虎出马前，白羽横穿更人立。\n回旗倒戟四边动，抽矢当前放蹄入。\n爪牙蹭蹬不得施，迹上流丹看来湿。\n胡天朔漠杀气高，烟云万里埋弓刀。\n穹庐无工可貌此，汉使自解丹青色。\n堂上绢素开欲裂，一见犹能动毛发。\n低徊使我思古人，此地抟兵走戎羯。\n禽逃兽遁亦萧然，岂若封疆今晏眠。\n契丹弋猎汉耕作，飞将自老南山边，还能射虎随少年。'},
    {t:'阴雨',a:'白居易〔唐代〕',c:'岚雾今朝重，江山此地深。\n滩声秋更急，峡气晓多阴。\n望阙云遮眼，思乡雨滴心。\n将何慰幽独，赖此北窗琴。'},
    {t:'吟白乐天哭崔儿二篇，怆然寄赠',a:'刘禹锡〔唐代〕',c:'吟君苦调我沾缨，能使无情尽下情。四望车中心未释，\n千秋亭下赋初成。庭梧已下栖雏处，池鹤今无子和声。\n从此期君比琼树，一枝吹折一枝生。'},
    {t:'银河吹笙',a:'李商隐〔唐代〕',c:'怅望银河吹玉笙，楼寒院冷接平明。\n重衾幽梦他年断，别树羁雌昨夜惊。\n月榭故香因雨发，风帘残烛隔霜清。\n不须浪作缑山意，湘瑟秦箫自有情。'},
    {t:'银山碛西馆',a:'岑参〔唐代〕',c:'银山碛口风似箭，铁门关西月沙练。\n双双愁泪沾马毛，飒飒胡沙迸人面。\n丈夫三十未富贵，安能终日守笔砚。'},
    {t:'引驾行·红尘紫陌',a:'柳永〔宋代〕',c:'红尘紫陌，斜阳暮草长安道，是离人。断魂处，迢迢匹马西征。新晴。韶光明媚，轻烟淡薄和气暖，望花村。路隐映，摇鞭时过长亭。愁生。伤凤城仙子，别来千里重行行。又记得、临歧泪眼，湿莲脸盈盈。\n消凝。花朝月夕，最苦冷落银屏。想媚容、耿耿无眠，屈指已算回程。相萦。空万般思忆，争如归去睹倾城。向绣帏、深处并枕，说如此牵情。'},
    {t:'引驾行·虹收残雨',a:'柳永〔宋代〕',c:'虹收残雨。蝉嘶败柳长堤暮。背都门、动消黯，西风片帆轻举。愁睹。泛画鹢翩翩，灵鼍隐隐下前浦。忍回首、佳人渐远，想高城、隔烟树。\n几许。秦楼永昼，谢阁连宵奇遇。算赠笑千金，酬歌百琲，尽成轻负。南顾。念吴邦越国，风烟萧索在何处。独自个、千山万水，指天涯去。'},
    {t:'饮茶歌诮崔石使君',a:'皎然〔唐代〕',c:'越人遗我剡溪茗，采得金芽爨金鼎。\n素瓷雪色缥沫香，何似诸仙琼蕊浆。\n一饮涤昏寐，情来朗爽满天地。\n再饮清我神，忽如飞雨洒轻尘。\n三饮便得道，何须苦心破烦恼。\n此物清高世莫知，世人饮酒多自欺。\n愁看毕卓瓮间夜，笑向陶潜篱下时。\n崔侯啜之意不已，狂歌一曲惊人耳。\n孰知茶道全尔真，唯有丹丘得如此。'},
    {t:'饮茶歌送郑容',a:'皎然〔唐代〕',c:'丹丘羽人轻玉食，采茶饮之生羽翼。名藏仙府世空知，\n骨化云宫人不识。云山童子调金铛，楚人茶经虚得名。\n霜天半夜芳草折，烂漫缃花啜又生。赏君此茶祛我疾，\n使人胸中荡忧栗。日上香炉情未毕，醉踏虎溪云，\n高歌送君出。'},
    {t:'饮湖上初晴后雨',a:'苏轼〔宋代〕',c:'水光潋滟晴方好，山色空蒙雨亦奇。\n欲把西湖比西子，淡妆浓抹总相宜。'},
    {t:'饮湖上初晴后雨二首·其一',a:'苏轼〔宋代〕',c:'朝曦迎客艳重冈，晚雨留人入醉乡。\n此意自佳君不会，一杯当属水仙王。'},
    {t:'饮酒',a:'柳宗元〔唐代〕',c:'今夕少愉乐，起坐开清尊。\n举觞酹先酒，为我驱忧烦。\n须臾心自殊，顿觉天地暄。\n连山变幽晦，绿水函晏温。\n蔼蔼南郭门，树木一何繁。\n清阴可自庇，竟夕闻佳言。\n尽醉无复辞，偃卧有芳荪。\n彼哉晋楚富，此道未必存。'},
    {t:'饮酒·二十',a:'陶渊明〔魏晋〕',c:'羲农去我久，举世少复真。\n汲汲鲁中叟，弥缝使其淳。\n凤鸟虽不至，礼乐暂得新，\n洙泗辍微响，漂流逮狂秦。\n诗书复何罪？一朝成灰尘。\n区区诸老翁，为事诚殷勤。\n如何绝世下，六籍无一亲。\n终日驰车走，不见所问津。\n若复不快饮，空负头上巾。\n但恨多谬误，君当恕醉人。'},
    {t:'饮酒·其八',a:'陶渊明〔魏晋〕',c:'青松在东园，众草没其姿。\n凝霜殄异类，卓然见高枝。\n连林人不觉，独树众乃奇。\n提壶抚寒柯，远望时复为。\n吾生梦幻间，何事绁尘羁。'},
    {t:'饮酒·其二',a:'陶渊明〔魏晋〕',c:'积善云有报，夷叔在西山。\n善恶苟不应，何事空立言！\n九十行带索，饥寒况当年。\n不赖固穷节，百世当谁传。'},
    {t:'饮酒·其九',a:'陶渊明〔魏晋〕',c:'清晨闻叩门，倒裳往自开。\n问子为谁与？田父有好怀。\n壶浆远见候，疑我与时乖。\n褴缕茅檐下，未足为高栖。\n一世皆尚同，愿君汩其泥。\n深感父老言，禀气寡所谐。\n纡辔诚可学，违己讵非迷。\n且共欢此饮，吾驾不可回。'},
    {t:'饮酒·其六',a:'陶渊明〔魏晋〕',c:'行止千万端，谁知非与是。\n是非苟相形，雷同共誉毁。\n三季多此事，达士似不尔。\n咄咄俗中愚，且当从黄绮。'},
    {t:'饮酒·其七',a:'陶渊明〔魏晋〕',c:'秋菊有佳色，裛露掇其英。\n泛此忘忧物，远我遗世情。\n一觞虽独尽，杯尽壶自倾。\n日入群动息，归鸟趋林鸣。\n啸傲东轩下，聊复得此生。'},
    {t:'饮酒·其三',a:'陶渊明〔魏晋〕',c:'道丧向千载，人人惜其情。\n有酒不肯饮，但顾世间名。\n所以贵我身，岂不在一生？\n一生复能几，倏如流电惊。\n鼎鼎百年内，持此欲何成！'},
    {t:'饮酒·其十',a:'陶渊明〔魏晋〕',c:'在昔曾远游，直至东海隅。\n道路迥且长，风波阻中途。\n此行谁使然？似为饥所驱。\n倾身营一饱，少许便有馀。\n恐此非名计，息驾归闲居。'},
    {t:'饮酒·其四',a:'陶渊明〔魏晋〕',c:'栖栖失群鸟，日暮犹独飞。\n徘徊远定止，夜夜声转悲。\n厉响思清远，去来何依依。\n因值孤生松，敛翮遥来归。\n劲风远荣木，此荫独不衰。\n托身已得所，千载不相违。'},
    {t:'饮酒·其五',a:'陶渊明〔魏晋〕',c:'结庐在人境，而无车马喧。\n问君何能尔？心远地自偏。\n采菊东篱下，悠然见南山。\n山气日夕佳，飞鸟相与还。\n此中有真意，欲辨已忘言。'},
    {t:'饮酒·其一',a:'陶渊明〔魏晋〕',c:'衰荣无定在，彼此更共之。\n邵生瓜田中，宁似东陵时！\n寒暑有代谢，人道每如兹。\n达人解其会，逝将不复疑。\n忽与一樽酒，日夕欢相持。'},
    {t:'饮酒·十八',a:'陶渊明〔魏晋〕',c:'子云性嗜酒，家贫无由得，\n时赖好事人，载醪祛所惑。\n觞来为之尽，是谘无不塞。\n有时不肯言，岂不在伐国。\n仁者用其心，何尝失显默。'},
    {t:'饮酒·十二',a:'陶渊明〔魏晋〕',c:'长公曾一仕，壮节忽失时；\n杜门不复出，终身与世辞。\n仲理归大泽，高风始在兹。\n一往便当已，何为复狐疑！\n去去当奚道，世俗久相欺。\n摆落悠悠谈，请从余所之。'},
    {t:'饮酒·十九',a:'陶渊明〔魏晋〕',c:'畴昔苦长饥，投耒去学仕。\n将养年得节，冻馁固缠己。\n是时向立年，志意多所耻。\n遂尽介然分，拂衣归田里，\n冉冉星气流，亭亭复一纪。\n世路廓悠悠，杨朱所以止。\n虽无挥金事，浊酒聊可恃。'},
    {t:'饮酒·十六',a:'陶渊明〔魏晋〕',c:'少年罕人事，游好在六经。\n行行向不惑，淹留遂无成。\n竟抱固穷节，饥寒饱所更。\n敝庐交悲风，荒草没前庭。\n披褐守长夜，晨鸡不肯鸣。\n孟公不在兹，终以翳吾情。'},
    {t:'饮酒·十三',a:'陶渊明〔魏晋〕',c:'有客常同止，取舍邈异境。\n年士常独醉，年夫终年醒。\n醒醉还相笑，发言各不领。\n规规年何愚，兀傲差若颖。\n寄言酣中客，日没烛当秉。'},
    {t:'饮酒·十四',a:'陶渊明〔魏晋〕',c:'故人赏我趣，挈壶相与至。\n班荆言松下，数斟已复醉。\n父老杂乱言，觞酌失行次。\n不觉知有我，安知物为贵。\n悠悠迷所留，酒中有深味。'},
    {t:'饮酒·十五',a:'陶渊明〔魏晋〕',c:'贫居乏人工，灌木荒余宅。\n班班悠翔鸟，寂寂无行迹。\n宇宙一何悠，人生少至百。\n岁月相催逼，鬓边早已白。\n若不委穷达，素抱深可惜。'},
    {t:'饮酒·十一',a:'陶渊明〔魏晋〕',c:'颜生称为仁，荣公言有道。\n屡空名获年，长饥至于老。\n虽留身后名，一生亦枯槁。\n死去何所知，称心固为好。\n客养千金躯，临化消其宝。\n裸葬何必恶，人当解意表。'},
    {t:'饮酒·幽兰生前庭',a:'陶渊明〔魏晋〕',c:'幽兰生前庭，含薰待清风。\n清风脱然至，见别萧艾中。\n行行失故路，任道或能通。\n觉悟当念还，鸟尽废良弓。'},
    {t:'饮酒诗四首',a:'秦观〔宋代〕',c:'客从南方来，酌我一瓯茗。\n我酌初不啜，强啜且复醒。\n既凿浑沌氏，遂出华胥境。\n操戈逐儒生，举觞还酩酊。'},
    {t:'饮酒诗四首其二',a:'秦观〔宋代〕',c:'左手持蟹螯，举觞属云汉。天生此神物，为我洗忧患。\n山川同恍惚，鱼鸟共萧散。客至壶自倾，欲去不容间。'},
    {t:'饮李氏园三首',a:'黄庭坚〔宋代〕',c:'手挼红杏醉繁香，回首春前梦一场。\n便与经营百船酒，再来应是菊花黄。'},
    {t:'饮马长城窟行',a:'佚名〔两汉〕',c:'青青河畔草，绵绵思远道。\n远道不可思，宿昔梦见之。\n梦见在我傍，忽觉在他乡。\n他乡各异县，辗转不相见。\n枯桑知天风，海水知天寒。\n入门各自媚，谁肯相为言？\n客从远方来，遗我双鲤鱼。\n呼儿烹鲤鱼，中有尺素书。\n长跪读素书，书中竟何如？\n上言加餐食，下言长相忆。'},
    {t:'饮新酒',a:'元稹〔唐代〕',c:'闻君新酒熟，况值菊花秋。\n莫怪平生志，图销尽日愁。'},
    {t:'饮中八仙歌',a:'杜甫〔唐代〕',c:'知章骑马似乘船，眼花落井水底眠。\n汝阳三斗始朝天，道逢麴车口流涎，恨不移封向酒泉。\n左相日兴费万钱，饮如长鲸吸百川，衔杯乐圣称避贤。\n宗之潇洒美少年，举觞白眼望青天，皎如玉树临风前。\n苏晋长斋绣佛前，醉中往往爱逃禅。\n李白斗酒诗百篇，长安市上酒家眠，\n天子呼来不上船，自称臣是酒中仙。\n张旭三杯草圣传，脱帽露顶王公前，挥毫落纸如云烟。\n焦遂五斗方卓然，高谈雄辩惊四筵。'},
    {t:'隐士',a:'孟郊〔唐代〕',c:'本末一相返，漂浮不还真。山野多馁士，市井无饥人。\n虎豹忌当道，糜鹿知藏身。奈何贪竞者，日与患害亲。\n颜貌岁岁改，利心朝朝新。孰知富生祸，取富不取贫。\n宝玉忌出璞，出璞先为尘。松柏忌出山，出山先为薪。\n君子隐石壁，道书为我邻。寝兴思其义，澹泊味始真。\n陶公自放归，尚平去有依。草木择地生，禽鸟顺性飞。\n青青与冥冥，所保各不违。'},
    {t:'隐者',a:'张籍〔唐代〕',c:'先生已得道，市井亦容身。救病自行药，得钱多与人。\n问年长不定，传法又非真。每见邻家说，时闻使鬼神。'},
    {t:'应天长·残蝉渐绝',a:'柳永〔宋代〕',c:'残蝉渐绝。傍碧砌修梧，败叶微脱。风露凄清，正是登高时节。东篱霜乍结。绽金蕊、嫩香堪折。聚宴处，落帽风流，未饶前哲。\n把酒与君说。恁好景佳辰，怎忍虚设。休效牛山，空对江天凝咽。尘劳无暂歇。遇良会、剩偷欢悦。歌声阕。杯兴方浓，莫便中辍。'},
    {t:'应天长·寒食',a:'周邦彦〔宋代〕',c:'条风布暖，霏雾弄晴，池台遍满春色。正是夜堂无月，沉沉暗寒食。梁间燕，前社客。似笑我、闭门愁寂。乱花过，隔院芸香，满地狼藉。\n长记那回时，邂逅相逢，郊外驻油壁。又见汉宫传烛，飞烟五侯宅。青青草，迷路陌。强载酒、细寻前迹。市桥远，柳下人家，犹自相识。'},
    {t:'应製赏花钓鱼',a:'范仲淹〔宋代〕',c:'万汇嘉亨日，皇心豫宴辰。\n华林新濯雨，灵沼正涵春。\n帝幄纷仙花，天钩掷锦鳞。\n洋洋颁睿唱，赓颂浃簪绅。'},
    {t:'莺莺诗·一作离思诗之首篇',a:'元稹〔唐代〕',c:'殷红浅碧旧衣裳，取次梳头暗雨妆。夜合带烟笼晓日，\n牡丹经雨泣残阳。低迷隐笑原非笑，散漫清香不似香。\n频动横波嗔阿母，等闲教见小儿郎。'},
    {t:'樱桃花',a:'元稹〔唐代〕',c:'樱桃花，一枝两枝千万朵。\n花砖曾立摘花人，窣破罗裙红似火。'},
    {t:'樱桃花下',a:'李商隐〔唐代〕',c:'流莺舞蝶两相欺，不取花芳正结时。\n他日未开今日谢，嘉辰长短是参差。'},
    {t:'鹦鹉洲',a:'李白〔唐代〕',c:'鹦鹉来过吴江水，江上洲传鹦鹉名。\n鹦鹉西飞陇山去，芳洲之树何青青。\n烟开兰叶香风暖，岸夹桃花锦浪生。\n迁客此时徒极目，长洲孤月向谁明。'},
    {t:'鹦鹉洲送王九之江左',a:'孟浩然〔唐代〕',c:'昔登江上黄鹤楼，遥爱江中鹦鹉洲。\n洲势逶迤绕碧流，鸳鸯鸂鶒满滩头。\n滩头日落沙碛长，金沙熠熠动飙光。\n舟人牵锦缆，浣女结罗裳。\n月明全见芦花白，风起遥闻杜若香。\n君行采采莫相忘。'},
    {t:'迎春花',a:'晏殊〔宋代〕',c:'浅艳侔莺羽，纖条结兔丝。\n偏凌早春发，应诮众芳迟。'},
    {t:'迎春乐·菖蒲叶叶知多少',a:'秦观〔宋代〕',c:'菖蒲叶叶知多少，惟有个、蜂儿黄。雨晴红粉齐开了，露一点、娇黄小。\n早是被、晓风力暴，更春共、斜阳俱老。怎得香香深处，作个蜂儿抱。'},
    {t:'迎春乐·近来憔悴人惊怪',a:'柳永〔宋代〕',c:'近来憔悴人惊怪。为别后、相思煞。我前生、负你愁烦债。便苦恁难开解。\n良夜永、牵情无计奈。锦被里、馀香犹在。怎得依前灯下，恣意怜娇态。'},
    {t:'迎春乐·双调',a:'周邦彦〔宋代〕',c:'清池小圃开云屋。结春伴、往来熟。忆年时、纵酒杯行速。看月上、归禽宿。\n墙里修篁森似束。记名字、曾刊新绿。见说别来长，沿翠藓、封寒玉。'},
    {t:'迎春乐·双调携妓',a:'周邦彦〔宋代〕',c:'人人花艳明春柳。忆筵上、偷携手。趁歌停舞罢来相就。醒醒个、无些酒。\n比目香囊新刺绣。连隔座、一时薰透。为甚月中归，长是他、随车后。'},
    {t:'迎春乐·桃蹊柳曲闲踪迹',a:'周邦彦〔宋代〕',c:'桃蹊柳曲闲踪迹。俱曾是、大堤胡。解春衣、贳酒城南陌。频醉卧、胡姬侧。\n鬓点吴霜嗟早白。更谁念、玉溪消息。他日水云身，相望处、无南北。'},
    {t:'迎春乐·长安紫陌春归早',a:'晏殊〔宋代〕',c:'长安紫陌春归早，亸垂杨、染芳频。被啼莺语燕催清晓。正好梦、频惊觉。\n当此际、青楼临大道。幽会处、两情多少。莫惜明珠百琲，占取长年少。'},
    {t:'迎新春·嶰管变青律',a:'柳永〔宋代〕',c:'嶰管变青律，帝里阳和新布。晴景回轻煦。庆嘉节、当三五。列华灯、千门万户。遍九陌罗绮，香风微度。十里然绛树。鳌山耸，喧天箫鼓。\n渐天如水，素月当午。香径里、绝缨掷果无数。更阑烛影花阴下，少年人、往往奇遇。太平时、朝野多欢民康阜。随分良聚。堪对此景，争忍独醒归去。'},
    {t:'萤火',a:'杜甫〔唐代〕',c:'幸因腐草出，敢近太阳飞。\n未足临书卷，时能点客衣。\n随风隔幔小，带雨傍林微。\n十月清霜重，飘零何处归。'},
    {t:'营州歌',a:'高适〔唐代〕',c:'营州少年厌原野，狐裘蒙茸猎城下。\n虏酒千钟不醉人，胡儿十岁能骑马。'},
    {t:'郢门秋怀',a:'李白〔唐代〕',c:'郢门一为客，巴月三成弦。\n朔风正摇落，行子愁归旋。\n杳杳山外日，茫茫江上天。\n人迷洞庭水，雁度潇湘烟。\n清旷谐宿好，缁磷及此年。\n百龄何荡漾，万化相推迁。\n空谒苍梧帝，徒寻溟海仙。\n已闻蓬海浅，岂见三桃圆。\n倚剑增浩叹，扪襟还自怜。\n终当游五湖，濯足沧浪泉。'},
    {t:'雍台歌',a:'温庭筠〔唐代〕',c:'太子池南楼百尺，入窗新树疏幢隔。黄金铺首画钩陈，\n羽葆停幢拂交戟。盘纡阑楯临高台，帐殿临流鸾扇开。\n早雁惊鸣细波起，映花卤簿龙飞回。'},
    {t:'慵不能',a:'白居易〔唐代〕',c:'架上非无书，眼慵不能看。\n匣中亦有琴，手慵不能弹。\n腰慵不能带，头慵不能冠。\n午后恣情寝，午时随事餐。\n一餐终日饱，一寝至夜安。\n饥寒亦闲事，况乃不饥寒。'},
    {t:'永定寺喜辟强夜至',a:'韦应物〔唐代〕',c:'子有新岁庆，独此苦寒归。\n夜叩竹林寺，山行雪满衣。\n深炉正燃火，空斋共掩扉。\n还将一尊对，无言百事违。'},
    {t:'永嘉别张子容',a:'孟浩然〔唐代〕',c:'旧国余归楚，新年子北征。挂帆愁海路，分手恋朋情。\n日夕故园意，汀洲春草生。何时一杯酒，重与季鹰倾。'},
    {t:'永嘉行',a:'张籍〔唐代〕',c:'黄头鲜卑入洛阳，胡儿执戟升明堂。\n晋家天子作降虏，公卿奔走如牛羊。\n紫陌旌幡暗相触，家家鸡犬惊上屋。\n妇人出门随乱兵，夫死眼前不敢哭。\n九州诸侯自顾土，无人领兵来护主。\n北人避胡多在南，南人至今能晋语。'},
    {t:'永王东巡歌·其八',a:'李白〔唐代〕',c:'长风挂席势难回，海动山倾古月摧。\n君看帝子浮江日，何似龙骧出峡来。'},
    {t:'永王东巡歌·其二',a:'李白〔唐代〕',c:'三川北虏乱如麻，四海南奔似永嘉。\n但用东山谢安石，为君谈笑净胡沙。'},
    {t:'永王东巡歌·其六',a:'李白〔唐代〕',c:'丹阳北固是吴关，画出楼台云水间。\n千岩烽火连沧海，两岸旌旗绕碧山。'},
    {t:'永王东巡歌·其三',a:'李白〔唐代〕',c:'雷鼓嘈嘈喧武昌，云旗猎猎过寻阳。\n秋毫不犯三吴悦，春日遥看五色光。'},
    {t:'永王东巡歌·其五',a:'李白〔唐代〕',c:'二帝巡游俱未回，五陵松柏使人哀。\n诸侯不救河南地，更喜贤王远道来。'},
    {t:'永王东巡歌·其一',a:'李白〔唐代〕',c:'永王正月东出师，天子遥分龙虎旗。\n楼船一举风波静，江汉翻为燕鹜池。'},
    {t:'永遇乐·京口北固亭怀古',a:'辛弃疾〔宋代〕',c:'千古江山，英雄无觅，孙仲谋处。去榭歌台，风流总被，雨打风吹去。斜阳草树，寻常巷陌，人道寄万曾住。想当年，金戈铁马，气吞万里如虎。\n元嘉草草，封狼居胥，赢得仓皇北顾。四十三年，望中犹记，烽火扬州路。可堪回首，佛狸祠下，一片神鸦社鼓。凭谁问：廉颇老矣，尚能饭否？'},
    {t:'永遇乐·天阁英游',a:'柳永〔宋代〕',c:'天阁英游，内朝密侍，当世荣遇。膂守分麾，尧庭请瑞，方面凭心膂。风驰千骑，云拥双旌，向晓洞竞严署。拥朱轓、喜色欢声，处处竞歌来暮。\n吴王旧国，今古江山秀异，人烟繁富。甘雨车行，仁风扇动，雅称安黎庶。棠郊成政，槐府登贤，非久定须归去。且乘闲、孙阁长竞，融尊盛举。'},
    {t:'永遇乐·投老空山',a:'辛弃疾〔宋代〕',c:'检校停云新种杉松，戏作。时欲作亲旧报书，纸笔偶为大风吹去，末章因及之。\n投老空山，万松手种，政尔堪叹。何日成阴，吾年有几，似见儿孙晚。古来池馆，云烟草棘，长使后人凄断。想当年良辰已恨，夜阑酒空人散。\n停云高处，谁知老子，万事不关心眼。梦觉东窗，聊复尔耳，起欲题书简。霎时风怒，倒翻笔砚，天也只教吾懒。又何事，催诗雨急，片云斗暗。'},
    {t:'永遇乐·薰风解愠',a:'柳永〔宋代〕',c:'薰风解愠，昼景清和，新霁时候。火德流光，萝图荐祉，累庆金枝秀。璿枢绕电，华渚流虹，是日挺生元后。缵唐虞垂拱，千载应期，万灵敷祐。\n殊方异域，争贡琛赆，架巘航波奔凑。三殿称觞，九仪就列，韶頀锵金奏。藩侯瞻望彤庭，亲携僚吏，竞歌元首。祝尧龄、北极齐尊，南山共久。'},
    {t:'永遇乐·长忆别时',a:'苏轼〔宋代〕',c:'孙巨源以八月十五日离海州，坐别于景疏楼上。既而与余会于润州，至楚州乃别。余以十一月十五日至海州，与太守会于景疏楼上，作此词以寄巨源。\n长忆别时，景疏楼上，明月如水。美酒清歌，留连不住，月随人千里。别来三度，孤光又满，冷落共谁同醉？卷珠帘、凄然顾影，共伊到明无寐。\n今朝有客，来从濉上，能道使君深意。凭仗清淮，分明到海，中有相思泪。而今何在？西垣清禁，夜永露华侵被。此时看、回廊晓月，也应暗记。'},
    {t:'咏春幡',a:'温庭筠〔唐代〕',c:'闲庭见早梅，花影为谁栽。碧烟随刃落，蝉鬓觉春来。\n代郡嘶金勒，梵声悲镜台。玉钗风不定，香步独徘徊。'},
    {t:'咏春笋',a:'杜甫〔唐代〕',c:'无数春笋满林生，柴门密掩断行人。\n会须上番看成竹，客至从嗔不出迎。'},
    {t:'咏春雪',a:'韦应物〔唐代〕',c:'裴回轻雪意，似惜艳阳时。不悟风花冷，翻令梅柳迟。'},
    {t:'咏二十四气诗·春分二月中',a:'元稹〔唐代〕',c:'二气莫交争，春分雨处行。\n雨来看电影，云过听雷声。\n山色连天碧，林花向日明。\n梁间玄鸟语，欲似解人情。'},
    {t:'咏二十四气诗·夏至五月中',a:'元稹〔唐代〕',c:'处处闻蝉响，须知五月中。\n龙潜渌水穴，火助太阳宫。\n过雨频飞电，行云屡带虹。\n蕤宾移去后，二气各西东。'},
    {t:'咏二疏',a:'陶渊明〔魏晋〕',c:'大象转四时，功成者自去。\n借问衰周来，几人得其趣？\n游目汉廷中，二疏复此举。\n高啸返旧居，长揖储君傅。\n饯送倾皇朝，华轩盈道路。\n离别情所悲，余荣何足顾！\n事胜感行人，贤哉岂常誉！\n厌厌阎里欢，所营非近务。\n促席延故老，挥觞道平素。\n问金终寄心，清言晓未悟。\n放意乐余年，遑恤身后虑！\n谁云其人亡，久而道弥著。'},
    {t:'咏桂',a:'李白〔唐代〕',c:'世人种桃李，皆在金张门。\n攀折争捷径，及此春风暄。\n一朝天霜下，荣耀难久存。\n安知南山桂，绿叶垂芳根。\n清阴亦可托，何惜树君园。'},
    {t:'咏桂',a:'杨万里〔宋代〕',c:'不是人间种，移从月中来。\n广寒香一点，吹得满山开。'},
    {t:'咏寒宵',a:'温庭筠〔唐代〕',c:'寒宵何耿耿，良宴有馀姿。宝靺徘徊处，熏炉怅望时。\n曲琼垂翡翠，斜月到罘罳。委坠金釭烬，阑珊玉局棋。\n话穷犹注睇，歌罢尚持颐。晻暖遥相属，氛氲积所思。\n秦蛾卷衣晚，胡雁度云迟。上郡归来梦，那知锦字诗。'},
    {t:'咏荷花中小莲蓬',a:'杨万里〔宋代〕',c:'山蜂愁雨损蜂儿，叶底安巢更倒垂。\n只有荷蜂不愁雨，蜡房仰卧万花枝。'},
    {t:'咏红白莲',a:'朱熹〔宋代〕',c:'红白莲花共一塘，两般颜色一般香。\n宫娥梳洗争先后，半是浓妆半淡妆。'},
    {t:'咏红柿子',a:'刘禹锡〔唐代〕',c:'晓连星影出，晚带日光悬。\n本因遗采掇，翻自保天年。'},
    {t:'咏琥珀',a:'韦应物〔唐代〕',c:'曾为老茯神，本是寒松液。\n蚊蚋落其中，千年犹可觌。'},
    {t:'咏怀',a:'文天祥〔宋代〕',c:'阴阳相烹然，天地一釜鬵。\n人生燎其间，便同肉在砧。\n热犹以火燎，湿犹以汤浔。\n一岁一煅炼，老不忽駸駸。\n吾生四十六，弱质本不任。\n矧当五六年，患难长侵寻。\n子卿羝羊节，少陵杜鹃心。\n酷罚毒我肤，深忧烦我襟。\n蹉蹉夏涉秋，天道何其淫。\n或时日杲杲，或时雨淋淋。\n方如坐蒸甑，又似立烘煁。\n水火交相禅，益热与益深。\n宛转儿戏中，日夜空呻吟。\n何如真鼎镬，殊我一寸金。\n脱此寒暑殻，谁能复岖嵚。'},
    {t:'咏怀',a:'张籍〔唐代〕',c:'老去多悲事，非唯见二毛。\n眼昏书字大，耳重觉声高。\n望月偏增思，寻山易发劳。\n都无作官意，赖得在闲曹。'},
    {t:'咏怀',a:'孟郊〔唐代〕',c:'浊水心易倾，明波兴初发。\n思逢海底人，乞取蚌中月。\n此兴若未谐，此心终不歇。'},
    {t:'咏怀二首',a:'李贺〔唐代〕',c:'长卿怀茂陵，绿草垂石井。\n弹琴看文君，春风吹鬓影。\n梁王与武帝，弃之如断梗。\n惟留一简书，金泥泰山顶。\n日夕著书罢，惊霜落素丝。\n镜中聊自笑，讵是南山期。\n头上无幅巾，苦蘗已染衣。\n不见清溪鱼，饮水得自宜。'},
    {t:'咏怀古迹五首·其二',a:'杜甫〔唐代〕',c:'摇落深知宋玉悲，风流儒雅亦吾师。\n怅望千秋一洒泪，萧条异代不同时。\n江山故宅空文藻，云雨荒台岂梦思。\n最是楚宫俱泯灭，舟人指点到今疑。'},
    {t:'咏怀古迹五首·其三',a:'杜甫〔唐代〕',c:'群山万壑赴荆门，生长明妃尚有村。\n一去紫台连朔漠，独留青冢向黄昏。\n画图省识春风面，环珮空归夜月魂。\n千载琵琶作胡语，分明怨恨曲中论。'},
    {t:'咏怀古迹五首·其四',a:'杜甫〔唐代〕',c:'蜀主窥吴幸三峡，崩年亦在永安宫。\n翠华想像空山里，玉殿虚无野寺中。\n古庙杉松巢水鹤，岁时伏腊走村翁。\n武侯祠屋常邻近，一体君臣祭祀同。'},
    {t:'咏怀古迹五首·其五',a:'杜甫〔唐代〕',c:'诸葛大名垂宇宙，宗臣遗像肃清高。\n三分割据纡筹策，万古云霄一羽毛。\n伯仲之间见伊吕，指挥若定失萧曹。\n运移汉祚终难复，志决身歼军务劳。'},
    {t:'咏怀古迹五首·其一',a:'杜甫〔唐代〕',c:'支离东北风尘际，漂泊西南天地间。\n三峡楼台淹日月，五溪衣服共云山。\n羯胡事主终无赖，词客哀时且未还。\n庾信平生最萧瑟，暮年诗赋动江关。'},
    {t:'咏蕙',a:'朱熹〔宋代〕',c:'今花得古名，旖旎香更好。\n适意欲忘言，尘编讵能老。'},
    {t:'咏槿',a:'李白〔唐代〕',c:'园花笑芳年，池草艳春色。\n犹不如槿花，婵娟玉阶侧。\n芬荣何夭促，零落在瞬息。\n岂若琼树枝，终岁长翕赩。'},
    {t:'咏荆轲',a:'陶渊明〔魏晋〕',c:'燕丹善养士，志在报强嬴。\n招集己夫良，岁暮得荆卿。\n君子死知己，提剑出燕京；\n素骥鸣广陌，慷长送我行。\n雄发指危冠，猛气冲长缨。\n饮饯易水上，四座列群英。\n渐离击悲筑，宋意唱高声。\n萧萧哀风逝，澹澹寒波生。\n商音更流涕，羽奏壮士惊。\n心知去不归，且有后世名。\n登车何时顾，飞盖入秦庭。\n凌厉越万里，逶迤过千城。\n图穷事自至，豪主正怔营。\n惜哉剑术疏，奇功遂不成。\n其人虽已没，千载有馀情。'},
    {t:'咏菊',a:'白居易〔唐代〕',c:'一夜新霜著瓦轻，芭蕉新折败荷倾。\n耐寒唯有东篱菊，金粟初开晓更清。'},
    {t:'咏郡斋壁画片云·得归字',a:'岑参〔唐代〕',c:'云片何人画，尘侵粉色微。未曾行雨去，不见逐风归。\n只怪偏凝壁，回看欲惹衣。丹青忽借便，移向帝乡飞。'},
    {t:'咏老赠梦得',a:'白居易〔唐代〕',c:'与君俱老也，自问老何如。\n眼涩出先卧，头慵朝未梳。\n有时扶杖出，尽日闭门居。\n懒照新磨镜，休看小字书。\n情于故人重，迹共少年疏。\n唯是闲谈兴，相逢尚有余。'},
    {t:'咏琉璃',a:'韦应物〔唐代〕',c:'有色同寒冰，无物隔纤尘。象筵看不见，堪将对玉人。'},
    {t:'咏笼莺',a:'纳兰性德〔清代〕',c:'何处金衣客，栖栖翠幕中。\n有心惊晓梦，无计啭春风。\n漫逐梁间燕，谁巢井上桐。\n空将云路翼，缄恨在雕笼。'},
    {t:'咏露珠',a:'韦应物〔唐代〕',c:'秋荷一滴露，清夜坠玄天。\n将来玉盘上，不定始知圆。'},
    {t:'咏马鞭',a:'高适〔唐代〕',c:'龙竹养根凡几年，工人截之为长鞭，一节一目皆天然。\n珠重重，星连连。绕指柔，纯金坚。绳不直，规不圆。\n把向空中捎一声，良马有心日驰千。'},
    {t:'咏梅',a:'王安石〔宋代〕',c:'颇怪梅花不肯开，岂知有意待春来。\n灯前玉面披香出，雪後春容取胜回。\n触拨清诗成走笔，淋漓红袖趣传杯。\n望尘俗眼那知此，只买夭桃艳杏栽。'},
    {t:'咏廿四气诗·白露八月节',a:'元稹〔唐代〕',c:'露沾蔬草白，天气转青高。\n叶下和秋吹，惊看两鬓毛。\n养羞因野鸟，为客讶蓬蒿。\n火急收田种，晨昏莫辞劳。'},
    {t:'咏廿四气诗·处暑七月中',a:'元稹〔唐代〕',c:'向来鹰祭鸟，渐觉白藏深。\n叶下空惊吹，天高不见心。\n气收禾黍熟，风静草虫吟。\n缓酌樽中酒，容调膝上琴。'},
    {t:'咏廿四气诗·大寒十二月中',a:'元稹〔唐代〕',c:'腊酒自盈樽，金炉兽炭温。\n大寒宜近火，无事莫开门。\n冬与春交替，星周月讵存。\n明朝换新律，梅柳待阳春。'},
    {t:'咏廿四气诗·大暑六月中',a:'元稹〔唐代〕',c:'大暑三秋近，林钟九夏移。\n桂轮开子夜，萤火照空时。\n菰果邀儒客，菰蒲长墨池。\n绛纱浑卷上，经史待风吹。'},
    {t:'咏廿四气诗·大雪十一月节',a:'元稹〔唐代〕',c:'积阴成大雪，看处乱霏霏。\n玉管鸣寒夜，披书晓绛帷。\n黄钟随气改，鴳鸟不鸣时。\n何限苍生类，依依惜暮晖。'},
    {t:'咏廿四气诗·冬至十一月中',a:'元稹〔唐代〕',c:'二气俱生处，周家正立年。\n岁星瞻北极，舜日照南天。\n拜庆朝金殿，欢娱列绮筵。\n万邦歌有道，谁敢动征边。'},
    {t:'咏廿四气诗·谷雨三月中',a:'元稹〔唐代〕',c:'谷雨春光晓，山川黛色青。\n叶间鸣戴胜，泽水长浮萍。\n暖屋生蚕蚁，喧风引麦葶。\n鸣鸠徒拂羽，信矣不堪听。'},
    {t:'咏廿四气诗·寒露九月节',a:'元稹〔唐代〕',c:'寒露惊秋晚，朝看菊渐黄。\n千家风扫叶，万里雁随阳。\n化蛤悲群鸟，收田畏早霜。\n因知松柏志，冬夏色苍苍。'},
    {t:'咏廿四气诗·惊蛰二月节',a:'元稹〔唐代〕',c:'阳气初惊蛰，韶光大地周。\n桃花开蜀锦，鹰老化春鸠。\n时候争催迫，萌芽互矩修。\n人间务生事，耕种满田畴。'},
    {t:'咏廿四气诗·立春正月节',a:'元稹〔唐代〕',c:'春冬移律吕，天地换星霜。\n间泮游鱼跃，和风待柳芳。\n早梅迎雨水，残雪怯朝阳。\n万物含新意，同欢圣日长。'},
    {t:'咏廿四气诗·立冬十月节',a:'元稹〔唐代〕',c:'霜降向人寒，轻冰渌水漫。\n蟾将纤影出，雁带几行残。\n田种收藏了，衣裘制造看。\n野鸡投水日，化蜃不将难。'},
    {t:'咏廿四气诗·立秋七月节',a:'元稹〔唐代〕',c:'不期朱夏尽，凉吹暗迎秋。\n天汉成桥鹊，星娥会玉楼。\n寒声喧耳外，白露滴林头。\n一叶惊心绪，如何得不愁。'},
    {t:'咏廿四气诗·立夏四月节',a:'元稹〔唐代〕',c:'欲知春与夏，仲吕启朱明。\n蚯蚓谁教出，王菰自合生。\n帘蚕呈茧样，林鸟哺雏声。\n渐觉云峰好，徐徐带雨行。'},
    {t:'咏廿四气诗·芒种五月节',a:'元稹〔唐代〕',c:'芒种看今日，螳螂应节生。\n彤云高下影，鴳鸟往来声。\n渌沼莲花放，炎风暑雨晴。\n相逢问蚕麦，幸得称人情。'},
    {t:'咏廿四气诗·清明三月节',a:'元稹〔唐代〕',c:'清明来向晚，山渌正光华。\n杨柳先飞絮，梧桐续放花。\n鴽声知化鼠，虹影指天涯。\n已识风云意，宁愁雨谷赊。'},
    {t:'咏廿四气诗·秋分八月中',a:'元稹〔唐代〕',c:'琴弹南吕调，风色已高清。\n云散飘飖影，雷收振怒声。\n乾坤能静肃，寒暑喜均平。\n忽见新来雁，人心敢不惊？'},
    {t:'咏廿四气诗·霜降九月中',a:'元稹〔唐代〕',c:'风卷清云尽，空天万里霜。\n野豺先祭月，仙菊遇重阳。\n秋色悲疏木，鸿鸣忆故乡。\n谁知一樽酒，能使百秋亡。'},
    {t:'咏廿四气诗·小寒十二月节',a:'元稹〔唐代〕',c:'小寒连大吕，欢鹊垒新巢。\n拾食寻河曲，衔柴绕树梢。\n霜鹰近北首，雊雉隐丛茅。\n莫怪严凝切，春冬正月交。'},
    {t:'咏廿四气诗·小满四月中',a:'元稹〔唐代〕',c:'小满气全时，如何靡草衰。\n田家私黍稷，方伯问蚕丝。\n杏麦修镰钐，錋欔竖棘篱。\n向来看苦菜，独秀也何为？'},
    {t:'咏廿四气诗·小暑六月节',a:'元稹〔唐代〕',c:'倏忽温风至，因循小暑来。\n竹喧先觉雨，山暗已闻雷。\n户牖深青霭，阶庭长绿苔。\n鹰鹯新习学，蟋蟀莫相催。'},
    {t:'咏廿四气诗·小雪十月中',a:'元稹〔唐代〕',c:'莫怪虹无影，如今小雪时。\n阴阳依上下，寒暑喜分离。\n满月光天汉，长风响树枝。\n横琴对渌醑，犹自敛愁眉。'},
    {t:'咏廿四气诗·雨水正月中',a:'元稹〔唐代〕',c:'雨水洗春容，平田已见龙。\n祭鱼盈浦屿，归雁过山峰。\n云色轻还重，风光淡又浓。\n向春入二月，花色影重重。'},
    {t:'咏贫士·其二',a:'陶渊明〔魏晋〕',c:'凄厉岁云暮，拥褐曝前轩。\n南圃无遗秀，枯条盈北园。\n倾壶绝馀沥，窥灶不见烟。\n诗书塞座外，日昃不遑研。\n闲居非陈厄，窃有愠见言。\n何以慰我怀，赖古多此贤。'},
    {t:'咏贫士·其三',a:'陶渊明〔魏晋〕',c:'荣叟老带索，欣然方弹琴。\n原生久决履，清歌畅商音。\n重华去我久，贫士世相寻。\n弊襟不掩肘，藜羹常乏斟。\n岂忘袭轻裘，苟得非所钦。\n赐也徒能辨，乃不见吾心。'},
    {t:'咏贫士·其四',a:'陶渊明〔魏晋〕',c:'安贫守贱者，自古有黔娄。\n好爵吾不荣，厚馈吾不酬。\n一旦寿命尽，弊服仍不周。\n岂不知其极，非道故无忧。\n从来将千载，未复见斯俦。\n朝与仁义生，夕死复何求。'},
    {t:'咏贫士·其一',a:'陶渊明〔魏晋〕',c:'万族各有托，孤云独无依。\n暧暧空中灭，何时见馀晖。\n朝霞开宿雾，众鸟相与飞。\n迟迟出林翮，未夕复来归。\n量力守故辙，岂不寒与饥？\n知音苟不存，已矣何所悲。'},
    {t:'咏贫士其六',a:'陶渊明〔魏晋〕',c:'仲蔚爱穷居，绕宅生蒿蓬。\n翳然者交游，赋诗颇能工；\n举世无知者，止有一刘龚。\n此士胡独然？实由罕所同；\n介然安其业，所乐非穷通。\n人事固以拙，聊得长相从。'},
    {t:'咏贫士其七',a:'陶渊明〔魏晋〕',c:'昔在黄子廉，弹冠佐名州。\n一朝辞吏归，清贫略难俦。\n年饥感仁妻，泣涕向我流。\n丈夫虽有志，固为儿女忧。\n惠孙一晤叹，腆赠竟莫酬。\n谁云固穷难，邈哉此前修。'},
    {t:'咏贫士其五',a:'陶渊明〔魏晋〕',c:'袁安困积雪，邈然不可干。\n阮公温钱入，即日弃其官。\n刍槁有常温，采莒足朝餐。\n岂不实辛苦，所惧非饥寒。\n贫富常交战，道胜无戚颜。\n至德冠邦闾，清节映西关。'},
    {t:'咏青',a:'王昌龄〔唐代〕',c:'雾辟天光远，春回日道临。\n草浓河畔色，槐结路旁阴。\n欲映君王史，先摽胄子襟。\n经明如何拾，自有致云心。'},
    {t:'咏三良',a:'陶渊明〔魏晋〕',c:'弹冠乘通津，但惧时我遗。\n服勤尽岁月，常恐功愈微。\n忠情谬获露，遂为君所私。\n出则陪文舆，入必侍丹帷。\n箴规响已从，计议初无亏。\n一朝长逝后，愿言同此归。\n厚恩固难忘，君命安可违！\n临穴罔惟疑，投义志攸希。\n荆棘笼高坟，黄鸟声正悲。\n良人不可赎，泫然沾我衣。'},
    {t:'咏三良',a:'柳宗元〔唐代〕',c:'束带值明后，顾盼流辉光。\n一心在陈力，鼎列夸四方。\n款款效忠信，恩义皎如霜。\n生时亮同体，死没宁分张。\n壮躯闭幽隧，猛志填黄肠。\n殉死礼所非，况乃用其良。\n霸基弊不振，晋楚更张皇。\n疾病命固乱，魏氏言有章。\n从邪陷厥父，吾欲讨彼狂。'},
    {t:'咏山鸡',a:'温庭筠〔唐代〕',c:'万壑动晴景，山禽凌翠微。绣翎翻草去，红觜啄花归。\n巢暖碧云色，影孤清镜辉。不知春树伴，何处又分飞。'},
    {t:'咏珊瑚',a:'韦应物〔唐代〕',c:'绛树无花叶，非石亦非琼。\n世人何处得，蓬莱石上生。'},
    {t:'咏声',a:'韦应物〔唐代〕',c:'万物自生听，太空恒寂寥。\n还从静中起，却向静中消。'},
    {t:'咏石榴花',a:'王安石〔宋代〕',c:'今朝五月正清和，榴花诗句入禅那。\n浓绿万枝红一点，动人春色不须多。'},
    {t:'咏史',a:'张九龄〔唐代〕',c:'大德始无颇，中智是所是。居然已不一，况乃务相诡。\n小道致泥难，巧言因萋毁。穰侯或见迟，苏生得阴揣。\n轻既长沙傅，重亦边郡徙。势倾不幸然，迹在胡宁尔。\n沧溟所为大，江汉日来委。沣水虽复清，鱼鳖岂游此。\n贤哉有小白，仇中有管氏。若人不世生，悠悠多如彼。'},
    {t:'咏史',a:'王昌龄〔唐代〕',c:'荷畚至洛阳，杖策游北门。天下尽兵甲，豺狼满中原。\n明夷方遘患，顾我徒崩奔。自惭菲薄才，误蒙国士恩。\n位重任亦重，时危志弥敦。西北未及终，东南不可吞。\n进则耻保躬，退乃为触藩。叹息嵩山老，而后知其尊。'},
    {t:'咏史',a:'柳宗元〔唐代〕',c:'燕有黄金台，远致望诸君。嗛嗛事强怨，三岁有奇勋。\n悠哉辟疆理，东海漫浮云。宁知世情异，嘉谷坐熇焚。\n致令委金石，谁顾蠢蠕群。风波欻潜构，遗恨意纷纭。\n岂不善图后，交私非所闻。为忠不顾内，晏子亦垂文。'},
    {t:'咏史',a:'李商隐〔唐代〕',c:'历览前贤国与家，成由勤俭破由奢。\n何须琥珀方为枕，岂得真珠始是车。\n运去不逢青海马，力穷难拔蜀山蛇。\n几人曾预南薰曲，终古苍梧哭翠华。'},
    {t:'咏史',a:'皎然〔唐代〕',c:'田氏门下客，冯公众中贱。一朝市义还，百代名独擅。\n始知下客不可轻，能使主人功业成。借问高车与珠履，\n何如卑贱一书生。'},
    {t:'咏史',a:'高适〔唐代〕',c:'尚有绨袍赠，应怜范叔寒。\n不知天下士，犹作布衣看。'},
    {t:'咏史二首',a:'刘禹锡〔唐代〕',c:'骠骑非无势，少卿终不去。\n世道剧颓波，我心如砥柱。\n贾生明王道，卫绾工车戏。\n同遇汉文时，何人居贵位。'},
    {t:'咏史二首·其一',a:'李商隐〔唐代〕',c:'北湖南埭水漫漫，一片降旗百尺竿。\n三百年间同晓梦，钟山何处有龙盘。'},
    {t:'咏史五首其二·有虞氏',a:'范仲淹〔宋代〕',c:'成都成邑即天开，终践尧基咏起哉。\n但得四门元凯至，九韶何必凤皇来。'},
    {t:'咏史五首其三·夏后氏',a:'范仲淹〔宋代〕',c:'景命还将伯益传，九川功大若为迁。\n讴歌终在吾君子，岂是当时不让贤。'},
    {t:'咏史五首其四·商人',a:'范仲淹〔宋代〕',c:'履癸昆吾祸莫移，应天重造帝王基。\n子孙何事为炮烙，不念嘻吁祝网时。'},
    {t:'咏史五首其五·周人',a:'范仲淹〔宋代〕',c:'斧钺为藩忍内侵，商人涂炭奈何深。\n不烦鱼火明天意，自有诸侯八百心。'},
    {t:'咏史五首其一·陶唐氏',a:'范仲淹〔宋代〕',c:'纯衣黄冕历星辰，白马彤车一百春。\n莫道茅茨无复见，古今时有致尧人。'},
    {t:'咏数探得七',a:'皎然〔唐代〕',c:'邹子谭天岁，黄童对日年。求真初作传，炼魄已成仙。\n鹤驾迎缑岭，星桥下蜀川。逢君竹林客，相对弄清弦。'},
    {t:'咏水精',a:'韦应物〔唐代〕',c:'映物随颜色，含空无表里。持来向明月，的皪愁成水。'},
    {t:'咏酥',a:'杨万里〔宋代〕',c:'似腻还成爽，才凝又欲飘。\n玉来盘底碎，雪到口边销。'},
    {t:'咏袜',a:'杜牧〔唐代〕',c:'钿尺裁量减四分，纤纤玉笋裹轻云。\n五陵年少欺他醉，笑把花前出画裙。'},
    {t:'咏蚊',a:'范仲淹〔宋代〕',c:'饱去樱桃重，饥来柳絮轻。\n但知离此去，不用问前程。'},
    {t:'咏雪',a:'辛弃疾〔宋代〕',c:'书窗夜生白，城角晓增悲。\n未奏蔡州捷，且歌梁苑诗。\n餐毡怀雁使，无酒羡羔儿。\n农事勤忧国，明年喜可知。'},
    {t:'咏雪奉呈广平公',a:'黄庭坚〔宋代〕',c:'连空春雪明如洗，忽忆江清水见沙。\n夜听疏疏还密密，晓看整整复斜斜。\n风回共作婆娑舞，天巧能开顷刻花。\n正使尽情寒至骨，不妨桃李用年华。'},
    {t:'咏岩桂二首其二',a:'朱熹〔宋代〕',c:'露浥黄金蕊，风生碧玉枝。千林向摇落，此树独华滋。\n木末难同调，篱边不并时。攀援香满袖，叹息共心期。'},
    {t:'咏岩桂二首其一',a:'朱熹〔宋代〕',c:'亭亭岩下桂，岁晚独芬芳。叶密千层绿，花开万点黄。\n天香生净想，云影护仙妆。谁识王孙意，空吟招隐章。'},
    {t:'咏燕',a:'张九龄〔唐代〕',c:'海燕何微眇，乘春亦暂来。岂知泥滓贱，祗见玉堂开。\n绣户时双入，华轩日几回。无心与物竞，鹰隼莫相猜。'},
    {t:'咏夜',a:'韦应物〔唐代〕',c:'明从何处去，暗从何处来。但觉年年老，半是此中催。'},
    {t:'咏一滴泉',a:'朱熹〔宋代〕',c:'遥望南岩百尺岗，青山叠叠树苍苍。题诗壁上云生石，入定岩前石作房。\n一窍有灵通地脉，半空无雨滴天浆。鹅湖此去无多路，肯借山间结草堂。'},
    {t:'咏敡上人座右画松',a:'皎然〔唐代〕',c:'写得长松意，千寻数尺中。翠阴疑背日，寒色欲生风。\n真树孤标在，高人立操同。一枝遥可折，吾欲问生公。'},
    {t:'咏萤火',a:'李白〔唐代〕',c:'雨打灯难灭，风吹色更明。\n若飞天上去，定作月边星。'},
    {t:'咏玉',a:'韦应物〔唐代〕',c:'乾坤有精物，至宝无文章。\n雕琢为世器，真性一朝伤。'},
    {t:'咏竹',a:'黄庭坚〔宋代〕',c:'竹笋才生黄犊角，蕨芽初放小儿拳。\n试寻野菜和香饭，便是黄州二月天。'},
    {t:'咏主人壁上画鹤寄乔主簿崔著作',a:'陈子昂〔唐代〕',c:'古壁仙人画，丹青尚有文。\n独舞纷如雪，孤飞暧似云。\n自矜彩色重，宁忆故池群。\n江海联翩翼，长鸣谁复闻。'},
    {t:'咏苎萝山',a:'李白〔唐代〕',c:'西施越溪女，出自苎萝山。\n秀色掩今古，荷花羞玉颜。\n浣纱弄碧水，自与清波闲。\n皓齿信难开，沉吟碧云间。\n勾践徵绝艳，扬蛾入吴关。\n提携馆娃宫，杳渺讵可攀。\n一破夫差国，千秋竟不还。'},
    {t:'用林择之韵别陈休斋',a:'朱熹〔宋代〕',c:'别离不觉岁时侵，两地相望共记心。今日还成一尊酒，它年应记百篇吟。\n伤情后会无期定，握手交情有旧深。多谢晚风知记意，不催寒日下疏林。'},
    {t:'用前人韵赋招隐',a:'文天祥〔宋代〕',c:'钓鱼船上听吹笛，煨芋炉头看梦棋。\n賸有晚愁归别浦，已无春梦到端闱。\n去年尚忆桃红处，好景重逢橘绿时。\n珍重山人招隐意，猿啼鹤啸白云飞。'},
    {t:'用萧敬夫韵',a:'文天祥〔宋代〕',c:'庭院芭蕉碎绿阴，高山一曲寄瑶琴。\n西风游子万山影，明月故乡千里心。\n江上断鸿随我老，天涯芳草为谁深。\n雪中若作梅花梦，约莫孤山人姓林。'},
    {t:'用子服韵谢水仙花',a:'朱熹〔宋代〕',c:'水中仙子来何处，翠袖黄冠白玉英。报道幽人被渠恼，著诗送与老难兄。'},
    {t:'幽怀',a:'韩愈〔唐代〕',c:'幽怀不能写，行此春江浔。适与佳节会，士女竞光阴。\n凝妆耀洲渚，繁吹荡人心。间关林中鸟，亦知和为音。\n岂无一尊酒，自酌还自吟。但悲时易失，四序迭相侵。\n我歌君子行，视古犹视今。'},
    {t:'幽涧泉',a:'李白〔唐代〕',c:'拂彼白石，弹吾素琴。\n幽涧愀兮流泉深，善手明徽高张清。\n心寂历似千古，松飕飗兮万寻。\n中见愁猿吊影而危处兮，叫秋木而长吟。\n客有哀时失志而听者，泪淋浪以沾襟。\n乃缉商缀羽，潺湲成音。\n吾但写声发情于妙指，殊不知此曲之古今。\n幽涧泉，鸣深林。'},
    {t:'幽居',a:'韦应物〔唐代〕',c:'贵贱虽异等，出门皆有营。\n独无过物牵，遂此幽居情。\n微雨夜来过，不知春草生。\n青山忽已曙，鸟雀绕舍鸣。\n时与道人偶，或随樵者行。\n自当安蹇劣，谁谓薄世荣。'},
    {t:'幽居初夏',a:'陆游〔宋代〕',c:'湖山胜处放翁家，槐柳阴中野径斜。\n水满有时观下鹭，草深无处不鸣蛙。\n箨龙已过头番笋，木笔犹开第一花。\n叹息老来交旧尽，睡来谁共午瓯茶。'},
    {t:'幽居冬暮',a:'李商隐〔唐代〕',c:'羽翼摧残日，郊园寂寞时。\n晓鸡惊树雪，寒鹜守冰池。\n急景忽云暮，颓年浸已衰。\n如何匡国分，不与夙心期。'},
    {t:'幽栖',a:'元稹〔唐代〕',c:'野人自爱幽栖所，近对长松远是山。尽日望云心不系，\n有时看月夜方闲。壶中天地乾坤外，梦里身名旦暮间。\n辽海若思千岁鹤，且留城市会飞还。'},
    {t:'幽州胡马客歌',a:'李白〔唐代〕',c:'幽州胡马客，绿眼虎皮冠。\n笑拂月只箭，万人不可干。\n弯弓若转月，白雁落云端。\n双双掉鞭行，游何向楼兰。\n出门不顾后，报国死何难？\n天骄五单于，狼戾好凶残。\n牛马散北海，割鲜若虎餐。\n虽居燕支山，不道朔雪寒。\n妇女马上笑，颜如赪玉盘。\n翻飞射野兽，花月醉雕鞍。\n旄头四光芒，争战若蜂攒。\n白刃洒赤血，流沙为之丹。\n名将古是谁，疲兵良可叹。\n何时天狼灭？父子得安闲。'},
    {t:'幽州马客吟歌辞',a:'佚名〔南北朝〕',c:'快马常苦瘦，剿儿常苦贫。\n黄禾起羸马，有钱始作人。\n荧荧帐中烛，烛灭不久停。\n盛时不作乐，春花不重生。\n南山自言高，只与北山齐。\n女儿自言好，故入郎君怀。\n郎著紫袴褶，女著彩裌裙。\n男女共燕游，黄花生后园。\n黄花郁金色，绿蛇衔珠丹。\n辞谢床上女，还我十指环。'},
    {t:'幽州马客吟歌辞其三',a:'佚名〔隋代〕',c:'南山自言高，只与北山齐。女儿自言好，故入郎君怀。'},
    {t:'游白水书付过',a:'苏轼〔宋代〕',c:'绍圣元年十月十二日，与幼子过游白水佛迹院，浴于汤池，热甚，其源殆可熟物。\n循山而东，少北，有悬水百仞，山八九折，折处辄为潭，深者缒石五丈，不得其所止。雪溅雷怒，可喜可畏。水崖有巨人迹数十，所谓佛迹也。\n暮归倒行，观山烧，火甚，俯仰度数谷。至江山月出，击汰中流，掬弄珠璧。\n到家二鼓，复与过饮酒，食余甘煮菜。顾影颓然，不复甚寐。书以付过。东坡翁。'},
    {t:'游城南韩氏庄',a:'孟郊〔唐代〕',c:'初疑潇湘林，锁在朱门中。时见林底月，动摇池上风。\n清气润竹林，白光连虚空。浪簇霄汉羽，岸芳金碧丛。\n何言数亩间，环泛路不穷。愿逐神仙侣，飘然汗漫通。'},
    {t:'游城南十六首·把酒',a:'韩愈〔唐代〕',c:'扰扰驰名者，谁能一日闲。我来无伴侣，把酒对南山。'},
    {t:'游城南十六首·嘲少年',a:'韩愈〔唐代〕',c:'直把春偿酒，都将命乞花。只知闲信马，不觉误随车。'},
    {t:'游城南十六首·出城',a:'韩愈〔唐代〕',c:'暂出城门蹋青草，远于林下见春山。\n应须韦杜家家到，只有今朝一日闲。'},
    {t:'游城南十六首·风折花枝',a:'韩愈〔唐代〕',c:'浮艳侵天难就看，清香扑地只遥闻。\n春风也是多情思，故拣繁枝折赠君。'},
    {t:'游城南十六首·落花',a:'韩愈〔唐代〕',c:'已分将身著地飞，那羞践踏损光晖。\n无端又被春风误，吹落西家不得归。'},
    {t:'游城南十六首·遣兴',a:'韩愈〔唐代〕',c:'断送一生惟有酒，寻思百计不如闲。\n莫忧世事兼身事，须著人间比梦间。'},
    {t:'游城南十六首·楸树',a:'韩愈〔唐代〕',c:'青幢紫盖立童童，细雨浮烟作彩笼。\n不得画师来貌取，定知难见一生中。'},
    {t:'游城南十六首·楸树二首',a:'韩愈〔唐代〕',c:'几岁生成为大树，一朝缠绕困花藤。\n谁人与脱青罗帔，看吐高花万万层。\n幸自枝条能树立，可烦萝蔓作交加。\n傍人不解寻根本，却道新花胜旧花。'},
    {t:'游城南十六首·赛神',a:'韩愈〔唐代〕',c:'白布长衫紫领巾，差科未动是闲人。\n麦苗含穟桑生葚，共向田头乐社神。'},
    {t:'游城南十六首·题于宾客庄',a:'韩愈〔唐代〕',c:'榆荚车前盖地皮，蔷薇蘸水笋穿篱。\n马蹄无入朱门迹，纵使春归可得知。'},
    {t:'游城南十六首·晚雨',a:'韩愈〔唐代〕',c:'廉纤晚雨不能晴，池岸草间蚯蚓鸣。\n投竿跨马蹋归路，才到城门打鼓声。'},
    {t:'游城南十六首·赠同游',a:'韩愈〔唐代〕',c:'唤起窗全曙，催归日未西。无心花里鸟，更与尽情啼。'},
    {t:'游城南十六首·赠张十八助教',a:'韩愈〔唐代〕',c:'喜君眸子重清朗，携手城南历旧游。\n忽见孟生题竹处，相看泪落不能收。'},
    {t:'游池州林泉寺金碧洞',a:'杜牧〔唐代〕',c:'袖拂霜林下石棱，潺湲声断满溪冰。\n携茶腊月游金碧，合有文章病茂陵。'},
    {t:'游凤林寺西岭',a:'孟浩然〔唐代〕',c:'共喜年华好，来游水石间。\n烟容开远树，春色满幽山。\n壶酒朋情洽，琴歌野兴闲。\n莫愁归路暝，招月伴人还。'},
    {t:'游杭州圣果寺',a:'王安石〔宋代〕',c:'登高见山水，身在水中央。\n下视楼台处，空多树木苍。\n浮云连海气，落日动湖光。\n偶坐吹横笛，残声入富阳。'},
    {t:'游华山云台观',a:'孟郊〔唐代〕',c:'华岳独灵异，草木恒新鲜。山尽五色石，水无一色泉。\n仙酒不醉人，仙芝皆延年。夜闻明星馆，时韵女萝弦。\n敬兹不能寐，焚柏吟道篇。'},
    {t:'游化感寺',a:'王维〔唐代〕',c:'翡翠香烟合，琉璃宝地平。\n龙宫响栋宇，虎穴傍檐楹。\n谷静唯松响，山深无鸟声。\n琼峰当户拆，金外透林明。\n郢路云端迥，秦川雨外晴。\n雁王衔果献，鹿女踏花行。\n抖擞辞贫里，归依宿化城。\n绕篱生野蕨，空馆发山樱。\n香饭青菰米，嘉蔬绿笋茎。\n誓陪清梵末，端坐学无生。'},
    {t:'游鉴湖',a:'秦观〔宋代〕',c:'画舫珠帘出缭墙，天风吹到芰荷乡。\n水光入座杯盘莹，花气侵人笑语香。\n翡翠侧身窥渌酒，蜻蜓偷眼避红妆。\n蒲萄力缓单衣怯，始信湖中五月凉。'},
    {t:'游江西留别富阳裴、刘二少府',a:'孟浩然〔唐代〕',c:'西上游江西，临流恨解携。千山叠成嶂，万水泻为溪。\n石浅流难溯，藤长险易跻。谁怜问津者，岁晏此中迷。'},
    {t:'游金山寺',a:'苏轼〔宋代〕',c:'我家江水初发源，宦游直送江入海。\n闻道潮头一丈高，天寒尚有沙痕在。\n中泠南畔石盘陀，古来出没随涛波。\n试登绝顶望乡国，江南江北青山多。\n羁愁畏晚寻归楫，山僧苦留看落日。\n微风万顷靴文细，断霞半空鱼尾赤。\n是时江月初生魄，二更月落天深黑。\n江心似有炬火明，飞焰照山栖鸟惊。\n怅然归卧心莫识，非鬼非人竟何物？\n江山如此不归山，江神见怪惊我顽。\n我谢江神岂得已，有田不归如江水。'},
    {t:'游精思，题观主山房',a:'孟浩然〔唐代〕',c:'误入桃源里，初怜竹径深。方知仙子宅，未有世人寻。\n舞鹤过闲砌，飞猿啸密林。渐通玄妙理，深得坐忘心。'},
    {t:'游精思观回王白云在后',a:'孟浩然〔唐代〕',c:'出谷未停午，到家日已曛。\n回瞻下山路，但见牛羊群。\n樵子暗相失，草虫寒不闻。\n衡门犹未掩，伫立望夫君。'},
    {t:'游景空寺兰若',a:'孟浩然〔唐代〕',c:'龙象经行处，山腰度石关。屡迷青嶂合，时爱绿萝闲。\n宴息花林下，高谈竹屿间。寥寥隔尘事，疑是入鸡山。'},
    {t:'游开元精舍',a:'韦应物〔唐代〕',c:'夏衣始轻体，游步爱僧居。\n果园新雨后，香台照日初。\n绿阴生昼静，孤花表春馀。\n符竹方为累，形迹一来疏。'},
    {t:'游琅琊山寺',a:'韦应物〔唐代〕',c:'受命恤人隐，兹游久未遑。\n鸣驺寒幽涧，前旌耀崇冈。\n青冥台砌寒，绿缛草木香。\n填壑跻花界，叠定构云房。\n经制随岩转，缭绕岂定方。\n新泉泄阴壁，高萝荫绿塘。\n攀林一栖止，饮水得清凉。\n物累诚可遣，疲氓终未忘。\n还归坐郡阁，但见山苍苍。'},
    {t:'游李山人所居因题屋壁',a:'王维〔唐代〕',c:'世上皆如梦，狂来止自歌。问年松树老，有地竹林多。\n药倩韩康卖，门容尚子过。翻嫌枕席上，无那白云何。'},
    {t:'游灵岩寺',a:'韦应物〔唐代〕',c:'始入松路永，独忻山寺幽。不知临绝槛，乃见西江流。\n吴岫分烟景，楚甸散林丘。方悟关塞眇，重轸故园愁。\n闻钟戒归骑，憩涧惜良游。地疏泉谷狭，春深草木稠。\n兹焉赏未极，清景期杪秋。'},
    {t:'游龙门奉先寺',a:'杜甫〔唐代〕',c:'已从招提游，更宿招提境。\n阴壑生虚籁，月林散清影。\n天阙象纬逼，云卧衣裳冷。\n欲觉闻晨钟，令人发深省。'},
    {t:'游龙门香山泉',a:'韦应物〔唐代〕',c:'山水本自佳，游人已忘虑。碧泉更幽绝，赏爱未能去。\n潺湲写幽磴，缭绕带嘉树。激转忽殊流，归泓又同注。\n羽觞自成玩，永日亦延趣。灵草有时香，仙源不知处。\n还当候圆月，携手重游寓。'},
    {t:'游庐山',a:'范仲淹〔宋代〕',c:'五老闲游依舳舻，碧梯云径好和途。\n云开瀑影千门挂，雨过松簧十里铺。\n客爱往来何所得，僧言荣辱此间无。\n从今愈识逍遥旨，一听升沉造化炉。'},
    {t:'游庐山作',a:'范仲淹〔宋代〕',c:'五老闲游倚舳舻，碧梯岚径好程途。云开瀑影千门挂，雨过松黄十里铺。\n客爱往来何所得，僧言荣辱此间无。从今愈识逍遥旨，一听升沉造化炉。'},
    {t:'游明禅师西山兰若',a:'孟浩然〔唐代〕',c:'西山多奇状，秀出倚前楹。停午收彩翠，夕阳照分明。\n吾师住其下，禅坐证无生。结庐就嵌窟，剪苕通往行。\n谈空对樵叟，授法与山精。日暮方辞去，田园归冶城。'},
    {t:'游南塘寄知者',a:'温庭筠〔唐代〕',c:'白鸟梳翎立岸莎，藻花菱刺泛珠波。烟光似带侵垂柳，\n露点如珠落卷荷。楚水晓凉催客早，杜陵秋思傍蝉多。\n镏公不信归心切，听取江楼一曲歌。'},
    {t:'游南阳清泠泉',a:'李白〔唐代〕',c:'惜彼落日暮，爱此寒泉清。\n西辉逐流水，荡漾游子情。\n空歌望云月，曲尽长松声。'},
    {t:'游南斋',a:'韦应物〔唐代〕',c:'池上鸣佳禽，僧斋日幽寂。\n高林晚露清，红药无人摘。\n春水不生烟，荒冈筠翳石。\n不应朝夕游，良为蹉跎客。'},
    {t:'游山西村',a:'陆游〔宋代〕',c:'莫笑农家腊酒浑，丰年留客足鸡豚。\n山重水复疑无路，柳暗花明又一村。\n箫鼓追随春社近，衣冠简朴古风存。\n从今若许闲乘月，拄杖无时夜叩门。'},
    {t:'游石角过小岭至长乌村',a:'柳宗元〔唐代〕',c:'志适不期贵，道存岂偷生？\n久忘上封事，复笑升天行。\n窜逐宦湘浦，摇心剧悬旌。\n始惊陷世议，终欲逃天刑。\n岁月杀忧栗，慵疏寡将迎。\n追游疑所爱，且复舒吾情。\n石角恣幽步，长乌遂遐征。\n磴回茂树断，景晏寒川明。\n旷望少行人，时闻田鹳鸣。\n风篁冒水远，霜稻侵山平。\n稍与人事间，益知身世轻。\n为农信可乐，居宠真虚荣。\n乔木余故国，愿言果丹诚。\n四支反田亩，释志东皋耕。'},
    {t:'游太平公主山庄',a:'韩愈〔唐代〕',c:'公主当年欲占春，故将台榭押城闉。\n欲知前面花多少，直到南山不属人。'},
    {t:'游乌龙山寺',a:'范仲淹〔宋代〕',c:'高岚指天近，远溜出山迟。\n万事不到处，白云无尽时。\n异花啼鸟乐，灵草隐人知。\n信是栖真地，林僧半雪眉。'},
    {t:'游悟真寺·一作王缙诗',a:'王维〔唐代〕',c:'闻道黄金地，仍开白玉田。掷山移巨石，咒岭出飞泉。\n猛虎同三径，愁猿学四禅。买香然绿桂，乞火踏红莲。\n草色摇霞上，松声泛月边。山河穷百二，世界接三千。\n梵宇聊凭视，王城遂渺然。灞陵才出树，渭水欲连天。\n远县分诸郭，孤村起白烟。望云思圣主，披雾隐群贤。\n薄宦惭尸素，终身拟尚玄。谁知草庵客，曾和柏梁篇。'},
    {t:'游西湖',a:'朱熹〔宋代〕',c:'越王城下水溶溶，此乐从今与众同。\n满眼芰荷方永日，转头禾黍便西风。\n湖光尽处天容阔，潮信来时海气通。\n酬唱不夸风物好，一心忧国愿年丰。'},
    {t:'游西林寺题萧二兄郎中旧堂',a:'韩愈〔唐代〕',c:'中郎有女能传业，伯道无儿可保家。\n偶到匡山曾住处，几行衰泪落烟霞。'},
    {t:'游西山',a:'韦应物〔唐代〕',c:'时事方扰扰，幽赏独悠悠。弄泉朝涉涧，采石夜归州。\n挥翰题苍峭，下马历嵌丘。所爱唯山水，到此即淹留。'},
    {t:'游溪',a:'韦应物〔唐代〕',c:'野水烟鹤唳，楚天云雨空。玩舟清景晚，垂钓绿蒲中。\n落花飘旅衣，归流澹清风。缘源不可极，远树但青葱。'},
    {t:'游溪待月',a:'皎然〔唐代〕',c:'溪色思泛月，沿洄欲未归。残灯逢水店，疏磬忆山扉。\n夜浦鱼惊少，空林鹊绕稀。可中才望见，撩乱捣寒衣。'},
    {t:'游襄阳怀孟浩然',a:'白居易〔唐代〕',c:'楚山碧岩岩，汉水碧汤汤。\n秀气结成象，孟氏之文章。\n今我讽遗文，思人至其乡。\n清风无人继，日暮空襄阳。\n南望鹿门山，蔼若有余芳。\n旧隐不知处，云深树苍苍。'},
    {t:'游终南龙池寺',a:'孟郊〔唐代〕',c:'飞鸟不到处，僧房终南巅。龙在上长碧，雨开山更鲜。\n步出白日上，坐依清溪边。地寒松桂短，石险道路偏。\n晚磬送归客，数声落遥天。'},
    {t:'游终南山',a:'孟郊〔唐代〕',c:'南山塞天地，日月石上生。\n高峰夜留景，深谷昼未明。\n山中人自正，路险心亦平。\n长风驱松柏，声拂万壑清。\n即此悔读书，朝朝近浮名。'},
    {t:'游钟山',a:'王安石〔宋代〕',c:'终日看山不厌山，买山终待老山间。\n山花落尽山长在，山水空流山自闲。'},
    {t:'游诸葛武侯书台',a:'陆游〔宋代〕',c:'沔阳道中草离离，卧龙往矣空遗祠。\n当时典午称猾贼，气丧不敢当王师。\n定军山前寒食路，至今人祠丞相墓。\n松风想像梁甫吟，尚忆幡然答三顾。\n出师一表千载无，远比管乐盖有余。\n世上俗儒宁办此，高台当日读何书?'},
    {t:'游祝融峰',a:'韩愈〔唐代〕',c:'祝融万丈拔地起，欲见不见轻烟里。山翁爱山不肯归，爱山醉眠山根底。\n山童寻着不敢惊，沉吟为怕山翁嗔。梦回抖擞下山去，一径萝月松风清。'},
    {t:'游子',a:'孟郊〔唐代〕',c:'萱草生堂阶，游子行天涯。\n慈亲倚堂门，不见萱草花。'},
    {t:'游子吟',a:'孟郊〔唐代〕',c:'慈母手中线，游子身上衣。\n临行密密缝，意恐迟迟归。\n谁言寸草心，报得三春晖。'},
    {t:'有感',a:'文天祥〔宋代〕',c:'平生心事付悠悠，风雨燕南老楚囚。\n故旧相思空万里，妻孥不见满三秋。\n绝怜诸葛隆中意，羸得子长天下游。\n一死皎然无复恨，忠魂多少暗荒丘。'},
    {t:'有感',a:'杜牧〔唐代〕',c:'宛溪垂柳最长枝，曾被春风尽日吹。\n不堪攀折犹堪看，陌上少年来自迟。'},
    {t:'有感',a:'李商隐〔唐代〕',c:'非关宋玉有微辞，却是襄王梦觉迟。\n一自高唐赋成后，楚天云雨尽堪疑。'},
    {t:'有怀在蒙飞卿',a:'李商隐〔唐代〕',c:'薄宦频移疾，当年久索居。\n哀同庾开府，瘦极沈尚书。\n城绿新阴远，江清返照虚。\n所思惟翰墨，从古待双鱼。'},
    {t:'有会而作',a:'陶渊明〔魏晋〕',c:'旧谷既没，新谷未登，颇为老农，而值年灾，日月尚悠，为患未已。登岁之功，既不可希，朝夕所资，烟火裁通。旬日已来，始念饥乏，岁云夕矣，慨然永怀，今我不述，后生何闻哉！\n弱年逢家乏，老至更长饥。\n菽麦实所羡，孰敢慕甘肥。\n惄如亚九饭，当暑厌寒衣。\n岁月将欲暮，如何辛苦悲。\n常善粥者心，深念蒙袂非。\n嗟来何足吝，徒没空自遗。\n斯滥岂攸志，固穷夙所归。\n馁也已矣夫，在昔余多师。'},
    {t:'有寄',a:'杜牧〔唐代〕',c:'云阔烟深树，江澄水浴秋。\n美人何处在，明月万山头。'},
    {t:'有美堂暴雨',a:'苏轼〔宋代〕',c:'游人脚底一声雷，满座顽云拨不开。\n天外黑风吹海立，浙东飞雨过江来。\n十分潋滟金樽凸，千杖敲铿羯鼓催。\n唤起谪仙泉洒面，倒倾鲛室泻琼瑰。'},
    {t:'有木诗八首·其八',a:'白居易〔唐代〕',c:'有木名丹桂，四时香馥馥。\n花团水雪明，叶剪春云绿。\n风影清似水，霜枝冷如玉。\n独占小山幽，不厦凡鸟宿。\n匠人爱芳直，裁截为厦屋。\n干细力未成，用之君自速。\n重任虽大过，直心终不曲。\n纵非梁栋材，犹胜寻常木。'},
    {t:'有所嗟二首',a:'刘禹锡〔唐代〕',c:'庾令楼中初见时，武昌春柳似腰肢。\n相逢相笑尽如梦，为雨为云今不知。\n鄂渚濛濛烟雨微，女郎魂逐暮云归。\n只应长在汉阳渡，化作鸳鸯一只飞。'},
    {t:'有所思',a:'李贺〔唐代〕',c:'去年陌上歌离曲，今日君书远游蜀。\n帘外花开二月风，台前泪滴千行竹。\n琴心与妾肠，此夜断还续。\n想君白马悬雕弓，世间何处无春风。\n君心未肯镇如石，妾颜不久如花红。\n夜残高碧横长河，河上无梁空白波。\n西风未起悲龙梭，年年织素攒双蛾。\n江山迢递无休绝，泪眼看灯乍明灭。\n自从孤馆深锁窗，桂花几度圆还缺。\n鸦鸦向晓鸣森木，风过池塘响丛玉。\n白日萧条梦不成，桥南更问仙人卜。'},
    {t:'有所思',a:'佚名〔两汉〕',c:'有所思，乃在大海南。\n何用问遗君，双珠玳瑁簪。\n用玉绍缭之。\n闻君有他心，拉杂摧烧之。\n摧烧之，思风扬其灰！\n从今以往，勿复相思，相思与君绝！\n鸡鸣狗吠，兄嫂思知之。\n妃呼豨！\n秋风肃肃晨风飔，东方须臾高知之！'},
    {t:'有所思',a:'李白〔唐代〕',c:'我思仙人，乃在碧海之东隅。\n海寒多天风，白波连山倒蓬壶。\n长鲸喷涌不可涉，抚心茫茫泪如珠。\n西来青鸟东飞去，愿寄一书谢麻姑。'},
    {t:'有所思联句',a:'孟郊〔唐代〕',c:'相思绕我心，日夕千万重。年光晦婉娩，春泪销颜容。——孟郊\n台镜晦旧晖，庭草滋深茸。望夫山上石，别剑水中龙。——韩愈'},
    {t:'有志',a:'佚名〔隋代〕',c:'天下无难事，在乎人为之。不为易亦难，为之难亦易。\n吾非千里马，然有千里志。旦旦而为之，终亦成骐骥。'},
    {t:'又',a:'王昌龄〔唐代〕',c:'眇默客子魂，倏铄川上晖。\n还云惨知暮，九月仍未归。'},
    {t:'又呈吴郎',a:'杜甫〔唐代〕',c:'堂前扑枣任西邻，无食无儿一妇人。\n不为困穷宁有此？只缘恐惧转须亲。\n即防远客虽多事，便插疏篱却甚真。\n已诉征求贫到骨，正思戎马泪盈巾。'},
    {t:'又观打鱼',a:'杜甫〔唐代〕',c:'苍江鱼子清晨集，设网提纲万鱼急。\n能者操舟疾若风，撑突波涛挺叉入。\n小鱼脱漏不可记，半死半生犹戢戢。\n大鱼伤损皆垂头，屈强泥沙有时立。\n东津观鱼已再来，主人罢鲙还倾杯。\n日暮蛟龙改窟穴，山根鳣鲔随云雷。\n干戈兵革斗未止，凤凰麒麟安在哉。\n吾徒胡为纵此乐，暴殄天物圣所哀。'},
    {t:'又和二首',a:'黄庭坚〔宋代〕',c:'西风鏖残暑，如用霍去病。\n疏沟满莲塘，扫叶明竹迳。\n中有寂寞人，自知圆觉性。\n心猿方睡起，一笑六窗静。'},
    {t:'又和风雨二首',a:'杨万里〔宋代〕',c:'东风未自颠如许，定被春光引自颠。\n晚雨何妨略弹压，不应犹自借渠权。\n风风雨雨又春穷，白白朱朱已眼空。\n拚却老红一万点，换将新绿百千重。'},
    {t:'又三绝',a:'文天祥〔宋代〕',c:'人间万事转头空，皂帽飘萧一病翁。\n不学孟嘉狂落魄，故将白发向西风。'},
    {t:'又示宗武',a:'杜甫〔唐代〕',c:'觅句新知律，摊书解满床。\n试吟饮玉案，莫羡紫罗囊。\n假日从时饮，明年共我长。\n应须饱经术，已似爱文章。\n十五男儿志，三千弟子行。\n曾参与游夏，达者得升堂。'},
    {t:'又送前人琴棋书画四首',a:'文天祥〔宋代〕',c:'不知甲子定何年，题满柴桑日本眠。\n意不在言君解否，壁间琴本是无弦。\n我爱商山茹紫芝，逍战胜似橘中时。\n纷纷玄白方龙战，世事从他一局棋。\n蔡邕去后右军死，谁是风流入品题。\n只少蛟龙大师字，至今风骨在浯溪。\n欲觅龙眠旧时事，相传此本世间无。\n黄金不买昭君本，只买严陵归钓图。'},
    {t:'又送族侄式颜',a:'高适〔唐代〕',c:'惜君才未遇，爱君才若此。世上五百年，吾家一千里。\n俱游帝城下，忽在梁园里。我今行山东，离忧不能已。'},
    {t:'又用前韵谢晏尚书以近著示及',a:'范仲淹〔宋代〕',c:'祖述贤人业，何因降玄乡。\n周公旧才美，夫子近文章。\n逸气弥冲斗，雄源甚决潢。\n月中灵桂老，春外实芝芳。\n远似天无翳，清如塞有霜。\n日星图舜禹，金石颂成康。\n涡曲风骚盛，营丘学校光。\n至精含变化，大手凿洪荒。\n崧岳词欺甫，甘泉价掩扬。\n满朝当讽诵，终古岂遗忘。\n恍若探龙际，森疑履虎傍。\n半生游此道，观海特茫茫。'},
    {t:'又赠李侍御',a:'王昌龄〔唐代〕',c:'渺然客子魂，倏铄川上晖。还云惨知暮，九月仍未归。'},
    {t:'又赠马云翎',a:'纳兰性德〔清代〕',c:'岧峣最高山，山气蒸为云。物本相感生，相感乃相亲。\n吁嗟人生不可拟，君南我北三千里。一朝倾盖便相欢，两人心事如江水。\n君身似是秋风客，身轻欲奋凌霄翮。语君无限伤心事，终古长江江月白。\n世事纷纷等飞絮，我今潦倒随所寓。惟愿饮酒读君诗，花前醉卧梦君去。'},
    {t:'又自赞',a:'杨万里〔宋代〕',c:'江风索我吟，山月唤我饮。\n醉倒落花前，天地为衾枕。'},
    {t:'柚花',a:'朱熹〔宋代〕',c:'春融百卉茂，素荣敷绿枝。淑郁丽芳远，悠飏风日迟。\n南国富嘉树，骚人留恨词。空斋对日夕，愁绝鬓成丝。'},
    {t:'于飞乐',a:'晏几道〔宋代〕',c:'晓日当帘，睡痕犹占香腮。轻盈花倚鸾台。晕残红，匀宿翠，满镜花开。娇蝉鬓畔，插一枝、淡蕊疏下。\n每到春深，多愁饶恨，妆成懒下香阶。意中人，从别后，萦后情怀。良辰好景，相思字、唤不归来。'},
    {t:'于阗采花',a:'李白〔唐代〕',c:'于阗采花人，自言花相似。\n明妃一朝西入胡，胡中美女多羞死。\n乃知汉地多名姝，胡中无花可方比。\n丹青能令丑者妍，无盐翻在深宫里。\n自古妒蛾眉，胡沙埋皓齿。'},
    {t:'于王抚军座送客',a:'陶渊明〔魏晋〕',c:'秋日凄且厉，百卉具已腓。\n爰以履霜节，登高饯将归。\n寒气冒山泽，游云倏无依。\n洲渚四缅邈，风水互乖违。\n瞻夕欣良宴，离言聿云悲。\n晨鸟暮来还，悬车敛馀辉。\n逝止判殊路，旋驾怅迟迟。\n目送回舟远，情随万化遗。'},
    {t:'于五松山赠南陵常赞府',a:'李白〔唐代〕',c:'为草当作兰，为木当作松。\n兰秋香风远，松寒不改容。\n松兰相因依，萧艾徒丰茸。\n鸡与鸡并食，鸾与鸾同枝。\n拣珠去沙砾，但有珠相随。\n远客投名贤，真堪写怀抱。\n若惜方寸心，待谁可倾倒？\n虞卿弃赵相，便与魏齐行。\n海上五百人，同日死田横。\n当时不好贤，岂传千古名。\n愿君同心人，于我少留情。\n寂寂还寂寂，出门迷所适。\n长铗归来乎，秋风思归客。'},
    {t:'于武原从送卢士举',a:'皎然〔唐代〕',c:'落日独归客，空山匹马嘶。萧条古关外，岐路更东西。\n大泽云寂寂，长亭雨凄凄。君还到湘水，寒夜满猿啼。'},
    {t:'于长史山池三日曲水宴',a:'陈子昂〔唐代〕',c:'摘兰藉芳月，祓宴坐回汀。泛滟清流满，葳蕤白芷生。\n金弦挥赵瑟，玉指弄秦筝。岩榭风光媚，郊园春树平。\n烟花飞御道，罗绮照昆明。日落红尘合，车马乱纵横。'},
    {t:'于中好·别绪如丝梦不成',a:'纳兰性德〔清代〕',c:'别绪如丝梦不成，那堪孤枕梦边城。因听紫塞三更雨，却忆红楼半夜灯。\n书郑重，恨分明，天将愁味酿多情。起来呵手封题处，偏到鸳鸯两字冰。'},
    {t:'于中好·独背残阳上小楼',a:'纳兰性德〔清代〕',c:'独背残阳上小楼，谁家玉笛韵花幽。一行白雁遥天暮，几点黄花满地秋。\n惊节序，叹沉浮，秾华如梦水东流。人间所事堪惆怅，莫向横塘问旧游。'},
    {t:'于中好·谁道阴山行路难',a:'纳兰性德〔清代〕',c:'谁道阴山行路难。风毛雨血万人欢。松梢露点沾鹰绁，芦叶溪深没马鞍。\n依树歇，映林看。黄羊高宴簇金盘。萧萧一夕霜风紧，却拥貂裘怨早寒。'},
    {t:'于中好·握手西风泪不干',a:'纳兰性德〔清代〕',c:'握手西风泪不干，年来多在别看间。遥知独听灯前雨，转忆同看雪后山。\n凭寄语，劝加餐。桂花时节约重还。分明小像沉香缕，一片伤心欲画难。'},
    {t:'于中好·小构园林寂不哗',a:'纳兰性德〔清代〕',c:'小构园林寂不哗，疏篱曲径仿山家。昼长吟罢风流子，忽听楸枰响碧纱。\n添竹石，伴烟霞。拟凭樽酒慰年华。休嗟髀里今生肉，努力春来自种花。'},
    {t:'于中好·雁帖寒云次第飞',a:'纳兰性德〔清代〕',c:'雁帖寒云次第飞，向南犹自怨风迟。谁能瘦马关山道，又到西风扑鬓时。\n人杳杳，思依依，更无芳树有乌啼。凭将扫黛窗前月，持向今宵照别离。'},
    {t:'于中好咏史',a:'纳兰性德〔清代〕',c:'马上吟成促渡江，分明闲气属闺房。生憎久闭金铺暗，花冷回心玉一床。\n添哽咽，足凄凉。谁教生得满身香。只今西海年年月，犹为萧家照断肠。'},
    {t:'盂兰盆',a:'晏殊〔宋代〕',c:'红白薇英落，朱黄槿艳残。\n家人愁溽暑，计日望盂兰。'},
    {t:'鱼儿',a:'王安石〔宋代〕',c:'绕岸车鸣水欲乾，鱼儿相逐尚相欢。\n无人挈入沧江去，汝死那知世界宽。'},
    {t:'鱼山神女祠歌·迎神',a:'王维〔唐代〕',c:'坎坎击鼓，鱼山之下。\n吹洞箫，望极浦。\n女巫进，纷屡舞。\n陈瑶席，湛清酤。\n风凄凄兮夜雨，\n不知神之来兮不来，\n使我心兮苦复苦。'},
    {t:'鱼游春水·秦楼东风里',a:'佚名〔宋代〕',c:'秦楼东风里，燕子还来寻旧垒。方寒犹峭，红日薄侵罗绮。嫩草方抽碧玉茵，媚柳轻窣黄金蕊。遍啭上林，鱼游春水。\n几曲阑干遍倚，又是一番新桃李。佳人应怪归迟，梅妆泪洗。凤箫声绝沉孤雁，望断清波无双鲤。云山万重，寸心千里。'},
    {t:'於潜僧绿筠轩',a:'苏轼〔宋代〕',c:'宁可食无肉，不可居无竹。\n无肉令人瘦，无竹令人俗。\n人瘦尚可肥，士俗不可医。\n旁人笑此言，似高还似痴。\n若对此君仍大嚼，世间那有扬州鹤？'},
    {t:'渔父',a:'岑参〔唐代〕',c:'扁舟沧浪叟，心与沧浪清。\n不自道乡里，无人知姓名。\n朝从滩上饭，暮向芦中宿。\n歌竟还复歌，手持一竿竹。\n竿头钓丝长丈馀，鼓枻乘流无定居。\n世人那得识深意，此翁取适非取鱼。'},
    {t:'渔父',a:'杜牧〔唐代〕',c:'白发沧浪上，全忘是与非。\n秋潭垂钓去，夜月叩船归。\n烟影侵芦岸，潮痕在竹扉。\n终年狎鸥鸟，来去且无机。'},
    {t:'渔父',a:'苏轼〔宋代〕',c:'渔父笑，轻鸥举，漠漠一江风雨。江边骑马是官人，借我孤舟南渡。'},
    {t:'渔父·收却纶竿落照红',a:'纳兰性德〔清代〕',c:'收却纶竿落照红，秋风宁为剪芙蓉。人淡淡，水蒙蒙，吹入芦花短笛中。'},
    {t:'渔父·渔父醒',a:'苏轼〔宋代〕',c:'渔父醒，春江午，梦断落花飞絮。酒醒还醉醉还醒，一笑人间今古。'},
    {t:'渔父·渔父饮',a:'苏轼〔宋代〕',c:'渔父饮，谁家去。鱼蟹一时分付。酒无多少醉为期，彼此不论钱数。'},
    {t:'渔父·渔父醉',a:'苏轼〔宋代〕',c:'渔父醉，蓑衣舞，醉里却寻归路。轻舟短棹任斜横，醒后不知何处。'},
    {t:'渔父歌',a:'高适〔唐代〕',c:'曲岸深潭一山叟，驻眼看钩不移手。世人欲得知姓名，\n良久问他不开口。笋皮笠子荷叶衣，心无所营守钓矶。\n料得孤舟无定止，日暮持竿何处归。'},
    {t:'渔歌子',a:'张炎〔宋代〕',c:'画溪，作渔歌子十解，述古调也。\n□卯湾头屋数间。放船收尽一溪山。聊适兴，且怡颜。问天难买是真闲。'},
    {t:'渔家傲',a:'晏殊〔宋代〕',c:'粉笔丹青描未得。金针彩线功难敌。谁傍暗香轻采摘。风淅淅。船头解散双鸂鶒。\n夜雨染成天水碧。朝阳借出胭脂色。欲落又开人共惜。秋气逼。盘中已见新莲菂。'},
    {t:'渔家傲',a:'晏殊〔宋代〕',c:'脸傅朝霞衣剪翠。重重占断秋鸳水。一曲采莲风细细。人未醉。鸳鸯不合惊飞起。\n欲摘嫩条嫌绿刺。闲敲画扇偷金蕊。半夜月明珠露坠。多少意，红腮点点相思泪。'},
    {t:'渔家傲',a:'张炎〔宋代〕',c:'辛苦移家聊处静。扫除花径歌声趁。也学维摩闲示病。迂疏甚。松风两耳和衣枕。\n颇倦扶筇寻捷径。东墙蔼蔼红香盛。少待摇人波自定。蓬壶近。且呼白鹤招韩令。'},
    {t:'渔家傲',a:'秦观〔宋代〕',c:'刚过淮流风景变。飞沙四面连天卷。霜拆冻髭如利剪。情莫遣。素衣一任缁尘染。\n回首家山云渐远。离肠暗逐车轮转。古木荒烟鸦点点。人不见。平原落日吟羌管。'},
    {t:'渔家傲·楚国细腰元自瘦',a:'晏殊〔宋代〕',c:'楚国细腰元自瘦，文君腻脸谁描就。日夜声声催箭漏。昏复昼，红颜岂得长如旧。\n醉折嫩房和蕊嗅，天丝不断清香透。却傍小阑凝坐久。风满袖，西池月上人归后。'},
    {t:'渔家傲·灯火已收正月半',a:'王安石〔宋代〕',c:'灯火已收正月半，山南山北花穿乱。闻说洊亭新水漫，骑款段，穿云入坞寻游伴。\n却拂僧床褰素幔，千岩万壑春风暖。一弄松声悲急管，吹梦断，西看窗日犹嫌短。'},
    {t:'渔家傲·粉面啼红腰束素',a:'晏殊〔宋代〕',c:'粉面啼红腰束素，当年拾翠曾相遇。密意深情谁与诉。空怨慕，西池夜夜风兼露。\n池上夕阳笼碧树，池中短棹惊微雨。水泛落英何处去。人不语，东流到了无停住。'},
    {t:'渔家傲·荷叶初开犹半卷',a:'晏殊〔宋代〕',c:'荷叶初开犹半卷。荷花欲拆犹青绽。此叶此花真可羡。秋水畔。青凉伞映红妆面。\n美酒一杯留客宴。拈花摘叶情无限。争奈世人多聚散。频祝愿。如花似叶长相见。'},
    {t:'渔家傲·荷叶荷花相间斗',a:'晏殊〔宋代〕',c:'荷叶荷花相间斗。红娇绿嫩新妆就。昨日小池疏雨后。铺锦绣。行人过去频回首。\n倚遍朱阑凝望久。鸳鸯浴处波文皱。谁唤谢娘斟美酒。萦舞袖。当筵劝我千长寿。'},
    {t:'渔家傲·画鼓声中昏又晓',a:'晏殊〔宋代〕',c:'画鼓声中昏又晓。时光只解催人老。求得浅欢风日好。齐揭调。神仙一曲渔家傲。\n绿水悠悠天杳杳。浮生岂得长年少。莫惜醉来开口笑。须信道。人间万事何时了。'},
    {t:'渔家傲·灰暖香融销永昼',a:'周邦彦〔宋代〕',c:'灰暖香融销永昼。蒲萄架上春藤秀。曲角栏干群雀斗。清明后。风梳万缕亭前柳。\n日照钗梁光欲溜。循阶竹粉沾衣袖。拂拂面红如著酒。沉吟久。昨宵正是来时候。'},
    {t:'渔家傲·几日轻阴寒恻恻',a:'周邦彦〔宋代〕',c:'几日轻阴寒恻恻。东风急处花成积。醉踏阳春怀故国。归未得。黄鹂久住如相识。\n赖有蛾眉能暖客。长歌屡劝金杯侧。歌罢月痕来照席。贪欢适。帘前重露成涓滴。'},
    {t:'渔家傲·寄仲高',a:'陆游〔宋代〕',c:'东望山阴何处是？往来一万三书里。写得家书空满纸。流清泪，书回已是明年事。\n寄语红桥桥下水，扁舟何日寻兄弟？行遍天涯真老矣。愁无寐，鬓丝几缕茶烟里。'},
    {t:'渔家傲·临水纵横回晚鞚',a:'苏轼〔宋代〕',c:'临水纵横回晚鞚。归来转觉情西动。梅笛烟中闻几弄。秋阴重，西山雪淡云凝冻。\n美酒一杯谁与共。尊前舞雪狂歌送。腰跨金鱼旌旆拥。将何用，只堪妆点浮生梦。'},
    {t:'渔家傲·门掩新阴孤馆静',a:'张炎〔宋代〕',c:'门掩新阴孤馆静。杨花却解来脱趁。几日方知因酒病。无憀甚。脱巾挂壁将书枕。见说红堆满径。不知何处游人盛。自笑扁舟犹未定。清和近。寻诗已约兰陵令。'},
    {t:'渔家傲·嫩绿堪裁红欲绽',a:'晏殊〔宋代〕',c:'嫩绿堪裁红欲绽，蜻蜓点水鱼游畔。一霎雨声香四散。风飐乱，高低掩映千千万。\n总是凋零终有恨，能无眼下生留恋。何似折来妆粉面。勤看玩，胜如落尽秋江岸。'},
    {t:'渔家傲·平岸小桥千嶂抱',a:'王安石〔宋代〕',c:'平岸小桥千嶂抱。柔蓝一水萦花草。茅屋数间窗窈窕。尘不到。时时自有春风扫。\n午枕觉来闻语鸟。欹眠似听朝鸡早。忽忆故人今总老。贪梦好。茫然忘了邯郸道。'},
    {t:'渔家傲·七夕',a:'苏轼〔宋代〕',c:'皎皎牵牛河汉女，盈盈临水无梦语。望断碧云空日暮，无寻处，梦回芳草生春浦。\n鸟散馀花纷似雨，汀洲蘋老香风度。明月多情来照户，但揽取，清光长送人归去。'},
    {t:'渔家傲·七夕立秋',a:'秦观〔宋代〕',c:'七夕湖头闲眺望。风烟做出秋模样。不见云屏月帐。天滉漾。龙軿暗渡银河浪。\n二十年前今日况。玄蟾乌鹊高楼上。回首西风犹未忘。追得丧。人间万事成惆怅。'},
    {t:'渔家傲·千古龙蟠并虎踞',a:'苏轼〔宋代〕',c:'金陵赏心亭送王胜之龙图。王守金陵，视事一日移南郡。\n千古龙蟠并虎踞。从公一吊兴亡处。渺渺斜风吹细雨。芳草渡。江南父老留公住。\n公驾飞车凌彩雾。红鸾骖乘青鸾驭。却讶此洲名白鹭。非吾侣。翩然欲下还飞去。'},
    {t:'渔家傲·秋思',a:'范仲淹〔宋代〕',c:'塞下秋来风景异，衡阳雁去无长意。四面边声连角起，千嶂里，长烟落日孤城闭。\n浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地，人不寐，将军白发征夫泪。'},
    {t:'渔家傲·三十年来无孔窍',a:'黄庭坚〔宋代〕',c:'三十年来无孔窍，几回得眼还迷照。一见桃花参学了。呈法要，无弦琴上单于调。\n摘叶寻枝虚半老，看花特地重年少。今后水云人欲晓。非玄妙，灵云合被桃花笑。'},
    {t:'渔家傲·送省亲秦州',a:'苏轼〔宋代〕',c:'一曲阳关情几许，知君欲向秦川去。白马皂貂留不住。回首处，孤城不见天霖雾。\n到日长安花似雨，故关杨柳初飞絮。渐见靴刀迎夹路。谁得似，风流膝上王文度。'},
    {t:'渔家傲·送台守江郎中',a:'苏轼〔宋代〕',c:'送客归来灯火尽。西楼淡月凉生晕。明日潮来无定准。潮来稳。舟横渡口重城近。\n江水似知孤客恨。南风为解佳人愠。莫学时流轻久困。频寄问。钱塘江上须忠信。'},
    {t:'渔家傲·宿蕊斗攒金粉闹',a:'晏殊〔宋代〕',c:'宿蕊斗攒金粉闹，青房暗结蜂儿小。敛面似啼开似笑，天与貌，人间不是铅华少。\n叶软香清无限好，风头日脚干催老。待得玉京仙子到，凭向道，红颜只合长年少。'},
    {t:'渔家傲·题船子钓滩',a:'黄庭坚〔宋代〕',c:'荡漾生涯身已老。短蓑箬笠扁舟小。深入水云人不到。吟复笑。一轮明月长相照。\n谁谓阿师来问道。一桡直与传心要。船子踏翻才是了。波渺渺。长鲸万古无人钓。'},
    {t:'渔家傲·罨画溪边停彩舫',a:'晏殊〔宋代〕',c:'罨画溪边停彩舫，仙娥绣被呈新样。飒飒风声来一饷，愁四望，残红片片随波浪。\n琼脸丽人青步障，风牵一袖低相向。应有锦鳞闲倚傍，秋水上，时时绿柄轻摇扬。'},
    {t:'渔家傲·杨柳风前香百步',a:'晏殊〔宋代〕',c:'杨柳风前香百步，盘心碎点真珠露。疑是水仙开洞府，妆景趣，红幢绿盖朝天路。\n小鸭飞来稠闹处，三三两两能言语。饮散短亭人欲去，留不住，黄昏更下萧萧雨。'},
    {t:'渔家傲·叶下鵁鶄眠未稳',a:'晏殊〔宋代〕',c:'叶下鵁鶄眠未稳，风翻露飐香成阵。仙女出游知远近，羞借问，饶将绿扇遮红粉。\n一掬蕊黄霑雨润，天人乞与金英嫩。试折乱条醒酒困，应有恨，芳心拗尽丝无尽。'},
    {t:'渔家傲·幽鹭慢来窥品格',a:'晏殊〔宋代〕',c:'幽鹭慢来窥品格，双鱼岂解传消息。绿柄嫩香频采摘。心似织，条条不断谁牵役。\n粉泪暗和清露滴，罗衣染尽秋江色。对面不言情脉脉。烟水隔，无人说似长相忆。'},
    {t:'渔家傲·越女采莲江北岸',a:'晏殊〔宋代〕',c:'越女采莲江北岸，轻桡短棹随风便。人貌与花相斗艳。流水慢，时时照影看妆面。\n莲叶层层张绿伞，莲房个个垂金盏。一把藕丝牵不断。红日晚，回头欲去心撩乱。'},
    {t:'渔家傲·赠曹光州',a:'苏轼〔宋代〕',c:'些小白须何用染。几人得见星星点。作郡浮光虽似箭。君莫厌。也应胜我三年贬。\n我欲自嗟还不敢。向来三郡宁非忝。婚嫁事稀年冉冉。知有渐。千钧重担从头减。'},
    {t:'渔家傲其二',a:'王安石〔宋代〕',c:'平岸小桥千嶂抱，揉蓝一水萦花草。茅屋数间窗窈窕。\n尘不到，时时自有春风扫。\n午枕觉来闻语鸟，攲眠似听朝鸡早。忽忆故人今总老。\n贪梦好，茫然忘了邯郸道。'},
    {t:'渔翁',a:'柳宗元〔唐代〕',c:'渔翁夜傍西岩宿，晓汲清湘燃楚竹。\n烟销日出不见人，欸乃一声山水绿。\n回看天际下中流，岩上无心云相逐。'},
    {t:'渔阳将',a:'张籍〔唐代〕',c:'塞深沙草白，都护领燕兵。放火烧奚帐，分旗筑汉城。\n下营看岭势，寻雪觉人行。更向桑干北，擒生问碛名。'},
    {t:'渔舟',a:'文天祥〔宋代〕',c:'一阵飞帆破碧烟，儿郎惊饵理弓弦。\n舟中自信娄师德，海上谁知鲁仲连。\n初谓悠扬真贼舰，后闻欸乃是渔船。\n人生漂泊多磨折，何日山林清昼眠。'},
    {t:'榆林郡歌',a:'王维〔唐代〕',c:'山头松柏林，山下泉声伤客心。\n千里万里春草色，黄河东流流不息。\n黄龙戍上游侠儿，愁逢汉使不相识。'},
    {t:'虞美人',a:'周邦彦〔宋代〕',c:'淡云笼月松溪路。长记分携处。梦魂连夜绕松溪。此夜相逢恰似、梦中时。\n海山陡觉风光好。莫惜金尊倒。柳花吹雪燕飞忙。生怕扁舟归去、断人肠。'},
    {t:'虞美人',a:'晏几道〔宋代〕',c:'飞花自有牵情处。不向枝边坠。随风飘荡已堪愁。更伴东流流水、过秦楼。\n楼中翠黛含春怨。闲倚阑干见。远弹双泪惜香红。暗恨玉颜光景、与花同。'},
    {t:'虞美人',a:'晏几道〔宋代〕',c:'秋风不似春风好。一夜金英老。更谁来凭曲阑干。惟有雁边斜月、照关山。\n双星旧约年年在。笑尽人情改。有期无定是无期。说与小云新恨、也低眉。'},
    {t:'虞美人',a:'晏几道〔宋代〕',c:'闲敲玉镫隋堤路。一笑开朱户。素云凝淡月婵娟。门外鸭头春水、木兰船。\n吹花拾蕊嬉游惯。天与相逢晚。一声长笛倚楼时。应恨不题红叶、寄相思。'},
    {t:'虞美人',a:'晏几道〔宋代〕',c:'一弦弹尽仙韶乐。曾破千金学。玉楼银烛夜深深。愁见曲中双泪、落香襟。\n从来不奈离声怨。几度朱弦断。未知谁解赏新音。长是好风明月、暗知心。'},
    {t:'虞美人',a:'晏几道〔宋代〕',c:'玉箫吹遍烟花路。小谢经年去。更教谁画远山眉。又是陌头风细、恼人时。\n时光不解年年好。叶上秋声早。可怜蝴蝶易分飞。只有杏梁双燕、每来归。'},
    {t:'虞美人·碧桃天上栽和露',a:'秦观〔宋代〕',c:'碧桃天上栽和露，不是凡花数。乱山深处水萦回，可惜一枝如画为谁开？\n轻寒细雨情何限！不道春难管。为君沉醉又何妨，只怕酒醒时候断人肠。'},
    {t:'虞美人·波声拍枕长淮晓',a:'苏轼〔宋代〕',c:'波声拍枕长淮晓，隙月窥人小。恨情汴水自东流，只载一船离恨向西州。\n竹溪花浦曾同醉，酒味多于泪。谁教风鉴在尘埃？酝造一场烦恼送人来！'},
    {t:'虞美人·彩云易向秋空散',a:'纳兰性德〔清代〕',c:'彩云易向秋空散，燕子怜长叹。僽翻离合总无因，赢得一回僝僽一回亲。\n归鸿旧约霜前至，可寄香笺字。不如前事不思量，且枕红蕤欹侧看斜阳。'},
    {t:'虞美人·残灯风灭炉烟冷',a:'纳兰性德〔清代〕',c:'残灯风灭炉烟冷，相伴唯孤影。判教狼藉醉清樽，为问世间醒眼是何人。\n难逢易散花间酒，饮罢空搔首。闲愁总付醉来眠，只恐醒时依旧到樽前。'},
    {t:'虞美人·持杯遥劝天边月',a:'苏轼〔宋代〕',c:'在杯遥劝天边月。愿月圆无缺。在杯复更劝花枝。且愿花枝长在、莫离披。\n在杯月下花前醉。休问荣枯事。此欢能有几人知。对酒逢花不饮、待何时。'},
    {t:'虞美人·春情只到梨花薄',a:'纳兰性德〔清代〕',c:'春情只到梨花薄，片片催零落。夕阳何事近黄昏，不道人间犹有未招魂。\n银笺别梦当时句，密绾同心苣。为伊判作梦中人，索向画图清夜唤真真。'},
    {t:'虞美人·赋虞美人草',a:'辛弃疾〔宋代〕',c:'当年得意如芳草。日日春风好。拔山力尽忽悲歌。饮罢虞兮从此、奈君何。\n人间不识精诚苦。贪看青青舞。蓦然敛袂却亭亭。怕是曲中犹带、楚歌声。'},
    {t:'虞美人·黄昏又听城头角',a:'纳兰性德〔清代〕',c:'黄昏又听城头角，病起心情恶。药炉初沸短檠青，无那残香半缕恼多情。\n多情自古原多病，清镜怜清影。一声弹指泪如丝，央及东风休遣玉人知。'},
    {t:'虞美人·黄金谁解教歌舞',a:'张炎〔宋代〕',c:'黄金谁解教歌舞。留得当时谱。却情残意落人间。汉上行云迷却、旧巫山。妆楼何处寻樊素。空误周郎顾。一帘秋雨翦灯看。无限羁愁分付、玉箫寒。'},
    {t:'虞美人·廉纤小雨池塘遍',a:'周邦彦〔宋代〕',c:'廉纤小雨池塘遍。细点看萍面。一双燕子守朱门。比似寻常时候、易黄昏。\n宜城酒泛浮香絮。细作更阑语。相将羁思乱如云。又是一窗灯影、两愁人。'},
    {t:'虞美人·绿阴帘外梧桐影',a:'纳兰性德〔清代〕',c:'绿阴帘外梧桐影，玉虎牵金井。日听啼鴂出帘迟，恰到年年今日两相思。\n凄凉满地红心草，此恨谁知道。待将幽忆寄新词，分付芭蕉风定月斜时。'},
    {t:'虞美人·陌头柳色春将半',a:'秦观〔宋代〕',c:'陌头柳色春将半。枝上莺声唤。管游晓日绮罗稠。紫陌东风弦管、咽朱楼。\n少年抚景渐虚过。终日看花坐。独愁不见玉人留。洞府空教燕子、占风流。'},
    {t:'虞美人·琵琶',a:'苏轼〔宋代〕',c:'定场贺老今何在，几度新声改。怨声坐使旧声阑，俗耳只知繁手，不须弹。\n断弦试问谁能晓，七岁文姬小。试教弹作辊雷声，应有开元遗老，泪纵横。'},
    {t:'虞美人·秋夕信步',a:'纳兰性德〔清代〕',c:'愁痕满地无人省，露湿琅玕影。闲阶小立倍荒凉。还剩旧时月色在潇湘。\n薄情转是多情累，曲曲柔肠碎。红笺向壁字模糊，忆共灯前呵手为伊书。'},
    {t:'虞美人·曲阑干外天如水',a:'晏几道〔宋代〕',c:'曲阑干外天如水。昨夜还曾倚。初将明月比佳期。长向月圆时候、望人归。\n罗衣著破前香在。旧意谁教改。一春离恨懒调弦。犹有两行闲泪、宝筝前。'},
    {t:'虞美人·曲阑深处重相见',a:'纳兰性德〔清代〕',c:'曲阑深处重相见，匀泪偎人颤。凄凉别后两应同，最是不胜清怨月明中。\n半生已分孤眠过，山枕檀痕涴。忆来何事最销魂，第一折枝花样画罗裙。'},
    {t:'虞美人·群花泣尽朝来露',a:'辛弃疾〔宋代〕',c:'群花泣尽朝来露。争奈春归去。不知庭下有荼靡。偷得十分春色、怕春知。\n淡中有味清中贵。飞絮残英避。露华微渗玉肌香。恰似杨妃初试、出兰汤。'},
    {t:'虞美人·三之三',a:'秦观〔宋代〕',c:'行行信马横塘畔。烟水秋平岸。绿荷多少夕阳中。知为阿谁凝恨、背西风。\n红妆艇子来何处。荡桨偷相顾。鸳鸯惊起不无愁。柳外一双飞去、却回头。'},
    {t:'虞美人·三之一',a:'秦观〔宋代〕',c:'高城望断尘如雾。不见联骖处。夕阳村外小湾头。只有柳花无数。送归舟。\n琼枝玉树频相见。只恨离人远。欲将幽事寄青楼。争奈无情江水、不西流。'},
    {t:'虞美人·湿红笺纸回纹字',a:'晏几道〔宋代〕',c:'湿红笺纸回纹字。多少柔肠事。去年双燕欲归时。还是碧云千里、锦书迟。\n南楼风月长依旧。别恨无端有。倩谁横笛倚危阑。今夜落梅声里、怨关山。'},
    {t:'虞美人·疏篱曲径田家小',a:'周邦彦〔宋代〕',c:'疏篱曲径田家小。云树开清晓。天寒山色有无中。野外一声钟起、送孤蓬。\n添衣策马寻亭堠。愁抱惟宜酒。菰蒲睡鸭占陂塘。纵被行人惊散、又成双。'},
    {t:'虞美人·疏梅月下歌金缕',a:'晏几道〔宋代〕',c:'疏梅月下歌金缕。忆共文君语。更谁情浅似春风。一夜满枝新绿、替残红。\n苹香已有莲开信。两桨佳期近。采莲时节定来无。醉后满身花影、倩人扶。'},
    {t:'虞美人·述怀',a:'苏轼〔宋代〕',c:'归心正似三春草。试著莱衣小。橘怀几日向翁开。怀祖已瞋文度、不归来。\n禅心已断人间爱。只有平交在。笑论瓜葛一枰同。看取灵光新赋、有家风。'},
    {t:'虞美人·为梁汾赋',a:'纳兰性德〔清代〕',c:'凭君料理花间课，莫负当初我。眼看鸡犬上天梯，黄九自招秦七共泥犁。\n瘦狂那似痴肥好，判任痴肥笑。笑他多病与长贫，不及诸公衮衮向风尘。'},
    {t:'虞美人·小梅枝上东君信',a:'晏几道〔宋代〕',c:'小梅枝上东君信。雪后花期近。南枝开尽北枝开。长被陇头游子、寄春来。\n年年衣袖年年泪。总为今朝意。问谁同是忆花人。赚得小鸿眉黛、也低颦。'},
    {t:'虞美人·宜州见梅作',a:'黄庭坚〔宋代〕',c:'天涯也有江南信。梅破知春近。夜阑风细得香迟。不道晓来开遍、向南枝。\n玉台弄粉花应妒。飘到眉心住。平生个里愿杯深。去国十年老尽、少年心。'},
    {t:'虞美人·银床淅沥青梧老',a:'纳兰性德〔清代〕',c:'银床淅沥青梧老，屧粉秋蛩扫。采香行处蹙连钱，拾得翠翘何恨不能言。\n回廊一寸相思地，落月成孤倚。背灯和月就花阴，已是十年踪迹十年心。'},
    {t:'虞美人·有美堂赠述古',a:'苏轼〔宋代〕',c:'湖山信是东南美，一望弥千里。倒君能得几回来？便倒樽前醉倒更徘徊。\n沙河塘里灯初上，水调谁家唱？夜阑风静欲归时，惟有一江明月碧琉璃。'},
    {t:'虞美人·虞美人',a:'王安石〔宋代〕',c:'虞美人，态浓意远淑且真。\n同辇楚君侍君侧，六宫粉黛无颜色。\n楚歌四面起，形势反苍黄。\n夜闻汉嘶晓无迹，蛾眉萧飒如秋霜。\n汉家离宫三十六，缓歌慢舞凝丝竹。\n人间举眼尽堪悲，独阴崖结茅屋。\n美人为黄土，草木皆含愁。\n红房紫谭处处有，听曲低昂如有求。\n青天漫漫覆长路，今人犁田昔人墓。\n虞兮虞兮奈若何，不见玉颜空死处。'},
    {t:'虞美人·正宫',a:'周邦彦〔宋代〕',c:'灯前欲去仍留恋。肠断朱扉远。未须红雨洗香腮。待得蔷薇花谢、便归来。\n舞腰歌版闲时按。一任傍人看。金炉应见旧残煤。莫使恩情容易、似寒灰。'},
    {t:'虞美人·正宫·第三',a:'周邦彦〔宋代〕',c:'玉觞才掩朱弦悄。弹指壶天晓。畔头犹认倚墙花。只向小桥南畔、便天涯。\n银蟾依旧当窗满。顾影魂先断。凄风休飐半残灯。拟倩今宵归梦、到云屏。'},
    {t:'与白明府游江',a:'孟浩然〔唐代〕',c:'故人来自远，邑宰复初临。执手恨为别，同舟无异心。\n沿洄洲渚趣，演漾弦歌音。谁识躬耕者，年年梁甫吟。'},
    {t:'与崔策登西山',a:'柳宗元〔唐代〕',c:'鹤鸣楚山静，露白秋江晓。\n连袂度危桥，萦回出林杪。\n西岑极远目，毫末皆可了。\n重叠九疑高，微茫洞庭小。\n迥穷两仪际，高出万象表。\n驰景泛颓波，遥风递寒筱。\n谪居安所习，稍厌从纷扰。\n生同胥靡遗，寿比彭铿夭。\n蹇连困颠踣，愚蒙怯幽眇。\n非令亲爱疏，谁使心神悄。\n偶兹遁山水，得以观鱼鸟。\n吾子幸淹留，缓我愁肠绕。'},
    {t:'与村老对饮',a:'韦应物〔唐代〕',c:'鬓眉雪色犹嗜酒，言辞淳朴古人风。\n乡村年少生离乱，见话先朝如梦中。'},
    {t:'与弟游家园',a:'张九龄〔唐代〕',c:'定省荣君赐，来归是昼游。林乌飞旧里，园果让新秋。\n枝长南庭树，池临北涧流。星霜屡尔别，兰麝为谁幽。\n善积家方庆，恩深国未酬。栖栖将义动，安得久情留。'},
    {t:'与二三友秋宵会话清上人院',a:'孟郊〔唐代〕',c:'何处山不幽，此中情又别。一僧清一磬，七子吟秋月。\n激石泉韵清，寄枝风啸咽。泠然诸境静，顿能浮累灭。\n扣寂兼探真，通宵讵能辍。\n好鸟无杂栖，华堂有嘉携。琴樽互倾奏，歌赋相和谐。\n但嘉鱼水合，莫令云雨乖。一为鹍鸡弹，再鼓壮士怀。\n初景待谁晓，新春逐君来。愿言良友会，高驾不知回。'},
    {t:'与高适薛据同登慈恩寺浮图',a:'岑参〔唐代〕',c:'塔势如涌出，孤高耸天宫。\n登临出世界，磴道盘虚空。\n突兀压神州，峥嵘如鬼工。\n四角碍白日，七层摩苍穹。\n下窥指高鸟，俯听闻惊风。\n连山若波涛，奔凑似朝东。\n青槐夹驰道，宫馆何玲珑。\n秋色从西来，苍然满关中。\n五陵北原上，万古青濛濛。\n净理了可悟，胜因夙所宗。\n誓将挂冠去，觉道资无穷。'},
    {t:'与歌者何戡',a:'刘禹锡〔唐代〕',c:'二十余年别帝京，重闻天乐不胜情。\n旧人唯有何戡在，更与殷勤唱渭城。'},
    {t:'与歌者米嘉荣',a:'刘禹锡〔唐代〕',c:'唱得凉州意外声，旧人唯数米嘉荣。\n近来时世轻先辈，好染髭须事后生。'},
    {t:'与韩库部会王祠曹宅作',a:'韦应物〔唐代〕',c:'闲门荫堤柳，秋渠含夕清。微风送荷气，坐客散尘缨。\n守默共无吝，抱冲俱寡营。良时颇高会，琴酌共开情。'},
    {t:'与韩愈、李翱、张籍话别',a:'孟郊〔唐代〕',c:'朱弦奏离别，华灯少光辉。物色岂有异，人心顾将违。\n客程殊未已，岁华忽然微。秋桐故叶下，寒露新雁飞。\n远游起重恨，送人念先归。夜集类饥鸟，晨光失相依。\n马迹绕川水，雁书还闺闱。常恐亲朋阻，独行知虑非。'},
    {t:'与杭州薛司户登樟亭楼作',a:'孟浩然〔唐代〕',c:'水楼一登眺，半出青林高。帟幕英僚敞，芳筵下客叨。\n山藏伯禹穴，城压伍胥涛。今日观溟涨，垂纶学钓鳌。'},
    {t:'与浩初上人同看山寄京华亲故',a:'柳宗元〔唐代〕',c:'海畔尖山似剑铓，秋来处处割愁肠。\n若为化得身千亿，散上峰头望故乡。'},
    {t:'与鄠县群官泛渼陂',a:'岑参〔唐代〕',c:'万顷浸天色，千寻穷地根。舟移城入树，岸阔水浮村。\n闲鹭惊箫管，潜虬傍酒樽。暝来呼小吏，列火俨归轩。'},
    {t:'与鄠县源少府泛渼陂·得人字',a:'岑参〔唐代〕',c:'载酒入天色，水凉难醉人。清摇县郭动，碧洗云山新。\n吹笛惊白鹭，垂竿跳紫鳞。怜君公事后，陂上日娱宾。'},
    {t:'与黄侍御北津泛舟',a:'孟浩然〔唐代〕',c:'津无蛟龙患，日夕常安流。本欲幸骢马，何如同鹢舟。\n岂伊今日幸，曾是昔年游。莫奏琴中鹤，且随波上鸥。\n堤缘九里郭，山面百城楼。自顾躬耕者，才非管乐俦。\n闻君荐草泽，从此泛沧洲。'},
    {t:'与贾岛闲游',a:'张籍〔唐代〕',c:'水北原南草色新，雪消风暖不生尘。\n城中车马应无数，能解闲行有几人。'},
    {t:'与李十二白同寻范十隐居',a:'杜甫〔唐代〕',c:'李侯有佳句，往往似阴铿。\n余亦东蒙客，怜君如弟兄。\n醉眠秋共被，携手日同行。\n更想幽期处，还寻北郭生。\n入门高兴发，侍立小童清。\n落景闻寒杵，屯云对古城。\n向来吟橘颂，谁与讨莼羹？\n不愿论簪笏，悠悠沧海情。'},
    {t:'与卢孟明别后宿南湖对月',a:'皎然〔唐代〕',c:'五湖生夜月，千里满寒流。旷望烟霞尽，凄凉天地秋。\n相思路渺渺，独梦水悠悠。何处空江上，裴回送客舟。'},
    {t:'与卢员外象过崔处士兴宗林亭',a:'王维〔唐代〕',c:'绿树重阴盖四邻，青苔日厚自无尘。\n科头箕踞长松下，白眼看他世上人。'},
    {t:'与卢陟同游永定寺北池僧斋',a:'韦应物〔唐代〕',c:'密竹行已远，子规啼更深。绿池芳草气，闲斋春树阴。\n晴蝶飘兰径，游蜂绕花心。不遇君携手，谁复此幽寻。'},
    {t:'与梦得沽酒闲饮且约后期',a:'白居易〔唐代〕',c:'少时犹不忧生计，老后谁能惜酒钱？\n共把十千沽一斗，相看七十欠三年。\n闲征雅令穷经史，醉听清吟胜管弦。\n更待菊黄家酝熟，共君一醉一陶然。'},
    {t:'与倪老伯辉九曲池有怀元龙参寥',a:'秦观〔宋代〕',c:'云月娟娟淮海秋，隋家池上共浮游。\n可怜一段风流事，特欠支郎与子猷。'},
    {t:'与人约访林处士阻雨因寄',a:'范仲淹〔宋代〕',c:'闲约诸公扣隐扃，江天风雨忽飘零。\n方怜春满王孙草，可忍云遮处士星。\n蕙帐未容登末席，兰舟无赖寄前汀。\n湖山早晚逢晴齐，重待寻仙入翠屏。'},
    {t:'与舍弟华藏院忞君亭咏竹',a:'王安石〔宋代〕',c:'一迳森然四座凉，残阴余韵去材长。\n人怜直节生来瘦，自许高材老更刚。\n曾与蒿藜同雨露，终随松柏到冰霜。\n烦君惜取根株在，欲乞伶伦学凤凰。'},
    {t:'与生公寻幽居处',a:'张九龄〔唐代〕',c:'同方久厌俗，相与事遐讨。及此源山去，窅然岩径好。\n疑入武陵源，如逢汉阴老。清谐欣有得，幽仙欻盈抱。\n我本玉阶侍，偶访金仙道。兹焉求卜筑，所过皆神造。\n岁晚林始敷，日晏崖方杲。不种缘岭竹，岂植临潭草。\n即途可淹留，随日成黼藻。期为静者说，曾是终焉保。\n今为简书畏，只令归思浩。'},
    {t:'与生公游石窟山',a:'张九龄〔唐代〕',c:'探秘孰云远，忘怀复尔同。日寻高深意，宛是神仙中。\n跻险构灵室，诡制非人功。潜洞黝无底，殊庭忽似梦。\n岂如武安凿，自若茅山通。造物良有寄，嬉游乃惬衷。\n犹希咽玉液，从此升云空。咄咄共携手，泠然且驭风。'},
    {t:'与史郎中钦听黄鹤楼上吹笛',a:'李白〔唐代〕',c:'一为迁客去长沙，西望长安不见家。\n黄鹤楼中吹玉笛，江城五月落梅花。'},
    {t:'与同年李定言曲水闲话戏作',a:'李商隐〔唐代〕',c:'海燕参差沟水流，同君身世属离忧。\n相携花下非秦赘，对泣春天类楚囚。\n碧草暗侵穿苑路，珠帘不卷枕江楼。\n莫惊玉媵埋香骨，地下伤春亦白头。'},
    {t:'与王昌龄宴王道士房',a:'孟浩然〔唐代〕',c:'归来卧青山，常梦游清都。漆园有傲吏，惠好在招呼。\n书幌神仙箓，画屏山海图。酌霞复对此，宛似入蓬壶。'},
    {t:'与王二十一员外涯游枋口柳溪',a:'孟郊〔唐代〕',c:'万株古柳根，拏此磷磷溪。野榜烟屈曲，仙浔无端倪。\n春桃散红烟，寒竹含晚凄。晓听忽以异，芳景安能齐。\n共疑落镜中，坐泛红景低。水意酒易醒，浪情事非迷。\n小儒峭章句，大贤嘉提携。潜窦韵灵瑟，翠崖鸣玉珪。\n主人稷卨翁，德茂芝朮畦。凿出幽隐端，气象皆升跻。\n曾是清乐抱，逮兹几省溪。宴位席兰草，滥觞惊凫鹥。\n灵味荐鲂瓣，金花屑橙齑。江调摆衰俗，洛风远尘泥。\n徒言奏狂狷，讵敢忘筌蹄。'},
    {t:'与王二十一员外涯游昭成寺',a:'孟郊〔唐代〕',c:'洛友寂寂约，省骑霏霏尘。游僧步晚磬，话茗含芳春。\n瑶策冰入手，粉壁画莹神。赪廓芙蓉霁，碧殿琉璃匀。\n玄讲岛岳尽，渊咏文字新。屡笑寒竹宴，况接青云宾。\n顾惭馀眷下，衰瘵婴残身。'},
    {t:'与王六履震广州津亭晓望',a:'张九龄〔唐代〕',c:'明发临前渚，寒来净远空。水纹天上碧，日气海边红。\n景物纷为异，人情赖此同。乘槎自有适，非欲破长风。'},
    {t:'与微之同赋梅花得香字三首',a:'王安石〔宋代〕',c:'结子非贪鼎鼐尝，偶先红杏占年芳。\n从教腊雪埋藏得，却怕春风漏泄香。\n不御铅华知国色，只裁云缕想仙装。\n少陵为尔牵诗兴，可是无心赋海棠。'},
    {t:'与夏十二登岳阳楼',a:'李白〔唐代〕',c:'楼观岳阳尽，川迥洞庭开。\n雁引愁心去，山衔好月来。\n云间连下榻，天上接行杯。\n醉后凉风起，吹人舞袖回。'},
    {t:'与薛肇明弈棋赌梅花诗输一首',a:'王安石〔宋代〕',c:'华发寻春喜见梅，一株临路雪倍堆。\n凤城南陌他年忆，香杳难随驿使来。'},
    {t:'与颜钱塘登障楼望潮作',a:'孟浩然〔唐代〕',c:'百里闻雷震，鸣弦暂辍弹。\n府中连骑出，江上待潮观。\n照日秋云迥，浮天渤澥宽。\n惊涛来似雪，一座凛生寒。'},
    {t:'与殷晋安别',a:'陶渊明〔魏晋〕',c:'去先作晋安南府长史掾，因居作阳，后作太尉参军，移家东下。作此以赠。\n游好非少长，一遇尽去勤。\n信宿酬清话，益复知为亲。\n去岁家南里，薄作少时邻。\n负杖肆游从，淹留忘宵晨。\n语默自殊势，亦知当乖分。\n未谓事已及，兴言在兹春。\n飘飘西来风，悠悠东去云。\n山川千里外，言笑难为因。\n良才不隐世，江湖多贱贫。\n脱有经过便，念来存故人。'},
    {t:'与友生野饮效陶体',a:'韦应物〔唐代〕',c:'携酒花林下，前有千载坟。于时不共酌，奈此泉下人。\n始自玩芳物，行当念徂春。聊舒远世踪，坐望还山云。\n且遂一欢笑，焉知贱与贫。'},
    {t:'与张十八同效阮步兵一日复一夕',a:'韩愈〔唐代〕',c:'一日复一日，一朝复一朝。只见味不如，不见味所超。\n食作前日味，事作前日调。不知久不死，煎煎尚谁要。\n富贵自絷拘，贫贱亦煎焦。俯仰未得所，一世已解镳。\n譬如笼中鹤，六翮无所摇。譬如兔得蹄，安用东西跳。\n还看古人书，复举前人瓢。未知所穷竟，且作新诗谣。'},
    {t:'与张焘太博行忻代间因话江山作',a:'范仲淹〔宋代〕',c:'数年风土塞门行，说着江山意暂清。\n求取罢兵南国去，满楼苍翠是平生。'},
    {t:'与张折冲游耆闍寺',a:'孟浩然〔唐代〕',c:'释子弥天秀，将军武库才。横行塞北尽，独步汉南来。\n贝叶传金口，山楼作赋开。因君振嘉藻，江楚气雄哉。'},
    {t:'与章子厚',a:'苏轼〔宋代〕',c:'某启：仆居东坡，作陂种稻。有田五十亩，身耕妻蚕，聊以卒岁。昨日一牛病几死，牛医不识其状，而老妻识之，曰：“此牛发豆斑疮也，法当以青蒿粥啖之。”用其言而效。勿谓仆谪居之后，一向便作村舍翁，老妻犹解接黑牡丹也。言此发公千里一笑。'},
    {t:'与长子受之（节选）',a:'朱熹〔宋代〕',c:'交游之间，最宜审慎。大凡敦厚忠信，能攻吾过者，益友也；其谄谀轻薄，导人为恶者，损友也。以此求之，百无所失矣。但须克己修身，痛加检点。若自己偏僻卑污，不能从善，则益友日远，损友日近也。'},
    {t:'与郑几夫',a:'晏几道〔宋代〕',c:'小白长红又满枝，筑球场外独支颐。\n春风自是人间客，主张繁华得几时？'},
    {t:'与郑介夫',a:'晏几道〔宋代〕',c:'小白长红又满枝，筑毬场外独支颐。春风自是人间客，张主繁华得几时。'},
    {t:'与诸子登岘山',a:'孟浩然〔唐代〕',c:'人事有代谢，往来成古今。\n江山浅胜迹，我辈复登临。\n水落鱼梁浅，天寒梦泽深。\n羊公碑尚在，读罢泪沾襟。'},
    {t:'与子上野步',a:'杨万里〔宋代〕',c:'篱落深深巷，茅茨小小家。\n冬晴好行脚，何处不梅花。'},
    {t:'屿赠白云先生王迥',a:'孟浩然〔唐代〕',c:'悠悠清水江，水落沙屿出。\n回潭石下深，绿筿岸傍密。\n鲛人潜不见，渔父歌自逸。\n忆与君别时，泛舟如昨日。\n夕阳开返照，中坐兴非一。\n南望鹿门山，归来恨如失。'},
    {t:'宇文秀才斋中海柳咏',a:'孟郊〔唐代〕',c:'玉缕青葳蕤，结为芳树姿。忽惊明月钩，钩出珊瑚枝。\n灼灼不死花，蒙蒙长生丝。饮柏泛仙味，咏兰拟古词。\n霜风清飕飕，与君长相思。'},
    {t:'羽林行',a:'孟郊〔唐代〕',c:'朔雪寒断指，朔风劲裂冰。\n胡中射雕者，此日犹不能。\n翩翩羽林儿，锦臂飞苍鹰。\n挥鞭快白马，走出黄河凌。'},
    {t:'雨',a:'李商隐〔唐代〕',c:'摵摵度瓜园，依依傍竹轩。秋池不自冷，风叶共成喧。\n窗迥有时见，檐高相续翻。侵宵送书雁，应为稻粱恩。'},
    {t:'雨',a:'杜甫〔唐代〕',c:'万木云深隐，连山雨未开。\n风扉掩不定，水鸟过仍回。\n鲛馆如鸣杼，樵舟岂伐枚。\n清凉破炎毒，衰意欲登台。'},
    {t:'雨',a:'杜牧〔唐代〕',c:'连云接塞添迢递，洒幕侵灯送寂寥。\n一夜不眠孤客耳，主人窗外有芭蕉。'},
    {t:'雨不绝',a:'杜甫〔唐代〕',c:'鸣雨既过渐细微，映空摇飏如丝飞。\n阶前短草泥不乱，院里长条风乍稀。\n舞石旋应将乳子，行云莫自湿仙衣。\n眼边江舸何匆促，未待安流逆浪归。'},
    {t:'雨过偶书',a:'王安石〔宋代〕',c:'霈然甘泽洗尘寰，南亩东郊共慰颜。\n地望岁功还物外，天将生意与人间。\n霁分星斗风雷静，凉入轩窗枕簟闲。\n谁似浮云知进退，才成霖雨便归山。'},
    {t:'雨过至城西苏家',a:'黄庭坚〔宋代〕',c:'飘然一雨洒青春，九陌净无车日尘。\n渐散紫烟笼帝阙，稍回晴日丽天津。\n花飞衣袖红香湿，柳拂鞍鞯绿色匀。\n管领风光唯痛饮，都城谁是得闲人。'},
    {t:'雨后秋凉',a:'白居易〔唐代〕',c:'夜来秋雨后，秋气飒然新。\n团扇先辞手，生衣不著身。\n更添砧引思，难与簟相亲。\n此境谁偏觉，贫闲老瘦人。'},
    {t:'雨后田间杂纪五首·其二',a:'杨万里〔宋代〕',c:'田水高低各斗鸣，溪流奔放更欢声。\n小儿倒捻青梅朵，独立茅檐看客行。'},
    {t:'雨后田间杂纪五首·其五',a:'杨万里〔宋代〕',c:'正是山花最闹时，浓浓淡淡未离披。\n映山红与昭亭紫，挽住行人赠一枝。'},
    {t:'雨后望月',a:'李白〔唐代〕',c:'四郊阴霭散，开户半蟾生。\n万里舒霜合，一条江练横。\n出时山眼白，高后海心明。\n为惜如团扇，长吟到五更。'},
    {t:'雨后晓行独至愚溪北池',a:'柳宗元〔唐代〕',c:'宿云散洲渚，晓日明村坞。\n高树临清池，风惊夜来雨。\n予心适无事，偶此成宾主。'},
    {t:'雨霖铃·寒蝉凄切',a:'柳永〔宋代〕',c:'寒蝉凄切，对长亭晚，骤雨初歇。都门帐饮无绪，留恋处，兰舟催发。执手相看泪眼，竟无语凝噎。念去去，千里烟波，暮霭沉沉楚天阔。\n多情自古伤离别，更那堪，冷落清秋节！今宵酒醒何处？杨柳岸，晓风残月。此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说？'},
    {t:'雨霖铃·孜孜矻矻',a:'王安石〔宋代〕',c:'孜孜矻矻。向无明里、强作窠窟。仓名仓利何济，堪留恋处，轮回仓猝。幸有明空妙觉，可弹指超作。缘底事、抛了全潮，认一仓沤作瀛渤。\n本源自性天真佛。只些些、妄想中埋没。贪他眼花阳艳，谁信道、本来无物。一旦茫然，终被阎罗老子相屈。便纵有、千种机筹，怎免伊唐突。'},
    {t:'雨晴至江渡',a:'柳宗元〔唐代〕',c:'江雨初晴思远步，日西独向愚溪渡。\n渡头水落村径成，撩乱浮槎在高树。'},
    {t:'雨声',a:'元稹〔唐代〕',c:'风吹竹叶休还动，雨点荷心暗复明。\n曾向西江船上宿，惯闻寒夜滴篷声。'},
    {t:'雨夜读书',a:'陆游〔宋代〕',c:'一灯如萤雨潺潺，老夫读书蓬户间。\n但与古人对生面，那恨镜里凋朱颜。\n功名本来我辈事，人自蹭蹬天何悭？\n君看病骥瘦露骨，不思仗下思天山。'},
    {t:'雨夜感怀',a:'韦应物〔唐代〕',c:'微雨洒高林，尘埃自萧散。\n耿耿心未平，沉沉夜方半。\n独惊长簟冷，遽觉愁鬓换。\n谁能当此夕，不有盈襟叹。'},
    {t:'雨中春山',a:'杨万里〔宋代〕',c:'谁作春山新幛子，尖峰为笔天为纸。\n近看点缀八九山，山外远山三万里。\n纸痕惨淡远山昏，上有长松青到云。\n自嫌松色太青在，旋拈粉笔轻轻盖。\n须臾粉淡松复青，至竟远山描不成。'},
    {t:'雨中登岳阳楼望君山二首',a:'黄庭坚〔宋代〕',c:'投荒万死鬓毛斑，生入瞿塘滟滪关。\n未到江南先一笑，岳阳楼上对君山。\n满川风雨独凭栏，绾结湘娥十二鬟。\n可惜不当湖水面，银山堆里看青山。'},
    {t:'雨中花·剪翠妆红欲就',a:'晏殊〔宋代〕',c:'剪翠妆红欲就，折得清香满袖。一对鸳鸯眠未足，叶下长相守。\n莫傍细条寻嫩藕，怕绿刺、罥衣伤手。可惜许、月明风露好，恰在人归后。'},
    {t:'雨中花·夜行船',a:'苏轼〔宋代〕',c:'初至密州。以累年旱蝗。斋素累月。方春牡丹盛开。遂不获一赏。至九月。忽开千叶一朵。雨中特为置酒。遂作。\n今岁花时深院，尽日东风，荡扬茶烟。但有绿苔芳草，柳絮榆钱。闻道城西，长廊古寺，甲第名园。有国艳带酒，天香染袂，为我留连。\n清明过了，残红无处，对此泪洒尊前。秋向晚，一枝何事，向我依然。高会聊追短景，清商不暇馀妍。不如留取，十分春态，付与明年。'},
    {t:'雨中花·指点虚无征路',a:'秦观〔宋代〕',c:'指点虚无征路，醉乘斑虬，远访西极。正天风吹落，满空寒白。玉女明星迎笑，何苦自淹尘域？正火轮飞上，雾卷烟开，洞观金碧。\n重重观阁，横枕鳌峰，水面倒衔苍石。随处有奇香幽火，杳然难测。好是蟠桃熟后，阿环偷报消息。在青天碧海，一枝难遇，占取春色。'},
    {t:'雨中花慢·邃院重帘何处',a:'苏轼〔宋代〕',c:'邃院重帘何处，惹得多情，愁对风光。睡起酒阑花谢，蝶乱蜂忙。今夜何人，吹笙北岭，待月西厢。空怅望处，一株红杏，斜倚低墙。\n羞颜易变，傍人先觉，到处被着猜防。谁信道，些儿恩爱。无限凄凉。好事若无间阻，幽欢却是寻常。一般滋味，就中香美，除是偷尝。'},
    {t:'雨中寄元宗简',a:'张籍〔唐代〕',c:'秋堂羸病起，盥漱风雨朝。\n竹影冷疏涩，榆叶暗飘萧。\n街径多坠果，墙隅有蜕蜩。\n延瞻游步阻，独坐闲思饶。\n君居应如此，恨言相去遥。'},
    {t:'雨中赠仙人山贾山人·即贾鹏也',a:'柳宗元〔唐代〕',c:'寒江夜雨声潺潺，晓云遮尽仙人山。\n遥知玄豹在深处，下笑羁绊泥涂间。'},
    {t:'雨中作',a:'杜牧〔唐代〕',c:'贱子本幽慵，多为隽贤侮。得州荒僻中，更值连江雨。\n一褐拥秋寒，小窗侵竹坞。浊醪气色严，皤腹瓶罂古。\n酣酣天地宽，怳怳嵇刘伍。但为适性情，岂是藏鳞羽。\n一世一万朝，朝朝醉中去。'},
    {t:'雨作，抵暮复晴五首',a:'杨万里〔宋代〕',c:'细雨如尘复似烟，两淮渡口各收船。\n南商北贾俱星散，古庙无人烧纸钱。'},
    {t:'禹庙',a:'杜甫〔唐代〕',c:'禹庙空山里，秋风落日斜。\n荒庭垂橘柚，古屋画龙蛇。\n云气嘘青壁，江声走白沙。\n早知乘四载，疏凿控三巴。'},
    {t:'庾楼晓望',a:'白居易〔唐代〕',c:'独凭朱槛立凌晨，山送初明水送新。\n竹雾晓笼衔岭月，频风暖送过江春。\n子城阴处犹残雪，衙鼓声前未有尘。\n三百年来庾楼上，曾经多少望乡人。'},
    {t:'玉关寄长安李主簿',a:'岑参〔唐代〕',c:'东去长安万里馀，故人何惜一行书。\n玉关西望堪肠断，况复明朝是岁除。'},
    {t:'玉壶吟',a:'李白〔唐代〕',c:'烈士击玉壶，壮心惜暮年。\n三杯拂剑舞秋月，忽然高咏涕泗涟。\n凤凰初下紫泥诏，谒帝称觞登御筵。\n揄扬九重万乘主，谑浪赤墀青琐贤。\n朝天数换飞龙马，敕赐珊瑚白玉鞭。\n世人不识东方朔，大隐金门是谪仙。\n西施宜笑复宜颦，丑女效之徒累身。\n君王虽爱蛾眉好，无奈宫中妒杀人！'},
    {t:'玉蝴蝶·淡荡素商行暮',a:'柳永〔宋代〕',c:'淡荡素商行暮，远空雨歇，平野烟收。满目江山，堪助楚客冥搜。素光动、云涛涨晚，紫翠冷、霜𪩘横秋。景清幽。渚兰香谢，汀树红愁。\n良俦。西风吹帽，东篱携酒，共结欢游。浅酌低吟，坐中俱是饮家流。对残晖、登临休叹，赏令节、酩酊方酬。且相留。眼前尤物，盏里忘忧。'},
    {t:'玉蝴蝶·赋玉绣球花',a:'张炎〔宋代〕',c:'留得一团和气，此花开尽，春已扬圆。虚白窗深，恍讶碧落星悬。扬芳丛、低翻雪羽，凝素艳、争簇千蝉。向西园。几回错认，明月秋千。\n欲觅生香何处，盈盈一水，空对娟娟。待折归来，倩谁偷解玉连环。试结取、鸳鸯锦带，好移傍、鹦鹉珠帘。晚阶前。落梅无数，因甚啼鹃。'},
    {t:'玉蝴蝶·渐觉芳郊明媚',a:'柳永〔宋代〕',c:'渐觉芳郊明媚，夜来膏雨，一洒尘埃。满目浅桃深杏，露染风裁。银塘静、鱼鳞簟展，烟岫翠、龟甲屏开。殷晴雷，云中鼓吹，游遍蓬莱。\n徘徊。集旟前后，三千珠履，十二金钗。雅俗熙熙，下车成宴尽春台。好雍容、东山妓女，堪笑傲、北海尊罍。且追陪，凤池归去，那更重来。'},
    {t:'玉蝴蝶·秋风凄切伤离',a:'温庭筠〔唐代〕',c:'秋风凄切伤离，行客未归时。塞嫩草先衰，江南雁到迟。\n芙蓉凋嫩脸，杨柳堕新眉。摇落使人悲，断肠谁得知。'},
    {t:'玉蝴蝶·是处小街斜巷',a:'柳永〔宋代〕',c:'是处小街斜巷，烂游花馆，连醉绛卮。选得芳容端丽，冠绝吴姬。绛唇轻、笑歌尽雅，莲步稳、举措肢奇。出屏帏。倚风情态，约素腰肢。\n当时。绮罗丛里，知名虽久，识面何迟。见了千花万柳，比并不如伊。未同欢、寸心暗许，欲话别、纤手重携。结前期。美人才子，合是相知。'},
    {t:'玉蝴蝶·望处雨收云断',a:'柳永〔宋代〕',c:'望处雨收云断，凭阑悄悄，目送秋光。晚景萧疏，堪动宋玉悲凉。水风轻、蘋花渐老，月露冷、梧叶飘黄。遣情伤。故人何在，烟水茫茫。\n难忘，文期酒会，几孤风月，屡变星霜。海阔山遥，未知何处是潇湘。念双燕、难凭远信，指暮天、空识归航。黯相望。断鸿声里，立尽斜阳。'},
    {t:'玉蝴蝶·误入平康小巷',a:'柳永〔宋代〕',c:'误入平康小巷，画檐深处，珠箔微褰。罗绮丛中，偶认旧识婵娟。翠眉开、娇横远岫，绿鬓亸、浓染春烟。忆情牵。粉墙曾恁，窥宋三年。\n迁延。珊瑚筵上，亲持犀管，旋叠香笺。要索新词，殢人含笑立尊前。接新声、珠喉渐稳，想旧意、波脸增妍。苦留连。凤衾鸳枕，忍负良天。'},
    {t:'玉蝴蝶其一',a:'柳永〔宋代〕',c:'望处雨收云断，凭栏悄悄，目送秋光。晚景萧疏，堪动宋玉悲凉。\n水风轻、萍花渐老，月露冷、梧叶飘黄。遣情伤。故人何在？\n烟水茫茫。\n难忘。文期酒会，几孤风月，屡变星霜。海阔山遥，未知何处是潇湘？\n念双燕、难凭远信，指暮天、空识归航。黯相望。断鸿声里，立尽斜阳。'},
    {t:'玉华宫',a:'杜甫〔唐代〕',c:'贞观二十一年，作玉华宫，后改为寺，在宜君县北凤凰谷。\n溪回松风长，苍鼠窜古瓦。\n不知何王殿，遗构绝壁下。\n阴房鬼火青，坏道哀湍泻。\n万籁真笙竽，秋色正萧洒。\n美人为黄土，况乃粉黛假。\n当时侍金舆，故物独石马。\n忧来藉草坐，浩歌泪盈把。\n冉冉征途间，谁是长年者？'},
    {t:'玉阶怨',a:'李白〔唐代〕',c:'玉阶生白露，夜久侵罗袜。\n却下水晶帘，玲珑望秋月。'},
    {t:'玉连环影',a:'纳兰性德〔清代〕',c:'何处几叶萧萧雨。湿尽檐花，花底人无语。掩屏山，玉炉寒。\n谁见两眉愁聚倚阑干。'},
    {t:'玉连环影·才睡',a:'纳兰性德〔清代〕',c:'才睡。愁压衾花碎。细数更筹，眼看银虫坠。\n梦难凭，讯难真，只是赚伊终日两眉颦。'},
    {t:'玉连环影·何处',a:'纳兰性德〔清代〕',c:'何处？几叶萧萧雨。湿尽檐花，花底无人语。\n掩屏山，玉炉寒。谁见两眉愁聚倚阑干。'},
    {t:'玉楼春',a:'周邦彦〔宋代〕',c:'大堤花艳惊郎目。秀色秾华看人足。休将宝瑟写幽怀，座上有人能顾曲。\n平波落照涵赪玉。画舸亭亭浮淡渌。临分何以祝深情，只有别离三万斛。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'斑骓路与阳台近。前度无题初借问。暖风鞭袖尽闲垂，微月帘栊曾暗认。\n梅花未足凭芳信。弦语岂堪传素恨。翠眉饶似远山长，寄与此愁颦不尽。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'采莲时候慵歌舞，永日闲从花里度。暗随苹末晓风来，直待柳梢斜月去。\n停桡共说江头路。临水楼台苏小住。细思巫峡梦回时，不减秦源肠断处。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'当年信道情无价。桃叶尊前论夫夜。脸红心绪学梅妆，眉翠工夫如月画。\n来时醉倒旗亭下。知是阿谁扶上马。忆曾挑尽五更灯，不记临分多少话。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'当年信道无情价\n桃叶尊前论夫夜\n脸红心绪学梅妆\n眉翠工夫如月画\n来时醉倒旗亭下\n知是阿谁扶上马\n忆曾挑尽五更灯\n不记临分多少话'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'芳年正是香英嫩。天与娇波长屏鬓。蕊珠宫里旧承恩，夜拂银屏朝把镜。\n云情去住终难信。花意有无休更问。醉中同尽一杯欢，归后各成孤枕恨。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'离鸾照罢尘生镜。几点吴霜侵绿鬓。琵琶弦上语无凭，豆蔻梢头春有信。\n相思拚损朱颜尽。天若多情终欲问。雪窗休记夜来寒，桂酒已消人去恨。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'红绡学舞腰肢软。旋织舞衣宫南染。织成云外雁行斜，染作江南春水浅。\n露桃宫里随歌管。一曲霓裳红日晚。归来双袖酒成痕，小字香笺无意展。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'旗亭西畔朝云住。沈水香烟长满路。柳阴分到画眉边，花片飞来垂手处。\n妆成尽任秋娘妒。袅袅盈盈当绣户。临风一曲醉朦腾，陌上行人凝恨去。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'轻风拂柳冰初绽。细雨消尘云未散。红窗青镜待妆梅，绿陌高楼催送雁。\n华罗歌扇金蕉盏。记得寻芳心绪惯。凤城寒尽又飞花，岁岁春光常有限。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'清歌学得秦娥似。金屋瑶台知姓字。可怜春恨一生心，长带粉痕双袖泪。\n从来懒话低眉事。今日新声谁会意。坐中应有赏音人，试问回肠曾断未。'},
    {t:'玉楼春',a:'晏几道〔宋代〕',c:'一尊相遇春风里。诗好似君人时几。吴姬十五语如弦，能唱当时楼下水。\n良辰易去如弹指。金盏十分须尽意。明朝三丈日高时，共拚醉头扶不起。'},
    {t:'玉楼春',a:'柳永〔宋代〕',c:'星闱上笏金章贵，\n重委外台疏储侍。\n百常天阁旧通班，\n九岁国储新上计。\n太仓日富中邦最，\n宣室夜思前席对。\n归心怡悦酒肠宽，\n不泛千锺应不醉。'},
    {t:'玉楼春',a:'秦观〔宋代〕',c:'参差帘影晨光动。露桃雨柳矜新宠。闲愁多仗酒驱除，春思不禁花从臾。\n倚楼听彻单于弄。却忆旧欢空有梦。当时误入饮牛津，何处重寻闻犬洞。'},
    {t:'玉楼春·春恨',a:'晏殊〔宋代〕',c:'绿杨芳草长亭路。年少抛人容易去。楼头残梦五更钟，花底离愁三月雨。\n无情不似多情苦。一寸还成千万缕。天涯地角有穷时，只有相思无尽处。'},
    {t:'玉楼春·大石',a:'周邦彦〔宋代〕',c:'当时携手城东道。月堕檐牙人睡了。酒边难使客愁惊，帐底不教春梦到。\n别来人事如秋草。应有吴霜侵翠葆。夕阳深锁绿苔门，一任卢郎愁里老。'},
    {t:'玉楼春·大石·第三',a:'周邦彦〔宋代〕',c:'玉奁收起新妆了。鬓畔斜枝红袅袅。浅颦轻笑百般宜，试著春衫犹更好。\n裁金簇翠天机巧。不称野人簪破帽。满头聊插片时狂，顿减十年尘土貌。'},
    {t:'玉楼春·雕鞍好为莺花住',a:'晏几道〔宋代〕',c:'雕鞍好为莺花住。占取东城南情路。尽教春思乱如云，莫管世情轻似絮。\n古来多被虚名误。宁负虚名身莫负。劝君频入醉乡来，此是无愁无恨处。'},
    {t:'玉楼春·东风又作无情计',a:'晏几道〔宋代〕',c:'东风又作无情计，艳粉娇红吹满地。碧楼帘影不遮愁，还似去年今日意。\n谁知错管春残事，到处登临曾费泪。此时金盏直须深，看尽落花能几醉！'},
    {t:'玉楼春·风前欲劝春光住',a:'辛弃疾〔宋代〕',c:'风前欲劝春光住。春在城南芳零路。未随流落水边花，且作飘零泥上絮。\n镜中已觉星星误。人不负春春自负。梦回人远许多愁，只在梨花风雨处。'},
    {t:'玉楼春·凤楼郁郁呈嘉瑞',a:'柳永〔宋代〕',c:'凤楼郁郁呈嘉瑞。降圣覃恩延晨裔。醮台清夜洞天严，公宴凌晨箫鼓沸。\n保生酒劝椒香腻，延寿带垂金缕细。几行鹓鹭望尧云，齐共南山呼万岁。'},
    {t:'玉楼春·皇都今夕知何夕',a:'柳永〔宋代〕',c:'皇都今夕知何夕。特地风光盈灯陌。金丝玉管咽春空，蜡炬兰灯晓夜色。\n凤楼十二神仙宅。珠履三千鹓鹭客。金吾不禁六街游，狂杀云踪并雨迹。'},
    {t:'玉楼春·集句',a:'秦观〔宋代〕',c:'狂风落尽深红色。春色恼人眠尘得。泪沿红粉湿罗巾，怨入青尘愁锦瑟。\n岂知一夕秦楼客。烟树重重芳信隔。倚楼无语欲销魂，柳外飞来双羽玉。'},
    {t:'玉楼春·阆风歧路连银阙',a:'柳永〔宋代〕',c:'阆风歧路连银阙，曾许金桃容易窃。乌龙未睡定惊猜，鹦鹉能言防漏泄。\n匆匆纵得邻香雪，窗隔残烟帘映月。别来也拟不思量，争奈余香犹未歇。'},
    {t:'玉楼春·琼酥酒面风吹醒',a:'晏几道〔宋代〕',c:'琼酥酒面风吹醒。一缕斜红临晚镜。小颦微笑尽妖娆，浅注轻匀长淡净。\n手挼梅蕊寻香径。正是佳期期未定。春来还为个般愁，瘦损宫腰罗带剩。'},
    {t:'玉楼春·三三两两谁家女',a:'辛弃疾〔宋代〕',c:'三三两两谁家女。听取鸣禽枝时语。提壶沽酒已多时，婆饼焦时须早去。\n醉中忘却来时路。借问行人家住处。只寻古庙那边行，更过溪南乌桕树。'},
    {t:'玉楼春·桃溪不作从容住',a:'周邦彦〔宋代〕',c:'桃溪不作从容住，秋藕绝来无续处。当时相候赤阑桥，今日独寻黄叶路。\n烟中列岫青无数，雁背夕阳红欲暮。人如风后入江云，情似雨馀粘地絮。'},
    {t:'玉楼春·戏赋云山',a:'辛弃疾〔宋代〕',c:'何人半夜推山去？四面浮云猜是汝。常时相对两三峰，走遍溪头无觅处。\n西风瞥起云横度，忽见东南天一柱。老僧拍手笑相夸，且喜青山依旧住。'},
    {t:'玉楼春·星闱上笏金章贵',a:'柳永〔宋代〕',c:'星闱上笏金章贵，重委外台疏储侍。百常天阁旧通班，九岁国储新上计。\n太仓日富中邦最。宣室夜思前席对。归心怡悦酒肠宽，不泛千钟应不醉。'},
    {t:'玉楼春·昭华夜醮连清曙',a:'柳永〔宋代〕',c:'昭华夜醮连清曙。金殿霓旌笼瑞雾。九枝擎烛灿繁星，百和焚香抽翠缕。\n香罗荐地延真驭。万乘凝旒听秘语。卜年无用考灵龟，从此乾坤齐历数。'},
    {t:'玉楼春仙吕惆怅',a:'周邦彦〔宋代〕',c:'玉琴虚下伤心泪。只有文君知融意。帘烘楼迥月宜人，酒暖香融春有味。\n萋萋芳草迷千里。惆怅王孙行未已。天涯回首一销魂，二十四桥歌舞地。'},
    {t:'玉漏迟·登无尽上人山楼',a:'张炎〔宋代〕',c:'竹多尘自扫。幽通径曲，禅房深木。空翠吹衣，坐对闲云舒啸。寒木犹悬故叶，又过了、一番残照。趣院悄。诗梦正迷，独怜衰草。\n幽趣尽属闲僧，浑未识人间，落花啼鸟。呼酒凭高，莫问四愁三笑。可惜秦山晋水，甚却向、此时登眺。清趣少。那更好游人老。'},
    {t:'玉女摇仙佩·佳人',a:'柳永〔宋代〕',c:'飞琼伴侣，偶别珠宫，未返神仙几缀。取次梳妆，寻常言语，有得几多姝丽。拟把名花比。恐旁人卉我，谈何容易。细思算、奇葩艳卉，惟是深红浅白而已。争如这多情，占得人间，千娇百媚。\n须信画堂绣阁，皓月清风，忍把光阴轻弃。自古及今，佳人才子，少得当年双美。且恁相偎倚。未消得、怜我多才多艺。愿妳妳、兰心蕙性，枕前言下，表余心意。为盟誓。今生断不孤鸳被。'},
    {t:'玉泉',a:'纳兰性德〔清代〕',c:'芙蓉殿俯御河寒，残月西风并马看。\n十里松杉清绝处，不知晓雪在西山。'},
    {t:'玉泉道中作',a:'元稹〔唐代〕',c:'楚俗物候晚，孟冬才有霜。早农寺华实，夕水含风凉。\n遐想云外寺，峰峦渺相望。松门接官路，泉夜连僧房。\n微露上弦月，暗焚初夜香。谷深烟壒净，山虚钟磬长。\n念此清境远，复忧尘事妨。行行即前路，勿滞分寸光。'},
    {t:'玉山',a:'李商隐〔唐代〕',c:'玉山高与阆风齐，玉水清流不贮泥。何处更求回日驭，\n此中兼有上天梯。珠容百斛龙休睡，桐拂千寻凤要栖。\n闻道神仙有才子，赤箫吹罢好相携。'},
    {t:'玉山道中',a:'杨万里〔宋代〕',c:'村北村南水响齐，巷头巷尾树阴低。\n青山自负无尘色，尽日殷勤照碧溪。'},
    {t:'玉山枕·骤雨新霁',a:'柳永〔宋代〕',c:'骤雨新霁。荡原野、清如洗。断霞相彩，残阳倒影，天外云峰，数朵相倚。露荷烟芰满池塘，见次第、炎番红翠。当是时、河朔飞觞，避炎蒸，想风流堪继。\n晚来高树清风起。动帘幕、生秋气。画楼昼寂，兰堂夜静，舞艳歌姝，渐任罗绮。讼闲时泰足风情，便争奈、雅歌都废。省教成、炎阕清歌，尽新声，好尊前重理。'},
    {t:'玉堂春·帝城春暖',a:'晏殊〔宋代〕',c:'帝城春暖。御柳暗遮空苑。海燕林林，拂扬帘栊。女伴相携、共绕林间路，折得樱桃插髻红。\n昨夜临明微雨，新英遍旧丛。宝马香车、欲傍西池看，触处杨花满袖风。'},
    {t:'玉堂春·斗城池馆',a:'晏殊〔宋代〕',c:'斗城池馆。二月风和烟暖。绣户珠帘，日影初长。玉辔金鞍、缭绕沙堤路，几处行人映绿杨。\n小槛朱阑回倚，千花浓露香。脆管清弦、欲奏新翻曲，依约林间坐夕阳。'},
    {t:'玉堂春·後园春早',a:'晏殊〔宋代〕',c:'后园春早。残雪尚濛烟草。数树寒梅，欲绽香英。小妹无端、折尽钗头朵，满把金尊细细倾。\n忆得往年同伴，沈吟无限情。恼乱东风、莫便吹零落，惜取芳菲眼下明。'},
    {t:'玉团儿',a:'周邦彦〔宋代〕',c:'妍姿艳态腰如束。笑无限、桃粗杏俗。玉体横陈，云鬟斜坠，春睡还熟。\n夕阳斗转阑干曲。乍醉起、余霞衫肉。搦粉搓酥，剪云裁雾，比并不足。'},
    {t:'玉团儿·双调',a:'周邦彦〔宋代〕',c:'铅华淡伫新妆束。好风韵、天然异俗。彼此知名，虽然初见，情分先熟。\n炉烟淡淡云屏曲。睡半醒、生香透肉。赖得相逢，若还虚过，生世不足。'},
    {t:'玉仙馆',a:'张籍〔唐代〕',c:'长溪新雨色如泥，野水阴云尽向西。\n楚客天南行渐远，山山树里鹧鸪啼。'},
    {t:'玉簪',a:'黄庭坚〔宋代〕',c:'宴罢瑶池阿母家，嫩琼飞上紫云车。玉簪堕地无人拾，化作东南第一花。'},
    {t:'玉簪',a:'王安石〔宋代〕',c:'瑶池仙子宴流霞，醉里遗簪幻作花。万斛浓香山麝馥，随风吹落到君家。'},
    {t:'玉真公主歌',a:'高适〔唐代〕',c:'常言龙德本天仙，谁谓仙人每学仙。\n更道玄元指李日，多于王母种桃年。\n仙宫仙府有真仙，天宝天仙秘莫传。\n为问轩皇三百岁，何如大道一千年。'},
    {t:'玉真观',a:'张籍〔唐代〕',c:'台殿曾为贵主家，春风吹尽竹窗纱。\n院中仙女修香火，不许闲人入看花。'},
    {t:'玉烛新',a:'秦观〔宋代〕',c:'泰阶开景运。见金锁绿沈，辕门春静。几年淮海，烟波境、贮此风流标韵。连天笳鼓，又催把、经纶管领。文武事，细柳长杨，从头属齐整。\n早闻横槊燕然，画图里，争传麒麟旧影。临岐笑问。谁得似、占了山林钟鼎。古来难并。才信是、人间英俊。试看取、紫绶金章，朱颜绿鬓。'},
    {t:'玉烛新·双调梅花',a:'周邦彦〔宋代〕',c:'溪源新腊后。见数朵江梅，剪裁初就。晕酥砌玉芳英嫩，故把春心轻漏。前村昨夜，想弄月、黄昏时候。孤岸峭，疏影横斜，浓香暗沾襟袖。\n尊前赋与多材，问岭外风光，故人知否。寿阳谩斗。终不似，照水一枝清瘦。风娇雨秀。好乱插、繁花盈首。须信道，羌管无情，看看又奏。'},
    {t:'狱中寄子由二首·其二',a:'苏轼〔宋代〕',c:'柏台霜气夜凄凄，风动琅珰月向低。\n梦绕云山心似鹿，魂飞汤火命如鸡。\n眼中犀角真吾子，身后牛衣愧老妻。\n百岁神游定何处，桐乡知葬浙江西。'},
    {t:'狱中寄子由二首·其一',a:'苏轼〔宋代〕',c:'圣主如天万物春，小臣愚暗自亡身。\n百年未满先偿债，十口无归更累人。\n是处青山可埋骨，他年夜雨独伤神。\n与君世世为兄弟，更结来生未了因。'},
    {t:'欲与元八卜邻先有是赠',a:'白居易〔唐代〕',c:'平生心迹最相亲，欲隐墙东不为身。\n明月好同三径夜，绿杨宜作两家春。\n每因暂出犹思伴，岂得安居不择邻。\n可独终身数相见，子孙长作隔墙人。'},
    {t:'遇冲和先生',a:'高适〔唐代〕',c:'冲和生何代，或谓游东溟。三命术金殿，一言拜银青。\n自云多方术，往往通神灵。万乘亲问道，六仪无敢听。\n昔去限霄汉，今来睹仪形。头戴鹖鸟冠，手摇白鹤翎。\n终日饮醇酒，不醉复不醒。常忆鸡鸣山，每诵西升经。\n拊背念离别，依然出户庭。莫见今如此，曾为一客星。'},
    {t:'遇崔二有别',a:'高适〔唐代〕',c:'大国多任士，明时遗此人。颐颔里丰盈，毛骨未合迍。\n逸足望千里，商歌悲四邻。谁谓多才富，却令家道贫。\n秋风吹别马，携手更伤神。'},
    {t:'遇灵阳子谈道赠以诗',a:'文天祥〔宋代〕',c:'昔我爱泉石，长揖离公卿。\n结屋青山下，咫尺蓬与瀛。\n至人不可见，世尘忽相缨。\n业风吹浩劫，蜗角争浮名。\n偶逢大吕翁，如有宿世盟。\n相从语寥廓，俯仰万念轻。\n天地不知老，日月交其精。\n人一阴阳性，本来自长生。\n指点虚无间，引我归员明。\n一针透顶门，道骨由天成。\n我如一逆旅，久欲蹑屩行。\n闻师此妙廖，蘧庐复何情。'},
    {t:'遇薛明府谒聪上人',a:'王昌龄〔唐代〕',c:'欣逢柏梁故，共谒聪公禅。石室无人到，绳床见虎眠。\n阴崖常抱雪，枯涧为生泉。出处虽云异，同欢在法筵。'},
    {t:'御街行',a:'晏几道〔宋代〕',c:'年光正似花梢露。弹指春还暮。树眉仙子望归来，倚遍玉城珠树。岂知别后，好风良月，往事无台处。\n狂情错向红尘住。忘了瑶台路。碧桃花蕊已应开，欲伴彩云飞去。回思十载，朱颜青鬓，枉被浮名误。'},
    {t:'御街行·街南绿树春饶絮',a:'晏几道〔宋代〕',c:'街昏绿户春饶絮，雪满游春路。户头花艳杂娇云，户底人家朱户。北楼闲上，疏帘高卷，直见街昏户。\n阑干倚尽犹慵去，几度黄昏雨。晚春盘马踏青苔，曾傍绿荫深驻。落花犹在，香屏空掩，人面知何处？'},
    {t:'御街行·前时小饮春庭院',a:'柳永〔宋代〕',c:'前时小饮春庭院。悔放笙歌散。限来中夜酒醺醺，惹起旧愁无限。虽看坠楼换马，争奈不是鸳惊伴。\n朦胧暗想如花面。欲梦还惊断。和衣拥被不成眠，一枕万回千转。惟有画梁，新来双燕，彻曙闻长叹。'},
    {t:'御街行·秋日怀旧',a:'范仲淹〔宋代〕',c:'纷纷坠叶飘香砌，夜寂静，寒声垂。真珠帘卷玉楼空，天淡银河垂地。年年今夜，月华如练，长是断千里。\n愁肠已断无由醉，酒未到，先成泪。残灯明灭枕头欹，谙尽孤眠滋味。都来此事，眉间心上，无计相回避。'},
    {t:'御街行·圣寿',a:'柳永〔宋代〕',c:'燔柴烟断星河曙。宝辇回天步。端门羽卫簇雕阑，六乐舜韶先举。鹤书飞下，鸡竿高耸，恩霈均寰寓。\n赤霜袍烂飘香雾。喜色成春煦。九仪三事仰天颜，八彩旋生眉宇。椿龄无尽，萝图有庆，常作乾坤主。'},
    {t:'御街行·霜风渐紧寒侵被',a:'佚名〔宋代〕',c:'霜风渐紧寒侵被。听孤雁、声嘹如。一声声送一声悲，云淡碧天如水。披衣告语：雁儿略住，听我个儿事。\n塔儿南畔城儿里，第三个、桥儿外，濒河西岸小红楼，门外梧桐雕砌。请教且与，低声飞过，那里有、人人无寐。'},
    {t:'御街行·银烛生花如红豆',a:'秦观〔宋代〕',c:'银烛生花如红豆。占好事、而今一。人醉曲屏深，借宝瑟、轻招手。一阵白苹风，故灭烛、教相就。\n花晓雨、冰肌香透。恨啼乌、辘轳声晓。岸柳微凉吹残酒。断肠时、至今依旧。镜中消瘦。那人知后。怕夯你来僝僽。'},
    {t:'寓居沣上精舍寄于张二舍人',a:'韦应物〔唐代〕',c:'万木丛云出香阁，西连碧涧竹林园。\n高斋犹宿远山曙，微霰下庭寒雀喧。\n道心淡泊对流水，生事萧疏空掩门。\n时忆故交那得见，晓排阊阖奉明恩。'},
    {t:'寓居永定精舍·苏州',a:'韦应物〔唐代〕',c:'政拙忻罢守，闲居初理生。家贫何由往，梦想在京城。\n野寺霜露月，农兴羁旅情。聊租二顷田，方课子弟耕。\n眼暗文字废，身闲道心精。即与人群远，岂谓是非婴。'},
    {t:'寓题',a:'杜牧〔唐代〕',c:'把酒直须判酩酊，逢花莫惜暂淹留。\n假如三万六千日，半是悲哀半是愁。'},
    {t:'寓言',a:'孟郊〔唐代〕',c:'谁言碧山曲，不废青松直。\n谁言浊水泥，不污明月色。\n我有松月心，俗骋风霜力。\n贞明既如此，摧折安可得。'},
    {t:'寓言',a:'杜牧〔唐代〕',c:'暖风迟日柳初含，顾影看身又自惭。\n何事明朝独惆怅，杏花时节在江南。'},
    {t:'寓言',a:'皎然〔唐代〕',c:'人生百年我过半，天生才定不可换。\n东海钓鳌鳌不食，南山坐石石欲烂。'},
    {t:'寓驿舍',a:'陆游〔宋代〕',c:'闲坊古驿掩朱扉，又憩空堂绽客衣。\n九万里中鲲自化，一千年外鹤仍归。\n遶庭数竹饶新笋，解带量松长旧围。\n惟有壁间诗句在，暗尘残墨两依依。'},
    {t:'豫章行',a:'李白〔唐代〕',c:'胡风吹代马，北拥鲁阳关。\n吴兵照海雪，西讨何时还。\n半渡上辽津，黄云惨无颜。\n老母与子别，呼天野草间。\n白马绕旌旗，悲鸣相追攀。\n白杨秋月苦，早落豫章山。\n本为休明人，斩虏素不闲。\n岂惜战斗死，为君扫凶顽。\n精感石没羽，岂云惮险艰。\n楼船若鲸飞，波荡落星湾。\n此曲不可奏，三军鬓成斑。'},
    {t:'鸳鸯',a:'杜牧〔唐代〕',c:'两两戏沙汀，长疑画不成。锦机争织样，歌曲爱呼名。\n好育顾栖息，堪怜泛浅清。凫鸥皆尔类，惟羡独含情。'},
    {t:'鸳鸯',a:'李商隐〔唐代〕',c:'雌去雄飞万里天，云罗满眼泪潸然。\n不须长结风波愿，锁向金笼始两全。'},
    {t:'鸳鸯篇',a:'陈子昂〔唐代〕',c:'飞飞鸳鸯鸟，举翼相蔽亏。\n俱来绿潭里，共向白云涯。\n音容相眷恋，羽翮两逶迤。\n蘋萍戏春渚，霜霰绕寒池。\n浦沙连岸净，汀树拂潭垂。\n年年此游玩，岁岁来追随。\n凤凰起丹穴，独向梧桐枝。\n鸿雁来紫塞，空忆稻粱肥。\n乌啼倦依托，鹤鸣伤别离。\n岂若此双禽，飞翻不异林。\n刷尾青江浦，交颈紫山岑。\n文章负奇色，和鸣多好音。\n闻有鸳鸯绮，复有鸳鸯衾。\n持为美人赠，勖此故交心。'},
    {t:'元处士池上',a:'温庭筠〔唐代〕',c:'蓼穗菱丛思蟪蛄，水萤江鸟满烟蒲。\n愁红一片风前落，池上秋波似五湖。'},
    {t:'元丹丘歌',a:'李白〔唐代〕',c:'元丹丘，爱神仙，朝饮颍川之清流，\n暮还嵩岑之紫烟，三十六峰长周旋。\n长周旋，蹑星虹，身骑飞龙耳生风，\n横河跨海与天通，我知尔游心无穷。'},
    {t:'元丰行示德逢',a:'王安石〔宋代〕',c:'四山翛翛映赤日，田背坼如龟车出。\n湖阴先生坐草室，看踏沟车望秋实。\n雷蟠电掣云滔滔，夜尻载雨输亭皋。\n旱禾秀发埋牛尻，豆死更苏肥荚毛。\n倒持龙骨挂屋敖，买酒浇客追前劳。\n三年五谷贱如水，今见西成复如此。\n元丰圣人与天通，千秋万岁与此同。\n先生在野故不穷，击壤至老歌元丰。'},
    {t:'元日',a:'温庭筠〔唐代〕',c:'神耀破氛昏，新阳入晏温。\n绪风调玉吹，端日应铜浑。\n威凤跄瑶簴，升龙护璧门。\n雨旸春令煦，裘冕晬容尊。'},
    {t:'元日',a:'王安石〔宋代〕',c:'爆竹声中一岁除，春风送暖入屠苏。\n千门万户曈曈日，总把新桃换旧符。'},
    {t:'元日词其二·东宫阁',a:'晏殊〔宋代〕',c:'条风发动协初辰，玄圃瑶山景象新。\n千载百灵资介福，沧溟重润月重轮。'},
    {t:'元日词其三·内廷',a:'晏殊〔宋代〕',c:'池冰初解雪初消，十二重城晓日高。\n飒飒和风绕珠树，千年春色在蟠桃。'},
    {t:'元日词其一·御阁',a:'晏殊〔宋代〕',c:'莺谷春风柳上归，禁闱芳树渐依依。\n尧年亿万如天远，万国欢心拱太微。'},
    {t:'元日感怀',a:'刘禹锡〔唐代〕',c:'振蛰春潜至，湘南人未归。\n身加一日长，心觉去年非。\n燎火委虚烬，儿童炫彩衣。\n异乡无旧识，车马到门稀。'},
    {t:'元日寄诸弟兼呈崔都水',a:'韦应物〔唐代〕',c:'一从守兹郡，两鬓生素发。新正加我年，故岁去超忽。\n淮滨益时候，了似仲秋月。川谷风景温，城池草木发。\n高斋属多暇，惆怅临芳物。日月昧还期，念君何时歇。'},
    {t:'元日乐天见过因举酒为贺',a:'刘禹锡〔唐代〕',c:'渐入有年数，喜逢新岁来。震方天籁动，寅位帝车回。\n门巷扫残雪，林园惊早梅。与君同甲子，寿酒让先杯。'},
    {t:'元日立春三绝',a:'秦观〔宋代〕',c:'此度春非草草回，美人休著剪刀催。\n直须残腊十分尽，始共新年一并来。'},
    {t:'元夕',a:'文天祥〔宋代〕',c:'灯火喧三市，衣冠宴九宸。\n金吾不禁夜，公子早行春。\n梦断青山远，愁侵白发新。\n燕山今夕月，清影伴孤臣。'},
    {t:'元相公挽歌词三首',a:'白居易〔唐代〕',c:'铭旌官重威仪盛，骑吹声繁卤簿长。\n后魏帝孙唐宰相，六年七月葬咸阳。\n墓门已闭笳箫去，唯有夫人哭不休。\n苍苍露草咸阳垄，此是千秋第一秋。\n送葬万人皆惨澹，反虞驷马亦悲鸣。\n琴书剑珮谁收拾，三岁遗孤新学行。'},
    {t:'园亭览物',a:'韦应物〔唐代〕',c:'积雨时物变，夏绿满园新。残花已落实，高笋半成筠。\n守此幽栖地，自是忘机人。'},
    {t:'原头送范侍御·得山字',a:'岑参〔唐代〕',c:'百尺原头酒色殷，路傍骢马汗斑斑。\n别君只有相思梦，遮莫千山与万山。'},
    {t:'原隰荑绿柳',a:'温庭筠〔唐代〕',c:'迥野韶光早，晴川柳满堤。\n拂尘短嫩绿，披雪见柔荑。\n碧玉牙犹短，黄金缕未齐。\n腰肢弄寒吹，眉意入春闺。\n预恐狂夫折，迎牵逸客迷。\n新莺将出谷，应借一枝栖。'},
    {t:'圆通院白衣阁',a:'秦观〔宋代〕',c:'无边刹境一毫端，同住澄清觉海间。\n还似此花并此叶，坏空成往未曾闲。'},
    {t:'猿',a:'杜牧〔唐代〕',c:'月白烟青水暗流，孤猿衔恨叫中秋。\n三声欲断疑肠断，饶是少年今白头。'},
    {t:'远别离',a:'李白〔唐代〕',c:'远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。\n海水直下万里深，谁人不言此离苦？\n日惨惨兮云冥冥，猩猩啼烟兮鬼啸雨。\n我纵言之将何补？\n皇穹窃恐不照余之忠诚，雷凭凭兮欲吼怒。\n尧舜当之亦禅禹。\n君失臣兮龙为鱼，权归臣兮鼠变虎。\n或云：尧幽囚，舜野死。\n九疑联绵皆相似，重瞳孤坟竟何是？\n帝子泣兮绿云间，随风波兮去无还。\n恸哭兮远望，见苍梧之深山。\n苍梧山崩湘水绝，竹上之泪乃可灭。'},
    {t:'远愁曲',a:'孟郊〔唐代〕',c:'飘飖何所从，遗冢行未逢。东西尽见人，哭向青青松。\n此地有时尽，此哀无处容。声翻太白云，泪洗蓝田峰。\n水涉七八曲，山登千万重。愿邀玄夜月，出视白日踪。'},
    {t:'远师',a:'白居易〔唐代〕',c:'东宫白庶子，南寺远禅师。\n何处遥相见，心无一事时。'},
    {t:'远望',a:'元稹〔唐代〕',c:'满眼伤心冬景和，一山红树寺边多。\n仲宣无限思乡泪，漳水东流碧玉波。'},
    {t:'远游',a:'周邦彦〔宋代〕',c:'淮西渡两桨，江左随一鸥。\n苦嗟人涛窄，所至胶吾舟。\n借问舟中人，流转何时休。\n帆高风色利，欲神不自由。\n传闻弱水外，鼎立三神丘。\n鼓柜未可到，载行有潜虯。\n扶桑睹浴日，阳精热东流。\n万族呈秘怪，九土皆飘浮。\n送者安在哉，吾往不可求。\n岂比鸱夷子，并湖名远游。'},
    {t:'远游',a:'孟郊〔唐代〕',c:'慈乌不远飞，孝子念先归。而我独何事，四时心有违。\n江海恋空积，波涛信来稀。长为路傍食，著尽家中衣。\n别剑不割物，离人难作威。远行少僮仆，驱使无是非。\n为性玩好尽，积愁心绪微。始知时节驶，夏日非长辉。'},
    {t:'怨别',a:'孟郊〔唐代〕',c:'一别一回老，志士白发早。在富灵为容，居贫难自好。\n沉忧损性灵，服药亦枯槁。秋风游子衣，落日行远道。\n君问去何之，贱身难自保。'},
    {t:'怨歌行',a:'李白〔唐代〕',c:'十五入汉宫，花颜笑春红。\n君王选玉色，侍寝金屏中。\n荐枕娇夕月，卷衣恋春风。\n宁知赵飞燕，夺宠恨无穷。\n沉忧能伤人，绿鬓成霜蓬。\n一朝不得意，世事徒为空。\n鹔鹴换美酒，舞衣罢雕龙。\n寒苦不忍言，为君奏丝桐。\n肠断弦亦绝，悲心夜忡忡。'},
    {t:'怨情',a:'李白〔唐代〕',c:'美人卷珠帘，深坐蹙蛾眉。\n但见泪痕湿，不知心恨谁。'},
    {t:'怨诗',a:'孟郊〔唐代〕',c:'试妾与君泪，两处滴池水。\n看取芙蓉花，今年为谁死。'},
    {t:'怨诗楚调示庞主簿邓治中',a:'陶渊明〔魏晋〕',c:'天道幽且远，鬼神茫昧然。\n结发念善事，僶俛六九年。\n弱冠逢世阻，始室丧其偏。\n炎火屡焚如，螟蜮恣中田。\n风雨纵横至，收敛不盈廛。\n夏日长抱饥，寒夜无被眠。\n造夕思鸡鸣，及晨愿乌迁。\n在己何怨天，离忧凄目前。\n吁嗟身后名，于我若浮烟。\n慷慨独悲歌，锺期信为贤。'},
    {t:'月',a:'杜甫〔唐代〕',c:'四更山吐月，残夜水明楼。\n尘匣元开镜，风帘自上钩。\n兔应疑鹤发，蟾亦恋貂裘。\n斟酌姮娥寡，天寒耐九秋。'},
    {t:'月',a:'李商隐〔唐代〕',c:'池上与桥边，难忘复可怜。\n帘开最明夜，簟卷已凉天。\n流处水花急，吐时云叶鲜。\n姮娥无粉黛，只是逞婵娟。'},
    {t:'月',a:'杜牧〔唐代〕',c:'三十六宫秋夜深，昭阳歌断信沉沉。\n唯应独伴陈皇后，照见长门望幸心。'},
    {t:'月儿弯弯照九州',a:'佚名〔宋代〕',c:'月儿弯弯照九州，几家欢乐几家愁。\n几家夫妇同罗帐，几个飘零在外头？'},
    {t:'月宫春怨恨',a:'周邦彦〔宋代〕',c:'蜀丝趁日染乾红。微暖面脂融。博山细篆霭房栊。静看打窗虫。\n愁多胆怯疑虚幕，声不断、暮景疏钟。团团四壁小屏风。啼尽梦魂中。'},
    {t:'月临花·临檎花',a:'元稹〔唐代〕',c:'临风飏飏花，透影胧胧月。巫峡隔波云，姑峰漏霞雪。\n镜匀娇面粉，灯泛高笼缬。夜久清露多，啼珠坠还结。'},
    {t:'月漉漉篇',a:'李贺〔唐代〕',c:'月漉漉，波烟玉。\n莎青桂花繁，芙蓉别江木。\n粉态袷罗寒，雁羽铺烟湿。\n谁能看石帆，乘船镜中入。\n秋白鲜红死，水香莲子齐。\n挽菱隔歌袖，绿刺罥银泥。'},
    {t:'月三首',a:'杜甫〔唐代〕',c:'断续巫山雨，天河此夜新。\n若无青嶂月，愁杀白头人。\n魍魉移深树，虾蟆动半轮。\n故园当北斗，直指照西秦。\n并照巫山出，新窥楚水清。\n羁栖愁里见，二十四回明。\n必验升沉体，如知进退情。\n不违银汉落，亦伴玉绳横。\n万里瞿塘峡，春来六上弦。\n时时开暗室，故故满青天。\n爽合风襟静，高当泪脸悬。\n南飞有乌鹊，夜久落江边。'},
    {t:'月上海棠·斜阳废苑朱门闭',a:'陆游〔宋代〕',c:'成都城南有蜀王旧苑，尤多梅，门二百余年古木。\n斜阳废苑朱门闭，吊兴亡、遗恨泪痕里。淡淡似梅，也依然、点酥剪水。凝愁处，似忆宣华旧事。\n行人别有凄凉意，折幽香、谁与寄千里。伫立江皋，杳难逢、陇头归骑。音尘远，楚天危楼独倚。'},
    {t:'月夕',a:'李商隐〔唐代〕',c:'草下阴虫叶上霜，朱栏迢递压湖光。\n兔寒蟾冷桂花白，此夜姮娥应断肠。'},
    {t:'月下笛·寄仇山村溧阳',a:'张炎〔宋代〕',c:'千里行秋，支筇背锦，顿怀清友。殊乡聚首。爱吟犹自诗瘦。山人不解思猿鹤，笑问我、韦娘在否。记长堤画舫，花柔春闹，几番携手。\n别后都依旧。但靖节门前，近来无柳。盟鸥尚有。可怜西塞渔叟。断肠不恨江南老，恨落叶、飘零最久。倦游处，减羁愁，犹未消磨是酒。'},
    {t:'月下笛·万里孤云',a:'张炎〔宋代〕',c:'孤游万竹山中，闲门落叶，愁思黯然，因动《黍离》之感。时寓甬东积翠山舍。\n万里孤云，清游渐远，故人何处？寒窗梦里，犹记经行旧时路。连昌约略无多柳，第一是难听夜雨。漫惊回凄悄，相看烛影，拥衾谁语？\n张绪归何暮？半零落依依，断桥鸥鹭。天涯倦旅，此时心事良苦。只愁重洒西州泪，问杜曲人家在否？恐翠袖正天寒，犹倚梅花那树。'},
    {t:'月下笛·越调',a:'周邦彦〔宋代〕',c:'小雨收尘，凉蟾莹彻，水光浮璧。谁知怨抑。静倚官桥吹笛。映宫墙、风叶乱飞，品高调侧人未识。想开元旧谱，柯亭遗韵，尽传胸臆。\n阑干四绕，听折柳徘徊，数声终拍。寒灯陋馆，最感平阳孤客。夜沈沈、雁啼甚哀，片云尽卷清漏滴。黯凝魂，但觉龙吟万壑天籁息。'},
    {t:'月下独酌·其二',a:'李白〔唐代〕',c:'天若不爱酒，酒星不在天。\n地若不爱酒，地应无酒泉。\n天地既爱酒，爱酒不愧天。\n已闻清比圣，复道浊如贤。\n贤圣既已饮，何必求神仙。\n三杯通大道，一斗合自然。\n但得酒中趣，勿为醒者传。'},
    {t:'月下独酌·其三',a:'李白〔唐代〕',c:'三月咸阳城，千花昼如锦。\n谁能春独愁，对此径须饮。\n穷通与修短，造化夙所禀。\n一樽齐死生，万事固难审。\n醉后失天地，兀然就孤枕。\n不知有吾身，此乐最为甚。'},
    {t:'月下独酌·其一',a:'李白〔唐代〕',c:'花间一壶酒，独酌无相亲。\n举杯邀明月，对影成三人。\n月既不解饮，影徒随我身。\n暂伴月将影，行乐须及春。\n我歌月徘徊，我舞影零乱。\n醒时同交欢，醉后各分散。\n永结无情游，相期邈云汉。'},
    {t:'月下醉题',a:'陆游〔宋代〕',c:'黄鹄飞鸣未免饥，此身自笑欲何之。\n闭门种菜英雄老，弹铗思鱼富贵迟。\n生拟入山随李广，死当穿冢近要离。\n一樽强醉南楼月，感慨长吟恐过悲。'},
    {t:'月夜',a:'杜甫〔唐代〕',c:'今夜鄜州月，闺中只独看。\n遥怜小儿女，未解忆长安。\n香雾云鬟湿，清辉玉臂寒。\n何时倚虚幌，双照泪痕干。'},
    {t:'月夜',a:'韦应物〔唐代〕',c:'皓月流春城，华露积芳草。\n坐念绮窗空，翻伤清景好。\n清景终若斯，伤多人自老。'},
    {t:'月夜江行寄崔员外宗之',a:'李白〔唐代〕',c:'飘飘江风起，萧飒海树秋。\n登舻美清夜，挂席移轻舟。\n月随碧山转，水合青天流。\n杳如星河上，但觉云林幽。\n归路方浩浩，徂川去悠悠。\n徒悲蕙草歇，复听菱歌愁。\n岸曲迷后浦，沙明瞰前洲。\n怀君不可见，望远增离忧。'},
    {t:'月夜金陵怀古',a:'李白〔唐代〕',c:'苍苍金陵月，空悬帝王州。\n天文列宿在，霸业大江流。\n绿水绝驰道，青松摧古丘。\n台倾鳷鹊观，宫没凤凰楼。\n别殿悲清暑，芳园罢乐游。\n一闻歌玉树，萧瑟后庭秋。'},
    {t:'月夜听卢子顺弹琴',a:'李白〔唐代〕',c:'闲夜坐明月，幽人弹素琴。\n忽闻悲风调，宛若寒松吟。\n白雪乱纤手，绿水清虚心。\n钟期久已没，世上无知音。'},
    {t:'月夜忆乐天兼寄微之',a:'刘禹锡〔唐代〕',c:'今宵帝城月，一望雪相似。\n遥想洛阳城，清光正如此。\n知君当此夕，亦望镜湖水。\n展转相忆心，月明千万里。'},
    {t:'月夜忆舍弟',a:'杜甫〔唐代〕',c:'戍鼓断人行，边秋一雁声。\n露从今夜白，月是故乡明。\n有弟皆分散，无家问死生。\n寄书长不达，况乃未休兵。'},
    {t:'月夜有怀',a:'陈子昂〔唐代〕',c:'美人挟赵瑟，微月在西轩。\n寂寞夜何久，殷勤玉指繁。\n清光委衾枕，遥思属湘沅。\n空帘隔星汉，犹梦感精魂。'},
    {t:'月夜与客饮酒杏花下',a:'苏轼〔宋代〕',c:'杏花飞帘散余春，明月入户寻水人。\n褰衣步月踏花影，炯如流水涵青苹。\n花间置酒清香发，争饮长条落香雪。\n山城薄酒不堪饮，劝君且吸杯中月。\n洞箫声断月明中，惟忧月落酒杯空。\n明朝卷地春风恶，但见绿叶栖残红。'},
    {t:'月夜重寄宋华阳姊妹',a:'李商隐〔唐代〕',c:'偷桃窃药事难兼，十二城中锁彩蟾。\n应共三英同夜赏，玉楼仍是水精帘。'},
    {t:'月圆',a:'杜甫〔唐代〕',c:'孤月当楼满，寒江动夜扉。\n委波金不定，照席绮逾依。\n未缺空山静，高悬列宿稀。\n故园松桂发，万里共清辉。'},
    {t:'月中宿云居寺上方',a:'温庭筠〔唐代〕',c:'虚閤披衣坐，寒阶踏叶行。\n众星中夜少，圆月上方明。\n霭尽无林色，暄馀有涧声。\n只应愁恨事，还逐晓光生。'},
    {t:'月中行·怨恨',a:'周邦彦〔宋代〕',c:'蜀丝趁日染干红。微暖面脂融。博山细篆霭房栊。静看打窗虫。\n愁多胆怯疑虚幕，声不断、暮景疏钟。团团四壁小屏风。啼尽梦魂中。'},
    {t:'月子弯弯照九州',a:'杨万里〔宋代〕',c:'月子弯弯照九州，几家欢乐几家愁。\n愁杀人来关月事，得休休处且休休。'},
    {t:'岳后步月',a:'朱熹〔宋代〕',c:'清光冰魄浩无边，桂影扶疏吐玉娟。\n人在峰头遥指望，举杯对影夜无眠。'},
    {t:'岳阳别李十七越宾',a:'王昌龄〔唐代〕',c:'相逢楚水寒，舟在洞庭驿。具陈江波事，不异沦弃迹。\n杉上秋雨声，悲切蒹葭夕。弹琴收馀响，来送千里客。\n平明孤帆心，岁晚济代策。时在身未充，潇湘不盈画。\n湖小洲渚联，澹淡烟景碧。鱼鳖自有性，龟龙无能易。\n谴黜同所安，风土任所适。闭门观玄化，携手遗损益。'},
    {t:'岳阳楼',a:'李商隐〔唐代〕',c:'汉水方城带百蛮，四邻谁道乱周班。\n如何一梦高唐雨，自此无心入武关。'},
    {t:'岳阳楼',a:'元稹〔唐代〕',c:'岳阳楼上日衔窗，影到深潭赤玉幢。\n怅望残春万般意，满棂湖水入西江。'},
    {t:'岳阳楼记',a:'范仲淹〔宋代〕',c:'庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，百废具兴，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，属予作文以记之。\n至若春和景明，波澜不惊，上下天光，一碧万顷，沙鸥翔集，锦鳞游泳，岸芷汀兰，郁郁青青。而或长烟一空，皓月千里，浮光跃金，静影沉璧，渔歌互答，此乐何极！登斯楼也，则有心旷神怡，宠辱偕忘，把酒临风，其喜洋洋者矣。\n嗟夫！予尝求古仁人之心，或异二者之为，何哉？不以物喜，不以己悲，居庙堂之高则忧其民，处江湖之远则忧其君。是进亦忧，退亦忧。然则何时而乐耶？其必曰“先天下之忧而忧，后天下之乐而乐”乎！噫！微斯人，吾谁与归？时六年九月十五日。'},
    {t:'岳州晚景',a:'张籍〔唐代〕',c:'晚景寒鸦集，秋声旅雁归。\n水光浮日去，霞彩映江飞。\n洲白芦花吐，园红柿叶稀。\n长沙卑湿地，九月未成衣。'},
    {t:'越女词五首',a:'李白〔唐代〕',c:'长干吴儿女，眉目艳新月。\n屐上足如霜，不著鸦头袜。\n吴儿多白皙，好为荡舟剧。\n卖眼掷春心，折花调行客。\n耶溪采莲女，见客棹歌回。\n笑入荷花去，佯羞不出来。\n东阳素足女，会稽素舸郎。\n相看月未堕，白地断肝肠。\n镜湖水如月，耶溪女似雪。\n新妆荡新波，光景两奇绝。'},
    {t:'越人歌',a:'佚名〔先秦〕',c:'今夕何夕兮，搴舟中流。\n今日何日兮，得与王子同舟。\n蒙羞被好兮，不訾诟耻。\n心几烦而不绝兮，得知王子。\n山有木兮木有枝，心悦君兮君不知。'},
    {t:'越上闻子规',a:'范仲淹〔宋代〕',c:'夜入翠烟啼，昼寻芳树飞。\n春山无限好，犹道不如归。'},
    {t:'越台曲',a:'周邦彦〔宋代〕',c:'玉颜如花越王女，自小娇痴不歌舞。\n嫁作江南国主妃，日日思归泪如雨。\n江南江北梅子黄，潮头夜涨秦淮江。\n江边雨多地卑湿，旋筑高台匀晓妆。\n千艘命载越中土，喜见越人仍越语。\n人生脚踏乡土难，无复归心越中去。\n高台何易倾，曲池亦复平。\n越姬一去向千载，不见此台空有名。'},
    {t:'越谣歌',a:'佚名〔两汉〕',c:'君乘车，我戴笠，他日相逢下车揖。\n君担簦，我跨马，他日相逢为君下。'},
    {t:'越中逢天台太乙子',a:'孟浩然〔唐代〕',c:'仙穴逢羽人，停舻向前拜。问余涉风水，何处远行迈。\n登陆寻天台，顺流下吴会。兹山夙所尚，安得问灵怪。\n上逼青天高，俯临沧海大。鸡鸣见日出，常觌仙人旆。\n往来赤城中，逍遥白云外。莓苔异人间，瀑布当空界。\n福庭长自然，华顶旧称最。永此从之游，何当济所届。'},
    {t:'越中览古',a:'李白〔唐代〕',c:'越王勾践破吴归，义士还家尽锦衣。\n宫女如花满春殿，只今惟有鹧鸪飞。'},
    {t:'越中山水',a:'孟郊〔唐代〕',c:'日觉耳目胜，我来山水州。蓬瀛若仿佛，田野如泛浮。\n碧嶂几千绕，清泉万馀流。莫穷合沓步，孰尽派别游。\n越水净难污，越天阴易收。气鲜无隐物，目视远更周。\n举俗媚葱蒨，连冬撷芳柔。菱湖有馀翠，茗圃无荒畴。\n赏异忽已远，探奇诚淹留。永言终南色，去矣销人忧。'},
    {t:'云',a:'杜牧〔唐代〕',c:'东西那有碍，出处岂虚心。\n晓入洞庭阔，暮归巫峡深。\n渡江随鸟影，拥树隔猿吟。\n莫隐高唐去，枯苗待作霖。'},
    {t:'云谷二十六咏其二十二茶坂',a:'朱熹〔宋代〕',c:'携籯北岭西，采撷供茗饮。一啜夜窗寒，跏趺谢衾枕。'},
    {t:'云谷杂诗十二首其四谢客',a:'朱熹〔宋代〕',c:'野人载酒来，农谈日西夕。此意良已勤，感叹情何极。\n归去莫频来，林深山路黑。'},
    {t:'云梦泽',a:'杜牧〔唐代〕',c:'日旗龙旆想飘扬，一索功高缚楚王。\n直是超然五湖客，未如终始郭汾阳。'},
    {t:'云山清晓',a:'王昌龄〔唐代〕',c:'苍深翠浅瀑峥潺，岂谓讥秦始爱山。一炬咸阳机冢赤，紫霄巍立晓云间。'},
    {t:'云童行',a:'张籍〔唐代〕',c:'云童童，白龙之尾垂江中。今年天旱不作雨，\n水足墙上有禾黍。'},
    {t:'云阳馆怀谷口',a:'韦应物〔唐代〕',c:'清泚阶下流，云自谷口源。念昔累衣士，结庐在石门。\n道高杳无累，景静得忘言。山夕绿阴满，世朝清赏存。\n吏役岂遑暇，幽怀复朝昏。云泉非所濯，萝月不可援。\n长往遂真性，暂游恨卑喧。出身既事世，高躅难等论。'},
    {t:'云之祁祁答董传',a:'王安石〔宋代〕',c:'云之祁祁，有雨于渊。\n苗之翘翘，有槁于田。\n云之祁祁，有雨于野。\n有槁于田，岂不自我。\n荟兮其隮，其在西郊。\n匪我为之，我歌且谣。\n蔚兮其复，南山之侧。\n我歌且谣，维以育德。'},
    {t:'陨星石',a:'秦观〔宋代〕',c:'萧然古丘上，有石传陨星。\n胡为霄汉间，坠地成此精。\n虽有坚白姿，块然谁汝灵。\n犬眼牛砺角，终日蒙膻腥。\n畴昔同列者，到今司赏刑。\n森然事芒角，次第罗空青。\n俛仰一气中，万化无常经。\n安知风云会，不复归青冥。'},
    {t:'杂感',a:'陆游〔宋代〕',c:'天际晴云舒复卷，庭中风絮去还来。\n人生自在常如此，何事能妨笑口开？'},
    {t:'杂歌谣辞·步虚词',a:'皎然〔唐代〕',c:'予因览真诀，遂感西域君。玉笙魄青冥，人间未曾闻。\n日华炼魂魄，皎皎无垢氛。谓我有仙骨，且令饵氤氲。\n俯仰愧灵颜，愿随鸾鹤群。俄然动风驭，缥眇归青云。'},
    {t:'杂歌谣辞·步虚词',a:'刘禹锡〔唐代〕',c:'阿母种桃云海际，花落子成二千岁。\n海风吹折最繁枝，跪捧琼盘献天帝。\n华表千年鹤一归，凝丹为顶雪为衣。\n星星仙语人听尽，却向五云翻翅飞。'},
    {t:'杂歌谣辞·邯郸郭公辞',a:'温庭筠〔唐代〕',c:'金笳悲故曲，玉座积深尘。言是邯郸伎，不易邺城人。\n青苔竟埋骨，红粉自伤神。唯有漳河柳，还向旧营春。'},
    {t:'杂歌谣辞·李夫人歌',a:'李商隐〔唐代〕',c:'一带不结心，两股方安髻。惭愧枝茅人，月没教星替。\n剩结茱萸枝，多擘秋莲的。独自有波光，彩香盛不得。\n蛮丝系条脱，妍眼和香屑。寿宫不惜铸南人，\n柔肠早被秋波割。清澄有馀幽素香，鳏鱼渴凤真珠房。\n不知瘦骨类冰井，更许夜帘通晓霜。土花漠碧云茫茫，\n黄河欲尽天苍黄。'},
    {t:'杂歌谣辞·李夫人歌',a:'李贺〔唐代〕',c:'紫皇宫殿重重开，夫人飞入琼瑶台。\n绿香绣帐何时歇，青云无光宫水咽。\n翩联桂花坠秋月，孤鸾惊啼商丝发。\n红璧阑珊悬佩当，歌台小妓遥相望。\n玉蟾滴水鸡人唱，露华兰叶参差光。'},
    {t:'杂歌谣辞·邺城童子谣',a:'李贺〔唐代〕',c:'邺城中，暮尘起。将黑丸，斫文吏。棘为鞭，虎为马。\n团团走，邺城下。切玉剑，射日弓。献何人，奉相公。\n扶毂来，关右儿。香扫途，相公归。'},
    {t:'杂记草木九首其八独觉',a:'朱熹〔宋代〕',c:'端居春向残，夏气已清穆。睡起悄无人，风惊满窗绿。'},
    {t:'杂记草木九首其六萱草一',a:'朱熹〔宋代〕',c:'春条拥深翠，夏花明夕阴。北堂罕悴物，独尔澹冲襟。'},
    {t:'杂记草木九首其四竹',a:'朱熹〔宋代〕',c:'种竹官墙阴，经年但憔悴。故园新绿多，宿干转苍翠。'},
    {t:'杂记草木九首其五榴花',a:'朱熹〔宋代〕',c:'窈窕安榴花，乃是西邻树。坠萼可怜人，风吹落幽户。'},
    {t:'杂曲歌辞·变行路难',a:'王昌龄〔唐代〕',c:'向晚横吹悲，风动马嘶合。\n前驱引旗节，千重阵云匝。\n单于下阴山，砂砾空飒飒。\n封侯取一战，岂复念闺阁。'},
    {t:'杂曲歌辞·车遥遥',a:'孟郊〔唐代〕',c:'路喜到江尽，江上又通舟。舟车两无阻，何处不得游。\n丈夫四方志，女子安可留。郎自别日言，无令生远愁。\n旅雁忽叫月，断猿寒啼秋。此夕梦君梦，君在百城楼。\n寄泪无因波，寄恨无因輈。愿为驭者手，与郎回马头。'},
    {t:'杂曲歌辞·出门行二首',a:'孟郊〔唐代〕',c:'长河悠悠去无极，百龄同此可叹息。\n秋风白露沾人衣，壮心凋落夺颜色。\n少年出门将诉谁，川无梁兮路无岐。\n一闻陌上苦寒奏，使我伫立惊且悲。\n君今得意厌粱肉，岂复念我贫贱时。\n海风萧萧天雨霜，穷愁独坐夜何长。\n驱车旧忆太行险，始知游子悲故乡。\n美人相思隔天阙，长望云端不可越。\n手持琅玕欲有赠，爱而不见心断绝。\n南山峨峨白石烂，碧海之波浩漫漫。\n参辰出没不相待，我欲横天无羽翰。'},
    {t:'杂曲歌辞·春江曲',a:'张籍〔唐代〕',c:'春江无云潮水平，蒲心出水凫雏鸣。长干夫婿爱远行，\n自染春衣缝已成。妾身生长金陵侧，去年随夫住江北。\n春来未到父母家，舟小风多渡不得。欲辞舅姑先问人，\n私向江头祭水神。'},
    {t:'杂曲歌辞·春日行',a:'张籍〔唐代〕',c:'春日融融池上暖，竹牙出土兰心短。\n草堂晨起酒半醒，家童报我园花满。\n头上皮冠未曾整，直入花间不寻径。\n树树殷勤尽绕行，举枝未遍春日暝。\n不用积金著青天，不用服药求神仙。\n但愿园里花长好，一生饮酒花前老。'},
    {t:'杂曲歌辞·纥那曲',a:'刘禹锡〔唐代〕',c:'杨柳郁青青，竹枝无限情。\n周郎一回顾，听唱纥那声。\n踏曲兴无穷，调同词不同。\n愿郎千万寿，长作主人翁。'},
    {t:'杂曲歌辞·古别离',a:'皎然〔唐代〕',c:'太湖三山口，吴王在时道。寂寞千载心，无人见春草。\n谁堪缄怨者，持此伤怀抱。孤舟畏狂风，一点宿烟岛。\n望所思兮若何，月荡漾兮空波。云离离兮北断，\n雁眇眇兮南多。身去兮天畔，心折兮湖岸。\n春山胡为兮塞路，使我归梦兮撩乱。'},
    {t:'杂曲歌辞·古离别二首',a:'孟郊〔唐代〕',c:'松山云缭绕，萍路水分离。云去眼归日，水分无合时。\n春芳役双眼，春色柔四支。杨柳织别愁，千断万断丝。\n山川古今路，纵横无断绝。来往天地间，人皆眼离别。\n行衣未束带，中肠已先结。不用看镜中，自知生白发。\n欲陈去留意，声向言前咽。愁结填心胸，茫茫若为说。\n荒郊烟莽苍，旷野风凄切。处处得相随，人那不如月。'},
    {t:'杂曲歌辞·何满子',a:'白居易〔唐代〕',c:'世传满子是人名，临就刑时曲始成。\n一曲四词歌八叠，从头便是断肠声。'},
    {t:'杂曲歌辞·湖阴曲',a:'温庭筠〔唐代〕',c:'祖龙黄须珊瑚鞭，铁骢金面青连钱。虎髯拔剑欲成梦，\n日压贼营如血鲜。海旗风急惊眠起，甲重光摇照湖水。\n苍黄追骑尘外归，森索妖星阵前死。五陵愁碧春萋萋，\n灞川玉马空中嘶。羽书如电入青琐，雪腕如捶催画鞞。\n白虬天子金煌铓，高临帝座回龙章。吴波不动楚山晚，\n花压阑干春昼长。'},
    {t:'杂曲歌辞·苦热行行',a:'王维〔唐代〕',c:'赤日满天地，火云成山岳。\n草木尽焦卷，川泽皆涸竭。\n轻纨觉衣重，密树苦阴薄。\n莞簟不可近，絺绤再三濯。\n思出宇宙外，旷然在寥廓。\n长风万里来，江海荡烦浊。\n却顾身为患，始知心未觉。\n忽入甘露门，宛然清凉乐。'},
    {t:'杂曲歌辞·鸣雁行',a:'韩愈〔唐代〕',c:'嗷嗷鸣雁鸣且飞，穷秋南去春北归。去寒就暖识所处，\n天长地阔栖息稀。风霜酸苦稻粱微，羽毛摧落身不肥。\n徘徊反顾群侣违，哀鸣欲下洲渚非。江南水阔朝云多，\n草长沙软无网罗，闲飞静集鸣相和。违忧怀息性匪他，\n凌风一举君谓何。'},
    {t:'杂曲歌辞·妾薄命',a:'张籍〔唐代〕',c:'薄命妇，良家子，无事从军去万里。汉家天子平四夷，\n护羌都尉裹尸归。念君此行为死别，对君裁缝泉下衣。\n与君一日为夫妇，千年万岁亦相守。君爱龙城征战功，\n妾愿青楼欢乐同。人生各各有所欲，讵得将心入君腹。'},
    {t:'杂曲歌辞·妾薄命',a:'孟郊〔唐代〕',c:'不惜十指弦，为君千万弹。常恐悲声至，坐使故声残。\n弃置今日悲，即是昨日欢。将悲变故易，持故为悲难。\n青山有蘼芜，泪叶长不干。空令后代人，采掇幽思攒。'},
    {t:'杂曲歌辞·秋夜长',a:'张籍〔唐代〕',c:'秋天如水夜未央，天汉东西月色光。愁人不寐畏枕席，\n暗虫唧唧绕我傍。荒城为村无更声，起看北斗天未明。\n白露满田风褭褭，千声万声鹖鸟鸣。'},
    {t:'杂曲歌辞·三台二首',a:'韦应物〔唐代〕',c:'一年一年老去，明日后日花开。\n未报长安平定，万国岂得衔杯。\n冰泮寒塘始绿，雨馀百草皆生。\n朝来门閤无事，晚下高斋有情。'},
    {t:'杂曲歌辞·伤歌行',a:'张籍〔唐代〕',c:'黄门诏下促收捕，京兆君系御史府。出门无复部曲随，\n亲戚相逢不容语。辞成谪尉南海州，受命不得须臾留。\n身著青衫骑恶马，东门之东无送者。邮夫防吏急喧驱，\n往往惊堕马蹄下。长安里中荒大宅，朱门已除十二戟。\n高堂舞榭锁管弦，美人遥望西南天。'},
    {t:'杂曲歌辞·伤歌行',a:'孟郊〔唐代〕',c:'众毒蔓贞松，一枝难久荣。岂知黄庭客，仙骨生不成。\n春色舍芳蕙，秋风绕枯茎。弹琴不成曲，始觉知音倾。\n馆月改旧照，吊宾写馀情。还舟空江上，波浪送铭旌。'},
    {t:'杂曲歌辞·少年乐',a:'李贺〔唐代〕',c:'芳草落花如锦地，二十长游醉丝里。\n红缨不重白马骄，垂柳金丝香拂水。\n吴娥未笑花不开，绿鬓耸堕兰云起。\n陆郎倚醉牵罗袂，夺得宝钗金翡翠。'},
    {t:'杂曲歌辞·少年行',a:'张籍〔唐代〕',c:'少年从出猎长杨，禁中新拜羽林郎。独到辇前射双虎，\n君王手赐黄金铛。日日斗鸡都市里，赢得宝刀重刻字。\n百里报仇夜出城，平明还在倡楼醉。遥闻虏到平陵下，\n不待诏书行上马。斩得名王献桂宫，封侯起第一日中。\n不为六郡良家子，百战始取边城功。'},
    {t:'杂曲歌辞·少年行二首',a:'杜牧〔唐代〕',c:'官为骏马监，职帅羽林儿。两绶藏不见，落花何处期。\n猎敲白玉镫，怒袖紫金鎚。田窦长留醉，苏辛曲护岐。\n豪持出塞节，笑别远山眉。捷报云台贺，公卿拜寿卮。\n连环羁玉声光碎，绿锦蔽泥虬卷高。\n春风细雨走马去，珠落璀璀白罽袍。'},
    {t:'杂曲歌辞·神仙曲',a:'李贺〔唐代〕',c:'碧峰海面藏灵书，上帝拣作神仙居。晴时笑语闻空虚，\n斗乘巨浪骑鲸鱼。春罗翦字邀王母，共宴红楼最深处。\n鹤羽冲风过海迟，不如却使青龙去。犹疑王母不相许，\n垂露娃鬟更传语。'},
    {t:'杂曲歌辞·十二月乐辞·九月',a:'李贺〔唐代〕',c:'离宫散萤天似水，竹黄池冷芙蓉死。月缀金铺光脉脉，\n凉苑虚庭空澹白。霜花飞飞风草草，翠锦斓斑满层道。\n鸡人罢唱晓珑璁，鸦啼金井下疏桐。'},
    {t:'杂曲歌辞·十二月乐辞·六月',a:'李贺〔唐代〕',c:'裁生罗，伐湘竹，帔拂疏霜簟秋玉。\n炎炎红镜东方开，晕如车轮上徘徊，啾啾赤帝骑龙来。'},
    {t:'杂曲歌辞·十二月乐辞·七月',a:'李贺〔唐代〕',c:'星依云渚冷，露滴盘中圆。好花生木末，衰蕙愁空园。\n夜天如玉砌，池叶极青钱。仅厌舞衫薄，稍知花簟寒。\n晓风何拂拂，北斗光阑干。'},
    {t:'杂曲歌辞·十二月乐辞·三月',a:'李贺〔唐代〕',c:'东方风来满眼春，花城柳暗愁襟人。\n复宫深殿竹风起，新翠舞襟静如水。\n光风转蕙百馀里，暖雾驱云扑天地。\n军装宫妓扫蛾浅，摇摇锦旗夹城暖。\n曲水飘香去不归，梨花落尽成秋苑。'},
    {t:'杂曲歌辞·十二月乐辞·十二月',a:'李贺〔唐代〕',c:'日脚淡光红洒洒，薄霜不销桂枝下。\n依稀和气解冬严，已就长日辞长夜。'},
    {t:'杂曲歌辞·十二月乐辞·十一月',a:'李贺〔唐代〕',c:'宫城团回凛严光，白天碎碎堕琼芳。挝钟高饮千日酒，\n却天凝寒作君寿。御沟泉合如环素，火井温水在何处。'},
    {t:'杂曲歌辞·十二月乐辞·十月',a:'李贺〔唐代〕',c:'玉壶银箭稍难倾，釭花夜笑凝行明。碎霜斜舞上罗幕，\n烛笼两行照飞阁。珠帷怨卧不成眠，金凤刺衣著体寒，\n长眉对月斗弯环。'},
    {t:'杂曲歌辞·十二月乐辞·五月',a:'李贺〔唐代〕',c:'雕玉押帘上，轻縠笼虚门。井汲铅华水，扇织鸳鸯文。\n回雪舞凉殿，甘露洗空绿。罗袖从徊翔，香汗沾宝粟。'},
    {t:'杂曲歌辞·十二月乐辞·五月',a:'李贺〔唐代〕',c:'雕玉押帘上，轻毂笼虚门。井汲铅华水，扇织鸳鸯文。\n回雪舞凉殿，甘露洗空绿。罗袖从徊翔，香汗沾宝粟。'},
    {t:'杂曲歌辞·十二月乐辞·正月',a:'李贺〔唐代〕',c:'上楼迎春新春归，暗黄著柳宫漏迟。\n薄薄淡霭弄野姿，寒绿幽泥生短丝。\n锦床晓卧玉肌冷，露脸未开对朝暝。\n官街柳带不堪折，早晚菖蒲胜绾结。'},
    {t:'杂曲歌辞·水调歌第一',a:'佚名〔唐代〕',c:'平沙落日大荒西，陇上明星高复低。\n孤山几处看烽火，壮士连营候鼓鼙。'},
    {t:'杂曲歌辞·突厥三台',a:'韦应物〔唐代〕',c:'雁门山上雁初飞，马邑阑中马正肥。\n日旰山西逢驿使，殷勤南北送征衣。'},
    {t:'杂曲歌辞·无愁果有愁曲',a:'李商隐〔唐代〕',c:'东有青龙西白虎，中含福皇包世度。\n玉壶渭水笑清潭，凿天不到牵牛处。\n骐麟踏云天马狞，牛山撼碎珊瑚声。\n秋娥点滴不成泪，十二玉楼无故钉。\n推烟唾月抛千里，十番红桐一行死。\n白杨别屋鬼迷人，空留暗记如蚕纸。\n日暮向风牵短丝，血凝血散今谁是。'},
    {t:'杂曲歌辞·西洲曲',a:'温庭筠〔唐代〕',c:'悠悠复悠悠，昨日下西洲。\n西洲风色好，遥见武昌楼。\n武昌何郁郁，侬家定无匹。\n小妇被流黄，登楼抚瑶瑟。\n朱弦繁复轻，素手直凄清。\n一弹三四解，掩抑似含情。\n南楼登且望，西江广复平。\n艇子摇两桨，催过石头城。\n门前乌臼树，惨澹天将曙。\n鹍鵊飞复还，郎随早帆去。\n回头语同伴，定复负情侬。\n去帆不安幅，作抵使西风。\n他日相寻索，莫作西洲客。\n西洲人不归，春草年年碧。'},
    {t:'杂曲歌辞·侠客行',a:'元稹〔唐代〕',c:'侠客白怕死，怕在事白成。\n事成白肯藏姓名，我非窃贼谁夜行。\n白日堂堂杀袁盎，九衢草草人背青。\n此客此心师海鲸，海鲸露背横沧溟。\n海滨分作两处生，海鲸分海减海力。\n侠客有谋人白测，三尺铁蛇延二国。'},
    {t:'杂曲歌辞·行路难',a:'韦应物〔唐代〕',c:'荆山之白玉兮，良工雕琢双环连，月蚀中央镜心穿。\n故人赠妾初相结，恩在环中寻不绝。人情厚薄苦须臾，\n昔似连环今似玦。连环可碎不可离，如何物在人自移。\n上客勿遽欢，听妾歌路难。傍人见环环可怜，\n不知中有长恨端。'},
    {t:'杂曲歌辞·行路难',a:'张籍〔唐代〕',c:'湘东行人长叹息，十年离家归未得。\n弊裘羸马苦难行，僮仆饥寒少筋力。\n君不见床头黄金尽，壮士无颜色。\n龙蟠泥中未有云，不能生彼升天翼。'},
    {t:'杂曲歌辞·行路难二首',a:'高适〔唐代〕',c:'君不见富家翁，昔时贫贱谁比数。一朝金多结豪贵，\n万事胜人健如虎。子孙成长满眼前，妻能管弦妾能舞。\n自矜一朝忽如此，却笑傍人独悲苦。东邻少年安所如，\n席门穷巷出无车。有才不肯学干谒，何用年年空读书。\n长安少年不少钱，能骑骏马鸣金鞭。五侯相逢大道边，\n美人弦管争留连。黄金如斗不敢惜，片言如山莫弃捐。\n安知憔悴读书者，暮宿虚台私自怜。'},
    {t:'杂曲歌辞·杨柳枝',a:'刘禹锡〔唐代〕',c:'扬子江头烟景迷，隋家宫树拂中堤。\n嵯峨犹有当时色，半蘸波中水鸟栖。\n迎得春光先到来，浅思轻绿映楼台。\n只缘袅娜多情思，便被春风长请挼。\n巫峡巫山杨柳多，朝云暮雨远相和。\n因想阳台无限事，为君回唱竹枝歌。'},
    {t:'杂曲歌辞·游侠行',a:'孟郊〔唐代〕',c:'壮士性刚决，火中见石裂。\n杀人不回头，轻生如暂别。\n岂知眼有泪，肯白头上发。\n平生无恩酬，剑闲一百月。'},
    {t:'杂曲歌辞·远别离',a:'张籍〔唐代〕',c:'莲叶团团杏花拆，长江鲤鱼鳍鬣赤。念君少年弃亲戚，\n千里万里独为客。谁言远别心不易，天星坠地能为石。\n几时断得城南陌，勿使居人有行役。'},
    {t:'杂曲歌辞·长安少年行',a:'皎然〔唐代〕',c:'翠楼春酒虾蟆陵，长安少年皆共矜。\n纷纷半醉绿槐道，蹀躞花骢骄不胜。'},
    {t:'杂曲歌辞·筑城曲',a:'张籍〔唐代〕',c:'筑城去，千人万人齐抱杵。重重土坚试行锥，\n军吏执鞭催作迟。来时一年深碛里，著尽短衣渴无水。\n力尽不得抛杵声，杵声未定人皆死。家家养男当门户，\n今日作君城下土。'},
    {t:'杂曲歌辞其二',a:'高适〔唐代〕',c:'汉家能用武，开拓穷异域。戍卒厌糠覈，降胡饱衣食。\n开亭试一望，吾欲涕沾臆。'},
    {t:'杂曲歌辞其四',a:'高适〔唐代〕',c:'边城十一月，雨雪乱霏霏。元戎号令严，人马亦轻肥。\n羌胡无尽日，征战几时归。'},
    {t:'杂曲歌辞其五',a:'高适〔唐代〕',c:'幽州多骑射，结发重横行。一朝事将军，出入有声名。\n纷纷猎秋草，相向角弓鸣。'},
    {t:'杂曲歌辞行路难二首其一',a:'高适〔唐代〕',c:'君不见富家翁，旧时贫贱谁比数。一朝金多结豪贵，万事胜人健如虎。\n子孙成行满眼前，妻能管弦妾能舞。自矜一身忽如此，却笑傍人独愁苦。\n东邻少年安所如，席门穷巷出无车。有才不肯学干谒，何用年年空读书。'},
    {t:'杂诗',a:'韩愈〔唐代〕',c:'古史散左右，诗书置后前。岂殊蠹书虫，生死文字间。\n古道自愚蠢，古言自包缠。当今固殊古，谁与为欣欢。\n独携无言子，共升昆仑颠。长风飘襟裾，遂起飞高圆。\n下视禹九州，一尘集豪端。遨嬉未云几，下已亿万年。\n向者夸夺子，万坟厌其巅。惜哉抱所见，白黑未及分。\n慷慨为悲咤，泪如九河翻。指摘相告语，虽还今谁亲。\n翩然下大荒，被发骑骐驎。'},
    {t:'杂诗',a:'王维〔唐代〕',c:'朝因折杨柳，相见洛阳隅。\n楚国腕如妾，秦家自有夫。\n对人传玉腕，映烛解罗襦。\n人见东方骑，皆言夫婿殊。\n持谢金吾子，烦君提玉壶。'},
    {t:'杂诗·近寒食雨草萋萋',a:'佚名〔唐代〕',c:'近寒食雨草萋萋，著麦苗风柳映堤。\n等是有家归未得，杜鹃休向耳边啼。'},
    {t:'杂诗·其八',a:'陶渊明〔魏晋〕',c:'代耕本非望，所业在田桑。\n躬亲未曾替，寒馁常糟糠。\n岂期过满腹，但愿饱粳粮。\n御冬足大布，粗絺已应阳。\n正尔不能得，哀哉亦可伤！\n人皆尽获宜，拙生失其方。\n理也可奈何！且为陶一觞。'},
    {t:'杂诗·其十一',a:'陶渊明〔魏晋〕',c:'我行未云远，回顾惨风凉。\n春燕应节起，高飞拂尘梁。\n边雁悲无所，代谢归北乡。\n离昆鸣清池，涉暑经秋霜。\n愁人难为辞，遥遥春夜长。'},
    {t:'杂诗七首·其二',a:'黄庭坚〔宋代〕',c:'营巢燕燕几时休，在处成家春复秋。\n岁岁自来还自去，主人无厌客无求。'},
    {t:'杂诗七首·其六',a:'黄庭坚〔宋代〕',c:'古屋清寒雪未消，小窗晴日展芭蕉。\n酸甘荔子尝春酒，更碾新芽荐菊苗。'},
    {t:'杂诗七首·其七',a:'黄庭坚〔宋代〕',c:'碧窗凉簟唯便睡，露井无尘荫绿槐。\n梦入醉乡犹病渴，辘轳声到枕边来。'},
    {t:'杂诗七首·其三',a:'黄庭坚〔宋代〕',c:'馆甥宫里叹才难，当日同朝听百官。\n光武早知尧舜事，只今那得子陵滩。'},
    {t:'杂诗七首·其四',a:'黄庭坚〔宋代〕',c:'少年不爱万金身，歌舞寻春愁送春。\n满眼纷华心寂寞，长安市上酒家人。'},
    {t:'杂诗七首·其五',a:'黄庭坚〔宋代〕',c:'薰炉茶鼎偶然同，晴日鸦啼柿叶风。\n万事尽还麴居士，百年常在大槐宫。'},
    {t:'杂诗七首·其一',a:'黄庭坚〔宋代〕',c:'此身天地一蘧庐，世事消磨绿鬓疏。\n毕竟几人真得鹿，不知终日梦为鱼。'},
    {t:'杂诗三首',a:'王维〔唐代〕',c:'家住孟津河，门对孟津口。\n常有来南船，寄书家中否。\n君自故乡来，应知故乡事。\n来日绮窗前，寒梅著花未。\n已见寒梅发，复闻啼鸟声。\n愁心视春草，畏向阶前生。'},
    {t:'杂诗三首·其二',a:'王维〔唐代〕',c:'君自故乡来，应知故乡事。\n来日绮窗前，寒梅著花未？'},
    {t:'杂诗十二首·其二',a:'陶渊明〔魏晋〕',c:'白日沦西河，素月出东岭。\n遥遥万里晖，荡荡空夕景。\n风来入房户，夜夕枕席冷。\n气变悟时易，不眠知夕永。\n欲言无予和，挥杯劝孤影。\n日月掷人去，有志不获骋。\n念此怀悲凄，终晓不能静。'},
    {t:'杂诗十二首·其六',a:'陶渊明〔魏晋〕',c:'昔闻长者言，掩耳每不喜。\n奈何欢十年，忽已亲此事。\n求我盛年欢，一毫无复意。\n去去转欲速，此生岂再值。\n倾家持作乐，竟此岁月驶。\n有子不留金，何用身後置！'},
    {t:'杂诗十二首·其七',a:'陶渊明〔魏晋〕',c:'日月不肯迟，四时相催迫。\n寒风拂枯条，落叶掩长陌。\n弱质与运颓，玄鬓早已白。\n素标插人头，前途渐就窄。\n家为逆旅舍，我如当去客。\n去去欲何之？南山有旧宅。'},
    {t:'杂诗十二首·其三',a:'陶渊明〔魏晋〕',c:'荣华难久居，盛衰不可量。\n昔为草春蕖，今作秋莲房。\n严霜结野草，枯悴未遽央。\n日月还复周，我去不再阳。\n眷眷往昔时，忆此断人肠。'},
    {t:'杂诗十二首·其十',a:'陶渊明〔魏晋〕',c:'闲居执荡志，时驶不可稽。\n驱役麝停息，轩裳逝东崖。\n沉阴拟薰麝，寒气激我怀。\n岁月有常御，我来淹已弥。\n慷慨忆绸缪，此情久已离。\n荏苒经十载，暂为人所羁。\n庭宇翳馀木，倏忽日月亏。'},
    {t:'杂诗十二首·其十二',a:'陶渊明〔魏晋〕',c:'袅袅松标崖，婉娈柔童子。\n年始二五间，乔柯何可倚。\n养色含津气，粲然有心理。'},
    {t:'杂诗十二首·其四',a:'陶渊明〔魏晋〕',c:'丈夫志四海，我愿不知老。\n亲戚共一处，子孙还相保。\n觞弦肆朝日，樽中酒不燥。\n缓带尽欢娱，起晚眠常早。\n孰若当世士，冰炭满怀抱。\n百年归丘垄，用此空名道！'},
    {t:'杂诗十二首·其五',a:'陶渊明〔魏晋〕',c:'忆我少壮时，无乐自欣豫。\n猛志颓四海，骞翮思远翥。\n荏苒岁月颓，此心稍已去。\n值欢无复娱，不不多忧虑。\n气力渐衰损，转觉日不如。\n壑舟无须臾，引我不得住。\n前涂当几许，未知止泊处。\n古人惜寸阴，念此使人惧。'},
    {t:'杂诗十二首·其一',a:'陶渊明〔魏晋〕',c:'人生无根蒂，飘如陌上尘。\n分散弟风转，此已非常身。\n落地为兄弟，何必骨肉亲！\n得欢当作乐，斗酒聚比邻。\n盛年不重来，一日难再晨。\n及时当勉励，岁月不待人。'},
    {t:'杂诗五首其三',a:'张九龄〔唐代〕',c:'良辰不可遇，心赏更蹉跎。终日块然坐，有时劳者歌。\n庭前揽芳蕙，江上托微波。路远无能达，忧情空复多。'},
    {t:'杂诗五首其四',a:'张九龄〔唐代〕',c:'湘水吊灵妃，斑竹为情绪。汉水访游女，解佩欲谁与。\n同心不可见，异路空延伫。浦上青枫林，津傍白沙渚。\n行吟至落日，坐望秖愁予。神物亦岂孤，佳期竟何许。'},
    {t:'杂说一·龙说',a:'韩愈〔唐代〕',c:'龙嘘气成云，云固弗灵于龙也。然龙乘是气，茫洋穷乎玄间，薄日月，伏光景，感震电，神变化，水下土，汩陵谷，云亦灵怪矣哉!\n云，龙之所能使为灵也；若龙之灵，则非云之所能使为灵也。然龙弗得云，无以神其灵矣。失其所凭依，信不可欤！\n异哉！其所凭依，乃其所自为也。《易》曰：“云从龙。”既曰：龙，云从之矣。'},
    {t:'杂兴',a:'王昌龄〔唐代〕',c:'握中铜匕首，粉锉楚山铁。\n义士频报雠，杀人不曾缺。\n可悲燕丹事，终被狼虎灭。\n一举无两全，荆轲遂为血。\n诚知匹夫勇，何取万人杰。\n无道吞诸侯，坐见九州裂。'},
    {t:'杂兴',a:'陆游〔宋代〕',c:'古寺高楼暮倚阑，野云不散白漫漫。\n好山遮尽君无恨，且作沧溟万里看。'},
    {t:'杂言送黎六郎·寿阳公之子',a:'韦应物〔唐代〕',c:'冰壶见底未为清，少年如玉有诗名。闻话嵩峰多野寺，\n不嫌黄绶向阳城。朱门严训朝辞去，骑出东郊满飞絮。\n河南庭下拜府君，阳城归路山氛氲。山氛氲，长不见。\n钓台水渌荷已生，少姨庙寒花始遍。县闲吏傲与尘隔，\n移竹疏泉常岸帻。莫言去作折腰官，岂似长安折腰客。'},
    {t:'杂忆五首',a:'元稹〔唐代〕',c:'今年寒食月无光，夜色才侵已处床。\n忆得双文通内里，玉栊深处暗闻香。\n花笼微月竹笼烟，百后丝绳拂地悬。\n忆得双文人静后，潜教桃叶送秋千。\n寒轻夜浅绕回廊，不辨花丛暗辨香。\n忆得双文胧月下，小楼前后捉迷藏。\n山榴似火叶相兼，亚拂砖阶半拂檐。\n忆得双文独披掩，满头花草倚新帘。\n春冰消尽碧波湖，漾影残霞似有无。\n忆得双文衫子薄，钿头云映褪红酥。'},
    {t:'杂咏四首',a:'范仲淹〔宋代〕',c:'铿铿千古峄山桐，金石声来造化中。\n谁道元和无复致，为君堂上起薰风。'},
    {t:'杂寓兴',a:'皎然〔唐代〕',c:'嗟嗟号呶子，世称谪仙俦。媚俗被鲛绡，欺天荐昫修。\n奔景谓可致，驰龄言易流。燕昭昧往事，嬴政亡前筹。\n三山果不见，九仙忽悠悠。君看牛山乐，君见麋浦游。\n昨日千金子，联绵成古丘。吾将揽明月，照尔生死流。\n至乐享爰居，惭贻达者尤。冥冥光尘内，机丧成海沤。'},
    {t:'杂怨',a:'张籍〔唐代〕',c:'切切重切切，秋风桂枝折。人当少年嫁，我当少年别。\n念君非征行，年年长远途。妾身甘独殁，高堂有舅姑。\n山川岂遥远，行人自不返。'},
    {t:'宰嚭',a:'王安石〔宋代〕',c:'谋臣本自系安危，贱妾何能作祸基。\n但愿君王诛宰嚭，不愁宫里有西施。'},
    {t:'宰予昼寝',a:'佚名〔先秦〕',c:'宰予昼寝，子曰：“朽木不可雕也，诛土之墙不可圬也！于予与何诛？”子曰：“始吾于人也，听其言而信其行；今吾于人也，听其言而观其行。于予与改是。”'},
    {t:'再次韵寄子由',a:'黄庭坚〔宋代〕',c:'想见苏耽携手僊，青山桑柘冒寒烟。\n骐驎堕地思千里，虎豹憎人上九天。\n风雨极知鸡自晓，雪霜宁与菌争年。\n何时确论倾樽酒，医得儒生自圣颠。'},
    {t:'再和',a:'朱熹〔宋代〕',c:'久矣投装返旧墟，不将心事赋闲居。\n荷锄带月朝治秽，植杖临风夕挽蔬。\n三径犹寻陶令宅，万签聊借邺侯书。\n木瓜更得琼琚报，吟咏从今乐有馀。'},
    {t:'再上湘江',a:'柳宗元〔唐代〕',c:'好在湘江水，今朝又上来。\n不知从此去，更遣几年回。'},
    {t:'再授连州至衡阳酬柳柳州赠别',a:'刘禹锡〔唐代〕',c:'去国十年同赴召，渡湘千里又分歧。\n重临事异黄丞相，三黜名惭柳士师。\n归目并随回雁尽，愁肠正遇断猿时。\n桂江东过连山下，相望长吟有所思。'},
    {t:'再下第',a:'孟郊〔唐代〕',c:'一夕九起嗟，梦短不到家。两度长安陌，空将泪见花。'},
    {t:'再游玄都观',a:'刘禹锡〔唐代〕',c:'百亩庭中半是苔，桃花净尽菜花开。\n种桃道士归何处，前度刘郎今又来。'},
    {t:'在儋耳书',a:'苏轼〔宋代〕',c:'吾始至南海，环视天水无际，凄然伤之曰：”何时得出此岛耶？“已而思之：天地在积水之中，九州在大瀛海中，中国在少海中，有生孰不在岛者？覆盆水于地，芥浮于水，蚁附于芥，茫然不知所济。少焉水涸，蚁即径去；见其类，出涕曰：”几不复与子相见。“岂知俯仰之间，有方轨八达之路乎？念此可以一笑。\n戊寅九月十二日，与客饮薄酒小醉，信笔书此纸。'},
    {t:'在水军宴赠幕府诸侍御',a:'李白〔唐代〕',c:'月化五白龙，翻飞凌九天。\n胡沙惊北海，电扫洛阳川。\n虏箭雨宫阙，皇舆成播迁。\n英王受庙略，秉钺清南边。\n云旗卷海雪，金戟罗江烟。\n聚散百万人，弛张在一贤。\n霜台降群彦，水国奉戎旃。\n绣服开宴语，天人借楼船。\n如登黄金台，遥谒紫霞仙。\n卷身编蓬下，冥机四十年。\n宁知草间人，腰下有龙泉。\n浮云在一决，誓欲清幽燕。\n愿与四座公，静谈金匮篇。\n齐心戴朝恩，不惜微躯捐。\n所冀旄头灭，功成追鲁连。'},
    {t:'遭田父泥饮',a:'杜甫〔唐代〕',c:'田翁逼社日，邀我尝春酒。\n朝来偶然出，自卯将及酉。\n高声索果栗，欲起时被肘。\n指挥过无礼，未觉村野丑。\n月出遮我留，仍嗔问升斗。'},
    {t:'早蝉',a:'白居易〔唐代〕',c:'六月初七日，江头蝉始鸣。\n石楠色叶里，薄暮两三声。\n一催衰鬓色，再动故园情。\n西风殊未起，秋思先秋生。\n忆昔在东掖，宫槐花下听。\n今朝无限思，云树绕湓城。'},
    {t:'早朝',a:'王维〔唐代〕',c:'皎洁明星高，苍茫远天曙。槐雾暗不开，城鸦鸣稍去。\n始闻高阁声，莫辨更衣处。银烛已成行，金门俨驺驭。'},
    {t:'早朝寄白舍人、严郎中',a:'张籍〔唐代〕',c:'鼓声初动未闻鸡，羸马街中踏冻泥。烛暗有时冲石柱，\n雪深无处认沙堤。常参班里人犹少，待漏房前月欲西。\n凤阙星郎离去远，閤门开日入还齐。'},
    {t:'早春',a:'秦观〔宋代〕',c:'黄金蔌蔌满垂杨，尚有春寒到画堂。\n酒力渐销歌扇怯，入帘飞雪带梅香。'},
    {t:'早春',a:'白居易〔唐代〕',c:'雪散因和气，冰开得暖光。\n春销不得处，唯有鬓边霜。'},
    {t:'早春浐水送友人',a:'温庭筠〔唐代〕',c:'青门烟野外，渡浐送行人。鸭卧溪沙暖，鸠鸣社树春。\n残波青有石，幽草绿无尘。杨柳东风里，相看泪满巾。'},
    {t:'早春呈水部张十八员外二首',a:'韩愈〔唐代〕',c:'天街小雨润如酥，草色遥看近柳无。\n最是一年春好处，绝胜烟柳满皇都。\n莫道官忙身老大，即无年少逐春心。\n凭君先到江头看，柳色如今深未深。'},
    {t:'早春对雪寄前殿中元侍御',a:'韦应物〔唐代〕',c:'扫雪开幽径，端居望故人。\n犹残腊月酒，更值早梅春。\n几日东城陌，何时曲水滨。\n闻闲且共赏，莫待绣衣新。'},
    {t:'早春寄王汉阳',a:'李白〔唐代〕',c:'闻道春还未相识，走傍寒梅访消息。\n昨夜东风入武阳，陌头杨柳黄金色。\n碧水浩浩云茫茫，美人不来空断肠。\n预拂青山一片石，与君连日醉壶觞。'},
    {t:'早春陪崔中丞同泛浣花谿宴',a:'岑参〔唐代〕',c:'旌节临谿口，寒郊陡觉暄。红亭移酒席，画舸逗江村。\n云带歌声飏，风飘舞袖翻。花间催秉烛，川上欲黄昏。'},
    {t:'早春润州送从弟还乡',a:'孟浩然〔唐代〕',c:'兄弟游吴国，庭闱恋楚关。已多新岁感，更饯白眉还。\n归泛西江水，离筵北固山。乡园欲有赠，梅柳著先攀。'},
    {t:'早春书怀寄李少府仲宣',a:'皎然〔唐代〕',c:'早年初问法，因悟目中花。忽值胡雏起，芟夷若乱麻。\n脱身投彼岸，吊影念生涯。迹与空门合，心将世路赊。\n东田已芜没，南涧益伤嗟。崇替惊人事，凋残感物华。\n知君过我里，惆怅旧烟霞。'},
    {t:'早春题僧舍',a:'秦观〔宋代〕',c:'东园紫梅初破蕾，北涧渌水方通流。\n归去一春花月梦，定应多在此中游。'},
    {t:'早春题真上人院·生天宝初',a:'杜牧〔唐代〕',c:'清羸已近百年身，古寺风烟又一春。\n寰海自成戎马地，唯师曾是太平人。'},
    {t:'早春闲游',a:'张籍〔唐代〕',c:'年长身多病，独宜作冷官。从来闲坐惯，渐觉出门难。\n树影新犹薄，池光晚尚寒。遥闻有花发，骑马暂行看。'},
    {t:'早春行',a:'王维〔唐代〕',c:'紫梅发初遍，黄鸟歌犹涩。\n谁家坐杨女，弄春如不及。\n爱水看妆坐，羞人映花立。\n香畏风吹散，衣车露沾湿。\n玉闺青门里，日落香车入。\n游衍益相思，含啼向彩帷。\n忆君长入梦，归晚更生疑。\n不及红檐燕，双栖绿草时。'},
    {t:'早冬',a:'白居易〔唐代〕',c:'十月江南天气好，可怜冬景似春华。\n霜轻未杀萋萋草，日暖初干漠漠沙。\n老柘叶黄如嫩树，寒樱枝白是狂花。\n此时却羡闲人醉，五马无由入酒家。'},
    {t:'早发白帝城',a:'李白〔唐代〕',c:'朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。'},
    {t:'早发焉耆怀终南别业',a:'岑参〔唐代〕',c:'晓笛别乡泪，秋冰鸣马蹄。一身虏云外，万里胡天西。\n终日见征战，连年闻鼓鼙。故山在何处，昨日梦清溪。'},
    {t:'早发渔浦潭',a:'孟浩然〔唐代〕',c:'东旭早光芒，渚禽已惊聒。卧闻渔浦口，桡声暗相拨。\n日出气象分，始知江湖阔。美人常晏起，照影弄流沫。\n饮水畏惊猿，祭鱼时见獭。舟行自无闷，况值晴景豁。'},
    {t:'早归',a:'元稹〔唐代〕',c:'春静晓风微，凌晨带酒归。\n远山笼宿雾，高树影朝晖。\n饮马鱼惊水，穿花露滴衣。\n娇莺似相恼，含啭傍人飞。'},
    {t:'早寒江上有怀',a:'孟浩然〔唐代〕',c:'木落雁南度，北风江上寒。\n我家尽水曲，遥隔楚云端。\n乡泪客中尽，孤帆天际看。\n迷津欲有问，平海夕漫漫。'},
    {t:'早梅',a:'柳宗元〔唐代〕',c:'早梅发高树，迥映楚天碧。\n朔吹飘夜香，繁霜滋晓白。\n欲为万里赠，杳杳山水隔。\n寒英坐销落，何用慰远客。'},
    {t:'早梅',a:'孟浩然〔唐代〕',c:'园中有早梅，年例犯寒开。\n少妇曾攀折，将归插镜台。\n犹言看不足，更欲剪刀裁。'},
    {t:'早梅芳·别恨·二之一',a:'周邦彦〔宋代〕',c:'花竹深，房栊好。夜阒无人到。隔窗寒雨，向壁孤灯弄余照。泪多罗袖重，意密莺声小。正魂惊梦怯，门外已知晓。\n去难留，话未了。早促登长道。风披宿雾，露洗初阳射林表。乱愁迷远览，苦语萦怀抱。谩回头，更堪归路杳。'},
    {t:'早梅芳·牵情·二之二',a:'周邦彦〔宋代〕',c:'缭墙深，丛竹绕。宴席临清沼。微呈纤履，故隐烘帘自嬉笑。粉香妆晕薄，带紧腰围小。看鸿惊凤翥，满座叹轻妙。\n酒醒时，会散了。回首城南道。河阴高转，露脚斜飞夜将晓。异乡淹岁月，醉眼迷登眺。路迢迢，恨满千里草。'},
    {t:'早梅芳·上孙资政',a:'柳永〔宋代〕',c:'海霞红，山烟翠。故都风景繁华地。谯门画戟，下临万井，金碧楼台相倚。芰荷浦溆，杨柳汀洲，映虹桥倒影，兰舟飞棹，游人聚散，一片湖光里。\n汉元侯，自从破虏征蛮，峻陟枢庭贵。筹帷厌久，盛年昼锦，归来吾乡我里。铃斋少讼，宴馆多欢，未周星，便恐皇家，图任勋贤，又作登庸计。'},
    {t:'早起',a:'李商隐〔唐代〕',c:'风露澹清晨，帘间独起人。\n莺花啼又笑，毕竟是谁春。'},
    {t:'早起偶成',a:'文天祥〔宋代〕',c:'江山如有意，天地可无秋。\n夜月冯驩铗，西风王粲楼。\n露蛩令我喜，烟草为谁愁。\n且醉杯中物，相看尚黑头。'},
    {t:'早秋',a:'杜牧〔唐代〕',c:'疏雨洗空旷，秋标惊意新。\n大热去酷吏，清风来故人。\n樽酒酌未酌，晓花颦不颦。\n铢秤与缕雪，谁觉老陈陈？'},
    {t:'早秋客舍',a:'杜牧〔唐代〕',c:'风吹一片叶，万物已惊秋。\n独夜他乡泪，年年为客愁。\n别离何处尽，摇落几时休。\n不及磻溪叟，身闲长自由。'},
    {t:'早秋陪韩明府泛阮元公溪',a:'皎然〔唐代〕',c:'雨信清残暑，萧条古县西。早凉生浦溆，秋意满高低。\n前事虽堆案，闲情得溯溪。何言战未胜，空寂用还齐。'},
    {t:'早秋曲江感怀',a:'白居易〔唐代〕',c:'离离暑云散，袅袅凉风起。\n池上秋又来，荷花半成子。\n朱颜易销歇，白日无穷已。\n人寿不如山，年光忽于水。\n青芜与红蓼，岁岁秋相似。\n去岁此悲秋，今秋复来此。'},
    {t:'早秋山居',a:'温庭筠〔唐代〕',c:'山近觉寒早，草堂霜气晴。\n树凋窗有日，池满水无声。\n果落见猿过，叶干闻鹿行。\n素琴机虑静，空伴夜泉清。'},
    {t:'早秋山中作',a:'王维〔唐代〕',c:'无才不敢累明时，思向东溪守故篱。\n岂厌尚平婚嫁早，却嫌陶令去官迟。\n草间蛩响临秋急，山里蝉声薄暮悲。\n寂寞柴门人不到，空林独与白云期。'},
    {t:'早秋与诸子登虢州西亭观眺',a:'岑参〔唐代〕',c:'亭高出鸟外，客到与云齐。\n树点千家小，天围万岭低。\n残虹挂陕北，急雨过关西。\n酒榼缘青壁，瓜田傍绿溪。\n微官何足道，爱客且相携。\n唯有乡园处，依依望不迷。'},
    {t:'早秋雨后寄乐天',a:'刘禹锡〔唐代〕',c:'夜云起河汉，朝雨洒高林。梧叶先风落，草虫迎湿吟。\n簟凉扇恩薄，室静琴思深。且喜炎前别，安能怀寸阴。'},
    {t:'早入荥阳界',a:'王维〔唐代〕',c:'汎舟入荥泽，兹邑乃雄藩。\n河曲闾阎隘，川中烟火繁。\n因人见风俗，入境闻方言。\n秋野田畴盛，朝光市井喧。\n渔商波上客，鸡犬岸旁村。\n前路白云外，孤帆安可论。'},
    {t:'早上五盘岭',a:'岑参〔唐代〕',c:'平旦驱驷马，旷然出五盘。\n江回两崖斗，日隐群峰攒。\n苍翠烟景曙，森沉云树寒。\n松疏露孤驿，花密藏回滩。\n栈道谿雨滑，畬田原草干。\n此行为知己，不觉蜀道难。'},
    {t:'早行',a:'杜牧〔唐代〕',c:'垂鞭信马行，数里未鸡鸣。\n林下带残梦，叶飞时忽惊。\n霜凝孤鹤迥，月晓远山横。\n僮仆休辞险，时平路复平。'},
    {t:'早行',a:'黄庭坚〔宋代〕',c:'失枕惊先起，人家半梦中。\n闻鸡凭早晏，占斗认西东。\n辔湿知行露，衣单觉晓风。\n秋阳弄光影，忽吐半林红。'},
    {t:'早兴',a:'白居易〔唐代〕',c:'晨光出照屋梁明，初打开门鼓一声。\n犬上阶眠知地湿，鸟临窗语报天晴。\n半销宿酒头仍重，新脱冬衣体乍轻。\n睡觉心空思想尽，近来乡梦不多成。'},
    {t:'早雁',a:'杜牧〔唐代〕',c:'金河秋半虏弦开，云外惊飞四散哀。\n仙掌月明孤影过，长门灯暗数声来。\n须知胡骑纷纷在，岂逐春风一一回？\n莫厌潇湘少人处，水多菰米岸莓苔。'},
    {t:'蚤秋',a:'文天祥〔宋代〕',c:'寒魄澹玄河，商飙慓明发。\n羁人坐环堵，壮士衣穿褐。\n晋陵谁复新，秦陵尚云秣。\n夫君百世心，患不在饥渴。'},
    {t:'责子',a:'陶渊明〔魏晋〕',c:'白发被两鬓，肌肤不复实。\n虽有五男儿，总不好纸笔。\n阿舒已二八，懒惰故无匹。\n阿宣行志学，而不爱文术。\n雍端年十三，不识六与七。\n通子垂九龄，但觅梨与栗。\n天运苟如此，且进杯中物。'},
    {t:'择友',a:'孟郊〔唐代〕',c:'兽中有人性，形异遭人隔。\n人中有兽心，几人能真识。\n古人形似兽，皆有大圣德。\n今人表似人，兽心安可测。\n虽笑未必和，虽哭未必戚。\n面结口头交，肚里生荆棘。\n好人常直道，不顺世间逆。\n恶人巧谄多，非义苟且得。\n若是效真人，坚心如铁石。\n不谄亦不欺，不奢复不溺。\n面无吝色容，心无诈忧惕。\n君子大道人，朝夕恒的的。'},
    {t:'赠白道者',a:'李商隐〔唐代〕',c:'十二楼前再拜辞，灵风正满碧桃枝。\n壶中若是有天地，又向壶中伤别离。'},
    {t:'赠别褚山人',a:'高适〔唐代〕',c:'携手赠将行，山人道姓名。光阴蓟子训，才术褚先生。\n墙上梨花白，尊中桂酒清。洛阳无二价，犹是慕风声。'},
    {t:'赠别二首·其二',a:'杜牧〔唐代〕',c:'多情却似总无情，唯觉尊前笑不成。\n蜡烛有心还惜别，替人垂泪到天明。'},
    {t:'赠别二首·其一',a:'杜牧〔唐代〕',c:'娉娉袅袅十三余，豆蔻梢头二月初。\n春风十里扬州路，卷上珠帘总不如。'},
    {t:'赠别河南李功曹',a:'韦应物〔唐代〕',c:'耿耿抱私戚，寥寥独掩扉。\n临觞自不饮，况与故人违。\n故人方琢磨，瑰朗代所稀。\n宪礼更右职，文翰洒天机。\n聿来自东山，群彦仰馀辉。\n谈笑取高第，绾绶即言归。\n洛都游燕地，千里及芳菲。\n今朝章台别，杨柳亦依依。\n云霞未改色，山川犹夕晖。\n忽复不相见，心思乱霏霏。'},
    {t:'赠别冀侍御崔司议',a:'陈子昂〔唐代〕',c:'有道君匡国，无闷余在林。\n白云峨眉上，岁晚来相寻。'},
    {t:'赠别晋三处士',a:'高适〔唐代〕',c:'有人家住清河源，渡河问我游梁园。手持道经注已毕，\n心知内篇口不言。卢门十年见秋草，此心惆怅谁能道。\n知己从来不易知，慕君为人与君好。别时九月桑叶疏，\n出门千里无行车。爱君且欲君先达，今上求贤早上书。'},
    {t:'赠别李次翁',a:'黄庭坚〔宋代〕',c:'利欲薰心，随人翕张。\n国好骏马，尽为王良。\n不有德人，俗无津梁。\n德人天游，秋月寒江。\n映彻万物，玲珑八窗。\n于爱欲泥，如莲生塘。\n处水超然，出泥而香。\n孔窍穿穴，明冰其相。\n维乃根华，其本含光。\n大雅次翁，用心不忘。\n日问月学，旅人念乡。\n能如斯莲，汔可小康。\n在俗行李，密密堂堂。\n观物慈哀，涖民爱庄。\n成功万年，付之面墙。\n草衣石质，与世低昂。'},
    {t:'赠别孟郊',a:'张籍〔唐代〕',c:'历历天上星，沉沉水中萍。幸当清秋夜，流影及微形。\n君生衰俗间，立身如礼经。纯诚发新文，独有金石声。\n才名振京国，归省东南行。停车楚城下，顾我不念程。\n宝镜曾坠水，不磨岂自明。苦节居贫贱，所知赖友生。\n欢会方别离，戚戚忧虑并。安得在一方，终老无送迎。'},
    {t:'赠别前蔚州契苾使君',a:'李商隐〔唐代〕',c:'何年部落到阴陵，奕世勤王国骑称。\n夜卷牙旗千帐雪，朝飞羽骑一河冰。\n蕃儿襁负来青冢，狄女壶浆出白登。\n日晚鸊鹈泉畔猎，路人遥识郅都鹰。'},
    {t:'赠别沈四逸人',a:'高适〔唐代〕',c:'沈侯未可测，其况信浮沉。十载常独坐，几人知此心。\n乘舟蹈沧海，买剑投黄金。世务不足烦，有田西山岑。\n我来遇知己，遂得开清襟。何意阃阈间，沛然江海深。\n疾风扫秋树，濮上多鸣砧。耿耿尊酒前，联雁飞愁音。\n平生重离别，感激对孤琴。'},
    {t:'赠别宣州崔群相公',a:'杜牧〔唐代〕',c:'衰散相逢洛水边，却思同在紫薇天。\n尽将舟楫板桥去，早晚归来更济川。'},
    {t:'赠别殷山人说易后归幽墅',a:'孟郊〔唐代〕',c:'夫子说天地，若与灵龟言。幽幽人不知，一一予所敦。\n秋月吐白夜，凉风韵清源。旁通忽已远，神感寂不喧。\n一悟袪万结，夕怀倾朝烦。旅輈无停波，别马嘶去辕。\n殷勤荒草士，会有知己论。'},
    {t:'赠别约师',a:'刘禹锡〔唐代〕',c:'师逢吴兴守，相伴住禅扃。春雨同栽树，秋灯对讲经。\n庐山曾结社，桂水远扬舲。话旧还惆怅，天南望柳星。'},
    {t:'赠别郑炼赴襄阳',a:'杜甫〔唐代〕',c:'戎马交驰际，柴门老病身。\n把君诗过日，念此别惊神。\n地阔峨眉晚，天高岘首春。\n为于耆旧内，试觅姓庞人。'},
    {t:'赠曾子固',a:'王安石〔宋代〕',c:'曾子文章众无有，水之江汉星之斗。\n挟才乘气不媚柔，群儿谤伤均一口。\n吾语群儿勿谤伤，岂有曾子终皇皇。\n借令不幸贱且死，後日犹为班与扬。'},
    {t:'赠拆字嗅衣相士',a:'文天祥〔宋代〕',c:'阿英薰蒸透肌理，不洁未蒙好蜋子。\n芙蓉浪中蔷薇水，苏合蜣蜋忘彼己。\n马嵬新袜钓新月，腥臊千年天地裂。\n是间曾著鼻孔麽，梅香窦臭无如何。'},
    {t:'赠常熟贺公叔隐士',a:'周邦彦〔宋代〕',c:'怀珠崖后枯，韫玉山有辉。\n隐翳后言德，人自知神奇。\n公步季贞后，后为世纲縻。\n浮沉里闾间，身无道同违。\n弓旌搜俊良，圭衡略无遗。\n难偕集雍鹭，宁作曳尾龟。\n慈仁盖天性，惠泽施鳏嫠。\n倒囷食流冗，死葬病有医。\n人今泣遗爱，若见岘首碑。\n肯构有材子，修德亦庶几。\n高风自兹显，岂病知者希。'},
    {t:'赠陈师道',a:'黄庭坚〔宋代〕',c:'陈侯学诗如学道，又似秋虫噫寒草。\n日晏肠鸣不俛眉，得意古人便忘老。\n君不见向来河伯负两河，观海乃知身一蠡。\n旅床争席方归去，秋水黏天不自多。\n春风吹园动花鸟，霜月入户寒皎皎。\n十度欲言九度休，万人丛中一人晓。\n贫无置锥人所怜，穷到无锥不属天。\n呻吟成声可管弦，能与不能安足言。'},
    {t:'赠成都六祖沙弥文信颂',a:'黄庭坚〔宋代〕',c:'尘是文信，界是沙弥。\n积尘成世界，析界作微尘。\n界喻人天果，尘为有漏因。\n尘因因不实，界果果非真。\n因果皆如幻，堂堂出世人。'},
    {t:'赠楚云上人',a:'温庭筠〔唐代〕',c:'松根满苔石，尽日闭禅关。有伴年年月，无家处处山。\n烟波五湖远，瓶屦一身闲。岳寺蕙兰晚，几时幽鸟还。'},
    {t:'赠从弟司库员外絿',a:'王维〔唐代〕',c:'少年识事浅，强学干名利。\n徒闻跃马年，苦无出人智。\n即事岂徒言，累官非不试。\n既寡遂性欢，恐招负时累。\n清冬见远山，积雪凝苍翠。\n浩然出东林，发我遗世意。\n惠连素清赏，夙语尘外事。\n欲缓携手期，流年一何驶。'},
    {t:'赠从兄襄阳少府皓',a:'李白〔唐代〕',c:'结发未识事，所交尽豪雄。\n却秦不受赏，击晋宁为功。\n托身白刃里，杀人红尘中。\n当朝揖高义，举世称英雄。\n小节岂足言，退耕舂陵东。\n归来无产业，生事如转蓬。\n一朝乌裘敝，百镒黄金空。\n弹剑徒激昂，出门悲路穷。\n吾兄青云士，然诺闻诸公。\n所以陈片言，片言贵情通。\n棣华倘不接，甘与秋草同。'},
    {t:'赠道士参寥',a:'孟浩然〔唐代〕',c:'蜀琴久不弄，玉匣细尘生。丝脆弦将断，金徽色尚荣。\n知音徒自惜，聋俗本相轻。不遇钟期听，谁知鸾凤声。'},
    {t:'赠都下隐者',a:'范仲淹〔宋代〕',c:'梅福隐市门，严平居卜肆。\n乃知人仙徒，非必烟霞地。\n异哉西山人，逍遥京洛尘。\n门多长者车，察然如有人。\n轩皇万馀载，此术了然在。\n精意洞五行，飞名落四海。\n结舍拟沧洲，东池接御沟。\n兰芳披幽径，琴樽在小舟。\n清夜泛月华，宛是江湖游。\n他日上云去，兹为黄鹤楼。'},
    {t:'赠杜二拾遗',a:'高适〔唐代〕',c:'传道招提客，诗书自讨论。佛香时入院，僧饭屡过门。\n听法还应难，寻经剩欲翻。草玄今已毕，此外复何言。'},
    {t:'赠方秀才',a:'范仲淹〔宋代〕',c:'高尚继先君，岩居与俗分。\n有泉皆漱石，无地不生云。\n邻里多垂钓，儿孙半属文。\n幽兰在深处，终日自清芬。'},
    {t:'赠房卢氏琯',a:'王维〔唐代〕',c:'达人无不可，忘己爱苍生。\n岂复归十室，弦歌在两楹。\n浮人日已归，但坐事农耕。\n桑榆郁相望，邑寒多鸡鸣。\n秋山一何净，苍翠临寒城。\n视事兼偃卧，对书不簪缨。\n萧条人吏疏，鸟雀下空庭。\n鄙夫心所尚，晚节异平生。\n将从海岳居，守静解天刑。\n或可累安邑，茅茨君试营。'},
    {t:'赠高子勉四首',a:'黄庭坚〔宋代〕',c:'妙在和光同尘，事须钩深入神。\n听他下虎口著，我不为牛後人。'},
    {t:'赠歌妓二首',a:'李商隐〔唐代〕',c:'水精如意玉连环，下蔡城危莫破颜。\n红绽樱桃含白雪，断肠声里唱阳关。\n白日相思可奈何，严城清夜断经过。\n只知解道春来瘦，不道春来独自多。'},
    {t:'赠龚豫轩数术',a:'文天祥〔宋代〕',c:'挟策考休微，巫甘迈何追。\n君亦布灵草，乃复探其微。\n载观河洛书，今也休明时。\n天高凤鸟翔，击拊遨以嬉。'},
    {t:'赠郭季鹰',a:'李白〔唐代〕',c:'河东郭有道，于世若浮云。\n盛德无我位，清光独映君。\n耻将鸡并食，长与凤为群。\n一击九千仞，相期凌紫氛。'},
    {t:'赠郭将军',a:'李白〔唐代〕',c:'将军少年出武威，入掌银台护紫微。\n平明拂剑朝天去，薄暮垂鞭醉酒归。\n爱子临风吹玉笛，美人向月舞罗衣。\n畴昔雄豪如梦里，相逢且欲醉春晖。'},
    {t:'赠海东僧',a:'张籍〔唐代〕',c:'别家行万里，自说过扶馀。学得中州语，能为外国书。\n与医收海藻，持咒取龙鱼。更问同来伴，天台几处居。'},
    {t:'赠韩郎中愈',a:'孟郊〔唐代〕',c:'何以定交契，赠君高山石。何以保贞坚，赠君青松色。\n贫居过此外，无可相彩饰。闻君硕鼠诗，吟之泪空滴。\n硕鼠既穿墉，又啮机上丝。穿墉有闲土，啮丝无馀衣。\n朝吟枯桑柘，暮泣空杼机。岂是无巧妙，丝断将何施。\n众人尚肥华，志士多饥羸。愿君保此节，天意当察微。\n前日远别离，今日生白发。欲知万里情，晓卧半床月。\n常恐百虫秋，使我芳草歇。'},
    {t:'赠韩郎中愈其三',a:'孟郊〔唐代〕',c:'前日远别离，今日生白发。欲知万里情，晓卧半床月。\n常恐百虫秋，使我芳草歇。'},
    {t:'赠何七判官昌浩',a:'李白〔唐代〕',c:'有时忽惆怅，匡坐至夜分。\n平明空啸咤，思欲解世纷。\n心随长风去，吹散万里云。\n羞作济南生，九十诵古文。\n不然拂剑起，沙漠收奇勋。\n老死阡陌间，何因扬清芬。\n夫子今管乐，英才冠三军。\n终与同出处，岂将沮溺群？'},
    {t:'赠荷花',a:'李商隐〔唐代〕',c:'世间花叶不相伦，花入金盆叶作尘。\n惟有绿荷红菡萏，卷舒开合任天真。\n此花此叶常相映，翠减红衰愁杀人。'},
    {t:'赠花卿',a:'杜甫〔唐代〕',c:'锦城丝管日纷纷，半入江风半入云。\n此曲只应天上有，人间能得几回闻。'},
    {t:'赠华严院僧',a:'张籍〔唐代〕',c:'一身依止荒闲院，烛耀窗中有宿烟。\n遍礼华严经里字，不曾行到寺门前。'},
    {t:'赠黄山胡公求白鹇',a:'李白〔唐代〕',c:'闻黄山胡公有双白鹇，盖是家鸡所伏，自小驯狎，了无惊猜，以其名呼之，皆就掌取食。然此鸟耿介，尤难畜之，余平生酷好，竟莫能致。而胡公辍赠于我，唯求一诗。闻之欣然，适会宿意，援笔三叫，文不加点以赠之。\n请以双白璧，买君双白鹇。\n白鹇白如锦，白雪耻容颜。\n照影玉潭里，刷毛琪树间。\n夜栖寒月静，朝步落花闲。\n我愿得此鸟，玩之坐碧山。\n胡公能辍赠，笼寄野人还。'},
    {t:'赠会稽道士',a:'晏殊〔宋代〕',c:'藐姑容化三阴馆，句漏砂封六采泥。\n五练夜穷青玉枕，七明晨采碧云梯。\n冠霞高把浮丘袂，握体深藏鬼谷奚。\n知有山西驻龄药，何妨相赠一刀圭，'},
    {t:'赠箕山僧',a:'张籍〔唐代〕',c:'久住空林下，长斋耳目清。蒲团借客坐，石磹甃人行。\n似鹤难知性，因山强号名。时闻衣袖里，暗掐念珠声。'},
    {t:'赠剑客李园联句',a:'孟郊〔唐代〕',c:'天地有灵术，得之者惟君。——孟郊\n筑炉地区外，积火烧氛氲。——韩愈\n照海铄幽怪，满空歊异氛。——孟郊\n山磨电奕奕，水淬龙蝹蝹。——韩愈\n太一装以宝，列仙篆其文。——孟郊\n可用慑百神，岂惟壮三军。——韩愈\n有时幽匣吟，忽似深潭闻。——孟郊\n风胡久已死，此剑将谁分。——韩愈\n行当献天子，然后致殊勋。——孟郊\n岂如丰城下，空有斗间云。——韩愈'},
    {t:'赠鉴湖相士',a:'文天祥〔宋代〕',c:'瘦竹凌风弄碧漪，山光云影共熹微。\n月黄昏里疏枝外，认取半天孤鹤飞。'},
    {t:'赠江华长老',a:'柳宗元〔唐代〕',c:'老僧道机熟，默语心皆寂。\n去岁者舂陵，沿流此投迹。\n室空无侍者，巾屦唯挂壁。\n一饭不愿馀，跏趺便终夕。\n风窗疏竹响，露井寒松滴。\n偶地即安居，满庭芳草积。'},
    {t:'赠镜斋徐相士',a:'文天祥〔宋代〕',c:'邹忌不如徐公美，引镜自窥得真是。\n门下食客才有求，昏昏便与妻妾比。\n徐家耳孙却不然，自名一镜京师市。\n世人无用看青铜，此君双眼明秋水。\n君以无求游公卿，勿令此镜生瑕滓。\n碟子大面何难知，从今光照二百里。'},
    {t:'赠酒泉韩太守',a:'岑参〔唐代〕',c:'太守有能政，遥闻如古人。俸钱玉供客，家计常清贫。\n酒泉西望玉关道，千山万碛皆白草。辞君走马归长安，\n忆君倏忽令人老。'},
    {t:'赠旧识',a:'韦应物〔唐代〕',c:'少年游太学，负气蔑诸生。\n蹉跎三十载，今日海隅行。'},
    {t:'赠考功卢郎中',a:'温庭筠〔唐代〕',c:'白首方辞满，荆扉对渚田。雪中无陋巷，醉后似当年。\n一笈负山药，两瓶携涧泉。夜来风浪起，何处认渔船。'},
    {t:'赠孔尚书',a:'张籍〔唐代〕',c:'能将直道历荣班，事著元和实录间。三表自陈辞北阙，\n一家相送入南山。买来侍女教人嫁，赐得朝衣在箧闲。\n宅近青山高静处，时归林下暂开关。'},
    {t:'赠乐天',a:'刘禹锡〔唐代〕',c:'一别旧游尽，相逢俱涕零。\n在人虽晚达，于树似冬青。\n痛饮连宵醉，狂吟满坐听。\n终期抛印绶，共占少微星。'},
    {t:'赠乐天',a:'元稹〔唐代〕',c:'等闲相见销长日，也有闲时更学琴。\n不是眼前无外物，不关心事不经心。'},
    {t:'赠乐轩彭善之',a:'文天祥〔宋代〕',c:'吾家小黄溪，其间石甚巨。\n可写归来辞，可刻盘谷序。\n晋唐文章手，谁敢以自负。\n异时此重来，烦君作玉筹。'},
    {t:'赠李白',a:'杜甫〔唐代〕',c:'二年客东都，所历厌机巧。\n野人对膻腥，蔬食常不饱。\n岂无青精饭，使我颜色好。\n苦乏大药资，山林迹如扫。\n李侯金闺彦，脱身事幽讨。\n亦有梁宋游，方期拾瑶草。'},
    {t:'赠李儋侍御',a:'韦应物〔唐代〕',c:'风光山郡少，来看广陵春。残花犹待客，莫问意中人。'},
    {t:'赠李观',a:'孟郊〔唐代〕',c:'谁言形影亲，灯灭影去身。\n谁言客水欢，水竭客枯鳞。\n昔为同恨客，今为独笑人。\n舍予在泥辙，飘再上云津。\n卧木易成蠹，弃花难再春。\n何言对芳景，愁望极萧晨。\n埋剑谁识气，匣弦日生尘。\n愿君语高风，为余问苍旻。'},
    {t:'赠李颀',a:'王维〔唐代〕',c:'闻君饵丹砂，甚有好颜色。\n不知从今去，几时生羽翼。\n王母翳华芝，望尔昆仑侧。\n文螭从赤豹，万里方一息。\n悲哉世上人，甘此膻腥食。'},
    {t:'赠李侍御',a:'王昌龄〔唐代〕',c:'青冥孤云去，终当暮归山。\n志士杖苦节，何时见龙颜。'},
    {t:'赠李司空妓',a:'刘禹锡〔唐代〕',c:'高髻云鬟宫样妆，春风一曲杜韦娘。\n司空见惯浑闲事，断尽苏州刺史肠。'},
    {t:'赠李司议',a:'张籍〔唐代〕',c:'汉庭谁问投荒客，十载天南着白衣。\n秋草茫茫恶谿路，岭头遥送北人稀。'},
    {t:'赠李秀才·是上公孙子',a:'杜牧〔唐代〕',c:'骨清年少眼如冰，凤羽参差五色层。\n天上麒麟时一下，人间不独有徐陵。'},
    {t:'赠李阳孙',a:'晏殊〔宋代〕',c:'不忍与君别，怜君仁义人。\n三年官满后，依旧一家贫。'},
    {t:'赠澧阳韦明府',a:'张九龄〔唐代〕',c:'君有百炼刃，堪断七重犀。谁开太阿匣，持割武城鸡。\n竟与尚书佩，遥应天子提。何时遇操宰，当使玉如泥。'},
    {t:'赠猎骑',a:'杜牧〔唐代〕',c:'已落双雕血尚新，鸣鞭走马又翻身。\n凭君莫射南来雁，恐有家书寄远人。'},
    {t:'赠林碧鉴相士',a:'文天祥〔宋代〕',c:'咸阳宫中四尺镜，照人五臟何炯炯。\n桑田沧海千馀年，百炼依然化为矿。\n君从何处得此物，铸就双瞳敌秋月。\n向来照心今照形，不事澜翻三寸舌。\n远冲风雪肯我过，看来犹未深知我。\n我方簑笠立钓矶，万事浮云都勘破。\n噫嘻吁，只今神目鬼眼纷道途，暗中许负应卢胡。\n试问何如林家老碧鉴，不知天津桥上复有龙钟无。'},
    {t:'赠令狐博士',a:'张籍〔唐代〕',c:'头白新年六十馀，近闻生计转安虚。久为博士谁能识，\n自到长安赁舍居。骑马出随寻寺客，呼儿散写乞钱书。\n古来贤哲皆如此，应是才高与众疏。'},
    {t:'赠刘矮跛相士',a:'文天祥〔宋代〕',c:'炼石为形，铿金为音。\n世方好圆，善守方心。\n阴阳絪緼，人一气质。\n善恶之微，证于声色。\n意所欲发，骯吾不知。\n彼美子刘，洞其先几。\n骯脏难合，今世道病。\n如子所言，生禀已定。\n戆夫勇士，往往一偏。\n以视妾妇，岂不犹贤。\n洪范得三，二曰刚克。\n会其归其，好是正直。\n学问工夫，气质用微。\n汝能观形，安知其馀。\n子术已定，吾情已成。\n子执子术，吾安吾情。'},
    {t:'赠刘采春',a:'元稹〔唐代〕',c:'新妆巧样画双蛾，谩裹常州透额罗。\n正面偷匀光滑笏，缓行轻踏破纹波。\n言辞雅措风流足，举止低回秀媚多。\n更有恼人肠断处，选词能唱望夫歌。'},
    {t:'赠刘景文',a:'苏轼〔宋代〕',c:'荷尽已无擎雨盖，菊残犹有傲霜枝。\n一年好景君须记，最是橙黄橘绿时。'},
    {t:'赠刘蓝田',a:'王维〔唐代〕',c:'篱间犬迎吠，出屋候荆扉。\n岁晏输井税，山村人夜归。\n晚田始家食，余布成我衣。\n讵肯无公事，烦君问是非。'},
    {t:'赠刘师服',a:'韩愈〔唐代〕',c:'羡君齿牙牢且洁，大肉硬饼如馀截。我今呀豁落者多，\n所存十馀皆兀臲。匙抄烂饭稳送之，合望软嚼如牛呞。\n妻儿恐我生怅望，盘中不饤栗与梨。只今年才四十五，\n后日悬知渐莽卤。朱颜皓颈讶莫亲，此外诸馀谁更数。\n忆昔太公仕进初，望含两齿无赢馀。虞翻十三比岂少，\n遂自惋恨形于书。丈夫命存百无害，谁能点检形骸外。\n巨缗东钓倘可期，与子共饱鲸鱼脍。'},
    {t:'赠刘使君景文',a:'秦观〔宋代〕',c:'落落衣冠八尺雄，鱼符新赐大河东。\n穰苴兵法申司马，曹植诗原出国风。\n拈笔古心生篆刻，引觞夹气上云空。\n石渠病客君应笑，手校黄书两鬓蓬。'},
    {t:'赠刘司户蕡',a:'李商隐〔唐代〕',c:'江风扬浪动云根，重碇危樯白日昏。\n已断燕鸿初起势，更惊骚客后归魂。\n汉廷急诏谁先入，楚路高歌自欲翻。\n万里相逢欢复泣，凤巢西隔九重门。'},
    {t:'赠柳',a:'李商隐〔唐代〕',c:'章台从掩映，郢路更参差。\n见说风流极，来当婀娜时。\n桥回行欲断，堤远意相随。\n忍放花如雪，青楼扑酒旗。'},
    {t:'赠卢嵩',a:'韦应物〔唐代〕',c:'百川注东海，东海无虚盈。泥滓流能浊，澄波非益清。\n恬然自安流，日照万里晴。云物流隐象，三山共分明。\n奈何疾风怒，忽若砥柱倾。海水虽无心，洪涛亦相惊。\n怒号在倏忽，谁识变化情。'},
    {t:'赠闾丘处士',a:'李白〔唐代〕',c:'贤人有素业，乃在沙塘陂。\n竹影扫秋月，荷衣落古池。\n闲读山海经，散帙卧遥帷。\n且耽田家乐，遂旷林中期。\n野酌劝芳酒，园蔬烹露葵。\n如能树桃李，为我结茅茨。'},
    {t:'赠吕二校书',a:'元稹〔唐代〕',c:'同年同拜校书郎，触处潜行烂熳狂。\n共占花园争赵辟，竞添钱贯定秋娘。\n七年浮世皆经眼，八月闲宵忽并床。\n语到欲明欢又泣，傍人相笑两相伤。'},
    {t:'赠猫三首·其二',a:'陆游〔宋代〕',c:'裹盐迎得小狸奴，尽护山房万卷书。\n惭愧家贫策勋薄，寒无毡坐食无鱼。'},
    {t:'赠猫三首·其三',a:'陆游〔宋代〕',c:'执鼠无功元不劾，一箪鱼饭以时来。\n看君终日常安卧，何事纷纷去又回？'},
    {t:'赠猫三首·其一',a:'陆游〔宋代〕',c:'盐裹聘狸奴，常看戏座隅。\n时时醉薄荷，夜夜占氍毹。\n鼠穴功方列，鱼餐赏岂无。\n仍当立名字，唤作小於菟。'},
    {t:'赠茅山张道者',a:'范仲淹〔宋代〕',c:'有客平生爱白云，无端年老尚红尘。\n祇应金简名犹在，得见仙岩种玉人。'},
    {t:'赠梅处士',a:'张籍〔唐代〕',c:'早闻声价满京城，头白江湖放著情。讲易自传新注义，\n题诗不著旧官名。近移马迹山前住，多向牛头寺里行。\n天子如今议封禅，应将束帛请先生。'},
    {t:'赠孟浩然',a:'李白〔唐代〕',c:'吾爱孟夫子，风流天下闻。\n红颜弃轩冕，白首卧松云。\n醉月频中圣，迷花不事君。\n高山安可仰，徒此揖清芬。'},
    {t:'赠梦得',a:'白居易〔唐代〕',c:'前日君家饮，昨日王家宴。\n今日放我庐，三日三会面。\n当歌聊自放，对酒交相劝。\n为我尽一杯，与君发三愿。\n一愿世清平，二愿身强健。\n三愿临老头，数与君相见。'},
    {t:'赠墨林曹大崧',a:'文天祥〔宋代〕',c:'巍峨幼妇碑，伶俜七步诗。\n又得墨林墨淋漓，凑作曹家三绝奇。'},
    {t:'赠内',a:'白居易〔唐代〕',c:'生为同室亲，死为同穴尘。\n他人士相勉，而况我与君。\n黔娄固穷士，妻贤忘其贫。\n冀缺一农夫，妻爨俨如宾。\n陶潜不营生，翟氏自爨薪。\n梁鸿不肯仕，孟光甘布裙。\n君虽不读书，此事耳亦闻。\n至此千载后，传是何如人？\n人生未死间，不能忘其身。\n所须者衣食，不过饱与温。\n蔬食足充饥，何必膏粱珍？\n缯絮足御寒，何必锦绣文？\n君家有贻训，清白遗子孙。\n我亦贞苦士，与君新结婚。\n庶保贫与素，偕老同欣欣。'},
    {t:'赠内',a:'李白〔唐代〕',c:'三百六十日，日日醉如泥。\n虽为李白妇，何异太常妻。'},
    {t:'赠内臣孙可久',a:'柳永〔宋代〕',c:'故侯幽隐直城东，草树扶疏一亩宫。\n曾珥貂珰为近侍，却纡絛褐作间翁。\n高吟拥鼻诗怀壮，雅论持衡道气充。\n厌尽繁华天上乐，始将踪迹学冥鸿。'},
    {t:'赠农人',a:'孟郊〔唐代〕',c:'劝尔勤耕田，盈尔仓中粟。劝尔伐桑株，减尔身上服。\n清霜一委地，万草色不绿。狂飙一入林，万叶不著木。\n青春如不耕，何以自结束。'},
    {t:'赠女冠畅师',a:'秦观〔宋代〕',c:'瞳人剪水腰如束，一幅乌纱裹寒玉。\n飘然自有姑射姿，回看粉黛皆尘俗。\n雾阁云窗人莫窥，门前车马任东西。\n礼罢晓坛春日静，落红满地乳鸦啼。'},
    {t:'赠裴迪',a:'王维〔唐代〕',c:'不相见，不相见来久。\n日日泉水头，常忆同携手。\n携手本同心，复叹忽分襟。\n相忆今如此，相思深不深。'},
    {t:'赠裴旻将军',a:'王维〔唐代〕',c:'腰间宝剑七星文，臂上雕弓百战勋。\n见说云中擒黠虏，始知天上有将军。'},
    {t:'赠裴十迪',a:'王维〔唐代〕',c:'风景日夕佳，与君赋新诗。\n澹然望远空，如意方支颐。\n春风动百草，兰蕙生我篱。\n暧暧日暖闺，田家来致词。\n欣欣春还皋，淡淡水生陂。\n桃李虽未开，荑萼满芳枝。\n请君理还策，敢告将农时。'},
    {t:'赠裴十四',a:'李白〔唐代〕',c:'朝见裴叔则，朗如行玉山。\n黄河落天走东海，万里写入胸怀间。\n身骑白鼋不敢度，金高南山买君顾。\n徘徊六合无相知，飘若浮云且西去！'},
    {t:'赠彭别峰太极数',a:'文天祥〔宋代〕',c:'手把先天已后书，当来一画本全无。\n白云山下泠泠水，自在人间太极图。'},
    {t:'赠辟谷者',a:'张籍〔唐代〕',c:'学得餐霞法，逢人与小还。身轻曾试鹤，力弱未离山。\n无食犬犹在，不耕牛自闲。朝朝空漱水，叩齿草堂间。'},
    {t:'赠萍乡道士',a:'文天祥〔宋代〕',c:'道上观行人，半似重相见。\n古云性相近，性岂不如面。\n万形本一性，万心方一殊。\n世固难绝圣，亦恐难绝愚。'},
    {t:'赠棋者',a:'范仲淹〔宋代〕',c:'何处逢神仙，传此棋上旨。\n静持舒杀权，密照安危理。\n接胜如云舒，御敌如山止。\n突围秦师震，诸背皆披靡。\n入险汉钭危，奇兵翻背水。\n势应不可隳，关河常表里。\n南轩春日长，国手相得喜。\n泰山不碍目，疾雷不经耳。\n一子贵千金，一路重千里。\n精思入于神。变化胡能拟。\n成败系之人，吾当著棋史。'},
    {t:'赠钱征君少阳',a:'李白〔唐代〕',c:'白玉一杯酒，绿杨三月时。\n春风余几日，两鬓各成丝。\n秉烛唯须饮，投竿也未迟。\n如逢渭水猎，犹可帝王师。'},
    {t:'赠黔府王中丞楚',a:'孟郊〔唐代〕',c:'旧说天下山，半在黔中青。又闻天下泉，半落黔中鸣。\n山水千万绕，中有君子行。儒风一以扇，污俗心皆平。\n我愿中国春，化从异方生。昔为阴草毒，今为阳华英。\n嘉实缀绿蔓，凉湍泻清声。逍遥物景胜，视听空旷并。\n困骥犹在辕，沉珠尚隐精。路遐莫及眄，泥污日已盈。\n岁晏将何从，落叶甘自轻。'},
    {t:'赠黔南贾使君',a:'黄庭坚〔宋代〕',c:'绿发将军领百蛮，横戈得句一开颜。\n少年圯下传书客，老去崆峒问道山。\n春入莺花空自笑，秋成梨枣为谁攀。\n何时定作风光主，待得征西鼓吹还。'},
    {t:'赠乔侍郎',a:'陈子昂〔唐代〕',c:'汉廷荣巧宦，云阁薄边功。\n可怜骢马使，白首为谁雄？'},
    {t:'赠任道人',a:'张籍〔唐代〕',c:'长安多病无生计，药铺医人乱索钱。\n欲得定知身上事，凭君为算小行年。'},
    {t:'赠任华',a:'高适〔唐代〕',c:'丈夫结交须结贫，贫者结交交始亲。世人不解结交者，唯重黄金不重人。\n黄金虽多有尽时，结交一成无竭期。君不见管仲与鲍叔，至今留名名不移。'},
    {t:'赠任懒',a:'张籍〔唐代〕',c:'未肯求科第，深坊且隐居。胜游寻野客，高卧看兵书。\n点药医闲马，分泉灌远蔬。汉庭无得意，谁拟荐相如。'},
    {t:'赠日本僧智藏',a:'刘禹锡〔唐代〕',c:'浮杯万里过沧溟，遍礼名山适性灵。\n深夜降龙潭水黑，新秋放鹤野田青。\n身无彼我那怀土，心会真如不读经。\n为问中华学道者，几人雄猛得宁馨。'},
    {t:'赠融上人',a:'皎然〔唐代〕',c:'常爱西林寺，池中月出时。芭蕉一片叶，书取寄吾师。'},
    {t:'赠柔之',a:'元稹〔唐代〕',c:'穷冬到乡国，正岁别京华。自恨风尘眼，常看远地花。\n碧幢还照曜，红粉莫咨嗟。嫁得浮云婿，相随即是家。'},
    {t:'赠僧云栖',a:'温庭筠〔唐代〕',c:'麈尾与筇杖，几年离石坛。梵馀林雪厚，棋罢岳钟残。\n开卷喜先悟，漱瓶知早寒。衡阳寺前雁，今日到长安。'},
    {t:'赠上封诸老',a:'朱熹〔宋代〕',c:'夜宿上封寺，翛然尘虑清。月明残雪里，泉溜隔窗声。\n楮衲今如许，绨袍那复情。炉红虚室暖，聊得话平生。'},
    {t:'赠少年',a:'温庭筠〔唐代〕',c:'江海相逢客恨多，秋风叶下洞庭波。\n酒酣夜别淮阴市，月照高楼一曲歌。'},
    {t:'赠神目相士',a:'文天祥〔宋代〕',c:'道茂数遁甲，长房得役鬼。\n风鉴麻衣仙，地理青乌子。\n择术患不精。\n精义本无二。\n奇哉梦笔生，熊鱼掩前氏。'},
    {t:'赠史昭',a:'王昌龄〔唐代〕',c:'东林月未升，廓落星与汉。是夕浦始来，斋中起长叹。\n怀哉望南浦，眇然夜将半。但有秋水声，愁使心神乱。\n握中何为赠，瑶草已衰散。海鳞未化时，各在天一岸。'},
    {t:'赠蜀府将',a:'温庭筠〔唐代〕',c:'蛮入成都，频著功劳。\n十年分散已关秋，万事皆随锦水流。\n志气已曾明汉节，功名犹自滞吴钩。\n雕边认箭寒云重，马上听笳塞草愁。\n今日逢君倍惆怅，灌婴韩信尽封侯。'},
    {t:'赠双文',a:'元稹〔唐代〕',c:'艳极翻含怨，怜多转自娇。有时还暂笑，闲坐爱无憀。\n晓月行看堕，春酥见欲消。何因肯垂手，不敢望回腰。'},
    {t:'赠司勋杜十三员外',a:'李商隐〔唐代〕',c:'杜牧司勋字牧之，清秋一首杜秋诗。\n前身应是梁江总，名总还曾字总持。\n心铁已从干镆利，鬓丝休叹雪霜垂。\n汉江远吊西江水，羊祜韦丹尽有碑。'},
    {t:'赠苏子瞻',a:'秦观〔宋代〕',c:'叹息苏子瞻，声名绝後先。\n衣冠百盛事，兄弟固多贤。\n感慨诗三百，流离路八千。\n直心羞媚灶，忠自欲回天。\n缧绁终非罪，江湖秪自怜。\n饥寒常并日，疾病更连年。\n明主无终弃，西州稍内迁。\n奏言深意苦，感涕内人百。\n前席须宣室，非熊起渭川。\n君臣悦相遇，愿上角招篇。'},
    {t:'赠田叟',a:'李商隐〔唐代〕',c:'荷蓧衰翁似有情，相逢携手绕村行。\n烧畬晓映远山色，伐树暝传深谷声。\n鸥鸟忘机翻浃洽，交亲得路昧平生。\n抚躬道地诚感激，在野无贤心自惊。'},
    {t:'赠外孙',a:'王安石〔宋代〕',c:'南山新长凤凰雏，眉目分明画不如。\n年小从他爱梨栗，长成须读五车书。'},
    {t:'赠万年陆郎中',a:'孟郊〔唐代〕',c:'天子忧剧县，寄深华省郎。纷纷案响珮，蛰蛰剑开霜。\n旧事笑堆案，新声唯雅章。谁言百里才，终作横天梁。\n江鸿耻承眷，云津未能翔。徘徊尘俗中，短毳无辉光。'},
    {t:'赠汪伦',a:'李白〔唐代〕',c:'李白乘舟将欲行，忽闻岸上踏歌声。\n桃花潭水深千尺，不及汪伦送我情。'},
    {t:'赠王建',a:'张籍〔唐代〕',c:'白君去后交游少，东野亡来箧笥贫。\n赖有白头王建在，眼前犹见咏诗人。'},
    {t:'赠王九',a:'孟浩然〔唐代〕',c:'日暮田家远，山中勿久淹。\n归人须早去，稚子望陶潜。'},
    {t:'赠王秘书',a:'张籍〔唐代〕',c:'早在山东声价远，曾将顺策佐嫖姚。赋来诗句无闲语，\n老去官班未在朝。身屈只闻词客说，家贫多见野僧招。\n独从书阁归时晚，春水渠边看柳条。'},
    {t:'赠王判官时余归隐居庐山屏风叠',a:'李白〔唐代〕',c:'昔别黄鹤楼，蹉跎淮海秋。\n俱飘零落叶，各散洞庭流。\n中年不相见，蹭蹬游吴越。\n何处我思君？天台绿萝月。\n会稽风月好，却绕剡溪回。\n云山海上出，人物镜中来。\n一度浙江北，十年醉楚台。\n荆门倒屈宋，梁苑倾邹枚。\n苦笑我夸诞，知音安在哉？\n大盗割鸿沟，如风扫秋叶。\n吾非济代人，且隐屏风叠。\n中夜天中望，忆君思见君。\n明朝拂衣去，永与海鸥群。'},
    {t:'赠王侍御',a:'韦应物〔唐代〕',c:'心同野鹤与尘远，诗似冰壶见底清。\n府县同趋昨日事，升沉不改故人情。\n上阳秋晚萧萧雨，洛水寒来夜夜声。\n自叹犹为折腰吏，可怜骢马路傍行。'},
    {t:'赠韦穆十八',a:'王维〔唐代〕',c:'与君青眼客，共有白云心。\n不向东山去，日令春草深。'},
    {t:'赠韦侍御黄裳二首',a:'李白〔唐代〕',c:'太华生长松，亭亭凌霜雪。\n天与百尺高，岂为微飙折？\n桃李卖阳艳，路人行且迷。\n春光扫地尽，碧叶成黄泥。\n愿君学长松，慎勿作桃李。\n受屈不改心，然后知君子。\n见君乘骢马，知上太行道。\n此地果摧轮，全身以为宝。\n我如丰年玉，弃置秋田草。\n但勖冰壶心，无为叹衰老。'},
    {t:'赠韦早陆羽',a:'皎然〔唐代〕',c:'只将陶与谢，终日可忘情。不欲多相识，逢人懒道名。'},
    {t:'赠卫八处士',a:'杜甫〔唐代〕',c:'人生不相见，动如参与商。\n今夕复何夕，共此灯烛光。\n少壮能几时，鬓发各已苍。\n访旧半为鬼，惊呼热中肠。\n焉知二十载，重上君子堂。\n昔别君未婚，儿女忽成行。\n怡然敬父执，问我来何方。\n问答乃未已，驱儿罗酒浆。\n夜雨剪春韭，新炊间黄粱。\n主称会面难，一举累十觞。\n十觞亦不醉，感子故意长。\n明日隔山岳，世事两茫茫。'},
    {t:'赠乌程李明府伯宜、沈兵曹仲昌',a:'皎然〔唐代〕',c:'水国苦凋瘵，东皋岂遗黍。云阴涨尽时，日出常带雨。\n昨夜西溪涨，扁舟入檐庑。野人同鸟巢，暴客若蜂聚。\n岁晏涨斗粟，寄身欲何所。空羡鸾鹤姿，翩翩自轻举。'},
    {t:'赠吴官',a:'王维〔唐代〕',c:'长安客舍热如煮，无个茗糜难御暑。空摇白团其谛苦，\n欲向缥囊还归旅。江乡鲭鲊不寄来，秦人汤饼那堪许。\n不如侬家任挑达，草屩捞虾富春渚。'},
    {t:'赠吴秀才',a:'范仲淹〔宋代〕',c:'万户侯家几叶孙，弟兄红旆独乌巾。\n携琴又入庐山去，谁信朱门有逸人。'},
    {t:'赠西岳山人李冈',a:'岑参〔唐代〕',c:'君隐处，当一星。莲花峰头饭黄精，仙人掌上演丹经。\n鸟可到，人莫攀，隐来十年不下山。袖中短书谁为达，\n华阴道士卖药还。'},
    {t:'赠萧少府',a:'孟浩然〔唐代〕',c:'上德如流水，安仁道若山。闻君秉高节，而得奉清颜。\n鸿渐升仪羽，牛刀列下班。处腴能不润，居剧体常闲。\n去诈人无谄，除邪吏息奸。欲知清与洁，明月照澄湾。'},
    {t:'赠萧巽斋',a:'文天祥〔宋代〕',c:'未有大挠书，先有伏羲易。\n古人尚卜筮，今人信命术。\n八卦与五行，皆自河图出。\n易中元有命，道一万事毕。\n卦义六十四，萧君得其一。\n江湖旅琐琐，谈命以巽入。\n人情爱委曲，喉舌嫌棘棘。\n言言依忠孝，君平意未失。\n我生独骯脏，动取无妄疾。\n是有命流行，谁陨复谁诎。\n安能从儿女，朝夕谈昵昵。\n若卦有人买，不妨君卖直。'},
    {t:'赠新平少年',a:'李白〔唐代〕',c:'韩信在淮阴，少年相欺凌。\n屈体若无骨，壮心有所凭。\n一遭龙颜君，啸咤从此兴。\n千金答漂母，万古共嗟称。\n而我竟何为？寒苦坐相仍。\n长风入短袂，内手如怀冰。\n故友不相恤，新交宁见矜？\n摧残槛中虎，羁绁韝上鹰。\n何时腾风云，搏击申所能？'},
    {t:'赠徐中书望终南山歌',a:'王维〔唐代〕',c:'晚下兮紫微，怅尘事兮多违。\n驻马兮双树，望青山兮不归。'},
    {t:'赠宣州元处士',a:'杜牧〔唐代〕',c:'陵阳北郭隐，身世两忘者。\n蓬蒿三亩居，宽于一天下。\n樽酒对不酌，默与玄相话。\n人生自不足，爱叹遭逢寡。'},
    {t:'赠严仓曹乞推命录',a:'陈子昂〔唐代〕',c:'少学纵横术，游楚复游燕。栖遑长委命，富贵未知天。\n闻道沉冥客，青囊有秘篇。九宫探万象，三算极重玄。\n愿奉唐生诀，将知跃马年。非同墨翟问，空滞杀龙川。'},
    {t:'赠颜主簿',a:'皎然〔唐代〕',c:'汉家仪礼盛，名教出诸颜。更见尚书后，能文在子山。'},
    {t:'赠眼医婆罗门僧',a:'刘禹锡〔唐代〕',c:'三秋伤望眼，终日哭途穷。两目今先暗，中年似老翁。\n看朱渐成碧，羞日不禁风。师有金篦术，如何为发蒙。'},
    {t:'赠羊长史·并序',a:'陶渊明〔魏晋〕',c:'左军羊长史，衔使秦川，作此与之。\n愚生三季后，慨然念黄虞。\n得知千载上，正赖古人书。\n圣贤留余迹，事事在中都。\n岂忘游心目？关河不可逾。\n九域甫已一，逝将理舟舆。\n闻君当先迈，负疴不获俱。\n路若经商山，为我少踌躇。\n多谢绮与甪，精爽今何如？\n紫芝谁复采？深谷久应芜。\n驷马无贳患，贫贱有交娱。\n清谣结心曲，人乖运见疏。\n拥怀累代下，言尽意不舒。'},
    {t:'赠姚怤',a:'张籍〔唐代〕',c:'漏天日无光，泽土松不长。君今壮下位，志气安得扬。\n白发文思壮，才为国贤良。无人识高韵，荐名天子傍。\n况我愚朴姿，强趋利名场。远同干贵人，身举固难彰。\n昔逢汴水滨，今会习池阳。岂无再来期，顾恐非此方。\n愿为石中泉，不为瓦上霜。离别勿复道，所贵不相忘。'},
    {t:'赠姚合',a:'张籍〔唐代〕',c:'丹凤城门向晓开，千官相次入朝来。\n唯君独走冲尘土，下马桥边报直回。'},
    {t:'赠叶少卿',a:'范仲淹〔宋代〕',c:'退也天之道，东南事了人。\n风波抛旧路，花月伴闲身。\n湖外扁舟远，门中驷马新。\n心從今日泰，家似昔时贫。\n见子登西掖，携孙过北邻。\n白云高阁曙，渌水后池春。\n樽酒呼前辈，鑪香叩上真。\n祇应阴德在，八十富精神。'},
    {t:'赠医者邹放',a:'秦观〔宋代〕',c:'百工皆圣作，惟医有书传。\n绪余起人死，妙处实通天。\n邹子本淮海，弱龄加讨研。\n岐扁逢卷中，遂知百病先。\n往岁游京室，公侯纷荐延。\n国工不敢妒，遣儿求执鞭。\n晚弃本州役，青衫鬓萧然。\n临衢开大肆，旁午送金钱。\n嗣子颇不凡，文场早周旋。\n行期拾青紫，善积神所怜。'},
    {t:'赠译经僧',a:'韩愈〔唐代〕',c:'万里休言道路赊，有谁教汝度流沙。\n只今中国方多事，不用无端更乱华。'},
    {t:'赠隐者',a:'温庭筠〔唐代〕',c:'茅堂对薇蕨，炉暖一裘轻。醉后楚山梦，觉来春鸟声。\n采茶溪树绿，煮药石泉清。不问人间事，忘机过此生。'},
    {t:'赠余月心五首',a:'文天祥〔宋代〕',c:'我生之辰月宿斗，如何谤誉由箕口。\n月明只合醒眼看，斗亦何须挹浆酒。'},
    {t:'赠馀杭唐异处士',a:'范仲淹〔宋代〕',c:'名动公卿四十秋，相逢仍作旅人游。\n青山欲买难开口，白发思归易满头。\n厌入市廛如海燕，可堪云水属江鸥。\n故乡知己方都督，千树春浓种橘休。'},
    {t:'赠渔父',a:'杜牧〔唐代〕',c:'芦花深泽静垂纶，月夕烟朝几十春。\n自说孤舟寒水畔，不曾逢著独醒人。'},
    {t:'赠宇文中丞·本畅当诗',a:'王昌龄〔唐代〕',c:'仆本濩落人，辱当州郡使。量力颇及早，谢归今即已。\n萧萧若凌虚，衿带顷消靡。车服卒然来，涔阳作游子。\n郁郁寡开颜，默默独行李。忽逢平生友，一笑方在此。\n秋清宁风日，楚思浩云水。为语弋林者，冥冥鸿远矣。'},
    {t:'赠元发弟放言',a:'黄庭坚〔宋代〕',c:'亏功一篑，未成丘山。\n凿井九阶，狐次水泽。\n行百里者半九十，小狐汔济濡其尾。\n故曰时乎，时狐再来。\n终终始始，是谓君子。'},
    {t:'赠元九侍御文石枕以诗奖之',a:'刘禹锡〔唐代〕',c:'文章似锦气如虹，宜荐华簪绿殿中。\n纵使凉飙生旦夕，犹堪拂拭愈头风。'},
    {t:'赠元稹',a:'白居易〔唐代〕',c:'自我从宦游，七年在长安。\n所得唯元君，乃知定交难。\n岂无山上苗？径寸无岁寒。\n岂无要津水？咫尺有波澜。\n之子异于是，久要誓不谖。\n无波古井水，有节秋竹竿。\n一为同心友，三及芳岁阑。\n花下鞍马游，雪中杯酒欢。\n衡门相逢迎，不具带与冠。\n春风日高睡，秋月夜深看。\n不为同登科，不为同署官。\n所合在方寸，心源无异端。'},
    {t:'赠越僧岳云二首',a:'温庭筠〔唐代〕',c:'世机消已尽，巾屦亦飘然。一室故山月，满瓶秋涧泉。\n禅庵过微雪，乡寺隔寒烟。应共白莲客，相期松桂前。\n兰亭旧都讲，今日意如何。有树关深院，无尘到浅莎。\n僧居随处好，人事出门多。不及新春雁，年年镜水波。'},
    {t:'赠张道士',a:'皎然〔唐代〕',c:'玉京真子名太一，因服日华心如日。\n此心不许世人知，只向仙宫未曾出。'},
    {t:'赠张徐州莫辞酒',a:'韩愈〔唐代〕',c:'莫辞酒，此会固难同。请看女工机上帛，半作军人旗上红。\n莫辞酒，谁为君王之爪牙？春雷三月不作响，\n战士岂得来还家。'},
    {t:'赠张轩民赞善',a:'王安石〔宋代〕',c:'潮打空城寂寞回，百年多病独登台。\n谁人得似张公子，有底忙时不肯来。'},
    {t:'赠长沙公其二',a:'陶渊明〔魏晋〕',c:'於穆令族，允构斯堂。\n谐气冬暄，映怀圭璋。\n爰采春华，载警秋霜。\n我曰钦哉！实宗之光。'},
    {t:'赠长沙公其四',a:'陶渊明〔魏晋〕',c:'何以写心，此贻话言。\n进篑虽微，终焉为山。\n敬哉离人，临路凄然。\n款襟或辽，音问其先。'},
    {t:'赠长沙讚头陀',a:'刘禹锡〔唐代〕',c:'外道邪山千万重，真言一发尽摧峰。\n有时明月无人夜，独向昭潭制恶龙。'},
    {t:'赠赵将军',a:'张籍〔唐代〕',c:'当年胆略已纵横，每见妖星气不平。身贵早登龙尾道，\n功高自破鹿头城。寻常得对论边事，委曲承恩掌内兵。\n会取安西将报国，凌烟阁上大书名。'},
    {t:'赠赵六贞固',a:'陈子昂〔唐代〕',c:'回中峰火入。\n塞上追兵起。\n此时边朔寒。\n登陇思君子。\n东顾望汉京。\n南山云雾里。\n赤螭媚其彩。\n婉娈苍梧泉。\n昔者琅琊子。\n躬耕亦慨然。\n美人岂遐旷。\n之子乃前贤。\n良辰在何许。\n白日屡颓迁。\n道心固微密。\n神用无留连。\n舒可弥宇宙。\n揽之不盈拳。\n蓬莱久芜没。\n金石徒精坚。\n良宝委短褐。\n闲琴独蝉娟。'},
    {t:'赠赵六贞固二首',a:'陈子昂〔唐代〕',c:'回中烽火入，塞上追兵起。此时边朔寒，登陇思君子。\n东顾望汉京，南山云雾里。\n赤螭媚其彩，婉娈苍梧泉。昔者琅琊子，躬耕亦慨然。\n美人岂遐旷，之子乃前贤。良辰在何许，白日屡颓迁。\n道心固微密，神用无留连。舒可弥宇宙，揽之不盈拳。\n蓬莱久芜没，金石徒精坚。良宝委短褐，闲琴独婵娟。'},
    {t:'赠赵协律皙',a:'李商隐〔唐代〕',c:'俱识孙公与谢公，二年歌哭处还同。\n已叨邹马声华末，更共刘卢族望通。\n南省恩深宾馆在，东山事往妓楼空。\n不堪岁暮相逢地，我欲西征君又东。'},
    {t:'赠郑兵曹',a:'韩愈〔唐代〕',c:'尊酒相逢十载前，君为壮夫我少年。尊酒相逢十载后，\n我为壮夫君白首。我材与世不相当，戢鳞委翅无复望。\n当今贤俊皆周行，君何为乎亦遑遑。杯行到君莫停手，\n破除万事无过酒。'},
    {t:'赠郑谠处士',a:'李商隐〔唐代〕',c:'浪迹江湖白发新，浮云一片是吾身。\n寒归山观随棋局，暖入汀洲逐钓轮。\n越桂留烹张翰鲙，蜀姜供煮陆机莼。\n相逢一笑怜疏放，他日扁舟有故人。'},
    {t:'赠郑夫子鲂',a:'孟郊〔唐代〕',c:'天地入胸臆，吁嗟生风雷。\n文章得其微，物象由我裁。\n宋玉逞大句，李白飞狂才。\n苟非圣贤心，孰与造化该。\n勉矣郑夫子，骊珠今始胎。'},
    {t:'赠知音',a:'温庭筠〔唐代〕',c:'翠羽花冠碧树鸡，未明先向短墙啼。\n窗间谢女青蛾敛，门外萧郎白马嘶。\n星汉渐移庭竹影，露珠犹缀野花迷。\n景阳宫里钟初动，不语垂鞭上柳堤。'},
    {t:'赠终南兰若僧',a:'杜牧〔唐代〕',c:'北阙南山是故乡，两枝仙桂一时芳。\n休公都不知名姓，始觉禅门气味长。'},
    {t:'赠锺道士',a:'范仲淹〔宋代〕',c:'人间无复动机心，挂了儒冠岁已深。\n惟有诗家风味在，一坛松月伴秋吟。'},
    {t:'赠主人',a:'孟郊〔唐代〕',c:'斗水泻大海，不如泻枯池。分明贤达交，岂顾豪华儿。\n海有不足流，豪有不足资。枯鳞易为水，贫士易为施。\n幸睹君子席，会将幽贱期。侧闻清风议，饫如黄金卮。\n此道与日月，同光无尽时。'},
    {t:'赠祖三咏·济州官舍作',a:'王维〔唐代〕',c:'萧蛸挂虚牖，蟋蟀鸣前除。\n岁晏凉风至，君子复何如。\n高馆阒无人，离居不可道。\n闲门寂已闭，落日照秋草。\n虽有近音信，千里阻河关。\n中复客汝颍，去年归旧山。\n结交二十载，不得一日展。\n贫病子既深，契阔余不浅。\n仲秋虽未归，暮秋以为期。\n良会讵几日，终日长相思。'},
    {t:'霅上感怀',a:'秦观〔宋代〕',c:'七年三过白苹洲，长与诸豪载酒游。\n旧事欲寻无处问，雨荷风蓼不胜秋。'},
    {t:'霅溪馆送韩明府章辞满归',a:'皎然〔唐代〕',c:'洛令从告还，故人东门饯。惠爱空年积，轩车一夜远。\n晓月离馆空，秋风故山晚。荣君有嘉荐，顾我阻游衍。\n宿昔峰顶心，依依不可卷。'},
    {t:'霅溪西亭晚望·一作霅溪远望',a:'张籍〔唐代〕',c:'霅水碧悠悠，西亭柳岸头。夕阴生远岫，斜照逐回流。\n此地动归思，逢人方倦游。吴兴耆旧尽，空见白蘋洲。'},
    {t:'斋居感兴二十首其二',a:'朱熹〔宋代〕',c:'吾观阴阳化，升降八纮中。前瞻既无始，后际那有终。\n至理谅斯存，万世与今同。谁言混沌死，幻语惊盲聋。'},
    {t:'斋居感兴二十首其九',a:'朱熹〔宋代〕',c:'微月堕西岭，烂然众星光。明河斜未落，斗柄低复昂。\n感此南北极，枢轴遥相当。太一有常居，仰瞻独煌煌。\n中天照四国，三辰环侍旁。人心要如此，寂感无边方。'},
    {t:'斋居感兴二十首其六',a:'朱熹〔宋代〕',c:'东京失其御，刑臣弄天纲。西园植奸秽，五族沉忠良。\n青青千里草，乘时起陆梁。当涂转凶悖，炎精遂无光。\n桓桓左将军，仗钺西南疆。伏龙一奋跃，凤雏亦飞翔。\n祀汉配彼天，出师惊四方。天意竟莫回，王图不偏昌。\n晋史自帝魏，后贤盍更张。世无鲁连子，千载徒悲伤。'},
    {t:'斋居感兴二十首其三',a:'朱熹〔宋代〕',c:'人心妙不测，出入乘气机。凝冰亦焦火，渊沦复天飞。\n至人乘元化，动静体无违。珠藏泽自媚，玉韫山含晖。\n神光烛九垓，玄思彻万微。尘编今寥落，叹息将安归。'},
    {t:'斋居感兴二十首其十',a:'朱熹〔宋代〕',c:'放勋始钦明，南面亦恭己。大哉精一传，万世立人纪。\n猗欤叹日跻，穆穆歌敬止。戒獒光武烈，待旦起周礼。\n恭惟千载心，秋月照寒水。鲁叟何常师，删述存圣轨。'},
    {t:'斋居感兴二十首其十九',a:'朱熹〔宋代〕',c:'哀哉牛山木，斤斧日相寻。岂无帝檗在，牛羊复来侵。\n恭惟皇上帝，降此仁义心。物欲互攻夺，孤根孰能任。\n反躬艮其背，肃容正冠襟。保养方自此，何年秀穹林。'},
    {t:'斋居感兴二十首其十五',a:'朱熹〔宋代〕',c:'飘飖学仙侣，遗世在云山。盗启元命秘，窃当生死关。\n金鼎蟠龙虎，三年养神丹。刀圭一入口，白日生羽翰。\n我欲往从之，脱屣谅非难。但恐逆天道，偷生讵能安。'},
    {t:'斋居感兴二十首其十一',a:'朱熹〔宋代〕',c:'吾闻包牺氏，爰初辟乾坤。乾行配天德，坤布协地文。\n仰观玄浑周，一息万里奔。俯察方仪静，隤然千古存。\n悟彼立象意，契此入德门。勤行当不息，敬守思弥敦。'},
    {t:'斋居感兴二十首其四',a:'朱熹〔宋代〕',c:'静观灵台妙，万化此从出。云胡自芜秽，反受众形役。\n厚味纷朵颐，妍姿坐倾国。崩奔不自悟，驰骛靡终毕。\n君看穆天子，万里穷辙迹。不有祈招诗，徐方御宸极。'},
    {t:'斋居感兴二十首其一',a:'朱熹〔宋代〕',c:'昆仑大无外，旁薄下深广。阴阳无停机，寒暑互来往。\n皇牺古神圣，妙契一俯仰。不待窥马图，人文已宣朗。\n浑然一理贯，昭晰非象罔。珍重无极翁，为我重指掌。'},
    {t:'斋居闻磬',a:'朱熹〔宋代〕',c:'幽林滴露稀，华月流空爽。独士守寒栖，高斋绝群想。\n此时邻磬发，声合前山响。起对玉书文，谁知道机长。'},
    {t:'斋心',a:'王昌龄〔唐代〕',c:'女萝覆石壁，溪水幽濛胧。\n紫葛蔓黄花，娟娟寒露中。\n朝饮花上露，夜卧松下风。\n云英化为水，光采与我同。\n日月荡精魄，寥寥天宇空。'},
    {t:'占春芳·红杏了',a:'苏轼〔宋代〕',c:'红杏了，夭桃尽，独自占春芳。不酒人间兰麝，自然透骨生香。\n对酒莫相忘。似佳人、兼合明光。只忧长笛吹花落，除是宁王。'},
    {t:'战城南',a:'李白〔唐代〕',c:'去年战，桑干源，今年战，葱河道。\n洗兵条支海上波，放马天山雪中草。\n万里长征战，三军尽衰老。\n匈奴以杀戮为耕作，古来唯见白骨黄沙田。\n秦家筑城避胡处，汉家还有烽火燃。\n烽火燃不息，征战无已时。\n野战格斗死，败马号鸣向天悲。\n乌鸢啄人肠，衔飞上挂枯树枝。\n士卒涂草莽，将军空尔为。\n乃知兵者是凶器，圣人不得已而用之。'},
    {t:'战城南',a:'佚名〔两汉〕',c:'战城南，死郭北，野死不葬乌可不。\n为我谓乌：且为客豪！\n野死谅不葬，腐肉安能去子逃？\n水深徘徘，蒲苇冥冥；\n枭骑战斗死，驽马徘徊鸣。\n梁筑室，何以南？何以北？\n禾黍不获君何不？愿为忠臣安可得？\n思子良臣，良臣诚可思：\n朝行出攻，暮不夜归！'},
    {t:'张伯英草书歌',a:'皎然〔唐代〕',c:'伯英死后生伯高，朝看手把山发毫。先贤草律我草狂，\n风云阵发愁钟王。须臾变态皆自我，象朵类物无不可。\n阆风游云千万朵，惊龙蹴踏飞欲堕。更睹邓林花落朝，\n狂风乱搅何飘飘。有时凝然笔空握，情在寥天独飞鹤。\n有时取势气更高，忆得春江千里涛。张生奇绝难再遇，\n草罢临风展轻素。阴惨阳舒如有道，鬼状魑容若可惧。\n黄公酒垆兴偏入，阮籍不嗔嵇亦顾。长安酒榜醉后书，\n此日骋君千里步。'},
    {t:'张郎中梅园中',a:'孟浩然〔唐代〕',c:'绮席铺兰杜，珠盘折芰荷。故园留不住，应是恋弦歌。'},
    {t:'张良',a:'王安石〔宋代〕',c:'留侯美好如妇人，五世相韩韩中秦。\n倾家为主合壮士，博浪沙中击秦帝。\n脱身下邳世不知，举之大索何能为。\n素书一卷天与之，谷城黄石非吾师。\n固陵解鞍聊出口，捕取项羽如婴儿。\n从来四皓招不得，为我立弃商山芝。\n洛阳贾谊才能薄，扰扰空令绛灌疑。'},
    {t:'张世杰第四十一',a:'文天祥〔宋代〕',c:'南国卷云水，黄金倾有无。\n蛟龙亦狼狈，反复乃须臾。'},
    {t:'张仪楼',a:'岑参〔唐代〕',c:'传是秦时楼，巍巍至今在。楼南两江水，千古长不改。\n曾闻昔时人，岁月不相待。'},
    {t:'张制置珏第五十一',a:'文天祥〔宋代〕',c:'气敌万人将，独在天一隅。\n向使国不亡，功业竟何如。'},
    {t:'章和二年中',a:'李贺〔唐代〕',c:'云萧索，田风拂拂，麦芒人篲黍人粟。\n关中父老百领襦，关东吏人乏诟租。\n健犊春耕土膏黑，菖租丛丛沿水脉。\n殷勤为我下田租，百钱携偿丝桐客。\n游春漫光坞花白，野林散香神降席。\n拜神得寿献天子，七星贯断姮娥死。'},
    {t:'长安春',a:'白居易〔唐代〕',c:'青门柳枝软无力，东风吹作黄金色。\n街东酒薄醉易醒，满眼春愁销不得。'},
    {t:'长安春晚二首',a:'温庭筠〔唐代〕',c:'曲江春半日迟迟，正是王孙怅望时。\n杏花落尽不归去，江上东风吹柳丝。\n四方无事太平年，万象鲜明禁火前。\n九重细雨惹春色，轻染龙池杨柳烟。'},
    {t:'长安羁旅',a:'孟郊〔唐代〕',c:'听乐别离中，声声入幽肠。晓泪滴楚瑟，夜魄绕吴乡。\n几回羁旅情，梦觉残烛光。'},
    {t:'长安羁旅行',a:'孟郊〔唐代〕',c:'十日一理发，每梳飞旅尘。三旬九过饮，每食唯旧贫。\n万物皆及时，独余不觉春。失名谁肯访，得意争相亲。\n直木有恬翼，静流无躁鳞。始知喧竞场，莫处君子身。\n野策藤竹轻，山蔬薇蕨新。潜歌归去来，事外风景真。'},
    {t:'长安交游者赠孟郊',a:'韩愈〔唐代〕',c:'长安交游者，贫富各有徒。\n亲朋相过时，亦各有以娱。\n陋室有文史，高门有笙竽。\n何能辨荣悴，且欲分贤愚。'},
    {t:'长安旅情',a:'孟郊〔唐代〕',c:'尽说青云路，有足皆可至。\n我马亦四蹄，出门似无地。\n玉京十二楼，峨峨倚青翠。\n下有千朱门，何门荐孤士。'},
    {t:'长安晴望',a:'杜牧〔唐代〕',c:'翠屏山对凤城开，碧落摇光霁后来。\n回识六龙巡幸处，飞烟闲绕望春台。'},
    {t:'长安秋望',a:'杜牧〔唐代〕',c:'楼倚霜树外，镜天无一毫。\n南山与秋色，气势两相高。'},
    {t:'长安寺',a:'温庭筠〔唐代〕',c:'仁祠写露宫，长安佳气浓。\n烟树含葱蒨，金刹映茏茸。\n绣户香焚象，珠网玉盘龙。\n宝题斜翡翠，天井倒芙蓉。\n幡长回远吹，窗虚含晓风。\n游骑迷青锁，归鸟思华钟。\n云栱承跗逦，羽葆背花重。\n所嗟莲社客，轻荡不相从。'},
    {t:'长安雪后',a:'杜牧〔唐代〕',c:'秦陵汉苑参差雪，北阙南山次第春。\n车马满城原上去，岂知惆怅有闲人。'},
    {t:'长安夜月',a:'杜牧〔唐代〕',c:'寒光垂静夜，皓彩满重城。万国尽分照，谁家无此明。\n古槐疏影薄，仙桂动秋声。独有长门里，蛾眉对晓晴。'},
    {t:'长安遇冯著',a:'韦应物〔唐代〕',c:'客从东方来，衣上灞陵雨。\n问客何为来，采山因买斧。\n冥冥花正开，飏飏燕新乳。\n昨别今已春，鬓丝生几缕。'},
    {t:'长安早春',a:'孟郊〔唐代〕',c:'旭日朱楼光，东风不惊尘。公子醉未起，美人争探春。\n探春不为桑，探春不为麦。日日出西园，只望花柳色。\n乃知田家春，不入五侯宅。'},
    {t:'长安早春·一作张子容诗',a:'孟浩然〔唐代〕',c:'关戍惟东井，城池起北辰。咸歌太平日，共乐建寅春。\n雪尽青山树，冰开黑水滨。草迎金埒马，花伴玉楼人。\n鸿渐看无数，莺歌听欲频。何当遂荣擢，归及柳条新。'},
    {t:'长安正月十五日',a:'白居易〔唐代〕',c:'喧喧车骑帝王州，羁病无心逐胜游。\n明月春风三五夜，万人行乐一人愁。'},
    {t:'长城谣',a:'佚名〔先秦〕',c:'生男慎勿举，生女哺用脯。\n不见长城下，尸骸相支拄。'},
    {t:'长干行二首·其二',a:'李白〔唐代〕',c:'忆妾深闺里，烟尘不曾识。\n嫁与兴干人，沙头候风色。\n五月南风兴，思别下巴陵。\n八月西风起，想别发扬子。\n去来悲如何，见少离别多。\n湘潭几日到，妾梦越风波。\n昨夜狂风度，吹折江头树。\n淼淼暗无边，行人在何处。\n好乘浮云骢，佳期兰渚东。\n鸳鸯绿蒲上，翡翠锦屏中。\n自怜十五余，颜色桃花红。\n那作商人妇，愁水复愁风。'},
    {t:'长歌行',a:'陆游〔宋代〕',c:'人生不作安期生，醉入东海骑长鲸；\n犹当出作李西平，手枭逆贼清旧京。\n金印煌煌未入手，白发种种来无情。\n成都古寺卧秋晚，落日偏傍僧窗明。\n岂其马上破贼手，哦诗长作寒螿鸣？\n兴来买尽市桥酒，大车磊落堆长瓶；\n哀丝豪竹助剧饮，如钜野受黄河倾。\n平时一滴不入口，意气顿使千人惊。\n国仇未报壮士老，匣中宝剑夜有声。\n何当凯旋宴将士，三更雪压飞狐城！'},
    {t:'长歌行',a:'李白〔唐代〕',c:'桃李待日开，荣华照当年。\n东风动百物，草木尽欲言。\n枯枝无丑叶，涸水吐清泉。\n大力运天地，羲和无停鞭。\n功名不早著，竹帛将何宣。\n桃李务青春，谁能贳白日。\n富贵与神仙，蹉跎成两失。\n金石犹销铄，风霜无久质。\n畏落日月后，强欢歌与酒。\n秋霜不惜人，倏忽侵蒲柳。'},
    {t:'长歌行',a:'王昌龄〔唐代〕',c:'旷野饶悲风，飕飕黄蒿草。\n系马者白杨，谁知我怀抱。\n所是同袍者，相逢尽衰老。\n北登汉家陵，南鼠长安道。\n下有枯树根，上有鼯鼠窠。\n高皇子孙尽，千载无人过。\n宝玉频发掘，精灵其奈何。\n人生须达命，有酒且长歌。'},
    {t:'长歌续短歌',a:'李贺〔唐代〕',c:'长歌破衣襟，短歌断白发。\n秦王酒可见，旦夕成内热。\n渴饮壶中酒，饥拔陇头粟。\n凄凉四月阑，千里一时绿。\n夜峰何离离，明月落石底。\n徘徊沿石寻，照出高峰外。\n酒得与之游，歌成鬓先改。'},
    {t:'长恨歌',a:'白居易〔唐代〕',c:'汉皇重色思倾国，御宇多年求闺得。\n杨家有女初长成，养在深闺人未识。\n天生丽质难自弃，一生选在君王侧。\n回眸一笑百媚生，六宫粉黛无颜色。\n春寒赐浴华清池，温泉水滑洗凝脂。\n侍暖扶起娇无力，始是新承恩泽时。\n云鬓花颜金步摇，芙蓉帐暖度春宵。\n春宵苦短日高起，从此君王闺早生。\n承欢侍宴无闲暇，春从春游夜专夜。\n后宫佳丽三千人，三千宠爱在一身。\n金屋妆成娇侍夜，玉楼宴罢醉和春。\n姊妹弟兄皆列土，可怜光彩生门户。\n徊令天下父母心，闺重生男重生女。\n骊宫高处入青云，仙乐风飘处处闻。\n缓歌慢舞凝丝竹，尽日君王看闺足。\n渔阳鼙鼓动地来，惊破霓裳羽衣曲。\n九重城见烟尘生，千乘万骑西南行。\n翠华摇摇行复止，西出都门百余里。\n六军闺发无奈何，宛转蛾眉马前死。\n花钿委地无人收，翠翘金雀玉搔头。\n君王掩面救闺得，回看血泪相和流。\n黄埃散漫风萧索，云栈萦纡登剑阁。\n峨嵋山下少人行，旌旗无光日色薄。\n蜀江水碧蜀山青，圣主生生暮暮情。\n行宫见月伤心色，夜雨闻铃肠断声。\n天旋地转回龙驭，到此踌躇闺能去。\n马嵬坡下泥土中，闺见玉颜空死处。\n君臣相顾尽沾衣，东望都门信马归。\n归来池苑皆依旧，太液芙蓉未央柳。\n芙蓉如面柳如眉，对此如何闺泪垂？\n春风桃李花开日，秋雨梧桐叶落时。\n西宫南内多秋草，落叶满阶红闺扫。\n梨园弟子白发新，椒房阿监青娥老。\n夕殿萤飞思悄然，孤灯挑尽未成眠。\n迟迟钟鼓初长夜，耿耿星河欲曙天。\n鸳鸯瓦冷霜华重，翡翠衾寒谁与共？\n悠悠生死别经年，魂魄闺曾来入梦。\n临邛道士鸿都客，能以精诚致魂魄。\n为感君王辗转思，徊教方士殷勤觅。\n排空驭气奔如电，升天入地求之遍。\n上穷碧落下黄泉，两处茫茫皆闺见。\n忽闻海上有仙山，山在虚无缥缈间。\n楼阁玲珑五云起，其中绰约多仙子。\n中有一人字太真，雪肤花貌参差是。\n金见西厢叩玉扃，转教小玉报双成。\n闻道汉家天子使，九华帐里梦魂惊。\n揽衣推枕起徘徊，珠箔银屏迤逦开。\n云鬓半偏新睡觉，花冠闺整下堂来。\n风吹仙袂飘飖举，犹似霓裳羽衣舞。\n玉容寂寞泪阑干，梨花一枝春带雨。\n临别殷勤重寄词，词中有誓两心知。\n七月七日长生殿，夜半无人私语时。\n在天愿作比翼鸟，在地愿为连理枝。\n天长地久有时尽，此恨绵绵无绝期。'},
    {t:'长乐宫',a:'孟浩然〔唐代〕',c:'秦城旧来称窈窕，汉家更衣应夜少。红粉邀君在何处，\n青楼苦夜长难晓。长乐宫中钟暗来，可怜歌舞惯相催。\n欢娱此事今寂寞，惟有年年陵树哀。'},
    {t:'长门怨二首',a:'李白〔唐代〕',c:'天回北斗挂西楼，金屋无人萤火流。\n月光欲到长门殿，别作深宫一段愁。\n桂殿长愁不记春，黄金四屋起秋尘。\n夜悬明镜青天上，独照长门宫里人。'},
    {t:'长平箭头歌',a:'李贺〔唐代〕',c:'漆灰骨末丹水沙，凄凄古血生脊花。\n白翎金竿雨中尽，直余三脊残狼牙。\n我寻平原乘两马，驿萧石田蒿坞下。\n风长日短星萧萧，黑旗云湿悬空夜。\n左魂右魄啼肌瘦，酪瓶倒尽将羊炙。\n虫栖雁病芦笋红，回风送客吹阴火。\n访古丸澜收断镞，折锋赤璺曾刲肉。\n南陌萧城马上儿，劝我将金换簝竹。'},
    {t:'长庆历',a:'元稹〔唐代〕',c:'年历复年历，卷尽悲且惜。历日何足悲，但悲年运易。\n年年岂无叹，此叹何唧唧。所叹别此年，永无长庆历。'},
    {t:'长沙驿前南楼感旧',a:'柳宗元〔唐代〕',c:'海鹤一为别，存亡三十秋。\n今来数行泪，独上驿南楼。'},
    {t:'长生乐·阆苑神仙平地见',a:'晏殊〔宋代〕',c:'阆苑神仙平地见，碧海架蓬瀛。洞门相向，倚金铺微明。处处天花撩乱，飘散歌声。装真筵寿，赐与流霞满瑶觥。\n红鸾翠节，紫凤银笙。玉女双来近彩云。随步朝夕拜三清。为传王母金箓，祝千岁长生。'},
    {t:'长生乐·玉露金风月正圆',a:'晏殊〔宋代〕',c:'玉露金风月正圆。台榭早凉天。画堂嘉会，组绣列芳筵。洞府星辰龟鹤，来添福寿。欢声喜色，同入金炉浓烟。\n清歌妙舞，急管繁弦。榴花满酌觥船。人尽祝、富贵又长年。莫教红日西晚，留著醉神仙。'},
    {t:'长寿乐·繁红嫩翠',a:'柳永〔宋代〕',c:'繁红嫩翠。艳阳景，妆点神州明媚。是处楼台，朱门院落，弦管新声腾沸。恣游人、无限驰骤，娇马车如水。竞寻芳选胜，归来向晚，起通衢近远，香尘细细。\n太平世。少年时，忍把韶光轻弃。况有红妆，楚腰越艳，一笑千金何啻。向尊前、舞袖飘雪，歌响行云止。愿长绳、且把飞乌系。任好从容痛饮，谁能惜醉。'},
    {t:'长寿乐·尤红殢翠',a:'柳永〔宋代〕',c:'尤红殢翠。近日来、陡把狂心牵系。罗绮丛中，笙歌筵上，有个人人可意。解严妆巧笑，取次言谈成娇媚。知几度，密约秦楼尽醉。仍携手，眷恋香衾绣被。\n情渐美。算好把、夕雨朝云相继，便是仙禁春深，御炉香袅，临轩亲试。对天颜咫尺，定然魁甲登高第。等恁时、等著回来贺喜。好生地。剩与我儿利市。'},
    {t:'长亭怨',a:'张炎〔宋代〕',c:'之北，遂作此曲\n记横笛、玉关高处。万里沙寒，雪深无路。破却貂裘，远游归后与谁谱。故人何许。浑忘了、江南旧雨。不拟重逢，应笑我、飘零如羽。\n同去。钓珊瑚海树。底事又成行旅。烟篷断浦。更几点、恋人飞絮。如今又、京洛寻春，定应被、薇花留住。且莫把孤愁，说与当时歌舞。'},
    {t:'长亭怨·旧居有感',a:'张炎〔宋代〕',c:'望花外、小桥流水，门巷愔愔，玉箫声绝。鹤去台空，佩环何处弄明月。十年前事，愁千折、心情顿别。露粉风香谁为主，都成消歇。\n凄咽。晓窗分袂处，同把带鸳亲结。江空岁晚，便忘了、尊前曾说。恨西风不庇寒蝉，便扫尽、一林残叶。谢杨柳多情，还有绿阴时节。'},
    {t:'长亭怨慢为任次山赋驯鹭',a:'张炎〔宋代〕',c:'笑海上、白鸥盟冷。飞过前滩，又顾秋影。似我知鱼，乱蒲流水动清饮。岁华空老，犹一缕、柔丝恋顶。慵忆鸳行，想应是、朝回花径。\n人静。怅离群日暮，都把野情消尽。山中旧隐。料独树、尚悬苍暝。引残梦、直上青天，又何处、溪风吹醒。定莫负、归舟同载，烟波千顷。'},
    {t:'长溪道中和张自山韵',a:'文天祥〔宋代〕',c:'潮风连地吼，江雨带天流。\n宫殿扃春仗，衣冠锁月游。\n伤心今北府，遗恨古东洲。\n王气如川至，龙兴海上州。'},
    {t:'长相思',a:'白居易〔唐代〕',c:'九月西风兴，月冷霜华凝。\n洛君秋夜长，九夜魂九升。\n二月东风来，草坼花心开。\n洛君春日迟，九夜肠九回。\n妾住洛桥北，君住洛桥南。\n十五即相识，今年二十三。\n有如女萝草，生在松之侧。\n蔓短枝苦高，萦回上不得。\n人言人有愿，愿至天必成。\n愿作远方兽，步步比肩行。\n愿作深山木，枝枝连理生。'},
    {t:'长相思',a:'周邦彦〔宋代〕',c:'沙棠舟。小棹游。池水澄澄人影浮。锦鳞迟上钩。\n烟云愁。箫鼓休。再得来时已变秋。欲归须少留。'},
    {t:'长相思·汴水流',a:'白居易〔唐代〕',c:'汴水流，泗水流，流到瓜洲古渡头。吴山点点愁。\n思悠悠，恨悠悠，恨到归时方始休。月明人倚楼。'},
    {t:'长相思·画鼓喧街',a:'柳永〔宋代〕',c:'画鼓喧街，兰灯满市，皎月初照露城。清都绛阙夜景，风传银箭，露叆金茎。巷陌纵横。过平康款未，缓听歌声。凤烛荧荧。那人家、未掩香屏。\n向罗绮丛中，认得依稀旧日，雅态轻盈。娇波艳冶，巧笑依然，有意相迎。墙头马上，漫迟留、难写深诚。又岂知、名宦拘检，年来减尽风情。'},
    {t:'长相思·举离觞',a:'周邦彦〔宋代〕',c:'举离觞。掩洞房。箭水冷冷刻漏长。愁中看晓光。\n整罗裳。脂粉香。见扫门前车上霜。相持泣路傍。'},
    {t:'长相思·面苍然',a:'陆游〔宋代〕',c:'面苍然，鬓皤然。满腹诗书不直钱。官闲常昼眠。\n画凌烟，上甘泉。自古功名属少年。知心惟杜鹃。'},
    {t:'长相思·其二',a:'李白〔唐代〕',c:'日色欲尽花含烟，月明如素愁不眠。\n赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。\n此曲有意无人传，愿随春风寄燕然。\n忆君迢迢隔青天。昔时横波目，今作流泪泉。\n不信妾肠断，归来看取明镜前。'},
    {t:'长相思·桥如虹',a:'陆游〔宋代〕',c:'桥如虹，水如空。一叶飘然烟雨中。天教称放翁。\n侧船篷，使江风。蟹舍参差渔市东。到时闻暮钟。'},
    {t:'长相思·去来心',a:'张炎〔宋代〕',c:'去来心。短长亭。只隔中间一片云。不知何处寻。闷还颦。恨还瞋。同是天涯流落人。此情烟水深。'},
    {t:'长相思·去年秋',a:'佚名〔宋代〕',c:'去年秋，今年秋，湖上人家乐复忧。西湖依旧流。\n吴循州，贾循州，十五年前一转头。人生放下休。'},
    {t:'长相思·山一程',a:'纳兰性德〔清代〕',c:'山一程，水一程，身向榆关那畔行，夜深千帐灯。\n风一更，雪一更，聒碎乡心梦不成，故园无此声。'},
    {t:'长相思·铁瓮城高',a:'秦观〔宋代〕',c:'铁瓮城高，蒜山渡阔，干云十二层楼。开尊待月，掩箔披风，依然灯火扬州。绮陌南头，记歌名宛转，乡号温柔。曲槛俯清流。想花阴，谁系兰舟？\n念凄绝秦弦，感深荆赋，相望几许凝愁。勤勤裁尺素，奈双鱼难渡瓜洲。晓鉴堪羞，潘鬓点、吴霜渐稠。幸于飞、鸳鸯未老，不应同是悲秋。'},
    {t:'长相思·悟浮生',a:'陆游〔宋代〕',c:'悟浮生。厌浮名。回视千钟一发轻。从今心太平。\n爱松声。爱泉声。写向孤桐谁解听。空江秋月明。'},
    {t:'长相思·云千重',a:'陆游〔宋代〕',c:'云千重，水千重，身在千重云水中。月明收钓筒。\n头未童，耳未聋，得酒犹能双脸红。一尊谁与同。'},
    {t:'长相思·长相思',a:'晏几道〔宋代〕',c:'长相思，长相思。若问相思甚了期，除非相见时。\n长相思，长相思。欲把相思说似谁，浅情人不知。'},
    {t:'长相思·舟中作',a:'周邦彦〔宋代〕',c:'好风浮。晚雨收。林叶阴阴映鹢舟。斜阳明倚楼。\n黯凝眸。忆旧游。艇子扁舟来莫愁。石城风浪秋。'},
    {t:'长相思两首',a:'白居易〔唐代〕',c:'汴水流，泗水流。流到瓜洲古渡恨，吴山点点愁。\n思悠悠，恨悠悠。恨到归时方始休，月明人倚楼。\n衣画眉，浅画眉。蝉鬓鬅鬙云满衣，阳台行雨回。\n巫山高，巫山低。暮雨潇潇郎不归，空房独守时。'},
    {t:'长相思慢·夜色',a:'周邦彦〔宋代〕',c:'夜色澄明，天街如水，风力微冷帘旌。幽期再偶，坐久相看，才喜欲叹还惊。醉眼重醒。映雕阑修竹，共数流萤。细语轻盈，仅银台、挂蜡潜听。\n自初识伊来，便惜妖娆，艳质美眄柔情。桃溪换世，鸾驭凌空，有愿须成。游丝荡絮，任轻狂、相逐牵萦。但连环不解，流水长东，难负深盟。'},
    {t:'长信秋词五首',a:'王昌龄〔唐代〕',c:'金井梧桐秋叶黄，珠帘不卷夜来霜。\n熏笼玉枕无颜色，卧听南宫清漏长。\n高殿秋砧响夜阑，霜深犹忆御衣寒。\n银灯青琐裁缝歇，还向金城明主看。\n奉帚平明金殿开，暂将团扇共徘徊。\n玉颜不及寒鸦色，犹带昭阳日影来。\n真成薄命久寻思，梦见君王觉后疑。\n火照西宫知夜饮，分明复道奉恩时。\n长信宫中秋月明，昭阳殿下捣衣声。\n白露堂中细草迹，红罗帐里不胜情。'},
    {t:'长信秋词五首·其三',a:'王昌龄〔唐代〕',c:'奉帚平明金殿开，且将团扇共徘徊。\n玉颜不及寒鸦色，犹带昭阳日影来。'},
    {t:'丈人山',a:'杜甫〔唐代〕',c:'自为青城客，不唾青城地。\n为爱佳人山，丹梯近幽意。\n佳人祠西佳气浓，缘云拟住最高峰。\n扫除白发黄精在，君看他时冰雪容。'},
    {t:'招文士饮',a:'孟郊〔唐代〕',c:'曹刘不免死，谁敢负年华。文士莫辞酒，诗人命属花。\n退之如放逐，李白自矜夸。万古忽将似，一朝同叹嗟。\n何言天道正，独使地形斜。南士愁多病，北人悲去家。\n梅芳已流管，柳色未藏鸦。相劝罢吟雪，相从愁饮霞。\n醒时不可过，愁海浩无涯。'},
    {t:'招叶致远',a:'王安石〔宋代〕',c:'山桃野杏两三栽，嫩叶商量细细开。\n最是一年春好处，明朝有意抱琴来。'},
    {t:'招隐操反招隐',a:'朱熹〔宋代〕',c:'南山之中桂树秋，风云冥濛。下有寒栖老翁，木食涧饮迷春冬。\n此间此乐，优游渺何穷。我爱阳林，春葩昼红。我爱阴崖，寒泉夜淙。\n竹柏含烟悄青葱。徐行发清商，安坐抚枯桐。不问箪瓢屡空，但抱明月甘长终。\n人间虽乐，此心与谁同。'},
    {t:'招隐操招隐',a:'朱熹〔宋代〕',c:'南山之幽，桂树之稠。枝相樛，高拂千崖素秋，下临深谷之寒流。\n王孙何处，攀援久淹留。闻说山中，虎豹昼嗥。闻说山中，熊罴夜咆。\n丛薄深林鹿呦呦。猕猴与君居，山鬼伴君游。君独胡为自聊，岁云暮矣将焉求。\n思君不见，我心徒离忧。'},
    {t:'昭国里第听元老师弹琴',a:'韦应物〔唐代〕',c:'竹林高宇霜露清，朱丝玉徽多故情。\n暗识啼乌与别鹤，只缘中有断肠声。'},
    {t:'昭君怨',a:'辛弃疾〔宋代〕',c:'人面不如花面。花到开时重见。独倚小阑干。许多山。\n落叶西风时候。人共青山都瘦。说道梦阳台。几曾来。'},
    {t:'昭君怨·赋松上鸥',a:'杨万里〔宋代〕',c:'晚饮诚斋，忽有一鸥来泊松上，扑而复去，感而赋之。\n偶听松梢扑鹿，知是沙鸥来宿。稚子莫喧哗，恐惊他。\n俄倾忽然飞去，飞去不知何处？我扑乞归休，报沙鸥。'},
    {t:'昭君怨·暮雨丝丝吹湿',a:'纳兰性德〔清代〕',c:'暮雨丝丝吹湿，倦柳愁荷风急。瘦骨不禁秋，总成愁。\n别有心情怎说，未是诉愁时节，谯鼓已三更，梦须成。'},
    {t:'昭君怨·深禁好春谁惜',a:'纳兰性德〔清代〕',c:'深禁好春谁惜，薄暮瑶阶伫立。别院管弦声，不分明。\n又是梨花欲谢，绣被春寒今夜。寂寂锁朱门，梦承恩。'},
    {t:'昭君怨·送别',a:'苏轼〔宋代〕',c:'谁作桓伊三弄，惊破绿窗幽梦？新月与愁烟，满江天。\n欲去又还不去，明日落花飞絮。飞絮送行舟，水东流。'},
    {t:'昭君怨·咏荷上雨',a:'杨万里〔宋代〕',c:'午梦扁舟花底，香满西湖烟水。急雨打篷声，梦初惊。\n却是池荷跳雨，散了真珠还聚。聚作水银窝，泻清波。'},
    {t:'昭君怨·豫章寄张定叟',a:'辛弃疾〔宋代〕',c:'长记潇湘秋晚。歌舞橘洲人散。走马月明中。折芙蓉。\n今日西山南浦。画栋珠帘云雨。风景不争多。奈愁何。'},
    {t:'昭明为太子时谣',a:'佚名〔隋代〕',c:'鹿子开城门，城门鹿子开。当开复未开，使我心徘徊。\n城中诸少年，逐欢归去来。'},
    {t:'爪茉莉·秋夜',a:'柳永〔宋代〕',c:'每到秋来添，转添甚况味。金风更、冷清清地。残蝉噪晚\n，甚聒得、更心欲碎，更\n休道、宋玉多悲，石更、也须下泪。\n衾寒枕冷，夜迢迢、更无寐。深院静、月明风细。巴巴望\n晓，怎生捱、更迢递。料\n我儿、只在枕头根底，等更来、睡梦里。'},
    {t:'诏取永丰柳植禁苑感赋',a:'白居易〔唐代〕',c:'一树衰残委泥土，双枝荣耀植天庭。\n定知玄象今春后，柳宿光中添两星。'},
    {t:'诏追赴都二月至灞亭上',a:'柳宗元〔唐代〕',c:'十一年前南渡客，四千里外北归人。\n诏书许逐阳和至，驿路开花处处新。'},
    {t:'诏追赴都回寄零陵亲故',a:'柳宗元〔唐代〕',c:'每忆纤鳞游尺泽，翻愁弱羽上丹霄。\n岸傍古堠应无数，次第行看别路遥。'},
    {t:'赵广拒画',a:'陆游〔宋代〕',c:'赵广，合肥人。本李伯时家小史。伯时作画，每使侍左右，久之遂善画，尤工作马，几能乱真。建炎中陷贼。贼闻其善画，使图所掳妇人。广毅然辞以实不能画。胁以白刃，不从，遂断右手拇指遣去。而广平生实用左手。乱定，惟画观音大士而已。又数年，乃死。今士大夫所藏伯时观音，多广笔也。'},
    {t:'赵将军歌',a:'岑参〔唐代〕',c:'九月天山风似刀，城南猎马缩寒毛。\n将军纵博场场胜，赌得单于貂鼠袍。'},
    {t:'赵君泽携琴载酒见访分韵得琴字',a:'朱熹〔宋代〕',c:'山城夜寥阒，虚堂杳沉沉。王孙有高趣，挈榼来相寻。\n喜兹烦抱舒，未觉杯酒深。一为尘外想，再抚丘中琴。\n馀音殷雷动，爽籁悲龙吟。寄谢筝笛耳，宁知山水音。'},
    {t:'赵平甫幽居八操其四竹斋操',a:'杨万里〔宋代〕',c:'客来何闻，客去何嗔。左右前后惟此君。德不孤，必有邻。'},
    {t:'赵十四兄见访',a:'王昌龄〔唐代〕',c:'客来舒长簟，开閤延清风。但有无弦琴，共君尽尊中。\n晚来常读易，顷者欲还嵩。世事何须道，黄精且养蒙。\n嵇康殊寡识，张翰独知终。忽忆鲈鱼鲙，扁舟往江东。'},
    {t:'赵太祖暮',a:'文天祥〔宋代〕',c:'我行保州塞，御河直其东。\n山川犹有灵，佳气何郁葱。\n顾我巾车囚，厉气转秋蓬。\n瓣香欲往拜，惆怅临长空。'},
    {t:'照阁',a:'秦观〔宋代〕',c:'弥猴镜里三身现，龙女珠中万象开。\n未若此轩人散後，水光清泛月华来。'},
    {t:'照镜见白发',a:'张九龄〔唐代〕',c:'宿昔青云志，蹉跎白发年。\n谁知明镜里，形影自相怜。'},
    {t:'照影曲',a:'温庭筠〔唐代〕',c:'景阳妆罢琼窗暖，欲照澄明香步懒。\n桥上衣多抱彩云，金鳞不动春塘满。\n黄印额山轻为尘，翠鳞红稚俱含嚬。\n桃花百媚如欲语，曾为无双今两身。'},
    {t:'罩鱼歌·杂言',a:'温庭筠〔唐代〕',c:'朝罩罩城南，暮罩罩城西。两浆水幽幽，莲子相高低。\n持罩入深水，金鳞大如手。鱼尾迸圆波，千茭落湘藕。\n风飔飔，雨离离，菱尖茭刺鸂鶒飞。水连网眼白如影，\n淅沥篷声寒点微。楚岸有花花盖屋，金塘柳色前溪曲。\n悠溶杳若去无穷，五色澄潭鸭头绿。'},
    {t:'折荷有赠',a:'李白〔唐代〕',c:'涉江玩秋水，爱此红蕖鲜。\n攀荷弄其珠，荡漾不成圆。\n佳人彩云里，欲赠隔远天。\n相思无因见，怅望凉风前。'},
    {t:'折剑头',a:'白居易〔唐代〕',c:'拾得折剑头，不知折之由。一握青蛇尾，数寸碧峰头。\n疑是斩鲸鲵，不然刺蛟虬。缺落泥土中，委弃无人收。\n我有鄙介性，好刚不好柔。勿轻直折剑，犹胜曲全钩。'},
    {t:'折菊',a:'杜牧〔唐代〕',c:'篱东菊径深，折得自孤吟。雨中衣半湿，拥鼻自知心。'},
    {t:'折杨柳',a:'李白〔唐代〕',c:'垂杨拂绿水，摇艳东风年。\n花明玉关雪，叶暖金窗烟。\n美人结长想，对此心凄然。\n攀条折春色，远寄龙庭前。'},
    {t:'折杨柳',a:'张九龄〔唐代〕',c:'纤纤折杨柳，持此寄情人。\n一枝何足贵，怜是故园春。\n迟景那能久，芳菲不及新。\n更愁征戍客，容鬓老边尘。'},
    {t:'折杨柳歌辞其二',a:'佚名〔隋代〕',c:'腹中愁不乐，愿作郎马鞭。出入擐郎臂，蹀座郎膝边。'},
    {t:'折杨柳歌辞五首',a:'佚名〔南北朝〕',c:'上马不捉鞭，反折杨柳枝。\n蹀座吹长笛，愁杀行客儿。\n腹中愁不乐，愿作郎马鞭。\n出入擐郎臂，蹀座郎膝边。\n放马两泉泽，忘不著连羁。\n担鞍逐马走，何见得马骑。\n遥看孟津河，杨柳郁婆娑。\n我是虏家儿，不解汉儿歌。\n健儿须快马，快马须健儿。\n跸跋黄尘下，然后别雄雌。'},
    {t:'折杨柳枝歌',a:'佚名〔隋代〕',c:'上马不捉鞭，反拗杨柳枝。\n下马吹长笛，愁杀行客儿。\n门前一株枣，岁岁不知老。\n阿婆不嫁女，那得孙儿抱。\n敕敕何力力，女子临窗织。\n不闻机杼声，只闻女叹息。\n问女何所思，问女何所忆。\n阿婆许嫁女，今年无消息。'},
    {t:'折枝花赠行',a:'元稹〔唐代〕',c:'樱桃花下送君时，一寸春心逐折枝。\n别后相思最多处，千株万片绕林垂。'},
    {t:'谪居悼往二首',a:'刘禹锡〔唐代〕',c:'邑邑何邑邑，长沙地卑湿。楼上叫春多，花前恨风急。\n猿愁肠断叫，鹤病翘趾立。牛衣独自眠，谁如仲卿泣。\n郁郁何郁郁，长安远如日。终日念乡关，燕来鸿复还。\n潘岳岁寒思，屈平憔悴颜。殷勤望归路，无雨即登山。'},
    {t:'谪居黔南十首',a:'黄庭坚〔宋代〕',c:'霜降水反壑，风落木归山。\n冉冉岁华晚，昆虫皆闭关。'},
    {t:'谪守睦州作',a:'范仲淹〔宋代〕',c:'重父必重母，正邦先正家。\n一心回主意，十口向天涯。\n铜虎思犹厚，鲈鱼味复佳。\n圣明何以报，殁齿愿无邪。'},
    {t:'鹧鸪天',a:'纳兰性德〔清代〕',c:'背立盈盈故作羞，手挪梅蕊打归头。欲将离恨寻郎说，待得郎归恨却休。\n云澹澹，水悠悠，一声横笛锁空楼。何时共泛春溪月，断岸垂杨一叶舟。'},
    {t:'鹧鸪天',a:'晏几道〔宋代〕',c:'晓日迎长岁岁同。太平箫鼓间歌钟。云高未有前村雪，梅小初开昨夜风。\n罗幕翠，锦筵红。钗头罗胜写宜冬。从今屈指春期近，莫使金尊对月空。'},
    {t:'鹧鸪天',a:'朱熹〔宋代〕',c:'已分江湖寄此生。长蓑短笠任阴晴。鸣桡细雨沧洲远，系舸斜阳画阁明。\n奇绝处，未忘情。几时还得去寻盟。江妃定许捐双佩，渔父何劳笑独醒。'},
    {t:'鹧鸪天',a:'黄庭坚〔宋代〕',c:'节去蜂愁蝶不知。晓庭环绕折残枝。自然今日人心别，未必秋香一夜衰。\n无闲事，即芳期。菊花须插满头归。宜将酩酊酬佳节，不用登临送落晖。'},
    {t:'鹧鸪天·碧藕花开水殿凉',a:'晏几道〔宋代〕',c:'碧藕花开水殿凉，万年枝外转红阳。升平歌管随天仗，祥瑞封章满御床。\n金掌露，玉炉香，岁华方共圣恩长。皇州又奏圜扉静，十样宫眉捧寿觞。'},
    {t:'鹧鸪天·别绪如丝睡不成',a:'纳兰性德〔清代〕',c:'别绪如丝睡不成，那堪孤枕梦边城。因听紫塞三更雨，却忆红楼半夜灯。\n书郑重，恨分明，天将愁味酿多情。起来呵手封题处，偏到鸳鸯两字冰。'},
    {t:'鹧鸪天·博山寺作',a:'辛弃疾〔宋代〕',c:'不向长安路上行。却教山寺厌间迎。味无味处求吾乐，材不材间过此生。\n宁作我，岂其卿。人间走遍却归耕。一松一竹真朋友，山鸟山花好弟兄。'},
    {t:'鹧鸪天·不寐',a:'辛弃疾〔宋代〕',c:'老病那堪岁月侵。霎时光景值千金。一生不负溪山债，百药难治书史淫。\n随巧拙，任浮沈。人无同处面如心。不妨旧事从头记，要写行藏入笑林。'},
    {t:'鹧鸪天·插脚红尘已是颠',a:'陆游〔宋代〕',c:'插脚红尘已是颠。更求平地上青天。新来有个生涯别，买断烟波不用钱。\n沽酒市，采菱船。醉听风雨拥蓑眠。三山老子真堪笑，见事迟来四十年。'},
    {t:'鹧鸪天·趁得东风汗漫游',a:'辛弃疾〔宋代〕',c:'趁得东风汗漫游。见他歌后怎生愁。事如芳草春长在，人似浮云影不留。\n眉黛敛，眼波流。十年薄幸谩扬州。明朝短棹轻衫梦，只在溪南罨画楼。'},
    {t:'鹧鸪天·楚女腰肢越女腮',a:'晏几道〔宋代〕',c:'楚女腰肢越女腮，粉圆双蕊髻中开。朱弦曲怨愁春尽，渌酒杯寒记夜来。\n新掷果，旧分钗，冶游音信隔章台。花间锦字空频寄，月底金鞍竟未回。'},
    {t:'鹧鸪天·吹破残烟入夜风',a:'柳永〔宋代〕',c:'吹破残烟入夜风。一轩明月上帘栊。因惊路远人还远，纵得心同寝未同。\n情脉脉，意忡忡。碧云归去认无踪。只应曾向前生里，爱把鸳鸯两处笼。'},
    {t:'鹧鸪天·代人赋',a:'辛弃疾〔宋代〕',c:'陌上柔桑破嫩芽，东邻蚕种已生些。平冈细草鸣黄犊，斜日寒林点暮鸦。\n山远近，路横斜，青旗沽酒有人家。城中桃李愁风雨，春在溪头荠菜花。'},
    {t:'鹧鸪天·当日佳期鹊误传',a:'晏几道〔宋代〕',c:'当日佳期鹊误传。至今犹作断肠仙。桥成汉渚星波外，人在鸾歌凤舞前。\n欢尽夜，别经年。别多欢少奈何天。情知此会无长计，咫尺凉蟾亦未圆。'},
    {t:'鹧鸪天·东阳道中',a:'辛弃疾〔宋代〕',c:'扑面征尘去路遥，香篝渐觉水沉销。山无重数周遭碧，花不知名分外娇。\n人历历，马萧萧，旌旗又过小红桥。愁边剩有相思句，摇断吟鞭碧玉梢。'},
    {t:'鹧鸪天·斗鸭池南夜不归',a:'晏几道〔宋代〕',c:'斗鸭池南夜不归。酒阑纨扇有琼诗。云随碧玉歌声转，雪绕红琼舞袖回。\n今感旧，欲沾衣。可怜人似水东西。回头满眼凄凉事，秋月春风岂得知。'},
    {t:'鹧鸪天·鹅湖归病起作',a:'辛弃疾〔宋代〕',c:'着意寻春懒便回。何如信步两时杯。山才好处行还倦，诗未成时雨早催。\n携竹杖，更芒鞋。朱朱粉粉野蒿开。谁家寒食归宁女，笑语柔桑陌上来。'},
    {t:'鹧鸪天·鹅湖寺道中',a:'辛弃疾〔宋代〕',c:'一榻清风殿影凉，涓涓流水响回廊。千章云木钩辀叫，十里溪风䎬稏香。\n冲急雨，趁斜阳，山园细路转微茫。倦途却被行人笑：只为林泉有底忙！'},
    {t:'鹧鸪天·发底青青无限春',a:'辛弃疾〔宋代〕',c:'发底青青无限春。落红飞雪谩前前。黄花也伴秋光老，何似尊前见在身。\n书万卷，笔如神。眼看同辈上青云。个中不许儿童会，只恐功名更逼人。'},
    {t:'鹧鸪天·和昌父',a:'辛弃疾〔宋代〕',c:'万事纷纷一笑中。渊明把菊对秋风。细看爽气今犹在，惟有南山一似翁。\n情味好，语言工。三贤高会古来同。谁知止酒停云老，独立斜阳数过鸿。'},
    {t:'鹧鸪天·黄沙道中',a:'辛弃疾〔宋代〕',c:'句里春风正剪裁。溪山一片画图开。轻鸥自趁虚船去，荒犬还迎野妇回。\n松共竹，翠成堆。要擎残雪斗疏梅。乱鸦毕竟无才思，时把琼瑶蹴下来。'},
    {t:'鹧鸪天·佳会',a:'晏几道〔宋代〕',c:'彩袖殷勤捧玉钟。当年拚却醉颜红。舞低杨柳楼心月，歌尽桃花扇底风。\n从别后，忆相逢。几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中。'},
    {t:'鹧鸪天·佳人',a:'苏轼〔宋代〕',c:'罗带双垂画不成。殢人娇态最轻盈。酥胸斜抱天边月，玉手轻弹水面冰。\n无限事，许多情。四弦丝竹苦丁宁。饶君拨尽相思调，待听梧桐叶落声。'},
    {t:'鹧鸪天·家住苍烟落照间',a:'陆游〔宋代〕',c:'家住苍烟落照间，丝毫尘事不相关。斟残玉瀣行穿竹，卷罢《黄庭》卧看山。\n贪啸傲，任衰残，不妨随处一开颜。元知造物心肠别，老却英雄似等闲！'},
    {t:'鹧鸪天·江槛',a:'朱熹〔宋代〕',c:'暮雨朝云不自怜。放教春涨绿诗天。只令画阁临无地，宿昔新诗满系船。\n青鸟外，白鸥前。几生香火旧因缘。酒阑山月移雕槛，歌罢江风拂玳筵。'},
    {t:'鹧鸪天·九日悲秋不到心',a:'晏几道〔宋代〕',c:'九日悲秋不到心。凤城歌管有花音。风凋碧柳愁眉淡，露染黄花笑靥深。\n初见雁，已闻砧。绮罗丛里胜登临。须教月户纤纤玉，细捧霞觞滟滟金。'},
    {t:'鹧鸪天·看尽巴山看蜀山',a:'陆游〔宋代〕',c:'看尽巴山看蜀山。子规江上过春残。惯眠古驿常安枕，熟听阳关不惨颜。\n慵服气，懒烧丹。不妨青鬓戏人间。秘传一字神仙诀，说与君知只是顽。'},
    {t:'鹧鸪天·懒向青门学种瓜',a:'陆游〔宋代〕',c:'懒向青门学种瓜，只将渔钓送年华。双双新燕飞春岸，片片轻鸥落晚沙。\n歌缥缈，舻呕哑，酒如清露鲊如花。逢人问道归何处，笑指船儿此是家。'},
    {t:'鹧鸪天·离恨',a:'纳兰性德〔清代〕',c:'背立盈盈故作羞，手挼梅蕊打来头。欲将离恨寻郎说，待得郎来恨却休。\n云淡淡，水悠悠。一声横笛锁空楼。何时共泛春溪月，断岸垂杨一叶舟。'},
    {t:'鹧鸪天·离豫章别司马汉章大监',a:'辛弃疾〔宋代〕',c:'聚散匆匆不偶然。二年遍历楚山川。但将痛饮酬风月，莫放离歌入管弦。\n萦绿带，点青钱，东湖春水碧连天。明朝放我东归去，后夜相思月满船。'},
    {t:'鹧鸪天·林断山明竹隐墙',a:'苏轼〔宋代〕',c:'林断山明竹隐墙。乱蝉衰草小池塘。翻空白鸟时时见，照水红蕖细细香。\n村舍外，古城旁。杖藜徐步转斜阳。殷勤昨夜三更雨，又得浮生一日凉。'},
    {t:'鹧鸪天·楼上谁将玉笛吹',a:'张炎〔宋代〕',c:'楼上谁将玉笛吹？山前水阔暝云低。劳劳燕子人千里，落落梨花雨一枝。\n修禊近，卖饧时。故乡惟有梦相随。夜来折得江头柳，不是苏堤也皱眉。'},
    {t:'鹧鸪天·绿橘梢头几点春',a:'晏几道〔宋代〕',c:'绿橘梢头几点春。似留香蕊送行人。明朝紫凤朝天路，十二重城五碧云。\n歌渐咽，酒初醺。尽将红泪湿湘裙。赣江西畔从今日，明月清风忆使君。'},
    {t:'鹧鸪天·梅蕊新妆桂叶眉',a:'晏几道〔宋代〕',c:'梅蕊新妆桂叶眉。小莲风韵出瑶池。云随绿水歌声转，雪绕红绡舞袖垂。\n伤别易，恨欢迟。惜无红锦为裁诗。行人莫便消魂去，汉渚星桥尚有期。'},
    {t:'鹧鸪天·明日独酌自嘲呈史应之',a:'黄庭坚〔宋代〕',c:'万事令人心骨寒。故人坟上土新干。淫坊酒肆狂居士，李下何妨也整冠。\n金作鼎，玉为餐。老来亦失少时欢。茱萸菊蕊年年事，十日还将九日看。'},
    {t:'鹧鸪天·陌上濛濛残絮飞',a:'晏几道〔宋代〕',c:'陌上濛濛残絮飞，杜鹃花里杜鹃啼。年年底事不归去，怨月愁烟长为谁。\n梅雨细，晓风微，倚楼人听欲沾衣。故园三度群花谢，曼倩天涯犹未归。'},
    {t:'鹧鸪天·莫殢春光花下游',a:'辛弃疾〔宋代〕',c:'莫殢春光花下游。便须准备落花愁。百年雨打风吹却，万事三平二满休。\n将扰扰，付悠悠。此生於世百无忧。新愁次第相抛舍，要伴春归天尽头。'},
    {t:'鹧鸪天·清颍尊前酒满衣',a:'晏几道〔宋代〕',c:'清颍尊前酒满衣。十年风月旧相知。凭谁细话当时事，肠断山长水远诗。\n金凤阙，玉龙墀。看君来换锦袍时。姮娥已有殷勤约，留著蟾宫第一枝。'},
    {t:'鹧鸪天·十里楼台倚翠微',a:'晏几道〔宋代〕',c:'十里楼台倚翠微。百花深处杜莺啼。殷勤自与行人语，不似流莺取次飞。\n惊梦觉，弄晴时。声声只道不如归。天涯岂是无归意，争奈归期未可期。'},
    {t:'鹧鸪天·手捻香笺忆小莲',a:'晏几道〔宋代〕',c:'手捻香笺忆小莲。欲将遗恨倩谁传。归来独卧逍遥夜，梦里相逢酩酊天。\n花易落，月难圆。只应花月似欢缘。秦筝算有心情在，试写离声入旧弦。'},
    {t:'鹧鸪天·守得莲开结伴游',a:'晏几道〔宋代〕',c:'守得莲开结伴游，约开萍叶上边舟。来时浦口云随棹，采罢江边月满楼。\n花不语，水空流，年年拚得为花愁。明朝万一西风动，争奈朱颜不耐秋。'},
    {t:'鹧鸪天·送廓之秋试',a:'辛弃疾〔宋代〕',c:'白苎新袍入嫩凉。春蚕食叶响收廊。禹门已准桃花浪，月殿先收桂子香。\n鹏北海，凤朝阳。又携书剑路茫茫。明年此日青云上，却笑人间举子忙。'},
    {t:'鹧鸪天·送欧阳国瑞入吴中',a:'辛弃疾〔宋代〕',c:'莫避春岖上马迟，春来未有不岖时。人情展转闲中看，客路崎岖倦后知。\n梅似雪，柳如丝。试听别语慰相思。短篷炊饮鲈鱼熟，除却松江枉费诗。'},
    {t:'鹧鸪天·送人',a:'辛弃疾〔宋代〕',c:'唱彻《阳关》泪未干，功名馀事且加餐。浮天水送无穷树，带雨云埋一半山。\n今古恨，几千般，只应离合是悲欢？江头未是风波恶，别有人间行路难！'},
    {t:'鹧鸪天·送叶梦锡·七之一',a:'陆游〔宋代〕',c:'家住东吴近帝乡。平生豪举少卢场。十千沽酒青楼上，百万呼卢锦瑟傍。\n身易老，恨难忘。尊前赢得是凄凉。君归为报京华旧，一事无成两鬓霜。'},
    {t:'鹧鸪天·送元济之归豫章',a:'辛弃疾〔宋代〕',c:'敧枕婆娑两鬓霜。起听檐溜碎喧江。那边玉筯销啼粉，这里车轮转别肠。\n诗酒社，水云乡。可堪醉墨几淋浪。画图恰似归家梦，千里河山寸许长。'},
    {t:'鹧鸪天·汤泛冰瓷一坐春',a:'黄庭坚〔宋代〕',c:'汤泛冰瓷一坐春。长松林下得成根。吉祥老子亲拈出，个个教成百岁人。灯焰焰，酒醺醺。壑源曾未醒酲魂。与君更把长生碗，聊为清歌驻白云。'},
    {t:'鹧鸪天·题破香笺小砑红',a:'晏几道〔宋代〕',c:'题破香笺小砑红。诗篇多寄旧相逢。西楼酒面垂垂雪，南苑春衫细细风。\n花不尽，柳无穷。别来欢事少人同。凭谁问取归云信，今在巫山第几峰。'},
    {t:'鹧鸪天·晚岁躬耕不怨贫',a:'辛弃疾〔宋代〕',c:'读渊明诗不能去手，戏作小词以送\n晚岁躬耕不怨贫，只鸡斗酒聚比邻。都无晋宋之间事，自是羲皇以上人。\n千载后，百篇存，更无一字不清真。若教王谢诸郎在，未抵柴桑陌上尘！'},
    {t:'鹧鸪天·吴子似过秋水',a:'辛弃疾〔宋代〕',c:'秋水长廊水石间。有谁来共听潺湲。羡君人物东西晋，分我诗名大小山。\n穷自乐，懒方闲。人间路窄酒杯宽。看君不了痴儿事，又似风流靖长官。'},
    {t:'鹧鸪天·戏题村舍',a:'辛弃疾〔宋代〕',c:'鸡鸭成群晚不收，桑麻长过屋山头。有何不可吾方羡，要底都无饱便休。\n新柳树，旧沙洲，去年溪打那边流。自言此地生儿女，不嫁余家即聘周。'},
    {t:'鹧鸪天·小令尊前见玉箫',a:'晏几道〔宋代〕',c:'小令尊前见玉箫。银灯一曲太妖娆。歌中醉倒谁能恨，唱罢归来酒未消。\n春悄悄，夜迢迢。碧云天共楚宫遥。梦魂惯得无拘检，又踏杨花过谢桥。'},
    {t:'鹧鸪天·寻菊花无有戏作',a:'辛弃疾〔宋代〕',c:'掩鼻人间臭腐场，古来惟有酒今香。自从来住云烟畔，直到而今歌舞忙。\n呼老伴，共秋光。黄花何处避重阳？要知烂熳开时节，直待西风一夜霜。'},
    {t:'鹧鸪天·一醉醒来春又残',a:'晏几道〔宋代〕',c:'一醉醒来春又残。野棠梨雨泪阑干。玉笙声里鸾空怨，罗幕香中燕未还。\n终易散，且长闲。莫教离恨损朱颜。谁堪共展鸳鸯锦，同过西楼此夜寒。'},
    {t:'鹧鸪天·游鹅湖醉书酒家壁',a:'辛弃疾〔宋代〕',c:'春入平原荠菜花，新耕雨后落群鸦。多情白发春无奈，晚日青帘酒易赊。\n闲意态，细生涯。牛栏西畔有桑麻。青裙缟袂谁家女，去趁蚕生看外家。'},
    {t:'鹧鸪天·欲上高楼去避愁',a:'辛弃疾〔宋代〕',c:'欲上高楼去避愁，愁还随我上高楼。经行几处江山改，多少亲朋尽白头。\n归休去，去归休。不成人总要封侯？浮云出处元无定，得似浮云也自由。'},
    {t:'鹧鸪天·月满蓬壶灿烂灯',a:'佚名〔宋代〕',c:'月满蓬壶灿烂灯，与郎携手至端门。贪看鹤阵笙歌举，不觉鸳鸯失却群。\n天渐晓，感皇恩。传宣赐酒饮杯巡。归家恐被翁姑责，窃取金杯作照凭。'},
    {t:'鹧鸪天·枝上流莺和泪闻',a:'秦观〔宋代〕',c:'枝上流莺和泪闻，新啼痕间旧啼痕。一春鱼鸟无消息，千里关山劳梦魂。\n无一语，对芳尊。安排肠断到黄昏。甫能炙得灯儿了，雨打梨花深闭门。'},
    {t:'鹧鸪天·重九日集句',a:'黄庭坚〔宋代〕',c:'寒雁初来秋影寒。霜林风过叶声乾。龙山落帽千年事，我对西风犹整冠。\n兰委佩，菊堪餐。人情时事半悲欢。但将酩酊酬佳节，更把茱萸仔细看。'},
    {t:'鹧鸪天·重九席上再赋',a:'辛弃疾〔宋代〕',c:'有甚闲愁可皱眉。老怀无绪自伤悲。百年旋逐花阴转，万事长看鬓发知。\n溪上枕，竹间棋。怕寻酒伴懒吟诗。十分筋力夸强健，只比年时病起时。'},
    {t:'鹧鸪天·醉拍春衫惜旧香',a:'晏几道〔宋代〕',c:'醉拍春衫惜旧香。天将离恨恼疏狂。年年陌上生秋草，日日楼中到夕阳。\n云渺渺，水茫茫。征人归路许多长。相思本是无凭语，莫向花笺费泪行。'},
    {t:'鹧鸪天·樽俎风流有几人',a:'辛弃疾〔宋代〕',c:'樽俎风流有几人。当年未遇已心亲。金陵种柳欢娱地，庾岭逢梅寂寞滨。\n樽似海，笔如神。故人南北一般春。玉人好把新妆样，淡画眉儿浅注唇。'},
    {t:'贞女峡',a:'韩愈〔唐代〕',c:'江盘峡束春湍豪，雷风战斗鱼龙逃。\n悬流轰轰射水府，一泻百里翻云涛。\n漂船摆石万瓦裂，咫尺性命轻鸿毛。'},
    {t:'珍珠令',a:'张炎〔宋代〕',c:'桃花扇底歌声杳。愁多少。便觉道花阴闲了。因甚不归来，甚归来不早。\n满院飞花休要扫。待留与、薄情知道。怕一似飞花，和春都老。'},
    {t:'浈阳峡',a:'张九龄〔唐代〕',c:'行舟傍越岑，窈窕越溪深。水暗先秋冷，山晴当昼阴。\n重林间五色，对壁耸千寻。惜此生遐远，谁知造化心。'},
    {t:'真兴寺阁',a:'苏轼〔宋代〕',c:'山川高城郭，漠漠同一形。\n市人高鸦鹊，浩浩同一声。\n此阁几何高，何人之所营。\n侧身送落日，引山攀飞星。\n当年王中令，斫木南山赪。\n写真留阁下，铁面眼有棱。\n身强八九尺，高阁两峥嵘。\n古人虽暴恣，作事今世惊。\n登者尚呀喘，作者何以胜。\n曷不观此阁，其人勇且英。'},
    {t:'真州驿',a:'文天祥〔宋代〕',c:'山川如识我，故旧更无人。\n俯仰干戈迹，往来车马尘。\n英雄遗算晚，天地暗愁新。\n北首燕山路，凄凉夜向晨。'},
    {t:'真珠帘·梨花',a:'张炎〔宋代〕',c:'绿房几夜迎清晓，光摇动、素月溶溶如水。惆怅一株寒，记东阑闲倚。近日花边无旧雨，便寂寞、何曾吹泪。烛外。谩羞得红妆，而今犹睡。\n琪树皎立风前，万尘空、独挹飘然清气。雅淡不成娇，拥玲珑春意。落寞云深诗梦浅，但一似、唐昌宫里。元是。是分明错认，当时玉蕊。'},
    {t:'真珠帘·云深别有深庭宇',a:'张炎〔宋代〕',c:'云深别有深庭宇。小帘栊、占取芳菲多处。花暗水房春，润几番酥雨。见说苏堤晴未稳，便懒趁、踏青人去。休去。且料理琴书，夷犹今古。\n谁见静里闲心，纵荷衣未葺，雪巢堪赋。醉醒一乾坤，任此情何许。茂树石床同坐久，又却被、清风留住。欲住。奈帘影妆楼，翦灯人语。'},
    {t:'枕上作',a:'陆游〔宋代〕',c:'萧萧白发卧扁舟，死尽中朝旧辈流。\n万里关河孤枕梦，五更风雨四山秋。\n郑虔自笑穷耽酒，李广何妨老不侯。\n犹有少年风味在，吴笺著句写清愁。'},
    {t:'镇江之战第十八',a:'文天祥〔宋代〕',c:'海胡舶千艘，肉食三十万。\n江平不肯流，到今有遗恨。'},
    {t:'镇州初归',a:'韩愈〔唐代〕',c:'别来杨柳街头树，摆弄春风只欲飞。\n还有小园桃李在，留花不发待郎归。'},
    {t:'镇州路上谨酬裴司空相公重见寄',a:'韩愈〔唐代〕',c:'衔命山东抚乱师，日驰三百自嫌迟。\n风霜满面无人识，何处如今更有诗。'},
    {t:'征部乐·雅欢幽会',a:'柳永〔宋代〕',c:'雅欢幽会，良辰可惜虚抛掷。每夕念、狂踪旧迹。长祗恁、愁闷朝夕。凭谁去、花衢觅。细说此中端苦。道向我、转觉厌厌，役梦劳魂苦相忆。\n须知最有，风前月下，心事始终难得。但愿我、虫虫心下，把人看待，长似初相识。况渐逢春色。便是有，举场消息。待这回、好好怜伊，更不轻离拆。'},
    {t:'征夫',a:'杜甫〔唐代〕',c:'十室几人在？千山空自多！\n路衢惟见哭，城市不闻歌。\n漂梗无安地，衔枚有荷戈。\n官军未通蜀，吾道竟如何？'},
    {t:'征妇怨',a:'孟郊〔唐代〕',c:'良人昨日去，明月又不圆。别时巾有泪，零落青楼前。\n君泪濡罗巾，妾泪满路尘。罗巾长在手，今车随妾身。\n路尘如车风，车上君车轮。\n渔阳千里道，近如中门限。中门逾有时，渔阳长在眼。\n生在绿罗下，不识渔阳道。良人自戍来，夜夜梦中到。'},
    {t:'征妇怨',a:'张籍〔唐代〕',c:'九月匈奴杀边将，汉军全没辽水上。\n万里无人收白骨，家家城下招魂葬。\n妇人依倚子与夫，同居贫贱心亦舒。\n夫死战场子在腹，妾身虽存如昼烛。'},
    {t:'征西将',a:'张籍〔唐代〕',c:'黄沙北风起，半夜又翻营。战马雪中宿，探人冰上行。\n深山旗未展，阴碛鼓无声。几道征西将，同收碎叶城。'},
    {t:'征招·答仇山村见寄',a:'张炎〔宋代〕',c:'可怜张绪门前柳，相看顿非年游。三径已荒凉，更如今怀抱。薄游浑是感，满烟水、东风残照。古洛谁弹，古音谁赏，岁华空老。\n京洛染缁尘，悠然意，独对南山一笑。只在此山中，甚相逢不早。瘦吟心共苦，知几度、翦灯窗小。何时更、听雨巴山，赋草池春晓。'},
    {t:'筝',a:'白居易〔唐代〕',c:'云髻飘萧绿，花颜旖旎红。双眸剪秋水，十指剥春葱。\n楚艳为门阀，秦声是女工。甲明银玓瓅，柱触玉玲珑。\n猿苦啼嫌月，莺娇语妮风。移愁来手底，送恨入弦中。\n赵瑟清相似，胡琴闹不同。慢弹回断雁，急奏转飞蓬。\n霜珮锵还委，冰泉咽复通。珠联千拍碎，刀截一声终。\n倚丽精神定，矜能意态融。歇时情不断，休去思无穷。\n灯下青春夜，尊前白首翁。且听应得在，老耳未多聋。'},
    {t:'筝',a:'元稹〔唐代〕',c:'莫愁私地爱王昌，夜夜筝声怨隔墙。火凤有凰求不得，\n春莺无伴啭空长。急挥舞破催飞燕，慢逐歌词弄小娘。\n死恨相如新索妇，枉将心力为他狂。'},
    {t:'正初奉酬歙州刺史邢群',a:'杜牧〔唐代〕',c:'翠岩千尺倚溪斜，曾得严光作见家。\n越嶂远分丁字水，腊梅迟见二年花。\n明时刀尺君须用，幽处田园我有涯。\n一壑风烟阳羡里，解龟休去路非赊。'},
    {t:'正见寺晓别生公',a:'温庭筠〔唐代〕',c:'清晓盥秋水，高窗留夕阴。初阳到古寺，宿鸟起寒林。\n香火有良愿，宦名非素心。灵山缘未绝，他日重来寻。'},
    {t:'正月崇让宅',a:'李商隐〔唐代〕',c:'密锁重关掩绿苔，廊深阁迥此徘徊。\n先知风起月含晕，尚自露寒花未开。\n蝙拂帘旌终展转，鼠翻窗网小惊猜。\n背灯独共馀香语，不觉犹歌起夜来。'},
    {t:'正月将晦繁星满天',a:'杨万里〔宋代〕',c:'兔冷蟾寒不出时，群仙无睡尚游嬉。\n可怜深夜无灯火，碧玉枰前暗著棋。'},
    {t:'正月三日闲行',a:'白居易〔唐代〕',c:'黄鹂巷口莺欲语，乌鹊河头冰欲销。\n绿浪东西南北水，红栏三百九十桥。\n鸳鸯荡漾双双翅，杨柳交加万万条。\n借问春风来早晚，只从前日到今朝。'},
    {t:'正月十八夜',a:'晏殊〔宋代〕',c:'槿户茅斋雅自便，京华风味入条年。\n楼台冷落收灯夜，门巷萧条扫雪天。\n疾酒不闻花外漏，放朝仍得日高眠。\n何妨静习间中趣，欲问林僧结净缘。'},
    {t:'正月十九日京邑上元收灯日',a:'晏殊〔宋代〕',c:'星逐绮罗沉曙色，月随丝管下层台。\n千蹄万轂无寻处，祇似华胥一梦回。'},
    {t:'正月十五夜闻京有灯恨不得观',a:'李商隐〔唐代〕',c:'月色灯山满帝都，香车宝辇隘通衢。\n身闲不睹中兴盛，羞逐乡人赛紫姑。'},
    {t:'郑驸马宅宴洞中',a:'杜甫〔唐代〕',c:'主家阴洞细烟雾，留客夏簟清琅玕。\n春酒杯浓琥珀薄，冰浆碗碧玛瑙寒。\n误疑茅堂过江麓，已入风磴霾云端。\n自是秦楼压郑谷，时闻杂佩声珊珊。'},
    {t:'郑瓘协律',a:'杜牧〔唐代〕',c:'广文遗韵留樗散，鸡犬图书共一船。\n自说江湖不归事，阻风中酒过年年。'},
    {t:'郑果州相过',a:'王维〔唐代〕',c:'丽日照残春，初晴草木新。\n床前磨镜客，树下灌园人。\n五马惊穷巷，双童逐老身。\n中厨办粗饭，当恕阮家贫。'},
    {t:'郑霍二山人',a:'王维〔唐代〕',c:'翩翩繁华子，多出金张门。\n幸有学丘业，早蒙明主恩。\n童年且未学，肉食骛华轩。\n岂知中林士，无丘荐至尊。\n郑公老泉石，霍子安丘樊。\n卖药不二价，著书盈万言。\n息阴无恶木，饮水必清源。\n吾贱不及议，斯丘竟谁论。'},
    {t:'郑群赠簟',a:'韩愈〔唐代〕',c:'蕲州笛竹天下知，郑君所宝尤瑰奇。携来当昼不得卧，\n一府传看黄琉璃。体坚色净又藏节，尽眼凝滑无瑕疵。\n法曹贫贱众所易，腰腹空大何能为，自从五月困暑湿，\n如坐深甑遭蒸炊。手磨袖拂心语口，慢肤多汗真相宜。\n日暮归来独惆怅，有卖直欲倾家资。谁谓故人知我意，\n卷送八尺含风漪。呼奴扫地铺未了，光彩照耀惊童儿。\n青蝇侧翅蚤虱避，肃肃疑有清飙吹。倒身甘寝百疾愈，\n却愿天日恒炎曦。明珠青玉不足报，赠子相好无时衰。'},
    {t:'郑容全成蛟形木机歌',a:'皎然〔唐代〕',c:'万物贵天然，天然不可得。浑朴欲劳剞劂工，\n幽姿自可蛟龙质。欲腾未去何翩翩，扬袂争前谁是拂。\n可中风雨一朝至，还应不是池中物。苍山万重采一枝，\n形如器车生意奇。风号雨喷心不折，众木千丛君独知。\n高人心，多越格。有时就月吟春风，持来座右惊神客。\n爱君开閤江之滨，白云黄鹤长相亲。南郭子綦我不识，\n非君独是是何人。'},
    {t:'郑县宿陶太公馆中赠冯六元二',a:'王昌龄〔唐代〕',c:'儒有轻王侯，脱略当世务。本家耕田下，非为渔弋故。\n无何困躬耕，且欲驰永路。幽居与君近，出秋同所骛。\n昨日辞石门，五年变秋露。云龙未相感，干谒亦已屡。\n子为黄绶羁，余忝蓬山顾。京门望西岳，百里见郊树。\n飞雨祠上来，霭然关中暮。驱车郑城宿，秉烛论往素。\n山月出华阴，开此河渚雾。清光比故人，豁达展心晤。\n冯公尚戢翼，元子仍跼步。拂衣易为高，沦迹难有趣。\n张范善终始，吾等岂不慕。罢酒当凉风，屈伸备冥数。'},
    {t:'之德化宿剧头铺夜闻杜宇',a:'朱熹〔宋代〕',c:'王事贤劳只自嗤，一官今是五年期。如何独宿荒山夜，更拥寒衾听子规。'},
    {t:'之广陵宿常二南郭幽居',a:'李白〔唐代〕',c:'绿水接柴门，有如桃花源。\n忘忧来假草，满院罗丛萱。\n暝色湖上来，微雨飞南轩。\n故人宿茅宇，夕鸟栖杨园。\n还惜诗酒别，深为江海言。\n明朝广陵道，独忆此倾樽。'},
    {t:'芝山寺',a:'范仲淹〔宋代〕',c:'楼殿观崔嵬，灵芝安在哉。云飞过江去，花落入城来。\n得食鸦朝聚，闻经虎夜回。偶临西阁望，五老夕阳开。'},
    {t:'芝朮歌',a:'周邦彦〔宋代〕',c:'华阳之天诸洞府，阿穴便门迷空所。三君谒帝不知还，帐冷祠空遗鹤羽。\n玉津宝气久成腴，灵明神芝时出土。日精潜烛山自明，人力穷搜神不与。\n前年栋挠作新宫，坎坎空岩响斤斧。君来胎禽舞海雪，君去山云杂川雨。\n是生朱草示尘寰，故遣樵青入林莽。檗膏紫漆自坚栗，下附天苏蟠石坞。\n肉人但恐奇祸作，药笼复忧神物取。庐陵太守蕴仙风，健骨清姿欲飞举。\n阴功除瘼民已悦，灵药引年天亦许。愿因服饵断膏粱，未让南华养生主。'},
    {t:'知音者诚希',a:'韩愈〔唐代〕',c:'知音者诚希，念子不能别。\n行行天未晓，携手踏明月。'},
    {t:'织妇词',a:'元稹〔唐代〕',c:'织妇何太忙，征经三卧行欲老。\n征神女圣早成丝，今年丝税抽征早。\n早征非是官人恶，去岁官将事戎索。\n征人战苦束刀疮，主将勋高换罗幕。\n缫丝织帛犹努力，变缉撩机苦难织。\n东将头白双女儿，为解挑纹嫁不得。\n檐前袅袅游丝上，上有蜘蛛巧来往。\n羡他虫豸解缘天，能向虚空织罗网。'},
    {t:'织妇辞',a:'孟郊〔唐代〕',c:'夫是田中郎，妾是田中女。\n当年嫁得君，为君秉机杼。\n筋力日已疲，不息窗下机。\n如何织纨素，自著蓝缕衣。\n官家榜村路，更索栽桑树。'},
    {t:'织锦词',a:'温庭筠〔唐代〕',c:'丁东细漏侵琼瑟，影转高梧月初出。\n簇簌金梭万缕红，鸳鸯艳锦初成匹。\n锦中百结皆同心，蕊乱云盘相间深。\n此意欲传传不得，玫瑰作柱朱弦琴。\n为君裁破合欢被，星斗迢迢共千里。\n象尺熏炉未觉秋，碧池已有新莲子。'},
    {t:'栀子花',a:'杨万里〔宋代〕',c:'树恰人来短，花将雪样年。\n孤姿妍外净，幽馥暑中寒。\n有朵篸瓶子，无风忽鼻端。\n如何山谷老，只为赋山矾。'},
    {t:'蜘蛛讽',a:'孟郊〔唐代〕',c:'万类皆有性，各各禀天和。蚕身与汝身，汝身何太讹。\n蚕身不为己，汝身不为佗。蚕丝为衣裳，汝丝为网罗。\n济物几无功，害物日已多。百虫虽切恨，其将奈尔何。'},
    {t:'直中书省',a:'白居易〔唐代〕',c:'丝纶阁下文书静，钟鼓楼中刻漏长。\n独坐黄昏谁是伴，紫薇花对紫微郎。'},
    {t:'植灵寿木',a:'柳宗元〔唐代〕',c:'白华鉴寒水，怡我适野情。\n前趋朽长老，重复欣嘉名。\n蹇连易衰朽，方刚谢经营。\n敢期齿杖赐？聊舒移孤茎。\n丛萼中竞秀，分房处舒英。\n柔条乍反植，劲节常对生。\n循玩足忘疲，稍觉步武轻。\n安能事翦伐，持用资徒行。'},
    {t:'止酒',a:'陶渊明〔魏晋〕',c:'居止次城邑，逍遥自闲止。\n坐止葵荫下，步止荜门里。\n好味止园葵，大懽止稚子。\n平生不止能，止能情无喜。\n暮止不安寝，晨止不能起。\n日日欲止之，营卫止不理。\n徒知止不乐，未知止利己。\n始觉止为善，今朝真止矣。\n从此一止去，将止扶桑涘。\n清颜止宿容，奚止千万祀。'},
    {t:'徵招',a:'张炎〔宋代〕',c:'秋风吹碎江南树，石床自听流水。别鹤不归来，引悲风千里。馀音犹在耳。有谁识、醉翁深意。去国情怀，草枯沙远，尚鸣山鬼。客里。可消忧，人间世、寥寥几年无此。杏老古坛荒，把凄凉空指。心尘聊更洗。傍何处、竹边松底。共良夜，白月纷纷，领一天清气。'},
    {t:'至大梁却寄匡城主人',a:'岑参〔唐代〕',c:'一从弃鱼钓，十载干明王。\n无由谒天阶，却欲归沧浪。\n仲秋至东郡，遂见天雨霜。\n昨夜梦故山，蕙草色已黄。\n平明辞铁丘，薄暮游大梁。\n仲秋萧条景，拔剌飞鹅鶬。\n四郊阴气闭，万里无晶光。\n长风吹白茅，野火烧枯桑。\n故人南燕吏，籍籍名更香。\n聊以玉壶赠，置之君子堂。'},
    {t:'至福安第六十二',a:'文天祥〔宋代〕',c:'握节汉臣回，麻鞋见天子。\n感激动四极，壮士泪如雨。'},
    {t:'至后',a:'杜甫〔唐代〕',c:'冬至至后日初长，远在剑南思洛阳。\n青袍白马有何意，金谷铜驼非故乡。\n梅花欲开不自觉，棣萼一别永相望。\n愁极本凭诗遣兴，诗成吟咏转凄凉。'},
    {t:'至滑州隔河望黎阳忆丁三寓',a:'王维〔唐代〕',c:'隔河见桑柘，蔼蔼黎阳川。\n望望行渐远，孤峰没云烟。\n故人不可见，河水复悠然。\n赖有政声远，时闻行路传。'},
    {t:'至南安军第七十八',a:'文天祥〔宋代〕',c:'短日行梅岭，天门郁嵯峨。\n江西万里船，归期无柰何。'},
    {t:'至南陵答皇甫岳',a:'王昌龄〔唐代〕',c:'与君同病复漂沦，昨夜宣城别故人。\n明主恩深非岁久，长江还共五溪滨。'},
    {t:'至扬州',a:'文天祥〔宋代〕',c:'颠崖一陷落千寻，奴仆偏生负主心。\n饥火相煎疲欲绝，满山荒草晓沉沉。'},
    {t:'炙蒸饼',a:'杨万里〔宋代〕',c:'圆莹僧何矮，清松絮尔轻。\n削成琼叶片，嚼作雪花声。\n炙手三家市，焦头五鼎烹。\n老夫饥欲死，女辈且同行。'},
    {t:'致酒行',a:'李贺〔唐代〕',c:'零落栖迟一杯酒，主人奉觞客长寿。\n主父西游困不归，家人折断门前柳。\n吾闻马周昔作新丰客，天荒地老无人识。\n空将笺上两行书，直犯龙颜请恩泽。\n我有迷魂招不得，雄鸡一声天下白。\n少年心事当拏云，谁念幽寒坐呜呃。'},
    {t:'智度师二首',a:'元稹〔唐代〕',c:'四十年前马上飞，功名藏尽拥禅衣。\n石榴园下擒生处，独自闲行独自归。\n三陷思明三突围，铁衣抛尽衲禅衣。\n天津桥上无人识，闲凭栏干望落晖。'},
    {t:'滞雨',a:'李商隐〔唐代〕',c:'滞雨长安夜，残灯独客愁。\n故乡云水地，归梦不宜秋。'},
    {t:'雉朝飞',a:'李白〔唐代〕',c:'麦陇青青三月时，白雉朝飞挟两雌。\n锦衣绣翼何离褷，犊牧采薪感之悲。\n春天和，白日暖。\n啄食饮泉勇气满，争雄斗死绣颈断。\n雉子班奏急管弦，倾心酒美尽玉碗。\n枯杨枯杨尔生稊，我独七十而孤栖。\n弹弦写恨意不尽，瞑目归黄泥。'},
    {t:'雉带箭',a:'韩愈〔唐代〕',c:'原头火烧静兀兀，野雉畏鹰出复没。\n将军欲以巧伏人，盘马弯弓惜不发。\n地形渐窄观者多，雉惊弓满劲箭加。\n冲人决起百余尺，红翎白镞随倾斜。\n将军仰笑军吏贺，五色离披马前堕。'},
    {t:'雉子班',a:'佚名〔两汉〕',c:'雉子，班如此。之于雉梁。无以吾翁孺，雉子。知得雉子高蜚止，黄鹄蜚，之以千里，王可思。雄来蜚从雌，视子趋一雉。雉子，车大驾马滕，被王送行所中。尧羊蜚从王孙行。'},
    {t:'稚子弄冰',a:'杨万里〔宋代〕',c:'稚子金盆脱晓冰，彩丝穿取当银钲。\n敲成玉磬穿林响，忽作玻璃碎地声。'},
    {t:'中吕·迎仙客·七月',a:'佚名〔元代〕',c:'乞巧楼，月如钩，聚散几回银汉秋。遣人愁，何日休，织女牵牛，万古情依旧。'},
    {t:'中秋',a:'文天祥〔宋代〕',c:'不教收骨瘴江边，驱向胡沙着去鞭。\n旧夺宫袍空独步，新食宫饭饱孤眠。\n客程恰与秋天半，人影何如月倍圆。\n犹是江南佳丽地，徘徊把酒看苍天。'},
    {t:'中秋口号',a:'秦观〔宋代〕',c:'云山檐楯接低空，公宴初开气吹葱。\n照海旌幢秋色里，激天鼓吹月明中。\n香槽旋滴珠千颗，歌扇惊围玉一丛。\n二十四桥人望处，台星正在广寒宫。'},
    {t:'中秋前二夕钓雪舟中静坐二首',a:'杨万里〔宋代〕',c:'月到南窗小半扉，无灯始觉室生辉。\n人间何处冰壶是？身在冰壶却道非。'},
    {t:'中秋玩月',a:'佚名〔五代〕',c:'团团离海角，渐渐入云衢。\n此夜一轮满，清光何处无！'},
    {t:'中秋与诸子果饮',a:'杨万里〔宋代〕',c:'几年今夕一番逢，千古何人此桂同？\n酒入银河波底月，笛吹玉桂树梢风。\n莫言秋色无多巧，净洗清光也费工。\n老子病来浑不饮，如何频报绿尊空。'},
    {t:'中秋月',a:'晏殊〔宋代〕',c:'三十六旬内，此时心赏并。\n中分九秋夜，占断百宵明。\n冷照兰闺澈，光含绮席清。\n谁知沧海曲，珠蚌最盈盈。'},
    {t:'中秋月',a:'晏殊〔宋代〕',c:'天时与人意，龃龉旧无疑。\n坐久翻遗恨，光来已后期。\n行云凝黛色，见跋费金枝。\n况复轮来夜，笙歌继夕曦。'},
    {t:'中秋月',a:'晏殊〔宋代〕',c:'十轮霜影转庭梧，此夕羁人独向隅。\n未必素娥无怅恨，玉蟾清冷桂花孤。'},
    {t:'中山孺子妾歌',a:'李白〔唐代〕',c:'中山孺子妾，特以色见珍。\n虽然不如延年妹，亦是当时绝世人。\n桃李出深井，花艳惊上春。\n一贵复一贱，关天岂由身。\n芙蓉老秋霜，团扇羞网尘。\n戚姬髡发入舂市，万古共悲辛。'},
    {t:'中书即事',a:'晏殊〔宋代〕',c:'惨惨高槐落，凄凄馀菊寒。\n粉墙多记墨，聊为拂尘看。'},
    {t:'中书令裴公挽歌词二首',a:'温庭筠〔唐代〕',c:'王俭风华首，萧何社稷臣。丹阳布衣客，莲渚白头人。\n铭勒燕山暮，碑沉汉水春。从今虚醉饱，无复污车茵。\n箭下妖星落，风前杀气回。国香荀令去，楼月庾公来。\n玉玺终无虑，金縢意不开。空嗟荐贤路，芳草满燕台。'},
    {t:'中途寄友人',a:'杜牧〔唐代〕',c:'道傍高木尽依依，落叶惊风路路飞。未到乡关闻早雁，\n独于客路授寒衣。烟霞旧想长相阻，书剑投人久不归。\n何日一名随事了，与君同采碧溪薇。'},
    {t:'中宵',a:'杜甫〔唐代〕',c:'西阁百寻馀，中宵步绮疏。\n飞星过水白，落月动沙虚。\n择木知幽鸟，潜波想巨鱼。\n亲朋满天地，兵甲少来书。'},
    {t:'中夜起望西园值月上',a:'柳宗元〔唐代〕',c:'觉闻繁露坠，开户临西园。\n寒月上东岭，泠泠疏竹根。\n石泉远逾响，山鸟时一喧。\n倚楹遂至旦，寂寞将何言。'},
    {t:'中元前一夕枕上偶成',a:'纳兰性德〔清代〕',c:'酒醒池塘耿不眠，帐纹漠漠隔弓烟。\n溪风到竹初疑雨，秋月如弓渐满弦。\n残梦远经吹角戍，明河长亘添衣天。\n哀蛩饯晓浑多事，也似严更古驿边。'},
    {t:'中元日午',a:'杨万里〔宋代〕',c:'雨余赤日尚如炊，亭午青阴不水移。\n蜂过无花绝粮道，蚁行有水遏归师。\n今朝道是中元节，天气过於初伏时。\n小圃追凉还得热，焚香清坐读唐诗。'},
    {t:'中元夜百花洲作',a:'范仲淹〔宋代〕',c:'南阳太守清狂发，未到中秋先赏月。\n百花洲里夜忘归，绿梧无声露光滑。\n天学碧海吐明珠，寒辉射空星斗疏。\n西楼下看人间世，莹然都在青玉壶。\n從来酷暑不可避，今夕凉生岂天意。\n一笛吹销万里云，主人高歌客大醉。\n客醉起舞逐我歌，弗舞弗歌如老何。'},
    {t:'中元雨中呈子晋',a:'朱熹〔宋代〕',c:'徂暑尚繁郁，大火空西流。兹辰喜佳节，凉雨忽惊秋。\n晼晚兰径滋，萧副庭树幽。炎气一以去，恢台逝不留。\n刀笔随事屏，尘嚣与心休。端居讽道言，焚香味真诹。\n子亦玩文史，及此同优游。'},
    {t:'中元作',a:'李商隐〔唐代〕',c:'绛节飘飖宫国来，中元朝拜上清回。羊权须得金条脱，\n温峤终虚玉镜台。曾省惊眠闻雨过，不知迷路为花开。\n有娀未抵瀛洲远，青雀如何鸩鸟媒。'},
    {t:'中原',a:'文天祥〔宋代〕',c:'中原方万里，明日是重阳。\n桑枣人家近，蓬蒿客路长。\n引弓虚射雁，失马为寻羊。\n见说今年旱，青青麦又秧。'},
    {t:'终南别业',a:'王维〔唐代〕',c:'中岁颇好道，晚家南山陲。\n兴来每独往，胜事空自知。\n行到水穷处，坐看云起时。\n偶然值林叟，谈笑无还期。'},
    {t:'终南东溪中作',a:'岑参〔唐代〕',c:'溪水碧于草，潺潺花底流。沙平堪濯足，石浅不胜舟。\n洗药朝与暮，钓鱼春复秋。兴来从所适，还欲向沧洲。'},
    {t:'终南秋雪',a:'刘禹锡〔唐代〕',c:'南岭见秋雪，千门生早寒。闲时驻马望，高处卷帘看。\n雾散琼枝出，日斜铅粉残。偏宜曲江上，倒影入清澜。'},
    {t:'终南山',a:'王维〔唐代〕',c:'太乙近天都，连山接海隅。\n白云回望合，青霭入看无。\n分野中峰变，阴晴众壑殊。\n欲投人处宿，隔水问樵夫。'},
    {t:'终南山双峰草堂作',a:'岑参〔唐代〕',c:'敛迹归山田，息心谢时辈。昼还草堂卧，但与双峰对。\n兴来恣佳游，事惬符胜概。著书高窗下，日夕见城内。\n曩为世人误，遂负平生爱。久与林壑辞，及来松杉大。\n偶兹近精庐，屡得名僧会。有时逐樵渔，尽日不冠带。\n崖口上新月，石门破苍霭。色向群木深，光摇一潭碎。\n缅怀郑生谷，颇忆严子濑。胜事犹可追，斯人邈千载。'},
    {t:'终南山下作',a:'孟郊〔唐代〕',c:'见此原野秀，始知造化偏。山村不假阴，流水自雨田。\n家家梯碧峰，门门锁青烟。因思蜕骨人，化作飞桂仙。'},
    {t:'钟山即事',a:'王安石〔宋代〕',c:'涧水无声绕竹流，竹西花草弄春柔。\n茅檐相对坐终日，一鸟不鸣山更幽。'},
    {t:'钟山晚步',a:'王安石〔宋代〕',c:'小雨轻风落楝花，细红如雪点平沙。\n槿篱竹屋江村路，时见宜城卖酒家。'},
    {t:'种白蘘荷',a:'柳宗元〔唐代〕',c:'皿虫化为疠，夷俗多所神。\n衔猜每腊毒，谋富不为仁。\n蔬果自远至，杯酒盈肆陈。\n言甘中必苦，何用知其真？\n华洁事外饰，尤病中州人。\n钱刀恐贾害，饥至益逡巡。\n窜伏常战栗，怀故逾悲辛。\n庶氏有嘉草，攻襘事久泯。\n炎帝垂灵编，言此殊足珍。\n崎驱乃有得，托以全余身。\n纷敷碧树阴，眄睐心所亲。'},
    {t:'种瓜',a:'韦应物〔唐代〕',c:'率性方卤莽，理生尤自疏。今年学种瓜，园圃多荒芜。\n众草同雨露，新苗独翳如。直以春窘迫，过时不得锄。\n田家笑枉费，日夕转空虚。信非吾侪事，且读古人书。'},
    {t:'种柳戏题',a:'柳宗元〔唐代〕',c:'柳州柳刺史，种柳柳江边。\n谈笑为故事，推移成昔年。\n垂阴当覆地，耸干会参天。\n好作思人树，惭无惠化传。'},
    {t:'种木槲花',a:'柳宗元〔唐代〕',c:'上苑年年占物华，飘零今日在天涯。\n只因长作龙城守，剩种庭前木槲花。'},
    {t:'种朮',a:'柳宗元〔唐代〕',c:'守闲事服饵，采朮东山阿。东山幽且阻，疲苶烦经过。\n戒徒劚灵根，封植閟天和。违尔涧底石，彻我庭中莎。\n土膏滋玄液，松露坠繁柯。南东自成亩，缭绕纷相罗。\n晨步佳色媚，夜眠幽气多。离忧苟可怡，孰能知其他。\n爨竹茹芳叶，宁虑瘵与瘥。留连树蕙辞，婉娩采薇歌。\n悟拙甘自足，激清愧同波。单豹且理内，高门复如何。'},
    {t:'种桃杏',a:'白居易〔唐代〕',c:'无论海角与天涯，大抵心安即是家。\n路远谁能念乡曲，年深兼欲忘京华。\n忠州且作三年计，种杏栽桃拟待花。'},
    {t:'种药',a:'韦应物〔唐代〕',c:'好读神农书，多识药草名。持缣购山客，移莳罗众英。\n不改幽涧色，宛如此地生。汲井既蒙泽，插楥亦扶倾。\n阴颖夕房敛，阳条夏花明。悦玩从兹始，日夕绕庭行。\n州民自寡讼，养闲非政成。'},
    {t:'种竹',a:'元稹〔唐代〕',c:'昔公怜我直，比之秋竹竿。\n秋来改相忆，种竹厅前看。\n失地颜色改，伤根枝叶残。\n清风犹淅淅，高幽空团团。\n鸣蝉聒暮景，跳蛙集幽阑。\n尘土复昼夜，梢云良独难。\n丹丘信云远，安得临仙坛。\n瘴江冬草绿，何人惊岁寒。\n可怜亭亭干，一一青琅玕。\n孤凤竟不至，坐伤时幽阑。'},
    {t:'仲夏归汉南园，寄京邑耆旧',a:'孟浩然〔唐代〕',c:'尝读高士传，最嘉陶征君。日耽者园趣，自谓羲皇人。\n予复何为者，栖栖徒问津。中年废丘壑，上老旅风尘。\n忠欲事明主，孝思侍老亲。归来当炎夏，耕稼不及春。\n扇枕北窗下，采芝南涧滨。因声谢同列，吾慕颍阳真。'},
    {t:'仲夏归汉南园寄京邑旧游①',a:'孟浩然〔唐代〕',c:'尝读高士传，最嘉陶徵君。②\n日耽田园趣，自谓羲皇人。③\n余复何为者，栖栖徒问津。\n中年废丘壑，上国旅风尘。④\n忠欲事明主，孝思侍老亲。\n归来当炎夏，耕稼不及春。⑤\n扇枕北窗下，采芝南涧滨。\n因声谢同列，吾慕颍阳真。⑥'},
    {t:'众人',a:'王安石〔宋代〕',c:'众人纷纷何足竞，是非吾喜非吾病。\n颂声交作莽岂贤，四国流言旦犹圣。\n唯圣人能轻重人，不能铢两为千钧。\n乃知轻重不在彼，要之美恶由吾身。'},
    {t:'重别李评事',a:'王昌龄〔唐代〕',c:'莫道秋江离别难，舟船明日是长安。\n吴姬缓舞留君醉，随意青枫白露寒。'},
    {t:'重别梦得',a:'柳宗元〔唐代〕',c:'二十年来万事同，今朝岐路忽西东。\n皇恩若许归田去，晚岁当为邻舍翁。'},
    {t:'重酬乐天',a:'元稹〔唐代〕',c:'红尘扰扰日西徂，我兴云心两共孤。暂出已遭千骑拥，\n故交求见一人无。百篇书判从饶白，八米诗章未伏卢。\n最笑近来黄叔度，自投名刺占陂湖。'},
    {t:'重酬李少府见赠',a:'孟浩然〔唐代〕',c:'养疾衡檐下，由来浩气真。\n五行将禁火，十步任寻春。\n致敬惟桑梓，邀欢即主人。\n回看后凋色，青翠有松筠。'},
    {t:'重酬苑郎中',a:'王维〔唐代〕',c:'何幸含香奉至尊，多惭未报主人恩。\n草木尽能酬雨露，荣枯安敢问乾坤。\n仙郎有意怜同舍，丞相无私断扫门。\n扬子解嘲徒自遣，冯唐已老复何论。'},
    {t:'重答柳柳州',a:'刘禹锡〔唐代〕',c:'弱冠同怀长者忧，临岐回想尽悠悠。\n耦耕若便遗身老，黄发相看万事休。'},
    {t:'重登科',a:'杜牧〔唐代〕',c:'星汉离宫月出轮，满街含笑绮罗春。\n花前每被青蛾问，何事重来只一人。'},
    {t:'重过圣女祠',a:'李商隐〔唐代〕',c:'白石岩扉碧藓滋，上清沦谪得归迟。\n一春梦雨常飘瓦，尽日灵风不满旗。\n萼绿华来无定所，杜兰香去未移时。\n玉郎会此通仙籍，忆向天阶问紫芝。'},
    {t:'重寄',a:'白居易〔唐代〕',c:'萧散弓惊雁，分飞剑化龙。\n悠悠天地内，不死会相逢。'},
    {t:'重将',a:'王安石〔宋代〕',c:'重将白发旁墙阴，陈迹茫然不可寻。\n花鸟总知春烂熳，人间独自有伤心。'},
    {t:'重联句一首',a:'皎然〔唐代〕',c:'刘令兴多常步履，柴桑事少但援琴。——皎然\n闲招法侣从山寺，每掇幽芳傍竹林。——皎然\n卷帘只爱荆峰色，入座偏宜郢客吟。——崔逵\n谁许近来轻印绶，因君昨日悟禅心。——崔逵'},
    {t:'重送鸿举师赴江陵谒马逢侍御',a:'刘禹锡〔唐代〕',c:'西北秋风凋蕙兰，洞庭波上碧云寒。\n茂陵才子江陵住，乞取新诗合掌看。'},
    {t:'重送绝句',a:'杜牧〔唐代〕',c:'绝艺如君天下少，闲人似我世间无。\n别后竹窗风雪夜，一灯明暗覆吴图。'},
    {t:'重午日戏书',a:'辛弃疾〔宋代〕',c:'青山吞吐古今月，绿树低昂朝暮风。\n万事有为应有尽，此身无我自无穷。'},
    {t:'重阳',a:'高适〔宋代〕',c:'节物惊心两鬓华，东离空绕未开花。\n百年将半仕三已，五亩就荒天一涯。\n岂有白衣来剥啄，一从乌帽自欹斜。\n真成独坐空搔首，门柳萧萧噪暮鸦。'},
    {t:'重阳',a:'文天祥〔宋代〕',c:'万里飘零两鬓蓬，故乡秋色老梧桐。\n雁栖新月江湖满，燕别斜阳巷陌空。\n落叶何心定流水，黄花无主更西风。\n乾坤遗恨知多少，前日龙山如梦中。'},
    {t:'重阳日至峡道',a:'张籍〔唐代〕',c:'无限青山行已尽，回看忽觉远离家。\n逢高欲饮重阳酒，山菊今朝未有花。'},
    {t:'重阳席上赋白菊',a:'白居易〔唐代〕',c:'满园花菊郁金黄，中有孤丛色似霜。\n还似今朝歌酒席，白头翁入少年场。'},
    {t:'重有感',a:'李商隐〔唐代〕',c:'玉帐牙旗得上游，安危须共主宜忧。\n窦融表已来关右，陶侃军宜次石头。\n岂有蛟龙愁失水，更无鹰隼与高秋！\n昼号夜哭兼幽显，早晚星关雪涕收？'},
    {t:'重赠',a:'元稹〔唐代〕',c:'休遣玲珑唱我诗，我诗多是别君词。\n明朝又向江头别，月落潮平是去时。'},
    {t:'重赠二首',a:'柳宗元〔唐代〕',c:'闻道将雏向墨池，刘家还有异人词。\n如今试遣隈墙问，已道世人那得知。\n世上悠悠不识真，姜芽尽是捧心人。\n若道柳家无子弟，往年何事乞西宾。'},
    {t:'重至衡阳伤柳仪曹',a:'刘禹锡〔唐代〕',c:'元和乙未岁，与故人柳子厚临湘水为别。柳浮舟适柳州，余登陆赴连州。后五年，余从故道出桂岭，至前别处，而君没于南中，因赋诗以投吊。\n忆昨与故人，湘江岸头别。\n我马映林嘶，君帆转山灭。\n马嘶循古道，帆灭如流电。\n千里江蓠春，故人今不见。'},
    {t:'舟次西径',a:'杨万里〔宋代〕',c:'夜来徐汊伴鸥眠，西径晨炊小泊船。\n芦荻渐多人渐少，鄱阳湖尾水如天。'},
    {t:'舟过安仁',a:'杨万里〔宋代〕',c:'一叶渔船两小童，收篙停棹坐船中。\n怪生无雨都张伞，不是遮头是使风。'},
    {t:'舟过安仁五首',a:'杨万里〔宋代〕',c:'初受遥山献画图，忽然卷去淡如无。\n莫欺老眼犹明在，和雾和烟数得渠。'},
    {t:'舟过谢潭三首·其二',a:'杨万里〔宋代〕',c:'夹江百里没人家，最苦江流曲更斜。\n岭草已青今岁叶，岸芦犹白去年花。'},
    {t:'舟过谢潭三首·其三',a:'杨万里〔宋代〕',c:'碧酒时倾一两杯，船门才闭又还开。\n好山万皱无人见，都被斜阳拈出来。'},
    {t:'舟过谢潭三首·其一',a:'杨万里〔宋代〕',c:'风头才北忽成南，转眼黄田到谢潭。\n仿佛一峰船外影，褰帏急看紫巉岩。'},
    {t:'舟行怀阎士和',a:'皎然〔唐代〕',c:'二月湖南春草遍，横山渡口花如霰。\n相思一日在孤舟，空见归云两三片。'},
    {t:'舟行寄李湖州',a:'张籍〔唐代〕',c:'客愁无次第，川路重辛勤。藻密行舟涩，湾多转楫频。\n薄游空感惠，失计自怜贫。赖有汀洲句，时时慰远人。'},
    {t:'舟夜即事',a:'王安石〔宋代〕',c:'火炬临遥岸，余光照客船。\n水明鱼中饵，沙暖鹭忘眠。\n感概无穷事，迟回欲晓天。\n山泉如有意，枕上送潺湲。'},
    {t:'舟中',a:'范仲淹〔宋代〕',c:'珠彩耀前川，归来一扣舷。\n微风不起浪，明月自随船。'},
    {t:'舟中读元九诗',a:'白居易〔唐代〕',c:'把君诗卷灯前读，诗尽灯残天未明。\n眼痛灭灯犹暗坐，逆风吹浪打船声。'},
    {t:'舟中对月',a:'陆游〔宋代〕',c:'百壶载酒游凌云，醉中挥袖别故人。\n依依向我不忍别，谁似峨嵋半轮月？\n月窥船窗挂凄冷，欲到渝州酒初醒。\n江空袅袅钓丝风，人静翩翩葛巾影。\n哦诗不睡月满船，清寒入骨我欲仙。\n人间更漏不到处，时有沙禽背船去。'},
    {t:'舟中晚赋',a:'朱熹〔宋代〕',c:'长风一万里，披豁暮云空。极浦三年梦，扁舟二子同。\n离离浮远树，杳杳没孤鸿。若问明朝事，西山晻霭中。'},
    {t:'舟中晚起',a:'白居易〔唐代〕',c:'日高犹掩水窗眠，枕簟清凉八月天。\n泊处或依沽酒店，宿时多伴钓鱼船。\n退身江海应无用，忧国朝廷自有贤。\n且向钱唐湖上去，冷吟闲醉二三年。'},
    {t:'舟中晓望',a:'孟浩然〔唐代〕',c:'挂席东南望，青山水国遥。\n舳舻争利涉，来往接风潮。\n问我今何适？天台访石桥。\n坐看霞色晓，疑是赤城标。'},
    {t:'舟中夜起',a:'苏轼〔宋代〕',c:'微风萧萧吹菰蒲，开门看雨月窜湖。\n舟人水鸟两同梦，大鱼惊窜如奔狐。\n夜深人物不相管，我蚓形影相嬉娱。\n暗潮生渚吊寒蚓，落月挂柳看悬蛛。\n此生忽忽忧患里，清境过眼能须臾。\n鸡鸣钟动百鸟散，船头击鼓还相呼。'},
    {t:'州桥',a:'王安石〔宋代〕',c:'州桥踏月想山椒，回首哀湍未觉遥。\n今夜重闻旧呜咽，却看山月话州桥。'},
    {t:'周苍崖入吾山作图诗赠之',a:'文天祥〔宋代〕',c:'三生石上结因缘，袍笏横斜学米颠。\n渔父几忘山下路，仙人时访岭头船。\n乌猿白鹤无根树，淡月疏星一线天。\n为我醉呼添蒙澒，倦来平卧看云烟。'},
    {t:'周长史昉画毗沙门天王歌',a:'皎然〔唐代〕',c:'在史画神独感神，高步区中无忽人。雅而逸，高且真，\n形生虚无忽可亲。降魔大戟缩在手，倚天在剑横诸绅。\n慈威示物虽凛凛，在德无秋唯有春。吾知真象本非色，\n此中妙用君心得。苟能下笔合神造，误点一点亦为道。\n写出霜缣可舒卷，何人应识此情远。秋斋清寂无外物，\n盥手焚香聊自展。忆昔胡兵围未解，感得此神天上下。\n至今云旗图我形，为君一顾烟尘清。'},
    {t:'昼居池上亭独吟',a:'刘禹锡〔唐代〕',c:'日午树阴正，独吟池上亭。\n静看蜂教诲，闲想鹤仪形。\n法酒调神气，清琴入性灵。\n浩然机已息，几杖复何铭。'},
    {t:'昼梦',a:'杜甫〔唐代〕',c:'二月饶睡昏昏然，不独夜短昼分眠。\n桃花气暖眼自醉，春渚日落梦相牵。\n故乡门巷荆棘底，中原君臣豺虎边。\n安得务农息战斗，普天无吏横索钱。'},
    {t:'昼夜乐·洞房记得初相遇',a:'柳永〔宋代〕',c:'洞房记得初相遇。便只合、长相聚。何期小会幽欢，变作离情别绪。况值阑珊春色暮，对满目、乱花狂絮。直恐好风光，尽随伊归去。\n一场寂寞凭谁诉。算前言、总轻负。早知恁地难拚，悔不当时留住。其奈风流端正外，更别有，系人心处。一日不思量，也攒眉千度。'},
    {t:'昼夜乐·秀香家住桃花径',a:'柳永〔宋代〕',c:'秀香家住桃花径。算神仙、才堪并。层波细翦明眸，腻玉圆搓素颈。爱把歌喉当筵逞。遏天边，乱云愁凝。言语似娇莺，一声声堪听。\n洞房饮散帘帏静。拥香衾、欢心称。金炉麝袅青烟，凤帐烛摇红影。无限狂心乘酒兴。这欢娱，渐入嘉境。犹自怨邻鸡，道秋宵不永。'},
    {t:'昼月',a:'韩愈〔唐代〕',c:'玉碗不磨著泥土，青天孔出白石补。兔入臼藏蛙缩肚，\n桂树枯株女闭户。阴为阳羞固自古，嗟汝下民或敢侮，\n戏嘲盗视汝目瞽。'},
    {t:'朱朝议移法云兰',a:'王安石〔宋代〕',c:'幽兰有佳气，千载閟山阿。\n不出阿兰若，岂遭乾闼婆。'},
    {t:'朱鹭',a:'佚名〔两汉〕',c:'朱鹭，鱼以乌。路訾邪鹭何食？食茄下。不之食，不以吐，将以问诛者。'},
    {t:'诸葛武侯',a:'王安石〔宋代〕',c:'汉日落西南，中原一星黄。\n群盗伺昏黑，联翩各飞扬。\n武侯当此时，龙卧独摧藏。\n掉头梁甫吟，羞与众争光。\n邂逅得所从，幅巾起南阳。\n崎岖巴汉间，屡以弱攻强。\n晖晖若长庚，孤出照一方。\n势欲起六龙，东回出扶桑。\n惜哉沦中路，怨者为悲伤。\n竖子祖余策，犹能走强梁。'},
    {t:'诸官游招隐寺',a:'王昌龄〔唐代〕',c:'山馆人已空，青萝换风雨。自从永明世，月向龙宫吐。\n凿井长幽泉，白云今如古。应真坐松柏，锡杖挂窗户。\n口云七十馀，能救诸有苦。回指岩树花，如闻道场鼓。\n金色身坏灭，真如性无主。僚友同一心，清光遣谁取。'},
    {t:'诸暨道中作',a:'范仲淹〔宋代〕',c:'林下提壶招客醉，溪边杜宇劝人归。\n可怜白酒青山在，不醉不归多少非。'},
    {t:'诸人共游周家墓柏下',a:'陶渊明〔魏晋〕',c:'今日天气佳，清吹与鸣弹。\n感彼柏下人，安得不为欢。\n清歌散新声，绿酒开芳颜。\n未知明日事，余襟良以殚。'},
    {t:'猪肉颂',a:'苏轼〔宋代〕',c:'净洗铛，少著水，柴头罨烟焰不起。待他自熟莫催他，火候足时他自美。黄州好猪肉，价贱如泥土。贵者不肯吃，贫者不解煮，早晨起来打两碗，饱得自家君莫管。'},
    {t:'竹',a:'李贺〔唐代〕',c:'入水文光动，抽空绿影春。\n露华生笋径，苔色拂霜根。\n织可承香汗，裁堪钓锦鳞。\n三梁曾入用，一节奉王孙。'},
    {t:'竹城',a:'周邦彦〔宋代〕',c:'竹城何檀乐，属翠分雉堞。\n王封尽四堑，同有岁寒节。'},
    {t:'竹簟',a:'元稹〔唐代〕',c:'竹簟衬重茵，未忍都令卷。忆昨初来日，看君自施展。'},
    {t:'竹间',a:'文天祥〔宋代〕',c:'倦来聊歇马，随分此青山。\n流水竹千个，清风沙一湾。\n乾坤醒醉里，身世有无间。\n客路真希绝，浮生半日闲。'},
    {t:'竹节滩',a:'朱熹〔宋代〕',c:'船下清江竹节滩，长烟漠漠水漫漫。人家断岸斜阳好，客子中流薄暮寒。'},
    {t:'竹里馆',a:'王维〔唐代〕',c:'独坐幽篁里，弹琴复长啸。\n深林人不知，明月来相照。'},
    {t:'竹马子·登孤垒荒凉',a:'柳永〔宋代〕',c:'登孤垒荒凉，危亭旷望，静临烟烦。对雌霓挂雨，雄风拂槛，微收烦暑。渐觉一叶惊秋，残蝉噪晚，非商时序。览景想前欢，指神京，非雾非烟深处。\n向此成追感，新愁易积，故人难聚。凭高尽日凝伫。赢得消魂无语。极目霁霭霏微，暝鸦零乱，萧索江城暮。南楼画角，又送残阳去。'},
    {t:'竹枝词二首',a:'黄庭坚〔宋代〕',c:'三峡猿声泪欲流，夔州竹枝解人愁。\n渠侬自有回天力，不学垂杨绕指柔。'},
    {t:'竹枝词二首·其二',a:'黄庭坚〔宋代〕',c:'撑崖拄谷蝮蛇愁，入箐攀天猿掉头。\n鬼门关外莫言远，五十三驿是皇州。'},
    {t:'竹枝词二首·其二',a:'刘禹锡〔唐代〕',c:'楚水巴山江雨多，巴人能唱本乡歌。\n今朝北客思归去，回入纥那披绿罗。'},
    {t:'竹枝词二首·其一',a:'刘禹锡〔唐代〕',c:'杨柳青青江水平，闻郎江上唱歌声。\n东边日出西边雨，道是无晴却有晴。'},
    {t:'竹枝词二首·其一',a:'黄庭坚〔宋代〕',c:'浮云一百八盘萦，落日四十八渡明。\n鬼门关外莫言远，四海一家皆弟兄。'},
    {t:'竹枝词九首·其八',a:'刘禹锡〔唐代〕',c:'巫峡苍苍烟雨时，清猿啼在最高枝。\n个里愁人肠自断，由来不是此声悲。'},
    {t:'竹枝词九首·其二',a:'刘禹锡〔唐代〕',c:'山桃红花满上头，蜀江春水拍山流。\n花红易衰似郎意，水流无限似侬愁。'},
    {t:'竹枝词九首·其九',a:'刘禹锡〔唐代〕',c:'山上层层桃李花，云间烟火是人家。\n银钏金钗来负水，长刀短笠去烧畲。'},
    {t:'竹枝词九首·其六',a:'刘禹锡〔唐代〕',c:'城西门前滟滪堆，年年波浪不能摧。\n懊恼人心不如石，少时东去复西来。'},
    {t:'竹枝词九首·其七',a:'刘禹锡〔唐代〕',c:'瞿塘嘈嘈十二滩，人言道路古来难。\n长恨人心不如水，等闲平地起波澜。'},
    {t:'竹枝词九首·其三',a:'刘禹锡〔唐代〕',c:'江上朱楼新雨晴，瀼西春水縠文生。\n桥东桥西好杨柳，人来人去唱歌行。'},
    {t:'竹枝词九首·其四',a:'刘禹锡〔唐代〕',c:'日出三竿春雾消，江头蜀客驻兰桡。\n凭寄狂夫书一纸，家住成都万里桥。'},
    {t:'竹枝词九首·其五',a:'刘禹锡〔唐代〕',c:'两岸山花似雪开，家家春酒满银杯。\n昭君坊中多女伴，永安宫外踏青来。'},
    {t:'竹枝词九首·其一',a:'刘禹锡〔唐代〕',c:'白帝城头春草生，白盐山下蜀江清。\n南人上来歌一曲，北人莫上动乡情。'},
    {t:'竹枝词四首',a:'白居易〔唐代〕',c:'瞿塘峡口水烟低，白帝城头月向西。\n唱到竹枝声咽处，寒猿闇鸟一时啼。\n竹枝苦怨怨何人？夜静山空歇又闻。\n蛮儿巴女齐声唱，愁杀江楼病使君。\n巴东船舫上巴西，波面风生雨脚齐。\n水蓼冷花红簇簇，江蓠湿叶碧凄凄。\n江畔谁人唱竹枝？前声断咽后声迟。\n怪来调苦缘词苦，多是通州司马诗。'},
    {t:'烛蛾',a:'孟郊〔唐代〕',c:'灯前双舞蛾，厌生何太切。\n想尔飞来心，恶明不恶灭。\n天若百尺高，应去掩明月。'},
    {t:'烛影摇红',a:'张炎〔宋代〕',c:'二三友行歌云舞绣中，亦清时之可乐，以词写之。\n舟舣鸥波，访邻寻里愁都散。老来犹似柳风流，先露看花眼。闲把花枝试拣。笑盈盈，和香待翦。也应回首，紫曲门荒，当年游惯。\n箫鼓黄昏，动人心处情无限。锦街不甚月明多，早已骄尘满。才过风柔夜暖。渐迤逦、芳程递趱。向西湖去，那里人家，依然莺燕。'},
    {t:'烛影摇红',a:'周邦彦〔宋代〕',c:'香脸轻匀，黛眉巧画宫妆淡。风是天付与精神，全在娇波转。\n早是萦心可惯。那更堪、频频顾盼。烛回得见，见了还休，争如不见。\n烛影摇红，夜阑饮散春宵短。当时谁解唱阳关，离恨天涯远。\n无奈云收雨散。凭阑干、东风泪眼。海棠开后，燕子来时，黄昏庭院。'},
    {t:'烛影摇红·答邵素心',a:'张炎〔宋代〕',c:'隔水呼舟，采香何处追游好。一年春事二分花，犹有花多少。\n容易繁华过了。趁园林、飞红未扫。旧酲新醉，几日不来，绿阴芳草。'},
    {t:'烛影摇红·芳脸匀红',a:'周邦彦〔宋代〕',c:'芳脸匀红，黛眉巧画宫妆浅。风是天付与精神，全在娇波眼。早是萦心可惯。向尊前、频频顾眄。烛回想见，见了还休，争如不见。\n烛影摇红，夜阑饮散春宵短。当时谁会唱阳关，离恨天涯远。争奈云收雨散。凭阑干、东风泪满。海棠开后，燕子来时，黄昏深院。'},
    {t:'烛影摇红·隔窗闻歌',a:'张炎〔宋代〕',c:'闲苑深迷，趁香随粉都行遍。隔窗花气暖扶春，只许莺莺占。烛焰晴烘醉脸。想东邻、偷窥笑眼。欲寻无处，暗掐新声，银屏斜掩。\n一片云闲，那知顾曲周郎怨。看花犹自未分明，毕竟何时见。已信仙缘较浅。谩凝思、风帘倒卷。出门一笑，月落江横，数峰天远。'},
    {t:'渚宫晚春寄秦地友人',a:'温庭筠〔唐代〕',c:'风华已眇然，独立思江天。凫雁野塘水，牛羊春草烟。\n秦原晓重叠，灞浪夜潺湲。今日思归客，愁容在镜悬。'},
    {t:'煮茶',a:'晏殊〔宋代〕',c:'稽山新茗绿如烟，静挈都蓝煮惠泉。\n未向人间杀风景，更持醪醑醉花前。'},
    {t:'杼山禅居寄赠东溪吴处士冯一首',a:'皎然〔唐代〕',c:'青云何润泽，下有贤人隐。路入菱湖深，迹与黄鹤近。\n野风吹白芷，山月摇清轸。诗祖吴叔庠，致君名不尽。\n身当青山秀，文体多郢声。澄澈湘水碧，泬寥楚山青。\n时人格不同，至今罕知名。昔贤敦师友，此道君独行。\n既得庐霍趣，乃高雷远情。别时春风多，扫尽雪山雪。\n为君中夜起，孤坐石上月。悠然遗尘想，邈矣达性说。\n故人不在兹，幽桂惜未结。'},
    {t:'驻马听·凤枕鸾帷',a:'柳永〔宋代〕',c:'凤枕鸾帷。二三载，如鱼似水相知。良天好景，深怜多爱，无非尽意依随。奈何伊。恣性灵、忒煞些儿。无事孜煎，万回千度，怎忍分离。\n而今渐行渐远，渐觉虽悔难追。漫寄消寄息，终久奚为。也拟重论缱绻，争奈翻覆思维。纵再会，只恐恩情，难似当时。'},
    {t:'驻舆遣人寻访后山陈德方家',a:'黄庭坚〔宋代〕',c:'江雨蒙蒙作小寒，雪飘五老发毛斑。\n城中咫尺云横栈，独立前山望后山。'},
    {t:'祝英台近·耕云',a:'张炎〔宋代〕',c:'占宽闲，锄浩渺。船舣水村悄。非雾非烟，生气覆瑶草。蒙茸数亩春阴，梦魂落寞，知踏碎、梨花多少。\n听孤啸。山浅种玉人归，缥缈度晴峭。鹤下芝田，五色散微照。笑他隔浦谁家，半江疏雨，空吟断、一犁清晓。'},
    {t:'祝英台近·寄陈直卿',a:'张炎〔宋代〕',c:'路重寻，门半掩、苔老旧时树。采药云深，童子更无语。怪他流水迢迢，湖天日暮，想只在、芦花多处。\n谩延伫。姓名题上芭蕉，凉夜未风雨。赋了秋声，还赋断肠句。几回独立长桥，扁舟欲唤，待招取、白鸥归去。'},
    {t:'祝英台近·水纵横',a:'辛弃疾〔宋代〕',c:'与客饮瓢泉，客以泉声喧静为问。余醉，未及答。或以“蝉噪林逾静”代对，意甚美矣。翌日为赋此词以褒之也。\n水纵横，山远近，拄杖占千顷。老眼羞明，水底看山影。度教水动山摇，吾生堪笑，似此个、青山无定。\n一瓢饮，人问“翁爱飞泉，来寻个中静；绕屋声喧，怎做静中镜”？“我眠君且归休，维摩方丈，待天女、散花时问。”'},
    {t:'祝英台近·题陆壶天水墨兰石',a:'张炎〔宋代〕',c:'带飘飘，衣楚楚。空谷饮甘露。一转花风，萧艾遽如许。细看息影云根，淡然诗思，曾□被、生香轻误。\n此中趣。能消几笔幽奇，羞掩众芳谱。薜老苔荒，山鬼竟无语。梦游忘了江南，故人何处，听一片、潇湘夜雨。'},
    {t:'祝英台近·晚春',a:'辛弃疾〔宋代〕',c:'宝钗分，桃叶渡，烟柳暗南浦。怕上层楼，十日九风雨。断肠片片飞红，都无人管，更谁劝、啼莺声住？\n鬓边觑，试把花卜归期，才簪又重数。罗帐灯昏，哽咽梦中语：是他春带愁来，春归何处？却不解、带将愁去。'},
    {t:'祝英台近·与周草窗话旧',a:'张炎〔宋代〕',c:'水痕深，花信足，寂寞汉南树。转首青阴，芳事顿如许。不知多少消魂，夜来风雨。犹梦到、断红流处。\n最无据。长年息影空山，愁入庾郎句。玉老田荒，心事已迟暮。几回听得啼鹃，不如归去。终不似、旧时鹦鹉。'},
    {t:'祝英台近·重过西湖书所见',a:'张炎〔宋代〕',c:'水西船，山北酒，多为买春去。事与云消，飞过旧时雨。谩留一掬相思，待题红叶，奈红叶、更无题处。\n正延伫。乱花浑不知名，娇小未成语。短棹轻装，逢迎段桥路。那知杨柳风流，柳犹如此，更休道、少年张绪。'},
    {t:'筑城词',a:'张籍〔唐代〕',c:'筑城处，千人万人齐把杵。\n重重土坚试行锥，军吏执鞭催作迟。\n来时一年深碛里，尽著短衣渴无水。\n力尽不得抛杵声，杵声未尽人皆死。\n家家养男当门户，今日作君城下土。'},
    {t:'庄陵挽歌词三首',a:'张籍〔唐代〕',c:'白日已昭昭，干戈亦渐消。迎师亲出道，从谏早临朝。\n佞幸威权薄，忠良宠锡饶。丘陵今一变，无复白云谣。\n观风欲巡洛，习战亦开池。始改三年政，旋闻七月期。\n陵分内外使，官具吉凶仪。渭北新园路，箫笳远更悲。\n晓日龙车动，秋风阊阖开。行帷六宫出，执绋万方来。\n惨惨郊原暮，迟迟挽唱哀。空山烟雨夕，新陌绕陵台。'},
    {t:'追赋画江潭苑四首',a:'李贺〔唐代〕',c:'吴苑晓苍苍，宫衣水溅黄。小鬟红粉薄，骑马珮珠长。\n路指台城迥，罗薰袴褶香。行云沾翠辇，今日似襄王。\n宝袜菊衣单，蕉花密露寒。水光兰泽叶，带重剪刀钱。\n角暖盘弓易，靴长上马难。泪痕沾寝帐，匀粉照金鞍。\n剪翅小鹰斜，绦根玉镟花。鞦垂妆钿粟，箭箙钉文牙。\n狒狒啼深竹，老湿沙。宫官烧蜡火，飞烬污铅华。\n十骑簇芙蓉，宫衣小队红。练香熏宋鹊，寻箭踏卢龙。\n旗湿金铃重，霜干玉镫空。今朝画眉早，不待景阳钟。'},
    {t:'追感往事五首·其五',a:'陆游〔宋代〕',c:'诸公可叹善谋身，误国当时岂一秦。\n不望夷吾出江左，新亭对泣亦无人！'},
    {t:'追和东坡壶中九华',a:'黄庭坚〔宋代〕',c:'有人夜半持山去，顿觉浮岚暖翠空。\n试问安排华屋处，何如零落乱云中。\n能回赵璧人安在，已入南柯梦不通。\n赖有霜钟难席卷，袖椎来听响玲珑。'},
    {t:'追和东坡题李亮功归来图',a:'黄庭坚〔宋代〕',c:'今人常恨古人少，今得见之谁诘无。\n欲学渊明归作赋，先烦摩诘画成图。\n小池已筑鱼千里，隙地仍栽芋百区。\n朝市山林俱有累，不居京洛不江湖。'},
    {t:'追和柳恽',a:'李贺〔唐代〕',c:'汀洲白蘋草，柳恽乘马归。\n江头樝树香，岸上蝴蝶飞。\n酒杯箬叶露，玉轸蜀桐虚。\n朱楼通水陌，沙暖一双鱼。'},
    {t:'追忆余泊舟',a:'黄庭坚〔宋代〕',c:'老大无机如汉阴，白鸟不去相泪深。\n往事刻舟求坠剑，怀人挥泪著亡簪。\n城南鼓罢吹画筒，城北归帆落晚风。\n人烟犬吠西山麓，鬼火狐鸣春竹丛。'},
    {t:'捉搦歌·其三',a:'佚名〔隋代〕',c:'华阴山头百丈井，下有流水彻骨冷。\n可怜女子能照影，不见其馀见斜领。'},
    {t:'涿鹿',a:'文天祥〔宋代〕',c:'我瞻涿鹿野，古来战蚩尤。\n轩辕雁立极，玉帛朝诸侯。\n历历关河雁，随风鸣寒秋。\n迩来三千年，王一行幽州。\n北海口沧海人间别一天，只容渔父钓苍烟。\n而今蜃起楼台处，亦有北来蕃汉船。'},
    {t:'酌酒与裴迪',a:'王维〔唐代〕',c:'酌酒与君君自宽，人情翻覆似波澜。\n白首相知犹按剑，朱门先达笑弹冠。\n草色全经细雨湿，花枝欲动春风寒。\n世事浮云何足问，不如高卧且加餐。'},
    {t:'濯足万里流',a:'朱熹〔宋代〕',c:'褰裳缘碧涧，濯足憩清幽。却拂千岩石，聊乘万里流。\n氛埃随脱屣，步武欲横秋。极目沧江晚，烟波殊未休。'},
    {t:'子规',a:'杜甫〔唐代〕',c:'峡里云安县，江楼翼瓦齐。\n两边山木合，终日子规啼。\n眇眇春风见，萧萧夜色凄。\n客愁那听此，故作傍人低。'},
    {t:'子规啼',a:'韦应物〔唐代〕',c:'高林滴露夏夜清，南山子规啼一声。\n邻家孀妇抱儿泣，我独展转何时明。'},
    {t:'子夜歌',a:'佚名〔南北朝〕',c:'高山种芙蓉，复经黄檗坞。\n果得一莲时，流离婴辛苦。'},
    {t:'子夜歌·今夕已欢别',a:'佚名〔南北朝〕',c:'今夕已欢别，合会在何时？\n明灯照空局，悠然未有期！'},
    {t:'子夜歌·侬作北辰星',a:'佚名〔南北朝〕',c:'侬作北辰星，千年无转移。\n欢行白日心，朝东暮还西。'},
    {t:'子夜歌·始欲识郎时',a:'佚名〔南北朝〕',c:'始欲识郎时，两心望如一。\n理丝入残机，何悟不成匹。'},
    {t:'子夜歌·夜长不得眠',a:'佚名〔南北朝〕',c:'夜长不得眠，明月何灼灼。\n想闻散唤声，虚应空中诺。'},
    {t:'子夜歌四十二首·其二',a:'佚名〔魏晋〕',c:'芳是香所为，冶容不敢当。\n天不夺人愿，故使侬见郎。'},
    {t:'子夜歌四十二首·其三',a:'佚名〔魏晋〕',c:'宿昔不梳头，丝发披两肩。\n婉伸郎膝上，何处不可怜。'},
    {t:'子夜四时歌·春风动春心',a:'佚名〔南北朝〕',c:'春风动春心，流目瞩山林。\n山林多奇采，阳鸟吐清音。'},
    {t:'子夜四时歌·春林花多媚',a:'佚名〔南北朝〕',c:'春林花多媚，春鸟意多哀。\n春风复多情，吹我罗裳开。'},
    {t:'子夜四时歌·其十八',a:'佚名〔魏晋〕',c:'情知三夏热，今日偏独甚。\n香巾拂玉席，共郎登楼寝。'},
    {t:'子夜四时歌·秋风入窗里',a:'佚名〔南北朝〕',c:'秋风入窗里，罗帐起飘飏。\n仰头看明月，寄情千里光。'},
    {t:'子夜四时歌·渊冰厚三尺',a:'佚名〔南北朝〕',c:'渊冰厚三尺，素雪覆千里。\n我心如松柏，君情复何似？'},
    {t:'子夜四时歌·自从别欢后',a:'佚名〔南北朝〕',c:'自从别欢后，叹音不绝响。\n黄檗向春生，苦心随日长。'},
    {t:'子夜吴歌·春歌',a:'李白〔唐代〕',c:'秦地罗敷女，采桑绿水边。\n素手青条上，红妆白日鲜。\n蚕饥妾欲去，五马莫留连。'},
    {t:'子夜吴歌·冬歌',a:'李白〔唐代〕',c:'明朝驿使发，一夜絮征袍。\n素手抽针冷，那堪把剪刀。\n裁缝寄远道，几日到临洮。'},
    {t:'子夜吴歌·秋歌',a:'李白〔唐代〕',c:'长安一片月，万户捣衣声。\n秋风吹不尽，总是玉关情。\n何日平胡虏，良人罢远征。'},
    {t:'子夜吴歌·夏歌',a:'李白〔唐代〕',c:'镜湖三百里，菡萏发荷花。\n五月西施采，人看隘若耶。\n回舟不待月，归去越王家。'},
    {t:'子瞻继和复答二首·其二',a:'黄庭坚〔宋代〕',c:'迎燕温风旎旎，润花小雨斑斑。\n一炷烟中得意，九衢尘里偷闲。'},
    {t:'梓州罢吟寄同舍',a:'李商隐〔唐代〕',c:'不拣花朝与雪朝，五年从事霍嫖姚。\n君缘接座交珠履，我为分行近翠翘。\n楚雨含情皆有托，漳滨卧病竟无憀。\n长吟远下燕台去，惟有衣香染未销。'},
    {t:'紫骝马',a:'李白〔唐代〕',c:'紫骝行且嘶，双翻碧玉蹄。\n临流不肯渡，似惜锦障泥。\n白雪关山远，黄云海戍迷。\n挥鞭万里去，安得念春闺。'},
    {t:'紫骝马歌',a:'佚名〔隋代〕',c:'独柯不成树，独树不成林。念郎锦裲裆，恒长不忘心。'},
    {t:'紫骝马歌辞',a:'佚名〔隋代〕',c:'烧火烧野田，野鸭飞上天。童男娶寡妇，壮女笑杀人。'},
    {t:'紫骝马歌辞其六',a:'佚名〔隋代〕',c:'羹饭一时熟，不知饴阿谁。出门东向望，泪落沾我衣。'},
    {t:'紫骝马歌辞其四',a:'佚名〔隋代〕',c:'遥看是君家，松柏冢累累。兔从狗窦入，雉从梁上飞。'},
    {t:'紫藤树',a:'李白〔唐代〕',c:'紫藤挂云木，花蔓宜阳春。\n密叶隐歌鸟，香风留美人。'},
    {t:'紫薇花',a:'白居易〔唐代〕',c:'紫薇花对紫微翁，名目虽同貌色同。独占芳菲当夏景，\n色将颜色托春风。浔阳官舍双高树，兴善僧庭一大丛。\n何似苏州安置处，花堂栏下月明中。'},
    {t:'紫薇花',a:'杜牧〔唐代〕',c:'晓迎秋露一枝新，不占园中最上春。\n桃李无言又何在，向风偏笑艳阳人。'},
    {t:'紫芝歌',a:'佚名〔两汉〕',c:'莫莫高山，深谷逶迤。\n晔晔紫芝，可以疗饥。\n唐虞世远，吾将何归。\n驷马高盖，其忧甚大。\n富贵之畏人兮，贫贱之肆志。'},
    {t:'紫踯躅',a:'元稹〔唐代〕',c:'紫踯躅，灭紫拢裙倚山腹。\n文君新寡乍归来，羞怨春风不能哭。\n我从相识便相怜，但是花丛不回目。\n去年春别湘水头，今年夏见青山曲。\n迢迢远在青山上，山高水阔难容足。\n愿为朝日早相暾，愿作轻风暗相触。\n乐踯躅，我向通州尔幽独。\n可怜今夜宿青山，何年却向青山宿。\n山花渐暗月渐明，月照空山满山绿。\n山空月午夜无人，何处知我颜如玉。'},
    {t:'紫竹花',a:'晏殊〔宋代〕',c:'长夏幽居景不穷，花开芳砌翠成丛。\n窗南高卧追凉际，时有微香逗晚风。'},
    {t:'自昌谷到洛后问',a:'李贺〔唐代〕',c:'九月大野白，苍岑竦秋门。\n寒凉十月末，露霰濛晓昏。\n澹色结昼天，心事填空云。\n道上千里风，野竹蛇涎痕。\n石涧涷波声，鸡叫清寒晨。\n强行到东舍，解马投旧邻。\n东家名廖者，乡曲传姓辛。\n杖头非饮酒，吾请造其人。\n始欲南去楚，又将西适秦。\n襄王与武帝，各自留青春。\n闻道兰台上，宋玉无归魂。\n缃缥两行字，蛰虫蠹秋芸。\n为探秦台意，岂命余负薪。'},
    {t:'自嘲',a:'陆游〔宋代〕',c:'少读诗书陋汉唐，莫年身世寄农桑。\n骑驴两脚欲到地，爱酒一樽常在旁。\n老去形容虽变改，醉来意气尚轩昂。\n太行王屋何由动，堪笑愚公不自量。'},
    {t:'自代内赠',a:'李白〔唐代〕',c:'宝刀截流水，无有断绝时。\n妾意逐君行，缠绵亦如之。\n别来门前草，秋巷春转碧。\n扫尽更还生，萋萋满行迹。\n鸣凤始相得，雄惊雌各飞。\n游云落何山？一往不见归。\n估客发大楼，知君在秋浦。\n梁苑空锦衾，阳台梦行雨。\n妾家三作相，失势去西秦。\n犹有旧歌管，凄清闻四邻。\n曲度入紫云，啼无眼中人。\n妾似井底桃，开花向谁笑？\n君如天上月，不肯一回照。\n窥镜不自识，别多憔悴深。\n安得秦吉了，为人道寸心。'},
    {t:'自法云归',a:'陆游〔宋代〕',c:'落日疏林数点鸦，青山阙处是吾家。\n归来何事添幽致，小灶灯前自煮茶。'},
    {t:'自蓟北归',a:'高适〔唐代〕',c:'驱马蓟门北，北风边马哀。\n苍茫远山口，豁达胡天开。\n五将已深入，前军止半回。\n谁怜不得意，长剑独归来。'},
    {t:'自江陵沿流道中',a:'刘禹锡〔唐代〕',c:'三千三百西江水，自古如今要色津。月夜歌谣有渔父，\n风天气色属商人。沙村好处多逢寺，山叶红时觉胜春。\n行到南朝征战地，古来名将尽为神。'},
    {t:'自洛之越',a:'孟浩然〔唐代〕',c:'遑遑三十载，书剑两无成。\n山水寻吴越，风尘厌洛京。\n扁舟泛湖海，长揖谢公卿。\n且乐杯中物，谁论世上名。'},
    {t:'自潘陵尖还少室居止，秋夕凭眺',a:'岑参〔唐代〕',c:'草堂近少室，夜静闻风松。月出潘陵尖，照见十六峰。\n九月山叶赤，谿云淡秋容。火点伊阳村，烟深嵩角钟。\n尚子不可见，蒋生难再逢。胜惬只自知，佳趣为谁浓。\n昨诣山僧期，上到天坛东。向下望雷雨，云间见回龙。\n夕与人群疏，转爱丘壑中。心澹水木会，兴幽鱼鸟通。\n稀微了自释，出处乃不同。况本无宦情，誓将依道风。'},
    {t:'自彭蠡湖初入江',a:'张九龄〔唐代〕',c:'江岫殊空阔，云烟处处浮。上来群噪鸟，中去独行舟。\n牢落谁相顾，逶迤日自愁。更将心问影，于役复何求。'},
    {t:'自蒲塘驿回驾经历山水',a:'韦应物〔唐代〕',c:'馆宿风雨滞，始晴行盖转。浔阳涧水多，草木俱纷衍。\n崎岖缘碧涧，苍翠践苔藓。高树夹潺湲，崩岚横阴巘。\n野杏依寒拆，馀云冒岚浅。性惬形岂劳，境殊路遗缅。\n忆昔终南下，佳游亦屡展。时禽下流暮，纷思何由遣。'},
    {t:'自淇涉黄河途中作十三首其十二',a:'高适〔唐代〕',c:'朝景入平川，川长复垂柳。遥看时公墓，突兀前山后。\n忆昔大业时，群雄角奔走。伊人何电迈，独洛风尘首。\n传檄举敖仓，拥兵屯洛口。连营一百万，六合如可有。\n方项终比肩，乱隋将假手。力争固难恃，骄战曷能久。\n若使学萧曹，功名当不朽。'},
    {t:'自遣',a:'杜牧〔唐代〕',c:'四十已云老，况逢忧窘馀。且抽阮板手，却展小年书。\n嗜酒狂嫌阮，知非晚笑蘧。闻流宁叹吒，待俗不亲疏。\n遇事知裁剪，操心识卷舒。还称二千石，于我意何如。'},
    {t:'自遣',a:'李白〔唐代〕',c:'对酒不觉暝，落花盈我衣。\n醉起步溪月，鸟还人亦稀。'},
    {t:'自商行谒复州卢使君虔',a:'孟郊〔唐代〕',c:'一身绕千山，远作行路人。未遂客吴归，暂出西京尘。\n仲宣荆州客，今余竟陵宾。往迹虽不同，托下皆有因。\n商岭莓苔滑，石坂上下频。江汉沙泥洁，永日光景新。\n独泪起残夜，孤吟望初晨。驱驰竟何事，章句依深仁。'},
    {t:'自始兴溪夜上赴岭',a:'张九龄〔唐代〕',c:'尝蓄名山意，兹为世网牵。征途屡及此，初服已非然。\n日落青岩际，溪行绿筱边。去舟乘月后，归鸟息人前。\n数曲迷幽嶂，连圻触暗泉。深林风绪结，遥夜客情悬。\n非梗胡为泛，无膏亦自煎。不知于役者，相乐在何年。'},
    {t:'自述',a:'文天祥〔宋代〕',c:'赤舄登黄道，朱旗上紫垣。\n有心扶日月，无力报乾坤。\n往事飞鸿渺，新愁落照昏。\n千年沧海上，精卫是吾魂。'},
    {t:'自苏州访医回酬卢士关判官见赠',a:'皎然〔唐代〕',c:'寻医初疾理，忽忆故山云。远访桑公子，还依柳使君。\n周旋承惠爱，佩服比兰薰。从事因高唱，秋风起处闻。'},
    {t:'自叹',a:'孟郊〔唐代〕',c:'愁与发相形，一愁白数茎。有发兵几多，禁愁日日生。\n古若不置兵，天下无战争。古若不置名，道不无欹倾。\n太行耸巍峨，是天产不平。黄河奔浊浪，是天生不清。\n四蹄日日多，双轮日日成。二物不在天，安兵免营营。'},
    {t:'自叹',a:'文天祥〔宋代〕',c:'草宿披宵露，松餐立晚风。\n乱离嗟我在，艰苦有谁同。\n祖逖关河志，程婴社稷功。\n身谋百年事，宇宙浩舞穷。'},
    {t:'自题金山画像',a:'苏轼〔宋代〕',c:'心似已灰之木，身如不系之舟。\n问汝平生功业，黄州惠州儋州。'},
    {t:'自惜',a:'孟郊〔唐代〕',c:'倾尽眼中力，抄诗过与人。自悲字雅老，恐被巴竹嗔。\n零落雪文字，分明镜精神。坐甘冰抱晚，永谢酒怀春。\n徒有言言旧，惭无默默新。始惊儒教误，渐与佛乘亲。'},
    {t:'自喜',a:'李商隐〔唐代〕',c:'自喜蜗牛舍，兼容燕子巢。\n绿筠遗粉箨，红药绽香苞。\n虎过遥知阱，鱼来且佐庖。\n慢行成酩酊，邻壁有松醪。'},
    {t:'自湘水南行',a:'张九龄〔唐代〕',c:'落日催行舫，逶迤洲渚间。虽云有物役，乘此更休闲。\n暝色生前浦，清晖发近山。中流澹容与，唯爱鸟飞还。'},
    {t:'自宣城赴官上京',a:'杜牧〔唐代〕',c:'潇洒江湖十过秋，酒杯无日不前留。\n谢公城畔溪惊梦，苏小门前柳拂头。\n千里云山何处好，几人襟韵一生休。\n尘冠挂却知闲事，终拟蹉跎访旧游。'},
    {t:'自浔阳泛舟经明海',a:'孟浩然〔唐代〕',c:'大江分九流，淼漫成水乡。\n舟子乘利涉，往来至浔阳。\n因之泛五湖，流浪经三湘。\n观涛壮枚发，吊屈痛沉湘。\n魏阙心恒在，金门诏不忘。\n遥怜上林雁，冰泮也回翔。'},
    {t:'自贻',a:'杜牧〔唐代〕',c:'杜陵萧次君，迁少去官频。寂寞怜吾道，依稀似古人。\n饰心无彩缋，到骨是风尘。自嫌如匹素，刀尺不由身。'},
    {t:'自咏',a:'白居易〔唐代〕',c:'随宜饮食聊充腹，取次衣裘亦福身。\n未必得年非瘦薄，无妨长福是单贫。\n老龟岂羡牺牲饱，蟠木宁争桃李春。\n随分自安心自断，是非何用问闲人。'},
    {t:'自咏示客',a:'陆游〔宋代〕',c:'衰发萧萧老郡丞，洪州又看上元灯。\n羞将枉直分寻尺，宁走东西就斗升。\n吏进饱谙箝纸尾，客来苦劝摸床棱。\n归装渐理君知否？笑指庐山古涧藤。'},
    {t:'自有扈至京师已后朱樱之期',a:'温庭筠〔唐代〕',c:'露圆霞赤数千枝，银笼谁家寄所思。秦苑飞禽谙熟早，\n杜陵游客恨来迟。空看翠幄成阴日，不见红珠满树时。\n尽日徘徊浓影下，只应重作钓鱼期。'},
    {t:'自豫章南还江上作',a:'张九龄〔唐代〕',c:'归去南江水，磷磷见底清。转逢空阔处，聊洗滞留情。\n浦树遥如待，江鸥近若迎。津途别有趣，况乃濯吾缨。'},
    {t:'自作挽词',a:'秦观〔宋代〕',c:'婴衅徙穷荒，茹哀与世辞。\n官来棺我橐，吏来验我尸。\n藤束木皮棺，槁葬路傍陂。\n家乡在万里，妻在天一涯。\n孤魂不敢归，惴惴犹在兹。\n昔忝柱下史，通籍黄金闺。\n奇祸一朝作，飘零至於斯。\n弱孤未堪事，返骨定何时。\n修途缭山海，岂免从闍维。\n荼毒复荼毒，彼苍那得知。\n岁冕瘴江急，鸟兽鸣声悲。\n空蒙寒雨零，惨淡阴风吹。\n殡宫生苍藓，纸钱挂空枝。\n无人设薄奠，谁与饭黄缁。\n亦无挽歌者，空有挽歌辞。'},
    {t:'宗武生日',a:'杜甫〔唐代〕',c:'小子何时见，高秋此日生。\n自从都邑语，已伴老夫名。\n诗是吾家事，人传世上情。\n熟精文选理，休觅彩衣轻。\n凋瘵筵初秩，欹斜坐不成。\n流霞分片片，涓滴就徐倾。'},
    {t:'纵笔',a:'苏轼〔宋代〕',c:'白头萧散满霜风，小阁藤床寄病容。\n报道先生春睡美，道人轻打五更钟。'},
    {t:'纵笔三首·其一',a:'苏轼〔宋代〕',c:'寂寂东坡一病翁，白须萧散满霜风。\n小儿误喜朱颜在，一笑那知是酒红。'},
    {t:'走马川行奉送封大夫出师西征',a:'岑参〔唐代〕',c:'君不见走马川行雪海边，平沙莽莽黄入天。\n轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。\n匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。\n将军金甲夜不脱，半夜军行戈相拨，风头如刀面如割。\n马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝。\n虏骑闻之应胆慑，料知短兵不敢接，车师西门伫献捷。'},
    {t:'走马楼三更曲',a:'温庭筠〔唐代〕',c:'春姿暖气昏神沼，李树拳枝紫芽小。玉皇夜入未央宫，\n长火千条照栖鸟。马过平桥通画堂，虎幡龙戟风飘扬。\n帘间清唱报寒点，丙舍无人遗烬香。'},
    {t:'走马引',a:'李贺〔唐代〕',c:'我有辞乡剑，玉锋堪截云。\n襄阳走马客，意气自生春。\n朝嫌剑光静，暮嫌剑花冷。\n能持剑向人，不解持照身。'},
    {t:'阻戎泸间群盗',a:'岑参〔唐代〕',c:'南州林莽深，亡命聚其间。杀人无昏晓，尸积填江湾。\n饿虎衔髑髅，饥乌啄心肝。腥裛滩草死，血流江水殷。\n夜雨风萧萧，鬼哭连楚山。三江行人绝，万里无征船。\n唯有白鸟飞，空见秋月圆。罢官自南蜀，假道来兹川。\n瞻望阳台云，惆怅不敢前。帝乡北近日，泸口南连蛮。\n何当遇长房，缩地到京关。愿得随琴高，骑鱼向云烟。\n明主每忧人，节使恒在边。兵革方御寇，尔恶胡不悛。\n吾窃悲尔徒，此生安得全。'},
    {t:'祖逖',a:'文天祥〔宋代〕',c:'平生祖豫州，白首起大事。\n东门长啸儿，为逊一头地。\n何哉戴若思，中道奋螳臂。\n豪杰事垂成，今古为短气。'},
    {t:'最高楼',a:'辛弃疾〔宋代〕',c:'归闽中矣\n相思苦，君与我同心。冕没雁沈沈。是梦他松后追轩冕，是化为鹤后去山林。对西风，有怅望，到如今。\n待不饮、奈何君有恨。待痛饮、奈何吾有病。君起舞，试重斟。苍梧云外湘妃泪，鼻亭山下鹧鸪吟。早归来，流水外，有知音。'},
    {t:'最高楼·吾衰矣',a:'辛弃疾〔宋代〕',c:'吾拟乞归，犬子以田产未置止我，赋此骂之。\n吾衰矣，须富贵何时？富贵是危机。暂忘设醴抽身去，未曾得米弃官归。穆先生，陶县令，是吾师。\n待葺个园儿名“佚老”，更作个亭儿名“亦好”，闲饮酒，醉吟诗。千年田换八百主，一人口插几张匙？便休休，更说甚，是和非！'},
    {t:'最高楼·醉中有索四时歌者为赋',a:'辛弃疾〔宋代〕',c:'长安道，投老倦游归。七十古来小。藕花雨湿前湖夜，桂枝风澹小山时。怎消除？须殢酒，更吟诗。\n边莫向竹边孤负雪。边莫向柳边孤负月。闲过了，总成痴。种花事业无人问，惜花情绪只天知。笑山中：云出早，鸟归迟。'},
    {t:'罪松',a:'孟郊〔唐代〕',c:'虽为青松姿，霜风何所宜。二月天下树，绿于青松枝。\n勿谓贤者喻，勿谓愚者规。伊吕代封爵，夷齐终身饥。\n彼曲既在斯，我正实在兹。泾流合渭流，清浊各自持。\n天令设四时，荣衰有常期。荣合随时荣，衰合随时衰。\n天令既不从，甚不敬天时。松乃不臣木，青青独何为。'},
    {t:'醉答乐天',a:'刘禹锡〔唐代〕',c:'洛城洛城何日归，故人故人今转稀。\n莫嗟雪里暂时别，终拟云间相逐飞。'},
    {t:'醉歌',a:'陆游〔宋代〕',c:'我饮江楼上，阑干四面空。\n手把白玉船，身游水精宫。\n方我吸酒时，江山入胸中。\n肺肝生崔嵬，吐出为长虹。\n欲吐辄复吞，颇畏惊儿童。\n乾坤大如许，无处著此翁。\n何当呼青鸾，更驾万里风。'},
    {t:'醉歌示妓人商玲珑',a:'白居易〔唐代〕',c:'罢胡琴，掩秦瑟，玲珑再拜歌初毕。\n谁道使君不解歌？听唱黄鸡与白日。\n黄鸡催晓丑时鸣，白日催年酉前没。\n腰间红绶系未稳，镜里朱颜看已失。\n玲珑玲珑奈老何？使君歌了汝更歌。'},
    {t:'醉后',a:'韩愈〔唐代〕',c:'煌煌东方星，奈此众客醉。\n初喧或忿争，中静杂嘲戏。\n淋漓身上衣，颠倒笔下字。\n人生如此少，酒贱且勤置。'},
    {t:'醉后',a:'白居易〔唐代〕',c:'酒后高歌且放狂，门前闲事莫思量。\n犹嫌小户长先醒，不得多时住醉乡。'},
    {t:'醉后却寄元九',a:'白居易〔唐代〕',c:'蒲池村里悤悤别，沣水桥边兀兀回。行到城门残酒醒，万重离恨一时来。'},
    {t:'醉后戏与赵歌儿',a:'岑参〔唐代〕',c:'秦州歌儿歌调苦，偏能立唱濮阳女。\n座中醉客不得意，闻之一声泪如雨。\n向使逢着汉帝怜，董贤气咽不能语。'},
    {t:'醉后赠马四',a:'孟浩然〔唐代〕',c:'四海重然诺，吾尝闻白眉。秦城游侠客，相得半酣时。'},
    {t:'醉后赠张九旭',a:'高适〔唐代〕',c:'世上谩相识，此翁殊不然。\n兴来书自圣，醉后语尤颠。\n白发老闲事，青云在目前。\n床头一壶酒，能更几回眠？'},
    {t:'醉花阴·黄花谩说年年好',a:'辛弃疾〔宋代〕',c:'黄花谩说年年好。也趁秋光老。绿鬓不惊秋，若斗尊前，人好花堪笑。\n蟠桃结子知多少。家住三山岛。何日跨归鸾，沧海飞尘，人世因缘了。'},
    {t:'醉里送裴子赴镇西',a:'岑参〔唐代〕',c:'醉后未能别，待醒方送君。\n看君走马去，直上天山云。'},
    {t:'醉留东野',a:'韩愈〔唐代〕',c:'昔年因读李白杜甫诗，长恨二人不相从。\n吾与东野生并世，如何复蹑二子踪。\n东野不得官，白首夸龙钟。\n韩子稍奸黠，自惭青蒿倚长松。\n低头拜东野，原得终始如駏蛩。\n东野不回头，有如寸筳撞巨钟。\n吾愿身为云，东野变为龙。\n四方上下逐东野，虽有离别无由逢？'},
    {t:'醉落魄',a:'张炎〔宋代〕',c:'柳侵阑角。画帘风软红香泊。引近蝴蝶翻轻薄。已自关情，和梦近来恶。\n眉梢轻把闲愁著。如今愁重眉梢弱。双眉不画愁消却。不道愁痕，来傍眼边觉。'},
    {t:'醉落魄',a:'晏几道〔宋代〕',c:'鸾孤月缺。两春惆怅音尘绝。如今若负当时节。信道欢缘，狂向衣襟结。\n若问相思何处歇。相逢便是相思彻。尽饶别后留心别。也待相逢。细把相思说。'},
    {t:'醉落魄',a:'晏几道〔宋代〕',c:'满街斜月。垂鞭自唱阳关彻。断多柔肠思归切。都为人人，不许多时别。\n南桥昨夜风吹雪。短长亭下征尘歇。归时定有梅堪折。欲把离愁，细捻花枝说。'},
    {t:'醉落魄',a:'晏几道〔宋代〕',c:'天教命薄。青楼占得声名恶。对酒当歌寻思著。月户星窗，多少旧期约。\n相逢细语初心错。两行红泪尊前落。霞觞且共深深酌。恼乱春宵，翠被都闲却。'},
    {t:'醉落魄',a:'晏几道〔宋代〕',c:'休休莫莫。离多还是因缘恶。有情无奈思量著。月夜佳期，近定青笺约。\n心心口口长恨昨。分飞容易当时错。后期休似前欢薄。买断青楼，莫放春闲却。'},
    {t:'醉落魄·离京口作',a:'苏轼〔宋代〕',c:'轻云微月，二更酒醒船初发。孤归回望苍烟合。记得歌时，不记归时节。\n巾偏扇坠藤床滑，觉来幽梦无人说。此生飘荡何时歇？家在西南，常作东南别。'},
    {t:'醉落魄·苏州阊门留别',a:'苏轼〔宋代〕',c:'苍颜华发，故山归计何时决！旧殷新贵音书绝，惟有佳人，犹作殷勤别。\n离亭欲去歌声咽，潇潇细雨凉吹颊。泪珠不用罗巾浥，弹在罗衫，图得见时说。'},
    {t:'醉落魄·天教命薄',a:'晏几道〔宋代〕',c:'天教命薄，青楼占得声名恶。\n对酒当歌寻思着，\n月户星窗，多少旧期约。\n相逢细语初心错，\n两行红泪尊前落。\n霞觞且共深深酌，\n恼乱春宵，翠被都闲却。'},
    {t:'醉落魄·席上呈元素',a:'苏轼〔宋代〕',c:'分携如昨。人生到处萍飘泊。偶然相聚还离索。多病多愁，须信从来错。\n尊前一笑休辞却。天涯同是伤沦落。故山犹负平生约。西望峨嵋，长羡归飞鹤。'},
    {t:'醉眠',a:'杜牧〔唐代〕',c:'秋醪雨中熟，寒斋落叶中。幽人本多睡，更酌一樽空。'},
    {t:'醉蓬莱',a:'秦观〔宋代〕',c:'见扬州独有，天下无双，号为琼一。占断天风，岁花开两次。九朵一苞，攒成环玉，心似珠玑缀。冷冷玲珑，枝枝洁净，世上无花类。冷露朝凝，香风远送，信是琼瑶贵。料得天宫有，此地久难留住。翰苑才人，贵家公子，都要看花去。莫吝金钱，好寻诗伴，日日花前醉。'},
    {t:'醉蓬莱·对朝云叆叇',a:'黄庭坚〔宋代〕',c:'对朝云叆叇，暮雨霏微，乱峰相移。巫峡高唐，锁楚宫朱翠。画戟移春，靓妆迎马，向一川都会。万道投荒，一身吊影，成何欢意。\n尽道黔南，去天尺五，望极神州，万重烟水。樽酒公堂，有中朝佳士。荔颊红深，麝脐香满，醉舞裀歌袂。杜宇声声，催人到晓，不如归是。'},
    {t:'醉蓬莱·渐亭皋叶下',a:'柳永〔宋代〕',c:'渐亭皋叶下，陇首云飞，素秋新霁。华阙中天，锁葱葱佳气。嫩菊黄深，拒霜红浅，近宝阶香砌。玉宇无尘，金茎有露，碧天如水。\n正值升平，万几多暇，夜色澄鲜，漏声迢递。南极星中，有老人呈瑞。此际宸游，凤辇何处，度管弦清脆。太液波翻，披香帘卷，月明风细。'},
    {t:'醉蓬莱·重九上君猷',a:'苏轼〔宋代〕',c:'余谪居黄州，三见重九，每岁与太守徐君猷会于栖霞楼。今年公将去，乞郡湖南。念此惘然，故作此词。\n笑劳生一梦，羁旅三年，又还重九。华发萧萧，对荒园搔首。赖有多情，好饮无事，似古人贤守。岁岁登高，年年落帽，物华依旧。\n此会应须烂醉，仍把紫菊茱萸，细看重嗅。摇落霜风，有手栽双柳。来岁今朝，为我西顾，酹羽觞江口。会与州人，饮公遗爱，一江醇酎。'},
    {t:'醉太平·讥贪小利者',a:'佚名〔元代〕',c:'夺泥燕口，削铁针头，刮金佛面细搜求：无中觅有。鹌鹑嗉里寻豌豆，鹭鸶腿上劈精肉，蚊子腹内刳脂油。亏老先生下手！'},
    {t:'醉太平·堂堂大元',a:'佚名〔元代〕',c:'堂堂大元，奸佞专权。开河变钞法根源，惹红巾万千。官法滥，刑法重，黎民怨。人吃人，钞买钞，何曾见。贼做官，官做贼，混愚贤。哀哉可怜！'},
    {t:'醉桃源·碧天如水月如眉',a:'秦观〔宋代〕',c:'碧天如水月如眉，\n城头银漏迟。\n绿波风动画船移，\n娇羞初见时。\n银烛暗，翠帘垂，\n芳心两自知。\n楚台魂断晓云飞，\n幽欢难再期。'},
    {t:'醉桃源·大石',a:'周邦彦〔宋代〕',c:'冬衣初染远山青。双丝云雁绫。情寒袖湿欲成冰。都缘珠泪零。\n情黯黯，闷腾腾。身如秋后蝇。若教随马逐郎行。不辞多少程。'},
    {t:'醉题匡城周少府厅壁',a:'岑参〔唐代〕',c:'妇姑城南风雨秋，妇姑城中人上愁。愁云遮却望乡处，\n数日不上西南楼。故人薄暮公事闲，玉壶美酒琥珀殷。\n颍阳秋草今黄尽，醉卧君家犹未还。'},
    {t:'醉卧海棠图歌赠陆务观',a:'杨万里〔宋代〕',c:'帝城二三月，海棠一万株。\n向来东女拉滕六，戏与一撼即日枯。\n东皇夜遣司花女，手挼红蓝滴梢露。\n染成片片净练酥，乳点梢梢酣日树。\n蓬莱仙人约老翁，寄牋招唤陆龟蒙。\n为花一醉也不惜，就中一事最奇特。\n海棠两岸绣惟裳，是间横著双胡床。\n龟蒙踞床忽倒卧，乌纱自落非风堕。\n落花满面雪霏霏，起来索笔手如飞。\n卧来起来都是韵，是醉是醒君莫问。\n好个海棠花下醉卧图，如今画手谁姓吴？'},
    {t:'醉戏窦子美人',a:'岑参〔唐代〕',c:'朱唇一点桃花殷，宿妆娇羞偏髻鬟。\n细看只似阳台女，醉著莫许归巫山。'},
    {t:'醉下祝融峰作',a:'朱熹〔宋代〕',c:'我来万里驾长风，绝壑层云许荡胸。浊酒三杯豪气发，朗吟飞下祝融峰。'},
    {t:'醉吟',a:'杨万里〔宋代〕',c:'古人亡，古人在，古人不在天应万。\n不留三句五句诗，安得千人万人爱。\n今人只叶古人痴，古人叶君君不知。\n朝来暮去能几许，叶落花开无尽时。\n人生须要印如斗，不道金槌控渠口。\n身前只解皱两眉，身後还能更杯酒。\n李太白，阮嗣宗，当年谁不叶两翁。\n万古贤愚俱白骨，两翁天地一清风。'},
    {t:'醉赠刘二十八使君',a:'白居易〔唐代〕',c:'为我引杯添酒饮，与君把箸击盘歌。\n诗称国手徒为尔，命压人头不奈何。\n举眼风光长寂寞，满朝官职独蹉跎。\n亦知合被才名折，二十三年折太多。'},
    {t:'醉中出西门偶书',a:'陆游〔宋代〕',c:'古寺闲房闭寂寥，几年耽酒负公朝。\n青山是处可埋骨，白发向人羞折腰。\n末路自悲终老蜀，少年常愿从征辽。\n醉来挟箭西郊去，极目寒芜雉兔骄。'},
    {t:'醉中感怀',a:'陆游〔宋代〕',c:'早岁君王记姓名，只今憔悴客边城。\n青衫犹是鵷行旧，白发新从剑外生。\n古戍旌旗秋惨淡，高城刁斗夜分明。\n壮心未许全消尽，醉听檀槽出塞声。'},
    {t:'醉中作行草数纸',a:'陆游〔宋代〕',c:'还家痛饮洗尘土，醉帖淋漓寄豪举；\n石池墨渖如海宽，玄云下垂黑蛟舞。\n太阴鬼神挟风雨，夜半马陵飞万弩。\n堂堂笔阵从天下，气压唐人折钗股。\n丈夫本意陋千古，残虏何足膏碪斧；\n驿书驰报儿单于，直用毛锥惊杀汝！'},
    {t:'昨日',a:'李商隐〔唐代〕',c:'昨日紫姑神去也，今朝青鸟使圆赊。\n未容言语还分散，少得团圆足怨嗟。\n二八月轮蟾影破，十三弦柱雁行斜。\n平明钟后更何事，笑倚墙边梅树花。'},
    {t:'昨夜',a:'李商隐〔唐代〕',c:'不辞鶗鴂妒年芳，但惜流尘暗烛房。\n昨夜西池凉露满，桂花吹断月中香。'},
    {t:'左迁至蓝关示侄孙湘',a:'韩愈〔唐代〕',c:'一封朝奏九重天，夕贬潮州路八千。\n欲为圣明除弊事，肯将衰朽惜残年！\n云横秦岭家何在？雪拥蓝关马不前。\n知汝远来应有意，好收吾骨瘴江边。'},
    {t:'左掖梨花',a:'王维〔唐代〕',c:'闲洒阶边草，轻随箔外风。\n黄莺弄不足，衔入未央宫。'},
    {t:'佐郡思旧游',a:'岑参〔唐代〕',c:'幸得趋紫殿，却忆侍丹墀。史笔众推直，谏书人莫窥。\n平生恒自负，垂老此安卑。同类皆先达，非才独后时。\n庭槐宿鸟乱，阶草夜虫悲。白发今无数，青云未有期。'},
    {t:'作蚕丝',a:'佚名〔南北朝〕',c:'春蚕不应老，昼夜常怀丝。\n何惜微躯尽，缠绵自有时。'},
    {t:'座右铭',a:'陈子昂〔唐代〕',c:'事父尽孝敬，事君贵端贞。\n兄弟慎和睦，朋友笃信诚。\n从官重公慎，立身贵廉明。\n待士慕谦让，莅审尚宽平。\n理讼惟正直，察狱必审情。\n谤议不足怨，宠辱讵须惊。\n处满常惮溢，居高本虑倾。\n诗礼固可学，郑卫不足听。\n幸能修实操，何俟钓虚声。\n白珪玷可灭，黄金诺不轻。\n秦穆饮盗马，楚客报绝缨。\n言行既无择，存殁自扬名。'},
    ];

/* 常见中英文标点（去标点时清理） */
const PUNCT_RE = /[，。、；：？！…—–·「」『』“”‘’（）《》〈〉【】〔〕〖〗［］｛｝,.;:?!'"`()\[\]{}<>~@#$%^&*+=|\\\/\-_]/g;

function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, m =>
        ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[m]));
}

function textCharCount(c) {
    return (c || '').replace(/\s|\u3000/g, '').replace(PUNCT_RE, '').length;
}

/* ---------- 篇目库：内置 + 本地导入/收藏（localStorage） ---------- */
const LIB_KEY = 'zitie-lib-extra-v1';
let libExtra = [];
try { libExtra = JSON.parse(localStorage.getItem(LIB_KEY) || '[]') || []; } catch (e) { libExtra = []; }

function saveLibExtra() {
    try { localStorage.setItem(LIB_KEY, JSON.stringify(libExtra)); } catch (e) { }
}

function normalizeEntry(e) {
    return {
        t: String(e.t || e.title || e.name || '未命名').trim(),
        a: String(e.a || e.author || '').trim(),
        c: String(e.c || e.content || e.body || e.text || '').replace(/\r/g, ''),
        fav: e.fav ? 1 : 0
    };
}

function allEntries() { return BUILTIN_TEXTS.concat(libExtra); }

function buildLibList() {
    const kw = ($('libSearch').value || '').trim().toLowerCase();
    const min = Math.max(0, Number($('libMin').value) || 0);
    const max = Math.max(min, Number($('libMax').value) || 99999);
    const list = allEntries().filter(e => {
        const n = textCharCount(e.c);
        if (n < min || n > max) return false;
        if (!kw) return true;
        return (e.t + e.a + e.c).toLowerCase().includes(kw);
    }).sort((x, y) => textCharCount(x.c) - textCharCount(y.c));

    $('libCount').innerText = `共 ${allEntries().length} 篇 · 匹配 ${list.length} 篇`;
    const box = $('libList');
    box.innerHTML = '';
    if (!list.length) {
        box.innerHTML = '<div class="lib-empty">没有匹配的篇目，放宽字数或换个关键词</div>';
        return;
    }
    const limit = 1000;
    list.slice(0, limit).forEach(e => {
        const it = document.createElement('div');
        it.className = 'lib-item';
        it.innerHTML = `<span class="lib-name">${esc(e.t)}<i>${esc(e.a)}</i></span>` +
            `<span class="lib-meta">${textCharCount(e.c)} 字${e.fav ? ' ★' : ''}</span>`;
        it.onclick = () => loadTextEntry(e);
        box.appendChild(it);
    });
    if (list.length > limit) {
        box.insertAdjacentHTML('beforeend',
            `<div class="lib-empty">还有 ${list.length - limit} 篇未显示，请缩小字数范围或搜索</div>`);
    }
}

/* 一键载入篇目：标题 + 作者行（空格由排版自动补，保证右对齐）+ 空行 + 正文 */
function loadTextEntry(e) {
    const body = e.c.replace(/\r/g, '');
    const authorLine = e.a ? '——' + e.a.trim() : '';
    $('content').value = e.t + (authorLine ? '\n' + authorLine : '') + '\n\n' + body;
    render();
}



/* 把当前输入内容收藏为篇目（存在本地，可反复调用） */
function saveCurrentAsText() {
    const raw = $('content').value.trim();
    if (!raw) return;
    const lines = raw.split('\n');
    const title = (lines[0] || '').trim() || '我的篇目';
    const authorLine = (lines[1] || '').trim();
    const author = authorLine.replace(/^[\s—]+/, '').trim();
    const body = lines.slice(2).join('\n').trim() || raw;
    libExtra.unshift({t: title, a: author, c: body, fav: 1});
    saveLibExtra();
    buildLibList();
}

/* 导入外部 JSON：[{title,author,content}] 或 {items:[...]} */
function importLibJson(file) {
    const reader = new FileReader();
    reader.onload = () => {
        try {
            const json = JSON.parse(reader.result);
            const arr = Array.isArray(json) ? json : (json.items || json.list || json.data || []);
            const add = arr.map(normalizeEntry).filter(x => x.c);
            libExtra = libExtra.concat(add);
            saveLibExtra();
            buildLibList();
            alert(`已导入 ${add.length} 篇，篇目库现有 ${allEntries().length} 篇`);
        } catch (err) {
            alert('JSON 解析失败：' + err.message);
        }
    };
    reader.readAsText(file, 'utf-8');
}

/* 列类练字方式 = 竖排：一列一个字，往下排 */
const VERTICAL_MODES = ['colFirst', 'half', 'colAlt', 'colFade'];
const isVerticalMode = m => VERTICAL_MODES.includes(m);

/* 竖排时每列的浓淡：前 N 列描红，后面的列留空或由深到浅 */
function verticalInk(col, cols, mode) {
    const fadeA = Number($('fadeAlpha').value) / 100;
    const sec = Number(document.querySelector('#secondarySeg .on').dataset.v);
    const n = Math.max(1, Number($('modeNum').value) || 1);
    let keep = 0;
    if (mode === 'colFirst') keep = n;
    else if (mode === 'half') keep = Math.ceil(cols / 2);
    else if (mode === 'colAlt') keep = null;   /* 隔列：奇数列描红 */
    if (mode === 'colFade') {
        return 1 - (1 - fadeA) * ((col - 1) / Math.max(1, cols - 1));
    }
    if (mode === 'colAlt') {
        return (col % 2 === 1) ? 1 : (sec ? fadeA : 0);
    }
    if (col <= keep) return 1;
    if (!sec) return 0;
    /* 后面的列由深到浅渐变，最后一列最淡 */
    const span = Math.max(1, cols - keep);
    return 1 - (1 - fadeA) * ((col - keep) / span);
}

/* ---------- 练字方式：按行/列计算描红强度（1=描红，0=留空，中间=变淡） ---------- */
function inkFor(row, col, rows, cols, lead) {
    const mode = $('modeSel').value;
    const fadeA = Number($('fadeAlpha').value) / 100;
    const sec = Number(document.querySelector('#secondarySeg .on').dataset.v);
    const dim = sec ? fadeA : 0;
    const n = Math.max(1, Number($('modeNum').value) || 1);
    const rel = col - (lead || 0);              /* 该行文字内的第几列（忽略缩进/居中留白） */
    const rp = (row - 1) / Math.max(1, rows - 1);
    const cp = (Math.max(1, rel) - 1) / Math.max(1, cols - 1);
    switch (mode) {
        case 'rowAlt':
        case 'rowAlt2': return 1;    /* 隔行由排版补空行实现，文字保持描红原色 */
        case 'colFirst': return (rel <= n) ? 1 : dim;
        case 'half': return (rel <= Math.ceil(cols / 2)) ? 1 : dim;
        case 'colAlt': return (rel % 2 === 1) ? 1 : dim;
        case 'halfRow': return (row <= Math.ceil(rows / 2)) ? 1 : dim;
        case 'rowFade': return 1 - (1 - fadeA) * rp;
        case 'colFade': return 1 - (1 - fadeA) * cp;
        case 'diag': return 1 - (1 - fadeA) * ((rp + cp) / 2);
        default: return 1;
    }
}

function syncModeRows() {
    const mode = $('modeSel').value;
    $('modeNumRow').classList.toggle('dim', mode !== 'colFirst');
    const cont = ['rowFade', 'colFade', 'diag'].includes(mode);
    $('fadeRow').classList.toggle('dim', !cont && Number(document.querySelector('#secondarySeg .on').dataset.v) === 0);
}

/* 把字帖文本拆成逐字数组；cols 为每行字数，indent 为首行缩进字数
    返回数组带两个附加属性：guard（首段标记，标题保护用）、fade（隔行临摹的淡字标记） */
function buildChars(text, cols) {
    const indent = Math.max(0, Math.min(cols, Number($('indent').value) || 0));
    const stripOn = stripPunct === 1;                       /* 是否去掉标点 */
    const keepLines = Math.max(0, Number($('stripKeep').value) || 0);  /* 前 N 行保留标点 */
    const mode = $('modeSel').value;
    const gapRows = mode === 'rowAlt' ? 1 : (mode === 'rowAlt2' ? 2 : 0);  /* 隔行：每行后补几行空白 */
    const gapFade = gapRows > 0 && Number(document.querySelector('#secondarySeg .on').dataset.v) === 1;
    const cellW = ch => (ch.charCodeAt(0) < 128 ? 0.5 : 1);   /* 半角算半格，其余整格 */

    const out = [], guard = [], fade = [];
    const push = (ch, g, f) => { out.push(ch); guard.push(g); fade.push(f || 0); };
    const fillRow = g => { for (let i = 0; i < cols; i++) push('', g, 0); };

    /* 竖排：不排格子，只按字流一个一个往下走（每行一个字，由渲染层按列复制/淡出） */
    if (isVerticalMode(mode)) {
        let seen = 0;
        text.replace(/\r/g, '').split('\n').forEach(raw0 => {
            if (!raw0.trim()) return;
            seen++;
            const line = (stripOn && seen > keepLines) ? raw0.replace(PUNCT_RE, '') : raw0;
            line.replace(/\s|\u3000/g, '').split('').forEach(c => push(c, 0, 0));
        });
        out.guard = guard;
        out.fade = fade;
        return out;
    }

    if (!preserveBreak) {
        /* 连续排：去掉所有空白后逐字拆分 */
        const t = stripOn ? text.replace(PUNCT_RE, '') : text;
        t.replace(/\s+/g, '').split('').forEach(c => push(c, 0, 0));
        while (out.length % cols !== 0) push('', 0, 0);
    } else {
        /* 去标点时：连续多个换行（空行）压缩为 1 个 */
        let src = text.replace(/\r/g, '');
        if (stripOn) src = src.replace(/\n{3,}/g, '\n\n');
        const lines = src.split('\n');
        let inFirst = true;                                  /* 是否仍在首段（标题 / 作者行） */
        let seen = 0;                                        /* 非空行序号，用于判断前几行保留标点 */
        lines.forEach(raw0 => {
            let raw = raw0;
            if (raw0.trim()) {
                seen++;
                if (stripOn && seen > keepLines) raw = raw0.replace(PUNCT_RE, '');
            } else {
                /* 空行：首段到此结束；隔行模式下每个文字行后面本来就有空行，这里不再额外补 */
                inFirst = false;
                if (!gapRows) fillRow(0);
                return;
            }
            
            const g = inFirst ? 1 : 0;
            const chars = raw.trim().split('');
            const width = chars.reduce((a, c) => a + cellW(c), 0);   /* 该行实际占几格 */
            let lead = indent;                               /* 默认首行缩进 */
            if (inFirst && /^—/.test(raw.trim())) {
                /* 作者行（——作者）：忽略输入的空格，按“破折号 + 名字”总宽度贴到行末右对齐，
                    每行字数一变就自动重算 */
                lead = Math.max(0, Math.round(cols - width));
                for (let i = 0; i < lead; i++) push('', g, 0);
            } else if (inFirst && centerFirst) {
                if (/^\s/.test(raw)) {
                    /* 行首已有空格：按用户手动补齐的空格排（空格补齐优先） */
                    lead = raw.length - raw.replace(/^\s+/, '').length;
                    const used = out.length % cols;
                    for (let i = 0; i < Math.min(lead, cols - used); i++) push('', g, 0);
                } else {
                    /* 自动居中：按该行实际字宽计算留白 */
                    lead = Math.max(0, Math.floor((cols - width) / 2));
                    for (let i = 0; i < lead; i++) push('', g, 0);
                }
            } else {
                for (let i = 0; i < indent; i++) push('', g, 0);
            }
            chars.forEach(c => push(c, g, 0));
            /* 不满一行补空格，保证每行字数对齐 */
            while (out.length % cols !== 0) push('', 0, 0);
        });
    }

    /* 隔行 / 隔两行：在每个有字的行后面插入 1～2 行空白（选“变淡”时重复淡字供临摹） */
    if (gapRows) {
        const res = [], g2 = [], f2 = [];
        for (let i = 0; i < out.length; i += cols) {
            const hasText = out.slice(i, i + cols).some(c => c);
            for (let c = 0; c < cols; c++) { res.push(out[i + c] || ''); g2.push(guard[i + c] || 0); f2.push(0); }
            if (!hasText) continue;
            for (let k = 0; k < gapRows; k++) {
                for (let c = 0; c < cols; c++) {
                    const ch = gapFade ? (out[i + c] || '') : '';
                    res.push(ch); g2.push(0); f2.push(ch ? 1 : 0);
                }
            }
        }
        out.length = 0; guard.length = 0; fade.length = 0;
        res.forEach((v, i) => { out.push(v); guard.push(g2[i]); fade.push(f2[i]); });
    }

    out.guard = guard;
    out.fade = fade;
    return out;
}

/* ==================== 全局网格线 SVG 生成 ====================
    在网格区域内统一绘制横线、竖线；坐标单位为毫米，与页面网格对齐 */
function buildGridLines(gridW, gridH, cell, opt) {
    const st = styleOf(opt.style);
    const dashAttr = st.dashMm === 'none' ? '' : `stroke-dasharray="${st.dashMm}"`;
    const capAttr = `stroke-linecap="${st.cap}"`;
    let lines = '';

    /* 横线：rows+1 条，覆盖网格上下边界 */
    if (opt.showH) {
        for (let r = 0; r <= opt.rows; r++) {
            const y = nf(r * cell);
            lines += `<line x1="0" y1="${y}" x2="${nf(gridW)}" y2="${y}"
        stroke="${opt.color}" stroke-width="${opt.widthMm}" ${dashAttr} ${capAttr}/>`;
        }
    }
    /* 竖线：cols+1 条，覆盖网格左右边界 */
    if (opt.showV) {
        for (let c = 0; c <= opt.cols; c++) {
            const x = nf(c * cell);
            lines += `<line x1="${x}" y1="0" x2="${x}" y2="${nf(gridH)}"
        stroke="${opt.color}" stroke-width="${opt.widthMm}" ${dashAttr} ${capAttr}/>`;
        }
    }

    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'grid-lines');
    svg.setAttribute('viewBox', `0 0 ${nf(gridW)} ${nf(gridH)}`);
    svg.style.width = nf(gridW) + 'mm';    /* 显式宽高，避免 SVG 默认 300×150 拉伸 */
    svg.style.height = nf(gridH) + 'mm';
    svg.innerHTML = lines;
    return svg;
}

/* ==================== 整组格子外框（SVG，线宽全部向外扩张） ====================
    mode: single 单实线 / double 双实线 / innerThin 内细外粗 / innerThick 内粗外细
    widthPx: 基准粗细（像素），换算为毫米后全部画在格子外侧
    返回 { svg, pad }，pad 为向外扩张的总厚度（毫米），用于定位与版面留白 */
function frameLines(mode, widthPx) {
    const w = Math.max(0.3, widthPx) * PX_TO_MM;   /* 基准线宽（毫米） */
    const gap = Math.max(0.7, w * 0.6);            /* 双线 / 内外线之间的净间隔 */

    let lines = [];   /* 每条线：off 为从格子边缘向外的起点，w 为线宽 */
    if (mode === 'single') {
        lines = [{w: w, off: 0}];
    } else if (mode === 'double') {
        lines = [{w: w * 0.6, off: 0},
        {w: w * 0.6, off: w * 0.6 + gap}];
    } else if (mode === 'innerThin') {
        lines = [{w: w * 0.45, off: 0},
        {w: w * 1.15, off: w * 0.45 + gap}];
    } else if (mode === 'innerThick') {
        lines = [{w: w * 1.15, off: 0},
        {w: w * 0.45, off: w * 1.15 + gap}];
    }
    const pad = lines.length ? lines.reduce((m, l) => Math.max(m, l.off + l.w), 0) + 0.4 : 0;
    return {lines, pad};
}

function buildFrame(gridW, gridH, mode, widthPx, color) {
    const {lines, pad} = frameLines(mode, widthPx);
    if (!lines.length) return {svg: null, pad: 0};

    const boxW = gridW + pad * 2, boxH = gridH + pad * 2;

    /* 描边以路径为中心向两侧各展开 w/2，故路径需外移 off + w/2，线才整体落在格子外侧 */
    const parts = lines.map(l => {
        const d = l.off + l.w / 2;
        return `<rect x="${nf(pad - d)}" y="${nf(pad - d)}"
    width="${nf(boxW - 2 * (pad - d))}" height="${nf(boxH - 2 * (pad - d))}"
    fill="none" stroke="${color}" stroke-width="${nf(l.w)}"/>`;
    }).join('');

    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'frame-svg');
    svg.setAttribute('viewBox', `0 0 ${nf(boxW)} ${nf(boxH)}`);
    svg.style.width = boxW + 'mm';
    svg.style.height = boxH + 'mm';
    svg.innerHTML = parts;
    return {svg, pad};
}

/* ==================== 主渲染函数 ==================== */
function render() {
    const content = $('content').value;
    const pageNoPos = $('pageNoPos').value;
    const headerSlots = [V('headerLeft'), V('headerCenter'), V('headerRight')];
    const footerSlots = [V('footerLeft'), V('footerCenter'), V('footerRight')];
    const customFont = $('customFont').value.trim();
    /* 自定义字体优先，其次使用内置字体栈 */
    const ff = customFont ? `"${customFont}", ${fontFamily}` : fontFamily;

    const ratio = Math.min(1, Math.max(0.3, Number($('fontRatio').value)));
    const fontColor = $('fontColor').value;
    const fontAlpha = Number($('fontAlpha').value);
    const fadeColor = $('fadeColor').value;   /* 变淡区域的文字颜色 */
    const gridColor = $('borderColor').value;
    const gridAlpha = Number($('borderAlpha').value);
    const guideColor = $('guideColor').value;
    const guideAlpha = Number($('guideAlpha').value);
    const gridWidth = Number($('borderWidth').value);
    const guideWidth = Number($('guideWidth').value);
    const shapeSize = Math.min(1, Math.max(0.2, Number($('shapeSize').value) / 100));
    const pfColor = $('pfColor').value;
    const pfAlpha = Number($('pfAlpha').value);
    const pfWidth = Number($('pfWidth').value);
    const hfFont = $('hfFont').value;
    const hfSize = Math.min(10, Math.max(4, Number($('hfSize').value)));
    const hfGap = Math.min(4, Math.max(0, Number($('hfGap').value)));
    const innerSvg = shapeSvg(selShapes, shapeSize, guideStyle);
    const strokeInfo = currentStroke();   /* 当前笔画档位（实心/空心各有两档） */

    /* 未选整组外框时，禁用其样式/粗细/颜色选项 */
    ['pfWidthRow', 'pfColorRow'].forEach(id =>
        $(id).classList.toggle('dim', pageBorder === 'none'));

    /* 每行字数限制在 6～20 */
    const cols = Math.min(20, Math.max(3, parseInt($('cols').value, 10) || 12));
    const cell = AVAIL_W / cols;   /* 单个方格边长（毫米） */
    /* 页眉页脚与整组外框保持 hfGap 的净间距，贴紧边框 */
    const framePad = pageBorder === 'none' ? 0 : frameLines(pageBorder, pfWidth).pad;
    const HDR_TOP = 6, FOOT_BOTTOM = 6;      /* 页眉 / 页脚距纸边的起始留白 */
    const bookH = PAGE_H_MM - HDR_TOP - FOOT_BOTTOM;
    /* 竖向构成：页眉 + 间距 + 外框 + 格子 + 外框 + 间距 + 页脚，多出高度上下均分 */
    const availH = Math.max(20, bookH - 2 * (hfSize + hfGap + framePad));
    let rows = Math.max(1, Math.floor(availH / cell));     /* 每页行数（自动计算） */
    /* 隔行类方式：每页行数取整成 2 行（隔行）/ 3 行（隔两行）一组，保证每页从描红行开始 */
    const modeNow = $('modeSel').value;
    const period = modeNow === 'rowAlt' ? 2 : (modeNow === 'rowAlt2' ? 3 : 1);
    if (period > 1 && rows > period) rows -= rows % period;
    const gridW = cols * cell;
    const gridH = rows * cell;
    const gridLeft = MARGIN_X + (AVAIL_W - gridW) / 2;    /* 网格水平居中 */
    const freeH = Math.max(0, bookH - (2 * hfSize + 2 * hfGap + 2 * framePad + gridH));
    const headTop = HDR_TOP + freeH / 2;
    const gridTop = headTop + hfSize + hfGap + framePad;  /* 网格顶边（含外框厚度） */
    const footTop = gridTop + gridH + framePad + hfGap;  /* 页脚顶边 */
    const fontSizeCm = (cell * ratio) / 10;              /* 字号（厘米） */

    $('layoutInfo').innerText = `格子 ${cell.toFixed(1)}mm · 每页 ${rows} 行（自动）`;

    const chars = buildChars(content, cols);
    const fadeAlphaV = Number($('fadeAlpha').value) / 100;   /* 隔行临摹淡字透明度 */
    const vertical = isVerticalMode(modeNow);                /* 竖排：一列一个字 */
    const perPage = vertical ? rows : cols * rows;           /* 竖排每页只占一列，共 rows 个字 */
    const totalPages = Math.max(1, Math.ceil(chars.length / perPage));

    const bookEl = $('book');
    bookEl.innerHTML = '';

    /* 预览缩放：按右侧容器宽度等比缩小，打印时仍为真实 A4 尺寸 */
    const avail = (bookEl.clientWidth || window.innerWidth) - 4;
    const scale = Math.min(1, Math.max(0.25, avail / (PAGE_W_MM * MM)));

    for (let pageNo = 1; pageNo <= totalPages; pageNo++) {
        /* 外层包裹：按缩放后尺寸占位 */
        const wrap = document.createElement('div');
        wrap.className = 'page-wrap';
        wrap.style.width = (PAGE_W_MM * MM * scale) + 'px';
        wrap.style.height = (PAGE_H_MM * MM * scale) + 'px';

        /* 内层 A4 页面 */
        const page = document.createElement('div');
        page.className = 'a4-page';
        page.style.transform = `scale(${scale})`;
        page.style.setProperty('--guide-color', rgba(guideColor, guideAlpha));
        page.style.setProperty('--guide-w', guideWidth + 'px');
        page.style.setProperty('--cell', cell + 'mm');

        /* 页眉 */
        const hb = makeBar('header', headerSlots, pageNoPos, pageNo, totalPages, hfFont, hfSize, headTop);
        if (hb) page.appendChild(hb);

        /* 字帖网格（只摆放文字与内部辅助线，不含边框） */
        const grid = document.createElement('div');
        grid.className = 'grid';
        grid.style.left = gridLeft + 'mm';
        grid.style.top = gridTop + 'mm';
        grid.style.width = gridW + 'mm';
        for (let r = 0; r < rows; r++) {
            const row = document.createElement('div');
            row.className = 'row';
            /* 该行首个有字的列：列类练字方式以“文字第一列”为起点计算 */
            let rowLead = 0;
            for (let c0 = 0; c0 < cols; c0++) {
                if (chars[(pageNo - 1) * perPage + r * cols + c0]) { rowLead = c0; break; }
            }
            for (let c = 0; c < cols; c++) {
                const idx = vertical ? (pageNo - 1) * perPage + r
                    : (pageNo - 1) * perPage + r * cols + c;
                const cellEl = document.createElement('div');
                cellEl.className = 'cell';
                if (innerSvg) cellEl.insertAdjacentHTML('beforeend', innerSvg);

                const protectedRow = guardFirst === 1 && !!(chars.guard && chars.guard[idx]);
                const repeatCell = !!(chars.fade && chars.fade[idx]);
                const ink = vertical ? verticalInk(c + 1, cols, modeNow)
                    : (protectedRow ? 1
                        : (repeatCell ? fadeAlphaV : inkFor(r + 1, c + 1, rows, cols, rowLead)));
                const t = chars[idx] || '';
                if (t && ink > 0.004) {
                    const cAlpha = fontAlpha * ink;
                    const cColor = ink >= 0.985 ? fontColor : fadeColor;
                    if (shape === 'hollow') {
                        /* 空心描红：SVG <text> 的 stroke 在 PDF 里是真正的矢量路径，
                            比 CSS -webkit-text-stroke 打印更清晰不失真 */
                        cellEl.insertAdjacentHTML('beforeend',
                            hollowGlyphSvg(t, ff, strokeInfo.weight, cColor, cAlpha,
                                strokeInfo.hollow, cell));
                    } else {
                        /* 实心：普通 span 文字 */
                        const ch = document.createElement('span');
                        ch.innerText = t;
                        ch.style.fontFamily = ff;
                        ch.style.fontSize = fontSizeCm.toFixed(3) + 'cm';
                        ch.style.fontWeight = strokeInfo.weight;
                        ch.style.color = rgba(cColor, cAlpha);
                        cellEl.appendChild(ch);
                    }
                }
                row.appendChild(cellEl);
            }
            grid.appendChild(row);
        }
        page.appendChild(grid);

        /* 全局网格线图层：统一横线 / 竖线，覆盖整个网格区域 */
        const gridLines = buildGridLines(gridW, gridH, cell, {
            showH: showH === 1, showV: showV === 1,
            style: gridStyle,
            color: rgba(gridColor, gridAlpha),
            widthMm: (gridWidth * PX_TO_MM).toFixed(3),
            rows, cols
        });
        gridLines.style.left = gridLeft + 'mm';
        gridLines.style.top = gridTop + 'mm';
        page.appendChild(gridLines);

        /* 整组格子外框：SVG 画在格子外侧，线宽向外扩张，不侵占格子区域 */
        if (pageBorder !== 'none') {
            const {svg, pad} = buildFrame(gridW, gridH, pageBorder, pfWidth, rgba(pfColor, pfAlpha));
            svg.style.left = (gridLeft - pad) + 'mm';
            svg.style.top = (gridTop - pad) + 'mm';
            page.appendChild(svg);
        }

        /* 页脚 */
        const fb = makeBar('footer', footerSlots, pageNoPos, pageNo, totalPages, hfFont, hfSize, footTop);
        if (fb) page.appendChild(fb);

        wrap.appendChild(page);
        bookEl.appendChild(wrap);
        fitBars(page);   /* 页眉页脚超出栏宽时自动缩小字号 */
    }

    /* 状态栏：总页数、每页行列数、有效字数 */
    const totalChars = chars.filter(c => c).length;
    $('pageTip').innerText = `共 ${totalPages} 页 · 每页 ${rows} 行 × ${cols} 字 · ${totalChars} 字`;
    $('scaleTip').innerText = scale < 1
        ? `预览为等比例缩放尺寸（ ${Math.round(scale * 100)}%），打印实际输出 A4 纸尺寸（210mm × 297mm）`
        : '预览为等比例缩放尺寸，打印实际输出 A4 纸尺寸（210mm × 297mm）';

    saveConfig();
}

/* ==================== 配置持久化 ==================== */
/* 收集当前所有配置项为对象 */
function collectConfig() {
    return {
        content: $('content').value,
        selShapes, guideStyle, gridStyle, pageBorder, fontFamily,
        customFont: $('customFont').value,
        cols: $('cols').value,
        fontRatio: $('fontRatio').value,
        shape, strokeLevel,
        fontColor: $('fontColor').value, fontAlpha: $('fontAlpha').value,
        borderColor: $('borderColor').value, borderAlpha: $('borderAlpha').value,
        guideColor: $('guideColor').value, guideAlpha: $('guideAlpha').value,
        shapeSize: $('shapeSize').value,
        borderWidth: $('borderWidth').value, guideWidth: $('guideWidth').value,
        showH, showV,
        pfColor: $('pfColor').value, pfAlpha: $('pfAlpha').value,
        pfWidth: $('pfWidth').value,
        headerLeft: $('headerLeft').value, headerCenter: $('headerCenter').value, headerRight: $('headerRight').value,
        footerLeft: $('footerLeft').value, footerCenter: $('footerCenter').value, footerRight: $('footerRight').value,
        pageNoPos: $('pageNoPos').value,
        hfFont: $('hfFont').value, hfSize: $('hfSize').value, hfGap: $('hfGap').value,
        preserveBreak, indent: $('indent').value, centerFirst,
        stripPunct, stripKeep: $('stripKeep').value,
        mode: $('modeSel').value, modeNum: $('modeNum').value,
        secondary: Number(document.querySelector('#secondarySeg .on').dataset.v), guardFirst,
        fadeAlpha: $('fadeAlpha').value, fadeColor: $('fadeColor').value
    };
}
/* 保存配置到 localStorage */
function saveConfig() {
    try {localStorage.setItem(STORE_KEY, JSON.stringify(collectConfig()));} catch (e) { }
}

/* 旧版复合类型 → 原子项映射（兼容历史存档） */
const LEGACY_MAP = {
    mi: ['h', 'v', 'd1', 'd2'],
    tian: ['h', 'v'],
    x: ['d1', 'd2'],
    blank: []
};

/* 旧版线型值映射到新线型预设（dashed→短划，dotted→点线，其余原样保留） */
function mapLegacyStyle(v) {
    if (!v) return 'solid';
    if (v === 'dashed') return 'short';
    return LINE_STYLES.some(s => s.v === v) ? v : 'solid';
}

/* 把存档配置回填到界面控件 */
function applyConfig(cfg) {
    if (!cfg) return;
    /* 普通输入框类配置直接赋值 */
    ['content', 'customFont', 'cols', 'fontRatio', 'fontColor', 'fontAlpha', 'borderColor', 'borderAlpha',
        'guideColor', 'guideAlpha', 'borderWidth', 'guideWidth', 'shapeSize', 'pfColor', 'pfAlpha', 'pfWidth',
        'headerLeft', 'headerCenter', 'headerRight', 'footerLeft', 'footerCenter', 'footerRight',
        'pageNoPos', 'indent', 'hfFont', 'hfSize', 'hfGap', 'stripKeep', 'modeNum', 'fadeAlpha', 'fadeColor'].forEach(k => {
            if (cfg[k] !== undefined && $(k)) $(k).value = cfg[k];
        });

    /* 已选样式：新格式为原子项数组，旧格式为复合类型 */
    if (Array.isArray(cfg.selShapes)) {
        selShapes = cfg.selShapes.filter(v => SHAPES.some(x => x.v === v));
    } else if (cfg.gridType && LEGACY_MAP[cfg.gridType]) {
        selShapes = LEGACY_MAP[cfg.gridType].slice();
    }

    /* 线型 / 显隐状态回填 */
    guideStyle = mapLegacyStyle(cfg.guideStyle);
    gridStyle = mapLegacyStyle(cfg.gridStyle || cfg.borderStyle);
    showH = cfg.showH !== undefined ? Number(cfg.showH) : 1;
    showV = cfg.showV !== undefined ? Number(cfg.showV) : 1;
    centerFirst = cfg.centerFirst !== undefined ? Number(cfg.centerFirst) : 1;

    /* 整组外框线型回填（兼容旧版 none/single/double 存档） */
    const LEGACY_FRAME = {solid: 'single', dashed: 'single', dotted: 'single'};
    const fr = cfg.frameMode || cfg.pageBorder || 'single';
    pageBorder = LEGACY_FRAME[fr] || fr;
    if (!['none', 'single', 'double', 'innerThin', 'innerThick'].includes(pageBorder)) pageBorder = 'single';

    /* 旧版单段页眉页脚 → 新三栏（放到中栏） */
    if (cfg.headerText !== undefined && cfg.headerCenter === undefined) $('headerCenter').value = cfg.headerText;
    if (cfg.footerText !== undefined && cfg.footerCenter === undefined) $('footerCenter').value = cfg.footerText;

    if (cfg.fontFamily) fontFamily = cfg.fontFamily;

    /* 字形与字重回填 */
    if (cfg.shape) {
        shape = cfg.shape;
        $('shapeSeg').querySelectorAll('button').forEach(b => b.classList.toggle('on', b.dataset.v === shape));
    }
    /* 笔画档位回填：优先新字段，兼容旧版 weight / hollowW 取值 */
    if (cfg.strokeLevel !== undefined) {
        strokeLevel = Math.min(1, Math.max(0, Number(cfg.strokeLevel)));
    } else {
        const LEGACY_W = {normal: 400, bold: 700};
        const oldW = LEGACY_W[cfg.weight] || Number(cfg.weight) || 400;
        strokeLevel = oldW <= 330 ? 0 : (oldW >= 600 ? 1 : 0);
    }
    $('strokeLevel').value = strokeLevel;
    syncStrokeMarks();
    if (cfg.preserveBreak !== undefined) {
        preserveBreak = Number(cfg.preserveBreak);
        $('breakSeg').querySelectorAll('button').forEach(b =>
            b.classList.toggle('on', Number(b.dataset.v) === preserveBreak));
    }
    $('centerFirstSeg').querySelectorAll('button').forEach(b =>
        b.classList.toggle('on', Number(b.dataset.v) === centerFirst));

    /* 去标点 / 练字方式回填 */
    stripPunct = cfg.stripPunct !== undefined ? Number(cfg.stripPunct) : 0;
    $('stripPunctSeg').querySelectorAll('button').forEach(b =>
        b.classList.toggle('on', Number(b.dataset.v) === stripPunct));
    $('modeSel').value = cfg.mode || 'none';
    const sec = cfg.secondary !== undefined ? Number(cfg.secondary) : 0;
    $('secondarySeg').querySelectorAll('button').forEach(b =>
        b.classList.toggle('on', Number(b.dataset.v) === sec));
    guardFirst = cfg.guardFirst !== undefined ? Number(cfg.guardFirst) : 1;
    $('guardFirstSeg').querySelectorAll('button').forEach(b =>
        b.classList.toggle('on', Number(b.dataset.v) === guardFirst));
    syncModeRows();

    /* 回填分段按钮选中态 */
    $('showHSeg').querySelectorAll('button').forEach(b => b.classList.toggle('on', Number(b.dataset.v) === showH));
    $('showVSeg').querySelectorAll('button').forEach(b => b.classList.toggle('on', Number(b.dataset.v) === showV));
    $('frameMode').value = pageBorder;

    /* 填充线型下拉并选中当前项 */
    fillStyleSelect($('guideStyle'), guideStyle);
    fillStyleSelect($('gridStyle'), gridStyle);

    /* 刷新所有滑块数值标签 */
    sliders.forEach(([id, fmt]) => $(id + 'Val').innerText = fmt(Number($(id).value)));
    $('shapeSizeVal').innerText = pct(Number($('shapeSize').value) / 100);
    syncSlots();
    buildShapeChips();
    syncFont();
}

/* 恢复默认：清空存档并回填默认配置 */
function resetAll() {
    try {localStorage.removeItem(STORE_KEY);} catch (e) { }
    $('content').value = DEFAULT_CONTENT;
    applyConfig(DEFAULTS);
    render();
}

/* ==================== 面板折叠 / 实时联动 ==================== */
/* 收起 / 展开左侧面板 */
function togglePanel() {
    const p = $('panel');
    p.classList.toggle('collapsed');
    $('toggleBtn').innerText = p.classList.contains('collapsed') ? '展开' : '收起';
}

/* 输入类控件防抖监听：停顿 250ms 后再重新渲染，避免频繁重绘 */
let timer = null;
['content', 'cols', 'customFont', 'indent', 'fontColor', 'borderColor', 'guideColor',
    'headerLeft', 'headerCenter', 'headerRight', 'footerLeft', 'footerCenter', 'footerRight'].forEach(id => {
        $(id).addEventListener('input', () => {
            clearTimeout(timer);
            timer = setTimeout(render, 250);
        });
    });

/* 窗口尺寸变化防抖：重新计算预览缩放 */
let resizeTimer = null;
window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(render, 200);
});

/* ==================== 启动初始化 ==================== */
const DEFAULT_CONTENT = $('content').value;   /* 保存初始示例文本用于恢复默认 */

(function init() {
    buildShapeChips();
    buildFontMenu();
    buildHfFontMenu();
    /* 先填充三个线型下拉的默认选项 */
    fillStyleSelect($('guideStyle'), DEFAULTS.guideStyle);
    fillStyleSelect($('gridStyle'), DEFAULTS.gridStyle);

    /* 读取本地存档（兼容 v3 旧键名），无存档则用默认配置 */
    let saved = null;
    try {
        saved = JSON.parse(localStorage.getItem(STORE_KEY) || 'null')
            || JSON.parse(localStorage.getItem('zitie-config-v3') || 'null');
    } catch (e) { }
    applyConfig(saved || DEFAULTS);
    buildTemplateRow();
    buildLibList();
    syncModeRows();
    render();

    /* 窄屏默认收起面板 */
    if (window.innerWidth < 700) {
        $('panel').classList.add('collapsed');
        $('toggleBtn').innerText = '展开';
    }
})();
